INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('busan', 'gyeongnam', 'Busan', 'Busan', 'Nam Gyeongsang', '#5a8aa6', 129.06, 35.1648, 'Thành phố cảng lớn nhất Hàn Quốc — biển, chợ cá, làng trên đồi và đời sống về đêm sát mép nước.', 'Busan trải dài giữa núi và biển, nên thành phố lúc nào cũng lên dốc xuống dốc. Sáng ở chợ cá Jagalchi xem đấu giá, trưa lạc trong các ngõ nhiều màu của Gamcheon, chiều nằm dài ở Haeundae, tối ra Gwangalli ngắm cầu đổi màu. Người Busan nói giọng nặng, ăn cay và mặn hơn Seoul, tự hào về món dwaeji-gukbap — canh xương heo ăn với cơm — món ra đời từ thời tị nạn chiến tranh. Tháng 10, cả thành phố sống theo nhịp Liên hoan phim quốc tế Busan.', 'Tháng 5–6 và 9–10', '["Dwaeji-gukbap","Milmyeon","Chả cá Busan","Ssiat hotteok"]', '{"en":{"name":"Busan","summary":"Korea''s biggest port city — beaches, fish markets, hillside villages and nightlife at the water''s edge.","story":"Busan is stretched between mountains and sea, so the city is always climbing or descending. Morning at the Jagalchi fish auction, midday lost in the coloured lanes of Gamcheon, afternoon flat out on Haeundae, evening at Gwangalli watching the bridge change colour. People here speak with a heavy accent, eat spicier and saltier than Seoul, and are proud of dwaeji-gukbap — pork bone soup with rice, a dish born of the refugee years. Each October the city runs on the rhythm of the Busan International Film Festival.","bestTime":"May–June and September–October","specialties":["Dwaeji-gukbap","Milmyeon noodles","Busan fish cakes","Seed hotteok"]},"ko":{"name":"부산","summary":"한국 최대의 항구 도시. 해변과 어시장, 산비탈 마을, 물가의 밤이 있다.","story":"부산은 산과 바다 사이에 길게 펼쳐져 있어 도시가 늘 오르막이거나 내리막이다. 아침에는 자갈치 경매를 보고, 낮에는 감천의 색색 골목에서 길을 잃고, 오후에는 해운대에 누웠다가, 저녁에는 광안리에서 색이 바뀌는 다리를 본다. 이곳 사람들은 억양이 세고 서울보다 맵고 짜게 먹으며, 피란 시절에 태어난 돼지국밥을 자랑스러워한다. 10월이면 도시 전체가 부산국제영화제의 리듬으로 움직인다.","bestTime":"5~6월, 9~10월","specialties":["돼지국밥","밀면","부산 어묵","씨앗호떡"]},"ja":{"name":"釜山","summary":"韓国最大の港町。浜と魚市場、丘の集落、そして水際の夜がある。","story":"釜山は山と海の間に長く伸びているので、街は常に上りか下りだ。朝はチャガルチの競りを見て、昼は甘川の色とりどりの路地で迷い、午後は海雲台に寝そべり、夜は広安里で色を変える橋を眺める。ここの人は訛りが強く、ソウルより辛く塩気の強い味を好み、避難時代に生まれたテジクッパを誇りにしている。10月には街全体が釜山国際映画祭のリズムで動く。","bestTime":"5〜6月、9〜10月","specialties":["テジクッパ","ミルミョン","釜山おでん","シアッホットク"]},"zh":{"name":"釜山","summary":"韓國最大的港口城市——海灘、魚市、山坡聚落，以及水邊的夜。","story":"釜山在山與海之間延展，所以這座城市不是在上坡就是在下坡。早上看札嘎其的拍賣，中午在甘川的彩色巷弄裡迷路，午後躺在海雲台，晚上到廣安里看變換顏色的大橋。這裡的人口音重，吃得比首爾更辣更鹹，也為豬肉湯飯自豪——那是難民歲月裡誕生的一道菜。每年十月，整座城市隨釜山國際電影節的節奏運轉。","bestTime":"5至6月、9至10月","specialties":["豬肉湯飯","小麥冷麵","釜山魚糕","堅果糖餅"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('chungbuk', 'chungcheong', 'Chungbuk', 'North Chungcheong', 'Chungcheong', '#6e8c5a', 127.8086, 36.7046, 'Tỉnh duy nhất không giáp biển, bù lại có núi đá vôi, hồ nước trong và những ngôi chùa quốc bảo.', 'Chungcheongbuk-do là tỉnh nội địa duy nhất của Hàn Quốc, và điều đó định hình mọi thứ: thay vì cảng cá là sông và hồ, thay vì bãi biển là núi đá vôi. Danyang có ba mỏm đá giữa sông, hang động măng đá và cầu treo trên vách núi. Songnisan giữ ngôi tháp gỗ năm tầng duy nhất còn lại của cả nước. Cheongju — thủ phủ tỉnh — là nơi in ra cuốn sách kim loại rời cổ nhất thế giới, trước Gutenberg gần tám mươi năm.', 'Tháng 5–6 và 10–11', '["Món tỏi Danyang","Cơm nấm Songnisan","Rượu gạo Chungbuk"]', '{"en":{"name":"North Chungcheong","summary":"The only landlocked province, trading coastline for limestone peaks, clear rivers and national-treasure temples.","story":"North Chungcheong is Korea''s only inland province, and that shapes everything: rivers and lakes instead of fishing ports, limestone karst instead of beaches. Danyang has three rock stacks mid-river, caves full of formations and a skywalk on a cliff. Songnisan holds the only five-storey wooden pagoda left in the country. Cheongju, the provincial capital, is where the world''s oldest book printed with movable metal type was made, nearly eighty years before Gutenberg.","bestTime":"May–June and October–November","specialties":["Danyang garlic dishes","Songnisan mushroom rice","Chungbuk rice wine"]},"ko":{"name":"충청북도","summary":"바다가 없는 유일한 도. 대신 석회암 봉우리와 맑은 강, 국보 사찰이 있다.","story":"충청북도는 한국에서 유일한 내륙 도이고, 그 사실이 모든 것을 결정한다. 어항 대신 강과 호수가, 해변 대신 석회암 지형이 있다. 단양에는 강 가운데 솟은 세 봉우리와 종유석 동굴, 절벽 위 스카이워크가 있다. 속리산에는 전국에 하나뿐인 오층 목탑이 남아 있다. 도청 소재지 청주는 구텐베르크보다 80년 가까이 앞서 세계에서 가장 오래된 금속활자본을 찍어낸 곳이다.","bestTime":"5~6월, 10~11월","specialties":["단양 마늘 요리","속리산 버섯밥","충북 막걸리"]},"ja":{"name":"忠清北道","summary":"海に接しない唯一の道。代わりに石灰岩の峰と澄んだ川、国宝の寺がある。","story":"忠清北道は韓国で唯一の内陸の道で、そのことがすべてを決めている。漁港ではなく川と湖、砂浜ではなく石灰岩の地形。丹陽には川の中に立つ三つの峰、鍾乳洞、崖の上のスカイウォークがある。俗離山には全国に一つだけの五層木塔が残る。道庁所在地の清州は、グーテンベルクより80年近く早く世界最古の金属活字本を刷った街だ。","bestTime":"5〜6月、10〜11月","specialties":["丹陽のニンニク料理","俗離山のきのこ飯","忠北のマッコリ"]},"zh":{"name":"忠清北道","summary":"唯一不臨海的道，以石灰岩峰、清澈江水與國寶級古剎作為補償。","story":"忠清北道是韓國唯一的內陸道，這一點決定了一切：沒有漁港，只有江與湖；沒有海灘，只有石灰岩地形。丹陽有江心三峰、滿是鐘乳石的洞窟，以及崖上的天空步道。俗離山保有全國唯一留存的五層木塔。道廳所在地清州，則是世界最早金屬活字印本的誕生地，比古騰堡早了近八十年。","bestTime":"5至6月、10至11月","specialties":["丹陽蒜味料理","俗離山菇飯","忠北馬格利"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('chungnam', 'chungcheong', 'Chungnam', 'South Chungcheong', 'Chungcheong', '#6e8c5a', 126.8738, 36.5017, 'Đất của vương quốc Bách Tế xưa, với thành cổ bên sông Geum và lễ hội bùn nổi tiếng thế giới.', 'Chungcheongnam-do là nơi Bách Tế đóng đô những thế kỷ cuối cùng: Gongju và Buyeo giữ lăng mộ, thành đất và hồ vườn cổ nhất Hàn Quốc, tất cả nằm trong quần thể di sản UNESCO. Bờ biển phía tây với thuỷ triều rút xa hàng cây số cho những bãi bùn giàu khoáng — nguồn gốc của lễ hội bùn Boryeong mỗi tháng 7. Xen giữa là các thành huyện như Haemi, đồng lúa và những cánh đồng bí đỏ mà cả nước biết tiếng.', 'Tháng 7 (lễ hội bùn) và tháng 9–10', '["Cháo bí đỏ","Canh gà Cheonan","Bánh hồ đào Cheonan","Hàu Seosan"]', '{"en":{"name":"South Chungcheong","summary":"The land of the old Baekje kingdom, with riverside fortresses and a mud festival known worldwide.","story":"South Chungcheong was where Baekje held its last capitals: Gongju and Buyeo keep the royal tombs, earthen ramparts and the oldest garden pond in Korea, all part of a UNESCO inscription. On the west coast the tide withdraws for kilometres, leaving mineral-rich flats — the origin of the Boryeong Mud Festival each July. In between are walled county towns like Haemi, rice fields and the pumpkin farms the whole country knows.","bestTime":"July (mud festival) and September–October","specialties":["Pumpkin porridge","Cheonan chicken soup","Cheonan walnut cakes","Seosan oysters"]},"ko":{"name":"충청남도","summary":"옛 백제의 땅. 강변의 성곽과 세계적으로 알려진 머드축제가 있다.","story":"충청남도는 백제가 마지막 도읍을 두었던 곳이다. 공주와 부여에는 왕릉과 토성, 한국에서 가장 오래된 정원 연못이 남아 유네스코 세계유산에 함께 등재되었다. 서해안은 물이 수 킬로미터씩 빠져나가며 미네랄이 풍부한 갯벌을 드러내는데, 그것이 매년 7월 보령머드축제의 뿌리다. 그 사이로 해미 같은 읍성과 논, 전국이 아는 호박밭이 이어진다.","bestTime":"7월(머드축제), 9~10월","specialties":["호박죽","천안 병천순대","천안 호두과자","서산 굴"]},"ja":{"name":"忠清南道","summary":"古の百済の地。川辺の城郭と、世界に知られた泥祭りがある。","story":"忠清南道は百済が最後の都を置いた地だ。公州と扶余には王陵や土城、韓国最古の庭園池が残り、まとめてユネスコ世界遺産に登録されている。西海岸は潮が数キロも引いてミネラル豊かな干潟を現す。それが毎年7月の保寧マッドフェスティバルの源だ。その間に海美のような邑城、田んぼ、全国が知るカボチャ畑が続く。","bestTime":"7月（泥祭り）、9〜10月","specialties":["カボチャ粥","天安のスンデ","天安のクルミ菓子","瑞山の牡蠣"]},"zh":{"name":"忠清南道","summary":"古百濟之地，有臨江城郭，也有享譽世界的泥漿節。","story":"忠清南道是百濟最後定都之處：公州與扶餘保有王陵、土城與韓國最古老的園林水池，同屬一項世界遺產。西海岸退潮時海水後撤數公里，露出礦物豐富的灘塗——這正是每年七月保寧泥漿節的由來。其間散布著海美這樣的邑城、稻田，以及全國聞名的南瓜田。","bestTime":"7月（泥漿節）與9至10月","specialties":["南瓜粥","天安血腸湯","天安核桃餅","瑞山生蠔"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('daegu', 'gyeongbuk', 'Daegu', 'Daegu', 'Bắc Gyeongsang', '#8a6e4b', 128.627, 35.8924, 'Thành phố lòng chảo nổi tiếng nóng nhất Hàn Quốc, với chợ dệt lâu đời và món ăn cay nhất nước.', 'Daegu nằm gọn trong một lòng chảo núi, nên mùa hè nóng đến mức người Hàn gọi đùa là ''Daefrica''. Đây từng là thủ phủ dệt may và chợ thuốc bắc lớn nhất bán đảo — chợ Yangnyeongsi vẫn còn thơm mùi cam thảo. Ẩm thực Daegu cay và mặn: mì trộn cay, canh xương bò, lòng nướng. Vòng quanh thành phố là núi Palgongsan và Apsan, chỉ nửa giờ xe là đã ở trong rừng.', 'Tháng 4–5 và 9–11', '["Mì trộn cay Daegu","Canh xương bò","Bánh xèo hẹ","Lòng nướng makchang"]', '{"en":{"name":"Daegu","summary":"A basin city known as Korea''s hottest, with an old textile market and the country''s spiciest food.","story":"Daegu sits in a bowl of mountains, so its summers are hot enough that Koreans joke about ''Daefrica''. It was long the centre of textiles and of the peninsula''s largest herbal medicine market — Yangnyeongsi still smells of liquorice. The food is hot and salty: spicy noodles, beef bone soup, grilled offal. And the city is ringed by mountains, with Palgongsan and Apsan half an hour away.","bestTime":"April–May and September–November","specialties":["Daegu spicy noodles","Beef bone soup","Chive pancakes","Grilled makchang"]},"ko":{"name":"대구","summary":"한국에서 가장 덥다는 분지 도시. 오래된 섬유시장과 가장 매운 음식이 있다.","story":"대구는 산으로 둘러싸인 분지에 앉아 있어 여름이면 ''대프리카''라는 농담이 나올 만큼 덥다. 오랫동안 섬유의 중심이자 한반도 최대의 한약재 시장이 있던 곳으로, 약령시에는 지금도 감초 냄새가 남아 있다. 음식은 맵고 짜다. 매운 쫄면, 소뼈 국물, 곱창구이. 그리고 도시를 둘러싼 팔공산과 앞산이 차로 30분이면 닿는 숲을 내준다.","bestTime":"4~5월, 9~11월","specialties":["대구 매운 쫄면","소뼈 국밥","부추전","막창구이"]},"ja":{"name":"大邱","summary":"韓国一暑いといわれる盆地の街。古い繊維市場と最も辛い料理がある。","story":"大邱は山に囲まれた盆地にあり、夏は「テプリカ」という冗談が出るほど暑い。長らく繊維の中心であり、半島最大の漢方薬材市場があった街で、薬令市には今も甘草の匂いが残る。料理は辛くて塩気が強い。辛いチョルミョン、牛骨のスープ、ホルモン焼き。そして街を囲む八公山と前山が、車で30分の距離に森を用意している。","bestTime":"4〜5月、9〜11月","specialties":["大邱の辛いチョルミョン","牛骨クッパ","ニラチヂミ","マクチャン焼き"]},"zh":{"name":"大邱","summary":"號稱韓國最熱的盆地城市，有老紡織市場與全國最辣的料理。","story":"大邱窩在群山圍成的盆地裡，夏天熱到韓國人開玩笑叫它「大非洲」。它長期是紡織中心，也擁有半島最大的中藥材市場——藥令市至今仍有甘草的氣味。這裡的食物又辣又鹹：辣拌麵、牛骨湯、烤腸。而城市四周就是八公山與前山，開車半小時便進入山林。","bestTime":"4至5月、9至11月","specialties":["大邱辣拌麵","牛骨湯飯","韭菜煎餅","烤牛腸"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('daejeon', 'chungcheong', 'Daejeon', 'Daejeon', 'Chungcheong', '#6e8c5a', 127.3591, 36.3646, 'Thành phố khoa học ở ngã tư đường sắt Hàn Quốc, nổi tiếng với tiệm bánh mà cả nước xếp hàng.', 'Daejeon lớn lên từ một nhà ga: mọi tuyến đường sắt bắc–nam đều đi qua đây, nên thành phố thành điểm trung chuyển của cả nước. Từ thập niên 70, khu nghiên cứu Daedeok và Đại học KAIST biến nơi này thành thủ phủ khoa học công nghệ. Với khách du lịch, Daejeon là điểm dừng nửa ngày rất dễ chịu: công viên Expo bên sông, núi Gyeryongsan chỉ nửa giờ xe, và tiệm bánh Sungsimdang mà người Hàn sẵn sàng xếp hàng cả tiếng.', 'Tháng 4–5 và 9–11', '["Bánh mì Sungsimdang","Canh xương Daejeon","Mì tay chợ Jungang"]', '{"en":{"name":"Daejeon","summary":"A science city at Korea''s railway crossroads, famous for a bakery the whole country queues at.","story":"Daejeon grew out of a railway station: every north–south line passes through, which made the city the country''s transfer point. From the 1970s the Daedeok research complex and KAIST turned it into Korea''s centre of science and technology. For a traveller, Daejeon is a very easy half-day: the Expo park by the river, Gyeryongsan mountain half an hour away, and Sungsimdang bakery, for which Koreans will happily stand in line for an hour.","bestTime":"April–May and September–November","specialties":["Sungsimdang bread","Daejeon bone-broth soup","Hand-cut noodles at Jungang Market"]},"ko":{"name":"대전","summary":"철도가 교차하는 과학 도시. 전국이 줄 서는 빵집으로도 유명하다.","story":"대전은 기차역에서 자라난 도시다. 남북을 잇는 모든 노선이 지나며 전국의 환승지가 되었다. 1970년대부터 대덕연구단지와 KAIST가 들어서 한국 과학기술의 중심이 되었다. 여행자에게 대전은 아주 편한 반나절이다. 강변의 엑스포공원, 차로 30분 거리의 계룡산, 그리고 한국 사람들이 한 시간쯤은 기꺼이 줄을 서는 성심당.","bestTime":"4~5월, 9~11월","specialties":["성심당 빵","대전 국밥","중앙시장 손칼국수"]},"ja":{"name":"大田","summary":"鉄道が交差する科学都市。全国が行列するパン屋でも知られる。","story":"大田は駅から育った街だ。南北を結ぶすべての路線が通り、全国の乗り換え地になった。1970年代からは大徳研究団地とKAISTが置かれ、韓国の科学技術の中心となった。旅行者にとって大田はとても気楽な半日だ。川辺のエキスポ公園、車で30分の鶏龍山、そして韓国の人が一時間は喜んで並ぶソンシムダン。","bestTime":"4〜5月、9〜11月","specialties":["ソンシムダンのパン","大田のクッパ","中央市場の手打ちカルグクス"]},"zh":{"name":"大田","summary":"位於鐵路交會處的科學之城，也因一家全國排隊的麵包店而聞名。","story":"大田是從一座車站長成的城市：南北向的每條鐵路都經過這裡，讓它成為全國的轉車點。自七〇年代起，大德研究園區與KAIST把這裡變成韓國的科技中心。對旅人而言，大田是很輕鬆的半天：河畔的世博公園、半小時車程的雞龍山，以及韓國人願意排上一小時的聖心堂。","bestTime":"4至5月、9至11月","specialties":["聖心堂麵包","大田湯飯","中央市場手切刀削麵"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('gangwon', 'gangwon', 'Gangwon', 'Gangwon', 'Gangwon', '#4f7b6a', 128.3458, 37.6651, 'Tỉnh của núi cao và biển Đông — Seoraksan, cao nguyên tuyết Pyeongchang và những bãi biển đón bình minh.', 'Gangwon là nửa phía đông thưa người nhất Hàn Quốc: dãy Taebaek chạy dọc suốt tỉnh, một bên là rừng núi, một bên đổ thẳng xuống biển Đông. Mùa thu, lá đỏ bắt đầu từ Seoraksan rồi lan xuống cả nước. Mùa đông, tuyết dày phủ cao nguyên Pyeongchang — nơi từng đăng cai Thế vận hội 2018 — và các khu trượt tuyết mở suốt mùa. Bờ biển Gangneung, Sokcho, Jeongdongjin là chỗ người Seoul đi tàu ra ngắm bình minh, ăn mực tươi và uống cà phê nhìn sóng.', 'Tháng 9–10 (lá đỏ) và tháng 12–2 (tuyết)', '["Mì lạnh Chuncheon makguksu","Gà xào cay dakgalbi","Mực tươi Sokcho","Khoai tây Gangwon"]', '{"en":{"name":"Gangwon","summary":"A province of high mountains and the East Sea — Seoraksan, the snow plateau of Pyeongchang and beaches made for sunrise.","story":"Gangwon is the emptiest half of the country''s east: the Taebaek range runs its whole length, forest on one side, a drop into the East Sea on the other. In autumn the red leaves start at Seoraksan and spread down the peninsula. In winter deep snow covers the Pyeongchang plateau — host of the 2018 Olympics — and the ski resorts stay open all season. The coast at Gangneung, Sokcho and Jeongdongjin is where Seoul takes the train to watch the sunrise, eat squid straight off the boat and drink coffee facing the waves.","bestTime":"September–October (autumn colour) and December–February (snow)","specialties":["Chuncheon makguksu","Dakgalbi","Sokcho squid","Gangwon potatoes"]},"ko":{"name":"강원","summary":"높은 산과 동해의 도. 설악산, 평창의 설원, 해돋이 해변이 있다.","story":"강원은 한국에서 사람이 가장 적은 동쪽 절반이다. 태백산맥이 도 전체를 세로로 지나 한쪽은 산림, 한쪽은 동해로 곧장 떨어진다. 가을이면 설악산에서 시작한 단풍이 남쪽으로 번져 내려간다. 겨울에는 평창 고원에 눈이 깊이 쌓이고, 2018년 올림픽을 치른 스키장들이 겨우내 문을 연다. 강릉과 속초, 정동진의 해안은 서울 사람들이 기차를 타고 해를 보러 오는 곳이다. 갓 잡은 오징어를 먹고 파도를 마주한 카페에서 커피를 마신다.","bestTime":"9~10월(단풍), 12~2월(설경)","specialties":["춘천 막국수","닭갈비","속초 오징어","강원 감자"]},"ja":{"name":"江原","summary":"高い山と東海の道。雪岳山、平昌の雪原、日の出の浜がある。","story":"江原は韓国で最も人の少ない東半分だ。太白山脈が道を縦に貫き、一方は森林、一方は東海へまっすぐ落ちる。秋には雪岳山から始まった紅葉が南へ広がっていく。冬は平昌の高原に雪が深く積もり、2018年五輪を開いたスキー場が冬じゅう営業する。江陵、束草、正東津の海岸は、ソウルの人々が列車に乗って日の出を見に来る場所だ。獲れたてのイカを食べ、波を正面に見るカフェでコーヒーを飲む。","bestTime":"9〜10月（紅葉）、12〜2月（雪）","specialties":["春川マッククス","タッカルビ","束草のイカ","江原のじゃがいも"]},"zh":{"name":"江原","summary":"高山與東海之道：雪嶽山、平昌雪原，以及迎接日出的海灘。","story":"江原是韓國東半部最空曠的一塊：太白山脈縱貫全道，一邊是山林，一邊直落東海。秋天，紅葉自雪嶽山開始，一路南下。冬天，平昌高原積雪深厚——這裡主辦過2018年冬奧——滑雪場整季開放。江陵、束草與正東津的海岸，是首爾人搭火車來看日出的地方：吃剛上岸的魷魚，坐在面海的咖啡館裡看浪。","bestTime":"9至10月（紅葉）與12至2月（雪）","specialties":["春川蕎麥涼麵","辣炒雞排","束草魷魚","江原馬鈴薯"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('gwangju', 'honam', 'Gwangju', 'Gwangju', 'Honam (Jeolla)', '#5d9e86', 126.9192, 35.2055, 'Thành phố của phong trào dân chủ 1980, nay là trung tâm nghệ thuật và ẩm thực của miền tây nam.', 'Gwangju mang trong mình ký ức tháng 5 năm 1980, khi người dân xuống đường đòi dân chủ và bị đàn áp đẫm máu; tư liệu về những ngày đó nay nằm trong Ký ức Thế giới của UNESCO. Thành phố không né tránh quá khứ ấy — nó được kể ở quảng trường, nghĩa trang và bảo tàng. Song song, Gwangju là đất của nghệ thuật: Biennale Gwangju là triển lãm nghệ thuật đương đại lớn nhất châu Á, và bàn ăn ở đây nổi tiếng vì số lượng món phụ nhiều đến mức phải xếp chồng.', 'Tháng 4–6 và 9–11', '["Vịt hầm Gwangju","Cơm bàn hanjeongsik","Kimchi lá cải Gwangju"]', '{"en":{"name":"Gwangju","summary":"The city of the 1980 democracy movement, now the art and food capital of the southwest.","story":"Gwangju carries the memory of May 1980, when its people took to the streets for democracy and were met with force; the archive of those days is now in UNESCO''s Memory of the World. The city does not avoid that past — it is told in the square, the cemetery and the museums. Alongside it, Gwangju is a city of art: the Gwangju Biennale is the largest contemporary art exhibition in Asia, and its dinner tables are famous for side dishes so numerous they have to be stacked.","bestTime":"April–June and September–November","specialties":["Gwangju duck soup","Hanjeongsik banquet table","Gwangju leaf kimchi"]},"ko":{"name":"광주","summary":"1980년 민주화운동의 도시. 지금은 서남권의 예술과 음식의 중심이다.","story":"광주는 1980년 5월의 기억을 품고 있다. 시민들이 민주주의를 위해 거리로 나섰고 무력에 부딪혔으며, 그 기록은 이제 유네스코 세계기록유산에 올라 있다. 도시는 그 과거를 피하지 않는다. 광장과 묘지와 박물관에서 그 이야기를 계속한다. 한편 광주는 예술의 도시이기도 하다. 광주비엔날레는 아시아 최대의 현대미술 전시이고, 이 도시의 밥상은 반찬이 너무 많아 그릇을 포개야 할 정도로 유명하다.","bestTime":"4~6월, 9~11월","specialties":["광주 오리탕","한정식","광주 갓김치"]},"ja":{"name":"光州","summary":"1980年の民主化運動の都市。今は南西部の芸術と食の中心。","story":"光州は1980年5月の記憶を抱えている。市民が民主主義のために街頭に出て武力に遭い、その記録は今ユネスコ世界記憶遺産にある。街はその過去を避けない。広場でも墓地でも博物館でも語り続ける。同時に光州は芸術の都市でもある。光州ビエンナーレはアジア最大の現代美術展であり、この街の食卓はおかずが多すぎて器を重ねるほどだと知られている。","bestTime":"4〜6月、9〜11月","specialties":["光州のオリタン","韓定食","光州のカッキムチ"]},"zh":{"name":"光州","summary":"1980年民主運動之城，如今是西南部的藝術與美食中心。","story":"光州承載著1980年五月的記憶：市民為民主走上街頭，遭到武力鎮壓；那些日子的檔案如今已列入世界記憶名錄。這座城市不迴避那段過去——廣場、墓地與博物館都在講述它。與此同時，光州也是藝術之城：光州雙年展是亞洲最大的當代藝術展，而這裡的餐桌以小菜多到必須疊起來而聞名。","bestTime":"4至6月、9至11月","specialties":["光州鴨湯","韓定食","光州芥菜泡菜"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('gyeongbuk', 'gyeongbuk', 'Gyeongbuk', 'North Gyeongsang', 'Bắc Gyeongsang', '#8a6e4b', 128.7046, 36.2654, 'Cái nôi của vương triều Silla và Nho học Triều Tiên — Gyeongju, Andong và những ngôi làng còn sống.', 'Gyeongsangbuk-do là nơi lịch sử Hàn Quốc dày nhất. Gyeongju từng là kinh đô Silla suốt gần một nghìn năm, và cả thành phố hôm nay là một bảo tàng ngoài trời: gò mộ vua giữa phố, đài thiên văn thế kỷ 7, chùa Bulguksa và hang Seokguram trên núi. Về phía bắc, Andong giữ làng Hahoe và các thư viện Nho giáo — nơi lễ nghi dòng họ vẫn được thực hành thật chứ không diễn cho khách xem. Xen giữa là núi non, chùa cổ và những hẻm đá như Juwangsan.', 'Tháng 4 (hoa anh đào) và tháng 10–11', '["Gà hầm jjimdak Andong","Cá thu muối Andong","Bánh gạo Gyeongju","Rượu soju Andong"]', '{"en":{"name":"North Gyeongsang","summary":"The cradle of the Silla kingdom and Korean Confucianism — Gyeongju, Andong and villages still lived in.","story":"North Gyeongsang is where Korean history lies thickest. Gyeongju was the Silla capital for nearly a thousand years, and the city today is an open-air museum: royal mounds among the streets, a 7th-century observatory, Bulguksa temple and the Seokguram grotto on the mountain. Further north, Andong keeps Hahoe village and its Confucian academies, where clan rites are still genuinely practised rather than performed for visitors. In between are mountains, old temples and rock gorges like Juwangsan.","bestTime":"April (cherry blossom) and October–November","specialties":["Andong jjimdak","Andong salted mackerel","Gyeongju rice bread","Andong soju"]},"ko":{"name":"경상북도","summary":"신라와 조선 유학의 요람. 경주와 안동, 그리고 지금도 사람이 사는 마을들.","story":"경상북도는 한국사가 가장 두껍게 쌓인 곳이다. 경주는 천 년 가까이 신라의 수도였고, 지금도 도시 전체가 지붕 없는 박물관이다. 거리 사이의 왕릉, 7세기의 천문대, 불국사와 산 위의 석굴암. 북쪽 안동에는 하회마을과 서원들이 있는데, 문중의 의례가 관광용 공연이 아니라 실제로 이어진다. 그 사이로 산과 옛 절, 주왕산 같은 암석 협곡이 흩어져 있다.","bestTime":"4월(벚꽃), 10~11월","specialties":["안동찜닭","안동 간고등어","경주 황남빵","안동소주"]},"ja":{"name":"慶尚北道","summary":"新羅と朝鮮儒学のゆりかご。慶州、安東、そして今も人の住む村々。","story":"慶尚北道は韓国史が最も厚く積もった土地だ。慶州は千年近く新羅の都であり、今も街全体が屋根のない博物館である。通りの合間の王陵、7世紀の天文台、仏国寺と山上の石窟庵。北の安東には河回村と書院が残り、門中の儀礼が観光用の演出ではなく実際に受け継がれている。その間に山と古寺、周王山のような岩の峡谷が点在する。","bestTime":"4月（桜）、10〜11月","specialties":["安東チムタク","安東の塩サバ","慶州の皇南パン","安東焼酎"]},"zh":{"name":"慶尚北道","summary":"新羅王朝與朝鮮儒學的搖籃——慶州、安東，以及至今仍有人居住的村落。","story":"慶尚北道是韓國歷史積得最厚的地方。慶州當了近千年新羅的都城，今日整座城市就是一座沒有屋頂的博物館：街區之間的王陵、七世紀的天文台、佛國寺與山上的石窟庵。再往北，安東保有河回村與各處書院，宗族禮儀在此是真實延續而非為遊客表演。其間散布著山巒、古寺，以及周王山那樣的岩石峽谷。","bestTime":"4月（櫻花）與10至11月","specialties":["安東燉雞","安東鹽漬鯖魚","慶州皇南麵包","安東燒酒"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('gyeonggi', 'sudogwon', 'Gyeonggi', 'Gyeonggi', 'Vùng Thủ đô Seoul', '#c7993f', 127.168, 37.5164, 'Tỉnh ôm trọn Seoul, giữ những toà thành UNESCO, làng dân tộc và cả ranh giới chia đôi bán đảo.', 'Gyeonggi bao quanh thủ đô như một vành đai, và gần như mọi chuyến đi trong ngày từ Seoul đều kết thúc ở đây. Suwon có thành Hwaseong — công trình phòng thủ tinh xảo bậc nhất triều Joseon. Yongin có làng dân tộc nơi nghề thủ công cũ vẫn được làm thật. Về phía đông là dãy núi với sơn thành Namhansanseong; phía bắc, đường quốc lộ dẫn thẳng tới Imjingak và vùng phi quân sự, nơi lịch sử chưa khép lại. Xen giữa là những trang trại, hồ chứa và quán cà phê ven núi mà người Seoul lái xe ra vào cuối tuần.', 'Tháng 4–6 và 9–11', '["Galbi Suwon","Đậu phụ Namhansanseong","Cơm trộn nấm"]', '{"en":{"name":"Gyeonggi","summary":"The province that wraps around Seoul, holding UNESCO fortresses, a folk village and the line that divides the peninsula.","story":"Gyeonggi encircles the capital, and almost every day trip from Seoul ends up here. Suwon has Hwaseong, the most refined piece of defensive engineering of the Joseon era. Yongin has a folk village where old crafts are genuinely practised. To the east rise the mountains of Namhansanseong; to the north the highway runs straight to Imjingak and the Demilitarized Zone, where history has not yet closed. In between are farms, reservoirs and the hillside cafés Seoulites drive out to at weekends.","bestTime":"April–June and September–November","specialties":["Suwon galbi","Namhansanseong tofu","Mushroom rice"]},"ko":{"name":"경기도","summary":"서울을 감싸는 도. 세계유산 성곽과 민속촌, 그리고 분단선까지 품고 있다.","story":"경기도는 수도를 띠처럼 두르고 있어 서울에서 떠나는 당일치기는 대개 여기서 끝난다. 수원에는 조선 최고의 축성 기술이 담긴 화성이 있고, 용인에는 옛 장인의 손일이 실제로 이어지는 민속촌이 있다. 동쪽 산줄기에는 남한산성이, 북쪽 국도 끝에는 임진각과 비무장지대가 있어 아직 닫히지 않은 역사와 마주한다. 그 사이로 농장과 저수지, 주말이면 서울 사람들이 차를 몰고 나오는 산자락 카페들이 흩어져 있다.","bestTime":"4~6월, 9~11월","specialties":["수원 갈비","남한산성 두부","버섯밥"]},"ja":{"name":"京畿道","summary":"ソウルを取り囲む道。世界遺産の城郭と民俗村、そして分断線までを抱える。","story":"京畿道は首都を帯のように囲み、ソウル発の日帰り旅はたいていここで終わる。水原には朝鮮随一の築城技術が凝縮された華城があり、龍仁には昔の手仕事が本当に続く民俗村がある。東の山並みには南漢山城、北の街道の先には臨津閣と非武装地帯があり、まだ閉じていない歴史と向き合う。その間に農場や貯水池、週末にソウルの人々が車で向かう山あいのカフェが点在する。","bestTime":"4〜6月、9〜11月","specialties":["水原カルビ","南漢山城の豆腐","きのこ飯"]},"zh":{"name":"京畿道","summary":"環抱首爾的一道，擁有世界遺產城郭、民俗村，以及分隔半島的那條線。","story":"京畿道像一條腰帶圍著首都，幾乎每一趟從首爾出發的一日遊都在這裡結束。水原有華城，朝鮮時代最精巧的防禦工程；龍仁有民俗村，舊時手藝在此真實地被實踐。往東是南漢山城所在的山脈；往北，公路一路通往臨津閣與非軍事區，那裡的歷史尚未合上。其間散布著農場、水庫，以及首爾人週末開車前往的山邊咖啡館。","bestTime":"4至6月、9至11月","specialties":["水原排骨","南漢山城豆腐","菇飯"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('gyeongnam', 'gyeongnam', 'Gyeongnam', 'South Gyeongsang', 'Nam Gyeongsang', '#5a8aa6', 128.2916, 35.3428, 'Tỉnh của quần đảo phía nam, chùa Haeinsa lưu giữ mộc bản Cao Ly và những cung đường ven biển.', 'Gyeongsangnam-do ôm lấy vùng biển vỡ thành hàng trăm đảo ở phía nam. Tongyeong và Geoje sống bằng nghề biển và phà; Namhae có ruộng bậc thang đổ thẳng xuống nước; Jinju giữ toà thành gắn với cuộc chiến Nhâm Thìn và lễ hội đèn lồng tháng 10. Sâu trong núi Gayasan là Haeinsa, nơi 81.258 tấm mộc bản kinh Phật nằm nguyên vẹn suốt bảy thế kỷ trong những nhà kho gỗ thông gió tự nhiên. Ẩm thực ở đây mặn mòi vị biển, nhiều món ăn sống.', 'Tháng 4–6 và 9–11', '["Kimbap Chungmu","Bibimbap Jinju","Cá nóc hầm","Hàu Tongyeong"]', '{"en":{"name":"South Gyeongsang","summary":"The province of the southern archipelago, of Haeinsa''s woodblocks and of coastal roads.","story":"South Gyeongsang embraces the sea where the land shatters into hundreds of islands. Tongyeong and Geoje live by fishing and ferries; Namhae has terraces that fall straight into the water; Jinju keeps a fortress bound up with the Imjin War and an October lantern festival. Deep in the Gayasan mountains sits Haeinsa, where 81,258 woodblocks of the Buddhist canon have survived seven centuries in naturally ventilated wooden halls. The food here tastes of the sea, and much of it is eaten raw.","bestTime":"April–June and September–November","specialties":["Chungmu gimbap","Jinju bibimbap","Braised pufferfish","Tongyeong oysters"]},"ko":{"name":"경상남도","summary":"남해 군도와 해인사 경판, 그리고 해안도로의 도.","story":"경상남도는 육지가 수백 개의 섬으로 부서지는 남쪽 바다를 품는다. 통영과 거제는 어업과 배로 살아가고, 남해에는 바다로 곧장 떨어지는 계단논이 있으며, 진주는 임진왜란의 성과 10월의 유등축제를 지킨다. 가야산 깊은 곳 해인사에서는 팔만대장경 81,258장이 자연 통풍의 목조 창고 안에서 700년을 견뎠다. 이곳의 음식은 바다 맛이 진하고 날것으로 먹는 것이 많다.","bestTime":"4~6월, 9~11월","specialties":["충무김밥","진주비빔밥","복국","통영 굴"]},"ja":{"name":"慶尚南道","summary":"南海の群島と海印寺の経板、そして海岸道路の道。","story":"慶尚南道は陸地が数百の島に砕ける南の海を抱く。統営と巨済は漁業と船で暮らし、南海には海へまっすぐ落ちる棚田があり、晋州は壬辰倭乱の城と10月の流灯祭りを守る。伽耶山の奥の海印寺では、八万大蔵経81,258枚が自然通風の木造の蔵の中で700年を耐えた。ここの料理は海の味が濃く、生で食べるものが多い。","bestTime":"4〜6月、9〜11月","specialties":["忠武キンパ","晋州ビビンバ","フグ鍋","統営の牡蠣"]},"zh":{"name":"慶尚南道","summary":"南海群島、海印寺經板與海岸公路之道。","story":"慶尚南道環抱著陸地碎成數百座島嶼的南方海域。統營與巨濟靠漁業與渡輪維生；南海有直落海面的梯田；晉州守著與壬辰倭亂相連的城池與十月的流燈節。在伽倻山深處的海印寺，81,258塊佛經經板在自然通風的木造藏經閣中安然度過七個世紀。這裡的食物海味濃厚，許多是生食。","bestTime":"4至6月、9至11月","specialties":["忠武紫菜飯捲","晉州拌飯","河豚湯","統營生蠔"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('incheon', 'sudogwon', 'Incheon', 'Incheon', 'Vùng Thủ đô Seoul', '#c7993f', 126.6869, 37.4625, 'Cửa ngõ hàng không của Hàn Quốc, nơi cảng biển cũ, phố người Hoa và một thành phố lấn biển cùng tồn tại.', 'Phần lớn du khách chỉ biết Incheon qua sân bay, nhưng thành phố này là nơi Hàn Quốc mở cửa ra thế giới từ năm 1883. Cảng cũ để lại khu phố người Hoa với món jjajangmyeon trứ danh, những kho hàng gạch đỏ nay thành bảo tàng, và bến phà đi ra hàng chục hòn đảo ngoài khơi biển Hoàng Hải. Ở hướng ngược lại là Songdo — cả một thành phố mọc lên từ đất lấn biển, kính và kênh nước. Cuối tuần dân Seoul đổ về đây ăn hải sản và ngắm hoàng hôn.', 'Tháng 4–6 và 9–10', '["Jjajangmyeon","Hải sản nướng","Bánh gongalppang"]', '{"en":{"name":"Incheon","summary":"Korea''s aviation gateway, where an old port, a Chinatown and a city built on reclaimed sea sit side by side.","story":"Most travellers know Incheon only from its airport, but this is where Korea opened to the world in 1883. The old port left behind a Chinatown with its famous jjajangmyeon, red-brick warehouses turned into museums, and a ferry terminal serving dozens of islands in the Yellow Sea. In the opposite direction lies Songdo — an entire city raised from reclaimed land, all glass and canals. At weekends Seoulites drive out here for seafood and sunsets.","bestTime":"April–June and September–October","specialties":["Jjajangmyeon","Grilled seafood","Gongal-ppang bread"]},"ko":{"name":"인천","summary":"한국의 관문 공항이 있는 도시. 옛 개항장과 차이나타운, 매립지 신도시가 공존한다.","story":"대부분의 여행자는 공항으로만 인천을 알지만, 이곳은 1883년 한국이 세계로 문을 연 자리다. 옛 개항장은 짜장면으로 유명한 차이나타운과 박물관이 된 붉은 벽돌 창고, 황해의 섬으로 향하는 연안부두를 남겼다. 반대편에는 매립지 위에 통째로 세운 유리와 수로의 도시 송도가 있다. 주말이면 서울 사람들이 해산물과 노을을 보러 이곳으로 넘어온다.","bestTime":"4~6월, 9~10월","specialties":["짜장면","해산물구이","공갈빵"]},"ja":{"name":"仁川","summary":"韓国の空の玄関口。旧開港場と中華街、埋立地の新都市が共存する。","story":"多くの旅行者は空港でしか仁川を知らないが、ここは1883年に韓国が世界へ開かれた場所だ。旧開港場はジャージャー麺で知られる中華街と、博物館になった赤煉瓦の倉庫、黄海の島々へ向かう沿岸埠頭を残した。反対側には埋立地の上に丸ごと造られたガラスと運河の街、松島がある。週末にはソウルの人々が海鮮と夕日を目当てにやってくる。","bestTime":"4〜6月、9〜10月","specialties":["ジャージャー麺","海鮮焼き","コンガルパン"]},"zh":{"name":"仁川","summary":"韓國的空中門戶，老港口、中華街與填海新城並存於此。","story":"多數旅人只在機場認識仁川，但這裡正是1883年韓國向世界開門的地方。老港區留下了以炸醬麵聞名的中華街、改成博物館的紅磚倉庫，以及通往黃海諸島的客運碼頭。另一頭則是松島——一整座建在填海地上的玻璃與運河之城。週末，首爾人開車來這裡吃海鮮、看落日。","bestTime":"4至6月、9至10月","specialties":["炸醬麵","炭烤海鮮","空心餅"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('jeju', 'jeju', 'Jeju', 'Jeju', 'Jeju', '#3e92a8', 126.5571, 33.3854, 'Hòn đảo núi lửa phía nam với hồ miệng núi trên đỉnh Hallasan, hang dung nham dưới lòng đất và những thợ lặn haenyeo.', 'Jeju nằm cách đất liền một chuyến bay ngắn nhưng giống một quốc gia riêng: tiếng địa phương khó nghe với cả người Seoul, tường đá đen xếp không vữa chạy dọc mọi thửa ruộng, và ba tượng đá dol hareubang canh cửa các ngôi làng. Cả hòn đảo là một khối núi lửa — Hallasan ở giữa, hơn ba trăm ngọn oreum nhỏ rải quanh, và hệ hang dung nham chạy ngầm bên dưới. Phụ nữ haenyeo vẫn lặn không bình khí để bắt bào ngư, một nghề đang mai một. Bờ đông đón bình minh, bờ tây giữ hoàng hôn, và đường mòn Olle nối tất cả lại thành 27 chặng đi bộ ven biển.', 'Tháng 4–6 và 9–11', '["Thịt heo đen nướng","Canh cá cam","Quýt Jeju","Bào ngư"]', '{"en":{"name":"Jeju","summary":"A volcanic island in the south with a crater lake on Hallasan, lava tubes beneath the ground and haenyeo diving off its shores.","story":"Jeju is a short flight from the mainland but feels like its own country: a dialect even Seoulites struggle with, black stone walls stacked without mortar along every field, and dol hareubang stone grandfathers guarding the village gates. The island is one volcanic mass — Hallasan in the middle, more than three hundred small oreum cones scattered around it, and a system of lava tubes running underneath. Haenyeo women still dive without air tanks for abalone, a trade now fading. The east coast takes the sunrise, the west keeps the sunset, and the Olle trail stitches it all together in 27 coastal walking stages.","bestTime":"April–June and September–November","specialties":["Grilled black pork","Braised cutlassfish","Jeju tangerines","Abalone"]},"ko":{"name":"제주","summary":"남쪽의 화산섬. 한라산 정상의 분화구 호수와 지하의 용암동굴, 그리고 해녀가 있다.","story":"제주는 육지에서 비행기로 잠깐이면 닿지만 하나의 다른 나라 같다. 서울 사람도 알아듣기 힘든 방언, 밭마다 시멘트 없이 쌓은 검은 돌담, 마을 어귀를 지키는 돌하르방. 섬 전체가 하나의 화산체다. 가운데 한라산이 있고 그 둘레에 300개가 넘는 오름이 흩어져 있으며 지하에는 용암동굴이 뻗어 있다. 해녀들은 여전히 산소통 없이 물질로 전복을 캔다. 사라져 가는 일이다. 동쪽 해안은 해돋이를, 서쪽은 노을을 품고, 올레길 27개 코스가 그 모두를 하나로 잇는다.","bestTime":"4~6월, 9~11월","specialties":["흑돼지구이","갈치조림","제주 감귤","전복"]},"ja":{"name":"済州","summary":"南の火山島。漢拏山の火口湖、地下の溶岩洞窟、そして海女がいる。","story":"済州は本土から短いフライトで着くのに、まるで別の国のようだ。ソウルの人でも聞き取りにくい方言、畑ごとにモルタルなしで積まれた黒い石垣、村の入口を守るトルハルバン。島全体がひとつの火山体で、中央に漢拏山、その周りに三百を超えるオルムが散らばり、地下には溶岩洞窟が伸びる。海女たちは今も空気ボンベなしで潜り、アワビを採る。消えつつある仕事だ。東の海岸は日の出を、西は夕日を抱き、オルレの27コースがそのすべてを結ぶ。","bestTime":"4〜6月、9〜11月","specialties":["黒豚の炭火焼き","タチウオの煮付け","済州みかん","アワビ"]},"zh":{"name":"濟州","summary":"南方的火山島：漢拏山頂的火口湖、地下的熔岩洞，以及潛水的海女。","story":"濟州離本土只有一段短程航班，感覺卻像另一個國家：連首爾人都聽不太懂的方言、每塊田邊不用灰漿疊起的黑石牆、守在村口的石頭爺爺。整座島是一個火山體——中間是漢拏山，周圍散布三百多座小火山錐，地底則有熔岩洞穿行。海女至今仍不帶氧氣瓶潛水採鮑，這門手藝正在消失。東岸迎日出，西岸留日落，二十七段的偶來步道把這一切串成一線。","bestTime":"4至6月、9至11月","specialties":["炭烤黑豬肉","燉白帶魚","濟州橘","鮑魚"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('jeonbuk', 'honam', 'Jeonbuk', 'North Jeolla', 'Honam (Jeolla)', '#5d9e86', 127.1626, 35.6945, 'Quê hương bibimbap và làng hanok Jeonju, cùng những ngọn núi lá đỏ đẹp nhất mùa thu.', 'Jeollabuk-do là vựa lúa của Hàn Quốc, và điều đó thể hiện thẳng lên bàn ăn: Jeonju được UNESCO công nhận là Thành phố Ẩm thực Sáng tạo, với bibimbap dọn trong tô đồng và những bàn nhậu makgeolli mà mỗi bình rượu kéo theo cả mâm đồ ăn kèm. Ngoài Jeonju, tỉnh có núi Maisan với hơn tám mươi tháp đá do một người xếp bằng tay, Naejangsan nơi lá đỏ đẹp nhất nước, và bãi mộ đá Gochang dày đặc nhất thế giới.', 'Tháng 4–5 và 10–11', '["Bibimbap Jeonju","Makgeolli Jeonju","Canh giá đỗ kongnamul-gukbap","Bánh gạo Jeonju"]', '{"en":{"name":"North Jeolla","summary":"Home of bibimbap and the Jeonju hanok village, with the country''s finest autumn mountains.","story":"North Jeolla is Korea''s rice bowl, and it shows on the table: Jeonju is a UNESCO Creative City of Gastronomy, serving bibimbap in brass bowls and makgeolli by the kettle with a spread of side dishes. Beyond Jeonju, the province has Maisan with its eighty hand-stacked stone pagodas, Naejangsan where the autumn colour is the best in the country, and the Gochang dolmen field, the densest on earth.","bestTime":"April–May and October–November","specialties":["Jeonju bibimbap","Jeonju makgeolli","Bean sprout soup rice","Jeonju rice cakes"]},"ko":{"name":"전라북도","summary":"비빔밥과 전주한옥마을의 고장. 가을 단풍이 가장 아름다운 산들이 있다.","story":"전라북도는 한국의 곡창지대이고, 그것이 밥상에 그대로 드러난다. 전주는 유네스코 음식창의도시로 놋그릇에 담긴 비빔밥과, 주전자 하나에 안주 한 상이 딸려 나오는 막걸리집으로 유명하다. 전주를 벗어나면 손으로 쌓은 80여 기의 돌탑이 있는 마이산, 전국에서 단풍이 가장 곱다는 내장산, 세계에서 가장 조밀한 고창 고인돌 군락이 있다.","bestTime":"4~5월, 10~11월","specialties":["전주비빔밥","전주 막걸리","콩나물국밥","전주 떡"]},"ja":{"name":"全羅北道","summary":"ビビンバと全州韓屋村の地。秋の紅葉が最も美しい山々がある。","story":"全羅北道は韓国の穀倉地帯で、それが食卓にそのまま現れる。全州はユネスコ食文化創造都市で、真鍮の器のビビンバと、やかん一つにつまみ一膳が付くマッコリの店で知られる。全州を離れれば、手積みの石塔80基余りが立つ馬耳山、全国一の紅葉といわれる内蔵山、そして世界一密集した高敞の支石墓群がある。","bestTime":"4〜5月、10〜11月","specialties":["全州ビビンバ","全州マッコリ","豆もやしクッパ","全州の餅"]},"zh":{"name":"全羅北道","summary":"拌飯與全州韓屋村的故鄉，也有全國最美的秋山。","story":"全羅北道是韓國的米倉，這一點直接反映在餐桌上：全州是聯合國教科文組織美食創意城市，拌飯用黃銅碗盛，馬格利一壺配一整桌小菜。走出全州，這裡還有堆著八十多座手砌石塔的馬耳山、被視為全國最美秋色的內藏山，以及全球密度最高的高敞支石墓群。","bestTime":"4至5月、10至11月","specialties":["全州拌飯","全州馬格利","豆芽湯飯","全州年糕"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('jeonnam', 'honam', 'Jeonnam', 'South Jeolla', 'Honam (Jeolla)', '#5d9e86', 126.9717, 34.9332, 'Tỉnh cực nam với hàng nghìn hòn đảo, đồi chè Boseong và vùng đất ngập mặn được UNESCO ghi danh.', 'Jeollanam-do có nhiều đảo hơn bất kỳ tỉnh nào khác — hơn hai nghìn hòn rải khắp vùng biển tây nam — và bờ biển của nó là những bãi triều rộng hàng chục cây số, nay thuộc di sản thiên nhiên thế giới. Suncheonman đón sếu về mỗi đông; Boseong phủ đồi chè xanh; Yeosu sáng đèn suốt đêm bên cảng. Đây cũng là vùng ăn ngon nhất Hàn Quốc theo nhiều người bản xứ: hải sản tươi, hàng chục món phụ mỗi bữa, và món cá đuối lên men gây tranh cãi bậc nhất.', 'Tháng 5–6 và 9–11', '["Cá đuối lên men hongeo","Bạch tuộc nhỏ Muan","Trà xanh Boseong","Cơm ống tre Damyang"]', '{"en":{"name":"South Jeolla","summary":"The far south, with thousands of islands, the Boseong tea hills and UNESCO-listed tidal flats.","story":"South Jeolla has more islands than any other province — over two thousand scattered across the southwestern sea — and its coast is tidal flats stretching for tens of kilometres, now part of a world natural heritage site. Suncheonman receives its cranes every winter, Boseong wears its green tea hills, and Yeosu shines all night beside its harbour. Many Koreans consider this the best place in the country to eat: seafood straight from the water, dozens of side dishes at every meal, and the most divisive dish of all, fermented skate.","bestTime":"May–June and September–November","specialties":["Fermented skate (hongeo)","Muan baby octopus","Boseong green tea","Damyang bamboo rice"]},"ko":{"name":"전라남도","summary":"수천 개의 섬과 보성 차밭, 유네스코에 오른 갯벌의 남쪽 끝.","story":"전라남도는 어느 도보다 섬이 많다. 서남해에 2천 개가 넘는 섬이 흩어져 있고, 해안은 수십 킬로미터씩 이어지는 갯벌로 이제 세계자연유산이 되었다. 순천만은 겨울마다 두루미를 맞고, 보성은 초록 차밭을 두르고, 여수는 항구 옆에서 밤새 빛난다. 많은 한국 사람이 이 지역을 나라에서 가장 잘 먹는 곳으로 꼽는다. 갓 잡은 해산물, 끼니마다 수십 가지 반찬, 그리고 호불호가 가장 갈리는 홍어까지.","bestTime":"5~6월, 9~11월","specialties":["홍어삼합","무안 낙지","보성 녹차","담양 대통밥"]},"ja":{"name":"全羅南道","summary":"数千の島と宝城の茶畑、ユネスコに登録された干潟の南端。","story":"全羅南道はどの道より島が多い。南西の海に二千を超える島が散らばり、海岸は数十キロに及ぶ干潟で、今や世界自然遺産となった。順天湾は毎冬ツルを迎え、宝城は緑の茶畑をまとい、麗水は港のそばで夜通し輝く。多くの韓国人がこの地方を国で最も食事のおいしい場所に挙げる。獲れたての海の幸、毎食数十のおかず、そして最も好みの分かれるホンオ（発酵エイ）まで。","bestTime":"5〜6月、9〜11月","specialties":["ホンオサンハプ","務安のテナガダコ","宝城の緑茶","潭陽の竹筒飯"]},"zh":{"name":"全羅南道","summary":"擁有數千島嶼、寶城茶山與世界遺產灘塗的最南之道。","story":"全羅南道的島嶼比任何一道都多——西南海域散布著兩千多座——海岸則是綿延數十公里的灘塗，如今已是世界自然遺產。順天灣每年冬天迎來鶴群，寶城披著綠茶山坡，麗水在港邊徹夜發亮。許多韓國人認為這裡是全國最會吃的地方：現撈海鮮、每餐數十道小菜，還有最令人兩極的發酵魟魚。","bestTime":"5至6月、9至11月","specialties":["發酵魟魚三合","務安章魚","寶城綠茶","潭陽竹筒飯"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('sejong', 'chungcheong', 'Sejong', 'Sejong', 'Chungcheong', '#6e8c5a', 127.1835, 36.5487, 'Thành phố hành chính được xây mới hoàn toàn, nơi Hàn Quốc thử thiết kế lại một đô thị từ đầu.', 'Sejong ra đời từ một quyết định chính trị: dời phần lớn bộ ngành khỏi Seoul để giảm tải cho thủ đô. Kết quả là một thành phố hoàn toàn quy hoạch, đặt tên theo vị vua sáng tạo bảng chữ Hangeul. Toà nhà chính phủ dài hơn ba cây số với mái vườn đi bộ được, hồ nước lớn giữa trung tâm, vườn thực vật quốc gia và những khu nhà ở bố trí theo cụm. Không có phố cổ, không có chợ trăm tuổi — nhưng đây là chỗ để thấy Hàn Quốc hình dung tương lai đô thị của mình.', 'Tháng 4–6 và 9–10', '["Canh đậu tương Sejong","Bánh gạo hấp","Nấm địa phương"]', '{"en":{"name":"Sejong","summary":"A purpose-built administrative city — Korea''s experiment in designing an urban centre from zero.","story":"Sejong exists because of a political decision: move most ministries out of Seoul to relieve the capital. The result is a fully planned city named after the king who created the Hangeul alphabet. The government complex runs more than three kilometres with a walkable roof garden, a large lake sits at the centre, and housing is arranged in clusters, with a national arboretum alongside. There is no old town and no century-old market — but this is where you see how Korea imagines its urban future.","bestTime":"April–June and September–October","specialties":["Sejong soybean stew","Steamed rice cakes","Local mushrooms"]},"ko":{"name":"세종","summary":"새로 지은 행정도시. 한국이 도시를 처음부터 설계한 실험이다.","story":"세종은 정치적 결정에서 태어났다. 수도의 과밀을 덜기 위해 대부분의 부처를 서울 밖으로 옮긴 것이다. 그 결과 한글을 만든 임금의 이름을 딴, 완전히 계획된 도시가 생겼다. 정부청사는 3km 넘게 이어지고 옥상은 걸을 수 있는 정원이며, 도심에는 큰 호수가, 주거지는 생활권 단위로 배치되고 옆에는 국립수목원이 있다. 옛 시가지도 백 년 된 시장도 없지만, 한국이 상상하는 도시의 미래를 볼 수 있는 곳이다.","bestTime":"4~6월, 9~10월","specialties":["세종 된장찌개","찐 떡","지역 버섯"]},"ja":{"name":"世宗","summary":"新しく造られた行政都市。韓国が都市をゼロから設計した実験だ。","story":"世宗は政治的決定から生まれた。首都の過密を緩めるため、大半の省庁をソウルの外へ移したのである。その結果、ハングルを作った王の名を冠した、完全に計画された都市ができた。政府庁舎は3kmを超えて連なり屋上は歩ける庭園、都心には大きな湖、住宅は生活圏ごとに配置され、隣には国立樹木園がある。旧市街も百年の市場もないが、韓国が思い描く都市の未来を見られる場所だ。","bestTime":"4〜6月、9〜10月","specialties":["世宗のテンジャンチゲ","蒸し餅","地元のきのこ"]},"zh":{"name":"世宗","summary":"為行政而全新打造的城市，是韓國從零設計一座都市的實驗。","story":"世宗誕生於一項政治決定：把大部分部會遷出首爾，以紓解首都壓力。結果是一座完全規劃的城市，並以創制韓文的國王為名。政府大樓綿延三公里以上、屋頂是可行走的花園，市中心有一片大湖，住宅按生活圈成組佈置，旁邊還有一座國立樹木園。這裡沒有老城區，也沒有百年市場——但你能看見韓國如何想像自己的都市未來。","bestTime":"4至6月、9至10月","specialties":["世宗大醬湯","蒸年糕","在地菇類"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('seoul', 'sudogwon', 'Seoul', 'Seoul', 'Vùng Thủ đô Seoul', '#c7993f', 127.0077, 37.5379, 'Thủ đô nơi cung điện Joseon, chợ đêm và các toà tháp kính chen nhau trong cùng một khung hình.', 'Seoul là thành phố sáu trăm năm tuổi bị nén vào một hình hài rất mới. Buổi sáng bạn đứng trong sân chầu Gyeongbokgung nghe trống đổi gác; buổi chiều lạc giữa các ngõ hanok Bukchon; tối đến ăn đứng ở Myeongdong rồi lên Namsan nhìn cả thành phố sáng đèn hai bên sông Hàn. Bốn mùa ở đây rất rõ: xuân hoa anh đào dọc bờ sông, hè mưa rào và đêm nóng ẩm, thu trời cao lá đỏ, đông tuyết phủ mái ngói cung điện. Tàu điện ngầm chằng chịt và đúng giờ khiến việc đi lại gần như không cần suy nghĩ.', 'Tháng 4–5 (hoa anh đào) và tháng 9–11 (thu lá đỏ)', '["Gimbap","Tteokbokki","Samgyetang","Gà rán Hàn Quốc"]', '{"en":{"name":"Seoul","summary":"A capital where Joseon palaces, night markets and glass towers all crowd into the same frame.","story":"Seoul is a six-hundred-year-old city compressed into a very new shape. In the morning you stand in the court of Gyeongbokgung listening to the changing-of-the-guard drums; in the afternoon you get lost in the hanok lanes of Bukchon; at night you eat standing up in Myeongdong and then ride up Namsan to watch the city light up on both banks of the Han. The four seasons are sharply drawn: cherry blossom along the river in spring, downpours and humid nights in summer, high skies and red leaves in autumn, snow on palace roofs in winter. The subway is dense and punctual enough that getting around barely requires thought.","bestTime":"April–May (cherry blossom) and September–November (autumn colour)","specialties":["Gimbap","Tteokbokki","Samgyetang","Korean fried chicken"]},"ko":{"name":"서울","summary":"조선의 궁궐과 야시장, 유리 빌딩이 한 화면에 겹치는 수도.","story":"서울은 600년 된 도시가 아주 새로운 형태 안으로 압축된 곳이다. 아침에는 경복궁 조정에서 교대의식 북소리를 듣고, 오후에는 북촌 한옥 골목에서 길을 잃고, 저녁에는 명동에서 서서 먹은 뒤 남산에 올라 한강 양쪽으로 켜지는 불빛을 본다. 사계절이 뚜렷하다. 봄에는 강변의 벚꽃, 여름에는 소나기와 열대야, 가을에는 높은 하늘과 단풍, 겨울에는 궁궐 지붕 위의 눈. 촘촘하고 정확한 지하철 덕분에 이동은 거의 고민거리가 되지 않는다.","bestTime":"4~5월(벚꽃)과 9~11월(단풍)","specialties":["김밥","떡볶이","삼계탕","치킨"]},"ja":{"name":"ソウル","summary":"朝鮮の宮殿と夜市、ガラスの塔が同じ一枚に収まる首都。","story":"ソウルは六百年の都市が、とても新しい形の中に圧縮された街だ。朝は景福宮の庭で交代儀式の太鼓を聞き、午後は北村の韓屋の路地で道に迷い、夜は明洞で立ち食いをして南山に登り、漢江の両岸に灯りがともるのを眺める。四季がはっきりしている。春は川沿いの桜、夏はにわか雨と熱帯夜、秋は高い空と紅葉、冬は宮殿の屋根の雪。地下鉄が密で正確なので、移動はほとんど考えずに済む。","bestTime":"4〜5月（桜）と9〜11月（紅葉）","specialties":["キンパ","トッポッキ","参鶏湯","ヤンニョムチキン"]},"zh":{"name":"首爾","summary":"朝鮮宮殿、夜市與玻璃高樓擠進同一個畫面的首都。","story":"首爾是一座六百年的城市，被壓縮進非常新的形體之中。早上你站在景福宮的庭院聽換崗的鼓聲，午後在北村的韓屋巷弄裡迷路，晚上到明洞站著吃，再上南山看漢江兩岸次第亮起的燈火。四季分明：春天沿江的櫻花，夏天的驟雨與熱夜，秋天的高空與紅葉，冬天覆在宮殿瓦頂上的雪。地鐵密而準時，移動幾乎不必費心思。","bestTime":"4至5月（櫻花）與9至11月（紅葉）","specialties":["紫菜飯捲","辣炒年糕","蔘雞湯","韓式炸雞"]}}', 'kr');
INSERT OR REPLACE INTO provinces (slug, region_id, name, name_en, region_name, color, center_lng, center_lat, summary, story, best_time, specialties, i18n, country) VALUES ('ulsan', 'gyeongnam', 'Ulsan', 'Ulsan', 'Nam Gyeongsang', '#5a8aa6', 129.2317, 35.5157, 'Thủ phủ công nghiệp bên bờ biển Đông, giữ tranh khắc đá tiền sử và những mũi đất đón bình minh sớm nhất.', 'Ulsan là nơi đóng tàu và làm ô tô cho cả Hàn Quốc, nhưng ngay cạnh các nhà máy là bờ biển đá đẹp bậc nhất bán đảo. Sông Taehwa từng chết vì ô nhiễm nay xanh trở lại với dải tre mười dặm và đàn cò về mỗi chiều. Ngược lên thượng nguồn là vách đá Bangudae với tranh săn cá voi khắc từ sáu nghìn năm trước — Ulsan cũng từng là cảng săn cá voi lớn, nay chỉ còn bảo tàng và món thịt cá voi gây tranh cãi. Mũi Ganjeolgot thì đón mặt trời đầu tiên của cả nước.', 'Tháng 4–6 và 9–11', '["Canh cá nóng Ulsan","Bánh xèo hẹ","Hải sản nướng"]', '{"en":{"name":"Ulsan","summary":"An industrial capital on the East Sea that also holds prehistoric rock art and the earliest sunrises.","story":"Ulsan builds the ships and cars of Korea, but beside its factories lies some of the finest rocky coast on the peninsula. The Taehwa River, once killed by pollution, runs clear again with its ten-mile bamboo belt and its evening egrets. Upstream is the Bangudae cliff, carved with whale hunts six thousand years ago — Ulsan was once a great whaling port, a history now left to a museum and a controversial dish. Ganjeolgot cape takes the country''s first sunrise.","bestTime":"April–June and September–November","specialties":["Ulsan hot fish soup","Chive pancakes","Grilled seafood"]},"ko":{"name":"울산","summary":"동해안의 산업 수도. 선사시대 암각화와 가장 이른 해돋이를 품고 있다.","story":"울산은 한국의 배와 자동차를 만들지만, 공장 바로 옆에 반도에서 손꼽히는 아름다운 바위 해안이 있다. 오염으로 죽었던 태화강은 다시 맑아져 십리대숲과 저녁의 백로를 되찾았다. 상류에는 6천 년 전 고래잡이를 새긴 반구대 암벽이 있다. 울산은 한때 큰 포경항이었고 지금은 박물관과 논쟁적인 음식으로만 남아 있다. 간절곶은 나라에서 가장 먼저 해를 맞는다.","bestTime":"4~6월, 9~11월","specialties":["울산 대구탕","부추전","해산물구이"]},"ja":{"name":"蔚山","summary":"東海岸の産業首都。先史時代の岩刻画と最も早い日の出を抱える。","story":"蔚山は韓国の船と自動車をつくるが、工場のすぐ隣には半島屈指の美しい岩の海岸がある。汚染で死んでいた太和江は再び澄み、十里竹林と夕方のサギを取り戻した。上流には六千年前の捕鯨を刻んだ盤亀台の岩壁がある。蔚山はかつて大きな捕鯨港であり、今では博物館と物議を醸す料理だけがその名残だ。艮絶岬は国で最も早く日を迎える。","bestTime":"4〜6月、9〜11月","specialties":["蔚山のタラ鍋","ニラチヂミ","海鮮焼き"]},"zh":{"name":"蔚山","summary":"東海岸的工業首都，也擁有史前岩刻畫與全國最早的日出。","story":"蔚山為韓國造船造車，但工廠旁邊就是半島上最漂亮的岩石海岸。曾因污染而死去的太和江如今再度清澈，帶回了十里竹林與傍晚的白鷺。溯江而上，是刻著六千年前捕鯨場景的盤龜台崖壁——蔚山曾是重要的捕鯨港，如今只剩博物館與一道充滿爭議的菜餚。艮絕岬則最早迎來全國的日出。","bestTime":"4至6月、9至11月","specialties":["蔚山鱈魚湯","韭菜煎餅","炭烤海鮮"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gyeongbokgung', 'gyeongbokgung', 'seoul', 'Cung Gyeongbokgung', 'Gyeongbokgung Palace', 'palace', 126.977, 37.5796, 'Chính cung của vương triều Joseon, nơi mái ngói cong vút soi bóng lên những toà nhà kính của Seoul hiện đại.', 'Bước qua cổng Gwanghwamun, tiếng còi xe của trung tâm Seoul bỗng lùi lại phía sau. Gyeongbokgung — ''cung điện phúc lành lớn lao'' — được dựng năm 1395, chỉ ba năm sau khi Joseon lập quốc. Điện Geunjeongjeon nơi vua thiết triều đứng trên hai tầng bệ đá, hai bên là hàng phẩm giai khắc tên quan văn quan võ. Phía sau, gác Gyeonghoeru nổi trên mặt hồ vuông, mùa hè sen phủ kín, mùa đông mặt nước đóng băng phản chiếu núi Bugaksan. Cung từng bị đốt trong chiến tranh Nhâm Thìn rồi bị thực dân phá dỡ; những gì bạn thấy hôm nay là công cuộc phục dựng kéo dài nhiều thập kỷ và vẫn đang tiếp tục.', '["Được xây năm 1395, là cung điện đầu tiên và lớn nhất trong năm cung của triều Joseon.","Lễ đổi gác Sumunjang diễn ra trước cổng Gwanghwamun hai lần mỗi ngày.","Gác Gyeonghoeru dựng trên 48 cột đá, từng là nơi vua thết đãi sứ thần.","Khách mặc hanbok được miễn phí vé vào cửa.","Bảo tàng Cung điện Quốc gia và Bảo tàng Dân gian Quốc gia nằm ngay trong khuôn viên."]', '["Thuê hanbok ở các cửa hiệu quanh ga Anguk để vừa miễn vé vừa có ảnh đẹp.","Cung đóng cửa thứ Ba — hãy đổi sang Changdeokgung nếu lỡ lịch.","Đi sớm 9h sáng để chụp điện Geunjeongjeon khi chưa đông người."]', 'Tháng 4–5 (hoa xuân) và tháng 10–11 (lá phong)', '2–3 giờ', '3.000 KRW (miễn phí nếu mặc hanbok)', '09:00–18:00 (tháng 11–2 đến 17:00; tháng 6–8 đến 18:30), đóng cửa thứ Ba', '["popular","verified"]', '["cung điện","lịch sử","hanbok","Joseon"]', '[{"seed":"gyeongbokgung","caption":"Điện Geunjeongjeon nhìn từ sân chầu","ratio":"16/9"},{"seed":"gyeongbokgung-gyeonghoeru","caption":"Gác Gyeonghoeru trên mặt hồ","ratio":"4/3"}]', '["changdeokgung","bukchon-hanok-village"]', 1, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=87740', '2026-08-04', '{"en":{"name":"Gyeongbokgung Palace","summary":"The main palace of the Joseon dynasty, its curved tile roofs mirrored in the glass towers of modern Seoul.","story":"Step through Gwanghwamun gate and the traffic of central Seoul falls away behind you. Gyeongbokgung — the ''palace greatly blessed by heaven'' — was raised in 1395, only three years after Joseon was founded. Geunjeongjeon Hall, where kings held court, stands on a double stone terrace flanked by rank stones marking where each official stood. Behind it, Gyeonghoeru pavilion floats on a square pond: lotus in summer, frozen and mirroring Bugaksan in winter. The palace burned in the Imjin War and was later dismantled under colonial rule; what you see today is a restoration that has run for decades and is still going on.","facts":["Built in 1395, the first and largest of the five Joseon palaces.","The Sumunjang changing of the guard takes place twice a day in front of Gwanghwamun.","Gyeonghoeru pavilion rests on 48 stone pillars and once hosted royal banquets for foreign envoys.","Entry is free for visitors wearing hanbok.","The National Palace Museum and National Folk Museum sit inside the grounds."],"travelTips":["Rent hanbok near Anguk station — it waives the ticket and makes for better photos.","Closed on Tuesdays; switch to Changdeokgung if your day falls wrong.","Arrive at 9am to photograph Geunjeongjeon before the crowds."],"bestTime":"April–May (spring blossom) and October–November (autumn colour)","visitDuration":"2–3 hours","ticket":"3,000 KRW (free in hanbok)","openingHours":"09:00–18:00 (to 17:00 Nov–Feb, to 18:30 Jun–Aug), closed Tuesdays","galleryCaptions":["Geunjeongjeon Hall seen from the court","Gyeonghoeru pavilion on its pond"]},"ko":{"name":"경복궁","summary":"조선 왕조의 법궁. 처마의 곡선이 서울의 유리 빌딩과 한 화면에 담긴다.","story":"광화문을 지나면 도심의 소음이 뒤로 물러난다. ''큰 복을 누리라''는 뜻의 경복궁은 조선 개국 3년 뒤인 1395년에 세워졌다. 왕이 조회를 열던 근정전은 이중 월대 위에 서 있고, 양옆에는 문무백관의 자리를 표시한 품계석이 늘어서 있다. 뒤편의 경회루는 네모난 연못 위에 떠 있어 여름에는 연꽃이, 겨울에는 얼어붙은 수면에 북악산이 비친다. 임진왜란 때 불타고 일제강점기에 헐린 이 궁궐은 수십 년째 복원이 이어지는 중이다.","facts":["1395년 창건된 조선 최초이자 최대의 궁궐이다.","광화문 앞에서 수문장 교대의식이 하루 두 차례 열린다.","경회루는 48개의 돌기둥 위에 서 있으며 사신 접대 연회장이었다.","한복을 입으면 입장료가 면제된다.","경내에 국립고궁박물관과 국립민속박물관이 있다."],"travelTips":["안국역 주변에서 한복을 대여하면 입장료도 면제되고 사진도 좋다.","화요일 휴궁이니 일정이 겹치면 창덕궁으로 바꾸자.","오전 9시에 가면 근정전을 한산할 때 담을 수 있다."],"bestTime":"4~5월(봄꽃)과 10~11월(단풍)","visitDuration":"2~3시간","ticket":"3,000원(한복 착용 시 무료)","openingHours":"09:00~18:00(11~2월 17:00까지, 6~8월 18:30까지), 화요일 휴관","galleryCaptions":["조정에서 바라본 근정전","연못 위의 경회루"]},"ja":{"name":"景福宮","summary":"朝鮮王朝の正宮。反り返った瓦屋根が、ソウルのガラスの高層ビルと同じ画面に収まる。","story":"光化門をくぐると、都心の喧騒が背後に退く。「大いなる福」を意味する景福宮は、朝鮮建国からわずか三年後の1395年に築かれた。王が政務を執った勤政殿は二重の月台の上に建ち、両脇には文武百官の位置を示す品階石が並ぶ。その奥、慶会楼は四角い池に浮かび、夏は蓮に覆われ、冬は凍った水面に北岳山を映す。壬辰倭乱で焼け、植民地時代に解体されたこの宮殿は、数十年にわたる復元が今も続いている。","facts":["1395年創建、朝鮮五大宮のうち最初かつ最大の宮殿。","光化門前では守門将の交代儀式が一日二回行われる。","慶会楼は48本の石柱の上に建ち、使節をもてなす宴の場だった。","韓服を着用すると入場料が無料になる。","敷地内に国立古宮博物館と国立民俗博物館がある。"],"travelTips":["安国駅周辺で韓服を借りれば入場無料になり、写真も映える。","火曜休宮。日程が合わなければ昌徳宮に振り替えよう。","午前9時に入れば、人が少ないうちに勤政殿を撮れる。"],"bestTime":"4〜5月（春の花）と10〜11月（紅葉）","visitDuration":"2〜3時間","ticket":"3,000ウォン（韓服着用で無料）","openingHours":"09:00〜18:00（11〜2月は17:00まで、6〜8月は18:30まで）、火曜休み","galleryCaptions":["朝廷から見た勤政殿","池に浮かぶ慶会楼"]},"zh":{"name":"景福宮","summary":"朝鮮王朝的正宮，翹起的瓦頂與首爾的玻璃高樓同框而立。","story":"穿過光化門，市中心的喧囂便退到身後。意為「大福」的景福宮建於1395年，距朝鮮開國僅三年。國王臨朝的勤政殿立於雙層月台之上，兩側排列著標示文武百官位置的品階石。其後的慶會樓浮於方形池上：夏日荷花滿池，冬日水面結冰，映出北岳山。這座宮殿在壬辰倭亂中焚毀，殖民時期又遭拆除，今日所見是延續數十年、至今仍在進行的復原工程。","facts":["建於1395年，是朝鮮五大宮中最早也最大的一座。","光化門前每日兩次舉行守門將換崗儀式。","慶會樓立於48根石柱之上，曾是宴請使節之所。","身著韓服可免費入場。","園內設有國立古宮博物館與國立民俗博物館。"],"travelTips":["在安國站一帶租韓服，既免門票又適合拍照。","週二閉宮，行程若撞上可改去昌德宮。","上午九點入場，可在人潮之前拍到勤政殿。"],"bestTime":"4至5月（春花）與10至11月（紅葉）","visitDuration":"2至3小時","ticket":"3,000韓元（著韓服免費）","openingHours":"09:00–18:00（11至2月至17:00，6至8月至18:30），週二休館","galleryCaptions":["自朝廷望向勤政殿","池上的慶會樓"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('changdeokgung', 'changdeokgung', 'seoul', 'Cung Changdeokgung & Hậu Uyển', 'Changdeokgung Palace & Secret Garden', 'unesco', 126.991, 37.5794, 'Cung điện được UNESCO ghi danh, nổi tiếng vì thuận theo thế núi thay vì bắt núi thuận theo mình.', 'Nếu Gyeongbokgung là quyền lực bày ra cho thiên hạ xem thì Changdeokgung là chốn các vị vua thực sự muốn sống — và họ đã sống ở đây lâu hơn bất kỳ cung nào khác. Thay vì san phẳng đất để dựng trục đối xứng, kiến trúc sư Joseon để các điện men theo sườn đồi, mỗi mái ngói nằm ở một cao độ khác nhau. Phía sau là Huwon, ''Hậu Uyển'' rộng hơn 30 hecta chỉ mở theo tour có hướng dẫn: một hồ vuông tượng trưng cho đất, đảo tròn giữa hồ tượng trưng cho trời, và những đình tạ nhỏ nơi vua đọc sách. Mùa thu, cả khu vườn chuyển sang màu đồng đỏ.', '["Được UNESCO công nhận Di sản Thế giới năm 1997.","Là nơi ở của các vua Joseon suốt hơn 250 năm.","Hậu Uyển chỉ vào được theo tour có hướng dẫn, số lượng khách giới hạn mỗi suất.","Điện Injeongjeon từng là nơi cử hành lễ đăng cơ của nhiều vị vua."]', '["Đặt vé tour Hậu Uyển trước trên mạng — suất tiếng Anh rất nhanh hết.","Vé cung và vé Hậu Uyển tính riêng, nhớ mua cả hai.","Đi giày êm: đường trong vườn là dốc đất và sỏi."]', 'Cuối tháng 10 đến giữa tháng 11 (mùa lá đỏ)', '2–3 giờ', '3.000 KRW (tour Hậu Uyển thêm 8.000 KRW)', '09:00–18:00 (tháng 11–1 đến 17:30; tháng 6–8 đến 18:30), đóng cửa thứ Hai', '["unesco","verified"]', '["UNESCO","cung điện","vườn","mùa thu"]', '[{"seed":"changdeokgung","caption":"Điện Injeongjeon","ratio":"16/9"}]', '["gyeongbokgung","bukchon-hanok-village"]', 1, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=94399', '2026-08-04', '{"en":{"name":"Changdeokgung Palace & Secret Garden","summary":"A UNESCO-listed palace famous for bending to the shape of the hill instead of forcing the hill to bend to it.","story":"If Gyeongbokgung was power on display, Changdeokgung was where the kings actually wanted to live — and they lived here longer than in any other palace. Rather than level the ground for a symmetrical axis, Joseon architects let the halls follow the slope, each roof at its own height. Behind them lies Huwon, the ''Secret Garden'' of more than 30 hectares, open only by guided tour: a square pond for the earth, a round island for the heavens, and small pavilions where kings came to read. In autumn the whole garden turns copper.","facts":["Inscribed as a UNESCO World Heritage Site in 1997.","Joseon kings lived here for more than 250 years.","The Secret Garden can only be entered on a guided tour with limited places.","Injeongjeon Hall hosted the coronations of several kings."],"travelTips":["Book the Secret Garden tour online — English slots sell out quickly.","Palace and garden tickets are separate; buy both.","Wear comfortable shoes: the garden paths are gravel and packed earth."],"bestTime":"Late October to mid-November (autumn leaves)","visitDuration":"2–3 hours","ticket":"3,000 KRW (Huwon guided tour a further 8,000 KRW)","openingHours":"09:00–18:00 (to 17:30 Nov–Jan, to 18:30 Jun–Aug), closed Mondays","galleryCaptions":["Injeongjeon Hall"]},"ko":{"name":"창덕궁과 후원","summary":"산을 깎지 않고 산세를 따라 앉힌 궁궐. 유네스코 세계유산이다.","story":"경복궁이 보여주기 위한 권위였다면 창덕궁은 왕들이 실제로 살고 싶어 한 곳이었고, 실제로 어느 궁보다 오래 머물렀다. 대칭 축을 만들려고 땅을 고르는 대신, 전각들이 언덕을 따라 저마다 다른 높이에 앉았다. 뒤편 30만 제곱미터의 후원은 해설 관람으로만 열린다. 땅을 뜻하는 네모난 연못과 하늘을 뜻하는 둥근 섬, 왕이 책을 읽던 작은 정자들이 이어지고, 가을이면 정원 전체가 구릿빛으로 물든다.","facts":["1997년 유네스코 세계문화유산에 등재되었다.","조선의 왕들이 250년 넘게 거처한 궁궐이다.","후원은 인원이 제한된 해설 관람으로만 입장할 수 있다.","인정전에서는 여러 왕의 즉위식이 거행되었다."],"travelTips":["후원 관람은 온라인 예약이 필수, 외국어 회차는 빨리 마감된다.","궁궐 입장권과 후원 관람권은 별도이니 둘 다 준비하자.","후원 길은 흙과 자갈이라 편한 신발이 좋다."],"bestTime":"10월 말~11월 중순(단풍)","visitDuration":"2~3시간","ticket":"3,000원(후원 관람 8,000원 별도)","openingHours":"09:00~18:00(11~1월 17:30까지, 6~8월 18:30까지), 월요일 휴관","galleryCaptions":["인정전"]},"ja":{"name":"昌徳宮と後苑","summary":"山を削らず地形に沿わせて建てた宮殿。ユネスコ世界遺産。","story":"景福宮が見せるための権威だったとすれば、昌徳宮は王たちが実際に住みたがった場所であり、事実どの宮よりも長く暮らした。左右対称の軸を通すために地面を均すのではなく、建物が丘の傾斜に従いそれぞれ違う高さに座る。奥に広がる30ヘクタール超の後苑はガイドツアーでのみ公開される。地を表す四角い池と天を表す円い島、王が書を読んだ小さな東屋。秋には庭全体が銅色に染まる。","facts":["1997年にユネスコ世界文化遺産に登録された。","朝鮮の王が250年以上暮らした宮殿。","後苑は人数制限のあるガイドツアーでのみ入場できる。","仁政殿では複数の王の即位式が行われた。"],"travelTips":["後苑ツアーはオンライン予約必須。外国語回は早く埋まる。","宮殿と後苑の入場券は別なので両方用意しよう。","後苑の道は土と砂利。歩きやすい靴を。"],"bestTime":"10月下旬〜11月中旬（紅葉）","visitDuration":"2〜3時間","ticket":"3,000ウォン（後苑の観覧は別途8,000ウォン）","openingHours":"09:00〜18:00（11〜1月は17:30まで、6〜8月は18:30まで）、月曜休み","galleryCaptions":["仁政殿"]},"zh":{"name":"昌德宮與後苑","summary":"順著山勢而非削山而建的宮殿，已列入世界遺產。","story":"若說景福宮是給人看的威權，昌德宮則是國王真正願意居住的地方，事實上他們在此停留的時間比任何一座宮都長。工匠沒有為對稱中軸而削平地面，而是讓殿宇沿著山坡各安其位、高低不一。宮後三十多公頃的後苑僅開放導覽入場：方池象徵大地，圓島象徵蒼天，還有幾座供國王讀書的小亭。到了秋天，整座園子染成銅色。","facts":["1997年列入聯合國教科文組織世界文化遺產。","朝鮮諸王在此居住逾250年。","後苑僅能參加限額的導覽團進入。","多位國王的即位大典在仁政殿舉行。"],"travelTips":["後苑導覽須線上預約，外語場次很快額滿。","宮殿門票與後苑門票分開販售，兩者都要買。","後苑步道為泥土與碎石，請穿好走的鞋。"],"bestTime":"10月下旬至11月中旬（紅葉）","visitDuration":"2至3小時","ticket":"3,000韓元（後苑導覽另收8,000韓元）","openingHours":"09:00–18:00（11至1月至17:30，6至8月至18:30），週一休館","galleryCaptions":["仁政殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jongmyo-shrine', 'jongmyo-shrine', 'seoul', 'Tông miếu Jongmyo', 'Jongmyo Shrine', 'unesco', 126.994, 37.5747, 'Nơi thờ bài vị các vua Joseon: một mái nhà gỗ dài hun hút, trống trải đến mức thành ra trang nghiêm.', 'Jongmyo không có tượng, không tranh, không sơn son thếp vàng. Chỉ có Jeongjeon — một dãy hành lang gỗ dài hơn trăm mét với mười chín gian cửa đóng kín, mỗi gian giữ bài vị một vị vua và hoàng hậu. Con đường đá dẫn vào được chia làm ba làn: làn giữa cao hơn dành cho linh hồn, người sống đi hai bên. Sự trống trải ấy là chủ ý — kiến trúc Nho giáo dùng tỉ lệ và im lặng thay cho trang trí. Mỗi tháng Năm, lễ Jongmyo Jerye được cử hành đúng nghi thức thế kỷ 15, với dàn nhạc cung đình và vũ công đội mũ đen chuyển động chậm như đồng hồ.', '["Được UNESCO công nhận Di sản Thế giới năm 1995.","Điện Jeongjeon dài khoảng 101m, là công trình gỗ truyền thống dài nhất châu Á.","Lễ Jongmyo Jerye và nhạc lễ Jeryeak là Di sản văn hoá phi vật thể của UNESCO.","Ngày thường chỉ vào được theo tour có hướng dẫn; riêng thứ Bảy được đi tự do.","Từng nối liền với Changdeokgung bằng một dải rừng, nay được phục hồi bằng cầu đi bộ."]', '["Kiểm tra lịch tour theo ngôn ngữ trước khi đi — số suất tiếng Anh hạn chế.","Đi vào thứ Bảy nếu bạn muốn tự đi và dừng lại lâu ở sân Jeongjeon.","Ghé cùng ngày với Changdeokgung: hai nơi cách nhau một cây cầu đi bộ."]', 'Tháng 5 (lễ Jongmyo Jerye) và tháng 10–11', '1–1,5 giờ', '1.000 KRW (miễn phí dưới 19 và trên 65 tuổi)', '09:00–18:00 (tháng 11–1 đến 17:30; tháng 6–8 đến 18:30), đóng cửa thứ Ba', '["unesco","hidden-gem"]', '["UNESCO","Nho giáo","nghi lễ","kiến trúc gỗ"]', '[{"seed":"jongmyo-shrine","caption":"Hành lang Jeongjeon","ratio":"16/9"}]', '["changdeokgung","ikseon-dong"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=94412', '2026-08-04', '{"en":{"name":"Jongmyo Shrine","summary":"Where the spirit tablets of the Joseon kings are kept: one long wooden hall, so bare it becomes solemn.","story":"Jongmyo has no statues, no paintings, no gilding. Only Jeongjeon — a wooden colonnade over a hundred metres long with nineteen closed doors, each holding the tablets of one king and queen. The stone path in is split into three lanes: the raised middle one is for the spirits, the living walk to either side. The emptiness is deliberate; Confucian architecture uses proportion and silence instead of ornament. Each May the Jongmyo Jerye rite is performed exactly as it was in the 15th century, with court musicians and black-hatted dancers moving as slowly as clockwork.","facts":["Inscribed as a UNESCO World Heritage Site in 1995.","Jeongjeon hall is about 101m long — the longest traditional wooden building in Asia.","The Jongmyo Jerye rite and its Jeryeak music are on UNESCO''s intangible heritage list.","On weekdays entry is by guided tour only; Saturdays are free-roaming.","It was once joined to Changdeokgung by a strip of forest, now restored as a footbridge."],"travelTips":["Check the tour timetable by language before you go — English slots are limited.","Come on a Saturday if you want to wander and linger in the Jeongjeon courtyard.","Pair it with Changdeokgung; the two are a footbridge apart."],"bestTime":"May (the Jongmyo Jerye rite) and October–November","visitDuration":"1–1.5 hours","ticket":"1,000 KRW (free under 19 and over 65)","openingHours":"09:00–18:00 (to 17:30 Nov–Jan, to 18:30 Jun–Aug), closed Tuesdays","galleryCaptions":["The Jeongjeon colonnade"]},"ko":{"name":"종묘","summary":"조선 역대 왕의 신주를 모신 곳. 길고 텅 빈 목조 건물 하나가 그대로 엄숙함이 된다.","story":"종묘에는 조각도, 그림도, 단청의 화려함도 없다. 오직 정전뿐이다. 100m가 넘는 목조 회랑에 열아홉 개의 닫힌 문이 늘어서 있고, 각 칸에 왕과 왕비의 신주가 모셔져 있다. 들어가는 돌길은 세 갈래로 나뉜다. 한 단 높은 가운데 길은 혼령의 길이고 산 사람은 양옆으로 걷는다. 이 비움은 의도된 것이다. 유교 건축은 장식 대신 비례와 침묵을 쓴다. 해마다 5월이면 15세기 그대로의 종묘제례가 봉행된다. 궁중 악사가 연주하고, 검은 관을 쓴 일무원이 시계처럼 천천히 움직인다.","facts":["1995년 유네스코 세계유산으로 등재되었다.","정전은 길이 약 101m로, 아시아에서 가장 긴 전통 목조 건축물이다.","종묘제례와 제례악은 유네스코 무형유산이다.","평일에는 해설 관람만 가능하고 토요일은 자유 관람이다.","창덕궁과 숲으로 이어져 있었고, 지금은 보행교로 복원되었다."],"travelTips":["언어별 해설 시간을 미리 확인하자. 영어 회차는 자리가 적다.","천천히 머물고 싶다면 자유 관람이 가능한 토요일에 가자.","창덕궁과 같은 날 묶어서 보자. 보행교 하나로 이어진다."],"bestTime":"5월(종묘대제)과 10~11월","visitDuration":"1~1.5시간","ticket":"1,000원(만 19세 미만·65세 이상 무료)","openingHours":"09:00~18:00(11~1월 17:30까지, 6~8월 18:30까지), 화요일 휴관","galleryCaptions":["정전의 긴 회랑"]},"ja":{"name":"宗廟","summary":"朝鮮歴代王の位牌を祀る場所。長く空虚な木造の建物が、そのまま荘厳さになっている。","story":"宗廟には像も絵も、極彩色の装飾もない。あるのは正殿だけだ。100mを超える木造の回廊に十九の閉じた扉が並び、それぞれに王と王妃の位牌が納められている。参道は三筋に分かれ、一段高い中央は霊の道、生きた者は両脇を歩く。この空虚さは意図されたものだ。儒教建築は装飾の代わりに比例と沈黙を使う。毎年五月には十五世紀そのままの宗廟大祭が執り行われる。宮廷楽師が奏で、黒い冠をかぶった舞人が時計のようにゆっくりと動く。","facts":["1995年にユネスコ世界遺産に登録された。","正殿は長さ約101mで、アジア最長の伝統木造建築である。","宗廟祭礼と祭礼楽はユネスコ無形文化遺産。","平日は解説付き見学のみ、土曜日は自由観覧。","かつて昌徳宮と森で繋がっており、現在は歩道橋として復元された。"],"travelTips":["言語別の解説時間を事前に確認しよう。英語回は席が少ない。","ゆっくり見たいなら自由観覧の土曜日に。","昌徳宮と同じ日にまとめよう。歩道橋ひとつで繋がっている。"],"bestTime":"5月（宗廟大祭）と10〜11月","visitDuration":"1〜1.5時間","ticket":"1,000ウォン（19歳未満・65歳以上は無料）","openingHours":"09:00〜18:00（11〜1月は17:30まで、6〜8月は18:30まで）、火曜休み","galleryCaptions":["正殿の長い回廊"]},"zh":{"name":"宗廟","summary":"供奉朝鮮歷代君王神主之處：一座長長的木造殿宇，空得反而莊嚴。","story":"宗廟沒有塑像、沒有繪畫、沒有彩繪貼金，只有正殿——一條長逾百公尺的木造廊廡，十九扇門一律緊閉，每一間安放一位君王與王后的神主。入口的石道分成三路，中央那條略高的是神走的路，活人走兩側。這份空曠是刻意的：儒家建築以比例與沉默取代裝飾。每年五月舉行的宗廟祭禮，仍依十五世紀的儀節進行，宮廷樂師奏樂，戴黑冠的佾舞者動作慢得像鐘擺。","facts":["1995年列入聯合國教科文組織世界遺產。","正殿長約101公尺，是亞洲最長的傳統木造建築。","宗廟祭禮及祭禮樂為聯合國教科文組織非物質文化遺產。","平日僅能參加導覽入場，週六可自由參觀。","昔日與昌德宮之間有林地相連，現已復原為人行橋。"],"travelTips":["先查各語言導覽場次，英語場名額有限。","想慢慢逛正殿庭院，就挑可自由參觀的週六。","和昌德宮排在同一天，兩者只隔一座人行橋。"],"bestTime":"5月（宗廟大祭）與10至11月","visitDuration":"1至1.5小時","ticket":"1,000韓元（未滿19歲與65歲以上免費）","openingHours":"09:00–18:00（11至1月至17:30，6至8月至18:30），週二休館","galleryCaptions":["正殿的長廊"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bukchon-hanok-village', 'bukchon-hanok-village', 'seoul', 'Làng Hanok Bukchon', 'Bukchon Hanok Village', 'village', 126.9849, 37.5826, 'Khu phố nhà gỗ hanok còn người ở thật, nằm nghiêng trên sườn đồi giữa hai cung điện.', 'Bukchon nghĩa là ''làng phía Bắc'' — phía bắc dòng suối Cheonggyecheon, nơi quan lại triều Joseon dựng nhà. Những con dốc hẹp lát đá dẫn lên cao, hai bên là hàng mái ngói đen uốn cong, và khi ngoảnh lại bạn thấy tháp N Seoul nhô lên phía sau các mái nhà. Đây không phải bảo tàng ngoài trời: người dân vẫn sống trong những căn hanok đó, nên các tấm biển nhắc khách nói khẽ. Nhiều căn đã thành xưởng thủ công, quán trà hay nhà khách — cách tốt nhất để hiểu hanok là ngủ lại một đêm trên sàn ondol ấm.', '["Có khoảng 900 căn hanok, phần lớn dựng vào đầu thế kỷ 20.","Nằm gọn giữa hai cung Gyeongbokgung và Changdeokgung.","Giờ tham quan được giới hạn để bảo vệ đời sống cư dân.","Nhiều hanok mở cửa thành xưởng làm nút áo, nhuộm vải, trà đạo."]', '["Tránh đến sau 17h — khu vực hạn chế khách để giữ yên tĩnh cho dân cư.","Ngõ số 8 (Bukchon-ro 11-gil) là góc chụp mái ngói kinh điển.","Kết hợp với phố Samcheong-dong ngay bên cạnh để ăn trưa."]', 'Quanh năm, đẹp nhất vào sáng sớm', '1–2 giờ', '', 'Từ 1/1/2026, khách du lịch chỉ được vào khu Bukchon-ro 11-gil trong khung 10:00–17:00; ra vào ngoài giờ đó bị phạt 100.000 KRW. Đây là quy định bắt buộc, không phải khuyến nghị', '["popular"]', '["hanok","kiến trúc","đi bộ","nhiếp ảnh"]', '[{"seed":"bukchon-hanok-village","caption":"Dốc hanok nhìn ra thành phố","ratio":"16/9"}]', '["gyeongbokgung","changdeokgung"]', 0, 'https://culture.jongno.go.kr/media/ko/conts/111/web.do', '2026-08-04', '{"en":{"name":"Bukchon Hanok Village","summary":"A hillside quarter of wooden hanok houses that people still live in, wedged between two palaces.","story":"Bukchon means ''northern village'' — north of the Cheonggyecheon stream, where Joseon officials built their homes. Narrow stone lanes climb the slope between rows of curved black-tiled roofs, and when you turn around, N Seoul Tower rises behind them. This is not an open-air museum: residents still live in these houses, which is why the signs ask you to keep your voice down. Many hanok have become craft workshops, tea rooms or guesthouses — and the best way to understand a hanok is to sleep one night on its warm ondol floor.","facts":["Around 900 hanok houses, most built in the early 20th century.","Tucked between Gyeongbokgung and Changdeokgung palaces.","Visiting hours are limited to protect residents'' daily life.","Several hanok open as workshops for knot-making, natural dyeing and tea ceremony."],"travelTips":["Avoid arriving after 5pm — access is restricted to keep the quarter quiet.","Alley 8 (Bukchon-ro 11-gil) is the classic rooftop viewpoint.","Combine it with Samcheong-dong next door for lunch."],"bestTime":"Year-round, best in early morning","visitDuration":"1–2 hours","ticket":"","openingHours":"From 1 January 2026 tourists may enter the Bukchon-ro 11-gil zone only between 10:00 and 17:00; being there outside those hours carries a 100,000 KRW fine. This is enforced, not advisory","galleryCaptions":["Hanok lane looking out over the city"]},"ko":{"name":"북촌한옥마을","summary":"두 궁궐 사이 언덕에 자리한, 사람이 실제로 사는 한옥 동네.","story":"북촌은 청계천 북쪽, 조선의 관리들이 집을 짓던 마을이라는 뜻이다. 좁은 돌길이 언덕을 오르고 양옆으로 검은 기와지붕이 이어지는데, 뒤를 돌아보면 지붕 너머로 남산타워가 솟아 있다. 이곳은 야외 박물관이 아니다. 주민들이 실제로 살고 있어 곳곳에 정숙을 부탁하는 안내가 붙어 있다. 여러 한옥이 공방과 찻집, 게스트하우스로 바뀌었고, 한옥을 이해하는 가장 좋은 방법은 따뜻한 온돌 바닥에서 하룻밤 자보는 것이다.","facts":["약 900채의 한옥이 있으며 대부분 20세기 초에 지어졌다.","경복궁과 창덕궁 사이에 자리한다.","주민 생활 보호를 위해 관람 시간이 제한된다.","매듭, 천연염색, 다도 등 공방으로 문을 연 한옥이 많다."],"travelTips":["오후 5시 이후에는 정숙을 위해 통행이 제한되니 그 전에 방문하자.","북촌로 11길(8경)이 지붕 풍경을 담는 대표 지점이다.","바로 옆 삼청동과 묶어 점심까지 해결하기 좋다."],"bestTime":"연중, 이른 아침이 가장 좋다","visitDuration":"1~2시간","ticket":"","openingHours":"2026년 1월 1일부터 북촌로11길 구역은 관광 목적 방문이 10:00~17:00로 제한되며, 시간 외 출입 적발 시 과태료 10만원이 부과된다. 권고가 아니라 강제 규정이다","galleryCaptions":["도심이 내려다보이는 한옥 골목"]},"ja":{"name":"北村韓屋村","summary":"二つの宮殿に挟まれた丘の上、人が今も暮らす韓屋の町。","story":"北村とは清渓川の北、朝鮮の官吏たちが屋敷を構えた村という意味だ。細い石畳の坂の両側に黒瓦の屋根が連なり、振り返ると屋根の向こうにNソウルタワーが立つ。ここは野外博物館ではない。住民が実際に暮らしているため、静かにと促す掲示が至るところにある。多くの韓屋が工房や茶室、ゲストハウスに変わった。韓屋を理解する一番の方法は、温かいオンドルの床で一晩眠ってみることだ。","facts":["約900棟の韓屋があり、大半は20世紀初頭に建てられた。","景福宮と昌徳宮の間に位置する。","住民の生活を守るため見学時間が制限されている。","組紐、草木染め、茶道などの工房として開かれた韓屋も多い。"],"travelTips":["17時以降は静粛のため通行が制限される。その前に訪れよう。","北村路11ギル（八景）が屋根並みを写す定番の場所。","隣の三清洞と合わせて昼食まで楽しめる。"],"bestTime":"通年、早朝が最も良い","visitDuration":"1〜2時間","ticket":"","openingHours":"2026年1月1日から北村路11ギル一帯は観光目的の立ち入りが10:00〜17:00に制限され、時間外は10万ウォンの過料が科される。推奨ではなく強制規定である","galleryCaptions":["街を見下ろす韓屋の路地"]},"zh":{"name":"北村韓屋村","summary":"夾在兩座宮殿之間的山坡聚落，至今仍有人居住的韓屋。","story":"北村意為「北邊的村子」——清溪川以北，朝鮮官員築宅之地。狹窄的石板坡道向上延伸，兩旁是連綿的黑瓦屋頂；回頭一望，屋脊之後便是南山塔。這裡不是露天博物館：居民仍住在這些屋子裡，所以到處掛著請輕聲的告示。許多韓屋改成了工坊、茶館與民宿，而理解韓屋最好的方式，是在溫熱的暖炕上睡上一晚。","facts":["約有900座韓屋，多數建於20世紀初。","位於景福宮與昌德宮之間。","為保障居民生活，參觀時間受到限制。","不少韓屋開放為結繩、草木染與茶道工坊。"],"travelTips":["下午五點後為維持安寧會限制通行，請提早前往。","北村路11街（八景）是拍攝屋頂群的經典位置。","可與隔壁的三清洞一併安排午餐。"],"bestTime":"全年，清晨最佳","visitDuration":"1至2小時","ticket":"","openingHours":"自2026年1月1日起，北村路11街一帶觀光客僅能於10:00至17:00進入，逾時進入將處10萬韓元罰鍰。這是強制規定，不是建議","galleryCaptions":["俯瞰城市的韓屋巷弄"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ikseon-dong', 'ikseon-dong', 'seoul', 'Ngõ hanok Ikseon-dong', 'Ikseon-dong Hanok Alleys', 'village', 126.9905, 37.5741, 'Khu hanok bình dân thập niên 1920, nay là mê cung ngõ hẹp đầy quán cà phê giấu sau cửa gỗ.', 'Nếu Bukchon là hanok của quan lại thì Ikseon-dong là hanok của thường dân: những căn nhỏ, sân vuông bé xíu, dựng hàng loạt vào thập niên 1920 cho người lao động đổ về thành phố. Khu này suýt bị giải toả, rồi được cứu bởi chính điều làm nó khó phá — ngõ quá hẹp cho máy móc. Giờ mỗi cánh cửa gỗ mở ra một quán cà phê, tiệm sách hay quán rượu makgeolli, mái ngói cũ giữ nguyên còn bên trong thì hoàn toàn hiện đại. Ngõ hẹp đến mức hai người phải né nhau, và đúng vì thế mà đi buổi tối, khi đèn giấy sáng lên, cảm giác rất khác Seoul bên ngoài.', '["Khu hanok dựng chủ yếu từ thập niên 1920, dành cho tầng lớp bình dân.","Từng nằm trong diện quy hoạch giải toả, được giữ lại từ giữa thập niên 2010.","Ngõ hẹp nhất chỉ rộng khoảng một mét.","Nằm ngay sau phố Jongno, cách ga Jongno 3-ga vài chục bước."]', '["Quán cà phê nhỏ và hay kín chỗ — đi trước 11h hoặc sau 20h.","Đi buổi tối để thấy đèn hắt qua cửa giấy, đẹp hơn ban ngày nhiều.","Ngõ rất hẹp, tránh mang vali hoặc đi nhóm đông."]', 'Quanh năm; buổi tối đẹp nhất', '1,5–2 giờ', '', 'Ngõ mở cả ngày, không có giờ quy định; quán cà phê và nhà hàng thường 11:00–23:00', '["trending","hidden-gem"]', '["hanok","cà phê","ngõ nhỏ","về đêm"]', '[{"seed":"ikseon-dong","caption":"Ngõ hanok về đêm","ratio":"16/9"}]', '["jongmyo-shrine","gwangjang-market"]', 0, 'https://korean.visitkorea.or.kr/', '2026-08-04', '{"en":{"name":"Ikseon-dong Hanok Alleys","summary":"A working-class hanok quarter from the 1920s, now a maze of narrow lanes with cafés hidden behind wooden doors.","story":"If Bukchon is the hanok of officials, Ikseon-dong is the hanok of ordinary people: small houses with tiny square courtyards, built by the dozen in the 1920s for workers moving into the city. The quarter came close to demolition and was saved by the very thing that made it hard to clear — lanes too narrow for machinery. Now every wooden door opens onto a café, a bookshop or a makgeolli bar, the old tiled roofs untouched and the interiors entirely modern. The alleys are tight enough that two people must turn sideways to pass, which is exactly why it is best at night, when the paper lanterns come on.","facts":["The hanok here were built mostly in the 1920s, for ordinary working families.","The quarter was once slated for redevelopment and was preserved from the mid-2010s.","The narrowest lane is barely a metre wide.","It sits directly behind Jongno, a few dozen steps from Jongno 3-ga station."],"travelTips":["The cafés are small and fill up — go before 11am or after 8pm.","Come in the evening: lamplight through paper doors beats the daytime view.","The lanes are very tight; avoid suitcases and large groups."],"bestTime":"Year-round; best in the evening","visitDuration":"1.5–2 hours","ticket":"","openingHours":"The alleys are open all day with no set hours; cafés and restaurants generally run 11:00–23:00","galleryCaptions":["Hanok alley at night"]},"ko":{"name":"익선동 한옥골목","summary":"1920년대 서민 한옥촌. 지금은 나무문 뒤에 카페가 숨어 있는 좁은 골목의 미로다.","story":"북촌이 사대부의 한옥이라면 익선동은 서민의 한옥이다. 도시로 몰려든 노동자를 위해 1920년대에 작은 집들이 한꺼번에 지어졌고, 마당은 손바닥만 하다. 재개발로 사라질 뻔했지만, 정작 철거를 어렵게 만든 것이 이 동네를 구했다. 골목이 장비가 들어갈 수 없을 만큼 좁았던 것이다. 이제 나무문마다 카페와 책방, 막걸리집이 들어섰다. 기와지붕은 그대로 두고 안쪽만 완전히 현대적이다. 두 사람이 몸을 틀어야 지나가는 골목이라, 종이문으로 등불이 배어 나오는 밤에 가장 좋다.","facts":["1920년대에 서민을 위해 지어진 한옥촌이다.","재개발 대상이었다가 2010년대 중반부터 보존되었다.","가장 좁은 골목은 폭이 1m 남짓이다.","종로 바로 뒤, 종로3가역에서 몇십 걸음이면 닿는다."],"travelTips":["가게가 작아 금방 찬다. 오전 11시 이전이나 저녁 8시 이후가 낫다.","낮보다 밤이 훨씬 좋다. 종이문에 등불이 비친다.","골목이 매우 좁으니 캐리어나 큰 일행은 피하자."],"bestTime":"연중, 저녁이 가장 좋다","visitDuration":"1.5~2시간","ticket":"","openingHours":"골목은 상시 개방되어 정해진 시간이 없다. 카페와 식당은 대체로 11:00~23:00","galleryCaptions":["밤의 한옥 골목"]},"ja":{"name":"益善洞の韓屋路地","summary":"1920年代の庶民の韓屋街。今は木の扉の奥にカフェが隠れる、細い路地の迷宮だ。","story":"北村が両班の韓屋なら、益善洞は庶民の韓屋だ。都市に流れ込んだ労働者のために1920年代へ一気に建てられた小さな家々で、中庭は手のひらほどしかない。再開発で消えかけたが、皮肉にも取り壊しを難しくしたものがこの街を救った。重機が入れないほど路地が狭かったのだ。今は木の扉ごとにカフェや書店、マッコリ屋が入る。瓦屋根はそのまま、内側だけが完全に現代的だ。二人がすれ違うのに体を横にする路地だから、紙障子から灯りがにじむ夜が一番いい。","facts":["1920年代に庶民向けとして建てられた韓屋街。","再開発対象だったが、2010年代半ばから保存された。","最も狭い路地は幅1mほどしかない。","鍾路のすぐ裏、鍾路3街駅から数十歩の距離。"],"travelTips":["店が小さくすぐ埋まる。午前11時前か夜8時以降がよい。","昼より夜。紙障子に灯りが映る。","路地が非常に狭い。スーツケースや大人数は避けよう。"],"bestTime":"通年、夜が最良","visitDuration":"1.5〜2時間","ticket":"","openingHours":"路地は終日開放で決まった時間はない。カフェや飲食店はおおむね11:00〜23:00","galleryCaptions":["夜の韓屋路地"]},"zh":{"name":"益善洞韓屋巷弄","summary":"1920年代的平民韓屋區，如今成了木門後藏著咖啡館的窄巷迷宮。","story":"若說北村是士大夫的韓屋，益善洞就是平民的韓屋：房子小，天井只有巴掌大，1920年代為湧入城市的工人成批興建。這一帶差點被拆除，救了它的偏偏是讓拆除變得困難的那件事——巷子窄到機具開不進來。如今每一道木門後面都是咖啡館、書店或馬格利酒館，瓦頂原封不動，裡頭卻完全現代。巷子窄到兩人得側身而過，也正因如此，夜裡紙門透出燈光時最好看。","facts":["韓屋多建於1920年代，供一般勞動家庭居住。","曾被列入重劃拆除範圍，自2010年代中期起獲得保存。","最窄的巷子寬度僅約一公尺。","就在鍾路後方，距鍾路三街站數十步。"],"travelTips":["店面小、容易客滿，建議上午11點前或晚上8點後。","夜裡比白天好看得多，燈光會透過紙門。","巷弄極窄，避免帶行李箱或大團體同行。"],"bestTime":"全年，夜晚最佳","visitDuration":"1.5至2小時","ticket":"","openingHours":"巷弄全日開放，沒有固定時間；咖啡館與餐廳大致11:00–23:00","galleryCaptions":["夜裡的韓屋巷弄"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('insadong', 'insadong', 'seoul', 'Phố Insa-dong', 'Insa-dong', 'city', 126.985, 37.5735, 'Con phố của giấy hanji, bút lông và trà — nơi duy nhất ở Seoul mà cả biển hiệu Starbucks cũng viết bằng chữ Hàn.', 'Insa-dong là phố đồ cổ và thủ công của Seoul từ thời Joseon, khi quan lại sa sút mang đồ trong nhà ra bán. Trục phố chính dài chừng bảy trăm mét, hai bên là tiệm giấy hanji, xưởng gốm, hiệu bút lông và quán trà truyền thống nằm sâu trong sân. Quy định của quận buộc mọi biển hiệu phải viết bằng hangul — kể cả các chuỗi nước ngoài — nên cả con phố có một nhịp thị giác riêng. Ssamziegil, toà nhà xoáy trôn ốc đi lên bằng đường dốc thay vì cầu thang, là nơi tập trung các xưởng thủ công nhỏ. Cuối tuần phố cấm xe và trở thành sân khấu ngoài trời.', '["Là khu buôn bán đồ cổ và thư pháp lâu đời nhất Seoul.","Quận Jongno quy định biển hiệu trên phố phải viết bằng hangul.","Toà Ssamziegil đi lên theo đường dốc xoắn ốc, không có cầu thang chính.","Cuối tuần trục phố chính cấm xe cơ giới."]', '["Vào các ngõ nhánh — quán trà và xưởng gốm hay nhất đều nằm khuất bên trong.","Thử trà ngũ vị omija hoặc trà táo tàu ở quán trà truyền thống.","Đi cuối tuần nếu bạn thích không khí hội hè; ngày thường thì dễ thở hơn."]', 'Quanh năm', '2 giờ', '', 'Phố mở cả ngày; cửa hàng thường 10:00–21:00. Cuối tuần con phố chính cấm xe, chỉ dành cho người đi bộ', '["popular"]', '["thủ công","trà","đồ cổ","mua sắm"]', '[{"seed":"insadong","caption":"Phố Insa-dong cuối tuần","ratio":"16/9"}]', '["jongmyo-shrine","bukchon-hanok-village"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=111926', '2026-08-04', '{"en":{"name":"Insa-dong","summary":"The street of hanji paper, ink brushes and tea — the one place in Seoul where even the Starbucks sign is written in Korean.","story":"Insa-dong has been Seoul''s antiques and craft street since Joseon times, when impoverished officials brought the contents of their houses out to sell. The main run is about seven hundred metres, lined with hanji paper shops, potteries, brush makers and traditional tea houses set back in courtyards. District rules require every sign on the street to be written in hangul — foreign chains included — which gives the whole stretch its own visual rhythm. Ssamziegil, a building you climb by a spiral ramp rather than stairs, gathers the small craft studios. At weekends the main street closes to traffic and turns into an open-air stage.","facts":["Seoul''s oldest antiques and calligraphy quarter.","Jongno district requires shop signs on the street to be written in hangul.","The Ssamziegil building is climbed by a spiral ramp, with no main staircase.","The main street is closed to vehicles at weekends."],"travelTips":["Turn into the side lanes — the best tea houses and potteries are tucked out of sight.","Try omija five-flavour tea or jujube tea at a traditional tea house.","Weekends are festive; weekdays are easier going."],"bestTime":"Year-round","visitDuration":"2 hours","ticket":"","openingHours":"The street is always open; shops generally run 10:00–21:00. At weekends the main street is closed to cars and becomes pedestrian-only","galleryCaptions":["Insa-dong street at the weekend"]},"ko":{"name":"인사동","summary":"한지와 붓, 전통차의 거리. 스타벅스 간판마저 한글로 쓰인 서울의 유일한 곳이다.","story":"인사동은 조선 말 몰락한 양반들이 집안 물건을 내다 팔면서 생긴 골동품과 공예의 거리다. 본거리는 700m쯤 되고, 한지 가게와 도자기 공방, 붓집, 마당 안쪽에 자리한 전통찻집이 늘어서 있다. 종로구 규정에 따라 이 거리의 간판은 외국 브랜드까지 모두 한글로 써야 해서, 거리 전체에 고유한 시각적 리듬이 있다. 계단 대신 나선형 경사로로 올라가는 쌈지길에는 작은 공예 공방이 모여 있다. 주말에는 차량이 통제되어 거리 자체가 야외 무대가 된다.","facts":["서울에서 가장 오래된 골동품·서예 거리다.","종로구 규정으로 거리 간판은 한글로 표기해야 한다.","쌈지길은 계단 없이 나선형 경사로로 오르는 건물이다.","주말에는 본거리 차량 통행이 통제된다."],"travelTips":["골목 안쪽으로 들어가자. 좋은 찻집과 공방은 안에 숨어 있다.","전통찻집에서 오미자차나 대추차를 마셔 보자.","북적이는 분위기를 원하면 주말, 여유를 원하면 평일이다."],"bestTime":"연중","visitDuration":"2시간","ticket":"","openingHours":"거리는 상시 개방, 상점은 대체로 10:00~21:00. 주말에는 큰길이 차 없는 거리로 운영된다","galleryCaptions":["주말의 인사동 거리"]},"ja":{"name":"仁寺洞","summary":"韓紙と筆、伝統茶の街。スターバックスの看板までハングルで書かれるソウル唯一の場所。","story":"仁寺洞は朝鮮末期、没落した両班が家財を売りに出したことから生まれた骨董と工芸の街だ。本通りは700mほどで、韓紙店、陶磁工房、筆屋、中庭の奥に構えた伝統茶屋が並ぶ。鍾路区の規定によりこの通りの看板は外国ブランドも含めすべてハングル表記でなければならず、街全体に独特の視覚的リズムがある。階段ではなく螺旋のスロープで上がるサムジキルには小さな工芸工房が集まる。週末は車両通行止めになり、通りそのものが野外の舞台になる。","facts":["ソウルで最も古い骨董・書芸の街。","鍾路区の規定で通りの看板はハングル表記とされている。","サムジキルは階段のない螺旋スロープで上がる建物。","週末は本通りが車両通行止めになる。"],"travelTips":["脇の路地に入ろう。よい茶屋と工房は奥に隠れている。","伝統茶屋でオミジャ茶やナツメ茶を試そう。","賑わいを求めるなら週末、落ち着きたいなら平日。"],"bestTime":"通年","visitDuration":"2時間","ticket":"","openingHours":"通りは常時開放、店はおおむね10:00〜21:00。週末は目抜き通りが歩行者天国になる","galleryCaptions":["週末の仁寺洞通り"]},"zh":{"name":"仁寺洞","summary":"韓紙、毛筆與傳統茶的街道——首爾唯一連星巴克招牌都寫韓文的地方。","story":"仁寺洞自朝鮮末年起就是古董與工藝之街，起因是家道中落的兩班把家中物件拿出來變賣。主街約七百公尺，兩側是韓紙店、陶藝工坊、筆莊，以及深藏在庭院裡的傳統茶館。鍾路區規定街上招牌一律以韓文書寫，連外國連鎖也不例外，整條街因此有了自己的視覺節奏。以螺旋坡道而非樓梯往上走的「Ssamziegil」，聚集了許多小型工藝工坊。週末主街封閉車輛，整條路變成露天舞台。","facts":["首爾歷史最悠久的古董與書藝街區。","鍾路區規定街上招牌須以韓文書寫。","Ssamziegil以螺旋坡道上行，沒有主樓梯。","週末主街禁止車輛通行。"],"travelTips":["拐進側巷——最好的茶館與工坊都藏在裡頭。","在傳統茶館試試五味子茶或紅棗茶。","喜歡熱鬧就週末，想從容些就平日。"],"bestTime":"全年","visitDuration":"2小時","ticket":"","openingHours":"街道全日開放，店家大致10:00–21:00；週末主街禁行車輛，改為行人徒步區","galleryCaptions":["週末的仁寺洞街道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangjang-market', 'gwangjang-market', 'seoul', 'Chợ Gwangjang', 'Gwangjang Market', 'market', 126.9997, 37.5701, 'Khu chợ có mái che hơn trăm tuổi, nơi bánh đậu xanh bindaetteok được chiên ngay trước mặt bạn trên chảo mỡ nóng.', 'Gwangjang mở cửa năm 1905, là chợ thường trực đầu tiên của Hàn Quốc, và phần ngon nhất của nó là dãy hàng ăn giữa lòng chợ. Bạn ngồi trên ghế nhựa sát vai người lạ, trước mặt là bà chủ xay đậu xanh bằng cối đá rồi múc lên chảo — bindaetteok ra lò giòn rụm, ăn kèm hành ngâm. Bên cạnh là mayak gimbap, những cuộn cơm bé bằng ngón tay chấm mù tạt, và cá đuối lên men nồng đến chảy nước mắt. Tầng trên bán vải và hanbok cũ, gần như không có khách du lịch. Chợ vừa là điểm ăn uống vừa là một lát cắt Seoul chưa kịp chỉnh trang.', '["Mở cửa năm 1905, là chợ thường trực đầu tiên của Hàn Quốc.","Nổi tiếng nhất với bindaetteok, mayak gimbap và cá đuối lên men.","Tầng hai là khu vải vóc và hanbok cũ, hoạt động chủ yếu cho dân địa phương.","Chợ nằm ngay bờ suối Cheonggyecheon, đi bộ được từ ga Jongno 5-ga."]', '["Đi trước 11h30 hoặc sau 14h để khỏi phải đứng chờ ghế.","Mang tiền mặt — nhiều quầy vẫn không nhận thẻ.","Nhiều quầy tính thêm phí chỗ ngồi; hỏi giá trước khi gọi thêm rượu."]', 'Quanh năm', '1,5 giờ', '', 'Ngõ hàng ăn 09:00–23:00, mở cả tuần quanh năm; các sạp vải và hàng thường 09:00–18:00, nghỉ Chủ nhật', '["popular","verified"]', '["chợ","ẩm thực đường phố","bindaetteok"]', '[{"seed":"gwangjang-market","caption":"Hàng bindaetteok giữa chợ","ratio":"16/9"}]', '["cheonggyecheon","ikseon-dong"]', 1, 'https://access.visitkorea.or.kr/ms/detail.do?cotId=132e94c0-0008-4147-89eb-3ffb1590713d', '2026-08-04', '{"en":{"name":"Gwangjang Market","summary":"A covered market over a century old, where mung bean pancakes are fried on a hot griddle right in front of you.","story":"Gwangjang opened in 1905 as Korea''s first permanent market, and its best part is the row of food stalls down the middle. You sit on a plastic stool shoulder to shoulder with strangers while the woman in front of you grinds mung beans in a stone mill and ladles the batter onto the griddle — bindaetteok comes off crisp, eaten with pickled onion. Beside it are mayak gimbap, finger-sized rice rolls dipped in mustard, and fermented skate pungent enough to make your eyes water. The floor above sells fabric and second-hand hanbok and sees almost no tourists. The market is both a place to eat and a slice of Seoul that was never tidied up.","facts":["Opened in 1905 as Korea''s first permanent market.","Best known for bindaetteok, mayak gimbap and fermented skate.","The second floor is a fabric and used-hanbok market, mostly for locals.","It sits on the Cheonggyecheon stream, walkable from Jongno 5-ga station."],"travelTips":["Go before 11:30 or after 2pm to avoid queuing for a seat.","Bring cash — many stalls still don''t take cards.","Some stalls add a seating charge; ask prices before ordering more drinks."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"","openingHours":"The food alley runs 09:00–23:00 every day of the year; the fabric and general stalls run 09:00–18:00 and close on Sundays","galleryCaptions":["The bindaetteok stalls"]},"ko":{"name":"광장시장","summary":"백 년이 넘은 지붕 있는 시장. 눈앞의 무쇠판에서 빈대떡이 바로 부쳐진다.","story":"광장시장은 1905년에 문을 연 한국 최초의 상설시장이고, 그 백미는 시장 한가운데의 먹거리 골목이다. 낯선 사람과 어깨를 붙이고 플라스틱 의자에 앉으면, 앞에서 아주머니가 맷돌로 녹두를 갈아 판에 붓는다. 바삭하게 부쳐진 빈대떡을 절인 양파와 함께 먹는다. 옆에는 손가락만 한 마약김밥이 겨자장을 기다리고, 눈물이 날 만큼 삭힌 홍어도 있다. 이층은 원단과 구제 한복을 파는 곳으로 관광객이 거의 없다. 시장은 먹는 곳이면서, 정비되지 않은 서울의 한 단면이기도 하다.","facts":["1905년 개장한 한국 최초의 상설시장이다.","빈대떡, 마약김밥, 삭힌 홍어로 가장 유명하다.","2층은 원단과 구제 한복 시장으로 주로 현지인이 찾는다.","청계천 바로 옆, 종로5가역에서 걸어갈 수 있다."],"travelTips":["자리를 기다리지 않으려면 11시 30분 전이나 오후 2시 이후에 가자.","카드를 받지 않는 가게가 아직 많으니 현금을 챙기자.","자릿세를 받는 곳도 있다. 술을 더 시키기 전에 가격을 물어보자."],"bestTime":"연중","visitDuration":"1.5시간","ticket":"","openingHours":"먹자골목은 09:00~23:00 연중무휴, 포목·일반 점포는 09:00~18:00이며 일요일 휴무","galleryCaptions":["시장 한가운데 빈대떡 가게"]},"ja":{"name":"広蔵市場","summary":"百年を超える屋根つき市場。目の前の鉄板で緑豆チヂミがその場で焼かれる。","story":"広蔵市場は1905年に開いた韓国初の常設市場で、その白眉は市場中央の食べ物横丁だ。見知らぬ人と肩を並べてプラスチックの椅子に座ると、目の前でおばさんが石臼で緑豆を挽き、鉄板に流す。かりっと焼けたピンデトクを漬け玉ねぎと一緒に食べる。隣には指ほどの大きさのマヤクキンパがからしを待ち、涙が出るほど発酵させたホンオもある。二階は生地と古着の韓服を売る階で、観光客はほとんどいない。市場は食べる場所であり、整えられなかったソウルの断面でもある。","facts":["1905年開場、韓国初の常設市場。","ピンデトク、マヤクキンパ、発酵エイで最も知られる。","2階は生地と中古韓服の市場で、主に地元客が訪れる。","清渓川のすぐ脇、鍾路5街駅から歩ける。"],"travelTips":["席待ちを避けるなら11時30分前か午後2時以降に。","カード不可の店がまだ多い。現金を用意しよう。","席料を取る店もある。追加の酒を頼む前に値段を聞こう。"],"bestTime":"通年","visitDuration":"1.5時間","ticket":"","openingHours":"食べ物横丁は09:00〜23:00で年中無休、布地・一般の店舗は09:00〜18:00で日曜休み","galleryCaptions":["市場中央のピンデトク屋"]},"zh":{"name":"廣藏市場","summary":"百年以上的有頂市場，綠豆煎餅就在你面前的熱鐵板上現煎。","story":"廣藏市場1905年開市，是韓國第一座常設市場，而它最精采的部分是市場正中央那排小吃攤。你和陌生人肩並肩坐在塑膠椅上，面前的大嬸用石磨磨綠豆、再舀上鐵板——綠豆煎餅起鍋時酥脆，配醃洋蔥吃。旁邊是手指大小、蘸芥末醬的「麻藥飯捲」，還有嗆到讓人流眼淚的發酵魟魚。二樓賣布料與二手韓服，幾乎沒有觀光客。這裡既是吃飯的地方，也是首爾一塊從未被整理過的切面。","facts":["1905年開市，是韓國第一座常設市場。","最著名的是綠豆煎餅、麻藥飯捲與發酵魟魚。","二樓是布料與二手韓服市場，主要服務在地人。","緊鄰清溪川，可從鍾路五街站步行前往。"],"travelTips":["想避免排隊等位，請在11:30前或下午2點後前往。","帶現金——不少攤位仍不收卡。","有些攤位另收座位費，加點酒水前先問價。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"","openingHours":"美食街09:00–23:00全年無休；布料與一般店鋪09:00–18:00，週日休息","galleryCaptions":["市場中央的綠豆煎餅攤"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheonggyecheon', 'cheonggyecheon', 'seoul', 'Suối Cheonggyecheon', 'Cheonggyecheon Stream', 'park', 126.9784, 37.5696, 'Dòng suối từng bị bê tông hoá thành đường trên cao, nay chảy trở lại thấp hơn mặt phố sáu mét.', 'Suốt nửa cuối thế kỷ 20, Cheonggyecheon nằm dưới một tuyến đường trên cao — biểu tượng của Seoul công nghiệp hoá vội vã. Năm 2003 thành phố làm điều ít ai dám: phá bỏ tuyến đường ấy và khơi lại dòng suối. Kết quả là một hành lang dài gần sáu cây số chạy xuyên trung tâm, thấp hơn mặt phố mấy mét nên tiếng xe cộ gần như biến mất khi bạn bước xuống. Có đá kê để nhảy sang bờ bên kia, có thác nhân tạo ở đầu nguồn, và mùa đông cả dòng suối được trang trí đèn lồng cho lễ hội. Người Seoul đi bộ ở đây vào giờ nghỉ trưa như một cách thoát khỏi thành phố mà không cần rời khỏi nó.', '["Dự án khơi lại suối hoàn thành năm 2005, sau khi phá bỏ tuyến đường trên cao.","Dòng suối dài khoảng 11 km, đoạn đi bộ trung tâm gần 6 km.","Nhiệt độ khu vực quanh suối giảm vài độ so với phố phía trên vào mùa hè.","Lễ hội đèn lồng Seoul được tổ chức dọc suối vào mùa đông."]', '["Xuống suối ở quảng trường Cheonggye rồi đi bộ xuôi về phía chợ Gwangjang.","Buổi tối đèn dưới nước bật lên, mát và ít người hơn ban ngày.","Sau mưa lớn lối đi ven suối có thể bị đóng — kiểm tra biển báo."]', 'Tháng 5–6, tháng 9–10 và mùa lễ hội đèn lồng', '1 giờ', '', 'Cả ngày', '["popular"]', '["đi bộ","cải tạo đô thị","về đêm"]', '[{"seed":"cheonggyecheon","caption":"Lối đi ven suối giữa trung tâm","ratio":"16/9"}]', '["gwangjang-market","myeongdong"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Cheonggyecheon Stream","summary":"A stream once buried under an elevated motorway, now running again six metres below street level.","story":"For the second half of the 20th century Cheonggyecheon lay under an elevated motorway — the emblem of a city industrialising in a hurry. In 2003 Seoul did something few cities dare: it tore the motorway down and brought the stream back. The result is a corridor almost six kilometres long through the centre, sunk several metres below the road, so the traffic noise all but vanishes as you step down. There are stepping stones to cross, an artificial waterfall at the head, and in winter the whole channel is strung with lanterns for the festival. Seoulites walk here on their lunch break as a way of leaving the city without leaving it.","facts":["The restoration was completed in 2005 after the elevated motorway was demolished.","The stream runs about 11km; the central walkable stretch is close to 6km.","Summer temperatures along the channel run several degrees below the street above.","The Seoul Lantern Festival is held along the stream in winter."],"travelTips":["Drop down at Cheonggye Plaza and walk downstream towards Gwangjang Market.","In the evening the underwater lighting comes on and it is cooler and quieter.","The path can close after heavy rain — watch for the warning boards."],"bestTime":"May–June, September–October and the lantern festival","visitDuration":"1 hour","ticket":"","openingHours":"Open all day","galleryCaptions":["The streamside path through the centre"]},"ko":{"name":"청계천","summary":"고가도로 아래 묻혔던 하천. 지금은 도로면보다 6m 아래에서 다시 흐른다.","story":"20세기 후반 내내 청계천은 고가도로 밑에 있었다. 서둘러 산업화한 도시의 상징이었다. 2003년 서울은 흔치 않은 결정을 내린다. 그 고가도로를 걷어내고 물길을 되살린 것이다. 그 결과 도심을 가로지르는 6km 가까운 산책로가 생겼다. 도로면보다 몇 미터 낮아서 계단을 내려서는 순간 차 소리가 거의 사라진다. 건너뛰는 징검다리가 있고, 상류에는 인공 폭포가 있으며, 겨울이면 물길 전체에 등불이 걸린다. 서울 사람들은 점심시간에 여기를 걷는다. 도시를 떠나지 않고 도시를 벗어나는 방법이다.","facts":["고가도로 철거 후 2005년 복원이 완료되었다.","하천 길이는 약 11km, 도심 산책 구간은 6km에 가깝다.","여름철 하천 주변 기온은 위쪽 도로보다 몇 도 낮다.","겨울에는 물길을 따라 서울빛초롱축제가 열린다."],"travelTips":["청계광장에서 내려가 광장시장 쪽으로 물길을 따라 걷자.","저녁에는 수중 조명이 켜지고 낮보다 시원하고 한산하다.","폭우 뒤에는 산책로가 통제될 수 있으니 안내판을 확인하자."],"bestTime":"5~6월, 9~10월, 그리고 빛초롱축제 기간","visitDuration":"1시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["도심을 지나는 물길 산책로"]},"ja":{"name":"清渓川","summary":"高架道路の下に埋もれていた川。今は路面より6m低いところを再び流れる。","story":"二十世紀後半を通じて清渓川は高架道路の下にあった。急いで工業化した都市の象徴だった。2003年、ソウルは滅多にない決断をする。その高架を撤去し、水路を蘇らせたのだ。結果として都心を貫く6km近い散策路が生まれた。路面より数メートル低いので、階段を下りた瞬間に車の音がほとんど消える。飛び石があり、上流には人工の滝があり、冬には水路全体に灯籠が並ぶ。ソウルの人々は昼休みにここを歩く。都市を出ずに都市を抜け出す方法だ。","facts":["高架道路の撤去を経て2005年に復元が完了した。","川の長さは約11km、都心の散策区間は6km近い。","夏場の川沿いの気温は上の道路より数度低い。","冬には川沿いでソウル・ランタンフェスティバルが開かれる。"],"travelTips":["清渓広場から下りて広蔵市場の方へ下流に歩こう。","夜は水中照明が入り、昼より涼しく空いている。","大雨のあとは通行止めになることがある。案内板を確認しよう。"],"bestTime":"5〜6月、9〜10月、ランタン祭りの時期","visitDuration":"1時間","ticket":"","openingHours":"終日開放","galleryCaptions":["都心を抜ける川沿いの道"]},"zh":{"name":"清溪川","summary":"曾被高架道路埋住的溪流，如今在低於路面六公尺處重新流動。","story":"整個二十世紀後半，清溪川都壓在一條高架道路底下，那是一座匆忙工業化的城市的象徵。2003年首爾做了少有城市敢做的事：拆掉高架，把溪流放回來。結果是一條穿越市中心、將近六公里的廊道，比路面低了好幾公尺，走下階梯的瞬間車聲幾乎消失。水上有踏石可以跨到對岸，上游有人工瀑布，冬天整條水道掛滿燈籠辦燈節。首爾人午休時來這裡散步——一種不必離開城市就能離開城市的方法。","facts":["拆除高架後，復原工程於2005年完成。","溪流全長約11公里，市中心可步行段接近6公里。","夏季溪畔氣溫比上方街道低上幾度。","冬季沿溪舉辦首爾燈節。"],"travelTips":["從清溪廣場下到水邊，順流走向廣藏市場。","傍晚水中照明亮起，比白天涼快也安靜。","大雨後步道可能封閉，請留意告示牌。"],"bestTime":"5至6月、9至10月與燈節期間","visitDuration":"1小時","ticket":"","openingHours":"全日開放","galleryCaptions":["穿過市中心的溪畔步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bongeunsa', 'bongeunsa', 'seoul', 'Chùa Bongeunsa', 'Bongeunsa Temple', 'temple', 127.0575, 37.515, 'Ngôi chùa nghìn năm nằm đối diện trung tâm hội nghị Gangnam, tượng Phật đá cao 23 mét đứng giữa rừng kính.', 'Không có nơi nào ở Seoul cho thấy hai thời đại chồng lên nhau rõ như Bongeunsa. Chùa dựng năm 794, còn ngay bên kia đường là COEX và những toà tháp Gangnam sáng đèn suốt đêm. Bước qua cổng Iljumun, tiếng phố tắt dần; sân chùa xếp đầy đèn lồng giấy vào mùa Phật đản, và tượng Di Lặc bằng đá cao hai mươi ba mét nhìn thẳng ra khu tài chính. Chùa có chương trình templestay cho khách nước ngoài: dậy lúc bốn giờ sáng, gõ mõ, ăn cơm chay trong im lặng tuyệt đối. Buổi tối thứ Năm hằng tuần có buổi thiền và trà bằng tiếng Anh.', '["Được dựng năm 794, thời Silla, dưới tên Gyeonseongsa.","Tượng Phật Di Lặc bằng đá cao khoảng 23m, hoàn thành năm 1996.","Chùa giữ bộ mộc bản kinh Phật hơn 3.400 tấm.","Có chương trình templestay và buổi thiền tiếng Anh cho khách nước ngoài."]', '["Đăng ký templestay trước ít nhất vài tuần, suất tiếng Anh rất nhanh hết.","Đi vào dịp Phật đản (tháng 4–5 âm lịch) để thấy sân chùa phủ kín đèn lồng.","Ga Bongeunsa (tuyến 9) ra là tới cổng, khỏi cần đi bộ xa."]', 'Tháng 4–5 (mùa đèn lồng) và tháng 10–11', '1,5 giờ', 'Miễn phí (chương trình Templelife 30.000 KRW)', '03:00–22:00, mở cửa quanh năm', '["hidden-gem"]', '["chùa","templestay","Gangnam","thiền"]', '[{"seed":"bongeunsa","caption":"Tượng Di Lặc trước nền cao ốc Gangnam","ratio":"16/9"}]', '["lotte-world-tower","seoul-forest"]', 0, 'https://english.visitseoul.net/gangnamarea/Bongeunsa/ENP000411', '2026-08-04', '{"en":{"name":"Bongeunsa Temple","summary":"A thousand-year-old temple facing the Gangnam convention centre, its 23-metre stone Buddha standing in a forest of glass.","story":"Nowhere in Seoul stacks two eras so plainly as Bongeunsa. The temple was founded in 794; directly across the road are COEX and the Gangnam towers, lit all night. Step through the Iljumun gate and the street noise fades; the courtyard fills with paper lanterns at Buddha''s Birthday, and a twenty-three-metre stone Maitreya looks straight out over the financial district. The temple runs a templestay for foreign visitors: up at four in the morning, wooden gong, vegetarian meals eaten in complete silence. On Thursday evenings there is a meditation and tea session in English.","facts":["Founded in 794 during Silla, originally as Gyeonseongsa.","The stone Maitreya Buddha stands about 23m tall, completed in 1996.","The temple holds more than 3,400 Buddhist woodblock scriptures.","It offers a templestay and English-language meditation sessions."],"travelTips":["Book the templestay weeks ahead; English slots go quickly.","Visit around Buddha''s Birthday to see the courtyard under a roof of lanterns.","Bongeunsa station (line 9) exits at the gate — no walk required."],"bestTime":"April–May (lantern season) and October–November","visitDuration":"1.5 hours","ticket":"Free (Templelife programme 30,000 KRW)","openingHours":"03:00–22:00, open every day of the year","galleryCaptions":["The Maitreya against the Gangnam towers"]},"ko":{"name":"봉은사","summary":"강남 컨벤션센터 맞은편의 천년 고찰. 23m 석조 미륵이 유리 숲 한가운데 서 있다.","story":"서울에서 두 시대가 이렇게 뚜렷하게 겹치는 곳은 봉은사뿐이다. 절은 794년에 창건되었고, 길 건너에는 코엑스와 밤새 불이 꺼지지 않는 강남 빌딩들이 서 있다. 일주문을 지나면 도심의 소리가 잦아든다. 부처님오신날이면 마당이 연등으로 덮이고, 23m 높이의 석조 미륵대불이 금융가를 정면으로 바라본다. 외국인을 위한 템플스테이도 운영한다. 새벽 네 시에 일어나 목탁 소리를 듣고, 완전한 침묵 속에서 발우공양을 한다. 매주 목요일 저녁에는 영어 명상과 차담 시간이 있다.","facts":["794년 신라 때 견성사라는 이름으로 창건되었다.","석조 미륵대불은 높이 약 23m로 1996년에 완성되었다.","3,400여 점의 불교 목판을 소장하고 있다.","외국인을 위한 템플스테이와 영어 명상 프로그램을 운영한다."],"travelTips":["템플스테이는 몇 주 전에 예약하자. 영어 회차는 금방 마감된다.","부처님오신날 즈음에 가면 마당 가득한 연등을 볼 수 있다.","9호선 봉은사역에서 나오면 바로 일주문이다."],"bestTime":"4~5월(연등철)과 10~11월","visitDuration":"1.5시간","ticket":"무료(템플라이프 프로그램 30,000원)","openingHours":"03:00~22:00, 연중무휴","galleryCaptions":["강남 빌딩을 등진 미륵대불"]},"ja":{"name":"奉恩寺","summary":"江南のコンベンションセンター向かいに立つ千年の古刹。23mの石造弥勒がガラスの森に立つ。","story":"ソウルでこれほど二つの時代がはっきり重なる場所はない。寺は794年の創建で、道路の向こうにはCOEXと夜通し灯る江南の高層ビルがある。一柱門をくぐると街の音が遠のく。灌仏会の頃には境内が提灯で埋まり、高さ二十三メートルの石造弥勒大仏が金融街を正面から見つめる。外国人向けのテンプルステイもある。朝四時に起き、木魚の音を聞き、完全な沈黙のなかで精進料理をいただく。毎週木曜の夜には英語での瞑想と茶の時間がある。","facts":["794年、新羅時代に見性寺として創建された。","石造弥勒大仏は高さ約23m、1996年に完成した。","3,400点を超える仏教木版を所蔵する。","外国人向けテンプルステイと英語の瞑想プログラムがある。"],"travelTips":["テンプルステイは数週間前に予約を。英語回はすぐ埋まる。","灌仏会の頃に行けば提灯に覆われた境内が見られる。","9号線・奉恩寺駅を出るとすぐ門である。"],"bestTime":"4〜5月（提灯の季節）と10〜11月","visitDuration":"1.5時間","ticket":"無料（テンプルライフ体験は30,000ウォン）","openingHours":"03:00〜22:00、年中無休","galleryCaptions":["江南の高層ビルを背にした弥勒大仏"]},"zh":{"name":"奉恩寺","summary":"面對江南會展中心的千年古剎，23公尺高的石造彌勒立在玻璃叢林之中。","story":"首爾沒有別的地方能把兩個時代疊得這麼分明。寺建於794年，馬路對面就是COEX與徹夜通明的江南高樓。穿過一柱門，街聲便退去；佛誕時庭院鋪滿紙燈籠，二十三公尺高的石造彌勒佛正對著金融區。寺方為外國訪客開設寺廟寄宿：清晨四點起身、敲木魚、在完全的沉默中用素齋。每週四晚上還有英語的禪修與茶敘。","facts":["794年新羅時期創建，原名見性寺。","石造彌勒佛高約23公尺，1996年落成。","寺內收藏三千四百餘片佛經木刻板。","設有寺廟寄宿與英語禪修課程。"],"travelTips":["寺廟寄宿請提前數週預約，英語場次很快額滿。","佛誕前後前往，可看到整個庭院被燈籠覆蓋。","地鐵9號線奉恩寺站出站即是山門。"],"bestTime":"4至5月（燈籠季）與10至11月","visitDuration":"1.5小時","ticket":"免費（寺廟體驗課程30,000韓元）","openingHours":"03:00–22:00，全年無休","galleryCaptions":["以江南高樓為背景的彌勒佛"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('n-seoul-tower', 'n-seoul-tower', 'seoul', 'Tháp N Seoul (Namsan)', 'N Seoul Tower', 'city', 126.9882, 37.5512, 'Đỉnh Namsan giữa lòng thành phố, nơi Seoul trải ra thành một biển đèn không có điểm kết.', 'Namsan là ngọn núi nằm ngay giữa Seoul, và cáp treo từ Myeongdong đưa bạn lên đó trong vài phút. Tháp phát sóng dựng năm 1971 nay thành đài quan sát: từ trên cao, dòng sông Hàn cắt ngang thành phố, những khối cao ốc Gangnam mọc ở bờ nam, còn phía bắc là các mái cung điện lọt thỏm giữa nhà cửa. Hoàng hôn là thời khắc đáng đợi nhất — đèn thành phố bật lên từng mảng. Dọc hàng rào quanh chân tháp treo kín những ổ khoá tình yêu đã han gỉ theo mưa gió.', '["Tháp cao 236m, đứng trên đỉnh Namsan cao 243m so với mực nước biển.","Khánh thành năm 1971, ban đầu là tháp phát sóng truyền hình.","Đèn tháp đổi màu theo chỉ số chất lượng không khí của thành phố.","Có thể lên bằng cáp treo, xe buýt Namsan hoặc đi bộ đường mòn khoảng 40 phút."]', '["Lên trước hoàng hôn khoảng một tiếng để xem cả cảnh ngày lẫn đêm.","Cáp treo đông nhất cuối tuần — đi bộ đường mòn lại rất dễ chịu.","Trời quang sau mưa cho tầm nhìn xa nhất."]', 'Tháng 9–11, trời trong', '2 giờ', 'Đài quan sát 21.000 KRW (cáp treo tính riêng)', '10:30–22:30 ngày thường, 10:00–23:00 cuối tuần; vào cửa cuối trước 30 phút', '["popular"]', '["toàn cảnh","hoàng hôn","cáp treo"]', '[{"seed":"n-seoul-tower","caption":"Seoul nhìn từ đài quan sát","ratio":"16/9"}]', '["myeongdong","gyeongbokgung"]', 0, 'https://www.seoultower.co.kr/eng/', '2026-08-04', '{"en":{"name":"N Seoul Tower (Namsan)","summary":"The peak in the middle of the city, where Seoul spreads out as a sea of lights with no visible end.","story":"Namsan is a mountain right in the centre of Seoul, and the cable car from Myeongdong gets you up it in minutes. The broadcast tower built in 1971 is now an observatory: from the top the Han River cuts the city in two, the towers of Gangnam rise on the south bank, and to the north the palace roofs sit low among the buildings. Sunset is the moment worth waiting for — the city lights come on in patches. Along the railings at the foot of the tower hang thousands of love padlocks, rusting in the weather.","facts":["The tower is 236m tall, on top of Namsan''s 243m peak.","Opened in 1971, originally as a television broadcast tower.","The tower lights change colour with the city''s air quality index.","Reachable by cable car, Namsan bus or a 40-minute walking trail."],"travelTips":["Go up an hour before sunset to see the city by day and by night.","The cable car is busiest at weekends — the walking trail is a pleasant alternative.","Clear air after rain gives the longest views."],"bestTime":"September–November, on clear days","visitDuration":"2 hours","ticket":"Observatory 21,000 KRW (cable car extra)","openingHours":"10:30–22:30 weekdays, 10:00–23:00 weekends; last entry 30 min before closing","galleryCaptions":["Seoul from the observation deck"]},"ko":{"name":"N서울타워(남산)","summary":"도심 한복판의 산 정상. 끝이 보이지 않는 불빛의 바다가 펼쳐진다.","story":"남산은 서울 한가운데 있는 산이고, 명동에서 케이블카를 타면 몇 분 만에 오른다. 1971년 세워진 송신탑은 이제 전망대가 되었다. 위에서 보면 한강이 도시를 가로지르고 남쪽에는 강남의 고층 빌딩이, 북쪽에는 건물들 사이로 낮게 깔린 궁궐 지붕이 보인다. 기다릴 만한 순간은 해질녘이다. 도시의 불빛이 구역별로 켜지기 시작한다. 탑 아래 난간에는 비바람에 녹슨 사랑의 자물쇠가 빼곡하다.","facts":["탑 높이 236m, 해발 243m의 남산 정상에 서 있다.","1971년 텔레비전 송신탑으로 준공되었다.","탑의 조명 색은 서울의 대기질 지수에 따라 바뀐다.","케이블카, 남산 순환버스, 도보(약 40분) 모두 가능하다."],"travelTips":["일몰 한 시간 전에 올라가면 낮과 밤 풍경을 모두 볼 수 있다.","주말에는 케이블카가 붐비니 산책로도 좋은 선택이다.","비 온 뒤 맑은 날에 가장 멀리까지 보인다."],"bestTime":"9~11월, 맑은 날","visitDuration":"2시간","ticket":"전망대 21,000원(케이블카 별도)","openingHours":"평일 10:30~22:30, 주말 10:00~23:00(입장 마감 30분 전)","galleryCaptions":["전망대에서 본 서울"]},"ja":{"name":"Nソウルタワー（南山）","summary":"都心のただ中にある山頂。果てのない光の海が広がる。","story":"南山はソウルの真ん中にある山で、明洞からケーブルカーに乗れば数分で登れる。1971年に建った送信塔は今や展望台だ。上から見ると漢江が街を二つに分け、南岸には江南の高層ビル群、北には建物の合間に低く伸びる宮殿の屋根が見える。待つ価値があるのは日没だ。街の灯りが区画ごとに点いていく。塔の足元の柵には、風雨に錆びた愛の南京錠がびっしりと掛かっている。","facts":["塔の高さは236m、標高243mの南山の頂に立つ。","1971年にテレビ送信塔として竣工した。","塔の照明の色はソウルの大気質指数によって変わる。","ケーブルカー、南山循環バス、徒歩（約40分）で行ける。"],"travelTips":["日没の1時間前に登れば昼と夜の両方の景色が見られる。","週末のケーブルカーは混雑する。散策路も気持ちがよい。","雨上がりの晴れた日が最も遠くまで見える。"],"bestTime":"9〜11月の晴れた日","visitDuration":"2時間","ticket":"展望台21,000ウォン（ケーブルカーは別途）","openingHours":"平日10:30〜22:30、週末10:00〜23:00（入場は閉館30分前まで）","galleryCaptions":["展望台から見たソウル"]},"zh":{"name":"N首爾塔（南山）","summary":"市中心的山頂，首爾在腳下鋪成一片望不到盡頭的燈海。","story":"南山就在首爾正中央，從明洞搭纜車幾分鐘即可登頂。1971年落成的發射塔如今成了觀景台：漢江把城市切成兩半，南岸是江南的高樓，北面則是低伏於樓群之間的宮殿屋頂。最值得等待的時刻是日落，城市的燈火一片片亮起。塔下的欄杆上掛滿了被風雨鏽蝕的愛情鎖。","facts":["塔高236公尺，立於海拔243公尺的南山之巔。","1971年落成，最初為電視發射塔。","塔身燈光顏色會隨城市空氣品質指數變化。","可搭纜車、南山循環巴士或步行約40分鐘上山。"],"travelTips":["日落前一小時上山，可同時看到白晝與夜景。","週末纜車擁擠，步道其實很舒服。","雨後放晴的日子視野最遠。"],"bestTime":"9至11月的晴天","visitDuration":"2小時","ticket":"觀景台21,000韓元（纜車另計）","openingHours":"平日10:30–22:30，週末10:00–23:00（閉館前30分鐘停止入場）","galleryCaptions":["自觀景台俯瞰首爾"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('myeongdong', 'myeongdong', 'seoul', 'Phố Myeongdong', 'Myeongdong Street', 'market', 126.985, 37.5636, 'Khu phố mua sắm ồn ã nhất Seoul, buổi tối biến thành một dãy bếp lộ thiên nghi ngút khói.', 'Ban ngày Myeongdong là mỹ phẩm: từng cửa hiệu phát mẫu thử, nhân viên đứng trước cửa mời chào bằng bốn thứ tiếng. Chập tối, xe đẩy đồ ăn được kéo ra giữa lòng đường và cả khu phố đổi mùi — tteokbokki cay đỏ, phô mai nướng kéo sợi, tôm hùm đất nướng bơ tỏi, bánh trứng gyeran-ppang nóng hổi. Ăn đứng, giấy lau vắt trên tay, rồi đi tiếp. Phía trên đầu là nhà thờ Myeongdong bằng gạch đỏ kiểu Gothic, chứng nhân lặng lẽ của khu phố từ năm 1898.', '["Là một trong những khu phố có giá thuê mặt bằng đắt nhất châu Á.","Nhà thờ Myeongdong xây năm 1898, là nhà thờ chính toà của Tổng giáo phận Seoul.","Hàng ăn đường phố dọn ra chủ yếu từ 16h đến khuya.","Có quầy hoàn thuế cho khách nước ngoài ngay trong khu phố."]', '["Mang tiền mặt lẻ — nhiều xe đẩy không nhận thẻ.","Nhớ giữ hoá đơn nếu mua mỹ phẩm để hoàn thuế ở sân bay.","Thứ Bảy tối là lúc đông nhất, đi trong tuần dễ chịu hơn."]', 'Buổi tối, quanh năm', '2–3 giờ', '', 'Không có giờ đóng mở chính thức; cửa hàng mở 10:00–11:00 và đóng 21:00–22:00, xe đồ ăn đường phố ra từ chiều muộn tới khuya', '["popular","trending"]', '["ẩm thực đường phố","mua sắm","về đêm"]', '[{"seed":"myeongdong","caption":"Xe đẩy đồ ăn buổi tối","ratio":"16/9"}]', '["n-seoul-tower","gyeongbokgung"]', 0, 'https://korean.visitkorea.or.kr/', '2026-08-04', '{"en":{"name":"Myeongdong Street","summary":"Seoul''s loudest shopping quarter, which turns into a street of open-air kitchens after dark.","story":"By day Myeongdong is cosmetics: every shop hands out samples, staff call out in four languages from the doorways. At dusk food carts are wheeled into the middle of the street and the whole quarter changes smell — fiery red tteokbokki, cheese pulled into strings, crayfish grilled in garlic butter, hot gyeran-ppang egg bread. You eat standing up, napkin in hand, then move on. Above it all stands Myeongdong Cathedral in red brick, a quiet witness to the neighbourhood since 1898.","facts":["One of the most expensive retail districts in Asia by rent.","Myeongdong Cathedral, built in 1898, is the seat of the Archdiocese of Seoul.","Street food carts mostly appear from 4pm until late.","Tax refund counters for foreign visitors are in the district itself."],"travelTips":["Bring small cash — many carts don''t take cards.","Keep cosmetics receipts for the airport tax refund.","Saturday night is the busiest; weekdays are far easier."],"bestTime":"Evenings, year-round","visitDuration":"2–3 hours","ticket":"","openingHours":"There are no official hours; shops open between 10:00 and 11:00 and close between 21:00 and 22:00, while the street-food carts appear from late afternoon into the night","galleryCaptions":["Evening food carts"]},"ko":{"name":"명동","summary":"서울에서 가장 북적이는 쇼핑 거리. 저녁이면 노천 주방으로 바뀐다.","story":"낮의 명동은 화장품이다. 가게마다 샘플을 건네고 직원들이 네 나라 말로 손님을 부른다. 해가 지면 길 한가운데로 포장마차가 나오고 거리의 냄새가 바뀐다. 새빨간 떡볶이, 늘어지는 치즈, 마늘버터를 바른 가재구이, 갓 구운 계란빵. 서서 먹고 휴지를 손에 쥔 채 다음 가게로 옮겨간다. 그 위로 1898년부터 이 동네를 지켜본 붉은 벽돌의 명동성당이 서 있다.","facts":["임대료 기준으로 아시아에서 손꼽히는 상권이다.","1898년 세워진 명동성당은 천주교 서울대교구 주교좌 성당이다.","노점은 주로 오후 4시부터 늦은 밤까지 열린다.","외국인 관광객을 위한 택스리펀 창구가 거리 안에 있다."],"travelTips":["현금을 조금 준비하자. 카드를 받지 않는 노점이 많다.","화장품을 샀다면 공항 환급을 위해 영수증을 챙기자.","토요일 밤이 가장 붐비고 평일이 훨씬 편하다."],"bestTime":"연중, 저녁 시간","visitDuration":"2~3시간","ticket":"","openingHours":"공식 운영시간은 없다. 상점은 10~11시에 열어 21~22시에 닫고, 노점은 늦은 오후부터 밤까지 영업한다","galleryCaptions":["저녁의 포장마차 거리"]},"ja":{"name":"明洞","summary":"ソウルで最も賑わう買い物街。夜になると屋台の厨房が路上に並ぶ。","story":"昼の明洞は化粧品だ。店ごとにサンプルを配り、店員が四か国語で客を呼ぶ。日が落ちると道の真ん中に屋台が引き出され、街の匂いが変わる。真っ赤なトッポッキ、糸を引くチーズ、ニンニクバターのザリガニ焼き、焼きたての鶏卵パン。立ったまま食べ、紙ナプキンを手に次の店へ移る。その上には1898年からこの町を見守る赤煉瓦の明洞聖堂が立っている。","facts":["賃料でアジア屈指の商業地区である。","1898年建立の明洞聖堂はソウル大司教区の司教座聖堂。","屋台はおおむね16時から深夜まで営業する。","外国人向けの税金還付カウンターが街区内にある。"],"travelTips":["現金を少し用意しよう。カード不可の屋台が多い。","化粧品を買ったら空港での還付のため領収書を保管しよう。","土曜の夜が最も混む。平日のほうがずっと歩きやすい。"],"bestTime":"通年、夕方","visitDuration":"2〜3時間","ticket":"","openingHours":"公式の営業時間はない。店は10〜11時に開き21〜22時に閉まり、屋台は夕方遅くから夜まで出る","galleryCaptions":["夜の屋台通り"]},"zh":{"name":"明洞","summary":"首爾最熱鬧的購物街，入夜化作一整排露天廚房。","story":"白天的明洞屬於化妝品：每間店都遞出試用品，店員在門口用四種語言招呼。天色一暗，攤車推到路中央，整條街的氣味就變了——火紅的辣炒年糕、拉出絲的起司、蒜香奶油小龍蝦、剛出爐的雞蛋糕。站著吃，紙巾捏在手裡，再走向下一攤。這一切之上，是1898年就在此的紅磚哥德式明洞聖堂，安靜地看著這個街區。","facts":["以租金計，是亞洲數一數二昂貴的商圈。","1898年落成的明洞聖堂是首爾總教區主教座堂。","路邊攤大多從下午四點營業到深夜。","街區內設有外國旅客退稅櫃檯。"],"travelTips":["帶些零錢，許多攤位不收卡。","買化妝品記得留發票，機場可退稅。","週六夜晚最擁擠，平日輕鬆許多。"],"bestTime":"全年，傍晚時段","visitDuration":"2至3小時","ticket":"","openingHours":"沒有官方營業時間；店家約10至11點開門、21至22點打烊，路邊攤則從傍晚擺到深夜","galleryCaptions":["夜晚的小吃攤"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hangang-yeouido-park', 'hangang-yeouido-park', 'seoul', 'Công viên sông Hàn Yeouido', 'Yeouido Hangang Park', 'park', 126.9337, 37.5285, 'Bãi cỏ ven sông nơi người Seoul trải bạt, gọi gà rán và xem mặt trời lặn sau các cây cầu.', 'Sông Hàn rộng đến mức bờ bên kia trông như một thành phố khác, và người Seoul đã biến hai bên bờ thành phòng khách chung của mình. Chiều muộn, bãi cỏ Yeouido phủ kín chiếu và lều bạt; điện thoại gọi gà rán giao tận nơi trên cỏ là một nghi thức. Thuê xe đạp chạy dọc đường ven sông, hoặc lên du thuyền ngắm cầu Banpo phun nước theo nhạc. Cuối tháng 3, con đường Yunjung-ro ngay sau lưng công viên nở trắng hoa anh đào và cả thành phố kéo về đây.', '["Là một trong 11 công viên ven sông Hàn của Seoul.","Lễ hội hoa anh đào Yeouido diễn ra vào đầu tháng 4 hằng năm.","Cầu Banpo gần đó có màn phun nước cầu vồng vào buổi tối mùa hè.","Có trạm thuê xe đạp công cộng Ttareungi ngay trong công viên."]', '["Cuối tuần đông nghịt — đi tối thứ Năm hoặc thứ Sáu dễ chọn chỗ hơn.","Tiện lợi hơn cả: mua chiếu và đồ ăn ở cửa hàng tiện lợi ngay cạnh bãi cỏ.","Mang áo khoác mỏng, gió sông về đêm khá lạnh kể cả mùa hè."]', 'Tháng 4 (hoa anh đào) và tháng 9–10', '2 giờ', '', 'Mở cả ngày', '["popular"]', '["sông Hàn","picnic","hoàng hôn","hoa anh đào"]', '[{"seed":"hangang-yeouido-park","caption":"Hoàng hôn trên sông Hàn","ratio":"16/9"}]', '["myeongdong"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Yeouido Hangang Park","summary":"The riverside lawn where Seoul spreads out mats, orders fried chicken and watches the sun set behind the bridges.","story":"The Han River is so wide that the far bank looks like a different city, and Seoulites have turned both banks into their shared living room. Late afternoon, the Yeouido lawn fills with mats and pop-up tents; ordering fried chicken delivered to you on the grass is a ritual. Rent a bike and ride the riverside path, or take a cruise past Banpo Bridge as it fountains water to music. At the end of March the Yunjung-ro road just behind the park turns white with cherry blossom and the whole city comes.","facts":["One of Seoul''s 11 Han River parks.","The Yeouido Cherry Blossom Festival is held in early April each year.","Nearby Banpo Bridge stages a rainbow fountain show on summer evenings.","A Ttareungi public bike station sits inside the park."],"travelTips":["Weekends are packed — Thursday or Friday evening gives you a better spot.","Easiest plan: buy a mat and food at the convenience store beside the lawn.","Bring a light jacket; the river wind is cool even in summer."],"bestTime":"April (cherry blossom) and September–October","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["Sunset over the Han River"]},"ko":{"name":"여의도 한강공원","summary":"돗자리를 펴고 치킨을 시켜 다리 너머 노을을 보는, 서울의 강변 잔디밭.","story":"한강은 건너편이 다른 도시처럼 보일 만큼 넓고, 서울 사람들은 그 양쪽 기슭을 공동의 거실로 만들었다. 늦은 오후 여의도 잔디밭은 돗자리와 그늘막으로 가득 차고, 잔디 위로 치킨을 배달시키는 것은 하나의 의식이다. 자전거를 빌려 강변길을 달리거나, 유람선을 타고 음악에 맞춰 물을 뿜는 반포대교를 지나도 좋다. 3월 말이면 공원 뒤 윤중로가 벚꽃으로 하얘지고 온 도시가 몰려든다.","facts":["서울의 11개 한강공원 가운데 하나다.","여의도 봄꽃축제는 해마다 4월 초에 열린다.","가까운 반포대교에서는 여름 저녁 달빛무지개분수가 가동된다.","공원 안에 따릉이 대여소가 있다."],"travelTips":["주말은 매우 붐빈다. 목요일이나 금요일 저녁이 자리 잡기 좋다.","잔디밭 옆 편의점에서 돗자리와 먹거리를 함께 사는 것이 가장 편하다.","여름에도 강바람이 서늘하니 얇은 겉옷을 챙기자."],"bestTime":"4월(벚꽃)과 9~10월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["한강의 일몰"]},"ja":{"name":"汝矣島漢江公園","summary":"レジャーシートを広げチキンを頼み、橋の向こうの夕日を眺める川辺の芝生。","story":"漢江は対岸が別の街に見えるほど広く、ソウルの人々はその両岸を共有の居間にしてしまった。午後遅く、汝矣島の芝生はシートとテントで埋まり、芝の上までチキンを配達させるのは一種の儀式だ。自転車を借りて川沿いを走るのもいいし、音楽に合わせて水を吹く盤浦大橋を遊覧船で通るのもいい。3月末には公園の裏の輪中路が桜で白くなり、街じゅうが押し寄せる。","facts":["ソウルに11ある漢江公園のひとつ。","汝矣島の春の花祭りは毎年4月初めに開かれる。","近くの盤浦大橋では夏の夜に月光レインボー噴水が稼働する。","公園内に公共自転車「タルンイ」の駐輪所がある。"],"travelTips":["週末は非常に混む。木曜か金曜の夕方が場所を取りやすい。","芝生脇のコンビニでシートと食べ物を揃えるのが一番手軽。","夏でも川風は涼しいので薄い上着を持とう。"],"bestTime":"4月（桜）と9〜10月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["漢江の夕暮れ"]},"zh":{"name":"汝矣島漢江公園","summary":"首爾人鋪野餐墊、叫炸雞，看夕陽落在橋後的河畔草地。","story":"漢江寬得對岸像是另一座城市，而首爾人把兩岸變成了共用的客廳。傍晚時分，汝矣島的草地鋪滿野餐墊與遮陽帳；打電話叫炸雞外送到草地上，幾乎成了一種儀式。你可以租輛單車沿江騎行，或搭遊船經過隨音樂噴水的盤浦大橋。三月底，公園後方的輪中路開滿櫻花，整座城市都湧來。","facts":["首爾11座漢江公園之一。","汝矣島春花節每年四月初舉行。","鄰近的盤浦大橋在夏夜有月光彩虹噴泉。","公園內設有公共單車「Ttareungi」站點。"],"travelTips":["週末非常擁擠，週四或週五傍晚較好找位置。","最省事的做法：在草地旁的便利商店買野餐墊與食物。","帶件薄外套，夏夜的江風仍涼。"],"bestTime":"4月（櫻花）與9至10月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["漢江上的日落"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('dongdaemun-ddp', 'dongdaemun-ddp', 'seoul', 'Quảng trường Thiết kế Dongdaemun (DDP)', 'Dongdaemun Design Plaza', 'city', 127.0094, 37.5665, 'Khối nhôm cong không một góc vuông của Zaha Hadid, đặt cạnh nền móng thành cổ đào được khi thi công.', 'DDP trông như một vật thể đáp xuống Dongdaemun: hơn bốn mươi nghìn tấm nhôm uốn cong, không có hai tấm nào giống nhau, và bên trong gần như không tìm được một đường thẳng. Trong lúc đào móng, công nhân chạm phải nền tường thành Seoul thời Joseon cùng doanh trại và cống nước — thay vì lấp đi, thành phố giữ lại và biến thành công viên di tích ngay dưới chân toà nhà. Ban đêm, sườn dốc phía ngoài được thắp bằng hàng chục nghìn bông hoa LED. Khu Dongdaemun quanh đó là chợ vải và quần áo sỉ mở tới rạng sáng — một nhịp sống hoàn toàn lệch múi giờ với phần còn lại của thành phố.', '["Do Zaha Hadid thiết kế, khánh thành năm 2014.","Vỏ ngoài ghép từ hơn 45.000 tấm nhôm, mỗi tấm một hình dạng khác nhau.","Di tích tường thành Joseon phát lộ khi thi công được giữ lại thành công viên lịch sử.","Chợ sỉ quần áo Dongdaemun quanh đó mở cửa từ tối tới rạng sáng."]', '["Đi buổi tối để xem cả đèn LED lẫn chợ đêm Dongdaemun.","Triển lãm bên trong tính vé riêng; khu ngoài trời và mái dốc thì miễn phí.","Ga Dongdaemun History & Culture Park nối thẳng vào tầng hầm toà nhà."]', 'Quanh năm; buổi tối đẹp nhất', '1,5–2 giờ', 'Khu ngoài trời miễn phí; triển lãm khoảng 8.000–15.000 KRW', 'Khu ngoài trời mở 24 giờ; phòng triển lãm 10:00–19:00 (thứ Tư và thứ Sáu đến 21:00), đóng cửa thứ Hai', '["trending"]', '["kiến trúc","thiết kế","về đêm","chợ đêm"]', '[{"seed":"dongdaemun-ddp","caption":"Vỏ nhôm cong của DDP về đêm","ratio":"16/9"}]', '["gwangjang-market","cheonggyecheon"]', 0, 'https://english.visitseoul.net/attractions/Dongdaemun-Design-Plaza-en/ENP024679', '2026-08-04', '{"en":{"name":"Dongdaemun Design Plaza","summary":"Zaha Hadid''s curving aluminium mass, set beside the foundations of the old city wall that were dug up while building it.","story":"DDP looks like something that landed in Dongdaemun: more than forty thousand curved aluminium panels, no two alike, and an interior in which a straight line is hard to find. While excavating the foundations, workers struck the base of Seoul''s Joseon-era city wall along with barracks and a water conduit — instead of covering it over, the city kept it and turned it into a heritage park at the building''s foot. At night the outer slope is lit with tens of thousands of LED flowers. The Dongdaemun district around it is a wholesale fabric and clothing market that trades until dawn, running on a clock entirely out of step with the rest of the city.","facts":["Designed by Zaha Hadid and opened in 2014.","The shell is made of more than 45,000 aluminium panels, each a different shape.","Joseon city-wall remains found during construction were preserved as a history park.","The surrounding Dongdaemun wholesale market trades from evening until dawn."],"travelTips":["Come in the evening for both the LED field and the Dongdaemun night market.","Indoor exhibitions are ticketed separately; the grounds and roof slope are free.","Dongdaemun History & Culture Park station connects straight into the basement."],"bestTime":"Year-round; best in the evening","visitDuration":"1.5–2 hours","ticket":"Grounds free; exhibitions typically 8,000–15,000 KRW","openingHours":"Grounds open 24 hours; exhibition halls 10:00–19:00 (to 21:00 Wed and Fri), closed Mondays","galleryCaptions":["DDP''s curved shell at night"]},"ko":{"name":"동대문디자인플라자(DDP)","summary":"직각이 없는 자하 하디드의 알루미늄 덩어리. 공사 중 드러난 한양도성 유구가 그 옆에 있다.","story":"DDP는 동대문에 내려앉은 물체처럼 보인다. 4만 장이 넘는 곡면 알루미늄 패널은 같은 것이 하나도 없고, 내부에서는 직선을 찾기 어렵다. 기초를 파던 중 인부들이 조선시대 한양도성의 기단과 군영 터, 수문을 만났다. 서울시는 덮는 대신 남겨 건물 발치의 역사공원으로 만들었다. 밤이면 바깥 경사면에 수만 송이의 LED 장미가 켜진다. 주변 동대문 일대는 새벽까지 돌아가는 원단·의류 도매시장이라, 도시의 나머지와 완전히 다른 시간표로 살아간다.","facts":["자하 하디드가 설계해 2014년 개관했다.","외피는 4만 5천 장이 넘는 알루미늄 패널로, 모두 형태가 다르다.","공사 중 발견된 한양도성 유구는 역사공원으로 보존되었다.","주변 동대문 도매시장은 저녁부터 새벽까지 영업한다."],"travelTips":["LED 장미와 동대문 야시장을 함께 보려면 저녁에 가자.","실내 전시는 별도 유료이고 외부 광장과 지붕 경사로는 무료다.","동대문역사문화공원역이 지하로 바로 연결된다."],"bestTime":"연중, 저녁이 가장 좋다","visitDuration":"1.5~2시간","ticket":"외부 공간 무료, 전시는 대체로 8,000~15,000원","openingHours":"외부 공간 24시간 개방, 전시관 10:00~19:00(수·금은 21:00까지), 월요일 휴관","galleryCaptions":["밤의 DDP 곡면 외피"]},"ja":{"name":"東大門デザインプラザ（DDP）","summary":"直角のないザハ・ハディドのアルミの塊。工事中に現れた漢陽都城の遺構がその脇にある。","story":"DDPは東大門に降り立った物体のように見える。四万枚を超える曲面アルミパネルは同じものがひとつもなく、内部では直線を探すのが難しい。基礎を掘っていた作業員が、朝鮮時代の漢陽都城の基壇と兵営跡、水門に突き当たった。市は覆う代わりに残し、建物の足元の歴史公園にした。夜には外側の斜面に数万のLEDの花が灯る。周囲の東大門一帯は明け方まで動く生地・衣料の卸売市場で、街の他の部分とはまるで違う時計で生きている。","facts":["ザハ・ハディド設計、2014年開館。","外皮は4万5千枚を超えるアルミパネルで、すべて形が異なる。","工事中に見つかった漢陽都城の遺構は歴史公園として保存された。","周辺の東大門卸売市場は夕方から明け方まで営業する。"],"travelTips":["LEDの花と東大門の夜市を両方見るなら夜に。","屋内展示は別料金、屋外広場と屋根の斜面は無料。","東大門歴史文化公園駅が地下で直結している。"],"bestTime":"通年、夜が最良","visitDuration":"1.5〜2時間","ticket":"屋外は無料、展示はおおむね8,000〜15,000ウォン","openingHours":"屋外は24時間開放、展示室は10:00〜19:00（水・金は21:00まで）、月曜休館","galleryCaptions":["夜のDDPの曲面外皮"]},"zh":{"name":"東大門設計廣場（DDP）","summary":"札哈·哈蒂沒有一個直角的鋁製量體，旁邊就是施工時挖出的舊城牆遺構。","story":"DDP看起來像降落在東大門的一件物體：四萬多片曲面鋁板，沒有兩片相同，室內幾乎找不到一條直線。開挖地基時，工人碰到了朝鮮時代漢陽都城的牆基、軍營遺址與水門——市府沒有覆蓋掉，而是保留下來，在建築腳下闢成歷史公園。入夜後，外側斜面點起數萬朵LED花。周邊東大門一帶是做到天亮的布料與成衣批發市場，作息與城市其他地方完全錯開。","facts":["由札哈·哈蒂設計，2014年啟用。","外殼由四萬五千多片鋁板構成，每片形狀都不同。","施工中發現的漢陽都城遺構被保留為歷史公園。","周邊東大門批發市場從傍晚營業到清晨。"],"travelTips":["傍晚前往，可同時看LED花海與東大門夜市。","室內展覽另行售票，戶外廣場與屋頂斜坡免費。","東大門歷史文化公園站可直通地下樓層。"],"bestTime":"全年，夜晚最佳","visitDuration":"1.5至2小時","ticket":"戶外免費，展覽約8,000至15,000韓元","openingHours":"戶外24小時開放，展廳10:00–19:00（週三與週五至21:00），週一休館","galleryCaptions":["夜裡DDP的曲面外殼"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hongdae', 'hongdae', 'seoul', 'Khu Hongdae', 'Hongdae', 'city', 126.9236, 37.5563, 'Khu quanh trường mỹ thuật Hongik, nơi ban nhạc sinh viên dựng loa ngay giữa phố và hát tới nửa đêm.', 'Hongdae lấy tên từ Đại học Hongik, trường mỹ thuật danh tiếng nhất Hàn Quốc, và cả khu phố mang tính cách của sinh viên nghệ thuật: tường vẽ graffiti, quán cà phê mở trong nhà xưởng cũ, tiệm đĩa than, và những sân khấu đường phố mọc lên ngay khi trời tối. Cuối tuần, ''phố đi bộ'' trước cổng trường chật kín người xem các nhóm nhảy cover và ban nhạc indie — nhiều nghệ sĩ Hàn nổi tiếng từng bắt đầu đúng ở vỉa hè này. Càng đi sâu vào các ngõ về phía Yeonnam-dong, nhịp phố càng chậm lại: quán nhỏ, cây xanh, công viên đường ray cũ chạy dài.', '["Tên khu lấy từ Đại học Hongik, trường mỹ thuật hàng đầu Hàn Quốc.","Sân khấu đường phố trước cổng trường diễn ra gần như mỗi tối cuối tuần.","Công viên Gyeongui Line Forest được cải tạo từ tuyến đường sắt cũ.","Là nơi tập trung nhiều câu lạc bộ nhạc sống và indie nhất Seoul."]', '["Tối thứ Sáu và thứ Bảy là lúc có nhiều buổi diễn đường phố nhất.","Muốn yên tĩnh hơn thì đi về phía Yeonnam-dong hoặc Sangsu-dong.","Ga Hongik University có nhiều cửa ra — cửa số 9 gần phố đi bộ nhất."]', 'Quanh năm; tối cuối tuần', '2–3 giờ', '', 'Phố mở cả ngày; biểu diễn đường phố và nhạc sống chủ yếu từ 19:00 tới nửa đêm, cuối tuần đông nhất', '["trending","popular"]', '["nhạc sống","sinh viên","cà phê","về đêm"]', '[{"seed":"hongdae","caption":"Diễn đường phố trước cổng Hongik","ratio":"16/9"}]', '["hangang-yeouido-park","myeongdong"]', 0, 'https://korean.visitkorea.or.kr/', '2026-08-04', '{"en":{"name":"Hongdae","summary":"The quarter around Hongik art university, where student bands set up amplifiers in the street and play until midnight.","story":"Hongdae takes its name from Hongik University, Korea''s most respected art school, and the whole quarter has the character of art students: graffitied walls, cafés in converted workshops, record shops, and street stages that appear the moment it gets dark. At weekends the pedestrian street outside the university gate fills with crowds watching cover dance crews and indie bands — plenty of well-known Korean acts started on exactly this pavement. The further you walk into the lanes towards Yeonnam-dong, the slower the pace gets: small bars, trees, and a long park built on a disused railway line.","facts":["Named after Hongik University, Korea''s leading art school.","Street performances happen outside the university gate almost every weekend night.","Gyeongui Line Forest Park was converted from a disused railway.","It has the highest concentration of live music and indie clubs in Seoul."],"travelTips":["Friday and Saturday nights have the most street performances.","For something quieter, head towards Yeonnam-dong or Sangsu-dong.","Hongik University station has many exits — exit 9 is closest to the walking street."],"bestTime":"Year-round; weekend nights","visitDuration":"2–3 hours","ticket":"","openingHours":"The streets are always open; busking and live music run mainly from 19:00 to midnight, busiest at weekends","galleryCaptions":["Street performance outside the Hongik gate"]},"ko":{"name":"홍대","summary":"홍익대 앞 동네. 학생 밴드가 길 한복판에 앰프를 놓고 자정까지 노래한다.","story":"홍대는 한국에서 가장 이름난 미술대학인 홍익대에서 이름을 따왔고, 동네 전체가 미대생의 성격을 닮았다. 그래피티가 그려진 벽, 옛 공장을 고친 카페, 레코드 가게, 그리고 해가 지면 생기는 거리 무대. 주말이면 학교 정문 앞 걷고싶은거리가 커버댄스 팀과 인디 밴드를 보러 온 사람으로 가득 찬다. 이름난 한국 뮤지션 상당수가 바로 이 인도에서 시작했다. 연남동 쪽 골목으로 들어갈수록 속도가 느려진다. 작은 가게와 나무, 그리고 옛 철길 위에 만든 긴 공원이 이어진다.","facts":["한국 대표 미술대학인 홍익대학교에서 이름을 따왔다.","정문 앞 거리 공연은 주말 밤이면 거의 매번 열린다.","경의선숲길공원은 폐선된 철길을 공원으로 바꾼 것이다.","서울에서 라이브 클럽과 인디 공연장이 가장 밀집한 곳이다."],"travelTips":["거리 공연이 가장 많은 때는 금요일과 토요일 밤이다.","조용한 곳을 원하면 연남동이나 상수동 쪽으로 가자.","홍대입구역은 출구가 많다. 걷고싶은거리는 9번 출구가 가깝다."],"bestTime":"연중, 주말 밤","visitDuration":"2~3시간","ticket":"","openingHours":"거리는 상시 개방. 버스킹과 라이브 공연은 주로 19:00부터 자정까지이며 주말에 가장 붐빈다","galleryCaptions":["홍대 정문 앞 거리 공연"]},"ja":{"name":"弘大","summary":"弘益大学前の一帯。学生バンドが路上にアンプを置き、真夜中まで歌う。","story":"弘大の名は韓国で最も名高い美術大学、弘益大学から来ていて、街全体が美大生の性格をしている。グラフィティの壁、古い工場を改装したカフェ、レコード店、そして日が落ちると現れる路上ステージ。週末には正門前の「歩きたい通り」が、カバーダンスチームとインディーバンドを見に来た人で埋まる。名の知れた韓国のミュージシャンの多くが、まさにこの歩道から始まった。延南洞の方の路地へ入るほど速度は落ちる。小さな店と木々、そして旧線路の上に作られた長い公園が続く。","facts":["韓国を代表する美術大学、弘益大学に由来する名。","正門前の路上公演は週末の夜ならほぼ毎回開かれる。","京義線フォレストパークは廃線跡を公園に変えたもの。","ソウルでライブクラブとインディー会場が最も密集する地域。"],"travelTips":["路上公演が最も多いのは金曜と土曜の夜。","静かな方がよければ延南洞や上水洞へ。","弘大入口駅は出口が多い。歩きたい通りは9番出口が近い。"],"bestTime":"通年、週末の夜","visitDuration":"2〜3時間","ticket":"","openingHours":"街は終日開放。バスキングやライブは主に19:00から深夜までで、週末が最も混む","galleryCaptions":["弘益大学正門前の路上公演"]},"zh":{"name":"弘大","summary":"弘益大學周邊，學生樂團把音箱搬到街上，一唱唱到半夜。","story":"弘大之名來自韓國最負盛名的美術學院弘益大學，整個街區也帶著美術系學生的性格：塗鴉牆、由舊廠房改建的咖啡館、黑膠唱片行，以及天一黑就冒出來的街頭舞台。週末校門前的「想走路的街」擠滿了看翻跳團體與獨立樂團的人群——不少知名韓國音樂人正是從這片人行道起步。往延南洞方向的巷子愈走愈深，節奏也愈慢：小店、樹蔭，以及一條蓋在廢棄鐵道上的狹長公園。","facts":["名稱來自韓國頂尖美術學院弘益大學。","校門前的街頭表演幾乎每個週末夜晚都有。","京義線林蔭道公園由廢棄鐵道改建而成。","是首爾展演空間與獨立音樂場地最密集的區域。"],"travelTips":["週五與週六夜晚的街頭表演最多。","想安靜一點就往延南洞或上水洞走。","弘大入口站出口很多，9號出口離步行街最近。"],"bestTime":"全年，週末夜晚","visitDuration":"2至3小時","ticket":"","openingHours":"街區全日開放；街頭表演與現場音樂主要在19:00至午夜，週末最熱鬧","galleryCaptions":["弘益大學校門前的街頭表演"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('lotte-world-tower', 'lotte-world-tower', 'seoul', 'Toà tháp Lotte World & Seoul Sky', 'Lotte World Tower & Seoul Sky', 'city', 127.1025, 37.5125, 'Toà nhà cao nhất Hàn Quốc, với sàn kính ở độ cao gần nửa cây số nhìn thẳng xuống Jamsil.', 'Lotte World Tower cao 555 mét và thon dần lên đỉnh theo hình dáng lấy cảm hứng từ cây bút lông và đồ gốm Hàn Quốc. Thang máy hai tầng lên đài quan sát Seoul Sky mất chưa tới một phút, và ở tầng 118 có một khoảng sàn bằng kính trong suốt — đứng lên đó nhìn xuống thấy xe cộ Jamsil bé như hạt. Ngày trời trong, tầm nhìn kéo tới tận núi Bukhansan phía bắc và dãy Gwanaksan phía nam. Dưới chân tháp là hồ Seokchon, nơi hoa anh đào nở vòng quanh mặt nước vào đầu tháng 4, và công viên giải trí trong nhà lớn nhất thế giới.', '["Cao 555m với 123 tầng, là toà nhà cao nhất Hàn Quốc.","Đài quan sát Seoul Sky nằm ở tầng 117–123, có sàn kính ở tầng 118.","Thang máy lên đài quan sát chạy khoảng 600m/phút.","Công viên Lotte World dưới chân tháp là công viên giải trí trong nhà lớn nhất thế giới."]', '["Đặt vé theo khung giờ trên mạng, rẻ và nhanh hơn mua tại quầy.","Chọn khung giờ trước hoàng hôn 45 phút để xem cả ngày lẫn đêm.","Đầu tháng 4 kết hợp đi vòng hồ Seokchon ngắm hoa anh đào."]', 'Tháng 4 (hoa anh đào) và tháng 10–11 (trời trong)', '2 giờ', 'Seoul Sky 31.000 KRW (người lớn)', '10:30–22:00 (thứ Sáu, thứ Bảy và ngày lễ đến 23:00); bán vé cuối trước 1 giờ', '["popular","trending"]', '["toàn cảnh","kiến trúc","sàn kính"]', '[{"seed":"lotte-world-tower","caption":"Seoul nhìn từ Seoul Sky","ratio":"16/9"}]', '["bongeunsa","seoul-forest"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=65854', '2026-08-04', '{"en":{"name":"Lotte World Tower & Seoul Sky","summary":"Korea''s tallest building, with a glass floor almost half a kilometre up looking straight down onto Jamsil.","story":"Lotte World Tower stands 555 metres and tapers as it rises, a shape drawn from Korean writing brushes and ceramics. The double-decker lift to the Seoul Sky observatory takes under a minute, and on floor 118 there is a stretch of clear glass floor — stand on it and the traffic in Jamsil is the size of grain. On a clear day the view reaches Bukhansan in the north and the Gwanaksan ridge in the south. At the foot of the tower is Seokchon Lake, ringed with cherry blossom in early April, and the largest indoor amusement park in the world.","facts":["555m tall with 123 floors, the tallest building in Korea.","The Seoul Sky observatory occupies floors 117–123, with a glass floor on 118.","The observatory lift travels at about 600m per minute.","Lotte World at its base is the world''s largest indoor amusement park."],"travelTips":["Book a timed ticket online; it is cheaper and faster than the counter.","Choose a slot 45 minutes before sunset to catch both day and night.","In early April, walk the loop around Seokchon Lake for the cherry blossom."],"bestTime":"April (cherry blossom) and October–November (clear skies)","visitDuration":"2 hours","ticket":"Seoul Sky 31,000 KRW (adult)","openingHours":"10:30–22:00 (to 23:00 Fri, Sat and holidays); last ticket 1 hour before closing","galleryCaptions":["Seoul from Seoul Sky"]},"ko":{"name":"롯데월드타워와 서울스카이","summary":"한국에서 가장 높은 건물. 500m에 가까운 높이에서 잠실을 내려다보는 유리 바닥이 있다.","story":"롯데월드타워는 높이 555m로, 위로 갈수록 가늘어지는 형태는 한국의 붓과 도자기에서 왔다. 서울스카이 전망대까지 가는 2층 엘리베이터는 1분이 채 걸리지 않고, 118층에는 투명한 유리 바닥 구간이 있다. 그 위에 서면 잠실의 차들이 낟알만 하다. 맑은 날에는 북쪽으로 북한산, 남쪽으로 관악산 능선까지 보인다. 타워 발치에는 4월 초 벚꽃이 물가를 두르는 석촌호수와, 세계에서 가장 큰 실내 놀이공원이 있다.","facts":["높이 555m, 123층으로 한국에서 가장 높은 건물이다.","서울스카이 전망대는 117~123층이며 118층에 유리 바닥이 있다.","전망대 엘리베이터는 분당 약 600m로 오른다.","발치의 롯데월드는 세계 최대 규모의 실내 놀이공원이다."],"travelTips":["온라인 시간 지정 예매가 현장 구매보다 싸고 빠르다.","일몰 45분 전 회차를 고르면 낮과 밤을 모두 볼 수 있다.","4월 초라면 석촌호수 한 바퀴를 걸으며 벚꽃을 보자."],"bestTime":"4월(벚꽃)과 10~11월(맑은 하늘)","visitDuration":"2시간","ticket":"서울스카이 31,000원(성인)","openingHours":"10:30~22:00(금·토·공휴일은 23:00까지), 매표 마감 1시간 전","galleryCaptions":["서울스카이에서 본 서울"]},"ja":{"name":"ロッテワールドタワーとソウルスカイ","summary":"韓国で最も高い建物。500m近い高さから蚕室を見下ろすガラス床がある。","story":"ロッテワールドタワーは高さ555m、上に向かって細くなる形は韓国の筆と陶磁器から取られている。ソウルスカイ展望台への二階建てエレベーターは一分もかからず、118階には透明なガラス床の区画がある。その上に立つと蚕室の車が粒のようだ。晴れた日には北に北漢山、南に冠岳山の稜線まで見える。タワーの足元には四月初めに桜が水辺を囲む石村湖と、世界最大の屋内遊園地がある。","facts":["高さ555m、123階建てで韓国一高い建物。","ソウルスカイ展望台は117〜123階、118階にガラス床がある。","展望台のエレベーターは毎分約600mで上がる。","足元のロッテワールドは世界最大級の屋内遊園地。"],"travelTips":["オンラインの時間指定予約が窓口より安く早い。","日没45分前の回を選べば昼と夜の両方が見られる。","四月初めなら石村湖を一周して桜を見よう。"],"bestTime":"4月（桜）と10〜11月（空が澄む）","visitDuration":"2時間","ticket":"ソウルスカイ31,000ウォン（大人）","openingHours":"10:30〜22:00（金・土・祝は23:00まで）、チケット販売は閉館1時間前まで","galleryCaptions":["ソウルスカイから見たソウル"]},"zh":{"name":"樂天世界塔與Seoul Sky","summary":"韓國最高的建築，將近半公里高處有一片玻璃地板，直直望向蠶室。","story":"樂天世界塔高555公尺，愈往上愈收窄的造型取自韓國毛筆與陶瓷。前往Seoul Sky觀景台的雙層電梯不到一分鐘就到，118樓有一段完全透明的玻璃地板——站上去，蠶室的車流細得像穀粒。天氣好時，視線北抵北漢山、南達冠岳山稜線。塔腳下是石村湖，四月初櫻花繞湖一圈，旁邊還有全世界最大的室內遊樂園。","facts":["高555公尺、共123層，是韓國最高的建築。","Seoul Sky觀景台位於117至123樓，118樓設有玻璃地板。","觀景台電梯速度約每分鐘600公尺。","塔下的樂天世界是全球最大的室內遊樂園。"],"travelTips":["線上預訂指定時段票，比現場購票便宜也快。","挑日落前45分鐘的場次，白天與夜景一次看足。","四月初可繞石村湖走一圈賞櫻。"],"bestTime":"4月（櫻花）與10至11月（天氣清朗）","visitDuration":"2小時","ticket":"Seoul Sky 31,000韓元（成人）","openingHours":"10:30–22:00（週五、週六與假日至23:00），售票至閉館前1小時","galleryCaptions":["從Seoul Sky俯瞰首爾"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('national-museum-korea', 'national-museum-korea', 'seoul', 'Bảo tàng Quốc gia Hàn Quốc', 'National Museum of Korea', 'museum', 126.98, 37.524, 'Bảo tàng lớn nhất nước, nơi hai tượng Phật Bán già tư duy ngồi trong một căn phòng tối chỉ dành riêng cho chúng.', 'Bảo tàng Quốc gia trải dài như một bức tường đá dài ba trăm mét, và khoảng trống lớn ở giữa khung đúng ngọn Namsan cùng tháp N Seoul — một cú dàn cảnh kiến trúc rất cố ý. Bên trong là hành trình từ đồ đá tới cuối Joseon, nhưng thứ khiến người ta quay lại là Phòng Tư duy: hai pho tượng Phật Bán già bằng đồng mạ vàng thế kỷ 6–7, đặt giữa một căn phòng tối thẫm, không tủ kính, không chú thích dài dòng, chỉ có ánh sáng rọi xuống nụ cười nửa miệng. Tháp đá mười tầng Gyeongcheonsa cao vút giữa sảnh chính là hiện vật duy nhất được đặt trong nhà vì quá lớn để ở ngoài trời.', '["Là bảo tàng lớn nhất Hàn Quốc, mở tại địa điểm hiện nay từ năm 2005.","Phòng Tư duy trưng bày hai tượng Phật Bán già bằng đồng mạ vàng, đều là quốc bảo.","Tháp đá Gyeongcheonsa mười tầng cao khoảng 13m, dựng năm 1348.","Vé vào khu trưng bày thường trực miễn phí."]', '["Vào Phòng Tư duy trước tiên, buổi sáng sớm khi phòng còn vắng.","Bảo tàng rất lớn — chọn hai tầng thay vì cố đi hết.","Ga Ichon (tuyến 4 và Jungang) có lối đi ngầm nối thẳng tới bảo tàng."]', 'Quanh năm', '2–3 giờ', 'Miễn phí (khu trưng bày thường trực); triển lãm đặc biệt tính vé riêng', '09:30–17:30, thứ Tư và thứ Bảy đến 21:00; vườn ngoài trời 07:00–22:00', '["verified","hidden-gem"]', '["bảo tàng","quốc bảo","lịch sử"]', '[{"seed":"national-museum-korea","caption":"Phòng Tư duy","ratio":"16/9"}]', '["n-seoul-tower","hangang-yeouido-park"]', 1, 'https://www.museum.go.kr/ENG/contents/E0101010000.do', '2026-08-04', '{"en":{"name":"National Museum of Korea","summary":"The country''s largest museum, where two Pensive Bodhisattvas sit in a dark room kept for them alone.","story":"The National Museum runs like a three-hundred-metre stone wall, and the great opening at its centre frames Namsan and N Seoul Tower exactly — a very deliberate piece of staging. Inside is a walk from the stone age to late Joseon, but what brings people back is the Room of Quiet Contemplation: two gilt-bronze Pensive Bodhisattvas from the 6th and 7th centuries, set in a near-black room with no vitrine and no wall of text, only light falling on a half-smile. The ten-storey Gyeongcheonsa pagoda rising through the main hall is the one exhibit kept indoors because it is too large to stand outside.","facts":["Korea''s largest museum, on its present site since 2005.","The Room of Quiet Contemplation holds two gilt-bronze Pensive Bodhisattvas, both national treasures.","The ten-storey Gyeongcheonsa pagoda is about 13m tall and dates from 1348.","Entry to the permanent galleries is free."],"travelTips":["Go to the Room of Quiet Contemplation first, early, while it is still empty.","The museum is vast — pick two floors rather than trying to see everything.","Ichon station (line 4 and Jungang) has an underground passage straight to the museum."],"bestTime":"Year-round","visitDuration":"2–3 hours","ticket":"Free (permanent galleries); special exhibitions ticketed separately","openingHours":"09:30–17:30, until 21:00 Wed and Sat; outdoor garden 07:00–22:00","galleryCaptions":["The Room of Quiet Contemplation"]},"ko":{"name":"국립중앙박물관","summary":"한국에서 가장 큰 박물관. 두 점의 반가사유상만을 위한 어두운 방이 있다.","story":"국립중앙박물관은 300m에 이르는 돌벽처럼 길게 뻗어 있고, 가운데 큰 열린 공간이 남산과 N서울타워를 정확히 액자에 넣는다. 아주 의도된 연출이다. 안에서는 구석기부터 조선 후기까지 걸어갈 수 있지만, 사람들이 다시 찾는 것은 사유의 방이다. 6~7세기 금동반가사유상 두 점이 거의 검은 방 안에 놓여 있다. 유리장도 없고 긴 설명도 없다. 오직 반쯤 지은 미소 위로 떨어지는 빛뿐이다. 중앙 홀을 관통해 솟은 경천사 십층석탑은 너무 커서 실내에 둘 수밖에 없었던 유일한 유물이다.","facts":["한국 최대의 박물관으로, 현재 자리에는 2005년부터 있다.","사유의 방에는 국보로 지정된 금동반가사유상 두 점이 있다.","경천사 십층석탑은 높이 약 13m로 1348년에 세워졌다.","상설전시관 관람은 무료다."],"travelTips":["이른 아침, 아직 비어 있을 때 사유의 방부터 보자.","규모가 크다. 다 보려 하지 말고 두 개 층만 정하자.","이촌역(4호선·경의중앙선)에서 지하 통로로 바로 연결된다."],"bestTime":"연중","visitDuration":"2~3시간","ticket":"상설전시 무료, 특별전은 별도 유료","openingHours":"09:30~17:30, 수·토요일은 21:00까지(야외 정원 07:00~22:00)","galleryCaptions":["사유의 방"]},"ja":{"name":"国立中央博物館","summary":"韓国最大の博物館。二体の半跏思惟像だけのために設けられた暗い部屋がある。","story":"国立中央博物館は三百メートルに及ぶ石の壁のように長く伸び、中央の大きな開口が南山とNソウルタワーをちょうど額縁に収める。きわめて意図的な演出だ。中では旧石器から朝鮮後期までを歩けるが、人々が再訪する理由は「思惟の部屋」にある。六〜七世紀の金銅半跏思惟像が二体、ほとんど黒い部屋に置かれている。ガラスケースも長い解説もない。半ば浮かべた微笑に落ちる光だけだ。中央ホールを貫いて立つ敬天寺十層石塔は、大きすぎて屋内に置くほかなかった唯一の遺物である。","facts":["韓国最大の博物館で、現在地には2005年から。","思惟の部屋には国宝の金銅半跏思惟像が二体ある。","敬天寺十層石塔は高さ約13m、1348年の造立。","常設展示は無料。"],"travelTips":["朝一番、まだ空いているうちに思惟の部屋から見よう。","規模が大きい。全部を狙わず二つの階に絞ろう。","二村駅（4号線・京義中央線）から地下通路で直結している。"],"bestTime":"通年","visitDuration":"2〜3時間","ticket":"常設展は無料、特別展は別料金","openingHours":"09:30〜17:30、水・土は21:00まで（屋外庭園は07:00〜22:00）","galleryCaptions":["思惟の部屋"]},"zh":{"name":"國立中央博物館","summary":"全國最大的博物館，兩尊半跏思惟像獨佔一間昏暗的展室。","story":"國立中央博物館像一道長達三百公尺的石牆，中央那道巨大開口，恰好把南山與N首爾塔框進畫面——是相當刻意的一手安排。館內可從舊石器一路走到朝鮮後期，但真正讓人一再回訪的是「思惟之室」：兩尊六至七世紀的金銅半跏思惟像，安置在近乎全黑的房間裡，沒有玻璃櫃，也沒有長篇說明，只有一道光落在那抹似笑非笑上。貫穿中央大廳的敬天寺十層石塔，是唯一因為太高大而只能放在室內的展品。","facts":["韓國規模最大的博物館，2005年遷至現址。","思惟之室陳列兩尊金銅半跏思惟像，皆為國寶。","敬天寺十層石塔高約13公尺，建於1348年。","常設展區免費參觀。"],"travelTips":["一早先去思惟之室，那時還沒有人。","館區很大——挑兩層樓好好看，別想全部走完。","二村站（4號線與京義中央線）有地下通道直達。"],"bestTime":"全年","visitDuration":"2至3小時","ticket":"常設展免費，特展另行售票","openingHours":"09:30–17:30，週三與週六至21:00（戶外庭園07:00–22:00）","galleryCaptions":["思惟之室"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bukhansan', 'bukhansan', 'seoul', 'Vườn quốc gia Bukhansan', 'Bukhansan National Park', 'mountain', 126.9878, 37.6588, 'Vườn quốc gia nằm ngay trong địa giới thủ đô — đi tàu điện ngầm bốn mươi phút là tới chân đường mòn đá granite.', 'Rất ít thủ đô có một vườn quốc gia thật sự bên trong ranh giới của mình, và Bukhansan là lý do người Seoul mê leo núi đến vậy. Từ ga tàu điện ngầm, chỉ vài trăm mét là tới cổng vườn, rồi đường mòn dựng đứng dần lên giữa rừng thông và các phiến granite trắng. Đỉnh Baegundae cao 836 mét, đoạn cuối phải bám dây cáp bò lên mặt đá trơ, nhưng phần thưởng là toàn cảnh Seoul trải kín chân trời phía nam. Trên sườn núi vẫn còn tường thành Bukhansanseong thời Joseon chạy dọc sống núi. Cuối tuần, đường mòn đông như phố, ai cũng áo khoác leo núi màu rực và bình kimbap trong ba lô.', '["Đỉnh cao nhất là Baegundae, 836m.","Là vườn quốc gia có mật độ khách tham quan trên mỗi km² cao nhất thế giới.","Thành Bukhansanseong trên núi được xây lại năm 1711 làm nơi lánh nạn cho triều đình.","Có nhiều lối lên; tuyến Bukhansanseong và Dobongsan là phổ biến nhất."]', '["Đi giày leo núi có đế bám — mặt đá granite trơn hơn vẻ ngoài rất nhiều.","Tránh cuối tuần mùa thu nếu bạn ngại đông; sáng sớm thứ Ba dễ chịu nhất.","Mùa đông đường mòn đóng băng, cần đế đinh crampon bán ngay ở cổng vườn."]', 'Tháng 4–6 và tháng 9–11', 'Nửa ngày đến cả ngày', '', 'Vào cổng 04:00–17:00 (tháng 12–2 đến 16:00); tuyến Baegundae có thể đóng khi đủ lượt', '["popular"]', '["leo núi","toàn cảnh","granite","thành cổ"]', '[{"seed":"bukhansan","caption":"Đỉnh Baegundae nhìn về Seoul","ratio":"16/9"}]', '["bukchon-hanok-village"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=87742', '2026-08-04', '{"en":{"name":"Bukhansan National Park","summary":"A national park inside the capital''s own boundary — forty minutes on the subway and you are at the foot of the granite trail.","story":"Very few capitals contain a real national park, and Bukhansan is why Seoulites are so devoted to hiking. From the subway station it is a few hundred metres to the park gate, then the trail steepens through pine forest and white granite slabs. Baegundae summit is 836 metres, and the last stretch means hauling yourself up bare rock on fixed cables — the reward is Seoul filling the entire southern horizon. Along the ridge the Joseon-era Bukhansanseong wall still runs. At weekends the trail is as busy as a street, everyone in bright hiking jackets with a flask of kimbap in the pack.","facts":["The highest peak is Baegundae at 836m.","It has the highest number of visitors per square kilometre of any national park in the world.","Bukhansanseong fortress on the mountain was rebuilt in 1711 as a royal refuge.","There are many routes up; the Bukhansanseong and Dobongsan trails are the most used."],"travelTips":["Wear hiking shoes with real grip — the granite is far more slippery than it looks.","Avoid autumn weekends if you dislike crowds; early Tuesday is the calmest.","In winter the trail ices over; crampons are sold at the park gate."],"bestTime":"April–June and September–November","visitDuration":"Half to a full day","ticket":"","openingHours":"Entry 04:00–17:00 (to 16:00 Dec–Feb); the Baegundae route can close once its daily cap is reached","galleryCaptions":["Baegundae summit looking back at Seoul"]},"ko":{"name":"북한산국립공원","summary":"수도 행정구역 안에 있는 국립공원. 지하철로 사십 분이면 화강암 등산로 입구에 닿는다.","story":"경계 안에 진짜 국립공원을 품은 수도는 흔치 않고, 서울 사람들이 그토록 등산을 좋아하는 이유가 여기 있다. 지하철역에서 몇백 미터면 공원 입구고, 소나무 숲과 흰 화강암 너럭바위 사이로 길이 점점 가팔라진다. 백운대는 836m, 마지막 구간은 맨바위에 걸린 쇠줄을 잡고 올라야 한다. 대가는 남쪽 지평선을 가득 채운 서울이다. 능선을 따라 조선시대 북한산성이 아직 남아 있다. 주말이면 등산로가 거리처럼 붐빈다. 모두 선명한 등산복 차림에 배낭에는 김밥이 들어 있다.","facts":["최고봉은 백운대로 836m다.","면적당 탐방객 수가 세계에서 가장 많은 국립공원이다.","산 위의 북한산성은 1711년 왕실의 피난처로 다시 쌓았다.","오르는 길이 여럿이며 북한산성 코스와 도봉산 코스가 가장 많이 쓰인다."],"travelTips":["접지력 좋은 등산화를 신자. 화강암은 보기보다 훨씬 미끄럽다.","붐비는 게 싫다면 가을 주말은 피하자. 화요일 이른 아침이 가장 한산하다.","겨울에는 길이 얼어붙는다. 아이젠은 공원 입구에서 판다."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절~하루","ticket":"","openingHours":"입산 04:00~17:00(12~2월은 16:00까지), 백운대 코스는 정원이 차면 통제","galleryCaptions":["백운대에서 돌아본 서울"]},"ja":{"name":"北漢山国立公園","summary":"首都の行政区域内にある国立公園。地下鉄で四十分、花崗岩の登山口に着く。","story":"境界の内側に本物の国立公園を持つ首都は多くない。ソウルの人がこれほど登山を好む理由がここにある。駅から数百メートルで公園の入口、そこから松林と白い花崗岩の一枚岩の間を道が次第に急になる。白雲台は836m、最後の区間は剥き出しの岩に張られた鎖を掴んで登る。代償はソウルが南の地平線を埋め尽くす眺めだ。稜線沿いには朝鮮時代の北漢山城が今も残る。週末の登山道は通りのように混み、誰もが鮮やかな山着でリュックにキンパを入れている。","facts":["最高峰は白雲台で836m。","面積あたりの訪問者数が世界一多い国立公園。","山上の北漢山城は1711年、王室の避難所として築き直された。","登山路は複数あり、北漢山城コースと道峰山コースが最も使われる。"],"travelTips":["グリップの効く登山靴を。花崗岩は見た目よりずっと滑る。","混雑が苦手なら秋の週末は避けよう。火曜の早朝が最も静かだ。","冬は道が凍る。アイゼンは公園入口で売っている。"],"bestTime":"4〜6月と9〜11月","visitDuration":"半日〜一日","ticket":"","openingHours":"入山04:00〜17:00（12〜2月は16:00まで）、白雲台コースは定員に達すると規制","galleryCaptions":["白雲台から振り返るソウル"]},"zh":{"name":"北漢山國立公園","summary":"位於首都行政區內的國立公園——搭地鐵四十分鐘，就站在花崗岩步道的起點。","story":"很少有首都在自己的邊界內擁有一座真正的國立公園，而這正是首爾人如此熱衷登山的原因。從地鐵站走幾百公尺就到園區入口，接著步道在松林與白色花崗岩板之間愈爬愈陡。白雲台海拔836公尺，最後一段得抓著固定鋼索在裸岩上往上撐——代價換來的是整個首爾填滿南方地平線。稜線上，朝鮮時代的北漢山城至今仍在。週末的步道熱鬧得像條街，人人一身鮮豔登山外套，背包裡裝著一盒紫菜飯捲。","facts":["最高峰為白雲台，海拔836公尺。","是全世界每平方公里訪客量最高的國立公園。","山上的北漢山城於1711年重建，作為王室避難處。","上山路線多條，以北漢山城與道峰山路線最常走。"],"travelTips":["穿抓地力好的登山鞋——花崗岩比看起來滑得多。","怕人多就避開秋天週末，週二清早最清靜。","冬天步道結冰，園區入口就有賣冰爪。"],"bestTime":"4至6月與9至11月","visitDuration":"半天至一整天","ticket":"","openingHours":"入山04:00–17:00（12至2月至16:00），白雲台路線達人數上限即管制","galleryCaptions":["白雲台回望首爾"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seoul-forest', 'seoul-forest', 'seoul', 'Rừng Seoul (Seoul Forest)', 'Seoul Forest', 'park', 127.0374, 37.5444, 'Trường đua ngựa và nhà máy nước cũ biến thành công viên rộng, có cả đàn hươu sống thả trong khu rừng nhỏ.', 'Trước năm 2005, khu đất này lần lượt là bãi săn của vua Joseon, trường đua ngựa, rồi nhà máy lọc nước. Thành phố gộp tất cả thành một công viên rộng gần một trăm hecta chia làm năm khu: rừng cây, vườn ven sông Hàn, đầm lầy sinh thái, khu thể thao và một vườn hươu nơi đàn hươu sao đi lại tự do sau hàng rào thấp. Các bể lắng của nhà máy nước cũ được giữ nguyên và trồng cây bên trong, thành một khu vườn chìm rất lạ. Cuối tuần dân Seongsu-dong — khu nhà xưởng cũ nay đầy quán cà phê rang xay — kéo sang đây trải bạt, và mùa thu hàng cây ngân hạnh dọc lối chính vàng rực.', '["Mở cửa năm 2005 trên nền trường đua ngựa và nhà máy lọc nước cũ.","Rộng khoảng 116 hecta, chia thành năm khu chức năng.","Có vườn hươu với đàn hươu sao nuôi thả.","Các bể lắng của nhà máy nước cũ được giữ lại làm vườn chìm."]', '["Thuê xe đạp công cộng để đi hết công viên — đi bộ hết cả năm khu khá xa.","Kết hợp với khu cà phê Seongsu-dong ngay bên cạnh.","Cuối tháng 10 là lúc hàng ngân hạnh vàng nhất."]', 'Tháng 4–5 và tháng 10–11', '2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["công viên","hươu","đạp xe","mùa thu"]', '[{"seed":"seoul-forest","caption":"Lối ngân hạnh mùa thu","ratio":"16/9"}]', '["lotte-world-tower","bongeunsa"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Seoul Forest","summary":"A racecourse and waterworks turned into a large park, with a herd of deer living loose in a patch of woodland.","story":"Before 2005 this ground was, in turn, a Joseon royal hunting park, a racecourse, and a water treatment plant. The city folded all of it into a park of nearly a hundred hectares in five parts: woodland, a riverside garden on the Han, an ecological wetland, a sports area, and a deer park where sika deer wander behind a low fence. The old settling tanks of the waterworks were kept and planted, making a strange sunken garden. At weekends the crowd from Seongsu-dong — a district of old workshops now full of coffee roasters — comes over with picnic mats, and in autumn the ginkgo avenue along the main path turns brilliant yellow.","facts":["Opened in 2005 on the site of a former racecourse and water treatment plant.","About 116 hectares, divided into five distinct areas.","There is a deer park with a resident herd of sika deer.","The old settling tanks of the waterworks were kept as a sunken garden."],"travelTips":["Hire a public bike; walking all five areas is a long way.","Combine it with the Seongsu-dong café district next door.","Late October is when the ginkgo avenue is at its brightest."],"bestTime":"April–May and October–November","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["The ginkgo avenue in autumn"]},"ko":{"name":"서울숲","summary":"경마장과 정수장이 넓은 공원이 되었다. 작은 숲에는 사슴 무리가 풀려 산다.","story":"2005년 이전 이 땅은 차례로 조선 왕의 사냥터였고, 경마장이었고, 정수장이었다. 서울시는 그 모두를 100헥타르에 가까운 공원으로 묶었다. 숲, 한강과 이어진 물가 정원, 생태 습지, 운동 구역, 그리고 낮은 울타리 안에서 꽃사슴이 돌아다니는 사슴방사장까지 다섯 구역이다. 옛 정수장의 침전지는 그대로 두고 나무를 심어, 묘한 가라앉은 정원이 되었다. 주말이면 옛 공장 지대에서 커피 로스터리 거리가 된 성수동 사람들이 돗자리를 들고 넘어오고, 가을이면 큰길의 은행나무가 온통 노랗다.","facts":["옛 경마장과 정수장 자리에 2005년 문을 열었다.","면적은 약 116헥타르로 다섯 구역으로 나뉜다.","꽃사슴을 방사해 기르는 사슴방사장이 있다.","옛 정수장의 침전지를 남겨 가라앉은 정원으로 만들었다."],"travelTips":["공공자전거를 빌리자. 다섯 구역을 걸어서 다 보기에는 멀다.","바로 옆 성수동 카페 거리와 묶어서 다니자.","은행나무가 가장 노란 때는 10월 말이다."],"bestTime":"4~5월, 10~11월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["가을의 은행나무길"]},"ja":{"name":"ソウルの森","summary":"競馬場と浄水場が広い公園になった。小さな林には鹿の群れが放し飼いにされている。","story":"2005年以前、この土地は順に朝鮮王の狩場であり、競馬場であり、浄水場だった。市はそのすべてを百ヘクタール近い公園にまとめた。林、漢江につながる水辺の庭、生態湿地、運動区域、そして低い柵の内側でニホンジカが歩き回る鹿放飼場の五区域だ。旧浄水場の沈殿池はそのまま残して木を植え、奇妙な沈んだ庭になった。週末には、古い工場地帯からコーヒー焙煎の街になった聖水洞の人々がレジャーシートを持って渡ってくる。秋には大通りの銀杏が一面に黄色くなる。","facts":["旧競馬場と浄水場の跡地に2005年開園。","面積は約116ヘクタール、五つの区域に分かれる。","ニホンジカを放し飼いにする鹿放飼場がある。","旧浄水場の沈殿池を残して沈んだ庭にした。"],"travelTips":["公共自転車を借りよう。五区域を歩きで回るには遠い。","隣の聖水洞カフェ街と合わせて回ろう。","銀杏が最も黄色いのは10月末。"],"bestTime":"4〜5月と10〜11月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["秋の銀杏並木"]},"zh":{"name":"首爾林","summary":"賽馬場與淨水場變成的大公園，一小片林地裡還養著一群放養的鹿。","story":"2005年之前，這塊地依序當過朝鮮王室獵場、賽馬場，以及淨水場。市府把這些全都收攏成一座近百公頃的公園，分為五區：林地、連著漢江的水邊花園、生態濕地、運動區，以及低矮圍籬內梅花鹿自在走動的鹿苑。舊淨水場的沉澱池被保留下來種上樹木，成了一座奇特的下沉花園。週末，隔壁由舊廠房變身咖啡烘焙街的聖水洞人潮會帶著野餐墊過來；到了秋天，主步道旁的銀杏大道一片金黃。","facts":["2005年在舊賽馬場與淨水場原址開園。","面積約116公頃，分為五個區域。","設有鹿苑，養著一群梅花鹿。","舊淨水場的沉澱池被保留為下沉花園。"],"travelTips":["租一台公共單車——五個區域全用走的相當遠。","可與隔壁的聖水洞咖啡街排在一起。","十月下旬是銀杏大道最金黃的時候。"],"bestTime":"4至5月與10至11月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["秋天的銀杏大道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('incheon-chinatown', 'incheon-chinatown', 'incheon', 'Phố người Hoa Incheon', 'Incheon Chinatown', 'city', 126.6178, 37.4746, 'Khu phố Hoa duy nhất còn nguyên vẹn của Hàn Quốc — và là nơi món jjajangmyeon ra đời.', 'Năm 1883 cảng Incheon mở cửa, thương nhân Sơn Đông kéo sang và dựng nên khu phố này. Những cổng tam quan sơn đỏ, tường bích hoạ kể lại Tam Quốc diễn nghĩa, và mùi hành phi từ các tiệm mì bay dọc con dốc. Chính tại đây, đầu bếp người Hoa đã pha tương đen chunjang với mì Hàn để làm ra jjajangmyeon — món ăn nay phổ biến khắp Hàn Quốc đến mức có hẳn một bảo tàng nhỏ dành riêng cho nó. Đi hết khu phố là tới công viên Jayu nhìn xuống cảng biển Hoàng Hải.', '["Hình thành từ năm 1883 khi cảng Incheon mở cho ngoại thương.","Là nơi khai sinh món jjajangmyeon, có Bảo tàng Jjajangmyeon ngay trong khu phố.","Bích hoạ Tam Quốc diễn nghĩa trải dài hơn 150 mét dọc đường lên dốc.","Cách ga Incheon (tuyến 1 tàu điện Seoul) chỉ vài bước chân."]', '["Đi tàu điện tuyến 1 từ Seoul, khoảng một tiếng, xuống ga cuối Incheon.","Ăn jjajangmyeon trước, để bụng cho bánh gongalppang giòn ăn tráng miệng.","Kết hợp với làng cổ tích Songwol ngay cạnh, tường nhà sơn màu rực rỡ."]', 'Quanh năm', '2–3 giờ', '', 'Khu phố mở cả ngày; nhà hàng thường 11:00–21:00', '["verified"]', '["ẩm thực","lịch sử","cảng biển"]', '[{"seed":"incheon-chinatown","caption":"Cổng tam quan phố người Hoa","ratio":"16/9"}]', '["wolmido","songdo-central-park"]', 1, 'https://www.icjg.go.kr/tour/cttu0102a06', '2026-08-04', '{"en":{"name":"Incheon Chinatown","summary":"Korea''s only intact Chinatown — and the birthplace of jjajangmyeon.","story":"The port of Incheon opened in 1883, Shandong merchants crossed over, and this quarter grew out of it. Red gates span the streets, murals retell the Romance of the Three Kingdoms, and the smell of fried scallion drifts down the hill from the noodle houses. It was here that Chinese cooks mixed black chunjang paste with Korean noodles to make jjajangmyeon — now so common across Korea that it has its own small museum. Walk to the end of the quarter and you reach Jayu Park, looking down on the Yellow Sea harbour.","facts":["Founded in 1883 when Incheon port opened to foreign trade.","Birthplace of jjajangmyeon; the Jjajangmyeon Museum stands in the quarter.","The Three Kingdoms mural runs for more than 150 metres up the hill.","A few minutes'' walk from Incheon station on Seoul Metro Line 1."],"travelTips":["Take Line 1 from Seoul — about an hour to the last stop, Incheon.","Eat jjajangmyeon first, then save room for crisp gongal-ppang bread.","Combine it with the brightly painted Songwol Fairytale Village next door."],"bestTime":"Year-round","visitDuration":"2–3 hours","ticket":"","openingHours":"The quarter is open all day; restaurants generally run 11:00–21:00","galleryCaptions":["The Chinatown gate"]},"ko":{"name":"인천 차이나타운","summary":"한국에 유일하게 온전히 남은 차이나타운이자 짜장면이 태어난 곳.","story":"1883년 인천항이 열리자 산둥의 상인들이 건너와 이 거리를 만들었다. 붉은 패루가 길을 가로지르고, 담벼락에는 삼국지 벽화가 이어지며, 언덕 위 중국집에서 파 볶는 냄새가 흘러내린다. 바로 이곳에서 중국인 요리사들이 검은 춘장에 한국식 면을 비벼 짜장면을 만들었다. 지금은 전국의 음식이 되어 작은 박물관까지 생겼다. 거리를 끝까지 걸으면 황해 앞바다를 내려다보는 자유공원에 닿는다.","facts":["1883년 인천항 개항과 함께 형성되었다.","짜장면의 발상지이며 거리 안에 짜장면박물관이 있다.","삼국지 벽화는 언덕을 따라 150m 넘게 이어진다.","수도권 전철 1호선 인천역에서 도보 몇 분 거리다."],"travelTips":["서울에서 1호선을 타고 종점 인천역까지 약 한 시간이다.","짜장면을 먼저 먹고 바삭한 공갈빵을 후식으로 남겨두자.","바로 옆 송월동 동화마을과 함께 둘러보기 좋다."],"bestTime":"연중","visitDuration":"2~3시간","ticket":"","openingHours":"거리는 상시 개방, 음식점은 대체로 11:00~21:00","galleryCaptions":["차이나타운 패루"]},"ja":{"name":"仁川チャイナタウン","summary":"韓国で唯一そのまま残る中華街。そしてジャージャー麺が生まれた場所。","story":"1883年に仁川港が開かれると山東の商人が渡ってきて、この一角ができた。赤い牌楼が道をまたぎ、壁には三国志の壁画が続き、坂の上の中華料理店からネギを炒める香りが流れてくる。ここで中国人の料理人が黒い春醤を韓国の麺に和え、ジャージャー麺が生まれた。今では全国の味となり、小さな博物館まである。街を抜ければ黄海の港を見下ろす自由公園に出る。","facts":["1883年の仁川開港とともに形成された。","ジャージャー麺発祥の地で、街区内にジャージャー麺博物館がある。","三国志の壁画は坂に沿って150m以上続く。","首都圏電鉄1号線の仁川駅から徒歩数分。"],"travelTips":["ソウルから1号線で終点の仁川駅まで約1時間。","先にジャージャー麺を食べ、締めにサクサクのコンガルパンを。","隣の松月洞童話村と合わせて歩くとよい。"],"bestTime":"通年","visitDuration":"2〜3時間","ticket":"","openingHours":"街は終日開放、飲食店はおおむね11:00〜21:00","galleryCaptions":["チャイナタウンの牌楼"]},"zh":{"name":"仁川中華街","summary":"韓國唯一完整保留的中華街，也是炸醬麵誕生之地。","story":"1883年仁川開港，山東商人渡海而來，建起了這片街區。紅色牌樓橫跨街道，牆上是《三國演義》的壁畫，麵館的蔥香從坡道上飄下來。正是在這裡，中國廚師把黑色春醬拌進韓國麵條，做出了炸醬麵——如今風行全韓，甚至有了一座小型博物館。走到街尾，便是俯瞰黃海港口的自由公園。","facts":["1883年仁川開港通商後形成。","炸醬麵發源地，街區內設有炸醬麵博物館。","《三國演義》壁畫沿坡延伸逾150公尺。","距首都圈電鐵1號線仁川站僅數步之遙。"],"travelTips":["從首爾搭1號線至終點仁川站，約一小時。","先吃炸醬麵，再留點肚子嚐酥脆的空心餅。","可與隔壁色彩繽紛的松月洞童話村一起逛。"],"bestTime":"全年","visitDuration":"2至3小時","ticket":"","openingHours":"街區全日開放；餐廳大致11:00–21:00","galleryCaptions":["中華街牌樓"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('songdo-central-park', 'songdo-central-park', 'incheon', 'Công viên Trung tâm Songdo', 'Songdo Central Park', 'park', 126.645, 37.3925, 'Thành phố lấn biển được thiết kế từ con số không, với kênh nước mặn chảy giữa rừng cao ốc.', 'Songdo được bồi lên từ đáy biển Hoàng Hải — một thành phố quy hoạch toàn bộ trên giấy trước khi có viên gạch đầu tiên. Trục sống của nó là công viên trung tâm với con kênh dẫn nước biển dài hơn một cây số, nơi khách chèo thuyền kayak hay đi thuyền lá giữa những toà nhà kính cao vút. Buổi tối, ánh đèn từ các cao ốc đổ xuống mặt kênh khiến khung cảnh giống một bản dựng đồ hoạ hơn là thành phố thật. Đây là nơi để thấy một khuôn mặt khác của Hàn Quốc: không cung điện, không hanok, chỉ có tương lai được lắp đặt sẵn.', '["Xây trên hơn 600 hecta đất lấn biển.","Kênh trong công viên dùng nước biển, dài khoảng 1,8 km.","Toà Tower Gongyeon (G-Tower) có đài quan sát miễn phí ở tầng 29.","Cách sân bay quốc tế Incheon khoảng 20 phút xe."]', '["Rất hợp làm điểm dừng chân nếu bạn quá cảnh dài ở sân bay Incheon.","Lên đài quan sát G-Tower miễn phí để nhìn toàn cảnh thành phố.","Thuê xe đạp đôi chạy dọc kênh vào chiều muộn."]', 'Tháng 4–6 và 9–11', '2 giờ', '', 'Mở cả ngày', '["new"]', '["đô thị hiện đại","kiến trúc","kênh nước"]', '[{"seed":"songdo-central-park","caption":"Kênh nước giữa các cao ốc Songdo","ratio":"16/9"}]', '["incheon-chinatown"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Songdo Central Park","summary":"A city reclaimed from the sea and designed from scratch, with a saltwater canal running between glass towers.","story":"Songdo was raised from the bed of the Yellow Sea — a city planned in full on paper before a single brick was laid. Its spine is the central park, with a saltwater canal over a kilometre long where visitors kayak or ride flat boats between mirrored towers. At night the light from the high-rises spills onto the water and the scene looks more like a render than a real place. This is where you see another face of Korea: no palaces, no hanok, just a future installed in advance.","facts":["Built on more than 600 hectares of reclaimed land.","The park canal uses seawater and runs about 1.8 km.","G-Tower has a free observation deck on the 29th floor.","About 20 minutes by car from Incheon International Airport."],"travelTips":["A good stop if you have a long layover at Incheon airport.","Go up G-Tower''s free observatory for the whole-city view.","Rent a tandem bike and ride the canal in the late afternoon."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["The canal between Songdo''s towers"]},"ko":{"name":"송도 센트럴파크","summary":"바다를 메워 처음부터 설계한 도시. 유리 빌딩 사이로 바닷물 수로가 흐른다.","story":"송도는 황해 바다를 메워 만든 땅 위에, 벽돌 한 장 놓기 전에 도면부터 완성한 도시다. 그 중심축이 센트럴파크로, 1km가 넘는 해수 수로에서 카누와 나룻배를 탈 수 있다. 밤이 되면 고층 건물의 불빛이 수면에 내려앉아 실제 도시라기보다 렌더링 이미지처럼 보인다. 궁궐도 한옥도 없이, 미리 설치된 미래를 보는 한국의 또 다른 얼굴이다.","facts":["600헥타르가 넘는 매립지 위에 조성되었다.","공원의 수로는 바닷물을 사용하며 길이는 약 1.8km다.","G타워 29층 전망대는 무료로 개방된다.","인천국제공항에서 차로 약 20분 거리다."],"travelTips":["인천공항 경유 시간이 길다면 들르기 좋은 곳이다.","G타워 무료 전망대에서 도시 전경을 보자.","늦은 오후에 2인용 자전거로 수로를 따라 달려보자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["빌딩 사이를 흐르는 송도의 수로"]},"ja":{"name":"松島セントラルパーク","summary":"海を埋め立ててゼロから設計した都市。ガラスの塔の間を海水の運河が流れる。","story":"松島は黄海の海底から立ち上げた土地に、レンガ一つ置く前に図面を完成させた都市だ。その背骨がセントラルパークで、1kmを超える海水の運河をカヌーや小舟で進める。夜になると高層ビルの光が水面に落ち、実在の街というよりレンダリング画像のように見える。宮殿も韓屋もなく、あらかじめ設置された未来を見る、韓国のもう一つの顔だ。","facts":["600ヘクタールを超える埋立地の上に造られた。","公園の運河は海水を用い、長さは約1.8km。","Gタワー29階の展望台は無料で開放されている。","仁川国際空港から車で約20分。"],"travelTips":["仁川空港での乗り継ぎ時間が長いときに立ち寄るとよい。","Gタワーの無料展望台から街全体を眺めよう。","夕方にタンデム自転車で運河沿いを走るのが気持ちいい。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["ビルの間を流れる松島の運河"]},"zh":{"name":"松島中央公園","summary":"填海造出、從零設計的城市，海水運河在玻璃高樓之間流過。","story":"松島是從黃海海床上填出來的土地——在動第一塊磚之前，整座城市已在圖紙上完成。它的脊梁是中央公園，一條逾一公里的海水運河可划獨木舟或乘平底船，穿行在鏡面般的樓群之間。夜裡高樓的燈光灑在水面，畫面更像一張渲染圖而非真實城市。這裡能看到韓國的另一張面孔：沒有宮殿、沒有韓屋，只有預先安裝好的未來。","facts":["建於600多公頃的填海土地之上。","公園運河使用海水，長約1.8公里。","G-Tower 29樓設有免費觀景台。","距仁川國際機場車程約20分鐘。"],"travelTips":["若在仁川機場轉機時間較長，很適合前來。","上G-Tower免費觀景台俯瞰全城。","傍晚租一輛協力車沿運河騎行。"],"bestTime":"4至6月、9至11月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["高樓之間的松島運河"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ganghwa-dolmen', 'ganghwa-dolmen', 'incheon', 'Mộ đá Ganghwa', 'Ganghwa Dolmen Site', 'unesco', 126.43, 37.742, 'Những phiến đá thời tiền sử nằm giữa đồng, có tuổi đời còn hơn cả kim tự tháp Ai Cập cuối cùng.', 'Đảo Ganghwa nằm nơi sông Hàn đổ ra biển, và trên các cánh đồng của nó rải rác hàng trăm ngôi mộ đá dựng cách đây khoảng ba nghìn năm. Ngôi nổi tiếng nhất — Bugeun-ri — có nắp đá nặng chừng 50 tấn đặt trên hai trụ đá, tạo thành hình chiếc bàn khổng lồ giữa bãi cỏ trống. Không hàng rào chật chội, không đám đông: chỉ có gió đồng và cảm giác đứng trước thứ đã ở đó trước mọi vương triều Triều Tiên. Bán đảo Triều Tiên là nơi tập trung mộ đá dày đặc nhất thế giới, và Ganghwa là cửa ngõ để hiểu điều đó.', '["Được UNESCO công nhận Di sản Thế giới năm 2000 cùng Gochang và Hwasun.","Mộ đá Bugeun-ri có nắp đá dài hơn 6 mét, nặng khoảng 50 tấn.","Niên đại ước tính khoảng thế kỷ 10–7 trước Công nguyên.","Bán đảo Triều Tiên có khoảng 40% tổng số mộ đá của toàn thế giới."]', '["Đi xe buýt liên tỉnh từ Seoul tới bến Ganghwa rồi bắt taxi tới bãi mộ đá.","Kết hợp trong ngày với thành cổ Ganghwa và bãi bồi ven biển.","Đồng trống nên gió rất mạnh vào mùa đông, mặc ấm."]', 'Tháng 4–6 và 9–10', '1–2 giờ', '', 'Mở cả ngày', '["unesco","hidden-gem"]', '["UNESCO","khảo cổ","tiền sử"]', '[{"seed":"ganghwa-dolmen","caption":"Mộ đá Bugeun-ri giữa cánh đồng","ratio":"16/9"}]', '["incheon-chinatown"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Ganghwa Dolmen Site","summary":"Prehistoric stones standing in open fields, older than the last of Egypt''s pyramids.","story":"Ganghwa Island sits where the Han River meets the sea, and hundreds of dolmens raised some three thousand years ago are scattered across its fields. The most famous — Bugeun-ri — carries a capstone of roughly 50 tonnes on two uprights, forming a giant table on empty grass. No crowds, no cramped railings: just wind off the fields and the feeling of standing in front of something that was here before every Korean dynasty. The peninsula holds the densest concentration of dolmens on earth, and Ganghwa is the doorway to understanding that.","facts":["Inscribed by UNESCO in 2000 together with Gochang and Hwasun.","The Bugeun-ri dolmen''s capstone is over 6m long and weighs about 50 tonnes.","Dated to roughly the 10th–7th centuries BCE.","The Korean peninsula holds around 40% of all dolmens in the world."],"travelTips":["Take an intercity bus from Seoul to Ganghwa terminal, then a taxi to the site.","Combine it with Ganghwa''s old fortress and the coastal mudflats in a day.","The open fields are windy in winter — dress warmly."],"bestTime":"April–June and September–October","visitDuration":"1–2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["The Bugeun-ri dolmen in its field"]},"ko":{"name":"강화 고인돌 유적","summary":"들판에 놓인 선사시대의 돌. 이집트 마지막 피라미드보다 오래되었다.","story":"강화도는 한강이 바다와 만나는 자리에 있고, 그 들판에는 약 3천 년 전에 세운 고인돌 수백 기가 흩어져 있다. 가장 유명한 부근리 고인돌은 50톤에 이르는 덮개돌을 두 개의 굄돌이 받쳐 들판 위 거대한 탁자를 이룬다. 좁은 울타리도 인파도 없이, 들바람과 함께 모든 왕조 이전부터 여기 있던 것 앞에 서게 된다. 한반도는 세계에서 고인돌이 가장 조밀하게 남은 곳이고, 강화는 그것을 이해하는 입구다.","facts":["2000년 고창·화순과 함께 유네스코 세계유산에 등재되었다.","부근리 고인돌의 덮개돌은 길이 6m가 넘고 무게는 약 50톤이다.","축조 시기는 기원전 10~7세기로 추정된다.","한반도에는 전 세계 고인돌의 약 40%가 분포한다."],"travelTips":["서울에서 강화터미널까지 시외버스, 이후 택시로 이동하면 편하다.","강화산성, 갯벌과 묶어 당일치기로 돌아보자.","겨울에는 들판 바람이 매우 세니 따뜻하게 입자."],"bestTime":"4~6월, 9~10월","visitDuration":"1~2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["들판의 부근리 고인돌"]},"ja":{"name":"江華支石墓群","summary":"野に置かれた先史時代の石。エジプト最後のピラミッドより古い。","story":"江華島は漢江が海と出会う場所にあり、その野には約三千年前に据えられた支石墓が数百基散らばる。最も名高い富近里の支石墓は、50トンほどの蓋石を二つの支石が支え、草地の上に巨大な卓を成す。窮屈な柵も人混みもなく、ただ野の風と、すべての王朝より前からここにあったものの前に立つ感覚がある。朝鮮半島は世界で最も支石墓が密集する地であり、江華はそれを理解する入口だ。","facts":["2000年に高敞・和順とともにユネスコ世界遺産に登録された。","富近里支石墓の蓋石は長さ6m超、重さ約50トン。","築造は紀元前10〜7世紀と推定される。","朝鮮半島には世界の支石墓の約40%が分布する。"],"travelTips":["ソウルから江華ターミナルまで市外バス、そこからタクシーが便利。","江華山城や干潟と合わせて日帰りで回れる。","冬は野の風が強い。暖かい服装で。"],"bestTime":"4〜6月、9〜10月","visitDuration":"1〜2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["野に立つ富近里の支石墓"]},"zh":{"name":"江華支石墓遺址","summary":"立在田野上的史前巨石，比埃及最後的金字塔還要古老。","story":"江華島位於漢江入海之處，島上的田野散布著數百座約三千年前立起的支石墓。最著名的富近里支石墓，以兩塊立石承托約五十噸的蓋石，在空曠草地上形成一張巨大的石桌。這裡沒有擁擠的圍欄與人潮，只有田野的風，以及站在早於所有朝鮮王朝之物面前的感受。朝鮮半島是全球支石墓分布最密集的地方，而江華正是理解它的入口。","facts":["2000年與高敞、和順一同列入世界遺產。","富近里支石墓的蓋石長逾6公尺，重約50噸。","年代約為公元前10至7世紀。","朝鮮半島擁有全球約四成的支石墓。"],"travelTips":["自首爾搭市外巴士至江華轉運站，再轉計程車前往。","可與江華山城、海邊灘塗安排成一日行程。","冬季田野風大，請注意保暖。"],"bestTime":"4至6月、9至10月","visitDuration":"1至2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["田野中的富近里支石墓"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('wolmido', 'wolmido', 'incheon', 'Đảo Wolmido', 'Wolmido Island', 'island', 126.5975, 37.472, 'Hòn đảo nối liền đất liền với con đường ven biển đầy quán hải sản và tiếng nhạc hội chợ.', 'Wolmido từng là đảo thật, nay nối với Incheon bằng đường bộ, và giữ nguyên vẻ ồn ào vui vẻ của một khu vui chơi ven biển thập niên 80. Con đường ven bờ chật kín quán ăn hải sản với bể cá còn quẫy, xen giữa là những trò chơi cảm giác mạnh cũ kỹ nhưng vẫn chạy tốt. Chiều xuống, mặt trời lặn thẳng xuống biển Hoàng Hải phía sau các con tàu container đang chờ vào cảng — một hoàng hôn rất công nghiệp mà rất đẹp. Từ bến tàu ở đây có phà đi các đảo nhỏ ngoài khơi.', '["Là nơi diễn ra cuộc đổ bộ Incheon năm 1950 trong Chiến tranh Triều Tiên.","Con đường ven biển Wolmi dài khoảng 1 km, kín quán hải sản.","Có phà nối ra các đảo Yeongjong và Muui.","Tàu điện một ray Wolmi Sea Train chạy vòng quanh đảo."]', '["Đi bus 45 từ ga Incheon, khoảng 15 phút.","Hải sản tính theo cân — hỏi giá trước khi gọi.","Hoàng hôn là thời điểm đẹp nhất để đi tàu Sea Train."]', 'Tháng 5–10', '2–3 giờ', '', 'Cả ngày', '[]', '["biển","hải sản","hoàng hôn"]', '[{"seed":"wolmido","caption":"Đường ven biển Wolmido","ratio":"16/9"}]', '["incheon-chinatown"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Wolmido Island","summary":"An island joined to the mainland by a seafront strip of seafood restaurants and fairground music.","story":"Wolmido was once a real island; now a causeway joins it to Incheon, and it keeps the cheerful noise of an eighties seaside resort. The shore road is lined with seafood restaurants whose tanks still twitch, interspersed with fairground rides that are old but still running. At dusk the sun drops straight into the Yellow Sea behind container ships waiting for port — an industrial sunset, and a beautiful one. Ferries leave from the pier here for the smaller islands offshore.","facts":["Site of the 1950 Incheon Landing during the Korean War.","The Wolmi seafront promenade runs about 1 km, packed with seafood places.","Ferries connect to Yeongjong and Muui islands.","The Wolmi Sea Train monorail loops around the island."],"travelTips":["Bus 45 from Incheon station takes about 15 minutes.","Seafood is sold by weight — agree on the price before ordering.","Sunset is the best time to ride the Sea Train."],"bestTime":"May–October","visitDuration":"2–3 hours","ticket":"","openingHours":"All day","galleryCaptions":["The Wolmido seafront"]},"ko":{"name":"월미도","summary":"해산물집과 놀이기구 음악이 이어지는 바닷가 길로 육지와 이어진 섬.","story":"월미도는 본래 섬이었지만 지금은 길로 인천과 이어져 있고, 1980년대 해변 유원지의 흥겨운 분위기를 그대로 간직하고 있다. 바닷가 길에는 수조가 출렁이는 해산물집이 늘어서 있고 사이사이 오래됐지만 여전히 잘 도는 놀이기구가 있다. 해질녘에는 입항을 기다리는 컨테이너선 뒤로 해가 황해 속으로 곧장 떨어진다. 아주 산업적이면서도 아름다운 노을이다. 이곳 선착장에서는 앞바다의 섬들로 가는 배가 뜬다.","facts":["1950년 인천상륙작전이 이뤄진 곳이다.","월미 바다열차와 함께 1km 남짓한 해안 산책로가 이어진다.","영종도, 무의도로 가는 여객선이 오간다.","월미 바다열차가 섬을 한 바퀴 돈다."],"travelTips":["인천역에서 45번 버스로 15분이면 닿는다.","해산물은 무게로 계산하니 주문 전에 가격을 확인하자.","바다열차는 해질녘에 타는 것이 가장 좋다."],"bestTime":"5~10월","visitDuration":"2~3시간","ticket":"","openingHours":"상시","galleryCaptions":["월미도 해안 산책로"]},"ja":{"name":"月尾島","summary":"海鮮食堂と遊園地の音楽が続く海辺の道で陸とつながった島。","story":"月尾島はもともと島だったが今は道路で仁川とつながり、1980年代の海辺の遊園地の陽気さをそのまま残している。海沿いの道には水槽が揺れる海鮮食堂が並び、その合間に古びてはいるがきちんと動く遊具がある。夕暮れには、入港を待つコンテナ船の向こうに太陽が黄海へまっすぐ落ちていく。とても工業的で、とても美しい夕景だ。ここの桟橋からは沖の島々へ船が出る。","facts":["1950年の仁川上陸作戦の舞台となった。","月尾海岸の遊歩道は約1kmにわたり海鮮食堂が並ぶ。","永宗島や舞衣島へのフェリーが発着する。","月尾海列車が島を一周する。"],"travelTips":["仁川駅から45番バスで15分ほど。","海鮮は重さで精算するので注文前に値段を確認しよう。","海列車は夕暮れ時に乗るのが一番いい。"],"bestTime":"5〜10月","visitDuration":"2〜3時間","ticket":"","openingHours":"終日","galleryCaptions":["月尾島の海岸遊歩道"]},"zh":{"name":"月尾島","summary":"以海濱路與陸地相連的島，滿是海鮮餐廳與遊樂園的音樂。","story":"月尾島原本是座島，如今以陸路與仁川相連，仍保有八〇年代海濱樂園那種喧鬧的歡快。海邊道路上排滿水槽仍在晃動的海鮮餐廳，其間夾著老舊卻依然運轉的遊樂設施。黃昏時分，太陽在等待入港的貨櫃船後方直直落入黃海——很工業，也很美。這裡的碼頭有船前往外海的小島。","facts":["1950年仁川登陸戰役發生地。","月尾海濱步道約長1公里，海鮮店林立。","有渡輪通往永宗島與舞衣島。","月尾海列車環島行駛。"],"travelTips":["自仁川站搭45號巴士約15分鐘。","海鮮按重量計價，點餐前先問清楚價格。","黃昏是搭乘海列車的最佳時刻。"],"bestTime":"5至10月","visitDuration":"2至3小時","ticket":"","openingHours":"全日","galleryCaptions":["月尾島海濱步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeondeungsa', 'jeondeungsa', 'incheon', 'Chùa Jeondeungsa (Ganghwa)', 'Jeondeungsa Temple, Ganghwa', 'temple', 126.485, 37.6465, 'Ngôi chùa nằm gọn trong lòng một toà thành đất, có bốn tượng khoả thân đỡ mái hiên vì một mối hận cũ.', 'Jeondeungsa là ngôi chùa hiếm hoi nằm bên trong tường thành — thành Samnangseong trên đảo Ganghwa, tương truyền do ba người con của Dangun đắp. Bạn đi qua cổng thành rồi mới tới cổng chùa, cả hai đều lẫn vào rừng. Điều khiến khách dừng lại lâu nhất là bốn góc mái điện Daeungjeon: mỗi góc có một tượng người đàn bà khoả thân quỳ đỡ, và câu chuyện truyền lại là người thợ mộc bị người tình ôm tiền bỏ trốn đã tạc bà ta vào đó để đời đời gánh mái chùa. Ganghwa từng là nơi triều đình lánh quân Mông Cổ suốt ba mươi năm, nên cả hòn đảo đầy thành luỹ và pháo đài nhìn ra cửa sông.', '["Tương truyền dựng năm 381, là một trong những ngôi chùa lâu đời nhất Hàn Quốc.","Nằm trong lòng thành đất Samnangseong trên đảo Ganghwa.","Bốn góc mái điện Daeungjeon có tượng người đỡ mái, gắn với truyền thuyết về người thợ mộc.","Chùa từng lưu giữ bản khắc Đại tạng kinh trước khi chuyển về Haeinsa."]', '["Vé vào tính cho cả khu thành Samnangseong, đi bộ vòng tường thành mất thêm một giờ.","Từ Seoul đi bus tới Ganghwa mất khoảng 1,5 giờ.","Kết hợp với khu mộ đá dolmen Ganghwa trong cùng ngày."]', 'Tháng 4–6 và 9–11', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["hidden-gem"]', '["chùa","thành cổ","Ganghwa","truyền thuyết"]', '[{"seed":"jeondeungsa","caption":"Điện Daeungjeon và tượng đỡ mái","ratio":"16/9"}]', '["ganghwa-dolmen","ganghwa-peace-observatory"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Jeondeungsa Temple, Ganghwa","summary":"A temple that sits inside an earthen fortress, with four naked figures holding up the eaves because of an old grudge.","story":"Jeondeungsa is a rare temple built inside city walls — Samnangseong on Ganghwa Island, said to have been raised by the three sons of Dangun. You pass through the fortress gate before you reach the temple gate, both lost in forest. What stops visitors longest are the four corners of the Daeungjeon roof: each carries a kneeling naked woman bearing the weight, and the story goes that the carpenter, whose lover ran off with his money, carved her there to hold up the roof for eternity. Ganghwa is where the court sheltered from the Mongols for thirty years, so the whole island is scattered with walls and forts facing the estuary.","facts":["Traditionally dated to 381, making it one of Korea''s oldest temples.","It stands inside the earthen fortress of Samnangseong on Ganghwa Island.","The four roof corners of Daeungjeon carry figures bearing the eaves, tied to the carpenter''s legend.","The temple once held Tripitaka woodblocks before they moved to Haeinsa."],"travelTips":["The ticket covers the Samnangseong fortress; walking the wall adds another hour.","The bus from Seoul to Ganghwa takes about 1.5 hours.","Pair it with the Ganghwa dolmen site on the same day."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["Daeungjeon hall and the eave-bearing figures"]},"ko":{"name":"전등사(강화)","summary":"토성 안에 들어앉은 절. 처마를 떠받친 네 개의 나부상에는 오래된 원한이 얽혀 있다.","story":"전등사는 성곽 안에 자리한 드문 절이다. 단군의 세 아들이 쌓았다고 전하는 강화도 삼랑성 안에 있다. 성문을 지나야 절 문이 나오고, 둘 다 숲에 묻혀 있다. 사람들이 가장 오래 멈춰 서는 곳은 대웅전 처마의 네 귀퉁이다. 각 귀퉁이마다 벌거벗은 여인이 무릎을 꿇고 지붕을 떠받치고 있는데, 돈을 갖고 달아난 정인을 목수가 새겨 넣어 영원히 지붕을 이게 했다는 이야기가 전한다. 강화는 고려 조정이 삼십 년간 몽골을 피해 머문 곳이라, 섬 전체에 성과 강화만을 바라보는 돈대가 흩어져 있다.","facts":["381년 창건으로 전해지는, 한국에서 가장 오래된 절 가운데 하나다.","강화도 삼랑성 토성 안에 자리한다.","대웅전 네 귀퉁이의 나부상에는 목수의 전설이 얽혀 있다.","대장경 경판을 해인사로 옮기기 전 한때 이곳에 보관했다고 전한다."],"travelTips":["입장권에 삼랑성이 포함된다. 성곽을 한 바퀴 걸으면 한 시간이 더 든다.","서울에서 강화까지 버스로 1시간 30분쯤 걸린다.","같은 날 강화 고인돌 유적과 묶어서 보자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["대웅전과 처마를 떠받친 나부상"]},"ja":{"name":"伝燈寺（江華）","summary":"土城の中に収まった寺。軒を支える四体の裸像には、古い恨みの話が絡んでいる。","story":"伝燈寺は城壁の内側にある珍しい寺だ。檀君の三人の息子が築いたと伝わる江華島の三郎城の中にある。城門をくぐってから寺の門が現れ、どちらも森に沈んでいる。人が最も長く足を止めるのは大雄殿の軒の四隅だ。それぞれに裸の女がひざまずいて屋根を支えており、金を持って逃げた恋人を大工が彫り込み、永遠に屋根を担がせたのだという話が伝わる。江華は高麗の朝廷が三十年ものあいだモンゴルを避けて過ごした島で、全島に城と河口を望む墩台が散らばっている。","facts":["381年創建と伝わる、韓国最古級の寺のひとつ。","江華島の三郎城という土城の中にある。","大雄殿の四隅の裸像には大工の伝説が結びついている。","大蔵経の版木を海印寺へ移す前、一時ここに納めていたと伝わる。"],"travelTips":["入場券に三郎城が含まれる。城壁を一周すると一時間ほど増える。","ソウルから江華までバスで1時間30分ほど。","同じ日に江華の支石墓遺跡とまとめて回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["大雄殿と軒を支える裸像"]},"zh":{"name":"傳燈寺（江華）","summary":"坐落在土城之內的寺院，四尊撐著屋簷的裸身像，背後是一段舊日的怨懟。","story":"傳燈寺是少見的、蓋在城牆內側的寺院——江華島的三郎城，相傳為檀君三子所築。你得先穿過城門才會遇到寺門，兩者都隱沒在林子裡。最讓人駐足的是大雄殿屋簷的四個轉角：每一角都有一名裸身女子跪著撐住屋頂。相傳木匠的情人捲款而逃，他便把她刻在那裡，讓她永世扛著寺頂。江華曾是高麗朝廷避蒙古三十年之地，全島散布著城牆與面向江口的墩台。","facts":["相傳建於381年，是韓國最古老的寺院之一。","位於江華島三郎城這座土城之內。","大雄殿四角的撐簷人像，與木匠的傳說相連。","相傳大藏經版木移往海印寺之前曾暫存於此。"],"travelTips":["門票含三郎城，繞城牆走一圈得再加一小時。","自首爾搭巴士到江華約需一個半小時。","可與江華支石墓遺址安排在同一天。"],"bestTime":"4至6月與9至11月","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["大雄殿與撐簷的人像"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ganghwa-peace-observatory', 'ganghwa-peace-observatory', 'incheon', 'Đài quan sát Hoà bình Ganghwa', 'Ganghwa Peace Observatory', 'museum', 126.529, 37.828, 'Đứng cách bờ Bắc Triều Tiên khoảng hai cây số, nhìn qua ống nhòm thấy người dân đang làm đồng.', 'Từ đài quan sát ở cực bắc đảo Ganghwa, dòng sông Hàn mở ra thành cửa biển, và bờ bên kia là huyện Kaepung của Bắc Triều Tiên — gần đến mức ống nhòm bàn cho thấy rõ nhà cửa, cột điện và người đang đi lại giữa ruộng. Không có hàng rào thép gai giữa hai bên, chỉ có nước. Tầng dưới là phòng trưng bày về đời sống miền Bắc và những gia đình ly tán; ngoài sân có bàn thờ hướng bắc để người cao tuổi cúng tổ tiên ở quê nhà mà họ chưa từng được về. Đây là nơi khiến sự chia cắt trở nên cụ thể theo cách không bảo tàng nào ở Seoul làm được.', '["Khoảng cách tới bờ Bắc Triều Tiên chỉ chừng 1,8–2,3 km qua cửa sông.","Mở cửa cho khách từ năm 2008.","Có ống nhòm cố định nhìn sang huyện Kaepung.","Trong sân có bàn thờ Manghyangdan cho người gốc miền Bắc cúng tổ tiên."]', '["Cần mang hộ chiếu hoặc giấy tờ tuỳ thân để qua chốt kiểm soát quân sự.","Ngày trời trong tầm nhìn rõ nhất; sương mù mùa hè che gần hết bờ bên kia.","Không có phương tiện công cộng thuận tiện — nên thuê xe hoặc đi tour."]', 'Tháng 10–3 (trời trong, ít sương)', '1,5 giờ', '2.500 KRW (thiếu niên và quân nhân 1.700, trẻ em 1.000); ống nhòm 500 KRW mỗi lượt 2 phút', '09:00–18:00, đóng cửa thứ Hai', '["hidden-gem","verified"]', '["biên giới","lịch sử","chia cắt"]', '[{"seed":"ganghwa-peace-observatory","caption":"Bờ Bắc Triều Tiên nhìn qua cửa sông","ratio":"16/9"}]', '["jeondeungsa","ganghwa-dolmen"]', 0, 'https://www.ganghwa.go.kr/open_content/tour/guide/entrance.jsp', '2026-08-04', '{"en":{"name":"Ganghwa Peace Observatory","summary":"Standing about two kilometres from the North Korean shore, close enough to watch people working the fields.","story":"From the observatory at the northern tip of Ganghwa the Han opens into an estuary, and the far bank is Kaepung county in North Korea — near enough that the mounted binoculars show houses, power poles and people moving between fields. There is no barbed wire between the two, only water. Downstairs, an exhibition covers life in the North and the families separated by the border; outside stands an altar facing north, where elderly visitors make offerings to ancestors in a home village they have never been allowed to return to. Nowhere in Seoul makes the division this concrete.","facts":["The North Korean shore lies roughly 1.8–2.3km away across the estuary.","The observatory opened to visitors in 2008.","Fixed binoculars look across to Kaepung county.","The Manghyangdan altar in the yard is used by people of northern origin to honour their ancestors."],"travelTips":["Bring a passport or ID — there is a military checkpoint on the way.","Clear days give the best view; summer haze hides the far bank almost entirely.","Public transport is poor; drive or take a tour."],"bestTime":"October–March (clear, haze-free days)","visitDuration":"1.5 hours","ticket":"2,500 KRW (1,700 teens and soldiers, 1,000 children); the telescopes cost 500 KRW for two minutes","openingHours":"09:00–18:00, closed Mondays","galleryCaptions":["The North Korean shore across the estuary"]},"ko":{"name":"강화평화전망대","summary":"북한 땅에서 2km 남짓. 망원경으로 들여다보면 논밭에서 일하는 사람이 보인다.","story":"강화도 북쪽 끝 전망대에 서면 한강이 하구로 벌어지고, 건너편은 북한 개풍군이다. 설치된 망원경으로 집과 전봇대, 밭 사이를 오가는 사람까지 보일 만큼 가깝다. 둘 사이에 철조망은 없다. 물뿐이다. 아래층에는 북한의 생활과 이산가족에 관한 전시가 있고, 마당에는 북쪽을 향한 제단이 서 있다. 한 번도 돌아가지 못한 고향의 조상에게 실향민들이 차례를 올리는 곳이다. 서울의 어떤 박물관도 분단을 이렇게 구체적으로 보여 주지는 못한다.","facts":["하구 건너 북한 땅까지 거리는 대략 1.8~2.3km다.","2008년부터 일반에 개방되었다.","개풍군을 바라보는 고정 망원경이 설치되어 있다.","마당의 망향단에서 실향민들이 제를 올린다."],"travelTips":["가는 길에 군 검문소가 있으니 신분증을 꼭 챙기자.","맑은 날이 가장 잘 보인다. 여름 안개가 끼면 건너편이 거의 가려진다.","대중교통이 불편하다. 차를 빌리거나 투어를 이용하자."],"bestTime":"10~3월(맑고 안개가 적은 시기)","visitDuration":"1.5시간","ticket":"2,500원(청소년·군인 1,700원, 어린이 1,000원), 망원경은 2분에 500원","openingHours":"09:00~18:00, 월요일 휴관","galleryCaptions":["하구 건너로 보이는 북한 땅"]},"ja":{"name":"江華平和展望台","summary":"北朝鮮の岸から2kmあまり。望遠鏡を覗くと畑で働く人の姿が見える。","story":"江華島北端の展望台に立つと漢江が河口へ広がり、対岸は北朝鮮の開豊郡だ。据え付けの望遠鏡では家や電柱、畑を行き交う人まで見えるほど近い。両者のあいだに鉄条網はない。あるのは水だけだ。階下には北朝鮮の暮らしと離散家族についての展示があり、庭には北を向いた祭壇が立つ。一度も帰ることの叶わなかった故郷の先祖に、離散者たちが供え物をする場所である。ソウルのどの博物館も、分断をこれほど具体的には見せられない。","facts":["河口を挟んだ北朝鮮の岸までおよそ1.8〜2.3km。","2008年から一般公開されている。","開豊郡を望む固定望遠鏡が設置されている。","庭の望郷壇では、北出身の人々が祖先を祀る。"],"travelTips":["途中に軍の検問所がある。身分証を必ず持参しよう。","晴れた日が最もよく見える。夏の靄がかかると対岸はほとんど隠れる。","公共交通が不便なので、車かツアーを利用しよう。"],"bestTime":"10〜3月（晴れて靄の少ない時期）","visitDuration":"1.5時間","ticket":"2,500ウォン（青少年・軍人1,700、子ども1,000）、望遠鏡は2分500ウォン","openingHours":"09:00〜18:00、月曜休み","galleryCaptions":["河口の向こうに見える北朝鮮の岸"]},"zh":{"name":"江華和平展望台","summary":"距北韓岸邊約兩公里，望遠鏡裡看得見田間走動的人。","story":"站在江華島最北端的展望台上，漢江在此展開成河口，對岸就是北韓開豐郡——近到台上的望遠鏡能看清房舍、電線桿，以及在田間走動的人。兩邊之間沒有鐵絲網，只有水。樓下的展示介紹北韓生活與離散家庭；院子裡立著一座朝北的祭壇，讓年長的訪客向從未獲准返回的故鄉祖先祭拜。首爾沒有任何一座博物館，能把分斷說得這麼具體。","facts":["隔著河口，北韓岸邊大約在1.8至2.3公里外。","展望台於2008年對外開放。","設有固定望遠鏡可眺望開豐郡。","院中的望鄉壇供北方出身者祭祀祖先。"],"travelTips":["沿途設有軍事檢查哨，請攜帶護照或身分證件。","天氣晴朗時視野最佳，夏季霧氣幾乎會遮住對岸。","大眾運輸不便，建議自駕或參加行程。"],"bestTime":"10月至隔年3月（晴朗少霧）","visitDuration":"1.5小時","ticket":"2,500韓元（青少年與軍人1,700、兒童1,000）；望遠鏡每次兩分鐘500韓元","openingHours":"09:00–18:00，週一休館","galleryCaptions":["隔著河口望見的北韓岸邊"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('muuido', 'muuido', 'incheon', 'Đảo Muui & bãi Hanagae', 'Muui Island & Hanagae Beach', 'island', 126.4283, 37.3872, 'Hòn đảo ngay cạnh sân bay Incheon, có bãi triều rút xa hàng trăm mét và những căn chòi gỗ dựng trên cát.', 'Muui-do nằm sát sân bay quốc tế Incheon đến mức máy bay hạ cánh bay ngang đầu, nhưng chỉ cần qua cầu là nhịp sống đổi hẳn. Bãi Hanagae có biên độ triều rất lớn: lúc nước rút, bãi bùn lộ ra xa hàng trăm mét và người ta xách xô đi bắt ngao, sò; lúc nước lên, biển trở lại tận chân những căn chòi gỗ dựng ngay trên cát cho khách thuê qua đêm. Phía sau bãi là đường mòn lên đỉnh Horyonggoksan nhìn ra cả quần đảo. Vì có cầu nối từ năm 2019, giờ tự lái xe ra đảo được, không cần chờ phà.', '["Đảo nối với đất liền bằng cầu Muuido từ năm 2019, không cần đi phà.","Bãi Hanagae có biên độ triều lớn, khi rút để lộ bãi bùn rộng hàng trăm mét.","Các chòi gỗ trên bãi cho thuê qua đêm là đặc trưng của Hanagae.","Cách nhà ga sân bay Incheon khoảng 30 phút xe."]', '["Tra lịch thuỷ triều trước — bãi tắm chỉ đẹp khi nước lên.","Mang ủng và xô nếu muốn bắt ngao lúc nước rút.","Rất hợp làm điểm dừng nếu bạn có chặng transit dài ở Incheon."]', 'Tháng 5–9', 'Nửa ngày', 'Đường ván ven biển miễn phí, mở quanh năm; rừng nghỉ dưỡng 1.000 KRW, bãi Hanagae thu riêng', 'Cả ngày', '["hidden-gem"]', '["đảo","bãi triều","bắt ngao","gần sân bay"]', '[{"seed":"muuido","caption":"Chòi gỗ trên bãi Hanagae","ratio":"16/9"}]', '["songdo-central-park"]', 0, 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=27d21711-6814-4775-b2ac-3e458cf341f6', '2026-08-04', '{"en":{"name":"Muui Island & Hanagae Beach","summary":"An island right beside Incheon airport, where the tide retreats hundreds of metres and wooden huts stand on the sand.","story":"Muui-do is so close to Incheon International that landing aircraft pass overhead, yet cross the bridge and the pace changes completely. Hanagae beach has an enormous tidal range: at low water the mudflat is exposed for hundreds of metres and people head out with buckets for clams and cockles; at high water the sea returns to the foot of the wooden huts built on the sand and rented out for the night. Behind the beach a trail climbs Horyonggoksan for a view over the whole archipelago. Since the bridge opened in 2019 you can simply drive across — no waiting for a ferry.","facts":["Linked to the mainland by the Muuido bridge since 2019; no ferry needed.","Hanagae beach has a large tidal range, exposing hundreds of metres of mudflat.","The wooden huts on the sand, rented overnight, are Hanagae''s signature.","About 30 minutes by car from Incheon airport terminal."],"travelTips":["Check the tide table — the beach is only good at high water.","Bring boots and a bucket if you want to dig for clams at low tide.","It makes an excellent stop if you have a long layover at Incheon."],"bestTime":"May–September","visitDuration":"Half a day","ticket":"The coastal boardwalk is free and open year-round; the forest park is 1,000 KRW and Hanagae beach charges separately","openingHours":"All day","galleryCaptions":["Wooden huts on Hanagae beach"]},"ko":{"name":"무의도와 하나개해변","summary":"인천공항 바로 옆 섬. 물이 수백 미터 빠지고, 모래 위에는 나무 원두막이 서 있다.","story":"무의도는 인천국제공항과 아주 가까워 착륙하는 비행기가 머리 위를 지나가지만, 다리를 건너면 속도가 완전히 달라진다. 하나개해변은 조수 간만의 차가 크다. 물이 빠지면 갯벌이 수백 미터까지 드러나 사람들이 양동이를 들고 조개를 캐러 나가고, 물이 들면 바다가 모래 위에 세운 나무 원두막 발치까지 돌아온다. 원두막은 하룻밤 빌릴 수 있다. 해변 뒤로는 호룡곡산 등산로가 이어져 섬 일대를 내려다본다. 2019년 다리가 놓인 뒤로는 배를 기다릴 필요 없이 차로 건널 수 있다.","facts":["2019년 무의대교가 놓여 배 없이 차로 들어갈 수 있다.","하나개해변은 간만의 차가 커서 수백 미터의 갯벌이 드러난다.","모래 위의 나무 원두막을 하룻밤 빌리는 것이 하나개의 상징이다.","인천공항 터미널에서 차로 30분쯤 걸린다."],"travelTips":["물때표를 확인하자. 해수욕은 밀물 때만 좋다.","썰물에 조개를 캐려면 장화와 양동이를 챙기자.","인천공항 경유 시간이 길 때 들르기 좋다."],"bestTime":"5~9월","visitDuration":"반나절","ticket":"해상관광탐방로는 무료·연중 개방, 자연휴양림은 1,000원, 하나개해수욕장은 별도 요금","openingHours":"상시","galleryCaptions":["하나개해변의 나무 원두막"]},"ja":{"name":"舞衣島とハナゲ海水浴場","summary":"仁川空港のすぐ隣の島。潮が数百メートル引き、砂の上には木の小屋が建つ。","story":"舞衣島は仁川国際空港にごく近く、着陸する飛行機が頭上を通るが、橋を渡ると速度がまるで変わる。ハナゲ海水浴場は干満の差が大きい。潮が引けば干潟が数百メートル現れ、人々はバケツを持って貝を掘りに出る。潮が満ちれば海は砂の上に建てられた木の小屋の足元まで戻ってくる。小屋は一晩借りられる。浜の背後には虎龍谷山の登山道が続き、島々を見渡せる。2019年に橋が架かってからは、船を待たずに車で渡れる。","facts":["2019年に舞衣大橋が架かり、船なしで車で渡れる。","ハナゲ海水浴場は干満差が大きく、数百メートルの干潟が現れる。","砂の上の木の小屋を一晩借りるのがハナゲの名物。","仁川空港ターミナルから車で30分ほど。"],"travelTips":["潮汐表を確認しよう。海水浴は満潮時だけがよい。","干潮に貝を掘るなら長靴とバケツを用意しよう。","仁川での乗り継ぎが長いときの立ち寄り先に向いている。"],"bestTime":"5〜9月","visitDuration":"半日","ticket":"海上観光遊歩道は無料で通年開放、自然休養林は1,000ウォン、ハナゲ海水浴場は別料金","openingHours":"終日","galleryCaptions":["ハナゲ海水浴場の木の小屋"]},"zh":{"name":"舞衣島與霞娜蓋海水浴場","summary":"緊鄰仁川機場的島嶼，退潮時海水後撤數百公尺，沙灘上立著木造小屋。","story":"舞衣島離仁川國際機場近到降落的飛機就從頭頂掠過，但過了橋，節奏完全變了。霞娜蓋海灘潮差極大：退潮時泥灘裸露出數百公尺，人們提著水桶出去挖蛤蜊；漲潮時海水又回到那些直接蓋在沙上的木屋腳邊——木屋可以租來過夜。海灘後方有步道通往虎龍谷山，能俯瞰整片群島。自2019年跨海橋通車後，開車就能過去，不必再等船。","facts":["2019年舞衣大橋通車後，開車即可抵達，無須搭船。","霞娜蓋海灘潮差很大，退潮時泥灘可裸露數百公尺。","沙灘上可過夜的木造小屋是這裡的招牌。","距仁川機場航廈約30分鐘車程。"],"travelTips":["先查潮汐表——只有漲潮時海灘才好看。","想在退潮時挖蛤蜊，記得帶雨鞋與水桶。","若在仁川轉機時間長，這裡很適合當停留點。"],"bestTime":"5至9月","visitDuration":"半天","ticket":"海上觀光步道免費且全年開放；自然休養林1,000韓元，霞那開海水浴場另行收費","openingHours":"全日開放","galleryCaptions":["霞娜蓋海灘上的木屋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('songwol-fairy-tale-village', 'songwol-fairy-tale-village', 'incheon', 'Làng cổ tích Songwol-dong', 'Songwol-dong Fairy Tale Village', 'village', 126.6155, 37.4745, 'Khu dân cư già nua được sơn lại thành thế giới cổ tích, mỗi bức tường một câu chuyện quen thuộc.', 'Songwol-dong từng là khu nhà cũ đang mất dần người ở, chỉ còn lại người già. Năm 2013, thành phố và cư dân sơn lại toàn bộ ngõ phố theo các truyện cổ tích: Chú lính chì, Cô bé quàng khăn đỏ, Jack và cây đậu thần leo lên tận mái nhà, Peter Pan bay ngang bức tường đầu hẻm. Chuyện lạ là nó có tác dụng thật — khách kéo đến, quán mở lại, và làng sống lại. Đi hết chỉ chừng bốn mươi phút, nhưng đây là điểm hiếm hoi ở Hàn Quốc mà trẻ con thích hơn người lớn, và nó nằm ngay sau lưng phố người Hoa Incheon.', '["Dự án vẽ tường bắt đầu năm 2013 nhằm hồi sinh khu dân cư xuống cấp.","Các bức tường tái hiện những truyện cổ tích quen thuộc của phương Tây.","Nằm ngay cạnh phố người Hoa Incheon, đi bộ vài phút.","Cư dân vẫn sinh sống bình thường trong các ngõ này."]', '["Đi cùng phố người Hoa và khu phố cổ khai cảng trong một buổi.","Đây là khu dân cư — nói khẽ và không tự ý bước vào sân nhà.","Buổi sáng ánh sáng đẹp nhất cho ảnh tường vẽ."]', 'Quanh năm', '1 giờ', '', 'Cả ngày', '["hidden-gem"]', '["tranh tường","gia đình","đi bộ"]', '[{"seed":"songwol-fairy-tale-village","caption":"Ngõ tường vẽ cổ tích","ratio":"16/9"}]', '["incheon-chinatown","incheon-open-port-street"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Songwol-dong Fairy Tale Village","summary":"An ageing neighbourhood repainted as a storybook world, a familiar tale on every wall.","story":"Songwol-dong was an old quarter steadily losing its residents, with mostly elderly people left. In 2013 the city and the residents repainted every lane after fairy tales: the Steadfast Tin Soldier, Little Red Riding Hood, Jack''s beanstalk climbing all the way to a roof, Peter Pan flying across the wall at the mouth of an alley. The odd thing is that it worked — visitors came, shops reopened, the neighbourhood revived. The whole loop takes about forty minutes, but it is one of the rare Korean sights children enjoy more than adults, and it sits directly behind Incheon''s Chinatown.","facts":["The mural project began in 2013 to revive a declining neighbourhood.","The walls retell well-known Western fairy tales.","It is a few minutes'' walk from Incheon Chinatown.","People still live ordinary lives in these lanes."],"travelTips":["Combine it with Chinatown and the open port quarter in one outing.","This is a residential area — keep your voice down and stay out of yards.","Morning light is best for photographing the murals."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"","openingHours":"All day","galleryCaptions":["A fairy tale mural lane"]},"ko":{"name":"송월동 동화마을","summary":"낡아 가던 동네가 동화의 세계로 다시 칠해졌다. 담벼락마다 익숙한 이야기가 있다.","story":"송월동은 사람이 계속 빠져나가 노인만 남던 오래된 동네였다. 2013년 시와 주민이 골목 전체를 동화로 다시 칠했다. 꿋꿋한 주석 병정, 빨간 모자, 지붕까지 뻗어 올라간 잭의 콩나무, 골목 어귀 담을 가로질러 나는 피터 팬. 신기하게도 그것이 실제로 통했다. 사람이 찾아오고, 가게가 다시 열리고, 마을이 살아났다. 다 돌아도 사십 분 남짓이지만, 한국에서 드물게 어른보다 아이가 더 좋아하는 곳이고, 인천 차이나타운 바로 뒤에 있다.","facts":["2013년 낙후된 주거지를 되살리기 위해 벽화 사업이 시작되었다.","담벼락에는 널리 알려진 서양 동화가 그려져 있다.","인천 차이나타운에서 걸어서 몇 분 거리다.","골목에는 주민들이 여전히 살고 있다."],"travelTips":["차이나타운, 개항장 거리와 한 번에 묶어서 돌자.","주거지이니 목소리를 낮추고 남의 마당에는 들어가지 말자.","벽화 사진은 아침 빛이 가장 좋다."],"bestTime":"연중","visitDuration":"1시간","ticket":"","openingHours":"상시","galleryCaptions":["동화 벽화가 그려진 골목"]},"ja":{"name":"松月洞童話村","summary":"老いていく町が童話の世界に塗り直された。塀ごとに見覚えのある物語がある。","story":"松月洞は人が抜けていき、老人ばかりが残った古い町だった。2013年、市と住民が路地全体を童話で塗り直した。しっかり者のすずの兵隊、赤ずきん、屋根まで伸びたジャックの豆の木、路地の入口の塀を横切って飛ぶピーター・パン。不思議なことにそれが本当に効いた。人が訪れ、店が再び開き、町が生き返ったのだ。ひと回りしても四十分ほどだが、韓国では珍しく大人より子どもが喜ぶ場所で、仁川のチャイナタウンのすぐ裏にある。","facts":["2013年、衰退した住宅地を再生するために壁画事業が始まった。","塀には広く知られた西洋の童話が描かれている。","仁川チャイナタウンから歩いて数分。","路地には今も住民が普通に暮らしている。"],"travelTips":["チャイナタウン、開港場通りとまとめて回ろう。","住宅地なので声を落とし、人の庭に入らないように。","壁画の撮影は朝の光が最もよい。"],"bestTime":"通年","visitDuration":"1時間","ticket":"","openingHours":"終日","galleryCaptions":["童話の壁画が続く路地"]},"zh":{"name":"松月洞童話村","summary":"逐漸老去的社區被重新漆成童話世界，每一面牆都是一則熟悉的故事。","story":"松月洞原本是個不斷流失居民、只剩老人家的舊社區。2013年，市府與居民把整片巷弄依童話重新彩繪：勇敢的錫兵、小紅帽、一路爬上屋頂的傑克豌豆藤、在巷口牆面飛過的彼得潘。奇妙的是這招真的有效——人來了，店重新開了，社區活了過來。全部走完不過四十分鐘，卻是韓國少數小孩比大人更喜歡的地方，而且就在仁川中華街的後方。","facts":["壁畫計畫始於2013年，用意在振興沒落的住宅區。","牆面重述的是廣為人知的西方童話。","距仁川中華街步行僅數分鐘。","巷弄裡仍有居民正常生活。"],"travelTips":["可與中華街、開港場街區安排在同一趟。","這是住宅區，請放低音量，也別擅自走進人家院子。","早晨光線最適合拍壁畫。"],"bestTime":"全年","visitDuration":"1小時","ticket":"","openingHours":"全日開放","galleryCaptions":["畫滿童話的巷弄"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('incheon-open-port-street', 'incheon-open-port-street', 'incheon', 'Phố cổ khai cảng Incheon', 'Incheon Open Port Street', 'city', 126.622, 37.4735, 'Vài dãy phố còn nguyên nhà băng, lãnh sự quán và kho hàng dựng từ khi Hàn Quốc mở cảng năm 1883.', 'Năm 1883 Incheon mở cảng, và trong vòng hai thập niên khu này mọc lên nhà băng Nhật, lãnh sự quán Thanh, nhà thờ, kho hàng gạch đỏ — mỗi nước một kiểu kiến trúc, đứng cạnh nhau trên vài con phố. Ngày nay chúng vẫn còn: một bậc thang đá chia đôi khu phố, một bên là mái ngói kiểu Trung Hoa, bên kia là cửa sổ vòm kiểu Nhật, ranh giới tô giới cũ vẫn hiện rõ dưới chân bạn. Các toà nhà băng nay thành bảo tàng nhỏ về thời khai cảng, còn dãy kho gạch đỏ bên bến thành khu nghệ thuật với xưởng vẽ và quán cà phê nhìn ra cần cẩu cảng.', '["Cảng Incheon mở cửa năm 1883 theo hiệp ước với Nhật Bản.","Bậc thang Cheongil chia ranh giới tô giới Thanh và Nhật ngày trước.","Nhiều toà nhà băng đầu thế kỷ 20 nay là bảo tàng khai cảng.","Khu kho gạch đỏ bên bến được cải tạo thành Incheon Art Platform."]', '["Đi bộ theo bậc thang Cheongil để thấy rõ hai kiểu kiến trúc hai bên.","Các bảo tàng nhỏ đóng cửa thứ Hai.","Ga Incheon (tuyến 1) là ga cuối, ra cửa là tới phố người Hoa và khu này."]', 'Quanh năm', '2 giờ', '', 'Phố mở cả ngày, bảo tàng 09:00–18:00. Dịp lễ ''Dạ hành di sản Khai cảng'' hằng năm mở cửa di tích tới đêm', '["hidden-gem"]', '["kiến trúc","lịch sử","khai cảng","đi bộ"]', '[{"seed":"incheon-open-port-street","caption":"Bậc thang Cheongil chia hai tô giới","ratio":"16/9"}]', '["incheon-chinatown","songwol-fairy-tale-village"]', 0, 'https://korean.visitkorea.or.kr/detail/rem_detail.do?cotid=ab67f07d-24db-4ed2-8363-18b651955c1c', '2026-08-04', '{"en":{"name":"Incheon Open Port Street","summary":"A few streets of banks, consulates and warehouses left exactly as they were built when Korea opened the port in 1883.","story":"Incheon opened its port in 1883, and within two decades the quarter filled with Japanese banks, a Qing consulate, churches and red-brick warehouses — each nation building in its own manner, side by side along a few streets. They are still here: a stone stairway splits the quarter, Chinese tiled roofs on one side and Japanese arched windows on the other, the old concession boundary still plain under your feet. The bank buildings are now small museums of the open-port years, and the red-brick warehouses on the quay have become an arts complex of studios and cafés looking out at the harbour cranes.","facts":["Incheon port opened in 1883 under treaty with Japan.","The Cheongil stairway marked the boundary between the Qing and Japanese concessions.","Several early 20th-century bank buildings are now open-port museums.","The red-brick quayside warehouses were converted into the Incheon Art Platform."],"travelTips":["Walk up the Cheongil stairway to see the two architectural styles facing each other.","The small museums close on Mondays.","Incheon station (line 1) is the terminus; Chinatown and this quarter are at the exit."],"bestTime":"Year-round","visitDuration":"2 hours","ticket":"","openingHours":"The street is open all day and the museums run 09:00–18:00. At the annual Open Port Heritage Night festival the historic buildings stay open after dark","galleryCaptions":["The Cheongil stairway between two concessions"]},"ko":{"name":"인천 개항장 거리","summary":"1883년 개항 때 지어진 은행과 영사관, 창고가 그대로 남은 몇 블록.","story":"1883년 인천이 개항하고 이십 년 사이에 이 일대는 일본 은행과 청 영사관, 교회, 붉은 벽돌 창고로 채워졌다. 나라마다 제 방식으로 지은 건물들이 몇 개의 거리에 나란히 섰다. 지금도 그대로다. 돌계단이 거리를 둘로 가르는데, 한쪽은 중국식 기와지붕이고 다른 쪽은 일본식 아치 창이다. 옛 조계의 경계가 발밑에 뚜렷하다. 은행 건물들은 개항기 박물관이 되었고, 부두 옆 붉은 벽돌 창고들은 항만 크레인이 보이는 작업실과 카페가 있는 예술 공간이 되었다.","facts":["인천항은 1883년 일본과의 조약에 따라 개항했다.","청일조계지 경계계단은 청과 일본 조계의 경계였다.","20세기 초 은행 건물 여러 채가 개항박물관으로 쓰인다.","부두의 붉은 벽돌 창고는 인천아트플랫폼으로 바뀌었다."],"travelTips":["경계계단을 따라 걸으며 양쪽의 서로 다른 건축을 보자.","작은 박물관들은 월요일에 문을 닫는다.","1호선 인천역이 종착역이고, 나오면 바로 차이나타운과 이 거리다."],"bestTime":"연중","visitDuration":"2시간","ticket":"","openingHours":"거리는 상시 개방, 박물관은 09:00~18:00. 해마다 열리는 ''개항장 문화재 야행'' 기간에는 문화재를 밤까지 개방한다","galleryCaptions":["두 조계를 가르는 경계계단"]},"ja":{"name":"仁川開港場通り","summary":"1883年の開港時に建った銀行、領事館、倉庫がそのまま残る数ブロック。","story":"1883年に仁川が開港し、二十年のうちにこの一帯は日本の銀行、清の領事館、教会、赤煉瓦の倉庫で埋まった。国ごとに自国の流儀で建てた建物が、いくつかの通りに並んで立った。今もそのままだ。石段が通りを二つに割り、片側は中国式の瓦屋根、もう片側は日本式のアーチ窓である。旧租界の境界が足元にはっきり残る。銀行の建物は開港期の博物館になり、埠頭脇の赤煉瓦倉庫は港のクレーンを望むアトリエとカフェの芸術空間になった。","facts":["仁川港は1883年、日本との条約により開港した。","清日租界地境界階段は清と日本の租界の境だった。","20世紀初頭の銀行建築のいくつかは開港博物館として使われている。","埠頭の赤煉瓦倉庫は仁川アートプラットフォームに転用された。"],"travelTips":["境界階段を歩いて、両側の異なる建築を見比べよう。","小さな博物館は月曜休み。","1号線・仁川駅が終点で、出るとすぐチャイナタウンとこの通りだ。"],"bestTime":"通年","visitDuration":"2時間","ticket":"","openingHours":"通りは終日開放、博物館は09:00〜18:00。毎年の「開港場文化財夜行」期間は文化財を夜まで開放する","galleryCaptions":["二つの租界を分ける境界階段"]},"zh":{"name":"仁川開港場街區","summary":"幾條街上仍保留著1883年開港時興建的銀行、領事館與倉庫。","story":"仁川1883年開港，二十年間這一帶便長出日本銀行、清國領事館、教堂與紅磚倉庫——每個國家各按自己的做法蓋房子，沿著幾條街並肩而立。它們至今仍在：一道石階把街區一分為二，一側是中式瓦頂，另一側是日式拱窗，舊租界的界線至今清清楚楚踩在腳下。銀行建築如今成了開港時期的小型博物館，碼頭邊的紅磚倉庫則變成藝術園區，工作室與咖啡館望著港口的起重機。","facts":["仁川港依據與日本簽訂的條約於1883年開港。","清日租界地境界階梯曾是清國與日本租界的分界。","多棟20世紀初的銀行建築現為開港博物館。","碼頭旁的紅磚倉庫被改造成仁川藝術平台。"],"travelTips":["沿著境界階梯走，可以看到兩側截然不同的建築。","小型博物館週一休館。","地鐵1號線仁川站是終點站，出站就是中華街與這片街區。"],"bestTime":"全年","visitDuration":"2小時","ticket":"","openingHours":"街道全日開放，博物館09:00–18:00；每年的「開港場文化財夜行」期間，古蹟會開放至夜間","galleryCaptions":["分隔兩處租界的境界階梯"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sorae-wetland-park', 'sorae-wetland-park', 'incheon', 'Công viên sinh thái đầm Sorae', 'Sorae Wetland Ecological Park', 'park', 126.738, 37.402, 'Ruộng muối bỏ hoang thành đầm lầy, nơi cối xay gió gỗ đứng giữa những ô nước đổi màu theo mùa.', 'Đây từng là ruộng muối lớn nhất vùng thủ đô, hoạt động tới thập niên 1990 rồi bị bỏ. Nước biển vẫn ra vào theo triều, và cả khu đất tự biến thành đầm lầy: các ô muối cũ giờ là hồ nông, bờ đất thành lối đi, và ba chiếc cối xay gió gỗ dùng để bơm nước biển ngày trước vẫn đứng đó. Cuối hè, cây nham thảo phủ kín mặt đầm và chuyển sang màu đỏ tía, biến cả vùng thành một tấm thảm đỏ — đây là lý do người ta kéo đến chụp ảnh. Cò, diệc và chim di cư về rất đông, còn chợ cá Sorae ngay bên cạnh thì ồn ào từ sáng sớm.', '["Từng là ruộng muối lớn nhất vùng thủ đô, ngừng hoạt động vào thập niên 1990.","Ba cối xay gió gỗ dùng bơm nước biển ngày trước được phục dựng tại chỗ.","Cuối tháng 9 đến tháng 10, nham thảo chuyển đỏ tía phủ kín mặt đầm.","Là điểm dừng chân của nhiều loài chim di cư trên tuyến Đông Á."]', '["Cuối tháng 9 đến giữa tháng 10 là lúc thảm nham thảo đỏ nhất.","Mang ống nhòm nếu muốn xem chim; có đài quan sát trong công viên.","Kết hợp với chợ cá Sorae bên cạnh để ăn trưa hải sản."]', 'Cuối tháng 9 đến tháng 10', '1,5–2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["đầm lầy","chim","nhiếp ảnh","ruộng muối"]', '[{"seed":"sorae-wetland-park","caption":"Cối xay gió giữa thảm nham thảo đỏ","ratio":"16/9"}]', '["songdo-central-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Sorae Wetland Ecological Park","summary":"Abandoned salt pans turned marsh, where wooden windmills stand among pools that change colour with the season.","story":"This was once the largest salt farm in the capital region, working until the 1990s and then left. Seawater still moves in and out with the tide, and the ground turned itself into marsh: the old salt pans are now shallow pools, the dykes are footpaths, and three wooden windmills once used to pump seawater still stand. In late summer glasswort covers the flats and turns purple-red, spreading a crimson carpet across the whole basin — which is why photographers come. Egrets, herons and migratory birds gather in numbers, and the Sorae fish market next door is loud from first light.","facts":["Once the capital region''s largest salt farm, out of use since the 1990s.","Three wooden windmills that pumped seawater have been rebuilt on site.","From late September into October the glasswort turns purple-red across the flats.","It is a stopover on the East Asian migratory bird flyway."],"travelTips":["Late September to mid-October is when the glasswort is reddest.","Bring binoculars for the birds; there is a hide in the park.","Combine it with the Sorae fish market next door for a seafood lunch."],"bestTime":"Late September to October","visitDuration":"1.5–2 hours","ticket":"","openingHours":"All day","galleryCaptions":["Windmills among the red glasswort"]},"ko":{"name":"소래습지생태공원","summary":"버려진 염전이 습지가 되었다. 나무 풍차가 계절마다 색이 바뀌는 물웅덩이 사이에 서 있다.","story":"이곳은 1990년대까지 돌아가던 수도권 최대의 염전이었고, 그 뒤 버려졌다. 바닷물은 여전히 조수를 따라 드나들었고, 땅은 스스로 습지가 되었다. 옛 염전 칸은 얕은 못이 되고 둑은 산책로가 되었으며, 바닷물을 퍼 올리던 나무 풍차 세 대가 아직 서 있다. 늦여름이면 칠면초가 갯벌을 덮고 자줏빛으로 물들어 일대가 붉은 융단이 된다. 사진 찍는 사람들이 몰려오는 이유다. 백로와 왜가리, 철새가 많이 모이고, 바로 옆 소래포구 어시장은 이른 아침부터 시끌벅적하다.","facts":["한때 수도권 최대 염전이었고 1990년대에 조업을 멈췄다.","바닷물을 퍼 올리던 나무 풍차 세 대가 현장에 복원되어 있다.","9월 말부터 10월까지 칠면초가 자줏빛으로 갯벌을 덮는다.","동아시아 철새 이동 경로의 중간 기착지다."],"travelTips":["칠면초가 가장 붉은 때는 9월 말에서 10월 중순이다.","새를 보려면 쌍안경을 챙기자. 공원 안에 관찰대가 있다.","바로 옆 소래포구 어시장에서 해산물로 점심을 먹자."],"bestTime":"9월 말~10월","visitDuration":"1.5~2시간","ticket":"","openingHours":"상시","galleryCaptions":["붉은 칠면초 사이의 풍차"]},"ja":{"name":"蘇萊湿地生態公園","summary":"捨てられた塩田が湿地になった。木の風車が、季節で色を変える水たまりの間に立つ。","story":"ここは1990年代まで稼働した首都圏最大の塩田で、その後放置された。海水は潮に従って出入りし続け、土地はひとりでに湿地になった。かつての塩田の枡は浅い池になり、堤は歩道になり、海水を汲み上げていた木の風車が三基まだ立っている。晩夏にはシチメンソウが干潟を覆って紫紅色に染まり、一帯が赤い絨毯になる。写真を撮る人が集まる理由だ。シラサギやアオサギ、渡り鳥が多く集まり、すぐ隣の蘇萊浦口の魚市場は早朝から騒がしい。","facts":["かつて首都圏最大の塩田で、1990年代に操業を終えた。","海水を汲み上げていた木の風車三基が現地に復元されている。","9月末から10月にかけてシチメンソウが干潟を紫紅色に染める。","東アジアの渡り鳥ルートの中継地である。"],"travelTips":["シチメンソウが最も赤いのは9月末から10月中旬。","鳥を見るなら双眼鏡を。公園内に観察台がある。","隣の蘇萊浦口魚市場で海鮮の昼食を合わせよう。"],"bestTime":"9月末〜10月","visitDuration":"1.5〜2時間","ticket":"","openingHours":"終日","galleryCaptions":["赤いシチメンソウの間の風車"]},"zh":{"name":"蘇萊濕地生態公園","summary":"廢棄鹽田變成的濕地，木造風車立在隨季節換色的水塘之間。","story":"這裡曾是首都圈最大的鹽田，一直運作到1990年代才荒廢。海水仍隨潮汐進出，這片土地便自己變成了濕地：舊鹽田格成了淺塘，田埂成了步道，三座當年用來汲取海水的木造風車仍立在原處。夏末，鹼蓬覆蓋灘地並轉為紫紅，整片盆地鋪成一張紅毯——這正是攝影者前來的理由。白鷺、蒼鷺與候鳥成群聚集，隔壁的蘇萊浦口魚市則從天剛亮就喧鬧起來。","facts":["曾是首都圈最大的鹽田，1990年代停止生產。","三座當年汲取海水的木造風車已在原地重建。","9月底至10月，鹼蓬會把整片灘地染成紫紅色。","是東亞候鳥遷徙路線上的中繼站。"],"travelTips":["9月底到10月中旬是鹼蓬最紅的時候。","賞鳥請帶望遠鏡，園內設有觀察台。","可搭配隔壁的蘇萊浦口魚市吃海鮮午餐。"],"bestTime":"9月底至10月","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["紅色鹼蓬間的風車"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hwaseong-fortress', 'hwaseong-fortress', 'gyeonggi', 'Thành Hwaseong (Suwon)', 'Suwon Hwaseong Fortress', 'unesco', 127.009, 37.288, 'Vòng thành đá dài gần 6 km do vua Jeongjo xây vì hiếu nghĩa với cha, và vì muốn dời cả kinh đô.', 'Cuối thế kỷ 18, vua Jeongjo dời mộ người cha bị chết oan về Suwon và cho xây quanh đó một toà thành kiểu mới. Hwaseong không giống thành cũ: kỹ sư Jeong Yak-yong dùng ròng rọc và cần cẩu tự chế, kết hợp đá với gạch nung, học cả kỹ thuật phương Tây lẫn Trung Hoa. Đi trọn vòng tường thành mất chừng hai tiếng, ngang qua bốn cổng lớn, các chòi quan sát, ụ pháo và một cây cầu vòm bảy nhịp bắc qua suối. Điều lạ là toà thành này chưa từng phải chống một cuộc vây hãm nào.', '["Được UNESCO công nhận Di sản Thế giới năm 1997.","Xây trong hai năm rưỡi (1794–1796), rất nhanh so với quy mô.","Tường thành dài khoảng 5,7 km với 48 công trình phòng thủ.","Bản vẽ thi công ''Hwaseong Seongyeok Uigwe'' còn nguyên nên việc phục dựng rất chính xác."]', '["Đi tàu điện tuyến 1 tới ga Suwon, rồi bắt bus tới cổng Paldalmun.","Đi ngược chiều kim đồng hồ từ Paldalmun để leo dốc trước, xuống dốc sau.","Có xe điện du lịch chạy quanh thành nếu ngại đi bộ."]', 'Tháng 4–5 và 9–11', '3 giờ', '1.000 KRW (vé gộp 4 điểm 3.500 KRW); đi bộ trên tường thành miễn phí', '09:00–18:00', '["unesco","verified"]', '["UNESCO","thành cổ","đi bộ"]', '[{"seed":"hwaseong-fortress","caption":"Cổng Paldalmun và tường thành","ratio":"16/9"}]', '["korean-folk-village","namhansanseong"]', 1, 'https://www.swcf.or.kr/', '2026-08-04', '{"en":{"name":"Suwon Hwaseong Fortress","summary":"Nearly six kilometres of stone wall built by King Jeongjo out of filial duty — and a wish to move the capital.","story":"In the late 18th century King Jeongjo moved his wronged father''s tomb to Suwon and built a new kind of fortress around it. Hwaseong was unlike the old walls: the engineer Jeong Yak-yong used homemade pulleys and cranes, combined stone with fired brick, and borrowed technique from both Europe and China. Walking the full circuit takes about two hours, past four great gates, watchtowers, artillery bastions and a seven-arch bridge over a stream. The strange part is that this fortress never had to withstand a siege.","facts":["Inscribed as a UNESCO World Heritage Site in 1997.","Built in only two and a half years (1794–1796), remarkably fast for its scale.","The wall runs about 5.7 km with 48 defensive structures.","The construction record ''Hwaseong Seongyeok Uigwe'' survives intact, making restoration unusually accurate."],"travelTips":["Take Line 1 to Suwon station, then a bus to Paldalmun gate.","Walk anticlockwise from Paldalmun to climb first and descend later.","A tourist trolley circles the fortress if you''d rather not walk."],"bestTime":"April–May and September–November","visitDuration":"3 hours","ticket":"1,000 KRW (4-site combined ticket 3,500 KRW); walking the wall itself is free","openingHours":"09:00–18:00","galleryCaptions":["Paldalmun gate and the fortress wall"]},"ko":{"name":"수원 화성","summary":"정조가 아버지를 향한 효심으로, 또 도읍을 옮길 뜻으로 쌓은 6km의 성벽.","story":"18세기 말 정조는 억울하게 죽은 아버지의 묘를 수원으로 옮기고 그 둘레에 새로운 형식의 성을 쌓았다. 화성은 옛 성과 달랐다. 정약용이 거중기와 녹로를 고안했고, 돌과 구운 벽돌을 함께 썼으며, 서양과 중국의 기술을 두루 참고했다. 성벽을 한 바퀴 도는 데 두 시간쯤 걸리며 네 개의 큰 문과 공심돈, 포루, 일곱 칸의 무지개다리를 지난다. 정작 이 성은 단 한 번도 공성전을 겪지 않았다.","facts":["1997년 유네스코 세계문화유산에 등재되었다.","1794~1796년, 2년 반 만에 완공된 대규모 공사였다.","성벽 길이는 약 5.7km, 48개의 시설물이 있다.","『화성성역의궤』가 남아 복원이 매우 정확하게 이뤄졌다."],"travelTips":["1호선 수원역에서 버스를 타고 팔달문에서 시작하자.","팔달문에서 시계 반대 방향으로 돌면 오르막을 먼저 지난다.","걷기 부담스럽다면 화성어차를 이용할 수 있다."],"bestTime":"4~5월, 9~11월","visitDuration":"3시간","ticket":"1,000원(4개소 통합권 3,500원), 성곽길 자체는 무료","openingHours":"09:00~18:00","galleryCaptions":["팔달문과 성벽"]},"ja":{"name":"水原華城","summary":"正祖が父への孝心と、遷都の意志で築いた約6kmの城壁。","story":"18世紀末、正祖は無念の死を遂げた父の墓を水原に移し、その周囲に新しい形式の城を築いた。華城は旧来の城とは違った。丁若鏞が挙重機と轆轤を考案し、石と焼成レンガを併用し、西洋と中国の技術を取り入れた。城壁を一周するには二時間ほど。四つの大門、望楼、砲楼、そして七つの虹の橋を通る。不思議なことに、この城は一度も攻城戦を経験していない。","facts":["1997年にユネスコ世界文化遺産に登録された。","1794〜1796年、わずか2年半で完成した大工事だった。","城壁は約5.7km、48の施設が備わる。","『華城城役儀軌』が残り、復元がきわめて正確に行われた。"],"travelTips":["1号線水原駅からバスで八達門へ向かうとよい。","八達門から反時計回りに歩けば先に上りを済ませられる。","歩くのが大変なら華城御車を利用できる。"],"bestTime":"4〜5月、9〜11月","visitDuration":"3時間","ticket":"1,000ウォン（4施設共通券3,500ウォン）、城壁を歩くだけなら無料","openingHours":"09:00〜18:00","galleryCaptions":["八達門と城壁"]},"zh":{"name":"水原華城","summary":"正祖為盡孝、也為遷都而築的近六公里城牆。","story":"十八世紀末，正祖將含冤而死的父親遷葬水原，並在四周築起一座嶄新形制的城。華城不同於舊城：工學家丁若鏞自製滑車與絞盤，以石材結合燒磚，兼取西洋與中國之技。繞城一周約需兩小時，途經四座大門、望樓、砲台，以及一座七孔拱橋。有趣的是，這座城從未經歷過一場攻城戰。","facts":["1997年列入世界文化遺產。","1794至1796年間興建，僅費時兩年半，以其規模而言相當迅速。","城牆長約5.7公里，設有48處防禦建築。","《華城城役儀軌》完整留存，使復原格外精確。"],"travelTips":["搭1號線至水原站，再轉巴士到八達門。","自八達門逆時針走，可先上坡後下坡。","不想走路可搭乘遊園車環城。"],"bestTime":"4至5月、9至11月","visitDuration":"3小時","ticket":"1,000韓元（四館聯票3,500韓元）；純走城牆免費","openingHours":"09:00–18:00","galleryCaptions":["八達門與城牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('korean-folk-village', 'korean-folk-village', 'gyeonggi', 'Làng Dân tộc Hàn Quốc', 'Korean Folk Village', 'village', 127.118, 37.26, 'Ngôi làng Joseon dựng lại nguyên vẹn ở Yongin, nơi thợ rèn, thầy đồ và người đi dây vẫn làm việc mỗi ngày.', 'Hơn 260 nếp nhà được dời về hoặc dựng lại theo đúng lối từng vùng: nhà tranh miền Nam mái rơm dày, nhà quan miền Trung có sân trong, chuồng trâu, cối xay, giếng làng. Nhưng thứ khiến nơi này sống động là con người: thợ gốm ngồi bên bàn xoay, người kéo mạch nha kể chuyện, và mỗi ngày vài lần có màn đi dây jultagi cùng đội nhạc nông dân nongak gõ trống đi vòng quanh sân. Nhiều bộ phim cổ trang Hàn Quốc được quay ở đây, nên khung cảnh sẽ quen mắt một cách kỳ lạ.', '["Mở cửa từ năm 1974, rộng khoảng 100 hecta.","Có hơn 260 công trình mô phỏng kiến trúc dân gian các vùng miền.","Là phim trường của rất nhiều phim truyền hình cổ trang Hàn Quốc.","Các buổi diễn nongak, jultagi và cưới truyền thống diễn ra theo lịch cố định trong ngày."]', '["Xem lịch diễn ngay ở cổng và sắp xếp đường đi theo giờ biểu diễn.","Có xe buýt miễn phí từ ga Suwon.","Làng rất rộng, dành ít nhất nửa ngày và mang giày đi bộ."]', 'Tháng 4–6 và 9–11', 'Nửa ngày', '32.000 KRW (trẻ em 26.000, từ 65 tuổi 22.000); đã gồm khu trò chơi', '10:00–18:00', '["popular"]', '["văn hoá dân gian","biểu diễn","gia đình"]', '[{"seed":"korean-folk-village","caption":"Nhà mái rơm trong làng dân tộc","ratio":"16/9"}]', '["hwaseong-fortress"]', 0, 'https://us.trip.com/travel-guide/attraction/yongin-si/korean-folk-village-81850/', '2026-08-04', '{"en":{"name":"Korean Folk Village","summary":"A Joseon village rebuilt in full at Yongin, where blacksmiths, scholars and tightrope walkers still work every day.","story":"More than 260 buildings were moved here or rebuilt in the styles of each region: thick-thatched southern cottages, officials'' houses with inner courtyards, ox sheds, mills and a village well. What makes the place live, though, is the people: a potter at his wheel, a taffy-puller telling stories, and several times a day a jultagi tightrope walk with a nongak farmers'' band drumming its way around the yard. Many Korean historical dramas are filmed here, so the scenery will feel oddly familiar.","facts":["Opened in 1974 and covering about 100 hectares.","More than 260 structures reproduce regional folk architecture.","A filming location for a great many Korean historical dramas.","Nongak, jultagi and traditional wedding performances run on a fixed daily schedule."],"travelTips":["Check the performance schedule at the gate and plan your route around it.","A free shuttle bus runs from Suwon station.","The village is large — allow half a day and wear walking shoes."],"bestTime":"April–June and September–November","visitDuration":"Half a day","ticket":"32,000 KRW (26,000 children, 22,000 over-65s); includes the amusement village","openingHours":"10:00–18:00","galleryCaptions":["Thatched houses in the folk village"]},"ko":{"name":"한국민속촌","summary":"용인에 되살린 조선의 마을. 대장장이도, 훈장도, 줄타기 광대도 매일 일한다.","story":"260채가 넘는 집이 지역별 양식 그대로 옮겨지거나 다시 지어졌다. 두꺼운 초가를 인 남부의 집, 안마당을 둔 중부의 반가, 외양간과 방앗간과 마을 우물까지. 이곳을 살아 있게 하는 것은 사람이다. 물레 앞의 도공, 이야기를 늘어놓는 엿장수, 그리고 하루 몇 차례 마당을 도는 농악대와 줄타기. 수많은 사극이 여기서 촬영되어 풍경이 묘하게 낯익다.","facts":["1974년 문을 열었고 면적은 약 100만 제곱미터다.","지역별 민가 260여 채가 재현되어 있다.","수많은 한국 사극의 촬영지다.","농악, 줄타기, 전통혼례 공연이 매일 정해진 시간에 열린다."],"travelTips":["입구에서 공연 시간표를 확인하고 동선을 짜자.","수원역에서 무료 셔틀버스가 운행한다.","규모가 크니 반나절 이상 잡고 편한 신발을 신자."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절","ticket":"32,000원(어린이 26,000원, 65세 이상 22,000원), 놀이마을 이용 포함","openingHours":"10:00~18:00","galleryCaptions":["민속촌의 초가집"]},"ja":{"name":"韓国民俗村","summary":"龍仁に丸ごと再現された朝鮮の村。鍛冶屋も塾の師匠も綱渡り師も毎日働いている。","story":"260棟を超える家が地域ごとの様式のまま移築・再建された。厚い茅を葺いた南部の家、内庭を持つ中部の両班屋敷、牛小屋、水車、村の井戸。この場所を生かしているのは人だ。轆轤に向かう陶工、話を語る飴売り、そして一日数回、庭を回る農楽隊と綱渡り。数多くの時代劇がここで撮影されており、風景が妙に見覚えのあるものに感じられる。","facts":["1974年に開村し、面積は約100ヘクタール。","地域別の民家260棟余りが再現されている。","数多くの韓国時代劇のロケ地である。","農楽、綱渡り、伝統婚礼の公演が毎日定刻に行われる。"],"travelTips":["入口で公演時間表を確認して動線を決めよう。","水原駅から無料シャトルバスが出ている。","広いので半日以上を見込み、歩きやすい靴で。"],"bestTime":"4〜6月、9〜11月","visitDuration":"半日","ticket":"32,000ウォン（子ども26,000、65歳以上22,000）、遊園村の利用込み","openingHours":"10:00〜18:00","galleryCaptions":["民俗村の茅葺きの家"]},"zh":{"name":"韓國民俗村","summary":"在龍仁完整重建的朝鮮村落，鐵匠、私塾先生與走繩藝人每天都在工作。","story":"兩百六十多棟房舍按各地樣式遷建或重建：南部厚實的茅草屋、中部帶內院的官宅、牛棚、磨坊與村井。真正讓這裡活起來的是人：轉著轆轤的陶匠、邊拉麥芽糖邊講故事的小販，以及每天數場的走繩與繞場敲打的農樂隊。許多韓國古裝劇在此拍攝，風景會讓人莫名眼熟。","facts":["1974年開放，面積約100公頃。","重現各地民居260餘棟。","是眾多韓國古裝劇的拍攝地。","農樂、走繩與傳統婚禮表演每日定時舉行。"],"travelTips":["在入口確認表演時刻表，再規劃動線。","水原站有免費接駁車。","園區很大，請預留半天並穿好走的鞋。"],"bestTime":"4至6月、9至11月","visitDuration":"半天","ticket":"32,000韓元（兒童26,000，65歲以上22,000），含遊樂村設施","openingHours":"10:00–18:00","galleryCaptions":["民俗村的茅草屋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('namhansanseong', 'namhansanseong', 'gyeonggi', 'Sơn thành Namhansanseong', 'Namhansanseong Fortress', 'unesco', 127.181, 37.479, 'Toà thành trên núi từng là kinh đô dự phòng của Joseon, nay là đường mòn đi bộ ưa thích của dân Seoul.', 'Namhansanseong được dựng trên dãy núi phía đông nam Seoul để làm nơi lánh nạn cho triều đình khi kinh thành thất thủ. Mùa đông năm 1636, vua Injo cùng quần thần cố thủ ở đây 47 ngày trước quân Thanh trước khi phải đầu hàng — một trong những chương cay đắng nhất sử Joseon. Ngày nay tường thành uốn theo sống núi thành một đường mòn dài, len giữa rừng thông; đi hết vòng mất chừng bốn tiếng. Dưới chân núi là dãy quán chuyên đậu phụ và cơm trộn nấm, phần thưởng quen thuộc sau chuyến leo.', '["Được UNESCO công nhận Di sản Thế giới năm 2014.","Tường thành dài khoảng 12 km, chạy men theo các đỉnh núi.","Từng là kinh đô lâm thời trong cuộc xâm lược của nhà Thanh năm 1636.","Nằm trong công viên tỉnh Namhansanseong, cách trung tâm Seoul khoảng một giờ."]', '["Tàu điện tuyến 8 tới ga Sanseong rồi bắt bus 9 lên cổng thành.","Đi đoạn từ cổng Nam tới cổng Đông nếu chỉ có nửa ngày.","Mùa thu lá đỏ rất đẹp nhưng cuối tuần rất đông."]', 'Tháng 10–11 (lá đỏ)', '3–4 giờ', 'Vào thành miễn phí từ năm 2007; riêng hành cung 2.000 KRW (thiếu niên 1.000), miễn phí cho trẻ dưới 6, người từ 65 tuổi và khách mặc hanbok', 'Thành mở cả ngày; hành cung 10:00–18:00 (tháng 4–10) và 10:00–17:00 (tháng 11–3), đóng cửa thứ Hai', '["unesco"]', '["UNESCO","leo núi","thành cổ","mùa thu"]', '[{"seed":"namhansanseong","caption":"Tường thành chạy theo sống núi","ratio":"16/9"}]', '["hwaseong-fortress"]', 0, 'https://www.gg.go.kr/namhansansung-2/contents/contents.do?ciIdx=1274&menuId=3486', '2026-08-05', '{"en":{"name":"Namhansanseong Fortress","summary":"A mountain fortress that served as Joseon''s emergency capital, now the favourite hiking wall of Seoul.","story":"Namhansanseong was raised on the ridges southeast of Seoul as a refuge for the court should the capital fall. In the winter of 1636 King Injo and his ministers held out here for 47 days against the Qing army before surrendering — one of the bitterest chapters in Joseon history. Today the wall follows the crest as a long trail through pine forest; the full circuit takes about four hours. At the foot of the mountain waits a row of restaurants specialising in tofu and mushroom rice, the familiar reward after the climb.","facts":["Inscribed as a UNESCO World Heritage Site in 2014.","The wall runs about 12 km along the mountain ridges.","Served as the temporary capital during the 1636 Qing invasion.","Inside Namhansanseong Provincial Park, about an hour from central Seoul."],"travelTips":["Line 8 to Sanseong station, then bus 9 up to the gate.","Walk the South Gate to East Gate stretch if you only have half a day.","Autumn colour is superb but weekends are very crowded."],"bestTime":"October–November (autumn leaves)","visitDuration":"3–4 hours","ticket":"The fortress has been free since 2007; the royal lodge charges 2,000 KRW (1,000 teens), free for under-6s, over-65s and visitors in hanbok","openingHours":"The fortress is open all day; the royal lodge runs 10:00–18:00 (April–October) and 10:00–17:00 (November–March), closed Mondays","galleryCaptions":["The wall following the mountain ridge"]},"ko":{"name":"남한산성","summary":"조선의 임시 수도였던 산성. 지금은 서울 사람들이 가장 즐겨 걷는 성곽길이다.","story":"남한산성은 도성이 무너졌을 때 조정이 피신할 곳으로 서울 동남쪽 능선에 쌓였다. 1636년 겨울 인조와 신하들은 청군에 맞서 47일을 버티다 항복했다. 조선사에서 가장 쓰라린 장면 가운데 하나다. 오늘날 성벽은 능선을 따라 긴 산책로가 되어 소나무 숲 사이로 이어지고, 한 바퀴 도는 데 네 시간쯤 걸린다. 산 아래에는 두부와 버섯밥을 내는 식당들이 줄지어 있어 산행 뒤의 익숙한 보상이 된다.","facts":["2014년 유네스코 세계문화유산에 등재되었다.","성벽은 능선을 따라 약 12km 이어진다.","1636년 병자호란 당시 임시 수도 역할을 했다.","서울 도심에서 약 한 시간 거리의 남한산성도립공원 안에 있다."],"travelTips":["8호선 산성역에서 9번 버스를 타면 성문 앞까지 간다.","반나절이라면 남문에서 동문 구간만 걸어도 좋다.","가을 단풍이 아름답지만 주말에는 매우 붐빈다."],"bestTime":"10~11월(단풍)","visitDuration":"3~4시간","ticket":"산성 입장료는 2007년에 폐지되어 무료이며, 행궁만 2,000원(청소년 1,000원)이다. 6세 이하와 65세 이상, 한복 착용자는 무료","openingHours":"산성은 상시 개방, 행궁은 10:00~18:00(4~10월), 10:00~17:00(11~3월)이며 월요일 휴궁","galleryCaptions":["능선을 따라 이어지는 성벽"]},"ja":{"name":"南漢山城","summary":"朝鮮の臨時首都となった山城。今はソウル市民が最も歩く城郭路だ。","story":"南漢山城は都が落ちたときに朝廷が避難する場所として、ソウル南東の稜線に築かれた。1636年の冬、仁祖と臣下たちは清軍に対して47日間持ちこたえた末に降伏する。朝鮮史で最も苦い場面のひとつだ。今日、城壁は稜線に沿って松林を抜ける長い散策路となり、一周は四時間ほど。麓には豆腐やきのこ飯を出す食堂が並び、山行のあとの馴染みの褒美になっている。","facts":["2014年にユネスコ世界文化遺産に登録された。","城壁は稜線に沿って約12km続く。","1636年の丙子の乱では臨時首都の役割を果たした。","ソウル都心から約1時間の南漢山城道立公園内にある。"],"travelTips":["8号線山城駅から9番バスで城門前まで行ける。","半日なら南門から東門の区間を歩くだけでも十分。","紅葉は美しいが週末は非常に混雑する。"],"bestTime":"10〜11月（紅葉）","visitDuration":"3〜4時間","ticket":"城の入場は2007年に無料化。行宮のみ2,000ウォン（青少年1,000）で、6歳以下・65歳以上・韓服着用者は無料","openingHours":"城は終日開放、行宮は10:00〜18:00（4〜10月）、10:00〜17:00（11〜3月）、月曜休宮","galleryCaptions":["稜線に沿って延びる城壁"]},"zh":{"name":"南漢山城","summary":"曾作朝鮮臨時首都的山城，如今是首爾人最愛的城牆步道。","story":"南漢山城築於首爾東南的山脊，作為都城失守時朝廷避難之所。1636年冬，仁祖與群臣在此抵抗清軍四十七日後投降——這是朝鮮史上最苦澀的篇章之一。今日城牆沿山脊化為一條穿越松林的長步道，環行一周約四小時。山腳下是一排以豆腐與菇飯聞名的餐館，成了登山之後熟悉的犒賞。","facts":["2014年列入世界文化遺產。","城牆沿山脊延伸約12公里。","1636年丙子之役期間曾為臨時首都。","位於距首爾市中心約一小時的南漢山城道立公園內。"],"travelTips":["搭8號線至山城站，再轉9號巴士至城門。","只有半天的話，走南門至東門一段即可。","秋季紅葉極美，但週末非常擁擠。"],"bestTime":"10至11月（紅葉）","visitDuration":"3至4小時","ticket":"山城自2007年起免費；行宮另收2,000韓元（青少年1,000），6歲以下、65歲以上與著韓服者免費","openingHours":"山城全日開放；行宮10:00–18:00（4至10月）、10:00–17:00（11至3月），週一休館","galleryCaptions":["沿山脊延伸的城牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('everland', 'everland', 'gyeonggi', 'Công viên Everland', 'Everland', 'park', 127.202, 37.294, 'Công viên giải trí lớn nhất Hàn Quốc, có tàu lượn gỗ dốc nhất thế giới và một vườn hoa đổi mặt bốn lần mỗi năm.', 'Everland không chỉ là công viên giải trí — nó là nơi người Hàn đo mùa. Tháng 4 vườn tulip nở kín sườn đồi, tháng 6 là hoa hồng, mùa thu hoa cúc và cỏ lau, mùa đông cả công viên phủ đèn. Trò được nhắc nhiều nhất là T Express, tàu lượn khung gỗ có đoạn đổ dốc 77 độ, dựng đứng đến mức bạn rời khỏi ghế trong một nhịp. Bên cạnh là Zootopia với tour xe chở khách đi giữa đàn sư tử và gấu, và một khu safari cho hổ trắng. Cuối tuần rất đông, nhưng công viên đủ rộng để tản ra.', '["Mở cửa năm 1976, là công viên giải trí lớn nhất Hàn Quốc.","T Express là tàu lượn khung gỗ có góc đổ dốc lớn nhất thế giới khi khánh thành, 77 độ.","Vườn hoa được thay theo bốn mùa: tulip, hoa hồng, cúc, đèn mùa đông.","Khu Zootopia có tour xe qua vùng thú ăn thịt và khu hổ trắng."]', '["Đặt vé trước trên mạng, rẻ hơn đáng kể so với mua tại cổng.","Vào cổng chạy thẳng tới T Express trước — hàng chờ dài nhất từ trưa.","Có xe buýt thẳng từ ga Gangnam, khoảng một giờ."]', 'Tháng 4 (tulip) và tháng 10–11', 'Cả ngày', 'Vé ngày niêm yết khoảng 62.000 KRW; vé đặt trước rẻ hơn nhiều', 'Thay đổi theo mùa và theo ngày — xem lịch trên trang chính thức trước khi đi', '["popular"]', '["công viên giải trí","gia đình","hoa","tàu lượn"]', '[{"seed":"everland","caption":"Vườn tulip mùa xuân","ratio":"16/9"}]', '["korean-folk-village","hwaseong-fortress"]', 0, 'https://www.everland.com/web/multi/en/everland/main.html', '2026-08-04', '{"en":{"name":"Everland","summary":"Korea''s largest theme park, with the steepest wooden roller coaster in the world and a flower garden that changes face four times a year.","story":"Everland is not just an amusement park — it is how Koreans measure the season. In April tulips cover the hillside, in June roses, in autumn chrysanthemums and silver grass, and in winter the whole park is strung with lights. The ride everyone talks about is T Express, a wooden-framed coaster with a 77-degree drop so near vertical that you leave your seat for a beat. Beside it is Zootopia, with a bus tour that runs among lions and bears and a white tiger enclosure. Weekends are packed, but the park is big enough to absorb it.","facts":["Opened in 1976 and is Korea''s largest theme park.","T Express had the steepest drop of any wooden coaster in the world when it opened, at 77 degrees.","The flower garden is replanted by season: tulips, roses, chrysanthemums, winter lights.","Zootopia includes a bus safari through the predator enclosure and a white tiger area."],"travelTips":["Book online ahead — noticeably cheaper than the gate.","Head straight for T Express on arrival; the queue is longest from midday.","There is a direct bus from Gangnam station, about an hour."],"bestTime":"April (tulips) and October–November","visitDuration":"A full day","ticket":"Gate day pass around 62,000 KRW; pre-booked tickets are considerably cheaper","openingHours":"Varies by season and by day — check the official calendar before you go","galleryCaptions":["The spring tulip garden"]},"ko":{"name":"에버랜드","summary":"한국에서 가장 큰 테마파크. 세계에서 가장 가파른 목조 롤러코스터와 일 년에 네 번 얼굴을 바꾸는 꽃밭이 있다.","story":"에버랜드는 단순한 놀이공원이 아니라 한국 사람이 계절을 재는 방식이다. 4월이면 튤립이 언덕을 덮고, 6월에는 장미, 가을에는 국화와 억새, 겨울에는 공원 전체에 조명이 걸린다. 가장 많이 이야기되는 것은 티익스프레스다. 77도로 떨어지는 목조 롤러코스터인데, 거의 수직이라 한 박자 동안 몸이 좌석에서 떠오른다. 그 옆 주토피아에는 사자와 곰 사이를 달리는 버스 사파리와 백호 구역이 있다. 주말은 붐비지만 공원이 넓어 사람이 흩어진다.","facts":["1976년 개장했으며 한국에서 가장 큰 테마파크다.","티익스프레스는 개장 당시 목조 코스터 중 세계에서 가장 가파른 77도 낙하각을 가졌다.","꽃밭은 계절마다 바뀐다. 튤립, 장미, 국화, 겨울 조명.","주토피아에는 맹수 구역을 지나는 버스 사파리와 백호 구역이 있다."],"travelTips":["온라인 사전 예매가 현장 구매보다 훨씬 싸다.","입장하면 티익스프레스부터 가자. 정오부터 줄이 가장 길다.","강남역에서 직통 버스로 한 시간쯤 걸린다."],"bestTime":"4월(튤립)과 10~11월","visitDuration":"하루","ticket":"현장 종일권 약 62,000원, 사전 예매는 훨씬 저렴","openingHours":"계절과 요일마다 다름 — 방문 전 공식 홈페이지에서 확인","galleryCaptions":["봄의 튤립 정원"]},"ja":{"name":"エバーランド","summary":"韓国最大のテーマパーク。世界一急な木造コースターと、年に四度顔を変える花畑がある。","story":"エバーランドは単なる遊園地ではなく、韓国の人が季節を測る場所だ。四月はチューリップが丘を覆い、六月はバラ、秋は菊とススキ、冬は園内全体に明かりが灯る。最も語られるのはTエクスプレス。77度で落ちる木造コースターで、ほぼ垂直のため一拍だけ座席から体が浮く。隣のズートピアには、ライオンやクマの間を走るバスサファリとホワイトタイガーの区域がある。週末は混むが、園が広いので人は散る。","facts":["1976年開園、韓国最大のテーマパーク。","Tエクスプレスは開業当時、木造コースターとして世界一急な77度の落下角だった。","花畑は季節ごとに植え替えられる。チューリップ、バラ、菊、冬の照明。","ズートピアには猛獣区域を走るバスサファリとホワイトタイガー区域がある。"],"travelTips":["オンラインの事前購入が窓口よりかなり安い。","入園したらまずTエクスプレスへ。昼から列が最も長くなる。","江南駅から直通バスで一時間ほど。"],"bestTime":"4月（チューリップ）と10〜11月","visitDuration":"一日","ticket":"当日券は約62,000ウォン、事前購入はかなり安い","openingHours":"季節と曜日で変動 — 訪問前に公式サイトで確認を","galleryCaptions":["春のチューリップ庭園"]},"zh":{"name":"愛寶樂園","summary":"韓國最大的主題樂園，擁有全球最陡的木造雲霄飛車，以及一年換四次面貌的花園。","story":"愛寶樂園不只是遊樂園，更是韓國人衡量季節的方式。四月鬱金香鋪滿山坡，六月是玫瑰，秋天是菊花與芒草，冬天則整座園區點滿燈。最常被談論的是T Express——一座木造結構的雲霄飛車，俯衝角度達77度，陡到讓人有那麼一拍離開座椅。旁邊的動物王國有巴士遊獵穿行於獅子與熊之間，還有白虎區。週末很擠，但園區夠大，人潮會散開。","facts":["1976年開幕，是韓國最大的主題樂園。","T Express開幕時是全球木造雲霄飛車中最陡的，俯衝角77度。","花園依季節換植：鬱金香、玫瑰、菊花、冬季燈飾。","動物王國設有穿越猛獸區的巴士遊獵與白虎區。"],"travelTips":["線上預購便宜不少，別在門口買。","入園先衝T Express，中午之後排隊最長。","自江南站有直達巴士，車程約一小時。"],"bestTime":"4月（鬱金香）與10至11月","visitDuration":"一整天","ticket":"現場一日票約62,000韓元，事先預訂便宜許多","openingHours":"依季節與日期變動——出發前請查看官網行事曆","galleryCaptions":["春天的鬱金香花園"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangmyeong-cave', 'gwangmyeong-cave', 'gyeonggi', 'Hang mỏ Gwangmyeong', 'Gwangmyeong Cave', 'cave', 126.856, 37.416, 'Mỏ vàng thời thuộc địa bị bỏ hoang bốn mươi năm, nay là hang nhân tạo với hầm rượu và thác ánh sáng.', 'Mỏ Gwangmyeong được người Nhật mở năm 1912 để lấy vàng, bạc và kẽm; sau khi đóng cửa năm 1972 nó thành nơi chứa mắm tôm suốt bốn thập niên vì nhiệt độ trong hầm ổn định quanh mười hai độ. Năm 2011 thành phố mua lại và biến đường hầm thành một không gian trưng bày: có hầm ủ rượu vang của các nhà làm rượu trong nước, một hang nhạc nước, khu chiếu sáng nghệ thuật, và một con rồng khổng lồ từng dùng trong phim. Trời ngoài kia bốn mươi độ thì trong này vẫn mười hai — riêng điều đó cũng đủ lý do đi vào mùa hè.', '["Mỏ mở năm 1912, khai thác vàng, bạc và kẽm, đóng cửa năm 1972.","Nhiệt độ trong hầm giữ quanh 12°C quanh năm.","Từng được dùng làm kho ủ mắm tôm suốt gần 40 năm.","Thành phố Gwangmyeong mở lại thành điểm tham quan năm 2011."]', '["Mang áo khoác kể cả giữa mùa hè — trong hầm rất lạnh.","Đường hầm khá dài và có dốc; giày bệt sẽ dễ chịu hơn.","Cuối tuần đông, nên đi buổi sáng sớm."]', 'Tháng 6–8 (tránh nóng) hoặc quanh năm', '2 giờ', '6.000 KRW', '09:00–18:00, vào cửa cuối 17:00, đóng cửa thứ Hai', '["hidden-gem"]', '["hang động","mỏ cũ","mát mẻ","gia đình"]', '[{"seed":"gwangmyeong-cave","caption":"Đường hầm mỏ được chiếu sáng","ratio":"16/9"}]', '["oido","hwaseong-fortress"]', 0, 'https://us.trip.com/travel-guide/attraction/gwangmyeong/gwangmyeong-cave-50695217/', '2026-08-04', '{"en":{"name":"Gwangmyeong Cave","summary":"A colonial-era gold mine left empty for forty years, now a man-made cave with a wine cellar and a wall of light.","story":"The Gwangmyeong mine was opened by the Japanese in 1912 for gold, silver and zinc; after it closed in 1972 it spent four decades as a store for salted shrimp, because the tunnels hold a steady twelve degrees. In 2011 the city bought it back and turned the workings into an exhibition space: a cellar for Korean winemakers, a cave with a water-and-music show, an art lighting section, and an enormous dragon left over from a film. When it is forty degrees outside it is still twelve in here — reason enough to come in summer.","facts":["The mine opened in 1912 for gold, silver and zinc, and closed in 1972.","The tunnels stay around 12°C all year.","It was used as a salted shrimp store for nearly 40 years.","Gwangmyeong city reopened it as a visitor attraction in 2011."],"travelTips":["Bring a jacket even in midsummer — it is genuinely cold inside.","The tunnel is long and sloping; flat shoes help.","Weekends are busy, so come early in the morning."],"bestTime":"June–August (to escape the heat), or year-round","visitDuration":"2 hours","ticket":"6,000 KRW","openingHours":"09:00–18:00, last entry 17:00, closed Mondays","galleryCaptions":["The lit mine tunnel"]},"ko":{"name":"광명동굴","summary":"일제강점기 금광이 사십 년간 버려졌다가, 와인 저장고와 빛의 벽이 있는 인공 동굴이 되었다.","story":"광명광산은 1912년 일본인이 금과 은, 아연을 캐려고 열었고, 1972년 문을 닫은 뒤 사십 년 가까이 새우젓 저장고로 쓰였다. 갱도 안 온도가 늘 12도 안팎으로 일정했기 때문이다. 2011년 시가 다시 사들여 갱도를 전시 공간으로 바꿨다. 국내 와이너리의 저장고, 물과 음악 쇼가 있는 동굴, 조명 예술 구간, 그리고 영화에 쓰였던 거대한 용이 있다. 바깥이 사십 도여도 이 안은 여전히 십이 도다. 여름에 올 이유로는 그것만으로 충분하다.","facts":["1912년 금·은·아연 광산으로 개발되어 1972년 폐광했다.","갱도 내부는 연중 12도 안팎을 유지한다.","폐광 후 40년 가까이 새우젓 저장고로 쓰였다.","광명시가 2011년 관광지로 다시 열었다."],"travelTips":["한여름에도 겉옷을 챙기자. 안은 정말 춥다.","갱도가 길고 경사가 있으니 굽 낮은 신발이 편하다.","주말에는 붐비니 이른 오전에 가자."],"bestTime":"6~8월(더위 피하기), 혹은 연중","visitDuration":"2시간","ticket":"6,000원","openingHours":"09:00~18:00, 입장 마감 17:00, 월요일 휴관","galleryCaptions":["조명이 들어온 갱도"]},"ja":{"name":"光明洞窟","summary":"植民地期の金鉱が四十年放置され、いまはワイン貯蔵庫と光の壁を持つ人工洞窟になった。","story":"光明鉱山は1912年に日本人が金・銀・亜鉛のために開き、1972年の閉山後は四十年近くアミの塩辛の貯蔵庫として使われた。坑道の温度が年中十二度前後で一定だったからだ。2011年に市が買い戻し、坑道を展示空間に変えた。国内ワイナリーの貯蔵庫、水と音楽のショーが行われる洞窟、照明アートの区間、そして映画で使われた巨大な龍がある。外が四十度でも、ここは十二度のままだ。夏に訪ねる理由としてはそれだけで十分である。","facts":["1912年に金・銀・亜鉛の鉱山として開発され、1972年に閉山した。","坑道内は年間を通じて12度前後を保つ。","閉山後は40年近くアミの塩辛の貯蔵庫として使われた。","光明市が2011年に観光地として再開した。"],"travelTips":["真夏でも上着を持とう。中は本当に寒い。","坑道は長く傾斜がある。かかとの低い靴が楽だ。","週末は混むので、朝早い時間に。"],"bestTime":"6〜8月（暑さしのぎ）、または通年","visitDuration":"2時間","ticket":"6,000ウォン","openingHours":"09:00〜18:00、最終入場17:00、月曜休館","galleryCaptions":["照明の入った坑道"]},"zh":{"name":"光明洞窟","summary":"殖民時期的金礦荒廢四十年，如今成了設有酒窖與光之牆的人造洞窟。","story":"光明礦坑1912年由日本人開採金、銀與鋅，1972年停採後，因坑道常年維持攝氏十二度左右，被拿來存放蝦醬近四十年。2011年市府買回，把坑道改造成展示空間：韓國酒莊的酒窖、有水舞表演的洞窟、燈光藝術區段，還有一條電影用過的巨龍。外頭四十度時，這裡仍是十二度——光憑這點，夏天就值得走一趟。","facts":["礦坑1912年開採金、銀、鋅，1972年停採。","坑道內全年維持攝氏12度上下。","停採後曾作為蝦醬倉庫使用近40年。","光明市於2011年重新開放為觀光景點。"],"travelTips":["盛夏也要帶外套——裡面是真的冷。","坑道長且有坡度，平底鞋比較舒服。","週末人多，建議一早前往。"],"bestTime":"6至8月（避暑），或全年皆宜","visitDuration":"2小時","ticket":"6,000韓元","openingHours":"09:00–18:00，最後入場17:00，週一休館","galleryCaptions":["點上燈的礦坑坑道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('oido', 'oido', 'gyeonggi', 'Oido & bãi triều Siheung', 'Oido & the Siheung Tidal Flats', 'beach', 126.6885, 37.3455, 'Ngọn hải đăng đỏ hình chiếc đồng hồ cát đứng cuối con đê, sau lưng là bãi triều mênh mông và những vựa nghêu.', 'Oido từng là một hòn đảo thật, rồi việc lấn biển nối nó vào đất liền và biến nơi đây thành điểm đi trong ngày quen thuộc của dân vùng thủ đô. Con đê chạy thẳng ra biển, cuối đê là ngọn hải đăng đỏ hình chiếc đồng hồ cát đã thành biểu tượng. Khi triều rút, bãi bùn trải ra tới tận chân trời và người ta lội ra cào nghêu; khi triều lên, nước vỗ ngay dưới lan can. Dọc bờ là dãy quán hải sản nướng, và hoàng hôn ở đây rơi thẳng xuống biển Hoàng Hải — điều mà bờ đông Hàn Quốc không có.', '["Từng là đảo, nối với đất liền sau các dự án lấn biển.","Hải đăng Oido hình chiếc đồng hồ cát cao khoảng 30m, có đài quan sát.","Bãi triều Siheung là một phần của hệ bãi triều bờ tây rộng lớn.","Khu vực này có di chỉ vỏ sò thời tiền sử được khai quật."]', '["Tra lịch thuỷ triều: triều rút để lội bãi, triều lên để chụp hải đăng.","Tàu điện tuyến Suin-Bundang tới ga Oido rồi bắt bus ra bờ biển.","Cuối tuần các quán hải sản kín chỗ từ chiều."]', 'Tháng 4–6 và 9–10', '2–3 giờ', '', 'Cả ngày', '["hidden-gem"]', '["bãi triều","hải đăng","hoàng hôn","hải sản"]', '[{"seed":"oido","caption":"Hải đăng đỏ cuối đê Oido","ratio":"16/9"}]', '["gwangmyeong-cave"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Oido & the Siheung Tidal Flats","summary":"A red hourglass-shaped lighthouse at the end of a causeway, with vast tidal flats and clam beds behind it.","story":"Oido was once a real island; land reclamation joined it to the mainland and turned it into a standard day trip for the capital region. The causeway runs straight out to sea, and at its end stands the red hourglass lighthouse that has become the local emblem. At low tide the mudflat runs to the horizon and people wade out to rake for clams; at high tide the water slaps just under the railing. Grilled seafood restaurants line the shore, and the sun sets straight into the Yellow Sea — something Korea''s east coast cannot offer.","facts":["Formerly an island, joined to the mainland by reclamation projects.","The hourglass-shaped Oido lighthouse is about 30m tall and has a viewing deck.","The Siheung flats are part of the extensive west coast tidal system.","Prehistoric shell middens have been excavated in the area."],"travelTips":["Check the tide table: low water for the flats, high water for lighthouse photos.","Take the Suin-Bundang line to Oido station, then a bus to the shore.","At weekends the seafood restaurants fill up from the afternoon."],"bestTime":"April–June and September–October","visitDuration":"2–3 hours","ticket":"","openingHours":"All day","galleryCaptions":["The red lighthouse at the end of the Oido causeway"]},"ko":{"name":"오이도와 시흥 갯벌","summary":"제방 끝에 선 모래시계 모양의 빨간 등대. 그 뒤로는 드넓은 갯벌과 조개밭이 이어진다.","story":"오이도는 원래 진짜 섬이었지만 간척으로 육지와 이어지면서 수도권 사람들의 흔한 당일치기 코스가 되었다. 제방이 바다로 곧게 뻗고, 그 끝에 이 지역의 상징이 된 모래시계 모양의 빨간 등대가 서 있다. 물이 빠지면 갯벌이 수평선까지 펼쳐져 사람들이 조개를 캐러 나가고, 물이 들면 난간 바로 아래까지 파도가 친다. 해안을 따라 조개구이집이 늘어서 있고, 해는 서해로 곧장 떨어진다. 동해안에서는 볼 수 없는 장면이다.","facts":["본래 섬이었으나 간척 사업으로 육지와 이어졌다.","모래시계 모양의 오이도 등대는 높이 약 30m로 전망대가 있다.","시흥 갯벌은 광활한 서해안 갯벌 체계의 일부다.","인근에서 선사시대 조개무지가 발굴되었다."],"travelTips":["물때표를 확인하자. 갯벌 체험은 썰물, 등대 사진은 밀물이 좋다.","수인분당선 오이도역에서 내려 해안까지 버스를 타자.","주말에는 오후부터 조개구이집이 꽉 찬다."],"bestTime":"4~6월, 9~10월","visitDuration":"2~3시간","ticket":"","openingHours":"상시","galleryCaptions":["오이도 제방 끝의 빨간 등대"]},"ja":{"name":"烏耳島と始興の干潟","summary":"堤防の先に立つ砂時計の形をした赤い灯台。その背後には広大な干潟と貝の漁場が広がる。","story":"烏耳島はもともと本当の島だったが、干拓で陸と繋がり、首都圏の人々のありふれた日帰り先になった。堤防が海へまっすぐ伸び、その先にこの地の象徴となった砂時計形の赤い灯台が立つ。潮が引けば干潟が水平線まで広がり、人々は貝を掘りに出ていく。潮が満ちれば波が手すりのすぐ下まで打ち寄せる。海岸沿いには貝焼きの店が並び、陽は黄海へまっすぐ沈む。韓国の東海岸にはない眺めだ。","facts":["もとは島だったが、干拓事業で陸地と繋がった。","砂時計形の烏耳島灯台は高さ約30mで展望台がある。","始興の干潟は広大な西海岸干潟系の一部である。","周辺で先史時代の貝塚が発掘されている。"],"travelTips":["潮汐表を確認しよう。干潟体験は引き潮、灯台の撮影は満ち潮がよい。","水仁盆唐線・烏耳島駅からバスで海岸へ。","週末は午後から貝焼きの店が満席になる。"],"bestTime":"4〜6月と9〜10月","visitDuration":"2〜3時間","ticket":"","openingHours":"終日","galleryCaptions":["烏耳島の堤防の先に立つ赤い灯台"]},"zh":{"name":"烏耳島與始興灘塗","summary":"堤道盡頭立著沙漏造型的紅色燈塔，身後是遼闊的潮間灘塗與蛤蜊田。","story":"烏耳島原本真的是座島，填海造陸把它接上了大陸，也讓它成為首都圈再普通不過的一日行程。堤道筆直伸進海裡，盡頭那座沙漏造型的紅色燈塔已成當地標誌。退潮時泥灘一路延伸到地平線，人們涉水出去耙蛤蜊；漲潮時海水就拍在欄杆底下。岸邊排滿烤海鮮店，太陽直直落進黃海——這是韓國東岸給不了的景色。","facts":["原為島嶼，因填海工程與陸地相連。","沙漏造型的烏耳島燈塔高約30公尺，設有觀景台。","始興灘塗是廣闊西海岸潮間帶系統的一部分。","周邊曾挖掘出史前貝塚。"],"travelTips":["先查潮汐表：退潮走灘塗，漲潮拍燈塔。","搭水仁盆唐線至烏耳島站，再轉公車到海邊。","週末海鮮店從下午就開始客滿。"],"bestTime":"4至6月與9至10月","visitDuration":"2至3小時","ticket":"","openingHours":"全日開放","galleryCaptions":["烏耳島堤道盡頭的紅色燈塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('dumulmeori', 'dumulmeori', 'gyeonggi', 'Ngã ba sông Dumulmeori', 'Dumulmeori Confluence', 'lake', 127.313, 37.535, 'Nơi hai nhánh sông Hàn gặp nhau, có cây zelkova bốn trăm tuổi và sương sớm dày đến mức xoá cả bờ bên kia.', 'Dumulmeori nghĩa đen là ''đầu hai dòng nước'': nhánh Bắc Hàn Giang từ Kumgangsan chảy xuống gặp nhánh Nam Hàn Giang từ Taebaeksan, rồi cùng nhau thành sông Hàn chảy về Seoul. Chỗ hợp lưu ấy rộng như một cái hồ, và vào những sáng lạnh, hơi nước bốc lên phủ kín mặt sông tới mức chỉ còn thấy ngọn cây zelkova bốn trăm tuổi nhô lên. Người ta đến đây từ trước bình minh với chân máy ảnh. Ngày thường thì nơi này bình lặng: lối đi ven nước, thuyền gỗ neo làm cảnh, ruộng sen nở tháng bảy và những quán cà phê nhìn ra sông.', '["Là điểm hợp lưu của Bắc Hàn Giang và Nam Hàn Giang thành sông Hàn.","Cây zelkova bên bờ được cho là hơn 400 năm tuổi.","Sương sông vào sáng sớm mùa lạnh là cảnh nhiếp ảnh nổi tiếng nhất vùng.","Ruộng sen Semiwon ngay cạnh nở rộ vào tháng 7–8."]', '["Đến trước bình minh nếu muốn chụp sương — sau 8h sương tan hết.","Tàu điện tuyến Gyeongui-Jungang tới ga Yangsu, đi bộ khoảng 20 phút.","Kết hợp vườn sen Semiwon (tính vé riêng) trong cùng buổi sáng."]', 'Tháng 10–2 (sương sớm) và tháng 7–8 (sen)', '2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["sông","sương sớm","nhiếp ảnh","sen"]', '[{"seed":"dumulmeori","caption":"Cây zelkova trong sương sông","ratio":"16/9"}]', '["yongmunsa"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Dumulmeori Confluence","summary":"Where the two branches of the Han meet, with a four-hundred-year-old zelkova and mist thick enough to erase the far bank.","story":"Dumulmeori means ''the head of two waters'': the North Han flowing down from Kumgangsan meets the South Han from Taebaeksan, and together they become the river that runs through Seoul. The junction is wide as a lake, and on cold mornings the vapour rising off it covers the water so completely that only the crown of the four-hundred-year-old zelkova shows above it. People arrive before dawn with tripods. On an ordinary day it is simply calm: a waterside path, wooden boats moored for effect, lotus fields flowering in July, and cafés facing the river.","facts":["It is where the North Han and South Han rivers join to form the Han.","The zelkova on the bank is said to be more than 400 years old.","River mist on cold early mornings is the region''s best-known photographic sight.","The Semiwon lotus gardens next door bloom in July and August."],"travelTips":["Arrive before dawn for the mist — it is gone by 8am.","Take the Gyeongui-Jungang line to Yangsu station, then walk about 20 minutes.","Add the Semiwon lotus garden (separate ticket) to the same morning."],"bestTime":"October–February (morning mist) and July–August (lotus)","visitDuration":"2 hours","ticket":"","openingHours":"All day","galleryCaptions":["The zelkova in river mist"]},"ko":{"name":"두물머리","summary":"한강의 두 물줄기가 만나는 곳. 사백 년 된 느티나무가 서 있고, 물안개가 건너편을 지운다.","story":"두물머리는 말 그대로 ''두 물의 머리''다. 금강산에서 내려온 북한강과 태백산에서 내려온 남한강이 여기서 만나 서울로 흐르는 한강이 된다. 합류 지점은 호수처럼 넓고, 추운 아침이면 피어오른 물안개가 수면을 완전히 덮어 사백 년 된 느티나무의 우듬지만 겨우 보인다. 사람들은 해뜨기 전부터 삼각대를 들고 온다. 평범한 날에는 그저 고요하다. 물가 산책로, 풍경으로 매어 둔 나룻배, 7월에 피는 연밭, 그리고 강을 바라보는 카페들이 있다.","facts":["북한강과 남한강이 합쳐져 한강이 되는 지점이다.","강가의 느티나무는 400년이 넘은 것으로 전한다.","추운 새벽의 물안개는 이 지역에서 가장 이름난 사진 풍경이다.","바로 옆 세미원의 연밭은 7~8월에 만개한다."],"travelTips":["물안개를 보려면 해뜨기 전에 도착하자. 8시면 사라진다.","경의중앙선 양수역에서 내려 20분쯤 걸으면 된다.","같은 아침에 세미원 연꽃정원(별도 요금)을 함께 보자."],"bestTime":"10~2월(새벽 물안개), 7~8월(연꽃)","visitDuration":"2시간","ticket":"","openingHours":"상시","galleryCaptions":["물안개 속의 느티나무"]},"ja":{"name":"トゥムルモリ（両水里の合流点）","summary":"漢江の二つの流れが出会う場所。四百年の欅が立ち、川霧が対岸を消してしまう。","story":"トゥムルモリは文字どおり「二つの水の頭」だ。金剛山から下る北漢江と、太白山から下る南漢江がここで出会い、ソウルへ流れる漢江になる。合流点は湖のように広く、寒い朝には立ちのぼる川霧が水面を覆い尽くし、四百年の欅の梢だけがかろうじて見える。人々は夜明け前から三脚を抱えてやって来る。普通の日はただ静かだ。水辺の遊歩道、景色として繋がれた木舟、七月に咲く蓮田、そして川を望むカフェがある。","facts":["北漢江と南漢江が合わさって漢江になる地点である。","岸辺の欅は樹齢400年を超えると伝わる。","寒い早朝の川霧は、この一帯で最も知られた写真の風景だ。","隣接する洗美苑の蓮田は7〜8月に見ごろを迎える。"],"travelTips":["川霧を見るなら夜明け前に着こう。8時には消える。","京義中央線・両水駅から徒歩20分ほど。","同じ朝に洗美苑の蓮の庭（別料金）も合わせよう。"],"bestTime":"10〜2月（早朝の川霧）と7〜8月（蓮）","visitDuration":"2時間","ticket":"","openingHours":"終日","galleryCaptions":["川霧の中の欅"]},"zh":{"name":"兩水頭","summary":"漢江兩條支流交會之處，一棵四百歲的櫸樹立在岸邊，水霧濃到把對岸抹去。","story":"兩水頭字面意思是「兩股水的頭」：自金剛山而下的北漢江，與自太白山而下的南漢江在此相遇，合成流過首爾的漢江。交會處寬闊如湖，寒冷的清晨水氣蒸騰，把整片水面蓋住，只剩那棵四百歲櫸樹的樹梢露在外頭。人們天未亮就扛著腳架來。平常日子這裡只是安靜：水邊步道、當作景致繫著的木船、七月盛開的蓮田，以及望著江面的咖啡館。","facts":["是北漢江與南漢江匯流成漢江之處。","岸邊的櫸樹相傳已有四百餘年。","寒冷清晨的江霧是此地最負盛名的攝影景色。","隔壁的洗美苑蓮田於7至8月盛開。"],"travelTips":["想拍霧就得在天亮前抵達，八點後就散了。","搭京義中央線到兩水站，再步行約20分鐘。","同一個早上可順道逛洗美苑蓮花園（另行購票）。"],"bestTime":"10月至隔年2月（晨霧）與7至8月（蓮花）","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["江霧中的櫸樹"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('yongmunsa', 'yongmunsa', 'gyeonggi', 'Chùa Yongmunsa & cây ngân hạnh nghìn tuổi', 'Yongmunsa Temple & the Great Ginkgo', 'temple', 127.554, 37.561, 'Cây ngân hạnh cao hơn bốn mươi mét, già nhất Hàn Quốc, đứng che gần trọn sân một ngôi chùa trong núi.', 'Đường lên Yongmunsa đi men theo con suối trong vắt chừng hai mươi phút, rồi sân chùa mở ra và bạn hiểu vì sao ai cũng nói về cái cây trước khi nói về ngôi chùa. Cây ngân hạnh này cao hơn bốn mươi mét, chu vi thân hơn mười bốn mét, và được cho là đã hơn một nghìn một trăm năm tuổi — tương truyền do thái tử Maui của Silla cắm gậy xuống đất mà thành. Nó sống sót qua cuộc đốt chùa thời chiến tranh Triều Tiên khi mọi công trình quanh đó cháy rụi. Giữa tháng 11, cả tán cây chuyển vàng rực và rụng phủ kín sân, và cả thung lũng kéo nhau tới xem.', '["Cây ngân hạnh cao khoảng 42m, chu vi thân hơn 14m.","Được cho là hơn 1.100 năm tuổi, là cây ngân hạnh già nhất Hàn Quốc.","Được công nhận là Đài kỷ niệm thiên nhiên số 30.","Cây sống sót khi chùa Yongmunsa bị thiêu rụi trong chiến tranh Triều Tiên."]', '["Đi vào giữa tháng 11 để thấy lá vàng rực nhất.","Đường từ cổng vườn lên chùa dốc nhẹ, mất khoảng 20–30 phút đi bộ.","Tàu Gyeongui-Jungang tới ga Yongmun rồi bắt bus địa phương."]', 'Giữa tháng 11 (lá vàng)', '2–3 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["hidden-gem","verified"]', '["chùa","cây cổ thụ","mùa thu","đi bộ"]', '[{"seed":"yongmunsa","caption":"Cây ngân hạnh nghìn tuổi trước chùa","ratio":"16/9"}]', '["dumulmeori"]', 1, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Yongmunsa Temple & the Great Ginkgo","summary":"A ginkgo over forty metres tall, the oldest in Korea, shading most of a mountain temple''s courtyard.","story":"The path up to Yongmunsa follows a clear stream for about twenty minutes, then the courtyard opens and you understand why everyone talks about the tree before the temple. This ginkgo is over forty metres tall, more than fourteen metres around the trunk, and is held to be over eleven hundred years old — planted, the story goes, when Prince Maui of Silla pushed his staff into the ground. It survived the burning of the temple in the Korean War, when everything around it went up. In mid-November the whole canopy turns gold and drops across the courtyard, and the entire valley comes to look.","facts":["The ginkgo is about 42m tall with a trunk over 14m in girth.","It is thought to be more than 1,100 years old, the oldest ginkgo in Korea.","It is designated Natural Monument No. 30.","The tree survived when Yongmunsa temple was burned down during the Korean War."],"travelTips":["Come in mid-November for the brightest gold.","The walk from the park gate to the temple is a gentle 20–30 minute climb.","Take the Gyeongui-Jungang line to Yongmun station, then a local bus."],"bestTime":"Mid-November (golden leaves)","visitDuration":"2–3 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["The thousand-year ginkgo before the temple"]},"ko":{"name":"용문사와 천년 은행나무","summary":"높이 사십 미터가 넘는 한국에서 가장 오래된 은행나무가 산사의 마당을 거의 다 덮는다.","story":"용문사로 오르는 길은 맑은 계곡을 따라 이십 분쯤 이어지고, 그러다 마당이 열리면 왜 다들 절보다 나무 이야기를 먼저 하는지 알게 된다. 이 은행나무는 높이가 사십 미터를 넘고 밑동 둘레가 십사 미터가 넘으며, 천백 년이 넘은 것으로 전한다. 신라 마의태자가 짚고 온 지팡이를 꽂은 것이 자랐다는 이야기가 있다. 한국전쟁 때 절이 불타 주변이 모두 사라졌을 때도 이 나무는 살아남았다. 11월 중순이면 나무 전체가 노랗게 물들어 마당을 덮고, 온 골짜기가 보러 온다.","facts":["은행나무는 높이 약 42m, 밑동 둘레는 14m가 넘는다.","1,100년이 넘은 것으로 전해지는 한국에서 가장 오래된 은행나무다.","천연기념물 제30호로 지정되어 있다.","한국전쟁으로 용문사가 소실되었을 때도 나무는 살아남았다."],"travelTips":["11월 중순에 가야 단풍이 가장 노랗다.","공원 입구에서 절까지는 완만한 오르막으로 20~30분 걸린다.","경의중앙선 용문역에서 내려 지역 버스를 타자."],"bestTime":"11월 중순(노란 단풍)","visitDuration":"2~3시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["절 앞의 천년 은행나무"]},"ja":{"name":"龍門寺と千年の銀杏","summary":"高さ四十メートルを超える韓国最古の銀杏が、山寺の境内をほとんど覆っている。","story":"龍門寺への道は澄んだ渓流に沿って二十分ほど続き、境内が開けた瞬間、なぜ誰もが寺より先に木の話をするのかが分かる。この銀杏は高さ四十メートルを超え、幹回りは十四メートルを超え、樹齢は千百年以上と伝わる。新羅の麻衣太子が突き立てた杖が根づいたのだという話もある。朝鮮戦争で寺が焼け、周囲がすべて失われたときもこの木は生き延びた。十一月半ばには樹冠がまるごと黄金色になって境内に降り積もり、谷じゅうの人が見に来る。","facts":["銀杏は高さ約42m、幹回りは14mを超える。","樹齢1,100年以上と伝わる韓国最古の銀杏である。","天然記念物第30号に指定されている。","朝鮮戦争で龍門寺が焼失した際も、この木は生き残った。"],"travelTips":["十一月中旬が最も黄色い。","公園入口から寺までは緩やかな上りで20〜30分。","京義中央線・龍門駅から地域バスに乗ろう。"],"bestTime":"11月中旬（黄葉）","visitDuration":"2〜3時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["寺の前に立つ千年の銀杏"]},"zh":{"name":"龍門寺與千年銀杏","summary":"一棵高逾四十公尺、韓國最古老的銀杏，幾乎遮蔽了整座山寺的庭院。","story":"上龍門寺的路沿著清澈溪流走約二十分鐘，庭院一開，你就明白為什麼大家談樹都談在談寺之前。這棵銀杏高逾四十公尺，樹幹周長超過十四公尺，相傳樹齡已超過一千一百年——傳說是新羅麻衣太子把手杖插進土裡長成的。韓戰時寺院焚毀、四周盡成灰燼，它卻活了下來。十一月中旬，整片樹冠轉成金黃，落滿整座庭院，整個山谷的人都來看。","facts":["銀杏高約42公尺，樹幹周長超過14公尺。","相傳樹齡逾1,100年，是韓國最古老的銀杏。","被指定為天然紀念物第30號。","韓戰中龍門寺焚毀時，此樹倖存。"],"travelTips":["十一月中旬金黃最盛。","自園區大門走到寺院是緩上坡，約需20至30分鐘。","搭京義中央線到龍門站，再轉當地公車。"],"bestTime":"11月中旬（黃葉）","visitDuration":"2至3小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["寺前的千年銀杏"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('imjingak-dmz', 'imjingak-dmz', 'gyeonggi', 'Imjingak & vùng phi quân sự DMZ', 'Imjingak & the DMZ', 'park', 126.74, 37.889, 'Điểm cuối cùng dân thường tới được trước ranh giới chia đôi bán đảo, cách Seoul chưa đầy một giờ.', 'Ở Imjingak, con đường sắt dừng lại giữa chừng: đầu máy hơi nước lỗ chỗ vết đạn nằm trên đoạn ray cụt, phía sau là cầu Tự do bắc qua sông Imjin, nơi tù binh trở về năm 1953. Hàng rào thép gai treo kín ruy băng và thư viết tay của những gia đình ly tán, nhiều người đến đây làm lễ cúng vọng về quê nhà phía Bắc mỗi dịp Tết. Từ đài quan sát, ống nhòm hướng thẳng sang bờ bên kia. Nghịch lý là vùng đệm không người suốt bảy thập kỷ ấy đã thành khu bảo tồn thiên nhiên hiếm hoi, nơi sếu đầu đỏ về trú đông.', '["Nằm cách ranh giới quân sự khoảng 7 km, dân thường vào được không cần giấy phép.","Cầu Tự do là nơi khoảng 12.773 tù binh trở về năm 1953.","Vùng phi quân sự rộng khoảng 4 km, dài 250 km cắt ngang bán đảo.","Các tour vào JSA hay đường hầm số 3 phải đăng ký trước và mang hộ chiếu."]', '["Mang theo hộ chiếu — bắt buộc với mọi tour đi sâu vào DMZ.","Đặt tour trước vài ngày; lịch có thể bị huỷ đột ngột vì lý do an ninh.","Có quy định về trang phục và chụp ảnh ở một số khu vực, nghe kỹ hướng dẫn viên."]', 'Tháng 4–6 và 9–11', 'Nửa ngày', 'Miễn phí tại Imjingak (tour DMZ tính riêng)', 'Công viên Pyeonghwa-Nuri mở cả ngày, vào tự do; các tour DMZ và điểm trong khu kiểm soát phải đăng ký trước và đi theo giờ quy định', '["verified"]', '["lịch sử","chiến tranh","DMZ"]', '[{"seed":"imjingak-dmz","caption":"Cầu Tự do bắc qua sông Imjin","ratio":"16/9"}]', '["heyri-art-valley","paju-book-city"]', 0, 'https://tour.paju.go.kr/user/tour/place/BD_tourPlaceInfoView.do?menuCode=78&cntntsSn=52', '2026-08-05', '{"en":{"name":"Imjingak & the DMZ","summary":"The last point civilians can reach before the line that splits the peninsula, less than an hour from Seoul.","story":"At Imjingak the railway simply stops: a bullet-riddled steam locomotive sits on a severed track, and behind it the Freedom Bridge crosses the Imjin River, where prisoners of war came home in 1953. The barbed wire is covered with ribbons and handwritten letters from separated families, and many come here at Lunar New Year to bow towards home in the north. From the observatory, binoculars point straight across. The paradox is that seven decades of empty buffer zone have made an accidental nature reserve, where red-crowned cranes winter.","facts":["About 7 km from the military demarcation line; civilians need no permit.","Some 12,773 prisoners of war returned across the Freedom Bridge in 1953.","The Demilitarized Zone is about 4 km wide and 250 km long across the peninsula.","Tours into the JSA or the Third Tunnel must be booked in advance with a passport."],"travelTips":["Carry your passport — it is required for every tour that goes deeper into the DMZ.","Book a few days ahead; schedules can be cancelled at short notice for security reasons.","There are dress and photography rules in some areas — listen to your guide."],"bestTime":"April–June and September–November","visitDuration":"Half a day","ticket":"Free at Imjingak (DMZ tours priced separately)","openingHours":"Pyeonghwa-Nuri park is open all day and free to enter; DMZ tours and the sites inside the controlled zone must be booked in advance and run to fixed departure times","galleryCaptions":["The Freedom Bridge over the Imjin River"]},"ko":{"name":"임진각과 비무장지대","summary":"서울에서 한 시간도 걸리지 않는, 민간인이 닿을 수 있는 마지막 지점.","story":"임진각에서는 철길이 도중에 끊긴다. 총탄 자국이 남은 증기기관차가 끊어진 선로 위에 서 있고, 그 뒤로 1953년 포로들이 돌아온 자유의 다리가 임진강을 건넌다. 철조망에는 이산가족이 남긴 리본과 손편지가 빼곡하고, 명절이면 북쪽 고향을 향해 절을 올리는 사람들이 모인다. 전망대의 망원경은 강 건너를 곧장 향한다. 역설적이게도 70년간 사람이 들지 않은 완충지대는 두루미가 겨울을 나는 보기 드문 자연보호구역이 되었다.","facts":["군사분계선에서 약 7km 떨어져 있으며 민간인은 허가 없이 갈 수 있다.","자유의 다리로 1953년 국군 포로 12,773명이 돌아왔다.","비무장지대는 폭 약 4km, 길이 250km로 한반도를 가로지른다.","JSA나 제3땅굴 견학은 사전 예약과 여권이 필요하다."],"travelTips":["여권을 반드시 챙기자. DMZ 내부 투어의 필수 요건이다.","며칠 전에 예약하되, 안보 사유로 갑자기 취소될 수 있다.","구역에 따라 복장과 촬영 규정이 있으니 안내를 잘 듣자."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절","ticket":"임진각 무료(DMZ 투어는 별도)","openingHours":"평화누리 공원은 상시 무료 개방되며, DMZ 투어와 통제구역 내 시설은 사전 예약 후 정해진 시간에만 이용할 수 있다","galleryCaptions":["임진강을 건너는 자유의 다리"]},"ja":{"name":"臨津閣と非武装地帯","summary":"ソウルから1時間もかからない、民間人が行ける最後の地点。","story":"臨津閣では線路が途中で途切れている。銃痕の残る蒸気機関車が断ち切られたレールの上に立ち、その先に1953年に捕虜が帰ってきた自由の橋が臨津江を渡る。鉄条網には離散家族が残したリボンと手書きの手紙がびっしりと結ばれ、名節には北の故郷へ向かって拝礼する人々が集まる。展望台の双眼鏡はまっすぐ対岸を向く。皮肉なことに、70年間人の入らなかった緩衝地帯は、ナベヅルが越冬する稀有な自然保護区になった。","facts":["軍事境界線から約7km。民間人は許可なしで行ける。","自由の橋を通って1953年に12,773人の捕虜が帰還した。","非武装地帯は幅約4km、長さ250kmで半島を横切る。","JSAや第三トンネルの見学は事前予約とパスポートが必要。"],"travelTips":["パスポートは必携。DMZ内部ツアーの必須条件だ。","数日前に予約を。ただし安全上の理由で急に中止されることがある。","区域により服装や撮影の規則がある。案内をよく聞こう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"半日","ticket":"臨津閣は無料（DMZツアーは別料金）","openingHours":"平和ヌリ公園は終日無料開放。DMZツアーや統制区域内の施設は事前予約が必要で、決められた時間にのみ利用できる","galleryCaptions":["臨津江を渡る自由の橋"]},"zh":{"name":"臨津閣與非軍事區","summary":"距首爾不到一小時，平民所能抵達、最靠近分界線的地方。","story":"在臨津閣，鐵路半途而止：一輛彈痕累累的蒸汽機車停在斷軌上，其後是自由之橋跨過臨津江——1953年戰俘由此歸來。鐵絲網上掛滿離散家庭繫上的絲帶與手寫信，逢年過節有人在此向北方故鄉遙祭。觀景台上的望遠鏡直直望向對岸。諷刺的是，七十年無人踏足的緩衝地帶，反而成了丹頂鶴越冬的珍稀自然保護區。","facts":["距軍事分界線約7公里，平民無須許可即可前往。","1953年約有12,773名戰俘經自由之橋返回。","非軍事區寬約4公里、長250公里，橫貫半島。","前往共同警備區或第三隧道須事先預約並攜帶護照。"],"travelTips":["務必攜帶護照，這是所有深入非軍事區行程的必要條件。","提前數日預約，但行程可能因安全因素臨時取消。","部分區域對服裝與拍攝有規定，請聽從導覽指示。"],"bestTime":"4至6月、9至11月","visitDuration":"半天","ticket":"臨津閣免費（非軍事區行程另計）","openingHours":"和平公園全日免費開放；DMZ導覽與管制區內景點須事先預約，並依固定梯次出發","galleryCaptions":["跨越臨津江的自由之橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('paju-book-city', 'paju-book-city', 'gyeonggi', 'Thành phố Sách Paju', 'Paju Book City', 'city', 126.69, 37.715, 'Cả một thị trấn do ngành xuất bản dựng lên, nơi mỗi toà nhà là một nhà xuất bản và kiến trúc sư được tự do làm điều mình muốn.', 'Đầu thập niên 1990, các nhà xuất bản Hàn Quốc quyết định làm một việc chưa ai làm: gom nhau về một chỗ và xây hẳn một thành phố cho sách. Kết quả là mấy trăm hecta ở Paju với nhà in, kho sách, toà soạn và nhà xuất bản — và vì mỗi đơn vị mời một kiến trúc sư riêng theo một bản quy ước chung, cả khu trở thành bảo tàng kiến trúc đương đại ngoài trời: bê tông trần, gạch mộc, thép gỉ, không toà nào giống toà nào. Trung tâm là Forest of Wisdom, một sảnh sách cao ba tầng với kệ chạy từ sàn lên trần, mở cửa suốt đêm cho ai muốn đọc.', '["Được quy hoạch từ đầu thập niên 1990 như một cụm ngành xuất bản.","Có hơn 250 nhà xuất bản, nhà in và cơ sở liên quan đặt trụ sở tại đây.","Thư viện Forest of Wisdom có kệ sách cao ba tầng và mở cửa 24 giờ.","Quy ước kiến trúc chung khiến khu này thành điểm tham quan kiến trúc đương đại."]', '["Đi vào ngày thường: cuối tuần nhiều nhà xuất bản đóng cửa showroom.","Forest of Wisdom mở cả đêm, rất đáng ghé nếu bạn ở lại muộn.","Kết hợp với Heyri Art Valley cách đó khoảng 15 phút xe."]', 'Quanh năm', '2–3 giờ', '', 'Khu phố mở cả ngày; ''Rừng Trí tuệ'' khu 1 và 2 mở 10:00–20:00, khu 3 mở 24/24. Các nhà xuất bản và hiệu sách khác có giờ riêng', '["hidden-gem"]', '["kiến trúc","sách","thiết kế"]', '[{"seed":"paju-book-city","caption":"Sảnh sách Forest of Wisdom","ratio":"16/9"}]', '["heyri-art-valley","imjingak-dmz"]', 0, 'http://intro.pajubookcity.org/', '2026-08-05', '{"en":{"name":"Paju Book City","summary":"A whole town built by the publishing industry, where every building is a publisher and the architects were let loose.","story":"In the early 1990s Korean publishers did something nobody had done: they moved out together and built a city for books. The result is a few hundred hectares at Paju holding printers, warehouses, editorial offices and publishing houses — and because each commissioned its own architect under a shared code, the whole place became an open-air museum of contemporary architecture: raw concrete, bare brick, weathered steel, no two buildings alike. At its centre is the Forest of Wisdom, a three-storey hall of shelves running floor to ceiling, open through the night for anyone who wants to read.","facts":["Planned from the early 1990s as a publishing-industry cluster.","More than 250 publishers, printers and related businesses are based here.","The Forest of Wisdom library has three-storey shelving and stays open 24 hours.","A shared architectural code turned the district into a contemporary architecture destination."],"travelTips":["Come on a weekday; many publishers close their showrooms at the weekend.","The Forest of Wisdom is open all night and worth a late visit.","Combine it with Heyri Art Valley, about 15 minutes away by car."],"bestTime":"Year-round","visitDuration":"2–3 hours","ticket":"","openingHours":"The district is open all day; Forest of Wisdom halls 1 and 2 run 10:00–20:00 and hall 3 is open 24 hours. Individual publishers and bookshops keep their own hours","galleryCaptions":["The Forest of Wisdom reading hall"]},"ko":{"name":"파주출판도시","summary":"출판 산업이 통째로 지어 올린 도시. 건물마다 출판사가 들어 있고, 건축가에게는 자유가 주어졌다.","story":"1990년대 초, 한국의 출판인들은 아무도 하지 않은 일을 했다. 다 함께 한곳으로 옮겨 가 책을 위한 도시를 지은 것이다. 그렇게 파주에 수백 헥타르의 인쇄소와 물류창고, 편집실, 출판사가 생겼다. 각자 공통의 건축 지침 아래 저마다 건축가를 불렀기 때문에, 이 일대는 야외 현대건축 박물관이 되었다. 노출 콘크리트, 민낯의 벽돌, 녹슨 강판. 같은 건물이 하나도 없다. 그 중심에 지혜의숲이 있다. 바닥부터 천장까지 이어지는 삼층 높이 서가의 열람실로, 읽고 싶은 사람을 위해 밤새 열려 있다.","facts":["1990년대 초부터 출판산업 단지로 계획되었다.","250곳이 넘는 출판사와 인쇄소, 관련 업체가 입주해 있다.","지혜의숲 도서관은 3층 높이 서가를 갖추고 24시간 열려 있다.","공통 건축 지침 덕분에 현대건축 답사지로도 유명하다."],"travelTips":["평일에 가자. 주말에는 쇼룸을 닫는 출판사가 많다.","지혜의숲은 밤새 열려 있어 늦게 들르기 좋다.","차로 15분 거리의 헤이리 예술마을과 묶어서 보자."],"bestTime":"연중","visitDuration":"2~3시간","ticket":"","openingHours":"단지는 상시 개방. 지혜의숲 1·2관은 10:00~20:00, 3관은 24시간 운영되며 출판사와 서점은 각자 운영시간을 둔다","galleryCaptions":["지혜의숲 열람실"]},"ja":{"name":"坡州出版都市","summary":"出版業界がまるごと建てた都市。建物ごとに出版社が入り、建築家には自由が与えられた。","story":"1990年代初め、韓国の出版人は誰もやらなかったことをした。揃って一か所へ移り、本のための都市を建てたのだ。こうして坡州に数百ヘクタールの印刷所、倉庫、編集部、出版社が生まれた。共通の建築指針のもとで各社が別々の建築家を呼んだため、この一帯は野外の現代建築博物館になった。打ち放しコンクリート、素地の煉瓦、錆びた鋼板。同じ建物がひとつもない。その中心にあるのが知恵の森だ。床から天井まで届く三層分の書架を備えた閲覧室で、読みたい人のために夜通し開いている。","facts":["1990年代初頭から出版産業団地として計画された。","250を超える出版社・印刷所・関連企業が拠点を置く。","知恵の森図書館は三層分の書架を備え、24時間開いている。","共通の建築指針により、現代建築の見どころとしても知られる。"],"travelTips":["平日に行こう。週末はショールームを閉める出版社が多い。","知恵の森は夜通し開いており、遅い時間の訪問にも向く。","車で15分のヘイリ芸術村と合わせて回ろう。"],"bestTime":"通年","visitDuration":"2〜3時間","ticket":"","openingHours":"団地は終日開放。知恵の森1・2館は10:00〜20:00、3館は24時間営業で、出版社や書店は各自の営業時間","galleryCaptions":["知恵の森の閲覧室"]},"zh":{"name":"坡州出版都市","summary":"由出版業整個蓋出來的城鎮，每一棟建築都是一家出版社，建築師則被放手去做。","story":"1990年代初，韓國出版人做了一件沒人做過的事：集體搬遷，蓋一座為書而生的城市。於是坡州出現了數百公頃的印刷廠、書庫、編輯部與出版社——由於各家在共同準則下各自委託建築師，整片區域成了露天的當代建築博物館：清水混凝土、素面磚、鏽蝕鋼板，沒有兩棟長得一樣。它的核心是「智慧之森」，一座書架從地板頂到天花板的三層閱覽廳，徹夜開放給任何想讀書的人。","facts":["自1990年代初起就以出版產業聚落的定位規劃。","逾250家出版社、印刷廠與相關業者設址於此。","智慧之森圖書館設有三層樓高書架，24小時開放。","共同的建築準則讓這裡成為當代建築的參訪地。"],"travelTips":["挑平日來，週末不少出版社的展售空間不開。","智慧之森整夜開放，很值得夜訪。","可與車程約15分鐘的Heyri藝術村排在一起。"],"bestTime":"全年","visitDuration":"2至3小時","ticket":"","openingHours":"園區全日開放；智慧之林1、2館10:00–20:00，3館24小時開放；各出版社與書店自訂營業時間","galleryCaptions":["智慧之森閱覽廳"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('heyri-art-valley', 'heyri-art-valley', 'gyeonggi', 'Làng nghệ thuật Heyri', 'Heyri Art Valley', 'village', 126.693, 37.79, 'Ngôi làng do nghệ sĩ tự xây, với quy ước không nhà nào cao quá ba tầng và không ai được sơn tường trắng.', 'Heyri là làng của khoảng ba trăm nghệ sĩ, nhà văn, nhạc sĩ và kiến trúc sư, những người tự bỏ tiền mua đất rồi cùng đặt ra luật chơi: không quá ba tầng, không hàng rào ngăn giữa các lô, vật liệu để mộc thay vì sơn phủ, và cây cối phải giữ nguyên. Kết quả là một khu vừa là chỗ ở vừa là xưởng vừa là phòng trưng bày — bạn đẩy cửa vào một căn nhà bê tông và bên trong là bảo tàng đồ chơi, căn kế bên là quán cà phê kiêm xưởng gốm, căn nữa là nhà riêng nên đừng gõ. Nằm sát vành đai DMZ, làng lấy tên từ một điệu hát cấy lúa cổ của vùng Paju.', '["Được khởi công cuối thập niên 1990 bởi một hợp tác xã nghệ sĩ.","Quy ước xây dựng giới hạn ba tầng và cấm hàng rào giữa các lô đất.","Tên làng lấy từ điệu hát cấy lúa cổ ''Heyri Sori'' của vùng Paju.","Có hàng chục bảo tàng tư nhân và phòng trưng bày nhỏ mở cửa cho khách."]', '["Nhiều phòng trưng bày đóng cửa thứ Hai — tránh đi đầu tuần.","Đây vẫn là nơi có người ở, chú ý biển ''nhà riêng'' trước khi bước vào.","Có bus từ ga Hapjeong (Seoul) chạy thẳng, khoảng 1 giờ."]', 'Tháng 4–6 và 9–11', '3 giờ', 'Miễn phí vào làng, bảo tàng tính vé riêng', 'Làng mở cả ngày; mỗi phòng trưng bày, bảo tàng và quán tự đặt giờ riêng, phần lớn nghỉ thứ Hai', '["hidden-gem"]', '["nghệ thuật","kiến trúc","bảo tàng","cà phê"]', '[{"seed":"heyri-art-valley","caption":"Nhà xưởng bê tông trong làng Heyri","ratio":"16/9"}]', '["paju-book-city","imjingak-dmz"]', 0, 'https://www.heyri.net/about', '2026-08-05', '{"en":{"name":"Heyri Art Valley","summary":"A village the artists built themselves, under a rule that nothing rises above three storeys and no wall gets painted white.","story":"Heyri is a village of some three hundred artists, writers, musicians and architects who bought the land themselves and then agreed the rules: nothing over three storeys, no fences between plots, materials left raw instead of painted, and the existing trees kept. The result is at once housing, studio and gallery — you push open the door of a concrete house and find a toy museum; the next is a café that is also a pottery workshop; the one after that is somebody''s home, so don''t knock. Sitting close to the DMZ belt, the village takes its name from an old rice-planting song of the Paju area.","facts":["Begun in the late 1990s by a cooperative of artists.","The building code limits height to three storeys and bans fences between plots.","The name comes from ''Heyri Sori'', an old Paju rice-planting song.","Dozens of small private museums and galleries are open to visitors."],"travelTips":["Many galleries close on Mondays — avoid the start of the week.","People live here; look for the ''private residence'' signs before walking in.","There is a direct bus from Hapjeong station in Seoul, about an hour."],"bestTime":"April–June and September–November","visitDuration":"3 hours","ticket":"Village free, museums ticketed separately","openingHours":"The village is open all day; every gallery, museum and café sets its own hours, and most close on Mondays","galleryCaptions":["A concrete studio house in Heyri"]},"ko":{"name":"헤이리 예술마을","summary":"예술가들이 직접 지은 마을. 3층을 넘기지 않고, 담장을 두르지 않는다는 약속 위에 서 있다.","story":"헤이리는 화가와 작가, 음악가, 건축가 삼백여 명이 스스로 땅을 사서 만든 마을이다. 그들은 규칙을 함께 정했다. 3층을 넘기지 않을 것, 필지 사이에 담장을 두지 않을 것, 페인트로 덮지 말고 재료를 그대로 드러낼 것, 있던 나무는 남길 것. 그래서 이곳은 주거이면서 작업실이고 동시에 갤러리다. 콘크리트 집 문을 밀고 들어가면 장난감박물관이고, 옆집은 도자 공방을 겸한 카페이며, 그 옆은 그냥 살림집이니 두드리지 말자. DMZ 접경에 가까운 이 마을의 이름은 파주 지역의 옛 모내기 노래에서 왔다.","facts":["1990년대 후반 예술인 조합이 조성을 시작했다.","건축 지침으로 3층 이하, 필지 간 담장 금지를 정했다.","마을 이름은 파주의 옛 모내기 노래 ''헤이리 소리''에서 따왔다.","수십 곳의 사립 박물관과 갤러리가 문을 열고 있다."],"travelTips":["월요일에 문을 닫는 갤러리가 많으니 주 초는 피하자.","사람이 사는 곳이다. 들어가기 전에 ''개인 주택'' 표시를 확인하자.","서울 합정역에서 직행 버스로 한 시간쯤 걸린다."],"bestTime":"4~6월, 9~11월","visitDuration":"3시간","ticket":"마을 무료, 박물관은 별도","openingHours":"마을은 상시 개방되고, 갤러리·박물관·카페마다 운영시간이 다르며 대부분 월요일에 쉰다","galleryCaptions":["헤이리의 콘크리트 작업실"]},"ja":{"name":"ヘイリ芸術村","summary":"芸術家たちが自ら建てた村。三階を超えない、塀を設けないという約束の上に立っている。","story":"ヘイリは画家、作家、音楽家、建築家およそ三百人が自ら土地を買って作った村だ。彼らは規則を共に決めた。三階を超えないこと、区画の間に塀を設けないこと、塗装で覆わず素材をそのまま見せること、もとからある木は残すこと。だからここは住まいであり、仕事場であり、同時にギャラリーでもある。コンクリートの家の扉を押せば玩具博物館、その隣は陶芸工房を兼ねたカフェ、さらに隣はただの住宅だから叩いてはいけない。DMZの帯に近いこの村の名は、坡州地方の古い田植え歌に由来する。","facts":["1990年代後半、芸術家の組合が造成を始めた。","建築指針で三階以下、区画間の塀の設置禁止を定めている。","村名は坡州の古い田植え歌「ヘイリ・ソリ」に由来する。","数十の私設博物館やギャラリーが来訪者に開かれている。"],"travelTips":["月曜休みのギャラリーが多いので週の初めは避けよう。","人が暮らしている。入る前に「個人住宅」の表示を確認しよう。","ソウルの合井駅から直通バスで一時間ほど。"],"bestTime":"4〜6月と9〜11月","visitDuration":"3時間","ticket":"村は無料、博物館は別料金","openingHours":"村は終日開放。ギャラリーや美術館、カフェはそれぞれ営業時間が異なり、多くは月曜休み","galleryCaptions":["ヘイリのコンクリートのアトリエ"]},"zh":{"name":"Heyri藝術村","summary":"藝術家自己蓋起來的村子，共同約定不超過三層樓，也不砌圍牆。","story":"Heyri是約三百位畫家、作家、音樂家與建築師自行買地建成的村落。他們一起訂下規矩：不超過三層樓、地塊之間不設圍牆、材料保持原色而非上漆、原有的樹要留著。於是這裡同時是住宅、工作室與畫廊——你推開一棟清水混凝土房子的門，裡頭是玩具博物館；隔壁是兼作陶藝工坊的咖啡館；再隔壁是人家住家，別敲。緊鄰DMZ地帶的這座村子，名字取自坡州一帶的古老插秧歌。","facts":["1990年代後期由藝術家合作社著手開發。","建築準則限制三層樓以下，並禁止地塊之間設圍牆。","村名取自坡州古老插秧歌「Heyri Sori」。","村內有數十間私人博物館與畫廊對外開放。"],"travelTips":["許多畫廊週一休息，避開週初。","這裡有人居住，進門前請先看清「私人住宅」標示。","自首爾合井站有直達巴士，約一小時。"],"bestTime":"4至6月與9至11月","visitDuration":"3小時","ticket":"村子免費，博物館另行售票","openingHours":"村落全日開放；各畫廊、美術館與咖啡館各自訂定營業時間，多數週一休息","galleryCaptions":["Heyri的清水混凝土工作室"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('petite-france', 'petite-france', 'gyeonggi', 'Làng Pháp Petite France (Gapyeong)', 'Petite France, Gapyeong', 'village', 127.4905, 37.715, 'Một ngôi làng Provence dựng trên sườn đồi Hàn Quốc, làm ra để tưởng nhớ Hoàng tử Bé.', 'Người sáng lập Petite France mê ''Hoàng tử Bé'' đến mức mua bản quyền hình ảnh và dựng cả một ngôi làng Pháp trên sườn đồi nhìn xuống hồ Cheongpyeong: nhà mái ngói cam, cửa chớp xanh, quảng trường nhỏ với đài phun nước, và một bảo tàng nhỏ về Saint-Exupéry cùng bộ sưu tập hộp nhạc cổ có người biểu diễn theo giờ. Nó hoàn toàn là dàn dựng và không giấu điều đó — nhưng vào một chiều thu, đứng ở quảng trường nhìn xuống mặt hồ, khung cảnh vẫn có sức thuyết phục riêng. Nhiều phim và chương trình truyền hình Hàn quay ở đây nên du khách châu Á rất đông.', '["Mở cửa năm 2008, lấy chủ đề từ ''Hoàng tử Bé'' của Saint-Exupéry.","Có bảo tàng hộp nhạc cổ với các buổi diễn theo giờ trong ngày.","Kiến trúc mô phỏng làng vùng Provence, gồm cả nhà thật dời từ Pháp sang.","Là bối cảnh của nhiều phim truyền hình Hàn Quốc."]', '["Kết hợp với Vườn Bình minh Tĩnh lặng cách đó khoảng 20 phút xe.","Có xe bus du lịch Gapyeong chạy vòng nối các điểm trong vùng.","Buổi chiều muộn ít khách hơn và ánh sáng đẹp hơn."]', 'Tháng 4–6 và 9–11', '1,5–2 giờ', '12.000 KRW', '09:00–18:00', '["popular"]', '["làng chủ đề","gia đình","hồ","phim trường"]', '[{"seed":"petite-france","caption":"Quảng trường làng nhìn xuống hồ","ratio":"16/9"}]', '["garden-of-morning-calm","pocheon-art-valley"]', 0, 'https://en.wikipedia.org/wiki/Petite_France_(theme_park)', '2026-08-04', '{"en":{"name":"Petite France, Gapyeong","summary":"A Provençal village built on a Korean hillside, made in memory of The Little Prince.","story":"The founder of Petite France loved The Little Prince enough to license the imagery and build an entire French village on a hillside above Cheongpyeong lake: orange-tiled roofs, blue shutters, a small square with a fountain, and a little museum about Saint-Exupéry alongside a collection of antique music boxes played to a timetable. It is entirely staged and makes no secret of it — yet on an autumn afternoon, standing in the square looking down at the lake, it carries its own conviction. Many Korean films and shows were filmed here, so Asian visitors come in numbers.","facts":["Opened in 2008, themed on Saint-Exupéry''s The Little Prince.","It has an antique music box museum with scheduled daily performances.","The architecture copies Provençal villages, including houses moved over from France.","It has been the setting for numerous Korean television dramas."],"travelTips":["Pair it with the Garden of Morning Calm, about 20 minutes away by car.","The Gapyeong tourist shuttle bus loops between the area''s sights.","Late afternoon is quieter and the light is better."],"bestTime":"April–June and September–November","visitDuration":"1.5–2 hours","ticket":"12,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["The village square above the lake"]},"ko":{"name":"쁘띠프랑스(가평)","summary":"한국의 언덕에 지은 프로방스 마을. 『어린 왕자』를 기리기 위해 만들어졌다.","story":"쁘띠프랑스를 만든 사람은 『어린 왕자』를 좋아한 나머지 이미지 사용권을 사들이고, 청평호가 내려다보이는 언덕에 프랑스 마을을 통째로 지었다. 주황 기와지붕과 파란 덧창, 분수가 있는 작은 광장, 생텍쥐페리를 다룬 작은 박물관, 그리고 시간마다 연주되는 앤티크 오르골 컬렉션이 있다. 완전히 연출된 공간이고 그것을 숨기지도 않는다. 그런데 가을 오후, 광장에 서서 호수를 내려다보면 나름의 설득력이 생긴다. 한국 영화와 드라마가 여러 편 촬영되어 아시아 관광객이 많다.","facts":["2008년 개장했으며 생텍쥐페리의 『어린 왕자』를 주제로 한다.","앤티크 오르골 박물관이 있고 하루 몇 차례 연주가 열린다.","프로방스 마을을 본떴고, 프랑스에서 옮겨 온 실제 가옥도 있다.","여러 한국 드라마의 촬영지였다."],"travelTips":["차로 20분 거리의 아침고요수목원과 묶어서 보자.","가평 관광순환버스가 지역 명소를 이어 준다.","늦은 오후가 덜 붐비고 빛도 좋다."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5~2시간","ticket":"12,000원","openingHours":"09:00~18:00","galleryCaptions":["호수를 내려다보는 마을 광장"]},"ja":{"name":"プチフランス（加平）","summary":"韓国の丘に建てたプロヴァンスの村。『星の王子さま』を偲ぶために作られた。","story":"プチフランスを作った人は『星の王子さま』を愛するあまり、その意匠の権利を買い、清平湖を見下ろす丘にフランスの村をまるごと建てた。オレンジの瓦屋根と青い鎧戸、噴水のある小さな広場、サン=テグジュペリを扱う小さな博物館、そして時間ごとに演奏されるアンティークオルゴールのコレクションがある。完全に演出された空間で、それを隠しもしない。それでも秋の午後、広場に立って湖を見下ろすと、独自の説得力が生まれる。韓国の映画やドラマが何本も撮影され、アジアからの旅行者が多い。","facts":["2008年開業、サン=テグジュペリの『星の王子さま』を主題とする。","アンティークオルゴール博物館があり、一日数回の演奏が行われる。","プロヴァンスの村を模し、フランスから移築した実際の家屋もある。","多くの韓国ドラマの撮影地となってきた。"],"travelTips":["車で20分の晨静樹木園と合わせて回ろう。","加平観光循環バスが周辺の名所を結んでいる。","遅い午後は空いていて光もよい。"],"bestTime":"4〜6月と9〜11月","visitDuration":"1.5〜2時間","ticket":"12,000ウォン","openingHours":"09:00〜18:00","galleryCaptions":["湖を見下ろす村の広場"]},"zh":{"name":"小法國村（加平）","summary":"蓋在韓國山坡上的普羅旺斯村落，為紀念《小王子》而生。","story":"小法國村的創辦人愛《小王子》愛到買下形象授權，在俯瞰清平湖的山坡上蓋起一整座法國村：橘瓦屋頂、藍色百葉窗、有噴泉的小廣場，還有一間關於聖修伯里的小博物館，以及按時段演奏的古董音樂盒收藏。它完全是佈景，也從不掩飾這一點——但在秋日午後，站在廣場上俯視湖面，它仍有自己的說服力。許多韓國影劇在此取景，因此亞洲遊客特別多。","facts":["2008年開幕，以聖修伯里的《小王子》為主題。","設有古董音樂盒博物館，每日按時段演奏。","建築仿普羅旺斯村落，其中包含自法國遷建的真實房舍。","曾是多部韓國電視劇的拍攝地。"],"travelTips":["可與車程約20分鐘的晨靜樹木園排在一起。","加平觀光循環巴士串連了周邊景點。","傍晚人較少，光線也更好。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5至2小時","ticket":"12,000韓元","openingHours":"09:00–18:00","galleryCaptions":["俯瞰湖面的村中廣場"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('garden-of-morning-calm', 'garden-of-morning-calm', 'gyeonggi', 'Vườn Bình minh Tĩnh lặng', 'The Garden of Morning Calm', 'park', 127.372, 37.744, 'Vườn thực vật tư nhân lâu đời nhất Hàn Quốc, mùa đông thắp hàng triệu bóng đèn giữa rừng thông.', 'Một giáo sư làm vườn mua lại sườn đồi này năm 1996 với ý định làm ra khu vườn thể hiện được ''đường cong Hàn Quốc'' — không đối xứng, không cắt tỉa vuông vức, mà uốn theo địa hình như dáng núi. Hai mươi khu vườn chủ đề trải trên sườn dốc, trong đó Vườn Bên nhà tái hiện sân sau của một nếp nhà nông thôn. Tên vườn lấy từ cách gọi cũ của Triều Tiên, ''xứ sở buổi sáng tĩnh lặng''. Từ tháng 12 đến tháng 3, cả khu được thắp bằng hàng triệu bóng đèn cho lễ hội ánh sáng — đây là lúc đông khách nhất, và cũng là lúc lạnh nhất.', '["Mở cửa năm 1996, là vườn thực vật tư nhân lâu đời nhất Hàn Quốc.","Rộng khoảng 33 hecta với hơn 20 khu vườn chủ đề.","Lễ hội ánh sáng mùa đông kéo dài từ tháng 12 đến tháng 3.","Tên vườn lấy từ tên gọi cũ của Triều Tiên, ''xứ sở buổi sáng tĩnh lặng''."]', '["Mùa đông vườn mở tới khuya cho lễ hội đèn — mặc thật ấm.","Tháng 5 là mùa hoa đỗ quyên và mẫu đơn nở rộ.","Đi tàu ITX tới Cheongpyeong rồi bắt bus du lịch Gapyeong."]', 'Tháng 5 (hoa) và tháng 12–2 (lễ hội đèn)', '2–3 giờ', '9.000–11.000 KRW tuỳ mùa', '08:30–19:00, mùa lễ hội đèn tới 21:00', '["popular","verified"]', '["vườn","hoa","lễ hội ánh sáng","mùa đông"]', '[{"seed":"garden-of-morning-calm","caption":"Lễ hội ánh sáng mùa đông","ratio":"16/9"}]', '["petite-france","pocheon-art-valley"]', 1, 'https://www.trip.com/travel-guide/attraction/gapyeong-gun/garden-of-morning-calm-90734/', '2026-08-04', '{"en":{"name":"The Garden of Morning Calm","summary":"Korea''s oldest private botanical garden, lit in winter by millions of bulbs strung through the pines.","story":"A horticulture professor bought this hillside in 1996 meaning to make a garden that expressed the ''Korean curve'' — not symmetrical, not clipped square, but following the ground the way a mountain ridge does. Twenty themed gardens run across the slope, among them the Garden Beside the House, which recreates the back yard of a rural home. The name comes from the old epithet for Korea, the land of morning calm. From December to March the whole place is lit by millions of bulbs for the light festival — the busiest time, and the coldest.","facts":["Opened in 1996, Korea''s oldest private botanical garden.","About 33 hectares with more than 20 themed gardens.","The winter light festival runs from December to March.","The name comes from the old epithet for Korea, the land of morning calm."],"travelTips":["In winter the garden stays open late for the lights — dress properly warm.","May is when the azaleas and peonies are at their peak.","Take the ITX to Cheongpyeong, then the Gapyeong tourist shuttle."],"bestTime":"May (flowers) and December–February (light festival)","visitDuration":"2–3 hours","ticket":"9,000–11,000 KRW depending on season","openingHours":"08:30–19:00, until 21:00 during the light festival","galleryCaptions":["The winter light festival"]},"ko":{"name":"아침고요수목원","summary":"한국에서 가장 오래된 사립 수목원. 겨울이면 잣나무 사이로 수백만 개의 전구가 켜진다.","story":"한 원예학 교수가 1996년 이 언덕을 사들였다. ''한국의 곡선''을 담은 정원을 만들겠다는 뜻이었다. 대칭도 아니고 네모나게 다듬지도 않은, 산등성이처럼 땅을 따라 흐르는 정원 말이다. 스무 개가 넘는 주제 정원이 비탈을 따라 이어지는데, 그중 하늘길정원과 함께 시골집 뒷마당을 재현한 정원도 있다. 이름은 한국의 옛 별칭인 ''고요한 아침의 나라''에서 왔다. 12월부터 3월까지는 수백만 개의 전구로 오색빛축제가 열린다. 가장 붐비는 때이자 가장 추운 때다.","facts":["1996년 문을 연 한국에서 가장 오래된 사립 수목원이다.","약 33헥타르에 20개가 넘는 주제 정원이 있다.","겨울 오색빛축제는 12월부터 3월까지 이어진다.","이름은 한국의 옛 별칭 ''고요한 아침의 나라''에서 따왔다."],"travelTips":["겨울에는 빛축제로 늦게까지 연다. 정말 따뜻하게 입자.","5월은 철쭉과 작약이 절정인 때다.","ITX로 청평까지 간 뒤 가평 관광순환버스를 타자."],"bestTime":"5월(꽃)과 12~2월(빛축제)","visitDuration":"2~3시간","ticket":"계절에 따라 9,000~11,000원","openingHours":"08:30~19:00, 빛축제 기간에는 21:00까지","galleryCaptions":["겨울 오색빛축제"]},"ja":{"name":"晨静樹木園","summary":"韓国で最も古い私設樹木園。冬には松の間に数百万の電球が灯る。","story":"ある園芸学の教授が1996年にこの丘を買った。「韓国の曲線」を表す庭を作るためだった。左右対称でもなく、四角く刈り込むのでもなく、尾根のように地形に沿って流れる庭である。二十を超える主題庭園が斜面に連なり、その中には田舎家の裏庭を再現した庭もある。名は韓国の古い別称「静かな朝の国」から来ている。十二月から三月にかけては数百万の電球による光の祭りが開かれる。最も混み、最も寒い時期だ。","facts":["1996年開園、韓国で最も古い私設樹木園である。","約33ヘクタールに20を超える主題庭園がある。","冬の光の祭りは12月から3月まで続く。","名称は韓国の古い別称「静かな朝の国」に由来する。"],"travelTips":["冬は光の祭りで遅くまで開く。本当に暖かい服装で。","5月はツツジとシャクヤクが盛りだ。","ITXで清平まで行き、加平観光循環バスに乗ろう。"],"bestTime":"5月（花）と12〜2月（光の祭り）","visitDuration":"2〜3時間","ticket":"季節により9,000〜11,000ウォン","openingHours":"08:30〜19:00、光の祭り期間は21:00まで","galleryCaptions":["冬の光の祭り"]},"zh":{"name":"晨靜樹木園","summary":"韓國歷史最久的私人植物園，冬天在松林之間點起數百萬顆燈泡。","story":"一位園藝學教授1996年買下這片山坡，想做一座能表現「韓國曲線」的花園——不對稱、不修剪成方正，而是像山稜那樣順著地勢起伏。二十多座主題花園沿坡展開，其中「家旁花園」重現了鄉間住宅的後院。園名取自韓國的舊稱「晨靜之國」。十二月到三月，整片園區以數百萬顆燈泡辦光之祭——那是最熱鬧的時候，也是最冷的時候。","facts":["1996年開園，是韓國歷史最久的私人植物園。","面積約33公頃，設有20多座主題花園。","冬季光之祭從12月持續到3月。","園名取自韓國舊稱「晨靜之國」。"],"travelTips":["冬季因光之祭延長開放時間，務必穿得夠暖。","五月是杜鵑與芍藥最盛的時候。","搭ITX到清平，再轉加平觀光循環巴士。"],"bestTime":"5月（花季）與12至2月（光之祭）","visitDuration":"2至3小時","ticket":"依季節9,000至11,000韓元","openingHours":"08:30–19:00，光之祭期間延長至21:00","galleryCaptions":["冬季光之祭"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('pocheon-art-valley', 'pocheon-art-valley', 'gyeonggi', 'Thung lũng nghệ thuật Pocheon', 'Pocheon Art Valley', 'lake', 127.32, 37.943, 'Mỏ đá granite bỏ hoang ngập nước thành hồ xanh ngọc, vách đá dựng đứng bao quanh bốn phía.', 'Suốt mấy chục năm, granite Pocheon được xẻ ra để xây nhà khắp Seoul; khi mỏ cạn và bị bỏ, nước ngầm dâng lên lấp đầy hố đá và tạo thành một cái hồ màu xanh ngọc kỳ lạ, bốn bề là vách cắt thẳng đứng còn nguyên vết máy xẻ. Thay vì lấp đi, huyện biến nó thành công viên nghệ thuật: có xe monorail bò lên miệng hố, sân khấu ngoài trời tận dụng vách đá làm phông, đài thiên văn nhỏ và các tác phẩm điêu khắc đá đặt dọc lối đi. Nước hồ sâu và lạnh quanh năm nên cấm bơi, nhưng đứng trên đài quan sát nhìn xuống thì màu nước rất khó tin.', '["Từng là mỏ khai thác granite, đóng cửa và ngập nước tự nhiên.","Hồ Cheonjuho hình thành trong lòng hố đá cũ, nước sâu và lạnh quanh năm.","Mở cửa thành công viên văn hoá từ năm 2009.","Có xe monorail đưa khách lên miệng hố và một đài thiên văn nhỏ."]', '["Đi monorail lên, đi bộ xuống — đường xuống thoải và nhiều góc nhìn đẹp.","Trời nắng nước mới lên đúng màu ngọc; ngày âm u màu xỉn hẳn.","Kết hợp với suối Bidulginang gần đó trong cùng chuyến."]', 'Tháng 5–6 và 9–10', '2 giờ', '5.000 KRW (thiếu niên 3.000, trẻ em 1.500); monorail khứ hồi thêm 5.300 KRW', '09:00–19:00', '["hidden-gem","trending"]', '["hồ","mỏ đá cũ","nghệ thuật","monorail"]', '[{"seed":"pocheon-art-valley","caption":"Hồ ngọc trong lòng mỏ đá cũ","ratio":"16/9"}]', '["garden-of-morning-calm","petite-france"]', 0, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=66111', '2026-08-04', '{"en":{"name":"Pocheon Art Valley","summary":"An abandoned granite quarry flooded into a jade-green lake, walled on all sides by sheer cut rock.","story":"For decades Pocheon granite was cut to build Seoul; when the quarry ran out and was abandoned, groundwater rose and filled the pit, making a strangely jade-coloured lake ringed by vertical faces still showing the saw marks. Rather than fill it in, the county turned it into an arts park: a monorail crawls up to the rim, an open-air stage uses the rock face as its backdrop, there is a small observatory, and stone sculptures line the paths. The water is deep and cold year-round so swimming is banned, but seen from the viewing deck the colour is hard to believe.","facts":["Formerly a granite quarry, abandoned and then naturally flooded.","Cheonjuho lake formed in the old pit; the water is deep and cold all year.","It opened as a cultural park in 2009.","A monorail carries visitors to the rim, and there is a small observatory."],"travelTips":["Ride the monorail up and walk down — the descent is gentle with the better views.","The jade colour only appears in sunshine; on grey days it goes dull.","Combine it with the nearby Bidulginang falls on the same trip."],"bestTime":"May–June and September–October","visitDuration":"2 hours","ticket":"5,000 KRW (3,000 teens, 1,500 children); the monorail is a further 5,300 KRW return","openingHours":"09:00–19:00","galleryCaptions":["The jade lake in the old quarry"]},"ko":{"name":"포천아트밸리","summary":"버려진 화강암 채석장에 물이 차 옥빛 호수가 되었다. 사방은 수직으로 잘린 암벽이다.","story":"수십 년 동안 포천의 화강암은 서울을 짓는 데 잘려 나갔다. 광석이 다해 채석장이 버려지자 지하수가 차올라 웅덩이를 채웠고, 톱자국이 그대로 남은 수직 암벽에 둘러싸인 기묘한 옥빛 호수가 생겼다. 군은 이를 메우는 대신 예술 공원으로 바꿨다. 모노레일이 채석장 위쪽까지 기어오르고, 암벽을 배경으로 쓰는 야외 무대가 있으며, 작은 천문과학관과 길을 따라 놓인 석조 조각들이 있다. 물이 깊고 연중 차가워 수영은 금지되어 있지만, 전망대에서 내려다보는 물빛은 믿기 어려울 정도다.","facts":["본래 화강암 채석장이었고, 폐광 후 자연적으로 물이 찼다.","옛 채석 웅덩이에 생긴 천주호는 물이 깊고 연중 차갑다.","2009년 문화예술공원으로 문을 열었다.","모노레일이 위쪽까지 오르고 작은 천문과학관이 있다."],"travelTips":["올라갈 때는 모노레일, 내려올 때는 도보가 좋다. 내리막이 완만하고 전망이 낫다.","옥빛은 햇빛이 있어야 나온다. 흐린 날에는 색이 죽는다.","가까운 비둘기낭폭포와 함께 묶어서 보자."],"bestTime":"5~6월, 9~10월","visitDuration":"2시간","ticket":"5,000원(청소년 3,000원, 어린이 1,500원), 모노레일 왕복 5,300원 별도","openingHours":"09:00~19:00","galleryCaptions":["옛 채석장에 생긴 옥빛 호수"]},"ja":{"name":"抱川アートバレー","summary":"捨てられた花崗岩の採石場に水が溜まり、翡翠色の湖になった。四方は垂直に切られた岩壁だ。","story":"何十年ものあいだ、抱川の花崗岩はソウルを建てるために切り出された。石が尽きて採石場が捨てられると地下水が満ちて窪みを埋め、鋸の跡がそのまま残る垂直の岩壁に囲まれた、奇妙な翡翠色の湖ができた。郡はこれを埋め戻す代わりに芸術公園に変えた。モノレールが縁まで這い上がり、岩壁を背景に使う野外舞台があり、小さな天文台と、道沿いに置かれた石の彫刻がある。水は深く年中冷たいので遊泳は禁止だが、展望台から見下ろす水の色は信じがたいほどだ。","facts":["もとは花崗岩の採石場で、閉鎖後に自然に水が溜まった。","旧採石窪地にできた天柱湖は水深があり年中冷たい。","2009年に文化芸術公園として開園した。","モノレールが縁まで上り、小さな天文台がある。"],"travelTips":["上りはモノレール、下りは徒歩がよい。下り坂は緩やかで眺めもよい。","翡翠色は日差しがあってこそ出る。曇りの日は色がくすむ。","近くの鳩浪の滝と合わせて回ろう。"],"bestTime":"5〜6月と9〜10月","visitDuration":"2時間","ticket":"5,000ウォン（青少年3,000、子ども1,500）、モノレール往復5,300ウォン別途","openingHours":"09:00〜19:00","galleryCaptions":["旧採石場にできた翡翠色の湖"]},"zh":{"name":"抱川藝術谷","summary":"廢棄花崗岩採石場積水成翡翠色湖泊，四面都是垂直切開的岩壁。","story":"數十年來，抱川的花崗岩被切下來蓋首爾；石材採盡、礦場遭棄之後，地下水湧上填滿了坑洞，形成一座奇異的翡翠色湖，四周是仍留著鋸痕的垂直岩壁。郡府沒有把它填掉，而是改成藝術公園：單軌列車爬上坑口，露天舞台直接拿岩壁當背景，還有一座小天文台與沿路擺放的石雕。湖水深而終年冰冷，禁止游泳，但從觀景台往下看，那個顏色實在難以置信。","facts":["原為花崗岩採石場，廢棄後自然積水。","在舊採石坑中形成的天柱湖水深且終年低溫。","2009年以文化藝術公園的形式開放。","設有單軌列車通往坑口，以及一座小型天文台。"],"travelTips":["上行搭單軌、下行用走的——下坡平緩，視野也更好。","翡翠色要有陽光才顯得出來，陰天顏色會發灰。","可與附近的鴿子囊瀑布排在同一趟。"],"bestTime":"5至6月與9至10月","visitDuration":"2小時","ticket":"5,000韓元（青少年3,000、兒童1,500）；單軌來回另收5,300韓元","openingHours":"09:00–19:00","galleryCaptions":["舊採石坑中的翡翠色湖"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seoraksan', 'seoraksan', 'gangwon', 'Vườn quốc gia Seoraksan', 'Seoraksan National Park', 'mountain', 128.465, 38.119, 'Dãy núi đá granite dựng đứng gần biển, nơi mùa thu Hàn Quốc bắt đầu mỗi năm.', 'Seoraksan là ngọn núi mà người Hàn nghĩ tới đầu tiên khi nói ''đi núi''. Những vách granite trắng dựng thẳng, thông mọc trên khe đá, và đường mòn dẫn tới Ulsanbawi — sáu khối đá khổng lồ mà truyền thuyết bảo đang trên đường tới núi Geumgang thì lỡ hẹn nên ở lại đây. Cáp treo đưa khách lên Gwongeumseong nếu ngại leo. Mỗi cuối tháng 9, lá đỏ bắt đầu từ đỉnh Seoraksan rồi lan dần xuống phía nam suốt một tháng — bản đồ mùa thu của cả nước tính từ đây.', '["Đỉnh Daecheongbong cao 1.708m, cao thứ ba Hàn Quốc.","Được UNESCO công nhận khu dự trữ sinh quyển năm 1982.","Chùa Sinheungsa dưới chân núi có tượng Phật đồng cao 14,6m.","Lá đỏ ở đây thường bắt đầu sớm nhất cả nước, cuối tháng 9."]', '["Đường lên Ulsanbawi có hơn 800 bậc thang cuối, mất khoảng 4 giờ khứ hồi.","Cuối tuần mùa thu cực đông — đi ngày thường nếu có thể.","Từ Seoul đi xe khách tới Sokcho khoảng 2,5 giờ."]', 'Cuối tháng 9 đến giữa tháng 10', 'Cả ngày', 'Vào vườn quốc gia miễn phí; cáp treo lên Gwongeumseong 16.000 KRW khứ hồi (trẻ em 12.000)', '06:00–20:00; cáp treo thường 09:00–17:30', '["popular","verified"]', '["núi","mùa thu","leo núi"]', '[{"seed":"seoraksan","caption":"Vách đá Ulsanbawi","ratio":"16/9"}]', '["naksansa","gyeongpo-beach"]', 1, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=97439', '2026-08-04', '{"en":{"name":"Seoraksan National Park","summary":"Granite walls rising close to the sea, where every Korean autumn begins.","story":"Seoraksan is the mountain Koreans think of first when they say ''let''s go hiking''. White granite faces stand vertical, pines grow out of the cracks, and one trail leads to Ulsanbawi — six huge rocks that legend says were on their way to Geumgangsan, arrived late, and stayed. A cable car carries you to Gwongeumseong if you would rather not climb. Every late September the red leaves start at Seoraksan''s summit and spread south over the following month — the country''s autumn map is drawn from here.","facts":["Daecheongbong peak reaches 1,708m, the third highest in South Korea.","Designated a UNESCO Biosphere Reserve in 1982.","Sinheungsa temple at the foot holds a 14.6m bronze Buddha.","Autumn colour usually starts here first in the country, in late September."],"travelTips":["The Ulsanbawi route ends with more than 800 steps; allow four hours return.","Autumn weekends are extremely busy — go on a weekday if you can.","Intercity buses from Seoul reach Sokcho in about 2.5 hours."],"bestTime":"Late September to mid-October","visitDuration":"Full day","ticket":"Park entry is free; the Gwongeumseong cable car is 16,000 KRW return (12,000 for children)","openingHours":"06:00–20:00; the cable car usually runs 09:00–17:30","galleryCaptions":["The Ulsanbawi rock walls"]},"ko":{"name":"설악산국립공원","summary":"바다 가까이 솟은 화강암 봉우리들. 한국의 가을이 시작되는 곳이다.","story":"설악산은 한국 사람이 ''산에 가자''고 할 때 가장 먼저 떠올리는 산이다. 흰 화강암 벽이 수직으로 서 있고 바위틈에서 소나무가 자라며, 한 갈래 길은 울산바위로 이어진다. 금강산으로 가던 여섯 덩이 바위가 늦어 이곳에 눌러앉았다는 전설이 있다. 오르기 부담스럽다면 케이블카로 권금성까지 갈 수 있다. 해마다 9월 말이면 설악산 정상에서 단풍이 시작해 한 달에 걸쳐 남쪽으로 내려간다. 전국의 단풍 지도는 이곳에서 그려진다.","facts":["대청봉은 해발 1,708m로 남한에서 세 번째로 높다.","1982년 유네스코 생물권보전지역으로 지정되었다.","산 아래 신흥사에는 높이 14.6m의 청동대불이 있다.","단풍이 보통 전국에서 가장 이르게, 9월 말에 시작된다."],"travelTips":["울산바위 코스는 마지막에 800개가 넘는 계단이 있고 왕복 네 시간쯤 걸린다.","가을 주말은 매우 붐비니 가능하면 평일에 가자.","서울에서 속초까지 시외버스로 약 2시간 30분이다."],"bestTime":"9월 말~10월 중순","visitDuration":"하루","ticket":"국립공원 입장 무료, 권금성 케이블카 왕복 16,000원(어린이 12,000원)","openingHours":"06:00~20:00, 케이블카는 대개 09:00~17:30","galleryCaptions":["울산바위 암벽"]},"ja":{"name":"雪岳山国立公園","summary":"海の近くにそびえる花崗岩の峰々。韓国の秋はここから始まる。","story":"雪岳山は、韓国の人が「山に行こう」と言うとき最初に思い浮かべる山だ。白い花崗岩の壁が垂直に立ち、岩の割れ目から松が生え、一本の道は蔚山岩へ続く。金剛山へ向かう途中の六つの岩が遅れてここに居ついた、という伝説がある。登るのが大変ならケーブルカーで権金城まで行ける。毎年9月末、紅葉は雪岳山の頂から始まり、一か月かけて南へ下っていく。全国の紅葉前線はここから描かれる。","facts":["大青峰は標高1,708mで韓国第三の高さ。","1982年にユネスコ生物圏保存地域に指定された。","ふもとの新興寺には高さ14.6mの青銅大仏がある。","紅葉は例年、全国で最も早く9月末に始まる。"],"travelTips":["蔚山岩コースは最後に800段超の階段があり往復四時間ほど。","秋の週末は非常に混雑する。可能なら平日に。","ソウルから束草まで市外バスで約2時間30分。"],"bestTime":"9月末〜10月中旬","visitDuration":"終日","ticket":"国立公園の入場は無料、権金城ケーブルカーは往復16,000ウォン（子ども12,000）","openingHours":"06:00〜20:00、ケーブルカーは概ね09:00〜17:30","galleryCaptions":["蔚山岩の岩壁"]},"zh":{"name":"雪嶽山國立公園","summary":"臨海而起的花崗岩峰群，韓國的秋天從這裡開始。","story":"當韓國人說「去爬山」，最先想到的就是雪嶽山。白色花崗岩壁垂直而立，松樹從石縫長出，其中一條路通往蔚山岩——傳說那是六塊巨石在前往金剛山的途中遲到，索性留了下來。不想爬山也可以搭纜車到權金城。每年九月底，紅葉自雪嶽山山頂開始，往後一個月一路南下——全國的秋色地圖就是從這裡畫起的。","facts":["大青峰海拔1,708公尺，為南韓第三高峰。","1982年被指定為聯合國教科文組織生物圈保護區。","山腳的新興寺有高14.6公尺的青銅大佛。","此地紅葉通常是全國最早，約於九月底開始。"],"travelTips":["蔚山岩路線最後有八百多級階梯，往返約四小時。","秋季週末極為擁擠，盡量選平日。","自首爾搭客運至束草約2.5小時。"],"bestTime":"9月底至10月中","visitDuration":"一整天","ticket":"國家公園免費入園；權金城纜車來回16,000韓元（兒童12,000）","openingHours":"06:00–20:00；纜車通常09:00–17:30","galleryCaptions":["蔚山岩岩壁"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gyeongpo-beach', 'gyeongpo-beach', 'gangwon', 'Bãi biển Gyeongpo (Gangneung)', 'Gyeongpo Beach, Gangneung', 'beach', 128.9, 37.8, 'Bãi cát dài của Gangneung, có hồ nước lợ và rừng thông ngay sau lưng.', 'Gangneung là nơi người Seoul chạy tới khi cần biển — từ khi có tàu cao tốc, chuyến đi chỉ còn chưa đầy hai tiếng. Bãi Gyeongpo dài gần hai cây số, phía sau là hồ Gyeongpo với đường đi bộ vòng quanh và lầu Gyeongpodae đã đứng đó từ thế kỷ 14. Người xưa nói ở đây có thể ngắm năm mặt trăng cùng lúc: trên trời, trên biển, trên mặt hồ, trong chén rượu và trong mắt người đối diện. Thành phố cũng là thủ phủ cà phê của Hàn Quốc, với cả một con phố cà phê ở Anmok kề bên.', '["Bãi dài khoảng 1,8 km, là bãi tắm lớn nhất bờ biển phía đông.","Lầu Gyeongpodae dựng năm 1326, nhìn ra hồ Gyeongpo.","Phố cà phê Anmok cách đó vài phút, nổi tiếng khắp Hàn Quốc.","Tàu KTX từ Seoul tới Gangneung mất khoảng 2 giờ."]', '["Đi tàu KTX từ ga Seoul, rất tiện và nhanh.","Tháng 4 có hoa anh đào nở quanh hồ Gyeongpo.","Ghé chợ Jungang Gangneung ăn bánh cá và mực nhồi."]', 'Tháng 6–9 (tắm biển), tháng 4 (hoa anh đào)', '2–3 giờ', '', 'Cả ngày', '["popular"]', '["bãi biển","hồ","cà phê"]', '[{"seed":"gyeongpo-beach","caption":"Bãi Gyeongpo và rừng thông","ratio":"16/9"}]', '["ojukheon","jeongdongjin"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Gyeongpo Beach, Gangneung","summary":"Gangneung''s long stretch of sand, with a brackish lagoon and a pine wood right behind it.","story":"Gangneung is where Seoul goes when it needs the sea — since the high-speed train arrived the trip takes under two hours. Gyeongpo beach runs almost two kilometres, backed by Gyeongpo lagoon with a walking loop and the Gyeongpodae pavilion that has stood there since the 14th century. The old saying goes that here you can see five moons at once: in the sky, on the sea, on the lake, in your cup and in the eyes of the person opposite. The city is also Korea''s coffee capital, with a whole café street at Anmok just around the bay.","facts":["The beach runs about 1.8 km, the largest on the east coast.","Gyeongpodae pavilion was built in 1326, overlooking the lagoon.","Anmok coffee street, minutes away, is famous across Korea.","The KTX from Seoul reaches Gangneung in about two hours."],"travelTips":["Take the KTX from Seoul station — fast and convenient.","Cherry blossom rings the lagoon in April.","Stop at Gangneung Jungang Market for fish cakes and stuffed squid."],"bestTime":"June–September (swimming), April (cherry blossom)","visitDuration":"2–3 hours","ticket":"","openingHours":"All day","galleryCaptions":["Gyeongpo beach and its pine wood"]},"ko":{"name":"강릉 경포해변","summary":"석호와 솔숲을 등에 두른 강릉의 긴 백사장.","story":"강릉은 서울이 바다가 필요할 때 가는 곳이다. 고속철이 생긴 뒤로는 두 시간이 채 걸리지 않는다. 경포해변은 2km 가까이 이어지고, 뒤로는 산책로가 있는 경포호와 14세기부터 서 있는 경포대가 있다. 옛사람들은 이곳에서 달을 다섯 번 볼 수 있다고 했다. 하늘에, 바다에, 호수에, 술잔에, 그리고 마주 앉은 사람의 눈에. 강릉은 한국의 커피 도시이기도 해서 만 건너 안목에는 커피 거리가 통째로 있다.","facts":["해변 길이는 약 1.8km로 동해안에서 가장 크다.","경포호를 내려다보는 경포대는 1326년에 세워졌다.","몇 분 거리의 안목 커피거리는 전국적으로 유명하다.","서울에서 KTX로 약 두 시간이면 강릉에 닿는다."],"travelTips":["서울역에서 KTX를 타면 빠르고 편하다.","4월이면 경포호 둘레에 벚꽃이 핀다.","강릉중앙시장에 들러 어묵과 오징어순대를 먹어보자."],"bestTime":"6~9월(해수욕), 4월(벚꽃)","visitDuration":"2~3시간","ticket":"","openingHours":"상시","galleryCaptions":["경포해변과 솔숲"]},"ja":{"name":"江陵 鏡浦海辺","summary":"潟湖と松林を背にした江陵の長い砂浜。","story":"江陵はソウルが海を欲したときに向かう場所で、高速鉄道ができてからは二時間もかからない。鏡浦海辺は2km近く続き、背後には遊歩道のある鏡浦湖と、14世紀から建つ鏡浦台がある。昔の人はここで月を五つ見られると言った。空に、海に、湖に、杯に、そして向かい合う人の瞳に。江陵は韓国のコーヒーの街でもあり、湾の向こうの安木にはカフェ通りが丸ごとある。","facts":["砂浜の長さは約1.8kmで東海岸最大。","鏡浦湖を見下ろす鏡浦台は1326年に建てられた。","数分の距離にある安木コーヒー通りは全国的に有名。","ソウルからKTXで約2時間。"],"travelTips":["ソウル駅からKTXが速くて便利。","4月には鏡浦湖の周りに桜が咲く。","江陵中央市場でおでんとイカスンデを味わおう。"],"bestTime":"6〜9月（海水浴）、4月（桜）","visitDuration":"2〜3時間","ticket":"","openingHours":"終日","galleryCaptions":["鏡浦海辺と松林"]},"zh":{"name":"江陵鏡浦海邊","summary":"背倚潟湖與松林的江陵長灘。","story":"江陵是首爾想看海時去的地方——高鐵通車後車程不到兩小時。鏡浦海灘綿延近兩公里，背後是設有環湖步道的鏡浦湖，以及自十四世紀矗立至今的鏡浦台。古人說在這裡能同時看見五個月亮：天上、海上、湖上、酒杯裡，以及對坐之人的眼中。這座城市也是韓國的咖啡之都，海灣另一頭的安木有一整條咖啡街。","facts":["海灘長約1.8公里，是東海岸最大的一處。","俯瞰鏡浦湖的鏡浦台建於1326年。","數分鐘車程外的安木咖啡街全國聞名。","自首爾搭KTX約兩小時可達江陵。"],"travelTips":["從首爾站搭KTX最快也最方便。","四月鏡浦湖畔櫻花盛開。","順道去江陵中央市場吃魚糕與魷魚米腸。"],"bestTime":"6至9月（戲水）、4月（櫻花）","visitDuration":"2至3小時","ticket":"","openingHours":"全日","galleryCaptions":["鏡浦海灘與松林"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ojukheon', 'ojukheon', 'gangwon', 'Ojukheon (Gangneung)', 'Ojukheon House', 'museum', 128.878, 37.779, 'Ngôi nhà gỗ 500 năm tuổi, nơi sinh của Yi I và nữ hoạ sĩ Shin Saimdang — hai gương mặt trên tiền Hàn Quốc.', 'Rất ít nơi trên thế giới có một ngôi nhà cho ra đời hai nhân vật in trên hai tờ tiền của cùng một quốc gia: Shin Saimdang (50.000 won) và con trai bà, học giả Yi I (5.000 won). Ojukheon là một trong những nhà gỗ cổ nhất còn nguyên ở Hàn Quốc, tên nghĩa là ''nhà tre đen'' theo bụi tre mọc quanh sân. Bên trong bày tranh cỏ cây côn trùng của Shin Saimdang — một phụ nữ thế kỷ 16 được kính trọng như nghệ sĩ chứ không chỉ như người mẹ, điều rất hiếm thời đó.', '["Ngôi nhà chính dựng vào đầu thế kỷ 16, là Bảo vật quốc gia số 165.","Nơi sinh của học giả Yi I (Yulgok) năm 1536.","Shin Saimdang là người phụ nữ đầu tiên xuất hiện trên tiền giấy Hàn Quốc.","Trong khuôn viên có bảo tàng địa phương Gangneung."]', '["Kết hợp cùng bãi Gyeongpo, cách nhau khoảng 10 phút xe.","Có thuyết minh tiếng Anh theo giờ cố định.","Vườn tre phía sau nhà là chỗ chụp ảnh đẹp nhất."]', 'Quanh năm', '1,5 giờ', '3.000 KRW (miễn phí từ 65 tuổi)', '08:00–18:00 (mùa đông đến 17:30), vào cửa cuối trước 30 phút', '["verified"]', '["lịch sử","nhà cổ","bảo tàng"]', '[{"seed":"ojukheon","caption":"Nhà gỗ Ojukheon và vườn tre","ratio":"16/9"}]', '["gyeongpo-beach"]', 0, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=110823', '2026-08-04', '{"en":{"name":"Ojukheon House","summary":"A 500-year-old wooden house, birthplace of Yi I and the painter Shin Saimdang — two faces on Korean banknotes.","story":"Very few houses anywhere produced two people printed on their country''s currency: Shin Saimdang (50,000 won) and her son, the scholar Yi I (5,000 won). Ojukheon is among the oldest wooden houses left standing in Korea, named for the black bamboo around its yard. Inside hang Shin Saimdang''s paintings of plants and insects — a 16th-century woman respected as an artist and not only as a mother, which was rare indeed in her time.","facts":["The main house dates from the early 16th century and is National Treasure No. 165.","Birthplace of the scholar Yi I (Yulgok) in 1536.","Shin Saimdang was the first woman to appear on a Korean banknote.","The grounds include the Gangneung municipal museum."],"travelTips":["Combine with Gyeongpo beach, about ten minutes away by car.","English guided tours run at fixed times.","The bamboo grove behind the house is the best photo spot."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"3,000 KRW (free for over 65s)","openingHours":"08:00–18:00 (to 17:30 in winter), last admission 30 min before closing","galleryCaptions":["Ojukheon''s wooden house and bamboo garden"]},"ko":{"name":"오죽헌","summary":"500년 된 목조 가옥. 신사임당과 율곡 이이가 태어난 곳으로 두 사람 모두 지폐에 있다.","story":"한 집에서 그 나라 지폐 두 종류의 인물이 태어난 경우는 세계적으로도 드물다. 신사임당(5만 원)과 그 아들 율곡 이이(5천 원)다. 오죽헌은 한국에 남은 가장 오래된 목조 가옥 가운데 하나로, 마당을 둘러싼 검은 대나무에서 이름을 얻었다. 안에는 신사임당의 초충도가 걸려 있다. 16세기 여성이 어머니로서만이 아니라 예술가로 존경받은 것은 당시로서는 매우 드문 일이었다.","facts":["본채는 16세기 초에 지어졌으며 보물 제165호다.","1536년 율곡 이이가 태어난 집이다.","신사임당은 한국 지폐에 등장한 최초의 여성이다.","경내에 강릉시립박물관이 있다."],"travelTips":["차로 10분 거리인 경포해변과 묶어 보자.","영어 해설은 정해진 시간에 운영된다.","집 뒤편 대숲이 사진 찍기 가장 좋다."],"bestTime":"연중","visitDuration":"1시간 30분","ticket":"3,000원(만 65세 이상 무료)","openingHours":"08:00~18:00(겨울 17:30까지), 입장 마감 30분 전","galleryCaptions":["오죽헌의 목조 가옥과 대숲"]},"ja":{"name":"烏竹軒","summary":"500年の木造家屋。申師任堂と栗谷李珥が生まれ、二人とも紙幣の顔になった。","story":"一軒の家からその国の紙幣二種類の人物が生まれた例は世界でも珍しい。申師任堂（5万ウォン）と、その息子である学者・李珥（5千ウォン）だ。烏竹軒は韓国に残る最古級の木造家屋で、庭を囲む黒竹から名がついた。中には申師任堂の草虫図が掛かる。16世紀の女性が母としてだけでなく芸術家として敬われたのは、当時としては極めて稀なことだった。","facts":["母屋は16世紀初頭の建築で宝物第165号。","1536年に李珥（栗谷）が生まれた家。","申師任堂は韓国紙幣に登場した最初の女性。","敷地内に江陵市立博物館がある。"],"travelTips":["車で10分の鏡浦海辺と合わせて回ろう。","英語ガイドは決まった時間に運営される。","家の裏の竹林が最も写真映えする。"],"bestTime":"通年","visitDuration":"1時間30分","ticket":"3,000ウォン（65歳以上は無料）","openingHours":"08:00〜18:00（冬は17:30まで）、入場は閉館30分前まで","galleryCaptions":["烏竹軒の木造家屋と竹林"]},"zh":{"name":"烏竹軒","summary":"五百年的木造宅第，申師任堂與栗谷李珥在此出生，兩人都印在紙鈔上。","story":"同一棟房子誕生兩位印在該國紙鈔上的人物，世上並不多見：申師任堂（五萬元）與她的兒子、學者李珥（五千元）。烏竹軒是韓國現存最古老的木造宅第之一，因庭院四周的黑竹而得名。屋內掛著申師任堂的草蟲圖——一位十六世紀的女性被尊為藝術家而不僅是母親，在當時極為罕見。","facts":["主屋建於十六世紀初，為寶物第165號。","1536年學者李珥（栗谷）在此出生。","申師任堂是首位登上韓國紙鈔的女性。","園區內設有江陵市立博物館。"],"travelTips":["可與車程十分鐘的鏡浦海灘一併安排。","英語導覽於固定時段進行。","屋後的竹林是最佳拍照處。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"3,000韓元（65歲以上免費）","openingHours":"08:00–18:00（冬季至17:30），閉館前30分鐘停止入場","galleryCaptions":["烏竹軒的木造宅第與竹園"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daegwallyeong-sky-ranch', 'daegwallyeong-sky-ranch', 'gangwon', 'Đồng cỏ Daegwallyeong (Pyeongchang)', 'Daegwallyeong Sky Ranch', 'park', 128.735, 37.687, 'Đồng cỏ chăn cừu trên cao nguyên 1.000 mét, mùa đông là xứ tuyết của Thế vận hội 2018.', 'Vượt đèo Daegwallyeong, khí hậu đổi hẳn: cao nguyên rộng, gió mạnh, cỏ trải tới chân trời và những cột điện gió trắng quay chậm. Các trang trại ở đây nuôi cừu và bò sữa, mở cửa cho khách đi bộ lên đỉnh đồi cho cừu ăn cỏ khô. Mùa đông tuyết dày cả mét — chính vùng này đăng cai Thế vận hội Mùa đông Pyeongchang 2018, và các khu trượt tuyết vẫn hoạt động suốt mùa. Sáng sớm mùa hè, sương phủ kín thung lũng bên dưới trong khi đỉnh đồi đã đầy nắng.', '["Nằm ở độ cao khoảng 1.000m trên đèo Daegwallyeong.","Pyeongchang đăng cai Thế vận hội Mùa đông 2018.","Khu vực có nhiều trang trại cừu mở cửa cho khách tham quan.","Cánh đồng điện gió Daegwallyeong là một trong những cụm lớn nhất Hàn Quốc."]', '["Gió rất mạnh quanh năm — mang áo khoác kể cả mùa hè.","Đường mòn quanh trang trại dài khoảng 1,2–2 km, đi bộ dễ.","Mùa đông cần xe có lốp tuyết hoặc đi tour."]', 'Tháng 6–9 (đồng cỏ xanh), tháng 12–2 (tuyết)', '2–3 giờ', '8.000 KRW (trẻ em và người cao tuổi 6.000); xe kéo tractor và cho cừu ăn tính riêng', '09:00–17:30', '[]', '["cao nguyên","cừu","tuyết"]', '[{"seed":"daegwallyeong-sky-ranch","caption":"Đồng cỏ và cột điện gió","ratio":"16/9"}]', '["gyeongpo-beach","seoraksan"]', 1, 'https://tour.pc.go.kr/Home/H40000/H40300/placeDetail?place_no=49', '2026-08-04', '{"en":{"name":"Daegwallyeong Sky Ranch, Pyeongchang","summary":"Sheep pasture on a 1,000-metre plateau — and the snow country of the 2018 Winter Olympics.","story":"Cross the Daegwallyeong pass and the climate changes outright: a broad plateau, hard wind, grass to the horizon and white turbines turning slowly. The farms here raise sheep and dairy cattle and open their hills to visitors who walk up to feed hay to the flock. In winter the snow lies a metre deep — this is the region that hosted the Pyeongchang 2018 Winter Olympics, and the ski resorts run all season. On summer mornings mist fills the valley below while the hilltops are already in sun.","facts":["Sits at around 1,000m on the Daegwallyeong pass.","Pyeongchang hosted the 2018 Winter Olympic Games.","Several sheep farms in the area open to visitors.","The Daegwallyeong wind farm is one of Korea''s largest turbine clusters."],"travelTips":["The wind is strong all year — bring a jacket even in summer.","The farm loop trails run 1.2–2 km and are easy walking.","In winter you need snow tyres or an organised tour."],"bestTime":"June–September (green pasture), December–February (snow)","visitDuration":"2–3 hours","ticket":"8,000 KRW (6,000 children and seniors); the tractor wagon and hay-feeding cost extra","openingHours":"09:00–17:30","galleryCaptions":["Pasture and wind turbines"]},"ko":{"name":"평창 대관령 목장","summary":"해발 1,000m 고원의 양 떼 초지. 겨울에는 2018 올림픽의 설국이 된다.","story":"대관령을 넘으면 기후가 아예 달라진다. 넓은 고원, 거센 바람, 지평선까지 이어지는 풀밭, 그리고 천천히 도는 흰 풍력발전기. 이곳 목장들은 양과 젖소를 키우고, 방문객이 언덕까지 올라가 건초를 먹이도록 개방한다. 겨울에는 눈이 1m 넘게 쌓인다. 2018 평창 동계올림픽이 열린 바로 이 지역이고 스키장은 겨우내 운영된다. 여름 이른 아침에는 아래 골짜기에 안개가 가득한데 언덕 위는 이미 햇살이다.","facts":["대관령 고원의 해발 약 1,000m 지대에 있다.","평창은 2018 동계올림픽을 개최했다.","인근에 방문객에게 개방하는 양떼목장이 여러 곳 있다.","대관령 풍력단지는 한국 최대 규모의 풍력 발전 단지 중 하나다."],"travelTips":["연중 바람이 강하니 여름에도 겉옷을 챙기자.","목장 산책로는 1.2~2km로 걷기 어렵지 않다.","겨울에는 스노타이어를 갖추거나 투어를 이용하자."],"bestTime":"6~9월(초원), 12~2월(설경)","visitDuration":"2~3시간","ticket":"8,000원(어린이·시니어 6,000원), 트랙터마차와 건초주기는 별도","openingHours":"09:00~17:30","galleryCaptions":["초원과 풍력발전기"]},"ja":{"name":"平昌 大関嶺牧場","summary":"標高1,000mの高原に広がる羊の牧草地。冬は2018年五輪の雪国になる。","story":"大関嶺を越えると気候がまるで変わる。広い高原、強い風、地平線まで続く草、そしてゆっくり回る白い風車。ここの牧場は羊と乳牛を育て、来訪者が丘の上まで登って干し草を与えられるよう開放している。冬は雪が1m以上積もる。2018年平昌冬季五輪が開かれたのがまさにこの地域で、スキー場は冬じゅう動いている。夏の早朝は谷に霧が満ち、丘の上だけがもう陽の中にある。","facts":["大関嶺の標高約1,000mに位置する。","平昌は2018年冬季オリンピックを開催した。","周辺には来訪者に開放された羊牧場が複数ある。","大関嶺風力団地は韓国最大級の風力発電集積地のひとつ。"],"travelTips":["一年中風が強い。夏でも上着を持とう。","牧場の散策路は1.2〜2kmで歩きやすい。","冬はスノータイヤかツアー利用が必要。"],"bestTime":"6〜9月（緑の草原）、12〜2月（雪景色）","visitDuration":"2〜3時間","ticket":"8,000ウォン（子ども・シニア6,000）、トラクター馬車と餌やりは別料金","openingHours":"09:00〜17:30","galleryCaptions":["草原と風力発電機"]},"zh":{"name":"平昌大關嶺牧場","summary":"海拔千米高原上的綿羊草場，冬天則是2018年冬奧的雪國。","story":"翻過大關嶺，氣候完全變了：開闊的高原、強風、一直鋪到天際的草地，還有緩緩轉動的白色風機。這裡的牧場養羊與乳牛，並開放旅客走上山丘餵乾草。冬天積雪可達一公尺——正是這片區域主辦了2018年平昌冬季奧運，滑雪場整季運作。夏日清晨，霧氣填滿下方山谷，山丘上卻已是陽光。","facts":["位於大關嶺約海拔1,000公尺處。","平昌主辦了2018年冬季奧運。","周邊有多座對外開放的綿羊牧場。","大關嶺風電場是韓國最大的風機聚落之一。"],"travelTips":["全年風勢強勁，夏天也請帶件外套。","牧場步道長1.2至2公里，走起來輕鬆。","冬天需備雪胎或參加行程。"],"bestTime":"6至9月（綠草）、12至2月（雪景）","visitDuration":"2至3小時","ticket":"8,000韓元（兒童與長者6,000）；牽引車與餵草體驗另計","openingHours":"09:00–17:30","galleryCaptions":["草原與風力發電機"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeongdongjin', 'jeongdongjin', 'gangwon', 'Jeongdongjin', 'Jeongdongjin', 'beach', 129.034, 37.691, 'Nhà ga nằm sát mặt biển nhất thế giới, nơi cả nước đổ về xem mặt trời mọc đêm giao thừa.', 'Sân ga Jeongdongjin chỉ cách sóng vài bước chân — kỷ lục Guinness cho nhà ga gần biển nhất. Sau khi một bộ phim truyền hình đình đám lấy bối cảnh ở đây vào thập niên 90, nơi này thành điểm hẹn của các cặp đôi và người đi đón bình minh. Đêm 31 tháng 12, tàu chạy suốt đêm từ Seoul chở người ra bãi biển chờ mặt trời đầu tiên của năm mới. Trên đồi phía sau là một con tàu du lịch khổng lồ được xây thành khách sạn, nhìn xuống biển.', '["Được Guinness ghi nhận là nhà ga gần biển nhất thế giới.","Nổi tiếng từ bộ phim ''Hourglass'' (1995).","Đồng hồ cát khổng lồ ở công viên bên cạnh quay một vòng mỗi năm.","Tàu đêm giao thừa từ Seoul là truyền thống đón năm mới của nhiều người Hàn."]', '["Đặt vé tàu đêm giao thừa trước hàng tháng nếu muốn đi dịp năm mới.","Bình minh ở đây khoảng 5h sáng mùa hè, 7h30 mùa đông.","Có tàu ray đạp (rail bike) chạy dọc bờ biển gần đó."]', 'Bình minh; đặc biệt ngày 1/1', '2 giờ', '', 'Cả ngày', '["popular"]', '["bình minh","nhà ga","biển"]', '[{"seed":"jeongdongjin","caption":"Sân ga sát mép biển","ratio":"16/9"}]', '["gyeongpo-beach"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Jeongdongjin","summary":"The railway station closest to the sea in the world, where the country gathers for New Year sunrise.","story":"The platform at Jeongdongjin is only a few steps from the surf — a Guinness record for the station nearest the sea. After a hit television drama was filmed here in the nineties the place became a meeting point for couples and sunrise-watchers. On the night of 31 December trains run through the dark from Seoul carrying people out to the beach to wait for the first sun of the year. On the hill behind, an enormous cruise ship built as a hotel looks down over the water.","facts":["Recognised by Guinness as the railway station closest to the sea.","Made famous by the 1995 drama ''Hourglass''.","The giant hourglass in the park beside it turns once a year.","The New Year''s Eve train from Seoul is a Korean tradition."],"travelTips":["Book the New Year''s Eve train months ahead if you want to go then.","Sunrise is around 5am in summer, 7:30am in winter.","Rail bikes run along the coast nearby."],"bestTime":"Sunrise; especially 1 January","visitDuration":"2 hours","ticket":"","openingHours":"All day","galleryCaptions":["The platform at the water''s edge"]},"ko":{"name":"정동진","summary":"세계에서 바다와 가장 가까운 기차역. 새해 첫날 해맞이 인파가 몰린다.","story":"정동진역 승강장은 파도에서 몇 걸음 떨어져 있지 않다. 바다와 가장 가까운 역으로 기네스에 올랐다. 1990년대 인기 드라마의 배경이 된 뒤로 연인과 해맞이 여행객의 약속 장소가 되었다. 12월 31일 밤이면 서울에서 밤새 기차가 달려와 사람들을 해변에 내려놓고, 모두 한 해의 첫 해를 기다린다. 뒤편 언덕에는 호텔로 지은 거대한 유람선이 바다를 내려다보고 서 있다.","facts":["바다에서 가장 가까운 기차역으로 기네스북에 등재되었다.","1995년 드라마 ''모래시계''로 널리 알려졌다.","옆 공원의 거대한 모래시계는 1년에 한 번 돌아간다.","12월 31일 밤 서울발 해맞이 열차는 하나의 전통이다."],"travelTips":["연말 해맞이 열차를 타려면 몇 달 전에 예매해야 한다.","일출은 여름에 5시경, 겨울에 7시 30분경이다.","인근 해안을 따라 레일바이크를 탈 수 있다."],"bestTime":"해돋이 시간, 특히 1월 1일","visitDuration":"2시간","ticket":"","openingHours":"상시","galleryCaptions":["바다에 맞닿은 승강장"]},"ja":{"name":"正東津","summary":"世界で海に最も近い駅。元日の初日の出に全国から人が集まる。","story":"正東津駅のホームは波打ち際から数歩しか離れていない。海に最も近い駅としてギネスに載る。1990年代の人気ドラマの舞台になってから、恋人たちと初日の出を待つ人の待ち合わせ場所になった。12月31日の夜にはソウルから夜通し列車が走り、人々を浜に降ろす。皆で新しい年の最初の太陽を待つのだ。背後の丘には、ホテルとして建てられた巨大な客船が海を見下ろしている。","facts":["海に最も近い鉄道駅としてギネスに認定された。","1995年のドラマ『砂時計』で広く知られるようになった。","隣の公園の巨大な砂時計は一年に一度回転する。","大晦日のソウル発の初日の出列車は一種の伝統だ。"],"travelTips":["年越し列車に乗るなら数か月前の予約が必要。","日の出は夏で5時頃、冬で7時30分頃。","近くの海岸沿いでレールバイクに乗れる。"],"bestTime":"日の出の時間、特に1月1日","visitDuration":"2時間","ticket":"","openingHours":"終日","galleryCaptions":["海に接したホーム"]},"zh":{"name":"正東津","summary":"世界上離海最近的車站，跨年夜全國湧來看第一道曙光。","story":"正東津站的月台距離浪花僅數步之遙——金氏世界紀錄中離海最近的車站。九〇年代一部熱門電視劇在此取景後，這裡成了情侶與看日出者的約定之地。12月31日夜裡，列車自首爾徹夜開來，把人們載到海邊等待新年的第一輪太陽。後方山丘上，一艘蓋成飯店的巨大郵輪俯瞰著海面。","facts":["被金氏世界紀錄認證為離海最近的火車站。","因1995年電視劇《砂時計》而聞名。","旁邊公園的巨型沙漏一年轉動一次。","跨年夜自首爾出發的列車已成韓國人的傳統。"],"travelTips":["想搭跨年列車，得提前數月訂票。","夏季日出約在五點，冬季約七點半。","附近可沿海岸騎鐵路自行車。"],"bestTime":"日出時分，尤其1月1日","visitDuration":"2小時","ticket":"","openingHours":"全日","galleryCaptions":["緊鄰海水的月台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('naksansa', 'naksansa', 'gangwon', 'Chùa Naksansa', 'Naksansa Temple', 'temple', 128.628, 38.123, 'Ngôi chùa trên vách biển với tượng Quan Âm trắng cao 15 mét nhìn ra biển Đông.', 'Naksansa dựng năm 671 trên vách đá nhìn thẳng ra biển, và đình Uisangdae bên mép vực là một trong những chỗ ngắm bình minh nổi tiếng nhất bán đảo. Năm 2005 một trận cháy rừng lớn thiêu rụi phần lớn chùa; tượng Quan Âm bằng đá trắng cao 15 mét đứng nguyên giữa đám cháy, và hình ảnh đó trở thành biểu tượng của việc dựng lại. Chùa nay đã được phục hồi, chuông đồng mới đúc, nhưng những gốc thông cháy đen vẫn còn trên sườn đồi.', '["Được dựng năm 671 bởi đại sư Uisang thời Silla.","Tượng Quan Âm bằng đá trắng cao 15m, hoàn thành năm 1977.","Trận cháy rừng năm 2005 thiêu rụi phần lớn chùa, sau đó được phục dựng.","Đình Uisangdae bên vách biển là điểm ngắm bình minh nổi tiếng."]', '["Đi lúc bình minh, kết hợp bãi biển Naksan ngay dưới chân chùa.","Cách Sokcho khoảng 20 phút xe, tiện ghép với Seoraksan.","Có chương trình templestay nhìn ra biển."]', 'Quanh năm, đẹp nhất lúc bình minh', '1,5 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '05:00–19:00', '["hidden-gem"]', '["chùa","biển","bình minh"]', '[{"seed":"naksansa","caption":"Tượng Quan Âm nhìn ra biển","ratio":"16/9"}]', '["seoraksan"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Naksansa Temple","summary":"A clifftop temple with a 15-metre white Avalokiteshvara looking out over the East Sea.","story":"Naksansa was founded in 671 on a cliff facing the sea, and its Uisangdae pavilion on the edge is one of the country''s best-known sunrise spots. In 2005 a great forest fire burned most of the temple down; the 15-metre white stone Avalokiteshvara stood untouched in the middle of the flames, and that image became the symbol of the rebuilding. The temple has since been restored and a new bronze bell cast, but blackened pine stumps still stand on the hillside.","facts":["Founded in 671 by the monk Uisang of Silla.","The white stone Avalokiteshvara, 15m tall, was completed in 1977.","A 2005 forest fire destroyed much of the temple, which was then rebuilt.","Uisangdae pavilion on the cliff is a famous sunrise viewpoint."],"travelTips":["Come at sunrise and combine it with Naksan beach below.","About 20 minutes from Sokcho, easy to pair with Seoraksan.","A templestay programme runs here, facing the sea."],"bestTime":"Year-round, best at sunrise","visitDuration":"1.5 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"05:00–19:00","galleryCaptions":["The Avalokiteshvara looking out to sea"]},"ko":{"name":"낙산사","summary":"동해를 내려다보는 절벽 위 사찰. 15m 백색 해수관음상이 서 있다.","story":"낙산사는 671년 바다를 향한 절벽 위에 세워졌고, 벼랑 끝 의상대는 한국에서 손꼽히는 해돋이 명소다. 2005년 큰 산불이 절 대부분을 태웠는데, 15m 높이의 흰 해수관음상은 불길 한가운데 그대로 서 있었고 그 모습이 재건의 상징이 되었다. 지금은 복원이 끝나고 범종도 새로 주조되었지만, 산비탈에는 아직 검게 그을린 소나무 밑동이 남아 있다.","facts":["671년 신라의 의상대사가 창건했다.","높이 15m의 해수관음상은 1977년에 완성되었다.","2005년 산불로 대부분이 소실된 뒤 복원되었다.","절벽 위 의상대는 유명한 해돋이 명소다."],"travelTips":["해돋이 시간에 맞춰 가서 아래 낙산해변까지 함께 걷자.","속초에서 20분 거리라 설악산과 묶기 좋다.","바다가 보이는 템플스테이가 운영된다."],"bestTime":"연중, 해돋이 시간이 가장 좋다","visitDuration":"1시간 30분","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"05:00~19:00","galleryCaptions":["바다를 바라보는 해수관음상"]},"ja":{"name":"洛山寺","summary":"東海を見下ろす崖の上の寺。15mの白い海水観音像が立つ。","story":"洛山寺は671年、海に向かう崖の上に建てられ、崖際の義湘台は韓国屈指の日の出の名所だ。2005年の大きな山火事で寺の大半が焼けたが、高さ15mの白い海水観音像は炎の中に無傷で立ち、その姿が再建の象徴となった。今は復元が終わり梵鐘も新たに鋳造されたが、斜面にはまだ黒く焦げた松の根元が残っている。","facts":["671年、新羅の義湘大師が創建した。","高さ15mの海水観音像は1977年に完成した。","2005年の山火事で大半が焼失し、その後復元された。","崖の上の義湘台は有名な日の出スポット。"],"travelTips":["日の出に合わせて行き、下の洛山海水浴場まで歩こう。","束草から20分ほどなので雪岳山と組み合わせやすい。","海を望むテンプルステイが運営されている。"],"bestTime":"通年、日の出の時間が最良","visitDuration":"1時間30分","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"05:00〜19:00","galleryCaptions":["海を見つめる海水観音像"]},"zh":{"name":"洛山寺","summary":"崖上的海邊古寺，十五公尺高的白色觀音望向東海。","story":"洛山寺始建於671年，坐落在面海的崖壁上，崖邊的義湘台是韓國最著名的日出點之一。2005年一場大森林火燒毀了大半寺院，十五公尺高的白石觀音卻在火中安然無恙，那個畫面成了重建的象徵。如今寺院已修復，新鑄了梵鐘，但山坡上仍留著被燒黑的松樹殘幹。","facts":["671年由新羅義湘大師創建。","十五公尺高的白石觀音像完成於1977年。","2005年森林大火燒毀大部分寺院，其後重建。","崖上的義湘台是著名的日出觀景點。"],"travelTips":["配合日出前來，並順道走訪下方的洛山海灘。","距束草約二十分鐘，很適合與雪嶽山一起安排。","此地有面海的寺院寄宿（templestay）。"],"bestTime":"全年，日出時分最佳","visitDuration":"1.5小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"05:00–19:00","galleryCaptions":["望向大海的觀音像"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('nami-island', 'nami-island', 'gangwon', 'Đảo Nami', 'Nami Island', 'island', 127.5255, 37.7905, 'Hòn đảo hình bán nguyệt với những hàng cây thẳng tắp đổi màu bốn lần mỗi năm.', 'Nami là một hòn đảo nhân tạo — nó xuất hiện khi đập Cheongpyeong tích nước và nhấn chìm phần đất nối với bờ. Cái làm nên tên tuổi của nó là những hàng cây trồng thẳng như kẻ chỉ: hàng ngân hạnh, hàng thuỷ sam, hàng bạch dương, mỗi hàng dài vài trăm mét và đổi màu theo mùa. Bộ phim truyền hình quay ở đây đầu những năm 2000 biến hòn đảo thành điểm hành hương của khách châu Á, và đến giờ vẫn thế. Đảo tự tuyên bố là ''Cộng hoà Naminara'' với hộ chiếu và tem riêng — một trò đùa được duy trì nghiêm túc đến mức có cả quầy hải quan.', '["Là đảo nhân tạo hình thành khi đập Cheongpyeong tích nước năm 1944.","Tên đảo lấy theo mộ tướng quân Nami thời Joseon nằm trên đảo.","Tự xưng là ''Cộng hoà Naminara'' từ năm 2006, có hộ chiếu và tem riêng.","Có thể vào đảo bằng phà hoặc bằng cáp trượt zipline từ bờ."]', '["Đi zipline từ bờ vào đảo nếu muốn khác với đám đông đi phà.","Cuối tuần rất đông khách đoàn — đi ngày thường hoặc chuyến phà sớm nhất.","Kết hợp với Vườn Bình minh Tĩnh lặng và Petite France cùng vùng Gapyeong."]', 'Cuối tháng 10 đến giữa tháng 11 (lá vàng)', 'Nửa ngày', '19.000 KRW (đã gồm phà khứ hồi); tăng 3.000 so với năm trước', '08:00–21:00, mở quanh năm; phà chuyến cuối 21:05', '["popular"]', '["đảo","hàng cây","mùa thu","phim trường"]', '[{"seed":"nami-island","caption":"Hàng thuỷ sam trên đảo Nami","ratio":"16/9"}]', '["chuncheon-soyang","daegwallyeong-sky-ranch"]', 1, 'https://namu.wiki/w/%EB%82%A8%EC%9D%B4%EC%84%AC', '2026-08-04', '{"en":{"name":"Nami Island","summary":"A crescent island of dead-straight tree avenues that change colour four times a year.","story":"Nami is a man-made island — it appeared when the Cheongpyeong dam filled and drowned the land that joined it to the shore. What made its name are the avenues planted arrow-straight: ginkgo, metasequoia, birch, each a few hundred metres long and each turning with the season. A television drama shot here in the early 2000s made the island a pilgrimage for Asian visitors, and it still is. The island declares itself the ''Naminara Republic'', with its own passport and stamps — a joke maintained so seriously that there is a customs desk.","facts":["A man-made island, formed when the Cheongpyeong dam filled in 1944.","Named after the tomb of General Nami of the Joseon era, which lies on the island.","It has styled itself the ''Naminara Republic'' since 2006, with its own passport and stamps.","You can arrive by ferry or by zipline from the shore."],"travelTips":["Take the zipline over if you''d rather not join the ferry queue.","Weekends bring coach parties — come on a weekday or on the first ferry.","Combine it with the Garden of Morning Calm and Petite France in the Gapyeong area."],"bestTime":"Late October to mid-November (autumn colour)","visitDuration":"Half a day","ticket":"19,000 KRW including the return ferry (up 3,000 on last year)","openingHours":"08:00–21:00, open year-round; last ferry 21:05","galleryCaptions":["The metasequoia avenue on Nami"]},"ko":{"name":"남이섬","summary":"반달 모양 섬. 곧게 뻗은 나무 길이 해마다 네 번 색을 바꾼다.","story":"남이섬은 사람이 만든 섬이다. 청평댐이 물을 채우면서 뭍과 이어진 땅이 잠겨 섬이 되었다. 이름을 알린 것은 자로 잰 듯 곧게 심은 나무 길이다. 은행나무길, 메타세쿼이아길, 자작나무길. 저마다 수백 미터씩 이어지며 계절마다 색이 달라진다. 2000년대 초의 드라마가 이 섬을 아시아 관광객의 순례지로 만들었고, 지금도 그렇다. 섬은 스스로 ''나미나라공화국''을 표방해 여권과 우표를 만든다. 입국 심사대까지 둘 만큼 진지하게 이어 가는 농담이다.","facts":["1944년 청평댐 담수로 생긴 인공 섬이다.","섬에 있는 조선 시대 남이 장군의 묘에서 이름을 따왔다.","2006년부터 ''나미나라공화국''을 표방하며 자체 여권과 우표를 발행한다.","배를 타거나 뭍에서 짚와이어로 들어갈 수 있다."],"travelTips":["배 대기줄이 싫다면 짚와이어로 건너가자.","주말에는 단체 관광객이 많다. 평일이나 첫 배를 타자.","가평권의 아침고요수목원, 쁘띠프랑스와 묶어서 보자."],"bestTime":"10월 말~11월 중순(단풍)","visitDuration":"반나절","ticket":"19,000원(왕복 배삯 포함), 지난해보다 3,000원 인상","openingHours":"08:00~21:00, 연중무휴(막배 21:05)","galleryCaptions":["남이섬의 메타세쿼이아길"]},"ja":{"name":"南怡島","summary":"半月形の島。まっすぐ伸びた並木が年に四度、色を変える。","story":"南怡島は人の手が生んだ島だ。清平ダムが水を満たし、陸と繋がっていた部分が沈んで島になった。名を知らしめたのは定規で引いたように植えられた並木である。イチョウ並木、メタセコイア並木、シラカバ並木。それぞれ数百メートル続き、季節ごとに色が変わる。二〇〇〇年代初めのドラマがこの島をアジアの旅行者の巡礼地にし、今もそれは続いている。島は自ら「ナミナラ共和国」を名乗り、独自の旅券と切手を作る。入国審査台まで置くほど真面目に続けられている冗談だ。","facts":["1944年、清平ダムの湛水によって生まれた人工の島である。","島にある朝鮮時代の南怡将軍の墓に由来する名。","2006年から「ナミナラ共和国」を名乗り、独自の旅券と切手を発行している。","船で渡るほか、陸からジップラインで入ることもできる。"],"travelTips":["船の行列が嫌ならジップラインで渡ろう。","週末は団体客が多い。平日か始発の船に。","加平圏の晨静樹木園やプチフランスと合わせて回ろう。"],"bestTime":"10月末〜11月中旬（紅葉）","visitDuration":"半日","ticket":"19,000ウォン（往復の船代込み）、前年より3,000ウォン値上げ","openingHours":"08:00〜21:00、年中無休（最終便21:05）","galleryCaptions":["南怡島のメタセコイア並木"]},"zh":{"name":"南怡島","summary":"半月形的島，筆直的林蔭道一年變四次顏色。","story":"南怡島是人造出來的島——清平水壩蓄水後淹沒了與陸地相連的那段地，它才成了島。真正讓它出名的是那些種得筆直如尺的林蔭道：銀杏道、水杉道、白樺道，每一條數百公尺長，各自隨季節換色。2000年代初的一部電視劇讓這座島成了亞洲旅人的朝聖地，至今依然。島上自稱「南怡共和國」，發行自己的護照與郵票——一個認真到設有入境櫃檯的玩笑。","facts":["1944年清平水壩蓄水後形成的人造島。","島名取自島上朝鮮時代南怡將軍之墓。","自2006年起自稱「南怡共和國」，發行自有護照與郵票。","可搭船前往，也可從岸邊搭高空滑索入島。"],"travelTips":["不想排渡船隊伍，就搭滑索過去。","週末團客很多，建議平日或搭第一班船。","可與加平一帶的晨靜樹木園、小法國村排在一起。"],"bestTime":"10月底至11月中旬（秋色）","visitDuration":"半天","ticket":"19,000韓元（含來回船資），較去年調漲3,000韓元","openingHours":"08:00–21:00，全年無休（末班船21:05）","galleryCaptions":["南怡島的水杉大道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('chuncheon-soyang', 'chuncheon-soyang', 'gangwon', 'Chuncheon & hồ Soyang', 'Chuncheon & Soyang Lake', 'lake', 127.7395, 37.8815, 'Thành phố nằm giữa ba hồ nước, quê hương của món gà xào cay dakgalbi.', 'Chuncheon bị bao bởi nước từ mọi phía — ba con đập trên sông Bukhan biến các thung lũng quanh thành phố thành hồ, và sương mù buổi sáng từ mặt hồ tràn vào phố là chuyện thường ngày. Hồ Soyang là hồ nhân tạo lớn nhất Hàn Quốc; phà chạy từ bến Soyang tới chùa Cheongpyeongsa nằm khuất trong núi, và chặng đi bộ từ bến lên chùa đi ngang một thác nước nhỏ. Ở trung tâm thành phố có cả một con phố chỉ bán dakgalbi — gà xào cải bắp, khoai lang và tteok trên chảo gang lớn, ăn xong đổ cơm vào chảo rang nốt phần sốt còn lại.', '["Hồ Soyang là hồ nhân tạo lớn nhất Hàn Quốc, hình thành từ đập Soyanggang năm 1973.","Chuncheon là thủ phủ tỉnh Gangwon.","Món dakgalbi ra đời tại đây vào thập niên 1960.","Chùa Cheongpyeongsa chỉ vào được bằng phà rồi đi bộ tiếp khoảng 20 phút."]', '["Tàu ITX từ ga Yongsan (Seoul) tới Chuncheon mất khoảng 1 giờ 10 phút.","Ăn dakgalbi ở phố Myeongdong Chuncheon, gọi thêm cơm rang cuối bữa.","Phà đi Cheongpyeongsa thưa chuyến vào mùa đông, kiểm tra giờ chót."]', 'Tháng 5–6 và 9–11', 'Nửa ngày', 'Phà lên Cheongpyeongsa khoảng 5.500–6.000 KRW khứ hồi (một chiều 3.000), mất 10 phút', 'Phà 09:00–17:00', '["popular"]', '["hồ","dakgalbi","phà","chùa"]', '[{"seed":"chuncheon-soyang","caption":"Sương sớm trên hồ Soyang","ratio":"16/9"}]', '["nami-island"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=81429', '2026-08-04', '{"en":{"name":"Chuncheon & Soyang Lake","summary":"A city ringed by three lakes, and the birthplace of dakgalbi.","story":"Chuncheon is surrounded by water on every side — three dams on the Bukhan turned the valleys around the city into lakes, and morning mist rolling off the water into the streets is routine. Soyang is Korea''s largest artificial lake; a ferry runs from Soyang pier to Cheongpyeongsa temple hidden up in the mountains, and the walk up from the landing passes a small waterfall. In the centre of town there is a whole street of dakgalbi — chicken fried with cabbage, sweet potato and rice cake on a large iron pan, finished by tipping rice in to fry up whatever sauce is left.","facts":["Soyang Lake is Korea''s largest artificial lake, created by the Soyanggang dam in 1973.","Chuncheon is the capital of Gangwon province.","Dakgalbi was invented here in the 1960s.","Cheongpyeongsa temple is reached by ferry and then about a 20-minute walk."],"travelTips":["The ITX from Yongsan station in Seoul takes about 1 hour 10 minutes.","Eat dakgalbi on Chuncheon''s Myeongdong street, and order the fried rice at the end.","Ferries to Cheongpyeongsa thin out in winter — check the last departure."],"bestTime":"May–June and September–November","visitDuration":"Half a day","ticket":"The ferry to Cheongpyeongsa is about 5,500–6,000 KRW return (3,000 one way), a 10-minute crossing","openingHours":"Ferry 09:00–17:00","galleryCaptions":["Morning mist on Soyang Lake"]},"ko":{"name":"춘천과 소양호","summary":"세 개의 호수에 둘러싸인 도시. 닭갈비가 태어난 곳이다.","story":"춘천은 사방이 물이다. 북한강의 댐 세 개가 도시 주변 골짜기를 호수로 바꾸었고, 아침이면 물에서 오른 안개가 거리로 흘러드는 일이 예사다. 소양호는 한국에서 가장 큰 인공호수다. 소양강 선착장에서 배를 타면 산속에 숨은 청평사에 닿고, 선착장에서 절까지 걷는 길에는 작은 폭포가 있다. 도심에는 닭갈비만 파는 골목이 통째로 있다. 큰 무쇠판에 닭과 양배추, 고구마, 떡을 볶고, 마지막에 밥을 넣어 남은 양념까지 볶아 먹는다.","facts":["소양호는 1973년 소양강댐으로 생긴 한국 최대의 인공호수다.","춘천은 강원특별자치도의 도청 소재지다.","닭갈비는 1960년대 이곳에서 시작되었다.","청평사는 배를 탄 뒤 20분쯤 더 걸어야 닿는다."],"travelTips":["서울 용산역에서 ITX로 1시간 10분쯤 걸린다.","춘천 명동 골목에서 닭갈비를 먹고 마지막에 볶음밥을 시키자.","겨울에는 청평사행 배편이 줄어든다. 막배 시간을 확인하자."],"bestTime":"5~6월, 9~11월","visitDuration":"반나절","ticket":"청평사행 배는 왕복 약 5,500~6,000원(편도 3,000원), 편도 10분","openingHours":"배편 09:00~17:00","galleryCaptions":["소양호의 아침 안개"]},"ja":{"name":"春川と昭陽湖","summary":"三つの湖に囲まれた街。タッカルビが生まれた場所だ。","story":"春川は四方が水だ。北漢江の三つのダムが街の周りの谷を湖に変え、朝に水から立った霧が通りへ流れ込むのは日常である。昭陽湖は韓国最大の人造湖だ。昭陽江の船着場から船に乗ると山中に隠れた清平寺に着き、船着場から寺までの道には小さな滝がある。中心街にはタッカルビだけを出す通りが丸ごとある。大きな鉄板で鶏とキャベツ、サツマイモ、餅を炒め、最後に飯を入れて残ったタレごと炒めて食べる。","facts":["昭陽湖は1973年の昭陽江ダムでできた韓国最大の人造湖である。","春川は江原特別自治道の道庁所在地。","タッカルビは1960年代にこの地で生まれた。","清平寺は船に乗ったあと、さらに20分ほど歩いて着く。"],"travelTips":["ソウルの龍山駅からITXで1時間10分ほど。","春川の明洞通りでタッカルビを食べ、最後に炒め飯を頼もう。","冬は清平寺行きの船便が減る。最終便を確認しよう。"],"bestTime":"5〜6月、9〜11月","visitDuration":"半日","ticket":"清平寺行きの船は往復約5,500〜6,000ウォン（片道3,000）、片道10分","openingHours":"船便09:00〜17:00","galleryCaptions":["昭陽湖の朝霧"]},"zh":{"name":"春川與昭陽湖","summary":"被三座湖圍住的城市，也是辣炒雞排的發源地。","story":"春川四面環水——北漢江上的三座水壩把城市周圍的谷地變成湖泊，清晨水氣化霧漫進街道是家常便飯。昭陽湖是韓國最大的人工湖；渡船自昭陽江碼頭開往藏在山裡的清平寺，從碼頭走上寺的路上會經過一道小瀑布。市中心有一整條只賣辣炒雞排的街：雞肉與高麗菜、地瓜、年糕在大鐵盤上同炒，最後倒進白飯，把剩下的醬汁一起炒成飯。","facts":["昭陽湖是1973年昭陽江水壩造成的韓國最大人工湖。","春川是江原特別自治道的道廳所在地。","辣炒雞排於1960年代在此誕生。","清平寺須先搭船，再步行約20分鐘才到。"],"travelTips":["自首爾龍山站搭ITX約1小時10分鐘。","在春川明洞街吃辣炒雞排，最後別忘了點炒飯。","冬季往清平寺的船班變少，請確認末班時間。"],"bestTime":"5至6月與9至11月","visitDuration":"半天","ticket":"往清平寺的渡船來回約5,500至6,000韓元（單程3,000），航程10分鐘","openingHours":"船班09:00–17:00","galleryCaptions":["昭陽湖的晨霧"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hwanseongul-cave', 'hwanseongul-cave', 'gangwon', 'Hang Hwanseongul (Samcheok)', 'Hwanseongul Cave, Samcheok', 'cave', 129.0355, 37.2955, 'Hang đá vôi lớn nhất Đông Á, có những khoang trần cao tới ba mươi mét và thác nước chảy trong lòng núi.', 'Hwanseongul là hệ hang đá vôi lớn nhất Đông Á: hơn sáu cây số đường hang đã khảo sát, trong đó chừng một phần tư mở cho khách. Đây không phải loại hang có măng đá tinh xảo mà là hang của quy mô — những khoang rộng như nhà thờ với trần cao ba mươi mét, cầu thang sắt bắc qua vực, và một thác nước ngầm đổ xuống trong bóng tối. Để vào hang phải đi monorail dốc gần bốn mươi độ lên sườn núi trước. Nhiệt độ trong hang giữ khoảng mười độ quanh năm nên mùa hè đây là một trong những chỗ mát nhất Gangwon.', '["Là hang đá vôi lớn nhất Đông Á, tổng chiều dài khảo sát hơn 6,2 km.","Được công nhận là Đài kỷ niệm thiên nhiên số 178.","Nhiệt độ trong hang giữ khoảng 10–12°C quanh năm.","Vào hang bằng monorail leo dốc khoảng 38 độ."]', '["Mang áo khoác — trong hang lạnh kể cả giữa tháng 8.","Có nhiều bậc thang sắt dốc và ẩm, không hợp người ngại độ cao.","Kết hợp với hang Daegeumgul gần đó nếu còn thời gian."]', 'Tháng 6–9 (tránh nóng), quanh năm', '2 giờ', '4.500 KRW; monorail lên hang 7.000 KRW khứ hồi (một chiều 4.000)', '08:30–17:00', '["hidden-gem"]', '["hang động","đá vôi","mát mẻ","monorail"]', '[{"seed":"hwanseongul-cave","caption":"Khoang hang trần cao Hwanseongul","ratio":"16/9"}]', '["jeongdongjin"]', 0, 'https://www.samcheok.go.kr/tour/01456/01464/02195.web', '2026-08-04', '{"en":{"name":"Hwanseongul Cave, Samcheok","summary":"East Asia''s largest limestone cave, with chambers thirty metres high and a waterfall inside the mountain.","story":"Hwanseongul is the largest limestone cave system in East Asia: over six kilometres surveyed, of which about a quarter is open. This is not a cave of delicate formations but a cave of scale — chambers like cathedrals with ceilings thirty metres up, steel stairs bridging drops, and an underground waterfall falling in the dark. To reach the entrance you first ride a monorail up a slope of nearly forty degrees. The cave holds around ten degrees all year, making it one of the coolest places in Gangwon in summer.","facts":["East Asia''s largest limestone cave, with over 6.2km surveyed.","Designated Natural Monument No. 178.","The cave holds about 10–12°C year-round.","Access is by a monorail climbing a slope of roughly 38 degrees."],"travelTips":["Bring a jacket — it is cold inside even in August.","There are many steep, damp steel stairways; not for anyone uneasy with heights.","Add the nearby Daegeumgul cave if you have time."],"bestTime":"June–September to escape the heat, or year-round","visitDuration":"2 hours","ticket":"4,500 KRW; the monorail up to the cave is 7,000 KRW return (4,000 one way)","openingHours":"08:30–17:00","galleryCaptions":["A high chamber inside Hwanseongul"]},"ko":{"name":"삼척 환선굴","summary":"동아시아 최대 석회동굴. 천장이 30m에 이르는 공간과 산속을 흐르는 폭포가 있다.","story":"환선굴은 동아시아에서 가장 큰 석회동굴계다. 6km 넘게 조사되었고 그중 4분의 1쯤이 개방되어 있다. 섬세한 종유석의 동굴이 아니라 규모의 동굴이다. 천장이 30m까지 솟은 성당 같은 공간, 낭떠러지를 건너는 철제 계단, 어둠 속으로 떨어지는 지하 폭포가 있다. 입구까지 가려면 먼저 경사 40도에 가까운 모노레일을 타야 한다. 굴 안은 연중 10도 안팎이라 여름에는 강원도에서 가장 시원한 곳 가운데 하나다.","facts":["동아시아 최대 석회동굴로 조사된 총 길이는 6.2km가 넘는다.","천연기념물 제178호로 지정되어 있다.","굴 내부는 연중 10~12도를 유지한다.","경사 약 38도의 모노레일을 타고 입구까지 오른다."],"travelTips":["겉옷을 챙기자. 8월에도 안은 춥다.","가파르고 젖은 철계단이 많다. 고소공포가 있다면 무리다.","시간이 남으면 가까운 대금굴도 함께 보자."],"bestTime":"6~9월(더위 피하기), 혹은 연중","visitDuration":"2시간","ticket":"4,500원, 동굴까지 모노레일은 왕복 7,000원(편도 4,000원)","openingHours":"08:30~17:00","galleryCaptions":["환선굴의 높은 광장"]},"ja":{"name":"三陟幻仙窟","summary":"東アジア最大の石灰洞。天井が30mに達する空間と、山の中を落ちる滝がある。","story":"幻仙窟は東アジア最大の石灰洞系だ。6kmを超えて調査され、その四分の一ほどが開放されている。繊細な鍾乳石の洞ではなく、規模の洞である。天井が30mまで届く聖堂のような空間、断崖を渡る鉄の階段、闇へ落ちる地下の滝がある。入口へ行くにはまず傾斜四十度近いモノレールに乗る。洞内は年中十度前後で、夏には江原道で最も涼しい場所のひとつになる。","facts":["東アジア最大の石灰洞で、調査済みの総延長は6.2kmを超える。","天然記念物第178号に指定されている。","洞内は年間を通じて10〜12度を保つ。","入口までは傾斜約38度のモノレールで上がる。"],"travelTips":["上着を持とう。8月でも中は寒い。","急で濡れた鉄階段が多い。高所が苦手なら無理をしないこと。","時間があれば近くの大金窟も合わせて。"],"bestTime":"6〜9月（暑さしのぎ）、または通年","visitDuration":"2時間","ticket":"4,500ウォン、洞窟までのモノレールは往復7,000ウォン（片道4,000）","openingHours":"08:30〜17:00","galleryCaptions":["幻仙窟の高い広間"]},"zh":{"name":"三陟幻仙窟","summary":"東亞最大的石灰岩洞，有高達三十公尺的洞廳，以及落在山腹之中的瀑布。","story":"幻仙窟是東亞最大的石灰岩洞系統：已探測逾六公里，其中約四分之一開放參觀。這不是以精緻鐘乳石取勝的洞窟，而是以尺度取勝——像教堂一樣、天花板高達三十公尺的洞廳，跨越深谷的鐵梯，以及一道在黑暗中落下的地下瀑布。要抵達洞口，得先搭上坡度近四十度的單軌車。洞內全年維持約十度，是夏天江原道最涼快的地方之一。","facts":["東亞最大的石灰岩洞，已探測總長逾6.2公里。","被指定為天然紀念物第178號。","洞內全年維持攝氏10至12度。","以坡度約38度的單軌車上抵洞口。"],"travelTips":["帶件外套——八月裡頭一樣冷。","陡峭潮濕的鐵梯很多，怕高的人不宜。","時間夠的話，可順道看鄰近的大金窟。"],"bestTime":"6至9月（避暑），或全年皆宜","visitDuration":"2小時","ticket":"4,500韓元；上洞窟的單軌來回7,000韓元（單程4,000）","openingHours":"08:30–17:00","galleryCaptions":["幻仙窟中的高聳洞廳"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('odaesan-woljeongsa', 'odaesan-woljeongsa', 'gangwon', 'Núi Odaesan & chùa Woljeongsa', 'Odaesan & Woljeongsa Temple', 'temple', 128.5925, 37.7315, 'Con đường thông cổ thụ dài một cây số dẫn vào ngôi chùa giữ tháp đá tám cạnh chín tầng.', 'Trước khi tới chùa Woljeongsa, bạn đi qua thứ đáng nhớ nhất: một cây số đường đất giữa hai hàng thông đỏ cổ thụ, thân thẳng đứng cao vút, mặt đất phủ kim thông êm như thảm. Người ta gọi đó là ''con đường ngàn năm''. Cuối đường là chùa, và giữa sân là tháp đá tám cạnh chín tầng thời Goryeo — hiếm, vì tháp Hàn Quốc thường bốn cạnh — với một pho tượng Bồ Tát quỳ dâng hương trước tháp. Odaesan là dãy núi lớn với rừng thông trải rộng nhất Hàn Quốc, và đường mòn từ chùa lên chùa Sangwonsa rồi lên đỉnh Birobong đi mất cả ngày.', '["Đường thông đỏ ''Thiên niên'' dẫn vào chùa dài khoảng 1 km.","Tháp đá tám cạnh chín tầng của Woljeongsa là quốc bảo thời Goryeo.","Odaesan có diện tích rừng thông đỏ lớn nhất Hàn Quốc.","Chùa có chương trình templestay cho cả khách nước ngoài."]', '["Đi vào sáng sớm khi sương còn đọng giữa hàng thông.","Từ Woljeongsa lên Sangwonsa có xe buýt nhỏ nếu không muốn đi bộ.","Mùa đông đường mòn đóng băng, cần đế đinh."]', 'Tháng 5–6 và 10 (lá đỏ)', 'Nửa ngày', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["hidden-gem","verified"]', '["chùa","rừng thông","templestay","quốc bảo"]', '[{"seed":"odaesan-woljeongsa","caption":"Đường thông đỏ dẫn vào chùa","ratio":"16/9"}]', '["daegwallyeong-sky-ranch","seoraksan"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Odaesan & Woljeongsa Temple","summary":"A kilometre of ancient pines leading to a temple that holds a nine-storey octagonal stone pagoda.","story":"Before you reach Woljeongsa you pass the most memorable part: a kilometre of dirt track between two ranks of old red pines, trunks running straight up, the ground soft with needles. They call it the thousand-year road. At the end is the temple, and in its courtyard a nine-storey octagonal stone pagoda from the Goryeo era — unusual, since Korean pagodas are normally square — with a stone bodhisattva kneeling in offering before it. Odaesan is a large massif holding Korea''s most extensive red pine forest, and the trail from the temple up to Sangwonsa and on to Birobong summit takes a full day.","facts":["The ''thousand-year'' red pine road into the temple runs about 1km.","Woljeongsa''s nine-storey octagonal pagoda is a national treasure of the Goryeo era.","Odaesan holds the largest area of red pine forest in Korea.","The temple runs a templestay open to foreign visitors."],"travelTips":["Come early, while mist still hangs between the pines.","A shuttle bus runs from Woljeongsa up to Sangwonsa if you''d rather not walk.","The trail ices over in winter; crampons are needed."],"bestTime":"May–June and October (autumn colour)","visitDuration":"Half a day","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["The red pine road into the temple"]},"ko":{"name":"오대산 월정사","summary":"1km의 전나무 숲길이 팔각구층석탑을 품은 절로 이어진다.","story":"월정사에 닿기 전, 가장 기억에 남는 구간을 지난다. 아름드리 전나무가 양옆으로 늘어선 1km의 흙길이다. 줄기는 곧게 솟고 바닥은 낙엽으로 푹신하다. 사람들은 그 길을 천년의 숲길이라 부른다. 길 끝에 절이 있고, 마당 한가운데에 고려의 팔각구층석탑이 서 있다. 한국의 탑은 대개 사각이라 팔각은 드물다. 탑 앞에는 무릎 꿇고 공양하는 석조보살좌상이 있다. 오대산은 한국에서 전나무 숲이 가장 넓은 큰 산이고, 절에서 상원사를 지나 비로봉까지 오르면 하루가 걸린다.","facts":["절로 드는 ''천년의 숲길'' 전나무길은 약 1km다.","월정사 팔각구층석탑은 고려 시대의 국보다.","오대산은 한국에서 전나무 숲 면적이 가장 넓다.","외국인도 참여할 수 있는 템플스테이를 운영한다."],"travelTips":["전나무 사이에 안개가 남아 있는 이른 아침에 가자.","걷기 부담되면 월정사에서 상원사까지 셔틀버스가 있다.","겨울에는 길이 얼어 아이젠이 필요하다."],"bestTime":"5~6월, 10월(단풍)","visitDuration":"반나절","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["절로 드는 전나무 숲길"]},"ja":{"name":"五台山月精寺","summary":"1kmのモミの林道が、八角九層石塔を抱く寺へ続く。","story":"月精寺に着く前に、最も記憶に残る区間を通る。太いモミが両側に並ぶ1kmの土の道だ。幹はまっすぐ立ち、地面は落葉でやわらかい。人はそれを千年の森の道と呼ぶ。道の果てに寺があり、境内の真ん中に高麗の八角九層石塔が立つ。韓国の塔はたいてい四角なので八角は珍しい。塔の前には膝をついて供養する石造菩薩坐像がある。五台山は韓国で最もモミ林の広い大きな山で、寺から上院寺を経て毘盧峰まで登れば一日かかる。","facts":["寺へ入る「千年の森の道」のモミ並木は約1km。","月精寺の八角九層石塔は高麗時代の国宝である。","五台山は韓国で最もモミ林の面積が広い。","外国人も参加できるテンプルステイを行っている。"],"travelTips":["モミの間に霧が残る早朝に行こう。","歩くのが大変なら月精寺から上院寺までシャトルバスがある。","冬は道が凍り、アイゼンが要る。"],"bestTime":"5〜6月と10月（紅葉）","visitDuration":"半日","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["寺へ続くモミの森の道"]},"zh":{"name":"五台山月精寺","summary":"一公里的冷杉林道，通往藏著八角九層石塔的寺院。","story":"抵達月精寺之前，你會先走過最令人難忘的一段：一公里長的土路，兩側是參天的老紅松與冷杉，樹幹筆直向上，地面鋪滿柔軟的落葉。人們稱它為千年之森的路。路的盡頭是寺院，庭院正中立著一座高麗時代的八角九層石塔——相當罕見，因為韓國的塔多為四方形——塔前還有一尊跪姿供養的石造菩薩坐像。五台山是韓國冷杉林面積最大的山塊，從寺院經上院寺登到毘盧峰，得走上一整天。","facts":["通往寺院的「千年之森」冷杉道約長1公里。","月精寺八角九層石塔是高麗時代的國寶。","五台山擁有韓國面積最大的冷杉林。","寺方經營對外國訪客開放的寺廟寄宿。"],"travelTips":["趁清早前往，霧氣還留在林間。","不想走路的話，月精寺到上院寺之間有接駁巴士。","冬季步道結冰，需要冰爪。"],"bestTime":"5至6月與10月（紅葉）","visitDuration":"半天","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["通往寺院的冷杉林道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gangneung-anmok-coffee', 'gangneung-anmok-coffee', 'gangwon', 'Phố cà phê Anmok (Gangneung)', 'Anmok Coffee Street, Gangneung', 'city', 128.9475, 37.7735, 'Bãi biển có cả một dãy quán cà phê rang xay, bắt đầu từ những máy bán cà phê tự động bên bờ cát.', 'Chuyện bắt đầu rất đời thường: thập niên 1980, người ta đặt vài chiếc máy bán cà phê tự động dọc bãi Anmok cho khách uống lúc ngắm biển, và dần thành thói quen của cả vùng. Rồi các thợ rang cà phê chuyển về, mở quán ngay sát mép cát, và giờ Gangneung tự nhận là thủ phủ cà phê của Hàn Quốc với lễ hội cà phê riêng vào tháng 10. Điều thú vị là các máy bán tự động cũ vẫn còn đó, đứng cạnh những quán rang xay cầu kỳ — và nhiều người địa phương vẫn chọn cái máy. Uống một ly rồi đi bộ dọc bờ, gió biển Đông thổi ngược, là cách người Gangneung mở đầu buổi sáng.', '["Phố cà phê hình thành từ những máy bán tự động đặt trên bãi biển thập niên 1980.","Gangneung tổ chức Lễ hội Cà phê Gangneung vào tháng 10 hằng năm.","Có hàng chục quán rang xay tại chỗ dọc bãi Anmok.","Bãi biển quay hướng đông, là điểm ngắm bình minh."]', '["Tàu KTX từ Seoul tới Gangneung chỉ khoảng 2 giờ.","Đi sớm để uống cà phê lúc mặt trời mọc trên biển.","Kết hợp với bãi Gyeongpo và nhà cổ Ojukheon trong cùng ngày."]', 'Quanh năm; tháng 10 có lễ hội cà phê', '2 giờ', '', 'Không có giờ chung — mỗi quán tự đặt giờ, phần lớn mở khoảng 09:00 đến 22:00; bãi biển ngay trước mặt mở cả ngày', '["trending"]', '["cà phê","biển","bình minh","lễ hội"]', '[{"seed":"gangneung-anmok-coffee","caption":"Quán cà phê bên bãi Anmok","ratio":"16/9"}]', '["gyeongpo-beach","ojukheon"]', 0, 'https://access.visitkorea.or.kr/opentour/detail.do?cotId=34bd6230-b3a4-433d-be50-6811f0a6699e', '2026-08-05', '{"en":{"name":"Anmok Coffee Street, Gangneung","summary":"A beach with a whole street of roasteries, which began with vending machines on the sand.","story":"It started plainly enough: in the 1980s a few coffee vending machines were installed along Anmok beach so people could drink something while watching the sea, and it turned into a regional habit. Then roasters moved in, opening right at the edge of the sand, and Gangneung now calls itself Korea''s coffee capital, with its own festival each October. The good part is that the old vending machines are still there, standing beside the elaborate roasteries — and plenty of locals still choose the machine. A cup, then a walk along the shore into the East Sea wind, is how Gangneung starts the morning.","facts":["The coffee street grew out of vending machines installed on the beach in the 1980s.","Gangneung holds the Gangneung Coffee Festival each October.","Dozens of cafés roast their own beans along Anmok beach.","The beach faces east and is a sunrise spot."],"travelTips":["The KTX from Seoul to Gangneung takes only about 2 hours.","Come early and drink your coffee as the sun comes up over the sea.","Combine with Gyeongpo beach and the Ojukheon house on the same day."],"bestTime":"Year-round; the coffee festival is in October","visitDuration":"2 hours","ticket":"","openingHours":"There are no shared hours — each café sets its own, most running roughly 09:00 to 22:00; the beach in front is open all day","galleryCaptions":["A café at the edge of Anmok beach"]},"ko":{"name":"강릉 안목 커피거리","summary":"로스터리가 늘어선 해변. 시작은 백사장의 자판기였다.","story":"시작은 대단할 것이 없었다. 1980년대에 안목해변을 따라 커피 자판기 몇 대를 놓아 바다를 보며 마시게 한 것이 지역의 습관이 되었다. 이후 로스터들이 모래 바로 옆에 가게를 열었고, 지금 강릉은 스스로를 한국의 커피 수도라 부르며 해마다 10월에 커피축제를 연다. 재미있는 것은 옛 자판기가 여전히 그 자리에 있다는 점이다. 정교한 로스터리 옆에 나란히 서 있고, 지역 사람 상당수는 여전히 자판기를 고른다. 한 잔 마시고 동해 바람을 맞으며 해변을 걷는 것이 강릉의 아침이다.","facts":["커피거리는 1980년대 해변에 놓인 자판기에서 비롯되었다.","강릉커피축제가 해마다 10월에 열린다.","안목해변을 따라 직접 원두를 볶는 카페가 수십 곳 있다.","동쪽을 향한 해변이라 일출 명소이기도 하다."],"travelTips":["서울에서 강릉까지 KTX로 약 두 시간이면 닿는다.","일찍 가서 바다 위로 해가 뜨는 동안 커피를 마시자.","같은 날 경포해변과 오죽헌을 묶어서 보자."],"bestTime":"연중, 10월에는 커피축제","visitDuration":"2시간","ticket":"","openingHours":"공통 운영시간은 없다. 카페마다 다르며 대체로 09:00~22:00이고, 바로 앞 안목해변은 상시 개방","galleryCaptions":["안목해변 가장자리의 카페"]},"ja":{"name":"江陵安木コーヒー通り","summary":"焙煎店が並ぶ海辺。始まりは砂浜の自販機だった。","story":"始まりは大したことではない。1980年代、安木海岸に沿ってコーヒーの自販機を数台置き、海を見ながら飲めるようにした。それが地域の習慣になった。やがて焙煎人たちが砂のすぐ脇に店を開き、今や江陵は自らを韓国のコーヒーの首都と称し、毎年十月にコーヒー祭りを開く。面白いのは、古い自販機が今もそこにあることだ。凝った焙煎店の隣に並んで立ち、地元の人の多くは今も自販機を選ぶ。一杯飲んで東海の風を受けながら浜を歩く。それが江陵の朝である。","facts":["コーヒー通りは1980年代に海岸へ置かれた自販機から生まれた。","江陵コーヒー祭りが毎年10月に開かれる。","安木海岸沿いには自家焙煎のカフェが数十軒ある。","東を向いた海岸で、日の出の名所でもある。"],"travelTips":["ソウルから江陵までKTXで約2時間。","早めに行き、海から日が昇る間にコーヒーを飲もう。","同じ日に鏡浦海岸と烏竹軒を合わせて回ろう。"],"bestTime":"通年、10月にはコーヒー祭り","visitDuration":"2時間","ticket":"","openingHours":"共通の営業時間はなく、カフェごとに異なりおおむね09:00〜22:00。目の前の安木海岸は終日開放","galleryCaptions":["安木海岸の際のカフェ"]},"zh":{"name":"江陵安木咖啡街","summary":"整條街都是自家烘焙店的海灘，起點是沙灘上的販賣機。","story":"起頭其實很平常：1980年代，人們沿著安木海灘擺了幾台咖啡販賣機，好讓人邊看海邊喝，久了竟成了地方習慣。後來烘豆師搬了進來，把店開在沙灘邊上，如今江陵自稱韓國的咖啡之都，每年十月還辦咖啡節。有趣的是那些舊販賣機仍在原地，就站在講究的烘焙店旁邊——而不少在地人依舊選販賣機。喝一杯，再迎著東海的風沿岸散步，就是江陵人開啟早晨的方式。","facts":["咖啡街源自1980年代設在海灘上的販賣機。","江陵咖啡節每年10月舉行。","安木海灘沿線有數十家自家烘焙咖啡館。","海灘面東，也是觀日出的地點。"],"travelTips":["自首爾搭KTX到江陵只需約兩小時。","早點來，在太陽從海上升起時喝咖啡。","可與鏡浦海灘、烏竹軒安排在同一天。"],"bestTime":"全年；10月有咖啡節","visitDuration":"2小時","ticket":"","openingHours":"沒有統一時間，各咖啡館自訂，多數約09:00至22:00；前方的安木海灘全日開放","galleryCaptions":["安木海灘邊的咖啡館"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheongoksan-mureung', 'cheongoksan-mureung', 'gangwon', 'Thung lũng Mureung (Donghae)', 'Mureung Valley, Donghae', 'waterfall', 129.0475, 37.4535, 'Phiến đá phẳng rộng bằng sân bóng nằm giữa suối, khắc chi chít tên các văn nhân xưa.', 'Mureung — ''thung lũng cõi tiên'' — mở đầu bằng một phiến đá trắng khổng lồ nằm phẳng giữa dòng suối, rộng đến mức chứa được cả nghìn người. Suốt các thế kỷ trước, văn nhân đi qua đây đều khắc tên mình lên đá, và giờ mặt phiến đá dày đặc chữ Hán chồng lên nhau như một cuốn sổ lưu bút bằng đá. Đi sâu vào thung lũng là chuỗi thác: Ssangpokpo với hai dòng nước đổ vào cùng một hồ đá, rồi Yongchupokpo cuối đường. Nước ở đây xanh lục vì đá vôi, và lạnh buốt kể cả tháng tám.', '["Phiến đá Mureungbanseok rộng khoảng 5.000 m², nằm giữa lòng suối.","Trên mặt đá có hàng trăm dòng chữ Hán do văn nhân các thời khắc lại.","Thác Ssangpokpo và Yongchupokpo nằm sâu trong thung lũng.","Thung lũng nằm dưới chân núi Dutasan, gần thành phố Donghae."]', '["Đi giày chống trượt: đá trong lòng suối rất trơn khi ướt.","Mùa hè đông người tắm suối; tháng 6 hoặc tháng 9 yên tĩnh hơn nhiều.","Đường lên thác cuối mất khoảng 1 giờ đi bộ từ cổng."]', 'Tháng 6–9 và tháng 10 (lá đỏ)', '3 giờ', '2.000 KRW (thiếu niên 1.500, trẻ em 700)', 'Mùa hè 09:00–20:00 (tháng 7–8 quầy vé mở từ 06:00), mùa đông 09:00–18:00', '["hidden-gem"]', '["thác nước","suối","khắc đá","đi bộ"]', '[{"seed":"cheongoksan-mureung","caption":"Phiến đá khắc chữ giữa suối Mureung","ratio":"16/9"}]', '["hwanseongul-cave","jeongdongjin"]', 0, 'https://www.dhsisul.org/pages/sub.htm?nav_code=new1701823163&mv_data=aWR4PTI3%7C%7C', '2026-08-04', '{"en":{"name":"Mureung Valley, Donghae","summary":"A flat slab of rock the size of a football pitch mid-stream, covered in the carved names of old scholars.","story":"Mureung — ''the valley of the immortals'' — opens with an enormous white slab lying flat in the stream, wide enough to hold a thousand people. For centuries scholars passing through carved their names into it, and the surface is now dense with overlapping Chinese characters, a visitors'' book written in stone. Deeper in the valley comes a chain of falls: Ssangpokpo, where two streams drop into the same rock pool, and Yongchupokpo at the end. The water runs green from the limestone and is bitterly cold even in August.","facts":["The Mureungbanseok slab covers about 5,000m² in the streambed.","Hundreds of Chinese inscriptions were carved into it by scholars over the centuries.","Ssangpokpo and Yongchupokpo falls lie deeper in the valley.","The valley sits below Dutasan, near the city of Donghae."],"travelTips":["Wear grippy shoes: the streambed rock is very slippery when wet.","Summer brings crowds who come to swim; June or September is far quieter.","The far waterfall is about an hour''s walk from the gate."],"bestTime":"June–September and October for autumn colour","visitDuration":"3 hours","ticket":"2,000 KRW (1,500 teens, 700 children)","openingHours":"Summer 09:00–20:00 (in July–August ticketing opens at 06:00), winter 09:00–18:00","galleryCaptions":["The inscribed slab in the Mureung stream"]},"ko":{"name":"동해 무릉계곡","summary":"계곡 한가운데 축구장만 한 너럭바위. 옛 선비들이 새긴 이름으로 빽빽하다.","story":"무릉계곡은 거대한 흰 너럭바위로 시작한다. 계곡 한복판에 평평하게 누워 천 명이 앉을 만큼 넓다. 수백 년 동안 이곳을 지난 선비들이 저마다 이름을 새겨서, 지금 바위 표면은 겹쳐 쓴 한자로 빼곡한 돌 방명록이 되었다. 계곡 안쪽으로 들어가면 폭포가 이어진다. 두 줄기가 한 소로 떨어지는 쌍폭포, 그리고 길 끝의 용추폭포다. 물은 석회암 때문에 초록빛이고, 8월에도 시릴 만큼 차갑다.","facts":["무릉반석은 계곡 바닥에 약 5,000m² 넓이로 펼쳐져 있다.","바위 표면에는 여러 시대 선비들이 새긴 한자가 수백 개 남아 있다.","계곡 안쪽에 쌍폭포와 용추폭포가 있다.","두타산 자락, 동해시 가까이에 있다."],"travelTips":["미끄럼 방지 신발을 신자. 계곡 바위는 젖으면 매우 미끄럽다.","여름에는 물놀이 인파가 많다. 6월이나 9월이 훨씬 한산하다.","가장 안쪽 폭포까지는 입구에서 한 시간쯤 걷는다."],"bestTime":"6~9월, 10월(단풍)","visitDuration":"3시간","ticket":"2,000원(청소년 1,500원, 어린이 700원)","openingHours":"하절기 09:00~20:00(7~8월 매표 06:00부터), 동절기 09:00~18:00","galleryCaptions":["무릉계곡의 글씨 새긴 너럭바위"]},"ja":{"name":"東海武陵渓谷","summary":"渓流の真ん中にサッカー場ほどの平らな岩。昔の文人が刻んだ名で埋まっている。","story":"武陵渓谷は巨大な白い一枚岩から始まる。渓流の真ん中に平らに横たわり、千人が座れるほど広い。何百年ものあいだここを通った文人がめいめい名を刻み、いまや岩の表面は重なり合う漢字で埋め尽くされた石の芳名帳になっている。奥へ進むと滝が続く。二筋がひとつの淵に落ちる双瀑布、そして道の果ての龍湫瀑布だ。水は石灰岩のせいで緑色を帯び、八月でも凍えるほど冷たい。","facts":["武陵盤石は渓流の底に約5,000m²にわたって広がる。","岩の表面には各時代の文人が刻んだ漢字が数百残る。","渓谷の奥に双瀑布と龍湫瀑布がある。","頭陀山の麓、東海市の近くにある。"],"travelTips":["滑り止めのある靴を。渓流の岩は濡れると非常に滑る。","夏は水遊びの人出が多い。6月か9月のほうがずっと静かだ。","最奥の滝までは入口から一時間ほど歩く。"],"bestTime":"6〜9月と10月（紅葉）","visitDuration":"3時間","ticket":"2,000ウォン（青少年1,500、子ども700）","openingHours":"夏季09:00〜20:00（7〜8月は券売06:00から）、冬季09:00〜18:00","galleryCaptions":["武陵渓谷の刻字のある一枚岩"]},"zh":{"name":"東海武陵溪谷","summary":"溪流正中一片足球場大的平坦岩盤，刻滿了昔日文人的名字。","story":"武陵溪谷以一片巨大的白色岩盤開場：它平坦地橫臥在溪流中央，寬得能容下上千人。數百年來途經此地的文人各自把名字刻上去，如今岩面已被層層疊疊的漢字填滿，成了一本用石頭寫的芳名錄。往溪谷深處走是一串瀑布：兩道水流落進同一潭的雙瀑布，以及路的盡頭的龍湫瀑布。溪水因石灰岩而泛綠，八月裡也冰得刺骨。","facts":["武陵磐石在溪床上鋪展約5,000平方公尺。","岩面留有數百則歷代文人刻下的漢字題名。","雙瀑布與龍湫瀑布位於溪谷深處。","溪谷位於頭陀山腳下，鄰近東海市。"],"travelTips":["穿防滑鞋：溪床岩面一濕就非常滑。","夏天戲水人潮多，六月或九月安靜得多。","從入口走到最深處的瀑布約需一小時。"],"bestTime":"6至9月，以及10月的紅葉","visitDuration":"3小時","ticket":"2,000韓元（青少年1,500、兒童700）","openingHours":"夏季09:00–20:00（7至8月售票自06:00起）、冬季09:00–18:00","galleryCaptions":["武陵溪中刻滿題字的岩盤"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('taebaeksan-snow', 'taebaeksan-snow', 'gangwon', 'Vườn quốc gia Taebaeksan', 'Taebaeksan National Park', 'mountain', 128.9155, 37.0965, 'Ngọn núi thiêng có đàn tế trời trên đỉnh, mùa đông cây thuỷ tùng đóng băng thành rừng pha lê.', 'Taebaeksan là núi thiêng trong tín ngưỡng Hàn Quốc: trên đỉnh có Cheonjedan, đàn đá tế trời tương truyền có từ thời Dangun, và đến giờ mỗi tháng 10 vẫn có lễ tế chính thức. Nhưng lý do đông người leo nhất lại là mùa đông. Núi đón gió biển ẩm nên tuyết bám dày, và những cây thuỷ tùng cổ thụ trên sườn — nhiều cây đã chết đứng hàng trăm năm mà không đổ — bị băng bao kín thành các hình thù trắng xoá. Đường lên từ Danggol mất khoảng hai tiếng và không quá dốc, nên đây được coi là ngọn núi tuyết dễ chinh phục nhất cho người mới.', '["Đỉnh Janggunbong cao 1.567m, là một trong những núi cao nhất Hàn Quốc.","Đàn tế trời Cheonjedan trên đỉnh vẫn được dùng cho lễ tế hằng năm.","Rừng thuỷ tùng cổ thụ trên sườn núi nổi tiếng với cảnh băng tuyết mùa đông.","Lễ hội tuyết Taebaeksan tổ chức vào tháng 1 hằng năm."]', '["Mùa đông bắt buộc mang đế đinh crampon; bán ngay ở chân núi.","Cuối tuần tháng 1 rất đông, đi ngày thường sẽ khác hẳn.","Thời tiết đổi rất nhanh trên đỉnh, mang thêm lớp áo giữ nhiệt."]', 'Tháng 1–2 (băng tuyết) và tháng 6 (hoa đỗ quyên)', 'Nửa ngày đến cả ngày', '', 'Áp dụng ''chế độ giờ vào núi'' của vườn quốc gia: được lên từ 04:00 (tháng 3–11) hoặc 05:00 (tháng 12–2), và mỗi cung đường có giờ chặn riêng trong khoảng 12:00–17:00. Kiểm tra thông báo đóng đường trước khi đi', '["popular"]', '["leo núi","tuyết","núi thiêng","mùa đông"]', '[{"seed":"taebaeksan-snow","caption":"Cây thuỷ tùng đóng băng trên Taebaeksan","ratio":"16/9"}]', '["cheongoksan-mureung"]', 1, 'https://www.knps.or.kr/front/portal/safe/acsCtrDtl.do?menuNo=8000340&rstId=0005', '2026-08-05', '{"en":{"name":"Taebaeksan National Park","summary":"A sacred mountain with a sky altar on its summit, where yews freeze into a crystal forest in winter.","story":"Taebaeksan is sacred in Korean belief: on the summit stands Cheonjedan, a stone altar to heaven said to date to the time of Dangun, and an official rite is still held there each October. But the reason most people climb it is winter. The mountain catches damp sea wind, so snow lies thick, and the ancient yews on its flanks — many dead upright for centuries without falling — ice over into white sculptures. The route from Danggol takes about two hours and is not steep, which makes this the friendliest snow mountain in the country for a first attempt.","facts":["Janggunbong summit is 1,567m, among Korea''s highest peaks.","The Cheonjedan sky altar on the summit is still used for an annual rite.","The ancient yew forest on its flanks is famous for winter ice.","The Taebaeksan Snow Festival is held each January."],"travelTips":["Crampons are essential in winter and are sold at the foot of the mountain.","January weekends are very busy; a weekday is a different mountain.","Weather turns fast on the summit — carry an extra insulating layer."],"bestTime":"January–February (ice and snow) and June (azaleas)","visitDuration":"Half to a full day","ticket":"","openingHours":"The national park entry-time system applies: ascent opens at 04:00 (March–November) or 05:00 (December–February), and each section has its own turn-back time somewhere between 12:00 and 17:00. Check the trail-closure notices before setting out","galleryCaptions":["Iced yews on Taebaeksan"]},"ko":{"name":"태백산국립공원","summary":"정상에 천제단이 있는 영산. 겨울이면 주목이 얼어붙어 수정 숲이 된다.","story":"태백산은 한국 신앙에서 영산이다. 정상에는 단군 때부터 있었다고 전해지는 돌제단 천제단이 있고, 지금도 해마다 10월에 공식 제례가 열린다. 그러나 사람들이 가장 많이 오르는 이유는 겨울이다. 산이 습한 바닷바람을 받아 눈이 두껍게 쌓이고, 비탈의 늙은 주목들은 수백 년을 죽은 채 서 있으면서도 쓰러지지 않은 것이 많은데, 그 위로 얼음이 덮여 하얀 조형이 된다. 당골에서 오르면 두 시간쯤이고 그리 가파르지 않아, 첫 겨울 산으로 가장 무난한 곳으로 꼽힌다.","facts":["장군봉은 1,567m로 한국에서도 높은 축에 든다.","정상의 천제단에서는 지금도 해마다 제례가 열린다.","비탈의 오래된 주목 숲은 겨울 상고대로 유명하다.","태백산 눈축제가 해마다 1월에 열린다."],"travelTips":["겨울에는 아이젠이 필수이며 산 아래에서 판다.","1월 주말은 매우 붐빈다. 평일에 가면 전혀 다른 산이다.","정상 날씨가 빨리 바뀐다. 보온 겉옷을 한 겹 더 챙기자."],"bestTime":"1~2월(눈과 상고대), 6월(철쭉)","visitDuration":"반나절~하루","ticket":"","openingHours":"국립공원 입산시간지정제가 적용된다. 입산은 3~11월 04:00, 12~2월 05:00부터 가능하며 구간마다 12:00~17:00 사이로 통제시간이 다르다. 출발 전 통제 정보를 확인하자","galleryCaptions":["태백산의 얼어붙은 주목"]},"ja":{"name":"太白山国立公園","summary":"山頂に天祭壇を持つ霊山。冬にはイチイが凍りつき、水晶の森になる。","story":"太白山は韓国の信仰における霊山だ。山頂には檀君の時代からあると伝わる石の祭壇・天祭壇があり、今も毎年十月に公式の祭礼が行われる。だが人が最も多く登る理由は冬にある。山が湿った海風を受けて雪が厚く積もり、斜面の老いたイチイ――何百年も枯れたまま立ち続け倒れないものが多い――に氷が着いて白い造形になる。堂谷から登れば二時間ほどで、さほど急でもないため、初めての冬山として最も無難な一座とされる。","facts":["将軍峰は1,567mで、韓国でも高い部類に入る。","山頂の天祭壇では今も毎年祭礼が行われる。","斜面の古いイチイ林は冬の樹氷で知られる。","太白山雪祭りが毎年1月に開かれる。"],"travelTips":["冬はアイゼンが必須で、麓で売っている。","1月の週末は非常に混む。平日ならまるで別の山だ。","山頂の天気は急変する。保温着をもう一枚持とう。"],"bestTime":"1〜2月（雪と樹氷）、6月（ツツジ）","visitDuration":"半日〜一日","ticket":"","openingHours":"国立公園の入山時間指定制が適用される。入山は3〜11月は04:00、12〜2月は05:00から可能で、区間ごとに12:00〜17:00の間で規制時刻が異なる。出発前に通行規制情報の確認を","galleryCaptions":["凍りついた太白山のイチイ"]},"zh":{"name":"太白山國立公園","summary":"山頂設有祭天壇的聖山，冬天紫杉結冰，化成一片水晶森林。","story":"太白山在韓國信仰中是聖山：山頂立著天祭壇，一座相傳可追溯至檀君時代的石砌祭壇，如今每年十月仍有正式祭典。但多數人上山的理由是冬天。這座山迎著潮濕海風，積雪厚實，山腰上的老紫杉——許多已枯立數百年卻不倒——被冰層裹住，成了一尊尊白色雕塑。自堂谷起登約兩小時，坡度不陡，因此被視為初次挑戰雪山最友善的一座。","facts":["將軍峰海拔1,567公尺，在韓國屬於高峰之列。","山頂的天祭壇至今仍用於每年的祭典。","山腰的老紫杉林以冬季霧淞聞名。","太白山雪祭每年1月舉行。"],"travelTips":["冬季必備冰爪，山腳下就有販售。","一月週末非常擁擠，平日來會是完全不同的一座山。","山頂天氣變化極快，請多帶一層保暖衣物。"],"bestTime":"1至2月（冰雪）與6月（杜鵑）","visitDuration":"半天至一整天","ticket":"","openingHours":"適用國家公園「入山時間指定制」：3至11月自04:00、12至2月自05:00開放入山，各路段的折返管制時間落在12:00至17:00之間。出發前請先查看步道封閉公告","galleryCaptions":["太白山上結冰的紫杉"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sokcho-abai-village', 'sokcho-abai-village', 'gangwon', 'Làng Abai (Sokcho)', 'Abai Village, Sokcho', 'village', 128.5945, 38.2075, 'Làng của người tị nạn miền Bắc, qua lại bằng chiếc phà kéo tay bằng móc sắt suốt bảy mươi năm.', 'Tháng 12 năm 1950, hàng nghìn người từ tỉnh Hamgyong ở miền Bắc theo tàu chiến xuống Sokcho, tin rằng chỉ vài tuần nữa là về được nhà. Họ dựng lều trên dải cát ở cửa cảng và đặt tên làng theo cách người quê họ gọi cha — ''abai''. Bảy mươi năm sau con cháu họ vẫn ở đó, và vẫn chưa ai về được. Cách sang làng là chiếc galbae — một chiếc bè sắt không động cơ, khách tự cầm móc sắt kéo dây cáp để đưa bè qua lạch nước rộng chừng năm mươi mét. Trong làng bán món ăn Hamgyong không có ở nơi nào khác của Hàn Quốc: ojingeo sundae, xúc xích nhồi trong thân mực, và mì lạnh Hamhung sợi khoai.', '["Làng hình thành từ tháng 12 năm 1950, khi người tị nạn Hamgyong theo tàu xuống Sokcho.","''Abai'' là cách gọi người cha trong phương ngữ Hamgyong.","Phà galbae không động cơ, khách tự kéo dây cáp để đưa bè qua lạch.","Món ojingeo sundae và mì lạnh Hamhung là đặc sản gốc miền Bắc của làng."]', '["Đi phà galbae ít nhất một chiều — đó là phần đáng nhớ nhất.","Thử ojingeo sundae ở chợ trong làng, ngon nhất lúc còn nóng.","Kết hợp với Seoraksan cách đó khoảng 20 phút xe."]', 'Tháng 5–6 và 9–10', '2 giờ', 'Phà kéo tay qua lạch 500 KRW mỗi lượt', 'Phà chạy khoảng 06:00–23:00', '["hidden-gem","verified"]', '["làng chài","tị nạn","ẩm thực","phà"]', '[{"seed":"sokcho-abai-village","caption":"Phà galbae kéo tay qua lạch Sokcho","ratio":"16/9"}]', '["seoraksan","naksansa"]', 0, 'https://www.koreatodo.com/seoraksan-national-park', '2026-08-04', '{"en":{"name":"Abai Village, Sokcho","summary":"A village of northern refugees, crossed for seventy years by a raft pulled hand over hand on a steel hook.","story":"In December 1950 thousands of people from Hamgyong province in the north came down to Sokcho aboard warships, believing they would be home again within weeks. They put up shelters on the sandspit at the harbour mouth and named the village after their word for father — abai. Seventy years on their descendants are still there, and nobody has gone home. You cross to it on the galbae: an engineless steel raft that passengers haul themselves, hooking a cable and pulling it across fifty metres of channel. The village sells Hamgyong food found nowhere else in Korea: ojingeo sundae, sausage stuffed into a squid''s body, and Hamhung cold noodles made from potato starch.","facts":["The village dates from December 1950, when Hamgyong refugees arrived at Sokcho by ship.","''Abai'' is the Hamgyong dialect word for father.","The galbae raft has no engine; passengers pull it across on a cable themselves.","Ojingeo sundae and Hamhung cold noodles are the village''s northern specialities."],"travelTips":["Take the galbae at least one way — it is the memorable part.","Try ojingeo sundae at the village market; it is best hot.","Combine it with Seoraksan, about 20 minutes away by car."],"bestTime":"May–June and September–October","visitDuration":"2 hours","ticket":"The hand-pulled ferry across the channel costs 500 KRW each way","openingHours":"Raft runs roughly 06:00–23:00","galleryCaptions":["The hand-pulled galbae raft across the Sokcho channel"]},"ko":{"name":"속초 아바이마을","summary":"북에서 내려온 실향민의 마을. 칠십 년째 손으로 쇠갈고리를 당겨 갯배로 건넌다.","story":"1950년 12월, 함경도에서 수천 명이 군함을 타고 속초로 내려왔다. 몇 주면 집에 돌아가리라 믿었다. 그들은 항구 어귀의 모래톱에 천막을 치고, 고향말로 아버지를 뜻하는 ''아바이''를 마을 이름으로 삼았다. 칠십 년이 지나도 후손들은 그대로 있고, 아무도 돌아가지 못했다. 마을로 건너가는 방법은 갯배다. 동력이 없는 철제 뗏목으로, 승객이 직접 쇠갈고리로 줄을 당겨 오십 미터쯤 되는 물길을 건넌다. 마을에서는 한국 어디에도 없는 함경도 음식을 판다. 오징어 몸통에 채워 넣은 오징어순대, 그리고 감자 전분으로 뽑은 함흥냉면이다.","facts":["1950년 12월 함경도 실향민이 배로 속초에 닿으며 생긴 마을이다.","''아바이''는 함경도 말로 아버지를 뜻한다.","갯배는 동력이 없고 승객이 직접 줄을 당겨 건넌다.","오징어순대와 함흥냉면이 마을의 북쪽 향토 음식이다."],"travelTips":["갯배는 한 번이라도 타 보자. 가장 기억에 남는 대목이다.","마을 시장에서 오징어순대를 뜨거울 때 먹자.","차로 20분 거리의 설악산과 묶어서 보자."],"bestTime":"5~6월, 9~10월","visitDuration":"2시간","ticket":"갯배 편도 500원","openingHours":"갯배는 대략 06:00~23:00 운행","galleryCaptions":["속초 물길을 건너는 갯배"]},"ja":{"name":"束草アバイ村","summary":"北から下りてきた避難民の村。七十年ものあいだ、鉄の鉤で綱を手繰る渡し舟で行き来する。","story":"1950年12月、咸鏡道から数千人が軍艦で束草へ下りてきた。数週間で家へ帰れると信じていた。彼らは港口の砂州に小屋を建て、故郷の言葉で父を意味する「アバイ」を村の名にした。七十年経っても子孫はそこにいて、誰も帰れていない。村へ渡る方法はケッペと呼ばれる渡し舟だ。動力のない鉄の筏で、乗客自身が鉄の鉤で綱を手繰り、五十メートルほどの水路を渡る。村では韓国のほかでは見ない咸鏡道の料理を売っている。イカの胴に詰めたイカスンデと、ジャガイモ澱粉で打つ咸興冷麺だ。","facts":["1950年12月、咸鏡道の避難民が船で束草に着いて生まれた村である。","「アバイ」は咸鏡道の方言で父を意味する。","ケッペは動力がなく、乗客が自ら綱を手繰って渡る。","イカスンデと咸興冷麺が村の北の郷土料理である。"],"travelTips":["片道だけでもケッペに乗ろう。最も記憶に残る部分だ。","村の市場でイカスンデを熱いうちに食べよう。","車で20分の雪岳山と合わせて回ろう。"],"bestTime":"5〜6月、9〜10月","visitDuration":"2時間","ticket":"手漕ぎ渡し船は片道500ウォン","openingHours":"ケッペはおよそ06:00〜23:00運航","galleryCaptions":["束草の水路を渡るケッペ"]},"zh":{"name":"束草阿爸伊村","summary":"北方難民的村落，七十年來靠一艘用鐵鉤拉纜過河的無動力筏往返。","story":"1950年12月，數千名咸鏡道人搭軍艦南下抵達束草，以為幾週後就能回家。他們在港口的沙洲上搭起棚屋，並以家鄉話裡「父親」的說法——阿爸伊——為村子命名。七十年過去，後代仍在那裡，沒有人回得去。過村的方式是「갯배」：一艘沒有動力的鐵筏，乘客自己用鐵鉤勾住纜繩，一把一把把筏子拉過約五十公尺寬的水道。村裡賣著韓國其他地方吃不到的咸鏡道菜：把香腸餡塞進魷魚身體裡的魷魚血腸，以及用馬鈴薯澱粉製麵的咸興冷麵。","facts":["村子源自1950年12月，咸鏡道難民搭船抵達束草之時。","「阿爸伊」是咸鏡道方言中對父親的稱呼。","渡筏沒有動力，由乘客自行拉纜過渡。","魷魚血腸與咸興冷麵是村中的北方鄉土菜。"],"travelTips":["至少單程搭一次渡筏，那才是最難忘的部分。","在村內市場趁熱吃魷魚血腸。","可與車程約20分鐘的雪嶽山排在一起。"],"bestTime":"5至6月與9至10月","visitDuration":"2小時","ticket":"手拉渡船單程500韓元","openingHours":"渡筏約06:00–23:00運行","galleryCaptions":["橫渡束草水道的手拉渡筏"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('danyang-dodamsambong', 'danyang-dodamsambong', 'chungbuk', 'Ba đỉnh đá Dodamsambong (Danyang)', 'Dodamsambong Peaks, Danyang', 'lake', 128.3455, 37.0165, 'Ba khối đá vôi nhô lên giữa sông Namhan, thắng cảnh được vẽ đi vẽ lại suốt sáu thế kỷ.', 'Ba mỏm đá đứng giữa dòng nước xanh: người ta gọi chúng là chồng, vợ và thiếp, kèm cả một câu chuyện ghen tuông để giải thích vì sao mỏm giữa quay lưng đi. Danh sĩ Jeong Do-jeon thời Joseon lớn lên gần đây và lấy hiệu từ chính thắng cảnh này. Thuyền du lịch chạy quanh ba mỏm đá, còn ban đêm chúng được chiếu sáng. Cả vùng Danyang là đá vôi, nên ngay gần đó là hang Gosu với măng đá dài hàng mét và những con đường ven sông uốn lượn.', '["Là Danh thắng quốc gia số 44 của Hàn Quốc.","Ba mỏm đá vôi cao khoảng 6m nhô lên từ sông Namhan.","Hang Gosu cách đó vài phút, dài khoảng 1,7 km.","Danyang nổi tiếng với tỏi và các món chế biến từ tỏi."]', '["Đi thuyền hoặc lên đài quan sát Danyang Gangbyeon để nhìn toàn cảnh.","Buổi tối ba mỏm đá được chiếu sáng rất đẹp.","Kết hợp hang Gosu và cầu treo Mancheonha trong cùng ngày."]', 'Tháng 4–6 và 9–11', '1,5 giờ', '', 'Cả ngày', '["hidden-gem"]', '["sông","đá vôi","thắng cảnh"]', '[{"seed":"danyang-dodamsambong","caption":"Ba mỏm đá giữa sông","ratio":"16/9"}]', '["guinsa","songnisan-beopjusa"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Dodamsambong Peaks, Danyang","summary":"Three limestone stacks standing mid-river, painted and repainted for six centuries.","story":"Three rocks rise out of the green water: people call them husband, wife and concubine, complete with a jealousy story to explain why the middle one turns away. The Joseon statesman Jeong Do-jeon grew up nearby and took his pen name from this very view. Tour boats circle the stacks, and at night they are floodlit. All of Danyang is limestone country, so a few minutes away are Gosu cave with its metre-long formations and winding roads along the river.","facts":["Designated National Scenic Site No. 44.","The three limestone peaks rise about 6m out of the Namhan River.","Gosu cave, minutes away, runs about 1.7 km.","Danyang is known for its garlic and garlic-based dishes."],"travelTips":["Take a boat, or climb to the Danyang riverside viewpoint for the wide view.","The stacks are beautifully lit after dark.","Combine with Gosu cave and the Mancheonha skywalk in one day."],"bestTime":"April–June and September–November","visitDuration":"1.5 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["The three peaks in the river"]},"ko":{"name":"단양 도담삼봉","summary":"강 한가운데 솟은 세 개의 석회암 봉우리. 600년간 그려진 명승이다.","story":"푸른 물 위로 바위 세 개가 솟아 있다. 사람들은 이를 남편과 아내, 첩이라 부르며 가운데 봉우리가 왜 등을 돌렸는지 설명하는 이야기까지 덧붙인다. 조선의 정도전이 이 근처에서 자라며 바로 이 풍경에서 호를 얻었다. 유람선이 세 봉우리를 돌고, 밤에는 조명이 들어온다. 단양 일대가 석회암 지대여서 몇 분 거리에는 종유석이 늘어선 고수동굴과 강을 따라 굽이치는 길이 있다.","facts":["국가 명승 제44호로 지정되었다.","남한강에서 약 6m 높이로 솟은 석회암 봉우리다.","몇 분 거리의 고수동굴은 길이가 약 1.7km다.","단양은 마늘과 마늘 요리로 유명하다."],"travelTips":["유람선을 타거나 단양강 전망대에 올라 전경을 보자.","밤에는 조명이 들어와 더 아름답다.","고수동굴, 만천하 스카이워크와 묶어 하루 코스로 좋다."],"bestTime":"4~6월, 9~11월","visitDuration":"1시간 30분","ticket":"","openingHours":"상시 개방","galleryCaptions":["강 가운데의 세 봉우리"]},"ja":{"name":"丹陽 島潭三峰","summary":"川の真ん中に立つ三つの石灰岩の峰。六百年描かれ続けた名勝。","story":"青い水の上に三つの岩が立つ。人々はこれを夫と妻と妾と呼び、なぜ真ん中の峰が背を向けているのかを説明する嫉妬の物語まで添える。朝鮮の鄭道伝はこの近くで育ち、まさにこの風景から号を得た。遊覧船が三つの峰を巡り、夜には照明が灯る。丹陽一帯は石灰岩地帯で、数分の距離には鍾乳石の並ぶ古藪洞窟と、川に沿ってうねる道がある。","facts":["国家名勝第44号に指定されている。","南漢江から約6m突き出た石灰岩の峰。","数分の距離にある古藪洞窟は全長約1.7km。","丹陽はニンニクとニンニク料理で有名。"],"travelTips":["遊覧船に乗るか、丹陽江の展望台から全景を眺めよう。","夜は照明が入りいっそう美しい。","古藪洞窟や万天下スカイウォークと合わせて一日コースに。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1時間30分","ticket":"","openingHours":"終日開放","galleryCaptions":["川の中の三つの峰"]},"zh":{"name":"丹陽島潭三峰","summary":"立於江心的三座石灰岩峰，六百年來被畫了又畫。","story":"三塊岩石自碧綠的水中拔起：人們稱它們為丈夫、妻子與妾，還配上一則妒意的故事，解釋中間那座為何背過身去。朝鮮名臣鄭道傳在附近長大，並以這片景致為號。遊船繞著三峰而行，入夜則打上燈光。整個丹陽都是石灰岩地帶，因此幾分鐘車程外便是石筍林立的古藪洞窟，以及沿江蜿蜒的道路。","facts":["被指定為國家名勝第44號。","三座石灰岩峰高約6公尺，聳立於南漢江中。","數分鐘車程外的古藪洞窟長約1.7公里。","丹陽以大蒜與蒜味料理聞名。"],"travelTips":["搭遊船，或登上丹陽江邊觀景台看全景。","夜間打燈後更美。","可與古藪洞窟、萬天下天空步道安排成一日遊。"],"bestTime":"4至6月、9至11月","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["江心的三座石峰"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('songnisan-beopjusa', 'songnisan-beopjusa', 'chungbuk', 'Núi Songnisan & chùa Beopjusa', 'Songnisan & Beopjusa Temple', 'temple', 127.834, 36.542, 'Tháp gỗ năm tầng duy nhất còn lại của Hàn Quốc, đứng cạnh tượng Phật đồng vàng cao 33 mét.', 'Beopjusa giữ hai thứ không nơi nào khác có: Palsangjeon, ngôi tháp gỗ năm tầng duy nhất còn sót lại ở Hàn Quốc, dựng lại năm 1626 mà không dùng một cái đinh sắt; và tượng Phật Di Lặc bằng đồng mạ vàng cao 33 mét, sáng loá giữa rừng. Chùa nằm trong vườn quốc gia Songnisan — ''núi lìa đời tục'' — với đường mòn xuyên rừng thông cổ thụ. Trên đường vào có cây thông được phong tước quan nhị phẩm vì đã tự nhấc cành cho kiệu vua đi qua.', '["Chùa dựng năm 553, thời Silla.","Tháp gỗ Palsangjeon là quốc bảo, tháp gỗ năm tầng duy nhất còn lại ở Hàn Quốc.","Tượng Phật Di Lặc bằng đồng cao 33m, hoàn thành năm 1990.","Cây thông Jeongipumsong trên đường vào được phong hàm quan từ thế kỷ 15."]', '["Đi bus liên tỉnh từ Cheongju hoặc Daejeon tới Songnisan.","Đường mòn từ chùa lên đỉnh Munjangdae mất khoảng 4 giờ khứ hồi.","Mùa thu là mùa đẹp nhất nhưng cũng đông nhất."]', 'Tháng 10–11', 'Nửa ngày', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '07:00–18:00', '["verified"]', '["chùa","núi","quốc bảo"]', '[{"seed":"songnisan-beopjusa","caption":"Tháp gỗ Palsangjeon","ratio":"16/9"}]', '["danyang-dodamsambong","cheongju-jikji"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Songnisan & Beopjusa Temple","summary":"Korea''s only surviving five-storey wooden pagoda, beside a 33-metre gilded bronze Buddha.","story":"Beopjusa holds two things found nowhere else: Palsangjeon, the only five-storey wooden pagoda left in Korea, rebuilt in 1626 without a single iron nail; and a 33-metre gilt-bronze Maitreya that shines out of the forest. The temple sits inside Songnisan National Park — ''the mountain that leaves the world'' — with trails through old pine woods. On the way in stands a pine granted the rank of a second-degree official, for lifting its branches so a king''s palanquin could pass.","facts":["The temple was founded in 553, during the Silla period.","Palsangjeon is a national treasure and Korea''s only remaining five-storey wooden pagoda.","The bronze Maitreya, 33m tall, was completed in 1990.","The Jeongipumsong pine on the approach has held official rank since the 15th century."],"travelTips":["Intercity buses run from Cheongju or Daejeon to Songnisan.","The trail from the temple to Munjangdae peak takes about four hours return.","Autumn is the finest season — and the busiest."],"bestTime":"October–November","visitDuration":"Half a day","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"07:00–18:00","galleryCaptions":["The Palsangjeon wooden pagoda"]},"ko":{"name":"속리산과 법주사","summary":"한국에 하나 남은 오층 목탑과 33m 금동미륵대불.","story":"법주사에는 다른 곳에 없는 두 가지가 있다. 1626년 쇠못 하나 없이 다시 세운, 한국에 유일하게 남은 오층 목탑 팔상전. 그리고 숲 사이에서 빛나는 높이 33m의 금동미륵대불이다. 절은 ''속세를 떠난 산''이라는 이름의 속리산국립공원 안에 있고, 오래된 솔숲 사이로 산길이 이어진다. 들어가는 길에는 임금의 가마가 지나도록 스스로 가지를 들어 올렸다 하여 정이품 벼슬을 받은 소나무가 서 있다.","facts":["553년 신라 때 창건되었다.","팔상전은 국보이며 한국에 남은 유일한 오층 목탑이다.","높이 33m의 금동미륵대불은 1990년에 완성되었다.","진입로의 정이품송은 15세기부터 벼슬을 지녔다."],"travelTips":["청주나 대전에서 속리산행 시외버스를 탈 수 있다.","절에서 문장대까지는 왕복 네 시간쯤 걸린다.","가을이 가장 아름답고 가장 붐빈다."],"bestTime":"10~11월","visitDuration":"반나절","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"07:00~18:00","galleryCaptions":["오층 목탑 팔상전"]},"ja":{"name":"俗離山と法住寺","summary":"韓国に唯一残る五層木塔と、33mの金銅弥勒大仏。","story":"法住寺には他にない二つがある。1626年に釘を一本も使わず建て直した、韓国唯一の五層木塔・捌相殿。そして森の中で輝く高さ33mの金銅弥勒大仏だ。寺は「俗世を離れる山」という名の俗離山国立公園にあり、古い松林の中を山道が続く。参道には、王の輿が通れるよう自ら枝を持ち上げたとして正二品の官位を授かった松が立っている。","facts":["553年、新羅時代に創建された。","捌相殿は国宝で、韓国に唯一残る五層木塔。","高さ33mの金銅弥勒大仏は1990年に完成した。","参道の正二品松は15世紀から官位を持つ。"],"travelTips":["清州や大田から俗離山行きの市外バスがある。","寺から文蔵台までは往復四時間ほど。","秋が最も美しく、最も混雑する。"],"bestTime":"10〜11月","visitDuration":"半日","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"07:00〜18:00","galleryCaptions":["五層木塔・捌相殿"]},"zh":{"name":"俗離山與法住寺","summary":"韓國僅存的五層木塔，旁邊立著三十三公尺高的鎏金彌勒佛。","story":"法住寺擁有別處沒有的兩樣東西：捌相殿，韓國唯一留存的五層木塔，1626年重建時未用一根鐵釘；以及自林間閃耀的三十三公尺鎏金銅彌勒。寺院位於名為「離開俗世之山」的俗離山國立公園內，山徑穿過古松林。入口處有一株松樹，因曾自行抬起枝條讓國王御轎通過而被封為正二品官。","facts":["寺院創建於553年的新羅時期。","捌相殿為國寶，是韓國唯一留存的五層木塔。","三十三公尺高的鎏金銅彌勒完成於1990年。","參道上的正二品松自十五世紀起便擁有官階。"],"travelTips":["可自清州或大田搭客運前往俗離山。","自寺院至文藏台往返約四小時。","秋季最美，也最擁擠。"],"bestTime":"10至11月","visitDuration":"半天","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"07:00–18:00","galleryCaptions":["五層木塔捌相殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('guinsa', 'guinsa', 'chungbuk', 'Chùa Guinsa', 'Guinsa Temple', 'temple', 128.479914, 37.031003, 'Quần thể chùa nhiều tầng xếp chồng trong một khe núi hẹp, khác hoàn toàn chùa cổ Hàn Quốc.', 'Guinsa không giống bất kỳ ngôi chùa nào khác ở Hàn Quốc: thay vì trải rộng theo sân, các toà nhà năm bảy tầng chồng lên nhau dọc một khe núi dốc, nối bằng cầu thang và hành lang. Đây là tổng bản sơn của tông Thiên Thai Hàn Quốc, xây từ 1945 và mở rộng liên tục, có thể tiếp hàng nghìn tăng ni cùng lúc. Đi từ cổng vào tới điện chính là leo dốc liên tục giữa hai vách núi, và cảm giác kiến trúc bao quanh mình rất mạnh.', '["Là tổng bản sơn của tông Thiên Thai Hàn Quốc, lập năm 1945.","Các toà nhà cao tới 5–7 tầng, xếp dọc theo khe núi.","Có thể phục vụ ăn ở cho hàng nghìn người cùng lúc.","Nằm ở Danyang, gần vườn quốc gia Sobaeksan."]', '["Có xe bus nhỏ đưa khách từ bãi xe lên cổng chùa.","Chùa cấm chụp ảnh ở một số khu vực hành lễ.","Kết hợp với Dodamsambong trong cùng chuyến Danyang."]', 'Tháng 5–6 và 9–10', '2 giờ', '', '05:00–19:00', '["hidden-gem"]', '["chùa","kiến trúc","núi"]', '[{"seed":"guinsa","caption":"Chùa xếp tầng trong khe núi","ratio":"16/9"}]', '["danyang-dodamsambong"]', 0, 'https://ko.wikipedia.org/wiki/구인사', '2026-08-04', '{"en":{"name":"Guinsa Temple","summary":"A temple complex stacked in storeys up a narrow ravine — nothing like Korea''s older monasteries.","story":"Guinsa looks like no other temple in Korea: instead of spreading out around courtyards, its buildings rise five to seven storeys and pile up along a steep ravine, linked by stairs and corridors. It is the head temple of the Korean Cheontae order, founded in 1945 and expanded ever since, able to house thousands of monks and pilgrims at once. Walking from the gate to the main hall is a continuous climb between two rock walls, and the sense of architecture closing around you is powerful.","facts":["Head temple of the Korean Cheontae order, established in 1945.","Buildings rise five to seven storeys along the ravine.","It can feed and house thousands of people at once.","Located in Danyang, near Sobaeksan National Park."],"travelTips":["A shuttle bus carries visitors from the car park up to the gate.","Photography is not allowed in some ritual areas.","Combine it with Dodamsambong on a Danyang trip."],"bestTime":"May–June and September–October","visitDuration":"2 hours","ticket":"","openingHours":"05:00–19:00","galleryCaptions":["The temple stacked in the ravine"]},"ko":{"name":"구인사","summary":"좁은 계곡을 따라 층층이 쌓아 올린 사찰. 한국의 옛 절과는 전혀 다르다.","story":"구인사는 한국의 다른 절과 닮은 데가 없다. 마당을 중심으로 펼쳐지는 대신, 대여섯 층에서 일곱 층에 이르는 건물이 가파른 계곡을 따라 층층이 포개지고 계단과 회랑으로 이어진다. 1945년 창건된 대한불교 천태종의 총본산으로 계속 확장되어 수천 명이 한꺼번에 머물 수 있다. 일주문에서 대법당까지는 두 절벽 사이를 계속 오르는 길이며, 건축이 사방에서 다가오는 감각이 강렬하다.","facts":["1945년 창건된 대한불교 천태종의 총본산이다.","건물이 계곡을 따라 5~7층으로 솟아 있다.","수천 명의 식사와 숙박을 동시에 감당할 수 있다.","소백산국립공원 인근 단양에 있다."],"travelTips":["주차장에서 일주문까지 셔틀버스가 운행된다.","일부 법당 구역은 촬영이 금지된다.","단양 여행 때 도담삼봉과 함께 묶기 좋다."],"bestTime":"5~6월, 9~10월","visitDuration":"2시간","ticket":"","openingHours":"05:00~19:00","galleryCaptions":["계곡에 층층이 선 사찰"]},"ja":{"name":"救仁寺","summary":"狭い渓谷に層を成して積み上がる寺。韓国の古刹とはまるで違う。","story":"救仁寺は韓国の他の寺と似たところがない。庭を中心に広がるのではなく、五階から七階に達する建物が急な谷に沿って積み重なり、階段と回廊でつながる。1945年創建の大韓仏教天台宗の総本山で、拡張を重ね数千人が同時に滞在できる。一柱門から大法堂までは二つの崖の間をひたすら登る道で、建築が四方から迫ってくる感覚が強烈だ。","facts":["1945年に創建された大韓仏教天台宗の総本山。","建物は谷に沿って5〜7階建てで立ち上がる。","数千人分の食事と宿泊を同時にまかなえる。","小白山国立公園に近い丹陽にある。"],"travelTips":["駐車場から一柱門までシャトルバスが運行する。","一部の法堂区域は撮影禁止。","丹陽旅行では島潭三峰と組み合わせやすい。"],"bestTime":"5〜6月、9〜10月","visitDuration":"2時間","ticket":"","openingHours":"05:00〜19:00","galleryCaptions":["谷に層を成す寺"]},"zh":{"name":"救仁寺","summary":"沿狹窄峽谷層層堆疊的寺院群，與韓國古剎截然不同。","story":"救仁寺不像韓國任何一座寺院：它不是圍著庭院展開，而是五到七層的建築沿著陡峭峽谷層層堆高，以階梯與迴廊相連。這是韓國天台宗的總本山，1945年創建並持續擴建，可同時容納數千名僧眾與信徒。從一柱門走到大法堂是在兩側崖壁之間不斷上行的過程，建築從四面壓過來的感受十分強烈。","facts":["1945年創建，是韓國天台宗總本山。","建築沿峽谷高達五至七層。","可同時提供數千人食宿。","位於丹陽，鄰近小白山國立公園。"],"travelTips":["有接駁車自停車場載旅客上到山門。","部分法堂區域禁止攝影。","遊丹陽時可與島潭三峰一併安排。"],"bestTime":"5至6月、9至10月","visitDuration":"2小時","ticket":"","openingHours":"05:00–19:00","galleryCaptions":["層疊於峽谷中的寺院"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheongju-jikji', 'cheongju-jikji', 'chungbuk', 'Di tích Heungdeoksa & Bảo tàng Jikji (Cheongju)', 'Cheongju Early Printing Museum', 'museum', 127.4405, 36.6395, 'Nơi in ra cuốn sách kim loại rời cổ nhất thế giới — trước Gutenberg 78 năm.', 'Năm 1377, tại chùa Heungdeoksa ở Cheongju, các nhà sư đã in cuốn ''Jikji'' bằng khuôn chữ kim loại rời — sớm hơn Kinh Thánh Gutenberg bảy mươi tám năm. Bản duy nhất còn lại nằm ở Thư viện Quốc gia Pháp, nên bảo tàng dựng trên nền chùa cũ trưng bày bản sao, cùng toàn bộ quy trình đúc chữ, sắp chữ và in. Có xưởng cho khách tự in một trang bằng khuôn gỗ. Với người mê sách, đây là một trong những địa chỉ đáng đi nhất Hàn Quốc.', '["''Jikji'' in năm 1377, được UNESCO ghi vào Ký ức Thế giới năm 2001.","Sớm hơn Kinh Thánh Gutenberg khoảng 78 năm.","Bản gốc duy nhất còn lại đang ở Thư viện Quốc gia Pháp.","Bảo tàng xây trên nền chùa Heungdeoksa, phát hiện năm 1985."]', '["Có workshop in thử bằng khuôn chữ, phù hợp cho trẻ em.","Thuyết minh tiếng Anh cần đăng ký trước.","Cheongju cách Seoul khoảng 1,5 giờ tàu."]', 'Quanh năm', '1,5 giờ', '', '09:00–18:00 quanh năm; đóng cửa thứ Hai, 1/1 và ngày Tết, Chuseok', '["verified","hidden-gem"]', '["in ấn","bảo tàng","UNESCO"]', '[{"seed":"cheongju-jikji","caption":"Khuôn chữ kim loại rời","ratio":"16/9"}]', '["songnisan-beopjusa"]', 0, 'https://www.cheongju.go.kr/jikjiworld/contents.do?key=17472', '2026-08-04', '{"en":{"name":"Cheongju Early Printing Museum","summary":"Where the world''s oldest book printed with movable metal type was made — 78 years before Gutenberg.","story":"In 1377, at Heungdeoksa temple in Cheongju, monks printed the ''Jikji'' using movable metal type — seventy-eight years before the Gutenberg Bible. The only surviving copy is in the National Library of France, so the museum built on the temple''s foundations displays a facsimile alongside the whole process of casting, setting and printing. There is a workshop where you can print a page yourself from a wooden block. For anyone who loves books, this is one of the most worthwhile addresses in Korea.","facts":["The ''Jikji'' was printed in 1377 and joined UNESCO''s Memory of the World register in 2001.","It predates the Gutenberg Bible by about 78 years.","The only surviving original is held by the National Library of France.","The museum stands on the site of Heungdeoksa temple, rediscovered in 1985."],"travelTips":["There is a hands-on printing workshop, good for children.","English guided tours need booking in advance.","Cheongju is about 1.5 hours from Seoul by train."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"","openingHours":"09:00–18:00 year-round; closed Mondays, 1 January, Seollal and Chuseok","galleryCaptions":["Movable metal type"]},"ko":{"name":"청주 고인쇄박물관(흥덕사지)","summary":"세계에서 가장 오래된 금속활자본이 인쇄된 곳. 구텐베르크보다 78년 빠르다.","story":"1377년 청주 흥덕사에서 승려들이 금속활자로 『직지』를 찍었다. 구텐베르크 성서보다 78년 앞선다. 유일한 원본은 프랑스 국립도서관에 있어, 절터 위에 세운 박물관은 영인본과 함께 활자 주조부터 조판, 인쇄까지 전 과정을 보여준다. 목판으로 한 장을 직접 찍어보는 체험실도 있다. 책을 좋아하는 사람이라면 한국에서 가장 가볼 만한 주소 가운데 하나다.","facts":["『직지』는 1377년에 인쇄되었고 2001년 유네스코 세계기록유산에 등재되었다.","구텐베르크 성서보다 약 78년 앞선다.","현존하는 유일한 원본은 프랑스 국립도서관이 소장하고 있다.","박물관은 1985년 발굴된 흥덕사 터 위에 세워졌다."],"travelTips":["활자 인쇄 체험이 있어 아이와 함께 가기 좋다.","영어 해설은 사전 예약이 필요하다.","청주는 서울에서 기차로 약 1시간 30분 거리다."],"bestTime":"연중","visitDuration":"1시간 30분","ticket":"","openingHours":"연중 09:00~18:00, 월요일과 1월 1일·설날·추석 당일 휴관","galleryCaptions":["금속활자"]},"ja":{"name":"清州古印刷博物館（興徳寺址）","summary":"世界最古の金属活字本が刷られた場所。グーテンベルクより78年早い。","story":"1377年、清州の興徳寺で僧たちが金属活字により『直指』を刷った。グーテンベルク聖書より78年早い。唯一残る原本はフランス国立図書館にあるため、寺跡に建つ博物館は複製とともに、活字の鋳造から組版、印刷までの全工程を見せる。木版で一枚刷ってみられる体験室もある。本が好きな人には、韓国で最も訪ねる価値のある住所のひとつだ。","facts":["『直指』は1377年に印刷され、2001年にユネスコ世界記憶遺産に登録された。","グーテンベルク聖書より約78年早い。","現存する唯一の原本はフランス国立図書館が所蔵する。","博物館は1985年に発掘された興徳寺跡に建つ。"],"travelTips":["活字印刷の体験があり子ども連れにも良い。","英語ガイドは事前予約が必要。","清州はソウルから列車で約1時間30分。"],"bestTime":"通年","visitDuration":"1時間30分","ticket":"","openingHours":"通年09:00〜18:00、月曜と1月1日・旧正月・秋夕は休館","galleryCaptions":["金属活字"]},"zh":{"name":"清州古印刷博物館（興德寺址）","summary":"世界現存最早金屬活字本的印製地，比古騰堡早了七十八年。","story":"1377年，清州興德寺的僧人以金屬活字印出《直指》——比古騰堡聖經早七十八年。唯一存世的原本藏於法國國家圖書館，因此建在寺址上的博物館展出影印本，並完整呈現鑄字、排版與印刷的全過程。館內另設工作坊，可親手用木版印一張紙。對愛書的人來說，這是韓國最值得一訪的地址之一。","facts":["《直指》印於1377年，2001年列入世界記憶名錄。","比古騰堡聖經早約78年。","唯一存世原本由法國國家圖書館收藏。","博物館建於1985年發掘的興德寺遺址上。"],"travelTips":["設有活字印刷體驗，適合親子同行。","英語導覽須事先預約。","清州距首爾搭火車約1.5小時。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"","openingHours":"全年09:00–18:00；週一、1月1日與春節、中秋當日休館","galleryCaptions":["金屬活字"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('mancheonha-skywalk', 'mancheonha-skywalk', 'chungbuk', 'Skywalk Mancheonha (Danyang)', 'Mancheonha Skywalk, Danyang', 'bridge', 128.3745, 36.9855, 'Sàn kính nhô ra khỏi vách đá cao tám mươi mét, nhìn thẳng xuống khúc uốn sông Namhan.', 'Ở Danyang, sông Namhan uốn một vòng gần khép quanh chân vách đá, và người ta xây một tháp xoắn ốc lên đỉnh vách rồi đẩy ba nhánh sàn kính nhô ra ngoài không trung. Đứng ở đầu nhánh, dưới chân bạn là tám mươi mét không khí rồi tới mặt nước xanh lục. Đường lên là một dốc xoắn dài chừng một trăm hai mươi mét, đi bộ vừa lên vừa nhìn cảnh mở dần ra. Bên cạnh có tuyến zipline dài nhất vùng và một máng trượt xuống chân đồi. Danyang là vùng đá vôi nên nước sông ở đây có màu xanh ngọc rất khác các sông khác của Hàn Quốc.', '["Sàn kính nhô ra khỏi vách đá cao khoảng 80m so với mặt sông Namhan.","Có ba nhánh sàn kính hình móng ngựa ở đầu tháp.","Đường dốc xoắn ốc lên đỉnh dài khoảng 120m.","Bên cạnh có zipline và máng trượt Alpine Coaster."]', '["Ngày mưa hoặc gió lớn sàn kính có thể đóng.","Đi buổi sáng sớm để tránh đông và có ánh sáng đẹp trên mặt sông.","Kết hợp Dodamsambong và hang Gosu trong cùng ngày ở Danyang."]', 'Tháng 4–6 và 9–11', '1,5 giờ', '4.000 KRW; zipline riêng 30.000 KRW', '09:00–18:00', '["trending"]', '["sàn kính","sông","vách đá","toàn cảnh"]', '[{"seed":"mancheonha-skywalk","caption":"Sàn kính nhìn xuống khúc uốn sông Namhan","ratio":"16/9"}]', '["danyang-dodamsambong","gosu-cave"]', 0, 'https://www.tripadvisor.com/Attraction_Review-g1544596-d13074307-Reviews-Mancheonha_Skywalk-Danyang_gun_Chungcheongbuk_do.html', '2026-08-04', '{"en":{"name":"Mancheonha Skywalk, Danyang","summary":"A glass deck out over a cliff eighty metres up, looking straight down at the Namhan river bend.","story":"At Danyang the Namhan river loops almost closed around the foot of a cliff, and someone built a spiral tower to the top of that cliff and pushed three glass arms out into the air. Standing at the end of an arm there is eighty metres of nothing under you, then green water. The way up is a spiral ramp about a hundred and twenty metres long, so the view opens gradually as you climb. Beside it are the region''s longest zipline and an alpine coaster down the hill. Danyang is limestone country, which is why the river here runs a jade green quite unlike other Korean rivers.","facts":["The glass deck stands about 80m above the Namhan river.","Three horseshoe-shaped glass arms extend from the top of the tower.","The spiral ramp to the top runs about 120m.","A zipline and an alpine coaster operate alongside it."],"travelTips":["The deck can close in rain or high wind.","Go early for fewer people and better light on the water.","Combine Dodamsambong and Gosu cave in the same day at Danyang."],"bestTime":"April–June and September–November","visitDuration":"1.5 hours","ticket":"4,000 KRW; the zipline is a separate 30,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["The glass deck over the Namhan river bend"]},"ko":{"name":"단양 만천하스카이워크","summary":"절벽에서 내민 유리 바닥. 80m 아래로 남한강의 물굽이가 그대로 보인다.","story":"단양에서 남한강은 절벽 아래를 거의 한 바퀴 감아 돌고, 사람들은 그 절벽 위로 나선형 탑을 세운 뒤 유리 바닥 세 갈래를 허공으로 내밀었다. 끝에 서면 발밑으로 80m의 공기가 있고 그 아래에 초록빛 물이 있다. 오르는 길은 120m쯤 되는 나선 경사로여서, 걸어 올라가는 동안 풍경이 조금씩 열린다. 옆에는 이 지역에서 가장 긴 짚와이어와 산 아래로 내려가는 알파인코스터가 있다. 단양은 석회암 지대여서 이곳의 강물은 한국의 다른 강과 다른 옥빛을 띤다.","facts":["유리 바닥은 남한강 수면에서 약 80m 위에 있다.","탑 끝에 말굽 모양의 유리 바닥 세 갈래가 있다.","정상까지 오르는 나선 경사로는 약 120m다.","옆에 짚와이어와 알파인코스터가 함께 운영된다."],"travelTips":["비가 오거나 바람이 세면 유리 바닥이 통제될 수 있다.","이른 아침에 가면 한산하고 물빛도 좋다.","같은 날 도담삼봉과 고수동굴을 묶어 단양을 돌자."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5시간","ticket":"4,000원, 짚라인은 별도 30,000원","openingHours":"09:00~18:00","galleryCaptions":["남한강 물굽이를 내려다보는 유리 바닥"]},"ja":{"name":"丹陽萬天下スカイウォーク","summary":"崖から突き出したガラスの床。80m下に南漢江の蛇行がそのまま見える。","story":"丹陽で南漢江は崖の下をほとんど一周するように曲がり、人々はその崖の上へ螺旋の塔を建て、ガラス床を三方へ宙に突き出した。先端に立てば足元に八十メートルの空気があり、その下に緑の水がある。上りは百二十メートルほどの螺旋スロープで、歩くうちに眺めが少しずつ開ける。隣には地域最長のジップラインと、山を下るアルパインコースターがある。丹陽は石灰岩地帯なので、ここの川の水は韓国の他の川とは違う翡翠色をしている。","facts":["ガラス床は南漢江の水面から約80m上にある。","塔の先端に馬蹄形のガラス床が三方へ張り出す。","頂上までの螺旋スロープは約120m。","隣にジップラインとアルパインコースターがある。"],"travelTips":["雨や強風のときはガラス床が閉鎖されることがある。","早朝は空いていて水の色もよい。","同じ日に島潭三峰と古藪洞窟を回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1.5時間","ticket":"4,000ウォン、ジップラインは別途30,000ウォン","openingHours":"09:00〜18:00","galleryCaptions":["南漢江の蛇行を見下ろすガラス床"]},"zh":{"name":"丹陽萬天下天空步道","summary":"自崖壁伸出的玻璃平台，八十公尺下就是南漢江的河灣。","story":"在丹陽，南漢江幾乎繞著一片崖壁轉了一整圈，有人便在崖頂蓋起一座螺旋塔，再把三道玻璃平台推進空中。站在末端，腳下是八十公尺的空氣，然後才是綠色的水。上去的路是一道約一百二十公尺的螺旋坡道，一邊走一邊看著視野慢慢展開。旁邊還有本地最長的高空滑索，以及一條下山的滑行車道。丹陽是石灰岩地帶，因此這裡的江水呈現一種與韓國其他河川都不同的翡翠綠。","facts":["玻璃平台位於南漢江水面上方約80公尺處。","塔頂伸出三道馬蹄形玻璃平台。","通往頂端的螺旋坡道長約120公尺。","旁邊設有高空滑索與滑行車道。"],"travelTips":["下雨或強風時玻璃平台可能封閉。","一早前往人少，水色也好。","同一天可把島潭三峰與古藪洞窟一起排進丹陽行程。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5小時","ticket":"4,000韓元；滑索另收30,000韓元","openingHours":"09:00–18:00","galleryCaptions":["俯瞰南漢江河灣的玻璃平台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gosu-cave', 'gosu-cave', 'chungbuk', 'Hang Gosu (Danyang)', 'Gosu Cave, Danyang', 'cave', 128.3665, 36.9885, 'Hang đá vôi chật hẹp phải bò và trèo, với măng đá hình tay Phật và sư tử được đặt tên riêng.', 'Gosu không phải loại hang có lối đi rộng cho xe đẩy. Đường trong hang dài hơn một cây số nhưng chật, thấp, nhiều đoạn phải cúi người và leo cầu thang sắt dựng gần như thẳng đứng qua các tầng. Đổi lại, mật độ nhũ đá ở đây cao đến mức nhiều khối được đặt tên riêng: ''tay Phật'', ''sư tử'', ''thác đá'', ''tháp sư''. Hang có ba tầng chồng lên nhau và một dòng nước ngầm vẫn đang chảy, nghĩa là nhũ đá vẫn đang lớn. Nhiệt độ trong hang giữ khoảng mười lăm độ quanh năm, và độ ẩm cao đến mức kính máy ảnh mờ ngay khi bước vào.', '["Tổng chiều dài hang khoảng 1,7 km, phần mở cho khách chừng 940m.","Được công nhận là Đài kỷ niệm thiên nhiên số 256.","Hang có ba tầng và dòng nước ngầm vẫn đang hoạt động.","Nhiệt độ trong hang giữ khoảng 15°C quanh năm."]', '["Nhiều đoạn phải cúi và leo thang sắt — không hợp người ngại hẹp hay đau gối.","Mang khăn lau ống kính; hơi nước làm mờ ngay.","Đi giày bám tốt, nền hang luôn ướt."]', 'Quanh năm; mùa hè mát nhất', '1,5 giờ', '11.000 KRW', '09:00–18:00', '["hidden-gem"]', '["hang động","nhũ đá","đá vôi","Danyang"]', '[{"seed":"gosu-cave","caption":"Nhũ đá trong hang Gosu","ratio":"16/9"}]', '["danyang-dodamsambong","mancheonha-skywalk"]', 0, 'https://www.tripadvisor.com/Attraction_Review-g1544596-d3823675-Reviews-Gosu_Cave-Danyang_gun_Chungcheongbuk_do.html', '2026-08-04', '{"en":{"name":"Gosu Cave, Danyang","summary":"A tight limestone cave of crawling and climbing, with formations named for a Buddha''s hand and a lion.","story":"Gosu is not the sort of cave with wide paths for pushchairs. The route runs over a kilometre but is narrow and low, with stretches where you stoop and steel stairs climbing almost vertically between levels. In return, the density of formations is such that many have their own names: the Buddha''s hand, the lion, the stone waterfall, the monk''s pagoda. The cave has three stacked levels and a stream still running through it, which means the formations are still growing. It holds about fifteen degrees year-round, and the humidity fogs a camera lens the moment you step in.","facts":["The cave runs about 1.7km in total, with roughly 940m open to visitors.","Designated Natural Monument No. 256.","It has three levels and an active underground stream.","The interior holds about 15°C year-round."],"travelTips":["Lots of stooping and steel ladders — not for anyone with bad knees or claustrophobia.","Bring a lens cloth; the humidity fogs everything immediately.","Wear grippy shoes; the floor is permanently wet."],"bestTime":"Year-round; coolest refuge in summer","visitDuration":"1.5 hours","ticket":"11,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["Formations inside Gosu cave"]},"ko":{"name":"단양 고수동굴","summary":"기어가고 올라가야 하는 좁은 석회동굴. 부처손과 사자로 불리는 종유석이 있다.","story":"고수동굴은 유모차가 다닐 만한 넓은 길의 동굴이 아니다. 관람로는 1km가 넘지만 좁고 낮아 몸을 숙여야 하는 구간이 있고, 층 사이를 거의 수직에 가까운 철계단으로 오른다. 대신 종유석의 밀도가 높아 이름이 붙은 것이 많다. 부처손, 사자바위, 돌폭포, 도담삼봉. 동굴은 세 층으로 겹쳐 있고 지하수가 아직 흐르고 있어 종유석이 지금도 자란다. 안은 연중 15도 안팎이고 습도가 높아 들어서는 순간 카메라 렌즈가 흐려진다.","facts":["총 길이는 약 1.7km이고 관람 구간은 940m가량이다.","천연기념물 제256호로 지정되어 있다.","동굴은 세 층이며 지하수가 지금도 흐른다.","내부는 연중 15도 안팎을 유지한다."],"travelTips":["몸을 숙이고 철계단을 오르는 구간이 많다. 무릎이 안 좋거나 좁은 곳이 힘들면 무리다.","렌즈 닦을 천을 챙기자. 습기로 바로 흐려진다.","바닥이 늘 젖어 있으니 접지력 좋은 신발을 신자."],"bestTime":"연중, 여름에 가장 시원하다","visitDuration":"1.5시간","ticket":"11,000원","openingHours":"09:00~18:00","galleryCaptions":["고수동굴의 종유석"]},"ja":{"name":"丹陽古藪洞窟","summary":"屈み、登らねばならない狭い石灰洞。仏の手や獅子と名づけられた鍾乳石がある。","story":"古藪洞窟はベビーカーが通れる広い道の洞ではない。観覧路は一キロを超えるが狭く低く、身を屈める区間があり、層のあいだをほぼ垂直の鉄階段で上る。その代わり鍾乳石の密度が高く、名を持つものが多い。仏の手、獅子岩、石の滝、僧の塔。洞は三層に重なり、地下水がいまも流れているので鍾乳石は今も育っている。内部は年中十五度前後で、湿度が高く、入った瞬間にカメラのレンズが曇る。","facts":["総延長は約1.7km、観覧区間は940mほどである。","天然記念物第256号に指定されている。","洞は三層あり、地下水が今も流れている。","内部は年間を通じて15度前後を保つ。"],"travelTips":["屈む区間と鉄階段が多い。膝が悪い人や狭所が苦手な人には向かない。","レンズ拭きを持とう。湿気ですぐ曇る。","床は常に濡れている。グリップのある靴で。"],"bestTime":"通年、夏は最も涼しい","visitDuration":"1.5時間","ticket":"11,000ウォン","openingHours":"09:00〜18:00","galleryCaptions":["古藪洞窟の鍾乳石"]},"zh":{"name":"丹陽古藪洞窟","summary":"得彎腰、攀爬的狹窄石灰岩洞，鐘乳石各有其名，如佛手與獅子。","story":"古藪洞窟不是那種嬰兒車推得進去的寬敞洞穴。參觀路線超過一公里，卻又窄又低，有些路段得彎著身子走，層與層之間靠幾乎垂直的鐵梯上下。作為回報，這裡鐘乳石的密度高到許多都有自己的名字：佛手、獅子岩、石瀑、僧塔。洞穴共三層相疊，地下水至今仍在流動，也就是說鐘乳石還在長。洞內全年約十五度，濕度高到一踏進去相機鏡頭就起霧。","facts":["洞穴總長約1.7公里，開放參觀段約940公尺。","被指定為天然紀念物第256號。","洞內共三層，地下水至今仍在流動。","洞內全年維持攝氏15度左右。"],"travelTips":["需要頻繁彎腰與攀爬鐵梯，膝蓋不好或怕狹窄者不宜。","帶塊擦鏡布，濕氣會立刻讓鏡頭起霧。","洞內地面長年濕滑，請穿抓地力好的鞋。"],"bestTime":"全年；夏天最涼爽","visitDuration":"1.5小時","ticket":"11,000韓元","openingHours":"09:00–18:00","galleryCaptions":["古藪洞窟中的鐘乳石"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('chungju-lake-ferry', 'chungju-lake-ferry', 'chungbuk', 'Hồ Chungju & tàu ngắm cảnh', 'Chungju Lake & Sightseeing Ferry', 'lake', 128.1465, 36.9885, 'Hồ nhân tạo lớn nhất nội địa Hàn Quốc, tàu chạy giữa các vách đá dựng đứng suốt hai tiếng.', 'Khi đập Chungju chặn dòng Namhan năm 1985, cả một hệ thung lũng bị ngập và thành hồ nhân tạo lớn nhất nội địa Hàn Quốc. Nước dâng lên tới lưng chừng các vách đá vôi, nên đi tàu trên hồ này giống đi trong một hẻm núi ngập nước — hai bên là đá dựng đứng, thi thoảng có một ngôi chùa hay một xóm nhỏ bám trên sườn. Tuyến tàu từ Chungju tới Danyang mất khoảng hai tiếng và đi ngang Gudambong, mỏm đá được xếp trong ''Đan Dương bát cảnh'' từ thời Joseon. Mực nước thay đổi theo mùa, và có năm hạn thì lộ ra nền các ngôi làng cũ dưới đáy.', '["Hình thành năm 1985 khi đập Chungju chặn sông Namhan.","Là hồ nhân tạo lớn nhất nằm hoàn toàn trong nội địa Hàn Quốc.","Tuyến tàu Chungju–Danyang mất khoảng 2 giờ.","Tàu đi ngang Gudambong, một trong ''Đan Dương bát cảnh''."]', '["Tàu ngừng chạy khi mực nước quá thấp — kiểm tra trước khi đi.","Đi chiều Chungju→Danyang rồi về bằng tàu hoả sẽ tiện hơn.","Ngồi boong ngoài; trong khoang kính khó nhìn rõ vách đá."]', 'Tháng 5–6 và 10–11 (lá đỏ hai bên hồ)', 'Nửa ngày', '12.000–20.000 KRW tuỳ tuyến và bến (trẻ em từ 8.000)', 'Theo lịch tàu, thường 2–4 chuyến/ngày', '["hidden-gem"]', '["hồ","tàu","vách đá","mùa thu"]', '[{"seed":"chungju-lake-ferry","caption":"Tàu chạy giữa vách đá hồ Chungju","ratio":"16/9"}]', '["danyang-dodamsambong","chungju-jungangtap"]', 0, 'https://onedaykorea.com/tours/danyang-eight-scenic-views-dodamsambong-peak-chungju-lake-cruise-tour/', '2026-08-04', '{"en":{"name":"Chungju Lake & Sightseeing Ferry","summary":"Korea''s largest inland reservoir, with a two-hour boat running between sheer limestone walls.","story":"When the Chungju dam blocked the Namhan in 1985 a whole valley system flooded and became Korea''s largest wholly inland reservoir. The water rose to halfway up the limestone cliffs, so travelling this lake by boat is like moving through a drowned gorge — vertical rock on both sides, with the occasional temple or hamlet clinging to a slope. The Chungju to Danyang run takes about two hours and passes Gudambong, a rock listed among the Eight Scenes of Danyang since Joseon times. Water levels shift with the season, and in a dry year the foundations of old villages surface on the bed.","facts":["Formed in 1985 when the Chungju dam blocked the Namhan river.","The largest artificial lake lying entirely inland in Korea.","The Chungju–Danyang ferry run takes about two hours.","The boat passes Gudambong, one of the Eight Scenes of Danyang."],"travelTips":["Sailings stop when the water is too low — check before travelling.","Going Chungju to Danyang and returning by train is the easier direction.","Sit on the open deck; the cliffs are hard to see through the cabin glass."],"bestTime":"May–June and October–November (autumn colour on both shores)","visitDuration":"Half a day","ticket":"12,000–20,000 KRW depending on route and pier (children from 8,000)","openingHours":"By sailing schedule, usually 2–4 a day","galleryCaptions":["The ferry between the cliffs of Chungju Lake"]},"ko":{"name":"충주호와 유람선","summary":"한국 최대의 내륙 인공호. 배가 두 시간 동안 깎아지른 석회암 절벽 사이를 지난다.","story":"1985년 충주댐이 남한강을 막자 골짜기 하나가 통째로 잠겨 한국에서 가장 큰 내륙 인공호가 되었다. 물이 석회암 절벽의 중턱까지 차올라, 이 호수를 배로 지나는 일은 물에 잠긴 협곡을 지나는 것과 같다. 양쪽은 수직의 바위이고 이따금 비탈에 절이나 작은 마을이 붙어 있다. 충주에서 단양까지는 두 시간쯤 걸리며, 조선 시대부터 단양팔경에 든 구담봉을 지난다. 수위는 계절에 따라 달라지고, 가문 해에는 바닥의 옛 마을 터가 드러나기도 한다.","facts":["1985년 충주댐이 남한강을 막으며 생겼다.","완전히 내륙에 있는 인공호 가운데 한국에서 가장 크다.","충주~단양 유람선은 두 시간쯤 걸린다.","배는 단양팔경의 하나인 구담봉을 지난다."],"travelTips":["수위가 낮으면 운항을 멈춘다. 미리 확인하자.","충주에서 단양 방향으로 타고 기차로 돌아오는 편이 수월하다.","선실 유리로는 절벽이 잘 안 보인다. 갑판에 앉자."],"bestTime":"5~6월, 10~11월(양안의 단풍)","visitDuration":"반나절","ticket":"항로와 선착장에 따라 12,000~20,000원(어린이 8,000원부터)","openingHours":"운항 일정에 따름, 보통 하루 2~4회","galleryCaptions":["충주호 절벽 사이를 지나는 유람선"]},"ja":{"name":"忠州湖と遊覧船","summary":"韓国最大の内陸人造湖。船が二時間、切り立った石灰岩の壁のあいだを進む。","story":"1985年に忠州ダムが南漢江を塞ぐと、谷がまるごと沈んで韓国最大の内陸人造湖になった。水は石灰岩の崖の中腹まで満ち、この湖を船で行くのは水没した峡谷を進むようだ。両側は垂直の岩で、ときおり斜面に寺や小さな集落が貼りついている。忠州から丹陽までは二時間ほどで、朝鮮時代から丹陽八景に数えられる亀潭峰を通る。水位は季節で変わり、渇水の年には湖底の旧村落の跡が現れることもある。","facts":["1985年、忠州ダムが南漢江を塞いでできた。","完全に内陸にある人造湖としては韓国最大である。","忠州〜丹陽の遊覧船は約2時間かかる。","船は丹陽八景のひとつ亀潭峰を通る。"],"travelTips":["水位が低いと運航を止める。事前に確認しよう。","忠州から丹陽へ乗り、鉄道で戻るほうが楽だ。","船室のガラス越しでは崖が見づらい。デッキに座ろう。"],"bestTime":"5〜6月、10〜11月（両岸の紅葉）","visitDuration":"半日","ticket":"航路と乗り場により12,000〜20,000ウォン（子どもは8,000ウォンから）","openingHours":"運航ダイヤによる、通常1日2〜4便","galleryCaptions":["忠州湖の崖のあいだを進む遊覧船"]},"zh":{"name":"忠州湖與遊覽船","summary":"韓國最大的內陸人工湖，遊船在陡直的石灰岩壁之間航行兩小時。","story":"1985年忠州水壩攔住南漢江，整片谷地沒入水中，成了韓國最大的完全內陸人工湖。水位漲到石灰岩崖壁的半腰，因此搭船遊這座湖，就像穿行在一條被淹沒的峽谷裡——兩側是垂直的岩壁，偶爾有一座寺院或小聚落攀在坡上。忠州到丹陽的航程約兩小時，會經過龜潭峰——自朝鮮時代起就名列丹陽八景。水位隨季節變動，乾旱的年份湖底舊村落的地基會浮出水面。","facts":["1985年忠州水壩攔截南漢江後形成。","是韓國最大的完全位於內陸的人工湖。","忠州至丹陽的航程約需兩小時。","航線會經過丹陽八景之一的龜潭峰。"],"travelTips":["水位過低時會停航，出發前先確認。","從忠州往丹陽、再搭火車回程比較順。","坐在露天甲板；隔著船艙玻璃看不清崖壁。"],"bestTime":"5至6月與10至11月（兩岸紅葉）","visitDuration":"半天","ticket":"依航線與碼頭為12,000至20,000韓元（兒童8,000起）","openingHours":"依航班時刻，通常每日2至4班","galleryCaptions":["穿行於忠州湖崖壁之間的遊覽船"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('chungju-jungangtap', 'chungju-jungangtap', 'chungbuk', 'Tháp Jungangtap (Chungju)', 'Jungangtap Pagoda, Chungju', 'park', 127.8635, 37.0165, 'Tháp đá cao nhất Hàn Quốc, dựng ở nơi được coi là trung tâm địa lý của vương quốc Silla.', 'Tháp bảy tầng này cao gần mười lăm mét, là tháp đá cao nhất còn lại ở Hàn Quốc, và tên gọi Jungangtap — ''tháp trung tâm'' — đến từ việc Silla xác định đây là điểm giữa của lãnh thổ mình rồi dựng tháp đánh dấu. Vào thời ấy Chungju là nút giao thông sống còn: sông Namhan chảy qua đây nối vùng nội địa với Seoul, và mỏ sắt gần đó cung cấp vũ khí. Tháp đứng trên một bãi cỏ rộng bên sông, quanh nó giờ là công viên điêu khắc ngoài trời và một bảo tàng nhỏ. Chiều muộn, bóng tháp đổ dài trên cỏ và gần như không có ai.', '["Cao khoảng 14,5m, là tháp đá cao nhất còn lại ở Hàn Quốc.","Được dựng thời Silla thống nhất, khoảng thế kỷ 8–9.","Tên ''Jungangtap'' nghĩa là tháp ở trung tâm lãnh thổ Silla.","Quanh tháp nay là công viên điêu khắc và bảo tàng Chungju."]', '["Chiều muộn ánh sáng đẹp nhất và gần như vắng người.","Có lối đi bộ ven sông Namhan ngay cạnh công viên.","Kết hợp với bến tàu hồ Chungju cách đó khoảng 20 phút xe."]', 'Tháng 4–6 và 9–11', '1 giờ', '', 'Công viên mở cả ngày, quanh năm; Bảo tàng Chungju và Bảo tàng Rượu trong khuôn viên mở 09:00–18:00', '["hidden-gem"]', '["tháp đá","Silla","công viên","sông"]', '[{"seed":"chungju-jungangtap","caption":"Tháp Jungangtap bên sông Namhan","ratio":"16/9"}]', '["chungju-lake-ferry"]', 0, 'https://access.visitkorea.or.kr/ms/detail.do?cotId=db6c28b7-4f93-42fd-8e80-56c5eaf9831e', '2026-08-05', '{"en":{"name":"Jungangtap Pagoda, Chungju","summary":"Korea''s tallest stone pagoda, raised at what Silla reckoned to be the centre of its territory.","story":"This seven-storey pagoda stands nearly fifteen metres, the tallest surviving stone pagoda in Korea, and its name — Jungangtap, the central pagoda — comes from Silla fixing this as the midpoint of its territory and marking it. Chungju was a crucial junction in that period: the Namhan river ran through it linking the interior with the capital, and the iron mines nearby supplied weapons. The pagoda stands on a broad lawn beside the river, now surrounded by an open-air sculpture park and a small museum. Late in the day its shadow stretches across the grass and there is almost nobody about.","facts":["About 14.5m tall, the tallest surviving stone pagoda in Korea.","Raised in the Unified Silla period, around the 8th–9th century.","The name means the pagoda at the centre of Silla''s territory.","The grounds now hold a sculpture park and the Chungju museum."],"travelTips":["Late afternoon has the best light and almost no visitors.","There is a riverside walking path along the Namhan beside the park.","Combine it with the Chungju Lake ferry pier, about 20 minutes away."],"bestTime":"April–June and September–November","visitDuration":"1 hour","ticket":"","openingHours":"The park is open all day, year-round; the Chungju Museum and the Liquor Museum inside run 09:00–18:00","galleryCaptions":["Jungangtap pagoda beside the Namhan river"]},"ko":{"name":"충주 중앙탑","summary":"한국에서 가장 높은 석탑. 신라가 자기 영토의 중심으로 삼은 자리에 세웠다.","story":"이 칠층석탑은 높이가 15m에 가까워 한국에 남은 석탑 중 가장 높고, 중앙탑이라는 이름은 신라가 이곳을 영토의 한가운데로 보고 표시한 데서 왔다. 당시 충주는 결정적인 길목이었다. 남한강이 이곳을 지나 내륙과 도읍을 잇고, 가까운 철광이 무기를 댔다. 탑은 강가의 넓은 잔디밭에 서 있고 둘레는 지금 야외 조각공원과 작은 박물관이다. 해가 기울면 탑 그림자가 잔디 위로 길게 눕고, 사람은 거의 없다.","facts":["높이 약 14.5m로 한국에 남은 석탑 가운데 가장 높다.","통일신라 시기인 8~9세기경에 세워졌다.","''중앙탑''은 신라 영토의 중심에 세운 탑이라는 뜻이다.","탑 둘레는 지금 조각공원과 충주박물관이다."],"travelTips":["늦은 오후가 빛도 좋고 사람도 거의 없다.","공원 옆으로 남한강 산책로가 이어진다.","차로 20분 거리의 충주호 선착장과 묶어서 보자."],"bestTime":"4~6월, 9~11월","visitDuration":"1시간","ticket":"","openingHours":"공원은 상시·연중무휴 개방. 경내 충주박물관과 술박물관은 09:00~18:00","galleryCaptions":["남한강가의 중앙탑"]},"ja":{"name":"忠州中央塔","summary":"韓国で最も高い石塔。新羅が自国領土の中心と定めた場所に建てられた。","story":"この七層石塔は高さ十五メートル近く、韓国に残る石塔で最も高い。中央塔という名は、新羅がここを領土の中心と定めて標としたことに由来する。当時の忠州は決定的な結節点だった。南漢江がここを通って内陸と都を結び、近くの鉄鉱が武器を供給した。塔は川辺の広い芝地に立ち、周囲はいま野外彫刻公園と小さな博物館である。日が傾くと塔の影が芝に長く伸び、人はほとんどいない。","facts":["高さ約14.5mで、韓国に残る石塔では最も高い。","統一新羅期、8〜9世紀ごろの造立である。","「中央塔」は新羅領土の中心に建てた塔の意である。","周囲は現在、彫刻公園と忠州博物館になっている。"],"travelTips":["遅い午後は光がよく、人もほとんどいない。","公園の脇に南漢江の遊歩道が続く。","車で20分の忠州湖の船着場と合わせて回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1時間","ticket":"","openingHours":"公園は終日・年中無休で開放。園内の忠州博物館と酒博物館は09:00〜18:00","galleryCaptions":["南漢江のほとりの中央塔"]},"zh":{"name":"忠州中央塔","summary":"韓國最高的石塔，立在新羅認定為自身疆域中心的位置上。","story":"這座七層石塔高近十五公尺，是韓國現存最高的石塔，而「中央塔」這個名字，來自新羅把此地定為疆域中點並立塔為記。在那個年代，忠州是至關重要的樞紐：南漢江流經此地，把內陸與都城連起來，附近的鐵礦則供應武器。塔立在江畔一片開闊草地上，四周如今是露天雕塑公園與一座小型博物館。天色轉晚時，塔影在草地上拉得很長，而且幾乎沒有人。","facts":["高約14.5公尺，是韓國現存最高的石塔。","建於統一新羅時期，約8至9世紀。","「中央塔」意為立於新羅疆域中心的塔。","周邊現為雕塑公園與忠州博物館。"],"travelTips":["傍晚光線最好，而且幾乎沒有遊客。","公園旁有沿南漢江的散步道。","可與車程約20分鐘的忠州湖碼頭排在一起。"],"bestTime":"4至6月與9至11月","visitDuration":"1小時","ticket":"","openingHours":"公園全日全年開放；園內忠州博物館與酒博物館09:00–18:00","galleryCaptions":["南漢江畔的中央塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheongnamdae', 'cheongnamdae', 'chungbuk', 'Biệt thự Cheongnamdae', 'Cheongnamdae Presidential Villa', 'park', 127.4795, 36.4585, 'Biệt thự nghỉ của tổng thống bị giấu kín hai mươi năm, mở cửa cho dân năm 2003.', 'Năm 1983, chính quyền quân sự cho xây một biệt thự nghỉ cho tổng thống bên hồ Daecheong và giữ nó hoàn toàn bí mật — không có trên bản đồ, đường vào bị chặn, dân quanh vùng không được lại gần. Trong hai mươi năm, sáu đời tổng thống dùng nơi này. Năm 2003, tổng thống Roh Moo-hyun quyết định trả nó lại cho dân và mở cửa. Giờ bạn đi trong khu vườn rộng bên hồ, xem phòng làm việc và phòng ngủ để nguyên như cũ, và đi trên con đường mòn mà các đời tổng thống từng đi bộ buổi sáng. Có cả một sân golf mini và một bể bơi ngoài trời khá khiêm tốn so với tưởng tượng.', '["Được xây năm 1983 làm nơi nghỉ của tổng thống và giữ bí mật trong 20 năm.","Sáu đời tổng thống Hàn Quốc đã sử dụng nơi này.","Mở cửa cho công chúng từ năm 2003.","Nằm bên hồ Daecheong, hồ nhân tạo lớn thứ ba Hàn Quốc."]', '["Khu vực rộng — có xe điện chở khách giữa các điểm.","Cuối tháng 4 có lễ hội hoa và rất đông.","Từ Cheongju đi bus khoảng 40 phút."]', 'Tháng 4–6 và 10–11', '2–3 giờ', '6.000 KRW (thiếu niên 4.000, trẻ em 3.000); miễn phí cho người từ 65 tuổi và trẻ dưới 7 tuổi', '09:00–18:00 (tháng 12–1 tới 17:00), vé bán tới 16:30; đóng cửa thứ Hai, 1/1, Tết và Chuseok', '["hidden-gem"]', '["biệt thự","lịch sử hiện đại","hồ","vườn"]', '[{"seed":"cheongnamdae","caption":"Vườn bên hồ ở Cheongnamdae","ratio":"16/9"}]', '["cheongju-jikji"]', 0, 'https://www.chungbuk.go.kr/chnam/content.do?key=2004170433966', '2026-08-04', '{"en":{"name":"Cheongnamdae Presidential Villa","summary":"A presidential retreat kept secret for twenty years, opened to the public in 2003.","story":"In 1983 the military government built a presidential retreat beside Daecheong lake and kept it entirely secret — off the maps, roads blocked, locals barred from approaching. Six presidents used it over twenty years. In 2003 President Roh Moo-hyun decided to give it back to the public and opened it. You now walk the large lakeside garden, see the study and bedroom left as they were, and take the path successive presidents walked in the mornings. There is a pitch-and-putt course and an outdoor pool considerably more modest than you would expect.","facts":["Built in 1983 as a presidential retreat and kept secret for 20 years.","Six Korean presidents used it.","Opened to the public in 2003.","It sits on Daecheong lake, Korea''s third largest reservoir."],"travelTips":["The grounds are large — a shuttle runs between the points of interest.","There is a flower festival in late April and it gets very busy.","About 40 minutes by bus from Cheongju."],"bestTime":"April–June and October–November","visitDuration":"2–3 hours","ticket":"6,000 KRW (4,000 teens, 3,000 children); free for over-65s and under-7s","openingHours":"09:00–18:00 (to 17:00 in December–January), ticketing until 16:30; closed Mondays, 1 Jan, Seollal and Chuseok","galleryCaptions":["The lakeside garden at Cheongnamdae"]},"ko":{"name":"청남대","summary":"이십 년 동안 비밀이었던 대통령 별장. 2003년 국민에게 열렸다.","story":"1983년 군사정권은 대청호 옆에 대통령 별장을 짓고 완전히 감췄다. 지도에 없었고 진입로는 막혔으며 인근 주민은 접근할 수 없었다. 이십 년 동안 여섯 명의 대통령이 이곳을 썼다. 2003년 노무현 대통령이 국민에게 돌려주기로 하고 개방했다. 지금은 호숫가의 넓은 정원을 걷고, 그대로 둔 집무실과 침실을 보고, 역대 대통령들이 아침에 걷던 길을 따라갈 수 있다. 파3 골프장과 야외 수영장도 있는데, 상상보다 훨씬 소박하다.","facts":["1983년 대통령 별장으로 지어져 20년간 비밀로 유지되었다.","여섯 명의 대통령이 이곳을 사용했다.","2003년부터 일반에 개방되었다.","한국에서 세 번째로 큰 인공호인 대청호 옆에 있다."],"travelTips":["부지가 넓다. 관람 지점 사이를 오가는 전동차가 있다.","4월 말 꽃축제 기간에는 매우 붐빈다.","청주에서 버스로 40분쯤 걸린다."],"bestTime":"4~6월, 10~11월","visitDuration":"2~3시간","ticket":"6,000원(청소년 4,000원, 어린이 3,000원), 65세 이상과 7세 미만 무료","openingHours":"09:00~18:00(12~1월은 17:00까지), 매표 16:30 마감, 월요일과 1월 1일·설날·추석 당일 휴관","galleryCaptions":["청남대의 호숫가 정원"]},"ja":{"name":"青南台","summary":"二十年ものあいだ秘密だった大統領別荘。2003年に国民へ開かれた。","story":"1983年、軍事政権は大清湖のほとりに大統領の別荘を建て、完全に隠した。地図になく、進入路は塞がれ、近隣住民は近づけなかった。二十年のあいだ六人の大統領がここを使った。2003年、盧武鉉大統領がこれを国民に返すと決めて開放した。いまは湖畔の広い庭を歩き、そのまま残された執務室と寝室を見て、歴代大統領が朝に歩いた道をたどれる。パー3のゴルフ場と屋外プールもあるが、想像よりずっと質素だ。","facts":["1983年に大統領別荘として建てられ、20年間秘密にされた。","六人の韓国大統領が使用した。","2003年から一般に開放されている。","韓国で三番目に大きい人造湖、大清湖のほとりにある。"],"travelTips":["敷地が広い。見どころのあいだを電動車が走る。","4月末の花祭りの時期は非常に混む。","清州からバスで40分ほど。"],"bestTime":"4〜6月、10〜11月","visitDuration":"2〜3時間","ticket":"6,000ウォン（青少年4,000、子ども3,000）、65歳以上と7歳未満は無料","openingHours":"09:00〜18:00（12〜1月は17:00まで）、券売は16:30まで。月曜と1月1日・旧正月・秋夕は休館","galleryCaptions":["青南台の湖畔の庭"]},"zh":{"name":"青南台","summary":"被保密二十年的總統別墅，2003年對民眾開放。","story":"1983年，軍政府在大清湖畔蓋了一座總統別墅，並將它徹底藏起來——地圖上沒有、聯外道路封閉、周邊居民不得靠近。二十年間，六位總統使用過這裡。2003年，盧武鉉總統決定把它還給民眾並開放參觀。如今你可以走在湖畔的大片庭園裡，看維持原狀的辦公室與臥室，走一走歷任總統晨間散步的那條路。園內還有一座三桿高爾夫球場與一座戶外泳池，樸素得遠遠超乎想像。","facts":["1983年興建為總統別墅，並保密二十年。","共有六位韓國總統使用過。","自2003年起對公眾開放。","位於韓國第三大人工湖大清湖畔。"],"travelTips":["園區很大——景點之間有電動車接駁。","四月底有花卉慶典，人潮非常多。","自清州搭巴士約40分鐘。"],"bestTime":"4至6月與10至11月","visitDuration":"2至3小時","ticket":"6,000韓元（青少年4,000、兒童3,000）；65歲以上與7歲以下免費","openingHours":"09:00–18:00（12月至1月至17:00），售票至16:30；週一、1月1日、春節與中秋當日休館","galleryCaptions":["青南台的湖畔庭園"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sobaeksan', 'sobaeksan', 'chungbuk', 'Vườn quốc gia Sobaeksan', 'Sobaeksan National Park', 'mountain', 128.4855, 36.9575, 'Sống núi trải hoa đỗ quyên vào tháng 6, và một đài thiên văn trên đỉnh vì trời ở đây trong nhất nước.', 'Sobaeksan có một sống núi dài chạy giữa Chungbuk và Gyeongbuk, và đoạn quanh đỉnh Birobong gần như không có cây cao — chỉ toàn cỏ và những bụi đỗ quyên hoàng gia thấp. Đầu tháng 6, cả sống núi phủ hồng, và vì ở độ cao gần một nghìn bốn trăm mét nên đây là nơi hoa đỗ quyên nở muộn nhất Hàn Quốc, khi các nơi khác đã tàn từ lâu. Trên một đỉnh khác là Đài thiên văn Sobaeksan — đặt ở đây vì không khí khô, ít mây và xa ánh đèn thành phố. Mùa đông, gió trên sống núi mạnh đến mức tuyết không đọng được mà bị thổi thành các gờ băng nằm ngang.', '["Đỉnh Birobong cao 1.439m, nằm trên ranh giới Chungbuk và Gyeongbuk.","Hoa đỗ quyên hoàng gia trên sống núi nở đầu tháng 6, muộn nhất Hàn Quốc.","Đài thiên văn Sobaeksan đặt trên núi vì điều kiện quan trắc tốt.","Gió mùa đông trên sống núi tạo ra các gờ băng nằm ngang đặc trưng."]', '["Tuyến phổ biến nhất là từ Huibangsa lên Birobong, khứ hồi khoảng 5 giờ.","Đầu tháng 6 mùa hoa rất đông vào cuối tuần.","Gió trên sống núi mạnh quanh năm — luôn mang áo gió."]', 'Đầu tháng 6 (đỗ quyên) và tháng 10 (lá đỏ)', 'Cả ngày', '', 'Áp dụng ''chế độ giờ vào núi'' của vườn quốc gia: được lên từ 04:00 (tháng 3–11) hoặc 05:00 (tháng 12–2), và mỗi cung đường có giờ chặn riêng trong khoảng 12:00–17:00. Kiểm tra thông báo đóng đường trước khi đi', '["hidden-gem"]', '["leo núi","đỗ quyên","sống núi","thiên văn"]', '[{"seed":"sobaeksan","caption":"Đỗ quyên trên sống núi Sobaeksan","ratio":"16/9"}]', '["guinsa","danyang-dodamsambong"]', 1, 'https://www.knps.or.kr/front/portal/safe/acsCtrDtl.do?menuNo=8000340&rstId=0005', '2026-08-05', '{"en":{"name":"Sobaeksan National Park","summary":"A ridge covered in royal azalea in June, and an observatory on a summit because the sky here is the country''s clearest.","story":"Sobaeksan has a long ridge running between Chungbuk and Gyeongbuk, and the stretch around Birobong summit carries almost no tall trees — only grass and low royal azalea. In early June the whole ridge turns pink, and because it sits near fourteen hundred metres this is the latest azalea bloom in Korea, when everywhere else finished long ago. On another summit stands Sobaeksan Observatory, sited here for dry air, few clouds and distance from city light. In winter the wind along the ridge is strong enough that snow cannot settle, and is instead blown into horizontal ridges of ice.","facts":["Birobong summit reaches 1,439m on the Chungbuk–Gyeongbuk border.","The ridge royal azaleas bloom in early June, the latest in Korea.","Sobaeksan Observatory was sited here for its observing conditions.","Winter wind along the ridge forms characteristic horizontal ice ridges."],"travelTips":["The usual route is Huibangsa to Birobong, about five hours return.","Early June weekends are very busy for the azaleas.","The ridge is windy year-round — always carry a windproof layer."],"bestTime":"Early June (azaleas) and October (autumn colour)","visitDuration":"A full day","ticket":"","openingHours":"The national park entry-time system applies: ascent opens at 04:00 (March–November) or 05:00 (December–February), and each section has its own turn-back time somewhere between 12:00 and 17:00. Check the trail-closure notices before setting out","galleryCaptions":["Royal azalea along the Sobaeksan ridge"]},"ko":{"name":"소백산국립공원","summary":"6월이면 철쭉으로 덮이는 능선. 하늘이 가장 맑아 정상에 천문대가 있다.","story":"소백산에는 충북과 경북 사이를 달리는 긴 능선이 있고, 비로봉 주변 구간에는 큰 나무가 거의 없다. 풀과 낮은 철쭉뿐이다. 6월 초면 능선 전체가 분홍으로 물드는데, 해발 1,400m 가까이라 다른 곳의 철쭉이 다 진 뒤에 피는 한국에서 가장 늦은 철쭉이다. 다른 봉우리에는 소백산천문대가 있다. 공기가 건조하고 구름이 적으며 도시 불빛에서 멀어 이곳에 세웠다. 겨울에는 능선의 바람이 너무 세서 눈이 쌓이지 못하고 가로로 뻗은 얼음 결로 붙는다.","facts":["비로봉은 1,439m로 충북과 경북의 경계에 있다.","능선의 철쭉은 6월 초에 피며 한국에서 가장 늦다.","소백산천문대는 관측 조건이 좋아 이곳에 세워졌다.","겨울 능선의 바람은 가로로 뻗은 얼음 결을 만든다."],"travelTips":["희방사에서 비로봉까지가 일반적인 코스로 왕복 다섯 시간쯤이다.","6월 초 주말은 철쭉을 보러 오는 사람으로 매우 붐빈다.","능선은 연중 바람이 세다. 바람막이는 늘 챙기자."],"bestTime":"6월 초(철쭉)와 10월(단풍)","visitDuration":"하루","ticket":"","openingHours":"국립공원 입산시간지정제가 적용된다. 입산은 3~11월 04:00, 12~2월 05:00부터 가능하며 구간마다 12:00~17:00 사이로 통제시간이 다르다. 출발 전 통제 정보를 확인하자","galleryCaptions":["소백산 능선의 철쭉"]},"ja":{"name":"小白山国立公園","summary":"6月にはツツジに覆われる稜線。空が国内で最も澄むため、山頂に天文台がある。","story":"小白山には忠清北道と慶尚北道のあいだを走る長い稜線があり、毘盧峰の周辺には高い木がほとんどない。草と背の低いレンゲツツジだけだ。六月初めには稜線全体が桃色に染まる。標高千四百メートル近くにあるため、他所のツツジがとうに終わったころに咲く、韓国で最も遅いツツジである。別の峰には小白山天文台がある。空気が乾き、雲が少なく、街の灯から遠いためにここへ置かれた。冬、稜線の風は強すぎて雪が積もれず、代わりに横へ伸びた氷の稜をつくる。","facts":["毘盧峰は1,439mで、忠清北道と慶尚北道の境にある。","稜線のレンゲツツジは6月初めに咲き、韓国で最も遅い。","小白山天文台は観測条件のよさからここに置かれた。","冬の稜線の風は特徴的な横向きの氷の稜をつくる。"],"travelTips":["喜方寺から毘盧峰までが一般的で、往復五時間ほど。","六月初めの週末はツツジ目当てで非常に混む。","稜線は年中風が強い。ウインドシェルは必携だ。"],"bestTime":"6月初め（ツツジ）と10月（紅葉）","visitDuration":"一日","ticket":"","openingHours":"国立公園の入山時間指定制が適用される。入山は3〜11月は04:00、12〜2月は05:00から可能で、区間ごとに12:00〜17:00の間で規制時刻が異なる。出発前に通行規制情報の確認を","galleryCaptions":["小白山の稜線のレンゲツツジ"]},"zh":{"name":"小白山國立公園","summary":"六月被杜鵑鋪滿的稜線，山頂還設有天文台——因為這裡的天空是全國最清澈的。","story":"小白山有一道橫在忠清北道與慶尚北道之間的長稜線，毘盧峰一帶幾乎沒有高大的樹，只有草與低矮的皇家杜鵑。六月初，整條稜線轉成粉紅；由於接近一千四百公尺高，這是韓國開得最晚的杜鵑，其他地方早就謝盡了。另一座峰頂立著小白山天文台，選在此處是因為空氣乾燥、雲量稀少、遠離城市燈光。冬天稜線上的風強到雪根本積不住，反而被吹成一道道橫向的冰稜。","facts":["毘盧峰海拔1,439公尺，位於忠北與慶北交界。","稜線上的皇家杜鵑於六月初盛開，是韓國最晚的。","小白山天文台因觀測條件優良而設於此。","冬季稜線強風會形成特有的橫向冰稜。"],"travelTips":["常走的路線是喜方寺至毘盧峰，來回約五小時。","六月初的週末因杜鵑而非常擁擠。","稜線全年風大，務必攜帶防風外套。"],"bestTime":"6月初（杜鵑）與10月（紅葉）","visitDuration":"一整天","ticket":"","openingHours":"適用國家公園「入山時間指定制」：3至11月自04:00、12至2月自05:00開放入山，各路段的折返管制時間落在12:00至17:00之間。出發前請先查看步道封閉公告","galleryCaptions":["小白山稜線上的皇家杜鵑"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gongju-tomb', 'gongju-tomb', 'chungnam', 'Lăng vua Muryeong & thành Gongsanseong (Gongju)', 'Tomb of King Muryeong & Gongsanseong', 'unesco', 127.1185, 36.4665, 'Ngôi mộ vua Bách Tế duy nhất xác định được danh tính, tìm thấy nguyên vẹn năm 1971.', 'Năm 1971, một nhóm công nhân đào rãnh thoát nước ở Gongju vô tình chạm vào một vòm gạch. Bên trong là mộ vua Muryeong của Bách Tế, chưa từng bị đào trộm, với hơn bốn nghìn hiện vật: vương miện vàng mỏng như lá, gối gỗ sơn son, và tấm bia ghi rõ tên tuổi — điều biến đây thành ngôi mộ Bách Tế duy nhất xác định được chủ nhân. Trên đồi cạnh đó là thành Gongsanseong với tường đất chạy vòng, nhìn xuống sông Geum.', '["Phát hiện năm 1971, còn nguyên vẹn với hơn 4.600 hiện vật.","Là ngôi mộ Bách Tế duy nhất xác định được danh tính chủ nhân.","Thuộc quần thể Di sản Thế giới UNESCO ''Khu vực lịch sử Bách Tế'' (2015).","Mộ thật đã đóng để bảo tồn; khách xem bản phục dựng kích thước thật."]', '["Ghé Bảo tàng Quốc gia Gongju để xem hiện vật gốc từ ngôi mộ.","Lễ hội văn hoá Bách Tế tổ chức vào tháng 9–10 tại Gongju và Buyeo.","Đi bộ vòng tường thành Gongsanseong mất khoảng một giờ."]', 'Tháng 9–10 (lễ hội Bách Tế)', '3 giờ', '1.500 KRW (Bảo tàng Quốc gia Gongju ngay cạnh vào miễn phí)', '09:00–18:00', '["unesco","verified"]', '["UNESCO","Bách Tế","khảo cổ"]', '[{"seed":"gongju-tomb","caption":"Tường thành Gongsanseong bên sông Geum","ratio":"16/9"}]', '["buyeo-busosanseong","gyeryongsan"]', 1, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=110612', '2026-08-04', '{"en":{"name":"Tomb of King Muryeong & Gongsanseong, Gongju","summary":"The only Baekje royal tomb whose occupant is known by name, found intact in 1971.","story":"In 1971 workmen digging a drainage ditch in Gongju struck a brick vault. Inside lay the tomb of King Muryeong of Baekje, never robbed, holding more than four thousand objects: gold crowns thin as leaves, lacquered wooden headrests, and a stone tablet naming the king — which makes this the only Baekje tomb whose owner is certain. On the hill beside it, the earthen ramparts of Gongsanseong run in a circle above the Geum River.","facts":["Discovered intact in 1971 with more than 4,600 artefacts.","The only Baekje tomb whose occupant has been positively identified.","Part of the UNESCO ''Baekje Historic Areas'' inscription of 2015.","The tomb itself is now sealed for conservation; visitors see a full-scale replica."],"travelTips":["Visit Gongju National Museum to see the original finds from the tomb.","The Baekje Cultural Festival is held in Gongju and Buyeo in September–October.","Walking the Gongsanseong ramparts takes about an hour."],"bestTime":"September–October (Baekje festival)","visitDuration":"3 hours","ticket":"1,500 KRW (the Gongju National Museum next door is free)","openingHours":"09:00–18:00","galleryCaptions":["Gongsanseong ramparts above the Geum River"]},"ko":{"name":"공주 무령왕릉과 공산성","summary":"주인을 이름으로 아는 유일한 백제 왕릉. 1971년 온전한 상태로 발견되었다.","story":"1971년 공주에서 배수로를 파던 인부들의 삽 끝에 벽돌 천장이 닿았다. 그 안에는 도굴되지 않은 백제 무령왕의 무덤이 있었고, 나뭇잎처럼 얇은 금제 관식과 옻칠한 나무 베개 등 4천 점이 넘는 유물이 나왔다. 무엇보다 왕의 이름을 새긴 지석이 있어, 주인이 확실한 유일한 백제 왕릉이 되었다. 바로 옆 언덕에는 금강을 내려다보며 흙과 돌로 쌓은 공산성의 성벽이 둥글게 이어진다.","facts":["1971년 온전한 상태로 발견되어 4,600여 점의 유물이 출토되었다.","주인이 확인된 유일한 백제 왕릉이다.","2015년 유네스코 세계유산 ''백제역사유적지구''에 포함되었다.","실제 무덤은 보존을 위해 폐쇄되었고 실물 크기 모형을 관람한다."],"travelTips":["국립공주박물관에서 무덤 출토 유물 원본을 볼 수 있다.","백제문화제는 9~10월 공주와 부여에서 열린다.","공산성 성벽 한 바퀴는 한 시간쯤 걸린다."],"bestTime":"9~10월(백제문화제)","visitDuration":"3시간","ticket":"1,500원(바로 옆 국립공주박물관은 무료)","openingHours":"09:00~18:00","galleryCaptions":["금강을 내려다보는 공산성 성벽"]},"ja":{"name":"公州 武寧王陵と公山城","summary":"被葬者の名が分かる唯一の百済王陵。1971年に無傷で見つかった。","story":"1971年、公州で排水溝を掘っていた作業員のシャベルがレンガの天井に当たった。中には盗掘を免れた百済・武寧王の墓があり、木の葉のように薄い金製冠飾りや漆塗りの木枕など四千点を超える遺物が出た。何より王の名を刻んだ誌石があり、被葬者が確実な唯一の百済王陵となった。すぐ隣の丘には、錦江を見下ろす公山城の土と石の城壁が円く連なる。","facts":["1971年に無傷で発見され、4,600点余りの遺物が出土した。","被葬者が確認された唯一の百済王陵。","2015年にユネスコ世界遺産「百済歴史遺跡地区」に含まれた。","実際の墓は保存のため閉鎖され、実物大の模型を見学する。"],"travelTips":["国立公州博物館で墓の出土品の原物を見られる。","百済文化祭は9〜10月に公州と扶余で開かれる。","公山城の城壁一周は一時間ほど。"],"bestTime":"9〜10月（百済文化祭）","visitDuration":"3時間","ticket":"1,500ウォン（隣の国立公州博物館は無料）","openingHours":"09:00〜18:00","galleryCaptions":["錦江を見下ろす公山城の城壁"]},"zh":{"name":"公州武寧王陵與公山城","summary":"唯一能確認墓主姓名的百濟王陵，1971年完好出土。","story":"1971年，公州挖排水溝的工人一鏟碰到了磚砌拱頂。裡面是百濟武寧王之墓，從未被盜，出土文物逾四千件：薄如樹葉的金製冠飾、髹漆木枕，以及一方刻著國王名號的誌石——正是它讓這裡成為唯一能確認墓主的百濟王陵。旁邊的山丘上，公山城的土石城牆環繞而行，俯瞰錦江。","facts":["1971年完整出土，共發現4,600餘件文物。","唯一確認墓主身分的百濟王陵。","屬2015年列入的世界遺產「百濟歷史遺跡地區」。","真墓已封閉保存，遊客參觀的是原尺寸復原模型。"],"travelTips":["到國立公州博物館可看到出自該墓的文物原件。","百濟文化節於九至十月在公州與扶餘舉行。","繞行公山城城牆一圈約需一小時。"],"bestTime":"9至10月（百濟文化節）","visitDuration":"3小時","ticket":"1,500韓元（隔壁的國立公州博物館免費）","openingHours":"09:00–18:00","galleryCaptions":["俯瞰錦江的公山城城牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('buyeo-busosanseong', 'buyeo-busosanseong', 'chungnam', 'Thành Busosanseong & Gungnamji (Buyeo)', 'Busosanseong Fortress & Gungnamji Pond', 'unesco', 126.9165, 36.2825, 'Kinh đô cuối cùng của Bách Tế, với vách đá bên sông và hồ vườn cổ nhất Hàn Quốc.', 'Buyeo là kinh đô cuối của vương quốc Bách Tế, và khi thành thất thủ năm 660, truyền thuyết kể ba nghìn cung nữ đã gieo mình xuống sông từ vách đá Nakhwaam — ''đá hoa rơi''. Đứng trên đó nhìn sông Baengma uốn khúc, rất khó tin nơi yên bình này từng là kết cục của một vương triều. Cách đó vài phút là Gungnamji, hồ vườn nhân tạo cổ nhất Hàn Quốc, đào năm 634, với đình bát giác giữa hồ và cả cánh đồng sen nở rộ vào tháng 7.', '["Thuộc Di sản Thế giới UNESCO ''Khu vực lịch sử Bách Tế''.","Hồ Gungnamji đào năm 634, là hồ vườn nhân tạo cổ nhất Hàn Quốc.","Vách đá Nakhwaam gắn với truyền thuyết cung nữ Bách Tế năm 660.","Lễ hội sen Buyeo tổ chức vào tháng 7 tại Gungnamji."]', '["Tháng 7 sen nở kín hồ Gungnamji — thời điểm đẹp nhất trong năm.","Có thuyền chạy trên sông Baengma ngay dưới chân vách Nakhwaam.","Kết hợp Gongju và Buyeo trong một ngày để đi trọn di sản Bách Tế."]', 'Tháng 7 (mùa sen) và tháng 9–10', '3 giờ', '2.000 KRW; giảm cho trẻ em, người cao tuổi và dân địa phương', '09:00–18:00', '["unesco"]', '["UNESCO","Bách Tế","hồ sen"]', '[{"seed":"buyeo-busosanseong","caption":"Đình giữa hồ Gungnamji","ratio":"16/9"}]', '["gongju-tomb"]', 0, 'https://www.chungnam.go.kr/cnportal/media/article/view.do?articleNo=MD0003262286', '2026-08-04', '{"en":{"name":"Busosanseong Fortress & Gungnamji Pond, Buyeo","summary":"Baekje''s last capital, with a river cliff and the oldest garden pond in Korea.","story":"Buyeo was the final capital of the Baekje kingdom, and when it fell in 660 legend says three thousand court women threw themselves from the cliff of Nakhwaam — ''the rock of falling flowers''. Standing there above the winding Baengma River, it is hard to believe this quiet place was the end of a dynasty. Minutes away lies Gungnamji, Korea''s oldest artificial garden pond, dug in 634, with an octagonal pavilion at its centre and a whole field of lotus in bloom in July.","facts":["Part of the UNESCO ''Baekje Historic Areas''.","Gungnamji, dug in 634, is the oldest artificial garden pond in Korea.","Nakhwaam cliff is tied to the legend of the Baekje court women in 660.","The Buyeo Lotus Festival is held at Gungnamji in July."],"travelTips":["July, when the lotus covers Gungnamji, is the finest time of year.","Boats run on the Baengma River below Nakhwaam.","Pair Gongju and Buyeo in one day to cover the Baekje heritage."],"bestTime":"July (lotus) and September–October","visitDuration":"3 hours","ticket":"2,000 KRW; discounts for children, seniors and local residents","openingHours":"09:00–18:00","galleryCaptions":["The pavilion at the centre of Gungnamji"]},"ko":{"name":"부여 부소산성과 궁남지","summary":"백제의 마지막 도읍. 강가 절벽과 한국에서 가장 오래된 정원 연못이 있다.","story":"부여는 백제의 마지막 도읍이었고, 660년 성이 함락되던 날 삼천 궁녀가 낙화암에서 몸을 던졌다는 이야기가 전한다. 굽이치는 백마강을 내려다보고 서면, 이 평온한 자리가 한 왕조의 결말이었다는 사실이 잘 믿기지 않는다. 몇 분 거리에는 634년에 판 한국에서 가장 오래된 인공 정원 연못 궁남지가 있다. 가운데 팔각 정자가 있고 7월이면 연꽃이 들판처럼 피어난다.","facts":["유네스코 세계유산 ''백제역사유적지구''에 속한다.","궁남지는 634년에 조성된 한국 최고(最古)의 인공 정원 연못이다.","낙화암은 660년 백제 궁녀 전설과 이어진다.","부여 서동연꽃축제가 7월 궁남지에서 열린다."],"travelTips":["궁남지에 연꽃이 가득한 7월이 일 년 중 가장 좋다.","낙화암 아래 백마강에서 유람선을 탈 수 있다.","공주와 부여를 하루에 묶으면 백제 유산을 모두 볼 수 있다."],"bestTime":"7월(연꽃), 9~10월","visitDuration":"3시간","ticket":"2,000원, 어린이·노인·지역주민 할인","openingHours":"09:00~18:00","galleryCaptions":["궁남지 가운데의 정자"]},"ja":{"name":"扶余 扶蘇山城と宮南池","summary":"百済最後の都。川辺の崖と韓国最古の庭園池がある。","story":"扶余は百済最後の都であり、660年に城が落ちた日、三千の宮女が落花岩から身を投げたという物語が伝わる。うねる白馬江を見下ろして立つと、この穏やかな場所が一つの王朝の結末だったとは信じにくい。数分の距離には634年に掘られた韓国最古の人工庭園池・宮南池がある。中央に八角の東屋があり、7月には蓮が野のように咲く。","facts":["ユネスコ世界遺産「百済歴史遺跡地区」に属する。","宮南池は634年造成の韓国最古の人工庭園池。","落花岩は660年の百済宮女の伝説と結びつく。","扶余薯童蓮祭りが7月に宮南池で開かれる。"],"travelTips":["宮南池が蓮で埋まる7月が一年で最も良い。","落花岩の下の白馬江で遊覧船に乗れる。","公州と扶余を一日で回れば百済の遺産を通して見られる。"],"bestTime":"7月（蓮）、9〜10月","visitDuration":"3時間","ticket":"2,000ウォン、子ども・高齢者・地元住民は割引","openingHours":"09:00〜18:00","galleryCaptions":["宮南池の中央に建つ東屋"]},"zh":{"name":"扶餘扶蘇山城與宮南池","summary":"百濟最後的都城，有臨江斷崖與韓國最古老的園林水池。","story":"扶餘是百濟王國最後的都城。660年城破之日，傳說三千宮女自落花岩投江。站在崖上望著蜿蜒的白馬江，很難相信這片寧靜之地曾是一個王朝的終局。幾分鐘車程外便是宮南池——韓國最古老的人工園林水池，開鑿於634年，池心有八角亭，七月時整片荷花盛放。","facts":["屬世界遺產「百濟歷史遺跡地區」。","宮南池開鑿於634年，是韓國最古老的人工園林水池。","落花岩與660年百濟宮女的傳說相連。","扶餘薯童蓮花節七月於宮南池舉行。"],"travelTips":["七月荷花鋪滿宮南池，是一年中最好的時節。","落花岩下的白馬江可搭乘遊船。","把公州與扶餘安排在同一天，可完整走過百濟遺產。"],"bestTime":"7月（荷花）與9至10月","visitDuration":"3小時","ticket":"2,000韓元；兒童、長者與在地居民有折扣","openingHours":"09:00–18:00","galleryCaptions":["宮南池中央的亭子"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('haemieupseong', 'haemieupseong', 'chungnam', 'Thành Haemi (Seosan)', 'Haemieupseong Walled Town', 'palace', 126.5495, 36.7045, 'Toà thành huyện còn nguyên vẹn bậc nhất Hàn Quốc, cũng là nơi hành hình các tín hữu Công giáo.', 'Haemieupseong là loại thành bao quanh cả một khu dân cư chứ không chỉ doanh trại, và là một trong ba toà thành huyện còn nguyên vẹn nhất nước: tường đá cao 5 mét chạy vòng gần hai cây số, bên trong là nha môn, kho lúa, nhà tranh và một cây hoè cổ thụ. Chính dưới gốc hoè đó, hàng nghìn tín hữu Công giáo bị hành hình vào thế kỷ 19 — Giáo hoàng Francis đã tới đây năm 2014. Ngày nay trong thành có các trò chơi dân gian và người mặc cổ phục làm nghề thủ công.', '["Xây trong giai đoạn 1417–1421, tường dài khoảng 1,8 km.","Là một trong những thành huyện (eupseong) còn nguyên vẹn nhất Hàn Quốc.","Là nơi tử đạo của nhiều tín hữu Công giáo thế kỷ 19.","Giáo hoàng Francis đến thăm năm 2014 nhân Đại hội Giới trẻ châu Á."]', '["Vào cửa miễn phí, mở tới tối và thành lên đèn rất đẹp.","Có các hoạt động trải nghiệm bắn cung, mặc cổ phục cho khách.","Kết hợp với chùa đá Maae Buddha ở Seosan gần đó."]', 'Tháng 4–6 và 9–11', '1,5–2 giờ', 'Miễn phí, kể cả bãi đỗ xe', '05:00–21:00 (tháng 3–10), 06:00–19:00 (tháng 11–2), mở quanh năm', '["hidden-gem"]', '["thành cổ","lịch sử","Công giáo"]', '[{"seed":"haemieupseong","caption":"Tường thành Haemi","ratio":"16/9"}]', '["gongju-tomb"]', 0, 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=ef24ef32-cdd3-42a8-8fcb-bee4afa4c458', '2026-08-04', '{"en":{"name":"Haemieupseong Walled Town, Seosan","summary":"One of Korea''s best-preserved county fortresses — and a place of Catholic martyrdom.","story":"Haemieupseong is the kind of fortress that enclosed a whole settlement rather than a garrison, and it is among the three best preserved in the country: five-metre stone walls running nearly two kilometres, with the magistrate''s office, granaries, thatched houses and an ancient zelkova tree inside. It was beneath that tree that thousands of Catholics were executed in the 19th century — Pope Francis came here in 2014. Today the grounds host folk games and costumed artisans at work.","facts":["Built between 1417 and 1421; the wall runs about 1.8 km.","One of the best-preserved walled county towns (eupseong) in Korea.","A site of 19th-century Catholic martyrdom.","Pope Francis visited in 2014 for Asian Youth Day."],"travelTips":["Entry is free and it stays open late, when the walls are lit.","Archery and costume experiences are offered to visitors.","Combine with the Seosan rock-carved Buddha triad nearby."],"bestTime":"April–June and September–November","visitDuration":"1.5–2 hours","ticket":"Free, including parking","openingHours":"05:00–21:00 (March–October), 06:00–19:00 (November–February), open year-round","galleryCaptions":["The walls of Haemi"]},"ko":{"name":"서산 해미읍성","summary":"가장 온전하게 남은 읍성 가운데 하나이자 천주교 순교의 자리.","story":"해미읍성은 군영이 아니라 마을 전체를 감싼 읍성으로, 한국에 남은 것 가운데 가장 온전한 축에 든다. 5m 높이의 돌담이 2km 가까이 이어지고 안에는 동헌과 곳간, 초가집, 그리고 오래된 회화나무가 있다. 바로 그 나무 아래에서 19세기에 수천 명의 천주교 신자가 처형되었다. 2014년에는 프란치스코 교황이 이곳을 찾았다. 지금은 성 안에서 민속놀이가 열리고 옛 복식을 입은 장인들이 일한다.","facts":["1417~1421년에 축조되었고 성벽 길이는 약 1.8km다.","한국에 남은 읍성 가운데 보존 상태가 가장 좋은 곳 중 하나다.","19세기 천주교 순교지다.","2014년 아시아청년대회를 계기로 프란치스코 교황이 방문했다."],"travelTips":["입장료가 없고 밤늦게까지 열려 조명이 켜진 성벽이 아름답다.","활쏘기와 전통복식 체험 프로그램이 있다.","인근 서산 마애여래삼존상과 함께 둘러보자."],"bestTime":"4~6월, 9~11월","visitDuration":"1시간 30분~2시간","ticket":"입장료와 주차 모두 무료","openingHours":"05:00~21:00(3~10월), 06:00~19:00(11~2월), 연중무휴","galleryCaptions":["해미읍성 성벽"]},"ja":{"name":"瑞山 海美邑城","summary":"最も原形をとどめる邑城のひとつであり、カトリック殉教の地。","story":"海美邑城は駐屯地ではなく集落全体を囲んだ邑城で、韓国に残るものの中でも保存状態が特に良い。高さ5mの石垣が2km近く続き、内には東軒や倉、藁葺きの家、そして古いエンジュの木がある。まさにその木の下で、19世紀に数千人のカトリック信者が処刑された。2014年には教皇フランシスコがここを訪れている。今では城内で民俗遊びが催され、古い装束の職人が働いている。","facts":["1417〜1421年に築かれ、城壁の長さは約1.8km。","韓国に残る邑城の中でも保存状態が最良の部類。","19世紀のカトリック殉教地である。","2014年、アジア青年大会を機に教皇フランシスコが訪れた。"],"travelTips":["入場無料で夜遅くまで開いており、照明の入った城壁が美しい。","弓射や伝統衣装の体験プログラムがある。","近くの瑞山磨崖三尊仏と合わせて回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1時間30分〜2時間","ticket":"入場も駐車も無料","openingHours":"05:00〜21:00（3〜10月）、06:00〜19:00（11〜2月）、年中無休","galleryCaptions":["海美邑城の城壁"]},"zh":{"name":"瑞山海美邑城","summary":"韓國保存最完整的縣城之一，也是天主教殉道之地。","story":"海美邑城屬於環抱整座聚落而非僅駐軍的邑城，是韓國保存最完好的三座之一：五公尺高的石牆綿延近兩公里，城內有衙門、糧倉、茅屋，以及一株古槐。正是在那株樹下，十九世紀有數千名天主教徒被處決——2014年教宗方濟各曾親臨此地。如今城內有民俗遊戲，也有身著古裝的工匠在勞作。","facts":["建於1417至1421年，城牆長約1.8公里。","是韓國保存最完整的邑城之一。","十九世紀天主教殉道地。","2014年教宗方濟各因亞洲青年節到訪。"],"travelTips":["免費入場且開放至夜間，打燈的城牆很美。","設有射箭與古裝體驗活動。","可與附近的瑞山磨崖三尊佛一併參觀。"],"bestTime":"4至6月、9至11月","visitDuration":"1.5至2小時","ticket":"入場與停車皆免費","openingHours":"05:00–21:00（3至10月）、06:00–19:00（11至2月），全年開放","galleryCaptions":["海美邑城城牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daecheon-beach', 'daecheon-beach', 'chungnam', 'Bãi biển Daecheon (Boryeong)', 'Daecheon Beach, Boryeong', 'beach', 126.5115, 36.3175, 'Bãi biển tây dài 3,5 km, mỗi tháng 7 thành sân chơi của lễ hội bùn Boryeong.', 'Bùn ở vịnh Boryeong giàu khoáng đến mức được dùng làm mỹ phẩm, và năm 1998 tỉnh nghĩ ra cách quảng bá: đổ bùn ra bãi biển rồi mời tất cả cùng nghịch. Lễ hội bùn Boryeong nay là một trong những sự kiện hè thu hút khách nước ngoài nhất Hàn Quốc — bể trượt bùn, đấu vật bùn, tắm bùn, nhạc sống tới khuya, ai cũng lấm lem như nhau. Ngoài mùa lễ hội, Daecheon là bãi biển bình thường với hoàng hôn rất đẹp vì quay mặt về hướng tây.', '["Bãi dài khoảng 3,5 km, là bãi tắm lớn nhất bờ biển phía tây.","Lễ hội bùn Boryeong tổ chức vào tháng 7 từ năm 1998.","Bùn Boryeong giàu khoáng chất, được dùng sản xuất mỹ phẩm.","Bờ tây nên đây là bãi biển ngắm hoàng hôn."]', '["Mùa lễ hội bùn phải đặt phòng trước hàng tháng.","Mang quần áo cũ và túi chống nước cho điện thoại.","Ngoài mùa hè, bãi rất vắng và yên tĩnh."]', 'Tháng 7 (lễ hội bùn), tháng 6–8 (tắm biển)', 'Nửa ngày', '', 'Cả ngày', '["festival","trending"]', '["biển","lễ hội","hoàng hôn"]', '[{"seed":"daecheon-beach","caption":"Lễ hội bùn trên bãi Daecheon","ratio":"16/9"}]', '["haemieupseong"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Daecheon Beach, Boryeong","summary":"A 3.5 km west-coast beach that turns every July into the playground of the Boryeong Mud Festival.","story":"The mud of Boryeong bay is so rich in minerals that it is used in cosmetics, and in 1998 the province found a way to advertise it: spread it over the beach and invite everyone to play. The Boryeong Mud Festival is now one of the summer events that draws the most foreign visitors in Korea — mud slides, mud wrestling, mud baths and live music until late, everyone equally filthy. Outside festival season Daecheon is an ordinary beach with a very good sunset, because it faces west.","facts":["The beach runs about 3.5 km, the largest on the west coast.","The Boryeong Mud Festival has been held each July since 1998.","Boryeong mud is mineral-rich and used in cosmetics.","Facing west, this is a sunset beach."],"travelTips":["Book accommodation months ahead for the mud festival.","Bring old clothes and a waterproof pouch for your phone.","Outside summer the beach is very quiet."],"bestTime":"July (mud festival), June–August (swimming)","visitDuration":"Half a day","ticket":"","openingHours":"All day","galleryCaptions":["The mud festival on Daecheon beach"]},"ko":{"name":"보령 대천해수욕장","summary":"3.5km의 서해안 백사장. 7월이면 보령머드축제의 무대가 된다.","story":"보령 앞바다의 갯벌 진흙은 화장품 원료로 쓸 만큼 미네랄이 풍부하다. 1998년 충청남도는 이를 알리는 방법을 찾아냈다. 진흙을 해변에 퍼놓고 모두 함께 놀게 한 것이다. 보령머드축제는 이제 한국에서 외국인이 가장 많이 찾는 여름 행사가 되었다. 머드 슬라이드와 머드 씨름, 진흙탕 목욕, 늦은 밤까지 이어지는 공연 속에서 모두가 똑같이 지저분해진다. 축제철이 아니면 대천은 평범한 해변이지만, 서쪽을 향해 있어 노을이 아주 좋다.","facts":["해변 길이는 약 3.5km로 서해안에서 가장 크다.","보령머드축제는 1998년부터 매년 7월에 열린다.","보령 머드는 미네랄이 풍부해 화장품에 쓰인다.","서쪽을 바라보고 있어 일몰 해변이다."],"travelTips":["머드축제 기간에는 숙소를 몇 달 전에 예약해야 한다.","낡은 옷과 휴대폰 방수팩을 챙기자.","여름을 제외하면 해변은 매우 한적하다."],"bestTime":"7월(머드축제), 6~8월(해수욕)","visitDuration":"반나절","ticket":"","openingHours":"상시","galleryCaptions":["대천해변의 머드축제"]},"ja":{"name":"保寧 大川海水浴場","summary":"3.5kmの西海岸の砂浜。7月には保寧マッドフェスティバルの舞台になる。","story":"保寧沖の泥は化粧品の原料になるほどミネラルが豊富だ。1998年、忠清南道はそれを知らせる方法を思いついた。泥を浜にまいて皆で遊ばせたのである。保寧マッドフェスティバルは今や韓国で最も外国人が集まる夏の行事になった。泥のすべり台、泥相撲、泥風呂、深夜まで続くライブ。誰もが等しく泥だらけになる。祭りの時期を外せば大川はふつうの浜だが、西を向いているので夕日がとても良い。","facts":["砂浜の長さは約3.5kmで西海岸最大。","保寧マッドフェスティバルは1998年から毎年7月に開かれる。","保寧の泥はミネラルが豊富で化粧品に使われる。","西向きのため夕日の浜である。"],"travelTips":["マッドフェスティバル期間の宿は数か月前に予約を。","古い服とスマホの防水ポーチを用意しよう。","夏を除けば浜はとても静かだ。"],"bestTime":"7月（泥祭り）、6〜8月（海水浴）","visitDuration":"半日","ticket":"","openingHours":"終日","galleryCaptions":["大川海水浴場の泥祭り"]},"zh":{"name":"保寧大川海水浴場","summary":"西海岸3.5公里長的沙灘，每年七月成為保寧泥漿節的舞台。","story":"保寧灣的泥漿礦物質豐富到能做化妝品原料，1998年忠清南道想出了宣傳方式：把泥鋪到沙灘上，請大家一起玩。保寧泥漿節如今是韓國最吸引外國旅客的夏日活動之一——泥滑梯、泥漿摔角、泥浴，加上通宵的現場音樂，人人一樣髒。非節慶期間，大川就是一片普通海灘，但因為面向西方，落日極美。","facts":["沙灘長約3.5公里，是西海岸最大的一處。","保寧泥漿節自1998年起每年七月舉行。","保寧泥漿礦物質豐富，用於化妝品製造。","面向西方，是看日落的海灘。"],"travelTips":["泥漿節期間住宿需提前數月預訂。","帶舊衣服與手機防水袋。","夏季以外，海灘非常安靜。"],"bestTime":"7月（泥漿節）、6至8月（戲水）","visitDuration":"半天","ticket":"","openingHours":"全日","galleryCaptions":["大川海灘上的泥漿節"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sudeoksa', 'sudeoksa', 'chungnam', 'Chùa Sudeoksa', 'Sudeoksa Temple', 'temple', 126.6185, 36.6675, 'Chính điện dựng năm 1308 với niên đại khắc ngay trên xà, hiếm có ở kiến trúc gỗ Hàn Quốc.', 'Phần lớn công trình gỗ cổ Hàn Quốc chỉ được đoán niên đại; Daeungjeon của Sudeoksa thì không cần đoán — khi tháo ra tu bổ năm 1937, người ta tìm thấy dòng mực ghi rõ năm 1308 trên xà nóc. Nhờ vậy nó thành cột mốc để đối chiếu mọi kiến trúc gỗ khác của Hàn Quốc. Điện này không sơn màu, chỉ để mộc, và cấu trúc đỡ mái lộ hết ra ngoài như một bản vẽ kỹ thuật dựng đứng. Chùa nằm dưới núi Deoksungsan, và trên sườn núi có Jeonghyesa — am thiền nơi ni sư Iryeop, một nhà văn nữ nổi tiếng đầu thế kỷ 20, xuất gia và sống nốt phần đời còn lại.', '["Chính điện Daeungjeon dựng năm 1308, có ghi niên đại bằng mực trên xà nóc.","Là quốc bảo số 49, một trong những công trình gỗ cổ nhất Hàn Quốc.","Điện để mộc không sơn, kết cấu đỡ mái lộ ra ngoài.","Trên núi có am Jeonghyesa nơi ni sư Iryeop tu hành."]', '["Đi lên am Jeonghyesa mất khoảng 40 phút leo dốc, cảnh nhìn ra rất đáng.","Có templestay cuối tuần cho khách nước ngoài.","Kết hợp với Haemieupseong cách đó khoảng 30 phút xe."]', 'Tháng 4–6 và 10–11', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["verified","hidden-gem"]', '["chùa","quốc bảo","kiến trúc gỗ","thiền"]', '[{"seed":"sudeoksa","caption":"Chính điện Daeungjeon để mộc","ratio":"16/9"}]', '["haemieupseong"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Sudeoksa Temple","summary":"A main hall built in 1308 with the date inked onto the ridge beam — a rarity in Korean timber architecture.","story":"Most old Korean timber buildings can only be dated by inference; Sudeoksa''s Daeungjeon does not need it. When it was dismantled for repair in 1937, an ink inscription giving the year 1308 was found on the ridge beam. That made it the reference point against which every other Korean timber building is measured. The hall is left unpainted, and the whole bracket system carrying the roof is exposed like a standing technical drawing. The temple sits below Deoksungsan, and up the slope is Jeonghyesa, the hermitage where Iryeop — a well-known woman writer of the early 20th century — took vows and lived out her life.","facts":["Daeungjeon hall was built in 1308, with the date inked on the ridge beam.","National Treasure No. 49 and among Korea''s oldest timber buildings.","The hall is unpainted, with the roof bracketing left exposed.","Jeonghyesa hermitage up the mountain is where the nun Iryeop practised."],"travelTips":["The climb to Jeonghyesa takes about 40 minutes and the view is worth it.","Weekend templestays are offered for foreign visitors.","Combine it with Haemieupseong, about 30 minutes away by car."],"bestTime":"April–June and October–November","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["The unpainted Daeungjeon hall"]},"ko":{"name":"수덕사","summary":"1308년에 지은 대웅전. 종도리에 연대가 먹으로 적혀 있는, 한국 목조건축에서 드문 경우다.","story":"한국의 오래된 목조 건물은 대개 연대를 추정할 뿐이지만, 수덕사 대웅전은 그럴 필요가 없다. 1937년 해체 수리 때 종도리에서 1308년을 적은 묵서가 나왔기 때문이다. 그래서 이 건물은 다른 모든 한국 목조건축을 견주는 기준이 되었다. 대웅전은 단청을 하지 않아 나뭇결이 그대로이고, 지붕을 받치는 공포가 전부 드러나 세워 놓은 도면 같다. 절은 덕숭산 아래에 있고, 산비탈에는 정혜사가 있다. 20세기 초의 이름난 여성 문인 일엽 스님이 출가해 남은 생을 보낸 암자다.","facts":["대웅전은 1308년에 지어졌고 종도리에 연대가 묵서로 남아 있다.","국보 제49호이며 한국에서 가장 오래된 목조건축에 든다.","단청을 하지 않아 공포 구조가 그대로 드러난다.","산 위의 정혜사는 일엽 스님이 수행한 암자다."],"travelTips":["정혜사까지는 40분쯤 오르막이지만 전망이 값을 한다.","외국인을 위한 주말 템플스테이가 있다.","차로 30분 거리의 해미읍성과 묶어서 보자."],"bestTime":"4~6월, 10~11월","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["단청하지 않은 대웅전"]},"ja":{"name":"修徳寺","summary":"1308年建立の大雄殿。棟木に年代が墨書されている、韓国木造建築では稀な例だ。","story":"韓国の古い木造建築は多くが年代を推定するしかないが、修徳寺の大雄殿はその必要がない。1937年の解体修理のとき、棟木に1308年と記した墨書が見つかったからだ。おかげでこの建物は、他のすべての韓国木造建築を測る基準になった。堂は彩色されず木肌のままで、屋根を支える組物がすべて露わになり、立てた設計図のようだ。寺は徳崇山の麓にあり、斜面には定慧寺がある。二十世紀初頭の名高い女性文人・一葉尼が出家し、残る生涯を過ごした庵である。","facts":["大雄殿は1308年建立で、棟木に年代の墨書が残る。","国宝第49号であり、韓国最古級の木造建築である。","彩色されず、屋根の組物がそのまま露出している。","山上の定慧寺は一葉尼が修行した庵である。"],"travelTips":["定慧寺までは40分ほどの上りだが、眺めが報いてくれる。","外国人向けの週末テンプルステイがある。","車で30分の海美邑城と合わせて回ろう。"],"bestTime":"4〜6月、10〜11月","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["彩色されていない大雄殿"]},"zh":{"name":"修德寺","summary":"1308年落成的大雄殿，年代直接以墨書寫在脊樑上——這在韓國木造建築裡相當罕見。","story":"韓國多數古老木造建築只能靠推斷定年，修德寺的大雄殿卻不必：1937年拆卸整修時，人們在脊樑上找到墨書寫下的1308年。於是這棟建築成了衡量其他所有韓國木構的基準。這座殿不上彩，木紋全露，支撐屋頂的斗栱毫無遮掩地攤在外面，像一張立起來的施工圖。寺院坐落在德崇山下，山坡上還有定慧寺——20世紀初知名女作家一葉尼師出家、並在此度過餘生的庵堂。","facts":["大雄殿建於1308年，脊樑上留有墨書年代。","為國寶第49號，屬韓國最古老的木造建築之列。","殿身不施彩繪，斗栱結構完全外露。","山上的定慧寺是一葉尼師修行的庵堂。"],"travelTips":["上定慧寺約需40分鐘爬坡，但視野值得。","設有供外國訪客參加的週末寺廟寄宿。","可與車程約30分鐘的海美邑城排在一起。"],"bestTime":"4至6月與10至11月","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["不施彩繪的大雄殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sinduri-dunes', 'sinduri-dunes', 'chungnam', 'Cồn cát Sinduri (Taean)', 'Sinduri Coastal Dunes, Taean', 'beach', 126.1795, 36.8145, 'Đồi cát ven biển lớn nhất Hàn Quốc, gió bồi suốt mười lăm nghìn năm thành một mảnh sa mạc nhỏ.', 'Sinduri là hệ cồn cát ven biển lớn nhất Hàn Quốc — cát từ bãi biển được gió tây bắc thổi ngược vào bờ suốt mười lăm nghìn năm, đắp thành những đồi cao tới hai chục mét chạy dài gần bốn cây số. Đứng giữa đó, xung quanh chỉ có cát và cỏ lau biển, rất khó tin mình vẫn đang ở Hàn Quốc. Đây là nơi sống của nhiều loài chỉ có ở cồn cát: cỏ đưng, bọ hung cát, thằn lằn cát. Lối đi bằng gỗ dẫn qua vùng lõi để không giẫm lên hệ sinh thái, và có một hồ nước ngọt nhỏ hình thành ngay sau đồi cát — chuyện hiếm gặp trong địa mạo cồn cát.', '["Là hệ cồn cát ven biển lớn nhất Hàn Quốc, được công nhận là Đài kỷ niệm thiên nhiên số 431.","Cồn cát hình thành qua khoảng 15.000 năm gió bồi.","Vùng cồn kéo dài gần 4 km với các đồi cao tới khoảng 20m.","Có hồ nước ngọt Duung nằm ngay sau dải cồn cát."]', '["Đi theo lối gỗ, không bước xuống cát trong vùng lõi bảo tồn.","Gió rất mạnh — mang kính râm để tránh cát bay vào mắt.","Kết hợp với các bãi biển Taean và công viên quốc gia biển Taeanhaean."]', 'Tháng 4–6 và 9–10', '2 giờ', 'Miễn phí', '09:00–18:00 (tháng 11–2 tới 17:00), đóng cửa thứ Hai', '["hidden-gem"]', '["cồn cát","sinh thái","biển","địa mạo"]', '[{"seed":"sinduri-dunes","caption":"Đồi cát ven biển Sinduri","ratio":"16/9"}]', '["daecheon-beach"]', 0, 'https://korean.visitkorea.or.kr/detail/rem_detail.do?cotid=0441ddca-b215-45de-a159-eddbb9624123', '2026-08-05', '{"en":{"name":"Sinduri Coastal Dunes, Taean","summary":"Korea''s largest coastal dune field, built by wind over fifteen thousand years into a small desert.","story":"Sinduri is the largest coastal dune system in Korea — sand blown back inland off the beach by the north-west wind over some fifteen thousand years, heaped into hills up to twenty metres high running nearly four kilometres. Standing in the middle of it, with nothing but sand and marram grass around you, it is hard to believe you are still in Korea. It shelters species found only on dunes: sand sedge, dune beetles, sand lizards. A boardwalk crosses the core so nobody treads on the ecosystem, and a small freshwater lake sits just behind the dunes — an unusual thing in dune geomorphology.","facts":["Korea''s largest coastal dune system, designated Natural Monument No. 431.","The dunes formed over roughly 15,000 years of wind deposition.","The field runs nearly 4km with hills up to about 20m high.","Duung freshwater lake lies immediately behind the dune belt."],"travelTips":["Stay on the boardwalk; do not step onto the sand in the protected core.","The wind is fierce — bring sunglasses to keep sand out of your eyes.","Combine it with the Taean beaches and Taeanhaean Marine National Park."],"bestTime":"April–June and September–October","visitDuration":"2 hours","ticket":"Free","openingHours":"09:00–18:00 (to 17:00 from November to February), closed Mondays","galleryCaptions":["The coastal dunes at Sinduri"]},"ko":{"name":"태안 신두리 해안사구","summary":"한국 최대의 해안 사구. 만오천 년 동안 바람이 쌓아 만든 작은 사막이다.","story":"신두리는 한국에서 가장 큰 해안 사구다. 북서풍이 해변의 모래를 뭍 쪽으로 되불어 만오천 년쯤 쌓아 올린 것으로, 높이 20m에 이르는 언덕이 4km 가까이 이어진다. 그 한가운데 서면 모래와 통보리사초뿐이라 여기가 한국이라는 사실이 잘 믿기지 않는다. 사구에서만 사는 종들의 서식지이기도 하다. 통보리사초, 표범장지뱀, 사구의 딱정벌레들. 핵심 구역에는 나무 데크를 놓아 생태계를 밟지 않게 했고, 사구 바로 뒤에는 두웅습지라는 담수호가 있다. 사구 지형에서는 드문 일이다.","facts":["한국 최대의 해안 사구로 천연기념물 제431호다.","약 1만 5천 년에 걸친 바람의 퇴적으로 형성되었다.","사구 지대는 4km 가까이 이어지고 언덕 높이는 20m에 이른다.","사구 바로 뒤에 담수호인 두웅습지가 있다."],"travelTips":["데크를 따라 걷고 핵심 보호구역의 모래는 밟지 말자.","바람이 매우 세다. 모래가 눈에 들어가니 선글라스를 챙기자.","태안의 해수욕장, 태안해안국립공원과 묶어서 보자."],"bestTime":"4~6월, 9~10월","visitDuration":"2시간","ticket":"무료","openingHours":"09:00~18:00(11~2월은 17:00까지), 월요일 휴관","galleryCaptions":["신두리의 해안 사구"]},"ja":{"name":"泰安新斗里海岸砂丘","summary":"韓国最大の海岸砂丘。一万五千年をかけて風が積み上げた小さな砂漠だ。","story":"新斗里は韓国で最も大きな海岸砂丘だ。北西の風が浜の砂を陸へ吹き戻し、一万五千年ほどかけて高さ二十メートルに及ぶ丘を、四キロ近くにわたって積み上げた。その真ん中に立つと、周りは砂とコウボウムギばかりで、ここが韓国だとは信じにくい。砂丘にしか棲まない種の生息地でもある。コウボウムギ、砂丘の甲虫、カナヘビ。中心部には木道を敷いて生態系を踏まないようにしてあり、砂丘のすぐ裏には斗雄湿地という淡水の池がある。砂丘地形では珍しいことだ。","facts":["韓国最大の海岸砂丘で、天然記念物第431号である。","およそ1万5千年に及ぶ風の堆積で形成された。","砂丘帯は4km近く続き、丘の高さは約20mに達する。","砂丘の背後に淡水の斗雄湿地がある。"],"travelTips":["木道を歩き、保護中心部の砂には踏み込まないこと。","風が強い。砂が目に入るのでサングラスを持とう。","泰安の海水浴場や泰安海岸国立公園と合わせて回ろう。"],"bestTime":"4〜6月、9〜10月","visitDuration":"2時間","ticket":"無料","openingHours":"09:00〜18:00（11〜2月は17:00まで）、月曜休館","galleryCaptions":["新斗里の海岸砂丘"]},"zh":{"name":"泰安新斗里海岸沙丘","summary":"韓國最大的海岸沙丘，風花了一萬五千年堆出這片小沙漠。","story":"新斗里是韓國最大的海岸沙丘系統——西北風把海灘的沙往內陸回吹，歷經約一萬五千年堆成高達二十公尺的沙丘，綿延近四公里。站在其中，四周只有沙與濱麥，很難相信自己還在韓國。這裡也是只在沙丘生存的物種的棲地：濱麥、沙丘甲蟲、沙蜥。核心區鋪了木棧道，避免有人踩進生態系；沙丘正後方還有一座淡水的斗雄濕地——在沙丘地形中相當少見。","facts":["韓國最大的海岸沙丘系統，為天然紀念物第431號。","沙丘由約一萬五千年的風力堆積而成。","沙丘帶綿延近4公里，丘高可達約20公尺。","沙丘後方緊鄰淡水的斗雄濕地。"],"travelTips":["請走木棧道，勿踏入核心保護區的沙地。","風勢很強，戴太陽眼鏡以免沙子入眼。","可與泰安的海水浴場及泰安海岸國立公園一併安排。"],"bestTime":"4至6月與9至10月","visitDuration":"2小時","ticket":"免費","openingHours":"09:00–18:00（11至2月至17:00），週一休館","galleryCaptions":["新斗里的海岸沙丘"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('oeam-folk-village', 'oeam-folk-village', 'chungnam', 'Làng cổ Oeam (Asan)', 'Oeam Folk Village, Asan', 'village', 126.9915, 36.7735, 'Làng dòng họ sáu trăm tuổi có hệ mương nước chạy qua từng sân nhà, dẫn từ chân núi vào.', 'Oeam là làng của dòng họ Yi xứ Yean, hình thành từ thế kỷ 16 và giữ gần như nguyên vẹn cách bố trí ngày ấy. Điểm đặc biệt là nước: người trong làng dẫn một dòng suối từ núi Seolhwasan chảy vào, rồi chia thành mương nhỏ len qua sân từng nhà — vừa để tưới vườn, vừa để phòng hoả hoạn, vừa làm mát mùa hè. Bạn đi trên đường làng và luôn nghe tiếng nước chảy bên chân tường đá. Trong làng còn Konggansa, ngôi nhà quan lại có khu vườn Nho giáo với hồ vuông đảo tròn. Khoảng sáu chục hộ vẫn sinh sống, nhiều nhà làm rượu gạo yeonyeopju theo lối cũ.', '["Làng hình thành từ thế kỷ 16, là làng dòng họ Yi xứ Yean.","Có hệ mương dẫn nước từ núi Seolhwasan chạy qua sân từng nhà.","Khoảng 60 hộ gia đình vẫn sinh sống trong làng.","Rượu gạo yeonyeopju của làng được công nhận là di sản phi vật thể địa phương."]', '["Đi bộ men theo mương nước — đó là điểm hay nhất của làng.","Đây là làng có người ở; chỉ vào các nhà mở cửa cho khách.","Kết hợp với suối nước nóng Asan gần đó."]', 'Tháng 4–6 và 9–11', '1,5–2 giờ', '2.000 KRW (đoàn 1.000)', '09:00–18:00', '["hidden-gem"]', '["làng cổ","mương nước","dòng họ","rượu gạo"]', '[{"seed":"oeam-folk-village","caption":"Mương nước chạy qua sân nhà làng Oeam","ratio":"16/9"}]', '["gongju-tomb"]', 0, 'http://www.oeam.co.kr/main/index.php?m_cd=31', '2026-08-04', '{"en":{"name":"Oeam Folk Village, Asan","summary":"A six-hundred-year-old clan village with a channel of mountain water running through every yard.","story":"Oeam belongs to the Yi clan of Yean, formed in the 16th century and holding almost exactly the layout of that time. What sets it apart is the water: the villagers led a stream down from Seolhwasan and split it into small channels running through each house''s yard — to water the gardens, to guard against fire, and to cool the summer. You walk the village lanes and hear running water beside the stone walls the whole way. The village also holds Konggansa, a gentry house with a Confucian garden of square pond and round island. Around sixty households still live here, several making yeonyeopju rice wine the old way.","facts":["The village formed in the 16th century and belongs to the Yi clan of Yean.","A channel system carries water from Seolhwasan through each house''s yard.","About 60 households still live in the village.","The village''s yeonyeopju rice wine is a recognised local intangible heritage."],"travelTips":["Walk along the water channels — that is the best of the village.","People live here; only enter houses opened to visitors.","Combine it with the Asan hot springs nearby."],"bestTime":"April–June and September–November","visitDuration":"1.5–2 hours","ticket":"2,000 KRW (1,000 for groups)","openingHours":"09:00–18:00","galleryCaptions":["A water channel running through an Oeam yard"]},"ko":{"name":"아산 외암마을","summary":"육백 년 된 반촌. 산에서 끌어온 물길이 집집마다 마당을 지난다.","story":"외암마을은 예안 이씨의 마을로 16세기에 이루어졌고 그때의 배치를 거의 그대로 지니고 있다. 특별한 것은 물이다. 마을 사람들은 설화산에서 물길을 끌어와 잘게 나누어 집집마다 마당을 지나게 했다. 텃밭에 물을 대고, 불을 막고, 여름을 식히기 위해서다. 마을 길을 걸으면 돌담 옆으로 내내 물소리가 따라온다. 마을에는 네모난 연못과 둥근 섬을 갖춘 유교식 정원이 있는 반가 건재고택도 있다. 지금도 예순 가구쯤이 살고, 여러 집이 옛 방식으로 연엽주를 빚는다.","facts":["16세기에 이루어진 예안 이씨의 반촌이다.","설화산에서 끌어온 물길이 집집마다 마당을 지난다.","지금도 60가구쯤이 마을에 산다.","마을의 연엽주는 지역 무형유산으로 지정되어 있다."],"travelTips":["물길을 따라 걷는 것이 이 마을의 백미다.","사람이 사는 곳이다. 개방한 집에만 들어가자.","가까운 아산 온천과 묶어서 보자."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5~2시간","ticket":"2,000원(단체 1,000원)","openingHours":"09:00~18:00","galleryCaptions":["외암마을 마당을 지나는 물길"]},"ja":{"name":"牙山外岩村","summary":"六百年の同族村。山から引いた水路が家ごとの庭を通る。","story":"外岩村は礼安李氏の村で、十六世紀に成り、その頃の配置をほぼそのまま保っている。特別なのは水だ。村人は雪華山から流れを引き、細く分けて家ごとの庭を通した。畑に水をやり、火を防ぎ、夏を涼しくするためである。村の道を歩けば、石垣の脇をずっと水の音がついてくる。村には四角い池と丸い島を持つ儒教式の庭を備えた両班の家、建材古宅もある。いまも六十戸ほどが暮らし、いくつかの家が昔ながらのやり方で蓮葉酒を醸している。","facts":["十六世紀に成立した礼安李氏の同族村である。","雪華山から引いた水路が家ごとの庭を通る。","いまも約60世帯が村に暮らす。","村の蓮葉酒は地域の無形遺産に指定されている。"],"travelTips":["水路に沿って歩くのがこの村の白眉だ。","人が暮らしている。公開されている家にだけ入ろう。","近くの牙山温泉と合わせて回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1.5〜2時間","ticket":"2,000ウォン（団体1,000）","openingHours":"09:00〜18:00","galleryCaptions":["外岩村の庭を通る水路"]},"zh":{"name":"牙山外岩村","summary":"六百年的宗族村落，一道自山上引來的水渠流經每一戶人家的院子。","story":"外岩村屬禮安李氏，成形於16世紀，至今幾乎維持著當時的配置。真正特別的是水：村民自雪華山引來一股溪流，再分成細渠穿過每戶人家的院子——既澆菜園，也防火災，還替夏天降溫。走在村巷裡，石牆邊一路都有水聲相隨。村裡還有建材古宅，一座備有方池圓島儒式庭園的士族宅第。如今仍有約六十戶人家在此生活，好幾戶依舊按古法釀造蓮葉酒。","facts":["村落成形於16世紀，屬禮安李氏的宗族村。","自雪華山引來的水渠流經每戶人家的院子。","至今仍有約60戶人家居住。","村中的蓮葉酒被列為地方無形遺產。"],"travelTips":["沿著水渠慢走，那是這座村子最精采的部分。","這裡有人居住，只進入對外開放的宅第。","可與鄰近的牙山溫泉排在一起。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5至2小時","ticket":"2,000韓元（團體1,000）","openingHours":"09:00–18:00","galleryCaptions":["流經外岩村院落的水渠"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('magoksa', 'magoksa', 'chungnam', 'Chùa Magoksa (Gongju)', 'Magoksa Temple, Gongju', 'unesco', 127.0135, 36.5535, 'Ngôi chùa nằm trong khúc uốn của dòng suối, chia làm hai nửa bởi chính dòng nước ấy.', 'Magoksa được dựng ở đúng chỗ một con suối uốn gần thành vòng, và chùa nằm hai bên bờ nối bằng một cây cầu nhỏ — bờ bắc là khu tu học, bờ nam là khu điện thờ, và bạn phải qua cầu để đi từ đời sống hằng ngày sang không gian lễ bái. Địa thế này được coi là cát tường đến mức sách phong thuỷ cổ xếp Magoksa vào số nơi tránh được tai ương. Trong sân có tháp đá năm tầng mang chóp kim loại kiểu Tây Tạng, dấu vết giao lưu thời Nguyên. Chí sĩ Kim Gu từng lánh nạn và xuất gia ở đây sau khi giết một sĩ quan Nhật, và cây bách ông trồng vẫn còn.', '["Được UNESCO ghi danh năm 2018 trong cụm ''Sansa, chùa núi Hàn Quốc''.","Chùa chia làm hai khu hai bên suối, nối bằng cầu.","Tháp đá năm tầng có chóp kim loại mang ảnh hưởng Tây Tạng thời Nguyên.","Chí sĩ Kim Gu từng xuất gia tại đây; cây bách ông trồng vẫn còn trong sân."]', '["Đường mòn quanh chùa ''Baekbeom Myeongsang-gil'' đi bộ mất khoảng 1 giờ.","Mùa xuân hoa anh đào dọc suối, mùa thu lá đỏ — cả hai đều đẹp.","Từ ga Gongju đi bus khoảng 40 phút."]', 'Tháng 4 (hoa anh đào) và tháng 10–11', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["unesco","hidden-gem"]', '["UNESCO","chùa","suối","lịch sử"]', '[{"seed":"magoksa","caption":"Cầu nối hai bờ suối trong chùa Magoksa","ratio":"16/9"}]', '["gongju-tomb","sudeoksa"]', 0, 'https://www.cctoday.co.kr/news/articleView.html?idxno=2177268', '2026-08-04', '{"en":{"name":"Magoksa Temple, Gongju","summary":"A temple set in the bend of a stream, and split in two by that same water.","story":"Magoksa was built exactly where a stream loops almost into a circle, and the temple sits on both banks joined by a small bridge — the north bank for study and living, the south for the halls of worship, so you cross the water to pass from daily life into ritual space. The siting was held to be so auspicious that old geomancy texts list Magoksa among the places spared from calamity. In the courtyard stands a five-storey stone pagoda with a Tibetan-style metal finial, a trace of exchange under the Yuan. The independence leader Kim Gu hid here and took vows after killing a Japanese officer, and the cypress he planted still stands.","facts":["Inscribed by UNESCO in 2018 as part of the Sansa mountain monasteries.","The temple is divided across two banks of a stream, linked by a bridge.","Its five-storey stone pagoda has a Tibetan-influenced metal finial from the Yuan period.","Kim Gu took vows here; the cypress he planted still stands in the courtyard."],"travelTips":["The Baekbeom Myeongsang-gil path around the temple takes about an hour.","Cherry blossom along the stream in spring, red leaves in autumn — both are good.","It is about 40 minutes by bus from Gongju station."],"bestTime":"April (cherry blossom) and October–November","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["The bridge joining the two banks at Magoksa"]},"ko":{"name":"공주 마곡사","summary":"개울이 크게 휘도는 자리에 앉은 절. 그 물이 절을 둘로 나눈다.","story":"마곡사는 개울이 거의 원을 그리며 휘도는 바로 그 자리에 지어졌고, 절은 양쪽 기슭에 나뉘어 작은 다리로 이어진다. 북쪽은 수행과 생활의 영역, 남쪽은 예불의 영역이라, 물을 건너야 일상에서 의례의 공간으로 넘어간다. 이 자리는 매우 길하다고 여겨져 옛 풍수서는 마곡사를 재난을 피하는 곳으로 꼽았다. 마당에는 원나라 때의 교류를 보여 주는 티베트식 금속 상륜부를 얹은 오층석탑이 있다. 김구는 일본군 장교를 죽인 뒤 이곳에 숨어 출가했고, 그가 심은 향나무가 아직 남아 있다.","facts":["2018년 ''산사, 한국의 산지 승원''으로 유네스코에 등재되었다.","절이 개울 양쪽으로 나뉘어 다리로 이어진다.","오층석탑에는 원나라의 영향을 받은 티베트식 금속 상륜부가 있다.","김구가 이곳에서 출가했고 그가 심은 향나무가 마당에 남아 있다."],"travelTips":["절을 둘러 걷는 백범명상길은 한 시간쯤 걸린다.","봄에는 개울가 벚꽃, 가을에는 단풍이 좋다.","공주역에서 버스로 40분쯤 걸린다."],"bestTime":"4월(벚꽃)과 10~11월","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["마곡사의 개울을 잇는 다리"]},"ja":{"name":"公州麻谷寺","summary":"谷川が大きく曲がる場所に据えられた寺。その水が寺を二つに分ける。","story":"麻谷寺は谷川がほとんど円を描いて曲がるまさにその場所に建てられ、寺は両岸に分かれて小さな橋で結ばれている。北岸は修行と生活の領域、南岸は礼拝の堂で、水を渡って日常から儀礼の空間へ移る。この立地は非常に吉とされ、古い風水書は麻谷寺を災いを免れる地に挙げた。境内には元の時代の交流を示すチベット風の金属相輪を頂く五層石塔がある。独立運動家・金九は日本人将校を殺した後ここに隠れて出家し、彼が植えた柏がいまも残る。","facts":["2018年「山寺、韓国の山地僧院」としてユネスコに登録された。","寺は谷川の両岸に分かれ、橋で結ばれている。","五層石塔には元の影響を受けたチベット風の金属相輪がある。","金九がここで出家し、彼が植えた柏が境内に残る。"],"travelTips":["寺を巡る白凡瞑想路は一時間ほど。","春は川沿いの桜、秋は紅葉がよい。","公州駅からバスで40分ほど。"],"bestTime":"4月（桜）と10〜11月","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["麻谷寺の両岸を結ぶ橋"]},"zh":{"name":"公州麻谷寺","summary":"建在溪流大彎處的寺院，而那道水把寺分成了兩半。","story":"麻谷寺正好蓋在一條溪流幾乎繞成圓圈的地方，寺院分立兩岸，中間以小橋相連——北岸是修行與生活的區域，南岸是禮佛的殿宇，你得跨過水，才從日常走進儀式的空間。這處地勢被認為極為吉利，古代風水書甚至把麻谷寺列為可避災厄之地。庭中立著一座五層石塔，塔剎為西藏式金屬構件，是元代交流留下的痕跡。獨立運動家金九殺死日本軍官後曾藏身於此並出家，他手植的柏樹至今仍在。","facts":["2018年以「山寺，韓國的山地僧院」列入世界遺產。","寺院分立溪流兩岸，以橋相連。","五層石塔的金屬塔剎帶有元代的西藏風格影響。","金九曾在此出家，他手植的柏樹仍留在庭中。"],"travelTips":["繞寺而行的白凡冥想路約需一小時。","春天溪畔櫻花、秋天紅葉，兩季都好。","自公州站搭巴士約40分鐘。"],"bestTime":"4月（櫻花）與10至11月","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["麻谷寺連接兩岸的橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seosan-maae-buddha', 'seosan-maae-buddha', 'chungnam', 'Tượng Phật Ma nhai Seosan', 'Seosan Rock-carved Buddha Triad', 'temple', 126.605278, 36.773889, 'Bộ ba tượng Phật khắc vào vách đá thế kỷ 7, nổi tiếng vì nụ cười đổi theo hướng nắng.', 'Ba pho tượng khắc vào vách đá granite trong một khe núi hẹp ở Seosan, có niên đại khoảng thế kỷ 7 thời Baekje. Điều khiến chúng nổi tiếng là nụ cười: vì mặt tượng được khắc với độ nghiêng rất tinh, ánh nắng chiếu vào theo góc khác nhau trong ngày làm nét mặt đổi theo — buổi sáng trông hiền hoà, giữa trưa gần như nghiêm, chiều muộn thì cười rõ. Người ta gọi đó là ''nụ cười Baekje''. Tượng được phát hiện lại năm 1959 sau khi bị quên trong rừng nhiều thế kỷ. Chỗ này không có gì ngoài ba pho tượng và một mái che, nhưng đáng đi vì rất ít nơi cho bạn cảm giác đứng trước một khuôn mặt sống động đến vậy.', '["Được khắc vào khoảng thế kỷ 7, thời Baekje, là quốc bảo số 84.","Nét mặt tượng thay đổi theo góc chiếu của ánh nắng trong ngày.","Được phát hiện lại năm 1959 sau nhiều thế kỷ bị lãng quên.","Được gọi là biểu tượng của ''nụ cười Baekje''."]', '["Đi buổi chiều muộn — đó là lúc nụ cười rõ nhất.","Đường lên từ bãi xe khoảng 10 phút đi bộ, có bậc thang.","Rất ít khách, kể cả cuối tuần."]', 'Quanh năm; chiều muộn trời nắng', '1 giờ', '', '09:00–18:00', '["hidden-gem","verified"]', '["Baekje","tượng đá","quốc bảo","nụ cười"]', '[{"seed":"seosan-maae-buddha","caption":"Bộ ba tượng Phật khắc trên vách đá","ratio":"16/9"}]', '["sudeoksa","haemieupseong"]', 1, 'https://ko.wikipedia.org/wiki/서산_용현리_마애여래삼존상', '2026-08-04', '{"en":{"name":"Seosan Rock-carved Buddha Triad","summary":"A 7th-century triad carved into a cliff, famous for a smile that changes with the angle of the sun.","story":"Three figures carved into a granite face in a narrow gorge at Seosan, dating from about the 7th century under Baekje. What made them famous is the smile: the faces are cut at such fine angles that the changing light through the day alters the expression — gentle in the morning, almost stern at noon, plainly smiling in late afternoon. It is called the Baekje smile. The carvings were rediscovered in 1959 after centuries forgotten in the woods. There is nothing here but the three figures and a shelter over them, yet very few places give you the sense of standing before a face this alive.","facts":["Carved around the 7th century under Baekje; National Treasure No. 84.","The expressions shift with the angle of sunlight through the day.","Rediscovered in 1959 after centuries of neglect.","Known as the embodiment of the ''Baekje smile''."],"travelTips":["Come in late afternoon — that is when the smile reads most clearly.","It is about a 10-minute walk up steps from the car park.","Very few visitors, even at weekends."],"bestTime":"Year-round; late afternoon on a sunny day","visitDuration":"1 hour","ticket":"","openingHours":"09:00–18:00","galleryCaptions":["The three figures carved into the cliff"]},"ko":{"name":"서산 마애여래삼존상","summary":"7세기 바위에 새긴 삼존불. 햇빛의 각도에 따라 미소가 달라지는 것으로 이름났다.","story":"서산의 좁은 골짜기, 화강암 벽에 새긴 세 분의 불상으로 백제 7세기 무렵의 것이다. 이름을 얻은 것은 미소 덕분이다. 얼굴을 아주 섬세한 각도로 깎아 놓아 하루 중 빛이 드는 방향이 바뀌면 표정이 달라진다. 아침에는 온화하고, 한낮에는 거의 근엄하며, 늦은 오후에는 분명히 웃는다. 사람들은 이것을 백제의 미소라 부른다. 이 불상은 여러 세기 숲에 잊혀 있다가 1959년에 다시 발견되었다. 이곳에는 삼존불과 보호각 말고는 아무것도 없지만, 이토록 살아 있는 얼굴 앞에 서는 경험을 주는 곳은 드물다.","facts":["백제 7세기경에 새겨진 것으로 보며 국보 제84호다.","하루 중 햇빛의 각도에 따라 표정이 달라진다.","여러 세기 잊혔다가 1959년에 다시 발견되었다.","''백제의 미소''를 대표하는 상으로 불린다."],"travelTips":["늦은 오후에 가자. 미소가 가장 또렷하다.","주차장에서 계단을 따라 10분쯤 오른다.","주말에도 사람이 아주 적다."],"bestTime":"연중, 맑은 날 늦은 오후","visitDuration":"1시간","ticket":"","openingHours":"09:00~18:00","galleryCaptions":["바위에 새긴 삼존불"]},"ja":{"name":"瑞山磨崖如来三尊像","summary":"七世紀に岩へ刻まれた三尊。日差しの角度で微笑が変わることで知られる。","story":"瑞山の狭い谷、花崗岩の壁に刻まれた三体の仏で、百済の七世紀ごろのものだ。名を得たのは微笑のためである。顔がきわめて繊細な角度で彫られているため、一日のうち光の差す向きが変わると表情が変わる。朝は穏やかで、真昼はほとんど厳しく、遅い午後にははっきりと笑う。人はこれを百済の微笑と呼ぶ。この像は数世紀のあいだ森に忘れられ、1959年に再発見された。ここには三尊像と覆屋のほかに何もないが、これほど生きた顔の前に立つ経験を与える場所は稀である。","facts":["百済の七世紀ごろの造像とされ、国宝第84号である。","一日のうち日差しの角度によって表情が変わる。","数世紀忘れられ、1959年に再発見された。","「百済の微笑」を代表する像とされる。"],"travelTips":["遅い午後に行こう。微笑が最もはっきり見える。","駐車場から階段を10分ほど上る。","週末でも訪れる人はごく少ない。"],"bestTime":"通年、晴れた日の遅い午後","visitDuration":"1時間","ticket":"","openingHours":"09:00〜18:00","galleryCaptions":["岩壁に刻まれた三尊像"]},"zh":{"name":"瑞山磨崖如來三尊像","summary":"七世紀刻進崖壁的三尊佛，以隨陽光角度改變的微笑聞名。","story":"在瑞山一道狹窄的山谷裡，三尊佛像被刻進花崗岩壁，年代約在百濟七世紀。真正讓它們出名的是那抹微笑：臉部的刻鑿角度極其細膩，一天之中光線方向改變，表情也跟著變——清晨溫和，正午近乎莊嚴，傍晚則明顯地笑了起來。人們稱之為「百濟的微笑」。這組佛像在林間被遺忘數百年，1959年才重新被發現。這裡除了三尊像與一座覆屋之外別無他物，但少有地方能讓人如此清楚地感覺到，自己正站在一張活著的臉之前。","facts":["約刻於百濟七世紀，為國寶第84號。","表情隨一天中陽光的角度而改變。","被遺忘數百年後，於1959年重新發現。","被視為「百濟微笑」的代表作。"],"travelTips":["傍晚前來——那時微笑最清楚。","自停車場沿階梯步行約10分鐘。","即使週末，遊客也非常少。"],"bestTime":"全年；晴天的傍晚","visitDuration":"1小時","ticket":"","openingHours":"09:00–18:00","galleryCaptions":["刻在崖壁上的三尊佛像"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('independence-hall', 'independence-hall', 'chungnam', 'Bảo tàng Độc lập (Cheonan)', 'Independence Hall of Korea, Cheonan', 'museum', 127.2745, 36.7855, 'Bảo tàng lớn nhất Hàn Quốc về thời thuộc địa, xây bằng tiền quyên góp của dân sau một vụ tranh cãi sách giáo khoa.', 'Năm 1982, việc Nhật Bản sửa cách mô tả thời thuộc địa trong sách giáo khoa gây phẫn nộ ở Hàn Quốc, và người dân bắt đầu quyên tiền để xây một bảo tàng kể lại chuyện đó theo cách của mình. Số tiền quyên được đủ để dựng một quần thể bảy toà nhà trên một khu đất rộng dưới chân núi Heukseongsan. Sảnh chính có mái ngói cong khổng lồ và bên dưới là tượng đài cao mười lăm mét; các gian trưng bày đi từ thời tiền sử tới phong trào độc lập, và phần về nhà tù, tra tấn được kể rất thẳng. Đây là nơi mà nhiều trường học Hàn Quốc bắt buộc học sinh phải tới ít nhất một lần.', '["Mở cửa năm 1987, xây chủ yếu bằng tiền quyên góp của người dân.","Là bảo tàng lịch sử lớn nhất Hàn Quốc về thời thuộc địa và phong trào độc lập.","Quần thể gồm bảy toà trưng bày trên khu đất rộng khoảng 400 hecta.","Vào cửa miễn phí."]', '["Khu đất rất rộng — có xe điện chở khách giữa các toà nhà.","Ngày 15 tháng 8 (Quốc khánh) có lễ lớn và rất đông.","Từ ga Cheonan-Asan đi bus khoảng 30 phút."]', 'Quanh năm', '3 giờ', 'Miễn phí từ năm 2008', '09:30–18:00 (tháng 3–10), 09:30–17:00 (tháng 11–2, vào cửa cuối 16:00), đóng cửa thứ Hai', '["verified"]', '["bảo tàng","lịch sử","độc lập","gia đình"]', '[{"seed":"independence-hall","caption":"Sảnh chính Bảo tàng Độc lập","ratio":"16/9"}]', '["oeam-folk-village"]', 0, 'https://i815.or.kr/2018/tour/info.do', '2026-08-04', '{"en":{"name":"Independence Hall of Korea, Cheonan","summary":"Korea''s largest museum of the colonial period, built with public donations after a textbook dispute.","story":"In 1982 Japan''s revision of how the colonial period was described in its textbooks caused outrage in Korea, and people began donating money to build a museum that would tell the story their own way. The sum raised was enough for a complex of seven buildings on a large site below Heukseongsan. The main hall has an enormous curved tiled roof with a fifteen-metre monument beneath it; the galleries run from prehistory to the independence movement, and the sections on prisons and torture are told very plainly. It is a place many Korean schools require pupils to visit at least once.","facts":["Opened in 1987, built largely with public donations.","Korea''s largest history museum of the colonial period and independence movement.","The complex holds seven exhibition buildings across about 400 hectares.","Entry is free."],"travelTips":["The site is large — a shuttle runs between the buildings.","15 August (Liberation Day) brings a major ceremony and heavy crowds.","About 30 minutes by bus from Cheonan-Asan station."],"bestTime":"Year-round","visitDuration":"3 hours","ticket":"Free since 2008","openingHours":"09:30–18:00 (March–October), 09:30–17:00 (November–February, last entry 16:00), closed Mondays","galleryCaptions":["The great hall of the Independence Hall"]},"ko":{"name":"천안 독립기념관","summary":"식민지기를 다룬 한국 최대의 박물관. 교과서 파동 뒤 국민 성금으로 지어졌다.","story":"1982년 일본이 교과서에서 식민지기 서술을 고친 일이 한국에서 큰 분노를 낳았고, 사람들은 그 이야기를 우리 방식으로 남길 박물관을 짓자며 돈을 모으기 시작했다. 모인 성금은 흑성산 아래 넓은 터에 일곱 채의 전시관을 세울 만큼이었다. 겨레의집은 거대한 기와지붕을 얹었고 그 아래에 15m 높이의 상징탑이 있다. 전시는 선사시대부터 독립운동까지 이어지며, 감옥과 고문을 다룬 부분은 아주 직설적이다. 한국의 많은 학교가 학생들을 적어도 한 번은 데려오는 곳이다.","facts":["1987년 개관했으며 대부분 국민 성금으로 지어졌다.","식민지기와 독립운동을 다룬 한국 최대의 역사박물관이다.","약 400헥타르 부지에 일곱 채의 전시관이 있다.","입장은 무료다."],"travelTips":["부지가 매우 넓다. 전시관 사이를 오가는 전동차가 있다.","8월 15일 광복절에는 큰 행사가 있고 매우 붐빈다.","천안아산역에서 버스로 30분쯤 걸린다."],"bestTime":"연중","visitDuration":"3시간","ticket":"2008년부터 무료","openingHours":"09:30~18:00(3~10월), 09:30~17:00(11~2월, 입장 마감 16:00), 월요일 휴관","galleryCaptions":["독립기념관의 겨레의집"]},"ja":{"name":"天安独立記念館","summary":"植民地期を扱う韓国最大の博物館。教科書問題のあと国民の募金で建てられた。","story":"1982年、日本が教科書で植民地期の記述を改めたことが韓国で強い怒りを呼び、人々はその歴史を自分たちのやり方で残す博物館を建てようと募金を始めた。集まった額は黒城山の麓の広大な敷地に七棟の展示館を建てるに足りた。中心の「民族の家」は巨大な瓦屋根を戴き、その下に高さ十五メートルの記念塔が立つ。展示は先史から独立運動まで続き、監獄と拷問を扱う部分はきわめて率直だ。韓国の多くの学校が、生徒を少なくとも一度は連れてくる場所である。","facts":["1987年開館、主に国民の募金で建てられた。","植民地期と独立運動を扱う韓国最大の歴史博物館である。","約400ヘクタールの敷地に七棟の展示館がある。","入場は無料である。"],"travelTips":["敷地が広い。展示館のあいだをシャトルが走る。","8月15日の光復節は大きな式典があり非常に混む。","天安牙山駅からバスで30分ほど。"],"bestTime":"通年","visitDuration":"3時間","ticket":"2008年から無料","openingHours":"09:30〜18:00（3〜10月）、09:30〜17:00（11〜2月、最終入場16:00）、月曜休館","galleryCaptions":["独立記念館の民族の家"]},"zh":{"name":"天安獨立紀念館","summary":"韓國規模最大的殖民時期博物館，在一場教科書爭議後由民間募款興建。","story":"1982年，日本修改教科書中對殖民時期的敘述，在韓國引發強烈憤怒，民眾於是開始捐款，要蓋一座用自己的方式講述那段歷史的博物館。募得的金額足以在黑城山下一片廣闊土地上建起七棟展示館。主館覆著巨大的曲線瓦頂，其下立著十五公尺高的紀念塔；展覽自史前一路走到獨立運動，關於監獄與刑求的段落講得非常直白。這裡是韓國許多學校規定學生至少要來一次的地方。","facts":["1987年開館，主要以民間捐款興建。","是韓國規模最大的殖民時期與獨立運動歷史博物館。","園區約400公頃，設有七棟展示館。","免費入場。"],"travelTips":["園區很大——館與館之間有接駁車。","8月15日光復節有大型典禮，人潮非常多。","自天安牙山站搭巴士約30分鐘。"],"bestTime":"全年","visitDuration":"3小時","ticket":"自2008年起免費","openingHours":"09:30–18:00（3至10月）、09:30–17:00（11至2月，最後入場16:00）；週一休館","galleryCaptions":["獨立紀念館的主殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daejeon-expo-park', 'daejeon-expo-park', 'daejeon', 'Công viên Expo & cầu Expo', 'Expo Science Park & Expo Bridge', 'park', 127.388, 36.375, 'Di sản của Triển lãm thế giới 1993, nay là công viên khoa học bên sông Gapcheon.', 'Năm 1993 Daejeon đăng cai Expo, và cả một khu triển lãm mọc lên bên sông. Ba mươi năm sau, tháp Hanbit vẫn đứng đó như biểu tượng thành phố, còn khu đất đã thành công viên với bảo tàng khoa học quốc gia, hồ nhạc nước và những cây cầu đi bộ lên đèn mỗi tối. Daejeon là thủ phủ nghiên cứu của Hàn Quốc — viện KAIST và hàng chục viện nghiên cứu nằm quanh đây — nên công viên khoa học ở thành phố này không phải chuyện trang trí.', '["Triển lãm Expo 1993 là hội chợ thế giới đầu tiên tổ chức tại Hàn Quốc.","Tháp Hanbit cao 93m, xây đúng dịp Expo.","Bảo tàng Khoa học Quốc gia nằm ngay cạnh công viên.","Daejeon là nơi đặt Đại học KAIST và khu nghiên cứu Daedeok."]', '["Buổi tối có màn nhạc nước trên hồ, xem lịch trước.","Đi tàu KTX từ Seoul chỉ khoảng 1 giờ.","Kết hợp đi bộ dọc suối Gapcheon, mùa xuân có hoa anh đào."]', 'Tháng 4 và 9–10', '2 giờ', '', 'Cả ngày', '[]', '["khoa học","công viên","gia đình"]', '[{"seed":"daejeon-expo-park","caption":"Tháp Hanbit bên sông","ratio":"16/9"}]', '["gyeryongsan"]', 1, 'https://en.wikipedia.org/wiki/Expo_Science_Park', '2026-08-04', '{"en":{"name":"Expo Science Park & Expo Bridge","summary":"The legacy of the 1993 World Expo, now a science park on the Gapcheon river.","story":"Daejeon hosted the World Expo in 1993 and a whole exhibition ground rose beside the river. Thirty years on, the Hanbit Tower still stands as the city''s landmark and the site has become a park with the national science museum, a musical fountain lake and footbridges that light up at night. Daejeon is Korea''s research capital — KAIST and dozens of institutes sit nearby — so a science park here is not decoration.","facts":["Expo 1993 was the first world''s fair held in Korea.","Hanbit Tower, 93m tall, was built for the Expo.","The National Science Museum stands next to the park.","Daejeon is home to KAIST and the Daedeok research complex."],"travelTips":["There is a musical fountain show on the lake in the evening — check the schedule.","The KTX from Seoul takes about an hour.","Walk the Gapcheon stream path; cherry blossom lines it in spring."],"bestTime":"April and September–October","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["Hanbit Tower beside the river"]},"ko":{"name":"엑스포과학공원과 엑스포다리","summary":"1993년 세계박람회가 남긴 유산. 갑천 변의 과학공원이 되었다.","story":"1993년 대전은 세계박람회를 열었고 강변에 거대한 전시장이 들어섰다. 30년이 지난 지금 한빛탑은 여전히 도시의 상징이고, 그 자리는 국립중앙과학관과 음악분수 호수, 밤이면 불이 켜지는 보행교를 갖춘 공원이 되었다. 대전은 한국의 연구 수도다. KAIST와 수십 개의 연구기관이 인근에 있으니, 이 도시의 과학공원은 장식이 아니다.","facts":["1993년 대전엑스포는 한국에서 처음 열린 세계박람회다.","한빛탑은 높이 93m로 엑스포에 맞춰 세워졌다.","공원 옆에 국립중앙과학관이 있다.","대전에는 KAIST와 대덕연구단지가 있다."],"travelTips":["저녁에는 호수에서 음악분수 공연이 있으니 시간을 확인하자.","서울에서 KTX로 약 한 시간이다.","갑천 산책로를 함께 걷자. 봄에는 벚꽃이 이어진다."],"bestTime":"4월, 9~10월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["강변의 한빛탑"]},"ja":{"name":"エキスポ科学公園とエキスポ橋","summary":"1993年万博が残した遺産。今は甲川沿いの科学公園。","story":"1993年、大田は万国博覧会を開き、川沿いに巨大な会場が生まれた。三十年を経て、ハンビッ塔は今も街のシンボルであり、跡地は国立中央科学館と音楽噴水の湖、夜に灯る歩道橋を備えた公園になった。大田は韓国の研究首都だ。KAISTと数十の研究機関が周辺にあるのだから、この街の科学公園は飾りではない。","facts":["1993年の大田エキスポは韓国で初めて開催された万国博覧会。","ハンビッ塔は高さ93m、万博に合わせて建てられた。","公園の隣に国立中央科学館がある。","大田にはKAISTと大徳研究団地がある。"],"travelTips":["夜は湖で音楽噴水の公演がある。時間を確認しよう。","ソウルからKTXで約1時間。","甲川の散策路も歩こう。春は桜が続く。"],"bestTime":"4月、9〜10月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["川辺のハンビッ塔"]},"zh":{"name":"世博科學公園與世博橋","summary":"1993年世界博覽會留下的遺產，如今是甲川畔的科學公園。","story":"1993年大田主辦世界博覽會，河邊蓋起了一整片展場。三十年後，韓光塔仍是城市地標，園區則變成擁有國立中央科學館、音樂噴泉湖與夜間亮燈人行橋的公園。大田是韓國的研究首都——KAIST與數十所研究機構就在附近——所以這座城市的科學公園並非裝飾。","facts":["1993年大田世博是韓國首次舉辦的世界博覽會。","韓光塔高93公尺，為世博而建。","國立中央科學館就在公園旁。","大田是KAIST與大德研究園區的所在地。"],"travelTips":["夜間湖上有音樂噴泉表演，請先查看時間。","自首爾搭KTX約一小時。","順著甲川步道走走，春天沿岸都是櫻花。"],"bestTime":"4月與9至10月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["河邊的韓光塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gyeryongsan', 'gyeryongsan', 'daejeon', 'Vườn quốc gia Gyeryongsan', 'Gyeryongsan National Park', 'mountain', 127.207, 36.342, 'Dãy núi hình mào gà lưng rồng, từ lâu được coi là ngọn núi linh thiêng bậc nhất miền trung.', 'Tên núi ghép từ ''gà'' và ''rồng'' — đường sống núi gồ ghề như mào gà đặt trên lưng rồng. Người Hàn từ xưa xem đây là nơi tụ khí, nên quanh núi có rất nhiều am, chùa và cả những giáo phái nhỏ từng chọn nơi này làm đất tu. Chùa Gapsa ở sườn tây nổi tiếng nhất vào mùa thu, còn Donghaksa phía đông đẹp nhất mùa xuân khi hoa nở dọc suối. Đường mòn nối hai chùa qua đèo mất chừng bốn tiếng.', '["Trở thành vườn quốc gia thứ hai của Hàn Quốc năm 1968.","Đỉnh cao nhất Cheonhwangbong đạt 845m.","Chùa Gapsa được dựng từ năm 420, thời Bách Tế.","Người xưa từng cân nhắc vùng này làm kinh đô mới."]', '["Tuyến Donghaksa – Gapsa là cung đi bộ kinh điển, khoảng 4 giờ.","Đi bus từ trung tâm Daejeon khoảng 40 phút.","Mùa thu cuối tuần rất đông, nên đi sớm."]', 'Tháng 4 và 10–11', 'Nửa ngày', '', 'Áp dụng ''chế độ giờ vào núi'' của vườn quốc gia: được lên từ 04:00 (tháng 3–11) hoặc 05:00 (tháng 12–2), và mỗi cung đường có giờ chặn riêng trong khoảng 12:00–17:00. Kiểm tra thông báo đóng đường trước khi đi', '["verified"]', '["núi","chùa","leo núi"]', '[{"seed":"gyeryongsan","caption":"Sống núi Gyeryongsan","ratio":"16/9"}]', '["daejeon-expo-park","gongju-tomb"]', 0, 'https://www.knps.or.kr/front/portal/safe/acsCtrDtl.do?menuNo=8000340&rstId=0005', '2026-08-05', '{"en":{"name":"Gyeryongsan National Park","summary":"A ridge shaped like a cockscomb on a dragon''s back, long held to be the most sacred mountain in central Korea.","story":"The name joins ''chicken'' and ''dragon'' — the jagged crest looks like a comb set on a dragon''s spine. Koreans have long considered this a mountain where energy gathers, so its slopes are dotted with hermitages, temples and the remains of small religious communities that chose it as their ground. Gapsa temple on the western flank is the autumn favourite, while Donghaksa on the east is at its best in spring when blossom lines the stream. The trail linking the two over the pass takes about four hours.","facts":["Became Korea''s second national park in 1968.","The highest peak, Cheonhwangbong, reaches 845m.","Gapsa temple was founded in 420, during the Baekje kingdom.","The area was once considered as a site for a new capital."],"travelTips":["The Donghaksa–Gapsa traverse is the classic walk, about four hours.","City buses from central Daejeon take about 40 minutes.","Autumn weekends are crowded — start early."],"bestTime":"April and October–November","visitDuration":"Half a day","ticket":"","openingHours":"The national park entry-time system applies: ascent opens at 04:00 (March–November) or 05:00 (December–February), and each section has its own turn-back time somewhere between 12:00 and 17:00. Check the trail-closure notices before setting out","galleryCaptions":["The Gyeryongsan ridge"]},"ko":{"name":"계룡산국립공원","summary":"용의 등에 닭 볏을 얹은 듯한 능선. 예부터 중부의 영산으로 꼽혔다.","story":"이름은 ''닭''과 ''용''을 합친 것으로, 들쭉날쭉한 능선이 용의 등에 얹힌 볏처럼 보인다는 뜻이다. 예부터 기가 모이는 산으로 여겨져 산자락에는 암자와 절, 한때 이곳을 수행터로 삼은 여러 종파의 흔적이 흩어져 있다. 서쪽 기슭의 갑사는 가을이 아름답고, 동쪽의 동학사는 계곡을 따라 꽃이 피는 봄이 좋다. 고개를 넘어 두 절을 잇는 길은 네 시간쯤 걸린다.","facts":["1968년 한국에서 두 번째 국립공원으로 지정되었다.","최고봉인 천황봉은 해발 845m다.","갑사는 백제 시대인 420년에 창건되었다.","이 일대는 한때 새 도읍 후보로 검토되기도 했다."],"travelTips":["동학사~갑사 종주가 대표 코스로 약 네 시간이다.","대전 시내에서 버스로 40분쯤 걸린다.","가을 주말은 붐비니 일찍 출발하자."],"bestTime":"4월, 10~11월","visitDuration":"반나절","ticket":"","openingHours":"국립공원 입산시간지정제가 적용된다. 입산은 3~11월 04:00, 12~2월 05:00부터 가능하며 구간마다 12:00~17:00 사이로 통제시간이 다르다. 출발 전 통제 정보를 확인하자","galleryCaptions":["계룡산 능선"]},"ja":{"name":"鶏龍山国立公園","summary":"龍の背に鶏冠を載せたような稜線。古くから中部の霊山とされてきた。","story":"名は「鶏」と「龍」を合わせたもので、ぎざぎざの稜線が龍の背に載る鶏冠のようだという意味だ。古来より気の集まる山とされ、斜面には庵や寺、この地を修行の場に選んだ諸宗派の痕跡が散らばる。西麓の甲寺は秋が美しく、東の東鶴寺は渓流沿いに花が咲く春がよい。峠を越えて二つの寺を結ぶ道は四時間ほどだ。","facts":["1968年に韓国で二番目の国立公園に指定された。","最高峰の天皇峰は標高845m。","甲寺は百済時代の420年に創建された。","この一帯は新都の候補地として検討されたこともある。"],"travelTips":["東鶴寺〜甲寺の縦走が定番で約四時間。","大田市内からバスで40分ほど。","秋の週末は混むので早出を。"],"bestTime":"4月、10〜11月","visitDuration":"半日","ticket":"","openingHours":"国立公園の入山時間指定制が適用される。入山は3〜11月は04:00、12〜2月は05:00から可能で、区間ごとに12:00〜17:00の間で規制時刻が異なる。出発前に通行規制情報の確認を","galleryCaptions":["鶏龍山の稜線"]},"zh":{"name":"雞龍山國立公園","summary":"狀似龍背上雞冠的山脊，自古被視為中部第一靈山。","story":"山名由「雞」與「龍」合成——嶙峋的稜線像是安在龍背上的雞冠。韓國人自古認為此處聚氣，因此山中散布著庵堂、寺院，以及一些曾選此地修行的教派遺跡。西麓的甲寺以秋色著稱，東側的東鶴寺則在春天溪畔花開時最美。翻越山口串連兩寺的路線約需四小時。","facts":["1968年成為韓國第二座國立公園。","最高峰天皇峰海拔845公尺。","甲寺創建於420年的百濟時期。","此地曾被考慮作為新都候選地。"],"travelTips":["東鶴寺至甲寺的縱走是經典路線，約四小時。","自大田市區搭公車約40分鐘。","秋季週末擁擠，建議早出發。"],"bestTime":"4月與10至11月","visitDuration":"半天","ticket":"","openingHours":"適用國家公園「入山時間指定制」：3至11月自04:00、12至2月自05:00開放入山，各路段的折返管制時間落在12:00至17:00之間。出發前請先查看步道封閉公告","galleryCaptions":["雞龍山稜線"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daejeon-jungang-market', 'daejeon-jungang-market', 'daejeon', 'Chợ Jungang Daejeon', 'Daejeon Jungang Market', 'market', 127.4293, 36.3287, 'Khu chợ truyền thống lớn nhất miền trung, nơi bánh mì Sungsimdang xếp hàng dài mỗi ngày.', 'Chợ Jungang trải dài nhiều dãy phố quanh ga Daejeon, bán mọi thứ từ vải vóc, đồ khô đến thuốc bắc. Nhưng thứ khiến du khách đến Daejeon là một tiệm bánh: Sungsimdang, mở từ 1956, với món bánh mì chiên nhân đậu đỏ và bánh sầu riêng nhân kem mà người ta xếp hàng cả tiếng để mua. Daejeon vì thế được gọi đùa là ''thành phố bánh mì''. Ăn xong, đi vài bước là tới các quán mì tay và canh xương lâu năm trong chợ.', '["Là chợ truyền thống lớn nhất khu vực Chungcheong.","Tiệm bánh Sungsimdang hoạt động từ năm 1956, là biểu tượng của Daejeon.","Chợ nằm ngay cạnh ga Daejeon, rất tiện cho khách quá cảnh.","Khu vực gồm nhiều chợ nhỏ nối nhau: chợ vải, chợ thuốc bắc, chợ đồ cũ."]', '["Đi Sungsimdang trước 11h sáng để tránh hàng dài nhất.","Nhiều quán trong chợ chỉ nhận tiền mặt.","Rất hợp làm điểm dừng 2 tiếng giữa hành trình KTX."]', 'Quanh năm', '1,5 giờ', '', 'Không có giờ chung — chợ lớn nhất vùng trung bộ, mỗi sạp một giờ riêng, phần lớn bán ban ngày; nên hỏi trước nếu nhắm một hàng cụ thể', '["popular"]', '["chợ","bánh mì","ẩm thực"]', '[{"seed":"daejeon-jungang-market","caption":"Dãy hàng trong chợ Jungang","ratio":"16/9"}]', '["daejeon-expo-park"]', 0, 'https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=9b54ece4-d0e2-4f6a-a586-acefc466c7d5', '2026-08-05', '{"en":{"name":"Daejeon Jungang Market","summary":"The largest traditional market in central Korea — and the bakery people queue an hour for.","story":"Jungang market sprawls over several blocks around Daejeon station, selling everything from fabric and dried goods to herbal medicine. But what brings visitors to Daejeon is a bakery: Sungsimdang, open since 1956, with its deep-fried red bean bun and a cream-filled pastry that people line up for. Daejeon is nicknamed the ''bread city'' because of it. Afterwards, a few steps away, are hand-cut noodle shops and old bone-broth kitchens inside the market.","facts":["The largest traditional market in the Chungcheong region.","Sungsimdang bakery has been open since 1956 and is a Daejeon institution.","The market sits beside Daejeon station, handy for travellers passing through.","It is a chain of smaller markets: fabric, herbal medicine and second-hand goods."],"travelTips":["Go to Sungsimdang before 11am to avoid the longest queue.","Many stalls inside the market are cash only.","It works well as a two-hour stop between KTX legs."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"","openingHours":"There are no shared hours — it is the largest market in the central region and each stall sets its own, most trading by day; ask ahead if you are after a particular shop","galleryCaptions":["Stalls inside Jungang Market"]},"ko":{"name":"대전 중앙시장","summary":"중부권 최대의 전통시장. 그리고 한 시간씩 줄 서는 빵집이 있는 곳.","story":"중앙시장은 대전역 일대 여러 블록에 걸쳐 옷감과 건어물, 한약재까지 없는 것이 없다. 그런데 여행자를 대전으로 불러들이는 것은 빵집이다. 1956년 문을 연 성심당의 튀김소보로와 생크림 빵을 사려고 사람들이 줄을 선다. 그래서 대전은 ''빵의 도시''라고 불린다. 다 먹고 몇 걸음만 옮기면 시장 안의 손칼국수집과 오래된 국밥집이 기다린다.","facts":["충청권 최대 규모의 전통시장이다.","1956년 문을 연 성심당은 대전의 상징이다.","대전역 바로 옆이라 환승 여행자에게 편리하다.","포목시장, 한약재시장, 중고시장 등 여러 시장이 이어져 있다."],"travelTips":["성심당은 오전 11시 전에 가야 줄이 짧다.","시장 안 상당수 가게는 현금만 받는다.","KTX 환승 사이 두 시간 코스로 아주 좋다."],"bestTime":"연중","visitDuration":"1시간 30분","ticket":"","openingHours":"공통 운영시간이 없다. 중부권 최대 전통시장으로 점포마다 시간이 다르고 대체로 낮에 영업하므로, 특정 가게를 찾는다면 미리 확인하자","galleryCaptions":["중앙시장 내부"]},"ja":{"name":"大田中央市場","summary":"中部最大の伝統市場。そして一時間並ぶパン屋がある場所。","story":"中央市場は大田駅一帯の数ブロックにわたり、生地から乾物、漢方薬材まで揃う。だが旅行者を大田へ呼ぶのはパン屋だ。1956年開業のソンシムダンの揚げパンと生クリームのパンを買うために人が並ぶ。だから大田は「パンの街」と呼ばれる。食べ終えて数歩進めば、市場の中の手打ちカルグクスや老舗のクッパ屋が待っている。","facts":["忠清圏で最大規模の伝統市場。","1956年開業のソンシムダンは大田の象徴。","大田駅のすぐそばで乗り継ぎ旅行者に便利。","布地市場、漢方市場、古物市場などが連なる。"],"travelTips":["ソンシムダンは午前11時前なら列が短い。","市場内の多くの店は現金のみ。","KTXの乗り継ぎ2時間コースに最適。"],"bestTime":"通年","visitDuration":"1時間30分","ticket":"","openingHours":"共通の営業時間はない。中部圏最大の伝統市場で店ごとに時間が異なり、多くは日中営業。目当ての店があるなら事前確認を","galleryCaptions":["中央市場の店先"]},"zh":{"name":"大田中央市場","summary":"中部最大的傳統市場，也是那家人們排一小時隊的麵包店所在。","story":"中央市場在大田站周邊綿延數個街區，布料、乾貨到中藥材應有盡有。但真正把旅客帶到大田的是一家麵包店：1956年開業的聖心堂，油炸紅豆麵包與奶油夾心麵包讓人排上一個小時。大田因此被戲稱為「麵包之城」。吃完再走幾步，就是市場裡的手切刀削麵與老字號湯飯店。","facts":["忠清地區規模最大的傳統市場。","聖心堂自1956年營業至今，是大田的象徵。","緊鄰大田站，對轉車旅客十分方便。","由布市場、藥材市場與舊貨市場等連成一片。"],"travelTips":["上午十一點前去聖心堂，隊伍最短。","市場內許多攤位只收現金。","很適合安排成KTX轉乘之間的兩小時行程。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"","openingHours":"沒有統一時間——中部地區最大的傳統市場，各攤自訂營業時間，多數白天營業；若有特定店家建議先詢問","galleryCaptions":["中央市場的攤位"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jangtaesan-metasequoia', 'jangtaesan-metasequoia', 'daejeon', 'Rừng thuỷ sam Jangtaesan', 'Jangtaesan Metasequoia Forest', 'park', 127.3305, 36.2295, 'Hàng nghìn cây thuỷ sam trồng thẳng hàng, có cầu đi bộ treo giữa tán cây cao mười bốn mét.', 'Thuỷ sam từng được coi là tuyệt chủng cho tới khi người ta tìm thấy vài cây sống sót ở Trung Quốc năm 1941 — nên mọi rừng thuỷ sam trên thế giới đều là rừng trồng, và rừng ở Jangtaesan trồng từ thập niên 1970. Cây mọc thẳng đứng, tán hình chóp, và trồng thành hàng nên đi vào giống bước vào một sảnh cột. Điều làm nơi này khác là ''skyway'' — cầu đi bộ dài gần sáu trăm mét treo ở độ cao mười bốn mét, tức là ngang tầm giữa tán cây, nên bạn đi giữa lá chứ không phải dưới lá. Mùa thu lá thuỷ sam chuyển màu gỉ sắt đỏ rồi rụng hết, trơ ra rừng cột xám.', '["Rừng thuỷ sam được trồng từ thập niên 1970 trên diện tích khoảng 80 hecta.","Cầu đi bộ trên cao dài khoảng 600m ở độ cao 14m giữa tán cây.","Thuỷ sam từng bị coi là tuyệt chủng cho tới khi được tìm lại năm 1941.","Là rừng do thành phố Daejeon quản lý, vào cửa miễn phí."]', '["Cuối tháng 10 đến đầu tháng 11 là lúc lá chuyển màu đẹp nhất.","Cầu trên cao đóng khi gió lớn hoặc băng giá.","Từ trung tâm Daejeon đi bus khoảng 50 phút."]', 'Tháng 6–8 (xanh mát) và cuối tháng 10', '2–3 giờ', 'Miễn phí, kể cả bãi đỗ xe (trừ nhà nghỉ và phòng họp)', '09:00–18:00, vào cửa cuối 17:00, mở quanh năm. Tháp Skytower đang tạm đóng để kiểm định an toàn', '["hidden-gem"]', '["rừng","thuỷ sam","cầu trên cao","đi bộ"]', '[{"seed":"jangtaesan-metasequoia","caption":"Cầu đi bộ giữa tán thuỷ sam","ratio":"16/9"}]', '["gyeryongsan"]', 0, 'https://www.foresttrip.go.kr/pot/rm/ug/selectFcltUseGdncView.do?hmpgId=ID02030106&menuId=004002005&ruleId=205', '2026-08-05', '{"en":{"name":"Jangtaesan Metasequoia Forest","summary":"Thousands of metasequoias planted in rows, with a walkway suspended fourteen metres up in the canopy.","story":"The metasequoia was believed extinct until a few survivors were found in China in 1941 — so every metasequoia forest in the world is planted, and the one at Jangtaesan dates from the 1970s. The trees grow dead straight with conical crowns and were set in rows, so walking in feels like entering a hall of columns. What makes this one different is the skyway: a walkway nearly six hundred metres long hung fourteen metres up, level with the middle of the canopy, so you walk among the leaves rather than beneath them. In autumn the needles turn rust red and drop, leaving a forest of grey columns.","facts":["The metasequoia stand was planted from the 1970s across about 80 hectares.","The elevated walkway runs about 600m at a height of 14m in the canopy.","The metasequoia was thought extinct until rediscovered in 1941.","The forest is run by the city of Daejeon and entry is free."],"travelTips":["Late October to early November is when the colour is best.","The skyway closes in high wind or icy conditions.","About 50 minutes by bus from central Daejeon."],"bestTime":"June–August (deep green) and late October","visitDuration":"2–3 hours","ticket":"Free, parking included (lodging and meeting rooms excepted)","openingHours":"09:00–18:00, last entry 17:00, open year-round. The Skytower is temporarily closed for a safety inspection","galleryCaptions":["The walkway through the metasequoia canopy"]},"ko":{"name":"장태산 메타세쿼이아 숲","summary":"줄지어 심은 수천 그루의 메타세쿼이아. 14m 높이 수관 사이로 스카이웨이가 지난다.","story":"메타세쿼이아는 1941년 중국에서 몇 그루가 발견되기 전까지 멸종한 것으로 알려져 있었다. 그래서 세상의 모든 메타세쿼이아 숲은 사람이 심은 것이고, 장태산의 숲은 1970년대에 조성되었다. 나무는 곧게 자라고 수관은 원뿔이며 줄지어 심어서, 들어서면 기둥의 홀에 들어온 것 같다. 이곳을 다르게 만드는 것은 스카이웨이다. 600m에 가까운 보행로가 14m 높이, 즉 수관 한가운데에 걸려 있어 잎 아래가 아니라 잎 사이를 걷게 된다. 가을이면 잎이 붉은 녹빛으로 물들었다가 다 떨어지고 회색 기둥의 숲만 남는다.","facts":["메타세쿼이아 숲은 1970년대부터 약 80헥타르에 조성되었다.","공중 보행로는 높이 14m, 길이 약 600m로 수관 사이를 지난다.","메타세쿼이아는 1941년 재발견 전까지 멸종종으로 여겨졌다.","대전시가 관리하는 숲으로 입장은 무료다."],"travelTips":["10월 말에서 11월 초가 단풍이 가장 좋다.","바람이 세거나 얼면 스카이웨이는 통제된다.","대전 시내에서 버스로 50분쯤 걸린다."],"bestTime":"6~8월(짙은 초록)과 10월 말","visitDuration":"2~3시간","ticket":"숙박·회의실을 제외한 입장료와 주차료 모두 무료","openingHours":"09:00~18:00(입장 마감 17:00), 연중무휴. 스카이타워는 정밀 안전점검으로 임시 폐쇄 중","galleryCaptions":["메타세쿼이아 수관 사이의 보행로"]},"ja":{"name":"長泰山メタセコイアの森","summary":"列植された数千本のメタセコイア。高さ14mの樹冠のあいだを歩道が抜ける。","story":"メタセコイアは1941年に中国で数本の生き残りが見つかるまで絶滅したと考えられていた。だから世界のメタセコイアの森はすべて人の手で植えたもので、長泰山の森は1970年代のものだ。木はまっすぐ育ち、樹冠は円錐で、列に植えられているので入ると柱の広間に踏み込んだようになる。ここを特別にしているのはスカイウェイだ。六百メートル近い歩道が高さ十四メートル、つまり樹冠の中ほどに架かっているので、葉の下ではなく葉のあいだを歩くことになる。秋には葉が錆びた赤に染まって落ち、灰色の柱の森が残る。","facts":["メタセコイア林は1970年代から約80ヘクタールに植えられた。","空中歩道は高さ14m、長さ約600mで樹冠を抜ける。","メタセコイアは1941年の再発見まで絶滅種とされていた。","大田市が管理する森で、入場は無料である。"],"travelTips":["10月末から11月初めが最も色づく。","強風や凍結の際はスカイウェイが閉鎖される。","大田市街からバスで50分ほど。"],"bestTime":"6〜8月（濃い緑）と10月末","visitDuration":"2〜3時間","ticket":"宿泊と会議室を除き、入場も駐車も無料","openingHours":"09:00〜18:00（最終入場17:00）、年中無休。スカイタワーは精密安全点検のため一時閉鎖中","galleryCaptions":["メタセコイアの樹冠を抜ける歩道"]},"zh":{"name":"長泰山水杉林","summary":"成排種下的數千株水杉，還有一條懸在十四公尺樹冠之間的空中步道。","story":"水杉一度被認為已經滅絕，直到1941年在中國發現幾株倖存者——所以世界上所有的水杉林都是人工種植的，而長泰山這一片始於1970年代。這種樹筆直生長、樹冠呈圓錐形，又是成排種下的，走進去就像走進一座柱廳。真正讓這裡不同的是空中步道：一條近六百公尺長的走道懸在十四公尺高處，恰好在樹冠中段，於是你是走在葉子之間，而不是葉子底下。秋天針葉轉成鏽紅後落盡，只留下一片灰色的柱林。","facts":["水杉林自1970年代起種植，面積約80公頃。","空中步道長約600公尺，架設於14公尺高的樹冠層。","水杉曾被認為滅絕，直到1941年重新被發現。","由大田市管理，免費入場。"],"travelTips":["10月底至11月初葉色最好。","強風或結冰時空中步道會封閉。","自大田市區搭巴士約50分鐘。"],"bestTime":"6至8月（濃綠）與10月底","visitDuration":"2至3小時","ticket":"免費，含停車（住宿與會議室除外）","openingHours":"09:00–18:00（最後入場17:00），全年開放；空中塔因安全檢測暫時關閉","galleryCaptions":["穿過水杉樹冠的空中步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daecheongho-observatory', 'daecheongho-observatory', 'daejeon', 'Hồ Daecheong & đường ven hồ', 'Daecheongho Lake & Lakeside Road', 'lake', 127.4835, 36.4795, 'Hồ cấp nước cho cả vùng trung bộ, có tuyến đường ven hồ được xếp trong các cung đường đẹp nhất Hàn Quốc.', 'Daecheongho là hồ nhân tạo lớn thứ ba Hàn Quốc, cấp nước sinh hoạt cho Daejeon, Cheongju và cả vùng trung bộ. Vì là nguồn nước nên phần lớn bờ hồ bị hạn chế xây dựng — và chính điều đó giữ cho cảnh quan gần như không bị đụng đến. Tuyến đường ven hồ chạy quanh co giữa các mũi đất và vịnh nhỏ, có những đoạn cây phủ kín thành đường hầm lá, và các đài quan sát nhỏ đặt ở các điểm nhìn đẹp. Có cả một đường mòn đi bộ hai mươi mốt chặng vòng quanh hồ. Sương sớm mùa thu bốc lên mặt hồ là cảnh nhiếp ảnh quen thuộc của vùng.', '["Là hồ nhân tạo lớn thứ ba Hàn Quốc, hình thành từ đập Daecheong năm 1980.","Cấp nước sinh hoạt cho Daejeon, Cheongju và vùng trung bộ.","Đường mòn đi bộ quanh hồ chia thành 21 chặng.","Phần lớn bờ hồ bị hạn chế xây dựng để bảo vệ nguồn nước."]', '["Cần xe riêng — đường ven hồ hầu như không có xe bus.","Sương sớm mùa thu là thời điểm đẹp nhất, đi trước bình minh.","Kết hợp với Cheongnamdae nằm ngay bên hồ."]', 'Tháng 10–11 (sương sớm và lá đỏ)', 'Nửa ngày', '', 'Cả ngày', '["hidden-gem"]', '["hồ","đường ven hồ","sương sớm","đi bộ"]', '[{"seed":"daecheongho-observatory","caption":"Sương sớm trên hồ Daecheong","ratio":"16/9"}]', '["daejeon-expo-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Daecheongho Lake & Lakeside Road","summary":"The reservoir supplying central Korea, with a lakeside road counted among the country''s finest drives.","story":"Daecheongho is Korea''s third largest reservoir, supplying drinking water to Daejeon, Cheongju and the wider central region. Because it is a water source, most of the shoreline is restricted from building — and that is exactly what has kept the landscape almost untouched. The lakeside road winds between headlands and small bays, with stretches where the trees close overhead into a tunnel and small observation points set at the best views. There is also a twenty-one stage walking trail circling the lake. Autumn mist rising off the water at dawn is the region''s stock photograph.","facts":["Korea''s third largest reservoir, formed by the Daecheong dam in 1980.","It supplies drinking water to Daejeon, Cheongju and central Korea.","The walking trail around the lake is divided into 21 stages.","Most of the shoreline is restricted from building to protect the water source."],"travelTips":["You need your own car — there is almost no bus service on the lakeside road.","Autumn dawn mist is the best of it; set out before sunrise.","Combine it with Cheongnamdae, which sits on the same lake."],"bestTime":"October–November (mist and autumn colour)","visitDuration":"Half a day","ticket":"","openingHours":"All day","galleryCaptions":["Dawn mist on Daecheong lake"]},"ko":{"name":"대청호와 호반도로","summary":"중부권에 물을 대는 호수. 호반도로는 한국에서 손꼽히는 드라이브 길이다.","story":"대청호는 한국에서 세 번째로 큰 인공호로, 대전과 청주를 비롯한 중부권에 상수를 공급한다. 상수원이라 호숫가 대부분은 건축이 제한되는데, 바로 그 덕분에 풍경이 거의 손대지 않은 채 남았다. 호반도로는 곶과 작은 만 사이를 굽이돌고, 나무가 머리 위로 맞닿아 터널이 되는 구간이 있으며, 전망이 좋은 자리마다 작은 전망대가 놓여 있다. 호수를 도는 21개 구간의 걷는 길도 있다. 가을 새벽 물 위로 오르는 안개는 이 지역의 대표적인 사진 풍경이다.","facts":["1980년 대청댐으로 생긴 한국에서 세 번째로 큰 인공호다.","대전과 청주를 비롯한 중부권의 상수원이다.","호수를 도는 걷는 길은 21개 구간으로 나뉜다.","상수원 보호를 위해 호숫가 대부분은 건축이 제한된다."],"travelTips":["차가 필요하다. 호반도로에는 버스가 거의 없다.","가을 새벽 안개가 백미다. 해 뜨기 전에 나서자.","같은 호숫가의 청남대와 묶어서 보자."],"bestTime":"10~11월(안개와 단풍)","visitDuration":"반나절","ticket":"","openingHours":"상시","galleryCaptions":["대청호의 새벽 물안개"]},"ja":{"name":"大清湖と湖畔道路","summary":"中部圏に水を供給する湖。湖畔の道は韓国屈指のドライブコースに数えられる。","story":"大清湖は韓国で三番目に大きい人造湖で、大田や清州をはじめ中部圏に上水を供給する。水源であるため湖岸の大半は建築が制限され、まさにそれが景観をほとんど手つかずのまま残した。湖畔道路は岬と小さな入り江のあいだを曲がりくねり、木が頭上で閉じてトンネルになる区間があり、眺めのよい地点ごとに小さな展望台が置かれている。湖を一周する二十一区間の歩く道もある。秋の明け方に水面から立ちのぼる霧は、この地域を代表する写真の風景だ。","facts":["1980年の大清ダムでできた韓国で三番目に大きい人造湖である。","大田・清州をはじめ中部圏の上水源である。","湖を巡る歩く道は21の区間に分かれている。","水源保護のため湖岸の大半は建築が制限されている。"],"travelTips":["車が要る。湖畔道路にはバスがほとんどない。","秋の明け方の霧が白眉だ。日の出前に出よう。","同じ湖畔の青南台と合わせて回ろう。"],"bestTime":"10〜11月（霧と紅葉）","visitDuration":"半日","ticket":"","openingHours":"終日","galleryCaptions":["大清湖の明け方の霧"]},"zh":{"name":"大清湖與環湖公路","summary":"供應中部地區用水的水庫，環湖公路名列韓國最美的路線之一。","story":"大清湖是韓國第三大人工湖，供應大田、清州以及整個中部地區的飲用水。因為是水源地，湖岸大部分禁止興建——而正是這一點，讓景觀幾乎維持原樣。環湖公路在岬角與小灣之間蜿蜒，有幾段樹冠在頭頂交會成隧道，視野好的地方則設有小型觀景台。此外還有一條分成二十一段、環繞整座湖的步道。秋天清晨自水面升起的霧氣，是這一帶最經典的攝影畫面。","facts":["1980年大清水壩形成，是韓國第三大人工湖。","供應大田、清州與中部地區的飲用水。","環湖步道共分為21段。","為保護水源，湖岸大部分限制興建。"],"travelTips":["需要自備交通工具，環湖公路幾乎沒有公車。","秋天清晨的霧氣最精采，天亮前就要出發。","可與同在湖畔的青南台排在一起。"],"bestTime":"10至11月（晨霧與紅葉）","visitDuration":"半天","ticket":"","openingHours":"全日開放","galleryCaptions":["大清湖的清晨霧氣"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daejeon-skyroad', 'daejeon-skyroad', 'daejeon', 'Phố Eunhaeng-dong & Sky Road', 'Eunhaeng-dong & Sky Road', 'city', 127.4275, 36.3275, 'Mái vòm LED dài hai trăm mét treo trên phố đi bộ cũ, chiếu phim ngay trên đầu người qua lại.', 'Eunhaeng-dong là khu phố trung tâm cũ của Daejeon, từng sầm uất rồi xuống dốc khi thành phố dịch về phía Dunsan. Năm 2013, thành phố dựng một mái vòm LED dài hai trăm mét bắc qua trục phố đi bộ, và mỗi tối nó chiếu các đoạn phim ngắn — cá bơi, sao băng, hoa nở — ngay trên đầu người đi đường. Nghe có vẻ phô trương nhưng nó có tác dụng: khu phố sống lại với quán ăn, tiệm quần áo và các nhóm nhạc đường phố. Ban ngày Eunhaeng-dong là khu mua sắm bình thường; đáng đi vào sau khi trời tối. Ngay cạnh là phố Daeheung-dong với các quán cà phê trong nhà cũ.', '["Mái vòm LED Sky Road dài khoảng 214m, khánh thành năm 2013.","Chiếu các đoạn phim ngắn vào buổi tối, mỗi suất vài phút.","Eunhaeng-dong là khu trung tâm thương mại cũ của Daejeon.","Được xây như một dự án hồi sinh khu phố cũ."]', '["Chỉ đáng đi sau khi trời tối hẳn; ban ngày mái vòm không chiếu.","Suất chiếu cách nhau khoảng 15–20 phút.","Cách ga Jungangno (tuyến 1) vài phút đi bộ."]', 'Quanh năm; buổi tối', '1 giờ', '', 'Phố mở cả ngày; màn hình Sky Road chiếu 19:00–23:00 (tháng 4–9) và 18:00–22:00 (tháng 10–3)', '["trending"]', '["về đêm","LED","phố đi bộ","hồi sinh đô thị"]', '[{"seed":"daejeon-skyroad","caption":"Mái vòm LED trên phố Eunhaeng-dong","ratio":"16/9"}]', '["daejeon-jungang-market"]', 0, 'http://djskyroad.kr/content/58', '2026-08-05', '{"en":{"name":"Eunhaeng-dong & Sky Road","summary":"A two-hundred-metre LED canopy over an old pedestrian street, playing films above people''s heads.","story":"Eunhaeng-dong is Daejeon''s old central quarter, once busy and then in decline as the city shifted towards Dunsan. In 2013 the city hung a two-hundred-metre LED canopy across the pedestrian spine, and each evening it plays short films — fish swimming, meteors, flowers opening — directly overhead. It sounds gimmicky, and it worked: the quarter revived with restaurants, clothes shops and street bands. By day Eunhaeng-dong is an ordinary shopping street; it is worth coming after dark. Next to it is Daeheung-dong, full of cafés in old houses.","facts":["The Sky Road LED canopy is about 214m long and opened in 2013.","It plays short films in the evening, each a few minutes long.","Eunhaeng-dong is Daejeon''s old commercial centre.","It was built as a regeneration project for the old quarter."],"travelTips":["Only worth it after full dark; the canopy does not run by day.","Screenings run roughly every 15–20 minutes.","A few minutes'' walk from Jungangno station on line 1."],"bestTime":"Year-round; evenings","visitDuration":"1 hour","ticket":"","openingHours":"The street is open all day; the Sky Road screen runs 19:00–23:00 (April–September) and 18:00–22:00 (October–March)","galleryCaptions":["The LED canopy over Eunhaeng-dong"]},"ko":{"name":"은행동과 스카이로드","summary":"옛 보행자 거리 위에 걸린 200m의 LED 천장. 지나는 사람 머리 위로 영상이 흐른다.","story":"은행동은 대전의 옛 도심으로, 한때 붐볐다가 도시가 둔산 쪽으로 옮겨 가면서 기울었다. 2013년 시는 보행자 거리 위로 200m가 넘는 LED 천장을 걸었고, 저녁마다 짧은 영상이 흐른다. 헤엄치는 물고기, 별똥별, 피는 꽃이 머리 바로 위에서 지나간다. 겉보기엔 요란해 보이지만 효과가 있었다. 거리에 식당과 옷가게, 버스킹이 돌아왔다. 낮의 은행동은 평범한 쇼핑 거리이니, 해가 진 뒤에 가는 편이 낫다. 바로 옆 대흥동에는 옛 건물에 든 카페들이 있다.","facts":["스카이로드 LED 천장은 길이 약 214m로 2013년 완공되었다.","저녁마다 몇 분짜리 짧은 영상을 상영한다.","은행동은 대전의 옛 상업 중심지다.","구도심 재생 사업으로 만들어졌다."],"travelTips":["완전히 어두워진 뒤에 가자. 낮에는 상영하지 않는다.","상영은 대략 15~20분 간격이다.","1호선 중앙로역에서 몇 분 거리다."],"bestTime":"연중, 저녁","visitDuration":"1시간","ticket":"","openingHours":"거리는 상시 개방, 스카이로드 영상은 19:00~23:00(4~9월), 18:00~22:00(10~3월)에 상영된다","galleryCaptions":["은행동 거리 위의 LED 천장"]},"ja":{"name":"銀杏洞とスカイロード","summary":"旧歩行者通りの上に架かる200mのLED天井。通る人の頭上で映像が流れる。","story":"銀杏洞は大田の旧中心街で、かつて賑わい、都市が屯山側へ移るにつれて傾いた。2013年、市は歩行者通りの上に二百メートルを超えるLED天井を架け、夕方ごとに短い映像を流している。泳ぐ魚、流れ星、開く花が頭のすぐ上を通り過ぎる。派手に聞こえるが効いた。通りに食堂と衣料店、路上演奏が戻った。昼の銀杏洞はありふれた商店街なので、日が落ちてから行くほうがよい。すぐ隣の大興洞には古い建物に入ったカフェがある。","facts":["スカイロードのLED天井は長さ約214mで2013年に完成した。","夕方ごとに数分の短い映像を上映する。","銀杏洞は大田の旧商業中心地である。","旧市街の再生事業として造られた。"],"travelTips":["完全に暗くなってから行こう。昼は上映しない。","上映はおよそ15〜20分間隔である。","1号線・中央路駅から数分。"],"bestTime":"通年、夕方","visitDuration":"1時間","ticket":"","openingHours":"通りは終日開放、スカイロードの映像は19:00〜23:00（4〜9月）、18:00〜22:00（10〜3月）に上映される","galleryCaptions":["銀杏洞の通りの上のLED天井"]},"zh":{"name":"銀杏洞與Sky Road","summary":"架在舊步行街上方的兩百公尺LED頂棚，在行人頭頂播放影片。","story":"銀杏洞是大田的舊市中心，曾經繁華，隨著城市重心移往屯山而沒落。2013年，市府在步行街上方架起一道兩百多公尺的LED頂棚，每晚播放短片——游動的魚、流星、綻放的花，就在人們頭頂掠過。聽起來像噱頭，但它奏效了：街區隨著餐廳、服飾店與街頭樂團一起復甦。白天的銀杏洞只是條普通的購物街，值得的是天黑之後來。緊鄰的大興洞則有許多開在老屋裡的咖啡館。","facts":["Sky Road的LED頂棚長約214公尺，2013年啟用。","每晚播放數分鐘長的短片。","銀杏洞是大田的舊商業中心。","作為舊城區再生計畫而興建。"],"travelTips":["務必等天全黑後再去，白天不播放。","播映大約每15至20分鐘一輪。","距地鐵1號線中央路站步行數分鐘。"],"bestTime":"全年；夜間","visitDuration":"1小時","ticket":"","openingHours":"街道全日開放；天空之路螢幕於19:00–23:00（4至9月）與18:00–22:00（10至3月）播放","galleryCaptions":["銀杏洞街道上方的LED頂棚"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ppuri-park', 'ppuri-park', 'daejeon', 'Công viên Cội nguồn (Ppuri Park)', 'Ppuri Park (Roots Park)', 'park', 127.4185, 36.2985, 'Công viên duy nhất trên thế giới dành riêng cho họ tộc, với đá khắc gia huy của hai trăm dòng họ Hàn Quốc.', 'Người Hàn Quốc chỉ có khoảng ba trăm họ, nhưng mỗi họ lại chia thành nhiều bản quán — ''Kim xứ Gimhae'' khác ''Kim xứ Gyeongju'' — và hệ thống ấy định hình cách người ta tự giới thiệu suốt hàng trăm năm. Ppuri Park là công viên duy nhất trên thế giới dựng riêng cho chuyện đó: hơn hai trăm bia đá, mỗi bia khắc gia huy và lịch sử của một bản quán, xếp dọc sườn đồi bên suối. Người Hàn đến đây tìm bia của dòng họ mình và chụp ảnh trước nó. Với khách nước ngoài, đây là cách nhanh nhất để hiểu vì sao câu hỏi ''bản quán của bạn ở đâu'' từng quan trọng đến thế. Trong công viên còn có bảo tàng phả hệ.', '["Là công viên duy nhất trên thế giới dành riêng cho hệ thống họ tộc.","Có hơn 200 bia đá khắc gia huy của các bản quán Hàn Quốc.","Mở cửa năm 1997, do thành phố Daejeon xây dựng.","Trong công viên có bảo tàng phả hệ và tư liệu gia phả."]', '["Có bản đồ chỉ vị trí bia của từng dòng họ ở cổng vào.","Vào cửa miễn phí, mở cả tuần.","Đi bộ dọc suối Ppuri phía dưới công viên cũng dễ chịu."]', 'Tháng 4–6 và 9–11', '1,5 giờ', '', 'Công viên 06:00–22:00 (tháng 3–10), 07:00–21:00 (tháng 11–2); Bảo tàng Gia phả trong công viên 09:00–18:00, đóng cửa thứ Hai', '["hidden-gem"]', '["dòng họ","phả hệ","công viên","văn hoá"]', '[{"seed":"ppuri-park","caption":"Bia đá gia huy các dòng họ","ratio":"16/9"}]', '["daejeon-skyroad","gyeryongsan"]', 0, 'https://www.djjunggu.go.kr/prog/tursmCn/tour/sub03_01_01/view.do?cntNo=24', '2026-08-05', '{"en":{"name":"Ppuri Park (Roots Park)","summary":"The world''s only park devoted to clans, with stones carved with the crests of two hundred Korean lineages.","story":"Koreans have only about three hundred surnames, but each divides into clan seats — a Kim of Gimhae is not a Kim of Gyeongju — and that system shaped how people introduced themselves for centuries. Ppuri Park is the only park in the world built for it: over two hundred stone steles, each carved with the crest and history of one clan seat, ranged along a hillside beside a stream. Koreans come to find their own family''s stele and be photographed in front of it. For a foreign visitor it is the quickest way to understand why the question ''where is your clan from'' once mattered so much. There is a genealogy museum on site.","facts":["The only park in the world devoted to the clan-seat system.","Over 200 stone steles carry the crests of Korean clan seats.","Opened in 1997 and built by the city of Daejeon.","The park holds a genealogy museum and family record archive."],"travelTips":["There is a map at the entrance showing where each clan''s stele stands.","Entry is free and it opens every day.","The walk along the Ppuri stream below the park is pleasant too."],"bestTime":"April–June and September–November","visitDuration":"1.5 hours","ticket":"","openingHours":"The park runs 06:00–22:00 (March–October) and 07:00–21:00 (November–February); the genealogy museum inside is 09:00–18:00, closed Mondays","galleryCaptions":["Stone steles carved with clan crests"]},"ko":{"name":"뿌리공원","summary":"성씨를 위해 만든 세계 유일의 공원. 200여 본관의 유래비가 늘어서 있다.","story":"한국의 성씨는 삼백 개쯤이지만 각 성은 본관으로 갈린다. 김해 김씨와 경주 김씨는 다르다. 그 체계가 수백 년 동안 사람들이 자기를 소개하는 방식을 정했다. 뿌리공원은 바로 그것을 위해 만든 세계 유일의 공원이다. 이백 개가 넘는 유래비가 각기 한 본관의 문장과 내력을 새기고 개울가 비탈을 따라 늘어서 있다. 한국 사람들은 자기 문중의 비를 찾아 그 앞에서 사진을 찍는다. 외국인에게는 ''본관이 어디냐''는 물음이 왜 그토록 중요했는지 가장 빨리 이해하는 길이다. 공원 안에는 족보박물관도 있다.","facts":["성씨의 본관 체계를 위해 만든 세계 유일의 공원이다.","200여 기의 유래비에 각 본관의 문장이 새겨져 있다.","1997년 대전시가 조성해 개원했다.","공원 안에 족보박물관과 가문 자료가 있다."],"travelTips":["입구에 각 문중 비의 위치를 표시한 안내도가 있다.","입장은 무료이고 매일 연다.","공원 아래 뿌리 개울을 따라 걷는 길도 좋다."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5시간","ticket":"","openingHours":"공원은 06:00~22:00(3~10월), 07:00~21:00(11~2월). 한국족보박물관은 09:00~18:00, 월요일 휴관","galleryCaptions":["문중의 문장을 새긴 유래비"]},"ja":{"name":"ルーツ公園（뿌리공원）","summary":"姓氏のために造られた世界唯一の公園。二百余りの本貫の由来碑が並ぶ。","story":"韓国の姓は三百ほどだが、各姓は本貫に分かれる。金海金氏と慶州金氏は別だ。その体系が数百年にわたり人の名乗り方を決めてきた。ルーツ公園はまさにそのために造られた世界唯一の公園である。二百を超える由来碑がそれぞれ一つの本貫の紋章と来歴を刻み、川辺の斜面に並ぶ。韓国の人は自分の一族の碑を探し、その前で写真を撮る。外国人にとっては、「本貫はどこか」という問いがなぜあれほど重かったのかを最も早く理解する道だ。園内には族譜博物館もある。","facts":["姓氏の本貫制度のために造られた世界唯一の公園である。","200基を超える由来碑に各本貫の紋章が刻まれている。","1997年に大田市が造成して開園した。","園内に族譜博物館と一族の資料がある。"],"travelTips":["入口に各一族の碑の位置を示す案内図がある。","入場は無料で、毎日開いている。","公園の下のルーツ川沿いを歩くのも心地よい。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1.5時間","ticket":"","openingHours":"公園は06:00〜22:00（3〜10月）、07:00〜21:00（11〜2月）。族譜博物館は09:00〜18:00、月曜休館","galleryCaptions":["一族の紋章を刻んだ由来碑"]},"zh":{"name":"尋根公園","summary":"全世界唯一為姓氏宗族而設的公園，兩百多座石碑刻著各家族的族徽。","story":"韓國只有大約三百個姓，但每個姓又分出「本貫」——金海金氏和慶州金氏並不相同——這套體系形塑了數百年來人們自我介紹的方式。尋根公園是全世界唯一為此而建的公園：兩百多座石碑，每一座刻著一個本貫的族徽與源流，沿著溪畔的山坡排開。韓國人來這裡尋找自家宗族的碑，並在碑前合影。對外國旅人而言，這是理解「你本貫是哪裡」為何曾經如此重要的最快途徑。園區內另設有族譜博物館。","facts":["全世界唯一為姓氏本貫制度而建的公園。","兩百多座石碑刻有各本貫的族徽。","1997年由大田市興建開放。","園內設有族譜博物館與家族史料。"],"travelTips":["入口有導覽圖標示各宗族石碑的位置。","免費入場，每日開放。","沿著公園下方的溪流散步也很舒服。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5小時","ticket":"","openingHours":"公園06:00–22:00（3至10月）、07:00–21:00（11至2月）；園內族譜博物館09:00–18:00，週一休館","galleryCaptions":["刻著宗族族徽的石碑"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sejong-lake-park', 'sejong-lake-park', 'sejong', 'Công viên hồ Sejong', 'Sejong Lake Park', 'lake', 127.2565, 36.5045, 'Hồ nhân tạo lớn giữa thành phố hành chính mới, với sân khấu nổi hình chiếc lá.', 'Sejong được xây từ đầu để chia bớt gánh nặng thủ đô: các bộ ngành dời về đây từ năm 2012, và cả thành phố là một bản quy hoạch được thi công liền mạch. Trung tâm của nó là hồ nước rộng với năm hòn đảo nhỏ, đường chạy bộ vòng quanh và một sân khấu nổi. Kiến trúc ở đây rất khác phần còn lại của Hàn Quốc: toà nhà chính phủ dài hơn ba cây số, mái phủ cây xanh đi bộ được. Đây là chỗ để thấy Hàn Quốc thiết kế một thành phố khi được làm lại từ đầu.', '["Sejong là thành phố tự trị đặc biệt, thành lập năm 2012.","Hồ có diện tích mặt nước khoảng 32 hecta.","Toà nhà chính phủ Sejong dài hơn 3,5 km với mái vườn đi bộ được.","Thư viện Quốc gia Sejong nằm ngay bên hồ."]', '["Thuê xe đạp công cộng để đi quanh hồ và khu trung tâm.","Buổi tối hồ lên đèn, có các buổi diễn ngoài trời vào cuối tuần.","Từ Daejeon đi bus BRT khoảng 40 phút."]', 'Tháng 4–6 và 9–10', '2 giờ', '', 'Cả ngày', '["new"]', '["hồ","đô thị mới","đi bộ"]', '[{"seed":"sejong-lake-park","caption":"Hồ Sejong và sân khấu nổi","ratio":"16/9"}]', '["sejong-arboretum"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Sejong Lake Park","summary":"A large artificial lake at the heart of the new administrative city, with a floating stage shaped like a leaf.","story":"Sejong was built from scratch to take pressure off the capital: ministries moved here from 2012, and the whole city is a single continuous plan. At its centre lies a broad lake with five small islands, a running loop and a floating stage. The architecture is unlike anywhere else in Korea: the government complex runs more than three kilometres with a rooftop garden you can walk along. This is where you see what Korea builds when it starts a city over.","facts":["Sejong became a special self-governing city in 2012.","The lake covers about 32 hectares of water.","The Sejong government complex is over 3.5 km long with a walkable roof garden.","The National Library of Sejong stands beside the lake."],"travelTips":["Rent a public bike to circle the lake and the centre.","The lake is lit at night, with outdoor performances at weekends.","BRT buses from Daejeon take about 40 minutes."],"bestTime":"April–June and September–October","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["Sejong lake and its floating stage"]},"ko":{"name":"세종호수공원","summary":"행정도시 한가운데의 인공 호수. 나뭇잎 모양 수상무대가 떠 있다.","story":"세종은 수도의 부담을 덜기 위해 처음부터 새로 지은 도시다. 2012년부터 부처들이 옮겨 왔고 도시 전체가 하나의 연속된 계획이다. 그 중심에 다섯 개의 작은 섬과 순환 산책로, 수상무대를 갖춘 넓은 호수가 있다. 건축도 한국의 다른 곳과 다르다. 정부청사는 3km 넘게 이어지고 옥상은 걸을 수 있는 정원이다. 한국이 도시를 처음부터 다시 만들 때 무엇을 하는지 볼 수 있는 곳이다.","facts":["세종은 2012년 출범한 특별자치시다.","호수의 수면 면적은 약 32헥타르다.","정부세종청사는 길이 3.5km가 넘고 옥상정원을 걸을 수 있다.","호숫가에 국립세종도서관이 있다."],"travelTips":["공공자전거로 호수와 도심을 함께 돌아보자.","밤에는 호수에 조명이 들어오고 주말에는 야외 공연이 열린다.","대전에서 BRT 버스로 약 40분이다."],"bestTime":"4~6월, 9~10월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["세종호수와 수상무대"]},"ja":{"name":"世宗湖水公園","summary":"行政都市の中心にある人工湖。葉の形の水上ステージが浮かぶ。","story":"世宗は首都の負担を減らすため一から造られた都市だ。2012年から省庁が移り、都市全体がひとつの連続した計画になっている。その中心に、五つの小島と周回散策路、水上ステージを備えた広い湖がある。建築も韓国の他所とは違う。政府庁舎は3kmを超えて連なり、屋上は歩ける庭園だ。韓国が都市を一から作り直すときに何をするかが見える場所である。","facts":["世宗は2012年に発足した特別自治市。","湖の水面面積は約32ヘクタール。","政府世宗庁舎は全長3.5km超で屋上庭園を歩ける。","湖畔に国立世宗図書館がある。"],"travelTips":["公共自転車で湖と都心を一緒に回ろう。","夜は湖に照明が入り、週末は野外公演もある。","大田からBRTバスで約40分。"],"bestTime":"4〜6月、9〜10月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["世宗湖と水上ステージ"]},"zh":{"name":"世宗湖水公園","summary":"新行政城市中心的人工湖，湖上浮著葉形水上舞台。","story":"世宗是為了替首都減壓而從零建起的城市：各部會自2012年起遷入，整座城市是一份連貫的規劃。它的中心是一座擁有五座小島、環湖跑道與水上舞台的大湖。這裡的建築與韓國他處不同：政府辦公大樓綿延三公里以上，屋頂是可以行走的花園。想看韓國從頭設計一座城市時會做什麼，來這裡就對了。","facts":["世宗於2012年成為特別自治市。","湖面面積約32公頃。","世宗政府辦公大樓長逾3.5公里，屋頂花園可步行。","國立世宗圖書館就在湖畔。"],"travelTips":["租公共單車環湖並逛市中心。","夜裡湖區點燈，週末有戶外表演。","自大田搭BRT公車約40分鐘。"],"bestTime":"4至6月、9至10月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["世宗湖與水上舞台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sejong-arboretum', 'sejong-arboretum', 'sejong', 'Vườn thực vật quốc gia Sejong', 'Sejong National Arboretum', 'park', 127.2475, 36.4995, 'Vườn thực vật đô thị đầu tiên của Hàn Quốc, có nhà kính hình cánh hoa cao 30 mét.', 'Mở cửa năm 2020, đây là vườn thực vật quốc gia đầu tiên đặt ngay trong lòng một thành phố. Điểm nhấn là nhà kính hình cánh hoa: bên trong chia thành vùng khí hậu Địa Trung Hải và vùng nhiệt đới, đi từ ô liu sang cọ chỉ trong vài chục bước. Bên ngoài là hơn hai chục khu vườn chủ đề, trong đó có vườn Hàn Quốc dựng theo lối truyền thống với ao vuông đảo tròn. Mùa xuân hoa tulip, mùa thu cỏ lau — mỗi mùa vườn thay một bộ mặt.', '["Là vườn thực vật quốc gia đầu tiên nằm trong khu đô thị.","Nhà kính chính cao khoảng 32m, hình cánh hoa.","Có hơn 2.000 loài thực vật và 20 khu vườn chủ đề.","Khai trương năm 2020."]', '["Đặt vé trước trên mạng vào cuối tuần và mùa lễ hội hoa.","Đi cùng công viên hồ Sejong ngay cạnh trong một buổi.","Nhà kính nhiệt đới rất ẩm — để áo khoác ở tủ gửi đồ."]', 'Tháng 4–5 và 9–10', '2–3 giờ', '5.000 KRW (thiếu niên 4.000, trẻ em 1.000)', '09:00–17:00; đóng cửa thứ Hai, 1/1 và ngày Tết, Chuseok', '["new"]', '["vườn thực vật","nhà kính","gia đình"]', '[{"seed":"sejong-arboretum","caption":"Nhà kính hình cánh hoa","ratio":"16/9"}]', '["sejong-lake-park"]', 0, 'https://www.koagi.or.kr/sjna/viewngGdnc/useGdnc.jsp', '2026-08-04', '{"en":{"name":"Sejong National Arboretum","summary":"Korea''s first urban national arboretum, with a 30-metre glasshouse shaped like flower petals.","story":"Opened in 2020, this is the country''s first national arboretum built inside a city. Its centrepiece is the petal-shaped glasshouse: inside, a Mediterranean zone gives way to a tropical one, so you pass from olive trees to palms in a few dozen steps. Outside are more than twenty themed gardens, including a Korean garden laid out in the traditional way with a square pond and a round island. Tulips in spring, silver grass in autumn — the garden changes face with the season.","facts":["The first national arboretum located within an urban area.","The main glasshouse is about 32m tall and petal-shaped.","More than 2,000 plant species across 20 themed gardens.","Opened in 2020."],"travelTips":["Book online at weekends and during flower festivals.","Pair it with Sejong Lake Park next door in one outing.","The tropical house is very humid — leave your coat in a locker."],"bestTime":"April–May and September–October","visitDuration":"2–3 hours","ticket":"5,000 KRW (4,000 teens, 1,000 children)","openingHours":"09:00–17:00; closed Mondays, 1 January and the main holidays","galleryCaptions":["The petal-shaped glasshouse"]},"ko":{"name":"국립세종수목원","summary":"한국 최초의 도심형 국립수목원. 꽃잎 모양의 30m 온실이 있다.","story":"2020년 문을 연 이곳은 도시 안에 만든 최초의 국립수목원이다. 백미는 꽃잎 모양의 온실이다. 안으로 들어가면 지중해 구역에서 열대 구역으로 이어져, 올리브나무에서 야자수까지 수십 걸음 만에 건너간다. 밖에는 스무 개가 넘는 주제 정원이 있는데 그중 한국전통정원은 네모난 연못과 둥근 섬을 갖춘 옛 방식으로 조성되었다. 봄에는 튤립, 가을에는 억새로 계절마다 얼굴이 달라진다.","facts":["도심에 자리한 한국 최초의 국립수목원이다.","중심 온실은 높이 약 32m의 꽃잎 형태다.","20개 주제 정원에 2,000종이 넘는 식물이 있다.","2020년에 개원했다."],"travelTips":["주말과 꽃 축제 기간에는 온라인 예약이 안전하다.","바로 옆 세종호수공원과 함께 반나절 코스로 좋다.","열대 온실은 습도가 높으니 겉옷은 사물함에 맡기자."],"bestTime":"4~5월, 9~10월","visitDuration":"2~3시간","ticket":"5,000원(청소년 4,000원, 어린이 1,000원)","openingHours":"09:00~17:00, 월요일과 1월 1일·명절 당일 휴원","galleryCaptions":["꽃잎 모양 온실"]},"ja":{"name":"国立世宗樹木園","summary":"韓国初の都市型国立樹木園。花びらの形をした30mの温室がある。","story":"2020年に開いたここは、都市の中に造られた初の国立樹木園だ。目玉は花びら形の温室で、中に入ると地中海ゾーンから熱帯ゾーンへと続き、オリーブからヤシまで数十歩で渡る。外には二十を超えるテーマ庭園があり、その中の韓国伝統庭園は四角い池と円い島を持つ昔ながらの様式で造られている。春はチューリップ、秋はススキ。季節ごとに顔が変わる。","facts":["都市部に位置する韓国初の国立樹木園。","中心の温室は高さ約32mの花びら形。","20のテーマ庭園に2,000種を超える植物がある。","2020年に開園した。"],"travelTips":["週末と花の祭りの時期はオンライン予約が安心。","隣の世宗湖水公園と合わせて半日コースに。","熱帯温室は湿度が高い。上着はロッカーへ。"],"bestTime":"4〜5月、9〜10月","visitDuration":"2〜3時間","ticket":"5,000ウォン（青少年4,000、子ども1,000）","openingHours":"09:00〜17:00、月曜と1月1日・旧正月・秋夕は休園","galleryCaptions":["花びら形の温室"]},"zh":{"name":"國立世宗樹木園","summary":"韓國首座都市型國立樹木園，有座三十公尺高的花瓣形溫室。","story":"2020年開園，這是韓國第一座建在城市之中的國立樹木園。主角是花瓣形的溫室：入內先是地中海區，再走幾十步便進入熱帶區，從橄欖樹一路到棕櫚。戶外有二十多座主題花園，其中的韓國傳統庭園依古法佈置，方池中有圓島。春天鬱金香、秋天芒草——每個季節換一張臉。","facts":["韓國第一座位於市區的國立樹木園。","主溫室高約32公尺，外形如花瓣。","二十座主題花園中種有逾2,000種植物。","2020年開園。"],"travelTips":["週末與花季期間建議線上預約。","可與隔壁的世宗湖水公園安排成半日行程。","熱帶溫室濕度高，外套請寄放置物櫃。"],"bestTime":"4至5月、9至10月","visitDuration":"2至3小時","ticket":"5,000韓元（青少年4,000、兒童1,000）","openingHours":"09:00–17:00；週一、1月1日與節慶當日休園","galleryCaptions":["花瓣形溫室"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('government-complex-rooftop', 'government-complex-rooftop', 'sejong', 'Vườn mái Toà nhà Chính phủ Sejong', 'Sejong Government Complex Rooftop Garden', 'park', 127.2585, 36.5045, 'Khu vườn trên mái dài ba cây số rưỡi nối liền các bộ, được ghi kỷ lục Guinness.', 'Khi Hàn Quốc dời phần lớn các bộ khỏi Seoul, họ không xây các toà nhà riêng lẻ mà làm một dải công trình uốn lượn nối liền nhau, và phủ toàn bộ mái bằng một khu vườn. Kết quả là vườn mái dài nhất thế giới theo kỷ lục Guinness — ba cây số rưỡi đường đi bộ chạy trên nóc các bộ, với cỏ, cây bụi, hồ nhỏ và các đài quan sát nhìn xuống thành phố mới. Công chức đi ăn trưa trên đó. Khách tham quan phải đăng ký trước và mang giấy tờ tuỳ thân vì đây vẫn là công sở, nhưng thủ tục đơn giản. Đứng trên vườn mái nhìn xuống, bạn thấy rõ một thành phố được vẽ trọn vẹn trước khi có người ở.', '["Vườn mái dài khoảng 3,6 km, được Guinness ghi nhận là dài nhất thế giới.","Phủ trên nóc dãy nhà nối liền của các bộ thuộc Chính phủ Sejong.","Diện tích vườn khoảng 7,9 hecta.","Khách tham quan cần đăng ký trước và mang giấy tờ tuỳ thân."]', '["Đăng ký trước qua trang của Toà nhà Chính phủ; suất có giới hạn theo ngày.","Mang hộ chiếu hoặc CCCD — bắt buộc để qua cổng an ninh.","Đi vào ngày thường; cuối tuần một số khu đóng."]', 'Tháng 4–6 và 9–10', '1,5 giờ', 'Miễn phí, nhưng phải mang giấy tờ tuỳ thân và đặt trước qua Naver (50 người mỗi suất) hoặc đăng ký tại chỗ', 'Ngày ba suất 10:00, 13:30 và 15:30, cả ngày thường lẫn cuối tuần, mỗi lượt 60–90 phút có hướng dẫn viên dẫn. Chỉ mở theo mùa: năm 2026 là 14/3–14/6 và 31/8–29/11; nghỉ dịp lễ và những đợt quá nóng hoặc quá lạnh', '["hidden-gem","verified"]', '["vườn mái","kiến trúc","kỷ lục","thành phố mới"]', '[{"seed":"government-complex-rooftop","caption":"Lối đi trên vườn mái nối các bộ","ratio":"16/9"}]', '["sejong-lake-park","sejong-arboretum"]', 1, 'https://gbmo.go.kr/chungsa/cm/cntnts/cntntsView.do?mi=1160&cntntsId=1044', '2026-08-05', '{"en":{"name":"Sejong Government Complex Rooftop Garden","summary":"A rooftop garden three and a half kilometres long linking the ministries, and a Guinness record.","story":"When Korea moved most of its ministries out of Seoul it did not build separate blocks but one continuous curving structure — and covered the entire roof with a garden. The result is the longest rooftop garden in the world by Guinness: three and a half kilometres of walkway running over the ministries, with grass, shrubs, small ponds and viewpoints over the new city. Civil servants walk it at lunch. Visitors must register in advance and bring ID because this is still a government building, but the process is simple. Standing on the roof looking down, you can see a city drawn whole before anyone lived in it.","facts":["The rooftop garden runs about 3.6km, recognised by Guinness as the world''s longest.","It covers the continuous roofline of the Sejong government ministries.","The garden area is about 7.9 hectares.","Visitors must register in advance and carry identification."],"travelTips":["Register through the government complex website; daily places are limited.","Bring a passport or ID card — required to pass security.","Come on a weekday; some sections close at weekends."],"bestTime":"April–June and September–October","visitDuration":"1.5 hours","ticket":"Free, but bring photo ID and book ahead on Naver (50 people per session) or register on site","openingHours":"Three guided sessions a day at 10:00, 13:30 and 15:30, weekdays and weekends alike, each lasting 60–90 minutes. It only runs in seasonal windows: in 2026, 14 March–14 June and 31 August–29 November; closed on major holidays and during extreme heat or cold","galleryCaptions":["The walkway along the ministries'' rooftop garden"]},"ko":{"name":"정부세종청사 옥상정원","summary":"부처들을 잇는 3.5km의 옥상정원. 기네스에 세계 최장으로 올랐다.","story":"한국이 부처 대부분을 서울 밖으로 옮길 때 개별 건물을 세우는 대신 굽이치며 이어지는 하나의 구조를 지었고, 그 지붕 전체를 정원으로 덮었다. 그 결과가 기네스가 인정한 세계에서 가장 긴 옥상정원이다. 부처들 위로 3.5km의 보행로가 이어지고 잔디와 관목, 작은 연못, 신도시를 내려다보는 전망대가 있다. 공무원들은 점심시간에 그 위를 걷는다. 관람객은 미리 신청하고 신분증을 지참해야 한다. 여전히 관공서이기 때문인데 절차는 간단하다. 옥상에서 내려다보면, 사람이 살기 전에 통째로 그려진 도시가 그대로 보인다.","facts":["옥상정원은 약 3.6km로 기네스가 세계 최장으로 인정했다.","정부세종청사의 이어진 지붕 전체를 덮는다.","정원 면적은 약 7.9헥타르다.","관람객은 사전 신청과 신분증 지참이 필요하다."],"travelTips":["정부청사 누리집에서 미리 신청하자. 하루 인원이 제한된다.","여권이나 신분증을 챙기자. 보안 검색에 필요하다.","평일에 가자. 주말에는 일부 구간이 닫힌다."],"bestTime":"4~6월, 9~10월","visitDuration":"1.5시간","ticket":"무료지만 신분증이 필수이며 네이버 사전예약(회당 50명) 또는 현장접수로 참여한다","openingHours":"평일·주말 하루 3회(10:00, 13:30, 15:30) 안내원 인솔로 60~90분간 진행된다. 운영기간은 2026년 상반기 3.14~6.14, 하반기 8.31~11.29이며 명절과 혹서기·혹한기에는 쉰다","galleryCaptions":["부처들을 잇는 옥상정원의 보행로"]},"ja":{"name":"政府世宗庁舎屋上庭園","summary":"省庁をつなぐ3.5kmの屋上庭園。ギネスに世界最長として登録された。","story":"韓国が省庁の大半をソウルの外へ移すとき、個別の建物を建てる代わりに、うねりながら連なるひとつの構造を造り、その屋根全体を庭園で覆った。結果はギネスが認めた世界最長の屋上庭園である。省庁の上を三・五キロの歩道が走り、芝と低木、小さな池、新都市を見下ろす展望台がある。公務員は昼休みにその上を歩く。来訪者は事前登録と身分証の持参が要る。ここが依然として官庁だからだが、手続きは簡単だ。屋上から見下ろすと、人が住む前に丸ごと描かれた都市がそのまま見える。","facts":["屋上庭園は約3.6kmで、ギネスが世界最長と認めている。","政府世宗庁舎の連なる屋根全体を覆っている。","庭園の面積は約7.9ヘクタール。","来訪者は事前登録と身分証の持参が必要である。"],"travelTips":["政府庁舎のサイトで事前に申し込もう。一日の人数に制限がある。","パスポートか身分証を持参しよう。保安検査で必要だ。","平日に行こう。週末は一部区間が閉じる。"],"bestTime":"4〜6月、9〜10月","visitDuration":"1.5時間","ticket":"無料だが身分証が必須で、Naverの事前予約（1回50名）または現地受付が必要","openingHours":"平日・週末とも1日3回（10:00、13:30、15:30）、案内員の引率で60〜90分。運営期間は2026年は3/14〜6/14と8/31〜11/29で、祝祭日や酷暑・酷寒期は休止","galleryCaptions":["省庁をつなぐ屋上庭園の歩道"]},"zh":{"name":"世宗政府辦公大樓屋頂花園","summary":"串起各部會、長三點五公里的屋頂花園，並列入金氏世界紀錄。","story":"韓國把多數部會遷出首爾時，沒有蓋一棟棟獨立的樓房，而是造了一條連綿起伏的建築，並把整片屋頂鋪成花園。結果是金氏世界紀錄認證的全球最長屋頂花園：三點五公里的步道橫越各部會上方，有草地、灌木、小水池，以及俯瞰這座新城的觀景點。公務員午休時就在上面散步。訪客須事先登記並攜帶證件，因為這裡終究是官署，不過手續並不複雜。站在屋頂往下看，你會清楚看見一座在有人入住之前就被整體畫好的城市。","facts":["屋頂花園長約3.6公里，經金氏世界紀錄認證為全球最長。","覆蓋世宗政府辦公大樓連續的屋頂。","花園面積約7.9公頃。","訪客須事先登記並攜帶身分證件。"],"travelTips":["請先透過政府辦公大樓網站登記，每日名額有限。","攜帶護照或身分證，通過安檢時需要。","挑平日前往；週末部分區段不開放。"],"bestTime":"4至6月與9至10月","visitDuration":"1.5小時","ticket":"免費，但須攜帶身分證件，並透過Naver預約（每場50人）或現場報名","openingHours":"平日與週末每日三場（10:00、13:30、15:30），由導覽人員帶領，約60至90分鐘。僅於特定期間開放：2026年為3月14日至6月14日、8月31日至11月29日；節慶與酷暑酷寒期間停辦","galleryCaptions":["串連各部會的屋頂花園步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bimatgil-geumgang', 'bimatgil-geumgang', 'sejong', 'Đường ven sông Geumgang & cầu Ihan', 'Geumgang Riverside & Ihan Bridge', 'bridge', 127.2915, 36.4915, 'Cầu đi bộ hai tầng bắc qua sông Geumgang, tầng trên có mái che chạy vòng thành hình elip.', 'Sông Geumgang chảy ngang Sejong và chia thành phố làm hai, nên khi quy hoạch người ta đặt vào đó một cây cầu chỉ dành cho người đi bộ và xe đạp. Cầu Ihan có hai tầng: tầng dưới cho xe đạp, tầng trên có mái che cho người đi bộ, và cả hai uốn thành hình elip khép kín nên đi hết một vòng là quay lại chỗ cũ mà không phải đi ngược. Ban đêm cầu lên đèn đổi màu và soi xuống mặt sông. Hai bờ là đường ven sông dài hàng chục cây số với ruộng hoa cải vào mùa xuân, cỏ lau vào mùa thu, và các trạm thuê xe đạp công cộng.', '["Cầu Ihan là cầu đi bộ hai tầng, dài khoảng 1,4 km kể cả vòng elip.","Tầng dưới dành cho xe đạp, tầng trên có mái che cho người đi bộ.","Hình elip khép kín cho phép đi một vòng mà không phải quay đầu.","Đường ven sông Geumgang có các trạm thuê xe đạp công cộng."]', '["Đi buổi tối để xem đèn cầu đổi màu trên mặt sông.","Thuê xe đạp công cộng để đi hết tuyến ven sông.","Tháng 4 có ruộng hoa cải vàng, tháng 10 có cỏ lau dọc bờ."]', 'Tháng 4–6 và 9–10', '1,5–2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["cầu đi bộ","sông","đạp xe","về đêm"]', '[{"seed":"bimatgil-geumgang","caption":"Cầu Ihan lên đèn trên sông Geumgang","ratio":"16/9"}]', '["sejong-lake-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Geumgang Riverside & Ihan Bridge","summary":"A two-level footbridge over the Geumgang, its upper deck roofed and looped into an ellipse.","story":"The Geumgang runs through Sejong and divides the city in two, so the planners put a bridge across it for pedestrians and cyclists only. Ihan bridge has two levels: bicycles below, a roofed walkway above, and both curve into a closed ellipse, so walking the full loop brings you back without retracing your steps. At night it lights in shifting colours reflected on the water. Both banks carry riverside paths running tens of kilometres, with rapeseed fields in spring, silver grass in autumn, and public bike stations along the way.","facts":["Ihan bridge is a two-level footbridge, about 1.4km including the elliptical loop.","The lower deck is for bicycles, the roofed upper deck for pedestrians.","The closed elliptical form lets you walk a full circuit without turning back.","The Geumgang riverside path has public bike hire stations along it."],"travelTips":["Come in the evening to see the bridge lights shift on the water.","Hire a public bike to cover the riverside route properly.","April brings rapeseed fields, October silver grass along the banks."],"bestTime":"April–June and September–October","visitDuration":"1.5–2 hours","ticket":"","openingHours":"All day","galleryCaptions":["Ihan bridge lit over the Geumgang"]},"ko":{"name":"금강 보행교(이응다리)","summary":"금강을 건너는 2층 보행교. 위층은 지붕이 있고 전체가 타원으로 이어진다.","story":"금강은 세종을 가로질러 도시를 둘로 나눈다. 그래서 계획 단계에서 보행자와 자전거만 다니는 다리를 놓았다. 이응다리는 두 층이다. 아래층은 자전거, 위층은 지붕 덮인 보행로이고, 두 층 모두 닫힌 타원으로 휘어 한 바퀴 돌면 되돌아 걷지 않고 제자리로 온다. 밤이면 색이 바뀌는 조명이 켜져 수면에 비친다. 양쪽 기슭에는 수십 킬로미터의 강변길이 이어지고, 봄에는 유채밭, 가을에는 억새, 그리고 공공자전거 대여소가 놓여 있다.","facts":["이응다리는 2층 보행교로 타원 구간을 포함해 약 1.4km다.","아래층은 자전거, 위층은 지붕 덮인 보행로다.","닫힌 타원 형태여서 되돌아 걷지 않고 한 바퀴 돌 수 있다.","금강 강변길에는 공공자전거 대여소가 있다."],"travelTips":["저녁에 가면 수면에 비치는 조명이 바뀌는 것을 볼 수 있다.","강변길을 제대로 돌려면 공공자전거를 빌리자.","4월에는 유채밭, 10월에는 억새가 강변을 채운다."],"bestTime":"4~6월, 9~10월","visitDuration":"1.5~2시간","ticket":"","openingHours":"상시","galleryCaptions":["금강 위에 불이 켜진 이응다리"]},"ja":{"name":"錦江歩行橋（イウン橋）","summary":"錦江を渡る二層の歩行橋。上層には屋根があり、全体が楕円に閉じる。","story":"錦江は世宗を横切り都市を二つに分ける。だから計画の段階で、歩行者と自転車だけの橋を架けた。イウン橋は二層だ。下層は自転車、上層は屋根つきの歩行路で、どちらも閉じた楕円に湾曲しているので、一周すれば引き返さずに元の場所へ戻る。夜には色の変わる照明が灯り、水面に映る。両岸には数十キロの河川敷の道が続き、春は菜の花畑、秋はススキ、そして公共自転車の貸出所が並ぶ。","facts":["イウン橋は二層の歩行橋で、楕円部分を含め約1.4km。","下層は自転車、上層は屋根つきの歩行路である。","閉じた楕円形なので引き返さずに一周できる。","錦江の河川敷の道には公共自転車の貸出所がある。"],"travelTips":["夕方に行けば水面に映る照明の変化が見られる。","河川敷をきちんと巡るなら公共自転車を借りよう。","4月は菜の花畑、10月は岸辺のススキがよい。"],"bestTime":"4〜6月、9〜10月","visitDuration":"1.5〜2時間","ticket":"","openingHours":"終日","galleryCaptions":["錦江に灯るイウン橋"]},"zh":{"name":"錦江人行橋（이응다리）","summary":"橫跨錦江的雙層人行橋，上層有頂棚，整座橋彎成一個封閉的橢圓。","story":"錦江橫穿世宗，把城市分成兩半，所以規劃時便在江上架了一座只供行人與自行車通行的橋。이응橋分成兩層：下層走自行車，上層是有頂棚的步道，兩層都彎成封閉的橢圓，因此走完一圈會回到原點，不必原路折返。入夜後橋上亮起變換色彩的燈光，映在江面上。兩岸則是綿延數十公里的濱江步道，春天有油菜花田，秋天有芒草，沿途還設有公共自行車租借站。","facts":["이응橋是雙層人行橋，含橢圓段全長約1.4公里。","下層供自行車通行，上層為有頂棚的人行道。","封閉的橢圓造型讓人不必折返即可走完一圈。","錦江濱江步道沿線設有公共自行車租借站。"],"travelTips":["傍晚前來，可看橋燈在江面上變換顏色。","想完整走完濱江路線，租一台公共自行車。","4月有油菜花田，10月兩岸是芒草。"],"bestTime":"4至6月與9至10月","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["錦江上亮起燈光的이응橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('birds-nest-library', 'birds-nest-library', 'sejong', 'Thư viện Quốc gia Sejong', 'National Library of Korea, Sejong', 'museum', 127.2565, 36.5025, 'Thư viện hình trang sách đang lật, xây riêng để phục vụ việc hoạch định chính sách của cả nước.', 'Toà nhà này được thiết kế theo hình một trang sách đang được lật lên — mái vươn cong ra rồi hạ xuống, và mặt kính bên dưới phản chiếu hồ Sejong ngay trước cửa. Đây không phải thư viện công cộng thông thường: nó là chi nhánh chuyên về chính sách của Thư viện Quốc gia, phục vụ các bộ vừa dời về Sejong, nên bộ sưu tập nghiêng hẳn về nghiên cứu chính sách và tư liệu hành chính. Nhưng tầng dành cho công chúng thì mở cho tất cả, và không gian đọc nhìn thẳng ra mặt hồ có lẽ là chỗ đọc sách đẹp nhất trong thành phố này. Nhiều người tới chỉ để ngồi ở đó.', '["Mở cửa năm 2013, là chi nhánh chuyên ngành chính sách của Thư viện Quốc gia Hàn Quốc.","Hình dáng toà nhà mô phỏng một trang sách đang được lật.","Phục vụ chủ yếu các bộ ngành đặt trụ sở tại Sejong.","Tầng dành cho công chúng mở cửa tự do và nhìn ra hồ Sejong."]', '["Không cần thẻ để vào khu vực dành cho công chúng.","Chỗ ngồi nhìn ra hồ hết nhanh vào cuối tuần.","Ngay cạnh công viên hồ Sejong, dễ ghép chung buổi."]', 'Quanh năm', '1 giờ', '', 'Ngày thường 09:00–21:00, cuối tuần 09:00–18:00; nghỉ thứ Hai tuần thứ hai và thứ tư hằng tháng, cùng các ngày lễ', '["hidden-gem"]', '["thư viện","kiến trúc","hồ","yên tĩnh"]', '[{"seed":"birds-nest-library","caption":"Thư viện hình trang sách bên hồ Sejong","ratio":"16/9"}]', '["sejong-lake-park","sejong-arboretum"]', 0, 'https://sejong.nl.go.kr/', '2026-08-05', '{"en":{"name":"National Library of Korea, Sejong","summary":"A library shaped like a turning page, built to serve the country''s policy-making.","story":"The building is designed as a page being turned — the roof lifts in a curve and settles, and the glass beneath reflects Sejong lake in front of it. This is not an ordinary public library: it is the policy branch of the National Library, serving the ministries newly moved to Sejong, so the collection leans heavily towards policy research and administrative records. But the public floor is open to everyone, and the reading space facing the lake is probably the finest place to read in this city. Plenty of people come only to sit there.","facts":["Opened in 2013 as the policy branch of the National Library of Korea.","The building''s form is modelled on a page being turned.","It mainly serves the ministries based in Sejong.","The public floor is freely open and faces Sejong lake."],"travelTips":["No card is needed for the public floor.","Seats facing the lake go quickly at weekends.","It sits beside Sejong Lake Park, easy to combine."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"","openingHours":"09:00–21:00 on weekdays, 09:00–18:00 at weekends; closed the second and fourth Monday of each month and on public holidays","galleryCaptions":["The page-shaped library beside Sejong lake"]},"ko":{"name":"국립세종도서관","summary":"책장을 넘기는 모양의 도서관. 나라의 정책 수립을 돕기 위해 지어졌다.","story":"이 건물은 넘어가는 책장의 모양으로 설계되었다. 지붕이 곡선으로 들렸다가 내려앉고, 그 아래 유리면이 바로 앞의 세종호수를 비춘다. 여기는 보통의 공공도서관이 아니다. 국립중앙도서관의 정책 분관으로, 세종으로 옮겨 온 부처들을 위해 만들어졌기에 장서가 정책 연구와 행정 자료 쪽으로 크게 기울어 있다. 하지만 일반 이용 층은 누구에게나 열려 있고, 호수를 마주 보는 열람 공간은 아마 이 도시에서 책 읽기 가장 좋은 자리일 것이다. 그 자리에 앉으려고만 오는 사람도 많다.","facts":["2013년 개관한 국립중앙도서관의 정책 분관이다.","건물의 형태는 넘어가는 책장을 본떴다.","주로 세종에 자리한 부처들을 지원한다.","일반 이용 층은 자유롭게 열려 있고 세종호수를 마주 본다."],"travelTips":["일반 이용 층은 회원증 없이 들어갈 수 있다.","호수를 마주 보는 자리는 주말이면 금방 찬다.","세종호수공원 바로 옆이라 함께 묶기 좋다."],"bestTime":"연중","visitDuration":"1시간","ticket":"","openingHours":"평일 09:00~21:00, 주말 09:00~18:00. 매월 둘째·넷째 월요일과 공휴일 휴관","galleryCaptions":["세종호수 옆의 책장 모양 도서관"]},"ja":{"name":"国立世宗図書館","summary":"めくられる書物のかたちの図書館。国の政策づくりを支えるために建てられた。","story":"この建物はめくられる書物のかたちで設計された。屋根が曲線で持ち上がって降り、その下のガラス面が目の前の世宗湖を映す。ここは普通の公共図書館ではない。国立中央図書館の政策分館で、世宗へ移ってきた省庁のために造られたので、蔵書は政策研究と行政資料に大きく偏っている。だが一般利用の階は誰にでも開かれており、湖に面した閲覧空間はおそらくこの街で最も本を読むのに向いた場所だ。そこに座るためだけに来る人も多い。","facts":["2013年開館、国立中央図書館の政策分館である。","建物の形はめくられる書物を模している。","主に世宗に移転した省庁を支援する。","一般利用の階は自由に開かれ、世宗湖に面している。"],"travelTips":["一般利用の階に会員証は要らない。","湖に面した席は週末にはすぐ埋まる。","世宗湖水公園のすぐ隣なので合わせやすい。"],"bestTime":"通年","visitDuration":"1時間","ticket":"","openingHours":"平日09:00〜21:00、週末09:00〜18:00。毎月第2・第4月曜と祝日は休館","galleryCaptions":["世宗湖のほとりの書物型の図書館"]},"zh":{"name":"國立世宗圖書館","summary":"造型如一頁正被翻開的書，為支援國家政策研擬而建。","story":"這棟建築以一頁正被翻開的書為造型：屋頂以曲線揚起再落下，底下的玻璃面映著門前的世宗湖。它並非一般的公共圖書館，而是國立中央圖書館的政策分館，為遷來世宗的各部會而設，因此館藏大幅偏向政策研究與行政檔案。不過開放給一般民眾的樓層人人可入，而那片面湖的閱覽空間，大概是這座城市裡最適合讀書的位置。不少人來，就只是為了坐在那裡。","facts":["2013年開館，是國立中央圖書館的政策分館。","建築造型取自一頁正被翻開的書。","主要服務遷至世宗的各部會。","開放樓層自由進出，正對世宗湖。"],"travelTips":["進入開放樓層不需要借閱證。","面湖的座位週末很快就被坐滿。","緊鄰世宗湖水公園，很容易一併安排。"],"bestTime":"全年","visitDuration":"1小時","ticket":"","openingHours":"平日09:00–21:00，週末09:00–18:00；每月第二與第四個週一及國定假日休館","galleryCaptions":["世宗湖畔如書頁般的圖書館"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeonju-hanok-village', 'jeonju-hanok-village', 'jeonbuk', 'Làng Hanok Jeonju', 'Jeonju Hanok Village', 'village', 127.1525, 35.8155, 'Hơn 700 nếp nhà gỗ quần tụ giữa lòng thành phố, và cái nôi của món bibimbap.', 'Không đâu ở Hàn Quốc có nhiều hanok tập trung như Jeonju: hơn bảy trăm căn nằm liền nhau, mái ngói đen nối thành sóng khi nhìn từ đài quan sát Omokdae. Jeonju là quê gốc của dòng họ Yi lập ra triều Joseon, và cũng là kinh đô ẩm thực của cả nước — bibimbap Jeonju được dọn trong tô đồng với hơn ba chục nguyên liệu, cơm nấu bằng nước hầm xương. Buổi tối, đèn lồng thắp dọc các con hẻm, và mùi bánh gạo chiên bay khắp phố ăn vặt.', '["Có hơn 700 ngôi hanok, khu tập trung lớn nhất Hàn Quốc.","Jeonju được UNESCO công nhận Thành phố Ẩm thực Sáng tạo năm 2012.","Bibimbap Jeonju là một trong ba biến thể nổi tiếng nhất của món này.","Nhà thờ Jeondong bằng gạch đỏ xây năm 1914, ngay cửa làng."]', '["Ngủ lại một đêm trong hanok để cảm nhận sàn ondol ấm.","Lên Omokdae vào chiều muộn để chụp toàn cảnh mái ngói.","Thử makgeolli Jeonju — gọi một bình là được kèm cả mâm đồ nhắm."]', 'Tháng 4–5 và 9–11', 'Nửa ngày', '', 'Cả ngày', '["popular","verified"]', '["hanok","ẩm thực","bibimbap"]', '[{"seed":"jeonju-hanok-village","caption":"Mái ngói làng hanok Jeonju","ratio":"16/9"}]', '["naejangsan","maisan"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Jeonju Hanok Village","summary":"More than 700 wooden houses gathered in the middle of the city — and the birthplace of bibimbap.","story":"Nowhere else in Korea has so many hanok in one place: more than seven hundred stand side by side, their black tiled roofs forming waves when seen from the Omokdae viewpoint. Jeonju is the ancestral home of the Yi clan who founded the Joseon dynasty, and it is also the country''s food capital — Jeonju bibimbap is served in a brass bowl with more than thirty ingredients, its rice cooked in beef broth. In the evening lanterns light the lanes and the smell of fried rice cakes drifts through the snack street.","facts":["More than 700 hanok houses, the largest concentration in Korea.","Jeonju was named a UNESCO Creative City of Gastronomy in 2012.","Jeonju bibimbap is one of the three most famous versions of the dish.","Jeondong Catholic Church, built of red brick in 1914, stands at the village gate."],"travelTips":["Stay a night in a hanok to feel the warm ondol floor.","Climb Omokdae in late afternoon for the roofscape photograph.","Try Jeonju makgeolli — order a kettle and a table of side dishes comes with it."],"bestTime":"April–May and September–November","visitDuration":"Half a day","ticket":"","openingHours":"All day","galleryCaptions":["Tiled roofs of Jeonju hanok village"]},"ko":{"name":"전주한옥마을","summary":"도심 한가운데 700채가 넘는 한옥. 비빔밥의 본향이다.","story":"한국 어디에도 이만큼 한옥이 모인 곳은 없다. 700채가 넘는 집이 나란히 서서, 오목대에서 내려다보면 검은 기와가 물결을 이룬다. 전주는 조선을 세운 이씨 왕가의 본향이자 나라의 음식 수도다. 전주비빔밥은 놋그릇에 서른 가지가 넘는 재료를 올리고 밥은 사골 국물로 짓는다. 저녁이면 골목마다 등이 걸리고 먹거리 골목에는 기름에 지진 떡 냄새가 퍼진다.","facts":["700채가 넘는 한옥이 모인, 한국 최대의 한옥 밀집지다.","전주는 2012년 유네스코 음식창의도시로 지정되었다.","전주비빔밥은 가장 유명한 세 가지 비빔밥 가운데 하나다.","마을 입구의 전동성당은 1914년 붉은 벽돌로 지어졌다."],"travelTips":["한옥에서 하룻밤 자며 따뜻한 온돌을 느껴보자.","늦은 오후 오목대에 올라 지붕 풍경을 담자.","전주 막걸리는 한 주전자를 시키면 안주 한 상이 함께 나온다."],"bestTime":"4~5월, 9~11월","visitDuration":"반나절","ticket":"","openingHours":"상시","galleryCaptions":["전주한옥마을의 기와지붕"]},"ja":{"name":"全州韓屋村","summary":"街の真ん中に700棟を超える韓屋。ビビンバの本場でもある。","story":"韓国のどこにもこれほど韓屋が集まる場所はない。700棟を超える家が並び、梧木台から見下ろすと黒瓦が波を成す。全州は朝鮮を建てた李氏の本貫であり、国の食の都でもある。全州ビビンバは真鍮の器に三十種を超える具を載せ、飯は牛骨の出汁で炊く。夕方には路地ごとに提灯が灯り、屋台通りには焼いた餅の香りが流れる。","facts":["700棟を超える韓屋が集まる韓国最大の韓屋密集地。","全州は2012年にユネスコ食文化創造都市に選ばれた。","全州ビビンバは最も有名な三つのビビンバのひとつ。","村の入口の殿洞聖堂は1914年に赤煉瓦で建てられた。"],"travelTips":["韓屋で一泊し、温かいオンドルを体験しよう。","午後遅くに梧木台へ登れば屋根並みの写真が撮れる。","全州マッコリはやかん一つ頼むとつまみが一膳ついてくる。"],"bestTime":"4〜5月、9〜11月","visitDuration":"半日","ticket":"","openingHours":"終日","galleryCaptions":["全州韓屋村の瓦屋根"]},"zh":{"name":"全州韓屋村","summary":"市中心聚集七百多棟木造韓屋，也是拌飯的故鄉。","story":"韓國沒有第二個地方有這麼多韓屋聚在一起：七百多棟比鄰而立，從梧木台望下去，黑瓦屋頂連成波浪。全州是開創朝鮮王朝的李氏本貫，也是全國的美食之都——全州拌飯以黃銅碗盛裝，配料超過三十種，米飯以牛骨高湯炊煮。入夜後巷弄掛起燈籠，小吃街飄著煎年糕的香氣。","facts":["七百多棟韓屋，是韓國最大的韓屋聚落。","全州於2012年獲選為聯合國教科文組織美食創意城市。","全州拌飯是最著名的三種拌飯之一。","村口的殿洞聖堂建於1914年，以紅磚砌成。"],"travelTips":["在韓屋住一晚，感受溫熱的暖炕。","傍晚登上梧木台，可拍下屋頂連成片的畫面。","點一壺全州馬格利，會附上一整桌下酒菜。"],"bestTime":"4至5月、9至11月","visitDuration":"半天","ticket":"","openingHours":"全日","galleryCaptions":["全州韓屋村的瓦頂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('naejangsan', 'naejangsan', 'jeonbuk', 'Vườn quốc gia Naejangsan', 'Naejangsan National Park', 'mountain', 126.889, 35.4855, 'Được coi là nơi lá đỏ đẹp nhất Hàn Quốc, với đường hầm phong dài 100 mét.', 'Mỗi cuối tháng 10, cả nước đổ về Naejangsan. Con đường dẫn vào chùa Naejangsa có hàng phong trồng hai bên khép tán thành một đường hầm đỏ rực dài chừng trăm mét — bức ảnh mùa thu quen thuộc nhất của Hàn Quốc được chụp ở đây. Vòng núi hình móng ngựa bao quanh thung lũng, nên đứng ở đâu cũng thấy màu đỏ cam vàng xếp lớp. Cáp treo đưa khách lên đài quan sát nếu không muốn leo.', '["Là vườn quốc gia nổi tiếng nhất Hàn Quốc về lá thu.","Đường hầm phong dẫn vào chùa Naejangsa dài khoảng 100m.","Chùa Naejangsa được dựng năm 636.","Các đỉnh núi tạo thành vòng cung như móng ngựa quanh thung lũng."]', '["Cuối tháng 10 đến đầu tháng 11 là đỉnh mùa lá đỏ — cực đông.","Đi bằng tàu tới Jeongeup rồi bắt bus khoảng 30 phút.","Đi sớm trước 8h sáng nếu muốn chụp đường hầm phong vắng người."]', 'Cuối tháng 10 đến đầu tháng 11', 'Nửa ngày', '', 'Theo giờ vườn quốc gia', '["popular"]', '["mùa thu","lá đỏ","vườn quốc gia"]', '[{"seed":"naejangsan","caption":"Đường hầm phong mùa thu","ratio":"16/9"}]', '["jeonju-hanok-village"]', 0, 'https://en.wikipedia.org/wiki/Naejangsan', '2026-08-04', '{"en":{"name":"Naejangsan National Park","summary":"Widely held to have Korea''s finest autumn colour, with a hundred-metre tunnel of maples.","story":"Every late October the country comes to Naejangsan. The approach to Naejangsa temple is lined with maples that close overhead into a burning red tunnel about a hundred metres long — the most familiar autumn photograph in Korea is taken here. The peaks form a horseshoe around the valley, so wherever you stand the red, orange and yellow are layered. A cable car carries you to a viewpoint if you would rather not climb.","facts":["The most famous national park in Korea for autumn leaves.","The maple tunnel to Naejangsa temple runs about 100m.","Naejangsa temple was founded in 636.","The peaks form a horseshoe ridge around the valley."],"travelTips":["Late October to early November is the peak — and extremely crowded.","Take the train to Jeongeup, then a bus of about 30 minutes.","Arrive before 8am to photograph the maple tunnel without people."],"bestTime":"Late October to early November","visitDuration":"Half a day","ticket":"","openingHours":"National park hours","galleryCaptions":["The autumn maple tunnel"]},"ko":{"name":"내장산국립공원","summary":"한국 최고의 단풍으로 꼽히는 산. 100m 단풍 터널이 있다.","story":"해마다 10월 말이면 전국이 내장산으로 모인다. 내장사로 가는 길에 심어진 단풍나무가 머리 위에서 맞닿아 100m쯤 되는 붉은 터널을 이룬다. 한국의 가을 사진 가운데 가장 익숙한 장면이 여기서 찍힌다. 봉우리들이 계곡을 말굽처럼 감싸고 있어 어디에 서도 붉고 주황이고 노란 색이 층층이 겹친다. 오르기 부담스럽다면 케이블카로 전망대까지 갈 수 있다.","facts":["가을 단풍으로 한국에서 가장 유명한 국립공원이다.","내장사로 이어지는 단풍 터널은 약 100m다.","내장사는 636년에 창건되었다.","봉우리들이 계곡을 둘러싸 말굽 모양 능선을 이룬다."],"travelTips":["10월 말~11월 초가 절정이며 그만큼 매우 붐빈다.","기차로 정읍까지 간 뒤 버스로 30분이면 닿는다.","사람 없는 단풍 터널을 담으려면 오전 8시 전에 도착하자."],"bestTime":"10월 말~11월 초","visitDuration":"반나절","ticket":"","openingHours":"국립공원 운영시간","galleryCaptions":["가을 단풍 터널"]},"ja":{"name":"内蔵山国立公園","summary":"韓国一の紅葉とされる山。100mのカエデのトンネルがある。","story":"毎年10月末、全国が内蔵山に集まる。内蔵寺へ続く道に植えられたカエデが頭上で触れ合い、100mほどの赤いトンネルを作る。韓国の秋の写真で最も見慣れた一枚はここで撮られる。峰々が谷を馬蹄形に囲むので、どこに立っても赤と橙と黄が層を成す。登るのが大変ならケーブルカーで展望台まで行ける。","facts":["秋の紅葉で韓国最も有名な国立公園。","内蔵寺へ続くカエデのトンネルは約100m。","内蔵寺は636年に創建された。","峰々が谷を囲み馬蹄形の稜線を成す。"],"travelTips":["10月末〜11月初めが最盛期で、その分非常に混む。","列車で井邑まで行き、バスで30分ほど。","人のいないカエデのトンネルを撮るなら朝8時前に。"],"bestTime":"10月末〜11月初め","visitDuration":"半日","ticket":"","openingHours":"国立公園の運営時間","galleryCaptions":["秋のカエデのトンネル"]},"zh":{"name":"內藏山國立公園","summary":"公認韓國最美的秋色，有一條百公尺長的楓葉隧道。","story":"每年十月底，全國都湧向內藏山。通往內藏寺的路兩旁楓樹在頭頂交會，形成約百公尺的火紅隧道——韓國秋天最為人熟悉的那張照片就是在這裡拍的。峰群像馬蹄一樣圍住山谷，因此站在任何角度，紅、橙、黃都層層疊疊。不想爬山可搭纜車到觀景台。","facts":["韓國最著名的賞楓國立公園。","通往內藏寺的楓葉隧道約長100公尺。","內藏寺創建於636年。","群峰環抱山谷，形成馬蹄形稜線。"],"travelTips":["十月底至十一月初是高峰期，也極為擁擠。","搭火車到井邑，再轉公車約30分鐘。","想拍沒有人的楓葉隧道，請在早上八點前抵達。"],"bestTime":"10月底至11月初","visitDuration":"半天","ticket":"","openingHours":"依國立公園時間","galleryCaptions":["秋天的楓葉隧道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('maisan', 'maisan', 'jeonbuk', 'Núi Maisan & chùa Tapsa', 'Maisan & Tapsa Stone Pagodas', 'mountain', 127.404, 35.762, 'Hai đỉnh núi hình tai ngựa, dưới chân là hơn 80 ngọn tháp đá do một người xếp bằng tay.', 'Maisan có hai đỉnh đá dựng đứng cạnh nhau, nhìn xa đúng như hai vành tai ngựa nhô lên khỏi rừng. Dưới chân núi, một người tu hành tên Yi Gap-yong đã dành ba mươi năm cuối đời xếp hơn tám mươi ngọn tháp đá — không vữa, không khung, chỉ đá chồng đá — và chúng vẫn đứng nguyên qua bão hơn một thế kỷ. Không ai giải thích được vì sao chúng không đổ. Mùa xuân, hoa anh đào phủ kín con đường dẫn vào chùa Tapsa.', '["Hai đỉnh Ammaisan (686m) và Sumaisan (678m) đứng liền nhau.","Hơn 80 tháp đá do Yi Gap-yong xếp trong giai đoạn 1885–1917.","Các tháp xếp khô hoàn toàn, không dùng chất kết dính.","Là Danh thắng quốc gia số 12 của Hàn Quốc."]', '["Cổng phía nam gần chùa Tapsa hơn, đỡ phải leo nhiều.","Cuối tháng 4 hoa anh đào nở dọc đường vào rất đẹp.","Cần xe riêng hoặc bus từ Jinan, xe công cộng khá thưa."]', 'Tháng 4 và 10–11', '3 giờ', 'Vào công viên tỉnh miễn phí; riêng chùa Tapsa 3.000 KRW (học sinh 2.000, trẻ em 1.000) — Tapsa chỉ có di sản cấp tỉnh nên không thuộc diện bỏ phí năm 2023', '08:00–18:00', '["hidden-gem"]', '["núi","tháp đá","chùa"]', '[{"seed":"maisan","caption":"Tháp đá dưới chân Maisan","ratio":"16/9"}]', '["jeonju-hanok-village"]', 0, 'https://www.jinan.go.kr/maisan/index.jinan', '2026-08-04', '{"en":{"name":"Maisan & Tapsa Stone Pagodas","summary":"Two peaks shaped like horse''s ears, with more than 80 stone pagodas stacked by hand below them.","story":"Maisan has two rock peaks standing side by side which, from a distance, look exactly like a pair of horse''s ears rising from the forest. Below them, a hermit named Yi Gap-yong spent the last thirty years of his life stacking more than eighty stone pagodas — no mortar, no frame, only stone on stone — and they have stood through a century of storms. No one has fully explained why they don''t fall. In spring, cherry blossom covers the road to Tapsa temple.","facts":["The twin peaks Ammaisan (686m) and Sumaisan (678m) stand together.","More than 80 stone pagodas were built by Yi Gap-yong between 1885 and 1917.","They are stacked entirely dry, without any binding material.","Designated National Scenic Site No. 12."],"travelTips":["The south gate is closer to Tapsa temple and saves climbing.","Cherry blossom lines the approach in late April.","You need a car or a bus from Jinan; public transport is sparse."],"bestTime":"April and October–November","visitDuration":"3 hours","ticket":"The provincial park is free; Tapsa temple charges 3,000 KRW (2,000 students, 1,000 children) — it holds only provincial-level heritage, so the 2023 fee abolition did not cover it","openingHours":"08:00–18:00","galleryCaptions":["Stone pagodas below Maisan"]},"ko":{"name":"마이산과 탑사","summary":"말의 귀를 닮은 두 봉우리, 그 아래 손으로 쌓은 80여 기의 돌탑.","story":"마이산은 두 개의 바위 봉우리가 나란히 서 있어 멀리서 보면 숲에서 솟은 말의 두 귀 같다. 그 아래에서 이갑룡이라는 사람이 생의 마지막 30년 동안 80기가 넘는 돌탑을 쌓았다. 접착제도 뼈대도 없이 돌 위에 돌을 얹었을 뿐인데 백 년 넘는 비바람에도 그대로 서 있다. 왜 무너지지 않는지 아직 아무도 완전히 설명하지 못한다. 봄이면 탑사로 가는 길에 벚꽃이 가득하다.","facts":["암마이봉(686m)과 수마이봉(678m)이 나란히 서 있다.","이갑룡이 1885~1917년에 80기가 넘는 돌탑을 쌓았다.","돌탑은 접착제 없이 마른 상태로 쌓아 올렸다.","국가 명승 제12호다."],"travelTips":["남부주차장이 탑사에 더 가까워 오르막이 짧다.","4월 말이면 진입로에 벚꽃이 핀다.","자가용이나 진안행 버스가 필요하다. 대중교통이 드물다."],"bestTime":"4월, 10~11월","visitDuration":"3시간","ticket":"도립공원 입장은 무료, 탑사 관람료 3,000원(학생 2,000원, 어린이 1,000원) — 탑사는 도지정문화재만 보유해 2023년 관람료 폐지 대상이 아니다","openingHours":"08:00~18:00","galleryCaptions":["마이산 아래의 돌탑"]},"ja":{"name":"馬耳山と塔寺","summary":"馬の耳に似た二つの峰。その下に手で積んだ80基余りの石塔。","story":"馬耳山は二つの岩峰が並び立ち、遠くから見ると森から突き出た馬の両耳そのものだ。その下で、李甲龍という人物が生涯最後の三十年をかけて80基を超える石塔を積んだ。接着剤も骨組みもなく、石の上に石を重ねただけなのに、百年を超える風雨に耐えて立っている。なぜ崩れないのか、いまだ完全には説明されていない。春には塔寺へ続く道が桜で満たされる。","facts":["岩馬耳峰（686m）と雌馬耳峰（678m）が並び立つ。","李甲龍が1885〜1917年に80基超の石塔を積んだ。","石塔は接着剤を使わず空積みで築かれている。","国家名勝第12号。"],"travelTips":["南部駐車場のほうが塔寺に近く、登りが短い。","4月下旬には参道に桜が咲く。","自家用車か鎮安行きのバスが必要。公共交通は少ない。"],"bestTime":"4月、10〜11月","visitDuration":"3時間","ticket":"道立公園の入場は無料、塔寺の拝観料は3,000ウォン（学生2,000、子ども1,000）。塔寺は道指定文化財のみのため2023年の拝観料廃止の対象外","openingHours":"08:00〜18:00","galleryCaptions":["馬耳山のふもとの石塔"]},"zh":{"name":"馬耳山與塔寺","summary":"形如馬耳的兩座山峰，其下是八十多座徒手堆起的石塔。","story":"馬耳山有兩座並立的岩峰，遠看正像從樹林中冒出的一對馬耳。峰下，一位名叫李甲龍的修行者以生命最後三十年堆起八十多座石塔——沒有黏著劑、沒有骨架，只是石頭疊石頭——卻在一個多世紀的風雨中屹立不倒。至今沒有人能完全解釋它們為何不塌。春天，通往塔寺的路上開滿櫻花。","facts":["岩馬耳峰（686公尺）與雌馬耳峰（678公尺）並肩而立。","李甲龍於1885至1917年間堆起八十多座石塔。","石塔完全乾砌，未使用任何黏著材料。","被指定為國家名勝第12號。"],"travelTips":["南側入口離塔寺較近，可少爬一段。","四月下旬參道櫻花盛開。","需要自駕或搭鎮安客運，大眾運輸班次很少。"],"bestTime":"4月與10至11月","visitDuration":"3小時","ticket":"道立公園免費；塔寺門票3,000韓元（學生2,000、兒童1,000）——塔寺僅有道級文化財，不在2023年廢除門票之列","openingHours":"08:00–18:00","galleryCaptions":["馬耳山下的石塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gochang-dolmen', 'gochang-dolmen', 'jeonbuk', 'Mộ đá Gochang', 'Gochang Dolmen Site', 'unesco', 126.7295, 35.4335, 'Quần thể mộ đá dày đặc nhất thế giới — hơn 440 ngôi trên một sườn đồi.', 'Nếu Ganghwa có những ngôi mộ đá nổi tiếng nhất thì Gochang có số lượng: hơn bốn trăm bốn mươi ngôi nằm rải trên một dải đồi dài chừng hai cây số, đủ mọi kích cỡ và kiểu dáng, từ loại bàn cao đến loại nắp đá đặt sát đất. Đi bộ theo đường mòn giữa chúng, bạn đi ngang ba nghìn năm lịch sử mà gần như không gặp ai. Gần đó còn có thành cổ Gochang Eupseong với tục đi vòng tường thành đội đá trên đầu để cầu sức khoẻ.', '["Có hơn 440 ngôi mộ đá, mật độ dày nhất thế giới.","Được UNESCO công nhận Di sản Thế giới năm 2000 cùng Hwasun và Ganghwa.","Niên đại khoảng thế kỷ 7–3 trước Công nguyên.","Gần đó là thành Gochang Eupseong xây năm 1453."]', '["Có xe điện chạy dọc khu mộ đá nếu ngại đi bộ.","Kết hợp thành Gochang Eupseong và chùa Seonunsa trong ngày.","Gochang nổi tiếng với dâu tây và rượu bokbunja."]', 'Tháng 4–6 và 9–10', '2 giờ', '3.000 KRW (thiếu niên 2.000, trẻ em 1.000); tàu điện tham quan thêm 1.000 KRW', '09:00–18:00', '["unesco","hidden-gem"]', '["UNESCO","khảo cổ","tiền sử"]', '[{"seed":"gochang-dolmen","caption":"Bãi mộ đá Gochang","ratio":"16/9"}]', '["jeonju-hanok-village"]', 0, 'https://en.trippose.com/tour/gochang-dolmen-site-unesco-world-heritage', '2026-08-04', '{"en":{"name":"Gochang Dolmen Site","summary":"The densest concentration of dolmens on earth — more than 440 on a single hillside.","story":"If Ganghwa has the most famous dolmens, Gochang has the numbers: more than four hundred and forty scattered along a ridge about two kilometres long, in every size and style, from tall table types to capstones laid almost on the ground. Walking the trail between them, you pass through three thousand years of history and meet almost no one. Nearby stands Gochang Eupseong fortress, where tradition has women walk the wall with a stone on their head for good health.","facts":["More than 440 dolmens, the densest concentration in the world.","Inscribed by UNESCO in 2000 with Hwasun and Ganghwa.","Dated to roughly the 7th–3rd centuries BCE.","Gochang Eupseong fortress, built in 1453, stands nearby."],"travelTips":["An electric shuttle runs along the dolmen field if you''d rather not walk.","Combine Gochang Eupseong and Seonunsa temple in the same day.","Gochang is known for strawberries and bokbunja berry wine."],"bestTime":"April–June and September–October","visitDuration":"2 hours","ticket":"3,000 KRW (2,000 youths, 1,000 children); the site train is a further 1,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["The dolmen field at Gochang"]},"ko":{"name":"고창 고인돌 유적","summary":"세계에서 가장 조밀한 고인돌 군락. 한 능선에 440기가 넘는다.","story":"강화에 가장 유명한 고인돌이 있다면 고창에는 숫자가 있다. 2km 남짓한 구릉을 따라 440기가 넘는 고인돌이 크기와 형식을 달리하며 흩어져 있다. 탁자식부터 덮개돌이 땅에 거의 닿은 것까지 다양하다. 그 사이 오솔길을 걸으면 3천 년의 시간을 지나면서도 마주치는 사람이 거의 없다. 근처에는 여인들이 머리에 돌을 이고 성벽을 도는 풍습으로 알려진 고창읍성이 있다.","facts":["440기가 넘는 고인돌이 세계에서 가장 조밀하게 분포한다.","2000년 화순·강화와 함께 유네스코 세계유산에 등재되었다.","축조 시기는 기원전 7~3세기로 추정된다.","1453년에 쌓은 고창읍성이 인근에 있다."],"travelTips":["걷기 부담스러우면 유적지를 도는 전기차를 이용하자.","고창읍성과 선운사를 하루에 묶어 보자.","고창은 딸기와 복분자주로 유명하다."],"bestTime":"4~6월, 9~10월","visitDuration":"2시간","ticket":"3,000원(청소년 2,000원, 어린이 1,000원), 유적지 관람열차 1,000원 별도","openingHours":"09:00~18:00","galleryCaptions":["고창의 고인돌 군락"]},"ja":{"name":"高敞支石墓群","summary":"世界で最も密集した支石墓群。ひとつの丘に440基以上。","story":"江華に最も有名な支石墓があるとすれば、高敞には数がある。2kmほどの丘陵に沿って440基を超える支石墓が、大きさも形も違えて散らばる。卓子式から蓋石が地面に接するものまで多様だ。その間の小道を歩けば三千年の時を横切りながら、人にはほとんど出会わない。近くには、女性たちが頭に石を載せて城壁を回る風習で知られる高敞邑城がある。","facts":["440基を超える支石墓が世界で最も密集して分布する。","2000年に和順・江華とともにユネスコ世界遺産に登録された。","築造は紀元前7〜3世紀と推定される。","1453年に築かれた高敞邑城が近くにある。"],"travelTips":["歩くのが大変なら遺跡を巡る電動カートを利用しよう。","高敞邑城と禅雲寺を一日で回るとよい。","高敞はイチゴとボクブンジャ酒で知られる。"],"bestTime":"4〜6月、9〜10月","visitDuration":"2時間","ticket":"3,000ウォン（青少年2,000、子ども1,000）、遺跡見学列車1,000ウォン別途","openingHours":"09:00〜18:00","galleryCaptions":["高敞の支石墓群"]},"zh":{"name":"高敞支石墓遺址","summary":"全世界最密集的支石墓群——單一丘陵上超過四百四十座。","story":"若說江華擁有最有名的支石墓，高敞則擁有數量：四百四十多座沿著約兩公里長的丘陵散布，大小形制各異，從高桌式到蓋石幾乎貼地的都有。沿著小徑穿行其間，你走過三千年歷史，卻幾乎遇不到人。附近還有高敞邑城，當地習俗是婦女頭頂石塊繞城牆而行以求健康。","facts":["四百四十多座支石墓，密度居世界之冠。","2000年與和順、江華一同列入世界遺產。","年代約為公元前7至3世紀。","附近有建於1453年的高敞邑城。"],"travelTips":["不想走路可搭乘遺址內的電動遊園車。","可與高敞邑城、禪雲寺安排在同一天。","高敞以草莓與覆盆子酒聞名。"],"bestTime":"4至6月、9至10月","visitDuration":"2小時","ticket":"3,000韓元（青少年2,000、兒童1,000）；園區遊園列車另收1,000韓元","openingHours":"09:00–18:00","galleryCaptions":["高敞的支石墓群"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seonunsa', 'seonunsa', 'jeonbuk', 'Chùa Seonunsa & rừng trà hoa', 'Seonunsa Temple & Camellia Forest', 'temple', 126.5785, 35.4985, 'Rừng trà hoa đỏ ba nghìn cây bao quanh một ngôi chùa, nở rộ đúng lúc cả nước còn chưa hết lạnh.', 'Sau lưng chính điện Seonunsa là một vạt rừng trà hoa camellia rộng chừng năm hecta với gần ba nghìn cây, nhiều cây đã hơn năm trăm tuổi. Cuối tháng 4, hoa nở đỏ sẫm rồi rụng nguyên bông xuống nền rêu — trà hoa không rụng cánh lẻ mà rơi cả bông, nên mặt đất phủ đầy những đoá còn nguyên hình. Đó là thứ khiến người ta đi bộ vào đây thay vì chỉ vào chùa. Bản thân Seonunsa dựng từ năm 577, và trên vách đá phía trong thung lũng có tượng Phật Ma nhai khắc thời Goryeo cao gần mười sáu mét. Mùa thu, cả thung lũng chuyển đỏ theo một kiểu khác.', '["Rừng trà hoa sau chùa rộng khoảng 5 hecta với gần 3.000 cây, là Đài kỷ niệm thiên nhiên số 184.","Chùa Seonunsa được dựng năm 577, thời Baekje.","Tượng Phật Ma nhai Dosolam khắc trên vách đá cao khoảng 15,7m.","Trà hoa nở muộn, thường vào cuối tháng 4."]', '["Hoa trà nở cuối tháng 4, muộn hơn hầu hết hoa xuân khác ở Hàn Quốc.","Đường vào tượng Phật Ma nhai đi bộ thêm khoảng 30 phút từ chùa.","Mùa thu lá đỏ ở đây cũng nổi tiếng không kém mùa hoa."]', 'Cuối tháng 4 (trà hoa) và tháng 11 (lá đỏ)', '2–3 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '07:00–18:00', '["hidden-gem"]', '["chùa","trà hoa","rừng","tượng đá"]', '[{"seed":"seonunsa","caption":"Trà hoa đỏ rụng nguyên bông trên nền rêu","ratio":"16/9"}]', '["gochang-dolmen"]', 0, 'https://www.cctoday.co.kr/news/articleView.html?idxno=2177268', '2026-08-04', '{"en":{"name":"Seonunsa Temple & Camellia Forest","summary":"Three thousand red camellias around a temple, flowering just as the rest of the country is still cold.","story":"Behind Seonunsa''s main hall lies about five hectares of camellia forest — nearly three thousand trees, many of them over five hundred years old. In late April the flowers open deep red and then drop whole onto the moss: camellias shed the entire bloom rather than petal by petal, so the ground fills with intact flowers. That is what brings people to walk in here rather than only visit the temple. Seonunsa itself was founded in 577, and on a rock face further up the valley is a Goryeo-era cliff Buddha nearly sixteen metres tall. In autumn the whole valley turns red another way.","facts":["The camellia forest covers about 5 hectares with nearly 3,000 trees; Natural Monument No. 184.","Seonunsa was founded in 577, during the Baekje kingdom.","The Dosolam cliff Buddha carved into the rock stands about 15.7m tall.","The camellias flower late, usually towards the end of April."],"travelTips":["The camellias bloom in late April, later than most Korean spring flowers.","The cliff Buddha is a further 30-minute walk beyond the temple.","The autumn colour here is as well known as the flowers."],"bestTime":"Late April (camellias) and November (autumn colour)","visitDuration":"2–3 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"07:00–18:00","galleryCaptions":["Whole camellia blooms fallen on the moss"]},"ko":{"name":"선운사와 동백숲","summary":"절을 감싼 삼천 그루의 붉은 동백. 나라의 나머지가 아직 추울 때 핀다.","story":"선운사 대웅전 뒤로 5헥타르쯤 되는 동백숲이 펼쳐진다. 삼천 그루에 가깝고 오백 년이 넘은 나무도 많다. 4월 말이면 짙붉게 피었다가 이끼 위로 통째 떨어진다. 동백은 꽃잎을 하나씩 떨구지 않고 송이째 지므로, 바닥이 온전한 꽃으로 덮인다. 사람들이 절만 보지 않고 이 숲을 걷는 이유다. 선운사 자체는 577년 창건이고, 골짜기 안쪽 바위에는 높이 16m에 가까운 고려 시대 마애불이 새겨져 있다. 가을이면 이 골짜기가 다른 방식으로 붉어진다.","facts":["동백숲은 약 5헥타르에 3,000그루에 가깝고 천연기념물 제184호다.","선운사는 백제 시대인 577년에 창건되었다.","도솔암 마애불은 높이 약 15.7m로 바위에 새겨져 있다.","동백은 늦게 펴서 보통 4월 말이 절정이다."],"travelTips":["동백은 4월 말에 핀다. 한국의 다른 봄꽃보다 늦다.","마애불까지는 절에서 30분쯤 더 걸어야 한다.","이곳의 가을 단풍도 꽃 못지않게 유명하다."],"bestTime":"4월 말(동백)과 11월(단풍)","visitDuration":"2~3시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"07:00~18:00","galleryCaptions":["이끼 위에 송이째 떨어진 동백"]},"ja":{"name":"禅雲寺と椿の森","summary":"寺を囲む三千本の赤い椿。国の他所がまだ寒いころに咲く。","story":"禅雲寺の大雄殿の裏に、五ヘクタールほどの椿の森が広がる。三千本近く、五百年を超える木も多い。四月末には濃い赤に咲き、そして苔の上へ丸ごと落ちる。椿は花びらを一枚ずつ散らさず花ごと落ちるので、地面が無傷の花で埋まる。人が寺だけでなくこの森を歩く理由だ。禅雲寺そのものは577年の創建で、谷の奥の岩肌には高さ十六メートル近い高麗時代の磨崖仏が刻まれている。秋になると、この谷は別のやり方で赤くなる。","facts":["椿の森は約5ヘクタールに3,000本近くあり、天然記念物第184号である。","禅雲寺は百済時代の577年に創建された。","兜率庵の磨崖仏は高さ約15.7mで岩に刻まれている。","椿は遅咲きで、見ごろは四月末ごろ。"],"travelTips":["椿は四月末に咲く。韓国の他の春の花より遅い。","磨崖仏へは寺からさらに30分ほど歩く。","ここの紅葉は花に劣らず知られている。"],"bestTime":"4月末（椿）と11月（紅葉）","visitDuration":"2〜3時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"07:00〜18:00","galleryCaptions":["苔の上に花ごと落ちた椿"]},"zh":{"name":"禪雲寺與山茶花林","summary":"環著寺院的三千株紅山茶，在全國其他地方還冷著時就開了。","story":"禪雲寺大雄殿後方是一片約五公頃的山茶林——將近三千株，不少已超過五百歲。四月底花開成深紅，然後整朵落在苔蘚上：山茶不是一瓣一瓣掉，而是整朵墜地，於是地面鋪滿了完好的花。這正是人們走進這片林子、而不只是看看寺院的原因。禪雲寺本身建於577年，山谷更深處的岩壁上，還刻著一尊近十六公尺高的高麗時代摩崖佛。到了秋天，整條山谷又用另一種方式紅起來。","facts":["山茶林約5公頃、近3,000株，為天然紀念物第184號。","禪雲寺創建於百濟時代的577年。","兜率庵摩崖佛刻於岩壁上，高約15.7公尺。","山茶開得晚，通常在四月底。"],"travelTips":["山茶四月底才開，比韓國多數春花都晚。","摩崖佛要從寺院再往上走約30分鐘。","這裡的秋天紅葉，名氣不輸花季。"],"bestTime":"4月底（山茶）與11月（紅葉）","visitDuration":"2至3小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"07:00–18:00","galleryCaptions":["整朵落在苔蘚上的山茶"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('muju-deogyusan', 'muju-deogyusan', 'jeonbuk', 'Vườn quốc gia Deogyusan (Muju)', 'Deogyusan National Park, Muju', 'mountain', 127.7465, 35.8605, 'Cáp treo đưa thẳng lên gần đỉnh cao 1.614 mét, nơi băng bám vào cây thành rừng trắng mùa đông.', 'Deogyusan là một trong ít ngọn núi trên một nghìn sáu trăm mét ở Hàn Quốc mà bạn lên gần đỉnh được bằng cáp treo — tuyến cáp của khu trượt tuyết Muju chạy quanh năm. Từ trạm trên, đi bộ thêm hai mươi phút là tới đỉnh Hyangjeokbong. Mùa đông, hơi ẩm đóng băng trên cành tạo thành sanghoju — rừng cây phủ băng trắng xoá mà người Hàn gọi là ''hoa tuyết'', và cả sườn núi trở nên trắng đến chói mắt. Dưới chân núi là thung lũng Gucheondong dài hơn hai chục cây số với ba mươi ba thắng cảnh được đặt tên từ thời Joseon, mỗi cái là một hồ đá hay một ghềnh nước.', '["Đỉnh Hyangjeokbong cao 1.614m, là một trong những đỉnh cao nhất Hàn Quốc.","Cáp treo của khu trượt tuyết Muju hoạt động quanh năm, đưa khách lên gần đỉnh.","Thung lũng Gucheondong có 33 thắng cảnh được đặt tên từ thời Joseon.","Cảnh cây phủ băng mùa đông là lý do chính khiến khách leo núi mùa lạnh."]', '["Cáp treo ngừng khi gió mạnh — kiểm tra trước khi lái xe tới.","Trên đỉnh lạnh hơn dưới chân núi rất nhiều, mang thêm áo.","Mùa hè có thể đi thung lũng Gucheondong thay vì lên đỉnh."]', 'Tháng 1–2 (cây phủ băng) và tháng 6–8 (thung lũng)', 'Nửa ngày đến cả ngày', 'Cáp treo (gondola) khứ hồi 25.000 KRW (trẻ em 20.000); có thể ngừng chạy khi thời tiết xấu', 'Theo giờ vườn quốc gia và lịch cáp treo', '["hidden-gem"]', '["leo núi","cáp treo","băng tuyết","thung lũng"]', '[{"seed":"muju-deogyusan","caption":"Cây phủ băng trên đỉnh Hyangjeokbong","ratio":"16/9"}]', '["maisan"]', 0, 'https://tour.muju.go.kr/tour/contents.do?key=110', '2026-08-04', '{"en":{"name":"Deogyusan National Park, Muju","summary":"A cable car straight up to near a 1,614-metre summit, where ice coats the trees into a white forest in winter.","story":"Deogyusan is one of the few Korean mountains over sixteen hundred metres you can reach the top of by cable car — the Muju ski resort line runs all year. From the upper station it is a twenty-minute walk to Hyangjeokbong summit. In winter moisture freezes onto the branches into what Koreans call snow flowers, and the whole flank turns a glaring white. At the foot of the mountain lies the Gucheondong valley, more than twenty kilometres long, holding thirty-three named scenic spots dating from the Joseon era, each one a rock pool or a run of rapids.","facts":["Hyangjeokbong summit reaches 1,614m, among Korea''s highest peaks.","The Muju ski resort cable car runs year-round, close to the summit.","Gucheondong valley holds 33 named scenic spots dating from Joseon.","Ice-covered trees in winter are the main reason people climb in the cold."],"travelTips":["The cable car stops in high wind — check before driving out.","The summit is far colder than the valley; bring an extra layer.","In summer, walk Gucheondong valley instead of going for the summit."],"bestTime":"January–February (ice) and June–August (the valley)","visitDuration":"Half to a full day","ticket":"Gondola 25,000 KRW return (20,000 children); it can stop running in bad weather","openingHours":"National park hours and cable car schedule","galleryCaptions":["Ice-covered trees on Hyangjeokbong"]},"ko":{"name":"무주 덕유산국립공원","summary":"해발 1,614m 정상 가까이 곤돌라로 오른다. 겨울이면 나무가 얼어 흰 숲이 된다.","story":"덕유산은 한국에서 1,600m를 넘는 산 가운데 정상 가까이까지 곤돌라로 오를 수 있는 몇 안 되는 곳이다. 무주 스키장의 곤돌라가 사철 운행한다. 상부 정류장에서 향적봉까지는 이십 분을 더 걸으면 된다. 겨울이면 습기가 가지에 얼어붙어 상고대가 되고, 산 사면 전체가 눈부시게 하얘진다. 산 아래에는 20km가 넘는 구천동 계곡이 있고, 조선 시대에 이름 붙은 서른세 개의 절경이 이어진다. 하나하나가 소나 여울이다.","facts":["향적봉은 1,614m로 한국에서도 손꼽히는 높이다.","무주 스키장 곤돌라가 사철 운행해 정상 가까이 오른다.","구천동 계곡에는 조선 시대에 이름 붙은 33경이 있다.","겨울 상고대가 추위에도 사람들이 오르는 가장 큰 이유다."],"travelTips":["바람이 세면 곤돌라가 멈춘다. 출발 전에 확인하자.","정상은 아래보다 훨씬 춥다. 겉옷을 한 겹 더 챙기자.","여름에는 정상 대신 구천동 계곡을 걷는 것도 좋다."],"bestTime":"1~2월(상고대)과 6~8월(계곡)","visitDuration":"반나절~하루","ticket":"곤돌라 왕복 25,000원(어린이 20,000원), 기상에 따라 운행 중단 가능","openingHours":"국립공원 운영시간과 곤돌라 일정에 따름","galleryCaptions":["향적봉의 상고대"]},"ja":{"name":"茂朱徳裕山国立公園","summary":"標高1,614mの山頂近くまでゴンドラで上がれる。冬には氷が木を包み白い森になる。","story":"徳裕山は、韓国で千六百メートルを超える山のうち、山頂近くまでゴンドラで上がれる数少ない一座だ。茂朱スキー場のゴンドラが通年動いている。上部駅から香積峰までは二十分歩けばよい。冬には湿気が枝に凍りついて樹氷になり、山の斜面全体がまばゆく白くなる。山の下には二十キロを超える九千洞渓谷があり、朝鮮時代に名づけられた三十三の景勝が続く。ひとつひとつが淵であり瀬である。","facts":["香積峰は1,614mで、韓国でも高い部類に入る。","茂朱スキー場のゴンドラが通年運行し、山頂近くまで運ぶ。","九千洞渓谷には朝鮮時代に名づけられた三十三景がある。","冬の樹氷が、寒い季節に人が登る最大の理由である。"],"travelTips":["強風だとゴンドラが止まる。車で行く前に確認しよう。","山頂は麓よりずっと寒い。もう一枚持とう。","夏は山頂を目指さず九千洞渓谷を歩くのもよい。"],"bestTime":"1〜2月（樹氷）と6〜8月（渓谷）","visitDuration":"半日〜一日","ticket":"ゴンドラ往復25,000ウォン（子ども20,000）、天候により運休あり","openingHours":"国立公園の運営時間とゴンドラの運行に従う","galleryCaptions":["香積峰の樹氷"]},"zh":{"name":"茂朱德裕山國立公園","summary":"纜車直上海拔1,614公尺山頂附近，冬天冰霜裹樹，成一片白色森林。","story":"德裕山是韓國少數能搭纜車直達山頂附近、海拔超過一千六百公尺的山——茂朱滑雪場的纜車全年營運。從上站再走二十分鐘就是香積峰。冬天，水氣在枝頭結冰，形成韓國人稱的「雪花」，整片山坡白得刺眼。山腳下是綿延二十多公里的九千洞溪谷，沿途有三十三處自朝鮮時代就命名的勝景，每一處都是一潭或一段急流。","facts":["香積峰海拔1,614公尺，屬韓國高峰之列。","茂朱滑雪場纜車全年營運，可上抵接近山頂處。","九千洞溪谷有33處自朝鮮時代命名的勝景。","冬季霧淞是人們在寒冷季節上山的主因。"],"travelTips":["強風時纜車停駛，開車前往前先確認。","山頂比山下冷得多，多帶一件外套。","夏天可改走九千洞溪谷，不必登頂。"],"bestTime":"1至2月（霧淞）與6至8月（溪谷）","visitDuration":"半天至一整天","ticket":"纜車來回25,000韓元（兒童20,000）；天候不佳時可能停駛","openingHours":"依國立公園時間與纜車班次","galleryCaptions":["香積峰上的霧淞"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('byeonsan-bando', 'byeonsan-bando', 'jeonbuk', 'Vườn quốc gia bán đảo Byeonsan', 'Byeonsanbando National Park', 'beach', 126.5385, 35.6455, 'Vườn quốc gia duy nhất của Hàn Quốc có cả núi lẫn biển, với bãi đá xếp lớp như chồng sách.', 'Byeonsanbando là vườn quốc gia duy nhất ở Hàn Quốc gộp cả vùng núi lẫn vùng biển vào một ranh giới. Phần núi có chùa Naesosa với đường thông đỏ dẫn vào và những cánh cửa gỗ chạm hoa đã bạc màu qua bốn thế kỷ, không sơn lại. Phần biển có Chaeseokgang — một bờ đá trầm tích bị sóng bào thành từng lớp phẳng xếp chồng lên nhau, trông đúng như một chồng sách khổng lồ, và chỉ đi được khi triều xuống. Hoàng hôn ở đây rơi thẳng xuống Hoàng Hải phía sau các lớp đá, và đó là bức ảnh mà ai đến Byeonsan cũng mang về.', '["Là vườn quốc gia duy nhất của Hàn Quốc bao gồm cả khu vực núi và khu vực biển.","Bờ đá Chaeseokgang là đá trầm tích xếp lớp, chỉ đi được lúc triều xuống.","Chùa Naesosa dựng năm 633, nổi tiếng với cửa gỗ chạm hoa không sơn.","Đường thông đỏ dẫn vào Naesosa dài khoảng 600m."]', '["Tra lịch thuỷ triều trước khi tới Chaeseokgang — triều lên là không xuống được.","Đá ở Chaeseokgang trơn và sắc, đi giày đế dày.","Hoàng hôn là thời điểm đáng đợi nhất ở bờ đá."]', 'Tháng 4–6 và 9–10', 'Cả ngày', 'Miễn phí (phí di sản Naesosa đã bỏ từ 5/2023)', 'Theo giờ vườn quốc gia; Chaeseokgang theo thuỷ triều', '["hidden-gem","verified"]', '["biển","địa chất","chùa","hoàng hôn"]', '[{"seed":"byeonsan-bando","caption":"Đá xếp lớp ở Chaeseokgang","ratio":"16/9"}]', '["seonunsa","gochang-dolmen"]', 1, 'https://www.cctoday.co.kr/news/articleView.html?idxno=2177268', '2026-08-04', '{"en":{"name":"Byeonsanbando National Park","summary":"Korea''s only national park holding both mountain and sea, with a rock shore layered like stacked books.","story":"Byeonsanbando is the only Korean national park to take in both a mountain area and a marine one inside a single boundary. The mountain side holds Naesosa temple, approached along an avenue of red pines, with carved flower doors left unpainted and weathered over four centuries. The sea side holds Chaeseokgang — sedimentary rock the waves have cut into flat layers stacked on top of each other, exactly like an enormous pile of books, walkable only at low tide. Sunset falls straight into the Yellow Sea behind those layers, and that is the photograph everyone takes home from Byeonsan.","facts":["The only Korean national park covering both a mountain and a marine area.","Chaeseokgang is layered sedimentary rock, accessible only at low tide.","Naesosa temple was founded in 633 and is known for its unpainted carved flower doors.","The red pine avenue into Naesosa runs about 600m."],"travelTips":["Check the tide before heading to Chaeseokgang — at high water you cannot get down.","The rock at Chaeseokgang is slippery and sharp; wear thick soles.","Sunset is the hour worth waiting for on the rock shore."],"bestTime":"April–June and September–October","visitDuration":"A full day","ticket":"Free (Naesosa''s heritage fee was abolished in May 2023)","openingHours":"National park hours; Chaeseokgang by tide","galleryCaptions":["The layered rock at Chaeseokgang"]},"ko":{"name":"변산반도국립공원","summary":"산과 바다를 함께 품은 한국 유일의 국립공원. 책을 쌓은 듯한 층리 해안이 있다.","story":"변산반도는 한 경계 안에 산악 지역과 해상 지역을 함께 담은 한국 유일의 국립공원이다. 산 쪽에는 전나무길로 드는 내소사가 있는데, 사백 년 동안 덧칠하지 않아 바랜 꽃살문이 남아 있다. 바다 쪽에는 채석강이 있다. 파도가 퇴적암을 평평한 층으로 깎아 켜켜이 쌓아 놓은 모습이 거대한 책 더미 같고, 물이 빠졌을 때만 걸을 수 있다. 그 층 뒤로 해가 서해로 곧장 떨어지는데, 변산에 다녀온 사람이 들고 오는 사진은 대개 그것이다.","facts":["산악과 해상 지역을 함께 포함한 한국 유일의 국립공원이다.","채석강은 층리가 뚜렷한 퇴적암 해안으로 간조에만 걸을 수 있다.","내소사는 633년 창건되었고 단청하지 않은 꽃살문으로 유명하다.","내소사로 드는 전나무길은 약 600m다."],"travelTips":["채석강에 가기 전 물때를 확인하자. 만조에는 내려갈 수 없다.","채석강의 바위는 미끄럽고 날카롭다. 두꺼운 밑창의 신발을 신자.","해안에서는 일몰이 가장 기다릴 만한 시간이다."],"bestTime":"4~6월, 9~10월","visitDuration":"하루","ticket":"무료(내소사 문화재관람료는 2023년 5월 폐지)","openingHours":"국립공원 운영시간, 채석강은 물때에 따름","galleryCaptions":["채석강의 층리 바위"]},"ja":{"name":"辺山半島国立公園","summary":"山と海をともに含む韓国唯一の国立公園。本を積み重ねたような層理の海岸がある。","story":"辺山半島は、ひとつの境界の中に山岳地域と海上地域をともに収めた韓国唯一の国立公園である。山側には来蘇寺があり、モミの並木を抜けて入る。四百年ものあいだ塗り直されず色の褪せた花模様の扉が残る。海側には彩石江がある。波が堆積岩を平らな層に削って積み重ねた姿は巨大な本の山そのもので、潮が引いたときだけ歩ける。その層の向こうへ日が黄海へまっすぐ沈む。辺山を訪ねた人が持ち帰る写真は、たいていそれだ。","facts":["山岳と海上の両地域を含む韓国唯一の国立公園である。","彩石江は層理の明瞭な堆積岩の海岸で、干潮時のみ歩ける。","来蘇寺は633年創建、彩色しない花模様の扉で知られる。","来蘇寺へ入るモミの並木は約600m。"],"travelTips":["彩石江へ行く前に潮を確認しよう。満潮では下りられない。","彩石江の岩は滑りやすく鋭い。厚い靴底で。","海岸では日没が最も待つ価値のある時間だ。"],"bestTime":"4〜6月、9〜10月","visitDuration":"一日","ticket":"無料（来蘇寺の文化財観覧料は2023年5月に廃止）","openingHours":"国立公園の運営時間、彩石江は潮汐に従う","galleryCaptions":["彩石江の層理の岩"]},"zh":{"name":"邊山半島國立公園","summary":"韓國唯一同時涵蓋山與海的國立公園，岩岸層層疊疊如堆起的書。","story":"邊山半島是韓國唯一在同一個範圍內同時納入山區與海域的國立公園。山的這一側有來蘇寺，沿著冷杉林道走進去，四百年來未曾重新上漆、色澤褪盡的花紋木門仍在。海的那一側是彩石江：海浪把沉積岩削成一層層平整岩板疊在一起，看起來就像一大疊書，只有退潮時才走得進去。夕陽正好落在那些岩層後方的黃海裡——去過邊山的人帶回來的照片，多半就是這一張。","facts":["是韓國唯一同時包含山區與海域的國立公園。","彩石江為層理分明的沉積岩海岸，僅退潮時可行走。","來蘇寺創建於633年，以未上彩的花紋木門聞名。","通往來蘇寺的冷杉林道長約600公尺。"],"travelTips":["前往彩石江前先查潮汐——漲潮時下不去。","彩石江的岩面又滑又利，請穿厚底鞋。","在岩岸上，日落是最值得等的時刻。"],"bestTime":"4至6月與9至10月","visitDuration":"一整天","ticket":"免費（來蘇寺的文化財觀覽費已於2023年5月廢止）","openingHours":"依國立公園時間；彩石江依潮汐","galleryCaptions":["彩石江的層理岩壁"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gunsan-modern-quarter', 'gunsan-modern-quarter', 'jeonbuk', 'Phố cận đại Gunsan', 'Gunsan Modern Quarter', 'city', 126.7135, 35.9855, 'Thành phố cảng còn nguyên ngân hàng, kho gạo và một ngôi chùa Nhật — thứ hiếm ở Hàn Quốc.', 'Gunsan là cảng người Nhật dùng để chở gạo đồng bằng Honam về chính quốc, và vì thế thành phố này giữ lại nhiều kiến trúc thời thuộc địa hơn bất kỳ nơi nào khác ở Hàn Quốc. Có Ngân hàng Chosen bằng đá, có kho hải quan gạch đỏ, có căn biệt thự gỗ hai tầng của một thương gia buôn gạo, và — hiếm nhất — Dongguksa, ngôi chùa kiểu Nhật duy nhất còn nguyên trên đất Hàn. Việc giữ lại những công trình này từng gây tranh cãi gay gắt, và cách Gunsan giải quyết là biến chúng thành bảo tàng kể thẳng chuyện bóc lột thay vì làm cảnh đẹp. Thành phố cũng nổi tiếng với tiệm bánh Lee Sung Dang, tiệm bánh lâu đời nhất Hàn Quốc.', '["Cảng Gunsan mở năm 1899 và trở thành cảng xuất gạo chính về Nhật Bản.","Chùa Dongguksa là ngôi chùa kiểu Nhật duy nhất còn nguyên vẹn ở Hàn Quốc.","Toà Ngân hàng Chosen và kho hải quan cũ nay là bảo tàng lịch sử cận đại.","Tiệm bánh Lee Sung Dang mở năm 1945, là tiệm bánh lâu đời nhất Hàn Quốc."]', '["Mua vé gộp các bảo tàng cận đại, rẻ hơn mua lẻ.","Xếp hàng ở Lee Sung Dang khá lâu vào cuối tuần; đi trước 10h sáng.","Từ Gunsan có phà đi quần đảo Seonyudo, cảnh rất đẹp."]', 'Tháng 4–6 và 9–11', 'Nửa ngày', 'Vé gộp các bảo tàng 3.000 KRW; riêng Bảo tàng Lịch sử Cận đại 2.000 KRW', '09:00–18:00, bảo tàng đóng cửa thứ Hai', '["hidden-gem"]', '["lịch sử cận đại","kiến trúc","cảng","bánh"]', '[{"seed":"gunsan-modern-quarter","caption":"Toà Ngân hàng Chosen cũ ở Gunsan","ratio":"16/9"}]', '["jeonju-hanok-village"]', 0, 'https://www.trip.com/travel-guide/attraction/gunsan/gunsan-modern-history-museum-62044614/', '2026-08-04', '{"en":{"name":"Gunsan Modern Quarter","summary":"A port city with its banks, rice warehouses and a Japanese temple intact — a rarity in Korea.","story":"Gunsan was the port the Japanese used to ship the Honam plain''s rice home, and as a result the city retains more colonial architecture than anywhere else in Korea. There is the stone Bank of Chosen, the red-brick customs house, the two-storey wooden villa of a rice merchant, and — rarest of all — Dongguksa, the only intact Japanese-style temple left on Korean soil. Keeping these buildings was fiercely contested, and Gunsan''s answer was to turn them into museums that state the exploitation plainly rather than dress it up. The city is also home to Lee Sung Dang, Korea''s oldest bakery.","facts":["Gunsan port opened in 1899 and became the main rice export port to Japan.","Dongguksa is the only fully intact Japanese-style temple remaining in Korea.","The old Bank of Chosen and customs house are now modern history museums.","Lee Sung Dang bakery, opened in 1945, is Korea''s oldest."],"travelTips":["Buy the combined museum ticket; it is cheaper than paying separately.","The queue at Lee Sung Dang is long at weekends — go before 10am.","Ferries run from Gunsan to the Seonyudo islands; the scenery is superb."],"bestTime":"April–June and September–November","visitDuration":"Half a day","ticket":"3,000 KRW for the combined museum ticket; 2,000 KRW for the Modern History Museum alone","openingHours":"09:00–18:00, museums closed Mondays","galleryCaptions":["The old Bank of Chosen building in Gunsan"]},"ko":{"name":"군산 근대문화거리","summary":"은행과 쌀 창고, 일본식 사찰이 그대로 남은 항구 도시. 한국에서는 드문 일이다.","story":"군산은 일본이 호남평야의 쌀을 실어 가던 항구였고, 그래서 한국 어느 도시보다 식민지기 건축이 많이 남았다. 석조 조선은행, 붉은 벽돌 세관, 쌀 상인의 이층 목조 저택, 그리고 가장 드문 것으로 한국 땅에 온전히 남은 유일한 일본식 사찰 동국사가 있다. 이 건물들을 남기는 일은 치열한 논쟁을 낳았고, 군산의 답은 그것을 예쁘게 꾸미는 대신 수탈을 그대로 말하는 박물관으로 만드는 것이었다. 이 도시에는 한국에서 가장 오래된 빵집 이성당도 있다.","facts":["군산항은 1899년 개항해 일본으로 쌀을 실어 내는 주요 항구가 되었다.","동국사는 한국에 온전히 남은 유일한 일본식 사찰이다.","옛 조선은행과 세관 건물은 지금 근대역사박물관으로 쓰인다.","1945년 문을 연 이성당은 한국에서 가장 오래된 빵집이다."],"travelTips":["박물관 통합권이 따로 사는 것보다 싸다.","주말 이성당은 줄이 길다. 오전 10시 전에 가자.","군산에서 선유도로 가는 배가 있는데 경치가 아주 좋다."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절","ticket":"박물관 통합권 3,000원, 근대역사박물관 단독 2,000원","openingHours":"09:00~18:00, 박물관은 월요일 휴관","galleryCaptions":["군산의 옛 조선은행 건물"]},"ja":{"name":"群山近代文化通り","summary":"銀行と米倉、日本式の寺がそのまま残る港町。韓国では珍しい。","story":"群山は日本が湖南平野の米を積み出した港であり、そのため韓国のどの都市より植民地期の建築が多く残る。石造の朝鮮銀行、赤煉瓦の税関、米商人の二階建て木造邸宅、そして最も稀なものとして、韓国の地に完全な形で残る唯一の日本式寺院・東国寺がある。これらを残すことは激しい議論を呼んだが、群山の答えは、美しく飾る代わりに収奪をそのまま語る博物館にすることだった。この街には韓国最古のパン屋・李盛堂もある。","facts":["群山港は1899年に開港し、日本への主要な米の積出港となった。","東国寺は韓国に完全な形で残る唯一の日本式寺院である。","旧朝鮮銀行と税関の建物は現在、近代歴史博物館である。","1945年開業の李盛堂は韓国最古のパン屋である。"],"travelTips":["博物館の共通券が別々に買うより安い。","週末の李盛堂は行列が長い。午前10時前に行こう。","群山から仙遊島へ船が出ており、景色がすばらしい。"],"bestTime":"4〜6月、9〜11月","visitDuration":"半日","ticket":"博物館共通券3,000ウォン、近代歴史博物館のみなら2,000ウォン","openingHours":"09:00〜18:00、博物館は月曜休館","galleryCaptions":["群山の旧朝鮮銀行の建物"]},"zh":{"name":"群山近代文化街區","summary":"銀行、米倉與一座日式寺院都完整保留下來的港市——這在韓國相當罕見。","story":"群山是日本用來把湖南平原稻米運回本國的港口，也因此保留了比韓國任何城市都多的殖民時期建築。這裡有石造的朝鮮銀行、紅磚海關、米商的兩層木造宅邸，以及最罕見的東國寺——韓國土地上唯一完整保存的日式寺院。要不要保留這些建築曾引發激烈爭論，而群山的答案是：不把它們美化，而是改成把剝削說清楚的博物館。這座城市也有韓國最老的麵包店李盛堂。","facts":["群山港1899年開港，成為輸往日本的主要稻米出口港。","東國寺是韓國唯一完整保存的日式寺院。","舊朝鮮銀行與海關建築現為近代歷史博物館。","1945年開業的李盛堂是韓國最古老的麵包店。"],"travelTips":["買博物館套票，比分開買便宜。","週末李盛堂排隊很長，建議上午10點前去。","群山有船前往仙遊島群島，沿途景色極佳。"],"bestTime":"4至6月與9至11月","visitDuration":"半天","ticket":"博物館聯票3,000韓元；僅近代歷史博物館為2,000韓元","openingHours":"09:00–18:00，博物館週一休館","galleryCaptions":["群山的舊朝鮮銀行建築"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeonju-nambu-market', 'jeonju-nambu-market', 'jeonbuk', 'Chợ Nambu & chợ đêm thanh niên (Jeonju)', 'Nambu Market & Youth Night Market, Jeonju', 'market', 127.1465, 35.8125, 'Khu chợ hai trăm tuổi có một tầng gác bị bỏ hoang được người trẻ biến thành chợ đêm.', 'Chợ Nambu có từ thế kỷ 18 và như mọi khu chợ truyền thống Hàn Quốc, nó đang thoi thóp trước các siêu thị lớn. Rồi năm 2011, thành phố cho người trẻ thuê tầng hai đang bỏ trống với giá gần như không — và họ mở quán ăn, xưởng thủ công, quán rượu nhỏ. Cùng lúc, tối thứ Sáu và thứ Bảy, lối đi giữa chợ biến thành chợ đêm với các gian hàng do chính người trẻ đứng bán. Kết quả là một khu chợ có hai nhịp: ban ngày là các bà bán rau và tương ớt truyền thống, ban đêm là bánh mì kẹp thịt heo và cocktail. Jeonju là kinh đô ẩm thực của Hàn Quốc, và bibimbap Jeonju ăn ở đây rẻ hơn nhiều so với khu hanok.', '["Chợ Nambu có lịch sử từ thế kỷ 18, là chợ truyền thống lớn nhất Jeonju.","Tầng hai bỏ hoang được cho người trẻ khởi nghiệp thuê từ năm 2011.","Chợ đêm thanh niên họp tối thứ Sáu và thứ Bảy.","Jeonju được UNESCO công nhận là Thành phố Ẩm thực năm 2012."]', '["Đi tối thứ Sáu hoặc thứ Bảy để gặp cả chợ ngày lẫn chợ đêm.","Bibimbap ở chợ rẻ hơn khu làng hanok và không kém ngon.","Cách làng hanok Jeonju khoảng 10 phút đi bộ."]', 'Quanh năm; tối cuối tuần', '2 giờ', '', 'Chợ ngày 07:00–20:00; chợ đêm chỉ họp tối thứ Sáu và thứ Bảy 17:00–23:00, khoảng 45 quầy dọc lối chợ dài 250 m', '["trending"]', '["chợ","ẩm thực","chợ đêm","bibimbap"]', '[{"seed":"jeonju-nambu-market","caption":"Chợ đêm thanh niên trong chợ Nambu","ratio":"16/9"}]', '["jeonju-hanok-village"]', 0, 'https://tour.jeonju.go.kr/board/view.jeonju?boardId=BBS_0000003&dataSid=16085', '2026-08-05', '{"en":{"name":"Nambu Market & Youth Night Market, Jeonju","summary":"A two-hundred-year-old market whose abandoned upper floor was taken over by young traders.","story":"Nambu market dates from the 18th century and, like every traditional Korean market, was dying against the supermarkets. Then in 2011 the city let young people rent the empty second floor for almost nothing — and they opened kitchens, craft studios and small bars. At the same time, on Friday and Saturday nights, the aisle down the middle turns into a night market run by those same young traders. The result is a market with two rhythms: by day, women selling vegetables and traditional chilli paste; by night, pork buns and cocktails. Jeonju is Korea''s food capital, and its bibimbap costs far less here than in the hanok quarter.","facts":["Nambu market dates from the 18th century and is Jeonju''s largest traditional market.","Its disused second floor has been let to young entrepreneurs since 2011.","The youth night market runs on Friday and Saturday evenings.","Jeonju was named a UNESCO City of Gastronomy in 2012."],"travelTips":["Go on a Friday or Saturday evening to catch both the day and night markets.","Bibimbap in the market is cheaper than in the hanok village and no worse.","It is about 10 minutes on foot from Jeonju Hanok Village."],"bestTime":"Year-round; weekend evenings","visitDuration":"2 hours","ticket":"","openingHours":"Day market 07:00–20:00; the night market runs only on Friday and Saturday evenings, 17:00–23:00, with about 45 stalls along a 250 m aisle","galleryCaptions":["The youth night market inside Nambu market"]},"ko":{"name":"전주 남부시장과 청년몰","summary":"이백 년 된 시장. 비어 있던 2층을 청년들이 채웠다.","story":"남부시장은 18세기부터 있었고, 한국의 모든 전통시장이 그렇듯 대형마트 앞에서 시들어 가고 있었다. 그러다 2011년, 시가 비어 있던 2층을 거의 공짜에 가깝게 청년들에게 내주었다. 그들은 식당과 공방, 작은 술집을 열었다. 동시에 금요일과 토요일 밤이면 시장 가운데 통로가 야시장으로 바뀌고, 그 청년들이 직접 좌판을 편다. 그래서 이 시장에는 두 개의 리듬이 있다. 낮에는 채소와 고추장을 파는 아주머니들, 밤에는 돼지고기 번과 칵테일이다. 전주는 한국의 미식 도시이고, 비빔밥은 여기가 한옥마을보다 훨씬 싸다.","facts":["남부시장은 18세기부터 이어진 전주 최대의 전통시장이다.","비어 있던 2층은 2011년부터 청년 창업자들에게 임대되었다.","청년 야시장은 금요일과 토요일 저녁에 열린다.","전주는 2012년 유네스코 음식창의도시로 지정되었다."],"travelTips":["금요일이나 토요일 저녁에 가면 낮 시장과 야시장을 다 볼 수 있다.","시장의 비빔밥은 한옥마을보다 싸고 맛은 뒤지지 않는다.","전주한옥마을에서 걸어서 10분쯤이다."],"bestTime":"연중, 주말 저녁","visitDuration":"2시간","ticket":"","openingHours":"낮 시장은 07:00~20:00, 야시장은 금·토요일 저녁 17:00~23:00에만 250m 통로에 45개 매대로 열린다","galleryCaptions":["남부시장 안의 청년 야시장"]},"ja":{"name":"全州南部市場と青年モール","summary":"二百年の市場。空いていた二階を若者たちが埋めた。","story":"南部市場は十八世紀からあり、韓国のあらゆる伝統市場と同じく、大型スーパーの前で衰えていた。ところが2011年、市が空いていた二階をほぼ無償に近い額で若者に貸した。彼らは食堂と工房、小さな酒場を開いた。同時に金曜と土曜の夜には市場の中央通路が夜市に変わり、その若者たちが自ら屋台を出す。だからこの市場には二つのリズムがある。昼は野菜やコチュジャンを売るおばさんたち、夜は豚肉のバーガーとカクテルだ。全州は韓国の美食の街であり、ビビンバはここが韓屋村よりずっと安い。","facts":["南部市場は十八世紀から続く全州最大の伝統市場である。","空いていた二階は2011年から若い起業者に貸し出されている。","青年夜市は金曜と土曜の夜に開かれる。","全州は2012年にユネスコ食文化創造都市に選ばれた。"],"travelTips":["金曜か土曜の夜に行けば昼の市場と夜市の両方を見られる。","市場のビビンバは韓屋村より安く、味も劣らない。","全州韓屋村から徒歩で10分ほど。"],"bestTime":"通年、週末の夜","visitDuration":"2時間","ticket":"","openingHours":"昼の市場は07:00〜20:00、夜市は金・土の夕方17:00〜23:00のみ、250mの通路に約45の屋台が並ぶ","galleryCaptions":["南部市場の中の青年夜市"]},"zh":{"name":"全州南部市場與青年商場","summary":"兩百年的老市場，空置的二樓被年輕人接手。","story":"南部市場自十八世紀就在，和所有韓國傳統市場一樣，正在大型超市面前凋零。然後2011年，市府幾乎免費把空著的二樓租給年輕人——他們開起小館子、工作室與小酒吧。同時，每逢週五、週六夜裡，市場中央的走道就變成夜市，攤主正是這批年輕人。於是這座市場有了兩種節奏：白天是賣蔬菜與辣椒醬的大嬸，夜裡是豬肉漢堡與調酒。全州是韓國的美食之都，而這裡的拌飯比韓屋村便宜得多。","facts":["南部市場自18世紀延續至今，是全州最大的傳統市場。","閒置的二樓自2011年起租給青年創業者。","青年夜市於週五、週六夜間營業。","全州於2012年獲選為聯合國教科文組織美食創意城市。"],"travelTips":["挑週五或週六傍晚來，日市與夜市都趕得上。","市場裡的拌飯比韓屋村便宜，味道不遜色。","距全州韓屋村步行約10分鐘。"],"bestTime":"全年；週末夜間","visitDuration":"2小時","ticket":"","openingHours":"日市07:00–20:00；夜市僅週五、週六晚間17:00–23:00，250公尺通道上約45個攤位","galleryCaptions":["南部市場中的青年夜市"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeonju-hyanggyo', 'jeonju-hyanggyo', 'jeonbuk', 'Văn miếu Jeonju', 'Jeonju Hyanggyo Confucian School', 'temple', 127.1545, 35.8135, 'Trường Nho học địa phương thời Joseon, có bốn cây ngân hạnh bốn trăm tuổi vàng rực mỗi tháng 11.', 'Hyanggyo là trường công do nhà nước Joseon lập ở mỗi huyện, vừa dạy học vừa thờ Khổng Tử. Jeonju Hyanggyo là một trong những cái còn nguyên vẹn nhất: giảng đường Myeongnyundang nơi học trò ngồi học, điện Daeseongjeon thờ bài vị phía sau, ký túc xá hai bên sân. Nhưng thứ khiến người ta xếp hàng vào giữa tháng 11 lại là bốn cây ngân hạnh trong sân, được cho là hơn bốn trăm tuổi. Người xưa trồng ngân hạnh ở trường học vì cây này không bị sâu — hàm ý học trò cũng nên giữ mình như thế. Sân trường đã xuất hiện trong nhiều phim cổ trang, và vào cửa thì miễn phí.', '["Hyanggyo là trường Nho học công lập cấp huyện thời Joseon.","Bốn cây ngân hạnh trong sân được cho là hơn 400 năm tuổi.","Điện Daeseongjeon thờ bài vị Khổng Tử và các bậc hiền triết.","Là bối cảnh quen thuộc của nhiều phim truyền hình cổ trang Hàn Quốc."]', '["Giữa tháng 11 là lúc ngân hạnh vàng nhất và cũng đông nhất.","Vào cửa miễn phí, mở cửa cả tuần.","Cách làng hanok Jeonju khoảng 10 phút đi bộ."]', 'Giữa tháng 11 (lá ngân hạnh vàng)', '1 giờ', '', '09:00–18:00 (tháng 3–10), 10:00–17:00 (tháng 11–2); đóng cửa thứ Hai', '["hidden-gem"]', '["Nho giáo","ngân hạnh","mùa thu","phim trường"]', '[{"seed":"jeonju-hyanggyo","caption":"Ngân hạnh vàng trong sân văn miếu","ratio":"16/9"}]', '["jeonju-hanok-village","jeonju-nambu-market"]', 0, 'https://www.jjhyanggyo.or.kr/map01/210', '2026-08-05', '{"en":{"name":"Jeonju Hyanggyo Confucian School","summary":"A Joseon state school with four four-hundred-year-old ginkgos that turn gold every November.","story":"A hyanggyo was a state school established by Joseon in every county, both teaching and enshrining Confucius. Jeonju''s is among the best preserved: the Myeongnyundang lecture hall where students sat, the Daeseongjeon shrine holding the tablets behind it, dormitories flanking the courtyard. But what draws the queue in mid-November are the four ginkgos in the yard, reckoned to be over four hundred years old. Ginkgos were planted at schools because the tree is not attacked by insects — the implication being that scholars should keep themselves the same way. The courtyard has appeared in many historical dramas, and entry is free.","facts":["A hyanggyo was a state-run county Confucian school under Joseon.","The four ginkgos in the courtyard are reckoned to be over 400 years old.","The Daeseongjeon shrine holds the tablets of Confucius and other sages.","It is a familiar location in Korean historical television dramas."],"travelTips":["Mid-November is when the ginkgos are brightest and the crowds heaviest.","Entry is free and it opens every day of the week.","It is about 10 minutes'' walk from Jeonju Hanok Village."],"bestTime":"Mid-November (golden ginkgo)","visitDuration":"1 hour","ticket":"","openingHours":"09:00–18:00 (March–October), 10:00–17:00 (November–February); closed Mondays","galleryCaptions":["Golden ginkgos in the school courtyard"]},"ko":{"name":"전주향교","summary":"조선의 관학. 마당의 은행나무 네 그루가 해마다 11월이면 노랗게 물든다.","story":"향교는 조선이 고을마다 세운 관립 학교로, 가르치는 곳이면서 공자를 모시는 곳이었다. 전주향교는 그중에서도 잘 남은 편이다. 유생이 앉던 명륜당, 그 뒤로 위패를 모신 대성전, 마당 양옆의 기숙사가 그대로다. 하지만 11월 중순에 줄을 서게 만드는 것은 마당의 은행나무 네 그루다. 사백 년이 넘은 것으로 본다. 향교에 은행나무를 심은 것은 이 나무에 벌레가 꼬이지 않기 때문이다. 유생도 그렇게 자신을 지키라는 뜻이었다. 이 마당은 여러 사극에 나왔고, 입장은 무료다.","facts":["향교는 조선이 고을마다 세운 관립 유학 교육기관이다.","마당의 은행나무 네 그루는 400년이 넘은 것으로 본다.","대성전에는 공자를 비롯한 성현의 위패를 모신다.","여러 한국 사극의 촬영지로 익숙한 곳이다."],"travelTips":["11월 중순이 은행잎이 가장 노랗고 사람도 가장 많다.","입장은 무료이고 주중 내내 연다.","전주한옥마을에서 걸어서 10분쯤이다."],"bestTime":"11월 중순(노란 은행잎)","visitDuration":"1시간","ticket":"","openingHours":"09:00~18:00(3~10월), 10:00~17:00(11~2월), 월요일 휴무","galleryCaptions":["향교 마당의 노란 은행나무"]},"ja":{"name":"全州郷校","summary":"朝鮮の官学。庭の四本のイチョウが毎年十一月に黄金色になる。","story":"郷校は朝鮮が郡ごとに置いた官立の学校で、教える場であると同時に孔子を祀る場でもあった。全州郷校はその中でもよく残っている。儒生が座った明倫堂、その裏に位牌を祀る大成殿、庭の両脇の寄宿舎がそのままだ。だが十一月半ばに行列を作らせるのは庭の四本のイチョウである。樹齢四百年を超えると見られている。郷校にイチョウを植えたのは、この木に虫がつかないからだ。儒生もそのように己を守れ、という含みである。この庭は数々の時代劇に登場し、入場は無料だ。","facts":["郷校は朝鮮が郡ごとに置いた官立の儒学教育機関である。","庭の四本のイチョウは樹齢400年を超えるとされる。","大成殿には孔子ら聖賢の位牌を祀る。","多くの韓国時代劇のロケ地として知られる。"],"travelTips":["十一月中旬がイチョウの盛りで、人出も最も多い。","入場は無料で、週を通して開いている。","全州韓屋村から徒歩で10分ほど。"],"bestTime":"11月中旬（黄葉）","visitDuration":"1時間","ticket":"","openingHours":"09:00〜18:00（3〜10月）、10:00〜17:00（11〜2月）、月曜休み","galleryCaptions":["郷校の庭の黄色いイチョウ"]},"zh":{"name":"全州鄉校","summary":"朝鮮的官學，庭院裡四棵四百歲的銀杏，每年十一月轉為金黃。","story":"鄉校是朝鮮在每個郡設立的官辦學校，既授課也奉祀孔子。全州鄉校保存得相當完好：儒生上課的明倫堂、其後供奉牌位的大成殿，以及庭院兩側的齋舍。但真正讓人在十一月中旬排隊的，是庭中那四棵銀杏，據信已逾四百歲。書院種銀杏，是因為這種樹不生蟲——言下之意，讀書人也該這樣守住自己。這座庭院出現在許多古裝劇裡，而且免費入場。","facts":["鄉校是朝鮮於各郡設置的官辦儒學教育機構。","庭中的四棵銀杏據信樹齡逾400年。","大成殿供奉孔子及諸位先賢的牌位。","是韓國古裝劇常見的取景地。"],"travelTips":["十一月中旬銀杏最黃，人也最多。","免費入場，一週每天開放。","距全州韓屋村步行約10分鐘。"],"bestTime":"11月中旬（金黃銀杏）","visitDuration":"1小時","ticket":"","openingHours":"09:00–18:00（3至10月）、10:00–17:00（11至2月）；週一休息","galleryCaptions":["鄉校庭中的金黃銀杏"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('suncheonman-bay', 'suncheonman-bay', 'jeonnam', 'Vịnh Suncheonman', 'Suncheonman Bay Wetland', 'park', 127.5095, 34.8855, 'Bãi lau sậy mênh mông trên vùng đất ngập mặn, nơi sếu đen về trú đông mỗi năm.', 'Suncheonman là một trong năm vùng đất ngập mặn ven biển lớn nhất thế giới còn nguyên vẹn. Đường gỗ dẫn khách đi giữa bãi lau cao quá đầu người, và từ đài quan sát Yongsan trên đồi, cả vịnh hiện ra với những vòng lau tròn xếp như vân gỗ trên mặt bùn — bức ảnh hoàng hôn kinh điển của Hàn Quốc. Mùa đông, sếu đầu trắng và sếu đen bay về hàng nghìn con. Thành phố đã dời cả một khu dân cư ra xa để giữ vùng chim trú.', '["Là một phần của Di sản Thế giới UNESCO ''Getbol — bãi triều Hàn Quốc'' (2021).","Bãi lau sậy rộng khoảng 3 km², một trong những bãi lớn nhất nước.","Là nơi trú đông của sếu đen và nhiều loài chim di cư quý hiếm.","Vườn quốc gia vườn Suncheonman nằm ngay cạnh, mở từ 2013."]', '["Lên đài quan sát Yongsan lúc hoàng hôn — leo khoảng 30 phút.","Mùa đông là mùa xem chim, mang ống nhòm.","Có xe điện nối khu vườn Suncheonman với vùng đất ngập mặn."]', 'Tháng 10–11 (lau chín) và tháng 12–2 (chim di cư)', 'Nửa ngày', '8.000 KRW; vé gộp Suncheon 12.000 KRW dùng chung với vườn quốc gia', '08:00–19:00', '["unesco","verified"]', '["đất ngập mặn","chim","hoàng hôn"]', '[{"seed":"suncheonman-bay","caption":"Bãi lau vịnh Suncheonman","ratio":"16/9"}]', '["boseong-tea-fields","yeosu-night-sea"]', 1, 'https://www.suncheonbaygarden.com/', '2026-08-04', '{"en":{"name":"Suncheonman Bay Wetland","summary":"A vast field of reeds on tidal flats, where hooded cranes come to winter.","story":"Suncheonman is one of the five largest intact coastal wetlands in the world. Boardwalks lead through reeds taller than you are, and from the Yongsan observatory on the hill the whole bay opens up, the reed beds curling across the mud like wood grain — the classic Korean sunset photograph. In winter thousands of hooded and white-naped cranes arrive. The city moved an entire residential district away from the shore to protect the birds'' ground.","facts":["Part of the UNESCO World Heritage ''Getbol, Korean Tidal Flats'' (2021).","The reed field covers about 3 km², one of the largest in the country.","A wintering site for hooded cranes and many rare migratory birds.","Suncheonman National Garden opened next door in 2013."],"travelTips":["Climb to the Yongsan observatory for sunset — about 30 minutes up.","Winter is the birdwatching season; bring binoculars.","A shuttle links the garden with the wetland."],"bestTime":"October–November (reeds) and December–February (migratory birds)","visitDuration":"Half a day","ticket":"8,000 KRW; the 12,000 KRW Suncheon integrated ticket also covers the national garden","openingHours":"08:00–19:00","galleryCaptions":["Reed beds at Suncheonman Bay"]},"ko":{"name":"순천만습지","summary":"광활한 갈대밭의 갯벌. 겨울이면 흑두루미가 찾아온다.","story":"순천만은 세계에서 원형이 가장 잘 남은 연안습지 다섯 곳 가운데 하나다. 나무 데크가 키를 넘는 갈대 사이로 이어지고, 언덕 위 용산전망대에 오르면 만 전체가 펼쳐진다. 갯벌 위로 둥글게 말린 갈대 무리가 나이테처럼 퍼져 있는 그 장면이 한국의 대표적인 일몰 사진이다. 겨울에는 흑두루미와 재두루미가 수천 마리 날아든다. 순천시는 새들의 서식지를 지키려고 해안가 마을 하나를 통째로 옮겼다.","facts":["2021년 유네스코 세계자연유산 ''한국의 갯벌''에 포함되었다.","갈대밭 면적은 약 3km²로 국내 최대 규모다.","흑두루미를 비롯한 희귀 철새의 월동지다.","2013년 옆에 순천만국가정원이 문을 열었다."],"travelTips":["일몰에 맞춰 용산전망대에 오르자. 약 30분 걸린다.","겨울은 탐조의 계절이니 쌍안경을 챙기자.","국가정원과 습지를 잇는 스카이큐브가 있다."],"bestTime":"10~11월(갈대), 12~2월(철새)","visitDuration":"반나절","ticket":"8,000원, 12,000원 순천 통합권으로 국가정원과 함께 이용 가능","openingHours":"08:00~19:00","galleryCaptions":["순천만의 갈대밭"]},"ja":{"name":"順天湾湿地","summary":"広大な葦原の干潟。冬にはナベヅルが渡ってくる。","story":"順天湾は世界で原形が最もよく残る沿岸湿地の五指に入る。木道が背丈を超える葦の間を抜け、丘の上の龍山展望台に登れば湾全体が広がる。干潟の上に丸く渦を巻く葦の群れが年輪のように広がるその光景が、韓国を代表する夕景写真だ。冬にはナベヅルやマナヅルが数千羽飛来する。順天市は鳥の生息地を守るため、海辺の住宅地をまるごと移した。","facts":["2021年にユネスコ世界自然遺産「韓国の干潟」に含まれた。","葦原の面積は約3km²で国内最大級。","ナベヅルをはじめ希少な渡り鳥の越冬地。","2013年に隣接して順天湾国家庭園が開園した。"],"travelTips":["夕日に合わせて龍山展望台へ。登りは約30分。","冬は探鳥の季節。双眼鏡を持っていこう。","国家庭園と湿地を結ぶスカイキューブがある。"],"bestTime":"10〜11月（葦）、12〜2月（渡り鳥）","visitDuration":"半日","ticket":"8,000ウォン、12,000ウォンの順天統合券で国家庭園と共通利用可","openingHours":"08:00〜19:00","galleryCaptions":["順天湾の葦原"]},"zh":{"name":"順天灣濕地","summary":"潮灘上遼闊的蘆葦原，冬天有黑鶴前來過冬。","story":"順天灣是世界上保存最完整的五大沿海濕地之一。木棧道穿過比人還高的蘆葦，登上山丘的龍山觀景台，整片海灣展開——葦叢在灘泥上捲成一圈圈，像木頭的年輪，這正是韓國最經典的落日照片。冬天，數以千計的黑鶴與白枕鶴飛來。順天市為了保護鳥類棲地，把一整個海邊社區遷離。","facts":["屬2021年列入的世界自然遺產「韓國灘塗」。","蘆葦原面積約3平方公里，是全國最大者之一。","黑鶴等多種珍稀候鳥的越冬地。","順天灣國家庭園於2013年在旁邊開園。"],"travelTips":["配合日落登上龍山觀景台，步行約30分鐘。","冬天是賞鳥季，記得帶望遠鏡。","有空中纜車連接國家庭園與濕地。"],"bestTime":"10至11月（蘆葦）與12至2月（候鳥）","visitDuration":"半天","ticket":"8,000韓元；12,000韓元的順天聯票可一併使用國家庭園","openingHours":"08:00–19:00","galleryCaptions":["順天灣的蘆葦原"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('boseong-tea-fields', 'boseong-tea-fields', 'jeonnam', 'Đồi chè Boseong', 'Boseong Green Tea Fields', 'park', 127.0785, 34.7405, 'Những luống chè uốn theo sườn đồi thành các đường cong xanh mướt, vùng chè lớn nhất Hàn Quốc.', 'Boseong trồng chè từ đầu thế kỷ 20, và các luống chè ở đây được cắt tỉa theo đường đồng mức, tạo thành những vệt cong ôm sườn đồi. Leo hết bậc thang lên đỉnh đồi Daehan Dawon mất chừng hai mươi phút, và từ đó nhìn xuống là biển chè xanh nối tiếp nhau tới tận rừng tuyết tùng. Người ta ăn kem trà xanh, mì trà xanh, cơm trộn lá chè — cả thị trấn sống bằng một thứ lá. Mùa đông, đồi chè được thắp đèn cho lễ hội ánh sáng.', '["Là vùng trồng chè lớn nhất Hàn Quốc, chiếm khoảng 40% sản lượng.","Đồn điền Daehan Dawon trồng từ năm 1939.","Hàng tuyết tùng dẫn vào đồi chè là bối cảnh của nhiều phim và quảng cáo.","Lễ hội ánh sáng đồi chè tổ chức vào mùa đông."]', '["Đi sớm buổi sáng khi còn sương để có ảnh đẹp nhất.","Tháng 5 là lúc lá chè non xanh nhất.","Từ Suncheon hoặc Gwangju đi bus khoảng 1–1,5 giờ."]', 'Tháng 5–6 và 9–10', '2–3 giờ', '4.000–5.000 KRW tuỳ nguồn (trẻ em 3.000)', '09:00–18:00', '["popular"]', '["đồi chè","nhiếp ảnh","nông nghiệp"]', '[{"seed":"boseong-tea-fields","caption":"Luống chè uốn theo sườn đồi","ratio":"16/9"}]', '["suncheonman-bay"]', 0, 'https://www.tripadvisor.com/Attraction_Review-g2024833-d3399689-Reviews-Boseong_Green_Tea_Field_Daehan_Dawon-Boseong_gun_Jeollanam_do.html', '2026-08-04', '{"en":{"name":"Boseong Green Tea Fields","summary":"Rows of tea curving around the hills — the largest tea-growing area in Korea.","story":"Boseong has grown tea since the early 20th century, and the rows here are cut along the contours so that they wrap the hillsides in green ribbons. Climbing the steps to the top of the Daehan Dawon estate takes about twenty minutes, and from there the tea runs on and on to a cedar wood. People eat green tea ice cream, green tea noodles, rice mixed with tea leaves — a whole town living off one leaf. In winter the slopes are strung with lights for a festival.","facts":["Korea''s largest tea region, producing around 40% of the national crop.","The Daehan Dawon plantation has been cultivated since 1939.","The cedar avenue leading in has appeared in many films and adverts.","A winter light festival is held across the tea hills."],"travelTips":["Come early while mist still hangs for the best photographs.","May is when the new leaves are greenest.","Buses from Suncheon or Gwangju take 1–1.5 hours."],"bestTime":"May–June and September–October","visitDuration":"2–3 hours","ticket":"4,000–5,000 KRW depending on source (3,000 children)","openingHours":"09:00–18:00","galleryCaptions":["Tea rows curving around the hill"]},"ko":{"name":"보성 녹차밭","summary":"산비탈을 따라 휘어지는 차 이랑. 한국 최대의 차 재배지다.","story":"보성은 20세기 초부터 차를 길렀고, 이곳의 이랑은 등고선을 따라 다듬어져 언덕을 초록 띠로 감는다. 대한다원 꼭대기까지 계단을 오르는 데 20분쯤 걸리고, 그 위에서 보면 차밭이 삼나무 숲까지 이어진다. 사람들은 녹차 아이스크림과 녹차 국수, 찻잎을 넣은 밥을 먹는다. 온 마을이 잎사귀 하나로 살아간다. 겨울이면 차밭에 조명을 달아 빛 축제를 연다.","facts":["한국 최대의 차 산지로 전국 생산량의 약 40%를 차지한다.","대한다원은 1939년부터 차를 재배해 왔다.","진입로의 삼나무 길은 여러 영화와 광고에 등장했다.","겨울에는 차밭 빛 축제가 열린다."],"travelTips":["안개가 남아 있는 이른 아침이 사진 찍기 가장 좋다.","5월은 새순이 가장 푸른 때다.","순천이나 광주에서 버스로 1~1시간 30분 걸린다."],"bestTime":"5~6월, 9~10월","visitDuration":"2~3시간","ticket":"자료에 따라 4,000~5,000원(어린이 3,000원)","openingHours":"09:00~18:00","galleryCaptions":["언덕을 따라 휘어지는 차 이랑"]},"ja":{"name":"宝城の緑茶畑","summary":"斜面に沿って弧を描く茶の畝。韓国最大の茶産地だ。","story":"宝城は20世紀初頭から茶を育て、ここの畝は等高線に沿って刈られ、丘を緑の帯で巻く。大韓茶園の頂上まで階段を登るのに二十分ほど。そこから見ると茶畑が杉林まで続いていく。人々は緑茶アイスや緑茶麺、茶葉を混ぜたご飯を食べる。町全体が一枚の葉で生きている。冬には茶畑に明かりを灯す光の祭りが開かれる。","facts":["韓国最大の茶産地で全国生産量の約40%を占める。","大韓茶園は1939年から茶を栽培している。","参道の杉並木は多くの映画や広告に登場した。","冬には茶畑の光の祭りが開かれる。"],"travelTips":["霧が残る早朝が写真に最も良い。","5月は新芽が最も青い時期。","順天や光州からバスで1〜1時間30分。"],"bestTime":"5〜6月、9〜10月","visitDuration":"2〜3時間","ticket":"資料により4,000〜5,000ウォン（子ども3,000）","openingHours":"09:00〜18:00","galleryCaptions":["丘に沿って弧を描く茶の畝"]},"zh":{"name":"寶城綠茶園","summary":"沿山坡畫出弧線的茶壟，是韓國最大的茶區。","story":"寶城自二十世紀初開始種茶，這裡的茶壟依等高線修剪，把山坡纏成一條條綠帶。爬完大韓茶園的階梯到丘頂約需二十分鐘，往下望去，茶園一直延伸到杉木林。人們吃綠茶冰淇淋、綠茶麵、拌了茶葉的飯——整座小鎮靠一片葉子維生。冬天，茶山掛上燈飾舉辦光之慶典。","facts":["韓國最大的茶區，約佔全國產量四成。","大韓茶園自1939年開始栽茶。","通往茶園的杉木大道曾出現在許多電影與廣告中。","冬季舉辦茶園燈光節。"],"travelTips":["清晨薄霧未散時最適合拍照。","五月新葉最青翠。","自順天或光州搭公車約1至1.5小時。"],"bestTime":"5至6月、9至10月","visitDuration":"2至3小時","ticket":"依資料為4,000至5,000韓元（兒童3,000）","openingHours":"09:00–18:00","galleryCaptions":["沿山坡起伏的茶壟"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('yeosu-night-sea', 'yeosu-night-sea', 'jeonnam', 'Biển đêm Yeosu & cáp treo', 'Yeosu Night Sea & Cable Car', 'city', 127.7495, 34.7405, 'Thành phố cảng phía nam nổi tiếng vì biển về đêm, có cáp treo đáy kính bay ngang eo biển.', 'Một bài hát nổi tiếng đã biến ''biển đêm Yeosu'' thành cụm từ mà người Hàn nào cũng biết, và thành phố sống rất tốt nhờ điều đó. Ban đêm, cầu Dolsan lên đèn, thuyền cá đậu kín bến, và các quán ăn ven cảng dọn hải sản ra sát mép nước. Cáp treo nối đất liền với đảo Dolsan có cabin đáy kính bay ngang eo biển — nhìn xuống thấy tàu chạy bên dưới. Yeosu cũng là nơi tổ chức Expo 2012, khu triển lãm cũ nay thành công viên biển.', '["Yeosu đăng cai Triển lãm thế giới Expo 2012 với chủ đề đại dương.","Cáp treo Yeosu dài 1,5 km, có cabin đáy kính.","Cầu Dolsan dài 450m, lên đèn đổi màu mỗi tối.","Là căn cứ thuỷ quân cũ của đô đốc Yi Sun-sin."]', '["Đi cáp treo lúc chạng vạng để thấy cả hoàng hôn lẫn đèn đêm.","Tàu KTX từ Seoul tới Yeosu-Expo mất khoảng 3 giờ.","Thử gat-kimchi và canh cá nóc, đặc sản địa phương."]', 'Tháng 5–10', 'Nửa ngày', 'Cáp treo khứ hồi 17.000 KRW (cabin đáy kính đắt hơn)', '09:30–22:00 (cáp treo)', '["popular","trending"]', '["cảng biển","về đêm","cáp treo"]', '[{"seed":"yeosu-night-sea","caption":"Cầu Dolsan lên đèn","ratio":"16/9"}]', '["suncheonman-bay","hyangiram"]', 0, 'https://en.namu.wiki/w/%EC%97%AC%EC%88%98%ED%95%B4%EC%83%81%EC%BC%80%EC%9D%B4%EB%B8%94%EC%B9%B4', '2026-08-04', '{"en":{"name":"Yeosu Night Sea & Cable Car","summary":"A southern port famous for its night sea, with a glass-floored cable car across the strait.","story":"A well-known song turned ''the night sea of Yeosu'' into a phrase every Korean knows, and the city has lived up to it. After dark Dolsan Bridge lights up, fishing boats fill the harbour and restaurants along the quay serve seafood at the water''s edge. The cable car linking the mainland to Dolsan island has glass-floored cabins that cross the strait with ships passing beneath. Yeosu also hosted Expo 2012; the old exhibition grounds are now a seaside park.","facts":["Yeosu hosted the 2012 World Expo on the theme of the ocean.","The Yeosu cable car runs 1.5 km with glass-floored cabins.","Dolsan Bridge, 450m long, changes colour each evening.","The city was Admiral Yi Sun-sin''s naval base."],"travelTips":["Ride the cable car at dusk to catch both sunset and city lights.","The KTX from Seoul to Yeosu-Expo takes about three hours.","Try gat-kimchi and pufferfish soup, the local specialities."],"bestTime":"May–October","visitDuration":"Half a day","ticket":"Cable car 17,000 KRW return (glass-floor cabin costs more)","openingHours":"09:30–22:00 (cable car)","galleryCaptions":["Dolsan Bridge lit at night"]},"ko":{"name":"여수 밤바다와 케이블카","summary":"밤바다로 유명한 남쪽 항구. 해협을 건너는 크리스탈 케이블카가 있다.","story":"노래 한 곡이 ''여수 밤바다''를 모두가 아는 말로 만들었고, 도시는 그 이름값을 해냈다. 어두워지면 돌산대교에 불이 들어오고 항구에는 어선이 가득 차며 부둣가 식당은 물가에 상을 차린다. 육지와 돌산도를 잇는 케이블카에는 바닥이 유리인 캐빈이 있어 아래로 지나가는 배가 보인다. 여수는 2012년 세계박람회를 열었고 옛 전시장은 바다 공원이 되었다.","facts":["여수는 2012년 해양을 주제로 세계박람회를 개최했다.","여수 해상케이블카는 길이 1.5km, 바닥이 유리인 캐빈이 있다.","길이 450m의 돌산대교는 매일 저녁 색이 바뀐다.","이순신 장군의 수군 본영이 있던 곳이다."],"travelTips":["해질녘에 케이블카를 타면 노을과 야경을 모두 볼 수 있다.","서울에서 여수엑스포역까지 KTX로 약 세 시간이다.","갓김치와 복국 등 지역 음식을 맛보자."],"bestTime":"5~10월","visitDuration":"반나절","ticket":"케이블카 왕복 17,000원(크리스탈 캐빈은 더 비쌈)","openingHours":"09:30~22:00(케이블카)","galleryCaptions":["불 밝힌 돌산대교"]},"ja":{"name":"麗水の夜の海とケーブルカー","summary":"夜の海で知られる南の港。海峡を渡るクリスタルケーブルカーがある。","story":"一曲の歌が「麗水の夜の海」を誰もが知る言葉にし、街はその名に応えてきた。暗くなると突山大橋に灯りが入り、港は漁船で埋まり、岸壁の食堂は水際に膳を並べる。陸と突山島を結ぶケーブルカーには床がガラスのキャビンがあり、下を船が通っていくのが見える。麗水は2012年に万博を開催し、旧会場は今、海辺の公園になっている。","facts":["麗水は2012年、海洋をテーマに万国博覧会を開催した。","麗水海上ケーブルカーは全長1.5km、床がガラスのキャビンがある。","全長450mの突山大橋は毎晩色が変わる。","李舜臣将軍の水軍本営が置かれた地。"],"travelTips":["夕暮れにケーブルカーへ乗れば夕日と夜景の両方が見られる。","ソウルから麗水エキスポ駅までKTXで約3時間。","カッキムチやフグのスープなど地元の味を試そう。"],"bestTime":"5〜10月","visitDuration":"半日","ticket":"ケーブルカー往復17,000ウォン（クリスタルキャビンは割高）","openingHours":"09:30〜22:00（ケーブルカー）","galleryCaptions":["灯りをまとった突山大橋"]},"zh":{"name":"麗水夜海與纜車","summary":"以夜海聞名的南方港市，有跨越海峽的水晶纜車。","story":"一首歌讓「麗水的夜海」成了每個韓國人都懂的詞，而這座城市也名副其實。天黑後突山大橋亮起燈，港內漁船擠滿，碼頭邊的餐廳把桌子擺到水邊。連接陸地與突山島的纜車設有玻璃地板車廂，往下能看見船隻通過。麗水也主辦過2012年世博，舊展場如今成了海濱公園。","facts":["麗水於2012年以海洋為主題舉辦世界博覽會。","麗水纜車長1.5公里，設有玻璃地板車廂。","長450公尺的突山大橋每晚變換燈色。","此地曾是李舜臣將軍的水軍基地。"],"travelTips":["黃昏搭纜車，可同時看到落日與夜景。","自首爾搭KTX至麗水世博站約三小時。","嚐嚐芥菜泡菜與河豚湯等在地料理。"],"bestTime":"5至10月","visitDuration":"半天","ticket":"纜車來回17,000韓元（水晶車廂較貴）","openingHours":"09:30–22:00（纜車）","galleryCaptions":["夜裡亮燈的突山大橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hyangiram', 'hyangiram', 'jeonnam', 'Am Hyangiram', 'Hyangiram Hermitage', 'temple', 127.802778, 34.591389, 'Am nhỏ treo trên vách đá cuối bán đảo, chỉ vào được qua các khe đá hẹp.', 'Hyangiram nghĩa là ''am hướng về mặt trời'', và nó nằm trên vách đá cuối đảo Dolsan, quay mặt ra biển phía đông. Đường lên đi qua bốn khe đá hẹp đến mức người to phải nghiêng người lách qua — theo truyền thống, đi hết bốn khe là gột được phiền não. Từ sân am nhìn xuống chỉ có biển và đá. Đây là một trong bốn nơi ngắm bình minh nổi tiếng nhất Hàn Quốc, và ngày 1 tháng 1 người ta đi bộ lên đây từ ba giờ sáng.', '["Được dựng năm 644 bởi đại sư Wonhyo.","Đường lên phải chui qua bốn khe đá tự nhiên rất hẹp.","Là một trong bốn điểm ngắm bình minh nổi tiếng nhất Hàn Quốc.","Nằm ở cực nam đảo Dolsan, cách trung tâm Yeosu khoảng 40 phút."]', '["Đi giày bám tốt: bậc đá và khe đá khá trơn.","Ngày đầu năm rất đông, nên đến sớm hoặc chọn ngày khác.","Kết hợp với biển đêm Yeosu trong cùng chuyến."]', 'Quanh năm, đẹp nhất lúc bình minh', '2 giờ', '2.000 KRW', '05:00–19:00', '["hidden-gem"]', '["chùa","bình minh","vách đá"]', '[{"seed":"hyangiram","caption":"Am trên vách đá nhìn ra biển","ratio":"16/9"}]', '["yeosu-night-sea"]', 0, 'https://ko.wikipedia.org/wiki/향일암', '2026-08-04', '{"en":{"name":"Hyangiram Hermitage","summary":"A small hermitage clinging to a cliff at the end of the peninsula, reached through narrow rock clefts.","story":"Hyangiram means ''the hermitage facing the sun'', and it sits on a cliff at the southern tip of Dolsan island, looking east. The path up passes through four rock clefts so narrow that larger visitors have to turn sideways — tradition holds that squeezing through all four clears your worldly troubles. From the courtyard there is nothing below but sea and rock. This is one of Korea''s four great sunrise spots, and on 1 January people start walking up at three in the morning.","facts":["Founded in 644 by the monk Wonhyo.","The approach passes through four very narrow natural rock clefts.","One of the four most famous sunrise viewpoints in Korea.","At the southern end of Dolsan island, about 40 minutes from central Yeosu."],"travelTips":["Wear shoes with grip: the steps and clefts get slippery.","New Year''s Day is extremely busy — come early or choose another date.","Combine it with the Yeosu night sea on the same trip."],"bestTime":"Year-round, best at sunrise","visitDuration":"2 hours","ticket":"2,000 KRW","openingHours":"05:00–19:00","galleryCaptions":["The hermitage on its sea cliff"]},"ko":{"name":"향일암","summary":"반도 끝 절벽에 매달린 암자. 좁은 바위틈을 지나야 닿는다.","story":"향일암은 ''해를 향한 암자''라는 뜻으로, 돌산도 남쪽 끝 절벽 위에서 동쪽 바다를 바라본다. 오르는 길에는 몸을 옆으로 틀어야 지나갈 만큼 좁은 바위틈이 네 곳 있는데, 그 네 곳을 모두 지나면 번뇌가 씻긴다는 이야기가 전한다. 암자 마당에서 내려다보면 바다와 바위뿐이다. 한국의 4대 해돋이 명소로 꼽혀 1월 1일이면 새벽 세 시부터 사람들이 오르기 시작한다.","facts":["644년 원효대사가 창건했다.","오르는 길에 매우 좁은 자연 바위틈 네 곳을 지난다.","한국의 4대 일출 명소 가운데 하나다.","돌산도 남단, 여수 시내에서 약 40분 거리다."],"travelTips":["계단과 바위틈이 미끄러우니 접지력 좋은 신발을 신자.","1월 1일은 매우 붐비니 일찍 가거나 다른 날을 택하자.","여수 밤바다와 함께 하루에 묶기 좋다."],"bestTime":"연중, 해돋이 시간이 가장 좋다","visitDuration":"2시간","ticket":"2,000원","openingHours":"05:00~19:00","galleryCaptions":["바다 절벽 위의 암자"]},"ja":{"name":"向日庵","summary":"半島の先端の崖に張りつく庵。狭い岩の裂け目を抜けて辿り着く。","story":"向日庵は「日に向かう庵」という意味で、突山島南端の崖の上から東の海を望む。登る道には体を横にしないと通れないほど狭い岩の裂け目が四か所あり、そのすべてを抜けると煩悩が洗われるという言い伝えがある。庵の庭から見下ろせば海と岩しかない。韓国四大日の出の名所とされ、1月1日には午前三時から人が登り始める。","facts":["644年に元暁大師が創建した。","参道で非常に狭い自然の岩の裂け目を四か所通る。","韓国四大日の出スポットのひとつ。","突山島南端、麗水市街から約40分。"],"travelTips":["階段と岩の隙間が滑りやすい。グリップの良い靴を。","元日は非常に混む。早く行くか別の日を選ぼう。","麗水の夜の海と同じ旅程に組み込みやすい。"],"bestTime":"通年、日の出の時間が最良","visitDuration":"2時間","ticket":"2,000ウォン","openingHours":"05:00〜19:00","galleryCaptions":["海の崖の上の庵"]},"zh":{"name":"向日庵","summary":"懸在半島盡頭崖壁上的小庵，須穿過狹窄岩縫才能抵達。","story":"向日庵意為「朝向太陽的庵」，坐落在突山島最南端的崖上，面向東海。上行的路要穿過四道岩縫，窄到身形壯碩的人得側身而過——傳統說法是，走完四道岩縫便能滌去煩惱。從庵前的院子往下望，只有海與岩石。這是韓國四大日出勝地之一，1月1日凌晨三點就有人開始往上走。","facts":["644年由元曉大師創建。","上行途中要穿過四道極窄的天然岩縫。","韓國四大日出觀景地之一。","位於突山島南端，距麗水市區約40分鐘。"],"travelTips":["石階與岩縫濕滑，請穿抓地力好的鞋。","元旦人潮極多，建議提早或另擇日期。","可與麗水夜海安排在同一趟行程。"],"bestTime":"全年，日出時分最佳","visitDuration":"2小時","ticket":"2,000韓元","openingHours":"05:00–19:00","galleryCaptions":["海崖上的庵堂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('damyang-bamboo', 'damyang-bamboo', 'jeonnam', 'Rừng tre Juknokwon (Damyang)', 'Juknokwon Bamboo Forest, Damyang', 'park', 127.0055, 35.3375, 'Rừng tre trồng rộng 31 hecta với tám đường mòn, mát rượi kể cả giữa mùa hè.', 'Damyang nổi tiếng vì tre từ hàng trăm năm — đồ đan, đũa, quạt, cả món cơm hấp trong ống tre. Juknokwon là rừng tre trồng mở cho khách với tám lối đi mang những cái tên như ''đường của người yêu'' hay ''đường suy tưởng''. Đi trong đó, tiếng lá tre cọ nhau tạo thành thứ âm thanh rất riêng, và nhiệt độ thấp hơn bên ngoài vài độ. Gần đó là hàng cây ngân hạnh Metasequoia dài hai cây số, một trong những con đường đẹp nhất Hàn Quốc.', '["Rừng tre trồng rộng khoảng 31 hecta với 8 tuyến đường mòn.","Damyang là vùng tre nổi tiếng nhất Hàn Quốc.","Con đường Metasequoia gần đó dài khoảng 2 km.","Món cơm hấp ống tre (daetongbap) là đặc sản địa phương."]', '["Ăn cơm ống tre ở các quán ngay cổng rừng.","Đi cả đường Metasequoia trong cùng buổi, cách khoảng 10 phút xe.","Từ Gwangju đi bus khoảng 40 phút."]', 'Tháng 5–10', '2 giờ', '3.000 KRW (trẻ em 1.500); miễn phí cho người trên 65 tuổi', '09:00–19:00 (tháng 3–10), 09:00–18:00 (tháng 11–2)', '[]', '["rừng tre","đi bộ","ẩm thực"]', '[{"seed":"damyang-bamboo","caption":"Lối đi trong rừng tre Juknokwon","ratio":"16/9"}]', '["boseong-tea-fields","mudeungsan"]', 0, 'https://us.trip.com/travel-guide/attraction/damyang/juknokwon-33123861/', '2026-08-04', '{"en":{"name":"Juknokwon Bamboo Forest, Damyang","summary":"A 31-hectare planted bamboo forest with eight trails, cool even in high summer.","story":"Damyang has lived off bamboo for centuries — basketry, chopsticks, fans, and rice steamed inside a bamboo tube. Juknokwon is its bamboo forest opened to visitors, with eight paths bearing names like ''the lovers'' way'' and ''the path of contemplation''. Inside, the sound of leaves rubbing together is unlike anything else, and the temperature drops a few degrees. Nearby runs the two-kilometre metasequoia avenue, one of the most beautiful roads in Korea.","facts":["A planted bamboo forest of about 31 hectares with eight walking trails.","Damyang is the best-known bamboo region in Korea.","The nearby metasequoia avenue runs about 2 km.","Rice steamed in a bamboo tube (daetongbap) is the local speciality."],"travelTips":["Eat bamboo-tube rice at the restaurants by the forest gate.","Do the metasequoia avenue the same afternoon, ten minutes away.","Buses from Gwangju take about 40 minutes."],"bestTime":"May–October","visitDuration":"2 hours","ticket":"3,000 KRW (1,500 children); free for over-65s","openingHours":"09:00–19:00 (March–October), 09:00–18:00 (November–February)","galleryCaptions":["A path inside the bamboo forest"]},"ko":{"name":"담양 죽녹원","summary":"31헥타르의 대나무 숲에 여덟 갈래 길. 한여름에도 서늘하다.","story":"담양은 수백 년간 대나무로 살아왔다. 바구니와 젓가락, 부채, 그리고 대통에 찐 밥까지. 죽녹원은 그 대숲을 개방한 곳으로 ''연인의 길'', ''사색의 길'' 같은 이름의 여덟 갈래 산책로가 있다. 안으로 들어서면 댓잎이 서로 스치는 소리가 다른 어디서도 들을 수 없는 소리를 내고 기온이 몇 도 내려간다. 가까이에는 한국에서 손꼽히게 아름다운 2km의 메타세쿼이아 길이 있다.","facts":["약 31헥타르의 조성 대숲에 여덟 개의 산책로가 있다.","담양은 한국에서 가장 유명한 대나무 고장이다.","인근 메타세쿼이아 길은 약 2km 이어진다.","대통밥이 이 고장의 대표 음식이다."],"travelTips":["죽녹원 입구 식당에서 대통밥을 먹어보자.","차로 10분 거리인 메타세쿼이아 길을 같은 날 걸어보자.","광주에서 버스로 약 40분이다."],"bestTime":"5~10월","visitDuration":"2시간","ticket":"3,000원(어린이 1,500원), 65세 이상 무료","openingHours":"09:00~19:00(3~10월), 09:00~18:00(11~2월)","galleryCaptions":["대숲 사이의 산책로"]},"ja":{"name":"潭陽 竹緑苑","summary":"31ヘクタールの竹林に八つの散策路。真夏でも涼しい。","story":"潭陽は何百年も竹で暮らしてきた。籠、箸、扇、そして竹筒で炊いた飯まで。竹緑苑はその竹林を開放した場所で、「恋人の道」「思索の道」といった名の八つの小道がある。中に入ると笹の葉が擦れ合う音が、他では聞けない響きをつくり、気温が数度下がる。近くには韓国屈指の美しさとされる2kmのメタセコイア並木がある。","facts":["約31ヘクタールの植栽竹林に八つの散策路がある。","潭陽は韓国で最も名高い竹の里。","近くのメタセコイア並木は約2km続く。","竹筒飯（テトンパプ）が地元の名物。"],"travelTips":["入口の食堂で竹筒飯を食べてみよう。","車で10分のメタセコイア並木も同じ日に歩こう。","光州からバスで約40分。"],"bestTime":"5〜10月","visitDuration":"2時間","ticket":"3,000ウォン（子ども1,500）、65歳以上は無料","openingHours":"09:00〜19:00（3〜10月）、09:00〜18:00（11〜2月）","galleryCaptions":["竹林の中の散策路"]},"zh":{"name":"潭陽竹綠苑","summary":"三十一公頃的人造竹林，八條步道，盛夏也涼爽。","story":"潭陽靠竹子過活已有數百年：竹籃、筷子、扇子，還有裝在竹筒裡蒸的飯。竹綠苑是對外開放的竹林，八條步道各有名字，像「情人之路」「沉思之路」。走進去，竹葉相擦的聲音是別處聽不到的，氣溫也低了幾度。附近則是兩公里長的水杉大道，堪稱韓國最美的道路之一。","facts":["約31公頃的人造竹林，設有八條步道。","潭陽是韓國最著名的竹鄉。","附近的水杉大道長約2公里。","竹筒飯是當地招牌。"],"travelTips":["在竹林入口的餐館嚐嚐竹筒飯。","同一個下午可順道走水杉大道，車程十分鐘。","自光州搭公車約40分鐘。"],"bestTime":"5至10月","visitDuration":"2小時","ticket":"3,000韓元（兒童1,500）；65歲以上免費","openingHours":"09:00–19:00（3至10月）、09:00–18:00（11至2月）","galleryCaptions":["竹林間的步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('songgwangsa', 'songgwangsa', 'jeonnam', 'Chùa Songgwangsa', 'Songgwangsa Temple', 'unesco', 127.2735, 35.0005, 'Một trong ba ngôi chùa bảo vật của Hàn Quốc, nơi sinh ra mười sáu vị quốc sư liên tiếp.', 'Phật giáo Hàn Quốc có ba ngôi chùa gọi là ''Tam Bảo tự'', mỗi ngôi đại diện cho một trong ba ngôi báu. Songgwangsa là Tăng bảo — chùa của tăng đoàn — vì trong hai thế kỷ nó đã đào tạo ra mười sáu vị quốc sư liên tiếp, điều không ngôi chùa nào khác làm được. Nơi đây vẫn là một trong những trung tâm thiền nghiêm ngặt nhất Hàn Quốc, và một phần khuôn viên đóng cửa với khách để tăng chúng tu tập. Cầu gỗ có mái Cheongnyanggak bắc qua suối trước cổng chùa là hình ảnh được chụp nhiều nhất. Chùa cũng là nơi thầy Kusan mở khoá thiền cho người nước ngoài từ thập niên 1970, sớm hơn hầu hết chùa Hàn Quốc.', '["Là một trong ba ''Tam Bảo tự'' của Phật giáo Hàn Quốc, đại diện cho Tăng bảo.","Đã đào tạo 16 vị quốc sư liên tiếp trong thời Goryeo.","Được UNESCO ghi danh năm 2018 trong cụm ''Sansa, chùa núi Hàn Quốc''.","Cầu gỗ có mái Cheongnyanggak bắc qua suối trước cổng chùa."]', '["Một số khu vực đóng cửa với khách vì tăng chúng đang nhập thất.","Có chương trình templestay nhiều ngày, đăng ký trước.","Kết hợp với vịnh Suncheonman cách đó khoảng 40 phút xe."]', 'Tháng 4–6 và 10–11', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '07:00–19:00', '["unesco","hidden-gem"]', '["UNESCO","chùa","thiền","templestay"]', '[{"seed":"songgwangsa","caption":"Cầu gỗ có mái trước cổng chùa","ratio":"16/9"}]', '["suncheonman-bay"]', 0, 'https://www.cctoday.co.kr/news/articleView.html?idxno=2177268', '2026-08-04', '{"en":{"name":"Songgwangsa Temple","summary":"One of Korea''s three jewel temples, which produced sixteen national preceptors in succession.","story":"Korean Buddhism has three ''jewel temples'', each standing for one of the Three Jewels. Songgwangsa is the Sangha jewel — the temple of the monastic community — because over two centuries it produced sixteen national preceptors one after another, which no other temple managed. It remains one of the strictest meditation centres in Korea, and part of the compound is closed to visitors so the monks can practise. The roofed wooden bridge Cheongnyanggak over the stream at the gate is the most photographed view. It was also here that Master Kusan opened meditation courses to foreigners in the 1970s, earlier than almost any Korean temple.","facts":["One of Korean Buddhism''s three jewel temples, representing the Sangha.","It produced sixteen national preceptors in succession during the Goryeo era.","Inscribed by UNESCO in 2018 as part of the Sansa mountain monasteries.","The roofed wooden Cheongnyanggak bridge crosses the stream at the gate."],"travelTips":["Parts of the compound are closed while the monks are in retreat.","Multi-day templestays are offered; book ahead.","Combine it with Suncheonman bay, about 40 minutes away by car."],"bestTime":"April–June and October–November","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"07:00–19:00","galleryCaptions":["The roofed wooden bridge at the temple gate"]},"ko":{"name":"송광사","summary":"한국 삼보사찰의 하나. 국사 열여섯 분을 잇달아 배출했다.","story":"한국 불교에는 삼보를 각각 상징하는 삼보사찰이 있다. 송광사는 승보사찰이다. 두 세기에 걸쳐 국사 열여섯 분을 잇달아 배출했기 때문인데, 다른 어느 절도 해내지 못한 일이다. 지금도 한국에서 가장 엄격한 선원 가운데 하나이고, 스님들의 수행을 위해 경내 일부는 방문객에게 닫혀 있다. 일주문 앞 개울을 건너는 지붕 얹은 나무다리 청량각이 가장 많이 찍히는 자리다. 구산 스님이 1970년대에 외국인을 위한 참선 과정을 연 곳도 여기다. 한국 절 가운데 이례적으로 이른 시도였다.","facts":["삼보사찰 가운데 승보사찰이다.","고려 시대에 국사 열여섯 분을 잇달아 배출했다.","2018년 ''산사, 한국의 산지 승원''으로 유네스코에 등재되었다.","일주문 앞 개울에 지붕 얹은 나무다리 청량각이 있다."],"travelTips":["스님들이 안거에 들면 경내 일부가 닫힌다.","여러 날 머무는 템플스테이가 있으니 미리 예약하자.","차로 40분 거리의 순천만과 묶어서 보자."],"bestTime":"4~6월, 10~11월","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"07:00~19:00","galleryCaptions":["일주문 앞의 지붕 얹은 나무다리"]},"ja":{"name":"松広寺","summary":"韓国三宝寺刹のひとつ。十六人の国師を続けて輩出した。","story":"韓国仏教には三宝をそれぞれ象徴する三つの寺がある。松広寺は僧宝寺刹だ。二世紀にわたって十六人の国師を続けて出したからで、ほかのどの寺も成し得なかった。今も韓国で最も厳格な禅院のひとつであり、僧の修行のため境内の一部は参拝者に閉ざされている。一柱門の前の谷川に架かる屋根つきの木橋・清涼閣が最も撮られる場所だ。九山禅師が1970年代に外国人向けの参禅講座を開いたのもここで、韓国の寺としては異例に早い試みだった。","facts":["三宝寺刹のうち僧宝寺刹にあたる。","高麗時代に十六人の国師を続けて輩出した。","2018年「山寺、韓国の山地僧院」としてユネスコに登録された。","一柱門前の谷川に屋根つきの木橋・清涼閣が架かる。"],"travelTips":["僧が安居に入ると境内の一部は閉じられる。","数日滞在するテンプルステイがある。予約を。","車で40分の順天湾と合わせて回ろう。"],"bestTime":"4〜6月、10〜11月","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"07:00〜19:00","galleryCaptions":["一柱門前の屋根つき木橋"]},"zh":{"name":"松廣寺","summary":"韓國三寶寺剎之一，接連出過十六位國師。","story":"韓國佛教有三座「三寶寺剎」，各自代表三寶其一。松廣寺是僧寶寺剎——僧團之寺——因為兩個世紀之間，它接連培養出十六位國師，這是其他寺院都做不到的。它至今仍是韓國最嚴格的禪修中心之一，部分院區不對訪客開放，好讓僧眾安心用功。山門前跨溪的有頂木橋清涼閣，是最常入鏡的一景。1970年代九山禪師也在此為外國人開設參禪課程，在韓國寺院中算相當早的嘗試。","facts":["韓國三寶寺剎之一，代表僧寶。","高麗時期接連出過十六位國師。","2018年以「山寺，韓國的山地僧院」列入世界遺產。","山門前的溪上架有有頂木橋清涼閣。"],"travelTips":["僧眾結夏安居期間，部分院區會關閉。","設有多日的寺廟寄宿，請提前預約。","可與車程約40分鐘的順天灣排在一起。"],"bestTime":"4至6月與10至11月","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"07:00–19:00","galleryCaptions":["山門前的有頂木橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('naganeupseong', 'naganeupseong', 'jeonnam', 'Thành làng Naganeupseong', 'Naganeupseong Walled Town', 'village', 127.3475, 34.9145, 'Toà thành Joseon còn nguyên tường bao, và bên trong vẫn là một ngôi làng có người ở thật.', 'Naganeupseong là thứ rất hiếm: một eupseong — thành bao quanh cả một thị trấn hành chính, không phải pháo đài quân sự — còn nguyên vẹn, và bên trong tường vẫn còn khoảng một trăm gia đình sinh sống. Bạn đi trên mặt tường thành cao bốn mét nhìn xuống những mái tranh xếp thành phố, khói bếp bốc lên buổi chiều, và người dân thật sự đang phơi ớt trước sân. Không có nhà nào được lắp cửa nhôm hay mái tôn. Đây là bối cảnh phim cổ trang quen thuộc, nhưng khác các phim trường ở chỗ nó chưa từng ngừng là một ngôi làng.', '["Tường thành xây từ năm 1397, dài khoảng 1,4 km và cao 4m.","Khoảng 100 hộ gia đình vẫn sinh sống bên trong thành.","Là một trong số ít eupseong (thành bao quanh thị trấn) còn nguyên vẹn ở Hàn Quốc.","Nhà trong thành giữ nguyên mái tranh, không dùng vật liệu hiện đại."]', '["Đi trọn vòng tường thành mất khoảng 30 phút, nên đi lúc chiều muộn.","Có thể ngủ lại trong một số nhà tranh trong thành, đặt trước.","Đây là làng có người ở — không tự ý vào sân hay mở cửa nhà."]', 'Tháng 4–6 và 9–11', '2 giờ', '4.000 KRW; nằm trong vé gộp Suncheon 12.000 KRW', '09:00–18:00', '["hidden-gem","verified"]', '["thành cổ","làng","mái tranh","Joseon"]', '[{"seed":"naganeupseong","caption":"Mái tranh nhìn từ tường thành","ratio":"16/9"}]', '["suncheonman-bay","songgwangsa"]', 0, 'https://www.suncheonbaygarden.com/', '2026-08-04', '{"en":{"name":"Naganeupseong Walled Town","summary":"An intact Joseon town wall — and inside it, a village people still live in.","story":"Naganeupseong is a rare thing: an eupseong — a wall around an entire administrative town rather than a military fort — still complete, with about a hundred families living inside it. You walk the four-metre wall looking down on thatched roofs laid out as streets, cooking smoke rising in the evening, and people actually drying chillies in their yards. Not one house has aluminium windows or a tin roof. It is a familiar backdrop for historical dramas, but unlike a film set it never stopped being a village.","facts":["The wall dates from 1397, runs about 1.4km and stands 4m high.","Around 100 households still live inside the walls.","One of very few intact eupseong (town-enclosing walls) left in Korea.","The houses keep their thatch, with no modern materials permitted."],"travelTips":["Walking the full circuit of the wall takes about 30 minutes; go late in the day.","You can stay overnight in some of the thatched houses; book ahead.","People live here — don''t wander into yards or open doors."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"4,000 KRW; included in the 12,000 KRW Suncheon integrated ticket","openingHours":"09:00–18:00","galleryCaptions":["Thatched roofs seen from the town wall"]},"ko":{"name":"낙안읍성","summary":"성벽이 온전히 남은 조선의 읍성. 그 안은 지금도 사람이 사는 마을이다.","story":"낙안읍성은 드문 것이다. 군사 요새가 아니라 행정 고을 전체를 두른 읍성이 온전히 남아 있고, 성벽 안에 백여 가구가 여전히 살고 있다. 높이 4m의 성벽 위를 걸으며 초가지붕이 골목을 이룬 모습을 내려다보면, 저녁이면 밥 짓는 연기가 오르고 마당에는 고추가 널려 있다. 알루미늄 새시나 함석지붕을 올린 집은 한 채도 없다. 사극의 익숙한 배경이지만, 세트장과 다른 점은 이곳이 한 번도 마을이기를 그만둔 적이 없다는 것이다.","facts":["성벽은 1397년에 쌓았고 길이 약 1.4km, 높이 4m다.","성 안에 100여 가구가 지금도 살고 있다.","한국에 온전히 남은 몇 안 되는 읍성 가운데 하나다.","성 안의 집은 초가를 유지하며 현대 자재를 쓰지 않는다."],"travelTips":["성벽을 한 바퀴 도는 데 30분쯤 걸린다. 해 질 무렵이 좋다.","성 안 초가에서 하룻밤 묵을 수 있다. 예약이 필요하다.","사람이 사는 마을이다. 마당에 들어가거나 문을 열지 말자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"4,000원, 12,000원 순천 통합권에 포함","openingHours":"09:00~18:00","galleryCaptions":["성벽에서 내려다본 초가지붕"]},"ja":{"name":"楽安邑城","summary":"城壁がそのまま残る朝鮮の邑城。その内側は今も人が暮らす村だ。","story":"楽安邑城は稀なものだ。軍事の砦ではなく行政の町ごと囲んだ邑城が完全な形で残り、壁の内に百戸ほどが今も暮らしている。高さ四メートルの城壁の上を歩けば、茅葺きの屋根が路地をなし、夕方には煮炊きの煙が立ち、庭には唐辛子が干してある。アルミサッシもトタン屋根も一軒としてない。時代劇でおなじみの背景だが、セットと違うのは、ここが一度も村であることをやめなかった点だ。","facts":["城壁は1397年築、長さ約1.4km、高さ4mである。","城壁の内側に約100世帯が今も暮らす。","韓国に完全な形で残る数少ない邑城のひとつ。","城内の家は茅葺きを保ち、近代的な資材を使わない。"],"travelTips":["城壁を一周すると30分ほど。日暮れ時がよい。","城内の茅葺きの家に泊まれる。予約が必要だ。","人が暮らす村である。庭に入ったり戸を開けたりしないこと。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"4,000ウォン、12,000ウォンの順天統合券に含まれる","openingHours":"09:00〜18:00","galleryCaptions":["城壁から見下ろす茅葺きの屋根"]},"zh":{"name":"樂安邑城","summary":"城牆完整保留的朝鮮邑城，而牆內至今仍是一座有人居住的村落。","story":"樂安邑城是很稀有的東西：一座圍住整個行政市鎮、而非軍事堡壘的「邑城」完整留存，城牆內還住著大約一百戶人家。你走在四公尺高的城牆上往下看，茅草屋頂排成街巷，傍晚炊煙升起，院子裡真的有人在曬辣椒。沒有任何一戶裝鋁窗或鐵皮屋頂。這裡是古裝劇熟悉的背景，但和片場不同的是——它從來沒有停止當一座村子。","facts":["城牆築於1397年，長約1.4公里、高4公尺。","城牆內至今仍有約100戶人家居住。","是韓國少數完整保存的邑城之一。","城內房舍維持茅頂，不得使用現代建材。"],"travelTips":["繞城牆一圈約需30分鐘，建議傍晚前往。","可在城內部分茅草屋過夜，需提前預訂。","這是有人居住的村子，請勿擅入院落或推門。"],"bestTime":"4至6月與9至11月","visitDuration":"2小時","ticket":"4,000韓元；已含在12,000韓元的順天聯票中","openingHours":"09:00–18:00","galleryCaptions":["自城牆俯瞰的茅草屋頂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('wando-cheongsando', 'wando-cheongsando', 'jeonnam', 'Đảo Cheongsando (Wando)', 'Cheongsando Island, Wando', 'island', 126.8935, 34.1685, 'Hòn đảo ''chậm'' đầu tiên của châu Á, có ruộng bậc thang tưới bằng hệ mương đá cổ.', 'Cheongsando được công nhận là ''Slow City'' đầu tiên của châu Á, và cái danh ấy không phải khẩu hiệu du lịch — hòn đảo thật sự chậm. Ruộng bậc thang gudeuljangnon ở đây dùng một hệ thống độc đáo: người ta xếp đá thành các mương ngầm dưới lớp đất ruộng, giống hệt cách làm sàn sưởi ondol trong nhà, để giữ nước trên nền đá không thấm. Kỹ thuật này được FAO công nhận là di sản nông nghiệp toàn cầu. Đường mòn quanh đảo dài mười một chặng đi qua ruộng bậc thang, đồng cải vàng vào tháng 4, và những bức tường đá thấp chắn gió biển. Phim ''Xuân, Hạ, Thu, Đông rồi lại Xuân'' và vài phim khác quay ở đây.', '["Là thành phố chậm (Cittaslow) đầu tiên được công nhận ở châu Á, năm 2007.","Ruộng bậc thang gudeuljangnon dùng mương đá ngầm theo nguyên lý sàn ondol.","Hệ ruộng này được FAO công nhận là Di sản Nông nghiệp Quan trọng Toàn cầu.","Đảo có 11 chặng đường mòn đi bộ quanh bờ."]', '["Phà từ Wando mất khoảng 50 phút; kiểm tra lịch trước vì phụ thuộc thời tiết.","Tháng 4 là mùa hoa cải vàng phủ kín ruộng bậc thang.","Trên đảo ít phương tiện — thuê xe đạp hoặc đi bộ là hợp lý nhất."]', 'Tháng 4 (hoa cải) và tháng 9–10', 'Cả ngày', 'Phà một chiều khoảng 8.700 KRW (khứ hồi khoảng 17.400); mang ô tô theo đắt hơn nhiều', 'Theo lịch phà', '["hidden-gem"]', '["đảo","ruộng bậc thang","slow city","đi bộ"]', '[{"seed":"wando-cheongsando","caption":"Ruộng bậc thang trên đảo Cheongsando","ratio":"16/9"}]', '["hyangiram"]', 0, 'https://www.wando.go.kr/wando/sub.cs?m=351', '2026-08-04', '{"en":{"name":"Cheongsando Island, Wando","summary":"Asia''s first ''slow'' island, with terraced paddies watered through an ancient stone conduit system.","story":"Cheongsando was designated Asia''s first Slow City, and the title is not a tourism slogan — the island really is slow. Its gudeuljangnon terraced paddies use a system found nowhere else: stones are laid as hidden channels beneath the soil, exactly the way an ondol underfloor heating system is built, to hold water on ground that will not otherwise keep it. The FAO recognises it as a globally important agricultural heritage system. Eleven walking stages ring the island, past the terraces, rapeseed fields in April, and low stone walls set against the sea wind. Several Korean films were shot here.","facts":["Designated Asia''s first Cittaslow in 2007.","The gudeuljangnon terraces use hidden stone channels on the ondol principle.","The FAO recognises the system as Globally Important Agricultural Heritage.","Eleven walking stages ring the island''s coast."],"travelTips":["The ferry from Wando takes about 50 minutes; check ahead, it is weather-dependent.","April is when rapeseed flowers cover the terraces.","There is little transport on the island — a bike or your own feet make most sense."],"bestTime":"April (rapeseed) and September–October","visitDuration":"A full day","ticket":"The ferry is about 8,700 KRW one way (roughly 17,400 return); taking a car costs far more","openingHours":"By ferry schedule","galleryCaptions":["Terraced paddies on Cheongsando"]},"ko":{"name":"완도 청산도","summary":"아시아 최초의 슬로시티 섬. 옛 돌 수로로 물을 대는 구들장논이 있다.","story":"청산도는 아시아 최초의 슬로시티로 지정되었고, 그 이름은 관광 구호가 아니다. 섬은 정말로 느리다. 이곳의 구들장논은 다른 데 없는 방식을 쓴다. 흙 아래에 돌을 깔아 숨은 물길을 내는데, 집 안의 온돌을 놓는 방식과 똑같다. 물이 새는 땅에 물을 가두기 위해서다. FAO는 이 논을 세계중요농업유산으로 인정했다. 섬을 두르는 열한 개의 걷는 길이 구들장논과 4월의 유채밭, 바닷바람을 막는 낮은 돌담을 지난다. 여러 편의 한국 영화가 여기서 찍혔다.","facts":["2007년 아시아 최초의 슬로시티(치타슬로)로 지정되었다.","구들장논은 온돌 원리를 쓴 숨은 돌 수로로 물을 가둔다.","FAO가 세계중요농업유산으로 인정했다.","섬 해안을 따라 열한 개의 걷는 길이 있다."],"travelTips":["완도에서 배로 50분쯤 걸린다. 날씨에 좌우되니 미리 확인하자.","4월이면 유채꽃이 구들장논을 덮는다.","섬에 교통편이 적다. 자전거나 도보가 가장 합리적이다."],"bestTime":"4월(유채)과 9~10월","visitDuration":"하루","ticket":"여객선 편도 약 8,700원(왕복 약 17,400원), 차량 선적은 훨씬 비싸다","openingHours":"배편 운항 일정에 따름","galleryCaptions":["청산도의 구들장논"]},"ja":{"name":"莞島青山島","summary":"アジア初のスローシティの島。古い石の水路で水を張る棚田がある。","story":"青山島はアジアで初めてスローシティに指定され、その名は観光の標語ではない。島は本当に遅い。ここのクドゥルジャン棚田はほかにない仕組みを使う。土の下に石を敷いて隠れた水路を作るのだが、家のオンドルを敷くやり方とまったく同じだ。水の抜ける土地に水を溜めるためである。FAOはこの棚田を世界農業遺産と認めた。島を巡る十一の歩く道が、棚田と四月の菜の花畑、潮風を遮る低い石垣を通る。韓国映画の何本かがここで撮られた。","facts":["2007年、アジアで初めてチッタスローに指定された。","クドゥルジャン棚田はオンドルの原理による隠れた石水路で水を保つ。","FAOが世界重要農業遺産として認定している。","島の海岸沿いに十一の歩行コースがある。"],"travelTips":["莞島から船で50分ほど。天候次第なので事前に確認を。","4月には菜の花が棚田を覆う。","島に交通が少ない。自転車か徒歩が最も理にかなう。"],"bestTime":"4月（菜の花）と9〜10月","visitDuration":"一日","ticket":"船は片道約8,700ウォン（往復約17,400）、車を載せるとかなり高くなる","openingHours":"船の運航ダイヤによる","galleryCaptions":["青山島の棚田"]},"zh":{"name":"莞島青山島","summary":"亞洲第一座「慢城」島嶼，梯田以古老的石造暗渠灌溉。","story":"青山島被指定為亞洲第一座慢城，而這個名號不是觀光口號——這座島是真的慢。島上的「溫突梯田」用的是別處沒有的做法：在田土之下鋪石造出暗渠，跟屋內鋪設溫突地暖的方式一模一樣，好把水留在原本存不住水的地面上。聯合國糧農組織認定它為全球重要農業遺產。十一段步道環繞全島，經過梯田、四月的油菜花田，以及擋海風的矮石牆。多部韓國電影在此取景。","facts":["2007年成為亞洲第一座慢城（Cittaslow）。","溫突梯田以溫突原理的暗渠石道保水。","獲聯合國糧農組織認定為全球重要農業遺產。","沿島海岸共有11段步行路線。"],"travelTips":["自莞島搭船約50分鐘，班次受天候影響，請先確認。","四月油菜花會覆蓋整片梯田。","島上交通稀少，租單車或步行最合理。"],"bestTime":"4月（油菜花）與9至10月","visitDuration":"一整天","ticket":"渡船單程約8,700韓元（來回約17,400）；載車費用高出許多","openingHours":"依船班時刻","galleryCaptions":["青山島的梯田"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jindo-sea-parting', 'jindo-sea-parting', 'jeonnam', 'Con đường rẽ biển Jindo', 'Jindo Sea Parting', 'beach', 126.3585, 34.4145, 'Mỗi năm vài lần, thuỷ triều rút để lộ một con đường đá dài gần ba cây số nối hai hòn đảo.', 'Vài lần mỗi năm, khi mặt trăng ở đúng vị trí, mực nước giữa Jindo và đảo Modo hạ xuống đủ để lộ ra một dải đá ngầm rộng chừng bốn chục mét và dài gần ba cây số — và người ta đi bộ qua đó, giữa biển. Hiện tượng chỉ kéo dài khoảng một tiếng rồi nước quay lại. Truyền thuyết địa phương kể rằng dân làng chạy hổ ra đảo Modo bỏ quên một bà cụ, bà cầu Long Vương suốt nhiều ngày, và biển rẽ ra cho bà đi. Lễ hội rẽ biển tổ chức đúng dịp này với đèn lồng và đội trống. Jindo cũng là quê của giống chó Jindo, được xếp hạng đài kỷ niệm thiên nhiên.', '["Con đường lộ ra dài khoảng 2,8 km và rộng chừng 40m.","Hiện tượng xảy ra vài lần mỗi năm và kéo dài khoảng một giờ.","Lễ hội rẽ biển Jindo tổ chức vào dịp thuỷ triều thấp nhất, thường tháng 3–4.","Giống chó Jindo là Đài kỷ niệm thiên nhiên số 53 của Hàn Quốc."]', '["Ngày và giờ rẽ biển thay đổi theo năm — tra lịch của huyện Jindo trước khi đặt vé.","Mang ủng cao su; ban tổ chức có cho thuê tại chỗ.","Nước quay lại nhanh, đừng nán lại quá giờ ban tổ chức thông báo."]', 'Tháng 3–4 (lễ hội rẽ biển)', 'Nửa ngày', 'Miễn phí; chỉ một số hoạt động trải nghiệm mới thu tiền', 'Đường biển chỉ mở khi triều xuống thấp nhất, mỗi lần khoảng một giờ, và giờ đó đổi từng ngày. Lễ hội tổ chức bốn ngày vào mùa xuân — hãy tra lịch triều của năm đó và đến sớm 1–2 tiếng, vì lối đi hiện dần chứ không mở đột ngột', '["festival","verified"]', '["thuỷ triều","lễ hội","biển","hiện tượng tự nhiên"]', '[{"seed":"jindo-sea-parting","caption":"Người đi bộ trên con đường biển rẽ","ratio":"16/9"}]', '["wando-cheongsando"]', 1, 'https://korean.visitkorea.or.kr/kfes/detail/fstvlDetail.do?fstvlCntntsId=e6b3596c-3769-41a2-9090-84a7585db5e0', '2026-08-05', '{"en":{"name":"Jindo Sea Parting","summary":"A few times a year the tide drops to reveal a rock road nearly three kilometres long between two islands.","story":"A few times a year, when the moon is in the right place, the water between Jindo and Modo island falls far enough to expose a reef about forty metres wide and nearly three kilometres long — and people walk across it, out in the sea. It lasts about an hour before the water returns. Local legend says villagers fleeing tigers to Modo left an old woman behind; she prayed to the Dragon King for days, and the sea opened for her. A festival with lanterns and drum troupes is held for the occasion. Jindo is also home to the Jindo dog, a designated natural monument.","facts":["The exposed road is about 2.8km long and some 40m wide.","It happens a few times a year and lasts roughly an hour.","The Jindo sea-parting festival is held at the lowest tides, usually March–April.","The Jindo dog is Korea''s Natural Monument No. 53."],"travelTips":["The dates and times shift each year — check Jindo county''s calendar before booking.","Bring rubber boots; the organisers also rent them on site.","The water returns quickly; don''t linger past the announced window."],"bestTime":"March–April (the sea-parting festival)","visitDuration":"Half a day","ticket":"Free; only some of the hands-on activities are ticketed","openingHours":"The sea road only opens at the lowest tide, for about an hour, and the time shifts every day. The festival runs four days in spring — look up that year''s tide table and arrive one or two hours early, since the path emerges gradually rather than all at once","galleryCaptions":["Walkers on the parted sea road"]},"ko":{"name":"진도 신비의 바닷길","summary":"해마다 몇 차례, 물이 빠지며 두 섬을 잇는 3km 가까운 바닷길이 드러난다.","story":"해마다 몇 번, 달이 제자리에 오면 진도와 모도 사이의 물이 충분히 빠져 폭 사십 미터, 길이 삼 킬로미터에 가까운 여울목이 드러난다. 그러면 사람들이 바다 한가운데를 걸어서 건넌다. 한 시간쯤 지나면 물이 돌아온다. 전설은 이렇다. 호랑이를 피해 모도로 건너간 마을 사람들이 할머니 한 분을 두고 갔고, 할머니가 여러 날 용왕에게 빌자 바다가 갈라져 길을 냈다는 것이다. 이 시기에 맞춰 등불과 풍물패가 나오는 축제가 열린다. 진도는 천연기념물인 진돗개의 고향이기도 하다.","facts":["드러나는 길은 길이 약 2.8km, 폭 40m가량이다.","해마다 몇 차례 일어나며 한 시간쯤 이어진다.","신비의 바닷길 축제는 물이 가장 많이 빠지는 3~4월에 열린다.","진돗개는 천연기념물 제53호다."],"travelTips":["날짜와 시각이 해마다 다르다. 진도군 일정을 확인하고 예매하자.","장화를 챙기자. 현장에서 빌려주기도 한다.","물이 빨리 돌아온다. 안내된 시간을 넘겨 머물지 말자."],"bestTime":"3~4월(바닷길 축제)","visitDuration":"반나절","ticket":"무료이며 일부 체험 프로그램만 유료다","openingHours":"바닷길은 조위가 가장 낮아질 때 한 시간 남짓만 열리고 그 시각은 날마다 다르다. 축제는 봄에 나흘간 열리므로 그해 물때표를 확인하고 1~2시간 일찍 도착하자. 길은 서서히 드러난다","galleryCaptions":["갈라진 바닷길을 걷는 사람들"]},"ja":{"name":"珍島の神秘の海割れ","summary":"年に数度、潮が引いて二つの島を結ぶ3km近い海の道が現れる。","story":"年に数度、月が然るべき位置に来ると、珍島と茅島のあいだの水が十分に引き、幅四十メートル、長さ三キロ近い浅瀬が姿を現す。すると人々は海の真ん中を歩いて渡る。一時間ほどで水は戻る。伝説はこうだ。虎を逃れて茅島へ渡った村人たちが老婆をひとり置き去りにし、老婆が幾日も龍王に祈ると海が割れて道ができた。この時期に合わせて提灯と農楽隊の出る祭りが開かれる。珍島は天然記念物である珍島犬の故郷でもある。","facts":["現れる道は長さ約2.8km、幅40mほど。","年に数回起こり、一時間ほど続く。","神秘の海割れ祭りは潮が最も引く3〜4月に開かれる。","珍島犬は天然記念物第53号である。"],"travelTips":["日付と時刻は年ごとに変わる。珍島郡の日程を確認してから予約しよう。","長靴を用意しよう。現地で貸し出しもある。","水はすぐ戻る。案内された時間を過ぎて留まらないこと。"],"bestTime":"3〜4月（海割れ祭り）","visitDuration":"半日","ticket":"無料で、一部の体験プログラムのみ有料","openingHours":"海の道は干潮の最も低い時にだけ約1時間開き、その時刻は日ごとに変わる。祭りは春に4日間。その年の潮見表を確認し、1〜2時間前に到着したい。道は徐々に現れる","galleryCaptions":["割れた海の道を歩く人々"]},"zh":{"name":"珍島神祕海路","summary":"每年幾次，潮水退去，露出一條近三公里、連接兩座島的岩石之路。","story":"每年幾次，當月亮走到對的位置，珍島與茅島之間的水位會退得夠低，露出一條寬約四十公尺、長近三公里的礁石帶——人們就走在海中央過去。這條路只維持約一小時，水就回來了。當地傳說：村民為躲老虎逃往茅島時，丟下了一位老婦；她向龍王祈禱多日，海便為她分開。當地會配合這個時節舉辦提燈與農樂隊的慶典。珍島也是天然紀念物珍島犬的故鄉。","facts":["露出的路長約2.8公里、寬約40公尺。","每年出現數次，每次持續約一小時。","神祕海路慶典在潮位最低時舉行，通常為3至4月。","珍島犬是韓國天然紀念物第53號。"],"travelTips":["日期與時間每年不同——訂票前先查珍島郡的行事曆。","帶雨鞋，主辦單位現場也有出租。","海水回來得很快，別超過公告時間逗留。"],"bestTime":"3至4月（神祕海路慶典）","visitDuration":"半天","ticket":"免費，僅部分體驗活動收費","openingHours":"海路只在潮位最低時開啟約一小時，時刻每天不同。慶典於春季舉行四天——請查閱當年潮汐表並提早一至兩小時抵達，因為路是慢慢浮現的","galleryCaptions":["走在分開的海路上的人們"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('mokpo-modern-history', 'mokpo-modern-history', 'jeonnam', 'Phố cận đại Mokpo', 'Mokpo Modern History Quarter', 'city', 126.3875, 34.7845, 'Cảng khai thị năm 1897 với toà lãnh sự Nhật, hầm trú bom trong núi và những con dốc nhìn ra biển.', 'Mokpo mở cảng năm 1897 và nhanh chóng thành nơi người Nhật gom gạo Jeolla chở về chính quốc. Toà lãnh sự Nhật bằng gạch đỏ trên sườn đồi Yudalsan giờ là bảo tàng lịch sử cận đại, và ngay sau lưng nó là những đường hầm đào vào núi cuối Thế chiến II bằng lao động cưỡng bức. Xuống dốc là khu phố cũ với nhà kho, ngân hàng và các căn nhà kiểu Nhật còn nguyên. Mokpo cũng là thành phố của nhạc trot và của món cá đuối lên men hongeo — thứ khiến người mới ăn phải rơi nước mắt. Ban đêm, cầu treo Mokpo lên đèn và cả vịnh sáng lên.', '["Cảng Mokpo mở cửa năm 1897 theo hiệp ước.","Toà lãnh sự Nhật xây năm 1900, nay là Bảo tàng Lịch sử Cận đại Mokpo.","Sau lưng toà lãnh sự là hệ hầm đào vào núi Yudalsan cuối Thế chiến II.","Mokpo nổi tiếng với món cá đuối lên men hongeo và nhạc trot."]', '["Leo Yudalsan lúc hoàng hôn để nhìn toàn cảnh cảng và các đảo ngoài khơi.","Hongeo rất nặng mùi — người mới nên thử phần ''samhap'' ăn kèm thịt luộc và kimchi.","Tàu KTX từ Yongsan tới Mokpo mất khoảng 2,5 giờ."]', 'Tháng 4–6 và 9–11', 'Nửa ngày', '2.000 KRW (thiếu niên và quân nhân 1.000, học sinh tiểu học 500, mẫu giáo miễn phí)', '09:00–18:00, bảo tàng đóng cửa thứ Hai', '["hidden-gem"]', '["lịch sử cận đại","cảng biển","kiến trúc","ẩm thực"]', '[{"seed":"mokpo-modern-history","caption":"Toà lãnh sự Nhật cũ trên đồi Yudalsan","ratio":"16/9"}]', '["jindo-sea-parting"]', 0, 'https://www.mpcc1897.or.kr/base/culturalSpace/read?culturalSpaceNo=27', '2026-08-04', '{"en":{"name":"Mokpo Modern History Quarter","summary":"A port opened in 1897, with a Japanese consulate, tunnels dug into the hill and lanes running down to the sea.","story":"Mokpo opened as a port in 1897 and quickly became the place from which the Japanese shipped Jeolla''s rice home. The red-brick Japanese consulate on the flank of Yudalsan is now the modern history museum, and directly behind it are tunnels driven into the hill by forced labour at the end of the Second World War. Downhill lies the old quarter of warehouses, banks and intact Japanese houses. Mokpo is also a city of trot music and of hongeo, fermented skate — which reduces first-timers to tears. At night the Mokpo suspension bridge lights up and the whole bay with it.","facts":["Mokpo port opened by treaty in 1897.","The Japanese consulate, built in 1900, is now the Mokpo Modern History Museum.","Tunnels behind the consulate were driven into Yudalsan late in the Second World War.","Mokpo is known for fermented skate (hongeo) and for trot music."],"travelTips":["Climb Yudalsan at sunset for the view over the port and the offshore islands.","Hongeo is pungent — beginners should try it as ''samhap'', with boiled pork and kimchi.","The KTX from Yongsan to Mokpo takes about 2.5 hours."],"bestTime":"April–June and September–November","visitDuration":"Half a day","ticket":"2,000 KRW (1,000 teens and soldiers, 500 primary pupils, free for preschoolers)","openingHours":"09:00–18:00, museum closed Mondays","galleryCaptions":["The old Japanese consulate on Yudalsan"]},"ko":{"name":"목포 근대역사거리","summary":"1897년 개항한 항구. 일본 영사관과 산속 방공호, 바다로 내려가는 골목이 남았다.","story":"목포는 1897년 개항했고, 곧 일본이 전라도의 쌀을 실어 가는 항구가 되었다. 유달산 자락의 붉은 벽돌 일본영사관은 지금 근대역사관이고, 그 바로 뒤에는 태평양전쟁 말기에 강제동원으로 판 굴이 남아 있다. 언덕을 내려가면 창고와 은행, 일본식 가옥이 그대로 남은 옛 거리가 이어진다. 목포는 트로트의 도시이자 홍어의 도시이기도 하다. 처음 먹는 사람은 눈물을 흘린다. 밤이면 목포대교에 불이 들어오고 만 전체가 밝아진다.","facts":["목포항은 1897년 조약에 따라 개항했다.","1900년에 지은 일본영사관은 현재 목포근대역사관이다.","영사관 뒤편에는 태평양전쟁 말기 유달산에 판 굴이 있다.","목포는 홍어와 트로트로 유명하다."],"travelTips":["해 질 무렵 유달산에 올라 항구와 앞바다 섬들을 보자.","홍어는 냄새가 강하다. 처음이라면 삼합으로 먹어 보자.","용산에서 목포까지 KTX로 약 2시간 30분이다."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절","ticket":"2,000원(청소년·군인 1,000원, 초등학생 500원, 유치원생 무료)","openingHours":"09:00~18:00, 역사관은 월요일 휴관","galleryCaptions":["유달산 자락의 옛 일본영사관"]},"ja":{"name":"木浦近代歴史通り","summary":"1897年開港の港。日本領事館、山に掘られた防空壕、海へ下る路地が残る。","story":"木浦は1897年に開港し、まもなく日本が全羅道の米を積み出す港になった。儒達山の中腹の赤煉瓦の日本領事館は今は近代歴史館で、そのすぐ裏には太平洋戦争末期に強制動員で掘られた坑道が残る。坂を下れば倉庫や銀行、日本家屋がそのまま残る旧市街が続く。木浦はトロットの街であり、ホンオ（発酵エイ）の街でもある。初めて食べる人は涙を流す。夜になると木浦大橋に灯が入り、湾全体が明るくなる。","facts":["木浦港は1897年、条約により開港した。","1900年建設の日本領事館は現在の木浦近代歴史館である。","領事館の裏手には太平洋戦争末期に儒達山へ掘られた坑道がある。","木浦は発酵エイ（ホンオ）とトロットで知られる。"],"travelTips":["夕暮れに儒達山へ登り、港と沖の島々を眺めよう。","ホンオは匂いが強い。初めてなら三合で試そう。","龍山から木浦までKTXで約2時間30分。"],"bestTime":"4〜6月、9〜11月","visitDuration":"半日","ticket":"2,000ウォン（青少年・軍人1,000、小学生500、幼稚園児は無料）","openingHours":"09:00〜18:00、歴史館は月曜休館","galleryCaptions":["儒達山中腹の旧日本領事館"]},"zh":{"name":"木浦近代歷史街區","summary":"1897年開港的港口，留有日本領事館、鑿進山裡的坑道，以及通往海邊的坡巷。","story":"木浦1897年開港，很快成為日本把全羅道稻米運回本國的港口。儒達山腰的紅磚日本領事館如今是近代歷史館，就在它後方，是二戰末期以強制勞動鑿進山裡的坑道。往坡下走，是倉庫、銀行與完整日式住宅構成的舊街區。木浦同時也是演歌（trot）之城與洪魚之城——發酵魟魚讓初嘗者流淚。入夜後木浦大橋亮燈，整座海灣也跟著亮起來。","facts":["木浦港依條約於1897年開港。","1900年興建的日本領事館，現為木浦近代歷史館。","領事館後方是二戰末期鑿入儒達山的坑道。","木浦以發酵魟魚與演歌聞名。"],"travelTips":["黃昏登儒達山，俯瞰港口與外海島嶼。","洪魚氣味強烈，初嘗者建議吃「三合」——配水煮豬肉與泡菜。","自龍山搭KTX到木浦約2.5小時。"],"bestTime":"4至6月與9至11月","visitDuration":"半天","ticket":"2,000韓元（青少年與軍人1,000、小學生500、幼稚園生免費）","openingHours":"09:00–18:00，歷史館週一休館","galleryCaptions":["儒達山腰的舊日本領事館"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gurye-sansuyu', 'gurye-sansuyu', 'jeonnam', 'Làng hoa thù du Gurye', 'Gurye Sansuyu Village', 'village', 127.4625, 35.2555, 'Ngôi làng dưới chân Jirisan nơi hoa thù du vàng nở trước mọi loài hoa khác của mùa xuân Hàn Quốc.', 'Mỗi tháng 3, khi phần còn lại của Hàn Quốc vẫn còn xám, thung lũng Sandong ở Gurye đã vàng rực. Cây thù du sansuyu ở đây được trồng từ hơn một nghìn năm trước và giờ có hàng chục nghìn cây bao quanh các ngôi làng đá — hoa nở trước khi ra lá nên cả cây chỉ toàn màu vàng. Người dân sống bằng quả thù du phơi khô làm thuốc, và theo lời họ kể, ngày xưa con gái trong làng phải tách hạt bằng răng nên ai lấy vợ Sandong là được cả một nghề. Những bức tường đá xếp khan giữa các vườn cây làm nền cho toàn bộ khung cảnh.', '["Hoa thù du sansuyu nở giữa đến cuối tháng 3, sớm nhất trong các loài hoa xuân ở Hàn Quốc.","Vùng Sandong ở Gurye trồng thù du từ hơn một nghìn năm trước.","Quả thù du được phơi khô làm dược liệu, là nguồn thu chính của làng.","Lễ hội hoa thù du Gurye tổ chức vào tháng 3 hằng năm."]', '["Hoa nở khoảng hai tuần giữa tháng 3 — theo dõi lịch lễ hội.","Đi bộ theo các tường đá giữa vườn cây thay vì chỉ đứng ở khu lễ hội.","Kết hợp với vườn quốc gia Jirisan ngay bên cạnh."]', 'Giữa đến cuối tháng 3', 'Nửa ngày', '', 'Cả ngày', '["festival","hidden-gem"]', '["hoa xuân","làng","lễ hội","Jirisan"]', '[{"seed":"gurye-sansuyu","caption":"Hoa thù du vàng quanh tường đá làng Sandong","ratio":"16/9"}]', '["songgwangsa"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Gurye Sansuyu Village","summary":"A village below Jirisan where cornelian cherry blooms yellow before anything else in the Korean spring.","story":"Every March, while the rest of Korea is still grey, the Sandong valley at Gurye turns yellow. The sansuyu cornelian cherries here were planted more than a thousand years ago and now number in the tens of thousands around stone-walled hamlets — they flower before they leaf, so each tree is nothing but yellow. Villagers live on the dried fruit, sold as medicine, and they will tell you that the daughters of the village used to separate the stones with their teeth, so marrying a Sandong woman meant marrying a trade. Dry-stone walls between the orchards frame the whole scene.","facts":["Sansuyu blooms from mid to late March, earliest of Korea''s spring flowers.","The Sandong area of Gurye has grown sansuyu for over a thousand years.","The dried fruit is sold as medicine and is the villages'' main income.","The Gurye Sansuyu Festival is held each March."],"travelTips":["The bloom lasts about two weeks in mid-March — follow the festival dates.","Walk the stone walls between the orchards rather than standing in the festival area.","Combine it with Jirisan National Park next door."],"bestTime":"Mid to late March","visitDuration":"Half a day","ticket":"","openingHours":"All day","galleryCaptions":["Yellow sansuyu around the stone walls of Sandong"]},"ko":{"name":"구례 산수유마을","summary":"지리산 아래 마을. 한국의 봄에서 가장 먼저 노랗게 피는 산수유가 있다.","story":"해마다 3월, 나라의 나머지가 아직 잿빛일 때 구례 산동 골짜기는 노랗게 물든다. 이곳의 산수유는 천 년도 더 전에 심기 시작해 지금은 돌담 마을을 둘러싸고 수만 그루에 이른다. 잎보다 꽃이 먼저 나오니 나무 전체가 노란색뿐이다. 마을 사람들은 말린 산수유 열매를 약재로 팔아 살아왔고, 옛날엔 마을 처녀들이 이로 씨를 발라냈다며 산동 색시를 얻으면 기술까지 얻는다고 말한다. 과수원 사이의 마른 돌담이 이 풍경의 틀이 된다.","facts":["산수유는 3월 중순에서 말까지 피며, 한국의 봄꽃 가운데 가장 이르다.","구례 산동 일대는 천 년 넘게 산수유를 길러 왔다.","말린 열매는 약재로 팔리며 마을의 주 수입원이다.","구례 산수유꽃축제가 해마다 3월에 열린다."],"travelTips":["개화는 3월 중순의 두 주쯤이다. 축제 일정을 따라가자.","축제장에 서 있기보다 과수원 사이 돌담길을 걷자.","바로 옆 지리산국립공원과 묶어서 보자."],"bestTime":"3월 중순~하순","visitDuration":"반나절","ticket":"","openingHours":"상시","galleryCaptions":["산동마을 돌담을 두른 노란 산수유"]},"ja":{"name":"求礼サンシュユ村","summary":"智異山の麓の村。韓国の春でいちばん早く黄色く咲くサンシュユがある。","story":"毎年三月、国の他所がまだ灰色のころ、求礼の山洞の谷は黄色く染まる。ここのサンシュユは千年以上前から植えられ、いまは石垣の集落を囲んで数万本に及ぶ。葉より先に花が出るので、木は黄色だけになる。村人は乾かした実を薬材として売って暮らしてきた。昔は村の娘が歯で種を外したので、山洞の嫁をもらえば技まで手に入る、と彼らは言う。果樹園のあいだの空積みの石垣が、この風景の額縁になる。","facts":["サンシュユは3月中旬から下旬に咲き、韓国の春の花で最も早い。","求礼・山洞一帯は千年以上サンシュユを育ててきた。","乾かした実は薬材として売られ、村の主な収入源である。","求礼サンシュユ祭りが毎年3月に開かれる。"],"travelTips":["開花は3月中旬の二週間ほど。祭りの日程を追おう。","祭り会場に立つより、果樹園のあいだの石垣道を歩こう。","隣接する智異山国立公園と合わせて回ろう。"],"bestTime":"3月中旬〜下旬","visitDuration":"半日","ticket":"","openingHours":"終日","galleryCaptions":["山洞の石垣を囲む黄色いサンシュユ"]},"zh":{"name":"求禮山茱萸村","summary":"智異山腳下的村落，山茱萸在韓國的春天裡開得比任何花都早。","story":"每年三月，當韓國其他地方還是一片灰時，求禮的山洞谷地已經黃了。這裡的山茱萸從一千多年前開始種，如今環著石牆村落，數以萬計——它先開花後長葉，所以整棵樹只有黃色。村民靠曬乾的果實入藥維生，他們會告訴你，從前村裡的姑娘是用牙齒把果核剔出來的，所以娶到山洞媳婦等於連手藝一起娶回家。果園之間那些乾砌的石牆，為整片風景框出了邊界。","facts":["山茱萸於3月中下旬開花，是韓國春花中最早的。","求禮山洞一帶種植山茱萸已逾千年。","曬乾的果實作為藥材販售，是村落主要收入。","求禮山茱萸花節每年3月舉行。"],"travelTips":["花期約在三月中的兩週，請跟著花節日程走。","與其站在慶典會場，不如走進果園間的石牆小徑。","可與隔壁的智異山國立公園排在一起。"],"bestTime":"3月中旬至下旬","visitDuration":"半天","ticket":"","openingHours":"全日開放","galleryCaptions":["圍著山洞石牆的黃色山茱萸"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('suncheon-national-garden', 'suncheon-national-garden', 'jeonnam', 'Vườn quốc gia Suncheon', 'Suncheon Bay National Garden', 'park', 127.501, 34.943, 'Vườn quốc gia đầu tiên của Hàn Quốc, dựng lên như một vành đai chặn thành phố lấn vào vùng đất ngập mặn.', 'Suncheon có một vấn đề: vùng đất ngập mặn của nó là nơi sếu đen về trú đông, còn thành phố thì đang lan dần về phía ấy. Giải pháp của họ khá lạ — thay vì chỉ cấm xây, họ dựng một khu vườn khổng lồ chắn ngang làm vành đai đệm, và dời cả một khu dân cư ra ngoài. Khu vườn rộng gần một trăm mười hecta mở năm 2013, có các vườn chủ đề theo từng quốc gia, một ngọn đồi nhân tạo hình mô phỏng địa hình Suncheon, và một tuyến xe điện nhỏ nối thẳng ra vùng đất ngập mặn. Năm 2015 nó thành vườn quốc gia đầu tiên của Hàn Quốc. Đây là ví dụ hiếm hoi về một thành phố tự lùi lại để nhường chỗ cho chim.', '["Được công nhận là Vườn Quốc gia đầu tiên của Hàn Quốc năm 2015.","Rộng khoảng 110 hecta, mở cửa từ năm 2013.","Được xây làm vành đai đệm ngăn đô thị lan vào vùng đất ngập mặn Suncheonman.","Có xe điện nhỏ nối khu vườn với vùng đất ngập mặn."]', '["Mua vé gộp vườn + đất ngập mặn, rẻ hơn mua riêng.","Vườn rất rộng — dùng xe điện hoặc thuê xe đạp.","Tháng 10–11 vừa có hoa cúc trong vườn vừa có lau chín ngoài vịnh."]', 'Tháng 4–6 và 10–11', 'Nửa ngày', '8.000 KRW; vé gộp Suncheon 12.000 KRW (vườn + đất ngập mặn + Naganeupseong, dùng 2 ngày)', '09:00–19:00 (mùa đông tới 18:00)', '["verified"]', '["vườn","sinh thái","gia đình","đất ngập mặn"]', '[{"seed":"suncheon-national-garden","caption":"Đồi cỏ nhân tạo giữa vườn quốc gia","ratio":"16/9"}]', '["suncheonman-bay","naganeupseong"]', 0, 'https://www.suncheonbaygarden.com/', '2026-08-04', '{"en":{"name":"Suncheon Bay National Garden","summary":"Korea''s first national garden, built as a belt to stop the city creeping into the wetland.","story":"Suncheon had a problem: its wetland is where hooded cranes winter, and the city was spreading towards it. Their answer was unusual — rather than simply ban building, they laid an enormous garden across the gap as a buffer, and moved a residential district out of the way. The garden covers nearly a hundred and ten hectares, opened in 2013, and holds gardens themed by country, an artificial hill shaped after Suncheon''s own topography, and a small train running out to the wetland. In 2015 it became Korea''s first national garden. It is a rare case of a city stepping back to leave room for birds.","facts":["Designated Korea''s first National Garden in 2015.","About 110 hectares, opened in 2013.","Built as a buffer belt to stop urban sprawl reaching Suncheonman wetland.","A small train links the garden with the wetland."],"travelTips":["Buy the combined garden and wetland ticket; it is cheaper than separate entries.","The garden is large — use the train or hire a bike.","October–November gives you chrysanthemums in the garden and ripe reeds in the bay."],"bestTime":"April–June and October–November","visitDuration":"Half a day","ticket":"8,000 KRW; the Suncheon integrated ticket is 12,000 KRW (garden + wetland + Naganeupseong, valid 2 days)","openingHours":"09:00–19:00 (until 18:00 in winter)","galleryCaptions":["The artificial grass hill in the national garden"]},"ko":{"name":"순천만국가정원","summary":"한국 최초의 국가정원. 도시가 습지로 번지는 것을 막는 완충 띠로 만들어졌다.","story":"순천에는 문제가 있었다. 습지는 흑두루미가 겨울을 나는 곳인데 도시가 그쪽으로 번지고 있었다. 해법은 좀 남달랐다. 개발을 금지하는 데 그치지 않고 그 사이에 거대한 정원을 놓아 완충 띠로 삼았고, 주거지 하나를 아예 옮겼다. 2013년에 문을 연 이 정원은 110헥타르에 가깝고, 나라별 주제 정원과 순천의 지형을 본뜬 인공 언덕, 그리고 습지까지 이어지는 작은 열차가 있다. 2015년 한국 최초의 국가정원이 되었다. 도시가 새에게 자리를 내주려고 스스로 물러선 드문 사례다.","facts":["2015년 한국 최초의 국가정원으로 지정되었다.","면적은 약 110헥타르, 2013년 개원했다.","도시가 순천만 습지로 번지는 것을 막는 완충 띠로 조성되었다.","정원과 습지를 잇는 작은 열차가 다닌다."],"travelTips":["정원과 습지 통합권이 따로 사는 것보다 싸다.","정원이 넓다. 열차를 타거나 자전거를 빌리자.","10~11월이면 정원의 국화와 만의 갈대를 함께 볼 수 있다."],"bestTime":"4~6월, 10~11월","visitDuration":"반나절","ticket":"8,000원, 순천 통합권 12,000원(정원·습지·낙안읍성, 2일간 유효)","openingHours":"09:00~19:00(겨울에는 18:00까지)","galleryCaptions":["국가정원 가운데의 인공 잔디 언덕"]},"ja":{"name":"順天湾国家庭園","summary":"韓国初の国家庭園。都市が湿地へ広がるのを止める緩衝帯として造られた。","story":"順天には問題があった。湿地はナベヅルが冬を越す場所なのに、都市がそちらへ広がっていた。その解き方は少し変わっている。開発を禁じるだけでなく、あいだに巨大な庭園を置いて緩衝帯とし、住宅地をひとつ丸ごと移したのだ。2013年に開いたこの庭園は百十ヘクタール近くあり、国別の主題庭園、順天の地形を模した人工の丘、そして湿地まで走る小さな列車がある。2015年、韓国初の国家庭園となった。都市が鳥のために自ら退いた稀な例である。","facts":["2015年、韓国初の国家庭園に指定された。","面積は約110ヘクタール、2013年開園。","都市が順天湾の湿地へ広がるのを防ぐ緩衝帯として造られた。","庭園と湿地を結ぶ小さな列車が走る。"],"travelTips":["庭園と湿地の共通券が、別々に買うより安い。","庭園が広い。列車に乗るか自転車を借りよう。","10〜11月なら庭園の菊と湾の葦を同時に見られる。"],"bestTime":"4〜6月、10〜11月","visitDuration":"半日","ticket":"8,000ウォン、順天統合券は12,000ウォン（庭園・湿地・楽安邑城、2日間有効）","openingHours":"09:00〜19:00（冬は18:00まで）","galleryCaptions":["国家庭園の人工の芝の丘"]},"zh":{"name":"順天灣國家庭園","summary":"韓國第一座國家庭園，蓋成一條阻止城市蔓延進濕地的緩衝帶。","story":"順天面臨一個難題：它的濕地是白頭鶴越冬之地，而城市正朝那裡擴張。他們的解法相當特別——不只是禁建，而是在中間鋪開一座巨大的庭園當緩衝帶，甚至把一整片住宅區遷走。這座2013年開放的庭園佔地近一百一十公頃，設有各國主題花園、一座依順天地形塑成的人造丘陵，以及一列直通濕地的小火車。2015年，它成為韓國第一座國家庭園。這是少見的、一座城市主動後退為鳥讓路的例子。","facts":["2015年獲指定為韓國第一座國家庭園。","面積約110公頃，2013年開放。","作為緩衝帶興建，阻止城市擴張進入順天灣濕地。","有小火車連接庭園與濕地。"],"travelTips":["買庭園加濕地的套票，比分開購買便宜。","園區很大——搭小火車或租單車。","10至11月可同時看到園內菊花與灣區成熟的蘆葦。"],"bestTime":"4至6月與10至11月","visitDuration":"半天","ticket":"8,000韓元；順天聯票12,000韓元（庭園＋濕地＋樂安邑城，2日內有效）","openingHours":"09:00–19:00（冬季至18:00）","galleryCaptions":["國家庭園中的人造草丘"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('may18-memorial-park', 'may18-memorial-park', 'gwangju', 'Quảng trường 5·18 & Nghĩa trang Quốc gia', 'May 18th Democracy Square & National Cemetery', 'museum', 126.9195, 35.1495, 'Nơi phong trào dân chủ Gwangju 1980 diễn ra, và nơi những người ngã xuống được an nghỉ.', 'Tháng 5 năm 1980, sinh viên và người dân Gwangju xuống đường phản đối chính quyền quân sự; cuộc đàn áp kéo dài mười ngày và để lại hàng trăm người chết. Quảng trường trước toà nhà chính quyền tỉnh cũ — nay là trung tâm văn hoá châu Á — là tâm điểm của những ngày đó, còn đài phun nước giữa quảng trường là nơi người biểu tình tập trung. Cách đó vài cây số, Nghĩa trang Quốc gia 5·18 lặng lẽ với những tấm ảnh chân dung trên từng bia mộ. Hồ sơ về phong trào này được UNESCO ghi vào Ký ức Thế giới năm 2011.', '["Phong trào dân chủ Gwangju diễn ra từ 18 đến 27 tháng 5 năm 1980.","Tư liệu về phong trào được UNESCO ghi vào Ký ức Thế giới năm 2011.","Toà nhà chính quyền tỉnh cũ nay thuộc Trung tâm Văn hoá châu Á (ACC).","Nghĩa trang Quốc gia 5·18 nằm ở khu Unjeong, cách trung tâm khoảng 10 km."]', '["Ghé Trung tâm Văn hoá châu Á ngay cạnh, một trong những bảo tàng lớn nhất Hàn Quốc.","Tháng 5 có lễ tưởng niệm, không khí rất khác ngày thường.","Có hướng dẫn viên tình nguyện nói tiếng Anh tại nhà tưởng niệm."]', 'Quanh năm; tháng 5 có lễ tưởng niệm', '2–3 giờ', '', '09:00–18:00', '["verified"]', '["lịch sử","dân chủ","tưởng niệm"]', '[{"seed":"may18-memorial-park","caption":"Quảng trường 5·18","ratio":"16/9"}]', '["mudeungsan"]', 1, 'https://ko.wikipedia.org/wiki/국립아시아문화전당', '2026-08-04', '{"en":{"name":"May 18th Democracy Square & National Cemetery","summary":"Where the 1980 Gwangju Uprising happened, and where those who died in it are buried.","story":"In May 1980 students and citizens of Gwangju took to the streets against military rule; the crackdown lasted ten days and left hundreds dead. The square in front of the old provincial government building — now the Asia Culture Center — was the centre of those days, and the fountain in the middle was where protesters gathered. A few kilometres away, the May 18th National Cemetery is quiet, each headstone carrying a photograph. The archive of the uprising was inscribed in UNESCO''s Memory of the World in 2011.","facts":["The Gwangju Democratization Movement ran from 18 to 27 May 1980.","Its archive joined UNESCO''s Memory of the World register in 2011.","The former provincial hall is now part of the Asia Culture Center.","The May 18th National Cemetery is in Unjeong, about 10 km from the centre."],"travelTips":["Visit the Asia Culture Center next door, one of Korea''s largest cultural complexes.","In May the memorial ceremonies give the place a very different atmosphere.","English-speaking volunteer guides are available at the memorial hall."],"bestTime":"Year-round; memorial events in May","visitDuration":"2–3 hours","ticket":"","openingHours":"09:00–18:00","galleryCaptions":["May 18th Democracy Square"]},"ko":{"name":"5·18민주광장과 국립5·18민주묘지","summary":"1980년 광주민주화운동이 일어난 자리, 그리고 그때 스러진 이들이 잠든 곳.","story":"1980년 5월 광주의 학생과 시민들이 군사정권에 맞서 거리로 나섰고, 열흘간의 진압으로 수백 명이 목숨을 잃었다. 옛 전남도청 앞 광장은 그날들의 중심이었고, 광장의 분수대는 시민들이 모이던 자리였다. 몇 킬로미터 떨어진 국립5·18민주묘지는 조용하고, 묘비마다 사진이 붙어 있다. 이 항쟁의 기록물은 2011년 유네스코 세계기록유산에 등재되었다.","facts":["광주민주화운동은 1980년 5월 18일부터 27일까지 이어졌다.","관련 기록물은 2011년 유네스코 세계기록유산에 등재되었다.","옛 전남도청은 현재 국립아시아문화전당의 일부다.","국립5·18민주묘지는 도심에서 약 10km 떨어진 운정동에 있다."],"travelTips":["바로 옆 국립아시아문화전당은 한국 최대급 복합문화시설이다.","5월 추모 기간에는 분위기가 평소와 사뭇 다르다.","기념관에는 영어 안내가 가능한 자원봉사 해설사가 있다."],"bestTime":"연중, 5월에 추모 행사","visitDuration":"2~3시간","ticket":"","openingHours":"09:00~18:00","galleryCaptions":["5·18민주광장"]},"ja":{"name":"5·18民主広場と国立5·18民主墓地","summary":"1980年の光州民主化運動が起きた場所、そして倒れた人々が眠る場所。","story":"1980年5月、光州の学生と市民が軍事政権に抗して街頭に出た。十日間の鎮圧で数百人が命を落とした。旧全南道庁前の広場はその日々の中心であり、広場の噴水台は市民が集まった場所だ。数キロ離れた国立5·18民主墓地は静かで、墓碑ごとに写真が掲げられている。この蜂起の記録は2011年、ユネスコ世界記憶遺産に登録された。","facts":["光州民主化運動は1980年5月18日から27日まで続いた。","関連記録物は2011年にユネスコ世界記憶遺産に登録された。","旧全南道庁は現在、国立アジア文化殿堂の一部。","国立5·18民主墓地は市街から約10kmの雲汀洞にある。"],"travelTips":["隣の国立アジア文化殿堂は韓国最大級の複合文化施設。","5月の追悼期間は普段とは雰囲気がまるで違う。","記念館には英語で案内できるボランティアガイドがいる。"],"bestTime":"通年、5月に追悼行事","visitDuration":"2〜3時間","ticket":"","openingHours":"09:00〜18:00","galleryCaptions":["5·18民主広場"]},"zh":{"name":"5·18民主廣場與國立5·18民主墓地","summary":"1980年光州民主化運動發生之地，以及倒下者長眠之處。","story":"1980年5月，光州的學生與市民走上街頭反抗軍事政權；鎮壓持續十天，數百人喪生。舊全南道廳前的廣場是那些日子的中心，廣場中央的噴水池是示威者集結的地方。幾公里外，國立5·18民主墓地一片安靜，每塊墓碑上都有一張照片。這場運動的紀錄於2011年列入世界記憶名錄。","facts":["光州民主化運動自1980年5月18日持續至27日。","相關紀錄於2011年列入聯合國教科文組織世界記憶名錄。","舊全南道廳現為國立亞洲文化殿堂的一部分。","國立5·18民主墓地位於雲汀洞，距市區約10公里。"],"travelTips":["隔壁的國立亞洲文化殿堂是韓國最大的複合文化設施之一。","五月的追悼期間，氛圍與平日截然不同。","紀念館有能以英語解說的志工導覽。"],"bestTime":"全年；五月有追悼活動","visitDuration":"2至3小時","ticket":"","openingHours":"09:00–18:00","galleryCaptions":["5·18民主廣場"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('mudeungsan', 'mudeungsan', 'gwangju', 'Vườn quốc gia Mudeungsan', 'Mudeungsan National Park', 'mountain', 127.0035, 35.1345, 'Ngọn núi ôm lấy Gwangju, với những cột đá lục lăng dựng thẳng như ống sáo đá.', 'Mudeungsan nghĩa là ''không gì sánh bằng'', và người Gwangju coi nó như một phần của thành phố — sáng nào cũng có người leo trước giờ làm. Đỉnh núi có Ipseokdae và Seoseokdae: những cột đá lục lăng cao hàng chục mét, hình thành từ dung nham nguội cách đây 85 triệu năm, dựng sát nhau như bó sáo. Đây là loại địa hình rất hiếm ở châu Á và là lý do núi được công nhận công viên địa chất toàn cầu. Chân núi có làng nghệ thuật, quán trà và bảo tàng.', '["Trở thành vườn quốc gia thứ 21 của Hàn Quốc năm 2013.","Được UNESCO công nhận Công viên Địa chất Toàn cầu năm 2018.","Các cột đá lục lăng hình thành cách đây khoảng 85 triệu năm.","Đỉnh Cheonwangbong cao 1.187m."]', '["Tuyến Jeungsimsa – Seoseokdae là cung phổ biến nhất, khoảng 4 giờ.","Xe bus thành phố chạy thẳng tới cửa rừng Jeungsimsa.","Mùa đông có băng tuyết trên đỉnh, cần giày đinh."]', 'Tháng 4–6 và 9–11', 'Nửa ngày', '', 'Áp dụng ''chế độ giờ vào núi'' của vườn quốc gia: được lên từ 04:00 (tháng 3–11) hoặc 05:00 (tháng 12–2), và mỗi cung đường có giờ chặn riêng trong khoảng 12:00–17:00. Kiểm tra thông báo đóng đường trước khi đi', '["verified"]', '["núi","địa chất","leo núi"]', '[{"seed":"mudeungsan","caption":"Cột đá lục lăng Seoseokdae","ratio":"16/9"}]', '["may18-memorial-park"]', 0, 'https://www.knps.or.kr/front/portal/safe/acsCtrDtl.do?menuNo=8000340&rstId=0005', '2026-08-05', '{"en":{"name":"Mudeungsan National Park","summary":"The mountain that holds Gwangju, crowned with hexagonal stone columns standing like pipes.","story":"Mudeungsan means ''without equal'', and the people of Gwangju treat it as part of the city — plenty climb it before work. At the top stand Ipseokdae and Seoseokdae: columns of hexagonal stone tens of metres high, formed as lava cooled 85 million years ago, packed together like a bundle of flutes. This kind of formation is rare in Asia and is why the mountain is a UNESCO Global Geopark. At its foot are an art village, tea houses and museums.","facts":["Became Korea''s 21st national park in 2013.","Designated a UNESCO Global Geopark in 2018.","The columnar joints formed about 85 million years ago.","The summit, Cheonwangbong, reaches 1,187m."],"travelTips":["The Jeungsimsa–Seoseokdae route is the most popular, about four hours.","City buses run directly to the Jeungsimsa trailhead.","Ice on the summit in winter calls for crampons."],"bestTime":"April–June and September–November","visitDuration":"Half a day","ticket":"","openingHours":"The national park entry-time system applies: ascent opens at 04:00 (March–November) or 05:00 (December–February), and each section has its own turn-back time somewhere between 12:00 and 17:00. Check the trail-closure notices before setting out","galleryCaptions":["The Seoseokdae stone columns"]},"ko":{"name":"무등산국립공원","summary":"광주를 품은 산. 정상에 육각 돌기둥이 피리 다발처럼 서 있다.","story":"무등산은 ''견줄 것이 없다''는 뜻이고, 광주 사람들은 이 산을 도시의 일부로 여긴다. 출근 전에 오르는 사람도 적지 않다. 정상에는 입석대와 서석대가 있다. 8,500만 년 전 용암이 식으며 만들어진 수십 미터 높이의 육각 기둥들이 피리 다발처럼 늘어서 있다. 아시아에서 보기 드문 지형이라 유네스코 세계지질공원으로 지정되었다. 산 아래에는 예술마을과 찻집, 박물관이 있다.","facts":["2013년 한국의 21번째 국립공원으로 지정되었다.","2018년 유네스코 세계지질공원에 인증되었다.","주상절리는 약 8,500만 년 전에 형성되었다.","최고봉 천왕봉은 해발 1,187m다."],"travelTips":["증심사~서석대 코스가 가장 대중적이며 약 네 시간 걸린다.","시내버스가 증심사 입구까지 바로 간다.","겨울 정상에는 빙판이 생기니 아이젠이 필요하다."],"bestTime":"4~6월, 9~11월","visitDuration":"반나절","ticket":"","openingHours":"국립공원 입산시간지정제가 적용된다. 입산은 3~11월 04:00, 12~2월 05:00부터 가능하며 구간마다 12:00~17:00 사이로 통제시간이 다르다. 출발 전 통제 정보를 확인하자","galleryCaptions":["서석대 주상절리"]},"ja":{"name":"無等山国立公園","summary":"光州を抱く山。頂に六角の石柱が笛の束のように並ぶ。","story":"無等山は「比べるものがない」という意味で、光州の人はこの山を街の一部と考えている。出勤前に登る人も少なくない。頂には立石台と瑞石台があり、8,500万年前に溶岩が冷えてできた数十メートルの六角柱が笛の束のように並ぶ。アジアでは珍しい地形で、ユネスコ世界ジオパークに認定された理由でもある。麓には芸術村や茶室、博物館がある。","facts":["2013年に韓国21番目の国立公園に指定された。","2018年にユネスコ世界ジオパークに認定された。","柱状節理は約8,500万年前に形成された。","最高峰の天王峰は標高1,187m。"],"travelTips":["証心寺〜瑞石台のコースが最も一般的で約四時間。","市内バスが証心寺の登山口まで直行する。","冬の山頂は凍結するのでアイゼンが要る。"],"bestTime":"4〜6月、9〜11月","visitDuration":"半日","ticket":"","openingHours":"国立公園の入山時間指定制が適用される。入山は3〜11月は04:00、12〜2月は05:00から可能で、区間ごとに12:00〜17:00の間で規制時刻が異なる。出発前に通行規制情報の確認を","galleryCaptions":["瑞石台の柱状節理"]},"zh":{"name":"無等山國立公園","summary":"環抱光州的山，山頂立著像笛束一樣的六角石柱。","story":"無等山意為「無可比擬」，光州人把它當作城市的一部分——不少人上班前先爬一趟。山頂有立石台與瑞石台：八千五百萬年前熔岩冷卻形成的六角石柱高達數十公尺，一根挨著一根，如同一束豎笛。這類地形在亞洲相當罕見，也是它獲認證為世界地質公園的原因。山腳下有藝術村、茶館與博物館。","facts":["2013年成為韓國第21座國立公園。","2018年獲認證為聯合國教科文組織世界地質公園。","柱狀節理約形成於8,500萬年前。","最高峰天王峰海拔1,187公尺。"],"travelTips":["證心寺至瑞石台是最熱門的路線，約四小時。","市區公車直達證心寺登山口。","冬天山頂結冰，需要冰爪。"],"bestTime":"4至6月、9至11月","visitDuration":"半天","ticket":"","openingHours":"適用國家公園「入山時間指定制」：3至11月自04:00、12至2月自05:00開放入山，各路段的折返管制時間落在12:00至17:00之間。出發前請先查看步道封閉公告","galleryCaptions":["瑞石台的柱狀節理"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('yangnim-dong', 'yangnim-dong', 'gwangju', 'Làng lịch sử Yangnim-dong', 'Yangnim-dong Historic Village', 'village', 126.9145, 35.1385, 'Khu phố truyền giáo đầu thế kỷ 20 với nhà gạch đỏ, nay thành xóm nghệ thuật.', 'Đầu thế kỷ 20, các nhà truyền giáo Mỹ tới Gwangju dựng trường học, bệnh viện và nhà ở trên ngọn đồi Yangnim. Kiến trúc gạch đỏ kiểu phương Tây trộn với hanok tạo nên một khu phố không giống nơi nào khác. Sau nhiều năm bị bỏ quên, Yangnim-dong hồi sinh thành làng nghệ thuật: nhà cũ thành phòng tranh, quán cà phê, bảo tàng nhỏ về nhạc sĩ Jeong Yul-seong. Đi bộ qua các con dốc hẹp ở đây giống như lật một cuốn album của thế kỷ trước.', '["Hình thành từ khu truyền giáo đầu thế kỷ 20.","Nhiều ngôi nhà gạch đỏ là di sản kiến trúc cấp thành phố.","Có bảo tàng về nhạc sĩ Jeong Yul-seong, người con của Gwangju.","Khu vực được cải tạo thành làng nghệ thuật từ những năm 2010."]', '["Đi bộ là cách duy nhất hợp lý — ngõ hẹp và dốc.","Nhiều quán cà phê cải tạo từ nhà cổ, mở tới tối.","Kết hợp với chợ Daein gần đó, có chợ đêm nghệ thuật vào cuối tuần."]', 'Quanh năm', '1,5–2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["kiến trúc","nghệ thuật","đi bộ"]', '[{"seed":"yangnim-dong","caption":"Nhà gạch đỏ ở Yangnim-dong","ratio":"16/9"}]', '["may18-memorial-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Yangnim-dong Historic Village","summary":"An early 20th-century missionary quarter of red brick, reborn as an artists'' neighbourhood.","story":"In the early 1900s American missionaries arrived in Gwangju and built schools, a hospital and houses on Yangnim hill. Western red brick mixed with hanok produced a quarter that looks like nowhere else in Korea. After years of neglect, Yangnim-dong came back as an arts village: old houses are now galleries, cafés and a small museum devoted to the composer Jeong Yul-seong. Walking its narrow slopes feels like turning the pages of an album from the last century.","facts":["Grew out of an early 20th-century missionary compound.","Several red-brick houses are listed municipal heritage.","There is a museum dedicated to the composer Jeong Yul-seong, a son of Gwangju.","The quarter was regenerated as an arts village during the 2010s."],"travelTips":["Walking is the only sensible way — the lanes are narrow and steep.","Many cafés occupy converted old houses and stay open into the evening.","Combine with Daein Market nearby, which holds a night art market at weekends."],"bestTime":"Year-round","visitDuration":"1.5–2 hours","ticket":"","openingHours":"All day","galleryCaptions":["Red-brick buildings in Yangnim-dong"]},"ko":{"name":"양림동 역사문화마을","summary":"20세기 초 선교사 구역의 붉은 벽돌 거리가 예술마을로 되살아났다.","story":"1900년대 초 미국 선교사들이 광주에 들어와 양림 언덕에 학교와 병원, 사택을 지었다. 서양식 붉은 벽돌과 한옥이 뒤섞여 한국 어디에도 없는 동네가 되었다. 오래 잊혔던 양림동은 예술마을로 되살아났다. 옛집은 갤러리와 카페가 되었고, 광주가 낳은 음악가 정율성을 기리는 작은 기념관도 있다. 좁은 비탈길을 걷다 보면 지난 세기의 앨범을 넘기는 기분이 든다.","facts":["20세기 초 선교사 구역에서 시작되었다.","여러 붉은 벽돌 건물이 시 지정 문화유산이다.","광주 출신 음악가 정율성을 기리는 기념관이 있다.","2010년대에 예술마을로 재생되었다."],"travelTips":["골목이 좁고 가팔라 걸어서 도는 것이 가장 좋다.","옛집을 고친 카페가 많고 저녁까지 문을 연다.","주말 야시장이 열리는 인근 대인시장과 묶어 보자."],"bestTime":"연중","visitDuration":"1시간 30분~2시간","ticket":"","openingHours":"상시","galleryCaptions":["양림동의 붉은 벽돌 건물"]},"ja":{"name":"楊林洞歴史文化村","summary":"20世紀初頭の宣教師街の赤煉瓦が、芸術村としてよみがえった。","story":"1900年代初頭、アメリカの宣教師が光州に入り、楊林の丘に学校や病院、住居を建てた。西洋式の赤煉瓦と韓屋が混じり合い、韓国のどこにもない町並みができた。長く忘れられていた楊林洞は芸術村として再生した。古い家はギャラリーやカフェになり、光州が生んだ音楽家・鄭律成の小さな記念館もある。細い坂を歩くと、前世紀のアルバムをめくるような気分になる。","facts":["20世紀初頭の宣教師居留地から始まった。","複数の赤煉瓦の建物が市の指定文化遺産。","光州出身の音楽家・鄭律成の記念館がある。","2010年代に芸術村として再生された。"],"travelTips":["路地が狭く急なので歩いて回るのが一番。","古民家を改装したカフェが多く、夜まで開いている。","週末に夜市が立つ大仁市場と合わせて。"],"bestTime":"通年","visitDuration":"1時間30分〜2時間","ticket":"","openingHours":"終日","galleryCaptions":["楊林洞の赤煉瓦の建物"]},"zh":{"name":"楊林洞歷史文化村","summary":"二十世紀初的傳教士街區紅磚建築，如今成了藝術村。","story":"二十世紀初，美國傳教士來到光州，在楊林山丘上蓋起學校、醫院與住宅。西式紅磚與韓屋交錯，形成韓國別處沒有的街區。荒廢多年後，楊林洞以藝術村之姿重生：老屋變成畫廊、咖啡館，還有一座紀念光州音樂家鄭律成的小型館舍。走在狹窄的坡道上，像在翻閱上個世紀的相冊。","facts":["源自二十世紀初的傳教士居留地。","多棟紅磚建築被列為市級文化遺產。","設有紀念光州出身音樂家鄭律成的館舍。","2010年代整建為藝術村。"],"travelTips":["巷弄狹窄陡峭，步行最合適。","許多咖啡館由老屋改造，營業到晚上。","可與週末有夜間藝術市集的大仁市場一起逛。"],"bestTime":"全年","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日","galleryCaptions":["楊林洞的紅磚建築"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('asia-culture-center', 'asia-culture-center', 'gwangju', 'Trung tâm Văn hoá châu Á (ACC)', 'Asia Culture Center', 'museum', 126.9195, 35.1465, 'Bảo tàng gần như hoàn toàn nằm dưới lòng đất, xây quanh chính toà nhà nơi cuộc đàn áp 1980 kết thúc.', 'Khi Gwangju quyết định xây một trung tâm văn hoá tầm châu Á ngay trên nền toà nhà chính quyền tỉnh cũ — nơi những người biểu tình cuối cùng bị bắn năm 1980 — họ gặp một bài toán: làm sao xây thứ gì đó lớn mà không che khuất di tích. Câu trả lời là đẩy gần như toàn bộ công trình xuống dưới đất. Trên mặt đất chỉ còn một công viên phẳng, vài giếng trời và toà nhà cũ được giữ nguyên; bên dưới là năm khu triển lãm, nhà hát, thư viện và xưởng sáng tác trải rộng mười sáu hecta. Ánh sáng vào qua các giếng trời, và bạn đi xuống dần cho tới khi quên mất mình đang ở dưới lòng một quảng trường.', '["Mở cửa năm 2015, phần lớn diện tích nằm dưới mặt đất.","Được xây trên nền toà nhà chính quyền tỉnh Jeonnam cũ, hiện trường của biến cố 1980.","Tổng diện tích khoảng 16 hecta với năm khu chức năng.","Là một trong những tổ hợp văn hoá lớn nhất châu Á tính theo diện tích sàn."]', '["Vào khu trưng bày thường trực miễn phí, triển lãm đặc biệt tính vé riêng.","Toà nhà rất lớn — lấy bản đồ ở quầy và chọn hai khu thay vì đi hết.","Ga Culture Complex (tuyến 1) nối thẳng vào tầng hầm."]', 'Quanh năm', '2–3 giờ', 'Trưng bày thường trực miễn phí', '10:00–18:00, thứ Tư và thứ Bảy tới 20:00, đóng cửa thứ Hai; giờ mở có thể đổi theo lịch biểu diễn và triển lãm', '["verified"]', '["bảo tàng","kiến trúc","lịch sử","nghệ thuật"]', '[{"seed":"asia-culture-center","caption":"Giếng trời của khu triển lãm ngầm","ratio":"16/9"}]', '["may18-memorial-park","yangnim-dong"]', 1, 'https://www.acc.go.kr/main/menu.do?PID=06', '2026-08-04', '{"en":{"name":"Asia Culture Center","summary":"A museum almost entirely underground, built around the very building where the 1980 crackdown ended.","story":"When Gwangju decided to build an Asia-scale culture centre on the site of the old provincial government building — where the last demonstrators were shot in 1980 — it faced a problem: how to build something large without obscuring the site. The answer was to push almost the whole thing below ground. At street level there is only a flat park, some skylights and the old building left standing; beneath it are five wings of galleries, theatres, a library and studios spread over sixteen hectares. Light comes down through the skylights, and you descend gradually until you forget you are under a plaza.","facts":["Opened in 2015, with most of its floor area below ground.","Built on the site of the former South Jeolla provincial government building, scene of the 1980 events.","It covers about 16 hectares across five wings.","One of Asia''s largest cultural complexes by floor area."],"travelTips":["The permanent galleries are free; special exhibitions are ticketed.","The building is vast — take a map at the desk and pick two wings.","Culture Complex station (line 1) connects directly to the basement."],"bestTime":"Year-round","visitDuration":"2–3 hours","ticket":"Permanent galleries free","openingHours":"10:00–18:00, to 20:00 on Wednesdays and Saturdays, closed Mondays; hours can shift with the performance and exhibition schedule","galleryCaptions":["A skylight over the underground galleries"]},"ko":{"name":"국립아시아문화전당","summary":"거의 전부가 지하에 있는 문화시설. 1980년의 마지막 현장이 된 건물을 둘러싸고 지었다.","story":"광주가 옛 전남도청 자리에 아시아 규모의 문화시설을 짓기로 했을 때 문제가 있었다. 1980년 마지막 시민군이 총에 맞은 그 자리를 가리지 않으면서 큰 건물을 어떻게 세울 것인가. 답은 거의 전부를 땅 밑으로 내리는 것이었다. 지상에는 평평한 공원과 몇 개의 천창, 그리고 남겨 둔 옛 건물만 있다. 그 아래에 전시실과 극장, 도서관, 창작 공간이 다섯 개 원으로 16헥타르에 걸쳐 펼쳐진다. 빛은 천창으로 내려오고, 내려가다 보면 광장 아래에 있다는 사실을 잊게 된다.","facts":["2015년 개관했으며 연면적의 대부분이 지하에 있다.","1980년의 현장인 옛 전라남도청 자리에 세워졌다.","다섯 개 원에 걸쳐 약 16헥타르 규모다.","연면적 기준으로 아시아 최대 규모의 복합문화시설 가운데 하나다."],"travelTips":["상설 전시는 무료이고 기획전은 별도 유료다.","건물이 매우 크다. 안내 데스크에서 지도를 받아 두 개 원만 정하자.","1호선 문화전당역이 지하로 바로 연결된다."],"bestTime":"연중","visitDuration":"2~3시간","ticket":"상설 전시 무료","openingHours":"10:00~18:00, 수요일과 토요일은 20:00까지, 월요일 휴관. 공연·전시 일정에 따라 개관시간이 달라질 수 있다","galleryCaptions":["지하 전시실 위의 천창"]},"ja":{"name":"国立アジア文化殿堂","summary":"ほとんどが地下にある文化施設。1980年の最後の現場となった建物を囲んで建てられた。","story":"光州が旧全羅南道庁の跡地にアジア規模の文化施設を建てると決めたとき、問題があった。1980年に最後の市民軍が撃たれたその場所を覆わずに、どうやって大きな建物を建てるのか。答えは、ほぼすべてを地下へ下ろすことだった。地上にあるのは平らな公園といくつかの天窓、そして残された旧庁舎だけである。その下に、展示室と劇場、図書館、創作空間が五つの院として十六ヘクタールに広がる。光は天窓から降り、下りていくうちに広場の下にいることを忘れる。","facts":["2015年開館で、延床面積の大半が地下にある。","1980年の現場である旧全羅南道庁の跡地に建てられた。","五つの院にわたり約16ヘクタールの規模である。","延床面積ではアジア最大級の複合文化施設のひとつ。"],"travelTips":["常設展は無料、企画展は別料金である。","建物が非常に大きい。案内所で地図をもらい、二つの院に絞ろう。","1号線・文化殿堂駅が地下で直結している。"],"bestTime":"通年","visitDuration":"2〜3時間","ticket":"常設展は無料","openingHours":"10:00〜18:00、水曜と土曜は20:00まで、月曜休館。公演・展示の日程により開館時間が変わることがある","galleryCaptions":["地下展示室の上の天窓"]},"zh":{"name":"國立亞洲文化殿堂","summary":"幾乎整座都埋在地下的文化園區，圍著1980年鎮壓終結之地的那棟建築而建。","story":"當光州決定在舊全羅南道廳原址興建一座亞洲級的文化園區時，遇到一個難題：1980年最後一批示威者中槍的地方就在那裡，要怎麼蓋大體量卻不遮住它？答案是把幾乎整座建築沉到地下。地面上只剩一片平坦的公園、幾道天窗，以及被保留下來的舊廳舍；地下則是展廳、劇場、圖書館與創作空間，分成五院、佔地十六公頃。光線從天窗落下，你一路往下走，走著走著就忘了自己正在一座廣場底下。","facts":["2015年開館，樓地板面積大半位於地下。","建於1980年事件現場的舊全羅南道廳原址。","分為五院，佔地約16公頃。","以樓地板面積計，是亞洲規模最大的文化綜合體之一。"],"travelTips":["常設展免費，特展另行售票。","館區極大——在服務台拿張地圖，挑兩個院看就好。","地鐵1號線文化殿堂站可直通地下樓層。"],"bestTime":"全年","visitDuration":"2至3小時","ticket":"常設展免費","openingHours":"10:00–18:00，週三與週六至20:00，週一休館；開館時間可能隨演出與展覽行程調整","galleryCaptions":["地下展廳上方的天窗"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangju-daein-market', 'gwangju-daein-market', 'gwangju', 'Chợ Daein & chợ đêm nghệ sĩ', 'Daein Market & Night Market', 'market', 126.9165, 35.1525, 'Khu chợ gần chết được các nghệ sĩ dọn vào ở, giờ mỗi tối thứ Bảy biến thành chợ đêm sáng đèn.', 'Đầu những năm 2000, chợ Daein gần như trống rỗng — các quầy đóng cửa, mái tôn dột. Rồi Gwangju Biennale mời nghệ sĩ vào thuê các quầy bỏ không làm xưởng với giá rẻ, và họ ở lại. Giờ giữa những hàng cá khô và hàng đồ khô là xưởng gốm, xưởng in, phòng vẽ, và các bức tường được vẽ kín. Tối thứ Bảy, chợ mở ''Byeolbam Market'' — chợ đêm sao trời — với đèn dây giăng khắp lối đi, quầy đồ ăn do chính nghệ sĩ và người bán cũ cùng dựng, và nhạc sống ở giữa chợ. Đây là ví dụ hiếm hoi của việc nghệ sĩ vào một khu chợ mà không đẩy người bán cũ ra ngoài.', '["Chợ Daein suy tàn vào đầu những năm 2000 rồi hồi sinh nhờ các nghệ sĩ dọn vào.","Dự án đưa nghệ sĩ vào chợ khởi đầu từ Gwangju Biennale năm 2008.","Chợ đêm ''Byeolbam'' họp vào tối thứ Bảy.","Các quầy bán truyền thống và xưởng nghệ thuật hoạt động song song."]', '["Đi tối thứ Bảy — các tối khác chợ khá vắng.","Nhiều xưởng nghệ sĩ mở cửa cho khách vào xem, cứ hỏi.","Cách Trung tâm Văn hoá châu Á khoảng 10 phút đi bộ."]', 'Quanh năm; tối thứ Bảy', '2 giờ', '', 'Chợ ngày 09:00–19:00. Chợ đêm nghệ thuật Daein năm 2026 chỉ họp 12 buổi, tối thứ Sáu hoặc thứ Bảy 16:00–21:00, kéo dài tới 31/10 — nên xem lịch trước khi đi', '["trending","hidden-gem"]', '["chợ đêm","nghệ sĩ","ẩm thực","hồi sinh đô thị"]', '[{"seed":"gwangju-daein-market","caption":"Đèn dây trong chợ đêm Daein","ratio":"16/9"}]', '["asia-culture-center"]', 0, 'https://v.daum.net/v/YQF83MMVhJ', '2026-08-05', '{"en":{"name":"Daein Market & Night Market","summary":"A market close to dying that artists moved into, and which now lights up every Saturday night.","story":"By the early 2000s Daein market was nearly empty — stalls shuttered, the tin roof leaking. Then the Gwangju Biennale invited artists to rent the abandoned stalls as studios for very little, and they stayed. Now, between the dried fish and the dry goods, there are potteries, print workshops, painting studios and painted walls. On Saturday nights the market runs ''Byeolbam Market'' — the starlight night market — with strings of lights down the aisles, food stalls run jointly by the artists and the old traders, and live music in the middle. It is a rare case of artists moving into a market without pushing the original sellers out.","facts":["Daein market declined in the early 2000s and was revived by artists moving in.","The artists-in-the-market project began with the Gwangju Biennale in 2008.","The ''Byeolbam'' night market runs on Saturday evenings.","Traditional stalls and art studios operate side by side."],"travelTips":["Come on a Saturday evening — other nights the market is fairly quiet.","Many artists'' studios are open to visitors; just ask.","It is about 10 minutes'' walk from the Asia Culture Center."],"bestTime":"Year-round; Saturday evenings","visitDuration":"2 hours","ticket":"","openingHours":"Day market 09:00–19:00. The 2026 Daein Art Night Market runs just 12 sessions, on Friday or Saturday evenings 16:00–21:00, ending 31 October — check the schedule before going","galleryCaptions":["String lights in the Daein night market"]},"ko":{"name":"대인시장과 별밤야시장","summary":"거의 죽어 가던 시장에 예술가들이 들어왔고, 이제 토요일 밤이면 불이 켜진다.","story":"2000년대 초 대인시장은 거의 비어 있었다. 점포는 닫히고 함석지붕은 샜다. 그때 광주비엔날레가 예술가들에게 빈 점포를 아주 싼값에 작업실로 내주었고, 그들은 남았다. 지금은 건어물과 마른 잡화 사이에 도자 공방과 판화 공방, 그림 작업실이 있고 벽마다 그림이 그려져 있다. 토요일 밤이면 시장은 별밤야시장을 연다. 통로마다 전구가 걸리고, 예술가와 기존 상인이 함께 차린 먹거리 좌판이 서고, 한가운데에서 라이브 공연이 있다. 예술가가 시장에 들어오면서 원래 상인을 밀어내지 않은 드문 사례다.","facts":["대인시장은 2000년대 초 쇠락했다가 예술가들이 들어오며 되살아났다.","예술가 입주 프로젝트는 2008년 광주비엔날레에서 시작되었다.","''별밤야시장''은 토요일 저녁에 열린다.","전통 점포와 예술 작업실이 나란히 운영된다."],"travelTips":["토요일 저녁에 가자. 다른 날은 꽤 한산하다.","작업실을 열어 두는 예술가가 많다. 물어보면 된다.","국립아시아문화전당에서 걸어서 10분쯤이다."],"bestTime":"연중, 토요일 저녁","visitDuration":"2시간","ticket":"","openingHours":"낮 시장은 09:00~19:00. 2026년 대인예술야시장은 금 또는 토요일 16:00~21:00에 총 12회만 열리며 10월 31일까지다. 방문 전 일정 확인이 필요하다","galleryCaptions":["대인 야시장의 전구 불빛"]},"ja":{"name":"大仁市場と星夜の夜市","summary":"死にかけていた市場に芸術家が入り、いまは土曜の夜ごとに灯がともる。","story":"2000年代初め、大仁市場はほとんど空だった。店は閉じ、トタン屋根は雨漏りしていた。そこへ光州ビエンナーレが芸術家たちに空き店舗をごく安い賃料でアトリエとして貸し、彼らは居ついた。いまでは干物や乾物のあいだに陶芸工房や版画工房、絵画のアトリエがあり、壁という壁に絵が描かれている。土曜の夜には市場が「星夜の夜市」を開く。通路ごとに電球が吊られ、芸術家と昔からの商人が一緒に屋台を出し、真ん中で生演奏がある。芸術家が市場に入りながら元の売り手を追い出さなかった、稀な例である。","facts":["大仁市場は2000年代初めに衰退し、芸術家の入居で息を吹き返した。","芸術家の入居事業は2008年の光州ビエンナーレから始まった。","「星夜の夜市」は土曜の夕方に開かれる。","伝統的な店舗と芸術のアトリエが並んで営まれている。"],"travelTips":["土曜の夜に行こう。他の日はかなり静かだ。","アトリエを開けている芸術家が多い。声をかけてみよう。","国立アジア文化殿堂から徒歩10分ほど。"],"bestTime":"通年、土曜の夜","visitDuration":"2時間","ticket":"","openingHours":"昼の市場は09:00〜19:00。2026年の大仁芸術夜市は金または土の16:00〜21:00に全12回のみで10月31日まで。訪問前に日程確認を","galleryCaptions":["大仁夜市の電球の灯り"]},"zh":{"name":"大仁市場與星夜夜市","summary":"一座幾乎凋零的市場，藝術家搬了進來，如今每逢週六夜裡就亮起燈。","story":"2000年代初，大仁市場幾乎空了——攤位拉下鐵門，鐵皮屋頂漏水。後來光州雙年展邀藝術家以極低的租金承租空攤當工作室，他們就留了下來。如今在乾魚與雜貨之間，是陶藝工坊、版畫工作室、畫室，牆面也畫滿了。每逢週六夜裡，市場舉辦「星夜夜市」：走道上串起燈泡，藝術家與老攤商合力擺出小吃攤，中央有現場演出。這是少見的、藝術家進駐市場卻沒有把原本攤商擠走的例子。","facts":["大仁市場於2000年代初沒落，因藝術家進駐而復甦。","藝術家進駐計畫始於2008年的光州雙年展。","「星夜」夜市於週六傍晚營業。","傳統攤商與藝術工作室並行運作。"],"travelTips":["挑週六傍晚來，其他夜晚市場相當安靜。","許多藝術家的工作室開放參觀，開口問就行。","距國立亞洲文化殿堂步行約10分鐘。"],"bestTime":"全年；週六傍晚","visitDuration":"2小時","ticket":"","openingHours":"日市09:00–19:00。2026年大仁藝術夜市僅有12場，於週五或週六16:00–21:00舉行，至10月31日止——出發前請先查看檔期","galleryCaptions":["大仁夜市裡的串燈"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangju-biennale', 'gwangju-biennale', 'gwangju', 'Biennale Gwangju', 'Gwangju Biennale', 'museum', 126.8895, 35.1795, 'Triển lãm nghệ thuật đương đại lâu đời nhất châu Á, lập năm 1995 để tưởng nhớ những người ngã xuống năm 1980.', 'Gwangju lập Biennale năm 1995, mười lăm năm sau cuộc đàn áp, với một lý do được nói thẳng: biến thành phố từ nơi bị nhớ đến vì bạo lực thành nơi được nhớ đến vì nghệ thuật. Đây là biennale nghệ thuật đương đại đầu tiên của châu Á và vẫn là biennale lớn nhất khu vực, tổ chức hai năm một lần vào mùa thu với hàng chục quốc gia tham gia. Các tác phẩm thường chính trị hơn hẳn những biennale khác — chủ đề dân chủ, ký ức, di dân xuất hiện liên tục, và điều đó không phải ngẫu nhiên. Ngoài năm tổ chức, khu nhà triển lãm vẫn mở với các chương trình nhỏ và một thư viện nghệ thuật.', '["Được lập năm 1995, là biennale nghệ thuật đương đại đầu tiên của châu Á.","Tổ chức hai năm một lần, thường vào mùa thu.","Ra đời như một cách tưởng niệm phong trào dân chủ Gwangju 1980.","Ngoài kỳ triển lãm chính, khu nhà vẫn mở với các chương trình nhỏ."]', '["Kiểm tra năm tổ chức trước khi lên kế hoạch — biennale chỉ diễn ra hai năm một lần.","Vé thông cho phép vào cả các địa điểm vệ tinh rải khắp thành phố.","Cần cả ngày nếu muốn xem hết khu chính."]', 'Tháng 9–11 của năm tổ chức', 'Nửa ngày đến cả ngày', '16.000 KRW; vé bán trước có thể giảm còn 8.000 KRW', '10:00–18:00, đóng cửa thứ Hai', '["trending"]', '["nghệ thuật đương đại","biennale","triển lãm"]', '[{"seed":"gwangju-biennale","caption":"Khu nhà triển lãm Biennale Gwangju","ratio":"16/9"}]', '["asia-culture-center","mudeungsan"]', 0, 'https://artexpoworld.com/gwangju_biennale_2026', '2026-08-04', '{"en":{"name":"Gwangju Biennale","summary":"Asia''s oldest contemporary art biennale, founded in 1995 in memory of those killed in 1980.","story":"Gwangju founded its Biennale in 1995, fifteen years after the crackdown, for a reason it stated openly: to turn the city from a place remembered for violence into one remembered for art. It was Asia''s first contemporary art biennale and is still the region''s largest, held every two years in autumn with dozens of countries taking part. The work tends to be markedly more political than at other biennales — democracy, memory and migration recur, and that is no accident. In off years the exhibition halls stay open with smaller programmes and an art library.","facts":["Founded in 1995, Asia''s first contemporary art biennale.","Held every two years, usually in autumn.","It was created as a memorial to the 1980 Gwangju democratic uprising.","The halls remain open between editions with smaller programmes."],"travelTips":["Check whether it is a biennale year before planning around it.","The pass covers the satellite venues scattered across the city.","Allow a full day if you want to see the main site properly."],"bestTime":"September–November of a biennale year","visitDuration":"Half to a full day","ticket":"16,000 KRW; advance sales can bring it down to 8,000 KRW","openingHours":"10:00–18:00, closed Mondays","galleryCaptions":["The Gwangju Biennale exhibition halls"]},"ko":{"name":"광주비엔날레","summary":"아시아에서 가장 오래된 현대미술 비엔날레. 1980년의 희생을 기려 1995년에 시작했다.","story":"광주는 항쟁 십오 년 뒤인 1995년에 비엔날레를 열었고, 이유를 숨기지 않았다. 폭력으로 기억되는 도시를 예술로 기억되는 도시로 바꾸겠다는 것이었다. 아시아 최초의 현대미술 비엔날레였고 지금도 이 지역에서 가장 크다. 두 해에 한 번 가을에 열리며 수십 개 나라가 참여한다. 작품은 다른 비엔날레보다 눈에 띄게 정치적이다. 민주주의와 기억, 이주 같은 주제가 되풀이되는데 그것은 우연이 아니다. 비엔날레가 없는 해에도 전시관은 작은 프로그램과 미술 도서관으로 문을 연다.","facts":["1995년 창설된 아시아 최초의 현대미술 비엔날레다.","두 해에 한 번, 주로 가을에 열린다.","1980년 광주민주화운동을 기리는 뜻에서 시작되었다.","비엔날레가 없는 해에도 전시관은 작은 프로그램으로 운영된다."],"travelTips":["일정을 짜기 전에 비엔날레가 열리는 해인지 확인하자.","통합권으로 시내 곳곳의 위성 전시장도 들어갈 수 있다.","본전시를 제대로 보려면 하루를 잡자."],"bestTime":"비엔날레 해의 9~11월","visitDuration":"반나절~하루","ticket":"16,000원, 사전 판매 시 8,000원까지 할인","openingHours":"10:00~18:00, 월요일 휴관","galleryCaptions":["광주비엔날레 전시관"]},"ja":{"name":"光州ビエンナーレ","summary":"アジア最古の現代美術ビエンナーレ。1980年の犠牲を悼み1995年に始まった。","story":"光州は蜂起から十五年後の1995年にビエンナーレを開き、その理由を隠さなかった。暴力で記憶される街を、芸術で記憶される街に変えるということだ。アジア初の現代美術ビエンナーレであり、いまも地域最大である。二年に一度、秋に開かれ、数十の国が参加する。作品は他のビエンナーレより明らかに政治的だ。民主主義、記憶、移住といった主題が繰り返し現れるが、それは偶然ではない。開催のない年も、展示館は小さな企画と美術図書館で開いている。","facts":["1995年創設、アジア初の現代美術ビエンナーレである。","二年に一度、主に秋に開催される。","1980年の光州民主化運動を悼む意図で始まった。","開催年以外も展示館は小規模なプログラムで運営される。"],"travelTips":["予定を立てる前に、開催年かどうかを確認しよう。","共通券で市内に点在するサテライト会場にも入れる。","本展をきちんと見るなら一日を取ろう。"],"bestTime":"開催年の9〜11月","visitDuration":"半日〜一日","ticket":"16,000ウォン、事前販売なら8,000ウォンまで割引","openingHours":"10:00〜18:00、月曜休館","galleryCaptions":["光州ビエンナーレの展示館"]},"zh":{"name":"光州雙年展","summary":"亞洲最早的當代藝術雙年展，1995年為紀念1980年的犧牲者而創辦。","story":"光州在事件十五年後的1995年創辦雙年展，理由講得很直白：要把一座因暴力被記住的城市，變成一座因藝術被記住的城市。它是亞洲第一個當代藝術雙年展，至今仍是本區規模最大者，每兩年於秋天舉行，數十國參與。這裡的作品明顯比其他雙年展更政治——民主、記憶、遷徙等主題反覆出現，而這並非偶然。非展期時，展館仍以較小型的計畫與一座藝術圖書館對外開放。","facts":["1995年創辦，是亞洲第一個當代藝術雙年展。","每兩年舉辦一次，通常在秋季。","創辦初衷是紀念1980年的光州民主化運動。","非展期間展館仍以小型計畫開放。"],"travelTips":["安排行程前先確認當年是否為展期。","通票可進入散布市內的衛星展場。","想好好看完主展場，請預留一整天。"],"bestTime":"展期年的9至11月","visitDuration":"半天至一整天","ticket":"16,000韓元；預售最低可到8,000韓元","openingHours":"10:00–18:00，週一休館","galleryCaptions":["光州雙年展展館"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangju-penguin-village', 'gwangju-penguin-village', 'gwangju', 'Làng chim cánh cụt Yangnim', 'Penguin Village, Yangnim-dong', 'village', 126.9135, 35.1395, 'Ngõ nhỏ dán đầy đồng hồ hỏng, quạt cũ và radio cassette — bảo tàng đồ bỏ đi do cả xóm cùng dựng.', 'Tên làng đến từ một chuyện rất đời: sau một trận hoả hoạn, những người già trong xóm dọn dẹp và đi lại lom khom vì đau chân, trông giống chim cánh cụt, nên người ta gọi đùa như thế. Rồi họ bắt đầu treo lên tường những thứ nhặt được — đồng hồ treo tường đã chết, quạt bàn gỉ, radio cassette, biển hiệu cũ, chậu hoa vỡ. Càng ngày càng nhiều, và giờ cả mấy con ngõ phủ kín đồ vật của bốn mươi năm đời sống Hàn Quốc, sắp xếp không theo trật tự nào ngoài trực giác của người treo. Không ai thu vé, không ai quản lý. Đây có lẽ là bảo tàng thành thật nhất về thế kỷ 20 ở Hàn Quốc.', '["Tên làng bắt nguồn từ dáng đi của những cư dân cao tuổi trong xóm.","Các bức tường ngõ phủ kín đồ gia dụng cũ do chính cư dân sưu tầm và treo lên.","Không thu vé và không có ban quản lý chính thức.","Nằm trong khu Yangnim-dong, cạnh các nhà truyền giáo và nhà gạch đỏ cũ."]', '["Kết hợp với khu nhà truyền giáo Yangnim-dong ngay bên cạnh.","Đây là ngõ dân sinh — đi nhẹ nói khẽ, đừng chạm vào đồ trưng bày.","Buổi sáng ánh sáng lọt vào ngõ đẹp nhất cho ảnh."]', 'Quanh năm', '1 giờ', '', 'Cả ngày', '["hidden-gem"]', '["ngõ nhỏ","đồ cũ","nghệ thuật dân gian","đi bộ"]', '[{"seed":"gwangju-penguin-village","caption":"Tường ngõ phủ kín đồ gia dụng cũ","ratio":"16/9"}]', '["yangnim-dong","gwangju-daein-market"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Penguin Village, Yangnim-dong","summary":"Lanes covered in dead clocks, old fans and cassette radios — a museum of discarded things the neighbourhood built itself.","story":"The name comes from something quite ordinary: after a fire, the elderly residents cleaning up walked stooped because their legs hurt, looking like penguins, so people called it that as a joke. Then they began hanging what they found on the walls — dead wall clocks, rusted desk fans, cassette radios, old shop signs, broken flowerpots. More and more, until several lanes were covered in the objects of forty years of Korean life, arranged by no principle other than the instinct of whoever hung them. Nobody charges, nobody curates. It may be the most honest museum of the 20th century in Korea.","facts":["The village name comes from how the elderly residents walked.","The lane walls are covered in old household objects collected and hung by the residents themselves.","There is no admission charge and no official management.","It sits within Yangnim-dong, beside the missionary houses and old red-brick buildings."],"travelTips":["Combine it with the Yangnim-dong missionary quarter next door.","These are residential lanes — keep quiet and don''t touch the displays.","Morning light reaching into the lanes is best for photographs."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"","openingHours":"All day","galleryCaptions":["A lane wall covered in old household objects"]},"ko":{"name":"양림동 펭귄마을","summary":"멈춘 시계와 낡은 선풍기, 카세트라디오로 뒤덮인 골목. 동네가 손수 만든 폐품 박물관이다.","story":"마을 이름은 아주 소박한 데서 왔다. 불이 난 뒤 정리하던 동네 어르신들이 다리가 아파 뒤뚱뒤뚱 걷는 모습이 펭귄 같다고 해서 그렇게 부르기 시작한 것이다. 그러다 그들은 주워 온 것을 벽에 걸기 시작했다. 멈춘 벽시계, 녹슨 선풍기, 카세트라디오, 옛 간판, 깨진 화분. 점점 늘어나 이제 골목 몇 개가 사십 년 한국 살림의 물건으로 뒤덮였고, 배열의 원칙은 건 사람의 감각뿐이다. 아무도 돈을 받지 않고 아무도 기획하지 않는다. 어쩌면 한국에서 20세기를 가장 정직하게 보여 주는 박물관이다.","facts":["마을 이름은 나이 든 주민들의 걸음걸이에서 비롯되었다.","골목 벽은 주민들이 직접 모아 건 옛 살림살이로 덮여 있다.","입장료도 없고 공식 운영 주체도 없다.","선교사 주택과 옛 붉은 벽돌 건물이 있는 양림동 안에 있다."],"travelTips":["바로 옆 양림동 선교사 주택 구역과 묶어서 보자.","사람이 사는 골목이다. 조용히 걷고 전시물에 손대지 말자.","아침에 골목으로 드는 빛이 사진에 가장 좋다."],"bestTime":"연중","visitDuration":"1시간","ticket":"","openingHours":"상시","galleryCaptions":["옛 살림살이로 뒤덮인 골목 벽"]},"ja":{"name":"楊林洞ペンギン村","summary":"止まった時計や古い扇風機、カセットラジオで覆われた路地。町が自ら作った廃品の博物館だ。","story":"村の名はごく素朴なところから来ている。火事のあと片づけをしていた年配の住民たちが、脚が痛くてよちよち歩く姿がペンギンのようだと、冗談でそう呼び始めたのだ。やがて彼らは拾ってきたものを壁に掛け始めた。止まった掛け時計、錆びた扇風機、カセットラジオ、古い看板、割れた植木鉢。それが増えつづけ、いまでは路地いくつかが四十年分の韓国の暮らしの品で覆われている。並べ方の原則は、掛けた人の勘だけだ。誰も金を取らず、誰も企画しない。おそらく韓国で二十世紀を最も正直に見せる博物館である。","facts":["村の名は年配の住民たちの歩き方に由来する。","路地の壁は、住民自身が集めて掛けた古い生活用品で覆われている。","入場料もなく、公式の運営主体もない。","宣教師住宅や古い赤煉瓦の建物が残る楊林洞の中にある。"],"travelTips":["隣の楊林洞・宣教師住宅地区と合わせて回ろう。","人が住む路地である。静かに歩き、展示物に触れないこと。","朝、路地に差し込む光が写真には最も向く。"],"bestTime":"通年","visitDuration":"1時間","ticket":"","openingHours":"終日","galleryCaptions":["古い生活用品で覆われた路地の壁"]},"zh":{"name":"楊林洞企鵝村","summary":"巷弄裡貼滿停走的時鐘、老電扇與卡帶收音機——整條街自己做出來的廢物博物館。","story":"村名的由來很平常：一場火災之後，收拾殘局的老人家因為腿疼而彎著身子走路，看起來像企鵝，大家就這麼玩笑地叫開了。後來他們開始把撿到的東西掛上牆——停走的掛鐘、生鏽的電扇、卡帶收音機、舊招牌、破花盆。愈掛愈多，如今好幾條巷子被四十年韓國生活的物件覆滿，排列的原則除了掛的人的直覺以外沒有別的。沒有人收費，沒有人策展。這也許是韓國最誠實的一座二十世紀博物館。","facts":["村名源自年長居民走路的姿態。","巷弄牆面覆滿居民自行蒐集並掛上的舊生活用品。","不收門票，也沒有正式的管理單位。","位於楊林洞，緊鄰傳教士宅邸與舊紅磚建築。"],"travelTips":["可與隔壁的楊林洞傳教士宅邸區一併逛。","這是住宅巷弄，請放輕聲量，也別碰展示物。","早晨光線斜進巷子時最適合拍照。"],"bestTime":"全年","visitDuration":"1小時","ticket":"","openingHours":"全日開放","galleryCaptions":["掛滿舊生活用品的巷弄牆面"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hahoe-folk-village', 'hahoe-folk-village', 'gyeongbuk', 'Làng cổ Hahoe (Andong)', 'Hahoe Folk Village', 'unesco', 128.518, 36.539, 'Ngôi làng Nho giáo được dòng sông ôm trọn một vòng, nơi mặt nạ Hahoe ra đời.', 'Sông Nakdong uốn một vòng gần khép kín quanh Hahoe — cái tên nghĩa là ''sông chảy vòng''. Trong đó là ngôi làng của dòng họ Ryu, giữ nguyên bố cục từ thế kỷ 15: nhà ngói của quan lại xen nhà tranh của tá điền, tường đất, giếng chung. Người dân vẫn sống và canh tác ở đây. Làng nổi tiếng với điệu múa mặt nạ byeolsingut — một loại kịch trào phúng nông dân được phép giễu cả quý tộc, và những chiếc mặt nạ gỗ Hahoe nay là bảo vật quốc gia.', '["Được UNESCO công nhận Di sản Thế giới năm 2010 (cùng làng Yangdong).","Là làng của dòng họ Ryu xứ Pungsan, hình thành từ thế kỷ 14–15.","Mặt nạ gỗ Hahoe có niên đại từ thời Goryeo, là quốc bảo.","Buổi diễn múa mặt nạ tổ chức thường xuyên tại làng."]', '["Xem lịch diễn múa mặt nạ trước khi đi.","Leo lên vách Buyongdae bên kia sông để nhìn toàn cảnh làng.","Andong cũng nổi tiếng với gà hầm jjimdak và rượu soju Andong."]', 'Tháng 9–10 (lễ hội mặt nạ Andong)', '3 giờ', '5.000 KRW', 'Từ lúc mặt trời mọc đến khi mặt trời lặn, mở quanh năm', '["unesco","festival"]', '["UNESCO","làng cổ","mặt nạ","Nho giáo"]', '[{"seed":"hahoe-folk-village","caption":"Làng Hahoe bên khúc sông","ratio":"16/9"}]', '["dosan-seowon"]', 1, 'http://www.tourandong.com/eng/sub1/sub1.cshtml?id=196', '2026-08-04', '{"en":{"name":"Hahoe Folk Village, Andong","summary":"A Confucian village wrapped in a loop of river, where the Hahoe masks were born.","story":"The Nakdong River bends almost the whole way around Hahoe — the name means ''river turning''. Inside sits the village of the Ryu clan, its layout unchanged since the 15th century: tiled houses of the gentry among the thatched homes of tenants, mud walls, a shared well. People still live and farm here. The village is famous for the byeolsingut mask dance, a peasant satire in which even aristocrats could be mocked, and its wooden Hahoe masks are now national treasures.","facts":["Inscribed by UNESCO in 2010 together with Yangdong village.","Home of the Ryu clan of Pungsan since the 14th–15th centuries.","The Hahoe wooden masks date from the Goryeo period and are national treasures.","Mask dance performances are staged regularly in the village."],"travelTips":["Check the mask dance schedule before you go.","Climb the Buyongdae cliff across the river for the full view of the village.","Andong is also known for jjimdak braised chicken and Andong soju."],"bestTime":"September–October (Andong Mask Dance Festival)","visitDuration":"3 hours","ticket":"5,000 KRW","openingHours":"Sunrise to sunset, open year-round","galleryCaptions":["Hahoe village inside the river bend"]},"ko":{"name":"안동 하회마을","summary":"강이 한 바퀴 감아 도는 유교 마을. 하회탈이 태어난 곳이다.","story":"낙동강이 마을을 거의 한 바퀴 감아 돌아 ''하회''라는 이름이 붙었다. 그 안에 류씨 집안의 마을이 15세기 배치 그대로 남아 있다. 양반의 기와집과 소작인의 초가가 섞이고 흙담과 공동 우물이 있다. 지금도 사람들이 살며 농사를 짓는다. 마을은 별신굿탈놀이로 유명하다. 양반까지 놀릴 수 있었던 농민의 풍자극이고, 그때 쓰던 나무 하회탈은 지금 국보가 되었다.","facts":["2010년 양동마을과 함께 유네스코 세계유산에 등재되었다.","14~15세기부터 이어진 풍산 류씨의 집성촌이다.","하회탈은 고려시대에 만들어졌으며 국보다.","마을에서 탈춤 공연이 정기적으로 열린다."],"travelTips":["탈춤 공연 시간을 미리 확인하자.","강 건너 부용대에 오르면 마을 전경을 볼 수 있다.","안동은 찜닭과 안동소주로도 유명하다."],"bestTime":"9~10월(안동국제탈춤페스티벌)","visitDuration":"3시간","ticket":"5,000원","openingHours":"해 뜰 때부터 해 질 때까지, 연중무휴","galleryCaptions":["강이 감아 도는 하회마을"]},"ja":{"name":"安東 河回村","summary":"川がぐるりと回り込む儒教の村。河回タルはここで生まれた。","story":"洛東江が村をほぼ一周するので「河回」の名がついた。その内側に柳氏一族の村が15世紀の配置のまま残る。両班の瓦屋根と小作の草葺きが混じり、土塀と共同井戸がある。今も人が住み、農業を営む。村は別神グッタルノリで名高い。両班さえ揶揄できた農民の風刺劇であり、そのとき使われた木製の河回タルは今や国宝だ。","facts":["2010年に良洞村とともにユネスコ世界遺産に登録された。","14〜15世紀から続く豊山柳氏の同族村。","河回タルは高麗時代に作られ、国宝に指定されている。","村では仮面劇の公演が定期的に行われる。"],"travelTips":["仮面劇の公演時間を事前に確認しよう。","川向こうの芙蓉台に登れば村の全景が見える。","安東はチムタクと安東焼酎でも知られる。"],"bestTime":"9〜10月（安東国際仮面舞踊祭）","visitDuration":"3時間","ticket":"5,000ウォン","openingHours":"日の出から日没まで、年中無休","galleryCaptions":["川に囲まれた河回村"]},"zh":{"name":"安東河回村","summary":"被河流環抱一圈的儒家村落，河回面具在此誕生。","story":"洛東江幾乎繞著河回村轉了一整圈——村名即「河水回流」之意。村內是柳氏一族的聚落，格局自十五世紀以來未變：士族的瓦房與佃戶的茅屋交錯，土牆、公用水井俱在。人們至今仍在此居住耕作。村子以別神儺戲面具舞聞名，那是一種連兩班貴族都可以被戲謔的農民諷刺劇，當時使用的木製河回面具如今已是國寶。","facts":["2010年與良洞村一同列入世界遺產。","自十四至十五世紀延續至今的豐山柳氏聚落。","河回面具可追溯至高麗時期，屬國寶。","村內定期上演面具舞。"],"travelTips":["出發前先查面具舞的演出時間。","登上對岸的芙蓉台，可俯瞰整座村落。","安東也以燉雞與安東燒酒聞名。"],"bestTime":"9至10月（安東國際面具舞節）","visitDuration":"3小時","ticket":"5,000韓元","openingHours":"日出至日落，全年開放","galleryCaptions":["被河流環抱的河回村"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('dosan-seowon', 'dosan-seowon', 'gyeongbuk', 'Thư viện Dosan Seowon (Andong)', 'Dosan Seowon Confucian Academy', 'unesco', 128.845, 36.727, 'Học đường Nho giáo của Yi Hwang — gương mặt in trên tờ 1.000 won — nằm bên hồ nước lặng.', 'Yi Hwang (hiệu Toegye), triết gia lớn nhất của Nho học Triều Tiên, từ chối quan trường để về quê dạy học. Ngôi trường ông dựng bên sông Nakdong giản dị đến mức gần như khắc khổ: gỗ mộc, mái ngói thấp, sân đất, và một giảng đường nhìn ra mặt nước. Học trò ở nội trú trong các dãy nhà nhỏ hai bên. Kiến trúc ấy chính là triết lý của ông — hướng nội, tiết chế, thuận theo tự nhiên. Chân dung Yi Hwang và cả ngôi trường này đều in trên tờ tiền 1.000 won.', '["Do học trò của Yi Hwang xây năm 1574, sau khi ông mất.","Nằm trong 9 seowon được UNESCO công nhận năm 2019.","Yi Hwang (1501–1570) là gương mặt in trên tờ 1.000 won.","Cách làng Hahoe khoảng 40 phút xe."]', '["Đi cùng ngày với làng Hahoe nếu ở Andong.","Rất vắng vào ngày thường — thời điểm tốt để cảm nhận sự tĩnh lặng.","Mùa thu lá đỏ soi bóng hồ trước trường rất đẹp."]', 'Tháng 10–11', '1,5 giờ', '1.500 KRW', '09:00–18:00 (mùa đông đến 17:00)', '["unesco","hidden-gem"]', '["UNESCO","Nho giáo","kiến trúc"]', '[{"seed":"dosan-seowon","caption":"Giảng đường Dosan Seowon","ratio":"16/9"}]', '["hahoe-folk-village"]', 0, 'http://www.tourandong.com/eng/sub1/sub1.cshtml?id=196', '2026-08-04', '{"en":{"name":"Dosan Seowon Confucian Academy, Andong","summary":"The academy of Yi Hwang — the face on the 1,000 won note — beside a still lake.","story":"Yi Hwang (pen name Toegye), the greatest philosopher of Korean Confucianism, turned away from office and went home to teach. The school he built beside the Nakdong River is almost austere: plain wood, low tiled roofs, a bare earth yard and a lecture hall facing the water. Students boarded in the small buildings on either side. That architecture is his philosophy — inward, restrained, following nature. Both Yi Hwang''s portrait and this academy appear on the 1,000 won banknote.","facts":["Built by Yi Hwang''s students in 1574, after his death.","One of nine seowon inscribed by UNESCO in 2019.","Yi Hwang (1501–1570) is the face on the 1,000 won note.","About 40 minutes by car from Hahoe village."],"travelTips":["Do it on the same day as Hahoe village if you are staying in Andong.","Weekdays are very quiet — the best time to feel the stillness.","Autumn colour reflected in the lake in front is superb."],"bestTime":"October–November","visitDuration":"1.5 hours","ticket":"1,500 KRW","openingHours":"09:00–18:00 (to 17:00 in winter)","galleryCaptions":["The lecture hall at Dosan Seowon"]},"ko":{"name":"안동 도산서원","summary":"천 원권 지폐의 인물 이황이 세운 서원. 잔잔한 물가에 앉아 있다.","story":"한국 성리학의 큰 학자 퇴계 이황은 벼슬을 마다하고 고향으로 돌아와 후학을 가르쳤다. 낙동강 가에 세운 그의 서당은 거의 검박하다. 다듬지 않은 나무와 낮은 기와지붕, 흙마당, 그리고 물을 향해 열린 강당. 학생들은 양옆의 작은 건물에서 기숙했다. 그 건축이 곧 그의 철학이다. 안으로 향하고, 절제하며, 자연을 따른다. 이황의 초상과 이 서원은 모두 천 원권 지폐에 실려 있다.","facts":["이황 사후인 1574년 제자들이 세웠다.","2019년 유네스코에 등재된 9개 서원 가운데 하나다.","이황(1501~1570)은 천 원권 지폐의 인물이다.","하회마을에서 차로 약 40분 거리다."],"travelTips":["안동에 머문다면 하회마을과 같은 날 묶어 보자.","평일에는 매우 한적해 고요함을 느끼기 좋다.","가을이면 앞 호수에 단풍이 비쳐 아름답다."],"bestTime":"10~11월","visitDuration":"1시간 30분","ticket":"1,500원","openingHours":"09:00~18:00(겨울에는 17:00까지)","galleryCaptions":["도산서원 강당"]},"ja":{"name":"安東 陶山書院","summary":"千ウォン札の人物・李滉が建てた書院。静かな水辺に佇む。","story":"韓国性理学の大学者・退渓李滉は官職を辞して故郷に戻り、後進を教えた。洛東江のほとりに建てた書堂はほとんど質素だ。飾らない木、低い瓦屋根、土の庭、そして水に向かって開いた講堂。学生たちは両脇の小さな建物に寄宿した。その建築こそが彼の哲学である。内へ向かい、抑制し、自然に従う。李滉の肖像とこの書院はどちらも千ウォン札に載っている。","facts":["李滉の没後、1574年に弟子たちが建てた。","2019年にユネスコに登録された九つの書院のひとつ。","李滉（1501〜1570）は千ウォン札の人物。","河回村から車で約40分。"],"travelTips":["安東に泊まるなら河回村と同じ日に回ろう。","平日はとても静かで、その静けさを味わうのに最適。","秋は前の湖に紅葉が映って美しい。"],"bestTime":"10〜11月","visitDuration":"1時間30分","ticket":"1,500ウォン","openingHours":"09:00〜18:00（冬は17:00まで）","galleryCaptions":["陶山書院の講堂"]},"zh":{"name":"安東陶山書院","summary":"千元紙鈔上人物李滉創辦的書院，靜靜坐落於水畔。","story":"韓國性理學最重要的學者退溪李滉辭官還鄉，專心教學。他在洛東江畔建的書堂近乎樸素：素木、低矮瓦頂、泥土院子，以及一間面向水面的講堂。學生住在兩側的小屋裡。那樣的建築正是他的哲學——向內、節制、順應自然。李滉的畫像與這座書院都印在千元紙鈔上。","facts":["1574年由李滉的弟子在其身後所建。","2019年列入世界遺產的九座書院之一。","李滉（1501–1570）是千元紙鈔上的人物。","距河回村車程約40分鐘。"],"travelTips":["若在安東過夜，可與河回村同日安排。","平日極為清靜，最適合感受那份安寧。","秋天前方湖面映著紅葉，格外好看。"],"bestTime":"10至11月","visitDuration":"1.5小時","ticket":"1,500韓元","openingHours":"09:00–18:00（冬季至17:00）","galleryCaptions":["陶山書院的講堂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('juwangsan', 'juwangsan', 'gyeongbuk', 'Vườn quốc gia Juwangsan', 'Juwangsan National Park', 'mountain', 129.18, 36.395, 'Hẻm núi đá dựng đứng với ba tầng thác, vườn quốc gia nhỏ nhất mà kịch tính nhất Hàn Quốc.', 'Juwangsan không cao, nhưng đá ở đây dựng thành vách thẳng đứng hai bên một khe hẹp, và đường mòn chính luồn ngay giữa khe đó. Đi chừng một giờ là gặp ba thác nước nối tiếp, mỗi thác đổ vào một hồ đá xanh ngắt. Truyền thuyết kể một vị vương gia Trung Hoa tên Juwang từng ẩn náu trong hang đá nơi đây, và tên núi ra đời từ đó. Mùa thu, hẻm núi đỏ rực; đầu hè, nước thác mạnh nhất.', '["Là vườn quốc gia nhỏ nhất trong hệ thống vườn quốc gia Hàn Quốc.","Nổi tiếng với ba thác Yongyeon, Jeolgu và Yongchu.","Vách đá hình thành từ hoạt động núi lửa cổ, được công nhận công viên địa chất.","Chùa Daejeonsa dưới chân núi dựng từ thời Silla."]', '["Đường tới ba thác dễ đi, phù hợp cả gia đình.","Cần xe riêng hoặc bus liên tỉnh tới Cheongsong.","Cuối tháng 10 lá đỏ đẹp nhất nhưng rất đông cuối tuần."]', 'Tháng 6 và tháng 10–11', 'Nửa ngày', '', 'Vào núi 04:00–15:00 (tháng 4–10) và 05:00–14:00 (tháng 11–3)', '["hidden-gem"]', '["vườn quốc gia","thác nước","leo núi"]', '[{"seed":"juwangsan","caption":"Hẻm đá và thác Juwangsan","ratio":"16/9"}]', '["hahoe-folk-village"]', 0, 'https://www.knps.or.kr/front/portal/visit/visitCourseMain.do?parkId=121000&menuNo=7020099', '2026-08-05', '{"en":{"name":"Juwangsan National Park","summary":"A gorge of vertical rock with three waterfalls — the smallest national park in Korea, and the most dramatic.","story":"Juwangsan is not high, but its rock stands in sheer walls on either side of a narrow cleft, and the main trail runs straight through it. About an hour in you reach three waterfalls in succession, each dropping into a green rock pool. Legend tells of a Chinese prince named Juwang who hid in a cave here, and the mountain took his name. In autumn the gorge burns red; in early summer the falls run strongest.","facts":["The smallest national park in the Korean system.","Known for the Yongyeon, Jeolgu and Yongchu waterfalls.","The rock walls formed in ancient volcanic activity and are a recognised geopark.","Daejeonsa temple at the foot dates from the Silla period."],"travelTips":["The trail to the three waterfalls is easy and suits families.","You need a car or an intercity bus to Cheongsong.","Late October has the best colour and the biggest weekend crowds."],"bestTime":"June and October–November","visitDuration":"Half a day","ticket":"","openingHours":"Entry 04:00–15:00 (April–October) and 05:00–14:00 (November–March)","galleryCaptions":["The gorge and waterfalls of Juwangsan"]},"ko":{"name":"주왕산국립공원","summary":"수직 암벽의 협곡과 세 개의 폭포. 가장 작지만 가장 극적인 국립공원이다.","story":"주왕산은 높지 않지만 바위가 좁은 골짜기 양쪽에 수직으로 서 있고, 주 등산로가 그 사이를 곧장 지난다. 한 시간쯤 걸으면 폭포 세 개가 이어지고 각각 초록빛 소로 떨어진다. 주왕이라는 중국의 왕족이 이곳 동굴에 숨었다는 전설에서 산 이름이 왔다. 가을이면 협곡이 붉게 타오르고, 초여름에는 폭포의 물이 가장 세차다.","facts":["한국 국립공원 가운데 면적이 가장 작다.","용연폭포, 절구폭포, 용추폭포로 유명하다.","암벽은 고대 화산활동으로 형성되었으며 지질공원으로 인정받았다.","산 아래 대전사는 신라 때 창건되었다."],"travelTips":["세 폭포까지 가는 길은 평이해 가족 여행에 좋다.","자가용이나 청송행 시외버스가 필요하다.","10월 말 단풍이 가장 좋지만 주말은 매우 붐빈다."],"bestTime":"6월, 10~11월","visitDuration":"반나절","ticket":"","openingHours":"입산 04:00~15:00(4~10월), 05:00~14:00(11~3월)","galleryCaptions":["주왕산의 협곡과 폭포"]},"ja":{"name":"周王山国立公園","summary":"垂直の岩壁の峡谷と三つの滝。最も小さく、最も劇的な国立公園。","story":"周王山は高くはないが、岩が狭い谷の両側に垂直に立ち、主な登山道がその間をまっすぐ抜ける。一時間ほど歩くと滝が三つ続き、それぞれ緑の淵に落ちる。周王という中国の王族がここの洞窟に隠れたという伝説から山の名が来た。秋には峡谷が赤く燃え、初夏には滝の水が最も勢いを増す。","facts":["韓国の国立公園の中で面積が最も小さい。","龍淵滝、臼滝、龍湫滝で知られる。","岩壁は古代の火山活動で形成され、ジオパークに認定されている。","麓の大典寺は新羅時代の創建。"],"travelTips":["三つの滝までの道は平易で家族連れにも向く。","自家用車か青松行きの市外バスが必要。","10月末の紅葉が最も美しいが週末は混む。"],"bestTime":"6月、10〜11月","visitDuration":"半日","ticket":"","openingHours":"入山は04:00〜15:00（4〜10月）、05:00〜14:00（11〜3月）","galleryCaptions":["周王山の峡谷と滝"]},"zh":{"name":"周王山國立公園","summary":"垂直岩壁夾出的峽谷與三道瀑布，是韓國最小卻最戲劇性的國立公園。","story":"周王山不高，但岩壁在狹窄谷地兩側垂直而立，主步道就從中間穿過。走約一小時，會遇上三道相連的瀑布，各自落入碧綠的水潭。傳說一位名叫周王的中國王族曾藏身此地的洞穴，山因此得名。秋天，峽谷紅得像燃燒；初夏則是瀑布水勢最強的時候。","facts":["是韓國國立公園中面積最小的一座。","以龍淵、臼谷與龍湫三道瀑布聞名。","岩壁形成於古代火山活動，獲認定為地質公園。","山腳的大典寺建於新羅時期。"],"travelTips":["通往三道瀑布的路平緩，適合親子同行。","需自駕或搭往青松的客運。","十月底紅葉最美，但週末很擁擠。"],"bestTime":"6月與10至11月","visitDuration":"半天","ticket":"","openingHours":"入山04:00–15:00（4至10月）、05:00–14:00（11至3月）","galleryCaptions":["周王山的峽谷與瀑布"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('yangdong-folk-village', 'yangdong-folk-village', 'gyeongbuk', 'Làng Yangdong', 'Yangdong Folk Village', 'unesco', 129.2525, 35.9955, 'Làng dòng họ Joseon còn nguyên trên sườn đồi, nhà quan lại trên cao, nhà tá điền dưới thấp.', 'Yangdong được UNESCO ghi danh cùng Hahoe, nhưng ít khách hơn hẳn và nhờ vậy giữ được cái yên tĩnh của một làng thật. Điều đáng đọc ở đây là địa hình: nhà của các gia đình quan lại nằm trên cao, mái ngói, có sân trong và nhà học riêng; nhà tá điền mái tranh nằm dưới chân đồi. Trật tự xã hội Joseon được viết thẳng vào cách bố trí đất đai, và bạn đọc được nó chỉ bằng cách đi lên dốc. Làng do hai dòng họ Wolseong Son và Yeogang Yi lập từ thế kỷ 15, và con cháu họ vẫn sống trong chính những căn nhà ấy.', '["Được UNESCO công nhận năm 2010 cùng với làng Hahoe.","Do hai dòng họ Wolseong Son và Yeogang Yi lập từ thế kỷ 15.","Nhà quan lại nằm trên cao, nhà tá điền mái tranh nằm dưới thấp.","Còn khoảng 160 nếp nhà cổ, phần lớn vẫn có người ở."]', '["Ít khách hơn Hahoe rất nhiều — đây là lý do chính để chọn Yangdong.","Làng trải trên sườn đồi, đi bộ nhiều dốc, mang giày êm.","Người dân đang sống ở đây; đừng tự ý vào sân hay chụp qua cửa sổ."]', 'Tháng 4–6 và 9–11', '2–3 giờ', '4.000 KRW', '09:00–18:00', '["unesco","hidden-gem"]', '["UNESCO","làng cổ","Joseon","dòng họ"]', '[{"seed":"yangdong-folk-village","caption":"Nhà quan lại trên sườn đồi Yangdong","ratio":"16/9"}]', '["daereungwon","gyeongju-national-museum"]', 0, 'https://www.gyeongju.go.kr/tour/page.do?mnu_uid=2378', '2026-08-04', '{"en":{"name":"Yangdong Folk Village","summary":"An intact Joseon clan village on a hillside — the gentry above, their tenants below.","story":"Yangdong was inscribed by UNESCO alongside Hahoe but gets far fewer visitors, and keeps the quiet of a real village because of it. The thing to read here is the terrain: the gentry houses stand high up, tiled, with inner courtyards and their own study halls; the tenants'' thatched houses sit at the bottom of the hill. Joseon''s social order is written straight into the layout of the land, and you read it simply by walking uphill. The village was founded in the 15th century by the Wolseong Son and Yeogang Yi clans, and their descendants still live in the same houses.","facts":["Inscribed by UNESCO in 2010 together with Hahoe village.","Founded in the 15th century by the Wolseong Son and Yeogang Yi clans.","Gentry houses stand high on the slope, thatched tenant houses at the bottom.","About 160 historic houses remain, most of them still lived in."],"travelTips":["Far quieter than Hahoe — that is the main reason to choose Yangdong.","The village spreads over a hillside with a lot of climbing; wear easy shoes.","People live here; don''t wander into yards or shoot through windows."],"bestTime":"April–June and September–November","visitDuration":"2–3 hours","ticket":"4,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["Gentry houses on the Yangdong hillside"]},"ko":{"name":"경주 양동마을","summary":"비탈에 그대로 남은 조선의 반촌. 위쪽에 양반집, 아래쪽에 소작농의 집이 있다.","story":"양동은 하회와 함께 유네스코에 등재되었지만 찾는 사람이 훨씬 적고, 그래서 진짜 마을의 고요가 남아 있다. 여기서 읽어야 할 것은 지형이다. 양반가는 높은 자리에 기와를 얹고 안마당과 자기 서당을 두었으며, 소작농의 초가는 언덕 아래에 있다. 조선의 신분 질서가 땅의 배치에 그대로 쓰여 있고, 비탈을 걸어 올라가는 것만으로 그것을 읽게 된다. 마을은 15세기에 월성 손씨와 여강 이씨가 세웠고, 후손들이 지금도 그 집에 산다.","facts":["2010년 하회마을과 함께 유네스코 세계유산에 등재되었다.","15세기 월성 손씨와 여강 이씨가 세운 마을이다.","양반가는 비탈 위쪽에, 초가의 소작농 집은 아래쪽에 있다.","고택 160여 채가 남아 있고 대부분 사람이 살고 있다."],"travelTips":["하회보다 훨씬 한산하다. 양동을 고르는 가장 큰 이유다.","마을이 비탈에 퍼져 있어 오르내림이 많다. 편한 신발을 신자.","사람이 사는 곳이다. 마당에 들어가거나 창 안을 찍지 말자."],"bestTime":"4~6월, 9~11월","visitDuration":"2~3시간","ticket":"4,000원","openingHours":"09:00~18:00","galleryCaptions":["양동마을 비탈의 양반가"]},"ja":{"name":"慶州良洞村","summary":"斜面にそのまま残る朝鮮の同族村。上に両班の家、下に小作の家がある。","story":"良洞は河回とともにユネスコに登録されたが訪れる人はずっと少なく、そのぶん本物の村の静けさが残っている。ここで読むべきは地形だ。両班の家は高い場所に瓦を葺き、内庭と自前の書堂を備える。小作の茅葺きは丘の下にある。朝鮮の身分秩序が土地の配置にそのまま書かれており、坂を上るだけでそれが読める。村は15世紀に月城孫氏と驪江李氏が興し、その子孫が今も同じ家に住んでいる。","facts":["2010年、河回村とともにユネスコ世界遺産へ登録された。","15世紀に月城孫氏と驪江李氏が興した村である。","両班の家は斜面の上、茅葺きの小作の家は下にある。","古宅160軒ほどが残り、その多くに人が住んでいる。"],"travelTips":["河回よりずっと静かだ。良洞を選ぶ最大の理由である。","村は斜面に広がり上り下りが多い。歩きやすい靴で。","人が暮らしている。庭に入ったり窓の中を撮ったりしないこと。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2〜3時間","ticket":"4,000ウォン","openingHours":"09:00〜18:00","galleryCaptions":["良洞村の斜面に建つ両班の家"]},"zh":{"name":"慶州良洞村","summary":"完整留在山坡上的朝鮮宗族村落——士族住高處，佃農住低處。","story":"良洞與河回同時被列入世界遺產，但遊客少得多，也因此保有一座真實村落的安靜。這裡真正該讀的是地形：士族的宅子建在高處，覆瓦、有內院與自家書堂；佃農的茅屋則在山腳。朝鮮的身分秩序被直接寫進土地的配置裡，而你只要往坡上走，就讀得出來。村子由月城孫氏與驪江李氏於十五世紀所建，他們的後代至今仍住在同樣的屋子裡。","facts":["2010年與河回村一同列入世界遺產。","由月城孫氏與驪江李氏於15世紀創建。","士族宅第位於坡上，茅頂的佃農住屋在坡下。","現存古宅約160棟，多數仍有人居住。"],"travelTips":["比河回安靜許多——這正是選良洞的主要理由。","村子沿坡展開，上上下下不少，穿好走的鞋。","這裡有人居住，別隨意走進院子或對著窗內拍照。"],"bestTime":"4至6月與9至11月","visitDuration":"2至3小時","ticket":"4,000韓元","openingHours":"09:00–18:00","galleryCaptions":["良洞村坡上的士族宅第"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('andong-woryeonggyo', 'andong-woryeonggyo', 'gyeongbuk', 'Cầu gỗ Woryeonggyo (Andong)', 'Woryeonggyo Bridge, Andong', 'bridge', 128.7295, 36.5595, 'Cầu gỗ đi bộ dài nhất Hàn Quốc, dựng theo một lá thư và đôi dép cỏ tìm thấy trong ngôi mộ cổ.', 'Năm 1998, người ta khai quật một ngôi mộ thế kỷ 16 ở Andong và tìm thấy trên ngực người đàn ông một lá thư của vợ ông cùng một đôi dép bện từ tóc bà. Trong thư, người vợ đang mang thai viết cho chồng vừa mất: ''Chàng luôn nói chúng ta sẽ sống bên nhau đến bạc đầu, sao lại bỏ thiếp mà đi trước?'' Bức thư ấy khiến cả nước xúc động, và thành phố dựng cây cầu gỗ này bắc qua sông Nakdong để tưởng nhớ — hình dáng cầu lấy từ đôi dép bện tóc. Cầu dài ba trăm tám mươi bảy mét, chỉ dành cho người đi bộ, và giữa cầu có một mái đình để dừng lại. Ban đêm cầu được thắp đèn và sương từ mặt sông dâng lên.', '["Dài khoảng 387m, là cầu gỗ dành cho người đi bộ dài nhất Hàn Quốc.","Được dựng để tưởng nhớ lá thư của một người vợ thế kỷ 16 tìm thấy năm 1998.","Hình dáng cầu lấy cảm hứng từ đôi dép bện bằng tóc trong ngôi mộ.","Giữa cầu có mái đình Woryeongjeong để nghỉ chân."]', '["Đi lúc chạng vạng khi đèn cầu vừa bật và sương sông bắt đầu lên.","Kết hợp với làng Hahoe cách đó khoảng 30 phút xe.","Có màn phun nước và nhạc vào các tối cuối tuần mùa hè."]', 'Tháng 4–6 và 9–11; buổi tối', '1 giờ', '', 'Cả ngày (đèn bật lúc chập tối)', '["hidden-gem"]', '["cầu gỗ","sông","về đêm","chuyện tình"]', '[{"seed":"andong-woryeonggyo","caption":"Cầu Woryeonggyo lên đèn","ratio":"16/9"}]', '["hahoe-folk-village","dosan-seowon"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Woryeonggyo Bridge, Andong","summary":"Korea''s longest wooden footbridge, built after a letter and a pair of woven shoes were found in a grave.","story":"In 1998 a 16th-century grave was excavated at Andong, and on the man''s chest lay a letter from his wife along with a pair of shoes woven from her hair. In it the pregnant widow wrote to her newly dead husband: ''You always said we would live together until our hair turned white — how could you go before me?'' The letter moved the whole country, and the city built this wooden bridge across the Nakdong in its memory, its shape taken from those woven shoes. It runs three hundred and eighty-seven metres, is for pedestrians only, and has a roofed pavilion halfway across. At night it is lit and mist rises off the river.","facts":["About 387m long, Korea''s longest wooden pedestrian bridge.","Built in memory of a 16th-century wife''s letter discovered in 1998.","Its shape was inspired by the hair-woven shoes found in the grave.","The Woryeongjeong pavilion sits halfway across for resting."],"travelTips":["Come at dusk, as the lights come on and the river mist starts to rise.","Combine it with Hahoe village, about 30 minutes away by car.","There is a fountain and music show on summer weekend evenings."],"bestTime":"April–June and September–November; evenings","visitDuration":"1 hour","ticket":"","openingHours":"Open all day (lit from dusk)","galleryCaptions":["Woryeonggyo bridge lit at night"]},"ko":{"name":"안동 월영교","summary":"한국에서 가장 긴 나무 인도교. 옛 무덤에서 나온 편지와 미투리를 따라 지었다.","story":"1998년 안동에서 16세기 무덤을 발굴했는데, 남자의 가슴 위에 아내의 편지와 그녀의 머리카락으로 삼은 미투리 한 켤레가 놓여 있었다. 아이를 밴 아내는 막 세상을 떠난 남편에게 이렇게 썼다. ''당신은 늘 머리가 셀 때까지 함께 살자 하셨는데, 어찌 나를 두고 먼저 가십니까.'' 이 편지는 온 나라를 울렸고, 시는 낙동강 위에 이 나무다리를 놓아 그것을 기렸다. 다리의 모양은 그 미투리에서 왔다. 길이 387m의 보행 전용 다리이고, 한가운데에 쉬어 갈 정자가 있다. 밤이면 불이 켜지고 강에서 안개가 오른다.","facts":["길이 약 387m로 한국에서 가장 긴 나무 인도교다.","1998년 발견된 16세기 아내의 편지를 기려 지었다.","다리의 형태는 무덤에서 나온 머리카락 미투리에서 따왔다.","다리 한가운데에 쉬어 가는 월영정이 있다."],"travelTips":["불이 켜지고 강 안개가 오르기 시작하는 해질 무렵에 가자.","차로 30분 거리의 하회마을과 묶어서 보자.","여름 주말 저녁에는 분수와 음악 공연이 있다."],"bestTime":"4~6월, 9~11월의 저녁","visitDuration":"1시간","ticket":"","openingHours":"상시(해질 무렵 점등)","galleryCaptions":["불이 켜진 월영교"]},"ja":{"name":"安東月映橋","summary":"韓国最長の木造歩道橋。古い墓から出た手紙と草鞋にならって架けられた。","story":"1998年、安東で16世紀の墓が発掘され、男の胸の上に妻の手紙と、彼女の髪で編んだ草鞋が一足置かれていた。身重の妻は、亡くなったばかりの夫にこう書いていた。「あなたはいつも髪が白くなるまで共に暮らそうと仰ったのに、どうして私を置いて先に行かれるのですか」。この手紙は国じゅうを泣かせ、市は洛東江の上にこの木の橋を架けて記念した。橋の形はその草鞋から取られている。長さ387mの歩行者専用で、中ほどに屋根つきの東屋がある。夜には灯が入り、川から霧が立つ。","facts":["長さ約387mで、韓国最長の木造歩道橋である。","1998年に見つかった16世紀の妻の手紙を記念して架けられた。","橋の形は墓から出た髪編みの草鞋に着想を得ている。","橋の中ほどに休憩用の月映亭がある。"],"travelTips":["灯が入り川霧が立ち始める夕暮れに行こう。","車で30分の河回村と合わせて回ろう。","夏の週末の夜には噴水と音楽の演出がある。"],"bestTime":"4〜6月、9〜11月の夕方","visitDuration":"1時間","ticket":"","openingHours":"終日（日没から点灯）","galleryCaptions":["灯のともる月映橋"]},"zh":{"name":"安東月映橋","summary":"韓國最長的木造人行橋，依一封信與一雙草鞋而建——兩者都出自一座古墓。","story":"1998年，安東一座十六世紀的墳墓出土，男子胸口放著妻子的一封信，以及一雙用她的頭髮編成的草鞋。信中，懷著身孕的妻子寫給剛過世的丈夫：「您總說要與我白頭偕老，怎麼就先丟下我走了呢？」這封信讓整個國家為之動容，市府於是在洛東江上架起這座木橋以為紀念，橋的形制便取自那雙髮編的草鞋。橋長三百八十七公尺，只供行人通行，橋中央設有一座有頂的亭子。入夜後打燈，江面霧氣升起。","facts":["全長約387公尺，是韓國最長的木造人行橋。","為紀念1998年發現的一封十六世紀妻子書信而建。","橋形靈感取自墓中以頭髮編成的草鞋。","橋中央設有月映亭供人歇腳。"],"travelTips":["黃昏前來，正好趕上點燈與江霧初起。","可與車程約30分鐘的河回村排在一起。","夏季週末夜間有噴泉與音樂表演。"],"bestTime":"4至6月與9至11月的傍晚","visitDuration":"1小時","ticket":"","openingHours":"全日開放（入夜點燈）","galleryCaptions":["點燈後的月映橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('buseoksa', 'buseoksa', 'gyeongbuk', 'Chùa Buseoksa (Yeongju)', 'Buseoksa Temple, Yeongju', 'unesco', 128.6875, 36.9945, 'Toà nhà gỗ cổ nhất Hàn Quốc, với những cây cột phình giữa thân đỡ mái nhìn ra trùng điệp núi.', 'Muryangsujeon của chùa Buseoksa dựng lại năm 1376 và là một trong những toà nhà gỗ cổ nhất còn đứng ở Hàn Quốc. Điều khiến giới kiến trúc say mê là các cây cột: chúng phình ra ở giữa rồi thon lại hai đầu — kỹ thuật entasis mà người Hy Lạp cổ cũng dùng — để mắt người nhìn không thấy cột bị lõm. Đứng tựa lan can trước điện, bạn nhìn xuống một biển núi Sobaeksan xếp lớp nhạt dần, và đó là lý do người ta bảo cảnh nhìn từ Buseoksa là đẹp nhất trong các ngôi chùa Hàn Quốc. Tên chùa nghĩa là ''đá nổi'', theo tảng đá lớn bên hông điện mà truyền thuyết nói từng lơ lửng trên không.', '["Điện Muryangsujeon dựng lại năm 1376, là một trong những công trình gỗ cổ nhất Hàn Quốc.","Cột điện dùng kỹ thuật entasis — phình ở giữa thân.","Được UNESCO ghi danh năm 2018 trong cụm ''Sansa, chùa núi Hàn Quốc''.","Tên chùa nghĩa là ''đá nổi'', theo tảng đá bên hông điện chính."]', '["Lên tới sân điện phải leo nhiều bậc đá, tính thêm 20 phút.","Chiều muộn ánh sáng xiên qua các lớp núi là lúc đẹp nhất.","Yeongju khá xa các điểm khác — nên đi bằng xe riêng."]', 'Tháng 10–11 (lá đỏ)', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:00–18:00', '["unesco","hidden-gem"]', '["UNESCO","chùa","kiến trúc gỗ","toàn cảnh"]', '[{"seed":"buseoksa","caption":"Điện Muryangsujeon nhìn ra dãy Sobaeksan","ratio":"16/9"}]', '["dosan-seowon"]', 1, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Buseoksa Temple, Yeongju","summary":"Korea''s oldest wooden building, its swelling columns holding a roof above range upon range of mountains.","story":"Buseoksa''s Muryangsujeon was rebuilt in 1376 and is among the oldest wooden buildings still standing in Korea. What fascinates architects are the columns: they swell at the middle and taper at both ends — entasis, the same correction the ancient Greeks used — so the eye does not read them as pinched. Leaning on the rail in front of the hall you look down over a sea of Sobaeksan ridges fading paler into the distance, which is why people say Buseoksa has the finest view of any Korean temple. The name means ''floating stone'', after the large rock beside the hall that legend says once hung in the air.","facts":["Muryangsujeon hall was rebuilt in 1376 and is among Korea''s oldest wooden structures.","Its columns use entasis — a swelling at the middle of the shaft.","Inscribed by UNESCO in 2018 as part of the Sansa, Buddhist Mountain Monasteries of Korea.","The name means ''floating stone'', after the rock beside the main hall."],"travelTips":["Reaching the hall means climbing a lot of stone steps; allow an extra 20 minutes.","Late afternoon, with the light raking across the ridges, is the best hour.","Yeongju is far from the other sights — you really want your own car."],"bestTime":"October–November (autumn colour)","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:00–18:00","galleryCaptions":["Muryangsujeon looking out over the Sobaeksan ridges"]},"ko":{"name":"영주 부석사","summary":"한국에서 가장 오래된 목조 건물. 배흘림기둥이 겹겹의 산 위로 지붕을 받친다.","story":"부석사 무량수전은 1376년에 다시 지어졌고, 한국에 서 있는 목조 건물 가운데 가장 오래된 축에 든다. 건축을 하는 사람들이 반하는 것은 기둥이다. 가운데가 불룩하고 위아래로 갈수록 가늘어지는 배흘림으로, 고대 그리스가 쓴 것과 같은 보정이다. 눈이 기둥을 잘록하게 읽지 않도록 하는 장치다. 전각 앞 난간에 기대면 소백산 능선이 겹겹이 옅어지며 펼쳐지는데, 그래서 사람들은 부석사의 조망이 한국 절 가운데 으뜸이라고 말한다. 절 이름은 ''뜬 돌''이라는 뜻으로, 무량수전 옆의 큰 바위가 한때 공중에 떠 있었다는 이야기에서 왔다.","facts":["무량수전은 1376년에 중건된, 한국 최고(最古)급 목조 건축이다.","기둥에 배흘림 기법을 썼다.","2018년 ''산사, 한국의 산지 승원''으로 유네스코에 등재되었다.","절 이름은 무량수전 옆의 바위에서 유래한 ''뜬 돌''이라는 뜻이다."],"travelTips":["전각 마당까지 돌계단을 꽤 올라야 한다. 20분쯤 더 잡자.","늦은 오후, 빛이 능선을 비스듬히 훑을 때가 가장 좋다.","영주는 다른 명소와 멀다. 자차가 사실상 필요하다."],"bestTime":"10~11월(단풍)","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:00~18:00","galleryCaptions":["소백산 능선을 바라보는 무량수전"]},"ja":{"name":"栄州浮石寺","summary":"韓国最古級の木造建築。胴の膨らんだ柱が、幾重もの山の上に屋根を支える。","story":"浮石寺の無量寿殿は1376年に建て直され、韓国に立つ木造建築のうち最も古い部類に入る。建築を志す人が惹かれるのは柱だ。中ほどが膨らみ上下へ細くなるエンタシスで、古代ギリシャが用いたのと同じ補正である。柱が窪んで見えないようにする工夫だ。堂の前の欄干に寄りかかると、小白山の稜線が幾重にも淡くなりながら広がる。だから人は、浮石寺の眺めは韓国の寺で随一だと言う。寺の名は「浮かぶ石」の意で、堂の脇の大岩がかつて宙に浮いていたという伝えによる。","facts":["無量寿殿は1376年の再建で、韓国最古級の木造建築である。","柱にはエンタシス（胴張り）が用いられている。","2018年「山寺、韓国の山地僧院」としてユネスコに登録された。","寺名は本堂脇の岩に由来する「浮かぶ石」の意である。"],"travelTips":["堂の前庭まで石段をかなり上る。20分ほど余分に見よう。","光が稜線を斜めに撫でる遅い午後が最も美しい。","栄州は他の名所から遠い。自家用車がほぼ必要だ。"],"bestTime":"10〜11月（紅葉）","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:00〜18:00","galleryCaptions":["小白山の稜線を望む無量寿殿"]},"zh":{"name":"榮州浮石寺","summary":"韓國最古老的木造建築，中段隆起的柱子把屋頂撐在層層山巒之上。","story":"浮石寺無量壽殿於1376年重建，是韓國現存最古老的木造建築之一。真正讓建築人著迷的是柱子：它們中段隆起、兩端收細——正是古希臘也用過的收分曲線修正——好讓眼睛不會把柱子看成凹陷。倚在殿前欄杆上向外望，小白山的稜線一層層淡去，這就是人們說浮石寺擁有韓國寺院中最好視野的理由。寺名意為「浮石」，取自正殿旁那塊傳說曾懸在空中的大岩。","facts":["無量壽殿重建於1376年，屬韓國最古老的木構建築之列。","殿柱採用收分曲線（柱身中段隆起）。","2018年以「山寺，韓國的山地僧院」之一列入世界遺產。","寺名意為「浮石」，取自正殿旁的巨岩。"],"travelTips":["上到殿前庭院要爬不少石階，請多抓20分鐘。","傍晚光線斜掠過稜線時最美。","榮州離其他景點都遠，基本上需要自駕。"],"bestTime":"10至11月（紅葉）","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:00–18:00","galleryCaptions":["望向小白山稜線的無量壽殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('pohang-homigot', 'pohang-homigot', 'gyeongbuk', 'Mũi Homigot (Pohang)', 'Homigot Cape, Pohang', 'beach', 129.5675, 36.0765, 'Điểm cực đông đất liền Hàn Quốc, có bàn tay đồng khổng lồ nhô lên khỏi mặt biển đón mặt trời đầu năm.', 'Homigot là chỗ mặt trời chạm vào đất liền Hàn Quốc sớm nhất mỗi ngày, và đêm giao thừa cả nước kéo về đây. Trên mũi đất có tác phẩm ''Bàn tay tương sinh'': hai bàn tay đồng lớn, một đặt trên bờ, một nhô lên khỏi mặt nước cách bờ chừng vài chục mét, và đúng lúc mặt trời mọc thì nó nằm gọn giữa các ngón tay của bàn tay ngoài biển. Ngoài dịp đầu năm nơi này rất vắng, chỉ có gió biển và mấy quán bán mực khô. Pohang ngay bên cạnh là thành phố thép của Hàn Quốc, nên khung cảnh ở đây luôn có một ống khói nhà máy ở rìa tầm mắt.', '["Là điểm cực đông của đất liền Hàn Quốc.","Tác phẩm ''Bàn tay tương sinh'' gồm hai bàn tay đồng, một trên bờ và một dưới biển.","Lễ đón mặt trời mọc đầu năm tổ chức tại đây mỗi ngày 1 tháng 1.","Pohang là trung tâm công nghiệp thép lớn nhất Hàn Quốc."]', '["Ngày 1 tháng 1 cực kỳ đông; các ngày khác gần như vắng.","Bàn tay ngoài biển ăn ảnh nhất lúc mặt trời vừa lên khỏi đường chân trời.","Gió ở mũi đất rất mạnh quanh năm, mặc ấm hơn bạn nghĩ."]', 'Bình minh, đặc biệt ngày 1 tháng 1', '1,5 giờ', '', 'Cả ngày', '["popular"]', '["bình minh","biển","điêu khắc","cực đông"]', '[{"seed":"pohang-homigot","caption":"Bàn tay đồng đón mặt trời mọc","ratio":"16/9"}]', '["gyeongju-national-museum"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Homigot Cape, Pohang","summary":"The easternmost point of mainland Korea, where a giant bronze hand rises out of the sea to catch the New Year sun.","story":"Homigot is where the sun first touches mainland Korea each day, and on New Year''s Eve the country comes here. On the headland stands ''The Hands of Harmony'': two large bronze hands, one on the shore and one rising out of the water some tens of metres off, positioned so that at sunrise the sun sits exactly between the fingers of the seaward hand. Outside the New Year it is very quiet, just sea wind and a few stalls selling dried squid. Pohang next door is Korea''s steel city, so there is always a smokestack somewhere at the edge of the view.","facts":["The easternmost point of the Korean mainland.","''The Hands of Harmony'' is a pair of bronze hands, one on shore and one in the sea.","A sunrise festival is held here every 1 January.","Pohang is Korea''s largest steel-producing centre."],"travelTips":["1 January is extremely busy; almost every other day is empty.","The seaward hand photographs best just as the sun clears the horizon.","The wind on the cape is strong year-round — dress warmer than you expect."],"bestTime":"Sunrise, especially 1 January","visitDuration":"1.5 hours","ticket":"","openingHours":"All day","galleryCaptions":["The bronze hand catching the sunrise"]},"ko":{"name":"포항 호미곶","summary":"한국 내륙의 최동단. 거대한 청동 손이 바다에서 솟아 새해 첫 해를 받는다.","story":"호미곶은 해가 한국 내륙에 가장 먼저 닿는 곳이고, 12월 31일 밤이면 온 나라가 여기로 온다. 곶에는 ''상생의 손''이 있다. 큰 청동 손 두 개로 하나는 뭍에, 하나는 물에서 수십 미터 떨어져 솟아 있는데, 해가 뜰 때 바다 쪽 손의 손가락 사이에 해가 정확히 들어앉는다. 새해가 아니면 아주 한산하다. 바닷바람과 오징어를 말려 파는 몇몇 가게뿐이다. 바로 옆 포항은 한국의 철강 도시라, 이곳의 풍경 가장자리에는 늘 굴뚝 하나가 서 있다.","facts":["한국 내륙의 최동단이다.","''상생의 손''은 뭍과 바다에 각각 놓인 두 개의 청동 손이다.","해맞이 행사가 매년 1월 1일 이곳에서 열린다.","포항은 한국 최대의 철강 산업 도시다."],"travelTips":["1월 1일은 극도로 붐빈다. 그 밖의 날은 거의 비어 있다.","바다 쪽 손은 해가 수평선을 막 넘을 때 가장 잘 나온다.","곶의 바람은 연중 세다. 생각보다 두껍게 입자."],"bestTime":"일출, 특히 1월 1일","visitDuration":"1.5시간","ticket":"","openingHours":"상시","galleryCaptions":["해돋이를 받는 청동 손"]},"ja":{"name":"浦項虎尾串","summary":"韓国本土の最東端。巨大な青銅の手が海から突き出し、新年の初日の出を受ける。","story":"虎尾串は毎日、太陽が韓国本土に最初に触れる場所で、大晦日の夜には国じゅうがここへ来る。岬には「相生の手」がある。大きな青銅の手が二つ、一方は陸に、一方は数十メートル沖の水面から突き出しており、日の出のとき海側の手の指のあいだに太陽がちょうど収まる。新年以外はとても静かだ。潮風と、スルメを干して売る店が数軒あるだけである。隣の浦項は韓国の鉄鋼の街なので、ここの風景の端にはいつも煙突が一本立っている。","facts":["韓国本土の最東端である。","「相生の手」は陸と海にそれぞれ据えられた二つの青銅の手だ。","毎年1月1日にここで日の出の行事が行われる。","浦項は韓国最大の鉄鋼産業都市である。"],"travelTips":["1月1日は極度に混む。それ以外の日はほとんど無人だ。","海側の手は、太陽が水平線を越えた直後が最もよく撮れる。","岬の風は年中強い。思うより厚く着よう。"],"bestTime":"日の出、とくに1月1日","visitDuration":"1.5時間","ticket":"","openingHours":"終日","galleryCaptions":["日の出を受ける青銅の手"]},"zh":{"name":"浦項虎尾串","summary":"韓國本土的最東端，一隻巨大的青銅手自海中伸出，迎接新年的第一道陽光。","story":"虎尾串是每天陽光最早觸及韓國本土之處，跨年夜全國的人都往這裡來。岬上立著《相生之手》：兩隻巨大的青銅手，一隻在岸上，一隻自數十公尺外的海面伸出，位置經過安排，日出時太陽恰好落在海上那隻手的指縫之間。除了元旦，這裡非常安靜，只有海風與幾攤曬魷魚的小販。隔壁的浦項是韓國的鋼鐵之城，所以這片風景的邊緣，總會有一支煙囪。","facts":["是韓國本土的最東端。","《相生之手》是一對青銅手，分置於岸上與海中。","每年1月1日在此舉行迎日出活動。","浦項是韓國最大的鋼鐵工業重鎮。"],"travelTips":["1月1日極度擁擠，其餘日子幾乎空無一人。","海中那隻手在太陽剛躍出地平線時最上相。","岬上的風全年都強，穿得比你以為的更厚。"],"bestTime":"日出時分，尤其1月1日","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["承接日出的青銅之手"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ulleungdo', 'ulleungdo', 'gyeongbuk', 'Đảo Ulleungdo', 'Ulleungdo Island', 'island', 130.9055, 37.4995, 'Đảo núi lửa cách bờ gần ba trăm cây số, vách đá dựng đứng quanh đảo và gần như không có đất bằng.', 'Ulleungdo nằm giữa biển Đông, cách đất liền gần ba trăm cây số — tàu cao tốc đi mất hai tiếng rưỡi và huỷ chuyến thường xuyên vì sóng. Đảo là một ngọn núi lửa nhô lên khỏi biển sâu, nên gần như không có chỗ nào bằng: đường vòng quanh đảo đục thẳng vào vách đá với hàng loạt hầm ngắn, và nhà cửa bám vào những khe dốc. Duy nhất có một vùng đất phẳng là lòng chảo Nari ở giữa đảo, nơi trồng rau rừng và mọc lên những căn nhà lợp vỏ cây. Đây là đảo hiếm hoi của Hàn Quốc mà du lịch chưa san phẳng — một phần vì đi lại quá khó.', '["Cách đất liền khoảng 290 km, đi tàu cao tốc mất khoảng 2,5–3 giờ.","Là đảo núi lửa với đỉnh Seonginbong cao 984m.","Lòng chảo Nari là vùng đất bằng duy nhất đáng kể trên đảo.","Đặc sản gồm rau rừng, mực và loại bò Ulleung nuôi thả."]', '["Tàu huỷ chuyến rất thường xuyên vì sóng — chừa dư ít nhất một ngày trong lịch trình.","Nếu say sóng, uống thuốc trước khi lên tàu; hành trình khá xóc.","Từ đây có tàu đi Dokdo nhưng chỉ cập đảo được khi biển lặng."]', 'Tháng 5–6 và 9–10', '2–3 ngày', 'Phà khứ hồi khoảng 160.000–180.000 KRW (một chiều 80.000–90.000), tuỳ cảng và hãng', 'Theo lịch tàu, thường 1–3 chuyến/ngày', '["hidden-gem","verified"]', '["đảo","núi lửa","vách đá","xa xôi"]', '[{"seed":"ulleungdo","caption":"Vách đá ven biển Ulleungdo","ratio":"16/9"}]', '["pohang-homigot"]', 0, 'https://www.klook.com/activity/62090-ulleung-ferry-ulleung-cruise-departs-from-pohang/', '2026-08-04', '{"en":{"name":"Ulleungdo Island","summary":"A volcanic island nearly three hundred kilometres offshore, ringed by cliffs with almost no flat ground.","story":"Ulleungdo sits in the East Sea nearly three hundred kilometres from the mainland — the fast ferry takes two and a half hours and cancels often for swell. The island is a volcano rising out of deep water, so there is barely a level place on it: the ring road is cut straight into the cliffs through a run of short tunnels, and houses cling to steep gullies. The one real piece of flat ground is the Nari basin in the middle, where wild greens are grown and houses are roofed with bark shingles. It is one of the rare Korean islands tourism has not flattened — partly because getting there is so hard.","facts":["About 290km from the mainland; the fast ferry takes 2.5–3 hours.","A volcanic island whose highest point, Seonginbong, reaches 984m.","The Nari basin is the only substantial area of flat ground on the island.","Local specialities include wild mountain greens, squid and free-ranging Ulleung beef."],"travelTips":["Ferries cancel frequently for swell — leave at least a spare day in your plan.","If you get seasick, take something before boarding; the crossing is rough.","Boats run on to Dokdo from here, but only land when the sea is calm."],"bestTime":"May–June and September–October","visitDuration":"2–3 days","ticket":"Ferry around 160,000–180,000 KRW return (80,000–90,000 each way), depending on port and operator","openingHours":"By ferry schedule, usually 1–3 sailings a day","galleryCaptions":["The cliff coast of Ulleungdo"]},"ko":{"name":"울릉도","summary":"뭍에서 300km 가까이 떨어진 화산섬. 섬을 두른 절벽뿐이고 평지가 거의 없다.","story":"울릉도는 동해 한가운데, 뭍에서 300km 가까이 떨어져 있다. 쾌속선으로 두 시간 반이 걸리고 너울 때문에 자주 결항한다. 깊은 바다에서 솟은 화산섬이라 평평한 곳이 거의 없다. 일주도로는 절벽을 그대로 뚫어 짧은 터널이 잇달고, 집들은 가파른 골에 붙어 있다. 쓸 만한 평지는 섬 가운데의 나리분지 하나뿐인데, 산나물을 기르고 너와를 얹은 집이 있다. 관광이 아직 밀어 버리지 않은 드문 한국의 섬이다. 가기가 너무 어려운 것도 이유의 하나다.","facts":["뭍에서 약 290km 떨어져 있고 쾌속선으로 2.5~3시간 걸린다.","최고봉 성인봉이 984m인 화산섬이다.","나리분지는 섬에서 유일하다시피 한 평지다.","산나물과 오징어, 방목하는 울릉약소가 특산이다."],"travelTips":["너울로 결항이 잦다. 일정에 하루는 여유를 두자.","뱃멀미가 있다면 승선 전에 약을 먹자. 항해가 꽤 흔들린다.","여기서 독도행 배가 있지만 바다가 잔잔해야 접안한다."],"bestTime":"5~6월, 9~10월","visitDuration":"2~3일","ticket":"여객선 왕복 약 160,000~180,000원(편도 80,000~90,000원), 출항지와 선사에 따라 다름","openingHours":"선박 운항 일정에 따름, 보통 하루 1~3편","galleryCaptions":["울릉도의 절벽 해안"]},"ja":{"name":"鬱陵島","summary":"本土から300km近い火山島。島を巡るのは断崖ばかりで、平地がほとんどない。","story":"鬱陵島は東海の真ん中、本土から300km近く離れている。高速船で二時間半、うねりで欠航も多い。深い海から立ち上がった火山島なので、平らな場所がほとんどない。一周道路は断崖をそのまま貫いて短いトンネルが続き、家々は急な谷に貼りついている。まともな平地は島の中央のナリ盆地だけで、山菜が育ち、樹皮で屋根を葺いた家がある。観光がまだ均していない稀な韓国の島だ。行くのが難しすぎることも理由のひとつである。","facts":["本土から約290km、高速船で2.5〜3時間かかる。","最高峰の聖人峰が984mの火山島である。","ナリ盆地が島でほぼ唯一のまとまった平地だ。","山菜、イカ、放牧の鬱陵牛が特産である。"],"travelTips":["うねりによる欠航が多い。日程に最低一日は余裕を持とう。","船に弱いなら乗る前に酔い止めを。航海はかなり揺れる。","ここから独島行きの船も出るが、接岸は凪のときだけだ。"],"bestTime":"5〜6月、9〜10月","visitDuration":"2〜3日","ticket":"船の往復は約160,000〜180,000ウォン（片道80,000〜90,000）、港と船社により異なる","openingHours":"船の運航ダイヤによる（通常1日1〜3便）","galleryCaptions":["鬱陵島の断崖の海岸"]},"zh":{"name":"鬱陵島","summary":"距本土近三百公里的火山島，四周盡是斷崖，幾乎沒有平地。","story":"鬱陵島位於東海之中，距本土將近三百公里——快艇要兩個半小時，還常因湧浪停航。這座島是從深海裡拔起的火山，因此幾乎找不到一塊平地：環島公路直接鑿進崖壁，一連串短隧道相接，房子則攀附在陡峭的溝谷上。唯一像樣的平地是島中央的羅里盆地，那裡種著山菜，屋頂鋪的是樹皮板。這是韓國少數尚未被觀光鏟平的島嶼——有一部分原因，正是它太難抵達。","facts":["距本土約290公里，搭快艇需2.5至3小時。","是一座火山島，最高峰聖人峰海拔984公尺。","羅里盆地是島上唯一具規模的平地。","名產包括山菜、魷魚與放牧的鬱陵牛。"],"travelTips":["船班常因湧浪停開，行程請至少多留一天彈性。","會暈船的話請在登船前先服藥，航程相當顛簸。","自此有船前往獨島，但只有海況平靜時才能靠岸。"],"bestTime":"5至6月與9至10月","visitDuration":"2至3天","ticket":"船票來回約160,000至180,000韓元（單程80,000至90,000），依港口與船公司而異","openingHours":"依船班時刻，通常每日1至3班","galleryCaptions":["鬱陵島的斷崖海岸"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bulguksa', 'bulguksa', 'gyeongbuk', 'Chùa Bulguksa (Gyeongju)', 'Bulguksa Temple', 'unesco', 129.332, 35.79, 'Kiệt tác kiến trúc Phật giáo Silla thế kỷ 8, với hai bậc thang đá dẫn lên ''cõi Phật''.', 'Bulguksa nghĩa là ''chùa cõi Phật'', và toàn bộ bố cục là một bài giảng bằng đá: bậc thang Cheongungyo–Baegungyo tượng trưng cho con đường từ cõi người lên cõi Phật, hai ngôi tháp Dabotap và Seokgatap đứng đối xứng trong sân với hai phong cách hoàn toàn khác nhau. Phần gỗ đã cháy trong chiến tranh Nhâm Thìn và được phục dựng, nhưng nền đá, bậc thang và tháp thì vẫn nguyên từ năm 751. Ngồi trên bậc đá ấy, bạn đang chạm vào thứ đã ở đó gần mười ba thế kỷ.', '["Hoàn thành năm 774, được UNESCO công nhận Di sản Thế giới năm 1995.","Tháp Seokgatap và Dabotap đều là quốc bảo của Hàn Quốc.","Phần kiến trúc gỗ bị đốt năm 1593 và được phục dựng nhiều lần.","Cách hang đá Seokguram trên núi Toham khoảng 3 km."]', '["Kết hợp Bulguksa và Seokguram trong cùng buổi sáng.","Đi sớm để tránh các đoàn học sinh tham quan.","Từ ga Singyeongju (KTX) đi bus khoảng 40 phút."]', 'Tháng 4 (hoa anh đào) và tháng 10–11', '2 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '09:00–18:00', '["unesco","popular"]', '["UNESCO","Silla","Phật giáo"]', '[{"seed":"bulguksa","caption":"Bậc thang đá dẫn lên chính điện","ratio":"16/9"}]', '["seokguram","daereungwon"]', 1, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Bulguksa Temple, Gyeongju","summary":"The masterpiece of 8th-century Silla Buddhist architecture, with two stone stairways to the ''Buddha land''.","story":"Bulguksa means ''temple of the Buddha land'', and the whole layout is a sermon in stone: the Cheongungyo–Baegungyo stairways stand for the passage from the human world to the Buddha''s, and the pagodas Dabotap and Seokgatap face each other across the court in two completely different styles. The wooden halls burned in the Imjin War and were rebuilt, but the stone platforms, stairs and pagodas have been in place since 751. Sitting on those steps, you are touching something almost thirteen centuries old.","facts":["Completed in 774 and inscribed by UNESCO in 1995.","Both the Seokgatap and Dabotap pagodas are national treasures.","The wooden architecture was burned in 1593 and rebuilt several times.","About 3 km from the Seokguram grotto on Mount Toham."],"travelTips":["Do Bulguksa and Seokguram in the same morning.","Arrive early to get ahead of the school groups.","From Singyeongju KTX station, buses take about 40 minutes."],"bestTime":"April (cherry blossom) and October–November","visitDuration":"2 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"09:00–18:00","galleryCaptions":["Stone stairways rising to the main hall"]},"ko":{"name":"경주 불국사","summary":"8세기 신라 불교 건축의 걸작. 두 개의 돌계단이 ''불국토''로 이어진다.","story":"불국사는 ''부처의 나라''라는 뜻이고, 가람 배치 전체가 돌로 쓴 설법이다. 청운교와 백운교는 인간의 세계에서 부처의 세계로 건너는 길을 뜻하고, 다보탑과 석가탑은 완전히 다른 양식으로 마당을 사이에 두고 마주 선다. 목조 건물은 임진왜란에 불타 다시 세웠지만 석축과 계단, 두 탑은 751년 그대로다. 그 계단에 앉으면 열세 세기 가까운 시간을 손으로 만지는 셈이다.","facts":["774년에 완공되었고 1995년 유네스코 세계유산에 등재되었다.","석가탑과 다보탑은 모두 국보다.","목조 건축은 1593년 소실된 뒤 여러 차례 복원되었다.","토함산의 석굴암과는 약 3km 거리다."],"travelTips":["불국사와 석굴암은 같은 오전에 함께 보는 것이 좋다.","수학여행 단체보다 먼저 도착하려면 일찍 가자.","신경주역(KTX)에서 버스로 약 40분이다."],"bestTime":"4월(벚꽃), 10~11월","visitDuration":"2시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"09:00~18:00","galleryCaptions":["대웅전으로 오르는 돌계단"]},"ja":{"name":"慶州 仏国寺","summary":"8世紀新羅仏教建築の傑作。二つの石段が「仏国土」へ導く。","story":"仏国寺は「仏の国の寺」という意味で、伽藍の配置そのものが石で書かれた説法だ。青雲橋と白雲橋は人の世界から仏の世界へ渡る道を表し、多宝塔と釈迦塔はまったく異なる様式で庭を挟んで向かい合う。木造の建物は壬辰倭乱で焼け再建されたが、石壇と階段、二つの塔は751年のままだ。その石段に腰かけると、十三世紀近い時間に触れていることになる。","facts":["774年に完成し、1995年にユネスコ世界遺産に登録された。","釈迦塔と多宝塔はいずれも国宝。","木造建築は1593年に焼失し、何度か復元された。","吐含山の石窟庵とは約3kmの距離。"],"travelTips":["仏国寺と石窟庵は同じ午前に回るのがよい。","修学旅行の団体より先に着くよう早めに。","新慶州駅（KTX）からバスで約40分。"],"bestTime":"4月（桜）、10〜11月","visitDuration":"2時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"09:00〜18:00","galleryCaptions":["大雄殿へ上がる石段"]},"zh":{"name":"慶州佛國寺","summary":"八世紀新羅佛教建築的傑作，兩道石階通往「佛國土」。","story":"佛國寺意為「佛之國的寺」，整體佈局本身就是一場以石頭寫成的說法：青雲橋與白雲橋象徵自人間走向佛境，多寶塔與釋迦塔以完全不同的樣式隔著庭院相對而立。木構建築毀於壬辰倭亂後重建，但石壇、石階與雙塔自751年以來未曾更易。坐在那些石階上，你正觸摸著近十三個世紀的時間。","facts":["774年落成，1995年列入世界遺產。","釋迦塔與多寶塔皆為國寶。","木構建築於1593年焚毀，其後多次重建。","距吐含山上的石窟庵約3公里。"],"travelTips":["佛國寺與石窟庵最好安排在同一個上午。","早點到，可趕在校外教學團體之前。","自新慶州站（KTX）搭公車約40分鐘。"],"bestTime":"4月（櫻花）與10至11月","visitDuration":"2小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"09:00–18:00","galleryCaptions":["通往大雄殿的石階"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seokguram', 'seokguram', 'gyeongbuk', 'Hang đá Seokguram', 'Seokguram Grotto', 'unesco', 129.349, 35.795, 'Tượng Phật đá granite ngồi trong hang nhân tạo trên đỉnh núi, mặt hướng thẳng ra biển Đông.', 'Người Silla thế kỷ 8 đã xẻ từng khối granite, ghép thành một vòm hang tròn trên núi Toham, rồi đặt vào giữa bức tượng Phật cao ba mét rưỡi. Tượng ngồi quay mặt về phía đông, và vào ngày đông chí, tia nắng đầu tiên từ biển từng chiếu thẳng vào giữa trán. Kỹ thuật ghép đá và hệ thông gió tự nhiên tinh vi đến mức các nỗ lực trùng tu hiện đại từng làm hỏng cân bằng độ ẩm, buộc phải lắp kính bảo vệ. Bạn xem tượng qua lớp kính — vẫn đủ để thấy nét mặt bình thản đến kinh ngạc.', '["Hoàn thành khoảng năm 774, cùng thời với Bulguksa.","Tượng Phật chính cao 3,5m, tạc từ granite.","Được UNESCO công nhận Di sản Thế giới năm 1995.","Hiện được ngăn bằng kính để kiểm soát độ ẩm."]', '["Có đường mòn đi bộ 3 km từ Bulguksa lên, mất khoảng một giờ.","Không được chụp ảnh bên trong hang.","Bình minh ở đây rất đẹp nhưng cổng mở theo giờ, kiểm tra trước."]', 'Tháng 4–5 và 10–11', '1,5 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '09:00–17:30', '["unesco"]', '["UNESCO","Silla","điêu khắc"]', '[{"seed":"seokguram","caption":"Đường lên hang đá Seokguram","ratio":"16/9"}]', '["bulguksa"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Seokguram Grotto","summary":"A granite Buddha in a man-made cave on a mountain top, facing straight out to the East Sea.","story":"In the 8th century Silla masons cut granite blocks, assembled them into a domed chamber on Mount Toham, and set inside it a Buddha three and a half metres tall. It faces east, and on the winter solstice the first light off the sea once struck it between the eyes. The jointing and natural ventilation were so refined that modern restoration upset the humidity balance and a glass screen had to be installed. You see the Buddha through that glass — still enough to register the astonishing calm of its face.","facts":["Completed around 774, at the same time as Bulguksa.","The main Buddha is 3.5m tall, carved from granite.","Inscribed by UNESCO in 1995.","It is now separated by glass to control humidity."],"travelTips":["A 3 km trail climbs from Bulguksa in about an hour.","Photography is not permitted inside the grotto.","Sunrise here is famous, but gate hours vary — check first."],"bestTime":"April–May and October–November","visitDuration":"1.5 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"09:00–17:30","galleryCaptions":["The approach to Seokguram"]},"ko":{"name":"석굴암","summary":"산정의 인공 석굴에 앉은 화강암 본존불. 동해를 정면으로 바라본다.","story":"8세기 신라의 석공들은 화강암을 잘라 토함산 위에 둥근 천장의 굴을 짜 올리고, 그 가운데 3.5m 높이의 본존불을 앉혔다. 불상은 동쪽을 향하고, 동짓날 바다에서 떠오른 첫 햇빛이 이마 한가운데를 비췄다고 한다. 돌을 짜맞춘 기술과 자연 환기 방식이 워낙 정교해, 근대의 보수가 오히려 습도 균형을 무너뜨려 유리벽을 설치해야 했다. 지금은 유리 너머로 보지만, 그 얼굴의 놀라운 평온함은 그대로 전해진다.","facts":["774년 무렵 불국사와 같은 시기에 완성되었다.","본존불은 화강암으로 조성되었으며 높이 3.5m다.","1995년 유네스코 세계유산에 등재되었다.","습도 관리를 위해 현재는 유리로 분리되어 있다."],"travelTips":["불국사에서 3km 산길을 한 시간쯤 걸어 오를 수 있다.","석굴 내부는 촬영이 금지된다.","일출 명소지만 개방 시간이 다르니 미리 확인하자."],"bestTime":"4~5월, 10~11월","visitDuration":"1시간 30분","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"09:00~17:30","galleryCaptions":["석굴암으로 오르는 길"]},"ja":{"name":"石窟庵","summary":"山頂の人工石窟に座る花崗岩の本尊。東海をまっすぐ望む。","story":"8世紀の新羅の石工は花崗岩を切り出し、吐含山の上に円蓋の窟を組み上げ、その中央に3.5mの本尊を据えた。仏は東を向き、冬至の日には海から昇る最初の光が額の中央を照らしたという。石の組み方と自然換気があまりに精緻で、近代の補修がかえって湿度の均衡を崩し、ガラス壁を設けざるを得なくなった。今はガラス越しに見るが、その表情の驚くべき静けさは変わらず伝わる。","facts":["774年頃、仏国寺と同時期に完成した。","本尊は花崗岩製で高さ3.5m。","1995年にユネスコ世界遺産に登録された。","湿度管理のため現在はガラスで隔てられている。"],"travelTips":["仏国寺から3kmの山道を約1時間で登れる。","石窟の内部は撮影禁止。","日の出の名所だが開門時間が異なるので事前確認を。"],"bestTime":"4〜5月、10〜11月","visitDuration":"1時間30分","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"09:00〜17:30","galleryCaptions":["石窟庵への参道"]},"zh":{"name":"石窟庵","summary":"山頂人工石窟中的花崗岩佛像，正面朝向東海。","story":"八世紀的新羅石匠切開花崗岩，在吐含山上拼組出一座圓頂石室，中央安置一尊三點五公尺高的佛像。佛面朝東，冬至那天，海上升起的第一道光曾正照在祂的眉心。石材的接合與自然通風極其精巧，以致近代的整修反而破壞了濕度平衡，不得不加裝玻璃。如今你隔著玻璃觀看——但那張面容驚人的平靜依然傳達得清清楚楚。","facts":["約於774年完成，與佛國寺同時期。","主尊以花崗岩雕成，高3.5公尺。","1995年列入世界遺產。","為控制濕度，現以玻璃隔開。"],"travelTips":["可自佛國寺沿3公里山徑步行約一小時上山。","石窟內部禁止攝影。","此地日出著名，但開門時間不同，請先確認。"],"bestTime":"4至5月、10至11月","visitDuration":"1.5小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"09:00–17:30","galleryCaptions":["通往石窟庵的參道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daereungwon', 'daereungwon', 'gyeongbuk', 'Khu lăng mộ Daereungwon', 'Daereungwon Tomb Complex', 'park', 129.21, 35.838, 'Hai mươi ba ngôi mộ vua Silla nổi lên giữa lòng thành phố như những quả đồi cỏ khổng lồ.', 'Gyeongju được gọi là ''bảo tàng không mái'', và Daereungwon là chương mở đầu: những gò đất tròn cao hàng chục mét, phủ cỏ xanh mượt, nằm ngay giữa phố. Một trong số đó — Cheonmachong, ''mộ ngựa trời'' — được khai quật và mở cho khách vào bên trong xem quan tài, vương miện vàng cùng bức tranh yên ngựa vẽ con ngựa trắng có cánh. Lúc hoàng hôn, bóng các gò mộ đổ dài trên cỏ và cả khu trở nên siêu thực.', '["Gồm 23 gò mộ lớn của tầng lớp quý tộc Silla.","Mộ Cheonmachong khai quật năm 1973, tìm được vương miện vàng và bức ''Thiên Mã đồ''.","Các mộ được đắp bằng đá và đất, cao tới hơn 20m.","Nằm trong quần thể di sản UNESCO Khu vực lịch sử Gyeongju."]', '["Đi bộ hoặc thuê xe đạp là cách hay nhất để đi hết Gyeongju.","Chiều muộn ánh sáng đẹp nhất cho ảnh các gò mộ.","Cạnh đó là hồ Donggung–Wolji, nên xem vào buổi tối khi lên đèn."]', 'Tháng 4 và 10–11', '1,5 giờ', '3.000 KRW', '09:00–22:00, vào cửa cuối 21:30', '["unesco","popular"]', '["Silla","khảo cổ","UNESCO"]', '[{"seed":"daereungwon","caption":"Gò mộ Silla giữa thành phố","ratio":"16/9"}]', '["cheomseongdae","bulguksa"]', 1, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=84258', '2026-08-04', '{"en":{"name":"Daereungwon Tomb Complex","summary":"Twenty-three Silla royal tombs rising out of the city like enormous grass hills.","story":"Gyeongju is called a museum without walls, and Daereungwon is its opening chapter: round earth mounds tens of metres high, covered in smooth green grass, sitting in the middle of the town. One of them — Cheonmachong, the ''heavenly horse tomb'' — was excavated and opened, and you can walk inside to see the coffin, the gold crown and the painted saddle flap showing a winged white horse. At sunset the mounds throw long shadows across the grass and the whole place turns unreal.","facts":["Twenty-three large burial mounds of the Silla aristocracy.","Cheonmachong, excavated in 1973, yielded a gold crown and the ''Heavenly Horse'' painting.","The mounds are built of stone and earth, some over 20m high.","Part of the UNESCO Gyeongju Historic Areas."],"travelTips":["Walking or cycling is the best way to see Gyeongju.","Late afternoon light is best for photographing the mounds.","Donggung Palace and Wolji Pond are next door and best seen after dark."],"bestTime":"April and October–November","visitDuration":"1.5 hours","ticket":"3,000 KRW","openingHours":"09:00–22:00, last entry 21:30","galleryCaptions":["Silla burial mounds in the city"]},"ko":{"name":"대릉원","summary":"도심 한가운데 거대한 잔디 언덕처럼 솟은 신라 왕릉 23기.","story":"경주를 지붕 없는 박물관이라 부르는데, 대릉원은 그 첫 장이다. 수십 미터 높이의 둥근 봉분이 매끈한 잔디를 덮고 시내 한복판에 앉아 있다. 그중 하나인 천마총은 발굴되어 내부가 공개되었다. 목관과 금관, 그리고 날개 달린 흰 말을 그린 장니 천마도를 볼 수 있다. 해질녘이면 봉분의 그림자가 잔디 위로 길게 늘어져 풍경이 비현실적으로 변한다.","facts":["신라 귀족의 대형 고분 23기가 모여 있다.","1973년 발굴된 천마총에서 금관과 ''천마도''가 나왔다.","봉분은 돌과 흙으로 쌓았고 높이가 20m를 넘는 것도 있다.","유네스코 경주역사유적지구에 포함된다."],"travelTips":["경주는 걷거나 자전거로 도는 것이 가장 좋다.","봉분 사진은 늦은 오후 빛이 가장 예쁘다.","바로 옆 동궁과 월지는 밤에 보는 것이 좋다."],"bestTime":"4월, 10~11월","visitDuration":"1시간 30분","ticket":"3,000원","openingHours":"09:00~22:00, 입장 마감 21:30","galleryCaptions":["도심 속 신라 고분"]},"ja":{"name":"大陵苑","summary":"街の真ん中に巨大な草の丘のように盛り上がる新羅の王陵23基。","story":"慶州は屋根のない博物館と呼ばれるが、大陵苑はその第一章だ。数十メートルの円い墳丘が滑らかな芝に覆われ、市街のただ中に座っている。そのひとつ天馬塚は発掘され内部が公開されていて、木棺と金冠、翼のある白馬を描いた障泥の天馬図を見ることができる。夕暮れには墳丘の影が芝に長く伸び、風景が現実離れしていく。","facts":["新羅貴族の大型古墳23基が集まる。","1973年発掘の天馬塚から金冠と「天馬図」が出土した。","墳丘は石と土で築かれ、高さ20mを超えるものもある。","ユネスコ慶州歴史遺跡地区に含まれる。"],"travelTips":["慶州は徒歩か自転車で回るのが一番。","墳丘の写真は午後遅くの光が最も美しい。","隣の東宮と月池は夜に見るのがよい。"],"bestTime":"4月、10〜11月","visitDuration":"1時間30分","ticket":"3,000ウォン","openingHours":"09:00〜22:00、最終入場21:30","galleryCaptions":["街なかの新羅古墳"]},"zh":{"name":"大陵苑","summary":"二十三座新羅王陵像巨大的草丘，隆起在城市之中。","story":"慶州被稱作沒有屋頂的博物館，大陵苑就是它的第一章：數十公尺高的圓形封土覆著平滑青草，就坐落在市街之間。其中的天馬塚已發掘並開放，可以走進去看棺木、金冠，以及畫著白色飛馬的障泥「天馬圖」。黃昏時分，墳丘的影子在草地上拉得很長，整片景象變得不真實。","facts":["二十三座新羅貴族大型古墳聚集於此。","1973年發掘的天馬塚出土金冠與「天馬圖」。","封土以石與土堆成，有的高逾20公尺。","屬世界遺產慶州歷史遺跡地區。"],"travelTips":["慶州最適合以步行或單車遊覽。","午後的光線最適合拍攝古墳。","隔壁的東宮與月池建議夜間參觀。"],"bestTime":"4月與10至11月","visitDuration":"1.5小時","ticket":"3,000韓元","openingHours":"09:00–22:00，最後入場21:30","galleryCaptions":["城中的新羅古墳"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheomseongdae', 'cheomseongdae', 'gyeongbuk', 'Đài thiên văn Cheomseongdae', 'Cheomseongdae Observatory', 'unesco', 129.219, 35.835, 'Đài quan sát thiên văn còn nguyên vẹn xưa nhất Đông Á, xây từ thế kỷ 7 bằng 362 viên đá.', 'Cao chín mét, hình cái chai, Cheomseongdae được nữ vương Seondeok cho dựng khoảng năm 634 để quan sát sao và định lịch nông vụ. Mọi con số trong công trình đều có ý: 362 viên đá tương ứng số ngày âm lịch, 12 tầng dưới và 12 tầng trên tương ứng 12 tháng, cửa sổ giữa thân chia đài thành hai nửa bằng nhau. Nó đứng cô độc giữa bãi cỏ, mùa hè viền hoa, và ban đêm được chiếu sáng — hình ảnh biểu tượng nhất của Gyeongju.', '["Xây khoảng năm 634 dưới triều nữ vương Seondeok.","Là đài thiên văn còn nguyên vẹn cổ nhất Đông Á.","Được ghép từ 362 viên đá granite, cao 9,17m.","Là Quốc bảo số 31 của Hàn Quốc."]', '["Đi buổi tối để thấy đài được chiếu sáng giữa bãi cỏ.","Tháng 9–10 có ruộng hoa nở ngay bên cạnh.","Kết hợp cùng Daereungwon và hồ Wolji trong một vòng đi bộ."]', 'Tháng 9–10', '45 phút', 'Miễn phí', '09:00–22:00, mở quanh năm; ban đêm có đèn chiếu nên đáng ghé lại sau khi trời tối', '["unesco"]', '["thiên văn","Silla","UNESCO"]', '[{"seed":"cheomseongdae","caption":"Đài Cheomseongdae giữa bãi cỏ","ratio":"16/9"}]', '["daereungwon"]', 0, 'https://www.gyeongju.go.kr/tour/page.do?mnu_uid=2378', '2026-08-05', '{"en":{"name":"Cheomseongdae Observatory","summary":"East Asia''s oldest surviving astronomical observatory, built in the 7th century from 362 stones.","story":"Nine metres tall and shaped like a bottle, Cheomseongdae was raised around 634 under Queen Seondeok to observe the stars and set the farming calendar. Every number in it means something: 362 stones for the days of the lunar year, twelve courses below and twelve above for the months, and a window that divides the tower into two equal halves. It stands alone on the grass, ringed by flowers in summer and floodlit at night — the single most recognisable image of Gyeongju.","facts":["Built around 634 under Queen Seondeok.","The oldest surviving astronomical observatory in East Asia.","Assembled from 362 granite stones and standing 9.17m tall.","National Treasure No. 31 of Korea."],"travelTips":["Come at night to see it lit on the open lawn.","Flower fields bloom beside it in September–October.","Combine it with Daereungwon and Wolji Pond in one walking loop."],"bestTime":"September–October","visitDuration":"45 minutes","ticket":"Free","openingHours":"09:00–22:00, open year-round; it is floodlit after dark and worth a second visit at night","galleryCaptions":["Cheomseongdae on its lawn"]},"ko":{"name":"첨성대","summary":"동아시아에서 가장 오래된 천문대. 7세기에 362개의 돌로 쌓았다.","story":"높이 9m, 병 모양의 첨성대는 634년 무렵 선덕여왕 때 별을 살피고 농사의 절기를 정하기 위해 세워졌다. 모든 숫자에 뜻이 있다. 362개의 돌은 음력 한 해의 날수, 아래위 각 12단은 열두 달, 몸통 가운데 창은 탑을 정확히 반으로 나눈다. 잔디밭 위에 홀로 서서 여름에는 꽃에 둘러싸이고 밤에는 조명을 받는다. 경주에서 가장 널리 알려진 장면이다.","facts":["634년 무렵 선덕여왕 때 세워졌다.","동아시아에 남은 가장 오래된 천문대다.","화강암 362개를 쌓아 높이 9.17m로 만들었다.","대한민국 국보 제31호다."],"travelTips":["밤에 가면 잔디밭 위 조명이 아름답다.","9~10월에는 옆에 꽃밭이 핀다.","대릉원, 월지와 묶어 도보로 한 바퀴 돌자."],"bestTime":"9~10월","visitDuration":"45분","ticket":"무료","openingHours":"09:00~22:00, 연중무휴. 밤에는 조명이 들어와 야간에 다시 볼 만하다","galleryCaptions":["잔디밭 위의 첨성대"]},"ja":{"name":"瞻星台","summary":"東アジア最古の現存天文台。7世紀に362個の石で築かれた。","story":"高さ9m、瓶の形をした瞻星台は634年頃、善徳女王のもとで星を観測し農事の暦を定めるために建てられた。すべての数字に意味がある。362個の石は太陰暦一年の日数、下段と上段の各12段は十二か月、胴の中ほどの窓は塔をちょうど二等分する。芝生の上に一基だけ立ち、夏は花に囲まれ、夜は照明を受ける。慶州で最も知られた一枚の風景だ。","facts":["634年頃、善徳女王の時代に建てられた。","東アジアに現存する最古の天文台。","花崗岩362個を積み、高さは9.17m。","大韓民国国宝第31号。"],"travelTips":["夜に行けば芝の上でライトアップされた姿が見られる。","9〜10月には隣に花畑が咲く。","大陵苑、月池と合わせて徒歩で一周しよう。"],"bestTime":"9〜10月","visitDuration":"45分","ticket":"無料","openingHours":"09:00〜22:00、年中無休。夜はライトアップされ、暗くなってから再訪する価値がある","galleryCaptions":["芝生の上の瞻星台"]},"zh":{"name":"瞻星台","summary":"東亞現存最古老的天文台，七世紀以362塊石頭砌成。","story":"高九公尺、形如瓶身的瞻星台，約建於634年善德女王時期，用以觀星並定農時。它的每個數字都有意義：362塊石頭對應陰曆一年的天數，上下各十二層對應十二個月，塔身中段的窗口把塔分成相等的兩半。它獨自立在草地上，夏天被花圍繞，夜裡打上燈光——這是慶州最具代表性的一個畫面。","facts":["約建於634年善德女王時期。","東亞現存最古老的天文台。","由362塊花崗岩砌成，高9.17公尺。","為大韓民國國寶第31號。"],"travelTips":["夜間前來，可看它在草地上被燈光照亮。","九至十月旁邊有花田盛開。","可與大陵苑、月池串成步行路線。"],"bestTime":"9至10月","visitDuration":"45分鐘","ticket":"免費","openingHours":"09:00–22:00，全年開放；入夜後有燈光照明，值得再看一次","galleryCaptions":["草地上的瞻星台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('anapji-donggung', 'anapji-donggung', 'gyeongbuk', 'Cung Donggung & ao Wolji (Anapji)', 'Donggung Palace & Wolji Pond', 'palace', 129.2265, 35.8345, 'Ao cung đình Silla đào từ thế kỷ thứ 7, ban đêm soi bóng ba toà điện xuống mặt nước phẳng lì.', 'Năm 674, vua Munmu cho đào một cái ao trong cung đông và đắp ba hòn đảo cùng mười hai ngọn giả sơn quanh nó. Bờ ao được cố ý làm uốn khúc để đứng ở bất cứ chỗ nào cũng không thấy hết toàn bộ mặt nước — một mẹo cổ khiến cái ao trông rộng hơn thực tế. Khi Silla sụp đổ, cung bỏ hoang và ao cạn dần; đến thập niên 1970 người ta nạo vét và vớt lên hơn ba vạn hiện vật, trong đó có một con xúc xắc gỗ mười bốn mặt ghi các hình phạt cho người thua trong tiệc rượu. Ba toà điện được phục dựng và chiếu sáng từ chập tối — đây là cảnh đêm được chụp nhiều nhất Gyeongju.', '["Ao được đào năm 674 dưới thời vua Munmu của Silla.","Đợt nạo vét thập niên 1970 vớt được hơn 30.000 hiện vật.","Trong số hiện vật có con xúc xắc gỗ 14 mặt dùng trong tiệc rượu cung đình.","Bờ ao uốn khúc có chủ ý để không nhìn thấy toàn bộ mặt nước từ một điểm."]', '["Đến sau khi trời tối hẳn — cảnh phản chiếu là lý do chính để tới đây.","Gió lặng thì mặt nước phẳng nhất; sau 21h bớt đông.","Vé vào rẻ và mở tới khuya, dễ ghép vào cuối ngày ở Gyeongju."]', 'Quanh năm; buổi tối', '1 giờ', '3.000 KRW', '09:00–22:00, vào cửa cuối 21:30', '["popular","verified"]', '["Silla","cung điện","về đêm","phản chiếu"]', '[{"seed":"anapji-donggung","caption":"Điện phản chiếu xuống ao Wolji","ratio":"16/9"}]', '["cheomseongdae","daereungwon"]', 1, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=84259', '2026-08-04', '{"en":{"name":"Donggung Palace & Wolji Pond","summary":"A Silla palace pond dug in the 7th century, three halls reflected at night in water like glass.","story":"In 674 King Munmu had a pond dug in the eastern palace, with three islands and twelve artificial hills around it. The banks were deliberately made to wind, so that from no single point can you see the whole surface — an old trick that makes the pond read as larger than it is. When Silla fell the palace was abandoned and the pond dried; a dredging in the 1970s recovered more than thirty thousand objects, among them a fourteen-sided wooden die inscribed with forfeits for losers at a drinking party. Three halls have been rebuilt and are lit from dusk — this is the most photographed night scene in Gyeongju.","facts":["The pond was dug in 674 under King Munmu of Silla.","A dredging in the 1970s recovered over 30,000 artefacts.","Among them was a 14-sided wooden die used at court drinking parties.","The banks wind deliberately so the whole surface is never visible at once."],"travelTips":["Come after full dark — the reflection is the whole point.","Still air gives the flattest water; after 9pm it thins out.","Cheap and open late, so it slots neatly into the end of a Gyeongju day."],"bestTime":"Year-round; evenings","visitDuration":"1 hour","ticket":"3,000 KRW","openingHours":"09:00–22:00, last entry 21:30","galleryCaptions":["The halls reflected in Wolji pond"]},"ko":{"name":"동궁과 월지(안압지)","summary":"7세기에 판 신라의 궁궐 연못. 밤이면 세 채의 전각이 유리 같은 물에 비친다.","story":"674년 문무왕은 동궁에 못을 파고 그 안에 섬 셋과 둘레에 열두 봉우리를 쌓았다. 물가는 일부러 굽이지게 만들어 어느 한 자리에서도 수면 전체가 보이지 않게 했다. 못을 실제보다 넓어 보이게 하는 옛 수법이다. 신라가 무너지자 궁은 버려지고 못은 말라 갔는데, 1970년대 준설에서 삼만 점이 넘는 유물이 나왔다. 그중에는 술자리에서 진 사람이 할 벌칙을 새긴 십사면 나무 주사위도 있었다. 전각 셋이 복원되어 해질 무렵부터 불이 들어온다. 경주에서 가장 많이 찍히는 밤 풍경이다.","facts":["못은 674년 신라 문무왕 때 조성되었다.","1970년대 준설로 3만 점이 넘는 유물이 나왔다.","그중에는 궁중 술자리에 쓰인 십사면 나무 주사위가 있다.","물가를 일부러 굽이지게 만들어 한 자리에서 수면 전체가 보이지 않는다."],"travelTips":["완전히 어두워진 뒤에 가자. 반영이 이곳의 전부다.","바람이 없어야 수면이 가장 잔잔하다. 9시 이후면 한산해진다.","입장료가 싸고 늦게까지 열어 경주 일정의 마지막에 넣기 좋다."],"bestTime":"연중, 저녁","visitDuration":"1시간","ticket":"3,000원","openingHours":"09:00~22:00, 입장 마감 21:30","galleryCaptions":["월지에 비친 전각"]},"ja":{"name":"東宮と月池（雁鴨池）","summary":"7世紀に掘られた新羅の宮の池。夜、三棟の殿舎がガラスのような水面に映る。","story":"674年、文武王は東宮に池を掘り、その中に三つの島と周囲に十二の築山を設けた。汀は意図的に入り組ませてあり、どの一点からも水面の全体は見えない。池を実際より広く見せる古い手法だ。新羅が滅ぶと宮は捨てられ池は涸れたが、1970年代の浚渫で三万点を超える遺物が上がった。その中には、酒宴で負けた者の罰を刻んだ十四面の木製サイコロもあった。三棟の殿舎が復元され、日暮れから灯が入る。慶州で最も撮られる夜の景色である。","facts":["池は674年、新羅の文武王のときに造られた。","1970年代の浚渫で3万点を超える遺物が出土した。","その中に宮中の酒宴で使われた十四面の木製サイコロがある。","汀を意図的に入り組ませ、一点から水面全体が見えないようにしている。"],"travelTips":["完全に暗くなってから行こう。映り込みがすべてだ。","無風のときが最も水面が平らになる。21時を過ぎると空いてくる。","入場料が安く遅くまで開いており、慶州の一日の締めに向く。"],"bestTime":"通年、夕方以降","visitDuration":"1時間","ticket":"3,000ウォン","openingHours":"09:00〜22:00、最終入場21:30","galleryCaptions":["月池に映る殿舎"]},"zh":{"name":"東宮與月池（雁鴨池）","summary":"七世紀開鑿的新羅宮苑池塘，入夜後三座殿閣倒映在如鏡的水面上。","story":"674年，文武王在東宮開池，池中築三島，周圍堆起十二座假山。池岸刻意做成曲折，因此站在任何一點都看不見整片水面——這是讓池子顯得比實際更大的古老手法。新羅覆亡後宮苑荒廢、池水漸涸；1970年代的清淤撈起三萬多件文物，其中包括一枚十四面的木骰，上頭刻著酒宴輸家要受的罰則。三座殿閣已重建，天一黑就打燈——這是慶州最常被拍下的夜景。","facts":["池塘開鑿於674年新羅文武王時期。","1970年代的清淤撈出逾三萬件文物。","其中有一枚宮廷酒宴用的十四面木骰。","池岸刻意曲折，使人無法從單一位置望見整片水面。"],"travelTips":["等天完全黑了再來——倒影就是這裡的全部。","無風時水面最平；九點過後人潮轉稀。","票價便宜又開到晚，很適合排在慶州行程的最後。"],"bestTime":"全年；夜間","visitDuration":"1小時","ticket":"3,000韓元","openingHours":"09:00–22:00，最後入場21:30","galleryCaptions":["倒映在月池中的殿閣"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gyeongju-national-museum', 'gyeongju-national-museum', 'gyeongbuk', 'Bảo tàng Quốc gia Gyeongju', 'Gyeongju National Museum', 'museum', 129.2275, 35.8305, 'Nơi cất giữ vương miện vàng Silla và quả chuông đồng lớn nhất Hàn Quốc, đúc để cầu siêu cho một vị vua.', 'Gyeongju là kinh đô Silla suốt gần một nghìn năm, và mọi thứ đào được từ các gò mộ quanh thành phố đều về đây. Phòng vàng trưng bày các vương miện Silla — vàng lá mỏng uốn thành hình cây và gạc hươu, treo lủng lẳng những phiến ngọc cong hình dấu phẩy — mỏng đến mức các nhà nghiên cứu tin chúng chỉ dùng để chôn cất chứ không đội được. Ngoài sân treo chuông Emille đúc năm 771, nặng gần mười chín tấn; truyền thuyết rùng rợn kể rằng phải hiến một đứa trẻ vào lò đồng thì chuông mới kêu, và tiếng ngân của nó nghe như đứa bé gọi mẹ. Chuông giờ không còn được gõ, chỉ phát lại bản ghi âm.', '["Trưng bày các vương miện vàng khai quật từ những gò mộ Silla ở Gyeongju.","Chuông Emille (Seongdeok Đại vương thần chung) đúc năm 771, nặng khoảng 18,9 tấn.","Là bảo tàng quốc gia lâu đời nhất Hàn Quốc, tiền thân lập từ năm 1913.","Vé vào khu trưng bày thường trực miễn phí."]', '["Bắt đầu từ phòng vàng rồi mới ra sân xem chuông.","Chuông không được gõ nữa; có bản ghi âm phát theo giờ.","Cách ao Wolji vài phút đi bộ, nên ghép chung buổi chiều tối."]', 'Quanh năm', '2 giờ', 'Miễn phí', '10:00–18:00; Chủ nhật và ngày lễ tới 19:00; mở đêm tới 21:00 vào thứ Bảy (tháng 3–12) và thứ Tư cuối tháng', '["verified"]', '["bảo tàng","Silla","vàng","chuông"]', '[{"seed":"gyeongju-national-museum","caption":"Vương miện vàng Silla","ratio":"16/9"}]', '["anapji-donggung","bulguksa"]', 0, 'https://gyeongju.museum.go.kr/kor/html/sub01/0101.html', '2026-08-04', '{"en":{"name":"Gyeongju National Museum","summary":"Home of the Silla gold crowns and of Korea''s largest bronze bell, cast for a dead king''s soul.","story":"Gyeongju was the Silla capital for nearly a thousand years, and everything dug from the mounds around the city ends up here. The gold room holds the Silla crowns — thin sheet gold bent into trees and antlers, hung with curved jade commas — so fragile that scholars believe they were made for burial rather than wearing. Outside hangs the Emille bell, cast in 771 and weighing close to nineteen tonnes; a grim legend says a child had to be given to the furnace before it would ring, and that its tone is the child calling for its mother. The bell is no longer struck; a recording is played instead.","facts":["It displays the gold crowns excavated from the Silla mounds at Gyeongju.","The Emille bell (Divine Bell of King Seongdeok) was cast in 771 and weighs about 18.9 tonnes.","It is Korea''s oldest national museum, with roots going back to 1913.","Entry to the permanent galleries is free."],"travelTips":["Start in the gold room, then go out to the bell.","The bell is no longer rung; a recording plays at set times.","It is minutes from Wolji pond, so pair them in one late afternoon."],"bestTime":"Year-round","visitDuration":"2 hours","ticket":"Free","openingHours":"10:00–18:00; to 19:00 on Sundays and holidays; late opening to 21:00 on Saturdays (March–December) and the last Wednesday of the month","galleryCaptions":["A Silla gold crown"]},"ko":{"name":"국립경주박물관","summary":"신라 금관과 한국에서 가장 큰 청동 종이 있는 곳. 종은 죽은 왕의 명복을 빌어 주조되었다.","story":"경주는 천 년 가까이 신라의 도읍이었고, 도시 주변 고분에서 나온 것은 모두 이곳으로 모인다. 금관실에는 신라의 금관들이 있다. 얇은 금판을 나무와 사슴뿔 모양으로 구부리고 굽은 옥을 매단 것으로, 너무 여려서 쓰기 위한 것이 아니라 껴묻기 위한 것이었다고 본다. 밖에는 771년에 주조된 성덕대왕신종이 걸려 있다. 무게는 19톤에 가깝다. 아이를 쇳물에 넣어야 소리가 났고 그 울림이 아이가 어미를 부르는 소리 같다는 무서운 전설이 따라다닌다. 지금은 종을 치지 않고 녹음을 튼다.","facts":["경주 신라 고분에서 출토된 금관들을 전시한다.","성덕대왕신종(에밀레종)은 771년 주조되었고 무게는 약 18.9톤이다.","1913년에 뿌리를 둔, 한국에서 가장 오래된 국립박물관이다.","상설전시 관람은 무료다."],"travelTips":["금관실부터 보고 밖으로 나가 종을 보자.","종은 더 이상 치지 않고 정해진 시간에 녹음을 튼다.","월지에서 몇 분 거리라 늦은 오후에 묶기 좋다."],"bestTime":"연중","visitDuration":"2시간","ticket":"무료","openingHours":"10:00~18:00, 일요일·공휴일은 19:00까지, 3~12월 토요일과 매월 마지막 수요일은 21:00까지 야간 연장","galleryCaptions":["신라 금관"]},"ja":{"name":"国立慶州博物館","summary":"新羅の金冠と、韓国最大の銅鐘がある。鐘は亡き王の冥福のために鋳られた。","story":"慶州は千年近く新羅の都であり、市中の古墳から出たものはすべてここへ集まる。金冠室には新羅の金冠がある。薄い金板を樹木や鹿角の形に曲げ、勾玉を吊るしたもので、被るためではなく副葬のために作られたと考えられるほど華奢だ。屋外には771年鋳造の聖徳大王神鐘が吊られている。重さは十九トン近い。子どもを鋳型に入れねば鳴らなかった、その響きは子が母を呼ぶ声だ、という陰惨な伝説がついて回る。いま鐘は撞かれず、録音が流される。","facts":["慶州の新羅古墳から出土した金冠を展示する。","聖徳大王神鐘（エミレの鐘）は771年鋳造、重さ約18.9トン。","1913年に起源をもつ、韓国で最も古い国立博物館である。","常設展示の観覧は無料。"],"travelTips":["まず金冠室を見て、それから外の鐘へ。","鐘はもう撞かれず、決まった時刻に録音が流れる。","月池から数分なので、夕方にまとめるとよい。"],"bestTime":"通年","visitDuration":"2時間","ticket":"無料","openingHours":"10:00〜18:00、日曜・祝日は19:00まで、3〜12月の土曜と毎月最終水曜は21:00まで夜間延長","galleryCaptions":["新羅の金冠"]},"zh":{"name":"國立慶州博物館","summary":"收藏新羅金冠與韓國最大銅鐘之處，那口鐘是為一位亡故君王的冥福而鑄。","story":"慶州當了近千年的新羅都城，城周古墳裡挖出的東西最後都進到這裡。金冠室陳列著新羅金冠——薄金片彎成樹木與鹿角的形狀，垂掛著曲玉——纖薄到學者相信它們是為陪葬而非配戴所製。館外懸著771年鑄成的聖德大王神鐘，重達近十九公噸；一則陰森的傳說稱，得把一名孩童投入熔爐鐘才會響，而那聲響就是孩子在喚母親。如今鐘已不再敲擊，改播錄音。","facts":["展出自慶州新羅古墳出土的金冠。","聖德大王神鐘（艾米萊鐘）鑄於771年，重約18.9公噸。","是韓國歷史最悠久的國立博物館，可追溯至1913年。","常設展區免費參觀。"],"travelTips":["先看金冠室，再走到戶外看鐘。","鐘已不再敲響，館方於固定時段播放錄音。","距月池僅數分鐘，適合安排在同一個傍晚。"],"bestTime":"全年","visitDuration":"2小時","ticket":"免費","openingHours":"10:00–18:00；週日與假日至19:00；3至12月週六與每月最後一個週三延長至21:00","galleryCaptions":["新羅金冠"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bunhwangsa-hwangnyongsa', 'bunhwangsa-hwangnyongsa', 'gyeongbuk', 'Tháp Bunhwangsa & nền chùa Hwangnyongsa', 'Bunhwangsa Pagoda & Hwangnyongsa Site', 'temple', 129.2345, 35.8455, 'Tháp gạch đá cổ nhất Hàn Quốc, đứng cạnh bãi đất trống từng là ngôi chùa lớn nhất Đông Á.', 'Hai công trình cạnh nhau kể cùng một câu chuyện theo hai cách. Tháp Bunhwangsa dựng năm 634 bằng đá andesite cắt thành viên như gạch — kỹ thuật học từ Trung Hoa — nay chỉ còn ba tầng trong số chín tầng ban đầu, bốn góc có sư tử đá canh. Cách đó vài trăm mét là Hwangnyongsa: một bãi cỏ mênh mông với những phiến đá kê chân cột xếp thành hàng. Nơi này từng có ngôi tháp gỗ chín tầng cao tám mươi mét, cao nhất Đông Á thời ấy, cho tới khi quân Mông Cổ đốt sạch năm 1238. Đứng giữa những phiến đá kê cột mà hình dung chiều cao ấy là trải nghiệm mạnh hơn nhiều so với xem một công trình còn nguyên.', '["Tháp Bunhwangsa dựng năm 634, là tháp đá còn lại cổ nhất Hàn Quốc.","Tháp ban đầu có chín tầng, nay chỉ còn ba.","Chùa Hwangnyongsa từng có tháp gỗ chín tầng cao khoảng 80m.","Hwangnyongsa bị quân Mông Cổ thiêu huỷ năm 1238, chỉ còn nền đá."]', '["Đi cả hai nơi cùng lúc — chúng chỉ cách nhau vài phút đi bộ.","Nền Hwangnyongsa không có bóng râm, tránh giữa trưa mùa hè.","Có trung tâm diễn giải với mô hình phục dựng tháp chín tầng gần đó."]', 'Tháng 4–6 và 9–11', '1,5 giờ', 'Miễn phí cả hai (phí di sản Bunhwangsa đã bỏ từ 5/2023)', '09:00–18:00', '["hidden-gem"]', '["Silla","tháp","khảo cổ","phế tích"]', '[{"seed":"bunhwangsa-hwangnyongsa","caption":"Tháp đá Bunhwangsa","ratio":"16/9"}]', '["cheomseongdae","anapji-donggung"]', 0, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Bunhwangsa Pagoda & Hwangnyongsa Site","summary":"Korea''s oldest stone pagoda, beside an empty field that was once East Asia''s largest temple.","story":"Two sites side by side tell the same story two ways. Bunhwangsa pagoda was built in 634 of andesite cut into brick-like blocks — a technique learned from China — and of its original nine storeys only three remain, with stone lions at the corners. A few hundred metres away is Hwangnyongsa: an enormous field of grass with stone column bases set out in rows. A nine-storey wooden pagoda eighty metres tall once stood here, the tallest in East Asia, until the Mongols burned it in 1238. Standing among the column bases and trying to picture that height affects you far more than an intact building would.","facts":["Bunhwangsa pagoda was built in 634 and is Korea''s oldest surviving stone pagoda.","It originally had nine storeys; three remain.","Hwangnyongsa temple once held a nine-storey wooden pagoda about 80m tall.","Hwangnyongsa was burned by the Mongols in 1238, leaving only the stone bases."],"travelTips":["Do both together — they are a few minutes'' walk apart.","The Hwangnyongsa field has no shade; avoid midday in summer.","There is an interpretation centre nearby with a model of the nine-storey pagoda."],"bestTime":"April–June and September–November","visitDuration":"1.5 hours","ticket":"Both free (Bunhwangsa''s heritage fee was abolished in May 2023)","openingHours":"09:00–18:00","galleryCaptions":["The Bunhwangsa stone pagoda"]},"ko":{"name":"분황사 모전석탑과 황룡사지","summary":"한국에서 가장 오래된 석탑, 그리고 한때 동아시아 최대의 절이었던 빈 터.","story":"나란히 있는 두 곳이 같은 이야기를 다른 방식으로 한다. 분황사탑은 634년 안산암을 벽돌처럼 잘라 쌓았다. 중국에서 배운 기법이고, 원래 아홉 층 가운데 세 층만 남았으며 네 귀퉁이에 돌사자가 앉아 있다. 몇백 미터 떨어진 곳이 황룡사지다. 드넓은 풀밭에 주춧돌이 줄지어 놓여 있다. 이곳에는 높이 80m의 구층목탑이 서 있었고 당시 동아시아에서 가장 높았는데, 1238년 몽골군이 불태웠다. 주춧돌 사이에 서서 그 높이를 그려 보는 일은, 온전히 남은 건물을 보는 것보다 훨씬 강하게 남는다.","facts":["분황사 모전석탑은 634년에 세워진, 한국에 남은 가장 오래된 석탑이다.","원래 아홉 층이었으나 지금은 세 층만 남았다.","황룡사에는 높이 약 80m의 구층목탑이 있었다.","황룡사는 1238년 몽골군에 소실되어 주춧돌만 남았다."],"travelTips":["두 곳을 함께 보자. 걸어서 몇 분 거리다.","황룡사지는 그늘이 없다. 여름 한낮은 피하자.","근처에 구층목탑 복원 모형을 갖춘 해설관이 있다."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5시간","ticket":"두 곳 모두 무료(분황사 문화재관람료는 2023년 5월 폐지)","openingHours":"09:00~18:00","galleryCaptions":["분황사 모전석탑"]},"ja":{"name":"芬皇寺模塼石塔と皇龍寺址","summary":"韓国最古の石塔と、かつて東アジア最大の寺だった空き地。","story":"並び立つ二つの場所が、同じ話を別のやり方で語る。芬皇寺塔は634年、安山岩を煉瓦のように切って積んだ。中国から学んだ技法で、もとの九層のうち三層が残り、四隅に石の獅子が座る。数百メートル離れた場所が皇龍寺址だ。広大な草地に礎石が列をなして並ぶ。ここには高さ八十メートルの九層木塔が立ち、当時の東アジアで最も高かったが、1238年にモンゴル軍が焼いた。礎石のあいだに立ってその高さを思い描くことは、無傷の建物を見るよりずっと強く残る。","facts":["芬皇寺模塼石塔は634年の造立で、韓国に残る最古の石塔である。","もとは九層だったが、現在は三層が残る。","皇龍寺にはかつて高さ約80mの九層木塔があった。","皇龍寺は1238年にモンゴル軍に焼かれ、礎石だけが残った。"],"travelTips":["二か所は徒歩数分。まとめて見よう。","皇龍寺址には日陰がない。夏の真昼は避けよう。","近くに九層木塔の復元模型を備えた解説館がある。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1.5時間","ticket":"どちらも無料（芬皇寺の文化財観覧料は2023年5月に廃止）","openingHours":"09:00〜18:00","galleryCaptions":["芬皇寺の模塼石塔"]},"zh":{"name":"芬皇寺模塼石塔與皇龍寺址","summary":"韓國現存最古老的石塔，緊鄰一片曾是東亞最大寺院的空地。","story":"兩處相鄰的遺址，用兩種方式說著同一個故事。芬皇寺塔建於634年，以安山岩切成磚狀砌成——這是從中國學來的作法——原本九層如今只剩三層，四角蹲著石獅。幾百公尺外是皇龍寺址：一大片草地上，柱礎成排排開。這裡曾立著一座高八十公尺的九層木塔，是當時東亞最高的建築，直到1238年被蒙古軍焚毀。站在柱礎之間試著想像那個高度，遠比看一棟完好的建築更震撼。","facts":["芬皇寺模塼石塔建於634年，是韓國現存最古老的石塔。","原有九層，現存三層。","皇龍寺曾有一座高約80公尺的九層木塔。","皇龍寺於1238年被蒙古軍焚毀，只餘石造柱礎。"],"travelTips":["兩處一起看，步行僅數分鐘。","皇龍寺址毫無遮蔭，夏天請避開正午。","附近設有解說館，展出九層木塔的復原模型。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5小時","ticket":"兩處皆免費（芬皇寺的文化財觀覽費已於2023年5月廢止）","openingHours":"09:00–18:00","galleryCaptions":["芬皇寺模塼石塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seomun-market', 'seomun-market', 'daegu', 'Chợ Seomun', 'Seomun Market', 'market', 128.576, 35.869, 'Chợ vải lâu đời nhất Daegu, tối đến biến thành một trong những chợ đêm ngon nhất Hàn Quốc.', 'Seomun đã họp từ thời Joseon, khởi đầu là chợ vải — Daegu vốn là kinh đô dệt may của Hàn Quốc. Ban ngày các dãy nhà chất đầy cuộn vải, chăn gối, đồ khô. Khi trời tối, hơn tám chục quầy ăn được dựng lên ở khu chợ đêm: bánh xèo hẹ, mì trộn cay kiểu Daegu, chả nướng, mực xào. Người Daegu ăn cay hơn phần còn lại của đất nước, và ở đây bạn sẽ thấy điều đó ngay từ miếng đầu tiên.', '["Là một trong ba chợ lớn nhất thời Joseon.","Chợ đêm mở từ khoảng 19h đến nửa đêm với hơn 80 quầy ăn.","Daegu nổi tiếng với món mì trộn cay jjolmyeon và bánh xèo hẹ.","Nằm ngay ga Seomun Market của tàu điện tuyến 3."]', '["Đi tối để trải nghiệm chợ đêm, ban ngày chủ yếu là hàng vải.","Mang tiền mặt, đa số quầy ăn không nhận thẻ.","Đồ ăn Daegu cay hơn Seoul — hỏi mức cay trước khi gọi."]', 'Quanh năm, buổi tối', '2 giờ', '', 'Chợ ngày 09:00–18:00 (tuỳ sạp); chợ đêm chỉ họp thứ Sáu và thứ Bảy 19:00–23:30, Chủ nhật 19:00–22:00', '["popular"]', '["chợ","ẩm thực","về đêm"]', '[{"seed":"seomun-market","caption":"Chợ đêm Seomun","ratio":"16/9"}]', '["kim-gwang-seok-street","apsan-park"]', 1, 'https://access.visitkorea.or.kr/ms/detail.do?cotId=9b79d379-def2-455d-a50d-95562aa702e9', '2026-08-05', '{"en":{"name":"Seomun Market","summary":"Daegu''s oldest cloth market, which becomes one of Korea''s best night markets after dark.","story":"Seomun has traded since the Joseon dynasty, beginning with cloth — Daegu was the textile capital of Korea. By day the halls are stacked with fabric rolls, bedding and dried goods. After dark more than eighty food stalls open as a night market: chive pancakes, Daegu-style spicy cold noodles, grilled skewers, stir-fried squid. People here eat spicier than the rest of the country, and you notice from the first bite.","facts":["One of the three great markets of the Joseon era.","The night market runs from about 7pm to midnight with 80+ food stalls.","Daegu is known for spicy jjolmyeon noodles and chive pancakes.","Right beside Seomun Market station on metro Line 3."],"travelTips":["Come in the evening for the night market; daytime is mostly fabric.","Bring cash — most food stalls don''t take cards.","Daegu food is spicier than Seoul''s; ask for the heat level before ordering."],"bestTime":"Year-round, evenings","visitDuration":"2 hours","ticket":"","openingHours":"Day market 09:00–18:00 (varies by stall); the night market runs only Friday and Saturday 19:00–23:30 and Sunday 19:00–22:00","galleryCaptions":["Seomun night market"]},"ko":{"name":"서문시장","summary":"대구에서 가장 오래된 포목시장. 밤이면 전국 손꼽히는 야시장이 된다.","story":"서문시장은 조선시대부터 열렸고 시작은 포목이었다. 대구는 한국 섬유산업의 중심이었다. 낮에는 원단과 이불, 건어물이 가득한 상가지만, 해가 지면 여든 곳이 넘는 먹거리 노점이 야시장으로 문을 연다. 부추전, 대구식 매운 쫄면, 꼬치구이, 오징어볶음. 이곳 사람들은 전국에서 가장 맵게 먹고, 그것은 첫 입에 바로 알 수 있다.","facts":["조선시대 3대 시장 가운데 하나였다.","야시장은 저녁 7시부터 자정까지, 80개가 넘는 먹거리 노점이 선다.","대구는 매운 쫄면과 부추전으로 유명하다.","도시철도 3호선 서문시장역 바로 앞이다."],"travelTips":["야시장을 보려면 저녁에 가자. 낮에는 주로 원단 상가다.","노점 대부분이 카드를 받지 않으니 현금을 챙기자.","대구 음식은 서울보다 맵다. 주문 전 매운 정도를 물어보자."],"bestTime":"연중, 저녁 시간","visitDuration":"2시간","ticket":"","openingHours":"낮 시장은 09:00~18:00(점포마다 다름), 야시장은 금·토 19:00~23:30, 일요일 19:00~22:00에만 열린다","galleryCaptions":["서문시장 야시장"]},"ja":{"name":"西門市場","summary":"大邱で最も古い織物市場。夜は韓国屈指の夜市になる。","story":"西門市場は朝鮮時代から立ち、始まりは織物だった。大邱は韓国の繊維の中心だったのだ。昼は生地や寝具、乾物が積み上がる商店街だが、日が落ちると八十を超える屋台が夜市として開く。ニラチヂミ、大邱式の辛いチョルミョン、串焼き、イカ炒め。ここの人は全国で最も辛く食べる。それは一口目で分かる。","facts":["朝鮮時代の三大市場のひとつだった。","夜市は19時から24時まで、80を超える屋台が並ぶ。","大邱は辛いチョルミョンとニラチヂミで有名。","都市鉄道3号線の西門市場駅前。"],"travelTips":["夜市を見るなら夕方に。昼は主に生地の商店街だ。","屋台の多くはカード不可なので現金を。","大邱の料理はソウルより辛い。注文前に辛さを聞こう。"],"bestTime":"通年、夕方","visitDuration":"2時間","ticket":"","openingHours":"昼の市場は09:00〜18:00（店により異なる）、夜市は金・土19:00〜23:30、日曜19:00〜22:00のみ","galleryCaptions":["西門市場の夜市"]},"zh":{"name":"西門市場","summary":"大邱最古老的布市，入夜後化為韓國數一數二的夜市。","story":"西門市場自朝鮮時代便已開市，最初賣的是布——大邱曾是韓國的紡織中心。白天，商場裡堆滿布疋、寢具與乾貨；天黑後，八十多個小吃攤位化身夜市：韭菜煎餅、大邱式辣拌麵、烤串、炒魷魚。這裡的人吃得比全國都辣，第一口就知道。","facts":["曾是朝鮮時代三大市場之一。","夜市自晚上七點營業到午夜，有八十多個小吃攤。","大邱以辣拌麵與韭菜煎餅聞名。","就在都市鐵道3號線西門市場站旁。"],"travelTips":["想逛夜市請傍晚前來，白天主要是布市。","多數攤位不收卡，請帶現金。","大邱料理比首爾辣，點餐前先問辣度。"],"bestTime":"全年，傍晚時段","visitDuration":"2小時","ticket":"","openingHours":"日市09:00–18:00（各攤不一）；夜市僅週五、週六19:00–23:30與週日19:00–22:00營業","galleryCaptions":["西門夜市"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('palgongsan-gatbawi', 'palgongsan-gatbawi', 'daegu', 'Núi Palgongsan & tượng Phật Gatbawi', 'Palgongsan & Gatbawi Buddha', 'mountain', 128.696, 35.993, 'Tượng Phật đá đội mũ đá trên đỉnh núi, nơi người ta tin mỗi người được cầu một điều.', 'Leo hơn một nghìn bậc đá lên đỉnh Gwanbong, bạn gặp một tượng Phật tạc từ thế kỷ 9, trên đầu là phiến đá phẳng trông như chiếc mũ gat của học sĩ Joseon. Truyền thuyết bảo Gatbawi ban cho mỗi người đúng một điều ước, nên vào mùa thi cử, cả sườn núi kín phụ huynh quỳ lạy. Từ trên đó nhìn xuống là toàn cảnh Daegu và dãy Palgongsan trải dài — mùa thu, cả dãy chuyển đỏ và đường cáp treo phía tây núi luôn kín chỗ.', '["Tượng Phật Gatbawi tạc vào thế kỷ 9, cao khoảng 4m.","Đường lên có hơn 1.000 bậc đá.","Palgongsan trở thành vườn quốc gia thứ 23 của Hàn Quốc năm 2023.","Chùa Donghwasa dưới chân núi được dựng từ năm 493."]', '["Mùa thi cử (tháng 11) rất đông người tới cầu nguyện.","Mang nước; đoạn bậc thang cuối khá dốc.","Nếu ngại leo, đi cáp treo phía Donghwasa để ngắm núi."]', 'Tháng 10–11 (lá đỏ)', 'Nửa ngày', '', 'Cả ngày', '["verified"]', '["núi","Phật giáo","leo núi"]', '[{"seed":"palgongsan-gatbawi","caption":"Tượng Phật Gatbawi trên đỉnh núi","ratio":"16/9"}]', '["seomun-market"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Palgongsan & the Gatbawi Buddha","summary":"A stone Buddha wearing a stone hat on a mountain top, said to grant each visitor one wish.","story":"Climb more than a thousand stone steps to Gwanbong peak and you meet a Buddha carved in the 9th century, with a flat slab on its head that looks like the gat hat of a Joseon scholar. Legend says Gatbawi grants each person exactly one wish, so during exam season the slope fills with praying parents. From up there the whole of Daegu lies below with the Palgongsan range running away behind — in autumn the range turns red and the cable car on the western side is always full.","facts":["The Gatbawi Buddha was carved in the 9th century and stands about 4m tall.","The path up has more than 1,000 stone steps.","Palgongsan became Korea''s 23rd national park in 2023.","Donghwasa temple at its foot was founded in 493."],"travelTips":["Exam season in November brings crowds of praying families.","Carry water; the final stairway is steep.","If you''d rather not climb, take the cable car on the Donghwasa side."],"bestTime":"October–November (autumn colour)","visitDuration":"Half a day","ticket":"","openingHours":"Open all day","galleryCaptions":["The Gatbawi Buddha on the summit"]},"ko":{"name":"팔공산 갓바위","summary":"갓을 쓴 산정의 석불. 한 사람에게 한 가지 소원을 들어준다고 전한다.","story":"천 개가 넘는 돌계단을 올라 관봉에 닿으면 9세기에 새긴 석불을 만난다. 머리에 얹힌 판판한 돌이 조선 선비의 갓처럼 보인다. 갓바위는 한 사람에게 꼭 한 가지 소원을 들어준다고 전해져, 수능철이면 산비탈이 기도하는 부모들로 가득 찬다. 그 위에서 내려다보면 대구 시내와 길게 뻗은 팔공산 능선이 펼쳐진다. 가을이면 산줄기 전체가 붉게 물들고 서쪽 케이블카는 늘 만원이다.","facts":["갓바위 석불은 9세기에 조성되었으며 높이는 약 4m다.","오르는 길에 1,000개가 넘는 돌계단이 있다.","팔공산은 2023년 한국의 23번째 국립공원이 되었다.","산 아래 동화사는 493년에 창건되었다."],"travelTips":["11월 수능철에는 기도객으로 매우 붐빈다.","마지막 계단 구간이 가파르니 물을 챙기자.","오르기 부담스럽다면 동화사 쪽 케이블카를 이용하자."],"bestTime":"10~11월(단풍)","visitDuration":"반나절","ticket":"","openingHours":"상시 개방","galleryCaptions":["산정의 갓바위 석불"]},"ja":{"name":"八公山 冠岩薬師如来（カッパウィ）","summary":"笠をかぶった山頂の石仏。一人に一つだけ願いを叶えるという。","story":"千段を超える石段を登って冠峰に着くと、9世紀に刻まれた石仏に出会う。頭に載る平らな石が、朝鮮の学者がかぶる笠のように見える。カッパウィは一人にきっかり一つの願いを叶えると伝わり、大学入試の季節には斜面が祈る親たちで埋まる。そこから見下ろせば大邱の街と長く伸びる八公山の稜線。秋には山並み全体が赤く染まり、西側のケーブルカーはいつも満員だ。","facts":["カッパウィ石仏は9世紀の造立で高さ約4m。","参道には1,000段を超える石段がある。","八公山は2023年、韓国23番目の国立公園になった。","麓の桐華寺は493年の創建。"],"travelTips":["11月の入試の時期は祈願者で非常に混む。","最後の階段が急なので水を持とう。","登るのが大変なら桐華寺側のケーブルカーを。"],"bestTime":"10〜11月（紅葉）","visitDuration":"半日","ticket":"","openingHours":"終日開放","galleryCaptions":["山頂のカッパウィ石仏"]},"zh":{"name":"八公山冠岩藥師如來（笠石佛）","summary":"山頂戴著石笠的佛像，傳說每人可求一願。","story":"爬上一千多級石階抵達冠峰，會遇見一尊九世紀雕成的石佛，頭頂一塊平石，看來就像朝鮮士人戴的笠帽。傳說笠石佛只為每個人實現一個願望，因此入學考季節，整片山坡跪滿祈禱的父母。從那裡往下望，是大邱市區與綿延的八公山稜線。秋天整片山脈轉紅，山西側的纜車總是滿座。","facts":["笠石佛雕於九世紀，高約4公尺。","登山道有一千多級石階。","八公山於2023年成為韓國第23座國立公園。","山腳的桐華寺建於493年。"],"travelTips":["十一月大考期間，祈願人潮眾多。","最後一段階梯很陡，記得帶水。","不想爬山可搭桐華寺一側的纜車。"],"bestTime":"10至11月（紅葉）","visitDuration":"半天","ticket":"","openingHours":"全日開放","galleryCaptions":["山頂的笠石佛"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('kim-gwang-seok-street', 'kim-gwang-seok-street', 'daegu', 'Phố Kim Gwang-seok', 'Kim Gwang-seok Street', 'city', 128.607, 35.862, 'Con hẻm dài 350 mét tưởng niệm người nhạc sĩ hát về nỗi buồn của cả một thế hệ.', 'Kim Gwang-seok mất năm 1996 khi mới 31 tuổi, để lại những bài hát mà người Hàn Quốc vẫn hát khi buồn. Tại con hẻm nơi ông lớn lên ở Daegu, tường được phủ tranh vẽ chân dung, lời bài hát, và loa nhỏ phát nhạc ông suốt ngày. Có tượng ông ngồi ôm đàn để khách ngồi cạnh chụp ảnh, có sân khấu nhỏ nơi nhạc sĩ trẻ hát live vào cuối tuần. Đây là loại điểm đến mà nếu bạn hiểu tiếng Hàn, sẽ đứng rất lâu.', '["Con hẻm dài khoảng 350m ở khu Bangcheon, Daegu.","Kim Gwang-seok (1964–1996) là biểu tượng của dòng nhạc folk Hàn Quốc.","Có sân khấu ngoài trời với biểu diễn cuối tuần.","Ngay cạnh là chợ Bangcheon với các quán ăn lâu đời."]', '["Đi cuối tuần để xem biểu diễn ngoài trời.","Kết hợp với chợ Bangcheon để ăn tối.","Ban đêm hẻm lên đèn, chụp ảnh đẹp hơn ban ngày."]', 'Quanh năm', '1 giờ', '', 'Cả ngày', '["hidden-gem"]', '["âm nhạc","tranh tường","đi bộ"]', '[{"seed":"kim-gwang-seok-street","caption":"Tranh tường trên phố Kim Gwang-seok","ratio":"16/9"}]', '["seomun-market"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Kim Kwang-seok Street","summary":"A 350-metre alley honouring the singer who put a generation''s sadness into song.","story":"Kim Kwang-seok died in 1996 at the age of thirty-one, leaving songs Koreans still sing when they are sad. In the alley where he grew up in Daegu, the walls carry his portraits and lyrics, and small speakers play his music all day. There is a statue of him seated with his guitar for photographs, and a small stage where young musicians play live at weekends. It is the kind of place where, if you understand Korean, you will stand for a long time.","facts":["The alley runs about 350m in Daegu''s Bangcheon district.","Kim Kwang-seok (1964–1996) was an icon of Korean folk music.","There is an open-air stage with weekend performances.","Bangcheon Market, with its long-established eateries, is next door."],"travelTips":["Come at the weekend for the outdoor performances.","Have dinner at Bangcheon Market next door.","The alley is lit at night and photographs better than by day."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"","openingHours":"All day","galleryCaptions":["Murals along Kim Kwang-seok Street"]},"ko":{"name":"김광석다시그리기길","summary":"한 세대의 슬픔을 노래한 가수를 기리는 350m의 골목.","story":"김광석은 1996년 서른한 살에 세상을 떠나며, 한국 사람들이 슬플 때 여전히 부르는 노래들을 남겼다. 그가 자란 대구의 골목에는 그의 초상과 노랫말이 벽마다 그려져 있고 작은 스피커에서 하루 종일 그의 노래가 흐른다. 기타를 안고 앉은 동상 옆에서 사진을 찍고, 주말이면 작은 무대에서 젊은 음악가들이 라이브를 한다. 한국어를 아는 사람이라면 아주 오래 서 있게 되는 곳이다.","facts":["대구 방천시장 옆으로 약 350m 이어지는 골목이다.","김광석(1964~1996)은 한국 포크음악의 상징이다.","야외무대에서 주말 공연이 열린다.","오래된 식당이 많은 방천시장이 바로 옆이다."],"travelTips":["주말에 가면 야외 공연을 볼 수 있다.","저녁은 옆 방천시장에서 해결하자.","밤에 조명이 켜지면 낮보다 사진이 좋다."],"bestTime":"연중","visitDuration":"1시간","ticket":"","openingHours":"상시","galleryCaptions":["김광석길의 벽화"]},"ja":{"name":"キム・グァンソク通り","summary":"ひと世代の悲しみを歌った歌手を記念する350mの路地。","story":"キム・グァンソクは1996年、三十一歳で世を去り、韓国の人が今も悲しいときに歌う歌を残した。彼が育った大邱の路地には肖像と歌詞が壁ごとに描かれ、小さなスピーカーから一日中その歌が流れる。ギターを抱えて座る像の横で写真を撮り、週末には小さな舞台で若い音楽家がライブをする。韓国語が分かる人なら、とても長く立ち止まってしまう場所だ。","facts":["大邱・防川市場の脇に約350m続く路地。","キム・グァンソク（1964〜1996）は韓国フォークの象徴。","野外ステージで週末に公演が行われる。","老舗の食堂が多い防川市場が隣接する。"],"travelTips":["週末に行けば野外公演が見られる。","夕食は隣の防川市場で。","夜は照明が入り、昼より写真映えする。"],"bestTime":"通年","visitDuration":"1時間","ticket":"","openingHours":"終日","galleryCaptions":["キム・グァンソク通りの壁画"]},"zh":{"name":"金光石路","summary":"紀念那位唱出一個世代悲傷的歌手的350公尺巷弄。","story":"金光石於1996年去世，年僅三十一歲，留下的歌至今仍是韓國人難過時會唱的。在他成長的大邱巷子裡，牆上畫滿他的肖像與歌詞，小喇叭整天播著他的音樂。有他抱著吉他而坐的雕像供人合影，週末小舞台上有年輕音樂人現場演出。如果你懂韓語，會在這裡站上很久。","facts":["位於大邱防川市場旁，巷弄長約350公尺。","金光石（1964–1996）是韓國民謠的象徵人物。","戶外舞台週末有演出。","隔壁是有許多老店的防川市場。"],"travelTips":["週末前來可看到戶外表演。","晚餐就在隔壁的防川市場解決。","夜裡打燈後比白天更適合拍照。"],"bestTime":"全年","visitDuration":"1小時","ticket":"","openingHours":"全日","galleryCaptions":["金光石路上的壁畫"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('apsan-park', 'apsan-park', 'daegu', 'Công viên Apsan', 'Apsan Park', 'park', 128.575, 35.814, 'Ngọn núi ngay phía nam thành phố, có cáp treo lên đài quan sát nhìn trọn Daegu.', 'Apsan nghĩa đơn giản là ''núi phía trước'' — ngọn núi mà người Daegu nào cũng thấy từ cửa sổ nhà mình. Cáp treo đưa bạn lên gần đỉnh trong bảy phút, và từ đài quan sát cả lòng chảo Daegu hiện ra, được bao bởi vòng núi. Trong công viên có bảo tàng chiến tranh Nakdonggang tưởng niệm phòng tuyến cuối cùng năm 1950, cùng nhiều đường mòn đi bộ ngắn thích hợp buổi chiều.', '["Cáp treo Apsan dài khoảng 790m, đưa khách lên độ cao 660m.","Trong công viên có Bảo tàng Chiến tranh phòng tuyến Nakdonggang.","Daegu nằm trong lòng chảo nên nhìn từ đây thấy trọn thành phố.","Có nhiều đường mòn đi bộ ngắn dưới 2 giờ."]', '["Lên lúc hoàng hôn để xem thành phố chuyển đèn.","Cáp treo có thể ngừng khi gió lớn.","Mùa hè Daegu rất nóng — đi buổi chiều muộn."]', 'Tháng 4–6 và 9–11', '2 giờ', 'Cáp treo khứ hồi 14.000 KRW (một chiều 10.000); công viên miễn phí', '10:30–18:00 (cáp treo)', '[]', '["toàn cảnh","cáp treo","công viên"]', '[{"seed":"apsan-park","caption":"Daegu nhìn từ đài quan sát Apsan","ratio":"16/9"}]', '["seomun-market"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=68080', '2026-08-04', '{"en":{"name":"Apsan Park","summary":"The mountain on the city''s southern edge, with a cable car to a viewpoint over all of Daegu.","story":"Apsan simply means ''the mountain in front'' — the one every Daegu resident sees from their window. The cable car lifts you close to the summit in seven minutes, and from the observation deck the entire Daegu basin appears, ringed by mountains. The park also holds the Nakdonggang Victory War Memorial, remembering the last defensive line of 1950, along with plenty of short trails that suit an afternoon.","facts":["The Apsan cable car runs about 790m to a height of 660m.","The park contains the Nakdonggang Victory War Memorial.","Daegu sits in a basin, so the view from here takes in the whole city.","Several walking trails run under two hours."],"travelTips":["Go up at sunset to watch the city lights come on.","The cable car stops running in high wind.","Daegu summers are very hot — go late in the afternoon."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"Cable car 14,000 KRW return (10,000 one way); the park itself is free","openingHours":"10:30–18:00 (cable car)","galleryCaptions":["Daegu from the Apsan observatory"]},"ko":{"name":"앞산공원","summary":"도시 남쪽의 산. 케이블카를 타면 대구 전경이 한눈에 들어온다.","story":"앞산은 말 그대로 ''앞에 있는 산''이다. 대구 사람이라면 누구나 창밖으로 보는 산이다. 케이블카를 타면 7분 만에 정상 가까이 닿고, 전망대에서는 산으로 둘러싸인 대구 분지 전체가 보인다. 공원 안에는 1950년 마지막 방어선을 기리는 낙동강승전기념관이 있고, 오후에 걷기 좋은 짧은 산책로가 여럿이다.","facts":["앞산 케이블카는 길이 약 790m, 해발 660m까지 오른다.","공원 안에 낙동강승전기념관이 있다.","대구는 분지라 이곳에서 도시 전체가 보인다.","두 시간 이내의 짧은 산책로가 여럿 있다."],"travelTips":["해질녘에 오르면 도시에 불이 켜지는 모습을 볼 수 있다.","바람이 강하면 케이블카 운행이 중단된다.","대구의 여름은 매우 더우니 늦은 오후에 가자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"케이블카 왕복 14,000원(편도 10,000원), 공원은 무료","openingHours":"10:30~18:00(케이블카)","galleryCaptions":["앞산전망대에서 본 대구"]},"ja":{"name":"前山公園","summary":"街の南の山。ケーブルカーで登れば大邱の全景が見渡せる。","story":"前山は文字どおり「前にある山」で、大邱の人なら誰もが窓から見る山だ。ケーブルカーに乗れば七分で山頂近くに着き、展望台からは山に囲まれた大邱盆地の全体が見える。公園内には1950年の最終防衛線を記念する洛東江勝戦記念館があり、午後の散歩に向く短い遊歩道もいくつもある。","facts":["前山ケーブルカーは全長約790m、標高660mまで登る。","公園内に洛東江勝戦記念館がある。","大邱は盆地なのでここから街全体が見える。","二時間以内の短い散策路が複数ある。"],"travelTips":["夕暮れに登れば街に灯りがともるのが見える。","風が強いとケーブルカーは運休する。","大邱の夏はとても暑い。午後遅くに行こう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"ケーブルカー往復14,000ウォン（片道10,000）、公園は無料","openingHours":"10:30〜18:00（ケーブルカー）","galleryCaptions":["前山展望台から見た大邱"]},"zh":{"name":"前山公園","summary":"城南邊的山，搭纜車上觀景台可俯瞰整個大邱。","story":"前山字面意思就是「前面的山」——每個大邱人從窗口都看得見的那座。纜車七分鐘就把你送到接近山頂處，從觀景台望去，被群山環抱的大邱盆地盡收眼底。園內還有紀念1950年最後防線的洛東江勝戰紀念館，以及多條適合午後散步的短程步道。","facts":["前山纜車長約790公尺，上抵海拔660公尺。","園內設有洛東江勝戰紀念館。","大邱位於盆地，因此從這裡能看見整座城市。","有多條兩小時以內的健行步道。"],"travelTips":["黃昏上山，可看城市燈火次第點亮。","強風時纜車會停駛。","大邱夏天很熱，建議傍晚前往。"],"bestTime":"4至6月、9至11月","visitDuration":"2小時","ticket":"纜車來回14,000韓元（單程10,000）；公園本身免費","openingHours":"10:30–18:00（纜車）","galleryCaptions":["自前山觀景台俯瞰大邱"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daegu-yangnyeongsi', 'daegu-yangnyeongsi', 'daegu', 'Chợ thuốc bắc Yangnyeongsi', 'Yangnyeongsi Herbal Medicine Market', 'market', 128.5905, 35.8665, 'Con phố thuốc bắc mở từ năm 1658, nơi cả khu phố thơm mùi rễ cây phơi khô.', 'Năm 1658, triều đình Joseon lập ở Daegu một chợ thu mua dược liệu cho cả nước, mỗi năm họp hai kỳ vào mùa xuân và mùa thu. Ba trăm năm mươi năm sau nó vẫn ở đúng chỗ ấy: chừng hơn trăm hiệu thuốc bắc và phòng chẩn trị đông y nằm dọc một con phố, và thứ đầu tiên bạn nhận ra là mùi — rễ cam thảo, quế, nhân sâm phơi khô trộn lại thành một thứ mùi ngọt và hăng đặc trưng, ngửi thấy từ đầu phố. Bảo tàng y học cổ truyền ở giữa phố cho khách bắt mạch thử và pha một thang trà thuốc theo thể trạng. Đây là lý do Daegu tự nhận là thủ phủ đông y của Hàn Quốc.', '["Được lập năm 1658 dưới triều Joseon, là chợ dược liệu lâu đời nhất Hàn Quốc.","Ban đầu chỉ họp hai kỳ mỗi năm, vào mùa xuân và mùa thu.","Hiện có hơn 100 hiệu thuốc và phòng chẩn trị đông y trên phố.","Lễ hội Yangnyeongsi tổ chức vào tháng 5 hằng năm."]', '["Vào bảo tàng y học cổ truyền để bắt mạch và thử trà thuốc.","Nhiều hiệu đóng cửa Chủ nhật; đi ngày thường chắc ăn hơn.","Cách chợ Seomun vài phút đi bộ, nên ghép chung."]', 'Quanh năm; tháng 5 có lễ hội', '1,5 giờ', 'Bảo tàng vào cửa miễn phí', 'Chợ thuốc mở ban ngày; bảo tàng 09:00–18:00, vào cửa cuối 17:30, đóng cửa thứ Hai, 1/1 và ngày Tết, Chuseok', '["hidden-gem","verified"]', '["thuốc bắc","chợ","đông y","lịch sử"]', '[{"seed":"daegu-yangnyeongsi","caption":"Dược liệu phơi trước hiệu thuốc","ratio":"16/9"}]', '["seomun-market","daegu-modern-alley"]', 0, 'https://www.daegu.go.kr/dgom/index.do', '2026-08-05', '{"en":{"name":"Yangnyeongsi Herbal Medicine Market","summary":"A herbal medicine street trading since 1658, where the whole quarter smells of drying roots.","story":"In 1658 the Joseon court set up a market in Daegu to buy medicinal herbs for the whole country, meeting twice a year in spring and autumn. Three hundred and fifty years later it is still in the same place: a hundred-odd herb shops and oriental clinics along one street, and the first thing you notice is the smell — liquorice root, cinnamon and dried ginseng combining into something sweet and sharp that reaches you from the end of the block. The traditional medicine museum halfway along will take your pulse and blend you a tea to match. This is why Daegu calls itself Korea''s capital of oriental medicine.","facts":["Established in 1658 under Joseon, the oldest herbal medicine market in Korea.","It originally met only twice a year, in spring and autumn.","Over 100 herb shops and oriental clinics operate on the street today.","The Yangnyeongsi festival is held each May."],"travelTips":["Go into the traditional medicine museum for a pulse reading and a herbal tea.","Many shops close on Sundays; a weekday is safer.","It is minutes from Seomun market, so pair the two."],"bestTime":"Year-round; the festival is in May","visitDuration":"1.5 hours","ticket":"The museum is free","openingHours":"The medicine market runs by day; the museum is 09:00–18:00, last entry 17:30, closed Mondays, 1 January, Seollal and Chuseok","galleryCaptions":["Herbs drying outside a shop"]},"ko":{"name":"대구 약령시","summary":"1658년부터 이어진 한약 거리. 골목 전체에서 말린 약재 냄새가 난다.","story":"1658년 조선 조정은 나라 전체가 쓸 약재를 사들이기 위해 대구에 시장을 열었고, 해마다 봄과 가을 두 차례 섰다. 삼백오십 년이 지난 지금도 자리는 그대로다. 한 거리에 백 곳이 넘는 한약방과 한의원이 늘어서 있고, 가장 먼저 알아차리게 되는 것은 냄새다. 감초 뿌리와 계피, 말린 인삼이 섞여 달고도 알싸한 냄새가 골목 어귀에서부터 밀려온다. 거리 중간의 한의약박물관에서는 맥을 짚어 주고 체질에 맞는 한방차를 내어 준다. 대구가 스스로를 한방의 도시라 부르는 이유다.","facts":["1658년 조선 때 개설된, 한국에서 가장 오래된 약령시다.","처음에는 봄과 가을, 한 해 두 차례만 열렸다.","지금은 거리에 100곳이 넘는 한약방과 한의원이 있다.","약령시 축제가 해마다 5월에 열린다."],"travelTips":["한의약박물관에서 맥진과 한방차를 체험해 보자.","일요일에 쉬는 가게가 많다. 평일이 안전하다.","서문시장에서 몇 분 거리라 함께 묶기 좋다."],"bestTime":"연중, 축제는 5월","visitDuration":"1.5시간","ticket":"박물관 관람 무료","openingHours":"약령시는 낮에 열리고, 박물관은 09:00~18:00(입장 마감 17:30), 월요일과 1월 1일·설날·추석 당일 휴관","galleryCaptions":["한약방 앞에 널린 약재"]},"ja":{"name":"大邱薬令市","summary":"1658年から続く漢方薬の通り。街区じゅうが干した薬草の匂いに満ちる。","story":"1658年、朝鮮の朝廷は国じゅうの薬材を買い付けるため大邱に市を開き、春と秋の年二回立った。三百五十年を経た今も場所は同じだ。ひとつの通りに百軒を超える韓方薬店と韓医院が並び、まず気づくのは匂いである。甘草の根、シナモン、干した高麗人参が混じって、甘く鋭い匂いが街区の端から漂ってくる。通りの中ほどの韓医薬博物館では脈を診て、体質に合う薬草茶を淹れてくれる。大邱が自らを韓方の都と呼ぶ理由だ。","facts":["1658年、朝鮮時代に開かれた韓国最古の薬令市である。","当初は春と秋の年二回のみ開かれた。","現在この通りには100軒を超える韓方薬店と韓医院がある。","薬令市祭りが毎年5月に開かれる。"],"travelTips":["韓医薬博物館で脈診と薬草茶を体験しよう。","日曜休みの店が多い。平日のほうが確実だ。","西門市場から数分なので合わせて回ろう。"],"bestTime":"通年、祭りは5月","visitDuration":"1.5時間","ticket":"博物館は無料","openingHours":"薬令市は日中に開き、博物館は09:00〜18:00（最終入場17:30）、月曜と1月1日・旧正月・秋夕は休館","galleryCaptions":["店先に干された薬材"]},"zh":{"name":"大邱藥令市","summary":"自1658年營生至今的中藥街，整條街區都是曬乾藥材的氣味。","story":"1658年，朝鮮朝廷在大邱設市，替全國採買藥材，每年春秋各開一次。三百五十年後，它仍在同一個地方：一條街上百餘家韓藥房與韓醫院，而你最先察覺到的是氣味——甘草根、肉桂與曬乾的人參混成一種又甜又嗆的味道，從街口就聞得到。街中段的韓醫藥博物館會替你把脈，再依體質調一壺藥茶。這正是大邱自稱韓方之都的原因。","facts":["1658年朝鮮時代設立，是韓國最古老的中藥市集。","最初一年只開春、秋兩次。","如今街上有逾百家韓藥房與韓醫院。","藥令市慶典每年5月舉行。"],"travelTips":["進韓醫藥博物館體驗把脈與藥茶。","不少店家週日休息，平日比較保險。","距西門市場僅數分鐘，可一併安排。"],"bestTime":"全年；慶典在5月","visitDuration":"1.5小時","ticket":"博物館免費參觀","openingHours":"藥令市白天營業；博物館09:00–18:00（最後入場17:30），週一、1月1日與春節、中秋當日休館","galleryCaptions":["店門前曬著的藥材"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daegu-modern-alley', 'daegu-modern-alley', 'daegu', 'Ngõ cận đại Daegu', 'Daegu Modern History Alleys', 'city', 128.5885, 35.868, 'Tuyến đi bộ nối nhà thờ gạch đỏ, nhà truyền giáo và con dốc 90 bậc nơi học sinh xuống đường năm 1960.', 'Tuyến ''ngõ cận đại'' số 2 của Daegu dài chừng bốn cây số và đi qua một trăm năm lịch sử. Bắt đầu ở nhà thờ Gyesan bằng gạch đỏ dựng năm 1902, rồi lên đồi Cheongna nơi ba căn nhà của các nhà truyền giáo Mỹ vẫn còn nguyên với cây táo đầu tiên được đem vào Hàn Quốc trồng trong sân. Đoạn đáng nhớ nhất là 3·1 Manse Undong-gil — con dốc chín mươi bậc mà học sinh đã lẻn xuống để tham gia biểu tình đòi độc lập năm 1919. Cuối tuyến là ngõ Jingolmok với những căn nhà thương gia thời thuộc địa, giờ thành quán cà phê. Tuyến này miễn phí và có bảng chỉ dẫn tiếng Anh suốt dọc đường.', '["Nhà thờ Gyesan xây năm 1902, là nhà thờ Gothic gạch đỏ đầu tiên ở vùng Yeongnam.","Cây táo đầu tiên đưa vào Hàn Quốc được trồng trong khu nhà truyền giáo trên đồi Cheongna.","Bậc thang 3·1 là lối học sinh dùng để tham gia phong trào độc lập năm 1919.","Tuyến đi bộ số 2 dài khoảng 4 km và có biển chỉ dẫn song ngữ."]', '["Đi tuyến số 2 nếu chỉ có một buổi — đó là tuyến hay nhất trong năm tuyến.","Có tour hướng dẫn miễn phí khởi hành từ ga Banwoldang, cần đăng ký trước.","Kết hợp chợ Seomun ở cuối tuyến để ăn tối."]', 'Tháng 4–6 và 9–11', '2–3 giờ', '', 'Ngõ mở cả ngày. Ba căn nhà giáo sĩ trên đồi Cheongna đang đóng để sửa thành bảo tàng — chỉ xem được bên ngoài', '["hidden-gem"]', '["đi bộ","kiến trúc","lịch sử cận đại"]', '[{"seed":"daegu-modern-alley","caption":"Bậc thang 3·1 trên đồi Cheongna","ratio":"16/9"}]', '["daegu-yangnyeongsi","seomun-market"]', 0, 'https://tour.daegu.go.kr/', '2026-08-05', '{"en":{"name":"Daegu Modern History Alleys","summary":"A walking route past a red-brick church, missionary houses and the ninety steps schoolchildren used in 1919.","story":"Daegu''s ''modern alley'' route 2 runs about four kilometres through a hundred years of history. It starts at Gyesan church, red brick, built in 1902, then climbs Cheongna hill where three American missionary houses still stand with the first apple tree brought into Korea growing in the garden. The most affecting stretch is the 3·1 Manse Undong-gil — ninety steps that schoolchildren slipped down to join the independence demonstrations of 1919. It ends in the Jingolmok lanes of colonial-era merchant houses, now cafés. The route is free and signposted in English the whole way.","facts":["Gyesan church, built in 1902, was the first red-brick Gothic church in the Yeongnam region.","The first apple tree brought to Korea was planted at the missionary houses on Cheongna hill.","The 3·1 steps were the route schoolchildren took to join the 1919 independence movement.","Walking route 2 is about 4km and signposted bilingually."],"travelTips":["Take route 2 if you only have one afternoon — it is the best of the five.","Free guided walks leave from Banwoldang station; book ahead.","Finish at Seomun market for dinner."],"bestTime":"April–June and September–November","visitDuration":"2–3 hours","ticket":"","openingHours":"The alleys are open all day. The three missionary houses on Cheongna hill are closed while they are converted into a museum — only the exteriors can be seen","galleryCaptions":["The 3·1 steps on Cheongna hill"]},"ko":{"name":"대구 근대골목","summary":"붉은 벽돌 성당과 선교사 주택, 그리고 1919년 학생들이 내려간 90계단을 잇는 도보길.","story":"대구 근대골목 2코스는 4km 남짓 되고 백 년의 역사를 지난다. 1902년에 지은 붉은 벽돌의 계산성당에서 시작해 청라언덕으로 오르면 미국 선교사 주택 세 채가 그대로 남아 있고, 마당에는 한국에 처음 들어온 사과나무가 자란다. 가장 마음에 남는 구간은 3·1만세운동길이다. 1919년 학생들이 만세 시위에 나가려고 몰래 내려간 아흔 개의 계단이다. 길의 끝은 일제강점기 상인 가옥이 남은 진골목이고, 지금은 카페가 되었다. 코스는 무료이고 영문 안내판이 끝까지 이어진다.","facts":["계산성당은 1902년에 지어진 영남 최초의 붉은 벽돌 고딕 성당이다.","한국에 처음 들어온 사과나무가 청라언덕 선교사 주택에 심겼다.","3·1계단은 1919년 학생들이 만세운동에 참여하러 내려간 길이다.","도보 2코스는 약 4km이며 이중 언어 안내판이 있다."],"travelTips":["반나절뿐이라면 2코스를 고르자. 다섯 코스 중 가장 낫다.","반월당역에서 출발하는 무료 해설 투어가 있다. 예약이 필요하다.","코스 끝에서 서문시장으로 이어 저녁을 먹자."],"bestTime":"4~6월, 9~11월","visitDuration":"2~3시간","ticket":"","openingHours":"골목은 상시 개방. 청라언덕의 선교사주택 세 채는 박물관 조성 공사로 임시 휴관 중이며 외부만 볼 수 있다","galleryCaptions":["청라언덕의 3·1계단"]},"ja":{"name":"大邱近代路地","summary":"赤煉瓦の聖堂、宣教師住宅、そして1919年に生徒たちが駆け下りた九十段を結ぶ散策路。","story":"大邱の近代路地2コースは4kmほどで、百年の歴史を通り抜ける。1902年建立の赤煉瓦の桂山聖堂に始まり、青蘿の丘を上ると米国宣教師の住宅が三棟そのまま残り、庭には韓国へ初めて持ち込まれたリンゴの木が育つ。最も胸に残る区間は三・一万歳運動路だ。1919年、生徒たちが独立示威に加わるためこっそり下りた九十段の階段である。終点は日本統治期の商人家屋が残る陣骨目の路地で、いまはカフェになっている。コースは無料で、英語の案内板が最後まで続く。","facts":["桂山聖堂は1902年建立、嶺南で最初の赤煉瓦ゴシック聖堂である。","韓国へ初めて渡来したリンゴの木が青蘿の丘の宣教師住宅に植えられた。","三・一階段は1919年、生徒たちが独立運動に加わるために通った道だ。","徒歩2コースは約4kmで、二言語の案内板がある。"],"travelTips":["半日しかないなら2コースを。五つのうち最も面白い。","半月堂駅発の無料ガイドツアーがある。予約が必要だ。","コースの終点から西門市場へ出て夕食にしよう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2〜3時間","ticket":"","openingHours":"路地は終日開放。青蘿の丘の宣教師住宅3棟は博物館整備工事のため休館中で、外観のみ見られる","galleryCaptions":["青蘿の丘の三・一階段"]},"zh":{"name":"大邱近代巷弄","summary":"一條串起紅磚聖堂、傳教士宅邸，以及1919年學生走下的九十級階梯的步行路線。","story":"大邱「近代巷弄」第2號路線約四公里，穿過一百年的歷史。起點是1902年落成的紅磚桂山聖堂，接著登上青蘿丘，三棟美國傳教士住宅原封不動地立著，院子裡長著第一棵引進韓國的蘋果樹。最動人的一段是三一萬歲運動路——1919年學生們為了加入獨立示威而偷偷走下的九十級階梯。終點是保留日治時期商人宅第的陣骨巷，如今成了咖啡館。路線免費，全程都有英文標示。","facts":["桂山聖堂建於1902年，是嶺南地區第一座紅磚哥德式聖堂。","第一棵引進韓國的蘋果樹種在青蘿丘的傳教士宅院。","三一階梯是1919年學生前往參加獨立運動所走的路。","第2號步行路線約4公里，設有雙語指標。"],"travelTips":["只有半天就走第2號路線，五條之中最精采。","半月堂站有免費導覽出發，需事先預約。","路線終點接西門市場，正好吃晚餐。"],"bestTime":"4至6月與9至11月","visitDuration":"2至3小時","ticket":"","openingHours":"巷弄全日開放；青蘿丘上的三棟傳教士住宅因改建博物館暫停開放，僅能看外觀","galleryCaptions":["青蘿丘上的三一階梯"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bullo-tumuli', 'bullo-tumuli', 'daegu', 'Khu mộ cổ Bullo-dong', 'Bullo-dong Tumuli Park', 'park', 128.639, 35.916, 'Hai trăm gò mộ tròn phủ cỏ xếp trên một quả đồi giữa khu dân cư, gần như không có khách.', 'Ngay giữa vùng ngoại ô phía bắc Daegu có một quả đồi phủ kín gò mộ — hơn hai trăm nấm đất tròn, cỏ mọc xanh, có từ thế kỷ 5–6 khi vùng này còn thuộc các tiểu quốc ngoài rìa Silla. Không có hàng rào, không có vé, không có loa thuyết minh; chỉ có lối mòn giữa các gò và người dân dắt chó đi dạo lúc chiều. Điều kỳ lạ là bạn được đi bộ ngay giữa chúng — thứ mà ở Gyeongju thì không. Chiều muộn, bóng các gò đổ dài trên cỏ và cả quả đồi trông như một tấm chăn có ai đó gấp lại thành từng ụ.', '["Có hơn 200 gò mộ có niên đại thế kỷ 5–6.","Thuộc thời kỳ các tiểu quốc vùng biên của Silla, trước khi bị sáp nhập hoàn toàn.","Khu di tích mở tự do, không thu vé và không có hàng rào ngăn.","Nằm ngay trong khu dân cư phía bắc thành phố Daegu."]', '["Đi lúc chiều muộn — bóng đổ làm các gò mộ hiện hình rõ nhất.","Không có bóng râm, tránh giữa trưa mùa hè.","Ga tàu điện gần nhất là Ayanggyo, đi bộ thêm khoảng 15 phút."]', 'Tháng 4–6 và 9–11', '1 giờ', '', 'Cả ngày', '["hidden-gem"]', '["khảo cổ","gò mộ","đi bộ","hoàng hôn"]', '[{"seed":"bullo-tumuli","caption":"Gò mộ phủ cỏ lúc chiều muộn","ratio":"16/9"}]', '["palgongsan-gatbawi"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Bullo-dong Tumuli Park","summary":"Two hundred grass-covered burial mounds on a hill in the suburbs, and almost nobody there.","story":"In the middle of Daegu''s northern suburbs is a hill covered in burial mounds — more than two hundred round grassy humps, dating from the 5th and 6th centuries when this was one of the small states at Silla''s edge. There is no fence, no ticket, no audio guide; just paths between the mounds and locals walking dogs in the evening. The strange part is that you can walk right among them — something Gyeongju does not allow. Late in the day the mounds throw long shadows across the grass and the whole hill looks like a blanket someone gathered into folds.","facts":["Over 200 burial mounds dating from the 5th–6th centuries.","They belong to the small border states absorbed into Silla.","The site is open, unticketed and unfenced.","It sits inside a residential district in northern Daegu."],"travelTips":["Come late in the day — the shadows are what make the mounds read.","There is no shade; avoid midday in summer.","The nearest metro is Ayanggyo, then about 15 minutes on foot."],"bestTime":"April–June and September–November","visitDuration":"1 hour","ticket":"","openingHours":"All day","galleryCaptions":["Grassy mounds in the late afternoon"]},"ko":{"name":"불로동 고분군","summary":"주택가 언덕에 잔디 덮인 고분 200여 기. 사람은 거의 없다.","story":"대구 북쪽 주택가 한가운데에 고분으로 뒤덮인 언덕이 있다. 잔디 덮인 둥근 봉분이 이백 기가 넘고, 이 일대가 신라 변방의 작은 나라였던 5~6세기의 것이다. 울타리도 매표소도 오디오 가이드도 없다. 봉분 사이의 오솔길과, 저녁이면 개를 데리고 나온 동네 사람들이 있을 뿐이다. 이상한 것은 그 사이를 그대로 걸을 수 있다는 점이다. 경주에서는 허용되지 않는 일이다. 해가 기울면 봉분이 잔디 위로 긴 그림자를 던지고, 언덕 전체가 누군가 접어 놓은 이불처럼 보인다.","facts":["5~6세기의 고분 200여 기가 모여 있다.","신라에 흡수되기 전 변방 소국의 무덤으로 본다.","울타리와 매표소가 없는 개방된 유적이다.","대구 북구의 주택가 안에 자리한다."],"travelTips":["해 질 무렵에 가자. 그림자가 있어야 봉분이 살아난다.","그늘이 없다. 여름 한낮은 피하자.","가장 가까운 역은 아양교역이고 거기서 15분쯤 걷는다."],"bestTime":"4~6월, 9~11월","visitDuration":"1시간","ticket":"","openingHours":"상시","galleryCaptions":["저녁 빛을 받은 잔디 고분"]},"ja":{"name":"不老洞古墳群","summary":"住宅地の丘に草に覆われた古墳が二百基あまり。人はほとんどいない。","story":"大邱北部の住宅地の真ん中に、古墳で覆われた丘がある。草の生えた丸い墳丘が二百基を超え、この一帯が新羅の辺境の小国だった五〜六世紀のものだ。柵も切符売り場も音声ガイドもない。墳丘のあいだの小径と、夕方に犬を連れて歩く近所の人がいるだけである。不思議なのは、そのあいだを普通に歩けることだ。慶州では許されない。日が傾くと墳丘が草の上に長い影を落とし、丘全体が誰かがたたんだ布団のように見える。","facts":["五〜六世紀の古墳が200基あまり集まっている。","新羅に併合される前の辺境の小国の墓と見られている。","柵も入場料もない開かれた遺跡である。","大邱北区の住宅地の中にある。"],"travelTips":["日暮れ時に行こう。影があってこそ墳丘が立ち上がる。","日陰がない。夏の真昼は避けよう。","最寄りは峨洋橋駅で、そこから15分ほど歩く。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1時間","ticket":"","openingHours":"終日","galleryCaptions":["夕日を受けた草の古墳"]},"zh":{"name":"不老洞古墳群","summary":"住宅區山丘上兩百多座覆草古墳，幾乎沒有遊客。","story":"在大邱北邊住宅區的正中央，有一座長滿古墳的山丘——兩百多個覆著草的圓形墳丘，年代在五、六世紀，當時這一帶還是新羅邊緣的小國。沒有圍籬，沒有售票口，沒有語音導覽；只有墳丘之間的小徑，以及傍晚牽狗散步的居民。奇妙的是你可以就這麼走在它們中間——這在慶州是不被允許的。日頭偏西時，墳丘在草地上拉出長長的影子，整座山丘看起來像被誰摺成一褶一褶的被子。","facts":["現存五、六世紀的古墳兩百餘座。","屬於被新羅併吞前的邊境小國墓葬。","遺址開放、免費，也沒有圍籬阻隔。","位於大邱北區的住宅區之中。"],"travelTips":["傍晚再來——有影子，墳丘才立體。","毫無遮蔭，夏天請避開正午。","最近的地鐵站是峨洋橋站，再步行約15分鐘。"],"bestTime":"4至6月與9至11月","visitDuration":"1小時","ticket":"","openingHours":"全日開放","galleryCaptions":["午後斜陽下的覆草古墳"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('biseulsan-azalea', 'biseulsan-azalea', 'daegu', 'Đồi đỗ quyên Biseulsan', 'Biseulsan Azalea Ridge', 'mountain', 128.5215, 35.713, 'Ba mươi hecta hoa đỗ quyên nở kín một cao nguyên trên đỉnh núi, mỗi tháng 4 chuyển hồng toàn bộ.', 'Biseulsan có một thứ hiếm ở Hàn Quốc: một cao nguyên bằng phẳng ngay dưới đỉnh, rộng chừng ba chục hecta, và toàn bộ nó phủ kín cây đỗ quyên chamkkot. Cuối tháng 4, cả cao nguyên chuyển sang màu hồng cùng lúc — không phải từng bụi rải rác mà là một mặt phẳng hồng liền mạch trải tới chân trời, và đó là lý do người ta đổ về đây. Ngoài mùa hoa, ngọn núi này còn nổi tiếng vì ''biển đá'' — một dòng sông đá granite khổng lồ chảy xuống sườn núi từ kỷ băng hà, được xếp hạng đài kỷ niệm thiên nhiên. Có xe điện chở khách lên gần đỉnh vào mùa cao điểm.', '["Cao nguyên đỗ quyên rộng khoảng 30 hecta, nằm gần đỉnh Biseulsan.","Hoa nở rộ vào cuối tháng 4, có lễ hội đỗ quyên hằng năm.","''Biển đá'' Biseulsan là dòng đá granite hình thành từ kỷ băng hà, là đài kỷ niệm thiên nhiên.","Đỉnh Cheonwangbong cao 1.084m."]', '["Mùa hoa chỉ kéo dài khoảng 10 ngày — theo dõi thông báo của huyện Dalseong.","Có xe điện lên gần đỉnh vào mùa lễ hội, nhưng xếp hàng rất lâu.","Đi bộ lên từ chùa Yuga mất khoảng 2 giờ, dốc vừa phải."]', 'Cuối tháng 4 (hoa đỗ quyên)', 'Nửa ngày', '', 'Núi mở ban ngày. Hoa đỗ quyên nở từ đầu tháng 4 và rộ quanh 20/4; lễ hội tổ chức giữa tháng 4, có xe đưa đón chạy 08:30–17:30 cách nhau 5–10 phút trong hai ngày chính', '["festival","hidden-gem"]', '["hoa đỗ quyên","leo núi","biển đá","mùa xuân"]', '[{"seed":"biseulsan-azalea","caption":"Cao nguyên đỗ quyên nở rộ","ratio":"16/9"}]', '["apsan-park"]', 1, 'https://korean.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Biseulsan Azalea Ridge","summary":"Thirty hectares of azalea on a plateau near the summit, turning the whole tableland pink each April.","story":"Biseulsan has something rare in Korea: a flat plateau just below the summit, some thirty hectares of it, entirely covered in chamkkot azalea. In late April the whole tableland turns pink at once — not scattered bushes but an unbroken pink plane running to the skyline, which is why people come. Outside flower season the mountain is known for its ''sea of stones'', an enormous granite river left running down the slope from the ice age and designated a natural monument. A shuttle runs to near the summit during the peak season.","facts":["The azalea plateau covers about 30 hectares near the Biseulsan summit.","Peak bloom is in late April, with an annual azalea festival.","Biseulsan''s ''sea of stones'' is an ice-age granite flow, a designated natural monument.","Cheonwangbong summit reaches 1,084m."],"travelTips":["The bloom lasts only about ten days — watch Dalseong county''s announcements.","A shuttle runs near the summit during the festival, but the queue is long.","Walking up from Yuga temple takes about two hours at a moderate gradient."],"bestTime":"Late April (azaleas)","visitDuration":"Half a day","ticket":"","openingHours":"The mountain is open by day. The azaleas start in early April and peak around 20 April; the festival falls in mid-April, with shuttle buses every 5–10 minutes from 08:30 to 17:30 on the two main days","galleryCaptions":["The azalea plateau in full bloom"]},"ko":{"name":"비슬산 참꽃군락","summary":"정상 부근 고원 30헥타르를 덮은 참꽃. 4월이면 대지 전체가 분홍으로 바뀐다.","story":"비슬산에는 한국에서 드문 것이 있다. 정상 바로 아래의 평평한 고원인데, 삼십 헥타르쯤 되는 그 땅이 온통 참꽃으로 덮여 있다. 4월 말이면 고원 전체가 한꺼번에 분홍으로 바뀐다. 드문드문한 덤불이 아니라 하늘 끝까지 이어지는 끊김 없는 분홍 평면이고, 사람들이 오는 이유가 그것이다. 꽃철이 아니어도 이 산은 ''돌바다''로 알려져 있다. 빙하기에 비탈을 따라 흘러내린 거대한 화강암의 강이며 천연기념물로 지정되어 있다. 성수기에는 정상 가까이까지 전기차가 오른다.","facts":["참꽃 군락은 비슬산 정상 부근 약 30헥타르에 이른다.","4월 말이 절정이며 해마다 참꽃문화제가 열린다.","비슬산 암괴류는 빙하기에 형성된 화강암 흐름으로 천연기념물이다.","정상 천왕봉은 1,084m다."],"travelTips":["개화는 열흘 남짓이다. 달성군 안내를 확인하자.","축제 기간에는 정상 가까이 전기차가 다니지만 대기가 길다.","유가사에서 걸어 오르면 두 시간쯤, 경사는 무난하다."],"bestTime":"4월 말(참꽃)","visitDuration":"반나절","ticket":"","openingHours":"산은 낮 동안 개방된다. 참꽃은 4월 초에 피기 시작해 4월 20일 전후에 절정이며, 축제는 4월 중순에 열리고 주요 이틀간 08:30~17:30에 5~10분 간격으로 셔틀버스가 운행된다","galleryCaptions":["만개한 참꽃 고원"]},"ja":{"name":"琵瑟山のツツジ群落","summary":"山頂近くの高原30ヘクタールを覆うツツジ。4月には台地全体が桃色に変わる。","story":"琵瑟山には韓国では珍しいものがある。山頂のすぐ下の平らな高原で、三十ヘクタールほどのその土地が一面のチャムコッ（ツツジ）に覆われている。四月末になると高原全体が一斉に桃色へ変わる。点在する茂みではなく、地平まで続く切れ目のない桃色の面であり、人が来るのはそのためだ。花の季節でなくとも、この山は「石の海」で知られる。氷期に斜面を流れ下った巨大な花崗岩の川で、天然記念物に指定されている。最盛期には山頂近くまで電気車が上る。","facts":["ツツジ群落は琵瑟山の山頂付近、約30ヘクタールに広がる。","見ごろは4月末で、毎年ツツジ祭りが開かれる。","琵瑟山の岩塊流は氷期に形成された花崗岩の流れで天然記念物である。","山頂の天王峰は1,084m。"],"travelTips":["開花は十日ほどしかない。達城郡の告知を確認しよう。","祭りの期間は山頂近くまで電気車が出るが待ち時間が長い。","瑜伽寺から歩けば二時間ほど、勾配は穏やかだ。"],"bestTime":"4月下旬（ツツジ）","visitDuration":"半日","ticket":"","openingHours":"山は日中開放。ツツジは4月初めに咲き始め4月20日前後が見頃で、祭りは4月中旬。主要な2日間は08:30〜17:30に5〜10分間隔でシャトルバスが運行する","galleryCaptions":["満開のツツジ高原"]},"zh":{"name":"琵瑟山杜鵑花海","summary":"山頂附近三十公頃高原上的杜鵑，每年四月把整片台地染成粉紅。","story":"琵瑟山有一樣韓國少見的東西：山頂正下方的一片平坦高原，約三十公頃，整片覆滿真杜鵑。四月底，整座台地同時轉為粉紅——不是零星的灌叢，而是一直鋪到天際、毫無斷裂的粉色平面，人們就是為此而來。不在花季時，這座山以「石海」聞名：一條冰河期沿坡流下的巨大花崗岩之河，已被指定為天然紀念物。旺季有電動車載客上到接近山頂處。","facts":["杜鵑花海位於琵瑟山山頂附近，面積約30公頃。","四月底為盛開期，每年舉辦杜鵑花節。","琵瑟山岩塊流是冰河期形成的花崗岩流，屬天然紀念物。","主峰天王峰海拔1,084公尺。"],"travelTips":["花期只有十天左右，請留意達城郡的公告。","花節期間有電動車開到接近山頂，但排隊很久。","自瑜伽寺步行上山約兩小時，坡度尚屬平緩。"],"bestTime":"4月下旬（杜鵑）","visitDuration":"半天","ticket":"","openingHours":"山區白天開放。杜鵑自四月初開花、約4月20日前後盛開；慶典在四月中旬舉行，主要兩天有接駁車於08:30至17:30每5至10分鐘一班","galleryCaptions":["盛開的杜鵑高原"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daegu-arboretum', 'daegu-arboretum', 'daegu', 'Vườn thực vật Daegu', 'Daegu Arboretum', 'park', 128.556, 35.802, 'Bãi rác của cả thành phố suốt bảy năm, nay là vườn thực vật với hơn một nghìn tám trăm loài cây.', 'Từ 1986 đến 1990, khu đất này là nơi Daegu đổ rác — hơn bốn trăm nghìn tấn. Khi bãi rác đóng, thành phố phủ lên một lớp đất dày rồi bắt đầu trồng cây, và đến năm 2002 mở cửa thành vườn thực vật. Giờ trên nền rác cũ có hơn một nghìn tám trăm loài thực vật, vườn xương rồng trong nhà kính, vườn thảo dược, và một khu hoa cúc mùa thu mà cả thành phố kéo tới xem. Vào cửa miễn phí. Người Daegu kể chuyện này với vẻ khá tự hào, và có lý do — rất ít thành phố biến được bãi rác của mình thành thứ mà dân đi dạo mỗi cuối tuần.', '["Khu đất từng là bãi rác của Daegu từ 1986 đến 1990, chứa hơn 400.000 tấn rác.","Được phủ đất và trồng cây, mở cửa thành vườn thực vật năm 2002.","Có hơn 1.800 loài thực vật trên diện tích khoảng 24 hecta.","Vào cửa miễn phí."]', '["Cuối tháng 10 là mùa hoa cúc, đông nhất trong năm.","Nhà kính xương rồng đáng ghé kể cả mùa đông.","Có bãi đỗ xe miễn phí nhưng kín chỗ vào cuối tuần mùa hoa."]', 'Tháng 4–5 và tháng 10 (hoa cúc)', '1,5–2 giờ', '', '09:00–18:00 (mùa đông tới 17:00), đóng cửa thứ Hai', '["hidden-gem"]', '["vườn thực vật","cải tạo","gia đình","hoa cúc"]', '[{"seed":"daegu-arboretum","caption":"Vườn hoa cúc mùa thu","ratio":"16/9"}]', '["apsan-park","biseulsan-azalea"]', 0, 'https://tour.daegu.go.kr/index.do?menu_id=00002913', '2026-08-05', '{"en":{"name":"Daegu Arboretum","summary":"The city''s rubbish tip for seven years, now an arboretum with more than eighteen hundred plant species.","story":"From 1986 to 1990 this ground was where Daegu dumped its rubbish — over four hundred thousand tonnes of it. When the tip closed the city laid a thick cap of soil over it and started planting, and in 2002 it opened as an arboretum. On top of the old landfill there are now more than eighteen hundred plant species, a cactus glasshouse, a herb garden, and an autumn chrysanthemum display the whole city turns out for. Entry is free. Daegu tells this story with some pride, and fairly — few cities manage to turn their tip into the place people walk on a Sunday.","facts":["The site was Daegu''s landfill from 1986 to 1990, holding over 400,000 tonnes of waste.","It was capped with soil, planted, and opened as an arboretum in 2002.","More than 1,800 plant species grow across about 24 hectares.","Entry is free."],"travelTips":["Late October is chrysanthemum season and the busiest time of year.","The cactus glasshouse is worth a look even in winter.","Parking is free but fills up on flower-season weekends."],"bestTime":"April–May and October (chrysanthemums)","visitDuration":"1.5–2 hours","ticket":"","openingHours":"09:00–18:00 (to 17:00 in winter), closed Mondays","galleryCaptions":["The autumn chrysanthemum garden"]},"ko":{"name":"대구수목원","summary":"7년 동안 시의 쓰레기 매립장이었던 땅. 지금은 1,800종이 넘는 수목원이다.","story":"1986년부터 1990년까지 이 땅은 대구가 쓰레기를 버리던 곳이었다. 사십만 톤이 넘었다. 매립이 끝나자 시는 두껍게 흙을 덮고 나무를 심기 시작했고, 2002년 수목원으로 문을 열었다. 옛 매립지 위에 지금은 천팔백 종이 넘는 식물과 선인장 온실, 허브원, 그리고 온 도시가 보러 오는 가을 국화 전시가 있다. 입장은 무료다. 대구 사람들은 이 이야기를 꽤 자랑스럽게 하는데, 그럴 만하다. 자기 쓰레기장을 주말마다 산책하는 곳으로 바꾼 도시는 많지 않다.","facts":["1986~1990년 대구의 쓰레기 매립장으로 40만 톤이 넘게 묻혔다.","흙으로 덮고 나무를 심어 2002년 수목원으로 개원했다.","약 24헥타르에 1,800종이 넘는 식물이 자란다.","입장은 무료다."],"travelTips":["10월 말은 국화철로 한 해 중 가장 붐빈다.","선인장 온실은 겨울에도 볼 만하다.","주차는 무료지만 꽃철 주말에는 자리가 찬다."],"bestTime":"4~5월, 10월(국화)","visitDuration":"1.5~2시간","ticket":"","openingHours":"09:00~18:00(겨울은 17:00까지), 월요일 휴원","galleryCaptions":["가을 국화 정원"]},"ja":{"name":"大邱樹木園","summary":"七年間、市のごみ埋立地だった土地。いまは1,800種を超える樹木園である。","story":"1986年から1990年まで、この土地は大邱がごみを捨てる場所だった。四十万トンを超える。埋立が終わると市は厚く土を被せて木を植え始め、2002年に樹木園として開いた。かつての埋立地の上に、いまは千八百種を超える植物とサボテン温室、ハーブ園、そして街じゅうが見に来る秋の菊の展示がある。入場は無料だ。大邱の人はこの話を少し誇らしげに語るが、無理もない。自分たちのごみ捨て場を、日曜に散歩する場所に変えられた都市は多くない。","facts":["1986〜1990年に大邱の埋立地として40万トン超のごみが埋められた。","土で覆って植樹し、2002年に樹木園として開園した。","約24ヘクタールに1,800種を超える植物が育つ。","入場は無料である。"],"travelTips":["10月末は菊の季節で一年で最も混む。","サボテン温室は冬でも見ごたえがある。","駐車は無料だが花の季節の週末は満車になる。"],"bestTime":"4〜5月と10月（菊）","visitDuration":"1.5〜2時間","ticket":"","openingHours":"09:00〜18:00（冬は17:00まで）、月曜休園","galleryCaptions":["秋の菊の庭"]},"zh":{"name":"大邱樹木園","summary":"當了七年的城市垃圾掩埋場，如今是擁有逾一千八百種植物的樹木園。","story":"1986到1990年間，這塊地是大邱傾倒垃圾的地方——總量超過四十萬公噸。掩埋場關閉後，市府覆上厚厚一層土並開始種樹，2002年以樹木園之姿開放。舊掩埋場之上，如今長著一千八百多種植物，還有仙人掌溫室、香草園，以及全城都會前來觀賞的秋季菊展。免費入場。大邱人講這段故事時帶著幾分自豪，也不無道理——沒幾座城市能把自家的垃圾場，變成人們週日散步的地方。","facts":["1986至1990年為大邱的垃圾掩埋場，掩埋逾40萬公噸廢棄物。","覆土植樹後，於2002年以樹木園開放。","約24公頃的園區內有逾1,800種植物。","免費入場。"],"travelTips":["十月底是菊花季，也是一年中最擁擠的時候。","仙人掌溫室即使冬天也值得一看。","停車免費，但花季週末很快就滿。"],"bestTime":"4至5月與10月（菊花）","visitDuration":"1.5至2小時","ticket":"","openingHours":"09:00–18:00（冬季至17:00），週一休園","galleryCaptions":["秋季的菊花園"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('haeinsa', 'haeinsa', 'gyeongnam', 'Chùa Haeinsa & Tam tạng Cao Ly', 'Haeinsa Temple & Tripitaka Koreana', 'unesco', 128.098, 35.801, 'Nơi lưu giữ hơn 81.000 bản khắc gỗ kinh Phật thế kỷ 13, còn nguyên vẹn nhờ những nhà kho biết thở.', 'Giữa núi Gayasan, trong bốn toà nhà gỗ giản dị đến bất ngờ, xếp kín 81.258 tấm mộc bản khắc trọn bộ kinh Phật — công trình mất mười sáu năm để hoàn thành vào thế kỷ 13, khi Cao Ly cầu Phật lực chống quân Mông Cổ. Điều kỳ diệu là các kho chứa: cửa sổ trên dưới khác kích thước, nền lót than và muối, tạo luồng khí tự nhiên giữ mộc bản khô ráo suốt bảy thế kỷ mà không cần máy móc. Nhiều nỗ lực xây kho hiện đại đều thất bại, còn Janggyeong Panjeon thì vẫn làm tốt công việc của nó.', '["Bộ Tam tạng Cao Ly gồm 81.258 tấm mộc bản, khắc trong giai đoạn 1237–1248.","Được UNESCO công nhận Di sản Thế giới năm 1995 (kho Janggyeong Panjeon).","Hệ thống thông gió tự nhiên giữ mộc bản nguyên vẹn suốt hơn 750 năm.","Chùa Haeinsa được dựng từ năm 802."]', '["Khách không vào trong kho, chỉ xem qua song cửa — hãy đến khi đủ sáng.","Đi bus từ Daegu (Seobu) khoảng 1,5 giờ.","Mùa thu lá đỏ trên đường lên núi Gayasan rất đẹp."]', 'Tháng 10–11', '2–3 giờ', 'Miễn phí (phí tham quan di sản đã bỏ từ 5/2023); bãi đỗ xe tính riêng', '08:30–18:00', '["unesco","verified"]', '["UNESCO","Phật giáo","mộc bản"]', '[{"seed":"haeinsa","caption":"Kho mộc bản Janggyeong Panjeon","ratio":"16/9"}]', '["jinju-fortress"]', 1, 'https://www.khan.co.kr/article/202305011106001', '2026-08-04', '{"en":{"name":"Haeinsa Temple & the Tripitaka Koreana","summary":"Home to more than 81,000 13th-century woodblocks of the Buddhist canon, kept perfect by storehouses that breathe.","story":"Deep in the Gayasan mountains, in four surprisingly plain wooden halls, sit 81,258 woodblocks carved with the complete Buddhist canon — sixteen years of work finished in the 13th century, when Goryeo sought the Buddha''s protection against the Mongols. The miracle is the storehouses: windows of different sizes above and below, floors layered with charcoal and salt, creating a natural airflow that has kept the blocks dry for seven centuries without machinery. Modern climate-controlled buildings failed; Janggyeong Panjeon still does its job.","facts":["The Tripitaka Koreana comprises 81,258 woodblocks, carved 1237–1248.","The Janggyeong Panjeon storehouses were inscribed by UNESCO in 1995.","Natural ventilation has preserved the blocks for over 750 years.","Haeinsa temple itself was founded in 802."],"travelTips":["Visitors look in through the lattice rather than entering — come while the light is good.","Buses from Daegu (Seobu terminal) take about 1.5 hours.","Autumn colour on the road up Gayasan is superb."],"bestTime":"October–November","visitDuration":"2–3 hours","ticket":"Free (the cultural heritage fee was abolished in May 2023); parking charged separately","openingHours":"08:30–18:00","galleryCaptions":["The Janggyeong Panjeon woodblock hall"]},"ko":{"name":"해인사와 팔만대장경","summary":"13세기 경판 8만여 장이 숨 쉬는 장경각 덕분에 온전히 남아 있다.","story":"가야산 깊은 곳, 놀랄 만큼 소박한 목조 건물 네 채 안에 불경 전체를 새긴 경판 81,258장이 놓여 있다. 몽골의 침입에 맞서 부처의 힘을 빌고자 16년에 걸쳐 새긴 13세기의 일이다. 놀라운 것은 창고다. 위아래 창의 크기를 달리하고 바닥에 숯과 소금을 깔아 자연 대류를 만들어, 기계 없이 700년 넘게 경판을 마른 상태로 지켜왔다. 현대식 수장고는 실패했지만 장경판전은 지금도 제 일을 한다.","facts":["팔만대장경은 81,258장의 경판으로 1237~1248년에 제작되었다.","장경판전은 1995년 유네스코 세계유산에 등재되었다.","자연 통풍 구조가 750년 넘게 경판을 보존해 왔다.","해인사는 802년에 창건되었다."],"travelTips":["내부에는 들어갈 수 없고 살창 너머로 본다. 빛이 좋은 시간에 가자.","대구 서부정류장에서 버스로 약 1시간 30분이다.","가야산 오르는 길의 가을 단풍이 아름답다."],"bestTime":"10~11월","visitDuration":"2~3시간","ticket":"무료(2023년 5월 문화재관람료 폐지), 주차료는 별도","openingHours":"08:30~18:00","galleryCaptions":["장경판전의 경판"]},"ja":{"name":"海印寺と八万大蔵経","summary":"13世紀の経板8万枚余りが、呼吸する蔵経板殿のおかげで完全に残る。","story":"伽耶山の奥、驚くほど簡素な木造の建物四棟の中に、仏典すべてを刻んだ経板81,258枚が納められている。モンゴルの侵攻に抗して仏の加護を願い、16年をかけて彫った13世紀の仕事だ。驚くべきは倉のほうだ。上下の窓の大きさを変え、床に炭と塩を敷いて自然の対流を生み、機械なしで700年以上も経板を乾いた状態に保ってきた。近代的な収蔵庫は失敗したが、蔵経板殿は今も役目を果たしている。","facts":["八万大蔵経は81,258枚の経板で、1237〜1248年に作られた。","蔵経板殿は1995年にユネスコ世界遺産に登録された。","自然通風の構造が750年以上も経板を守ってきた。","海印寺は802年の創建。"],"travelTips":["内部には入れず格子越しに見る。光の良い時間に行こう。","大邱西部ターミナルからバスで約1時間30分。","伽耶山へ登る道の紅葉が美しい。"],"bestTime":"10〜11月","visitDuration":"2〜3時間","ticket":"無料（2023年5月に文化財観覧料が廃止）、駐車料は別途","openingHours":"08:30〜18:00","galleryCaptions":["蔵経板殿の経板"]},"zh":{"name":"海印寺與八萬大藏經","summary":"八萬多塊十三世紀經板，因會「呼吸」的藏經閣而完好保存至今。","story":"在伽倻山深處，四棟樸素得出乎意料的木造建築裡，安放著刻有全套佛教經典的81,258塊經板——那是十三世紀高麗祈求佛力抵禦蒙古時，耗費十六年完成的工程。真正的奇蹟在於藏經閣：上下窗口大小不同，地板鋪了木炭與鹽，形成自然對流，七個世紀以來未靠任何機械便讓經板保持乾燥。現代恆溫恆濕庫房失敗了，藏經板殿卻仍在盡職。","facts":["八萬大藏經共81,258塊經板，刻於1237至1248年。","藏經板殿於1995年列入世界遺產。","自然通風構造已保存經板逾750年。","海印寺本身創建於802年。"],"travelTips":["遊客只能隔著木格窗觀看，請挑光線好的時段。","自大邱西部客運站搭車約1.5小時。","伽倻山沿途的秋色極美。"],"bestTime":"10至11月","visitDuration":"2至3小時","ticket":"免費（文化財觀覽費已於2023年5月廢止），停車費另計","openingHours":"08:30–18:00","galleryCaptions":["藏經板殿內的經板"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('tongyeong-dongpirang', 'tongyeong-dongpirang', 'gyeongnam', 'Tongyeong & làng bích hoạ Dongpirang', 'Tongyeong & Dongpirang Village', 'city', 128.433, 34.845, 'Thành phố cảng nhìn ra hàng trăm hòn đảo, với ngôi làng trên đồi được cứu bằng tranh tường.', 'Tongyeong nằm ở chỗ đất liền vỡ vụn thành quần đảo Hallyeohaesang, và cáp treo lên núi Mireuksan cho bạn thấy toàn cảnh: hàng trăm đảo lớn nhỏ rải trên mặt biển xanh. Dưới chân đồi, làng Dongpirang từng bị lên kế hoạch giải toả cho đến khi các hoạ sĩ tình nguyện phủ kín tường nhà bằng tranh — dân tình kéo đến xem, và làng được giữ lại. Cảng cá bên dưới bán kimbap Chungmu ăn kèm mực cay, món ăn ra đời để không bị ôi khi ngư dân ra khơi.', '["Là căn cứ thuỷ quân của đô đốc Yi Sun-sin thời Joseon.","Cáp treo Mireuksan dài 1.975m, dài nhất Hàn Quốc khi khánh thành.","Làng Dongpirang được giữ lại nhờ phong trào vẽ tranh tường năm 2007.","Kimbap Chungmu là đặc sản gắn với nghề đi biển của thành phố."]', '["Đi cáp treo vào sáng sớm khi trời trong để nhìn rõ quần đảo.","Từ Busan có xe khách trực tiếp, khoảng 1,5 giờ.","Bến tàu Tongyeong có phà đi các đảo Somaemuldo, Yokjido."]', 'Tháng 4–6 và 9–10', 'Nửa ngày', 'Cáp treo Mireuksan khứ hồi 17.000 KRW (trẻ 3–12 tuổi 13.000); làng bích hoạ Dongpirang miễn phí', '09:30–17:00 (cáp treo)', '["popular"]', '["cảng biển","đảo","tranh tường"]', '[{"seed":"tongyeong-dongpirang","caption":"Quần đảo nhìn từ núi Mireuksan","ratio":"16/9"}]', '["geoje-oedo","namhae-daraengi"]', 0, 'https://cablecar.ttdc.kr/sub02/sub02_01.php', '2026-08-04', '{"en":{"name":"Tongyeong & Dongpirang Village","summary":"A port town looking out on hundreds of islands, with a hillside village saved by its murals.","story":"Tongyeong sits where the land breaks up into the Hallyeohaesang archipelago, and the cable car up Mireuksan shows you the whole of it: hundreds of islands scattered over blue water. Below, Dongpirang village was scheduled for demolition until volunteer artists covered its walls with paintings — visitors came to see them, and the village was kept. Down at the fishing harbour they sell Chungmu gimbap, invented so that a fisherman''s lunch would not spoil at sea.","facts":["Tongyeong was Admiral Yi Sun-sin''s naval headquarters in the Joseon era.","The Mireuksan cable car is 1,975m long, the longest in Korea when it opened.","Dongpirang village was saved by a mural campaign in 2007.","Chungmu gimbap is the local dish, born of the fishing trade."],"travelTips":["Ride the cable car early on a clear morning to see the islands sharply.","Direct coaches from Busan take about 1.5 hours.","Ferries leave Tongyeong for Somaemuldo and Yokjido islands."],"bestTime":"April–June and September–October","visitDuration":"Half a day","ticket":"The Mireuksan cable car is 17,000 KRW return (13,000 for ages 3–12); Dongpirang mural village is free","openingHours":"09:30–17:00 (cable car)","galleryCaptions":["Murals in Dongpirang village"]},"ko":{"name":"통영과 동피랑마을","summary":"수백 개의 섬을 바라보는 항구 도시. 벽화로 살아남은 언덕 마을이 있다.","story":"통영은 육지가 부서져 한려해상의 군도가 되는 자리에 있고, 미륵산 케이블카에 오르면 그 전부가 보인다. 푸른 바다 위에 흩어진 수백 개의 섬. 그 아래 동피랑마을은 철거될 예정이었지만 자원한 화가들이 담벼락을 그림으로 채우면서 사람들이 찾아왔고 마을은 살아남았다. 항구에서는 어부의 도시락이 상하지 않도록 만들어진 충무김밥을 판다.","facts":["조선시대 이순신 장군의 삼도수군통제영이 있던 곳이다.","미륵산 케이블카는 길이 1,975m로 개통 당시 한국에서 가장 길었다.","동피랑마을은 2007년 벽화 사업으로 보존되었다.","충무김밥은 이 고장의 어업 문화에서 태어난 음식이다."],"travelTips":["맑은 날 이른 아침에 케이블카를 타면 섬들이 또렷하다.","부산에서 시외버스로 약 1시간 30분이다.","통영항에서 소매물도, 욕지도로 가는 배가 뜬다."],"bestTime":"4~6월, 9~10월","visitDuration":"반나절","ticket":"미륵산 케이블카 왕복 17,000원(3~12세 13,000원), 동피랑 벽화마을은 무료","openingHours":"09:30~17:00(케이블카)","galleryCaptions":["동피랑마을의 벽화"]},"ja":{"name":"統営と東ピラン村","summary":"数百の島を望む港町。壁画で生き延びた丘の集落がある。","story":"統営は陸地が砕けて閑麗海上の群島になる場所にあり、弥勒山のケーブルカーに登ればその全部が見える。青い海に散らばる数百の島。その下の東ピラン村は取り壊される予定だったが、志願した画家たちが壁を絵で埋めると人が訪れるようになり、村は残った。港では、漁師の弁当が傷まないよう工夫されて生まれた忠武キンパを売っている。","facts":["朝鮮時代、李舜臣将軍の三道水軍統制営が置かれた。","弥勒山ケーブルカーは全長1,975mで開通当時は韓国最長だった。","東ピラン村は2007年の壁画事業で保存された。","忠武キンパはこの土地の漁業文化から生まれた料理。"],"travelTips":["晴れた日の早朝にケーブルカーへ乗れば島々がくっきり見える。","釜山から市外バスで約1時間30分。","統営港から小梅物島や欲知島へ船が出る。"],"bestTime":"4〜6月、9〜10月","visitDuration":"半日","ticket":"弥勒山ケーブルカー往復17,000ウォン（3〜12歳13,000）、東披郎壁画村は無料","openingHours":"09:30〜17:00（ケーブルカー）","galleryCaptions":["東ピラン村の壁画"]},"zh":{"name":"統營與東皮廊村","summary":"面對數百座島嶼的港市，山坡上的村落靠壁畫存活下來。","story":"統營位於陸地碎裂成閑麗海上群島之處，搭弥勒山纜車上去便能看見全貌：藍色海面上散布著數百座島。山下的東皮廊村原本要被拆除，直到志願藝術家把牆面畫滿——遊客為此而來，村子得以保留。港邊賣著忠武紫菜飯捲，那是為了讓漁民的午餐在海上不致腐壞而發明的。","facts":["朝鮮時代曾是李舜臣將軍的三道水軍統制營所在。","弥勒山纜車長1,975公尺，啟用時為韓國最長。","東皮廊村因2007年的壁畫行動而被保留。","忠武紫菜飯捲源自當地的漁業生活。"],"travelTips":["晴朗的清晨搭纜車，島嶼輪廓最清楚。","自釜山搭客運約1.5小時。","統營港有船前往小梅物島與欲知島。"],"bestTime":"4至6月、9至10月","visitDuration":"半天","ticket":"彌勒山纜車來回17,000韓元（3至12歲13,000）；東披郎壁畫村免費","openingHours":"09:30–17:00（纜車）","galleryCaptions":["東皮廊村的壁畫"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('geoje-oedo', 'geoje-oedo', 'gyeongnam', 'Đảo vườn Oedo Botania (Geoje)', 'Oedo Botania, Geoje', 'island', 128.71, 34.79, 'Một hòn đảo đá được hai vợ chồng biến thành khu vườn Địa Trung Hải suốt ba mươi năm.', 'Năm 1969 một cặp vợ chồng mua hòn đảo đá cằn này sau khi thuyền của họ trú bão ở đây. Họ trồng thử cam, thất bại; trồng thử nhiều thứ khác, cũng thất bại; rồi kiên trì gây rừng và làm vườn suốt ba thập kỷ cho tới khi cả đảo thành một khu vườn bậc thang với hàng nghìn loài cây, tượng đá trắng và lối đi nhìn ra biển. Chỉ tới được bằng phà, và mỗi lượt khách chỉ ở lại được chừng một tiếng rưỡi — vừa đủ để đi hết vòng vườn.', '["Được cải tạo từ năm 1969, mở cửa cho khách từ 1995.","Có hơn 3.000 loài thực vật, nhiều loài á nhiệt đới.","Chỉ đến được bằng phà từ Geoje hoặc Tongyeong.","Thời gian tham quan trên đảo được giới hạn theo lịch phà."]', '["Đặt vé phà trước vào mùa cao điểm.","Phà có thể huỷ khi biển động — luôn có phương án dự phòng.","Kết hợp ghé Haegeumgang, khối đá ngoài khơi gần đó."]', 'Tháng 4–6 và 9–10', 'Nửa ngày (kể cả phà)', 'Khoảng 38.000 KRW (phà ~27.000 + vé vào đảo ~11.000); giá thay đổi theo bến và hãng tàu', 'Theo lịch phà, 08:00–17:00', '[]', '["đảo","vườn","phà"]', '[{"seed":"geoje-oedo","caption":"Vườn bậc thang trên đảo Oedo","ratio":"16/9"}]', '["tongyeong-dongpirang"]', 0, 'https://www.tripadvisor.com/Attraction_Review-g1510776-d5924172-Reviews-Oedo_Botania-Geoje_Gyeongsangnam_do.html', '2026-08-04', '{"en":{"name":"Oedo Botania, Geoje","summary":"A rocky island turned into a Mediterranean garden by one couple over thirty years.","story":"In 1969 a married couple bought this barren rock after their boat sheltered here in a storm. They tried oranges and failed; tried other crops and failed; then spent three decades planting windbreaks and building terraces until the whole island became a garden of thousands of species, white statues and paths looking out to sea. It is reachable only by ferry, and each group has about ninety minutes ashore — just enough to walk the full circuit.","facts":["Cultivated from 1969 and opened to visitors in 1995.","More than 3,000 plant species, many of them subtropical.","Reachable only by ferry from Geoje or Tongyeong.","Time ashore is limited by the ferry schedule."],"travelTips":["Book ferry tickets ahead in high season.","Ferries are cancelled in rough seas — keep a backup plan.","Combine with Haegeumgang, the rock formation offshore nearby."],"bestTime":"April–June and September–October","visitDuration":"Half a day including the ferry","ticket":"Around 38,000 KRW (ferry ~27,000 + island entry ~11,000); varies by harbour and operator","openingHours":"Ferry schedule, 08:00–17:00","galleryCaptions":["Terraced gardens on Oedo island"]},"ko":{"name":"거제 외도 보타니아","summary":"부부가 30년에 걸쳐 지중해식 정원으로 바꾼 바위섬.","story":"1969년 한 부부가 폭풍우를 피해 정박했던 이 척박한 바위섬을 샀다. 감귤을 심었다가 실패하고, 다른 작물도 실패한 끝에, 30년 동안 방풍림을 기르고 단을 쌓아 섬 전체를 수천 종의 식물과 흰 조각상, 바다를 향한 산책로가 있는 정원으로 만들었다. 배로만 갈 수 있고 한 회차당 한 시간 반쯤 머무를 수 있다. 정원을 한 바퀴 도는 데 딱 알맞은 시간이다.","facts":["1969년부터 가꾸어 1995년 관람객에게 개방되었다.","아열대 식물을 포함해 3,000종이 넘는 식물이 있다.","거제나 통영에서 여객선으로만 갈 수 있다.","섬에 머무는 시간은 배 시간표에 따라 제한된다."],"travelTips":["성수기에는 여객선 표를 미리 예매하자.","파도가 높으면 결항되니 대안을 준비하자.","인근 해금강과 함께 둘러보자."],"bestTime":"4~6월, 9~10월","visitDuration":"반나절(배편 포함)","ticket":"약 38,000원(배 27,000원 + 입장 11,000원), 출항지와 선사에 따라 다름","openingHours":"여객선 운항 시간, 08:00~17:00","galleryCaptions":["외도의 계단식 정원"]},"ja":{"name":"巨済 外島ボタニア","summary":"夫婦が30年かけて地中海風の庭園に変えた岩の島。","story":"1969年、一組の夫婦が嵐を避けて停泊したこの荒れた岩島を買った。ミカンを植えては失敗し、他の作物も失敗し、それから三十年かけて防風林を育て段を築き、島全体を数千種の植物と白い彫像、海へ開く小道のある庭園に変えた。船でしか行けず、一回あたり一時間半ほど滞在できる。庭を一周するのにちょうどよい時間だ。","facts":["1969年から整備され、1995年に一般公開された。","亜熱帯を含む3,000種を超える植物がある。","巨済または統営からの旅客船でのみ行ける。","島での滞在時間は船の時刻表で制限される。"],"travelTips":["繁忙期は乗船券を事前に手配しよう。","波が高いと欠航する。代替案を用意しよう。","近くの海金剛と合わせて回るとよい。"],"bestTime":"4〜6月、9〜10月","visitDuration":"半日（船を含む）","ticket":"約38,000ウォン（船27,000＋入場11,000）、出発港と船社により変動","openingHours":"旅客船の運航時間、08:00〜17:00","galleryCaptions":["外島の段々の庭園"]},"zh":{"name":"巨濟外島Botania","summary":"一對夫婦花三十年把岩石小島變成地中海式花園。","story":"1969年，一對夫婦在暴風雨中避難停靠後買下這座貧瘠的岩島。他們種柑橘失敗，種別的作物也失敗，然後花了三十年造防風林、築梯田，直到整座島成為擁有數千種植物、白色雕像與面海步道的花園。這裡只能搭船前往，每批遊客上岸約一個半小時——剛好夠走完整座花園。","facts":["自1969年開始整建，1995年對外開放。","擁有逾3,000種植物，其中許多為亞熱帶物種。","只能自巨濟或統營搭船前往。","上島時間依船班表限制。"],"travelTips":["旺季請提前訂船票。","風浪大時會停航，記得準備備案。","可順道遊覽附近的海金剛岩礁。"],"bestTime":"4至6月、9至10月","visitDuration":"半天（含船程）","ticket":"約38,000韓元（船票約27,000＋登島門票約11,000），依碼頭與船公司而異","openingHours":"依船班時間，08:00–17:00","galleryCaptions":["外島上的梯狀花園"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jinju-fortress', 'jinju-fortress', 'gyeongnam', 'Thành Jinju & đèn lồng sông Nam', 'Jinju Fortress & Lantern Festival', 'unesco', 128.08, 35.19, 'Toà thành bên sông gắn với hai trận vây hãm khốc liệt, mỗi tháng 10 lại rực sáng đèn lồng.', 'Năm 1592, ba nghìn quân giữ thành Jinju đẩy lui hai vạn quân Nhật — một trong ba chiến thắng lớn nhất cuộc chiến Nhâm Thìn. Năm sau thành thất thủ, và kỹ nữ Non-gae đã ôm một tướng Nhật nhảy xuống sông Nam từ mỏm đá dưới lầu Chokseongnu. Ngày nay thành là công viên yên tĩnh nhìn xuống sông. Mỗi tháng 10, lễ hội đèn lồng Jinju thả hàng nghìn chiếc đèn giấy trên mặt nước — tục lệ bắt nguồn từ đèn hiệu quân sự thời chiến.', '["Gắn với hai trận vây thành năm 1592 và 1593 trong chiến tranh Nhâm Thìn.","Lầu Chokseongnu là một trong ba lầu gác nổi tiếng nhất Hàn Quốc.","Lễ hội đèn lồng sông Nam tổ chức vào tháng 10 hằng năm.","Trong thành có bảo tàng quốc gia Jinju về cuộc chiến Nhâm Thìn."]', '["Đi vào tháng 10 nếu muốn xem lễ hội đèn lồng, nhớ đặt phòng sớm.","Buổi tối thành lên đèn, đi dạo ven sông rất dễ chịu.","Jinju cũng nổi tiếng với bibimbap kiểu riêng, ăn thử ở chợ trung tâm."]', 'Tháng 10 (lễ hội đèn lồng)', '2 giờ', '2.000 KRW (thiếu niên 1.000, trẻ em 600) trong khung 09:00–18:00; ngoài giờ đó vào tự do', '05:00–23:00', '["festival"]', '["thành cổ","lễ hội","lịch sử"]', '[{"seed":"jinju-fortress","caption":"Lầu Chokseongnu bên sông Nam","ratio":"16/9"}]', '["haeinsa"]', 0, 'https://www.jinju.go.kr/02238.web', '2026-08-04', '{"en":{"name":"Jinju Fortress & the Namgang Lantern Festival","summary":"A riverside fortress tied to two brutal sieges, lit each October by thousands of lanterns.","story":"In 1592 three thousand defenders of Jinju threw back twenty thousand Japanese troops — one of the three great victories of the Imjin War. The following year the fortress fell, and the courtesan Non-gae pulled a Japanese commander into the Nam River with her from the rock beneath Chokseongnu pavilion. Today the fortress is a quiet park above the water. Each October the Jinju Lantern Festival floats thousands of paper lanterns on the river, a custom descended from wartime signal lamps.","facts":["Site of the sieges of 1592 and 1593 during the Imjin War.","Chokseongnu is one of the three most celebrated pavilions in Korea.","The Namgang Lantern Festival is held each October.","The Jinju National Museum inside the walls covers the Imjin War."],"travelTips":["Come in October for the lantern festival, and book a room early.","The fortress is lit at night and pleasant to walk along the river.","Jinju has its own style of bibimbap — try it at the central market."],"bestTime":"October (lantern festival)","visitDuration":"2 hours","ticket":"2,000 KRW (1,000 teens, 600 children) between 09:00 and 18:00; outside those hours entry is free","openingHours":"05:00–23:00","galleryCaptions":["Chokseongnu pavilion above the Nam River"]},"ko":{"name":"진주성과 남강유등축제","summary":"두 번의 처절한 공성전이 서린 강가의 성. 10월이면 등불로 빛난다.","story":"1592년 진주성의 3천 병력이 왜군 2만을 물리쳤다. 임진왜란 3대 대첩의 하나다. 이듬해 성은 함락되었고, 촉석루 아래 바위에서 논개가 왜장을 끌어안고 남강에 몸을 던졌다. 지금 성은 강을 내려다보는 조용한 공원이다. 해마다 10월이면 진주남강유등축제가 수천 개의 등을 강에 띄운다. 전쟁 때의 신호 등불에서 비롯된 풍습이다.","facts":["1592년과 1593년 임진왜란의 두 차례 진주성 전투가 있었다.","촉석루는 한국의 3대 누각 가운데 하나로 꼽힌다.","진주남강유등축제는 매년 10월에 열린다.","성 안에 임진왜란을 다루는 국립진주박물관이 있다."],"travelTips":["유등축제를 보려면 10월에 가고 숙소는 미리 잡자.","밤에는 성에 조명이 들어와 강변 산책이 좋다.","진주는 고유한 비빔밥으로도 유명하니 중앙시장에서 먹어보자."],"bestTime":"10월(유등축제)","visitDuration":"2시간","ticket":"09:00~18:00에는 2,000원(청소년 1,000원, 어린이 600원), 그 외 시간은 무료 개방","openingHours":"05:00~23:00","galleryCaptions":["남강을 굽어보는 촉석루"]},"ja":{"name":"晋州城と南江流灯祭り","summary":"二度の激しい攻城戦の記憶を宿す川辺の城。10月には灯りで輝く。","story":"1592年、晋州城の三千の兵が二万の日本軍を退けた。壬辰倭乱の三大大捷のひとつだ。翌年、城は落ち、矗石楼の下の岩から論介が敵将を抱いて南江に身を投げた。今、城は川を見下ろす静かな公園である。毎年10月には晋州南江流灯祭りが数千の灯籠を川に浮かべる。戦時の信号灯に由来する習わしだ。","facts":["1592年と1593年、壬辰倭乱の二度の晋州城の戦いがあった。","矗石楼は韓国三大楼閣のひとつに数えられる。","晋州南江流灯祭りは毎年10月に開かれる。","城内には壬辰倭乱を扱う国立晋州博物館がある。"],"travelTips":["流灯祭りを見るなら10月に行き、宿は早めに確保しよう。","夜は城がライトアップされ、川辺の散歩が心地よい。","晋州は独自のビビンバでも有名。中央市場で味わおう。"],"bestTime":"10月（流灯祭り）","visitDuration":"2時間","ticket":"09:00〜18:00は2,000ウォン（青少年1,000、子ども600）、それ以外の時間は無料開放","openingHours":"05:00〜23:00","galleryCaptions":["南江を見下ろす矗石楼"]},"zh":{"name":"晉州城與南江流燈節","summary":"與兩場慘烈攻城戰相連的江畔城池，每年十月被燈火點亮。","story":"1592年，晉州城的三千守軍擊退兩萬日軍——這是壬辰倭亂三大捷之一。翌年城破，妓女論介在矗石樓下的岩石上抱住一名日軍將領，一同墜入南江。今日的城池是俯瞰江面的安靜公園。每年十月，晉州南江流燈節把數千盞紙燈放上江面，這習俗源自戰時的信號燈。","facts":["1592與1593年壬辰倭亂兩度晉州城之戰的發生地。","矗石樓是韓國三大名樓之一。","南江流燈節每年十月舉行。","城內設有講述壬辰倭亂的國立晉州博物館。"],"travelTips":["想看流燈節請在十月前來，並提早訂房。","夜裡城池打燈，沿江散步很舒服。","晉州也有自己風格的拌飯，可在中央市場品嚐。"],"bestTime":"10月（流燈節）","visitDuration":"2小時","ticket":"09:00至18:00收費2,000韓元（青少年1,000、兒童600）；其餘時段免費開放","openingHours":"05:00–23:00","galleryCaptions":["俯瞰南江的矗石樓"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('namhae-daraengi', 'namhae-daraengi', 'gyeongnam', 'Ruộng bậc thang Daraengi (Namhae)', 'Daraengi Terraced Fields, Namhae', 'village', 127.908, 34.71, 'Hơn một trăm bậc ruộng nhỏ xíu xếp từ sườn núi xuống tận mép biển.', 'Ở làng Gacheon, đất dốc đến mức người ta phải chia sườn núi thành hơn một trăm bậc ruộng, có bậc bé đến mức chỉ cấy được vài hàng lúa. Từ trên đường nhìn xuống, các bậc ruộng xếp lớp như vảy cá, và ngay dưới chân là biển. Người làng vẫn canh tác theo lối cũ vì máy móc không lên được. Con đường ven biển Namhae dẫn qua đây là một trong những cung đường lái xe đẹp nhất Hàn Quốc, đặc biệt vào tháng 6 khi ruộng đầy nước phản chiếu trời chiều.', '["Có khoảng 108 bậc ruộng, thửa nhỏ nhất chỉ vài mét vuông.","Được công nhận là Danh thắng quốc gia số 15.","Canh tác chủ yếu bằng tay do địa hình quá dốc.","Nằm trên cung đường ven biển đảo Namhae."]', '["Tháng 6 ruộng đổ nước, tháng 10 lúa chín — hai thời điểm đẹp nhất.","Cần xe riêng; xe buýt tới làng rất thưa.","Có nhà nghỉ homestay ngay trong làng, đặt trước vào cuối tuần."]', 'Tháng 6 và tháng 10', '1,5–2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["ruộng bậc thang","làng","ven biển"]', '[{"seed":"namhae-daraengi","caption":"Ruộng bậc thang đổ xuống biển","ratio":"16/9"}]', '["tongyeong-dongpirang"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Daraengi Terraced Fields, Namhae","summary":"More than a hundred tiny terraces stepping down the mountain to the sea.","story":"At Gacheon village the land is so steep that people cut the slope into more than a hundred terraces, some barely wide enough for a few rows of rice. Seen from the road above they stack like fish scales, and directly below them is the sea. Villagers still farm by hand because machinery cannot reach. The Namhae coastal road that passes here is one of the finest drives in Korea, particularly in June when the flooded terraces mirror the evening sky.","facts":["About 108 terraces, the smallest only a few square metres.","Designated National Scenic Site No. 15.","Farmed largely by hand because the ground is too steep for machines.","On the coastal road around Namhae island."],"travelTips":["June (flooded fields) and October (ripe rice) are the two best moments.","You need your own car; buses to the village are infrequent.","There are homestays in the village — book ahead at weekends."],"bestTime":"June and October","visitDuration":"1.5–2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["Terraces dropping to the sea"]},"ko":{"name":"남해 다랭이마을","summary":"산비탈에서 바다까지 백여 층으로 이어지는 작은 계단논.","story":"가천마을은 땅이 너무 가팔라 비탈을 백 층이 넘는 논으로 나눴다. 어떤 논은 벼 몇 줄이 겨우 들어갈 만큼 작다. 위쪽 도로에서 내려다보면 논이 물고기 비늘처럼 포개지고 바로 아래가 바다다. 기계가 오르지 못해 주민들은 여전히 손으로 농사를 짓는다. 이곳을 지나는 남해 해안도로는 한국에서 손꼽히는 드라이브 길이고, 특히 6월 물을 댄 논이 저녁 하늘을 비출 때가 아름답다.","facts":["약 108개의 계단논이 있으며 가장 작은 것은 몇 제곱미터에 불과하다.","국가 명승 제15호다.","경사가 급해 대부분 손으로 농사를 짓는다.","남해섬 해안도로 변에 있다."],"travelTips":["6월(물 댄 논)과 10월(벼 익는 때)이 가장 좋다.","자가용이 필요하다. 마을로 가는 버스는 매우 드물다.","마을에 민박이 있으니 주말에는 미리 예약하자."],"bestTime":"6월과 10월","visitDuration":"1시간 30분~2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["바다로 내려앉는 계단논"]},"ja":{"name":"南海 タレンイ村","summary":"山の斜面から海まで、百段を超えて連なる小さな棚田。","story":"加川村は土地があまりに急なので、斜面を百段を超える田に分けた。稲が数列しか入らないほど小さな田もある。上の道路から見下ろすと田が魚の鱗のように重なり、そのすぐ下が海だ。機械が上がれないため住民は今も手で耕す。ここを通る南海の海岸道路は韓国屈指のドライブルートで、とりわけ6月、水を張った田が夕空を映すときが美しい。","facts":["約108枚の棚田があり、最小のものは数平方メートルしかない。","国家名勝第15号。","傾斜が急で大半を手作業で耕作している。","南海島の海岸道路沿いにある。"],"travelTips":["6月（田に水を張る時期）と10月（稲の実り）が最も良い。","自家用車が必要。村へのバスは非常に少ない。","村に民宿があるので週末は事前予約を。"],"bestTime":"6月と10月","visitDuration":"1時間30分〜2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["海へ下る棚田"]},"zh":{"name":"南海多樂里梯田","summary":"一百多層小小的梯田，自山坡一路階梯而下直抵海邊。","story":"加川村的土地太陡，人們把坡面切成一百多層田，有些窄到只能插下幾行稻。從上方公路俯視，田塊層層相疊像魚鱗，正下方就是大海。機械上不去，村民至今仍以人力耕作。經過此地的南海海岸公路是韓國最美的自駕路線之一，尤其六月田裡蓄水、映著晚霞的時候。","facts":["約有108層梯田，最小的僅數平方公尺。","被指定為國家名勝第15號。","因坡度過陡，多以人力耕作。","位於南海島的海岸公路旁。"],"travelTips":["六月（蓄水）與十月（稻熟）是兩個最佳時刻。","需自駕；前往村子的公車班次極少。","村內有民宿，週末請提前預訂。"],"bestTime":"6月與10月","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["層層落向海面的梯田"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gimhae-gaya-tombs', 'gimhae-gaya-tombs', 'gyeongnam', 'Khu mộ cổ Gaya (Gimhae)', 'Daeseong-dong Gaya Tumuli, Gimhae', 'unesco', 128.876, 35.235, 'Những gò mộ của một vương quốc bị lịch sử gạt ra rìa, được UNESCO ghi danh năm 2023.', 'Trước khi Silla thống nhất bán đảo, vùng hạ lưu sông Nakdong thuộc về liên minh Gaya — một tập hợp các tiểu quốc sống bằng sắt và buôn bán đường biển với Nhật Bản, Trung Hoa. Vì Gaya bị Silla thôn tính và sử sách do bên thắng viết, người ta gần như quên mất họ; chỉ có các gò mộ ở Daeseong-dong giữ lại bằng chứng. Trong đó là giáp sắt, mũ trụ, hàng nghìn thanh sắt thỏi dùng làm tiền tệ, và cả xương của người tuỳ táng. Bảo tàng ngay cạnh cắt một gò mộ ra làm đôi để bạn thấy các lớp chôn cất chồng lên nhau qua bốn thế kỷ.', '["Được UNESCO công nhận Di sản Thế giới năm 2023 trong cụm ''Lăng mộ Gaya''.","Gimhae từng là kinh đô của Geumgwan Gaya, tiểu quốc mạnh nhất liên minh.","Trong mộ tìm thấy giáp sắt, mũ trụ và sắt thỏi dùng như tiền tệ.","Bảo tàng Daeseong-dong trưng bày một gò mộ được cắt dọc tại chỗ."]', '["Đi tàu điện nhẹ Busan–Gimhae tới ga Bảo tàng Quốc gia Gimhae.","Vào bảo tàng trước rồi mới ra khu gò mộ, thứ tự đó dễ hiểu hơn.","Khu gò mộ là bãi cỏ trống, mùa hè rất nắng — mang mũ."]', 'Tháng 4–6 và 9–11', '2 giờ', 'Miễn phí', '09:00–18:00, vào cửa cuối 17:30; đóng cửa thứ Hai, 1/1 và ngày Tết, Chuseok', '["unesco","hidden-gem"]', '["UNESCO","Gaya","khảo cổ","bảo tàng"]', '[{"seed":"gimhae-gaya-tombs","caption":"Gò mộ Daeseong-dong","ratio":"16/9"}]', '["jinhae-cherry-blossom"]', 0, 'https://www.gimhae.go.kr/06048/06049.web', '2026-08-04', '{"en":{"name":"Daeseong-dong Gaya Tumuli, Gimhae","summary":"The burial mounds of a kingdom history pushed to the margins, inscribed by UNESCO in 2023.","story":"Before Silla unified the peninsula, the lower Nakdong belonged to the Gaya confederacy — a set of small states living on iron and sea trade with Japan and China. Because Silla absorbed Gaya and the winners wrote the histories, they were all but forgotten; only the mounds at Daeseong-dong kept the evidence. Inside were iron armour, helmets, thousands of iron ingots used as currency, and the bones of people buried alongside their lord. The museum next door cuts one mound in half so you can see four centuries of burials stacked on top of each other.","facts":["Inscribed by UNESCO in 2023 as part of the Gaya Tumuli.","Gimhae was the capital of Geumgwan Gaya, the strongest state in the confederacy.","Iron armour, helmets and iron ingots used as currency were found in the tombs.","The Daeseong-dong museum displays a mound sectioned in place."],"travelTips":["Take the Busan–Gimhae light rail to Gimhae National Museum station.","Do the museum first and the mounds after; it makes far more sense that way.","The mound field is open grass with no shade — bring a hat in summer."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"Free","openingHours":"09:00–18:00, last entry 17:30; closed Mondays, 1 January, Seollal and Chuseok","galleryCaptions":["The Daeseong-dong burial mounds"]},"ko":{"name":"김해 대성동 고분군","summary":"역사가 변두리로 밀어낸 왕국의 무덤. 2023년 유네스코에 등재되었다.","story":"신라가 반도를 통일하기 전, 낙동강 하류는 가야 연맹의 땅이었다. 철과 바닷길 교역으로 살아간 작은 나라들의 모임이었고, 일본과 중국을 오갔다. 가야는 신라에 흡수되었고 역사는 이긴 쪽이 썼기에 그들은 거의 잊혔다. 증거를 남긴 것은 대성동의 무덤들뿐이다. 그 안에서 철갑과 투구, 화폐로 쓰인 수천 개의 덩이쇠, 그리고 함께 묻힌 사람의 뼈가 나왔다. 옆의 박물관은 무덤 하나를 그대로 잘라 보여 준다. 네 세기에 걸친 매장이 층층이 겹쳐 있다.","facts":["2023년 ''가야고분군''의 일부로 유네스코 세계유산에 등재되었다.","김해는 가야 연맹에서 가장 강했던 금관가야의 도읍이었다.","무덤에서 철갑과 투구, 화폐로 쓰인 덩이쇠가 출토되었다.","대성동고분박물관은 봉분을 단면으로 잘라 현장 전시한다."],"travelTips":["부산김해경전철 국립김해박물관역에서 내리면 된다.","박물관을 먼저 보고 고분군으로 나가면 훨씬 이해가 쉽다.","고분군은 그늘 없는 잔디밭이다. 여름에는 모자를 챙기자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"무료","openingHours":"09:00~18:00, 입장 마감 17:30. 월요일과 1월 1일·설날·추석 당일 휴관","galleryCaptions":["대성동 고분군"]},"ja":{"name":"金海大成洞古墳群","summary":"歴史が周縁へ押しやった王国の墓。2023年にユネスコへ登録された。","story":"新羅が半島を統一する前、洛東江の下流は伽耶連盟の地だった。鉄と海上交易で生きた小国の集まりで、日本や中国と行き来していた。伽耶は新羅に吸収され、歴史は勝った側が書いたため、彼らはほとんど忘れられた。証拠を残したのは大成洞の墓だけである。中からは鉄の甲冑と兜、貨幣として使われた数千の鉄鋌、そして共に葬られた人の骨が出た。隣の博物館は墳丘をそのまま断ち割って見せる。四世紀にわたる埋葬が層になって重なっている。","facts":["2023年、「伽耶古墳群」の一部としてユネスコ世界遺産に登録された。","金海は伽耶連盟で最も強かった金官伽耶の都だった。","墓からは鉄の甲冑・兜と、貨幣として用いられた鉄鋌が出土した。","大成洞古墳博物館は墳丘を断面で現地展示している。"],"travelTips":["釜山金海軽電鉄の国立金海博物館駅で降りればよい。","博物館を先に見てから古墳群へ出ると理解しやすい。","古墳群は日陰のない芝地だ。夏は帽子を持とう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"無料","openingHours":"09:00〜18:00、最終入場17:30。月曜と1月1日・旧正月・秋夕は休館","galleryCaptions":["大成洞の古墳群"]},"zh":{"name":"金海大成洞古墳群","summary":"一個被歷史推到邊緣的王國留下的墓塚，2023年列入世界遺產。","story":"在新羅統一半島之前，洛東江下游屬於伽倻聯盟——一群靠鐵器與海上貿易維生的小國，往來於日本與中國之間。伽倻被新羅併吞，而歷史由勝者書寫，於是他們幾乎被遺忘；留下證據的只有大成洞的這些墓塚。裡頭出土了鐵甲、頭盔、數以千計作為貨幣使用的鐵鋌，以及陪葬者的骨骸。隔壁的博物館把一座墳丘直接剖開展示，讓人看見四個世紀的埋葬如何層層疊起。","facts":["2023年以「伽倻古墳群」的一部分列入世界遺產。","金海曾是伽倻聯盟中最強的金官伽倻的都城。","墓中出土鐵甲、頭盔與作為貨幣使用的鐵鋌。","大成洞古墳博物館以剖面方式原地展示一座墳丘。"],"travelTips":["搭釜山金海輕軌至國立金海博物館站。","先看博物館再走古墳群，理解起來會清楚得多。","古墳群是一片沒有遮蔭的草地，夏天請戴帽子。"],"bestTime":"4至6月與9至11月","visitDuration":"2小時","ticket":"免費","openingHours":"09:00–18:00，最後入場17:30；週一、1月1日與春節、中秋當日休館","galleryCaptions":["大成洞古墳群"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jirisan-national-park', 'jirisan-national-park', 'gyeongnam', 'Vườn quốc gia Jirisan', 'Jirisan National Park', 'mountain', 127.7305, 35.337, 'Vườn quốc gia đầu tiên của Hàn Quốc, dãy núi lớn nhất đất liền với đường sống núi đi mất ba ngày.', 'Jirisan là vườn quốc gia đầu tiên của Hàn Quốc và vẫn là khối núi lớn nhất trên đất liền: trải qua ba tỉnh, đỉnh Cheonwangbong cao 1.915 mét, và một tuyến sống núi dài hơn bốn mươi cây số mà dân leo núi Hàn coi là chặng đường phải đi một lần trong đời — ba ngày, ngủ ở các nhà nghỉ trên núi phải đặt trước cả tháng. Nếu chỉ có một ngày thì đi từ Jungsan-ri lên Cheonwangbong rồi xuống lại. Núi này còn mang lịch sử nặng: du kích ẩn náu ở đây suốt những năm sau chiến tranh, và các thung lũng vẫn còn bia tưởng niệm.', '["Được lập năm 1967, là vườn quốc gia đầu tiên của Hàn Quốc.","Đỉnh Cheonwangbong cao 1.915m, cao nhất Hàn Quốc lục địa.","Tuyến sống núi chính dài khoảng 45 km, thường đi trong 3 ngày.","Vườn trải trên ba tỉnh: Gyeongnam, Jeonbuk và Jeonnam."]', '["Nhà nghỉ trên núi phải đặt trước qua hệ thống của vườn quốc gia, thường kín sớm.","Tuyến một ngày phổ biến nhất: Jungsan-ri lên Cheonwangbong, khứ hồi 9–10 giờ.","Thời tiết trên đỉnh khác hẳn dưới chân núi — luôn mang áo gió."]', 'Tháng 5–6 (hoa đỗ quyên) và tháng 10 (lá đỏ)', 'Cả ngày đến 3 ngày', '', 'Áp dụng ''chế độ giờ vào núi'' của vườn quốc gia: được lên từ 04:00 (tháng 3–11) hoặc 05:00 (tháng 12–2), và mỗi cung đường có giờ chặn riêng trong khoảng 12:00–17:00. Kiểm tra thông báo đóng đường trước khi đi', '["verified"]', '["leo núi","vườn quốc gia","sống núi","mùa thu"]', '[{"seed":"jirisan-national-park","caption":"Sống núi Jirisan lúc bình minh","ratio":"16/9"}]', '["haeinsa"]', 1, 'https://www.knps.or.kr/front/portal/safe/acsCtrDtl.do?menuNo=8000340&rstId=0005', '2026-08-05', '{"en":{"name":"Jirisan National Park","summary":"Korea''s first national park, the largest massif on the mainland, with a ridge walk that takes three days.","story":"Jirisan was Korea''s first national park and is still the largest massif on the mainland: it spans three provinces, Cheonwangbong summit reaches 1,915 metres, and the main ridge runs more than forty kilometres — the walk Korean hikers treat as a once-in-a-lifetime obligation. Three days, sleeping in mountain huts you must book a month ahead. With only one day, go up from Jungsan-ri to Cheonwangbong and back. The mountain carries heavy history too: partisans hid here through the years after the war, and memorials still stand in the valleys.","facts":["Designated in 1967 as Korea''s first national park.","Cheonwangbong summit is 1,915m, the highest point on the Korean mainland.","The main ridge traverse is about 45km and usually walked over three days.","The park spans three provinces: Gyeongnam, Jeonbuk and Jeonnam."],"travelTips":["Mountain huts must be booked through the national park system and fill early.","The usual day route is Jungsan-ri to Cheonwangbong and back, 9–10 hours.","Summit weather is nothing like the valley — always carry a windproof layer."],"bestTime":"May–June (azaleas) and October (autumn colour)","visitDuration":"A full day to three days","ticket":"","openingHours":"The national park entry-time system applies: ascent opens at 04:00 (March–November) or 05:00 (December–February), and each section has its own turn-back time somewhere between 12:00 and 17:00. Check the trail-closure notices before setting out","galleryCaptions":["The Jirisan ridge at dawn"]},"ko":{"name":"지리산국립공원","summary":"한국 최초의 국립공원. 내륙에서 가장 큰 산덩이이고, 능선을 다 걸으면 사흘이 걸린다.","story":"지리산은 한국 최초의 국립공원이고, 지금도 내륙에서 가장 큰 산덩이다. 세 개 도에 걸쳐 있고, 천왕봉은 1,915m이며, 주능선은 40km가 넘는다. 한국 산꾼들이 일생에 한 번은 해야 한다고 여기는 종주다. 사흘이 걸리고, 산장은 한 달 전에 예약해야 한다. 하루뿐이라면 중산리에서 천왕봉까지 올랐다가 되돌아오면 된다. 이 산은 무거운 역사도 지녔다. 전쟁 뒤 여러 해 동안 빨치산이 여기 숨었고, 골짜기마다 위령비가 남아 있다.","facts":["1967년 지정된 한국 최초의 국립공원이다.","천왕봉은 1,915m로 한국 내륙에서 가장 높다.","주능선 종주는 약 45km이며 보통 사흘에 걸쳐 걷는다.","경남, 전북, 전남 세 개 도에 걸쳐 있다."],"travelTips":["산장은 국립공원 예약 시스템으로만 잡을 수 있고 일찍 마감된다.","당일 코스는 중산리~천왕봉 왕복이 일반적이며 9~10시간 걸린다.","정상 날씨는 아래와 전혀 다르다. 바람막이는 늘 챙기자."],"bestTime":"5~6월(철쭉)과 10월(단풍)","visitDuration":"하루~사흘","ticket":"","openingHours":"국립공원 입산시간지정제가 적용된다. 입산은 3~11월 04:00, 12~2월 05:00부터 가능하며 구간마다 12:00~17:00 사이로 통제시간이 다르다. 출발 전 통제 정보를 확인하자","galleryCaptions":["새벽의 지리산 능선"]},"ja":{"name":"智異山国立公園","summary":"韓国初の国立公園。内陸最大の山塊で、稜線を歩き通すと三日かかる。","story":"智異山は韓国最初の国立公園であり、今も内陸で最も大きな山塊だ。三つの道にまたがり、天王峰は1,915m、主稜線は40kmを超える。韓国の登山者が一生に一度はやるものと考える縦走である。三日かかり、山小屋は一か月前に予約しなければならない。一日しかないなら中山里から天王峰へ登って引き返せばよい。この山は重い歴史も背負う。戦後の数年間パルチザンがここに潜み、谷ごとに慰霊碑が残っている。","facts":["1967年指定、韓国初の国立公園である。","天王峰は1,915mで、韓国内陸の最高峰。","主稜線の縦走は約45kmで、通常三日かけて歩く。","慶尚南道・全羅北道・全羅南道の三道にまたがる。"],"travelTips":["山小屋は国立公園の予約制度でしか取れず、早く埋まる。","日帰りは中山里〜天王峰の往復が一般的で9〜10時間。","山頂の天気は麓とまるで違う。ウインドシェルは常に携行を。"],"bestTime":"5〜6月（ツツジ）と10月（紅葉）","visitDuration":"一日〜三日","ticket":"","openingHours":"国立公園の入山時間指定制が適用される。入山は3〜11月は04:00、12〜2月は05:00から可能で、区間ごとに12:00〜17:00の間で規制時刻が異なる。出発前に通行規制情報の確認を","galleryCaptions":["夜明けの智異山の稜線"]},"zh":{"name":"智異山國立公園","summary":"韓國第一座國立公園，本島最大的山塊，走完主稜要三天。","story":"智異山是韓國第一座國立公園，至今仍是本島上最大的山塊：橫跨三個道，天王峰海拔1,915公尺，主稜線長逾四十公里——韓國登山者視為此生必走一次的縱走。要三天，山莊得提前一個月訂。若只有一天，就從中山里上天王峰再原路折返。這座山也背著沉重的歷史：戰後好幾年游擊隊藏身於此，各個山谷至今仍立著慰靈碑。","facts":["1967年劃設，是韓國第一座國立公園。","天王峰海拔1,915公尺，是韓國本島最高點。","主稜縱走約45公里，通常分三天走完。","橫跨慶尚南道、全羅北道與全羅南道三個道。"],"travelTips":["山莊只能透過國立公園系統預約，且很早就額滿。","一日行程通常是中山里往返天王峰，需9至10小時。","山頂天氣與山下完全不同，務必攜帶防風外套。"],"bestTime":"5至6月（杜鵑）與10月（紅葉）","visitDuration":"一天至三天","ticket":"","openingHours":"適用國家公園「入山時間指定制」：3至11月自04:00、12至2月自05:00開放入山，各路段的折返管制時間落在12:00至17:00之間。出發前請先查看步道封閉公告","galleryCaptions":["破曉時分的智異山稜線"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('upo-wetland', 'upo-wetland', 'gyeongnam', 'Đầm Upo (Changnyeong)', 'Upo Wetland, Changnyeong', 'lake', 128.42, 35.558, 'Đầm nước ngọt tự nhiên lớn nhất Hàn Quốc, hình thành từ thời khủng long và chưa từng bị tháo cạn.', 'Upo tồn tại từ khoảng một trăm bốn mươi triệu năm trước, và điều đáng nói là nó vẫn còn — phần lớn đầm lầy Hàn Quốc đã bị lấp để làm ruộng trong thế kỷ 20. Đầm rộng hơn hai cây số vuông, mặt nước phủ kín cỏ và bèo đến mức từ xa trông như một cánh đồng, chỉ khi lại gần mới thấy nước bên dưới. Đây là nơi con cò quăm mào — loài từng tuyệt chủng ngoài tự nhiên ở Hàn Quốc — được thả về lại từ năm 2019. Đường mòn và lối xe đạp chạy vòng quanh mất chừng ba tiếng, và sương sớm trên mặt đầm là lý do người ta dậy từ bốn giờ.', '["Là đầm nước ngọt tự nhiên lớn nhất Hàn Quốc, rộng khoảng 2,3 km².","Được cho là hình thành từ khoảng 140 triệu năm trước.","Đăng ký theo Công ước Ramsar về đất ngập nước năm 1998.","Là nơi tái thả cò quăm mào, loài từng tuyệt chủng ngoài tự nhiên tại Hàn Quốc."]', '["Thuê xe đạp ở cổng để đi vòng quanh đầm — đi bộ hết khá xa.","Sương sớm đẹp nhất vào những sáng lạnh tháng 10–12.","Mang chống muỗi nếu đi vào mùa hè."]', 'Tháng 10–12 (sương và chim di cư)', '3 giờ', '', 'Đường tham quan mở 24 giờ; có 5 tuyến từ 1 km (30 phút) tới 9,7 km (3 giờ 30 phút)', '["hidden-gem"]', '["đầm lầy","chim","Ramsar","đạp xe"]', '[{"seed":"upo-wetland","caption":"Sương sớm trên đầm Upo","ratio":"16/9"}]', '["gimhae-gaya-tombs"]', 0, 'https://www.cng.go.kr/tour/upo.web', '2026-08-05', '{"en":{"name":"Upo Wetland, Changnyeong","summary":"Korea''s largest natural freshwater marsh, formed in the age of dinosaurs and never drained.","story":"Upo has existed for something like a hundred and forty million years, and the remarkable thing is that it still does — most Korean marshland was filled for farmland during the 20th century. The wetland covers more than two square kilometres, its surface so thick with grass and duckweed that from a distance it reads as a field; only up close do you see water beneath. This is where the crested ibis, extinct in the wild in Korea, has been reintroduced since 2019. A walking and cycling loop takes about three hours, and the dawn mist is why people get up at four.","facts":["Korea''s largest natural freshwater wetland at about 2.3km².","Thought to have formed around 140 million years ago.","Registered under the Ramsar Convention on wetlands in 1998.","It is the reintroduction site for the crested ibis, once extinct in the wild in Korea."],"travelTips":["Hire a bike at the gate for the loop; walking it all is a long way.","The mist is best on cold mornings from October to December.","Bring insect repellent in summer."],"bestTime":"October–December (mist and migratory birds)","visitDuration":"3 hours","ticket":"","openingHours":"The trails are open 24 hours; there are five routes, from 1 km (30 minutes) to 9.7 km (3 hours 30 minutes)","galleryCaptions":["Dawn mist over Upo"]},"ko":{"name":"창녕 우포늪","summary":"한국에서 가장 큰 자연 담수 습지. 공룡의 시대에 생겨 한 번도 메워지지 않았다.","story":"우포늪은 약 1억 4천만 년 전부터 있었고, 놀라운 것은 지금도 있다는 사실이다. 한국의 습지 대부분은 20세기에 논으로 메워졌다. 늪은 2km²가 넘고, 수면이 풀과 개구리밥으로 빽빽해 멀리서 보면 들판 같다. 가까이 가야 아래에 물이 있음을 안다. 한국에서 야생 절멸했던 따오기를 2019년부터 다시 풀어놓은 곳이기도 하다. 도보와 자전거로 한 바퀴 도는 데 세 시간쯤 걸리고, 새벽 물안개는 사람들이 네 시에 일어나는 이유다.","facts":["면적 약 2.3km²로 한국에서 가장 큰 자연 담수 습지다.","약 1억 4천만 년 전에 형성된 것으로 본다.","1998년 람사르 습지로 등록되었다.","한국에서 야생 절멸했던 따오기의 복원 방사지다."],"travelTips":["입구에서 자전거를 빌리자. 걸어서 한 바퀴는 꽤 멀다.","물안개는 10~12월의 추운 아침이 가장 좋다.","여름에는 모기 기피제를 챙기자."],"bestTime":"10~12월(물안개와 철새)","visitDuration":"3시간","ticket":"","openingHours":"탐방로는 24시간 개방되며, 1km(30분)부터 9.7km(3시간 30분)까지 다섯 개 코스가 있다","galleryCaptions":["우포늪의 새벽 물안개"]},"ja":{"name":"昌寧牛浦沼","summary":"韓国最大の自然淡水湿地。恐竜の時代に生まれ、一度も干拓されなかった。","story":"牛浦沼はおよそ一億四千万年前から存在し、驚くべきは今も存在していることだ。韓国の湿地の大半は二十世紀に田へと埋め立てられた。沼は2km²を超え、水面が草と浮草で覆われて遠目には野原に見える。近づいて初めて下に水があると分かる。韓国で野生絶滅していたトキが、2019年から再導入されている場所でもある。徒歩と自転車で一周すると三時間ほど。明け方の水霧は、人々が四時に起きる理由である。","facts":["面積約2.3km²で韓国最大の自然淡水湿地である。","およそ1億4千万年前に形成されたと考えられている。","1998年にラムサール条約湿地として登録された。","韓国で野生絶滅したトキの再導入地である。"],"travelTips":["入口で自転車を借りよう。一周を歩くとかなり遠い。","水霧は10〜12月の寒い朝が最もよい。","夏は虫除けを持とう。"],"bestTime":"10〜12月（水霧と渡り鳥）","visitDuration":"3時間","ticket":"","openingHours":"遊歩道は24時間開放。1km（30分）から9.7km（3時間30分）まで5つのコースがある","galleryCaptions":["牛浦沼の明け方の水霧"]},"zh":{"name":"昌寧牛浦沼","summary":"韓國最大的天然淡水濕地，形成於恐龍時代，從未被排乾。","story":"牛浦沼存在了大約一億四千萬年，而真正了不起的是它至今還在——韓國大部分沼澤都在二十世紀被填成農田。濕地面積超過兩平方公里，水面被水草與浮萍蓋得密不透風，遠看像一片原野，走近才看得見底下的水。這裡也是朱䴉的野放地——這種鳥在韓國一度野外滅絕，自2019年起重新引入。步道與自行車道繞行一圈約需三小時，而清晨的水霧，正是人們四點就起床的原因。","facts":["面積約2.3平方公里，是韓國最大的天然淡水濕地。","一般認為形成於約一億四千萬年前。","1998年依拉姆薩公約登錄為國際重要濕地。","是朱䴉的復育野放地，該鳥曾在韓國野外滅絕。"],"travelTips":["在入口租單車繞湖，全程用走的相當遠。","水霧以10至12月的寒冷清晨最美。","夏天請攜帶防蚊用品。"],"bestTime":"10至12月（水霧與候鳥）","visitDuration":"3小時","ticket":"","openingHours":"步道24小時開放；共五條路線，從1公里（30分鐘）到9.7公里（3小時30分鐘）","galleryCaptions":["牛浦沼的清晨水霧"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jinhae-cherry-blossom', 'jinhae-cherry-blossom', 'gyeongnam', 'Hoa anh đào Jinhae', 'Jinhae Cherry Blossom', 'park', 128.665, 35.147, 'Ba mươi sáu vạn cây anh đào phủ trắng một thị trấn hải quân, trong đó có đường ray và con suối nổi tiếng nhất Hàn Quốc.', 'Cuối tháng 3, thị trấn hải quân Jinhae biến mất dưới hoa. Hơn ba trăm sáu mươi nghìn cây anh đào nở cùng lúc, và cả nước đổ về dự lễ hội Gunhangje. Hai điểm ai cũng xếp hàng: ga Gyeonghwa, nơi đường ray cũ chạy xuyên một đường hầm hoa dài tám trăm mét; và suối Yeojwacheon, nơi cành anh đào rủ xuống mặt nước hai bên một cây cầu nhỏ — cây cầu này xuất hiện trong bộ phim truyền hình mà nhiều người vẫn nhớ. Ngoài mùa hoa, Jinhae là một thị trấn quân cảng bình thường, yên ắng và ít khách.', '["Có hơn 360.000 cây anh đào, nhiều nhất trong một đô thị ở Hàn Quốc.","Lễ hội Gunhangje diễn ra vào cuối tháng 3 đến đầu tháng 4.","Đường ray ga Gyeonghwa dài khoảng 800m phủ kín hoa hai bên.","Jinhae là quân cảng chính của hải quân Hàn Quốc."]', '["Mùa hoa cực kỳ đông — đi tàu tới Changwon rồi bắt bus, đừng lái xe.","Ga Gyeonghwa đông nhất vào giữa trưa; đi sớm 7h sáng để chụp được ảnh.","Thời điểm nở thay đổi theo năm, kiểm tra dự báo hoa trước khi đặt vé."]', 'Cuối tháng 3 đến đầu tháng 4', 'Nửa ngày', '', 'Cả ngày', '["festival","popular"]', '["hoa anh đào","lễ hội","nhiếp ảnh","mùa xuân"]', '[{"seed":"jinhae-cherry-blossom","caption":"Đường ray ga Gyeonghwa mùa hoa","ratio":"16/9"}]', '["gimhae-gaya-tombs"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Jinhae Cherry Blossom","summary":"Three hundred and sixty thousand cherry trees burying a naval town, including Korea''s most photographed railway and stream.","story":"In late March the naval town of Jinhae disappears under blossom. More than three hundred and sixty thousand cherry trees flower at once and the whole country turns up for the Gunhangje festival. Two spots have queues: Gyeonghwa station, where an old railway line runs through eight hundred metres of blossom tunnel; and the Yeojwacheon stream, where branches lean over the water on either side of a small bridge made famous by a television drama. Outside blossom season Jinhae is an ordinary naval port town, quiet and largely unvisited.","facts":["More than 360,000 cherry trees, the highest concentration in any Korean city.","The Gunhangje festival runs from late March into early April.","The Gyeonghwa station railway runs about 800m under blossom on both sides.","Jinhae is the main base of the Republic of Korea Navy."],"travelTips":["Blossom season is extremely crowded — take a train to Changwon and a bus; don''t drive.","Gyeonghwa station is worst at midday; arrive by 7am for photographs.","Bloom dates shift each year, so check the forecast before booking."],"bestTime":"Late March to early April","visitDuration":"Half a day","ticket":"","openingHours":"All day","galleryCaptions":["The Gyeonghwa station railway in blossom"]},"ko":{"name":"진해 벚꽃","summary":"36만 그루의 벚나무가 해군 도시를 뒤덮는다. 한국에서 가장 많이 찍히는 철길과 개천이 여기 있다.","story":"3월 말이면 해군 도시 진해가 꽃 아래로 사라진다. 36만 그루가 넘는 벚나무가 한꺼번에 피고, 온 나라가 군항제를 보러 몰려온다. 줄이 늘어서는 곳은 두 군데다. 옛 철길이 800m의 꽃 터널을 지나는 경화역, 그리고 작은 다리 양옆으로 가지가 물 위로 늘어지는 여좌천이다. 그 다리는 어느 드라마로 유명해졌다. 꽃철이 아니면 진해는 조용하고 손님도 적은 평범한 군항 도시다.","facts":["36만 그루가 넘는 벚나무로, 한국의 도시 가운데 가장 많다.","군항제는 3월 말부터 4월 초까지 열린다.","경화역 철길은 약 800m 구간 양옆이 벚꽃으로 덮인다.","진해는 대한민국 해군의 주요 군항이다."],"travelTips":["꽃철에는 매우 붐빈다. 창원까지 기차로 간 뒤 버스를 타자. 자가용은 피하는 게 좋다.","경화역은 한낮이 가장 붐빈다. 사진을 찍으려면 아침 7시까지 가자.","개화 시기는 해마다 다르니 예매 전에 개화 예보를 확인하자."],"bestTime":"3월 말~4월 초","visitDuration":"반나절","ticket":"","openingHours":"상시","galleryCaptions":["벚꽃철의 경화역 철길"]},"ja":{"name":"鎮海の桜","summary":"三十六万本の桜が海軍の街を埋める。韓国で最も撮られる線路と小川がここにある。","story":"三月末、海軍の街・鎮海は花の下に消える。三十六万本を超える桜が一斉に咲き、国じゅうが軍港祭を見に押し寄せる。行列ができるのは二か所だ。古い線路が八百メートルの花のトンネルを抜ける慶和駅と、小さな橋の両脇から枝が水面へ垂れる余佐川である。その橋はあるドラマで有名になった。花の季節を外せば、鎮海は静かで客も少ない普通の軍港の街だ。","facts":["36万本を超える桜があり、韓国の都市では最も多い。","軍港祭は3月下旬から4月初めにかけて開かれる。","慶和駅の線路は約800mにわたり両脇が桜で覆われる。","鎮海は韓国海軍の主要な軍港である。"],"travelTips":["花の時期は非常に混む。昌原まで鉄道で行きバスに乗り換えよう。車は避けたい。","慶和駅は昼が最も混む。撮影するなら朝7時までに。","開花時期は年によって動く。予約前に開花予報を確認しよう。"],"bestTime":"3月下旬〜4月初め","visitDuration":"半日","ticket":"","openingHours":"終日","galleryCaptions":["桜の季節の慶和駅の線路"]},"zh":{"name":"鎮海櫻花","summary":"三十六萬株櫻花淹沒一座海軍小城，韓國最常被拍的鐵道與小溪都在這裡。","story":"三月底，海軍城鎮鎮海會整個沒入花海。三十六萬餘株櫻花同時綻放，全國的人都湧來看軍港祭。兩個地方永遠在排隊：慶和站，一段舊鐵道穿過長達八百公尺的花隧道；以及余佐川，櫻枝自小橋兩側低垂到水面上——那座橋因一部電視劇而聞名。花季之外，鎮海只是一座安靜、少有遊客的普通軍港城鎮。","facts":["櫻樹逾36萬株，是韓國城市中密度最高的。","軍港祭於3月底至4月初舉行。","慶和站鐵道約有800公尺兩側覆滿櫻花。","鎮海是韓國海軍的主要軍港。"],"travelTips":["花季極度擁擠——搭火車到昌原再轉公車，別開車。","慶和站中午最擠，想拍照請在早上七點前抵達。","花期每年不同，訂票前先查開花預報。"],"bestTime":"3月底至4月初","visitDuration":"半天","ticket":"","openingHours":"全日開放","galleryCaptions":["花季中的慶和站鐵道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('tongyeong-mireuksan', 'tongyeong-mireuksan', 'gyeongnam', 'Cáp treo núi Mireuksan (Tongyeong)', 'Mireuksan Cable Car, Tongyeong', 'mountain', 128.423, 34.818, 'Từ đỉnh núi nhìn xuống hàng trăm hòn đảo rải kín mặt biển Hallyeohaesang như vụn đá.', 'Tongyeong nằm giữa vùng biển Hallyeohaesang — dải biển kín gió rải hàng trăm hòn đảo lớn nhỏ mà người Hàn hay gọi là ''Naples của phương Đông''. Cách tốt nhất để hiểu địa hình ấy là lên đỉnh Mireuksan: cáp treo dài gần hai cây số đưa bạn lên gần đỉnh trong mười phút, rồi đi bộ thêm mười lăm phút là tới đài quan sát. Từ đó, cả vùng vịnh mở ra với các đảo xếp lớp nhạt dần về phía chân trời; ngày trời cực trong có thể thấy đảo Tsushima. Dưới chân núi là thành phố với chợ cá, xưởng đóng thuyền và món cơm cuộn chungmu nổi tiếng.', '["Cáp treo dài khoảng 1,975 km, là một trong những tuyến dài nhất Hàn Quốc.","Đỉnh Mireuksan cao 461m, nhìn ra vườn quốc gia biển Hallyeohaesang.","Ngày trời rất trong có thể nhìn thấy đảo Tsushima của Nhật Bản.","Tongyeong là quê hương của nhạc sĩ Yun Isang và món kimbap chungmu."]', '["Đặt vé cáp treo trước vào cuối tuần; hàng chờ có thể tới một giờ.","Cáp treo ngừng khi gió mạnh — nên đi buổi sáng, gió thường nhẹ hơn.","Từ trạm trên còn phải đi bộ 15 phút lên đài quan sát, có bậc thang."]', 'Tháng 4–6 và 9–11', '2–3 giờ', 'Cáp treo khứ hồi 17.000 KRW (người lớn)', '09:30–17:00 (thay đổi theo mùa)', '["popular"]', '["cáp treo","đảo","toàn cảnh","biển"]', '[{"seed":"tongyeong-mireuksan","caption":"Vùng đảo Hallyeohaesang nhìn từ đỉnh","ratio":"16/9"}]', '["tongyeong-dongpirang","geoje-windy-hill"]', 0, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=77581', '2026-08-04', '{"en":{"name":"Mireuksan Cable Car, Tongyeong","summary":"From the summit, hundreds of islands scattered across the Hallyeohaesang sea like broken stone.","story":"Tongyeong sits in the middle of Hallyeohaesang — a sheltered stretch of sea strewn with hundreds of islands that Koreans like to call the Naples of the East. The best way to grasp that geography is from the top of Mireuksan: a cable car almost two kilometres long lifts you near the summit in ten minutes, then it is a fifteen-minute walk to the observation deck. From there the bay opens out with islands layering paler towards the horizon; on the clearest days you can see Tsushima. Below is a city of fish markets, boatyards and the famous chungmu gimbap.","facts":["The cable car runs about 1.975km, one of the longest in Korea.","Mireuksan summit is 461m, overlooking Hallyeohaesang National Marine Park.","On very clear days the Japanese island of Tsushima is visible.","Tongyeong is the home town of composer Yun Isang and of chungmu gimbap."],"travelTips":["Book the cable car ahead at weekends; the queue can reach an hour.","It stops in strong wind — mornings are usually calmer.","From the upper station it is a further 15-minute walk up steps to the deck."],"bestTime":"April–June and September–November","visitDuration":"2–3 hours","ticket":"Cable car 17,000 KRW return (adult)","openingHours":"09:30–17:00 (varies by season)","galleryCaptions":["The Hallyeohaesang islands from the summit"]},"ko":{"name":"통영 미륵산 케이블카","summary":"정상에서 내려다보면 한려해상의 섬 수백 개가 부서진 돌처럼 바다에 흩어져 있다.","story":"통영은 한려해상 한가운데에 있다. 수백 개의 섬이 흩어진 잔잔한 바다로, 한국 사람들이 흔히 ''동양의 나폴리''라 부르는 곳이다. 그 지형을 이해하는 가장 좋은 방법은 미륵산 정상에 오르는 것이다. 2km에 가까운 케이블카가 십 분이면 정상 가까이 데려다주고, 거기서 전망대까지는 십오 분을 더 걸으면 된다. 전망대에 서면 만이 펼쳐지고 섬들이 수평선 쪽으로 갈수록 옅어진다. 아주 맑은 날에는 쓰시마도 보인다. 산 아래는 어시장과 조선소, 그리고 충무김밥의 도시다.","facts":["케이블카 길이는 약 1.975km로 한국에서 가장 긴 축에 든다.","미륵산 정상은 461m로 한려해상국립공원을 내려다본다.","아주 맑은 날에는 일본 쓰시마섬이 보인다.","통영은 작곡가 윤이상의 고향이자 충무김밥의 고장이다."],"travelTips":["주말에는 케이블카를 미리 예약하자. 대기가 한 시간에 이르기도 한다.","바람이 세면 운행을 멈춘다. 대체로 오전이 잔잔하다.","상부 정류장에서 전망대까지 계단으로 15분을 더 걸어야 한다."],"bestTime":"4~6월, 9~11월","visitDuration":"2~3시간","ticket":"케이블카 왕복 17,000원(성인)","openingHours":"09:30~17:00(계절에 따라 다름)","galleryCaptions":["정상에서 본 한려해상의 섬들"]},"ja":{"name":"統営弥勒山ロープウェー","summary":"山頂から見下ろすと、閑麗海上の数百の島が砕けた石のように海に散っている。","story":"統営は閑麗海上のただ中にある。数百の島が散らばる穏やかな海で、韓国の人々はよく「東洋のナポリ」と呼ぶ。その地形を掴む最良の方法は弥勒山の頂に立つことだ。2km近いロープウェーが十分で頂上近くまで運び、そこから展望台までさらに十五分歩く。展望台に立つと湾が開け、島々が水平線へ向かって淡く重なっていく。よく晴れた日には対馬も見える。山の下は魚市場と造船所、そして忠武キンパの街だ。","facts":["ロープウェーの長さは約1.975kmで、韓国でも最長級である。","弥勒山の頂は461mで、閑麗海上国立公園を見下ろす。","非常に晴れた日には日本の対馬が見える。","統営は作曲家・尹伊桑の故郷であり、忠武キンパの本場でもある。"],"travelTips":["週末はロープウェーを事前予約しよう。待ち時間が一時間に及ぶこともある。","強風時は運休する。おおむね午前が穏やかだ。","上部駅から展望台まで階段を15分ほど登る必要がある。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2〜3時間","ticket":"ケーブルカー往復17,000ウォン（大人）","openingHours":"09:30〜17:00（季節により変動）","galleryCaptions":["頂上から見た閑麗海上の島々"]},"zh":{"name":"統營彌勒山纜車","summary":"從山頂望下去，閑麗海上數百座島嶼像碎石般散在海面上。","story":"統營位於閑麗海上的正中央——一片風平浪靜、散布著數百座島嶼的海域，韓國人習慣稱它為「東方的那不勒斯」。要理解這樣的地形，最好的方式是登上彌勒山頂：一條近兩公里長的纜車十分鐘就把人送到山頂附近，再步行十五分鐘便是觀景台。從那裡望出去，整片海灣展開，島嶼一層層朝地平線淡去；天氣極好時甚至看得到對馬島。山腳下是一座有魚市、造船廠與著名忠武紫菜飯捲的城市。","facts":["纜車長約1.975公里，是韓國最長的路線之一。","彌勒山頂海拔461公尺，俯瞰閑麗海上國立公園。","天氣極為晴朗時可望見日本對馬島。","統營是作曲家尹伊桑的故鄉，也是忠武紫菜飯捲的發源地。"],"travelTips":["週末請先預訂纜車，排隊可能長達一小時。","強風時停駛，通常早上風勢較穩。","自上站到觀景台還要走約15分鐘階梯。"],"bestTime":"4至6月與9至11月","visitDuration":"2至3小時","ticket":"纜車來回17,000韓元（成人）","openingHours":"09:30–17:00（依季節調整）","galleryCaptions":["自山頂望見的閑麗海上群島"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('geoje-windy-hill', 'geoje-windy-hill', 'gyeongnam', 'Đồi Gió & bờ đá Geoje', 'Windy Hill & Geoje Coast', 'beach', 128.705, 34.79, 'Đồi cỏ trọc nhô ra biển với một cối xay gió gỗ, gió mạnh đến mức khó đứng thẳng.', 'Đúng như tên gọi, gió ở đây không ngừng. Đồi cỏ nhô ra biển ở mũi Dojangpo, trên đỉnh có một cối xay gió gỗ dựng làm cảnh, và cỏ thì luôn nằm rạp về một phía. Đứng đó nhìn ra là vùng biển Hallyeohaesang với đảo Oedo và Haegeumgang ngay ngoài khơi — Haegeumgang là hai khối đá tách đôi bởi một khe hẹp mà thuyền nhỏ chui qua được vào lúc nước lặng. Geoje là hòn đảo lớn thứ hai Hàn Quốc, nổi tiếng vì nhà máy đóng tàu, nhưng bờ nam của nó thì toàn vách đá và vịnh nhỏ.', '["Đồi Gió nằm ở mũi Dojangpo, đảo Geoje.","Geoje là đảo lớn thứ hai Hàn Quốc sau Jeju.","Ngoài khơi gần đó là Haegeumgang, khối đá tách đôi nổi tiếng.","Có thuyền du lịch đi Oedo và Haegeumgang xuất phát từ các bến gần đây."]', '["Giữ chặt mũ và điện thoại — gió ở đây thật sự mạnh.","Thuyền ra Haegeumgang huỷ chuyến khi biển động, hỏi bến trước.","Đường xuống bờ đá dốc và trơn khi mưa."]', 'Tháng 4–6 và 9–10', '1,5 giờ', '', 'Cả ngày', '["hidden-gem"]', '["biển","đồi cỏ","gió","đảo"]', '[{"seed":"geoje-windy-hill","caption":"Cối xay gió trên Đồi Gió","ratio":"16/9"}]', '["geoje-oedo","tongyeong-mireuksan"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Windy Hill & Geoje Coast","summary":"A bare grass hill running out to sea with a wooden windmill, and wind strong enough to make standing hard.","story":"The name is accurate: the wind here does not stop. The grass hill juts into the sea at Dojangpo point, a wooden windmill stands on top as scenery, and the grass lies permanently flat one way. Looking out you have the Hallyeohaesang sea with Oedo and Haegeumgang just offshore — Haegeumgang being two rock masses split by a gap narrow enough for a small boat to pass through in calm water. Geoje is Korea''s second largest island, known for its shipyards, but its southern coast is all cliffs and small bays.","facts":["Windy Hill stands at Dojangpo point on Geoje island.","Geoje is Korea''s second largest island after Jeju.","Haegeumgang, the famous split rock, lies just offshore nearby.","Tour boats to Oedo and Haegeumgang leave from harbours close by."],"travelTips":["Hold onto your hat and your phone — the wind is genuinely strong.","Boats to Haegeumgang cancel in rough sea; check at the harbour first.","The path down to the rocks is steep and slippery in rain."],"bestTime":"April–June and September–October","visitDuration":"1.5 hours","ticket":"","openingHours":"All day","galleryCaptions":["The windmill on Windy Hill"]},"ko":{"name":"거제 바람의 언덕과 해안","summary":"바다로 내민 민둥한 풀 언덕에 나무 풍차가 서 있다. 똑바로 서 있기 힘들 만큼 바람이 세다.","story":"이름 그대로다. 여기 바람은 멎지 않는다. 도장포의 풀 언덕이 바다로 내밀고, 꼭대기에는 풍경으로 세운 나무 풍차가 있으며, 풀은 늘 한쪽으로 누워 있다. 내다보면 한려해상 바다에 외도와 해금강이 바로 앞바다에 있다. 해금강은 물이 잔잔할 때 작은 배가 지날 만큼 좁은 틈으로 갈라진 두 덩이 바위다. 거제는 한국에서 두 번째로 큰 섬으로 조선소로 알려져 있지만, 남쪽 해안은 온통 절벽과 작은 만이다.","facts":["바람의 언덕은 거제도 도장포에 있다.","거제는 제주 다음으로 큰 한국의 섬이다.","가까운 앞바다에 갈라진 바위로 유명한 해금강이 있다.","인근 항구에서 외도와 해금강행 유람선이 출발한다."],"travelTips":["모자와 휴대전화를 꼭 잡자. 바람이 정말 세다.","파도가 높으면 해금강행 배는 결항한다. 항구에 먼저 확인하자.","바위로 내려가는 길은 가파르고 비 오면 미끄럽다."],"bestTime":"4~6월, 9~10월","visitDuration":"1.5시간","ticket":"","openingHours":"상시","galleryCaptions":["바람의 언덕 위의 풍차"]},"ja":{"name":"巨済「風の丘」と海岸","summary":"海へ突き出した草の丘に木の風車が立つ。まっすぐ立っていられないほど風が強い。","story":"名の通り、ここの風はやまない。道場浦の草の丘が海へ突き出し、頂には風景として据えられた木の風車が立ち、草はいつも一方へ倒れている。見晴らせば閑麗海上の海に外島と海金剛がすぐ沖にある。海金剛は、凪のときに小舟が通れるほど狭い隙間で割れた二つの岩塊だ。巨済は韓国で二番目に大きな島で造船所で知られるが、南の海岸は一面の断崖と小さな入り江である。","facts":["風の丘は巨済島の道場浦にある。","巨済は済州に次いで韓国で二番目に大きい島である。","近くの沖には、割れた岩で知られる海金剛がある。","周辺の港から外島・海金剛行きの遊覧船が出る。"],"travelTips":["帽子とスマートフォンをしっかり押さえよう。風は本当に強い。","波が高いと海金剛行きの船は欠航する。まず港で確認を。","岩場へ下る道は急で、雨の日は滑る。"],"bestTime":"4〜6月、9〜10月","visitDuration":"1.5時間","ticket":"","openingHours":"終日","galleryCaptions":["風の丘に立つ風車"]},"zh":{"name":"巨濟風之丘與海岸","summary":"一片光禿草丘伸進海裡，上頭立著木造風車，風大到讓人站不直。","story":"名副其實：這裡的風從不停。草丘在道場浦岬伸進海中，頂上立著一座作為造景的木造風車，草則永遠朝同一個方向倒伏。向外望去是閑麗海上，外島與海金剛就在近海——海金剛是兩塊被窄縫劈開的巨岩，風平浪靜時小船能從中穿過。巨濟是韓國第二大島，以造船廠聞名，但它的南岸盡是斷崖與小灣。","facts":["風之丘位於巨濟島的道場浦岬。","巨濟是繼濟州之後韓國第二大島。","附近海面上有以裂岩聞名的海金剛。","鄰近港口有前往外島與海金剛的遊船。"],"travelTips":["抓緊帽子與手機——這裡的風是真的強。","海象不佳時往海金剛的船會停航，先向碼頭確認。","下到岩岸的路很陡，下雨時濕滑。"],"bestTime":"4至6月與9至10月","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["風之丘上的風車"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('namhae-german-village', 'namhae-german-village', 'gyeongnam', 'Làng Đức Namhae', 'German Village, Namhae', 'village', 128.04, 34.798889, 'Làng mái ngói đỏ do những người đi làm thợ mỏ và y tá ở Đức trở về dựng lên bên bờ biển Namhae.', 'Thập niên 1960–70, hàng nghìn người Hàn sang Tây Đức làm thợ mỏ và y tá, gửi ngoại tệ về nước trong những năm nghèo nhất. Đầu những năm 2000, tỉnh Gyeongsangnam cấp đất cho những người trong số đó muốn về hưu ở quê nhà, và họ dựng nhà theo đúng lối Đức — mái ngói đỏ, tường trắng, cửa gỗ nhập từ Đức. Kết quả là một sườn đồi nhìn ra vịnh Namhae với vài chục ngôi nhà trông như vùng Bavaria. Nhiều nhà mở thành nhà nghỉ hoặc quán cà phê do chính chủ nhà lớn tuổi trông coi, và tháng 10 có lễ hội bia riêng.', '["Được lập đầu những năm 2000 cho người Hàn từng đi lao động ở Tây Đức trở về.","Nhà xây theo kiểu Đức, nhiều vật liệu nhập trực tiếp từ Đức.","Có bảo tàng nhỏ về lịch sử thợ mỏ và y tá người Hàn tại Đức.","Lễ hội bia Oktoberfest phiên bản Namhae tổ chức vào tháng 10."]', '["Kết hợp với ruộng bậc thang Daraengi cách đó khoảng 30 phút xe.","Đây là làng có người ở — chỉ vào các nhà có biển mở cửa.","Đường ven biển Namhae rất đẹp nhưng nhiều khúc cua, lái chậm."]', 'Tháng 4–6, 9–10 (lễ hội bia tháng 10)', '1,5–2 giờ', '', 'Cả ngày (bảo tàng 09:00–18:00)', '["hidden-gem"]', '["làng","di dân","biển","kiến trúc"]', '[{"seed":"namhae-german-village","caption":"Mái ngói đỏ nhìn ra vịnh Namhae","ratio":"16/9"}]', '["namhae-daraengi"]', 0, 'https://en.wikipedia.org/wiki/Namhae_German_Village', '2026-08-04', '{"en":{"name":"German Village, Namhae","summary":"A village of red-tiled roofs built on the Namhae coast by returning miners and nurses who had worked in Germany.","story":"In the 1960s and 70s thousands of Koreans went to West Germany as miners and nurses, sending hard currency home through the country''s poorest years. In the early 2000s South Gyeongsang province granted land to those among them who wanted to retire back home, and they built in the German manner — red tiles, white walls, timber joinery imported from Germany. The result is a hillside above Namhae bay holding a few dozen houses that look like Bavaria. Many are now guesthouses or cafés run by the elderly owners themselves, and there is a beer festival each October.","facts":["Established in the early 2000s for Koreans returning from working in West Germany.","The houses are built in German style, with much of the material imported from Germany.","A small museum covers the history of Korean miners and nurses in Germany.","A Namhae version of Oktoberfest is held each October."],"travelTips":["Combine it with the Daraengi terraced fields, about 30 minutes away by car.","People live here — only enter houses with an open sign.","The Namhae coast road is beautiful but full of bends; drive slowly."],"bestTime":"April–June and September–October (beer festival in October)","visitDuration":"1.5–2 hours","ticket":"","openingHours":"All day (museum 09:00–18:00)","galleryCaptions":["Red roofs above Namhae bay"]},"ko":{"name":"남해 독일마을","summary":"독일에서 광부와 간호사로 일하고 돌아온 사람들이 남해 바닷가에 세운 붉은 기와 마을.","story":"1960~70년대 수천 명의 한국인이 서독으로 건너가 광부와 간호사로 일했고, 나라가 가장 가난하던 시절에 외화를 보내왔다. 2000년대 초 경상남도는 그들 가운데 고향에서 노년을 보내고 싶어 하는 이들에게 땅을 내주었고, 그들은 독일식으로 집을 지었다. 붉은 기와, 흰 벽, 독일에서 들여온 목재 창호. 그렇게 남해만이 내려다보이는 비탈에 바이에른처럼 보이는 집 수십 채가 생겼다. 여러 채는 나이 든 주인이 직접 꾸리는 민박과 카페가 되었고, 10월에는 맥주 축제가 열린다.","facts":["2000년대 초, 서독에서 일하고 돌아온 한국인들을 위해 조성되었다.","집은 독일식으로 지어졌고 자재 상당수를 독일에서 들여왔다.","독일에서 일한 한국인 광부와 간호사의 역사를 다룬 작은 전시관이 있다.","해마다 10월에 남해판 옥토버페스트가 열린다."],"travelTips":["차로 30분 거리의 다랭이마을과 묶어서 보자.","사람이 사는 마을이다. 영업 표시가 있는 집에만 들어가자.","남해 해안도로는 아름답지만 굽이가 많다. 천천히 달리자."],"bestTime":"4~6월, 9~10월(10월에 맥주 축제)","visitDuration":"1.5~2시간","ticket":"","openingHours":"상시(전시관 09:00~18:00)","galleryCaptions":["남해만을 내려다보는 붉은 지붕"]},"ja":{"name":"南海ドイツ村","summary":"ドイツで炭鉱夫や看護師として働き帰ってきた人々が、南海の海辺に建てた赤瓦の村。","story":"1960〜70年代、数千人の韓国人が西ドイツへ渡り炭鉱夫や看護師として働き、国が最も貧しかった時代に外貨を送り続けた。2000年代初め、慶尚南道は彼らのうち故郷で老後を過ごしたい人に土地を分け、彼らはドイツ式に家を建てた。赤い瓦、白い壁、ドイツから取り寄せた木の建具。こうして南海湾を見下ろす斜面に、バイエルンのように見える数十軒が生まれた。多くは年配の家主自身が営む民宿やカフェになり、十月にはビール祭りが開かれる。","facts":["2000年代初め、西ドイツで働いて帰国した韓国人のために造成された。","家はドイツ式で建てられ、資材の多くをドイツから輸入した。","ドイツで働いた韓国人炭鉱夫と看護師の歴史を扱う小さな展示館がある。","毎年10月に南海版オクトーバーフェストが開かれる。"],"travelTips":["車で30分のタレンイ棚田村と合わせて回ろう。","人が暮らす村だ。営業の表示がある家にだけ入ろう。","南海の海岸道路は美しいがカーブが多い。ゆっくり走ろう。"],"bestTime":"4〜6月、9〜10月（10月にビール祭り）","visitDuration":"1.5〜2時間","ticket":"","openingHours":"終日（展示館は09:00〜18:00）","galleryCaptions":["南海湾を見下ろす赤い屋根"]},"zh":{"name":"南海德國村","summary":"曾赴德國當礦工與護士的人們回鄉後，在南海海邊蓋起的紅瓦村落。","story":"1960至70年代，數千名韓國人前往西德擔任礦工與護士，在國家最窮的年頭把外匯寄回家。2000年代初，慶尚南道撥地給其中想回故鄉養老的人，他們便照德國的樣式蓋房：紅瓦、白牆、自德國進口的木製門窗。於是俯瞰南海灣的山坡上，出現了數十棟看起來像巴伐利亞的房子。許多如今由年長屋主自己經營成民宿或咖啡館，每年十月還有啤酒節。","facts":["2000年代初為自西德工作返鄉的韓國人所設。","房舍採德國樣式，許多建材直接自德國進口。","設有小型展館，介紹韓國礦工與護士在德國的歷史。","每年10月舉辦南海版的啤酒節。"],"travelTips":["可與車程約30分鐘的多樂伊梯田村排在一起。","這是有人居住的村子，只進有營業標示的房舍。","南海海岸公路很美但彎道多，請放慢速度。"],"bestTime":"4至6月與9至10月（10月有啤酒節）","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日開放（展館09:00–18:00）","galleryCaptions":["俯瞰南海灣的紅屋頂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('haeundae-beach', 'haeundae-beach', 'busan', 'Bãi biển Haeundae', 'Haeundae Beach', 'beach', 129.16, 35.1587, 'Bãi tắm nổi tiếng nhất Hàn Quốc, cát vàng cong hình lưỡi liềm dưới chân rừng cao ốc.', 'Mùa hè, Haeundae là một biển dù xanh trắng xếp sát nhau, tiếng loa, tiếng sóng và mùi hải sản nướng. Ngoài mùa cao điểm, bãi biển trở lại là nơi người Busan đi bộ buổi sáng, và con đường ven biển dẫn sang Dongbaekseom — hòn đảo cũ nay dính vào bờ, có lối đi lát gỗ vòng quanh vách đá nhìn thẳng ra cầu Gwangan. Phía sau bãi là chợ Haeundae và những ngõ nhỏ bán bánh cá, còn phía đông là tuyến đường sắt ven biển cũ đã thành đường đi bộ ngắm biển.', '["Bãi dài khoảng 1,5 km, là bãi tắm đông khách nhất Hàn Quốc mỗi mùa hè.","Lễ hội biển Busan và lễ hội cát diễn ra tại đây hằng năm.","Đảo Dongbaekseom ngay cạnh có đường dạo ven vách đá và tháp APEC.","Tuyến tàu Blue Line Park chạy dọc bờ biển cũ về hướng Songjeong."]', '["Tháng 7–8 rất đông; tháng 6 và tháng 9 nước vẫn ấm mà vắng hơn nhiều.","Đi tàu Blue Line Park lúc chiều muộn để ngắm biển từ toa kính.","Tàu điện tuyến 2 tới ga Haeundae rồi đi bộ 10 phút."]', 'Tháng 6–9', '2–4 giờ', '', 'Cả ngày', '["popular"]', '["bãi biển","mùa hè","thành phố biển"]', '[{"seed":"haeundae-beach","caption":"Bãi Haeundae nhìn từ Dongbaekseom","ratio":"16/9"}]', '["gwangalli-beach","haedong-yonggungsa"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Haeundae Beach","summary":"Korea''s most famous beach, a crescent of golden sand under a wall of high-rises.","story":"In summer Haeundae is a solid field of blue-and-white parasols, loudspeakers, surf and grilled seafood. Out of season it goes back to being where Busan walks in the morning, and the coastal path leads on to Dongbaekseom — once an island, now joined to the shore — with a boardwalk around the cliffs looking straight at Gwangan Bridge. Behind the sand is Haeundae market and lanes of fish-cake shops; to the east, a disused coastal railway has become a walking line above the sea.","facts":["The beach runs about 1.5 km and is the busiest in Korea each summer.","The Busan Sea Festival and the sand festival are both held here.","Dongbaekseom next door has a cliffside walkway and the APEC House.","The Blue Line Park train runs along the old coastal railway towards Songjeong."],"travelTips":["July–August is packed; June and September have warm water and far fewer people.","Ride the Blue Line Park train late in the afternoon for sea views from a glass carriage.","Metro Line 2 to Haeundae station, then a ten-minute walk."],"bestTime":"June–September","visitDuration":"2–4 hours","ticket":"","openingHours":"All day","galleryCaptions":["Haeundae beach from Dongbaekseom"]},"ko":{"name":"해운대해수욕장","summary":"한국에서 가장 유명한 해변. 고층 건물 아래 초승달 모양의 백사장이 펼쳐진다.","story":"여름의 해운대는 파란 파라솔이 빼곡한 벌판이 된다. 확성기 소리와 파도, 해산물 굽는 냄새가 뒤섞인다. 성수기가 지나면 다시 부산 사람들의 아침 산책길로 돌아가고, 해안길은 동백섬으로 이어진다. 원래 섬이었다가 뭍에 붙은 이곳에는 광안대교를 정면으로 보는 벼랑길이 놓여 있다. 백사장 뒤로는 해운대시장과 어묵집 골목이, 동쪽으로는 폐선된 해안 철길이 바다 위 산책로가 되어 있다.","facts":["해변 길이 약 1.5km로 매년 여름 한국에서 가장 붐빈다.","부산바다축제와 모래축제가 이곳에서 열린다.","옆의 동백섬에는 해안 산책로와 누리마루 APEC하우스가 있다.","옛 동해남부선 철길을 활용한 블루라인파크 열차가 송정 방향으로 달린다."],"travelTips":["7~8월은 매우 붐빈다. 6월과 9월은 물이 따뜻하면서도 한산하다.","늦은 오후에 블루라인파크 열차를 타면 유리창 너머 바다가 좋다.","2호선 해운대역에서 도보 10분이다."],"bestTime":"6~9월","visitDuration":"2~4시간","ticket":"","openingHours":"상시","galleryCaptions":["동백섬에서 본 해운대 해변"]},"ja":{"name":"海雲台海水浴場","summary":"韓国で最も有名な浜。高層ビルの壁の下に三日月形の砂浜が広がる。","story":"夏の海雲台は青と白のパラソルで埋まる野原になる。拡声器の声と波、海鮮を焼く匂いが入り混じる。最盛期を過ぎれば、また釜山の人の朝の散歩道に戻り、海岸路は冬柏島へ続く。もとは島で今は陸続きのこの場所には、広安大橋を正面に望む断崖の遊歩道がある。砂浜の裏には海雲台市場とおでん屋の路地、東には廃線になった海岸鉄道が海の上の散歩道になっている。","facts":["砂浜は約1.5kmで、毎年夏に韓国で最も混雑する。","釜山海祭りと砂祭りがここで開かれる。","隣の冬柏島には断崖の遊歩道とヌリマルAPECハウスがある。","旧東海南部線を活用したブルーラインパークの列車が松亭方面へ走る。"],"travelTips":["7〜8月は非常に混む。6月と9月は水が暖かく人が少ない。","午後遅くにブルーラインパークの列車に乗れば車窓の海が良い。","2号線海雲台駅から徒歩10分。"],"bestTime":"6〜9月","visitDuration":"2〜4時間","ticket":"","openingHours":"終日","galleryCaptions":["冬柏島から見た海雲台の浜"]},"zh":{"name":"海雲台海水浴場","summary":"韓國最著名的海灘，一彎金沙躺在高樓之牆下。","story":"夏天的海雲台是一整片藍白相間的遮陽傘，擴音器、浪聲與烤海鮮的香氣混在一起。旺季過後，它回到釜山人晨間散步的樣子，海岸步道通往冬柏島——它曾是座島，如今與陸地相連，環崖木棧道正對廣安大橋。沙灘後方是海雲台市場與魚糕店的巷弄；往東，一段廢棄的海岸鐵道成了臨海步道。","facts":["沙灘約長1.5公里，是韓國每年夏天最擁擠的海灘。","釜山海洋節與沙雕節都在此舉行。","隔壁的冬柏島有臨崖步道與APEC世峰樓。","藍線公園列車沿舊海岸鐵道往松亭方向行駛。"],"travelTips":["七、八月人潮洶湧；六月與九月水溫仍暖但人少得多。","傍晚搭藍線公園列車，可從玻璃車廂看海。","地鐵2號線海雲台站步行十分鐘可達。"],"bestTime":"6至9月","visitDuration":"2至4小時","ticket":"","openingHours":"全日","galleryCaptions":["自冬柏島望向海雲台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gamcheon-culture-village', 'gamcheon-culture-village', 'busan', 'Làng văn hoá Gamcheon', 'Gamcheon Culture Village', 'village', 129.0107, 35.0975, 'Khu nhà bậc thang sơn đủ màu bám sườn đồi, từ xóm tị nạn thành làng nghệ thuật.', 'Sau Chiến tranh Triều Tiên, người tị nạn dựng nhà chen chúc trên sườn đồi này, mái nọ nối mái kia thành từng bậc. Năm 2009 một dự án nghệ thuật cộng đồng sơn lại toàn bộ nhà cửa và mời hoạ sĩ vào ở; hôm nay các ngõ hẹp đầy tranh tường, tượng nhỏ, quán cà phê nhìn xuống thung lũng. Bức tượng Hoàng tử bé ngồi trên lan can là chỗ xếp hàng chụp ảnh đông nhất. Cư dân vẫn sống ở đây, nên biển nhắc giữ yên lặng treo khắp nơi.', '["Hình thành từ thập niên 1950 bởi người tị nạn chiến tranh.","Được cải tạo thành làng nghệ thuật từ năm 2009.","Nhà được sơn theo bảng màu thống nhất để nhìn từ xa thành một khối.","Có bản đồ đóng dấu (stamp map) bán ở cổng để đi tìm các điểm nghệ thuật."]', '["Đi bus nhỏ từ ga Toseong (tuyến 1) lên đỉnh làng rồi đi bộ xuống dốc.","Ngõ rất hẹp và dốc — giày bám tốt là cần thiết.","Buổi chiều ánh nắng xiên làm màu nhà lên đẹp nhất."]', 'Quanh năm', '2–3 giờ', '', 'Làng mở tự do cả ngày; trung tâm hướng dẫn và đài quan sát Haneulmaru 09:00–16:00', '["popular","trending"]', '["nghệ thuật","nhiếp ảnh","làng"]', '[{"seed":"gamcheon-culture-village","caption":"Nhà nhiều màu trên sườn đồi","ratio":"16/9"}]', '["jagalchi-market"]', 1, 'https://www.gamcheon.or.kr/', '2026-08-04', '{"en":{"name":"Gamcheon Culture Village","summary":"Stepped houses painted in every colour on a hillside, once a refugee settlement, now an art village.","story":"After the Korean War, refugees packed houses onto this slope, roof stacked above roof in terraces. In 2009 a community art project repainted the whole village and invited artists to move in; today the narrow lanes are full of murals, small sculptures and cafés looking down the valley. The Little Prince statue on the railing draws the longest photo queue. Residents still live here, which is why signs asking for quiet hang everywhere.","facts":["Formed in the 1950s by refugees from the war.","Regenerated as an art village from 2009.","The houses are painted from a coordinated palette so they read as one composition from afar.","A stamp map is sold at the entrance for finding the art installations."],"travelTips":["Take a minibus from Toseong station (Line 1) to the top and walk down.","The lanes are narrow and steep — shoes with grip help.","Afternoon light brings out the colours best."],"bestTime":"Year-round","visitDuration":"2–3 hours","ticket":"","openingHours":"The village is open all day; the information centre and Haneulmaru viewpoint run 09:00–16:00","galleryCaptions":["Painted houses on the hillside"]},"ko":{"name":"감천문화마을","summary":"산비탈에 층층이 선 알록달록한 집들. 피란민촌에서 예술마을이 되었다.","story":"한국전쟁 뒤 피란민들이 이 비탈에 집을 지으면서 지붕 위에 지붕이 얹히듯 계단식 마을이 만들어졌다. 2009년 마을미술 프로젝트로 집들을 다시 칠하고 작가들을 불러들이면서, 지금은 좁은 골목마다 벽화와 작은 조형물, 골짜기를 내려다보는 카페가 들어섰다. 난간에 앉은 어린왕자 조형물 앞은 사진 줄이 가장 길다. 주민들이 실제로 살고 있어 조용히 해달라는 안내가 곳곳에 붙어 있다.","facts":["1950년대 전쟁 피란민들이 형성한 마을이다.","2009년부터 예술마을로 재생되었다.","멀리서도 하나의 그림처럼 보이도록 통일된 색으로 칠했다.","입구에서 파는 스탬프 지도로 예술 작품을 찾아다닐 수 있다."],"travelTips":["1호선 토성역에서 마을버스로 정상까지 올라가 걸어 내려오자.","골목이 좁고 가파르니 접지력 좋은 신발이 좋다.","오후 햇빛에 색이 가장 잘 산다."],"bestTime":"연중","visitDuration":"2~3시간","ticket":"","openingHours":"마을은 상시 개방, 안내센터와 하늘마루 전망대는 09:00~16:00","galleryCaptions":["비탈의 알록달록한 집들"]},"ja":{"name":"甘川文化村","summary":"斜面に段々に建つ色とりどりの家。避難民の集落から芸術村になった。","story":"朝鮮戦争のあと、避難民がこの斜面に家を建て、屋根の上に屋根が重なるような階段状の村ができた。2009年の村アートプロジェクトで家々を塗り直し作家を招いた結果、今では狭い路地に壁画や小さなオブジェ、谷を見下ろすカフェが並ぶ。手すりに座る星の王子さまの像の前は写真の列が最も長い。住民が実際に暮らしているので、静かにと促す掲示が至るところにある。","facts":["1950年代に戦争避難民が形成した集落。","2009年から芸術村として再生された。","遠くから一枚の絵に見えるよう統一した色で塗られている。","入口で売るスタンプ地図でアート作品を巡れる。"],"travelTips":["1号線土城駅から村バスで頂上まで上がり、歩いて下るとよい。","路地が狭く急なのでグリップの利く靴を。","午後の光で色が最も映える。"],"bestTime":"通年","visitDuration":"2〜3時間","ticket":"","openingHours":"村は終日開放、案内センターとハヌルマル展望台は09:00〜16:00","galleryCaptions":["斜面に並ぶ色とりどりの家"]},"zh":{"name":"甘川文化村","summary":"沿山坡層疊的彩色房舍，從難民聚落變成藝術村。","story":"韓戰之後，難民在這片山坡上蓋房，一層屋頂疊著另一層，形成階梯狀的聚落。2009年一項社區藝術計畫替整村重新上色並邀請藝術家進駐；如今狹窄巷弄裡滿是壁畫、小型雕塑與俯瞰山谷的咖啡館。坐在欄杆上的小王子雕像前排隊拍照的人最多。居民仍住在這裡，因此到處掛著請安靜的告示。","facts":["由1950年代的戰爭難民所形成。","自2009年起再生為藝術村。","房屋依統一色盤上色，遠望時如同一幅畫。","入口販售蓋章地圖，可循線尋找藝術作品。"],"travelTips":["自1號線土城站搭社區小巴上到村頂，再步行下山。","巷弄狹窄陡峭，建議穿抓地力好的鞋。","午後的光線最能襯出色彩。"],"bestTime":"全年","visitDuration":"2至3小時","ticket":"","openingHours":"村落全日開放；遊客中心與天空瞭望台為09:00–16:00","galleryCaptions":["山坡上的彩色房舍"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jagalchi-market', 'jagalchi-market', 'busan', 'Chợ cá Jagalchi', 'Jagalchi Fish Market', 'market', 129.0304, 35.0967, 'Chợ hải sản lớn nhất Hàn Quốc, nơi bạn chọn cá dưới tầng rồi mang lên tầng trên ăn ngay.', 'Jagalchi do những người phụ nữ bán cá — jagalchi ajumma — gây dựng sau chiến tranh, và đến giờ vẫn là họ đứng sau các bể nước. Tầng trệt là hàng trăm quầy bạch tuộc, cá bơn, hải sâm, ốc; bạn chỉ tay chọn con mình muốn, họ làm ngay tại chỗ rồi bạn bê lên tầng hai, trả thêm tiền công chế biến và có ngay một mâm sashimi. Ngoài cửa là cảng cá Nampo, sáng sớm tàu về, tiếng đấu giá vang cả dãy phố.', '["Là chợ hải sản lớn nhất Hàn Quốc, hoạt động từ sau năm 1945.","Toà nhà chợ hiện tại mang hình sóng biển, khánh thành năm 2006.","Tầng 1 bán hải sản sống, tầng 2 là các quán chế biến tại chỗ.","Lễ hội chợ Jagalchi tổ chức vào tháng 10 hằng năm."]', '["Hỏi giá và chốt tiền công chế biến trước khi họ mổ cá.","Đi sớm (trước 9h) để thấy nhịp chợ thật sự.","Kết hợp với phố Gukje và BIFF Square ngay cạnh."]', 'Quanh năm', '1,5–2 giờ', '', '05:00–22:00, nghỉ thứ Ba tuần thứ nhất và thứ ba hằng tháng', '["verified"]', '["hải sản","chợ","ẩm thực"]', '[{"seed":"jagalchi-market","caption":"Quầy hải sản sống ở Jagalchi","ratio":"16/9"}]', '["gamcheon-culture-village"]', 0, 'https://www.bisco.or.kr/jagalchimarket/sub/sub02/sub02_1/', '2026-08-04', '{"en":{"name":"Jagalchi Fish Market","summary":"Korea''s largest seafood market, where you pick your fish downstairs and eat it upstairs.","story":"Jagalchi was built up after the war by the women who sold the fish — the jagalchi ajumma — and it is still they who stand behind the tanks. The ground floor is hundreds of stalls of octopus, flounder, sea cucumber and shellfish; you point at what you want, they prepare it on the spot, and you carry it upstairs where a small fee turns it into a plate of sashimi. Outside is Nampo fishing harbour, where the boats come in at dawn and the auction rings down the quay.","facts":["The largest seafood market in Korea, trading since 1945.","The current building, shaped like a wave, opened in 2006.","Level one sells live seafood; level two prepares it for you.","The Jagalchi Festival is held each October."],"travelTips":["Agree the price and the preparation fee before anything is cut.","Come before 9am to see the market working properly.","Combine with Gukje Market and BIFF Square next door."],"bestTime":"Year-round","visitDuration":"1.5–2 hours","ticket":"","openingHours":"05:00–22:00, closed the first and third Tuesday of each month","galleryCaptions":["Live seafood stalls at Jagalchi"]},"ko":{"name":"자갈치시장","summary":"한국 최대의 수산시장. 1층에서 고르고 2층에서 바로 먹는다.","story":"자갈치는 전쟁 뒤 생선을 팔던 여인들, 자갈치 아지매들이 일으켜 세웠고 지금도 수조 뒤에는 그들이 서 있다. 1층에는 낙지와 광어, 해삼, 조개를 파는 수백 개의 좌판이 늘어서 있다. 원하는 것을 가리키면 그 자리에서 손질해 주고, 2층으로 올려 상차림비를 내면 회 한 상이 된다. 밖에는 남포 어항이 있어 새벽이면 배가 들어오고 부둣가를 따라 경매 소리가 울린다.","facts":["1945년 이후 이어진 한국 최대의 수산시장이다.","파도 형상의 현재 건물은 2006년에 지어졌다.","1층은 활어 판매, 2층은 조리 식당가다.","자갈치축제가 매년 10월에 열린다."],"travelTips":["손질 전에 가격과 상차림비를 먼저 정하자.","오전 9시 전에 가면 시장이 제대로 돌아가는 모습을 볼 수 있다.","바로 옆 국제시장, BIFF광장과 묶어 보자."],"bestTime":"연중","visitDuration":"1시간 30분~2시간","ticket":"","openingHours":"05:00~22:00, 매월 첫째·셋째 화요일 휴무","galleryCaptions":["자갈치시장의 활어 좌판"]},"ja":{"name":"チャガルチ市場","summary":"韓国最大の水産市場。一階で選び、二階でそのまま食べる。","story":"チャガルチは戦後に魚を売った女性たち、チャガルチ・アジメが築き上げ、今も水槽の後ろに立つのは彼女たちだ。一階にはタコやヒラメ、ナマコ、貝を売る何百もの台が並ぶ。指させばその場でさばいてくれ、二階に上げて調理代を払えば刺身の膳になる。外には南浦の漁港があり、夜明けに船が入ると岸壁沿いに競りの声が響く。","facts":["1945年以降続く韓国最大の水産市場。","波を象った現在の建物は2006年竣工。","1階は活魚販売、2階は調理して出す食堂街。","チャガルチ祭りは毎年10月に開かれる。"],"travelTips":["さばいてもらう前に値段と調理代を決めておこう。","午前9時前なら市場が本来の姿で動いている。","隣の国際市場やBIFF広場と合わせて。"],"bestTime":"通年","visitDuration":"1時間30分〜2時間","ticket":"","openingHours":"05:00〜22:00、毎月第1・第3火曜休み","galleryCaptions":["チャガルチ市場の活魚売り場"]},"zh":{"name":"札嘎其市場","summary":"韓國最大的海鮮市場，樓下挑、樓上吃。","story":"札嘎其是戰後賣魚的女性們——札嘎其阿嬤——一手撐起來的，至今站在水槽後方的仍是她們。一樓是數百個攤位，章魚、比目魚、海參與貝類任你挑；指一指要哪隻，她們當場處理，你再端到二樓，付一點料理費就成了一桌生魚片。市場外是南浦漁港，天亮前漁船進港，拍賣聲沿著碼頭響起。","facts":["韓國最大的海鮮市場，自1945年後持續營運。","現在如波浪造型的建築落成於2006年。","一樓賣活海鮮，二樓為代客料理的食堂。","札嘎其慶典每年十月舉行。"],"travelTips":["動刀前先談好價錢與料理費。","上午九點前來，才看得到市場真正運作的樣子。","可與隔壁的國際市場與BIFF廣場一併逛。"],"bestTime":"全年","visitDuration":"1.5至2小時","ticket":"","openingHours":"05:00–22:00，每月第一和第三個週二休市","galleryCaptions":["札嘎其市場的活海鮮攤"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('haedong-yonggungsa', 'haedong-yonggungsa', 'busan', 'Chùa Haedong Yonggungsa', 'Haedong Yonggungsa Temple', 'temple', 129.2234, 35.1884, 'Ngôi chùa hiếm hoi dựng sát mép sóng thay vì trên núi, đón bình minh đầu tiên của Busan.', 'Phần lớn chùa Hàn Quốc nằm sâu trong núi; Yonggungsa thì bám vào ghềnh đá nhìn thẳng ra biển Đông. Xuống 108 bậc đá — tượng trưng cho 108 phiền não — bạn tới sân chùa nơi sóng đập vào chân tường. Người ta tin rằng cầu nguyện ở đây sẽ được toại nguyện một điều, nên tượng Phật ven biển lúc nào cũng có người vái. Đẹp nhất là lúc mặt trời mọc, hoặc dịp lễ Phật đản khi hàng nghìn đèn lồng giấy phủ kín mọi lối đi.', '["Được dựng lần đầu năm 1376 dưới triều Goryeo.","Là một trong số rất ít chùa Hàn Quốc nằm ngay sát biển.","Lối vào có 108 bậc đá tượng trưng cho 108 phiền não.","Rất đông vào dịp Phật đản và ngày đầu năm mới."]', '["Đi sớm lúc bình minh để tránh đông và có ánh sáng đẹp nhất.","Từ Haeundae đi bus 181 khoảng 30 phút.","Đường trong chùa nhiều bậc đá trơn khi mưa."]', 'Quanh năm; tháng 4–5 có lễ đèn lồng', '1,5 giờ', '', '04:30–19:00 hằng ngày', '["popular"]', '["chùa","biển","bình minh"]', '[{"seed":"haedong-yonggungsa","caption":"Chùa bên ghềnh đá","ratio":"16/9"}]', '["haeundae-beach"]', 0, 'https://breezekorea.com/haedong-yonggungsa-temple/', '2026-08-04', '{"en":{"name":"Haedong Yonggungsa Temple","summary":"A rare temple built at the water''s edge rather than in the mountains, catching Busan''s first sunrise.","story":"Most Korean temples sit deep in the hills; Yonggungsa clings to the rocks facing the East Sea. You descend 108 steps — one for each affliction — to a courtyard where waves break against the wall. It is said that a prayer offered here will grant one wish, so there is always someone bowing before the seaside Buddha. It is at its best at sunrise, or at Buddha''s Birthday when thousands of paper lanterns cover every path.","facts":["First founded in 1376 during the Goryeo dynasty.","One of very few Korean temples built right on the sea.","The entrance has 108 stone steps, for the 108 afflictions.","Extremely busy at Buddha''s Birthday and on New Year''s Day."],"travelTips":["Come at sunrise for the light and the smaller crowd.","Bus 181 from Haeundae takes about 30 minutes.","The stone steps are slippery in the rain."],"bestTime":"Year-round; lantern season in April–May","visitDuration":"1.5 hours","ticket":"","openingHours":"04:30–19:00 daily","galleryCaptions":["The temple on its sea rocks"]},"ko":{"name":"해동용궁사","summary":"산이 아니라 파도 곁에 세운 드문 절. 부산의 첫 해를 맞는다.","story":"한국의 절은 대개 산속 깊이 있지만 용궁사는 동해를 정면으로 보는 바위 벼랑에 붙어 있다. 108가지 번뇌를 뜻하는 108계단을 내려가면 파도가 담장을 때리는 마당에 닿는다. 이곳에서 기도하면 한 가지 소원은 이뤄진다고 하여 바닷가 불상 앞에는 늘 절하는 사람이 있다. 해돋이 때가 가장 아름답고, 부처님오신날이면 수천 개의 연등이 모든 길을 덮는다.","facts":["1376년 고려 때 처음 창건되었다.","바다에 바로 면한 한국의 몇 안 되는 사찰이다.","입구에 108번뇌를 뜻하는 108개의 돌계단이 있다.","부처님오신날과 새해 첫날에는 매우 붐빈다."],"travelTips":["일출 시간에 맞춰 가면 빛도 좋고 사람도 적다.","해운대에서 181번 버스로 약 30분이다.","비 오는 날에는 돌계단이 미끄럽다."],"bestTime":"연중, 4~5월 연등 시기","visitDuration":"1시간 30분","ticket":"","openingHours":"매일 04:30~19:00","galleryCaptions":["바위 벼랑 위의 사찰"]},"ja":{"name":"海東龍宮寺","summary":"山ではなく波打ち際に建つ珍しい寺。釜山の最初の日の出を迎える。","story":"韓国の寺はたいてい山の奥にあるが、龍宮寺は東海を正面に望む岩の崖に張りついている。百八の煩悩を表す108段を下りると、波が塀を叩く境内に出る。ここで祈れば一つだけ願いが叶うといわれ、海辺の仏像の前にはいつも礼拝する人がいる。日の出の時が最も美しく、灌仏会には数千の提灯がすべての道を覆う。","facts":["1376年、高麗時代に最初に創建された。","海に直接面した韓国では数少ない寺院。","入口には108の煩悩を表す108段の石段がある。","灌仏会と元日は非常に混雑する。"],"travelTips":["日の出の時間に行けば光も良く人も少ない。","海雲台から181番バスで約30分。","雨の日は石段が滑りやすい。"],"bestTime":"通年、4〜5月の提灯の時期","visitDuration":"1時間30分","ticket":"","openingHours":"毎日04:30〜19:00","galleryCaptions":["岩の崖の上の寺"]},"zh":{"name":"海東龍宮寺","summary":"少見蓋在浪邊而非山中的寺院，迎接釜山的第一道日出。","story":"韓國的寺院多半深藏山中，龍宮寺卻攀在正對東海的岩崖上。走下一百零八級石階——象徵一百零八種煩惱——來到浪花拍打牆腳的庭院。人們相信在這裡祈願可得一願，因此海邊的佛像前總有人合掌。日出時最美；佛誕日時，數千盞紙燈籠鋪滿每一條步道。","facts":["始建於高麗時期的1376年。","是韓國極少數緊臨海邊的寺院之一。","入口有108級石階，象徵108種煩惱。","佛誕日與元旦時人潮極多。"],"travelTips":["日出時前來，光線好、人也少。","自海雲台搭181號公車約30分鐘。","雨天石階濕滑。"],"bestTime":"全年；4至5月為燈籠季","visitDuration":"1.5小時","ticket":"","openingHours":"每日04:30–19:00","galleryCaptions":["岩崖上的寺院"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('gwangalli-beach', 'gwangalli-beach', 'busan', 'Bãi biển Gwangalli & cầu Gwangan', 'Gwangalli Beach & Gwangan Bridge', 'beach', 129.118, 35.1532, 'Bãi biển nhìn thẳng ra cây cầu treo hai tầng, nơi Busan bắn drone và pháo hoa mỗi cuối tuần.', 'Gwangalli nhỏ hơn Haeundae nhưng có thứ Haeundae không có: cả một cây cầu dài 7,4 km giăng ngang tầm mắt, đèn đổi màu suốt đêm. Dãy quán cà phê và quán nhậu dọc bờ đều hướng mặt kính ra biển, và tối thứ Bảy thành phố thường tổ chức màn trình diễn drone ngay trên mặt nước. Cuối tháng 10, lễ hội pháo hoa Busan biến bãi biển này thành khán đài lớn nhất thành phố — đến trước vài tiếng mới có chỗ ngồi.', '["Cầu Gwangan dài 7,42 km, là cầu treo hai tầng đầu tiên của Hàn Quốc.","Đèn cầu đổi màu theo ngày trong tuần và theo mùa.","Lễ hội pháo hoa Busan diễn ra vào cuối tháng 10.","Màn trình diễn drone thường tổ chức tối cuối tuần trên mặt vịnh."]', '["Đặt bàn quán ven biển trước nếu muốn xem pháo hoa từ trong nhà.","Tàu điện tuyến 2 tới ga Gwangan, đi bộ khoảng 10 phút.","Ban đêm là lúc đáng đến nhất, khác hẳn ban ngày."]', 'Tháng 5–10, tối cuối tuần', '2 giờ', '', 'Cả ngày', '["trending"]', '["biển","về đêm","pháo hoa"]', '[{"seed":"gwangalli-beach","caption":"Cầu Gwangan nhìn từ bãi biển","ratio":"16/9"}]', '["haeundae-beach"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Gwangalli Beach & Gwangan Bridge","summary":"A beach facing a two-tier suspension bridge, where Busan flies drones and fireworks every weekend.","story":"Gwangalli is smaller than Haeundae but has something Haeundae doesn''t: a 7.4 km bridge strung across the eye line, its lights changing colour all night. The cafés and bars along the shore all face the water through glass, and on Saturday evenings the city usually stages a drone show over the bay. In late October the Busan Fireworks Festival turns this beach into the city''s biggest grandstand — arrive hours early for a seat.","facts":["Gwangan Bridge is 7.42 km long, Korea''s first two-tier suspension bridge.","Its lights change colour by day of the week and by season.","The Busan Fireworks Festival takes place in late October.","Drone shows are usually held over the bay on weekend evenings."],"travelTips":["Book a seafront restaurant in advance if you want to watch fireworks indoors.","Metro Line 2 to Gwangan station, then a ten-minute walk.","Night is the time to come — it is a different place from the daytime."],"bestTime":"May–October, weekend evenings","visitDuration":"2 hours","ticket":"","openingHours":"All day","galleryCaptions":["Gwangan Bridge from the beach"]},"ko":{"name":"광안리해수욕장과 광안대교","summary":"2층 현수교를 마주 보는 해변. 주말마다 드론쇼와 불꽃이 오른다.","story":"광안리는 해운대보다 작지만 해운대에 없는 것이 있다. 눈높이를 가로지르는 7.4km의 다리와 밤새 색이 바뀌는 조명이다. 해변을 따라 늘어선 카페와 술집은 모두 유리창을 바다로 냈고, 토요일 저녁이면 만 위에서 드론쇼가 열린다. 10월 말 부산불꽃축제 때는 이 해변이 도시에서 가장 큰 관람석이 된다. 자리를 잡으려면 몇 시간 전에 와야 한다.","facts":["광안대교는 길이 7.42km로 한국 최초의 2층 현수교다.","다리 조명은 요일과 계절에 따라 색이 바뀐다.","부산불꽃축제는 10월 말에 열린다.","주말 저녁에는 만 위에서 드론 라이트쇼가 열린다."],"travelTips":["불꽃축제를 실내에서 보려면 해변 식당을 미리 예약하자.","2호선 광안역에서 도보 10분이다.","밤에 가야 제맛이다. 낮과는 완전히 다른 곳이다."],"bestTime":"5~10월, 주말 저녁","visitDuration":"2시간","ticket":"","openingHours":"상시","galleryCaptions":["해변에서 본 광안대교"]},"ja":{"name":"広安里海水浴場と広安大橋","summary":"二層の吊り橋を正面に望む浜。週末ごとにドローンと花火が上がる。","story":"広安里は海雲台より小さいが、海雲台にないものがある。視線を横切る7.4kmの橋と、一晩中色を変える照明だ。浜沿いのカフェやバーはみなガラス窓を海に向け、土曜の夜には湾の上でドローンショーが催される。10月末の釜山花火祭りのときは、この浜が街で最大の観覧席になる。席を取るには数時間前に来る必要がある。","facts":["広安大橋は全長7.42kmで韓国初の二層吊り橋。","橋の照明は曜日や季節によって色が変わる。","釜山花火祭りは10月末に開かれる。","週末の夜には湾の上でドローンショーが行われる。"],"travelTips":["花火を屋内から見たいなら海辺の店を事前予約しよう。","2号線広安駅から徒歩10分。","夜に行ってこそ本領。昼とはまったく別の場所だ。"],"bestTime":"5〜10月の週末の夜","visitDuration":"2時間","ticket":"","openingHours":"終日","galleryCaptions":["浜から見た広安大橋"]},"zh":{"name":"廣安里海水浴場與廣安大橋","summary":"正對雙層吊橋的海灘，釜山每逢週末在此放無人機與煙火。","story":"廣安里比海雲台小，卻有海雲台沒有的東西：一座橫在視線高度、長7.4公里的大橋，燈光整夜變換顏色。海邊的咖啡館與酒吧都把玻璃窗朝向海面，週六晚間，城市通常會在海灣上空舉行無人機表演。十月底的釜山煙火節，更把這片沙灘變成全城最大的看台——想有位置，得提早幾小時到。","facts":["廣安大橋長7.42公里，是韓國第一座雙層吊橋。","橋的燈光顏色依星期與季節變化。","釜山煙火節於十月底舉行。","週末夜晚常在海灣上空舉行無人機表演。"],"travelTips":["想在室內看煙火，請提前訂海景餐廳。","地鐵2號線廣安站步行十分鐘。","夜晚才是重點，與白天完全是兩個地方。"],"bestTime":"5至10月的週末夜晚","visitDuration":"2小時","ticket":"","openingHours":"全日","galleryCaptions":["自海灘望向廣安大橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('beomeosa', 'beomeosa', 'busan', 'Chùa Beomeosa', 'Beomeosa Temple', 'temple', 129.0689, 35.2822, 'Ngôi tổ đình 1.300 năm tuổi nép dưới chân núi Geumjeong, ngay rìa thành phố.', 'Chỉ cách trung tâm Busan chưa đầy một giờ, Beomeosa cho cảm giác đã rời hẳn thành phố: suối chảy qua rừng thông, cổng nhất trụ Iljumun dựng trên bốn cột đá, chính điện Daeungjeon với hoa văn dancheong đã bạc màu thời gian. Chùa mở chương trình templestay để khách ở lại một đêm, dậy ba giờ sáng dự khoá lễ và ăn cơm chay trong im lặng. Từ chùa có đường mòn lên thành núi Geumjeongsanseong, bức tường đá dài nhất Hàn Quốc.', '["Được dựng năm 678, thời Silla Thống nhất.","Là một trong những tổ đình lớn của Thiền phái Tào Khê.","Cổng Iljumun bốn cột đá là một bảo vật quốc gia.","Có chương trình templestay cho khách nước ngoài."]', '["Tàu điện tuyến 1 tới ga Beomeosa rồi bắt bus 90 lên chùa.","Đăng ký templestay trước ít nhất vài ngày.","Kết hợp leo thành núi Geumjeongsanseong nếu còn sức."]', 'Tháng 4–5 và 10–11', '2 giờ', '', 'Mở từ sáng sớm đến chập tối, vào cửa miễn phí', '["hidden-gem"]', '["chùa","núi","templestay"]', '[{"seed":"beomeosa","caption":"Chính điện Beomeosa","ratio":"16/9"}]', '["haeundae-beach"]', 0, 'https://www.visitbusan.net/index.do?menuCd=DOM_000000203013001000&uctcp_seq=20&lang_cd=ko', '2026-08-04', '{"en":{"name":"Beomeosa Temple","summary":"A 1,300-year-old head temple under Geumjeongsan, on the very edge of the city.","story":"Less than an hour from central Busan, Beomeosa feels like leaving the city altogether: a stream through pine forest, the Iljumun gate standing on four stone pillars, and the main hall Daeungjeon with its dancheong painting faded by time. The temple runs a templestay where guests wake at three in the morning for the service and eat monastic meals in silence. From here a trail climbs to Geumjeongsanseong, the longest fortress wall in Korea.","facts":["Founded in 678, during the Unified Silla period.","A major head temple of the Jogye Order of Korean Buddhism.","The four-pillared Iljumun gate is a national treasure.","Runs templestay programmes for foreign visitors."],"travelTips":["Metro Line 1 to Beomeosa station, then bus 90 up to the temple.","Book templestay at least a few days ahead.","Add the Geumjeongsanseong wall walk if you have the energy."],"bestTime":"April–May and October–November","visitDuration":"2 hours","ticket":"","openingHours":"Open from early morning to dusk; admission is free","galleryCaptions":["The main hall at Beomeosa"]},"ko":{"name":"범어사","summary":"금정산 자락의 1,300년 된 총림. 도시의 경계에 있다.","story":"부산 도심에서 한 시간도 걸리지 않는데, 범어사에 들어서면 도시를 완전히 벗어난 느낌이 든다. 솔숲을 지나는 계곡, 네 개의 돌기둥 위에 선 일주문, 세월에 색이 바랜 단청의 대웅전. 절에서는 템플스테이를 운영해 하룻밤 머물며 새벽 세 시 예불에 참여하고 발우공양을 한다. 이곳에서 한국에서 가장 긴 성벽인 금정산성으로 오르는 길이 이어진다.","facts":["678년 통일신라 시대에 창건되었다.","대한불교 조계종의 주요 총림 가운데 하나다.","네 개의 돌기둥으로 된 일주문은 보물이다.","외국인을 위한 템플스테이를 운영한다."],"travelTips":["1호선 범어사역에서 90번 버스를 타면 절 앞까지 간다.","템플스테이는 최소 며칠 전에 예약하자.","체력이 남는다면 금정산성 성곽길까지 걸어보자."],"bestTime":"4~5월, 10~11월","visitDuration":"2시간","ticket":"","openingHours":"이른 아침부터 해질 무렵까지 개방, 입장 무료","galleryCaptions":["범어사 대웅전"]},"ja":{"name":"梵魚寺","summary":"金井山の麓に建つ1,300年の叢林。街の境界にある。","story":"釜山の都心から一時間もかからないのに、梵魚寺に入ると街を完全に離れた気分になる。松林を抜ける渓流、四本の石柱の上に立つ一柱門、歳月に色あせた丹青の大雄殿。寺ではテンプルステイを運営し、一晩泊まって午前三時の勤行に加わり、鉢盂供養で静かに食事をする。ここから韓国で最も長い城壁、金井山城への道が延びている。","facts":["678年、統一新羅時代に創建された。","大韓仏教曹渓宗の主要な叢林のひとつ。","四本の石柱からなる一柱門は宝物に指定されている。","外国人向けのテンプルステイを運営している。"],"travelTips":["1号線梵魚寺駅から90番バスで寺の前まで行ける。","テンプルステイは数日前までに予約を。","体力があれば金井山城の城壁歩きも加えよう。"],"bestTime":"4〜5月、10〜11月","visitDuration":"2時間","ticket":"","openingHours":"早朝から日暮れまで開放、入場無料","galleryCaptions":["梵魚寺の大雄殿"]},"zh":{"name":"梵魚寺","summary":"金井山下1,300年的叢林古剎，就在城市邊緣。","story":"距釜山市中心不到一小時，梵魚寺卻讓人覺得完全離開了城市：溪水穿過松林，一柱門立在四根石柱之上，大雄殿的丹青已被歲月褪色。寺院開設寺院寄宿，客人留宿一晚，凌晨三點參加早課，在寂靜中用缽盂進齋。從寺院可沿步道登上金井山城——韓國最長的城牆。","facts":["創建於678年的統一新羅時期。","是韓國曹溪宗的重要叢林之一。","四柱式的一柱門為國家寶物。","設有面向外國旅客的寺院寄宿計畫。"],"travelTips":["地鐵1號線梵魚寺站轉90號公車直達寺前。","寺院寄宿請至少提前數日預約。","體力尚可的話，再加走金井山城城牆。"],"bestTime":"4至5月、10至11月","visitDuration":"2小時","ticket":"","openingHours":"清晨開放至日落，免費入場","galleryCaptions":["梵魚寺大雄殿"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('taejongdae', 'taejongdae', 'busan', 'Vách đá Taejongdae', 'Taejongdae', 'park', 129.087, 35.053, 'Mũi đá cuối đảo Yeongdo, nơi vách dựng đứng đổ thẳng xuống biển và hải đăng trắng đứng chơ vơ.', 'Taejongdae là điểm cuối phía nam của Busan: rừng thông phủ kín một mũi đất, rồi đất đột ngột hụt xuống thành vách đá cao gần trăm mét dựng đứng trên biển. Xe điện chạy vòng quanh mũi đất, nhưng đi bộ mới thấy hết — đường men theo mép rừng, thi thoảng mở ra một khoảng nhìn thẳng ra Thái Bình Dương. Dưới chân hải đăng có bậc đá dẫn xuống bãi đá, nơi các bà bán hải sản sống bày mực và hải sâm ngay trên mặt đá. Tên nơi này lấy từ vua Taejong Muyeol của Silla, người tương truyền từng tới đây bắn cung.', '["Vách đá cao khoảng 100m, nằm ở cực nam đảo Yeongdo.","Đặt tên theo vua Taejong Muyeol của Silla.","Có xe điện Danubi chạy vòng quanh mũi đất, dừng ở các điểm ngắm cảnh.","Ngày trời trong có thể nhìn thấy đảo Tsushima của Nhật Bản."]', '["Đi bộ chiều xuống, đi xe điện chiều lên nếu ngại dốc.","Bãi đá dưới hải đăng trơn — đi giày bám tốt.","Ngày gió lớn một số lối bị đóng vì an toàn."]', 'Tháng 4–6 và 9–11', '2–3 giờ', 'Vào công viên miễn phí; tàu Danubi 4.000 KRW trọn vòng (một chặng 2.000)', '05:00–24:00 (xe điện 09:00–18:00)', '["popular"]', '["vách đá","hải đăng","đi bộ","biển"]', '[{"seed":"taejongdae","caption":"Hải đăng trên vách đá Taejongdae","ratio":"16/9"}]', '["huinnyeoul-culture-village","jagalchi-market"]', 0, 'https://www.visitbusan.net/index.do?menuCd=DOM_000000302002001000&uc_seq=542&lang_cd=en', '2026-08-04', '{"en":{"name":"Taejongdae","summary":"The rocky headland at the end of Yeongdo, where sheer cliffs drop straight into the sea and a white lighthouse stands alone.","story":"Taejongdae is Busan''s southern full stop: pine forest covers a headland, then the ground gives out into cliffs a hundred metres high standing over the water. A road train loops the point, but walking shows you more — the path follows the edge of the wood and now and then opens onto the open sea. Below the lighthouse, stone steps lead down to a rock shelf where women sell live seafood, squid and sea cucumber laid out straight on the stone. The name comes from King Taejong Muyeol of Silla, said to have practised archery here.","facts":["The cliffs are about 100m high, at the southern tip of Yeongdo island.","Named after King Taejong Muyeol of Silla.","The Danubi road train loops the headland, stopping at the viewpoints.","On a clear day you can see the Japanese island of Tsushima."],"travelTips":["Walk down and ride the train back up if you''d rather skip the climb.","The rock shelf below the lighthouse is slippery — wear shoes with grip.","Some paths close on very windy days."],"bestTime":"April–June and September–November","visitDuration":"2–3 hours","ticket":"Park entry is free; the Danubi train is 4,000 KRW for the full loop (2,000 for one leg)","openingHours":"05:00–24:00 (road train 09:00–18:00)","galleryCaptions":["The lighthouse on the Taejongdae cliffs"]},"ko":{"name":"태종대","summary":"영도 끝의 바위 곶. 절벽이 바다로 곧장 떨어지고, 흰 등대가 홀로 서 있다.","story":"태종대는 부산의 남쪽 마침표다. 솔숲이 곶을 덮다가 땅이 갑자기 끊기며 바다 위로 백 미터 절벽이 선다. 다누비열차가 곶을 한 바퀴 돌지만, 걸어야 더 많이 보인다. 길은 숲의 가장자리를 따라가다 이따금 툭 트인 바다를 내어 준다. 등대 아래로는 돌계단이 바위 마당까지 이어지고, 그곳에서 아주머니들이 오징어와 해삼을 바위 위에 그대로 펼쳐 놓고 판다. 이름은 이곳에서 활을 쏘았다고 전해지는 신라 태종무열왕에서 왔다.","facts":["영도 남쪽 끝의 절벽으로 높이는 약 100m다.","신라 태종무열왕의 이름을 따왔다.","다누비열차가 곶을 돌며 전망 지점마다 선다.","맑은 날에는 일본 쓰시마섬이 보인다."],"travelTips":["오르막이 부담되면 내려갈 때 걷고 올라올 때 열차를 타자.","등대 아래 바위 마당은 미끄럽다. 접지력 좋은 신발을 신자.","바람이 센 날에는 일부 구간이 통제된다."],"bestTime":"4~6월, 9~11월","visitDuration":"2~3시간","ticket":"공원 입장 무료, 다누비열차는 순환 1회 4,000원(1구간 2,000원)","openingHours":"05:00~24:00(다누비열차 09:00~18:00)","galleryCaptions":["태종대 절벽 위의 등대"]},"ja":{"name":"太宗台","summary":"影島の先端の岩の岬。切り立った崖が海へまっすぐ落ち、白い灯台がぽつんと立つ。","story":"太宗台は釜山の南の終止符だ。松林が岬を覆い、そこで地面が不意に途切れて、海の上に百メートルの崖が立つ。ダヌビ列車が岬を一周するが、歩いたほうが多くを見られる。道は林の縁に沿い、ときおり外海へ開ける。灯台の下からは石段が岩の広場へ下り、そこでは女性たちがイカやナマコを岩の上にじかに並べて売っている。名は、ここで弓を引いたと伝わる新羅の太宗武烈王に由来する。","facts":["影島の南端にある高さ約100mの崖。","新羅の太宗武烈王にちなむ名。","ダヌビ列車が岬を巡り、展望地点ごとに停まる。","晴れた日には日本の対馬が見える。"],"travelTips":["上りがつらければ、下りを歩いて戻りは列車にしよう。","灯台下の岩場は滑る。グリップのある靴で。","風の強い日は一部の道が閉鎖される。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2〜3時間","ticket":"公園の入場は無料、ダヌビ列車は一周4,000ウォン（1区間2,000）","openingHours":"05:00〜24:00（ダヌビ列車は09:00〜18:00）","galleryCaptions":["太宗台の崖に立つ灯台"]},"zh":{"name":"太宗台","summary":"影島盡頭的岩岬，峭壁直落入海，一座白色燈塔孤零零立著。","story":"太宗台是釜山南端的句點：松林覆滿整片岬角，地面忽然中斷，成為高逾百公尺、直插海面的斷崖。園區小火車繞岬一圈，但用走的才看得多——步道沿著林緣走，不時開出一片正對外海的視野。燈塔下方有石階通往岩台，婦人們把活魷魚與海參直接攤在石頭上叫賣。地名取自新羅太宗武烈王，相傳他曾在此射箭。","facts":["斷崖高約100公尺，位於影島最南端。","以新羅太宗武烈王命名。","Danubi小火車繞行岬角，於各觀景點停靠。","天氣晴朗時可望見日本對馬島。"],"travelTips":["怕爬坡的話，可以走下去、搭小火車回來。","燈塔下的岩台濕滑，請穿抓地力好的鞋。","強風日部分步道會封閉。"],"bestTime":"4至6月與9至11月","visitDuration":"2至3小時","ticket":"公園免費入場；達努比列車全程4,000韓元（單段2,000）","openingHours":"05:00–24:00（小火車09:00–18:00）","galleryCaptions":["太宗台斷崖上的燈塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('huinnyeoul-culture-village', 'huinnyeoul-culture-village', 'busan', 'Làng văn hoá Huinnyeoul', 'Huinnyeoul Culture Village', 'village', 129.0163, 35.0785, 'Dãy nhà trắng bám trên vách biển đảo Yeongdo, có lối đi hẹp chạy ngay trên mặt sóng.', 'Huinnyeoul nghĩa là ''dòng nước trắng'' — tên đặt theo những con suối từng đổ từ vách đá xuống biển. Sau chiến tranh Triều Tiên, người tị nạn dựng nhà bám vào sườn dốc này vì không còn chỗ nào khác; giờ những căn nhà trắng xếp tầng ấy nhìn thẳng ra cảng Busan với hàng tàu container neo ngoài khơi. Con đường ven biển hẹp đến mức hai người phải né nhau, và bên dưới là sóng vỗ vào kè đá. Nhiều căn đã thành quán cà phê có cửa sổ mở ra biển. Đây là bối cảnh của phim ''Hiệp sĩ đen'' và vài phim Hàn khác nên khách trẻ rất đông.', '["Hình thành từ khu định cư của người tị nạn sau chiến tranh Triều Tiên.","Tên làng nghĩa là ''dòng nước trắng'', theo các con suối chảy xuống vách biển.","Lối đi ven biển Huinnyeoul dài khoảng 1,5 km sát mép nước.","Là bối cảnh của nhiều phim điện ảnh Hàn Quốc."]', '["Đi vào chiều muộn: nắng xiên ngang làm tường trắng và mặt biển đẹp nhất.","Đây là khu dân cư — không gõ cửa, không quay phim vào trong nhà.","Kết hợp Taejongdae trong cùng chuyến ra đảo Yeongdo."]', 'Tháng 4–6 và 9–11', '1,5–2 giờ', '', 'Cả ngày', '["trending","hidden-gem"]', '["làng ven biển","cà phê","nhiếp ảnh","đi bộ"]', '[{"seed":"huinnyeoul-culture-village","caption":"Lối đi ven biển dưới làng","ratio":"16/9"}]', '["taejongdae","gamcheon-culture-village"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Huinnyeoul Culture Village","summary":"A run of white houses clinging to Yeongdo''s sea cliff, with a narrow path running right above the waves.","story":"Huinnyeoul means ''white stream'', after the brooks that once fell from the cliff into the sea. After the Korean War refugees built here, on the slope, because there was nowhere else; now those stacked white houses look straight out at Busan harbour with container ships anchored offshore. The coastal path is narrow enough that two people must turn sideways, and below it the swell hits the sea wall. Many houses are cafés with windows onto the water. It appeared in Korean films, so the crowd skews young.","facts":["It grew out of a post-Korean War refugee settlement.","The name means ''white stream'', after the brooks that fell down the sea cliff.","The Huinnyeoul coastal path runs about 1.5km right along the water.","It has been used as a location in several Korean films."],"travelTips":["Come late afternoon: raking light is best on the white walls and the sea.","People live here — don''t knock on doors or film into the houses.","Combine it with Taejongdae on the same trip out to Yeongdo."],"bestTime":"April–June and September–November","visitDuration":"1.5–2 hours","ticket":"","openingHours":"All day","galleryCaptions":["The coastal path below the village"]},"ko":{"name":"흰여울문화마을","summary":"영도 해안 절벽에 붙은 흰 집들. 파도 바로 위로 좁은 길이 이어진다.","story":"흰여울은 절벽에서 바다로 떨어지던 물줄기에서 온 이름이다. 한국전쟁 뒤 피란민들이 달리 갈 곳이 없어 이 비탈에 집을 지었고, 지금 그 층층이 쌓인 흰 집들은 앞바다에 정박한 컨테이너선과 부산항을 마주 본다. 해안 산책로는 두 사람이 몸을 틀어야 지나갈 만큼 좁고, 그 아래로는 파도가 방파제를 친다. 여러 집이 바다로 창을 낸 카페가 되었다. 한국 영화의 배경이 되면서 젊은 손님이 많다.","facts":["한국전쟁 이후 피란민 정착지에서 비롯되었다.","마을 이름은 절벽을 타고 내리던 물줄기에서 왔다.","흰여울 해안 산책로는 물가를 따라 약 1.5km 이어진다.","여러 편의 한국 영화 촬영지로 쓰였다."],"travelTips":["늦은 오후에 가자. 비스듬한 빛이 흰 벽과 바다에 가장 잘 든다.","사람이 사는 곳이다. 문을 두드리거나 집 안을 찍지 말자.","영도로 나가는 김에 태종대와 묶어서 보자."],"bestTime":"4~6월, 9~11월","visitDuration":"1.5~2시간","ticket":"","openingHours":"상시","galleryCaptions":["마을 아래 해안 산책로"]},"ja":{"name":"白い渓流文化村（フィニョウル）","summary":"影島の海食崖に貼りつく白い家並み。波のすぐ上に細い道が続く。","story":"フィニョウルは「白い渓流」の意で、かつて崖から海へ落ちていた小川に由来する。朝鮮戦争のあと、行き場のない避難民がこの斜面に家を建てた。今その積み重なった白い家々は、沖に錨を下ろすコンテナ船と釜山港を正面から見ている。海沿いの道は二人がすれ違うのに体を横にするほど狭く、その下では波が防波堤を打つ。多くの家が海に窓を開けたカフェになった。韓国映画の舞台になったことで、若い客が多い。","facts":["朝鮮戦争後の避難民集落から生まれた。","村名は海食崖を流れ落ちていた小川に由来する。","フィニョウル海岸散策路は水際を約1.5km続く。","複数の韓国映画のロケ地として使われてきた。"],"travelTips":["遅い午後に。斜めの光が白い壁と海に最もよく当たる。","人が暮らしている。扉を叩いたり家の中を撮ったりしないこと。","影島へ出るついでに太宗台とまとめて回ろう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1.5〜2時間","ticket":"","openingHours":"終日","galleryCaptions":["村の下の海岸散策路"]},"zh":{"name":"白浪文化村","summary":"一排白房子攀在影島的海蝕崖上，一條窄路就走在浪的正上方。","story":"白浪之名來自昔日從崖上流入海中的溪水。韓戰之後，難民無處可去，就在這片斜坡蓋起房子；如今那些層層堆疊的白色房舍，正對著釜山港與外海下錨的貨櫃船。海邊步道窄到兩人得側身才過得去，底下就是浪打防波堤。許多屋子已改成朝海開窗的咖啡館。因為多部韓國電影在此取景，來客偏年輕。","facts":["源自韓戰後的難民聚落。","村名取自昔日流下海蝕崖的溪水。","白浪海岸步道沿著水邊延伸約1.5公里。","曾是多部韓國電影的取景地。"],"travelTips":["傍晚前來：斜射的光落在白牆與海面上最好看。","這裡有人居住，別敲門，也別把鏡頭伸進屋內。","出海到影島時可與太宗台排在一起。"],"bestTime":"4至6月與9至11月","visitDuration":"1.5至2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["村子下方的海岸步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('oryukdo-skywalk', 'oryukdo-skywalk', 'busan', 'Skywalk Oryukdo', 'Oryukdo Skywalk', 'island', 129.1265, 35.0965, 'Sàn kính nhô ra khỏi vách đá, dưới chân là chỗ Hoàng Hải và biển Nhật Bản chính thức gặp nhau.', 'Oryukdo nghĩa là ''năm sáu đảo'' — tuỳ con nước mà bạn đếm được năm hay sáu hòn, vì một hòn tách làm đôi khi triều lên. Đây là điểm được lấy làm ranh giới giữa Nam Hải và Đông Hải trong hải văn Hàn Quốc, nên tấm biển ở đây ghi hẳn ''nơi hai biển gặp nhau''. Từ vách đá, một sàn kính hình móng ngựa nhô ra khoảng chín mét trên mặt nước ba mươi lăm mét bên dưới; khách phải đi dép vải phủ ngoài giày để giữ kính trong. Đứng ở mép sàn nhìn xuống, cảm giác chân trống là có thật.', '["Tên gọi vì tuỳ mực nước mà đếm được năm hoặc sáu đảo.","Sàn kính nhô ra khoảng 9m, cách mặt biển chừng 35m.","Được coi là ranh giới giữa Nam Hải và Đông Hải trong hải văn Hàn Quốc.","Là điểm khởi đầu của tuyến đường mòn ven biển Galmaetgil."]', '["Khách phải mang dép vải phủ giày, phát miễn phí ở lối vào.","Ngày gió mạnh hoặc mưa sàn kính có thể đóng.","Kết hợp đường mòn Igidae ngay bên cạnh nếu còn sức đi bộ."]', 'Tháng 4–6 và 9–11', '1 giờ', 'Miễn phí', '09:00–19:00 (1/6–30/9), 09:00–18:00 (1/10–31/5); vào cửa cuối trước giờ đóng 10 phút, đóng cửa thứ Hai', '["trending"]', '["sàn kính","vách đá","biển","toàn cảnh"]', '[{"seed":"oryukdo-skywalk","caption":"Sàn kính nhìn xuống Oryukdo","ratio":"16/9"}]', '["igidae-coastal-walk","gwangalli-beach"]', 0, 'https://www.visitbusan.net/index.do?menuCd=DOM_000000301001001000&uc_seq=282&lang_cd=en', '2026-08-04', '{"en":{"name":"Oryukdo Skywalk","summary":"A glass deck jutting out from the cliff, above the point where the Yellow Sea and the Sea of Japan officially meet.","story":"Oryukdo means ''five or six islands'' — depending on the tide you count five or six, because one splits in two at high water. Korean hydrography treats this as the boundary between the South Sea and the East Sea, and a sign here says so outright. From the cliff, a horseshoe of glass extends about nine metres over water thirty-five metres below; visitors wear cloth slippers over their shoes to keep the glass clear. Standing at the edge and looking down, the sense of nothing underfoot is entirely real.","facts":["The name reflects counting five or six islands depending on the tide.","The glass deck extends about 9m, some 35m above the sea.","Korean hydrography treats it as the boundary between the South Sea and the East Sea.","It is the starting point of the Galmaetgil coastal trail."],"travelTips":["Cloth overshoes are compulsory and handed out free at the entrance.","The deck can close in strong wind or rain.","Add the Igidae trail next door if you still have legs for walking."],"bestTime":"April–June and September–November","visitDuration":"1 hour","ticket":"Free","openingHours":"09:00–19:00 (1 Jun–30 Sep), 09:00–18:00 (1 Oct–31 May); last entry 10 minutes before closing, closed Mondays","galleryCaptions":["The glass deck looking down on Oryukdo"]},"ko":{"name":"오륙도 스카이워크","summary":"절벽에서 내민 유리 바닥. 그 아래가 남해와 동해가 공식적으로 만나는 지점이다.","story":"오륙도는 ''다섯 혹은 여섯 섬''이라는 뜻이다. 물때에 따라 하나가 둘로 갈라져 다섯으로도 여섯으로도 세어진다. 한국 해양 지리에서는 이곳을 남해와 동해의 경계로 삼고, 여기 세워진 표지판도 그렇게 적고 있다. 절벽에서 말굽 모양의 유리 바닥이 약 9m 내밀어져 있고, 그 아래 바다까지는 35m다. 유리를 지키기 위해 방문객은 신발 위에 덧신을 신는다. 가장자리에 서서 내려다보면 발밑이 비어 있다는 감각은 진짜다.","facts":["물때에 따라 다섯 또는 여섯 개로 세어져 붙은 이름이다.","유리 바닥은 약 9m 내밀어져 있고 해수면까지는 약 35m다.","한국 해양 지리에서 남해와 동해의 경계로 본다.","해안 트레일 갈맷길의 시작 지점이다."],"travelTips":["덧신 착용은 필수이며 입구에서 무료로 준다.","바람이 세거나 비가 오면 통제될 수 있다.","걸을 힘이 남았다면 바로 옆 이기대 길을 이어 걷자."],"bestTime":"4~6월, 9~11월","visitDuration":"1시간","ticket":"무료","openingHours":"09:00~19:00(6/1~9/30), 09:00~18:00(10/1~5/31), 마감 10분 전 입장 종료, 월요일 휴무","galleryCaptions":["오륙도를 내려다보는 유리 바닥"]},"ja":{"name":"五六島スカイウォーク","summary":"崖から突き出したガラスの床。その下が南海と東海が公式に出会う地点だ。","story":"五六島は「五つあるいは六つの島」という意味だ。潮位によって一つが二つに分かれ、五にも六にも数えられる。韓国の海洋地理ではここを南海と東海の境とし、立てられた標識にもそう書かれている。崖から馬蹄形のガラス床が約9m張り出し、その下の海までは35m。ガラスを守るため、来訪者は靴の上に布のカバーを履く。縁に立って見下ろすと、足元に何もないという感覚は本物だ。","facts":["潮位により五つとも六つとも数えられることから付いた名。","ガラス床は約9m張り出し、海面まで約35m。","韓国の海洋地理では南海と東海の境とされる。","海岸トレイル「カルメッキル」の起点である。"],"travelTips":["布のカバーの着用が必須で、入口で無料配布される。","強風や雨の日は閉鎖されることがある。","まだ歩けるなら隣の二妓台の道を続けて歩こう。"],"bestTime":"4〜6月、9〜11月","visitDuration":"1時間","ticket":"無料","openingHours":"09:00〜19:00（6/1〜9/30）、09:00〜18:00（10/1〜5/31）、最終入場は閉場10分前、月曜休み","galleryCaptions":["五六島を見下ろすガラスの床"]},"zh":{"name":"五六島天空步道","summary":"自斷崖伸出的玻璃平台，腳下正是黃海與日本海正式交界之處。","story":"五六島意為「五座或六座島」——依潮位不同，有一座會裂成兩座，因此有時數五、有時數六。韓國海洋地理以此為南海與東海的分界，這裡的告示牌也直接這麼寫。玻璃平台自崖壁呈馬蹄形伸出約九公尺，下方離海面約三十五公尺；為了保護玻璃，遊客得在鞋外套上布套。站到邊緣往下看，腳下懸空的感覺是真的。","facts":["名稱源自依潮位可數出五座或六座島。","玻璃平台外伸約9公尺，離海面約35公尺。","韓國海洋地理以此為南海與東海的分界。","是海岸步道「鷗鳥路」的起點。"],"travelTips":["入口免費發放布套，必須穿戴。","強風或下雨時平台可能關閉。","腳力還夠的話，可接著走隔壁的二妓台步道。"],"bestTime":"4至6月與9至11月","visitDuration":"1小時","ticket":"免費","openingHours":"09:00–19:00（6/1至9/30）、09:00–18:00（10/1至5/31）；閉館前10分鐘停止入場，週一休息","galleryCaptions":["俯瞰五六島的玻璃平台"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('igidae-coastal-walk', 'igidae-coastal-walk', 'busan', 'Đường mòn ven biển Igidae', 'Igidae Coastal Walk', 'mountain', 129.12, 35.1265, 'Con đường bám theo đá núi lửa dọc bờ biển, nhìn thẳng sang rừng cao ốc Haeundae bên kia vịnh.', 'Igidae là dải bờ đá dài chừng bốn cây số từng bị phong toả làm khu quân sự suốt mấy thập niên, nên khi mở lại vào năm 2001 nó vẫn còn nguyên vẻ hoang. Đường mòn men theo mép nước trên nền đá núi lửa nứt nẻ, lúc thì cầu gỗ bắc qua khe, lúc thì bậc thang leo lên mỏm cao. Điều làm nơi này khác biệt là góc nhìn: bên trái là sóng vỗ vào đá đen, bên phải qua vịnh là toàn bộ hàng cao ốc Haeundae và cầu Gwangan — thiên nhiên và thành phố trong cùng một khung hình. Tên Igidae gắn với truyền thuyết về hai kỹ nữ ôm tướng giặc gieo mình xuống biển.', '["Đường mòn ven biển dài khoảng 4 km trên nền đá núi lửa.","Từng là khu vực quân sự bị phong toả, mở lại cho dân thường năm 2001.","Là một chặng của tuyến đường mòn Galmaetgil quanh Busan.","Tên gắn với truyền thuyết hai kỹ nữ trong cuộc chiến Nhâm Thìn."]', '["Đi từ hướng Oryukdo sang Gwangalli để kết thúc ở chỗ có quán ăn.","Đường có nhiều bậc và đá trơn — không hợp xe đẩy hay giày cao.","Mang nước: gần như không có hàng quán dọc đường."]', 'Tháng 4–6 và 9–11', '3 giờ', '', 'Cả ngày (nên đi ban ngày)', '["hidden-gem"]', '["đi bộ","bờ biển","đá núi lửa","toàn cảnh"]', '[{"seed":"igidae-coastal-walk","caption":"Đường mòn nhìn sang Haeundae","ratio":"16/9"}]', '["oryukdo-skywalk","gwangalli-beach"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Igidae Coastal Walk","summary":"A path over volcanic rock along the shore, facing the wall of Haeundae towers across the bay.","story":"Igidae is about four kilometres of rocky shoreline that spent decades sealed off as a military zone, so when it reopened in 2001 it was still wild. The trail follows the waterline over cracked volcanic rock, sometimes on a boardwalk across a gully, sometimes up steps onto a headland. What sets it apart is the angle: to your left, surf on black rock; to your right, across the bay, the entire Haeundae skyline and the Gwangan bridge — nature and city in one frame. The name is tied to a legend of two courtesans who pulled an enemy general into the sea.","facts":["About 4km of coastal trail over volcanic rock.","Formerly a closed military zone, reopened to the public in 2001.","It forms one stage of Busan''s Galmaetgil trail network.","The name is linked to a legend from the Imjin War."],"travelTips":["Walk from the Oryukdo end towards Gwangalli so you finish where the restaurants are.","Lots of steps and slick rock — not for pushchairs or smooth soles.","Carry water; there is almost nothing to buy along the way."],"bestTime":"April–June and September–November","visitDuration":"3 hours","ticket":"","openingHours":"Open all day (best walked in daylight)","galleryCaptions":["The trail looking across to Haeundae"]},"ko":{"name":"이기대 해안산책로","summary":"화산암 위를 따라가는 해안길. 만 건너 해운대의 빌딩 숲을 마주 본다.","story":"이기대는 수십 년간 군사지역으로 막혀 있던 4km 남짓의 바위 해안이라, 2001년 개방되었을 때도 여전히 거칠었다. 길은 갈라진 화산암 위 물가를 따라가며, 때로는 협곡을 건너는 데크가 되고 때로는 곶으로 오르는 계단이 된다. 이곳을 다르게 만드는 것은 시선의 각도다. 왼쪽은 검은 바위에 부딪히는 파도, 오른쪽은 만 건너 해운대의 스카이라인과 광안대교. 자연과 도시가 한 화면에 들어온다. 이름은 임진왜란 때 두 기녀가 왜장을 안고 바다로 떨어졌다는 전설과 얽혀 있다.","facts":["화산암 위를 지나는 약 4km의 해안 산책로다.","군사지역으로 통제되다가 2001년 일반에 개방되었다.","부산 갈맷길 코스의 한 구간이다.","이름은 임진왜란 시기의 전설과 관련이 있다."],"travelTips":["오륙도 쪽에서 광안리 방향으로 걸으면 식당가에서 끝난다.","계단이 많고 바위가 미끄럽다. 유모차나 굽 있는 신발에는 맞지 않는다.","물을 챙기자. 길에는 파는 곳이 거의 없다."],"bestTime":"4~6월, 9~11월","visitDuration":"3시간","ticket":"","openingHours":"상시(낮에 걷기를 권함)","galleryCaptions":["해운대를 마주 보는 산책로"]},"ja":{"name":"二妓台海岸散策路","summary":"火山岩の上を辿る海岸の道。湾の向こうに海雲台のビル群を正面から見る。","story":"二妓台は数十年ものあいだ軍事区域として閉ざされていた4kmほどの岩の海岸で、2001年に開放されたときもなお荒々しかった。道は割れた火山岩の水際を辿り、あるときは谷を渡るデッキになり、あるときは岬へ上る階段になる。ここを特別にしているのは視線の角度だ。左には黒い岩を打つ波、右には湾の向こうに海雲台のスカイラインと広安大橋。自然と都市が同じ一枚に収まる。名は、壬辰倭乱のとき二人の妓生が敵将を抱いて海へ落ちたという伝説に結びついている。","facts":["火山岩の上を通る約4kmの海岸散策路。","軍事区域として閉ざされ、2001年に一般開放された。","釜山のカルメッキル・トレイルの一区間である。","名は壬辰倭乱期の伝説に由来する。"],"travelTips":["五六島側から広安里へ歩けば、食堂街で終われる。","階段が多く岩も滑る。ベビーカーやかかとのある靴には向かない。","水を持とう。途中に買える場所はほとんどない。"],"bestTime":"4〜6月、9〜11月","visitDuration":"3時間","ticket":"","openingHours":"終日（日中に歩くのがよい）","galleryCaptions":["海雲台を望む散策路"]},"zh":{"name":"二妓台海岸步道","summary":"走在火山岩上的海岸路，正對著海灣另一頭海雲台的高樓叢林。","story":"二妓台是一段約四公里的岩岸，曾以軍事管制封閉數十年，2001年重新開放時依然野性未褪。步道沿著水邊在龜裂的火山岩上前行，時而化為跨越溝壑的木棧，時而變成登上岬角的階梯。真正讓它與眾不同的是視角：左邊是浪打黑岩，右邊隔著海灣是海雲台整片天際線與廣安大橋——自然與城市收進同一個畫面。地名連著一則傳說：壬辰倭亂時兩名妓生抱著敵將投海。","facts":["約4公里長的海岸步道，路面為火山岩。","曾為軍事管制區，2001年才對外開放。","是釜山鷗鳥路步道系統的其中一段。","名稱與壬辰倭亂時期的傳說有關。"],"travelTips":["從五六島往廣安里走，可以結束在有餐廳的一頭。","階梯多、岩面滑，不適合推車或有跟的鞋。","自備飲水，沿途幾乎買不到東西。"],"bestTime":"4至6月與9至11月","visitDuration":"3小時","ticket":"","openingHours":"全日開放（建議白天行走）","galleryCaptions":["望向海雲台的步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('yongdusan-busan-tower', 'yongdusan-busan-tower', 'busan', 'Công viên Yongdusan & tháp Busan', 'Yongdusan Park & Busan Tower', 'city', 129.0322, 35.101, 'Ngọn đồi giữa phố cũ, lên bằng thang cuốn ngoài trời, đỉnh là tháp nhìn trọn cảng Busan.', 'Yongdusan nghĩa là ''núi đầu rồng'', và nó nhô lên ngay giữa khu phố cũ Nampo-dong. Bạn không phải leo: một dãy thang cuốn ngoài trời đưa lên thẳng đỉnh đồi, nơi có quảng trường lát đá, đàn bồ câu và tượng đô đốc Yi Sun-sin. Tháp Busan cao một trăm hai mươi mét dựng năm 1973, đài quan sát trên đỉnh cho thấy toàn bộ cảng — hàng cần cẩu container, phà đi Nhật, và những dãy nhà bám lên sườn núi phía sau. Dưới chân đồi là chợ Gukje và phố BIFF nơi các ngôi sao điện ảnh in dấu tay trên vỉa hè.', '["Tháp Busan cao 120m, khánh thành năm 1973.","Lên đồi bằng hệ thống thang cuốn ngoài trời, không phải leo bộ.","Trong công viên có tượng đô đốc Yi Sun-sin và chuông Citizens'' Bell.","Sát bên là chợ Gukje và phố điện ảnh BIFF."]', '["Lên lúc chạng vạng để thấy cảng chuyển từ ngày sang đèn.","Vào công viên miễn phí, chỉ đài quan sát trên tháp mới tính vé.","Kết hợp chợ Gukje và chợ cá Jagalchi trong cùng buổi."]', 'Quanh năm', '1,5 giờ', 'Công viên miễn phí; đài quan sát khoảng 12.000 KRW tại quầy, mua trực tuyến thường rẻ hơn', 'Công viên cả ngày; tháp 10:00–23:00', '["popular"]', '["toàn cảnh","cảng biển","phố cổ"]', '[{"seed":"yongdusan-busan-tower","caption":"Cảng Busan nhìn từ tháp","ratio":"16/9"}]', '["jagalchi-market","bosu-dong-book-street"]', 0, 'https://www.visitbusan.net/index.do?menuCd=DOM_000000301001001000', '2026-08-04', '{"en":{"name":"Yongdusan Park & Busan Tower","summary":"A hill in the old quarter reached by outdoor escalator, topped by a tower over the whole harbour.","story":"Yongdusan means ''dragon''s head mountain'', and it rises right in the middle of the old Nampo-dong quarter. You don''t have to climb: a run of outdoor escalators lifts you to the top, where there is a paved plaza, pigeons and a statue of Admiral Yi Sun-sin. Busan Tower, 120 metres and built in 1973, has an observation deck taking in the whole port — the container cranes, the ferries to Japan, and the housing running up the hillsides behind. At the foot of the hill are Gukje market and BIFF Square, where film stars have pressed their handprints into the pavement.","facts":["Busan Tower is 120m tall and opened in 1973.","The hill is reached by a system of outdoor escalators rather than on foot.","The park holds a statue of Admiral Yi Sun-sin and the Citizens'' Bell.","Gukje market and BIFF film street are right below."],"travelTips":["Go at dusk to watch the port turn from daylight to lights.","The park is free; only the tower''s observation deck is ticketed.","Combine with Gukje market and Jagalchi fish market in one outing."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"The park is free; the observatory is about 12,000 KRW at the gate, usually cheaper booked online","openingHours":"Park open all day; the tower 10:00–23:00","galleryCaptions":["Busan harbour from the tower"]},"ko":{"name":"용두산공원과 부산타워","summary":"구도심 한가운데의 언덕. 야외 에스컬레이터로 올라가면 부산항이 한눈에 들어오는 탑이 있다.","story":"용두산은 ''용의 머리 산''이라는 뜻으로, 남포동 구도심 한복판에 솟아 있다. 오를 필요는 없다. 야외 에스컬레이터가 정상까지 데려다준다. 위에는 포석 광장과 비둘기, 이순신 장군 동상이 있다. 1973년에 세운 높이 120m의 부산타워 전망대에서는 항구 전체가 보인다. 컨테이너 크레인, 일본으로 가는 여객선, 그리고 뒤편 산비탈을 타고 올라간 집들까지. 언덕 아래에는 국제시장과, 영화인들의 손도장이 보도에 찍힌 BIFF광장이 있다.","facts":["부산타워는 높이 120m로 1973년에 세워졌다.","언덕까지 걸어 오르지 않고 야외 에스컬레이터로 올라간다.","공원에는 이순신 장군 동상과 시민의 종이 있다.","바로 아래에 국제시장과 BIFF광장이 있다."],"travelTips":["해질 무렵에 올라 항구가 낮에서 불빛으로 바뀌는 것을 보자.","공원은 무료이고 타워 전망대만 유료다.","국제시장, 자갈치시장과 묶어 한 번에 돌자."],"bestTime":"연중","visitDuration":"1.5시간","ticket":"공원은 무료, 전망대는 현장 약 12,000원이며 온라인 예매가 보통 더 싸다","openingHours":"공원은 상시, 타워는 10:00~23:00","galleryCaptions":["타워에서 본 부산항"]},"ja":{"name":"龍頭山公園と釜山タワー","summary":"旧市街の真ん中の丘。屋外エスカレーターで上がると、釜山港を一望する塔がある。","story":"龍頭山は「龍の頭の山」の意で、南浦洞の旧市街の真ん中に盛り上がっている。登る必要はない。屋外エスカレーターが頂上まで運んでくれる。上には石畳の広場と鳩、そして李舜臣将軍の像がある。1973年に建った高さ120mの釜山タワーの展望台からは港の全体が見える。コンテナクレーン、日本行きのフェリー、そして背後の山肌を這い上がる家並みまで。丘の下には国際市場と、映画人の手形が歩道に押されたBIFF広場がある。","facts":["釜山タワーは高さ120m、1973年の建設。","丘へは徒歩ではなく屋外エスカレーターで上がる。","公園には李舜臣将軍の像と市民の鐘がある。","すぐ下に国際市場とBIFF広場がある。"],"travelTips":["夕暮れに上って、港が昼から灯りへ移るのを見よう。","公園は無料で、有料なのは塔の展望台だけ。","国際市場とチャガルチ市場をまとめて回ろう。"],"bestTime":"通年","visitDuration":"1.5時間","ticket":"公園は無料、展望台は現地で約12,000ウォン、オンライン購入の方が安いことが多い","openingHours":"公園は終日、タワーは10:00〜23:00","galleryCaptions":["タワーから見た釜山港"]},"zh":{"name":"龍頭山公園與釜山塔","summary":"舊城區中央的小山，搭戶外電扶梯上去，山頂的塔可俯瞰整座釜山港。","story":"龍頭山意為「龍頭之山」，就聳在南浦洞舊城區的正中央。你不必爬：一連串戶外電扶梯直接把人送上山頂，那裡有石鋪廣場、鴿子，以及李舜臣將軍銅像。1973年建成、高120公尺的釜山塔，觀景層可看盡整座港口——貨櫃起重機、開往日本的渡輪，以及背後爬上山坡的一片屋舍。山腳下就是國際市場與BIFF廣場，影人的手印壓在人行道上。","facts":["釜山塔高120公尺，1973年落成。","上山靠戶外電扶梯系統，不必徒步攀爬。","公園內有李舜臣將軍銅像與市民之鐘。","山下即為國際市場與BIFF電影街。"],"travelTips":["黃昏上去，可看港口從白日轉為燈火。","公園免費，只有塔上觀景層收費。","可與國際市場、札嘎其魚市場安排在同一趟。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"公園免費；觀景台現場約12,000韓元，線上購票通常更便宜","openingHours":"公園全日開放；塔為10:00–23:00","galleryCaptions":["從塔上俯瞰釜山港"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bosu-dong-book-street', 'bosu-dong-book-street', 'busan', 'Ngõ sách Bosu-dong', 'Bosu-dong Book Street', 'market', 129.0245, 35.1015, 'Con ngõ hẹp với vài chục hiệu sách cũ, sách chất từ sàn lên trần từ thời chiến tranh tới nay.', 'Năm 1950, khi Busan thành thủ đô lâm thời và người tị nạn tràn về, một đôi vợ chồng trải bao tải bán sách cũ ở con ngõ này. Bảy mươi năm sau vẫn còn khoảng ba chục hiệu, ngõ vẫn hẹp, và sách vẫn chất từ sàn lên trần thành những vách giấy chỉ chừa lối đi vừa một người. Có sách giáo khoa cũ, tiểu thuyết Nhật, tạp chí thập niên 70, bản đồ cũ; nhiều chủ hiệu là đời thứ hai, thứ ba. Không ai dùng máy tính để tra — hỏi một cuốn, người ta ngẩng lên nghĩ vài giây rồi rút đúng cuốn đó ra khỏi vách.', '["Hình thành từ năm 1950, khi Busan là thủ đô lâm thời thời chiến.","Hiện còn khoảng 30 hiệu sách cũ trong ngõ.","Nhiều hiệu do thế hệ thứ hai hoặc thứ ba trong gia đình tiếp quản.","Nằm ngay sau chợ Gukje và phố BIFF."]', '["Có vài hiệu bán sách ngoại văn cũ, hỏi chủ hiệu là họ chỉ ngay.","Phần lớn đóng cửa sớm và nghỉ một số Chủ nhật.","Mang tiền mặt; nhiều hiệu không nhận thẻ."]', 'Quanh năm', '1 giờ', '', '09:00–21:00; nghỉ Chủ nhật tuần thứ nhất và thứ ba hằng tháng, cùng dịp Tết và Chuseok', '["hidden-gem"]', '["sách cũ","ngõ nhỏ","lịch sử"]', '[{"seed":"bosu-dong-book-street","caption":"Vách sách trong ngõ Bosu-dong","ratio":"16/9"}]', '["yongdusan-busan-tower","jagalchi-market"]', 0, 'http://www.bosubook.com/main/5', '2026-08-05', '{"en":{"name":"Bosu-dong Book Street","summary":"A narrow lane of a few dozen second-hand bookshops, stacked floor to ceiling since the war years.","story":"In 1950, when Busan became the provisional capital and refugees poured in, a couple spread sacking in this lane and sold used books. Seventy years on there are still about thirty shops, the lane is still narrow, and the books still run floor to ceiling in walls of paper that leave a gap wide enough for one person. There are old schoolbooks, Japanese novels, magazines from the seventies, old maps; many owners are the second or third generation. Nobody looks anything up on a computer — ask for a title and the owner thinks for a second, then pulls it straight out of the wall.","facts":["It began in 1950, when Busan was the wartime provisional capital.","Around 30 second-hand bookshops remain in the lane.","Many shops are run by the second or third generation of the same family.","It sits directly behind Gukje market and BIFF Square."],"travelTips":["A few shops carry second-hand foreign-language books; just ask the owner.","Most close early and some shut on Sundays.","Bring cash; many shops don''t take cards."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"","openingHours":"09:00–21:00; closed the first and third Sunday of each month and over Seollal and Chuseok","galleryCaptions":["Walls of books in the Bosu-dong lane"]},"ko":{"name":"보수동 책방골목","summary":"헌책방 수십 곳이 늘어선 좁은 골목. 전쟁기부터 지금까지 책이 바닥에서 천장까지 쌓여 있다.","story":"1950년, 부산이 임시수도가 되고 피란민이 몰려들던 때 한 부부가 이 골목에 가마니를 펴고 헌책을 팔았다. 칠십 년이 지난 지금도 서른 곳쯤이 남아 있고, 골목은 여전히 좁으며, 책은 여전히 바닥에서 천장까지 쌓여 한 사람이 지날 만큼의 틈만 남긴 종이 벽이 된다. 옛 교과서, 일본 소설, 70년대 잡지, 낡은 지도가 있다. 주인 상당수는 2대, 3대다. 아무도 컴퓨터로 찾지 않는다. 제목을 말하면 잠시 생각하다가 벽에서 바로 그 책을 뽑아낸다.","facts":["부산이 전시 임시수도였던 1950년에 시작되었다.","골목에는 지금도 헌책방이 30곳가량 남아 있다.","2대, 3대째 이어 가는 가게가 많다.","국제시장과 BIFF광장 바로 뒤에 있다."],"travelTips":["외국 서적 헌책을 두는 가게도 있으니 주인에게 물어보자.","대부분 일찍 닫고 일요일에 쉬는 곳도 있다.","카드를 받지 않는 가게가 많으니 현금을 챙기자."],"bestTime":"연중","visitDuration":"1시간","ticket":"","openingHours":"09:00~21:00, 매월 첫째·셋째 일요일과 설날·추석 연휴에 휴무","galleryCaptions":["보수동 골목의 책 벽"]},"ja":{"name":"宝水洞古書店街","summary":"数十軒の古本屋が並ぶ細い路地。戦時から今日まで、本が床から天井まで積まれている。","story":"1950年、釜山が臨時首都となり避難民が押し寄せていた頃、ある夫婦がこの路地にむしろを敷いて古本を売った。七十年経った今も三十軒ほどが残り、路地は変わらず狭く、本は今も床から天井まで積み上がって、人ひとり分の隙間だけを残す紙の壁になっている。古い教科書、日本の小説、七〇年代の雑誌、古い地図がある。店主の多くは二代目、三代目だ。誰もパソコンで探さない。題名を告げると数秒考え、壁からその一冊を抜き出す。","facts":["釜山が戦時の臨時首都だった1950年に始まった。","路地には今も30軒ほどの古本屋が残る。","二代、三代と続く店が多い。","国際市場とBIFF広場のすぐ裏にある。"],"travelTips":["外国語の古書を置く店もある。店主に聞いてみよう。","多くは早じまいで、日曜に休む店もある。","カード不可の店が多い。現金を用意しよう。"],"bestTime":"通年","visitDuration":"1時間","ticket":"","openingHours":"09:00〜21:00、毎月第1・第3日曜と旧正月・秋夕は休み","galleryCaptions":["宝水洞の路地の本の壁"]},"zh":{"name":"寶水洞舊書街","summary":"一條窄巷裡有數十家舊書店，書從地板堆到天花板，自戰時延續至今。","story":"1950年，釜山成為臨時首都、難民湧入之際，一對夫婦在這條巷子鋪開麻布袋賣舊書。七十年後仍有約三十家，巷子依舊窄，書依舊從地板堆到天花板，砌成只留一人通道的紙牆。這裡有舊課本、日文小說、七〇年代雜誌、老地圖；許多老闆已是第二代、第三代。沒有人用電腦查書——說出書名，老闆想個幾秒，就直接從牆裡把那一本抽出來。","facts":["始於1950年，當時釜山是戰時的臨時首都。","巷內仍有約30家舊書店。","不少店由同一家族的第二或第三代經營。","就在國際市場與BIFF廣場後方。"],"travelTips":["有幾家備有外文舊書，直接問老闆即可。","多數店家提早打烊，部分週日休息。","帶現金，許多店不收卡。"],"bestTime":"全年","visitDuration":"1小時","ticket":"","openingHours":"09:00–21:00；每月第一與第三個週日及春節、中秋期間休息","galleryCaptions":["寶水洞巷內的書牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('songdo-cable-car', 'songdo-cable-car', 'busan', 'Bãi Songdo & cáp treo đáy kính', 'Songdo Beach & Marine Cable Car', 'beach', 129.018, 35.0755, 'Bãi tắm công cộng đầu tiên của Hàn Quốc, nay có cáp treo đáy kính bay thẳng ngang mặt vịnh.', 'Songdo mở cửa năm 1913, là bãi tắm công cộng đầu tiên của Hàn Quốc, rồi tàn lụi dần vào cuối thế kỷ 20 khi Haeundae lên ngôi. Thành phố làm lại từ đầu: cát được bơm bổ sung, một lối đi bằng gỗ uốn lượn nhô ra mặt nước, và năm 2017 tuyến cáp treo dài một cây số rưỡi nối hai mũi đất hai bên vịnh được mở. Cabin đáy kính là thứ đáng trả thêm tiền — nhìn xuống thấy sóng chạy bên dưới chân. Buổi tối, đèn cáp treo và đèn cầu treo phản chiếu xuống mặt nước, và các quán ốc dọc bờ đông kín người.', '["Mở cửa năm 1913, là bãi tắm công cộng đầu tiên của Hàn Quốc.","Tuyến cáp treo Songdo dài khoảng 1,6 km, khai trương năm 2017.","Có cabin đáy kính tính giá vé riêng.","Lối đi bằng gỗ Songdo Cloud Trails nhô ra mặt biển từ bờ bắc."]', '["Trả thêm cho cabin đáy kính — chênh lệch trải nghiệm rất rõ.","Đi lúc hoàng hôn rồi ăn tối ở dãy quán hải sản ven bờ.","Cáp treo ngừng chạy khi gió mạnh, kiểm tra trước khi đi."]', 'Tháng 5–9 (tắm biển), quanh năm cho cáp treo', '2–3 giờ', 'Cáp treo khứ hồi khoảng 17.000 KRW; cabin đáy kính Crystal 22.000 KRW', 'Bãi biển cả ngày, cáp treo 09:00–22:00', '["popular"]', '["bãi biển","cáp treo","hoàng hôn","hải sản"]', '[{"seed":"songdo-cable-car","caption":"Cáp treo bay ngang vịnh Songdo","ratio":"16/9"}]', '["jagalchi-market","huinnyeoul-culture-village"]', 0, 'https://en.namu.wiki/w/%EC%86%A1%EB%8F%84%ED%95%B4%EC%83%81%EC%BC%80%EC%9D%B4%EB%B8%94%EC%B9%B4', '2026-08-04', '{"en":{"name":"Songdo Beach & Marine Cable Car","summary":"Korea''s first public bathing beach, now crossed by a glass-floored cable car straight over the bay.","story":"Songdo opened in 1913 as Korea''s first public beach, then faded late in the 20th century as Haeundae took over. The city started again: sand was pumped back in, a curving boardwalk was pushed out over the water, and in 2017 a cable car a kilometre and a half long opened between the headlands on either side of the bay. The glass-floored cabin is worth the surcharge — you watch the swell run underneath your feet. At night the cable car lights and the bridge lights sit on the water, and the shellfish restaurants along the shore fill up.","facts":["Opened in 1913 as Korea''s first public bathing beach.","The Songdo cable car runs about 1.6km and opened in 2017.","Glass-floored cabins are available for a higher fare.","The Songdo Cloud Trails boardwalk reaches out over the sea from the north shore."],"travelTips":["Pay extra for the glass-floored cabin; the difference is obvious.","Ride at sunset, then eat at the seafood places along the shore.","The cable car stops in high wind — check before setting out."],"bestTime":"May–September for swimming, year-round for the cable car","visitDuration":"2–3 hours","ticket":"Cable car around 17,000 KRW return; the glass-floored Crystal cabin 22,000 KRW","openingHours":"Beach all day, cable car 09:00–22:00","galleryCaptions":["The cable car crossing Songdo bay"]},"ko":{"name":"송도해수욕장과 해상케이블카","summary":"한국 최초의 공설 해수욕장. 지금은 유리 바닥 케이블카가 만을 가로지른다.","story":"송도는 1913년 한국 최초의 공설 해수욕장으로 문을 열었다가, 20세기 후반 해운대에 밀려 시들었다. 시는 처음부터 다시 시작했다. 모래를 다시 채우고, 바다 위로 굽이치는 구름산책로를 내고, 2017년에는 만 양쪽 곶을 잇는 1.6km의 케이블카를 열었다. 유리 바닥 캐빈은 추가 요금이 아깝지 않다. 발밑으로 파도가 지나간다. 밤이면 케이블카와 다리의 불빛이 수면에 앉고, 해안의 조개구이집들이 가득 찬다.","facts":["1913년 개장한 한국 최초의 공설 해수욕장이다.","송도해상케이블카는 길이 약 1.6km로 2017년 개통했다.","유리 바닥 캐빈은 요금이 따로 책정된다.","북쪽 해안에서 바다로 뻗은 송도구름산책로가 있다."],"travelTips":["유리 바닥 캐빈에 추가 요금을 내자. 차이가 확실하다.","해질 무렵에 타고, 해안의 해산물집에서 저녁을 먹자.","바람이 세면 운행을 멈춘다. 출발 전에 확인하자."],"bestTime":"해수욕은 5~9월, 케이블카는 연중","visitDuration":"2~3시간","ticket":"케이블카 왕복 약 17,000원, 크리스탈 캐빈 22,000원","openingHours":"해변은 상시, 케이블카는 09:00~22:00","galleryCaptions":["송도만을 가로지르는 케이블카"]},"ja":{"name":"松島海水浴場と海上ケーブルカー","summary":"韓国初の公設海水浴場。今はガラス床のケーブルカーが湾を横切る。","story":"松島は1913年に韓国初の公設海水浴場として開き、二十世紀後半には海雲台に押されて寂れた。市は一から作り直した。砂を入れ直し、海の上へうねる雲の散策路を伸ばし、2017年には湾の両岸の岬を結ぶ1.6kmのケーブルカーを開いた。ガラス床のキャビンは追加料金の価値がある。足の下を波が走っていく。夜にはケーブルカーと橋の灯りが水面に乗り、海岸の貝焼きの店が満席になる。","facts":["1913年開場、韓国初の公設海水浴場である。","松島海上ケーブルカーは全長約1.6km、2017年開通。","ガラス床のキャビンは別料金である。","北岸から海へ伸びる松島雲の散策路がある。"],"travelTips":["ガラス床のキャビンに追加料金を払おう。違いは明らかだ。","夕暮れに乗り、海岸の海鮮店で夕食を。","強風時は運休する。出発前に確認しよう。"],"bestTime":"海水浴は5〜9月、ケーブルカーは通年","visitDuration":"2〜3時間","ticket":"ケーブルカー往復約17,000ウォン、クリスタルキャビンは22,000ウォン","openingHours":"海水浴場は終日、ケーブルカーは09:00〜22:00","galleryCaptions":["松島湾を横切るケーブルカー"]},"zh":{"name":"松島海水浴場與海上纜車","summary":"韓國第一座公共海水浴場，如今有玻璃底纜車直接橫越海灣。","story":"松島1913年開放，是韓國第一座公共海水浴場，二十世紀後期在海雲台崛起後逐漸沒落。市府從頭來過：回填沙灘、在海面上架起蜿蜒的雲端步道，並於2017年開通橫跨海灣兩岬、長約一點六公里的纜車。玻璃底車廂值得多付那筆錢——浪就從你腳下跑過去。入夜後，纜車與橋的燈光落在水面，岸邊的烤貝店家家客滿。","facts":["1913年開放，是韓國第一座公共海水浴場。","松島海上纜車全長約1.6公里，2017年通車。","玻璃底車廂另計票價。","北岸有伸入海面的松島雲端步道。"],"travelTips":["加價搭玻璃底車廂，差別非常明顯。","黃昏搭乘，再到岸邊海鮮店吃晚餐。","強風時會停駛，出發前先確認。"],"bestTime":"戲水為5至9月，纜車全年皆宜","visitDuration":"2至3小時","ticket":"纜車來回約17,000韓元，水晶車廂22,000韓元","openingHours":"海灘全日開放，纜車09:00–22:00","galleryCaptions":["橫越松島灣的纜車"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('busan-cinema-center', 'busan-cinema-center', 'busan', 'Trung tâm Điện ảnh Busan', 'Busan Cinema Center', 'city', 129.1265, 35.171, 'Mái đua dài tám mươi lăm mét không cột chống, phủ kín đèn LED — trụ sở của liên hoan phim Busan.', 'Trung tâm Điện ảnh Busan có một chi tiết khiến kỹ sư nào cũng phải ngẩng lên: tấm mái khổng lồ đua ra tám mươi lăm mét mà không có cột nào đỡ ở đầu mút, mặt dưới phủ hàng chục nghìn bóng LED chạy hình mỗi tối. Bên dưới là quảng trường ngoài trời với hơn bốn nghìn chỗ ngồi, nơi diễn ra lễ khai mạc Liên hoan phim quốc tế Busan mỗi tháng 10 — liên hoan phim lớn nhất châu Á. Ngoài mùa liên hoan, nơi này vẫn chiếu phim độc lập và phim kinh điển quanh năm với giá vé rẻ, và quảng trường thì luôn có người trượt ván.', '["Khánh thành năm 2011, thiết kế bởi văn phòng Coop Himmelb(l)au.","Mái đua dài khoảng 85m không có cột đỡ ở đầu mút.","Mặt dưới mái phủ hơn 40.000 bóng LED trình chiếu mỗi tối.","Là địa điểm chính của Liên hoan phim quốc tế Busan tổ chức vào tháng 10."]', '["Đến sau 19h để xem màn trình diễn đèn trên mái.","Vé xem phim ở rạp trong trung tâm rẻ hơn rạp thương mại.","Tháng 10 khu vực này rất đông vì liên hoan phim."]', 'Tháng 10 (liên hoan phim), quanh năm cho phần còn lại', '1–2 giờ', 'Miễn phí vào quảng trường', 'Quảng trường cả ngày, rạp theo lịch chiếu', '["trending"]', '["kiến trúc","điện ảnh","về đêm","LED"]', '[{"seed":"busan-cinema-center","caption":"Mái đèn LED về đêm","ratio":"16/9"}]', '["haeundae-beach","gwangalli-beach"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Busan Cinema Center","summary":"An 85-metre unsupported cantilever roof covered in LEDs — home of the Busan film festival.","story":"The Busan Cinema Center has one detail that makes every engineer look up: an enormous roof cantilevering eighty-five metres with no column under its tip, its underside carrying tens of thousands of LEDs that run animations each night. Beneath it is an outdoor plaza seating more than four thousand, where the Busan International Film Festival — the largest in Asia — opens each October. Outside festival season it screens independent and classic films all year at low prices, and there are always skateboarders on the plaza.","facts":["Opened in 2011, designed by the practice Coop Himmelb(l)au.","The roof cantilevers about 85m with no column at its tip.","Its underside carries more than 40,000 LEDs that play a show each evening.","It is the main venue of the Busan International Film Festival each October."],"travelTips":["Arrive after 7pm for the roof light show.","Tickets in the centre''s own cinemas are cheaper than commercial chains.","The area is very busy during the October festival."],"bestTime":"October for the festival, year-round otherwise","visitDuration":"1–2 hours","ticket":"Plaza free","openingHours":"Plaza all day, cinemas by screening schedule","galleryCaptions":["The LED roof at night"]},"ko":{"name":"영화의전당","summary":"기둥 없이 85m를 내민 지붕에 LED가 깔렸다. 부산국제영화제의 본거지다.","story":"영화의전당에는 공학자라면 누구나 올려다보게 되는 부분이 있다. 끝에 기둥 하나 없이 85m를 내민 거대한 지붕이다. 그 아래에는 수만 개의 LED가 깔려 밤마다 영상이 흐른다. 지붕 아래 야외광장은 4천 석이 넘고, 해마다 10월 아시아 최대 규모인 부산국제영화제의 개막식이 여기서 열린다. 영화제 기간이 아니어도 독립영화와 고전영화를 저렴한 값에 연중 상영하고, 광장에는 늘 스케이트보드를 타는 사람이 있다.","facts":["2011년 개관했으며 쿱 힘멜블라우가 설계했다.","지붕은 끝부분에 기둥 없이 약 85m를 내밀고 있다.","지붕 아래에는 4만 개가 넘는 LED가 설치되어 매일 밤 공연을 한다.","매년 10월 부산국제영화제의 주 무대다."],"travelTips":["지붕의 조명쇼를 보려면 저녁 7시 이후에 가자.","전당 내 상영관의 표는 일반 상업 영화관보다 싸다.","10월 영화제 기간에는 이 일대가 매우 붐빈다."],"bestTime":"영화제는 10월, 그 외에는 연중","visitDuration":"1~2시간","ticket":"광장 무료","openingHours":"광장은 상시, 상영관은 상영 일정에 따름","galleryCaptions":["밤의 LED 지붕"]},"ja":{"name":"映画の殿堂","summary":"柱なしで85m張り出した屋根にLEDが敷かれている。釜山国際映画祭の本拠地だ。","story":"映画の殿堂には、技術者なら誰でも見上げてしまう部分がある。先端に柱を一本も持たずに85m張り出した巨大な屋根だ。その裏面には数万個のLEDが敷かれ、夜ごと映像が流れる。屋根の下の野外広場は四千席を超え、毎年十月、アジア最大規模の釜山国際映画祭の開幕式がここで行われる。映画祭の時期でなくても、独立系映画や名作を安い料金で通年上映しており、広場にはいつもスケートボードの人がいる。","facts":["2011年開館、コープ・ヒンメルブラウの設計。","屋根は先端に柱なしで約85m張り出している。","屋根の裏面には4万個を超えるLEDが設置され、毎晩演出が行われる。","毎年10月の釜山国際映画祭の主会場である。"],"travelTips":["屋根の照明ショーを見るなら19時以降に。","館内の上映館のチケットは一般の商業館より安い。","10月の映画祭期間はこの一帯が非常に混む。"],"bestTime":"映画祭は10月、それ以外は通年","visitDuration":"1〜2時間","ticket":"広場は無料","openingHours":"広場は終日、上映館は上映日程による","galleryCaptions":["夜のLEDの屋根"]},"zh":{"name":"釜山電影殿堂","summary":"一片懸挑85公尺、末端無柱的屋頂，底面鋪滿LED——釜山影展的大本營。","story":"釜山電影殿堂有個細節會讓任何工程師抬頭：一片巨大的屋頂懸挑八十五公尺，末端沒有任何柱子支撐，底面鋪著數萬顆LED，每晚播放影像。屋頂之下是可容四千多人的露天廣場，每年十月，亞洲規模最大的釜山國際影展就在這裡開幕。非影展期間，這裡全年以低廉票價放映獨立與經典電影，廣場上永遠有人在玩滑板。","facts":["2011年啟用，由Coop Himmelb(l)au事務所設計。","屋頂懸挑約85公尺，末端無柱支撐。","屋頂底面裝有逾四萬顆LED，每晚演出燈光秀。","是每年10月釜山國際影展的主場地。"],"travelTips":["晚上七點後前往，才看得到屋頂燈光秀。","館內影廳票價比一般商業影城便宜。","10月影展期間這一帶非常擁擠。"],"bestTime":"影展在10月，其餘時間全年皆宜","visitDuration":"1至2小時","ticket":"廣場免費","openingHours":"廣場全日開放，影廳依放映時刻","galleryCaptions":["夜裡的LED屋頂"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('daewangam-park', 'daewangam-park', 'ulsan', 'Công viên Daewangam', 'Daewangam Park', 'park', 129.436, 35.489, 'Rừng thông trăm tuổi dẫn ra ghềnh đá đỏ nơi hoàng hậu Silla được cho là hoá rồng giữ biển.', 'Truyền thuyết kể hoàng hậu của vua Munmu nguyện hoá rồng canh giữ bờ biển, và tảng đá lớn ngoài khơi Ulsan chính là chỗ bà an nghỉ. Cầu sắt đỏ dẫn ra khối đá ấy, sóng đập trắng xoá bốn phía. Phía trong là rừng thông đen hơn một vạn cây, mát rượi kể cả giữa trưa hè, với đường mòn dẫn tới hải đăng trắng — một trong những hải đăng cổ nhất Hàn Quốc. Đây cũng là một trong những chỗ đón bình minh sớm nhất trên đất liền.', '["Rừng thông đen trong công viên có hơn 15.000 cây, nhiều cây trên 100 tuổi.","Hải đăng Ulgi hoạt động từ năm 1906.","Gắn với truyền thuyết hoàng hậu triều Silla hoá rồng.","Là một trong những điểm đón bình minh sớm nhất bán đảo."]', '["Đi sớm để đón bình minh trên ghềnh đá.","Đường ven biển trơn khi sóng lớn — bám lan can.","Kết hợp với bãi Ilsan ngay bên cạnh."]', 'Tháng 4–6 và 9–11', '2 giờ', '', 'Cả ngày', '["hidden-gem"]', '["biển","rừng thông","bình minh"]', '[{"seed":"daewangam-park","caption":"Cầu đỏ ra ghềnh Daewangam","ratio":"16/9"}]', '["ganjeolgot"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Daewangam Park","summary":"A century-old pine wood leading to red rocks where a Silla queen is said to have become a sea dragon.","story":"Legend holds that the queen of King Munmu vowed to become a dragon guarding the coast, and that the great rock offshore at Ulsan is where she rests. A red iron bridge crosses to it, with surf breaking white on all sides. Behind stands a black pine forest of more than ten thousand trees, cool even at noon in summer, with a path to a white lighthouse — one of the oldest in Korea. This is also one of the first places on the mainland to catch the sunrise.","facts":["The park''s black pine forest holds more than 15,000 trees, many over a century old.","Ulgi lighthouse has been in service since 1906.","Tied to the legend of a Silla queen turning into a dragon.","One of the earliest sunrise points on the peninsula."],"travelTips":["Come early for sunrise over the rocks.","The coastal path is slippery in heavy surf — hold the railing.","Combine with Ilsan beach next door."],"bestTime":"April–June and September–November","visitDuration":"2 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["The red bridge to Daewangam rock"]},"ko":{"name":"대왕암공원","summary":"백 년 솔숲을 지나면 신라 왕비가 용이 되었다는 붉은 바위가 나온다.","story":"문무왕의 왕비가 용이 되어 바다를 지키겠다 하였고, 울산 앞바다의 큰 바위가 그가 잠든 자리라는 전설이 전한다. 붉은 철제 다리가 그 바위로 이어지고 사방에서 파도가 하얗게 부서진다. 안쪽으로는 만 그루가 넘는 해송 숲이 한여름 대낮에도 서늘하고, 그 사이 오솔길이 한국에서 가장 오래된 등대 가운데 하나인 흰 울기등대로 이어진다. 육지에서 해가 가장 일찍 뜨는 곳 중 하나이기도 하다.","facts":["공원의 해송 숲에는 100년이 넘은 나무를 포함해 1만 5천 그루가 넘는 소나무가 있다.","울기등대는 1906년부터 불을 밝혀 왔다.","신라 왕비가 용이 되었다는 전설과 이어진다.","한반도에서 해가 가장 일찍 뜨는 곳 가운데 하나다."],"travelTips":["일찍 가서 바위 위로 뜨는 해를 보자.","파도가 높을 때는 해안길이 미끄러우니 난간을 잡자.","바로 옆 일산해수욕장과 함께 둘러보자."],"bestTime":"4~6월, 9~11월","visitDuration":"2시간","ticket":"","openingHours":"상시 개방","galleryCaptions":["대왕암으로 이어지는 붉은 다리"]},"ja":{"name":"大王岩公園","summary":"百年の松林を抜けると、新羅の王妃が龍になったという赤い岩が現れる。","story":"文武王の王妃が龍となって海を守ると誓い、蔚山沖の大きな岩がその眠る場所だという伝説がある。赤い鉄の橋がその岩へ渡り、四方で波が白く砕ける。内側には一万本を超えるクロマツの森が真夏の日中でも涼しく、その間の小道が韓国有数の古さを誇る白い蔚埼灯台へ続く。本土で日の出が最も早い場所のひとつでもある。","facts":["公園のクロマツ林には樹齢100年超を含む1万5千本以上の松がある。","蔚埼灯台は1906年から灯をともしてきた。","新羅の王妃が龍になったという伝説と結びつく。","朝鮮半島で日の出が最も早い場所のひとつ。"],"travelTips":["早めに行って岩の上に昇る日を見よう。","波が高い日は海岸路が滑る。手すりをつかもう。","隣の日山海水浴場と合わせて。"],"bestTime":"4〜6月、9〜11月","visitDuration":"2時間","ticket":"","openingHours":"終日開放","galleryCaptions":["大王岩へ続く赤い橋"]},"zh":{"name":"大王岩公園","summary":"穿過百年松林，來到傳說新羅王后化龍之處的紅色岩礁。","story":"傳說文武王的王后立誓化為護海之龍，蔚山外海的那塊巨岩便是她安息之處。一座紅色鐵橋通向那塊岩石，四面浪花翻白。內側是一萬多株黑松構成的樹林，盛夏正午也依然涼爽，林間小徑通往白色的蔚埼燈塔——韓國最古老的燈塔之一。這裡也是本土最早迎來日出的地點之一。","facts":["園內黑松林有逾15,000株松樹，其中不少樹齡逾百年。","蔚埼燈塔自1906年開始運作。","與新羅王后化龍的傳說相連。","是半島最早迎接日出的地點之一。"],"travelTips":["早點來，在岩礁上看日出。","浪大時海岸步道濕滑，請扶好欄杆。","可順道去隔壁的日山海水浴場。"],"bestTime":"4至6月、9至11月","visitDuration":"2小時","ticket":"","openingHours":"全日開放","galleryCaptions":["通往大王岩的紅色鐵橋"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('taehwagang-bamboo', 'taehwagang-bamboo', 'ulsan', 'Rừng tre Taehwagang', 'Taehwagang Bamboo Grove', 'park', 129.313, 35.554, 'Dải tre dài mười dặm chạy dọc dòng sông từng chết vì ô nhiễm, nay đầy cò về làm tổ.', 'Sông Taehwa từng là biểu tượng của cái giá công nghiệp hoá: nước đen, cá chết, không ai dám lại gần. Sau hai thập kỷ làm sạch, dòng sông hồi sinh và dải tre Simnidaebat hai bên bờ trở thành công viên quốc gia đầu tiên của một thành phố công nghiệp. Đi giữa rừng tre, ánh nắng lọc qua thân tre thành sọc xanh trên đường; buổi chiều hàng nghìn con cò trắng bay về đậu kín ngọn cây. Đây là câu chuyện phục hồi môi trường mà Ulsan tự hào nhất.', '["Dải tre dài khoảng 4 km dọc bờ sông Taehwa (tên gọi ''Simnidaebat'' nghĩa là ruộng tre mười dặm).","Sông Taehwa từng ô nhiễm nặng, được phục hồi từ đầu những năm 2000.","Là nơi trú của hàng vạn con cò và diệc mỗi mùa.","Được công nhận là vườn quốc gia đô thị của Hàn Quốc."]', '["Chiều tối là lúc chim về tổ, cảnh đáng xem nhất.","Có đường xe đạp chạy suốt dọc sông.","Lễ hội pháo hoa và lễ hội hoa mùa xuân tổ chức ngay tại bãi sông."]', 'Tháng 5–10', '1,5 giờ', '', 'Cả ngày', '[]', '["rừng tre","sông","chim"]', '[{"seed":"taehwagang-bamboo","caption":"Lối đi trong rừng tre","ratio":"16/9"}]', '["daewangam-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Taehwagang Bamboo Grove","summary":"A ten-mile bamboo belt along a river that once died of pollution and now fills with egrets.","story":"The Taehwa River used to be the price of industrialisation: black water, dead fish, nobody near it. Two decades of cleaning brought it back, and the Simnidaebat bamboo belt along its banks became the first national garden of an industrial city. Walking inside, sunlight filters through the stems in green stripes; towards evening thousands of white egrets come back to roost in the tops. This is the recovery story Ulsan is proudest of.","facts":["The bamboo belt runs about 4 km along the river (''Simnidaebat'' means ten-mile bamboo field).","The Taehwa River was heavily polluted and was restored from the early 2000s.","Thousands of egrets and herons roost here each season.","Recognised as a national urban garden of Korea."],"travelTips":["Late afternoon, when the birds return, is the sight worth timing for.","A cycle path runs the length of the river.","Fireworks and spring flower festivals are held on the riverbank."],"bestTime":"May–October","visitDuration":"1.5 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["A path inside the bamboo grove"]},"ko":{"name":"태화강 십리대숲","summary":"오염으로 죽었던 강을 따라 이어지는 대숲. 지금은 백로가 돌아온다.","story":"태화강은 한때 산업화의 대가 그 자체였다. 검은 물, 죽은 물고기, 아무도 다가가지 않는 강. 20년의 정화 끝에 강이 되살아났고 양안의 십리대숲은 산업도시 최초의 국가정원이 되었다. 대숲 사이를 걸으면 햇빛이 대나무 줄기를 지나며 초록 줄무늬를 만들고, 저녁이면 수천 마리의 백로가 나무 꼭대기로 돌아온다. 울산이 가장 자랑스러워하는 회복의 이야기다.","facts":["강변을 따라 약 4km의 대숲이 이어진다(''십리대밭'').","태화강은 심하게 오염되었다가 2000년대 초부터 복원되었다.","해마다 수만 마리의 백로와 왜가리가 찾아온다.","대한민국 국가정원으로 지정되었다."],"travelTips":["새들이 돌아오는 저녁 무렵이 가장 볼만하다.","강을 따라 자전거길이 이어진다.","강변 둔치에서 불꽃축제와 봄꽃축제가 열린다."],"bestTime":"5~10월","visitDuration":"1시간 30분","ticket":"","openingHours":"상시 개방","galleryCaptions":["대숲 사이의 산책로"]},"ja":{"name":"太和江 十里竹林","summary":"汚染で死んだ川に沿う竹林。今はサギが帰ってくる。","story":"太和江はかつて工業化の代償そのものだった。黒い水、死んだ魚、誰も近づかない川。二十年の浄化の末に川はよみがえり、両岸の十里竹林は工業都市初の国家庭園になった。竹の間を歩けば陽の光が幹を抜けて緑の縞をつくり、夕方には数千羽の白鷺が梢へ帰ってくる。蔚山が最も誇る回復の物語だ。","facts":["川沿いに約4kmの竹林が続く（「十里竹田」の名の由来）。","太和江は激しく汚染され、2000年代初頭から復元された。","毎季、数万羽のサギやアオサギが飛来する。","大韓民国の国家庭園に指定されている。"],"travelTips":["鳥が戻る夕方が最も見応えがある。","川沿いに自転車道が続く。","河川敷では花火祭りや春の花祭りが開かれる。"],"bestTime":"5〜10月","visitDuration":"1時間30分","ticket":"","openingHours":"終日開放","galleryCaptions":["竹林の中の散策路"]},"zh":{"name":"太和江十里竹林","summary":"沿著一度因污染而死去的河流延伸的竹林，如今白鷺歸來。","story":"太和江曾經是工業化代價的化身：黑水、死魚、沒人敢靠近。經過二十年整治，河流復活，兩岸的十里竹林成了工業城市的第一座國家庭園。走在竹林裡，陽光穿過竹幹落成一道道綠色條紋；傍晚，數千隻白鷺回到樹梢。這是蔚山最引以為傲的復原故事。","facts":["沿岸竹林約長4公里（「十里竹田」之名由此而來）。","太和江曾嚴重污染，自2000年代初開始復原。","每季有數萬隻白鷺與蒼鷺在此棲息。","被指定為大韓民國國家庭園。"],"travelTips":["傍晚鳥群歸巢時最值得一看。","沿河有自行車道。","河灘會舉辦煙火節與春季花卉節。"],"bestTime":"5至10月","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["竹林中的步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ganjeolgot', 'ganjeolgot', 'ulsan', 'Mũi Ganjeolgot', 'Ganjeolgot Cape', 'island', 129.36, 35.359, 'Mũi đất đón mặt trời đầu tiên của bán đảo Triều Tiên mỗi ngày đầu năm.', 'Mỗi sáng 1 tháng 1, hàng chục nghìn người đứng chật mũi đất này để xem mặt trời đầu tiên của năm nhô lên khỏi biển Đông — ở Ganjeolgot, nó lên sớm hơn bất kỳ nơi nào khác trên đất liền Hàn Quốc. Ngày thường, nơi đây yên tĩnh: một hải đăng trắng, đồng cải vàng vào tháng 4, và chiếc hộp thư khổng lồ nơi khách gửi thư cho chính mình, mỗi năm bưu điện phát đi một lần.', '["Là điểm đón bình minh sớm nhất trên đất liền Hàn Quốc.","Hải đăng Ganjeolgot cao 17m, hoạt động từ năm 1920.","Có hộp thư ''gửi thư cho tương lai'' cao hơn 5m.","Lễ hội đón bình minh đầu năm thu hút hàng chục nghìn người."]', '["Ngày 1/1 rất đông và lạnh — đi sớm, mặc thật ấm.","Tháng 4 có cánh đồng cải vàng nở ngay sau hải đăng.","Đi bus từ ga Ulsan (KTX) mất khoảng một giờ."]', 'Bình minh, đẹp nhất tháng 4 và ngày đầu năm', '1,5 giờ', '', 'Cả ngày', '[]', '["bình minh","hải đăng","biển"]', '[{"seed":"ganjeolgot","caption":"Hải đăng Ganjeolgot","ratio":"16/9"}]', '["daewangam-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Ganjeolgot Cape","summary":"The cape that takes the peninsula''s first sunrise every New Year''s Day.","story":"Every 1 January tens of thousands of people crowd this headland to watch the year''s first sun come out of the East Sea — at Ganjeolgot it rises earlier than anywhere else on the Korean mainland. On ordinary days it is quiet: a white lighthouse, fields of yellow rape flowers in April, and a giant postbox where visitors write letters to their future selves, posted once a year.","facts":["The earliest sunrise point on the Korean mainland.","Ganjeolgot lighthouse, 17m tall, has operated since 1920.","There is a ''letters to the future'' postbox more than 5m high.","The New Year sunrise festival draws tens of thousands."],"travelTips":["1 January is crowded and cold — arrive early and dress warmly.","In April a field of rape flowers blooms behind the lighthouse.","Buses from Ulsan KTX station take about an hour."],"bestTime":"Sunrise; best in April and on New Year''s Day","visitDuration":"1.5 hours","ticket":"","openingHours":"Open all day","galleryCaptions":["Ganjeolgot lighthouse"]},"ko":{"name":"간절곶","summary":"새해 첫날, 한반도에서 해가 가장 먼저 뜨는 곶.","story":"1월 1일이면 수만 명이 이 곶에 서서 동해에서 솟는 새해 첫 해를 본다. 간절곶에서는 한반도 육지 어디보다 해가 먼저 뜬다. 평소에는 조용하다. 흰 등대, 4월이면 노랗게 물드는 유채밭, 그리고 방문객이 미래의 자신에게 쓴 편지를 넣으면 1년에 한 번 발송하는 거대한 우체통이 있다.","facts":["한반도 육지에서 해가 가장 먼저 뜨는 곳이다.","간절곶 등대는 높이 17m로 1920년부터 운영되었다.","높이 5m가 넘는 ''소망 우체통''이 있다.","새해 해맞이 행사에 수만 명이 모인다."],"travelTips":["1월 1일은 매우 붐비고 춥다. 일찍 가고 두껍게 입자.","4월에는 등대 뒤로 유채꽃밭이 펼쳐진다.","울산역(KTX)에서 버스로 약 한 시간이다."],"bestTime":"해돋이 시간, 4월과 새해 첫날","visitDuration":"1시간 30분","ticket":"","openingHours":"상시 개방","galleryCaptions":["간절곶 등대"]},"ja":{"name":"艮絶岬","summary":"元日、朝鮮半島で最も早く日が昇る岬。","story":"1月1日には数万人がこの岬に立ち、東海から昇る新年最初の日を見る。艮絶岬では半島の陸地のどこよりも早く日が昇る。ふだんは静かだ。白い灯台、4月に黄色く染まる菜の花畑、そして未来の自分に宛てた手紙を入れると年に一度発送される巨大な郵便ポストがある。","facts":["朝鮮半島の陸地で日の出が最も早い場所。","艮絶岬灯台は高さ17m、1920年から稼働している。","高さ5mを超える「願いの郵便ポスト」がある。","新年の日の出行事には数万人が集まる。"],"travelTips":["1月1日は非常に混み、寒い。早めに行き厚着を。","4月には灯台の裏に菜の花畑が広がる。","蔚山駅（KTX）からバスで約1時間。"],"bestTime":"日の出の時間、4月と元日","visitDuration":"1時間30分","ticket":"","openingHours":"終日開放","galleryCaptions":["艮絶岬の灯台"]},"zh":{"name":"艮絕岬","summary":"每年元旦，朝鮮半島最早看到日出的海岬。","story":"每年1月1日，數萬人擠在這片海岬上，看新年第一輪太陽自東海升起——在艮絕岬，它比韓國本土任何地方都早。平常這裡很安靜：一座白色燈塔、四月轉黃的油菜花田，還有一個巨大的郵筒，旅人在此寫信給未來的自己，郵局每年寄出一次。","facts":["韓國本土日出最早的地點。","艮絕岬燈塔高17公尺，自1920年運作至今。","有一座高逾5公尺的「寄給未來」郵筒。","元旦日出活動可聚集數萬人。"],"travelTips":["1月1日人多又冷，請早到並穿暖。","四月燈塔後方有一片油菜花田。","自蔚山站（KTX）搭公車約一小時。"],"bestTime":"日出時分；四月與元旦最佳","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["艮絕岬燈塔"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bangudae-petroglyphs', 'bangudae-petroglyphs', 'ulsan', 'Tranh khắc đá Bangudae', 'Bangudae Petroglyphs', 'unesco', 129.175, 35.605, 'Vách đá khắc cảnh săn cá voi từ thời tiền sử — bằng chứng săn cá voi xưa nhất thế giới.', 'Trên một vách đá bên sông, người thời đồ đá mới đã khắc hơn ba trăm hình: cá voi mẹ cõng con, thuyền có người chèo, hươu, hổ, lưới bẫy. Đây được xem là ghi chép hình ảnh xưa nhất về việc săn cá voi trên thế giới. Trớ trêu là hồ chứa nước xây năm 1965 khiến vách đá bị ngập nhiều tháng mỗi năm, và cuộc tranh luận cứu tranh khắc kéo dài hàng chục năm. Khách xem qua ống nhòm từ đài quan sát bên kia sông; bảo tàng gần đó dựng bản sao kích thước thật.', '["Có hơn 300 hình khắc, niên đại ước tính 6.000–3.500 năm trước.","Được xem là ghi chép hình ảnh sớm nhất thế giới về săn cá voi.","Là Quốc bảo số 285 của Hàn Quốc.","Bị ngập nước nhiều tháng mỗi năm do hồ chứa Sayeon."]', '["Mang ống nhòm hoặc dùng ống nhòm đặt sẵn ở đài quan sát.","Ghé bảo tàng tranh khắc đá gần đó để xem bản sao chi tiết.","Mùa khô (mùa đông – đầu xuân) nước rút, dễ nhìn hơn."]', 'Tháng 11–4 (nước hồ thấp)', '1,5 giờ', '', 'Bảo tàng tranh khắc đá 09:00–18:00, mở thứ Ba–Chủ nhật; đóng cửa thứ Hai và 1/1. Đài quan sát vách đá ngoài trời xem tự do', '["hidden-gem","verified"]', '["khảo cổ","tiền sử","cá voi"]', '[{"seed":"bangudae-petroglyphs","caption":"Vách đá khắc hình cá voi","ratio":"16/9"}]', '["taehwagang-bamboo"]', 0, 'https://www.ulsan.go.kr/s/bangudae/main.ulsan', '2026-08-05', '{"en":{"name":"Bangudae Petroglyphs","summary":"Prehistoric whale-hunting scenes carved into a cliff — the world''s oldest record of whaling.","story":"On a cliff above a river, Neolithic people carved more than three hundred figures: whales with calves on their backs, boats with rowers, deer, tigers, traps. It is regarded as the oldest pictorial record of whaling anywhere. The irony is that a reservoir built in 1965 submerges the cliff for months each year, and the argument over how to save the carvings has run for decades. Visitors view them by telescope from an observation point across the water; a museum nearby holds a full-size replica.","facts":["More than 300 carvings, dated to roughly 6,000–3,500 years ago.","Considered the earliest pictorial record of whaling in the world.","National Treasure No. 285 of Korea.","Submerged for months each year by the Sayeon reservoir."],"travelTips":["Bring binoculars, or use the telescopes at the viewpoint.","Visit the petroglyph museum nearby to see the replica in detail.","The dry season (winter to early spring) lowers the water and improves the view."],"bestTime":"November–April (low reservoir)","visitDuration":"1.5 hours","ticket":"","openingHours":"The petroglyph museum runs 09:00–18:00, Tuesday to Sunday; closed Mondays and 1 January. The outdoor viewpoint over the cliff is freely accessible","galleryCaptions":["The carved whale panel"]},"ko":{"name":"반구대 암각화","summary":"선사시대 고래잡이를 새긴 절벽. 세계에서 가장 오래된 포경 기록이다.","story":"강가 절벽에 신석기 사람들이 삼백 점이 넘는 그림을 새겼다. 새끼를 업은 고래, 노 젓는 사람이 탄 배, 사슴과 호랑이와 덫. 세계에서 가장 오래된 포경의 그림 기록으로 평가된다. 얄궂게도 1965년에 만든 댐 때문에 절벽은 해마다 여러 달 물에 잠기고, 암각화를 구하는 논쟁은 수십 년째 이어진다. 관람은 강 건너 전망대에서 망원경으로 하고, 인근 박물관에는 실물 크기 복제가 있다.","facts":["300점이 넘는 그림이 있으며 6,000~3,500년 전의 것으로 추정된다.","세계에서 가장 이른 포경 그림 기록으로 평가된다.","대한민국 국보 제285호다.","사연댐 때문에 해마다 여러 달 물에 잠긴다."],"travelTips":["쌍안경을 챙기거나 전망대의 망원경을 이용하자.","인근 암각화박물관에서 복제본을 자세히 볼 수 있다.","수위가 낮은 겨울~초봄이 보기에 좋다."],"bestTime":"11~4월(수위가 낮은 시기)","visitDuration":"1시간 30분","ticket":"","openingHours":"암각화박물관은 화~일 09:00~18:00, 월요일과 1월 1일 휴관. 야외 전망대는 자유롭게 이용할 수 있다","galleryCaptions":["고래가 새겨진 암벽"]},"ja":{"name":"盤亀台岩刻画","summary":"先史時代の捕鯨を刻んだ崖。世界最古の捕鯨の記録である。","story":"川沿いの崖に、新石器時代の人々が三百を超える図像を刻んだ。子を背負うクジラ、漕ぎ手の乗る舟、シカ、トラ、罠。世界で最も古い捕鯨の絵の記録と評価される。皮肉にも1965年のダムのため崖は毎年数か月水に沈み、岩刻画をどう救うかの議論が数十年続いている。見学は川向こうの展望台から望遠鏡で行い、近くの博物館には実物大の複製がある。","facts":["300を超える図像があり、6,000〜3,500年前のものと推定される。","世界最古級の捕鯨の絵画記録とされる。","大韓民国国宝第285号。","泗淵ダムのため毎年数か月水没する。"],"travelTips":["双眼鏡を持参するか、展望台の望遠鏡を使おう。","近くの岩刻画博物館で複製を細部まで見られる。","水位の下がる冬から早春が見やすい。"],"bestTime":"11〜4月（水位が低い時期）","visitDuration":"1時間30分","ticket":"","openingHours":"岩刻画博物館は火〜日09:00〜18:00、月曜と1月1日は休館。屋外の展望台は自由に利用できる","galleryCaptions":["クジラが刻まれた岩壁"]},"zh":{"name":"盤龜台岩刻畫","summary":"刻在崖壁上的史前捕鯨場景，是世界最早的捕鯨紀錄。","story":"在一面臨河的崖壁上，新石器時代的人刻下三百多個圖像：背著幼鯨的母鯨、載著划槳者的船、鹿、虎與陷阱。它被視為世界上最早以圖像記錄捕鯨的遺跡。諷刺的是，1965年建的水庫讓崖壁每年有數月沒入水中，如何拯救岩刻畫的爭論已持續數十年。遊客在對岸觀景台以望遠鏡觀看，附近博物館則有原尺寸複製品。","facts":["刻有三百多個圖像，年代約在距今6,000至3,500年前。","被視為世界最早的捕鯨圖像紀錄。","為大韓民國國寶第285號。","因泗淵水庫，每年有數月沒入水中。"],"travelTips":["自備望遠鏡，或使用觀景台的望遠設備。","到附近的岩刻畫博物館可近距離看複製品。","枯水期（冬季至初春）水位低，較容易觀看。"],"bestTime":"11月至4月（水位較低）","visitDuration":"1.5小時","ticket":"","openingHours":"岩刻畫博物館週二至週日09:00–18:00，週一與1月1日休館；戶外觀景台可自由前往","galleryCaptions":["刻著鯨魚的岩壁"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jangsaengpo-whale-village', 'jangsaengpo-whale-village', 'ulsan', 'Làng văn hoá cá voi Jangsaengpo', 'Jangsaengpo Whale Culture Village', 'museum', 129.386, 35.501, 'Cảng săn cá voi cuối cùng của Hàn Quốc, nay là bảo tàng kể lại nghề đã bị cấm từ năm 1986.', 'Jangsaengpo từng là trung tâm săn cá voi của Hàn Quốc; đến năm 1986, khi lệnh cấm quốc tế có hiệu lực, cả một nghề và cả một lối sống biến mất chỉ trong một mùa. Thay vì lờ đi, thành phố dựng lại nguyên khu phố thợ săn cá voi thập niên 1960 — tiệm cắt tóc, quán rượu, nhà máy chế biến, rạp chiếu bóng — và mở một bảo tàng cá voi bên cạnh, nơi treo bộ xương cá voi lớn nguyên vẹn. Có cả tàu ra vịnh xem cá heo hoang. Cách kể ở đây thẳng thắn một cách bất ngờ: vừa là bảo tàng ký ức nghề nghiệp, vừa là bài học về việc săn bắt đã đẩy loài vật tới đâu.', '["Jangsaengpo là căn cứ săn cá voi chính của Hàn Quốc cho đến lệnh cấm năm 1986.","Khu phố thợ săn thập niên 1960 được dựng lại nguyên trạng làm bảo tàng ngoài trời.","Bảo tàng Cá voi trưng bày bộ xương cá voi nguyên vẹn và tàu săn cũ.","Có tour tàu ra vịnh Ulsan ngắm cá heo hoang dã."]', '["Tour ngắm cá heo phụ thuộc thời tiết và không đảm bảo thấy cá — hỏi kỹ trước khi mua.","Bảo tàng và làng tính vé riêng, có vé gộp rẻ hơn.","Kết hợp với đài quan sát cầu Ulsan cách đó khoảng 15 phút xe."]', 'Tháng 4–6 và 9–10', '2–3 giờ', '3.000 KRW cho làng văn hoá, 3.000 KRW cho bảo tàng cá voi (mua riêng)', '09:00–18:00, đóng cửa thứ Hai', '["hidden-gem"]', '["cá voi","bảo tàng","lịch sử nghề","gia đình"]', '[{"seed":"jangsaengpo-whale-village","caption":"Khu phố thợ săn cá voi dựng lại","ratio":"16/9"}]', '["ulsan-bridge-observatory","daewangam-park"]', 0, 'https://en.trippose.com/tour/jangsaengpo-whale-culture-village', '2026-08-04', '{"en":{"name":"Jangsaengpo Whale Culture Village","summary":"Korea''s last whaling port, now a museum to a trade banned since 1986.","story":"Jangsaengpo was the centre of Korean whaling until the international ban took effect in 1986, when an entire trade and an entire way of life vanished within a season. Rather than let it go quietly, the city rebuilt a whole 1960s whalers'' quarter — barber''s shop, bar, processing plant, cinema — and opened a whale museum beside it, where a complete large whale skeleton hangs. There is also a boat out into the bay to look for wild dolphins. The telling here is unexpectedly frank: part memorial to a lost trade, part lesson in where hunting took the animals.","facts":["Jangsaengpo was Korea''s main whaling base until the 1986 ban.","A 1960s whalers'' quarter has been rebuilt in full as an open-air museum.","The Whale Museum displays a complete whale skeleton and an old whaling boat.","Boat tours run into Ulsan bay to look for wild dolphins."],"travelTips":["Dolphin trips depend on weather and guarantee nothing — ask before buying.","The museum and the village are ticketed separately; a combined ticket is cheaper.","Combine it with the Ulsan Bridge Observatory, 15 minutes away by car."],"bestTime":"April–June and September–October","visitDuration":"2–3 hours","ticket":"3,000 KRW for the culture village and 3,000 KRW for the whale museum, bought separately","openingHours":"09:00–18:00, closed Mondays","galleryCaptions":["The rebuilt whalers'' quarter"]},"ko":{"name":"장생포 고래문화마을","summary":"한국 마지막 포경 항구. 1986년 금지된 그 일을 기억하는 마을이 되었다.","story":"장생포는 1986년 국제 포경 금지가 발효되기 전까지 한국 포경의 중심이었다. 그해 한 계절 만에 하나의 산업과 하나의 생활방식이 사라졌다. 시는 그것을 조용히 보내는 대신 1960년대 포경 마을을 통째로 되살렸다. 이발소, 선술집, 해체장, 극장까지. 그 옆에는 고래박물관이 있고 대형 고래의 온전한 골격이 걸려 있다. 만으로 나가 야생 돌고래를 찾는 배도 있다. 이곳의 설명은 뜻밖에 솔직하다. 사라진 생업에 대한 기록이면서, 포획이 그 동물들을 어디까지 몰아갔는지에 대한 이야기이기도 하다.","facts":["장생포는 1986년 금지 이전까지 한국 포경의 주요 기지였다.","1960년대 포경 마을을 그대로 재현한 야외 전시 마을이 있다.","고래박물관에는 온전한 고래 골격과 옛 포경선이 전시되어 있다.","울산만으로 나가 야생 돌고래를 찾는 배 관광이 있다."],"travelTips":["돌고래 관광은 날씨에 좌우되고 목격을 보장하지 않는다. 사기 전에 확인하자.","박물관과 마을은 요금이 따로이며 통합권이 더 싸다.","차로 15분 거리의 울산대교 전망대와 묶어서 보자."],"bestTime":"4~6월, 9~10월","visitDuration":"2~3시간","ticket":"고래문화마을 3,000원, 고래박물관 3,000원(별도 발권)","openingHours":"09:00~18:00, 월요일 휴관","galleryCaptions":["재현된 포경 마을"]},"ja":{"name":"長生浦クジラ文化村","summary":"韓国最後の捕鯨港。1986年に禁じられた生業を記憶する村になった。","story":"長生浦は1986年に国際的な捕鯨禁止が発効するまで、韓国の捕鯨の中心だった。その年、ひとつの産業とひとつの暮らし方がひと季節のうちに消えた。市はそれを静かに手放す代わりに、1960年代の捕鯨の町をまるごと復元した。理髪店、居酒屋、解体場、映画館まで。その隣にはクジラ博物館があり、大型鯨の完全な骨格が吊られている。湾へ出て野生のイルカを探す船もある。ここの語り口は意外なほど率直だ。失われた生業の記録であり、同時に捕獲がその動物たちをどこまで追い詰めたかの話でもある。","facts":["長生浦は1986年の禁止まで韓国の主要な捕鯨基地だった。","1960年代の捕鯨の町がそのまま復元され、野外展示になっている。","クジラ博物館には完全な鯨の骨格と旧捕鯨船が展示されている。","蔚山湾へ出て野生のイルカを探す船のツアーがある。"],"travelTips":["イルカのツアーは天候に左右され、遭遇は保証されない。買う前に確認を。","博物館と村は別料金で、共通券のほうが安い。","車で15分の蔚山大橋展望台と合わせて回ろう。"],"bestTime":"4〜6月、9〜10月","visitDuration":"2〜3時間","ticket":"クジラ文化村3,000ウォン、クジラ博物館3,000ウォン（別売り）","openingHours":"09:00〜18:00、月曜休館","galleryCaptions":["復元された捕鯨の町"]},"zh":{"name":"長生浦鯨魚文化村","summary":"韓國最後的捕鯨港，如今成了一座紀念1986年遭禁行業的村落。","story":"長生浦曾是韓國捕鯨的中心，直到1986年國際禁令生效——那一季之內，一整個行業與一整套生活方式就此消失。市府沒有讓它悄悄過去，而是完整重建了1960年代的捕鯨聚落：理髮店、酒館、加工場、電影院；旁邊另設鯨魚博物館，館內懸著一副完整的大型鯨骨。還有船隻出海進入海灣尋找野生海豚。這裡的敘述坦率得出乎意料：既是對消逝行業的紀念，也是一堂關於獵捕把這些動物逼到何處的課。","facts":["長生浦是1986年禁令之前韓國主要的捕鯨基地。","1960年代的捕鯨聚落被完整重建為露天展示村。","鯨魚博物館展出完整鯨骨與舊捕鯨船。","有船班駛入蔚山灣尋找野生海豚。"],"travelTips":["賞豚行程看天候，且不保證見得到，購票前請先問清楚。","博物館與村落分開售票，購買套票較便宜。","可與車程15分鐘的蔚山大橋展望台排在一起。"],"bestTime":"4至6月與9至10月","visitDuration":"2至3小時","ticket":"鯨魚文化村3,000韓元，鯨魚博物館3,000韓元（分開購票）","openingHours":"09:00–18:00，週一休館","galleryCaptions":["重建的捕鯨聚落"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ganwoljae-silver-grass', 'ganwoljae-silver-grass', 'ulsan', 'Đèo Ganwoljae & cỏ lau Yeongnam Alps', 'Ganwoljae & the Yeongnam Alps', 'mountain', 129.01, 35.573, 'Cánh đồng cỏ lau trên yên núi ở độ cao chín trăm mét, tháng 10 chuyển bạc và đổ sóng theo gió.', '''Yeongnam Alps'' là cách người Hàn gọi cụm chín ngọn núi trên một nghìn mét quanh ranh giới Ulsan, Gyeongbuk và Gyeongnam. Điểm được yêu nhất trong cụm ấy là Ganwoljae, một yên núi ở độ cao khoảng chín trăm mét phủ kín cỏ lau eoksae. Tháng 10, cả sườn yên chuyển màu bạc và khi gió thổi qua, đám cỏ đổ thành từng đợt sóng — đó là lý do hàng nghìn người leo lên đây mỗi cuối tuần mùa thu. Đường lên từ Baenaegol mất chừng hai tiếng, không quá khó, và trên yên có nhà tránh trú cùng một quán bán mì gói nóng.', '["Ganwoljae là yên núi ở độ cao khoảng 900m trong cụm Yeongnam Alps.","''Yeongnam Alps'' gồm chín đỉnh núi trên 1.000m nằm giáp ranh ba tỉnh.","Cỏ lau eoksae chuyển bạc và đẹp nhất vào tháng 10.","Có cáp treo Yeongnam Alps lên gần đỉnh Sinbulsan gần đó."]', '["Cuối tuần tháng 10 rất đông — đi ngày thường hoặc lên từ sáng sớm.","Trên yên gió mạnh và lạnh hơn dưới chân núi vài độ, mang thêm áo.","Đường mòn không có nước dọc đường, mang đủ nước theo."]', 'Tháng 10 (mùa cỏ lau)', 'Nửa ngày', '', 'Cả ngày (nên lên vào ban ngày)', '["hidden-gem","trending"]', '["cỏ lau","leo núi","mùa thu","toàn cảnh"]', '[{"seed":"ganwoljae-silver-grass","caption":"Cỏ lau trên yên Ganwoljae","ratio":"16/9"}]', '["bangudae-petroglyphs"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Ganwoljae & the Yeongnam Alps","summary":"A field of silver grass on a nine-hundred-metre saddle, turning silver in October and rolling in the wind.","story":"''Yeongnam Alps'' is what Koreans call the cluster of nine thousand-metre peaks around the borders of Ulsan, North and South Gyeongsang. The best-loved spot among them is Ganwoljae, a saddle at about nine hundred metres covered in eoksae silver grass. In October the whole slope turns silver and, when the wind crosses it, the grass falls in waves — which is why thousands climb up here on autumn weekends. The route from Baenaegol takes about two hours and is not hard; there is a shelter on the saddle and a stall selling hot instant noodles.","facts":["Ganwoljae is a saddle at about 900m within the Yeongnam Alps.","The ''Yeongnam Alps'' are nine peaks over 1,000m across three provincial borders.","The eoksae silver grass is at its best in October.","A cable car runs to near the summit of nearby Sinbulsan."],"travelTips":["October weekends are packed — go on a weekday or set off at dawn.","The saddle is windy and several degrees colder than the valley; bring a layer.","There is no water on the trail; carry enough with you."],"bestTime":"October (silver grass season)","visitDuration":"Half a day","ticket":"","openingHours":"Open all day (best climbed in daylight)","galleryCaptions":["Silver grass on the Ganwoljae saddle"]},"ko":{"name":"간월재와 영남알프스","summary":"해발 900m 안부를 덮은 억새밭. 10월이면 은빛으로 변해 바람에 물결친다.","story":"''영남알프스''는 울산과 경북, 경남 경계에 모인 1,000m 넘는 아홉 봉우리를 부르는 이름이다. 그 가운데 가장 사랑받는 곳이 간월재다. 해발 900m쯤의 안부가 온통 억새로 덮여 있다. 10월이면 비탈 전체가 은빛으로 바뀌고, 바람이 지나가면 억새가 물결처럼 눕는다. 가을 주말마다 수천 명이 오르는 이유다. 배내골에서 오르면 두 시간쯤 걸리고 그리 어렵지 않다. 안부에는 대피소와 뜨거운 라면을 파는 매점이 있다.","facts":["간월재는 영남알프스 안의 해발 약 900m 안부다.","''영남알프스''는 세 개 도 경계에 걸친 1,000m 이상 아홉 봉우리를 가리킨다.","억새는 10월에 은빛으로 가장 좋다.","가까운 신불산 정상 부근까지 영남알프스 케이블카가 오른다."],"travelTips":["10월 주말은 매우 붐빈다. 평일이나 이른 아침에 오르자.","안부는 바람이 세고 아래보다 몇 도 춥다. 겉옷을 챙기자.","등산로에 식수가 없다. 물을 충분히 지고 가자."],"bestTime":"10월(억새철)","visitDuration":"반나절","ticket":"","openingHours":"상시(낮에 오르기를 권함)","galleryCaptions":["간월재 안부의 억새"]},"ja":{"name":"澗月嶺と嶺南アルプス","summary":"標高900mの鞍部を覆うススキの原。10月には銀色に変わり、風で波打つ。","story":"「嶺南アルプス」は、蔚山と慶尚北道・慶尚南道の境に集まる千メートル超の九つの峰の呼び名だ。その中で最も愛されているのが澗月嶺である。標高九百メートルほどの鞍部が一面のススキに覆われている。十月になると斜面全体が銀色に変わり、風が渡るとススキが波のように倒れる。秋の週末ごとに数千人が登る理由だ。ペネゴルからは二時間ほどで、さほど難しくない。鞍部には避難小屋と、熱いラーメンを売る売店がある。","facts":["澗月嶺は嶺南アルプス内の標高約900mの鞍部である。","「嶺南アルプス」は三つの道の境にまたがる1,000m超の九峰を指す。","ススキは10月が最も美しい。","近くの神佛山の山頂近くまで嶺南アルプス・ロープウェーが上る。"],"travelTips":["10月の週末は非常に混む。平日か早朝に登ろう。","鞍部は風が強く、麓より数度寒い。羽織るものを持とう。","登山道に水場はない。十分に持って上がろう。"],"bestTime":"10月（ススキの季節）","visitDuration":"半日","ticket":"","openingHours":"終日（日中に登るのがよい）","galleryCaptions":["澗月嶺の鞍部のススキ"]},"zh":{"name":"澗月嶺與嶺南阿爾卑斯","summary":"海拔九百公尺鞍部上的芒草原，十月轉為銀色，隨風翻起波浪。","story":"「嶺南阿爾卑斯」是韓國人對聚集在蔚山與慶尚南北道交界處那九座逾千公尺山峰的稱呼。其中最受喜愛的是澗月嶺——一處海拔約九百公尺的鞍部，滿覆芒草。到了十月，整片坡面轉成銀色，風一掠過，芒草便一波波倒伏。這正是每逢秋日週末就有數千人上山的原因。自梨內谷起登約需兩小時，難度不高；鞍部上有避難小屋與一間賣熱泡麵的小舖。","facts":["澗月嶺是嶺南阿爾卑斯山區中海拔約900公尺的鞍部。","「嶺南阿爾卑斯」指橫跨三道交界、逾1,000公尺的九座山峰。","芒草以10月最美。","鄰近的神佛山有纜車可上抵接近山頂處。"],"travelTips":["十月週末非常擁擠，改挑平日或天亮就出發。","鞍部風大，比山下低好幾度，記得帶外套。","步道沿途沒有水源，請自行帶足飲水。"],"bestTime":"10月（芒草季）","visitDuration":"半天","ticket":"","openingHours":"全日開放（建議白天上山）","galleryCaptions":["澗月嶺鞍部的芒草"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('ulsan-bridge-observatory', 'ulsan-bridge-observatory', 'ulsan', 'Đài quan sát cầu Ulsan', 'Ulsan Bridge Observatory', 'city', 129.3915, 35.5195, 'Chỗ duy nhất nhìn thấy trọn bộ máy công nghiệp Ulsan: nhà máy đóng tàu, lọc dầu và cầu treo dài nhất nước.', 'Ulsan là thành phố công nghiệp nặng của Hàn Quốc — nơi đặt nhà máy ô tô lớn nhất thế giới tính theo một địa điểm, một trong những xưởng đóng tàu lớn nhất, và cả một tổ hợp hoá dầu. Từ đài quan sát trên núi Hwajeongsan, toàn bộ guồng máy ấy hiện ra cùng lúc: cần cẩu giàn xếp hàng bên vịnh, ống khói lọc dầu, và cây cầu treo Ulsan dài một nghìn một trăm mét vắt ngang cửa vịnh. Ban ngày đây là bài học về cách Hàn Quốc công nghiệp hoá; ban đêm, khi các tổ hợp hoá dầu bật đèn, nó biến thành một thứ cảnh quan khác hẳn — lạnh, sáng và rất khó rời mắt.', '["Cầu Ulsan dài khoảng 1.150m, là cầu treo một nhịp dài nhất Hàn Quốc khi khánh thành năm 2015.","Đài quan sát cao 63m, nằm trên núi Hwajeongsan.","Nhìn thấy được xưởng đóng tàu Hyundai và tổ hợp hoá dầu Ulsan.","Vào đài quan sát miễn phí."]', '["Lên sau khi trời tối để thấy tổ hợp công nghiệp lên đèn.","Không có phương tiện công cộng thuận tiện — nên đi taxi hoặc tự lái.","Ngày nhiều bụi mịn tầm nhìn kém hẳn, kiểm tra chỉ số trước khi đi."]', 'Tháng 10–3 (không khí trong hơn)', '1 giờ', 'Miễn phí', '09:00–21:00, vào cửa cuối 20:30; nghỉ thứ Hai tuần thứ hai và thứ tư hằng tháng, cùng ngày Tết và Chuseok', '["hidden-gem"]', '["công nghiệp","toàn cảnh","về đêm","cầu"]', '[{"seed":"ulsan-bridge-observatory","caption":"Cầu Ulsan và vịnh công nghiệp về đêm","ratio":"16/9"}]', '["jangsaengpo-whale-village","daewangam-park"]', 0, 'https://www.ulsan.go.kr/', '2026-08-05', '{"en":{"name":"Ulsan Bridge Observatory","summary":"The one place to see Ulsan''s industrial machine whole: shipyards, refineries and the country''s longest suspension bridge.","story":"Ulsan is Korea''s heavy industrial city — home to the largest car plant in the world on a single site, one of the biggest shipyards, and a full petrochemical complex. From the observatory on Hwajeongsan the entire apparatus appears at once: gantry cranes lined along the bay, refinery stacks, and the 1,150-metre Ulsan suspension bridge across the harbour mouth. By day it is a lesson in how Korea industrialised; by night, when the petrochemical plants light up, it becomes something else entirely — cold, brilliant and hard to look away from.","facts":["The Ulsan Bridge spans about 1,150m and was Korea''s longest single-span suspension bridge when it opened in 2015.","The observatory tower is 63m tall, on Hwajeongsan hill.","The Hyundai shipyard and the Ulsan petrochemical complex are both visible.","Entry to the observatory is free."],"travelTips":["Go after dark to see the industrial complex lit up.","There is no convenient public transport; take a taxi or drive.","Visibility drops badly on high fine-dust days — check the index first."],"bestTime":"October–March (clearer air)","visitDuration":"1 hour","ticket":"Free","openingHours":"09:00–21:00, last entry 20:30; closed the second and fourth Monday of each month and on Seollal and Chuseok","galleryCaptions":["The Ulsan Bridge and the industrial bay at night"]},"ko":{"name":"울산대교 전망대","summary":"울산이라는 산업 기계를 통째로 볼 수 있는 유일한 자리. 조선소와 정유공장, 그리고 국내 최장 현수교.","story":"울산은 한국 중공업의 도시다. 단일 부지 기준 세계 최대 자동차 공장, 손꼽히는 조선소, 그리고 석유화학 단지가 모두 여기 있다. 화정산 전망대에 오르면 그 장치 전체가 한눈에 들어온다. 만을 따라 늘어선 골리앗 크레인, 정유공장의 굴뚝, 그리고 항만 입구를 가로지르는 길이 1,150m의 울산대교. 낮에는 한국이 어떻게 산업화했는지에 대한 수업이고, 밤에 석유화학 단지에 불이 들어오면 완전히 다른 풍경이 된다. 차갑고 눈부시고, 좀처럼 눈을 떼기 어렵다.","facts":["울산대교는 길이 약 1,150m로, 2015년 개통 당시 국내 최장 단경간 현수교였다.","전망대 탑은 높이 63m로 화정산에 있다.","현대중공업 조선소와 울산 석유화학단지가 함께 보인다.","전망대 입장은 무료다."],"travelTips":["어두워진 뒤에 올라 산업단지의 불빛을 보자.","대중교통이 마땅치 않다. 택시나 자차를 이용하자.","미세먼지가 심한 날은 시야가 크게 나빠진다. 수치를 먼저 확인하자."],"bestTime":"10~3월(공기가 더 맑다)","visitDuration":"1시간","ticket":"무료","openingHours":"09:00~21:00, 입장 마감 20:30. 매월 둘째·넷째 월요일과 설날·추석 당일 휴관","galleryCaptions":["밤의 울산대교와 산업 항만"]},"ja":{"name":"蔚山大橋展望台","summary":"蔚山という産業機械を丸ごと見渡せる唯一の場所。造船所と製油所、そして国内最長の吊り橋。","story":"蔚山は韓国の重工業都市だ。単一敷地としては世界最大の自動車工場、屈指の造船所、そして石油化学コンビナートがすべてここにある。花亭山の展望台に上ると、その装置全体が一度に見える。湾に沿って並ぶガントリークレーン、製油所の煙突、そして港の入口を跨ぐ全長1,150mの蔚山大橋。昼は韓国がいかに工業化したかの授業であり、夜、石油化学コンビナートに灯が入ると、まったく別の風景になる。冷たく、まぶしく、目を離しにくい。","facts":["蔚山大橋は全長約1,150m、2015年の開通時は韓国最長の単径間吊り橋だった。","展望塔は高さ63mで花亭山の上にある。","現代重工業の造船所と蔚山石油化学団地がともに見える。","展望台の入場は無料である。"],"travelTips":["暗くなってから上り、工業団地の灯りを見よう。","使える公共交通がない。タクシーか自家用車で。","微小粒子状物質の多い日は視界が大きく落ちる。数値を先に確認しよう。"],"bestTime":"10〜3月（空気がより澄む）","visitDuration":"1時間","ticket":"無料","openingHours":"09:00〜21:00、最終入場20:30。毎月第2・第4月曜と旧正月・秋夕当日は休館","galleryCaptions":["夜の蔚山大橋と工業港"]},"zh":{"name":"蔚山大橋展望台","summary":"唯一能把蔚山這部工業機器一次看全的地方：造船廠、煉油廠，以及韓國最長的吊橋。","story":"蔚山是韓國的重工業城市——全球單一廠址最大的汽車廠、數一數二的造船廠，以及一整片石化園區都在這裡。從花亭山上的展望台望去，這整套裝置同時展開：沿灣排開的門式起重機、煉油廠的煙囪，以及橫跨港口入口、長一千一百五十公尺的蔚山大橋。白天，它是一堂關於韓國如何工業化的課；入夜後石化廠亮起燈，它又成了另一種東西——冰冷、明亮，讓人難以移開視線。","facts":["蔚山大橋長約1,150公尺，2015年通車時是韓國最長的單跨吊橋。","展望塔高63公尺，位於花亭山上。","現代重工造船廠與蔚山石化園區同時盡收眼底。","展望台免費入場。"],"travelTips":["天黑之後再上去，才看得到工業區的燈火。","沒有方便的大眾運輸，建議搭計程車或自駕。","細懸浮微粒濃度高的日子視野極差，出發前先查空品指數。"],"bestTime":"10月至隔年3月（空氣較清）","visitDuration":"1小時","ticket":"免費","openingHours":"09:00–21:00，最後入場20:30；每月第二與第四個週一及春節、中秋當日休館","galleryCaptions":["夜裡的蔚山大橋與工業港灣"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jujeon-pebble-beach', 'jujeon-pebble-beach', 'ulsan', 'Bãi cuội Jujeon', 'Jujeon Pebble Beach', 'beach', 129.431, 35.573, 'Bãi biển không có cát, chỉ toàn cuội đen tròn, và tiếng sóng rút để lại là âm thanh riêng của nơi này.', 'Jujeon không có một hạt cát nào. Cả bãi dài một cây số rưỡi phủ kín cuội đen tròn nhẵn, to bằng nắm tay, và điều khiến người ta ngồi lại lâu là âm thanh: khi sóng rút, hàng triệu viên cuội va vào nhau tạo thành tiếng lạo xạo kéo dài như tiếng vỗ tay từ xa. Bãi nằm trên đường ven biển phía bắc Ulsan, quay mặt về hướng đông nên đây là một trong những chỗ ngắm bình minh của vùng. Dọc bờ có các quán bán ngao nướng và rong biển hái tại chỗ; mùa hè người ta dựng lều ngay trên cuội.', '["Bãi dài khoảng 1,5 km, phủ hoàn toàn bằng cuội đen thay vì cát.","Tiếng cuội va nhau khi sóng rút là đặc trưng được đặt tên riêng trong tiếng Hàn.","Quay mặt hướng đông, là điểm ngắm bình minh của vùng Ulsan.","Nằm trên tuyến đường ven biển nối Ulsan với Gyeongju."]', '["Đi giày đế dày — cuội đau chân hơn bạn nghĩ.","Đến trước bình minh khoảng 30 phút nếu muốn xem mặt trời lên.","Kết hợp với công viên Daewangam trên cùng tuyến đường ven biển."]', 'Tháng 5–9; bình minh quanh năm', '1,5 giờ', '', 'Cả ngày', '["hidden-gem"]', '["bãi cuội","bình minh","biển","hải sản"]', '[{"seed":"jujeon-pebble-beach","caption":"Cuội đen bãi Jujeon","ratio":"16/9"}]', '["daewangam-park"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Jujeon Pebble Beach","summary":"A beach with no sand at all, only round black pebbles — and the sound the backwash leaves behind.","story":"There is not a grain of sand at Jujeon. The whole kilometre and a half is covered in smooth round black pebbles the size of a fist, and what makes people sit for a while is the sound: as each wave draws back, millions of pebbles knock together in a long rattle like applause heard from far off. The beach sits on the coast road north of Ulsan and faces east, so it is one of the region''s sunrise spots. Along the shore are stalls selling grilled clams and seaweed gathered on the spot; in summer people pitch tents straight onto the stones.","facts":["The beach runs about 1.5km and is covered entirely in black pebbles rather than sand.","The rattle of pebbles in the backwash has its own name in Korean.","Facing east, it is one of the Ulsan region''s sunrise viewing spots.","It lies on the coastal road linking Ulsan with Gyeongju."],"travelTips":["Wear thick soles — the pebbles are harder on the feet than you expect.","Arrive about 30 minutes before dawn if you want the sunrise.","Combine it with Daewangam Park along the same coast road."],"bestTime":"May–September; sunrise year-round","visitDuration":"1.5 hours","ticket":"","openingHours":"All day","galleryCaptions":["The black pebbles of Jujeon"]},"ko":{"name":"주전몽돌해변","summary":"모래가 한 알도 없는 해변. 둥근 검은 몽돌뿐이고, 파도가 물러날 때 남기는 소리가 이곳의 것이다.","story":"주전에는 모래가 한 알도 없다. 1.5km 남짓 되는 해변 전체가 주먹만 한 둥글고 검은 몽돌로 덮여 있다. 사람들이 한참 앉아 있게 만드는 것은 소리다. 파도가 물러날 때마다 수백만 개의 몽돌이 서로 부딪히며 멀리서 들려오는 박수 같은 긴 소리를 낸다. 울산 북쪽 해안도로에 있고 동쪽을 보고 있어 이 지역의 일출 명소이기도 하다. 해안을 따라 조개구이와 그 자리에서 딴 미역을 파는 집들이 있고, 여름이면 사람들이 몽돌 위에 그대로 텐트를 친다.","facts":["해변 길이는 약 1.5km이며 모래가 아니라 검은 몽돌로만 덮여 있다.","파도에 몽돌이 부딪히는 소리는 한국어로 따로 이름이 있다.","동쪽을 향하고 있어 울산권의 일출 명소다.","울산과 경주를 잇는 해안도로변에 있다."],"travelTips":["밑창이 두꺼운 신발을 신자. 몽돌은 생각보다 발이 아프다.","일출을 보려면 해뜨기 30분쯤 전에 도착하자.","같은 해안도로의 대왕암공원과 묶어서 보자."],"bestTime":"5~9월, 일출은 연중","visitDuration":"1.5시간","ticket":"","openingHours":"상시","galleryCaptions":["주전의 검은 몽돌"]},"ja":{"name":"注田玉石海岸","summary":"砂がひと粒もない浜。丸い黒石ばかりで、波が引くときに残す音がこの場所のものだ。","story":"注田には砂がひと粒もない。1.5kmほどの浜がすべて、拳ほどの丸く滑らかな黒い玉石で覆われている。人をしばらく座らせるのは音だ。波が引くたび、数百万の玉石が触れ合って、遠くの拍手のような長い音を立てる。蔚山の北の海岸道路沿いにあり東を向いているので、この地域の日の出の名所でもある。海岸沿いには焼き貝やその場で採ったワカメを売る店が並び、夏には人々が玉石の上に直接テントを張る。","facts":["浜の長さは約1.5kmで、砂ではなく黒い玉石だけに覆われている。","引き波で玉石が触れ合う音には韓国語で固有の呼び名がある。","東を向いており、蔚山圏の日の出の名所である。","蔚山と慶州を結ぶ海岸道路沿いにある。"],"travelTips":["底の厚い靴を履こう。玉石は思うより足に応える。","日の出を見るなら30分ほど前に着こう。","同じ海岸道路の大王岩公園と合わせて回ろう。"],"bestTime":"5〜9月、日の出は通年","visitDuration":"1.5時間","ticket":"","openingHours":"終日","galleryCaptions":["注田の黒い玉石"]},"zh":{"name":"注田礫石海灘","summary":"一粒沙也沒有的海灘，只有渾圓的黑色礫石——以及退浪留下的聲音。","story":"注田沒有一粒沙。整段一公里半的海灘鋪滿拳頭大小、渾圓光滑的黑色礫石，真正讓人坐上一陣子的是聲音：每當浪退，數以百萬計的礫石相互碰撞，發出一陣長長的、彷彿遠處掌聲的沙沙聲。海灘位於蔚山北面的海岸公路旁、面向東方，因此也是這一帶的日出景點。岸邊有攤子賣烤蛤與現採海帶；夏天人們就直接在礫石上搭帳篷。","facts":["海灘長約1.5公里，整片鋪的是黑色礫石而非沙。","退浪時礫石相碰的聲響，在韓語裡有專門的稱呼。","面向東方，是蔚山一帶的日出觀賞點。","位於連接蔚山與慶州的海岸公路旁。"],"travelTips":["穿厚底鞋——礫石比想像中傷腳。","想看日出請在天亮前約30分鐘抵達。","可與同一條海岸公路上的大王岩公園排在一起。"],"bestTime":"5至9月；日出則全年皆宜","visitDuration":"1.5小時","ticket":"","openingHours":"全日開放","galleryCaptions":["注田的黑色礫石"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hallasan', 'hallasan', 'jeju', 'Núi Hallasan', 'Hallasan Mountain', 'mountain', 126.5297, 33.3617, 'Ngọn núi cao nhất Hàn Quốc — một núi lửa đã tắt với hồ miệng núi nằm ngay trên đỉnh.', 'Cả đảo Jeju thực chất là sườn của Hallasan; đứng ở đâu trên đảo bạn cũng thấy đỉnh núi ẩn hiện sau mây. Đường lên đỉnh Baengnokdam mất khoảng chín tiếng cả đi lẫn về, xuyên qua rừng lá rộng, rồi rừng lùn, rồi trảng cỏ trống lộng gió. Trên cùng là hồ miệng núi lửa — theo truyền thuyết là nơi tiên cưỡi hươu trắng xuống uống nước. Mùa xuân, đỗ quyên nở tím cả sườn núi; mùa đông, tuyết dày khiến Hallasan thành điểm leo tuyết được yêu thích nhất nước.', '["Cao 1.947m, là đỉnh cao nhất Hàn Quốc.","Là một phần Di sản Thiên nhiên Thế giới UNESCO ''Đảo núi lửa và hang dung nham Jeju''.","Hồ miệng núi Baengnokdam có đường kính khoảng 550m.","Chỉ hai tuyến Seongpanak và Gwaneumsa lên được tới đỉnh.","Ban quản lý giới hạn giờ xuất phát — lên muộn sẽ bị chặn ở trạm kiểm soát."]', '["Đặt chỗ leo núi trực tuyến trước, hai tuyến lên đỉnh đều giới hạn số người.","Xuất phát trước 6h sáng để kịp quay xuống trước giờ đóng đường mòn.","Thời tiết đổi rất nhanh — luôn mang áo gió và nước."]', 'Tháng 5 (đỗ quyên) và tháng 10 (trời trong)', 'Cả ngày', 'Miễn phí, nhưng hai tuyến lên đỉnh (Seongpanak và Gwaneumsa) bắt buộc đặt chỗ trước trên trang đặt chỗ của vườn quốc gia', 'Bắt đầu lên núi từ 05:00 (mùa đông 06:00); trạm kiểm soát chặn tiếp tục leo khoảng 12:00–14:00 tuỳ tuyến và mùa — tuyến Seongpanak phải qua chòi Jindallaebat trước 11:30. Bắt buộc lên xuống trong ngày, cấm cắm trại', '["unesco","verified"]', '["leo núi","núi lửa","UNESCO"]', '[{"seed":"hallasan","caption":"Hồ miệng núi Baengnokdam","ratio":"16/9"}]', '["seongsan-ilchulbong","manjanggul"]', 1, 'https://visithalla.jeju.go.kr/reservation/status.do', '2026-08-05', '{"en":{"name":"Hallasan Mountain","summary":"Korea''s highest peak — a dormant volcano with a crater lake sitting right on its summit.","story":"The whole of Jeju is really the flank of Hallasan; wherever you stand on the island the summit appears and disappears behind cloud. The climb to Baengnokdam crater takes about nine hours return, through broadleaf forest, then dwarf forest, then open windswept grass. At the top lies the crater lake — where, legend says, immortals rode down on white deer to drink. In spring azaleas turn the slopes purple; in winter deep snow makes Hallasan the country''s favourite snow climb.","facts":["At 1,947m it is the highest point in South Korea.","Part of the UNESCO World Natural Heritage ''Jeju Volcanic Island and Lava Tubes''.","The Baengnokdam crater lake is about 550m across.","Only the Seongpanak and Gwaneumsa trails reach the summit.","Park rangers cap departure times — late starters are turned back at the checkpoints."],"travelTips":["Reserve your climb online in advance; both summit trails limit numbers.","Set out before 6am to be back down before the trail closes.","Weather turns fast — always carry a windproof layer and water."],"bestTime":"May (azaleas) and October (clear skies)","visitDuration":"Full day","ticket":"Free, but the two summit trails (Seongpanak and Gwaneumsa) require an advance reservation on the national park booking site","openingHours":"Ascent starts at 05:00 (06:00 in winter); control points turn hikers back around 12:00–14:00 depending on trail and season — on Seongpanak you must pass the Jindallaebat shelter by 11:30. Up and down the same day; camping is banned","galleryCaptions":["The Baengnokdam crater lake"]},"ko":{"name":"한라산","summary":"남한에서 가장 높은 산. 정상에 분화구 호수를 품은 휴화산이다.","story":"제주도 전체가 사실은 한라산의 산자락이다. 섬 어디에 서 있어도 구름 사이로 정상이 나타났다 사라진다. 백록담까지는 왕복 아홉 시간쯤 걸리며 활엽수림과 관목대를 지나 바람이 몰아치는 초원으로 이어진다. 정상에는 분화구 호수가 있다. 전설에 따르면 신선들이 흰 사슴을 타고 내려와 물을 마시던 곳이다. 봄이면 철쭉이 산비탈을 자줏빛으로 물들이고, 겨울이면 눈이 깊이 쌓여 전국에서 가장 사랑받는 설산이 된다.","facts":["해발 1,947m로 남한에서 가장 높다.","유네스코 세계자연유산 ''제주 화산섬과 용암동굴''에 포함된다.","백록담 분화구의 지름은 약 550m다.","정상에 오를 수 있는 코스는 성판악과 관음사 두 곳뿐이다.","출발 시간이 통제되어 늦게 오르면 통제소에서 되돌아가야 한다."],"travelTips":["정상 코스는 인원이 제한되니 온라인으로 미리 예약하자.","탐방로 폐쇄 시각 전에 내려오려면 오전 6시 이전에 출발하는 것이 좋다.","날씨가 급변하니 바람막이와 물은 반드시 챙기자."],"bestTime":"5월(철쭉), 10월(맑은 하늘)","visitDuration":"하루","ticket":"무료이나 정상 코스(성판악·관음사)는 국립공원 예약 사이트에서 사전 예약이 필수다","openingHours":"입산은 05:00부터(겨울 06:00), 탐방로와 계절에 따라 12:00~14:00 사이에 통제된다. 성판악 코스는 진달래밭 대피소를 11:30까지 통과해야 한다. 당일 산행만 가능하며 야영은 금지","galleryCaptions":["백록담 분화구"]},"ja":{"name":"漢拏山","summary":"韓国最高峰。頂上に火口湖を抱く休火山。","story":"済州島そのものが漢拏山の裾野だ。島のどこに立っても、雲の切れ間に山頂が現れては消える。白鹿潭までは往復九時間ほど。広葉樹林を抜け、低木帯を越え、風の吹きさらす草原に出る。頂には火口湖があり、伝説では仙人が白鹿に乗って降り、水を飲んだ場所だという。春はツツジが斜面を紫に染め、冬は深い雪に覆われて、韓国で最も愛される雪山になる。","facts":["標高1,947mで韓国最高峰。","ユネスコ世界自然遺産「済州火山島と溶岩洞窟群」に含まれる。","白鹿潭火口の直径は約550m。","山頂に至る登山道は城板岳と観音寺の二つだけ。","出発時刻が管理され、遅い入山は検問所で引き返される。"],"travelTips":["山頂コースは人数制限があるので事前にオンライン予約を。","閉鎖時刻前に下山するには午前6時前の出発が安全。","天候が急変する。ウインドブレーカーと水は必携。"],"bestTime":"5月（ツツジ）、10月（澄んだ空）","visitDuration":"終日","ticket":"無料だが頂上コース（城板岳・観音寺）は国立公園の予約サイトで事前予約が必須","openingHours":"入山は05:00から（冬は06:00）。登山道と季節により12:00〜14:00頃に規制がかかり、城板岳コースはツツジ畑避難小屋を11:30までに通過する必要がある。日帰りのみで野営は禁止","galleryCaptions":["白鹿潭の火口湖"]},"zh":{"name":"漢拏山","summary":"韓國最高峰，一座頂上抱著火口湖的休眠火山。","story":"整座濟州其實就是漢拏山的山坡；無論站在島上哪裡，山頂都在雲後時隱時現。登上白鹿潭往返約需九小時，穿過闊葉林、灌木林，再走進風吹不停的草原。山頂是火口湖——傳說仙人騎著白鹿下來飲水之處。春天杜鵑把山坡染成紫色；冬天積雪深厚，使漢拏山成為全國最受喜愛的雪山。","facts":["海拔1,947公尺，為南韓最高峰。","屬世界自然遺產「濟州火山島與熔岩洞窟」的一部分。","白鹿潭火口湖直徑約550公尺。","只有城板岳與觀音寺兩條路線可登頂。","管理處管制出發時間，太晚入山會在檢查站被勸返。"],"travelTips":["登頂路線名額有限，請提前線上預約。","清晨六點前出發，才能在步道關閉前下山。","天氣說變就變，務必攜帶防風外套與飲水。"],"bestTime":"5月（杜鵑）與10月（天色清朗）","visitDuration":"一整天","ticket":"免費，但兩條登頂路線（城板岳、觀音寺）須先在國家公園預約網站訂位","openingHours":"05:00開始入山（冬季06:00）；依路線與季節，管制站約在12:00至14:00勸返，城板岳路線須於11:30前通過杜鵑花田避難小屋。當日上下山，禁止露營","galleryCaptions":["白鹿潭火口湖"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seongsan-ilchulbong', 'seongsan-ilchulbong', 'jeju', 'Đỉnh Bình minh Seongsan', 'Seongsan Ilchulbong', 'unesco', 126.94, 33.458, 'Miệng núi lửa nhô lên từ biển như một chiếc vương miện đá, đẹp nhất lúc mặt trời mọc.', 'Seongsan Ilchulbong hình thành khi dung nham phun trào dưới nước cách đây khoảng năm nghìn năm, để lại một miệng núi rộng bao quanh bởi vách đá dựng đứng. Leo hai mươi phút theo bậc thang là tới vành miệng: bên dưới là lòng chảo cỏ xanh, bên kia là biển và làng chài Seongsan. Người ta dậy từ bốn giờ sáng để đón bình minh ở đây — mặt trời lên thẳng từ mặt biển phía đông. Dưới chân núi, các haenyeo — thợ lặn nữ Jeju, phần lớn đã ngoài sáu mươi — vẫn biểu diễn buổi lặn bắt bào ngư như họ đã làm cả đời.', '["Thuộc Di sản Thiên nhiên Thế giới UNESCO của đảo Jeju.","Miệng núi rộng khoảng 600m, cao 182m so với mực nước biển.","Hình thành từ vụ phun trào dưới nước cách đây khoảng 5.000 năm.","Văn hoá haenyeo (thợ lặn nữ) được UNESCO ghi danh di sản phi vật thể năm 2016."]', '["Cổng mở sớm trước bình minh — kiểm tra giờ mặt trời mọc theo mùa.","Bậc thang khá dốc, đi giày bám tốt.","Xem lịch biểu diễn haenyeo ở bãi đá dưới chân núi."]', 'Quanh năm, đẹp nhất lúc bình minh', '1,5–2 giờ', '5.000 KRW', '07:30–20:00 (đóng cửa sớm hơn vào mùa đông)', '["unesco","popular"]', '["UNESCO","bình minh","núi lửa","haenyeo"]', '[{"seed":"seongsan-ilchulbong","caption":"Miệng núi lửa nhìn từ biển","ratio":"16/9"}]', '["udo-island","manjanggul"]', 1, 'https://www.visitjeju.net/en/detail/view?contentsid=CONT_000000000500339', '2026-08-04', '{"en":{"name":"Seongsan Ilchulbong (Sunrise Peak)","summary":"A volcanic crater rising straight out of the sea like a stone crown, at its best at sunrise.","story":"Seongsan Ilchulbong formed when lava erupted underwater some five thousand years ago, leaving a broad crater ringed by sheer cliffs. Twenty minutes of steps bring you to the rim: below is a green bowl of grass, beyond it the sea and the fishing village of Seongsan. People rise at four in the morning to catch the sunrise here — the sun comes straight up out of the eastern sea. At the foot of the peak, the haenyeo — Jeju''s women divers, most of them well past sixty — still perform the abalone dive they have done all their lives.","facts":["Part of Jeju''s UNESCO World Natural Heritage listing.","The crater is about 600m wide and the peak stands 182m above the sea.","Formed by an underwater eruption roughly 5,000 years ago.","Haenyeo culture was inscribed by UNESCO as intangible heritage in 2016."],"travelTips":["The gate opens before dawn — check sunrise times by season.","The steps are steep; wear shoes with grip.","Check the haenyeo demonstration schedule on the rocks below."],"bestTime":"Year-round, best at sunrise","visitDuration":"1.5–2 hours","ticket":"5,000 KRW","openingHours":"07:30–20:00 (earlier closing in winter)","galleryCaptions":["The crater seen from the sea"]},"ko":{"name":"성산일출봉","summary":"바다에서 솟은 왕관 모양의 분화구. 해돋이 때 가장 아름답다.","story":"성산일출봉은 약 5천 년 전 바닷속에서 분출한 용암이 만든 분화구로, 가파른 절벽이 넓은 분화구를 감싸고 있다. 계단을 20분쯤 오르면 능선에 닿는다. 아래로는 초록 사발 같은 분화구가, 건너편으로는 바다와 성산 어촌이 펼쳐진다. 사람들은 새벽 네 시에 일어나 이곳에서 해를 맞는다. 해는 동쪽 바다에서 곧장 솟는다. 봉우리 아래 바닷가에서는 대부분 예순을 넘긴 해녀들이 평생 해온 물질을 그대로 보여준다.","facts":["제주도의 유네스코 세계자연유산에 포함된다.","분화구 지름은 약 600m, 높이는 해발 182m다.","약 5천 년 전 수중 분화로 형성되었다.","해녀 문화는 2016년 유네스코 무형문화유산에 등재되었다."],"travelTips":["일출 전에 개방하니 계절별 일출 시각을 확인하자.","계단이 가파르므로 접지력이 좋은 신발이 좋다.","아래 바위터의 해녀 물질 시연 시간을 확인해 보자."],"bestTime":"연중, 해돋이 시간이 가장 좋다","visitDuration":"1시간 30분~2시간","ticket":"5,000원","openingHours":"07:30~20:00(겨울에는 더 일찍 마감)","galleryCaptions":["바다에서 본 분화구"]},"ja":{"name":"城山日出峰","summary":"海から立ち上がる王冠のような火口。日の出の時が最も美しい。","story":"城山日出峰は約五千年前の海底噴火でできた火口で、切り立った崖が広い火口を取り巻く。階段を二十分ほど登れば稜線に出る。眼下には草の緑の器のような火口、向こうには海と城山の漁村。人々は朝四時に起きてここで日を迎える。太陽は東の海からまっすぐ昇る。ふもとの磯では、多くが六十を超えた海女たちが、生涯続けてきた素潜り漁を見せてくれる。","facts":["済州島のユネスコ世界自然遺産に含まれる。","火口の直径は約600m、標高は182m。","約5,000年前の水中噴火で形成された。","海女文化は2016年にユネスコ無形文化遺産に登録された。"],"travelTips":["日の出前に開門する。季節ごとの日の出時刻を確認しよう。","階段が急なのでグリップの利く靴を。","ふもとの海女の実演スケジュールも確認してみよう。"],"bestTime":"通年、日の出の時間が最良","visitDuration":"1時間30分〜2時間","ticket":"5,000ウォン","openingHours":"07:30〜20:00（冬は早めに閉場）","galleryCaptions":["海から見た火口"]},"zh":{"name":"城山日出峰","summary":"自海中拔起、狀如石冠的火山口，日出時分最美。","story":"城山日出峰形成於約五千年前的水下噴發，陡峭崖壁環抱著寬闊的火山口。沿階梯走二十分鐘可達稜線：下方是青草鋪成的碗，遠處是海與城山漁村。人們清晨四點起床來此看日出——太陽直接從東海升起。峰下的岩灘上，濟州的女性潛水者海女——多半已年過六旬——仍展示著她們做了一輩子的採鮑潛水。","facts":["屬濟州世界自然遺產的一部分。","火山口寬約600公尺，峰頂海拔182公尺。","由約五千年前的水下噴發形成。","海女文化於2016年列入非物質文化遺產。"],"travelTips":["日出前開門，請先查好各季節的日出時間。","階梯陡峭，建議穿抓地力好的鞋。","可查詢峰下岩灘的海女表演時間。"],"bestTime":"全年，日出時分最佳","visitDuration":"1.5至2小時","ticket":"5,000韓元","openingHours":"07:30–20:00（冬季提早閉園）","galleryCaptions":["自海上望向火山口"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('manjanggul', 'manjanggul', 'jeju', 'Hang dung nham Manjanggul', 'Manjanggul Lava Tube', 'cave', 126.771, 33.5285, 'Đường hầm do dung nham khoét ra dưới lòng đất, mát lạnh và tối như mực suốt bốn mùa.', 'Khi dung nham chảy, lớp ngoài nguội cứng lại thành vỏ còn dòng bên trong tiếp tục chảy đi, để lại một đường ống rỗng dưới lòng đất. Manjanggul là một trong những ống dung nham lớn nhất thế giới còn giữ được nguyên trạng. Đoạn mở cho khách dài khoảng một cây số, trần cao tới hơn hai chục mét, tường hằn rõ các ngấn dung nham như vệt nước thuỷ triều. Nhiệt độ trong hang giữ quanh 11–14°C quanh năm. Cuối đường là cột dung nham cao 7,6 mét — cột dung nham cao nhất từng biết đến.', '["Thuộc quần thể hang dung nham Geomunoreum, Di sản UNESCO.","Tổng chiều dài hang khoảng 7,4 km; mở cho khách khoảng 1 km.","Cột dung nham cuối hang cao 7,6m, được xem là cao nhất thế giới.","Nhiệt độ trong hang ổn định 11–14°C quanh năm."]', '["Mang áo khoác kể cả giữa mùa hè — trong hang rất lạnh.","Sàn hang ẩm và gồ ghề, không phù hợp giày trơn.","Hang có thể đóng cửa bảo trì định kỳ, kiểm tra trước khi đi."]', 'Quanh năm', '1 giờ', '4.000 KRW (thiếu niên và trẻ em 2.000 KRW)', '09:00–18:00; hang mở lại từ 30/5/2026 sau đợt sửa chữa', '["unesco"]', '["UNESCO","hang động","địa chất"]', '[{"seed":"manjanggul","caption":"Lòng ống dung nham","ratio":"16/9"}]', '["seongsan-ilchulbong","hallasan"]', 0, 'https://english.visitkorea.or.kr/svc/whereToGo/locIntrdn/rgnContentsView.do?vcontsId=111165', '2026-08-04', '{"en":{"name":"Manjanggul Lava Tube","summary":"A tunnel carved underground by flowing lava, cold and pitch dark in every season.","story":"When lava flows, its outer skin cools into a crust while the river inside keeps moving, leaving a hollow pipe under the ground. Manjanggul is one of the largest lava tubes in the world still in original condition. The section open to visitors runs about a kilometre, its ceiling more than twenty metres high in places, the walls marked with lava lines like tide marks. The temperature holds at 11–14°C all year. At the far end stands a lava column 7.6 metres tall — the tallest known anywhere.","facts":["Part of the Geomunoreum lava tube system, a UNESCO site.","The cave runs about 7.4 km in total; roughly 1 km is open to visitors.","The lava column at the end is 7.6m high, considered the world''s tallest.","The temperature stays a steady 11–14°C year-round."],"travelTips":["Bring a jacket even in midsummer — it is genuinely cold inside.","The floor is damp and uneven; avoid smooth-soled shoes.","The cave closes periodically for maintenance — check before travelling."],"bestTime":"Year-round","visitDuration":"1 hour","ticket":"4,000 KRW (2,000 KRW teens and children)","openingHours":"09:00–18:00; the cave reopened on 30 May 2026 after repairs","galleryCaptions":["Inside the lava tube"]},"ko":{"name":"만장굴","summary":"흐르던 용암이 뚫어놓은 지하 터널. 사계절 서늘하고 캄캄하다.","story":"용암이 흐를 때 겉면은 식어 굳고 안쪽 흐름은 계속 빠져나가면서 땅속에 빈 관이 남는다. 만장굴은 원형이 잘 보존된 세계 최대급 용암동굴이다. 개방 구간은 약 1km, 천장은 20m가 넘는 곳도 있고 벽에는 밀물 자국 같은 용암선이 또렷하다. 내부 온도는 연중 11~14도를 유지한다. 구간의 끝에는 높이 7.6m의 용암석주가 서 있는데, 알려진 것 중 세계에서 가장 높다.","facts":["유네스코 세계유산인 거문오름 용암동굴계에 속한다.","총 길이 약 7.4km 가운데 1km가 개방된다.","동굴 끝의 용암석주는 높이 7.6m로 세계 최대로 꼽힌다.","내부 온도는 연중 11~14도로 일정하다."],"travelTips":["한여름에도 겉옷이 필요할 만큼 춥다.","바닥이 젖어 있고 울퉁불퉁하니 미끄러운 신발은 피하자.","정기 보수로 폐쇄될 수 있으니 방문 전 확인하자."],"bestTime":"연중","visitDuration":"1시간","ticket":"4,000원(청소년·어린이 2,000원)","openingHours":"09:00~18:00, 보수 공사를 마치고 2026년 5월 30일 재개방","galleryCaptions":["용암동굴 내부"]},"ja":{"name":"万丈窟","summary":"流れる溶岩が地下に掘ったトンネル。四季を通じて冷たく暗い。","story":"溶岩が流れると外側は冷えて殻になり、内側の流れは進み続けて、地下に空洞の管が残る。万丈窟は原形をよく保った世界最大級の溶岩洞窟だ。公開区間は約1km、天井は20mを超える場所もあり、壁には潮の跡のような溶岩線がくっきり残る。内部の気温は年間を通じて11〜14度。区間の終わりには高さ7.6mの溶岩石柱が立つ。知られている中で世界一の高さだ。","facts":["ユネスコ世界遺産の拒文岳溶岩洞窟系に属する。","全長約7.4kmのうち1kmが公開されている。","終端の溶岩石柱は高さ7.6mで世界最大とされる。","洞内は年間を通じて11〜14度で安定している。"],"travelTips":["真夏でも上着が必要なほど寒い。","床は濡れて凹凸がある。滑る靴は避けよう。","定期補修で閉鎖されることがあるので事前確認を。"],"bestTime":"通年","visitDuration":"1時間","ticket":"4,000ウォン（青少年・子ども2,000ウォン）","openingHours":"09:00〜18:00、補修を終え2026年5月30日に再開","galleryCaptions":["溶岩洞窟の内部"]},"zh":{"name":"萬丈窟","summary":"熔岩在地下鑿出的隧道，四季陰冷、漆黑如墨。","story":"熔岩流動時外殼冷卻成硬皮，內部仍持續流走，於是地下留下一根中空的管子。萬丈窟是世界上保存最完整的大型熔岩洞之一。開放段約一公里，頂部有些地方高逾二十公尺，牆上留著像潮痕般清晰的熔岩線。洞內全年維持攝氏11至14度。盡頭立著一根七點六公尺高的熔岩石柱——已知世界最高。","facts":["屬世界遺產拒文岳熔岩洞窟系統。","全長約7.4公里，開放參觀約1公里。","洞窟盡頭的熔岩石柱高7.6公尺，被視為世界最高。","洞內溫度全年穩定在11至14度。"],"travelTips":["即使盛夏也要帶外套，裡面確實很冷。","地面潮濕不平，避免穿光滑鞋底。","洞窟會定期維修關閉，出發前請確認。"],"bestTime":"全年","visitDuration":"1小時","ticket":"4,000韓元（青少年與兒童2,000韓元）","openingHours":"09:00–18:00；整修後於2026年5月30日重新開放","galleryCaptions":["熔岩洞內部"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeongbang-waterfall', 'jeongbang-waterfall', 'jeju', 'Thác Jeongbang', 'Jeongbang Waterfall', 'waterfall', 126.572, 33.2447, 'Thác nước hiếm hoi ở châu Á đổ thẳng xuống biển, ngay rìa thành phố Seogwipo.', 'Từ bãi đỗ xe, bậc đá dẫn xuống một vịnh nhỏ đầy sỏi tròn, và dòng thác cao hơn hai chục mét rơi thẳng từ vách đá đen xuống mép sóng. Gió biển thổi ngược làm bụi nước bay mù, mặn trên môi. Tương truyền sứ giả của Tần Thuỷ Hoàng đi tìm thuốc trường sinh đã khắc chữ lên vách đá này trước khi quay về tay không — cái tên Seogwipo được cho là bắt nguồn từ đó. Chiều muộn, ánh nắng xiên qua màn nước tạo cầu vồng ngay trước mặt.', '["Cao khoảng 23m, là một trong số ít thác đổ trực tiếp xuống biển ở châu Á.","Gắn với truyền thuyết sứ giả Từ Phúc thời Tần đi tìm thuốc trường sinh.","Nằm trong thành phố Seogwipo, cách trung tâm chỉ vài phút xe.","Cùng với Cheonjiyeon và Cheonjeyeon tạo thành bộ ba thác nổi tiếng của Jeju."]', '["Bãi sỏi trơn khi ướt — đi cẩn thận và đừng lại quá gần chân thác.","Đi buổi chiều để dễ thấy cầu vồng trong bụi nước.","Kết hợp với chợ Olle Seogwipo cách đó vài phút."]', 'Tháng 6–9 (nhiều nước nhất)', '1 giờ', '2.000 KRW', '09:00–19:00, vào cửa cuối 18:00', '[]', '["thác nước","biển","Seogwipo"]', '[{"seed":"jeongbang-waterfall","caption":"Thác đổ thẳng xuống biển","ratio":"16/9"}]', '["hallasan"]', 0, 'https://www.visitjeju.net/en/detail/view?contentsid=CONT_000000000500350', '2026-08-04', '{"en":{"name":"Jeongbang Waterfall","summary":"One of Asia''s rare waterfalls that drops straight into the sea, on the edge of Seogwipo city.","story":"From the car park, stone steps lead down to a small bay of rounded pebbles where a fall of more than twenty metres drops off a black cliff into the surf. The sea wind blows the spray back at you, salt on your lips. Legend has it that an envoy of China''s first emperor, sent to find the elixir of life, carved characters into this cliff before going home empty-handed — and that the name Seogwipo comes from that story. Late in the day, sunlight through the spray puts a rainbow right in front of you.","facts":["About 23m high, one of the few waterfalls in Asia that falls directly into the sea.","Tied to the legend of Xu Fu, the Qin envoy sent in search of immortality.","Inside Seogwipo city, minutes from the centre.","With Cheonjiyeon and Cheonjeyeon it forms Jeju''s famous trio of waterfalls."],"travelTips":["The pebbles are slippery when wet — tread carefully and don''t get too close.","Come in the afternoon for the best chance of a rainbow in the spray.","Combine with Seogwipo Olle Market a few minutes away."],"bestTime":"June–September (highest flow)","visitDuration":"1 hour","ticket":"2,000 KRW","openingHours":"09:00–19:00, last entry 18:00","galleryCaptions":["The waterfall dropping into the sea"]},"ko":{"name":"정방폭포","summary":"바다로 곧장 떨어지는 아시아의 드문 폭포. 서귀포 도심 가장자리에 있다.","story":"주차장에서 돌계단을 내려가면 둥근 자갈이 깔린 작은 만이 나오고, 20m가 넘는 물줄기가 검은 절벽에서 파도 위로 곧장 떨어진다. 바닷바람이 물보라를 되돌려 보내 입술에 소금기가 남는다. 진시황의 사자 서복이 불로초를 찾다가 빈손으로 돌아가며 이 절벽에 글자를 새겼고, 서귀포라는 이름이 거기서 비롯되었다는 이야기가 전한다. 늦은 오후에는 물보라를 통과한 햇빛이 눈앞에 무지개를 만든다.","facts":["높이 약 23m로, 아시아에서 바다로 직접 떨어지는 드문 폭포다.","불로초를 찾아 왔다는 서복 전설과 이어진다.","서귀포 도심에서 차로 몇 분 거리에 있다.","천지연, 천제연과 함께 제주 3대 폭포로 꼽힌다."],"travelTips":["자갈이 젖으면 미끄러우니 폭포에 너무 가까이 가지 말자.","오후에 가면 물보라 속 무지개를 볼 확률이 높다.","몇 분 거리의 서귀포 올레시장과 묶어 보자."],"bestTime":"6~9월(수량이 가장 많다)","visitDuration":"1시간","ticket":"2,000원","openingHours":"09:00~19:00, 입장 마감 18:00","galleryCaptions":["바다로 떨어지는 폭포"]},"ja":{"name":"正房瀑布","summary":"海へ直接落ちるアジアでは稀な滝。西帰浦の街のすぐ端にある。","story":"駐車場から石段を下りると丸い小石の入り江に出て、二十数メートルの水が黒い崖から波の上へまっすぐ落ちる。海風が飛沫を吹き返し、唇に塩気が残る。秦の始皇帝の使者・徐福が不老草を探し、手ぶらで帰る前にこの崖に文字を刻んだという伝説があり、西帰浦の地名はそこから来たとされる。午後遅く、飛沫を抜けた光が目の前に虹をつくる。","facts":["高さ約23m。アジアで海に直接落ちる数少ない滝のひとつ。","不老不死の薬を求めた徐福の伝説と結びつく。","西帰浦の市街から車で数分。","天地淵、天帝淵とともに済州三大瀑布に数えられる。"],"travelTips":["小石は濡れると滑る。滝に近づきすぎないように。","午後に行けば飛沫の虹を見られる確率が高い。","数分の距離にある西帰浦オルレ市場と合わせて。"],"bestTime":"6〜9月（水量が最も多い）","visitDuration":"1時間","ticket":"2,000ウォン","openingHours":"09:00〜19:00、最終入場18:00","galleryCaptions":["海へ落ちる滝"]},"zh":{"name":"正房瀑布","summary":"亞洲少見直接落入海中的瀑布，就在西歸浦城邊。","story":"從停車場沿石階而下，來到一處圓卵石鋪成的小灣，二十多公尺高的水流自黑色崖壁直落浪頭。海風把水霧吹回臉上，唇上留著鹹味。傳說秦始皇派來尋找長生藥的使者徐福，在空手而歸前於這面崖壁刻下文字，西歸浦之名便由此而來。日暮時分，陽光穿過水霧，在眼前架起一道彩虹。","facts":["高約23公尺，是亞洲少數直接落入海中的瀑布之一。","與秦朝使者徐福尋找長生不老藥的傳說相連。","位於西歸浦市內，距市中心僅數分鐘車程。","與天地淵、天帝淵並稱濟州三大瀑布。"],"travelTips":["卵石濕滑，切勿太靠近瀑布。","午後前往較有機會看到水霧中的彩虹。","可與數分鐘車程的西歸浦偶來市場一併安排。"],"bestTime":"6至9月（水量最豐）","visitDuration":"1小時","ticket":"2,000韓元","openingHours":"09:00–19:00，最後入場18:00","galleryCaptions":["直落大海的瀑布"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('udo-island', 'udo-island', 'jeju', 'Đảo Udo', 'Udo Island', 'island', 126.954, 33.506, 'Hòn đảo nhỏ hình con bò nằm ngoài khơi phía đông, đi trọn một vòng bằng xe đạp trong nửa ngày.', 'Phà từ bến Seongsan mất mười lăm phút. Udo nhỏ đến mức con đường ven đảo chỉ dài chừng mười bảy cây số, và cách hay nhất để đi là thuê xe đạp điện rồi dừng bất cứ đâu mình muốn. Bãi Seobinbaeksa trắng lạ thường vì cát ở đây là san hô vụn chứ không phải cát thường, nước xanh ngọc như vùng nhiệt đới. Trên đảo, những bức tường đá đen xếp không vữa chắn gió cho ruộng lạc và ruộng cà rốt. Đặc sản là kem lạc — béo, thơm, bán ở mọi quán ven đường.', '["Tên đảo nghĩa là ''đảo con bò'', theo hình dáng nhìn từ trên cao.","Bãi Seobinbaeksa được tạo từ vụn san hô, hiếm gặp ở Hàn Quốc.","Đường vòng quanh đảo dài khoảng 17 km.","Nổi tiếng với lạc trồng trên đảo và món kem lạc."]', '["Phà chạy theo giờ cố định — nhớ giờ chuyến cuối để không mắc kẹt lại.","Cần hộ chiếu/CCCD khi mua vé phà.","Thuê xe đạp điện cần bằng lái tại một số điểm; xe đạp thường thì không."]', 'Tháng 5–10', 'Nửa ngày', 'Phà khứ hồi khoảng 10.500 KRW; chuyến mất 15 phút, 30 phút một chuyến vào giờ cao điểm', 'Theo lịch phà, thường 08:00–18:00', '["popular"]', '["đảo","xe đạp","bãi biển"]', '[{"seed":"udo-island","caption":"Bãi Seobinbaeksa","ratio":"16/9"}]', '["seongsan-ilchulbong"]', 0, 'https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=110876', '2026-08-04', '{"en":{"name":"Udo Island","summary":"A small island shaped like a lying cow, easy to circle by bike in half a day.","story":"The ferry from Seongsan takes fifteen minutes. Udo is small enough that its ring road is only about seventeen kilometres, and the best way round is a rented electric bike with stops wherever you feel like. Seobinbaeksa beach is startlingly white because the sand is crushed coral rather than ordinary grain, the water tropical turquoise. Across the island, black stone walls stacked without mortar shield fields of peanuts and carrots. The local speciality is peanut ice cream — rich, nutty, sold at every roadside stand.","facts":["The name means ''cow island'', after its shape seen from above.","Seobinbaeksa beach is formed from crushed coral, rare in Korea.","The ring road around the island is about 17 km.","Famous for island-grown peanuts and peanut ice cream."],"travelTips":["Ferries run to a fixed timetable — note the last departure so you don''t get stranded.","You need photo ID to buy the ferry ticket.","Some rental points require a licence for electric bikes; ordinary bicycles don''t."],"bestTime":"May–October","visitDuration":"Half a day","ticket":"Ferry about 10,500 KRW return; the crossing takes 15 minutes, every 30 minutes at busy times","openingHours":"Ferry schedule, usually 08:00–18:00","galleryCaptions":["Seobinbaeksa beach"]},"ko":{"name":"우도","summary":"소가 누운 모습을 닮은 작은 섬. 반나절이면 자전거로 한 바퀴 돈다.","story":"성산항에서 배로 15분이면 닿는다. 우도는 해안도로가 17km 남짓할 만큼 작아서, 전기 자전거를 빌려 마음 내키는 곳에 멈추는 것이 가장 좋은 방법이다. 서빈백사는 모래가 아니라 부서진 산호라서 유난히 하얗고, 물빛은 열대의 바다처럼 푸르다. 섬 곳곳에는 시멘트 없이 쌓은 검은 돌담이 땅콩밭과 당근밭의 바람을 막는다. 대표 먹거리는 땅콩아이스크림. 고소하고 진해 길가 어디서나 판다.","facts":["위에서 본 모습이 소를 닮아 ''우도''라 불린다.","서빈백사는 산호 조각으로 이뤄져 한국에서는 드문 해변이다.","섬 일주 도로는 약 17km다.","섬에서 나는 땅콩과 땅콩아이스크림이 유명하다."],"travelTips":["배 시간이 정해져 있으니 막배 시각을 꼭 확인하자.","승선권을 살 때 신분증이 필요하다.","전기 자전거는 대여점에 따라 면허가 필요하고 일반 자전거는 필요 없다."],"bestTime":"5~10월","visitDuration":"반나절","ticket":"여객선 왕복 약 10,500원, 15분 소요, 성수기에는 30분 간격","openingHours":"여객선 운항 시간(대개 08:00~18:00)","galleryCaptions":["서빈백사 해변"]},"ja":{"name":"牛島","summary":"牛が寝そべる姿に似た小さな島。半日あれば自転車で一周できる。","story":"城山港から船で15分。牛島は海岸道路が17kmほどしかない小さな島で、電動自転車を借りて気の向くまま止まるのが一番いい。西浜白沙は砂ではなく砕けた珊瑚なので驚くほど白く、水は熱帯のように青い。島のあちこちで、モルタルを使わず積んだ黒い石垣が落花生畑と人参畑を風から守る。名物は落花生アイスクリーム。濃厚で香ばしく、道沿いのどこでも売っている。","facts":["上から見た形が牛に似ていることから「牛島」と呼ばれる。","西浜白沙は珊瑚のかけらでできた、韓国では珍しい浜。","島の周回道路は約17km。","島で採れる落花生と落花生アイスクリームが名物。"],"travelTips":["船の時刻が決まっている。最終便を必ず確認しよう。","乗船券の購入には身分証が必要。","電動自転車は店により免許が必要。普通の自転車は不要。"],"bestTime":"5〜10月","visitDuration":"半日","ticket":"船は往復約10,500ウォン、所要15分、繁忙期は30分間隔","openingHours":"フェリー運航時間（おおむね08:00〜18:00）","galleryCaptions":["西浜白沙の浜"]},"zh":{"name":"牛島","summary":"形似臥牛的小島，半天就能騎車環島一圈。","story":"從城山港搭船十五分鐘即到。牛島小到環島公路僅約十七公里，最好的方式是租一輛電動自行車，想停就停。西濱白沙之所以白得驚人，是因為沙子其實是碎珊瑚，海水呈熱帶般的碧綠。島上到處是不用灰漿疊起的黑石牆，為花生田與胡蘿蔔田擋風。招牌是花生冰淇淋——濃香醇厚，路邊處處有賣。","facts":["島名意為「牛島」，因自空中俯瞰形似臥牛。","西濱白沙由碎珊瑚形成，在韓國相當罕見。","環島公路約17公里。","以島產花生與花生冰淇淋聞名。"],"travelTips":["船班固定，務必記下末班時間以免受困。","購買船票需出示身分證件。","部分店家租電動車需駕照，一般自行車則不需要。"],"bestTime":"5至10月","visitDuration":"半天","ticket":"渡船來回約10,500韓元，航程15分鐘，旺季每30分鐘一班","openingHours":"依船班時間，多為08:00–18:00","galleryCaptions":["西濱白沙海灘"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('hyeopjae-beach', 'hyeopjae-beach', 'jeju', 'Bãi biển Hyeopjae', 'Hyeopjae Beach', 'beach', 126.24, 33.394, 'Bãi cát trắng nước cạn nhìn thẳng sang đảo Biyangdo, hoàng hôn đẹp nhất bờ tây Jeju.', 'Nước ở Hyeopjae nông và trong đến mức nhìn rõ đáy cát cách bờ cả trăm mét, màu chuyển dần từ ngọc lam sang xanh thẫm. Ngay ngoài khơi là đảo Biyangdo tròn trịa, và khi mặt trời lặn sau nó cả bãi biển chuyển sang màu cam. Sau lưng bãi là rừng thông cho bóng mát và chỗ cắm trại, cạnh đó là làng dân tộc Hallim. Vì nằm ở bờ tây nên đây là một trong ít bãi biển ở Jeju mà bạn xem được hoàng hôn xuống biển thay vì bình minh.', '["Cát trắng do lẫn vụn vỏ sò, khác với cát đen núi lửa ở nhiều nơi khác trên đảo.","Nước nông kéo dài, phù hợp cho trẻ nhỏ.","Nhìn thẳng ra đảo Biyangdo, có phà từ cảng Hallim.","Kề bên là công viên Hallim với vườn thực vật và hang dung nham nhỏ."]', '["Đi buổi chiều muộn để tắm rồi ở lại xem hoàng hôn.","Mùa hè rất đông; tháng 6 hoặc tháng 9 dễ chịu hơn nhiều.","Có vòi sen và nhà thay đồ công cộng ngay sau bãi."]', 'Tháng 6–9', '2–3 giờ', '', 'Cả ngày', '["popular"]', '["bãi biển","hoàng hôn","gia đình"]', '[{"seed":"hyeopjae-beach","caption":"Bãi Hyeopjae nhìn ra đảo Biyangdo","ratio":"16/9"}]', '["hallasan"]', 0, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Hyeopjae Beach","summary":"White sand and shallow water facing Biyangdo island — the finest sunset on Jeju''s west coast.","story":"The water at Hyeopjae is so shallow and clear that you can see the sand bottom a hundred metres out, the colour shifting from turquoise to deep blue. Just offshore sits the round hump of Biyangdo, and when the sun drops behind it the whole beach turns orange. Behind the sand a pine wood offers shade and camping ground, with Hallim Park next door. Because it faces west, this is one of the few Jeju beaches where you watch the sun set into the sea rather than rise out of it.","facts":["The white sand comes from crushed shells, unlike the black volcanic sand elsewhere on the island.","Long shallows make it good for small children.","Faces Biyangdo island, reachable by ferry from Hallim port.","Next door is Hallim Park with its botanical garden and small lava caves."],"travelTips":["Come late afternoon to swim and then stay for the sunset.","Summer is crowded; June or September is far more comfortable.","Public showers and changing rooms sit just behind the beach."],"bestTime":"June–September","visitDuration":"2–3 hours","ticket":"","openingHours":"All day","galleryCaptions":["Hyeopjae beach looking out to Biyangdo"]},"ko":{"name":"협재해수욕장","summary":"비양도를 마주 보는 흰 모래와 얕은 물. 제주 서쪽 최고의 일몰이다.","story":"협재의 물은 백 미터 밖에서도 바닥이 보일 만큼 얕고 맑아, 물빛이 옥빛에서 짙은 파랑으로 천천히 바뀐다. 바로 앞바다에는 둥근 비양도가 떠 있고, 그 뒤로 해가 내려앉으면 해변 전체가 주황빛이 된다. 백사장 뒤로는 그늘과 야영장을 내주는 소나무 숲이, 옆으로는 한림공원이 있다. 서쪽을 향하고 있어 제주에서 해돋이가 아니라 바다로 지는 해를 볼 수 있는 몇 안 되는 해변이다.","facts":["조개껍데기가 섞인 흰 모래로, 섬의 검은 화산 모래와 다르다.","얕은 물이 길게 이어져 아이와 함께 가기 좋다.","한림항에서 배로 갈 수 있는 비양도를 마주 본다.","옆에는 식물원과 작은 용암동굴을 갖춘 한림공원이 있다."],"travelTips":["늦은 오후에 가서 물놀이를 하고 일몰까지 보자.","여름 성수기는 매우 붐빈다. 6월이나 9월이 훨씬 여유롭다.","해변 뒤에 공용 샤워장과 탈의실이 있다."],"bestTime":"6~9월","visitDuration":"2~3시간","ticket":"","openingHours":"상시","galleryCaptions":["비양도가 보이는 협재 해변"]},"ja":{"name":"挟才海水浴場","summary":"飛揚島を望む白砂と浅瀬。済州西海岸で最も美しい夕日。","story":"挟才の海は百メートル先でも底が見えるほど浅く澄み、水の色が翡翠から濃い青へと移ろう。すぐ沖には丸い飛揚島が浮かび、その向こうに日が落ちると浜全体が橙色になる。砂浜の背後には日陰とキャンプ場になる松林があり、隣には翰林公園。西を向いているため、済州で日の出ではなく海に沈む夕日を見られる数少ない浜だ。","facts":["貝殻の混じった白砂で、島の黒い火山砂とは異なる。","浅瀬が長く続き、小さな子ども連れでも安心。","翰林港から船で渡れる飛揚島を正面に望む。","隣には植物園と小さな溶岩洞窟のある翰林公園がある。"],"travelTips":["午後遅くに行って泳ぎ、そのまま夕日まで過ごそう。","夏の最盛期は非常に混む。6月か9月がずっと快適。","浜の裏に公共シャワーと更衣室がある。"],"bestTime":"6〜9月","visitDuration":"2〜3時間","ticket":"","openingHours":"終日","galleryCaptions":["飛揚島を望む挟才の浜"]},"zh":{"name":"挾才海水浴場","summary":"面向飛揚島的白沙與淺水，是濟州西岸最美的日落。","story":"挾才的海水又淺又清，離岸百公尺仍看得見沙底，顏色從碧綠漸層到深藍。海面上是渾圓的飛揚島，太陽落到它後面時，整片沙灘轉為橙色。沙灘後方的松林提供樹蔭與營地，一旁是翰林公園。由於面向西方，這是濟州少數能看見太陽沉入海中、而非自海中升起的海灘。","facts":["白沙由貝殼碎屑構成，與島上他處的黑色火山沙不同。","淺灘綿延，適合帶小孩同行。","正對飛揚島，可自翰林港搭船前往。","隔壁是設有植物園與小型熔岩洞的翰林公園。"],"travelTips":["傍晚前來，戲水後可直接留下看日落。","夏季旺季非常擁擠，六月或九月舒服得多。","沙灘後方設有公共淋浴間與更衣室。"],"bestTime":"6至9月","visitDuration":"2至3小時","ticket":"","openingHours":"全日","galleryCaptions":["望向飛揚島的挾才海灘"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jusangjeolli-cliff', 'jusangjeolli-cliff', 'jeju', 'Vách đá cột Jusangjeolli', 'Jusangjeolli Basalt Cliffs', 'beach', 126.427, 33.238, 'Hàng nghìn cột đá sáu cạnh xếp thẳng đứng bên biển, do dung nham nguội đi mà thành.', 'Khi dung nham của Hallasan chảy tới đây rồi gặp nước biển, nó nguội đột ngột và nứt theo phương thẳng đứng thành những cột đá đều tăm tắp, phần lớn sáu cạnh — thứ hiện tượng địa chất mà sách giáo khoa vẫn dùng ảnh Ireland để minh hoạ, còn Jeju thì có sẵn. Vách đá cao khoảng hai chục mét, kéo dài gần một cây số dọc bờ Daepo, và sóng đập vào chân cột bắn nước lên cao. Đài quan sát bằng gỗ chạy dọc mép vách nên không phải leo trèo gì; ngày biển động sóng dựng đứng, ngày lặng thì nhìn rõ từng cạnh cột dưới mặt nước trong.', '["Các cột đá hình thành khi dung nham gặp nước biển và nguội nhanh, nứt theo phương thẳng đứng.","Vách cao khoảng 20m, kéo dài gần 1 km dọc bờ biển Daepo.","Được công nhận là Đài kỷ niệm thiên nhiên số 443.","Nằm trong khu du lịch Jungmun, gần các khách sạn lớn phía nam đảo."]', '["Ngày biển động sóng đẹp nhất nhưng gió lớn — giữ chặt mũ.","Đài quan sát bằng gỗ, đi lại dễ, phù hợp cả xe đẩy.","Kết hợp với thác Cheonjiyeon và chợ Seogwipo trong cùng buổi."]', 'Quanh năm; đẹp nhất khi biển động', '1 giờ', '2.000 KRW', '09:00–18:00', '["popular"]', '["địa chất","biển","núi lửa","vách đá"]', '[{"seed":"jusangjeolli-cliff","caption":"Cột đá sáu cạnh bên biển Daepo","ratio":"16/9"}]', '["cheonjiyeon-waterfall","sanbangsan"]', 0, 'https://www.visitjeju.net/en', '2026-08-04', '{"en":{"name":"Jusangjeolli Basalt Cliffs","summary":"Thousands of vertical hexagonal stone columns by the sea, formed as lava cooled.","story":"When Hallasan''s lava reached here and met the sea it cooled abruptly and cracked vertically into even columns, most of them six-sided — the geological effect textbooks usually illustrate with photographs of Ireland, and which Jeju has to hand. The cliff stands about twenty metres and runs nearly a kilometre along the Daepo shore, with the swell throwing spray up the base of the columns. A wooden deck follows the cliff edge, so there is no scrambling; on rough days the waves stand up, and on calm ones you can count the faces of the columns through clear water.","facts":["The columns formed as lava met seawater and cooled fast, cracking vertically.","The cliff is about 20m high and runs nearly 1km along the Daepo coast.","Designated Natural Monument No. 443.","It lies in the Jungmun resort area on the island''s south coast."],"travelTips":["Rough days give the best waves but strong wind — hold onto your hat.","The wooden deck is easy going and works for pushchairs.","Combine with Cheonjiyeon falls and Seogwipo market in one outing."],"bestTime":"Year-round; best when the sea is rough","visitDuration":"1 hour","ticket":"2,000 KRW","openingHours":"09:00–18:00","galleryCaptions":["Hexagonal columns on the Daepo shore"]},"ko":{"name":"주상절리대","summary":"바다 옆에 수직으로 늘어선 수천 개의 육각 돌기둥. 용암이 식으며 생겼다.","story":"한라산의 용암이 여기까지 흘러와 바닷물을 만나면서 급히 식었고, 세로로 갈라져 고른 기둥이 되었다. 대부분 육각이다. 교과서가 흔히 아일랜드 사진으로 설명하는 지질 현상을, 제주는 그냥 가지고 있다. 절벽은 높이 20m쯤에 대포 해안을 따라 1km 가까이 이어지고, 너울이 기둥 밑동을 때리며 물보라를 올린다. 벼랑을 따라 나무 데크가 놓여 있어 기어오를 일은 없다. 파도가 센 날은 물기둥이 서고, 잔잔한 날은 맑은 물 아래로 기둥의 면이 다 보인다.","facts":["용암이 바닷물을 만나 빠르게 식으면서 세로로 갈라져 생긴 기둥이다.","절벽 높이는 약 20m, 대포 해안을 따라 1km 가까이 이어진다.","천연기념물 제443호로 지정되어 있다.","섬 남쪽 중문관광단지 안에 있다."],"travelTips":["파도가 센 날이 가장 볼 만하지만 바람도 세다. 모자를 붙잡자.","나무 데크라 걷기 편하고 유모차도 괜찮다.","천지연폭포, 서귀포 시장과 묶어서 한 번에 돌자."],"bestTime":"연중, 파도가 센 날이 가장 좋다","visitDuration":"1시간","ticket":"2,000원","openingHours":"09:00~18:00","galleryCaptions":["대포 해안의 육각 돌기둥"]},"ja":{"name":"柱状節理帯","summary":"海辺に垂直に並ぶ数千本の六角の石柱。溶岩が冷えて生まれた。","story":"漢拏山の溶岩がここまで流れて海水に触れ、急に冷えて縦に割れ、揃った柱になった。多くは六角である。教科書がたいていアイルランドの写真で説明する地質現象を、済州は手元に持っている。崖は高さ二十メートルほどで大浦海岸沿いに一キロ近く続き、うねりが柱の根元を打って飛沫を上げる。崖の縁に沿って木のデッキがあるので登る必要はない。波の高い日は水柱が立ち、凪の日は澄んだ水の下に柱の面が数えられる。","facts":["溶岩が海水に触れて急冷し、縦に割れてできた柱である。","崖の高さは約20m、大浦海岸沿いに1km近く続く。","天然記念物第443号に指定されている。","島南部の中文観光団地内にある。"],"travelTips":["波の高い日が見応えがあるが風も強い。帽子を押さえよう。","木のデッキで歩きやすく、ベビーカーでも問題ない。","天地淵滝や西帰浦の市場とまとめて回ろう。"],"bestTime":"通年、波の高い日が最良","visitDuration":"1時間","ticket":"2,000ウォン","openingHours":"09:00〜18:00","galleryCaptions":["大浦海岸の六角石柱"]},"zh":{"name":"柱狀節理帶","summary":"海邊上千根垂直的六角石柱，是熔岩冷卻後裂出來的。","story":"當漢拏山的熔岩流到這裡遇上海水，急速冷卻並沿垂直方向裂開，形成一根根整齊的石柱，多數是六邊形——教科書通常拿愛爾蘭的照片來說明的地質現象，濟州直接就有。崖高約二十公尺，沿大浦海岸延伸將近一公里，湧浪打在柱腳上濺起水花。崖邊架有木棧道，不必攀爬；風浪大的日子浪柱直立，風平時則能透過清澈的海水數清每根柱子的稜面。","facts":["石柱形成於熔岩遇海水急速冷卻、沿垂直方向裂開。","崖高約20公尺，沿大浦海岸延伸近1公里。","被指定為天然紀念物第443號。","位於島南部的中文觀光園區內。"],"travelTips":["風浪大的日子浪最好看，但風也強，記得抓緊帽子。","木棧道好走，推嬰兒車也沒問題。","可與天地淵瀑布、西歸浦市場排在同一趟。"],"bestTime":"全年；風浪大時最精采","visitDuration":"1小時","ticket":"2,000韓元","openingHours":"09:00–18:00","galleryCaptions":["大浦海岸的六角石柱"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('cheonjiyeon-waterfall', 'cheonjiyeon-waterfall', 'jeju', 'Thác Cheonjiyeon', 'Cheonjiyeon Waterfall', 'waterfall', 126.554, 33.247, 'Thác nước giữa một khe rừng á nhiệt đới ngay sau lưng thành phố, thắp đèn tới tận khuya.', 'Cheonjiyeon nghĩa là ''ao nơi trời gặp đất''. Đường vào chỉ chừng mười lăm phút đi bộ từ trung tâm Seogwipo, men theo một khe suối rợp cây á nhiệt đới — dây leo, dương xỉ thân gỗ, và rừng cây Psilotum được bảo vệ nghiêm ngặt. Cuối đường, thác cao hai mươi hai mét đổ xuống một hồ nước sâu hai chục mét, quanh năm không cạn. Dưới hồ có loài lươn khổng lồ được xếp hạng thiên nhiên bảo tồn, sống ẩn dưới đá. Thác mở tới mười giờ tối và được chiếu đèn, nên đây là một trong ít nơi ở Jeju đi được sau bữa tối.', '["Thác cao khoảng 22m, đổ xuống hồ sâu chừng 20m.","Khe suối là môi trường sống của rừng cây á nhiệt đới được bảo vệ.","Trong hồ có loài lươn khổng lồ được công nhận là Đài kỷ niệm thiên nhiên.","Mở cửa tới 22:00 và có chiếu sáng ban đêm."]', '["Đi buổi tối để tránh nắng và xem thác dưới đèn.","Đường vào bằng phẳng, chỉ khoảng 15 phút đi bộ.","Đừng nhầm với thác Cheonjeyeon ở Jungmun — hai nơi khác nhau."]', 'Tháng 5–10; sau mưa nước mạnh nhất', '1 giờ', '2.000 KRW (7–24 tuổi 1.000 KRW)', '09:00–21:20', '["popular"]', '["thác nước","rừng á nhiệt đới","về đêm"]', '[{"seed":"cheonjiyeon-waterfall","caption":"Thác Cheonjiyeon dưới đèn đêm","ratio":"16/9"}]', '["seogwipo-olle-market","jusangjeolli-cliff"]', 0, 'https://www.visitjeju.net/en/detail/view?contentsid=CONT_000000000500348', '2026-08-04', '{"en":{"name":"Cheonjiyeon Waterfall","summary":"A waterfall in a subtropical gorge right behind the city, floodlit until late.","story":"Cheonjiyeon means ''the pond where sky meets earth''. It is only a fifteen-minute walk from central Seogwipo, along a gorge thick with subtropical growth — lianas, tree ferns and a strictly protected stand of Psilotum. At the end, the fall drops twenty-two metres into a pool twenty metres deep that never runs dry. Giant eels, themselves a protected natural monument, live under the rocks below. The falls stay open until ten at night and are lit, making this one of the few things on Jeju you can do after dinner.","facts":["The fall is about 22m high, dropping into a pool some 20m deep.","The gorge shelters a protected subtropical forest.","Giant eels in the pool are themselves designated a natural monument.","It stays open until 22:00 and is floodlit at night."],"travelTips":["Come in the evening to skip the heat and see the falls lit.","The path in is flat and takes about 15 minutes.","Don''t confuse it with Cheonjeyeon falls at Jungmun — different place."],"bestTime":"May–October; strongest flow after rain","visitDuration":"1 hour","ticket":"2,000 KRW (1,000 KRW ages 7–24)","openingHours":"09:00–21:20","galleryCaptions":["Cheonjiyeon falls under the night lights"]},"ko":{"name":"천지연폭포","summary":"도심 바로 뒤 아열대 골짜기의 폭포. 밤늦게까지 조명이 켜진다.","story":"천지연은 ''하늘과 땅이 만나는 못''이라는 뜻이다. 서귀포 도심에서 걸어서 십오 분이면 닿고, 길은 아열대 식생이 빽빽한 골짜기를 따라간다. 덩굴과 나무고사리, 그리고 엄격히 보호되는 솔잎란 자생지가 있다. 길 끝에서 22m 높이의 폭포가 깊이 20m쯤 되는 못으로 떨어지고, 그 물은 마르지 않는다. 못 아래 바위 밑에는 천연기념물인 무태장어가 산다. 밤 열 시까지 열고 조명을 켜기 때문에, 제주에서 저녁을 먹고 갈 수 있는 몇 안 되는 곳이다.","facts":["폭포 높이는 약 22m, 깊이 20m가량의 못으로 떨어진다.","골짜기는 보호되는 아열대 식물 군락의 서식지다.","못에 사는 무태장어 역시 천연기념물로 지정되어 있다.","밤 22:00까지 개방하며 야간 조명이 있다."],"travelTips":["더위를 피하고 조명도 볼 겸 저녁에 가자.","진입로는 평탄하고 15분쯤이면 닿는다.","중문의 천제연폭포와 헷갈리지 말자. 다른 곳이다."],"bestTime":"5~10월, 비 온 뒤 수량이 가장 많다","visitDuration":"1시간","ticket":"2,000원(7~24세 1,000원)","openingHours":"09:00~21:20","galleryCaptions":["야간 조명 아래의 천지연폭포"]},"ja":{"name":"天地淵滝","summary":"市街のすぐ裏、亜熱帯の谷にある滝。夜遅くまで照明が入る。","story":"天地淵は「天と地が出会う淵」の意だ。西帰浦の中心から歩いて十五分、亜熱帯の植生が濃い谷に沿って進む。蔓とヘゴ、そして厳重に保護されるマツバランの自生地がある。道の果てで、高さ二十二メートルの滝が深さ二十メートルほどの淵へ落ち、その水は涸れない。淵の岩の下には天然記念物のオオウナギが棲む。夜十時まで開いて照明が入るため、済州で夕食のあとに行ける数少ない場所である。","facts":["滝の高さは約22m、深さ20mほどの淵へ落ちる。","谷は保護された亜熱帯植物群落の生息地である。","淵に棲むオオウナギも天然記念物に指定されている。","夜22:00まで開放され、夜間照明がある。"],"travelTips":["暑さを避け、照明も見るなら夕方に行こう。","進入路は平坦で15分ほどで着く。","中文の天帝淵滝と混同しないように。別の場所だ。"],"bestTime":"5〜10月、雨のあとが最も水量が多い","visitDuration":"1時間","ticket":"2,000ウォン（7〜24歳は1,000ウォン）","openingHours":"09:00〜21:20","galleryCaptions":["夜間照明の天地淵滝"]},"zh":{"name":"天地淵瀑布","summary":"市區後方亞熱帶峽谷中的瀑布，打燈開放到深夜。","story":"天地淵意為「天與地相遇的水潭」。從西歸浦市中心步行僅十五分鐘，沿著一條亞熱帶植被濃密的峽谷前行：藤蔓、樹蕨，以及一片受嚴格保護的松葉蕨自生地。路的盡頭，瀑布自二十二公尺高處落入約二十公尺深的水潭，終年不涸。潭底岩石下棲息著同樣被列為天然紀念物的巨鰻。瀑布開放至晚間十點並打上燈光，是濟州少數能在晚餐後前往的景點。","facts":["瀑布高約22公尺，落入約20公尺深的水潭。","峽谷是受保護的亞熱帶植物群落棲地。","潭中的巨鰻本身也被指定為天然紀念物。","開放至22:00，並設有夜間照明。"],"travelTips":["傍晚前來可避開暑氣，也看得到打燈的瀑布。","步道平坦，走進去約15分鐘。","別和中文的天帝淵瀑布搞混，是兩個不同的地方。"],"bestTime":"5至10月；雨後水量最大","visitDuration":"1小時","ticket":"2,000韓元（7至24歲1,000韓元）","openingHours":"09:00–21:20","galleryCaptions":["夜燈下的天地淵瀑布"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('sanbangsan', 'sanbangsan', 'jeju', 'Núi Sanbangsan & bờ đá Yongmeori', 'Sanbangsan & Yongmeori Coast', 'mountain', 126.312, 33.236, 'Vòm dung nham dựng đứng như một quả chuông đá, dưới chân là bờ đá trầm tích xếp lớp như vảy rồng.', 'Sanbangsan không có miệng núi lửa — nó là một khối dung nham đặc quánh trồi lên rồi đông cứng tại chỗ, tạo thành hình quả chuông cao gần bốn trăm mét đứng lẻ loi giữa đồng. Truyền thuyết bảo đây chính là phần đỉnh Hallasan bị một vị thần giận dữ ném đi. Lưng chừng núi có một hang đá với ngôi chùa nhỏ nhìn thẳng ra biển. Dưới chân núi là bờ Yongmeori — ''đầu rồng'' — nơi đá trầm tích bị sóng và gió khoét thành từng lớp uốn lượn, đi được khi thuỷ triều xuống. Cũng ở đây có bản sao con tàu của Hendrick Hamel, người Hà Lan dạt vào Jeju năm 1653 và sau này viết cuốn sách đầu tiên giới thiệu Triều Tiên cho châu Âu.', '["Sanbangsan cao khoảng 395m, là vòm dung nham trồi lên chứ không có miệng núi.","Hang Sanbanggulsa lưng chừng núi có chùa nhìn ra biển.","Bờ Yongmeori chỉ đi được khi thuỷ triều xuống và biển lặng.","Gần đó có bảo tàng và bản sao tàu của Hendrick Hamel, đắm ở Jeju năm 1653."]', '["Tra lịch thuỷ triều: bờ Yongmeori đóng khi nước lên hoặc sóng lớn.","Lên hang chùa phải leo khoảng 150 bậc đá khá dốc.","Kết hợp với cánh đồng cải vàng quanh núi vào tháng 3."]', 'Tháng 3 (hoa cải) và tháng 4–6, 9–11', '2–3 giờ', 'Bờ Yongmeori 2.000 KRW (thiếu niên và trẻ em 1.000); chùa trong hang 1.000 KRW. Miễn phí cho trẻ dưới 6 và người từ 65 tuổi', '09:00–18:00', '["hidden-gem","verified"]', '["núi lửa","bờ đá","chùa","địa chất"]', '[{"seed":"sanbangsan","caption":"Sanbangsan nhìn từ bờ Yongmeori","ratio":"16/9"}]', '["jusangjeolli-cliff"]', 1, 'https://theshinvia.com/yongmeori-coast-jeju/', '2026-08-04', '{"en":{"name":"Sanbangsan & Yongmeori Coast","summary":"A lava dome standing like a stone bell, above a shore of layered rock folded like dragon scales.","story":"Sanbangsan has no crater — it is a plug of stiff lava that pushed up and set where it stood, a bell nearly four hundred metres high standing alone in the fields. Legend says it is the summit of Hallasan, thrown here by an angry god. Halfway up is a cave holding a small temple that looks straight out to sea. Below the mountain is the Yongmeori coast — ''dragon''s head'' — where sedimentary rock has been cut by wind and waves into curving layers, walkable at low tide. Here too is a replica of the ship of Hendrick Hamel, the Dutchman wrecked on Jeju in 1653 who later wrote the first account of Korea for European readers.","facts":["Sanbangsan is about 395m high and is a lava dome, with no crater.","The Sanbanggulsa cave halfway up holds a temple facing the sea.","The Yongmeori shore is only accessible at low tide in calm weather.","A museum and replica ship nearby commemorate Hendrick Hamel, wrecked here in 1653."],"travelTips":["Check the tide table: Yongmeori closes at high water or in heavy swell.","The cave temple is about 150 fairly steep stone steps up.","Come in March for the rapeseed fields around the mountain."],"bestTime":"March (rapeseed) and April–June, September–November","visitDuration":"2–3 hours","ticket":"Yongmeori coast 2,000 KRW (1,000 teens and children); the cave temple 1,000 KRW. Free under 6 and over 65","openingHours":"09:00–18:00","galleryCaptions":["Sanbangsan seen from the Yongmeori shore"]},"ko":{"name":"산방산과 용머리해안","summary":"돌종처럼 선 용암돔. 그 아래는 용의 비늘처럼 층진 퇴적암 해안이다.","story":"산방산에는 분화구가 없다. 끈적한 용암이 솟아올라 그 자리에서 굳은 용암돔으로, 높이 400m에 가까운 종 모양이 들판 가운데 홀로 서 있다. 화가 난 신이 한라산 꼭대기를 뽑아 던진 것이라는 이야기가 전한다. 중턱에는 바다를 정면으로 보는 작은 절이 든 굴이 있다. 산 아래는 용머리해안이다. 퇴적암이 바람과 파도에 깎여 굽이치는 층을 이루었고, 물이 빠졌을 때만 걸을 수 있다. 이곳에는 1653년 제주에 표착해 훗날 유럽에 조선을 처음 알린 하멜의 배 모형도 있다.","facts":["산방산은 높이 약 395m의 용암돔으로 분화구가 없다.","중턱의 산방굴사에는 바다를 향한 절이 있다.","용머리해안은 간조에 파도가 잔잔할 때만 들어갈 수 있다.","1653년 표착한 하멜을 기리는 기념관과 배 모형이 가까이 있다."],"travelTips":["물때를 확인하자. 만조나 너울이 크면 용머리해안은 통제된다.","산방굴사까지는 제법 가파른 돌계단 150개쯤을 올라야 한다.","3월에는 산 둘레의 유채밭과 함께 보자."],"bestTime":"3월(유채)과 4~6월, 9~11월","visitDuration":"2~3시간","ticket":"용머리해안 2,000원(청소년·어린이 1,000원), 산방굴사 1,000원. 6세 이하와 65세 이상 무료","openingHours":"09:00~18:00","galleryCaptions":["용머리해안에서 본 산방산"]},"ja":{"name":"山房山と龍頭海岸","summary":"石の鐘のように立つ溶岩ドーム。その下は龍の鱗のように層をなす堆積岩の海岸だ。","story":"山房山に火口はない。粘り気の強い溶岩が盛り上がってその場で固まった溶岩ドームで、高さ四百メートル近い鐘の形が野の中に独り立つ。怒った神が漢拏山の頂を抜いて投げたのだという話が伝わる。中腹には海を正面に望む小さな寺を収めた洞がある。山の下は龍頭海岸だ。堆積岩が風と波に削られてうねる層をなし、潮が引いたときだけ歩ける。ここには1653年に済州へ漂着し、のちにヨーロッパへ朝鮮を初めて伝えたハメルの船の復元模型もある。","facts":["山房山は高さ約395mの溶岩ドームで火口がない。","中腹の山房窟寺には海を向いた寺がある。","龍頭海岸は干潮で波の穏やかなときだけ入れる。","1653年に漂着したハメルを記念する館と復元船が近くにある。"],"travelTips":["潮汐を確認しよう。満潮やうねりが大きいと龍頭海岸は閉鎖される。","山房窟寺までは急な石段を150段ほど上る。","3月には山を囲む菜の花畑と合わせて見よう。"],"bestTime":"3月（菜の花）と4〜6月、9〜11月","visitDuration":"2〜3時間","ticket":"龍頭海岸2,000ウォン（青少年・子ども1,000）、山房窟寺1,000ウォン。6歳以下と65歳以上は無料","openingHours":"09:00〜18:00","galleryCaptions":["龍頭海岸から見た山房山"]},"zh":{"name":"山房山與龍頭海岸","summary":"像石鐘般矗立的熔岩穹丘，腳下是層層摺疊如龍鱗的沉積岩海岸。","story":"山房山沒有火山口——它是一團黏稠熔岩湧上後就地凝固而成的熔岩穹丘，近四百公尺高的鐘形獨自立在原野之中。傳說那是被憤怒的神明拔走扔到這裡的漢拏山山頂。半山腰有一處洞窟，裡頭的小寺正對著大海。山腳下是龍頭海岸——被風與浪切削成波狀層理的沉積岩，只有退潮時才能行走。這裡還有一艘哈梅爾船的複製品：這位荷蘭人1653年在濟州遇難，後來寫下歐洲第一本介紹朝鮮的書。","facts":["山房山高約395公尺，屬熔岩穹丘，沒有火山口。","半山腰的山房窟寺內有一座面海的寺院。","龍頭海岸僅在退潮且風平浪靜時開放通行。","附近設有紀念館與複製船，紀念1653年在此遇難的哈梅爾。"],"travelTips":["先查潮汐表：漲潮或浪大時龍頭海岸會封閉。","上到洞窟寺要爬約150級相當陡的石階。","三月可順道看山周圍的油菜花田。"],"bestTime":"3月（油菜花）與4至6月、9至11月","visitDuration":"2至3小時","ticket":"龍頭海岸2,000韓元（青少年與兒童1,000）、山房窟寺1,000韓元；6歲以下與65歲以上免費","openingHours":"09:00–18:00","galleryCaptions":["自龍頭海岸望向山房山"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seongeup-folk-village', 'seongeup-folk-village', 'jeju', 'Làng dân tộc Seongeup', 'Seongeup Folk Village', 'village', 126.799, 33.388, 'Ngôi làng còn người ở với nhà mái tranh buộc dây thừng và tường đá đen xếp không vữa.', 'Seongeup từng là lỵ sở của huyện Jeongui suốt năm thế kỷ, và khác với các làng dựng lại cho khách xem, đây là làng thật với người thật đang sống. Nhà ở Jeju khác hẳn đất liền: mái tranh không lợp dày mà buộc chằng bằng lưới dây thừng để chống gió bão, tường đá bazan đen xếp khan không vữa cho gió lùa qua khe thay vì đẩy đổ, và trước cổng có ba thanh gỗ ngang — hạ cả ba nghĩa là chủ nhà có nhà, dựng cả ba nghĩa là đi xa nhiều ngày. Trong làng còn cây zelkova cổ thụ, cối xay ngựa kéo và những ông đá dol hareubang gác cổng.', '["Từng là lỵ sở huyện Jeongui từ năm 1423 đến 1914.","Mái tranh được buộc bằng lưới dây thừng để chống gió bão Jeju.","Hệ thống ba thanh gỗ jeongnang trước cổng dùng để báo chủ nhà có ở nhà hay không.","Là làng dân tộc được bảo tồn nhưng cư dân vẫn sinh sống bình thường."]', '["Có hướng dẫn viên tình nguyện miễn phí ở cổng làng, nên hỏi.","Cẩn thận với các tour bán đặc sản ép giá bên trong làng.","Đây là nơi có người ở — hỏi trước khi bước vào sân nhà."]', 'Quanh năm', '1,5 giờ', '', '09:00 đến lúc mặt trời lặn; đây là làng có người ở thật, hãy giữ yên tĩnh', '["hidden-gem"]', '["làng cổ","kiến trúc","văn hoá Jeju"]', '[{"seed":"seongeup-folk-village","caption":"Nhà mái tranh buộc dây và tường đá đen","ratio":"16/9"}]', '["seongsan-ilchulbong","bijarim-forest"]', 0, 'https://m.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500351', '2026-08-05', '{"en":{"name":"Seongeup Folk Village","summary":"A lived-in village of rope-lashed thatch and black stone walls stacked without mortar.","story":"Seongeup was the seat of Jeongui county for five centuries, and unlike villages rebuilt for visitors this is a real one with people still living in it. Jeju houses are unlike the mainland''s: thatch is not laid thick but lashed down under a net of rope against the typhoons, walls of black basalt are stacked dry so the wind passes through the gaps rather than pushing them over, and three wooden bars sit across the gateway — all three down means the owner is home, all three up means away for days. The village also holds an old zelkova, a horse-drawn millstone and dol hareubang stone grandfathers at the gates.","facts":["It was the seat of Jeongui county from 1423 to 1914.","Thatch is lashed under a rope net against Jeju''s typhoons.","The three jeongnang bars at each gate signal whether the owner is at home.","It is a preserved folk village where residents still live ordinary lives."],"travelTips":["Free volunteer guides wait at the village gate — worth asking for one.","Be wary of hard-sell speciality tours inside the village.","People live here; ask before stepping into a yard."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"","openingHours":"09:00 until sunset; this is a village people actually live in, so keep the noise down","galleryCaptions":["Rope-lashed thatch and black stone walls"]},"ko":{"name":"성읍민속마을","summary":"새끼줄로 동여맨 초가와 회 없이 쌓은 검은 돌담이 있는, 사람이 사는 마을.","story":"성읍은 오백 년 동안 정의현의 현청이 있던 곳이고, 관광용으로 지은 마을과 달리 지금도 사람이 사는 진짜 마을이다. 제주의 집은 뭍과 다르다. 초가는 두껍게 얹는 대신 새끼줄 그물로 눌러 태풍에 대비했고, 검은 현무암 담은 회 없이 쌓아 바람이 틈으로 지나가게 했다. 대문 자리에는 나무 막대 세 개가 걸리는데, 셋 다 내려 있으면 주인이 집에 있다는 뜻이고 셋 다 걸려 있으면 여러 날 집을 비웠다는 뜻이다. 마을에는 늙은 느티나무와 말이 끌던 연자방아, 그리고 대문을 지키는 돌하르방이 있다.","facts":["1423년부터 1914년까지 정의현의 현청이 있던 곳이다.","제주의 태풍에 대비해 초가를 새끼줄 그물로 눌러 묶는다.","대문의 정낭 세 개로 주인의 재실 여부를 알린다.","보존 민속마을이지만 주민들이 실제로 살고 있다."],"travelTips":["마을 입구에 무료 자원봉사 해설사가 있으니 청해 보자.","마을 안의 강매성 특산물 판매 안내는 조심하자.","사람이 사는 곳이다. 마당에 들어가기 전에 물어보자."],"bestTime":"연중","visitDuration":"1.5시간","ticket":"","openingHours":"09:00부터 일몰까지. 실제 주민이 사는 마을이니 조용히 둘러보자","galleryCaptions":["새끼줄로 묶은 초가와 검은 돌담"]},"ja":{"name":"城邑民俗村","summary":"縄で縛った茅葺きと、モルタルなしで積んだ黒い石垣が残る、人の住む村。","story":"城邑は五百年のあいだ旌義県の県庁が置かれた場所で、見せるために建てた村と違い、今も人が暮らす本物の村だ。済州の家は本土と違う。茅は厚く葺かず縄の網で押さえて台風に備え、黒い玄武岩の垣はモルタルなしで積んで風が隙間を抜けるようにする。門の位置には木の棒が三本渡され、三本とも下ろしてあれば主人は家にいて、三本とも掛けてあれば何日も留守という意味だ。村には古いケヤキ、馬が挽いた石臼、そして門を守る石の翁トルハルバンがある。","facts":["1423年から1914年まで旌義県の県庁が置かれていた。","済州の台風に備え、茅葺きを縄の網で押さえる。","門の三本の棒チョンナンで主人の在宅を知らせる。","保存民俗村でありながら、住民が実際に暮らしている。"],"travelTips":["村の入口に無料のボランティア解説員がいる。頼んでみよう。","村内での強引な特産品販売には注意しよう。","人が住んでいる。庭に入る前にひと言尋ねよう。"],"bestTime":"通年","visitDuration":"1.5時間","ticket":"","openingHours":"09:00から日没まで。実際に住民が暮らす集落なので静かに見学を","galleryCaptions":["縄で縛った茅葺きと黒い石垣"]},"zh":{"name":"城邑民俗村","summary":"以繩網壓住茅頂、用黑石乾砌矮牆的村落，至今仍有人居住。","story":"城邑做了五百年旌義縣的縣治所在，與那些為觀光而重建的村子不同，這是真的還有人住的村落。濟州的房子和本土不一樣：茅草不鋪厚，而是用繩網壓住以抗颱風；黑色玄武岩牆乾砌不抹灰，好讓風從縫隙穿過而不是把牆推倒；門口橫著三根木棍——三根都放下表示主人在家，三根都架起表示外出多日。村裡還有老櫸樹、馬拉的石磨，以及守在門口的石爺爺「石頭爺」。","facts":["1423年至1914年間為旌義縣縣治所在地。","茅頂以繩網壓住，用以抵擋濟州的颱風。","門口三根「正木」用來示意主人是否在家。","雖是保存民俗村，居民仍過著日常生活。"],"travelTips":["村口有免費的志工導覽員，值得請一位。","村內若遇強力推銷特產的行程，請留意。","這裡有人居住，進院子前請先詢問。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"","openingHours":"09:00至日落；這是真的有居民生活的村落，請保持安靜","galleryCaptions":["繩網壓住的茅頂與黑石矮牆"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('bijarim-forest', 'bijarim-forest', 'jeju', 'Rừng Bijarim', 'Bijarim Nutmeg Yew Forest', 'park', 126.81, 33.488, 'Rừng thông đầu rìu thuần loài lớn nhất thế giới, hơn hai nghìn cây, cây già nhất tám trăm tuổi.', 'Bijarim là rừng thuần loài cây bija lớn nhất thế giới — hơn hai nghìn tám trăm cây, tuổi từ ba trăm đến tám trăm năm, mọc chen nhau trên một vùng đất bằng phẳng. Lối đi rải đá núi lửa đỏ vụn, và không khí trong rừng đặc quánh mùi nhựa cây, được đo là có nồng độ phytoncide rất cao nên người Hàn đến đây để ''tắm rừng''. Cuối đường có cây bija tổ hơn tám trăm tuổi với thân to đến mức ba người ôm không xuể. Tương truyền rừng này mọc lên từ hạt bija mà dân làng quanh vùng dùng làm thuốc rồi vứt bỏ.', '["Có hơn 2.800 cây bija, là rừng thuần loài lớn nhất thế giới của loài này.","Cây già nhất trong rừng ước tính hơn 800 năm tuổi.","Được công nhận là Đài kỷ niệm thiên nhiên số 374.","Lối đi rải đá núi lửa đỏ scoria, tổng chiều dài khoảng 2,2 km."]', '["Đường đi bằng phẳng, phù hợp cả người lớn tuổi và trẻ nhỏ.","Đi buổi sáng sớm khi rừng còn ẩm sương, mùi nhựa cây rõ nhất.","Không có bóng râm ở bãi xe — đỗ xe rồi vào rừng ngay."]', 'Quanh năm; tháng 5–6 và 9–11 dễ chịu nhất', '1,5–2 giờ', '3.000 KRW (thiếu niên và trẻ em 1.500); miễn phí cho trẻ dưới 6 và người từ 65 tuổi', '09:00–18:00, vào cửa cuối 17:00', '["hidden-gem"]', '["rừng","cây cổ thụ","tắm rừng","đi bộ"]', '[{"seed":"bijarim-forest","caption":"Lối đá đỏ giữa rừng bija","ratio":"16/9"}]', '["manjanggul","seongeup-folk-village"]', 0, 'https://www.visitjeju.net/kr/detail/view?contentsid=CONT_000000000500580', '2026-08-04', '{"en":{"name":"Bijarim Nutmeg Yew Forest","summary":"The world''s largest pure stand of nutmeg yew — over two thousand trees, the oldest eight hundred years old.","story":"Bijarim is the largest single-species stand of bija in the world — more than two thousand eight hundred trees, between three and eight hundred years old, growing close together on flat ground. The paths are laid with crushed red volcanic scoria, and the air inside is thick with resin; it measures very high in phytoncides, which is why Koreans come here to take a forest bath. At the far end stands the ancestral bija, over eight hundred years old, with a trunk three people cannot reach around. The forest is said to have grown from bija seeds that villagers used as medicine and threw away.","facts":["Over 2,800 bija trees, the world''s largest pure stand of the species.","The oldest tree in the forest is estimated at more than 800 years.","Designated Natural Monument No. 374.","The paths are laid with red volcanic scoria and run about 2.2km in total."],"travelTips":["The route is flat and suits both older visitors and small children.","Come early, while the forest is still damp and the resin smell is strongest.","There is no shade in the car park — park and go straight in."],"bestTime":"Year-round; May–June and September–November are most comfortable","visitDuration":"1.5–2 hours","ticket":"3,000 KRW (1,500 teens and children); free under 6 and over 65","openingHours":"09:00–18:00, last entry 17:00","galleryCaptions":["The red scoria path through the bija forest"]},"ko":{"name":"비자림","summary":"세계 최대의 비자나무 단일 숲. 이천 그루가 넘고 가장 늙은 나무는 팔백 살이다.","story":"비자림은 세계에서 가장 큰 비자나무 단일 군락이다. 이천팔백 그루가 넘고 수령은 삼백 년에서 팔백 년 사이이며, 평평한 땅에 서로 붙어 자란다. 길에는 붉은 화산 송이가 깔려 있고, 숲 안의 공기는 나무 진 냄새로 짙다. 피톤치드 농도가 매우 높게 측정되어 사람들이 숲을 찾는 이유이기도 하다. 길 끝에는 팔백 년이 넘은 비자나무 조상목이 있는데, 셋이 팔을 벌려도 안기지 않는다. 이 숲은 마을 사람들이 약으로 쓰고 버린 비자 씨앗에서 자라났다고 전한다.","facts":["비자나무 2,800여 그루로 이 수종의 세계 최대 단일 군락이다.","숲에서 가장 늙은 나무는 수령 800년이 넘는 것으로 본다.","천연기념물 제374호로 지정되어 있다.","길에는 붉은 화산 송이가 깔려 있고 총 길이는 약 2.2km다."],"travelTips":["길이 평탄해 어르신과 아이도 걷기 좋다.","숲이 아직 젖어 있는 이른 아침에 가면 나무 냄새가 가장 짙다.","주차장에 그늘이 없다. 차를 대고 바로 숲으로 들어가자."],"bestTime":"연중, 5~6월과 9~11월이 가장 쾌적하다","visitDuration":"1.5~2시간","ticket":"3,000원(청소년·어린이 1,500원), 6세 이하와 65세 이상 무료","openingHours":"09:00~18:00, 입장 마감 17:00","galleryCaptions":["비자림의 붉은 송이길"]},"ja":{"name":"榧子林","summary":"世界最大のカヤ単一林。二千本を超え、最も古い木は八百年。","story":"榧子林は世界最大のカヤの単一群落だ。二千八百本を超え、樹齢は三百年から八百年、平らな土地に密に育つ。道には赤い火山礫が敷かれ、林の空気は樹脂の匂いで濃い。フィトンチッドの濃度が非常に高く測られ、人々が森林浴に訪れる理由になっている。道の果てには八百年を超える始祖木があり、三人で腕を回しても届かない。この森は、村人が薬に使って捨てたカヤの種から育ったのだと伝わる。","facts":["カヤ2,800本余りで、この樹種としては世界最大の単一群落である。","森で最も古い木は樹齢800年を超えると見られる。","天然記念物第374号に指定されている。","道には赤い火山礫が敷かれ、総延長は約2.2kmである。"],"travelTips":["道が平坦で、高齢者にも子どもにも歩きやすい。","森がまだ湿っている早朝に行くと樹脂の匂いが最も濃い。","駐車場に日陰がない。車を停めたらすぐ森へ入ろう。"],"bestTime":"通年、5〜6月と9〜11月が最も快適","visitDuration":"1.5〜2時間","ticket":"3,000ウォン（青少年・子ども1,500）、6歳以下と65歳以上は無料","openingHours":"09:00〜18:00、最終入場17:00","galleryCaptions":["榧子林の赤い火山礫の道"]},"zh":{"name":"榧子林","summary":"全球最大的榧樹純林，逾兩千株，最老的一株已八百歲。","story":"榧子林是全世界最大的榧樹單一樹種林——兩千八百餘株，樹齡介於三百至八百年之間，密密地長在一片平地上。步道鋪著紅色火山礫，林中空氣裡滿是樹脂味；此地測得的芬多精濃度極高，韓國人因此專程來這裡「森林浴」。步道盡頭立著一株逾八百歲的榧樹祖木，樹幹粗到三個人環抱也接不上手。相傳這片林子，是村民拿榧子入藥後丟棄的種子長成的。","facts":["榧樹逾2,800株，是該樹種全球最大的純林。","林中最老的樹推估樹齡超過800年。","被指定為天然紀念物第374號。","步道鋪紅色火山礫，總長約2.2公里。"],"travelTips":["路線平坦，長輩與幼童都走得輕鬆。","趁清早林子還帶著濕氣時來，樹脂味最濃。","停車場沒有遮蔭，停好車就直接進林子吧。"],"bestTime":"全年；5至6月與9至11月最舒適","visitDuration":"1.5至2小時","ticket":"3,000韓元（青少年與兒童1,500）；6歲以下與65歲以上免費","openingHours":"09:00–18:00，最後入場17:00","galleryCaptions":["穿過榧樹林的紅色火山礫步道"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('haenyeo-museum', 'haenyeo-museum', 'jeju', 'Bảo tàng Haenyeo', 'Haenyeo Museum', 'museum', 126.848, 33.527, 'Bảo tàng về những người phụ nữ lặn biển không bình khí, nghề đang tắt dần cùng thế hệ cuối.', 'Haenyeo là những người phụ nữ Jeju lặn xuống mười mét nước, nín thở hai phút, để bắt bào ngư và hải sâm — không bình khí, không đồ lặn hiện đại, chỉ một phao lưới và một cái móc sắt. Nghề này từng nuôi sống cả đảo và làm đảo lộn trật tự gia đình: người vợ ra biển kiếm tiền, người chồng trông con ở nhà. Bảo tàng trưng bày bộ đồ lặn bằng vải bông thời trước, phao tewak làm từ quả bầu khô, và những đoạn phim phỏng vấn. Điều lặng lẽ nhất trong bảo tàng là biểu đồ độ tuổi: phần lớn haenyeo còn hành nghề hiện nay đã trên bảy mươi.', '["Văn hoá haenyeo được UNESCO ghi vào danh sách di sản phi vật thể năm 2016.","Haenyeo lặn tới độ sâu khoảng 10m và nín thở khoảng 2 phút mỗi lần.","Phần lớn haenyeo đang hành nghề hiện nay đã trên 70 tuổi.","Bảo tàng nằm ở Hado-ri, một trong những làng haenyeo lâu đời nhất."]', '["Xem lịch biểu diễn lặn thật của haenyeo tại các bến gần đó.","Kết hợp với đảo Udo, nơi vẫn còn nhiều haenyeo hành nghề.","Bảo tàng đóng cửa thứ Hai."]', 'Quanh năm', '1,5 giờ', '1.100 KRW (thiếu niên 13–24 tuổi 500; trẻ dưới 12 tuổi miễn phí)', '09:00–18:00, đóng cửa thứ Hai', '["unesco","hidden-gem"]', '["haenyeo","bảo tàng","UNESCO","nghề biển"]', '[{"seed":"haenyeo-museum","caption":"Đồ nghề lặn của haenyeo","ratio":"16/9"}]', '["udo-island","seongsan-ilchulbong"]', 0, 'https://www.much.go.kr/cooperation/net/haen.do', '2026-08-04', '{"en":{"name":"Haenyeo Museum","summary":"A museum to the women who dive without air tanks — a trade fading with its last generation.","story":"Haenyeo are the Jeju women who dive ten metres down, holding their breath for two minutes, to gather abalone and sea cucumber — no tanks, no modern gear, only a net float and an iron hook. The trade once fed the whole island and inverted the order of the household: the wife went to sea for the money, the husband minded the children. The museum shows the cotton diving suits of earlier years, tewak floats made from dried gourds, and filmed interviews. The quietest thing in the building is the age chart: most working haenyeo today are over seventy.","facts":["Haenyeo culture was inscribed on UNESCO''s intangible heritage list in 2016.","Haenyeo dive to about 10m and hold their breath around two minutes at a time.","Most working haenyeo today are over seventy years old.","The museum stands in Hado-ri, one of the oldest haenyeo villages."],"travelTips":["Check the schedule for live haenyeo diving demonstrations at nearby landings.","Combine it with Udo island, where many haenyeo still work.","The museum closes on Mondays."],"bestTime":"Year-round","visitDuration":"1.5 hours","ticket":"1,100 KRW (500 for ages 13–24; free under 12)","openingHours":"09:00–18:00, closed Mondays","galleryCaptions":["A haenyeo''s diving equipment"]},"ko":{"name":"해녀박물관","summary":"산소통 없이 물에 드는 여자들의 박물관. 마지막 세대와 함께 저물어 가는 일이다.","story":"해녀는 십 미터를 내려가 이 분 동안 숨을 참으며 전복과 해삼을 캐는 제주 여자들이다. 산소통도 현대 장비도 없이 테왁 하나와 빗창 하나뿐이다. 이 일은 한때 섬을 먹여 살렸고 집안의 질서를 뒤집었다. 아내가 바다에 나가 돈을 벌고 남편이 아이를 봤다. 박물관에는 예전의 무명 물옷, 마른 박으로 만든 테왁, 그리고 구술 영상이 있다. 이 건물에서 가장 조용한 것은 연령 그래프다. 지금 물질하는 해녀 대부분이 일흔이 넘었다.","facts":["해녀 문화는 2016년 유네스코 무형문화유산에 등재되었다.","해녀는 약 10m까지 내려가 한 번에 2분가량 숨을 참는다.","현재 물질하는 해녀 대부분이 70세를 넘었다.","박물관은 오래된 해녀 마을 가운데 하나인 하도리에 있다."],"travelTips":["인근 포구의 해녀 물질 시연 일정을 확인해 보자.","아직 해녀가 많이 활동하는 우도와 묶어서 보자.","월요일은 휴관이다."],"bestTime":"연중","visitDuration":"1.5시간","ticket":"1,100원(청소년 13~24세 500원, 12세 이하 무료)","openingHours":"09:00~18:00, 월요일 휴관","galleryCaptions":["해녀의 물질 도구"]},"ja":{"name":"海女博物館","summary":"空気ボンベなしで潜る女たちの博物館。最後の世代とともに消えていく生業だ。","story":"海女は十メートル潜り、二分息を止めてアワビやナマコを採る済州の女たちだ。ボンベも現代的な装備もなく、あるのは網の浮きテワクと鉄の鉤だけである。この仕事はかつて島を養い、家の秩序を裏返した。妻が海へ出て稼ぎ、夫が子を見た。博物館には昔の木綿の潜水着、干した瓢箪で作ったテワク、そして聞き取りの映像がある。この建物で最も静かなのは年齢の図表だ。いま働いている海女の大半が七十を超えている。","facts":["海女文化は2016年にユネスコ無形文化遺産へ登録された。","海女は約10mまで潜り、一回につき2分ほど息を止める。","現在働いている海女の大半は70歳を超えている。","博物館は最も古い海女村のひとつ、下道里にある。"],"travelTips":["近くの船着場での海女の実演の日程を確認しよう。","今も海女が多く働く牛島と合わせて回ろう。","月曜は休館である。"],"bestTime":"通年","visitDuration":"1.5時間","ticket":"1,100ウォン（13〜24歳500ウォン、12歳以下は無料）","openingHours":"09:00〜18:00、月曜休館","galleryCaptions":["海女の潜水道具"]},"zh":{"name":"海女博物館","summary":"一座獻給不帶氧氣瓶下潛的女人們的博物館，這門行業正隨最後一代凋零。","story":"海女是濟州潛入十公尺深、閉氣兩分鐘採鮑魚與海參的女性——沒有氧氣瓶，沒有現代裝備，只有一個網製浮球和一支鐵鉤。這門行業曾養活整座島，也顛倒了家庭的秩序：妻子下海賺錢，丈夫在家帶孩子。館內展出早年的棉布潛水衣、用曬乾葫蘆做的浮球，以及口述影像。整棟建築裡最安靜的是那張年齡圖表：如今仍在下海的海女，大多已超過七十歲。","facts":["海女文化於2016年列入聯合國教科文組織非物質文化遺產。","海女下潛約10公尺，每次閉氣約兩分鐘。","如今仍在工作的海女多半年逾七十。","博物館位於下道里，是最古老的海女村落之一。"],"travelTips":["可查查鄰近碼頭海女實地表演的時間表。","可與仍有許多海女作業的牛島排在一起。","博物館週一休館。"],"bestTime":"全年","visitDuration":"1.5小時","ticket":"1,100韓元（13至24歲500韓元；12歲以下免費）","openingHours":"09:00–18:00，週一休館","galleryCaptions":["海女的潛水工具"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('seogwipo-olle-market', 'seogwipo-olle-market', 'jeju', 'Chợ Olle Seogwipo', 'Seogwipo Maeil Olle Market', 'market', 126.562, 33.249, 'Chợ có mái che dài bốn trăm mét, bán quýt hallabong, thịt heo đen và bánh cá xếp thành núi.', 'Chợ Seogwipo có từ đầu thế kỷ 20 và giờ là nơi tốt nhất trên đảo để ăn thử mọi thứ Jeju làm ra trong một buổi chiều. Dãy hàng dài bốn trăm mét có mái che nên mưa gió gì cũng đi được. Quýt hallabong xếp thành kim tự tháp cam rực, thịt heo đen nướng bán theo xiên, bánh omegi làm từ kê nếp lăn qua đậu đỏ, và bánh cá nhồi ăn nóng. Có cả quầy bán bào ngư do haenyeo bắt sáng đó. Tên chợ lấy theo tuyến đường mòn Olle số 6 đi ngang qua đây, nên nhiều người đi bộ đường dài dừng lại ăn trưa giữa chặng.', '["Chợ hình thành từ đầu thế kỷ 20, khu có mái che dài khoảng 400m.","Tuyến đường mòn Jeju Olle số 6 đi ngang qua chợ.","Đặc sản gồm quýt hallabong, thịt heo đen, bánh omegi và bào ngư.","Nhiều quầy bán đồ ăn chế biến tại chỗ để ăn ngay."]', '["Đi khoảng 16–19h khi hàng ăn nóng dọn ra đông đủ nhất.","Mua quýt hallabong về làm quà — có quầy đóng thùng gửi đi.","Có khu ghế ngồi chung ở giữa chợ để ăn tại chỗ."]', 'Quanh năm; quýt ngon nhất tháng 12–2', '1,5 giờ', '', 'Chợ mở quanh năm, phần lớn sạp bán khoảng 07:00–21:00, nhưng mỗi hàng một giờ riêng', '["popular"]', '["chợ","ẩm thực","quýt","Olle"]', '[{"seed":"seogwipo-olle-market","caption":"Quầy quýt hallabong trong chợ","ratio":"16/9"}]', '["cheonjiyeon-waterfall","jeju-olle-trail"]', 0, 'https://access.visitkorea.or.kr/ms/detail.do?cotId=a63eb571-d505-4743-93cc-ce2ee4c25ea7', '2026-08-05', '{"en":{"name":"Seogwipo Maeil Olle Market","summary":"Four hundred metres of covered market: hallabong tangerines, black pork and fish cakes stacked in heaps.","story":"Seogwipo market dates from the early 20th century and is now the best place on the island to eat your way through everything Jeju makes in a single afternoon. Four hundred metres of stalls sit under a roof, so weather is irrelevant. Hallabong tangerines are piled into orange pyramids, grilled black pork is sold on skewers, omegi cakes of glutinous millet are rolled in red bean, and stuffed fish cakes are eaten hot. One stall sells abalone the haenyeo brought up that morning. The market takes its name from Olle trail route 6, which runs straight through it, so long-distance walkers stop here for lunch mid-stage.","facts":["The market dates from the early 20th century; the covered section runs about 400m.","Jeju Olle trail route 6 passes directly through the market.","Specialities include hallabong tangerines, black pork, omegi cakes and abalone.","Many stalls cook to order for eating on the spot."],"travelTips":["Come between 4pm and 7pm, when the hot food stalls are all open.","Buy hallabong tangerines to take home; some stalls box and ship them.","There is communal seating in the middle of the market."],"bestTime":"Year-round; tangerines are best December–February","visitDuration":"1.5 hours","ticket":"","openingHours":"Open year-round; most stalls run roughly 07:00–21:00, though each keeps its own hours","galleryCaptions":["The hallabong tangerine stalls"]},"ko":{"name":"서귀포매일올레시장","summary":"400m의 지붕 덮인 시장. 한라봉과 흑돼지, 산처럼 쌓인 어묵이 있다.","story":"서귀포 시장은 20세기 초부터 있었고, 지금은 제주가 만드는 거의 모든 것을 한 오후에 먹어 볼 수 있는 섬에서 가장 좋은 곳이다. 400m의 가게들이 지붕 아래 있어 날씨는 상관없다. 한라봉이 주황색 피라미드로 쌓이고, 흑돼지 구이는 꼬치로 팔며, 차조로 빚은 오메기떡은 팥고물을 두르고, 속을 채운 어묵은 뜨거울 때 먹는다. 그날 아침 해녀가 잡아 온 전복을 파는 자리도 있다. 시장 이름은 이곳을 관통하는 올레 6코스에서 왔고, 그래서 장거리 도보 여행자들이 중간에 들러 점심을 먹는다.","facts":["20세기 초에 형성되었고 지붕이 덮인 구간은 약 400m다.","제주올레 6코스가 시장을 관통한다.","한라봉, 흑돼지, 오메기떡, 전복이 대표 먹거리다.","즉석에서 조리해 바로 먹을 수 있는 가게가 많다."],"travelTips":["오후 4시에서 7시 사이에 가면 따뜻한 먹거리 가게가 다 열려 있다.","한라봉은 선물용으로 좋다. 포장해 택배로 보내 주는 가게도 있다.","시장 가운데에 함께 앉아 먹을 수 있는 자리가 있다."],"bestTime":"연중, 한라봉은 12~2월이 제철","visitDuration":"1.5시간","ticket":"","openingHours":"연중 열리며 대부분의 점포가 대략 07:00~21:00이지만 가게마다 다르다","galleryCaptions":["시장의 한라봉 가게"]},"ja":{"name":"西帰浦毎日オルレ市場","summary":"400mの屋根つき市場。ハルラボンに黒豚、山積みの練り物がある。","story":"西帰浦の市場は二十世紀初めからあり、今では済州が作るものをひと午後で食べ尽くせる島で最良の場所だ。四百メートルの店が屋根の下に並ぶので天気は関係ない。ハルラボンがオレンジ色のピラミッドに積まれ、黒豚の焼き物は串で売られ、もち粟のオメギ餅は小豆をまとい、詰め物をした練り物は熱いうちに食べる。その朝に海女が採ってきたアワビを売る店もある。市場の名は、ここを貫くオルレ6コースから来ており、長く歩く旅人が途中の昼食に立ち寄る。","facts":["二十世紀初めに生まれ、屋根のある区間は約400mである。","済州オルレ6コースが市場を貫いている。","ハルラボン、黒豚、オメギ餅、アワビが名物である。","その場で調理してすぐ食べられる店が多い。"],"travelTips":["16時から19時のあいだに行くと、温かい食べ物の店が揃っている。","ハルラボンは土産に向く。箱詰めして送ってくれる店もある。","市場の中央に共同の飲食スペースがある。"],"bestTime":"通年、ハルラボンは12〜2月が旬","visitDuration":"1.5時間","ticket":"","openingHours":"年中営業で、多くの店はおおむね07:00〜21:00だが店ごとに異なる","galleryCaptions":["市場のハルラボンの店"]},"zh":{"name":"西歸浦每日偶來市場","summary":"四百公尺長的有頂市場：漢拏峰橘、黑豬肉，以及堆成小山的魚板。","story":"西歸浦市場自二十世紀初就在，如今是全島最適合用一個下午吃遍濟州出產的地方。四百公尺的攤商都在屋頂之下，天氣好壞無所謂。漢拏峰橘堆成橘色金字塔，炭烤黑豬肉論串賣，用糯粟做的五味子糕裹著紅豆粉，包餡魚板要趁熱吃。還有攤子賣海女當天早上採上來的鮑魚。市場的名字來自貫穿其中的偶來第6號路線，因此長程健行的人常在中途停下來吃午餐。","facts":["市場形成於二十世紀初，有頂區段長約400公尺。","濟州偶來第6號路線直接穿過市場。","名產包括漢拏峰橘、黑豬肉、五味子糕與鮑魚。","許多攤位現點現做，可當場食用。"],"travelTips":["下午四點到七點之間來，熱食攤位開得最齊。","漢拏峰橘適合帶回家，有些攤位可裝箱寄送。","市場中央設有共用的用餐座位。"],"bestTime":"全年；橘子以12月至2月最好","visitDuration":"1.5小時","ticket":"","openingHours":"全年營業，多數攤位約07:00–21:00，但各家時間不一","galleryCaptions":["市場裡的漢拏峰橘攤"]}}', 'kr');
INSERT OR REPLACE INTO destinations (id, slug, province_slug, name, name_en, type, lng, lat, summary, story, facts, travel_tips, best_time, visit_duration, ticket, opening_hours, badges, tags, gallery, nearby, featured, source_url, verified_at, i18n, country) VALUES ('jeju-olle-trail', 'jeju-olle-trail', 'jeju', 'Đường mòn Jeju Olle', 'Jeju Olle Trail', 'park', 126.5695, 33.2415, 'Bốn trăm hai mươi cây số đường mòn đi bộ vòng quanh đảo, chia thành hai mươi bảy chặng ven biển.', 'Năm 2007, một nhà báo người Jeju nghỉ việc sau hơn hai mươi năm làm nghề, đi bộ đường Camino ở Tây Ban Nha, rồi về quê tự mở một tuyến đường mòn cho hòn đảo của mình. ''Olle'' trong tiếng Jeju là con ngõ nhỏ dẫn từ đường cái vào cửa nhà — ý là đường mòn này dẫn bạn về nhà. Hai mươi bảy chặng nối nhau thành vòng khép kín quanh đảo, tổng cộng hơn bốn trăm cây số, đi qua bờ đá đen, ruộng quýt, làng chài, rừng oreum và cả sân bay. Chặng số 7 từ Oedolgae dọc bờ nam là chặng được đi nhiều nhất; mỗi chặng mất bốn đến sáu tiếng và được đánh dấu bằng ruy băng xanh cam cùng những chú ngựa lùn bằng gỗ.', '["Gồm 27 chặng với tổng chiều dài khoảng 425 km quanh đảo.","Tuyến đầu tiên mở năm 2007, lấy cảm hứng từ đường Camino de Santiago.","''Olle'' trong phương ngữ Jeju nghĩa là con ngõ dẫn vào nhà.","Đường được đánh dấu bằng ruy băng xanh dương–cam và tượng ngựa gỗ Ganse."]', '["Chặng 7 (Oedolgae–Wolpyeong) là chặng phổ biến nhất, khoảng 5 giờ đi bộ.","Mua hộ chiếu Olle ở trung tâm để đóng dấu từng chặng.","Mùa hè rất nắng và ít bóng râm — đi sớm và mang đủ nước."]', 'Tháng 3–6 và 9–11', '4–6 giờ mỗi chặng', '', 'Cả ngày (nên đi ban ngày)', '["verified","trending"]', '["đi bộ đường dài","bờ biển","Olle","trekking"]', '[{"seed":"jeju-olle-trail","caption":"Ruy băng dẫn đường trên chặng Olle ven biển","ratio":"16/9"}]', '["seogwipo-olle-market","sanbangsan"]', 1, 'https://english.visitkorea.or.kr/', '2026-08-05', '{"en":{"name":"Jeju Olle Trail","summary":"Four hundred and twenty-five kilometres of walking trail around the island, in twenty-seven coastal stages.","story":"In 2007 a Jeju-born journalist left the profession after more than twenty years, walked the Camino in Spain, then came home and laid out a trail for her own island. ''Olle'' in the Jeju dialect is the small lane that leads from the road to your front door — the implication being that this path leads you home. Twenty-seven stages link into a closed loop around the island, more than four hundred kilometres in total, past black rock shores, tangerine groves, fishing villages, oreum cones and even the airport. Stage 7 along the south coast from Oedolgae is the most walked; each stage takes four to six hours and is marked with blue-and-orange ribbons and small wooden ponies.","facts":["27 stages totalling about 425km around the island.","The first route opened in 2007, inspired by the Camino de Santiago.","''Olle'' in the Jeju dialect means the lane leading to a house.","The route is marked with blue-and-orange ribbons and Ganse wooden pony figures."],"travelTips":["Stage 7 (Oedolgae–Wolpyeong) is the most popular, about five hours'' walking.","Buy an Olle passport at the centre and stamp each stage.","Summer is hot with little shade — start early and carry plenty of water."],"bestTime":"March–June and September–November","visitDuration":"4–6 hours per stage","ticket":"","openingHours":"Open all day (walk in daylight)","galleryCaptions":["Trail ribbons on a coastal Olle stage"]},"ko":{"name":"제주올레길","summary":"섬을 한 바퀴 도는 425km의 도보길. 해안을 따라 27개 코스로 나뉜다.","story":"2007년, 제주에서 태어난 한 기자가 이십 년 넘게 해 온 일을 그만두고 스페인의 카미노를 걸은 뒤, 고향으로 돌아와 자기 섬에 길을 냈다. 제주말 ''올레''는 큰길에서 집 대문까지 이어지는 좁은 골목을 뜻한다. 이 길이 당신을 집으로 데려간다는 뜻이다. 스물일곱 개 코스가 이어져 섬을 도는 원을 이루고, 모두 합쳐 400km가 넘는다. 검은 바위 해안과 감귤밭, 어촌, 오름, 심지어 공항 옆도 지난다. 외돌개에서 시작하는 남쪽 해안의 7코스가 가장 많이 걸리며, 코스마다 네 시간에서 여섯 시간이 걸리고 파란색과 주황색 리본, 그리고 작은 나무 조랑말로 표시된다.","facts":["27개 코스, 섬을 도는 총 길이 약 425km다.","첫 코스는 2007년 카미노 데 산티아고에서 영감을 받아 열렸다.","제주말 ''올레''는 집으로 드는 좁은 골목을 뜻한다.","파란색·주황색 리본과 나무 조랑말 간세로 길을 표시한다."],"travelTips":["7코스(외돌개~월평)가 가장 인기 있고 약 다섯 시간 걸린다.","안내센터에서 올레 패스포트를 사서 코스마다 도장을 찍자.","여름은 덥고 그늘이 적다. 일찍 출발하고 물을 넉넉히 챙기자."],"bestTime":"3~6월, 9~11월","visitDuration":"코스당 4~6시간","ticket":"","openingHours":"상시(낮에 걷기를 권함)","galleryCaptions":["해안 올레 코스의 길 표시 리본"]},"ja":{"name":"済州オルレ","summary":"島を一周する425kmの歩く道。海岸沿いに27のコースへ分かれる。","story":"2007年、済州生まれの記者が二十年以上続けた仕事を辞め、スペインのカミノを歩いたのち、故郷へ戻って自分の島に道を引いた。済州の言葉「オルレ」は、大通りから家の門へ続く細い路地を指す。この道があなたを家へ連れて行く、という含みだ。二十七のコースがつながって島を回る環になり、合わせて四百キロを超える。黒い岩の海岸、みかん畑、漁村、オルム、そして空港の脇まで通る。外突介から始まる南岸の7コースが最も歩かれ、コースごとに四〜六時間かかり、青と橙のリボンと小さな木の馬で示される。","facts":["27コース、島を回る総延長は約425km。","最初のコースは2007年、カミノ・デ・サンティアゴに着想を得て開かれた。","済州の方言「オルレ」は家へ続く路地を意味する。","青と橙のリボン、そして木馬ガンセで道が示される。"],"travelTips":["7コース（外突介〜月坪）が最も人気で、歩行は約5時間。","案内センターでオルレパスポートを買い、コースごとに押印しよう。","夏は暑く日陰が少ない。早く出発し、水を多めに持とう。"],"bestTime":"3〜6月、9〜11月","visitDuration":"1コースあたり4〜6時間","ticket":"","openingHours":"終日（日中に歩くのがよい）","galleryCaptions":["海岸のオルレコースの道しるべリボン"]},"zh":{"name":"濟州偶來小路","summary":"環島四百二十五公里的步道，沿海岸分成二十七段。","story":"2007年，一位在濟州出生的記者辭去做了二十多年的工作，走完西班牙的朝聖之路後返鄉，為自己的島鋪出一條步道。濟州方言裡的「偶來」，指的是從大路通往自家門口的那條小巷——言下之意，這條路會帶你回家。二十七段串成環島的一圈，總長超過四百公里，行經黑岩海岸、橘子園、漁村、火山丘，甚至機場旁邊。自外突介出發、沿南岸的第7段最多人走；每一段需四到六小時，路上以藍橘相間的絲帶與小木馬指路。","facts":["共27段，環島總長約425公里。","第一條路線於2007年開通，靈感來自聖雅各朝聖之路。","濟州方言中「偶來」意為通往住家的小巷。","路線以藍橘絲帶與「Ganse」木馬標記。"],"travelTips":["第7段（外突介至月坪）最受歡迎，步行約五小時。","可在服務中心買一本偶來護照，每段蓋章留念。","夏天酷熱且缺乏遮蔭，請早點出發並多帶飲水。"],"bestTime":"3至6月與9至11月","visitDuration":"每段4至6小時","ticket":"","openingHours":"全日開放（建議白天行走）","galleryCaptions":["海岸偶來路段上的指路絲帶"]}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-kimchi-jjigae', 'kr-kimchi-jjigae', 'Canh kimchi (kimchi-jjigae)', 'Kimchi jjigae', '🍲', 'Nồi canh kimchi chua cay sôi lục bục với thịt heo và đậu phụ — bữa cơm nhà quen thuộc nhất Hàn Quốc.', 'Kimchi càng chua càng nấu canh ngon, nên món này sinh ra từ việc tận dụng kimchi cũ. Thịt ba chỉ xào cho ra mỡ, kimchi vào xào tiếp cho thấm, rồi chan nước, thả đậu phụ và hành. Ở quán, nồi canh được dọn ra khi còn sôi trên bếp cồn, ăn với cơm trắng và vài món phụ.', 'seoul', '["seoul","gyeonggi"]', '["Kimchi chua","Thịt ba chỉ","Đậu phụ","Hành lá","Bột ớt gochugaru"]', 'Chua, cay, đậm đà', 'Bữa trưa hoặc tối', '["spicy","rice"]', 1, '{"en":{"name":"Kimchi jjigae","summary":"A bubbling pot of sour kimchi with pork and tofu — the most familiar home meal in Korea.","story":"The sourer the kimchi, the better the stew, so this dish was born from using up old kimchi. Pork belly is rendered, the kimchi fried in the fat, then water, tofu and spring onion go in. At restaurants it arrives still boiling on a portable burner, with rice and a few side dishes.","ingredients":["Sour kimchi","Pork belly","Tofu","Spring onion","Gochugaru chilli flakes"],"flavor":"Sour, spicy, deeply savoury","bestTime":"Lunch or dinner"},"ko":{"name":"김치찌개","summary":"신 김치와 돼지고기, 두부가 끓는 냄비. 한국에서 가장 익숙한 집밥이다.","story":"김치는 시어질수록 찌개가 맛있어 묵은지를 쓰는 데서 시작된 음식이다. 삼겹살에서 기름을 내고 김치를 볶아 물을 붓고 두부와 파를 넣는다. 식당에서는 휴대용 버너 위에서 끓는 채로 나와 흰밥, 밑반찬과 함께 먹는다.","ingredients":["신 김치","삼겹살","두부","대파","고춧가루"],"flavor":"시고 맵고 깊다","bestTime":"점심 또는 저녁"},"ja":{"name":"キムチチゲ","summary":"酸っぱいキムチと豚肉、豆腐が煮立つ鍋。韓国で最も馴染みのある家庭の味。","story":"キムチは酸味が出るほどチゲに向くので、古漬けを使い切る料理として生まれた。豚バラから脂を出してキムチを炒め、水を注いで豆腐とネギを入れる。店では携帯コンロの上で煮えたまま出され、白飯と小皿のおかずが添えられる。","ingredients":["酸味の出たキムチ","豚バラ肉","豆腐","長ねぎ","粉唐辛子"],"flavor":"酸味と辛味、深いコク","bestTime":"昼または夕食"},"zh":{"name":"泡菜鍋","summary":"酸泡菜配豬肉與豆腐的滾燙鍋物，韓國最家常的一餐。","story":"泡菜越酸越適合煮鍋，這道菜正是為了用掉老泡菜而生。先煸出五花肉的油，再下泡菜同炒，加水後放豆腐與蔥。餐廳端上桌時仍在卡式爐上滾著，配白飯與幾樣小菜。","ingredients":["酸泡菜","五花肉","豆腐","青蔥","辣椒粉"],"flavor":"酸辣而濃郁","bestTime":"午餐或晚餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-samgyetang', 'kr-samgyetang', 'Gà hầm sâm (samgyetang)', 'Samgyetang', '🍗', 'Gà tơ nhồi gạo nếp, sâm và táo tàu hầm trong nồi đá — món ăn của những ngày nóng nhất năm.', 'Người Hàn ăn đồ nóng để chống nóng: vào ba ngày ''sambok'' oi bức nhất mùa hè, các quán samgyetang xếp hàng dài. Con gà nhỏ được nhồi gạo nếp, sâm tươi, hạt dẻ, táo tàu rồi hầm tới khi thịt rơi khỏi xương và nước dùng ngả trắng sữa. Nêm bằng chút muối tiêu tự trộn ở bàn.', 'seoul', '["seoul"]', '["Gà tơ","Nhân sâm","Gạo nếp","Táo tàu","Tỏi"]', 'Thanh, béo nhẹ, thơm sâm', 'Mùa hè', '["rice"]', 1, '{"en":{"name":"Samgyetang (ginseng chicken soup)","summary":"A young chicken stuffed with glutinous rice, ginseng and jujube, simmered in a stone pot — food for the hottest days.","story":"Koreans eat hot food to beat the heat: on the three hottest ''sambok'' days of summer, samgyetang shops have queues down the street. The bird is stuffed with rice, fresh ginseng, chestnuts and jujube, then simmered until the meat falls off the bone and the broth turns milky. You season it yourself with salt and pepper at the table.","ingredients":["Young chicken","Ginseng","Glutinous rice","Jujube","Garlic"],"flavor":"Clean, lightly rich, fragrant with ginseng","bestTime":"Summer"},"ko":{"name":"삼계탕","summary":"찹쌀과 인삼, 대추를 채운 어린 닭을 뚝배기에 끓인 여름 보양식.","story":"한국에서는 더위를 뜨거운 음식으로 이긴다. 가장 더운 삼복에는 삼계탕집 앞에 줄이 길게 늘어선다. 영계 뱃속에 찹쌀과 수삼, 밤, 대추를 채워 살이 뼈에서 떨어질 때까지 고면 국물이 뽀얗게 우러난다. 상에서 소금과 후추로 직접 간을 맞춘다.","ingredients":["영계","인삼","찹쌀","대추","마늘"],"flavor":"담백하고 은은히 고소하며 인삼 향이 난다","bestTime":"여름"},"ja":{"name":"参鶏湯","summary":"もち米と高麗人参、なつめを詰めた若鶏を土鍋で煮た、真夏の滋養食。","story":"韓国では暑さを熱いもので乗り切る。最も暑い三伏の日には参鶏湯の店に行列ができる。若鶏の腹にもち米、生の人参、栗、なつめを詰め、肉が骨から離れ、汁が乳白色になるまで煮る。味付けは卓上の塩と胡椒で自分で行う。","ingredients":["若鶏","高麗人参","もち米","なつめ","にんにく"],"flavor":"澄んでいて軽くコクがあり、人参が香る","bestTime":"夏"},"zh":{"name":"蔘雞湯","summary":"童子雞塞入糯米、人蔘與紅棗，以石鍋燉煮的酷暑補品。","story":"韓國人以熱制熱：一年最熱的三伏天，蔘雞湯店外會排起長隊。雞腹填入糯米、鮮人蔘、栗子與紅棗，燉到肉離骨、湯色乳白。上桌後自己以鹽和胡椒調味。","ingredients":["童子雞","人蔘","糯米","紅棗","大蒜"],"flavor":"清爽微醇，帶人蔘香","bestTime":"夏季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-tteokbokki', 'kr-tteokbokki', 'Bánh gạo cay (tteokbokki)', 'Tteokbokki', '🌶️', 'Thanh bánh gạo dai đẫm sốt ớt ngọt cay, món ăn đường phố quốc dân của Hàn Quốc.', 'Tteokbokki nguyên bản trong cung là món xào nước tương, không cay. Phiên bản sốt gochujang đỏ rực ra đời ở chợ Sindang những năm 1950 và lan ra cả nước. Bánh gạo nấu cùng chả cá, trứng luộc, hành, và người ta luôn gọi thêm đĩa chiên để nhúng vào sốt.', 'seoul', '["seoul","gyeonggi","incheon"]', '["Bánh gạo tteok","Tương ớt gochujang","Chả cá","Trứng luộc","Hành lá"]', 'Cay ngọt, dẻo dai', 'Chiều tối', '["street","spicy"]', 1, '{"en":{"name":"Tteokbokki (spicy rice cakes)","summary":"Chewy rice cake sticks in a sweet-hot chilli sauce — Korea''s national street food.","story":"The original palace version was stir-fried in soy sauce and wasn''t spicy at all. The red gochujang version appeared in Sindang market in the 1950s and spread across the country. The rice cakes cook with fish cake, boiled egg and spring onion, and everybody orders a plate of fried snacks to dip in the sauce.","ingredients":["Tteok rice cakes","Gochujang","Fish cake","Boiled egg","Spring onion"],"flavor":"Sweet-hot and chewy","bestTime":"Late afternoon and evening"},"ko":{"name":"떡볶이","summary":"쫄깃한 떡을 매콤달콤한 고추장 소스에 볶은 국민 분식.","story":"궁중 떡볶이는 간장에 볶아 맵지 않았다. 고추장 떡볶이는 1950년대 신당동에서 나와 전국으로 퍼졌다. 어묵과 삶은 달걀, 파를 함께 끓이고, 소스에 찍어 먹을 튀김은 늘 함께 주문한다.","ingredients":["떡","고추장","어묵","삶은 달걀","대파"],"flavor":"맵고 달며 쫄깃하다","bestTime":"오후와 저녁"},"ja":{"name":"トッポッキ","summary":"もちもちの餅を甘辛いコチュジャンだれで煮た、韓国の国民的屋台料理。","story":"宮中のトッポッキは醤油炒めで辛くなかった。赤いコチュジャン版は1950年代に新堂洞で生まれ全国へ広がった。餅は練り物やゆで卵、ねぎと一緒に煮え、たれに浸すための揚げ物は必ず一緒に頼む。","ingredients":["餅","コチュジャン","練り物","ゆで卵","長ねぎ"],"flavor":"甘辛く、もちもち","bestTime":"午後から夕方"},"zh":{"name":"辣炒年糕","summary":"彈牙年糕裹上甜辣醬，韓國的國民街頭小吃。","story":"宮廷版的炒年糕用醬油，並不辣。紅色辣椒醬版本於1950年代在新堂洞出現，隨即傳遍全國。年糕與魚板、水煮蛋和蔥同煮，人們一定會加點炸物來沾醬。","ingredients":["年糕","辣椒醬","魚板","水煮蛋","青蔥"],"flavor":"甜辣、Q彈","bestTime":"午後與傍晚"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-gimbap', 'kr-gimbap', 'Gimbap', 'Gimbap', '🍙', 'Cuộn cơm rong biển với trứng, cà rốt, củ cải muối — bữa trưa mang đi của mọi gia đình Hàn.', 'Gimbap gắn với những chuyến dã ngoại: mẹ dậy sớm cuộn cả chồng rồi cắt lát xếp hộp. Cơm trộn dầu mè và muối chứ không dùng giấm, nhân thay đổi tuỳ nhà — chả cá, thịt bò xào, trứng cuộn, rau chân vịt, củ cải vàng. Quán gimbap mở cả ngày và là chỗ ăn nhanh rẻ nhất Hàn Quốc.', 'seoul', '["seoul","gyeonggi"]', '["Cơm trộn dầu mè","Rong biển gim","Trứng cuộn","Củ cải muối","Cà rốt"]', 'Nhẹ, thơm dầu mè', 'Bữa trưa, mang đi', '["rice","street"]', 0, '{"en":{"name":"Gimbap","summary":"Seaweed rice rolls with egg, carrot and pickled radish — every family''s packed lunch.","story":"Gimbap belongs to day trips: mothers rise early, roll a stack and cut them into a box. The rice is seasoned with sesame oil and salt rather than vinegar, and the filling changes from house to house — fish cake, stir-fried beef, rolled egg, spinach, yellow pickled radish. Gimbap shops open all day and are the cheapest quick meal in Korea.","ingredients":["Rice with sesame oil","Gim seaweed","Rolled egg","Pickled radish","Carrot"],"flavor":"Light, fragrant with sesame","bestTime":"Lunch, or to take away"},"ko":{"name":"김밥","summary":"달걀과 당근, 단무지를 넣어 만 김밥. 모든 집의 도시락이다.","story":"김밥은 소풍의 음식이다. 어머니가 새벽에 일어나 한 줄씩 말아 썰어 담는다. 밥은 식초가 아니라 참기름과 소금으로 간하고, 속 재료는 집마다 다르다. 어묵, 소불고기, 달걀말이, 시금치, 노란 단무지. 김밥집은 하루 종일 열려 있고 한국에서 가장 싼 한 끼다.","ingredients":["참기름 밥","김","달걀말이","단무지","당근"],"flavor":"담백하고 참기름 향이 난다","bestTime":"점심 또는 도시락"},"ja":{"name":"キンパ","summary":"卵、にんじん、たくあんを巻いた海苔巻き。どの家庭の弁当にもある。","story":"キンパは遠足の食べ物だ。母が早起きして何本も巻き、切って弁当箱に詰める。ご飯は酢ではなくごま油と塩で味付けし、具は家ごとに違う。練り物、牛肉炒め、卵焼き、ほうれん草、黄色いたくあん。キンパ屋は一日中開いていて、韓国で最も安い一食だ。","ingredients":["ごま油のご飯","海苔","卵焼き","たくあん","にんじん"],"flavor":"軽やかでごまが香る","bestTime":"昼食、または持ち帰り"},"zh":{"name":"紫菜飯捲","summary":"包著蛋、紅蘿蔔與醃蘿蔔的海苔飯捲，每個家庭的便當。","story":"紫菜飯捲屬於郊遊：媽媽早起捲上一疊，切好裝盒。飯以麻油和鹽調味而非醋，餡料家家不同——魚板、炒牛肉、煎蛋捲、菠菜、黃色醃蘿蔔。飯捲店整天營業，是韓國最便宜的一餐。","ingredients":["麻油拌飯","海苔","煎蛋捲","醃蘿蔔","紅蘿蔔"],"flavor":"清淡而有麻油香","bestTime":"午餐或外帶"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-fried-chicken', 'kr-fried-chicken', 'Gà rán Hàn Quốc (chimaek)', 'Korean fried chicken', '🍺', 'Gà rán hai lần lớp vỏ mỏng giòn, ăn kèm bia — nghi thức tối thứ Sáu của người Hàn.', 'Chimaek ghép từ ''chicken'' và ''maekju'' (bia). Gà được rán hai lần cho vỏ giòn lâu, rồi hoặc để nguyên (huraideu) hoặc phủ sốt yangnyeom cay ngọt. Người ta gọi giao tận nơi ra bãi cỏ ven sông Hàn, hoặc ngồi quán tới khuya. Đây là món ăn khiến ngành gà rán Hàn Quốc lớn hơn cả McDonald''s toàn cầu về số cửa hàng.', 'seoul', '["seoul","incheon","gyeonggi","daegu"]', '["Gà","Bột chiên giòn","Sốt yangnyeom","Củ cải muối","Bia"]', 'Giòn, mặn ngọt, cay nhẹ', 'Tối', '["late-night","street"]', 1, '{"en":{"name":"Korean fried chicken (chimaek)","summary":"Double-fried chicken with a thin, crackling crust, eaten with beer — Korea''s Friday-night ritual.","story":"Chimaek joins ''chicken'' and ''maekju'' (beer). The bird is fried twice so the crust stays crisp, then either left plain or coated in sweet-spicy yangnyeom sauce. People have it delivered onto the grass beside the Han River, or sit in a shop until late. This is the dish that made Korea''s fried chicken chains outnumber McDonald''s worldwide.","ingredients":["Chicken","Frying batter","Yangnyeom sauce","Pickled radish","Beer"],"flavor":"Crisp, salty-sweet, gently spicy","bestTime":"Evening"},"ko":{"name":"치맥(한국식 치킨)","summary":"두 번 튀겨 얇고 바삭한 껍질에 맥주를 곁들이는, 금요일 밤의 의식.","story":"치맥은 치킨과 맥주를 합친 말이다. 두 번 튀겨 바삭함이 오래가고, 그대로 먹거나 매콤달콤한 양념을 입힌다. 한강 둔치로 배달시켜 잔디에서 먹거나 가게에서 밤늦게까지 앉아 있는다. 한국의 치킨 매장 수가 전 세계 맥도날드보다 많아진 이유다.","ingredients":["닭","튀김옷","양념소스","치킨무","맥주"],"flavor":"바삭하고 짭짤달콤하며 살짝 맵다","bestTime":"저녁"},"ja":{"name":"チメク（韓国式フライドチキン）","summary":"二度揚げの薄くパリッとした衣にビールを合わせる、金曜の夜の儀式。","story":"チメクはチキンとメクチュ（ビール）を合わせた言葉。二度揚げで衣のさくさくが長持ちし、そのままか、甘辛いヤンニョムだれをまとわせる。漢江の芝生まで配達させたり、店で夜遅くまで粘ったりする。韓国のチキン店舗数が世界のマクドナルドを上回った理由でもある。","ingredients":["鶏肉","揚げ衣","ヤンニョムだれ","たくあん","ビール"],"flavor":"さくさくで甘塩っぱく、ほのかに辛い","bestTime":"夜"},"zh":{"name":"韓式炸雞（雞啤）","summary":"二次油炸、外皮薄脆的炸雞配啤酒——韓國週五夜的儀式。","story":"「雞啤」由炸雞與啤酒組成。雞肉炸兩次以維持酥脆，之後或保持原味，或裹上甜辣醬。人們把它外送到漢江邊的草地上，或在店裡坐到深夜。正是這道菜讓韓國炸雞店的數量超過全球麥當勞。","ingredients":["雞肉","炸粉","甜辣醬","醃蘿蔔","啤酒"],"flavor":"酥脆鹹甜，微辣","bestTime":"夜晚"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-bossam', 'kr-bossam', 'Thịt luộc cuốn (bossam)', 'Bossam', '🥬', 'Thịt ba chỉ luộc thái lát cuốn lá cải thảo với kimchi củ cải và mắm tôm.', 'Bossam ra đời từ ngày muối kimchi (gimjang): cả nhà xúm vào muối cả trăm cây cải, và bữa trưa hôm đó là thịt luộc ăn với kimchi vừa trộn còn tươi. Thịt luộc cùng tương đậu, lá trà, quế nên không ngấy; cuốn cùng cải thảo, tỏi sống, ớt xanh và một chút mắm tôm mặn.', 'seoul', '["seoul","gyeonggi"]', '["Thịt ba chỉ","Cải thảo","Kimchi củ cải","Mắm tôm","Tỏi sống"]', 'Béo mềm, mặn tươi', 'Tối, mùa đông', '["rice"]', 0, '{"en":{"name":"Bossam (boiled pork wraps)","summary":"Sliced boiled pork belly wrapped in cabbage leaves with radish kimchi and salted shrimp.","story":"Bossam comes from gimjang day, when a household salts a hundred cabbages at once and lunch is boiled pork with the kimchi still fresh from the mixing bowl. The pork is simmered with soybean paste, tea leaves and cinnamon so it never feels heavy; you wrap it with cabbage, raw garlic, green chilli and a dab of salted shrimp.","ingredients":["Pork belly","Napa cabbage","Radish kimchi","Salted shrimp","Raw garlic"],"flavor":"Soft and rich, savoury and fresh","bestTime":"Winter evenings"},"ko":{"name":"보쌈","summary":"삶은 삼겹살을 배춧잎에 무김치, 새우젓과 함께 싸 먹는 음식.","story":"김장날에서 비롯됐다. 온 집이 배추 백 포기를 절이는 날, 점심은 삶은 고기에 갓 버무린 김치였다. 된장과 찻잎, 계피를 넣어 삶아 느끼하지 않고, 배추와 생마늘, 풋고추, 새우젓을 곁들여 싼다.","ingredients":["삼겹살","배추","무김치","새우젓","생마늘"],"flavor":"부드럽고 고소하며 짭짤하고 상큼하다","bestTime":"겨울 저녁"},"ja":{"name":"ポッサム","summary":"ゆでた豚バラを白菜で包み、大根キムチとアミの塩辛を添えて食べる。","story":"キムジャンの日に由来する。家じゅうで白菜を百株漬けるその日の昼食が、ゆで豚と和えたての生キムチだった。豚は味噌や茶葉、シナモンと一緒にゆでるので重くならない。白菜、生にんにく、青唐辛子、アミの塩辛を少し添えて包む。","ingredients":["豚バラ肉","白菜","大根キムチ","アミの塩辛","生にんにく"],"flavor":"やわらかくコクがあり、塩気と爽やかさ","bestTime":"冬の夜"},"zh":{"name":"菜包肉（bossam）","summary":"水煮五花肉切片，以白菜葉包上蘿蔔泡菜與蝦醬。","story":"菜包肉源自醃泡菜的日子：全家一次醃上百顆白菜，那天的午餐就是水煮肉配剛拌好的泡菜。豬肉以大醬、茶葉與肉桂同煮，因此不膩；包時配白菜、生蒜、青辣椒與一點蝦醬。","ingredients":["五花肉","大白菜","蘿蔔泡菜","蝦醬","生蒜"],"flavor":"軟嫩醇厚，鹹鮮清爽","bestTime":"冬夜"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-jjajangmyeon', 'kr-jjajangmyeon', 'Mì tương đen (jjajangmyeon)', 'Jjajangmyeon', '🍜', 'Mì trộn tương đen chunjang với thịt và hành tây — món Hoa sinh ra ở phố người Hoa Incheon.', 'Cuối thế kỷ 19, thương nhân Sơn Đông ở cảng Incheon pha tương đen với hành tây, thịt heo và mì Hàn để bán cho phu bến tàu. Món ăn lan ra cả nước và thành thứ người Hàn gọi giao tận nhà nhiều nhất. Ngày 14 tháng 4 — ''ngày đen'' — người độc thân rủ nhau ăn jjajangmyeon.', 'incheon', '["incheon","seoul"]', '["Mì tươi","Tương đen chunjang","Thịt heo","Hành tây","Dưa chuột thái sợi"]', 'Mặn ngọt, béo ngậy', 'Bữa trưa', '["noodle"]', 1, '{"en":{"name":"Jjajangmyeon (black bean noodles)","summary":"Noodles in black chunjang sauce with pork and onion — a Chinese dish born in Incheon''s Chinatown.","story":"In the late 19th century, Shandong merchants at Incheon port mixed black bean paste with onion, pork and Korean noodles to feed dock workers. The dish spread nationwide and became the thing Koreans order for delivery more than anything else. On 14 April — ''Black Day'' — single people gather to eat it together.","ingredients":["Fresh noodles","Chunjang black bean paste","Pork","Onion","Shredded cucumber"],"flavor":"Salty-sweet and rich","bestTime":"Lunch"},"ko":{"name":"짜장면","summary":"춘장에 돼지고기와 양파를 볶아 비빈 면. 인천 차이나타운에서 태어났다.","story":"19세기 말 인천항의 산둥 상인들이 춘장에 양파와 돼지고기, 한국 면을 섞어 부두 노동자에게 팔았다. 이 음식은 전국으로 퍼져 가장 많이 배달되는 메뉴가 되었고, 4월 14일 ''블랙데이''에는 솔로들이 모여 먹는다.","ingredients":["생면","춘장","돼지고기","양파","채 썬 오이"],"flavor":"짭짤달콤하고 고소하다","bestTime":"점심"},"ja":{"name":"ジャージャー麺","summary":"黒い春醤に豚肉と玉ねぎを合わせた麺。仁川チャイナタウン生まれ。","story":"19世紀末、仁川港の山東商人が黒い豆味噌に玉ねぎと豚肉、韓国の麺を合わせて港湾労働者に売った。やがて全国の味となり、韓国で最も出前される一皿になった。4月14日「ブラックデー」には独り身の人々が集まってこれを食べる。","ingredients":["生麺","春醤","豚肉","玉ねぎ","きゅうりの千切り"],"flavor":"甘塩っぱくコクがある","bestTime":"昼食"},"zh":{"name":"炸醬麵","summary":"黑春醬拌豬肉與洋蔥的麵條，這道中式料理誕生於仁川中華街。","story":"十九世紀末，仁川港的山東商人把黑豆醬拌上洋蔥、豬肉與韓國麵條，賣給碼頭工人。這道菜傳遍全國，成了韓國外送最多的一餐。4月14日「黑色情人節」，單身的人會聚在一起吃它。","ingredients":["生麵","春醬","豬肉","洋蔥","小黃瓜絲"],"flavor":"鹹甜濃郁","bestTime":"午餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-suwon-galbi', 'kr-suwon-galbi', 'Sườn nướng Suwon (galbi)', 'Suwon Galbi', '🥩', 'Sườn bò tảng lớn ướp nhạt, nướng than để vị thịt tự nói — kiểu galbi riêng của Suwon.', 'Suwon từng có chợ bò lớn nhất vùng thủ đô do vua Jeongjo lập ra để nuôi thành Hwaseong. Galbi ở đây ướp nhạt hơn nơi khác, miếng sườn to bản, chỉ nêm muối là chính, nướng than cho cháy cạnh. Ăn kèm canh sườn và cơm hấp trong nồi đá.', 'gyeonggi', '["gyeonggi"]', '["Sườn bò","Muối","Dầu mè","Hành lá","Nước tương chấm"]', 'Ngọt thịt, khói than', 'Tối', '[]', 1, '{"en":{"name":"Suwon galbi (grilled beef ribs)","summary":"Large-cut beef ribs, lightly seasoned and charcoal-grilled so the meat speaks for itself.","story":"Suwon once had the largest cattle market in the capital region, established by King Jeongjo to supply Hwaseong fortress. Galbi here is marinated more lightly than elsewhere, cut in big pieces, seasoned mainly with salt and grilled over charcoal until the edges char. It comes with rib soup and rice steamed in a stone pot.","ingredients":["Beef short ribs","Salt","Sesame oil","Spring onion","Soy dipping sauce"],"flavor":"Sweet with beef, smoky from charcoal","bestTime":"Evening"},"ko":{"name":"수원 왕갈비","summary":"크게 자른 소갈비를 연하게 양념해 숯불에 구워 고기 맛을 살린다.","story":"수원에는 정조가 화성을 위해 세운 수도권 최대의 우시장이 있었다. 이곳 갈비는 다른 지역보다 양념이 옅고 크게 썰어 주로 소금으로 간해 숯불에 굽는다. 갈비탕과 돌솥밥이 함께 나온다.","ingredients":["소갈비","소금","참기름","대파","간장 양념장"],"flavor":"고기 맛이 달고 숯향이 난다","bestTime":"저녁"},"ja":{"name":"水原カルビ","summary":"大ぶりの牛カルビを薄味に漬け、炭火で焼いて肉の味を生かす。","story":"水原には、正祖が華城のために設けた首都圏最大の牛市場があった。ここのカルビは他所より漬けだれが薄く、大きく切って主に塩で味を付け、炭火で縁が焦げるまで焼く。カルビタンと石鍋ご飯が一緒に出る。","ingredients":["牛カルビ","塩","ごま油","長ねぎ","つけだれ"],"flavor":"肉の甘みと炭の香り","bestTime":"夜"},"zh":{"name":"水原排骨","summary":"大塊牛小排只做淡醃，以炭火燒烤，讓肉味自己說話。","story":"水原曾有首都圈最大的牛市，是正祖為供養華城而設。這裡的排骨醃得比別處淡，切得大塊，主要以鹽調味，炭火烤到邊緣焦香。上桌時附排骨湯與石鍋飯。","ingredients":["牛小排","鹽","麻油","青蔥","醬油沾醬"],"flavor":"肉甜且帶炭香","bestTime":"晚餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-dakgalbi', 'kr-dakgalbi', 'Gà xào cay Chuncheon (dakgalbi)', 'Chuncheon Dakgalbi', '🍳', 'Gà xào tương ớt trên chảo gang lớn với bắp cải, khoai lang và bánh gạo — kết thúc bằng cơm rang.', 'Ra đời ở Chuncheon những năm 1960 như món nhậu rẻ cho lính và sinh viên, dakgalbi được xào ngay giữa bàn trên chảo gang. Khi gần hết, người ta xin thêm cơm và rong biển để rang ngay trên phần sốt còn lại — phần ngon nhất bữa ăn. Cả một con phố ở Chuncheon chỉ bán món này.', 'gangwon', '["gangwon"]', '["Thịt gà","Tương ớt gochujang","Bắp cải","Khoai lang","Bánh gạo"]', 'Cay ngọt, đậm', 'Tối', '["spicy"]', 1, '{"en":{"name":"Chuncheon dakgalbi","summary":"Chicken stir-fried in chilli paste on a great iron pan with cabbage, sweet potato and rice cake — finished with fried rice.","story":"Born in Chuncheon in the 1960s as a cheap dish for soldiers and students, dakgalbi is cooked on a cast-iron pan in the middle of your table. When it is nearly finished you ask for rice and seaweed to fry in what remains of the sauce — the best part of the meal. A whole street in Chuncheon sells nothing else.","ingredients":["Chicken","Gochujang","Cabbage","Sweet potato","Rice cake"],"flavor":"Sweet-hot and full-bodied","bestTime":"Evening"},"ko":{"name":"춘천닭갈비","summary":"커다란 무쇠판에 고추장 양념 닭과 양배추, 고구마, 떡을 볶고 마지막엔 볶음밥.","story":"1960년대 춘천에서 군인과 학생을 위한 값싼 안주로 시작해, 지금은 식탁 한가운데 무쇠판에서 볶아 먹는다. 거의 다 먹을 즈음 밥과 김을 넣어 남은 양념에 볶는데, 그게 이 식사의 백미다. 춘천에는 이 한 가지만 파는 거리가 있다.","ingredients":["닭고기","고추장","양배추","고구마","떡"],"flavor":"맵고 달며 진하다","bestTime":"저녁"},"ja":{"name":"春川タッカルビ","summary":"大きな鉄板でコチュジャンだれの鶏とキャベツ、さつまいも、餅を炒め、締めは炒飯。","story":"1960年代の春川で、兵士や学生向けの安いつまみとして生まれた。卓上の鉄鍋で炒めて食べ、残りが少なくなったらご飯と海苔を入れてたれごと炒める。それが一番のごちそうだ。春川にはこの一品しか売らない通りがある。","ingredients":["鶏肉","コチュジャン","キャベツ","さつまいも","餅"],"flavor":"甘辛く濃厚","bestTime":"夜"},"zh":{"name":"春川辣炒雞排","summary":"大鐵板上以辣椒醬炒雞肉、高麗菜、地瓜與年糕，最後以炒飯收尾。","story":"1960年代誕生於春川，是給士兵與學生的便宜下酒菜，就在桌子中央的鑄鐵鍋上邊炒邊吃。快吃完時要一份飯和海苔，用剩下的醬汁炒——那才是整餐的重點。春川有一整條街只賣這一味。","ingredients":["雞肉","辣椒醬","高麗菜","地瓜","年糕"],"flavor":"甜辣濃厚","bestTime":"晚餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-makguksu', 'kr-makguksu', 'Mì kiều mạch lạnh (makguksu)', 'Chuncheon Makguksu', '🥶', 'Mì kiều mạch trộn lạnh với kimchi, dưa chuột và nước dùng mát — món hè của Gangwon.', 'Gangwon nhiều núi, trồng kiều mạch tốt hơn trồng lúa, nên mì kiều mạch là món ăn thường ngày. Makguksu nghĩa là ''mì làm vội'': sợi mì luộc xả nước lạnh, trộn tương ớt hoặc chan nước dùng lạnh, thêm kimchi, dưa chuột, trứng luộc. Ăn cùng dakgalbi là cặp đôi kinh điển ở Chuncheon.', 'gangwon', '["gangwon"]', '["Mì kiều mạch","Kimchi","Dưa chuột","Trứng luộc","Nước dùng lạnh"]', 'Mát, chua nhẹ, cay dịu', 'Mùa hè', '["noodle"]', 0, '{"en":{"name":"Makguksu (cold buckwheat noodles)","summary":"Buckwheat noodles tossed cold with kimchi and cucumber in chilled broth — Gangwon''s summer dish.","story":"Gangwon is mountainous and grows buckwheat better than rice, so buckwheat noodles are everyday food. Makguksu means ''noodles made in a hurry'': boiled, rinsed cold, then either tossed with chilli paste or served in chilled broth with kimchi, cucumber and boiled egg. Paired with dakgalbi it is the classic Chuncheon meal.","ingredients":["Buckwheat noodles","Kimchi","Cucumber","Boiled egg","Chilled broth"],"flavor":"Cool, gently sour and spicy","bestTime":"Summer"},"ko":{"name":"막국수","summary":"메밀국수를 김치와 오이를 넣어 차게 비비거나 말아 먹는 강원의 여름 음식.","story":"강원은 산이 많아 벼보다 메밀이 잘 자라 메밀국수가 일상 음식이었다. 막국수는 ''막 만든 국수''라는 뜻으로, 삶아 찬물에 헹궈 고추장에 비비거나 찬 육수에 말고 김치와 오이, 달걀을 얹는다. 닭갈비와 함께 먹는 것이 춘천의 정석이다.","ingredients":["메밀국수","김치","오이","삶은 달걀","찬 육수"],"flavor":"시원하고 새콤하며 매콤하다","bestTime":"여름"},"ja":{"name":"マックッス（そば冷麺）","summary":"そば麺をキムチときゅうりで冷たく和える、江原の夏の一皿。","story":"江原は山が多く、米より蕎麦がよく育つので蕎麦麺は日常食だ。マックッスは「さっと作る麺」の意味。茹でて冷水で締め、コチュジャンで和えるか冷たい出汁を張り、キムチ、きゅうり、ゆで卵をのせる。タッカルビと合わせるのが春川の定番。","ingredients":["そば麺","キムチ","きゅうり","ゆで卵","冷たい出汁"],"flavor":"冷たく、ほのかに酸味と辛味","bestTime":"夏"},"zh":{"name":"蕎麥涼麵（makguksu）","summary":"蕎麥麵以泡菜與小黃瓜冷拌或加冰湯，江原的夏日一碗。","story":"江原多山，蕎麥比稻更好種，蕎麥麵因此成為日常。makguksu意為「隨手做的麵」：煮好以冷水沖過，或拌辣椒醬，或注入冰涼高湯，配泡菜、小黃瓜與水煮蛋。與辣炒雞排同吃是春川的經典組合。","ingredients":["蕎麥麵","泡菜","小黃瓜","水煮蛋","冰高湯"],"flavor":"涼爽微酸帶辣","bestTime":"夏季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-ojingeo-sundae', 'kr-ojingeo-sundae', 'Mực nhồi Sokcho (ojingeo-sundae)', 'Sokcho Squid Sundae', '🦑', 'Mực tươi nhồi rau củ và miến, hấp rồi thái khoanh — đặc sản chợ cá Sokcho.', 'Ở bờ biển Gangwon, mực nhiều đến mức người ta nghĩ ra cách nhồi thay vì chỉ nướng: thân mực nhồi miến, đậu phụ, rau và chính râu mực băm nhỏ, hấp chín rồi nhúng trứng chiên áp chảo. Cắt khoanh ra thấy từng vòng nhân đẹp mắt. Chợ cá Sokcho bán món này cùng bánh cá và cua tuyết.', 'gangwon', '["gangwon"]', '["Mực tươi","Miến","Đậu phụ","Rau hẹ","Trứng"]', 'Ngọt mực, mềm ẩm', 'Quanh năm', '["seafood"]', 0, '{"en":{"name":"Sokcho squid sundae","summary":"Fresh squid stuffed with vegetables and glass noodles, steamed and sliced — a Sokcho fish-market speciality.","story":"On the Gangwon coast squid is so plentiful that people invented something better than grilling it: the body is stuffed with glass noodles, tofu, vegetables and the chopped tentacles, steamed, then dipped in egg and pan-fried. Sliced into rounds, each piece shows a pretty ring of filling. Sokcho''s fish market sells it alongside fish cakes and snow crab.","ingredients":["Fresh squid","Glass noodles","Tofu","Garlic chives","Egg"],"flavor":"Sweet with squid, soft and moist","bestTime":"Year-round"},"ko":{"name":"속초 오징어순대","summary":"오징어 몸통에 채소와 당면을 채워 쪄서 썰어 낸 속초 어시장의 명물.","story":"강원 해안은 오징어가 많아 굽는 것 말고 다른 방법을 찾아냈다. 몸통에 당면과 두부, 채소, 다진 다리를 채워 쪄낸 뒤 달걀물을 입혀 지진다. 썰면 속이 예쁜 무늬로 드러난다. 속초 어시장에서는 어묵, 대게와 함께 판다.","ingredients":["생오징어","당면","두부","부추","달걀"],"flavor":"오징어가 달고 촉촉하며 부드럽다","bestTime":"연중"},"ja":{"name":"束草イカスンデ","summary":"イカの胴に野菜と春雨を詰めて蒸し、輪切りにした束草の魚市場の名物。","story":"江原の海岸ではイカが豊富で、焼く以外の方法が生まれた。胴に春雨、豆腐、野菜、刻んだ足を詰めて蒸し、卵液をまとわせて焼く。切ると具の輪が美しく現れる。束草の魚市場では、練り物やズワイガニと並んで売られる。","ingredients":["生イカ","春雨","豆腐","にら","卵"],"flavor":"イカが甘く、しっとり柔らかい","bestTime":"通年"},"zh":{"name":"束草魷魚米腸","summary":"新鮮魷魚身填入蔬菜與冬粉蒸熟後切片，束草魚市場的名物。","story":"江原海岸魷魚極多，於是人們想出比燒烤更好的辦法：把冬粉、豆腐、蔬菜與切碎的魷魚腳塞進魷魚身，蒸熟後沾蛋液煎香。切成圓片，每一片都露出漂亮的餡心。束草魚市場把它與魚板、雪蟹一起賣。","ingredients":["鮮魷魚","冬粉","豆腐","韭菜","雞蛋"],"flavor":"魷魚鮮甜，柔軟濕潤","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-gamja-ongsimi', 'kr-gamja-ongsimi', 'Canh bánh khoai tây (gamja ongsimi)', 'Potato Ongsimi Soup', '🥔', 'Viên bột khoai tây dai thả trong canh rau — món ăn no của vùng núi Gangwon.', 'Khoai tây Gangwon nổi tiếng cả nước, và ở vùng núi người ta mài khoai lấy tinh bột rồi vo thành viên thả vào canh. Viên ongsimi dai và trong, nấu với bí ngòi, hành và cá cơm khô. Đây là món ăn của những mùa giáp hạt, nay thành đặc sản mà khách phải tìm quán chuyên mới có.', 'gangwon', '["gangwon"]', '["Khoai tây","Bí ngòi","Cá cơm khô","Hành lá","Rong biển"]', 'Thanh, dai mềm', 'Mùa đông', '["vegetarian-option"]', 0, '{"en":{"name":"Potato ongsimi soup","summary":"Chewy potato-starch dumplings in a vegetable broth — filling food from the Gangwon mountains.","story":"Gangwon potatoes are famous across Korea, and in the mountains people grate them for starch and roll it into balls dropped in soup. The ongsimi are chewy and translucent, cooked with courgette, onion and dried anchovy. This was food for the lean season; now it is a speciality you have to find a specialist shop to eat.","ingredients":["Potato","Courgette","Dried anchovy","Spring onion","Seaweed"],"flavor":"Clean broth, chewy and soft","bestTime":"Winter"},"ko":{"name":"감자옹심이","summary":"감자 전분을 빚어 넣은 쫄깃한 옹심이 국. 강원 산간의 든든한 한 끼다.","story":"강원 감자는 전국이 알아준다. 산간에서는 감자를 갈아 전분을 내고 동그랗게 빚어 국에 넣었다. 애호박과 멸치로 국물을 내면 옹심이가 투명하고 쫄깃하다. 보릿고개의 음식이 이제는 전문점을 찾아야 먹는 별미가 되었다.","ingredients":["감자","애호박","마른 멸치","대파","김"],"flavor":"국물이 담백하고 쫄깃하다","bestTime":"겨울"},"ja":{"name":"じゃがいもオンシミ汁","summary":"じゃがいものでんぷんを丸めた団子入りの汁。江原の山間の腹持ちの良い一杯。","story":"江原のじゃがいもは全国的に有名で、山間ではすりおろしてでんぷんを取り、丸めて汁に落とす。オンシミは半透明でもちもち。ズッキーニ、玉ねぎ、煮干しで煮る。端境期の食べ物が、今では専門店を探さないと食べられない名物になった。","ingredients":["じゃがいも","ズッキーニ","煮干し","長ねぎ","海苔"],"flavor":"すっきりした汁ともちもちの食感","bestTime":"冬"},"zh":{"name":"馬鈴薯麵疙瘩湯","summary":"馬鈴薯澱粉搓成的Q彈丸子加蔬菜湯，江原山區的飽足一餐。","story":"江原馬鈴薯全國聞名，山裡的人把它磨出澱粉搓成丸子下湯。ongsimi半透明而彈牙，與櫛瓜、洋蔥和小魚乾同煮。這原是青黃不接時的食物，如今得找專門店才吃得到。","ingredients":["馬鈴薯","櫛瓜","小魚乾","青蔥","海苔"],"flavor":"湯頭清爽，口感彈軟","bestTime":"冬季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-sungsimdang-bread', 'kr-sungsimdang-bread', 'Bánh mì Sungsimdang (Daejeon)', 'Sungsimdang Bread', '🥐', 'Bánh mì chiên nhân đậu đỏ và bánh vỏ giòn nhân kem — lý do người ta xuống tàu ở Daejeon.', 'Tiệm bánh mở năm 1956 bằng một lò hấp thuê lại, nay là biểu tượng khiến Daejeon được gọi là ''thành phố bánh mì''. Hai món phải thử: twigim-soboro — bánh nhân đậu đỏ chiên phủ lớp vụn giòn — và bánh vỏ nhiều lớp nhân kem tươi. Hàng người xếp vòng ra cả vỉa hè là chuyện bình thường.', 'daejeon', '["daejeon"]', '["Bột mì","Nhân đậu đỏ","Kem tươi","Vụn bánh soboro"]', 'Ngọt, giòn ngoài mềm trong', 'Sáng', '["dessert"]', 1, '{"en":{"name":"Sungsimdang bread (Daejeon)","summary":"A deep-fried red bean bun and a crisp cream pastry — the reason people get off the train at Daejeon.","story":"The bakery opened in 1956 with a rented steamer and is now the symbol that earned Daejeon the nickname ''bread city''. Two things to try: twigim-soboro, a red bean bun deep-fried and coated in crumbs, and the layered pastry filled with fresh cream. Queues stretching onto the pavement are normal.","ingredients":["Wheat flour","Red bean paste","Fresh cream","Soboro crumb"],"flavor":"Sweet, crisp outside and soft within","bestTime":"Morning"},"ko":{"name":"성심당 빵(대전)","summary":"튀김소보로와 생크림빵. 사람들이 대전역에 내리는 이유다.","story":"1956년 찐빵 기계 하나로 시작한 빵집이 지금은 대전을 ''빵의 도시''로 만든 상징이다. 튀김소보로는 팥소를 넣어 튀긴 뒤 소보로를 입혔고, 결이 많은 빵에는 생크림이 가득하다. 인도까지 늘어선 줄은 흔한 풍경이다.","ingredients":["밀가루","팥소","생크림","소보로"],"flavor":"달고 겉은 바삭 속은 부드럽다","bestTime":"오전"},"ja":{"name":"聖心堂のパン（大田）","summary":"揚げあんパンとクリームパン。人々が大田で途中下車する理由。","story":"1956年に借り物の蒸し器一台で始まったパン屋は、今や大田を「パンの街」にした象徴だ。二つの名物がある。あんを包んで揚げ、そぼろをまとわせたトゥィギムソボロと、幾層にも重なった生地に生クリームを詰めたパン。歩道まで伸びる行列は日常の風景だ。","ingredients":["小麦粉","こしあん","生クリーム","そぼろ"],"flavor":"甘く、外はさくさく中はふんわり","bestTime":"午前"},"zh":{"name":"聖心堂麵包（大田）","summary":"油炸紅豆麵包與奶油夾心酥皮——人們在大田下車的理由。","story":"1956年以一台租來的蒸籠起家的麵包店，如今是讓大田被稱為「麵包之城」的象徵。兩樣必嚐：包著紅豆餡油炸後裹上酥粒的튀김소보로，以及層層酥皮夾滿鮮奶油的麵包。隊伍排到人行道上是常態。","ingredients":["麵粉","紅豆餡","鮮奶油","酥粒"],"flavor":"香甜，外酥內軟","bestTime":"上午"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-daejeon-kalguksu', 'kr-daejeon-kalguksu', 'Mì dao Daejeon (kalguksu)', 'Daejeon Kalguksu', '🍜', 'Mì cắt dao trong nước dùng cá cơm hoặc hải sản — Daejeon có cả một con phố mì.', 'Kalguksu nghĩa là ''mì dao'': bột được cán mỏng rồi thái tay, nên sợi không đều và nước dùng luôn hơi sánh vì bột. Daejeon nổi tiếng với món này đến mức có lễ hội kalguksu riêng; mỗi quán một kiểu nước dùng — cá cơm, ngao, gà hoặc thịt bò.', 'daejeon', '["daejeon","sejong"]', '["Bột mì cán tay","Cá cơm khô","Bí ngòi","Ngao","Kim chi ăn kèm"]', 'Thanh, ấm bụng', 'Bữa trưa', '["noodle"]', 0, '{"en":{"name":"Daejeon kalguksu (knife-cut noodles)","summary":"Hand-cut noodles in anchovy or seafood broth — Daejeon has a whole street of them.","story":"Kalguksu means ''knife noodles'': the dough is rolled flat and cut by hand, so the strands are uneven and the broth always thickens slightly with flour. Daejeon is famous enough for it to hold its own kalguksu festival, with each shop keeping to its own stock — anchovy, clam, chicken or beef.","ingredients":["Hand-cut wheat noodles","Dried anchovy","Courgette","Clams","Kimchi on the side"],"flavor":"Clean and warming","bestTime":"Lunch"},"ko":{"name":"대전 칼국수","summary":"손으로 썬 면을 멸치나 해물 국물에 끓인다. 대전에는 칼국수 거리가 있다.","story":"칼국수는 ''칼로 썬 국수''다. 반죽을 밀어 손으로 썰기 때문에 면발이 고르지 않고 국물은 늘 밀가루로 살짝 걸쭉해진다. 대전은 칼국수 축제가 있을 만큼 유명하고 집집마다 국물이 다르다. 멸치, 바지락, 닭, 사골.","ingredients":["손칼국수 면","마른 멸치","애호박","바지락","겉절이"],"flavor":"담백하고 속이 편하다","bestTime":"점심"},"ja":{"name":"大田カルグクス","summary":"手切りの麺を煮干しや魚介の出汁で。大田にはカルグクス通りがある。","story":"カルグクスとは「包丁の麺」。生地を薄く伸ばして手で切るので麺は不揃いで、粉のおかげで汁がわずかにとろむ。大田は専用の祭りがあるほど有名で、店ごとに出汁が違う。煮干し、あさり、鶏、牛。","ingredients":["手切り麺","煮干し","ズッキーニ","あさり","添えのキムチ"],"flavor":"澄んでいて体が温まる","bestTime":"昼食"},"zh":{"name":"大田刀削麵","summary":"手切麵條配小魚乾或海鮮高湯，大田有一整條刀削麵街。","story":"kalguksu意為「刀切的麵」：麵團擀平後以刀手切，因此麵條粗細不一，湯頭也總會被麵粉稍稍勾稠。大田有名到辦起自己的刀削麵節，每家店守著自己的高湯——小魚乾、蛤蜊、雞或牛。","ingredients":["手切麵","小魚乾","櫛瓜","蛤蜊","配菜泡菜"],"flavor":"清爽暖胃","bestTime":"午餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-doenjang-jjigae', 'kr-doenjang-jjigae', 'Canh tương đậu (doenjang-jjigae)', 'Doenjang Jjigae', '🥘', 'Canh tương đậu lên men với đậu phụ và bí ngòi — món ăn hằng ngày nấu bằng thứ tương ủ cả năm.', 'Tương doenjang được ủ từ đậu nành nấu chín, nén thành bánh meju phơi khô rồi ngâm nước muối hàng tháng. Vùng Chungcheong quanh Sejong còn nhiều nhà ủ tương truyền thống với dãy chum sành phơi ngoài sân. Canh nấu đơn giản — tương, đậu phụ, bí ngòi, khoai tây — nhưng vị thì phụ thuộc hoàn toàn vào hũ tương của nhà đó.', 'sejong', '["sejong","chungnam","chungbuk"]', '["Tương doenjang","Đậu phụ","Bí ngòi","Khoai tây","Ớt xanh"]', 'Mặn dịu, thơm lên men', 'Quanh năm', '["vegetarian-option","rice"]', 0, '{"en":{"name":"Doenjang jjigae (soybean paste stew)","summary":"A daily stew of fermented soybean paste with tofu and courgette, made from paste aged a whole year.","story":"Doenjang is made by boiling soybeans, pressing them into meju blocks, drying them and steeping them in brine for months. The Chungcheong countryside around Sejong still has houses that ferment their own, with rows of earthenware jars in the yard. The stew itself is simple — paste, tofu, courgette, potato — but its flavour depends entirely on that family''s jar.","ingredients":["Doenjang paste","Tofu","Courgette","Potato","Green chilli"],"flavor":"Gently salty, fragrant with fermentation","bestTime":"Year-round"},"ko":{"name":"된장찌개","summary":"일 년 묵힌 장으로 끓인 두부와 애호박의 찌개. 매일의 음식이다.","story":"된장은 삶은 콩을 메주로 빚어 말린 뒤 소금물에 몇 달을 담가 만든다. 세종 주변 충청 시골에는 장독대를 마당에 두고 직접 담그는 집이 아직 있다. 장과 두부, 애호박, 감자를 넣어 끓이는 단순한 음식이지만 맛은 그 집 장독에 달렸다.","ingredients":["된장","두부","애호박","감자","청양고추"],"flavor":"짭짤하고 발효 향이 구수하다","bestTime":"연중"},"ja":{"name":"テンジャンチゲ","summary":"一年寝かせた味噌で作る豆腐とズッキーニのチゲ。毎日の食卓の味。","story":"テンジャンは大豆を煮て麹玉に固め、干して塩水に数か月漬けて作る。世宗周辺の忠清の田舎には、今も庭に甕を並べて自家製する家がある。味噌、豆腐、ズッキーニ、じゃがいも——作りは単純だが、味はその家の甕次第だ。","ingredients":["テンジャン","豆腐","ズッキーニ","じゃがいも","青唐辛子"],"flavor":"穏やかな塩気と発酵の香り","bestTime":"通年"},"zh":{"name":"大醬湯","summary":"以發酵大醬煮豆腐與櫛瓜的日常湯品，醬要熟成整整一年。","story":"大醬以煮熟黃豆壓成麴磚、曬乾後浸鹽水數月而成。世宗一帶的忠清鄉間仍有人家自己釀醬，院子裡排著陶甕。湯本身很簡單——醬、豆腐、櫛瓜、馬鈴薯——但味道完全取決於那戶人家的醬甕。","ingredients":["大醬","豆腐","櫛瓜","馬鈴薯","青辣椒"],"flavor":"鹹味柔和，帶發酵香","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-danyang-garlic', 'kr-danyang-garlic', 'Món tỏi Danyang', 'Danyang Garlic Dishes', '🧄', 'Tỏi Danyang trồng trên đất đá vôi — nướng, chiên tempura hay hầm với gà.', 'Đất đá vôi vùng Danyang cho củ tỏi chắc, cay và thơm hơn nơi khác, nên cả thị trấn bán đồ ăn từ tỏi: tỏi nướng chấm muối, tỏi tẩm bột chiên, gà hầm tỏi, thậm chí kem vị tỏi. Ở chợ Danyang, mùi tỏi nướng bay khắp dãy hàng và ai cũng được mời nếm thử.', 'chungbuk', '["chungbuk"]', '["Tỏi Danyang","Gà","Bột chiên","Dầu mè","Muối tiêu"]', 'Thơm nồng, ngọt hậu', 'Tháng 6–10', '["street"]', 0, '{"en":{"name":"Danyang garlic dishes","summary":"Garlic grown on limestone soil — roasted, fried in batter or stewed with chicken.","story":"The limestone ground around Danyang gives firm garlic that is sharper and more fragrant than elsewhere, so the whole town sells food made from it: roasted cloves with salt, garlic tempura, chicken stewed with garlic, even garlic ice cream. At Danyang market the smell of roasting garlic drifts down the whole row and everyone is offered a taste.","ingredients":["Danyang garlic","Chicken","Frying batter","Sesame oil","Salt and pepper"],"flavor":"Pungent and aromatic, sweet after the heat","bestTime":"June–October"},"ko":{"name":"단양 마늘 요리","summary":"석회암 땅에서 자란 마늘을 굽고 튀기고 닭과 함께 고아 낸다.","story":"단양의 석회암 토양은 단단하고 향이 강한 마늘을 낸다. 그래서 온 고을이 마늘로 만든 음식을 판다. 소금에 찍어 먹는 구운 마늘, 마늘 튀김, 마늘 닭백숙, 심지어 마늘 아이스크림까지. 단양 구경시장에는 마늘 굽는 냄새가 온 골목에 퍼진다.","ingredients":["단양 마늘","닭","튀김옷","참기름","소금후추"],"flavor":"향이 진하고 끝맛이 달다","bestTime":"6~10월"},"ja":{"name":"丹陽のにんにく料理","summary":"石灰岩の土で育ったにんにくを、焼き、揚げ、鶏と煮込む。","story":"丹陽の石灰質の土は、締まって香りの強いにんにくを生む。だから町じゅうがにんにくの料理を売る。塩で食べる焼きにんにく、天ぷら、にんにく鶏の水炊き、さらにはにんにくアイスまで。丹陽の市場では焼きにんにくの匂いが通り中に漂い、誰にでも味見を勧める。","ingredients":["丹陽のにんにく","鶏肉","揚げ衣","ごま油","塩胡椒"],"flavor":"香りが強く、後味は甘い","bestTime":"6〜10月"},"zh":{"name":"丹陽蒜味料理","summary":"石灰岩土壤長出的大蒜，可烤、可炸，也可燉雞。","story":"丹陽的石灰岩土讓蒜頭結實、辛香更濃，於是整座小鎮都賣蒜做的食物：沾鹽的烤蒜、蒜頭天婦羅、蒜燉雞，甚至蒜味冰淇淋。丹陽市場裡，烤蒜的香氣飄滿整排攤位，人人都被請去嚐一口。","ingredients":["丹陽大蒜","雞肉","炸粉","麻油","鹽與胡椒"],"flavor":"辛香濃烈，餘味回甘","bestTime":"6至10月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-olgaengi-guk', 'kr-olgaengi-guk', 'Canh ốc Chungju (olgaengi-guk)', 'Olgaengi Soup', '🐌', 'Canh ốc suối nấu tương đậu và rau — món giải rượu của vùng nội địa Chungbuk.', 'Chungbuk là tỉnh duy nhất không giáp biển, nên ''hải sản'' của họ đến từ sông suối: ốc olgaengi nhỏ bằng đầu ngón tay, luộc lấy nước, khều ruột nấu canh tương với rau lá. Nước canh xanh nhạt, vị khoáng và mát, được xem là món giải rượu tốt nhất vùng.', 'chungbuk', '["chungbuk"]', '["Ốc suối olgaengi","Tương doenjang","Rau cải","Bột đậu","Hành lá"]', 'Thanh, hơi đắng hậu ngọt', 'Quanh năm', '[]', 0, '{"en":{"name":"Chungju olgaengi soup","summary":"Freshwater snail soup with soybean paste and greens — the hangover cure of landlocked Chungbuk.","story":"Chungbuk is the only province without a coast, so its ''seafood'' comes from streams: olgaengi snails the size of a fingertip, boiled for stock, then picked and simmered into a soybean-paste soup with leafy greens. The broth is pale green, mineral and cooling, and is considered the region''s finest cure for a hangover.","ingredients":["Freshwater olgaengi snails","Doenjang paste","Leafy greens","Bean flour","Spring onion"],"flavor":"Clean, slightly bitter with a sweet finish","bestTime":"Year-round"},"ko":{"name":"충주 올갱이국","summary":"민물 다슬기를 된장에 풀어 끓인 국. 내륙 충북의 해장국이다.","story":"충북은 바다가 없는 유일한 도라 ''해산물''이 강에서 온다. 손가락 한 마디만 한 올갱이를 삶아 국물을 내고 살을 발라 된장에 푼 뒤 아욱이나 부추를 넣는다. 국물이 연둣빛으로 시원해 이 지역 최고의 해장국으로 꼽힌다.","ingredients":["올갱이","된장","아욱","콩가루","대파"],"flavor":"시원하고 살짝 쌉쌀하며 끝이 달다","bestTime":"연중"},"ja":{"name":"忠州オルゲンイ汁","summary":"川の巻貝を味噌で仕立てた汁。内陸忠北の酔い覚まし。","story":"忠北は海のない唯一の道で、「魚介」は川から来る。指先ほどのオルゲンイを茹でて出汁を取り、身をほぐして味噌汁に仕立て、葉物を加える。汁は淡い緑色でミネラル感があり、この地方随一の酔い覚ましとされる。","ingredients":["川の巻貝オルゲンイ","テンジャン","葉物野菜","豆粉","長ねぎ"],"flavor":"すっきりしてほろ苦く、後に甘い","bestTime":"通年"},"zh":{"name":"忠州田螺湯","summary":"淡水螺加大醬與野菜煮成的湯，內陸忠北的解酒良方。","story":"忠北是唯一不臨海的道，「海鮮」因此來自溪流：指節大小的田螺先煮出湯頭，再挑肉入大醬湯，加上葉菜。湯色淡綠，帶礦物感且清爽，被視為當地最好的解酒湯。","ingredients":["淡水田螺","大醬","葉菜","豆粉","青蔥"],"flavor":"清爽微苦，尾韻回甘","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-hodu-gwaja', 'kr-hodu-gwaja', 'Bánh hồ đào Cheonan (hodu-gwaja)', 'Cheonan Walnut Cake', '🌰', 'Bánh nướng nhỏ hình quả óc chó, nhân đậu đỏ và hạt óc chó — quà tàu xe quốc dân.', 'Ra đời ở Cheonan năm 1934, hodu-gwaja được nướng trong khuôn hình quả óc chó, nhân đậu đỏ mịn ôm lấy một mẩu hạt óc chó. Vì Cheonan là nút giao đường bộ lớn, món bánh này thành quà mua dọc đường của cả nước, bán ở mọi trạm dừng nghỉ cao tốc.', 'chungnam', '["chungnam"]', '["Bột mì","Đậu đỏ","Hạt óc chó","Sữa","Mật ong"]', 'Ngọt vừa, bùi', 'Quanh năm', '["dessert"]', 0, '{"en":{"name":"Cheonan walnut cakes","summary":"Small walnut-shaped cakes filled with red bean and a piece of walnut — the classic travel snack.","story":"Created in Cheonan in 1934, hodu-gwaja is baked in walnut-shaped moulds, the smooth red bean paste wrapping a nub of walnut. Because Cheonan is a major road junction, the cakes became the snack people buy on the way through, sold at every motorway service area in the country.","ingredients":["Wheat flour","Red bean paste","Walnut","Milk","Honey"],"flavor":"Mildly sweet and nutty","bestTime":"Year-round"},"ko":{"name":"천안 호두과자","summary":"호두 모양 틀에 구운 작은 과자. 팥소 안에 호두가 들어 있다.","story":"1934년 천안에서 만들어진 호두과자는 호두 모양 틀에 구워 고운 팥소가 호두 한 조각을 감싼다. 천안이 교통의 요지였던 덕에 길에서 사 가는 선물이 되어 전국 고속도로 휴게소에서 판다.","ingredients":["밀가루","팥소","호두","우유","꿀"],"flavor":"적당히 달고 고소하다","bestTime":"연중"},"ja":{"name":"天安クルミ菓子","summary":"クルミの形に焼いた小さな菓子。あんの中にクルミが一粒入る。","story":"1934年に天安で生まれたクルミ菓子は、クルミ形の型で焼き、なめらかなこしあんがクルミのかけらを包む。天安が交通の要衝だったため、道すがら買う土産となり、全国の高速道路サービスエリアで売られている。","ingredients":["小麦粉","こしあん","クルミ","牛乳","はちみつ"],"flavor":"ほどよい甘さと香ばしさ","bestTime":"通年"},"zh":{"name":"天安核桃餅","summary":"核桃造型的小點心，紅豆餡裡包著一塊核桃。","story":"1934年誕生於天安，以核桃形狀的模具烘烤，細滑的紅豆餡包住一小塊核桃。因為天安是重要的公路樞紐，它成了旅途上順手買的伴手禮，全國高速公路休息站都有賣。","ingredients":["麵粉","紅豆餡","核桃","牛奶","蜂蜜"],"flavor":"甜而不膩，堅果香","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-seosan-gulbap', 'kr-seosan-gulbap', 'Cơm hàu Seosan (gulbap)', 'Seosan Oyster Rice', '🦪', 'Cơm nấu cùng hàu tươi vùng triều Seosan, trộn nước tương hành trước khi ăn.', 'Bờ tây Chungnam có bãi triều rộng, hàu nhỏ nhưng đậm vị. Vào mùa lạnh, người ta nấu cơm cùng hàu trong nồi đá, khi chín rưới nước tương pha hành lá và dầu mè rồi trộn đều. Ăn kèm canh rong biển và kimchi cải — bữa cơm mùa đông điển hình của vùng biển tây.', 'chungnam', '["chungnam"]', '["Hàu tươi","Gạo","Nước tương","Hành lá","Dầu mè"]', 'Ngọt biển, thơm dầu mè', 'Tháng 11–2', '["seafood","rice"]', 0, '{"en":{"name":"Seosan oyster rice","summary":"Rice cooked with oysters from the Seosan tidal flats, mixed with soy and spring onion before eating.","story":"The west coast of Chungnam has wide tidal flats where oysters grow small but intensely flavoured. In the cold months they are cooked into rice in a stone pot; when it is done you pour over soy sauce with spring onion and sesame oil and mix. Served with seaweed soup and cabbage kimchi, it is the classic winter meal of the west coast.","ingredients":["Fresh oysters","Rice","Soy sauce","Spring onion","Sesame oil"],"flavor":"Sweet with the sea, fragrant with sesame","bestTime":"November–February"},"ko":{"name":"서산 굴밥","summary":"서산 갯벌의 굴로 지은 밥. 간장 양념장에 비벼 먹는다.","story":"충남 서해안은 갯벌이 넓어 굴이 작지만 맛이 진하다. 추운 계절에 굴을 넣어 돌솥에 밥을 짓고, 다 되면 파와 참기름을 넣은 간장을 둘러 비빈다. 미역국과 배추김치를 곁들이면 서해안의 전형적인 겨울 밥상이다.","ingredients":["생굴","쌀","간장","대파","참기름"],"flavor":"바다의 단맛과 참기름 향","bestTime":"11~2월"},"ja":{"name":"瑞山カキご飯","summary":"瑞山の干潟のカキで炊いたご飯を、醤油だれで混ぜて食べる。","story":"忠南の西海岸は干潟が広く、カキは小ぶりだが味が濃い。寒い季節、石鍋でカキと一緒に米を炊き、炊き上がりにねぎとごま油の醤油だれを回しかけて混ぜる。わかめスープと白菜キムチを添えれば、西海岸の典型的な冬の食卓になる。","ingredients":["生カキ","米","醤油","長ねぎ","ごま油"],"flavor":"海の甘みとごまの香り","bestTime":"11〜2月"},"zh":{"name":"瑞山牡蠣飯","summary":"以瑞山灘塗的牡蠣炊飯，食用前拌入醬油蔥花。","story":"忠南西海岸有寬闊的灘塗，牡蠣個頭不大但味道濃郁。天冷時把牡蠣與米一同放進石鍋炊煮，起鍋後淋上蔥花與麻油調的醬油拌開。配海帶湯與白菜泡菜，就是西海岸典型的冬季一餐。","ingredients":["鮮牡蠣","白米","醬油","青蔥","麻油"],"flavor":"海味清甜，麻油生香","bestTime":"11月至2月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-hobakjuk', 'kr-hobakjuk', 'Cháo bí đỏ (hobakjuk)', 'Pumpkin Porridge', '🎃', 'Cháo bí đỏ vàng óng, sánh mịn, điểm những viên bánh gạo nhỏ.', 'Chungnam là vùng trồng bí đỏ lớn, và cháo bí là món ăn nhẹ dành cho người ốm, người già hoặc bữa sáng nhẹ. Bí hấp chín, nghiền mịn, nấu với bột gạo nếp cho sánh, thả thêm những viên bánh gạo nhỏ gọi là saealsim. Vị ngọt tự nhiên, gần như không cần thêm đường.', 'chungnam', '["chungnam","sejong"]', '["Bí đỏ","Bột gạo nếp","Bánh gạo nhỏ","Đậu đỏ","Muối"]', 'Ngọt dịu, sánh mịn', 'Mùa thu đông', '["dessert","vegetarian-option"]', 0, '{"en":{"name":"Pumpkin porridge","summary":"Golden, silky pumpkin porridge dotted with small rice cake balls.","story":"Chungnam is a major pumpkin-growing region, and this porridge is what you give someone recovering, or eat as a light breakfast. The pumpkin is steamed, puréed and thickened with glutinous rice flour, then finished with tiny rice balls called saealsim. The sweetness is natural enough that it needs almost no sugar.","ingredients":["Pumpkin","Glutinous rice flour","Small rice cakes","Red beans","Salt"],"flavor":"Gently sweet and silky","bestTime":"Autumn and winter"},"ko":{"name":"호박죽","summary":"노랗고 부드러운 호박죽에 작은 새알심을 띄운다.","story":"충남은 호박 산지가 넓고, 호박죽은 아픈 사람과 어르신을 위한, 혹은 가벼운 아침을 위한 음식이다. 호박을 쪄서 곱게 으깨고 찹쌀가루로 농도를 내어 새알심을 넣는다. 단맛이 자연스러워 설탕이 거의 필요 없다.","ingredients":["늙은 호박","찹쌀가루","새알심","팥","소금"],"flavor":"은은히 달고 부드럽다","bestTime":"가을과 겨울"},"ja":{"name":"かぼちゃ粥","summary":"黄金色でなめらかなかぼちゃ粥に、小さな白玉を浮かべる。","story":"忠南はかぼちゃの一大産地で、この粥は病み上がりの人や年配の方、あるいは軽い朝食のための料理だ。かぼちゃを蒸して裏ごしし、もち米粉でとろみを付け、セアルシムという小さな団子を落とす。甘みが自然で砂糖はほとんど要らない。","ingredients":["かぼちゃ","もち米粉","小さな白玉","小豆","塩"],"flavor":"ほのかに甘くなめらか","bestTime":"秋と冬"},"zh":{"name":"南瓜粥","summary":"金黃綿滑的南瓜粥，點綴著小小的糯米丸子。","story":"忠南是南瓜產區，這碗粥是給病後恢復的人、長輩，或作為清淡早餐。南瓜蒸熟壓成泥，以糯米粉勾稠，再放入名為saealsim的小丸子。甜味天然，幾乎不必加糖。","ingredients":["南瓜","糯米粉","小糯米丸","紅豆","鹽"],"flavor":"清甜綿密","bestTime":"秋冬"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-jeonju-bibimbap', 'kr-jeonju-bibimbap', 'Bibimbap Jeonju', 'Jeonju Bibimbap', '🍚', 'Cơm trộn dọn trong tô đồng với hơn ba chục nguyên liệu, cơm nấu bằng nước hầm xương.', 'Bibimbap có ở khắp nơi, nhưng bản Jeonju là bản được coi là chuẩn mực: cơm nấu bằng nước hầm xương bò nên hạt cơm đã có vị, phủ lên là giá đỗ, rau dại theo mùa, nấm, trứng sống hoặc lòng đỏ, thịt bò sống thái sợi và một thìa tương ớt. Trộn đều trước khi ăn — càng trộn kỹ càng ngon.', 'jeonbuk', '["jeonbuk"]', '["Cơm nấu nước xương","Giá đỗ","Rau theo mùa","Thịt bò","Tương ớt gochujang"]', 'Cân bằng, đậm nhẹ, thơm dầu mè', 'Bữa trưa', '["rice","vegetarian-option"]', 1, '{"en":{"name":"Jeonju bibimbap","summary":"Rice cooked in beef broth, served in a brass bowl with more than thirty ingredients.","story":"Bibimbap is everywhere, but the Jeonju version is treated as the standard: the rice is cooked in beef stock so it is already seasoned, then topped with bean sprouts, seasonal wild greens, mushrooms, a raw egg yolk, slivers of raw beef and a spoon of chilli paste. Mix it thoroughly before eating — the more you mix, the better it gets.","ingredients":["Rice cooked in beef stock","Bean sprouts","Seasonal greens","Beef","Gochujang"],"flavor":"Balanced, gently rich, fragrant with sesame","bestTime":"Lunch"},"ko":{"name":"전주비빔밥","summary":"사골 국물로 지은 밥에 서른 가지가 넘는 재료를 올려 놋그릇에 낸다.","story":"비빔밥은 어디에나 있지만 전주 것이 기준으로 통한다. 밥을 사골 국물로 지어 이미 간이 배어 있고, 그 위에 콩나물과 제철 나물, 버섯, 노른자, 채 썬 육회, 고추장 한 술을 올린다. 먹기 전에 충분히 비빌수록 맛있다.","ingredients":["사골 밥","콩나물","제철 나물","육회","고추장"],"flavor":"균형 잡히고 고소하다","bestTime":"점심"},"ja":{"name":"全州ビビンバ","summary":"牛骨出汁で炊いたご飯に三十種超の具をのせ、真鍮の器で供する。","story":"ビビンバはどこにでもあるが、全州のものが標準とされる。ご飯を牛骨のスープで炊くので既に味が付いており、その上に豆もやし、季節の山菜、きのこ、生卵の黄身、細切りの牛刺し、コチュジャンを一匙。食べる前によく混ぜるほどおいしくなる。","ingredients":["牛骨出汁のご飯","豆もやし","季節の山菜","牛肉","コチュジャン"],"flavor":"バランスが良く、ごまが香る","bestTime":"昼食"},"zh":{"name":"全州拌飯","summary":"以牛骨高湯炊飯，黃銅碗盛裝，配料超過三十種。","story":"拌飯到處都有，但全州版被視為標準：米以牛骨高湯炊煮，本身已有味道，上面鋪豆芽、時令山菜、菇類、生蛋黃、切絲生牛肉與一匙辣椒醬。吃之前務必拌勻——拌得越透越好吃。","ingredients":["牛骨高湯炊飯","黃豆芽","時令野菜","牛肉","辣椒醬"],"flavor":"均衡溫潤，麻油生香","bestTime":"午餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-kongnamul-gukbap', 'kr-kongnamul-gukbap', 'Canh giá đỗ Jeonju (kongnamul-gukbap)', 'Kongnamul Gukbap', '🥣', 'Canh giá đỗ nóng chan cơm, ăn kèm trứng chần — món giải rượu buổi sáng của Jeonju.', 'Giá đỗ Jeonju được trồng bằng nước giếng địa phương, thân mập và giòn. Canh nấu đơn giản với cá cơm khô, giá và hành, chan cơm ăn nóng; nhiều quán dọn kèm một chén trứng chần để húp trước cho ấm bụng. Quán mở từ tờ mờ sáng, phục vụ người đi làm sớm và người vừa qua một đêm dài.', 'jeonbuk', '["jeonbuk"]', '["Giá đỗ","Cơm","Cá cơm khô","Trứng","Kimchi"]', 'Thanh, ấm, cay nhẹ', 'Sáng sớm', '["rice","breakfast"]', 0, '{"en":{"name":"Jeonju bean sprout soup rice","summary":"Hot bean sprout soup poured over rice with a poached egg — Jeonju''s morning hangover cure.","story":"Jeonju''s bean sprouts are grown with local well water and come out thick and crunchy. The soup is simple — dried anchovy, sprouts, spring onion — poured over rice and eaten hot, often with a small bowl of poached egg to sip first. The shops open before dawn, serving early workers and people coming off a long night.","ingredients":["Bean sprouts","Rice","Dried anchovy","Egg","Kimchi"],"flavor":"Clean, warming, gently spicy","bestTime":"Early morning"},"ko":{"name":"전주 콩나물국밥","summary":"뜨거운 콩나물국에 밥을 말고 수란을 곁들이는 아침 해장.","story":"전주 콩나물은 이 고장 우물물로 길러 대가 굵고 아삭하다. 멸치와 콩나물, 파로 간단히 끓여 밥을 말고, 많은 집이 먼저 후루룩 마실 수란을 함께 낸다. 새벽부터 문을 열어 일 나가는 사람과 긴 밤을 보낸 사람을 맞는다.","ingredients":["콩나물","밥","마른 멸치","달걀","김치"],"flavor":"시원하고 따뜻하며 살짝 맵다","bestTime":"이른 아침"},"ja":{"name":"全州豆もやしクッパ","summary":"熱い豆もやしスープにご飯を入れ、落とし卵を添える朝の酔い覚まし。","story":"全州の豆もやしは地元の井戸水で育てるので太くて歯切れが良い。煮干しともやし、ねぎで簡単に取った汁にご飯を入れて熱いうちに食べ、多くの店では先にすする落とし卵の小鉢が付く。夜明け前から開き、早出の人と長い夜を過ごした人を迎える。","ingredients":["豆もやし","ご飯","煮干し","卵","キムチ"],"flavor":"すっきり温かく、ほのかに辛い","bestTime":"早朝"},"zh":{"name":"全州黃豆芽湯飯","summary":"滾燙的豆芽湯澆在飯上，配一碗溫泉蛋——全州的晨間解酒。","story":"全州的黃豆芽以當地井水培育，粗壯爽脆。湯很簡單：小魚乾、豆芽與蔥，澆在飯上趁熱吃，多數店家還附一小碗溫泉蛋先喝。店家天未亮就開門，迎接早班工人與熬過長夜的人。","ingredients":["黃豆芽","白飯","小魚乾","雞蛋","泡菜"],"flavor":"清爽溫暖，微辣","bestTime":"清晨"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-makgeolli', 'kr-makgeolli', 'Makgeolli Jeonju', 'Jeonju Makgeolli', '🍶', 'Rượu gạo đục uống bằng bát — gọi một bình là được kèm cả mâm đồ nhắm.', 'Ở phố makgeolli Jeonju có luật bất thành văn: gọi bình rượu đầu tiên, quán bưng ra một mâm đồ nhắm; gọi bình thứ hai, mâm mới lại xuất hiện với món khác. Rượu gạo lên men nhẹ, đục, hơi ngọt và có ga tự nhiên, uống bằng bát chứ không bằng ly. Đây là cách người Jeonju tiếp khách phương xa.', 'jeonbuk', '["jeonbuk"]', '["Gạo","Men nuruk","Nước"]', 'Chua ngọt nhẹ, có ga', 'Tối', '["late-night"]', 0, '{"en":{"name":"Jeonju makgeolli","summary":"Cloudy rice wine drunk from a bowl — order one kettle and a table of food arrives with it.","story":"On Jeonju''s makgeolli streets there is an unwritten rule: order the first kettle and the house brings a tray of dishes; order a second and a new tray appears with different food. The wine is lightly fermented, cloudy, faintly sweet and naturally fizzy, drunk from bowls rather than glasses. This is how Jeonju receives visitors.","ingredients":["Rice","Nuruk starter","Water"],"flavor":"Lightly sweet and tart, softly sparkling","bestTime":"Evening"},"ko":{"name":"전주 막걸리","summary":"사발에 마시는 탁주. 한 주전자를 시키면 안주 한 상이 따라온다.","story":"전주 막걸리 골목에는 불문율이 있다. 첫 주전자를 시키면 안주 한 상이 나오고, 두 번째를 시키면 다른 안주로 새 상이 나온다. 가볍게 발효된 탁한 술은 살짝 달고 자연 탄산이 있어 잔이 아니라 사발로 마신다.","ingredients":["쌀","누룩","물"],"flavor":"새콤달콤하고 톡 쏜다","bestTime":"저녁"},"ja":{"name":"全州マッコリ","summary":"碗で飲む濁り酒。やかん一つ頼めば料理が一膳ついてくる。","story":"全州のマッコリ横丁には不文律がある。最初のやかんを頼めば店がつまみを一膳出し、二本目を頼めば別の料理で新しい膳が出る。軽く発酵した濁った酒はほのかに甘く自然な炭酸があり、グラスではなく碗で飲む。これが全州の客のもてなし方だ。","ingredients":["米","ヌルク（麹）","水"],"flavor":"ほのかに甘酸っぱく、微発泡","bestTime":"夜"},"zh":{"name":"全州馬格利","summary":"以碗盛的濁米酒——點一壺，一整桌下酒菜就跟著來。","story":"全州的馬格利街有一條不成文的規矩：點第一壺，店家送上一桌小菜；點第二壺，換一批菜再上一桌。這種輕發酵的濁酒微甜、帶天然氣泡，用碗而不是杯子喝。全州就是這樣招待遠客的。","ingredients":["米","麴（nuruk）","水"],"flavor":"微甜帶酸，輕微氣泡","bestTime":"夜晚"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-oritang', 'kr-oritang', 'Vịt hầm Gwangju (oritang)', 'Gwangju Duck Soup', '🦆', 'Vịt hầm với rau thơm và bột gạo, nước dùng sánh — món tự hào của bàn ăn Gwangju.', 'Gwangju nổi tiếng vì mâm cơm nhiều món phụ, nhưng món chính được nhắc nhiều nhất là oritang. Vịt hầm mềm với hành tây, tỏi và các loại lá thơm, nước dùng thêm bột gạo cho sánh, chấm cùng nước tương mù tạt. Ăn xong, phần nước còn lại dùng để nấu cháo hoặc mì.', 'gwangju', '["gwangju"]', '["Thịt vịt","Bột gạo","Hành tây","Rau thơm","Mù tạt"]', 'Béo mềm, thơm rau', 'Mùa thu đông', '[]', 1, '{"en":{"name":"Gwangju duck soup","summary":"Duck simmered with herbs and thickened with rice flour — the dish Gwangju is proudest of.","story":"Gwangju is famous for tables crowded with side dishes, but the main course people talk about is oritang. Duck is simmered soft with onion, garlic and aromatic leaves, the broth thickened with rice flour, and the meat dipped in mustard soy. When the meat is gone, the remaining broth is used to cook rice porridge or noodles.","ingredients":["Duck","Rice flour","Onion","Aromatic herbs","Mustard"],"flavor":"Rich and tender, fragrant with herbs","bestTime":"Autumn and winter"},"ko":{"name":"광주 오리탕","summary":"오리를 들깨와 미나리에 끓여 걸쭉하게 낸, 광주가 자랑하는 음식.","story":"광주는 반찬 많은 상차림으로 유명하지만 사람들이 가장 많이 말하는 본 요리는 오리탕이다. 양파와 마늘, 향채와 함께 푹 끓이고 들깨가루로 농도를 내며, 겨자 간장에 찍어 먹는다. 고기를 다 먹으면 남은 국물로 죽이나 국수를 만든다.","ingredients":["오리고기","들깨가루","양파","미나리","겨자"],"flavor":"부드럽고 고소하며 향이 진하다","bestTime":"가을과 겨울"},"ja":{"name":"光州オリタン（鴨鍋）","summary":"鴨を香味野菜と煮て米粉でとろみを付けた、光州自慢の一品。","story":"光州はおかずの多い食卓で有名だが、主菜として語られるのはオリタンだ。鴨を玉ねぎ、にんにく、香りの葉と柔らかく煮て、米粉で汁にとろみを付け、辛子醤油で食べる。肉を食べ終えたら、残りの汁で粥や麺を作る。","ingredients":["鴨肉","米粉","玉ねぎ","香味野菜","辛子"],"flavor":"こくがあり柔らかく、香草が香る","bestTime":"秋と冬"},"zh":{"name":"光州鴨湯","summary":"鴨肉與香料同燉、以米粉勾稠，光州最自豪的一道。","story":"光州以滿桌小菜聞名，但人們談論最多的主菜是鴨湯。鴨肉與洋蔥、大蒜及香草慢燉至軟，湯以米粉勾稠，肉沾芥末醬油吃。肉吃完後，剩下的湯用來煮粥或下麵。","ingredients":["鴨肉","米粉","洋蔥","香草","芥末"],"flavor":"醇厚軟嫩，香草生香","bestTime":"秋冬"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-hanjeongsik', 'kr-hanjeongsik', 'Mâm cơm Honam (hanjeongsik)', 'Honam Hanjeongsik', '🍱', 'Bàn ăn phủ kín hai ba chục đĩa nhỏ, đặc sản của vùng ăn ngon nhất Hàn Quốc.', 'Ở Gwangju và Jeollanam-do, một bữa hanjeongsik có thể lên tới ba chục đĩa: cá kho, thịt nướng, rau trộn, hải sản muối, các loại kimchi, canh, chè tráng miệng. Đĩa phải xếp chồng lên nhau vì bàn không đủ chỗ. Vùng này đất tốt, biển gần, nên truyền thống bày bàn thịnh soạn đã có từ lâu và tới nay vẫn giữ.', 'gwangju', '["gwangju","jeonnam"]', '["Cá kho","Rau trộn theo mùa","Hải sản muối jeotgal","Nhiều loại kimchi","Canh"]', 'Đủ vị: mặn, chua, cay, ngọt', 'Bữa trưa hoặc tối', '["rice"]', 1, '{"en":{"name":"Honam banquet table (hanjeongsik)","summary":"A table covered with twenty or thirty small dishes — the speciality of Korea''s best-eating region.","story":"In Gwangju and South Jeolla a hanjeongsik meal can run to thirty dishes: braised fish, grilled meat, seasoned greens, salted seafood, several kimchi, soup and a sweet to finish. Plates have to be stacked because the table runs out of room. The land is rich and the sea is close, so this tradition of abundance is old and still going.","ingredients":["Braised fish","Seasonal greens","Jeotgal salted seafood","Several kimchi","Soup"],"flavor":"Every register at once: salty, sour, spicy, sweet","bestTime":"Lunch or dinner"},"ko":{"name":"호남 한정식","summary":"스무 가지에서 서른 가지 반찬이 상을 덮는, 가장 잘 먹는 고장의 상차림.","story":"광주와 전남의 한정식은 서른 접시에 이르기도 한다. 생선조림, 고기구이, 나물, 젓갈, 여러 김치, 국, 그리고 후식까지. 상이 좁아 접시를 포개야 한다. 땅이 좋고 바다가 가까워 이 넉넉한 상차림의 전통이 오래도록 이어졌다.","ingredients":["생선조림","제철 나물","젓갈","여러 김치","국"],"flavor":"짜고 시고 맵고 단맛이 한 상에","bestTime":"점심 또는 저녁"},"ja":{"name":"湖南の韓定食","summary":"二十から三十の小皿が卓を覆う、韓国で最も食の豊かな地方の膳。","story":"光州と全羅南道の韓定食は三十皿に及ぶこともある。魚の煮付け、焼き物、和え物、塩辛、数種のキムチ、汁物、そして甘味。卓が足りず皿を重ねることになる。土地が豊かで海が近いため、この豊穣な膳の伝統は古く、今も続いている。","ingredients":["魚の煮付け","季節の和え物","塩辛","数種のキムチ","汁物"],"flavor":"塩味・酸味・辛味・甘味が一度に","bestTime":"昼食または夕食"},"zh":{"name":"湖南韓定食","summary":"二三十碟小菜鋪滿一桌，韓國最會吃的地區的宴席。","story":"在光州與全羅南道，一頓韓定食可以上到三十道：燉魚、烤肉、涼拌野菜、鹽辛海產、好幾種泡菜、湯品，最後還有甜點。桌子放不下，只好把盤子疊起來。這裡土地肥沃、海又近，豐盛的傳統由來已久，至今不衰。","ingredients":["燉魚","時令野菜","鹽辛海產","多種泡菜","湯品"],"flavor":"鹹、酸、辣、甜一次到齊","bestTime":"午餐或晚餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-hongeo-samhap', 'kr-hongeo-samhap', 'Cá đuối lên men (hongeo-samhap)', 'Hongeo Samhap', '😤', 'Cá đuối lên men ăn cùng thịt luộc và kimchi — món gây tranh cãi nhất bàn ăn Hàn Quốc.', 'Cá đuối được ủ trong vại cho lên men, sinh amoniac mạnh đến mức xộc lên mũi. ''Samhap'' nghĩa là bộ ba: một miếng cá đuối, một miếng thịt luộc, một miếng kimchi cải, ăn cùng nhau và nhấp một ngụm makgeolli. Người Jeonnam coi đây là món quý dọn trong đám cưới, đám giỗ; người ngoài vùng thường cần vài lần mới quen.', 'jeonnam', '["jeonnam"]', '["Cá đuối lên men","Thịt heo luộc","Kimchi cải","Makgeolli"]', 'Nồng, mặn, hậu ngọt', 'Quanh năm', '["seafood"]', 0, '{"en":{"name":"Hongeo samhap (fermented skate)","summary":"Fermented skate eaten with boiled pork and kimchi — the most divisive dish on a Korean table.","story":"The skate is fermented in a crock until it gives off enough ammonia to sting your nose. ''Samhap'' means the set of three: a piece of skate, a slice of boiled pork and a leaf of cabbage kimchi eaten together, chased with makgeolli. In Jeonnam it is the prestige dish served at weddings and memorial rites; outsiders usually need a few attempts.","ingredients":["Fermented skate","Boiled pork","Cabbage kimchi","Makgeolli"],"flavor":"Pungent and salty with a sweet finish","bestTime":"Year-round"},"ko":{"name":"홍어삼합","summary":"삭힌 홍어에 수육과 김치를 곁들이는, 가장 호불호가 갈리는 음식.","story":"항아리에서 삭힌 홍어는 코를 찌르는 암모니아 향을 낸다. 삼합은 홍어 한 점, 수육 한 점, 묵은지 한 장을 함께 먹고 막걸리를 한 모금 넘기는 것이다. 전남에서는 잔칫상과 제사상에 올리는 귀한 음식이고, 외지 사람은 대개 몇 번은 겪어야 익숙해진다.","ingredients":["삭힌 홍어","돼지 수육","묵은지","막걸리"],"flavor":"톡 쏘고 짭짤하며 끝에 단맛이 남는다","bestTime":"연중"},"ja":{"name":"ホンオサンハプ（発酵エイ）","summary":"発酵させたエイをゆで豚とキムチで食べる、最も好みの分かれる料理。","story":"甕で発酵させたエイは鼻を突くアンモニアを放つ。サンハプとは三つ揃いの意味で、エイ一切れ、ゆで豚一切れ、白菜キムチ一枚を一緒に口に入れ、マッコリを流し込む。全羅南道では婚礼や法事に出される格の高い料理で、他所の人はたいてい何度か試して慣れる。","ingredients":["発酵エイ","ゆで豚","白菜キムチ","マッコリ"],"flavor":"刺激的で塩気があり、後に甘み","bestTime":"通年"},"zh":{"name":"洪魚三合（發酵魟魚）","summary":"發酵魟魚配水煮豬肉與泡菜，韓國餐桌上最兩極的一道。","story":"魟魚在甕中發酵到散發嗆鼻的阿摩尼亞味。「三合」意指三樣一起：一片魟魚、一片水煮豬肉、一葉白菜泡菜同時入口，再喝一口馬格利。在全南，這是婚宴與祭祀的體面菜；外地人通常要試幾次才習慣。","ingredients":["發酵魟魚","水煮豬肉","白菜泡菜","馬格利"],"flavor":"嗆烈鹹香，尾韻回甘","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-nakji', 'kr-nakji', 'Bạch tuộc nhỏ Muan (nakji)', 'Muan Baby Octopus', '🐙', 'Bạch tuộc bắt tay trên bãi triều, ăn sống, nướng hoặc nấu canh cay.', 'Ở Muan, người ta bắt bạch tuộc bằng cách móc tay xuống lỗ bùn trên bãi triều. Bạch tuộc tươi được ăn ngay: cắt khúc còn ngọ nguậy chấm dầu mè, hoặc quấn quanh đũa nướng than, hoặc nấu canh cay với rau. Người địa phương nói một con nakji vào mùa hè bổ bằng cả một thang thuốc.', 'jeonnam', '["jeonnam"]', '["Bạch tuộc nhỏ","Dầu mè","Tương ớt","Rau thơm","Tỏi"]', 'Ngọt tươi, dai giòn', 'Tháng 5–9', '["seafood"]', 0, '{"en":{"name":"Muan baby octopus","summary":"Octopus caught by hand on the mudflats — eaten raw, grilled, or in a spicy soup.","story":"In Muan people catch octopus by reaching into mud holes on the tidal flats. It is eaten as fresh as possible: cut up while still moving and dipped in sesame oil, wound around a chopstick and grilled, or cooked into a fiery soup with vegetables. Locals say one nakji in summer is worth a whole course of medicine.","ingredients":["Baby octopus","Sesame oil","Chilli paste","Herbs","Garlic"],"flavor":"Sweet, fresh, springy","bestTime":"May–September"},"ko":{"name":"무안 낙지","summary":"갯벌에서 손으로 잡은 낙지를 산낙지, 연포탕, 구이로 먹는다.","story":"무안에서는 갯벌 구멍에 손을 넣어 낙지를 잡는다. 잡자마자 먹는 것이 최고다. 꿈틀거리는 채로 썰어 참기름에 찍거나, 젓가락에 말아 숯에 굽거나, 채소를 넣어 맵게 끓인다. 여름 낙지 한 마리가 보약 한 첩이라는 말이 있다.","ingredients":["낙지","참기름","고추장","미나리","마늘"],"flavor":"달고 신선하며 쫄깃하다","bestTime":"5~9월"},"ja":{"name":"務安のテナガダコ","summary":"干潟で手づかみしたタコを、生で、焼いて、辛い鍋で。","story":"務安では干潟の穴に手を入れてタコを捕る。捕れたてを食べるのが一番だ。動いているうちに切ってごま油で、箸に巻き付けて炭で焼いて、あるいは野菜を入れて辛い鍋にする。夏のタコ一匹は薬一服に匹敵する、と地元では言う。","ingredients":["テナガダコ","ごま油","コチュジャン","香味野菜","にんにく"],"flavor":"甘く新鮮で、こりこりした食感","bestTime":"5〜9月"},"zh":{"name":"務安小章魚","summary":"在灘塗上徒手抓的章魚——生吃、燒烤，或煮成辣湯。","story":"務安人把手伸進灘塗的泥洞裡抓章魚，越新鮮越好：切開時還在動，沾麻油吃；或纏在筷子上炭烤；或加蔬菜煮成火辣的湯。當地人說，夏天一隻章魚抵得上一帖補藥。","ingredients":["小章魚","麻油","辣椒醬","香菜蔬","大蒜"],"flavor":"鮮甜彈牙","bestTime":"5至9月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-daetongbap', 'kr-daetongbap', 'Cơm ống tre Damyang (daetongbap)', 'Damyang Bamboo Rice', '🎋', 'Cơm nếp hấp trong ống tre tươi, thơm mùi tre và điểm hạt dẻ, táo tàu.', 'Damyang có rừng tre lớn nhất Hàn Quốc, nên ống tre thành nồi: gạo nếp trộn hạt dẻ, táo tàu, đậu và hạt thông được nhồi vào ống tre tươi, bịt giấy rồi hấp. Khi mở ra, cơm ngấm hương tre thoang thoảng. Dọn kèm cả chục món rau vùng núi — bữa cơm chay thanh nhã nhất Hàn Quốc.', 'jeonnam', '["jeonnam"]', '["Gạo nếp","Ống tre tươi","Hạt dẻ","Táo tàu","Hạt thông"]', 'Thơm tre, ngọt bùi', 'Tháng 5–10', '["rice","vegetarian-option"]', 1, '{"en":{"name":"Damyang bamboo rice","summary":"Glutinous rice steamed inside a fresh bamboo tube with chestnut and jujube.","story":"Damyang has the largest bamboo groves in Korea, so the tube becomes the pot: glutinous rice with chestnuts, jujube, beans and pine nuts is packed into fresh bamboo, sealed with paper and steamed. Opened at the table, the rice carries a faint scent of bamboo. It comes with a dozen mountain vegetable dishes — the most elegant vegetarian meal in Korea.","ingredients":["Glutinous rice","Fresh bamboo tube","Chestnuts","Jujube","Pine nuts"],"flavor":"Fragrant with bamboo, sweet and nutty","bestTime":"May–October"},"ko":{"name":"담양 대통밥","summary":"생대나무 통에 밤과 대추를 넣어 찐 찹쌀밥.","story":"담양에는 한국에서 가장 큰 대숲이 있어 대통이 곧 솥이 된다. 찹쌀에 밤과 대추, 콩, 잣을 섞어 생대통에 채우고 한지로 막아 찐다. 열면 대나무 향이 은은히 배어 있다. 산나물 반찬 열 가지가 함께 나오는 가장 정갈한 밥상이다.","ingredients":["찹쌀","생대나무 통","밤","대추","잣"],"flavor":"대나무 향이 나고 고소하다","bestTime":"5~10월"},"ja":{"name":"潭陽の竹筒飯","summary":"生の竹筒に栗となつめを入れて蒸したもち米飯。","story":"潭陽には韓国最大の竹林があり、竹筒がそのまま釜になる。もち米に栗、なつめ、豆、松の実を混ぜて生の竹に詰め、紙で蓋をして蒸す。開けると竹の香りがほのかに移っている。山菜のおかず十数皿と一緒に出される、韓国で最も端正な精進の膳だ。","ingredients":["もち米","生の竹筒","栗","なつめ","松の実"],"flavor":"竹が香り、甘く香ばしい","bestTime":"5〜10月"},"zh":{"name":"潭陽竹筒飯","summary":"糯米加栗子與紅棗，裝入新鮮竹筒蒸熟。","story":"潭陽有韓國最大的竹林，竹筒就是鍋：糯米拌栗子、紅棗、豆子與松子填入新鮮竹筒，以紙封口蒸熟。打開時，飯帶著淡淡竹香。搭配十來碟山菜小菜，是韓國最雅緻的一頓素食。","ingredients":["糯米","新鮮竹筒","栗子","紅棗","松子"],"flavor":"竹香清雅，甘甜堅果味","bestTime":"5至10月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-boseong-tea', 'kr-boseong-tea', 'Trà xanh Boseong', 'Boseong Green Tea', '🍵', 'Trà xanh từ đồi chè lớn nhất Hàn Quốc — uống nóng, làm kem, trộn cả vào cơm.', 'Boseong chiếm phần lớn sản lượng chè Hàn Quốc, và cả thị trấn sống quanh lá chè: trà pha nóng theo lối truyền thống trong ấm nhỏ, kem trà xanh bán ở cổng đồi chè, mì trà xanh, thậm chí thịt heo nuôi bằng bã chè. Lá hái đầu tháng 5 (ujeon) là loại đắt nhất, vị ngọt hậu và ít chát.', 'jeonnam', '["jeonnam"]', '["Lá chè xanh Boseong","Nước suối","Sữa (cho kem)"]', 'Chát nhẹ, hậu ngọt', 'Tháng 5–6', '["dessert"]', 0, '{"en":{"name":"Boseong green tea","summary":"Tea from Korea''s largest plantation — brewed hot, churned into ice cream, even mixed into rice.","story":"Boseong produces most of Korea''s tea, and the whole town lives around the leaf: tea brewed traditionally in small pots, green tea ice cream at the plantation gate, green tea noodles, even pork raised on tea residue. Leaves picked in early May (ujeon) are the most prized, sweet in the finish with little astringency.","ingredients":["Boseong green tea leaves","Spring water","Milk (for ice cream)"],"flavor":"Lightly astringent with a sweet finish","bestTime":"May–June"},"ko":{"name":"보성 녹차","summary":"한국 최대 차밭의 녹차. 우려 마시고, 아이스크림으로도, 밥에도 넣는다.","story":"보성은 한국 차 생산의 대부분을 차지하고 온 고을이 찻잎으로 산다. 작은 다관에 우린 차, 차밭 입구의 녹차 아이스크림, 녹차 국수, 심지어 차 찌꺼기를 먹인 돼지까지 있다. 5월 초에 딴 우전이 가장 귀하고 떫은맛이 적으며 끝이 달다.","ingredients":["보성 찻잎","샘물","우유(아이스크림용)"],"flavor":"은은히 떫고 끝맛이 달다","bestTime":"5~6월"},"ja":{"name":"宝城の緑茶","summary":"韓国最大の茶園の緑茶。淹れて飲み、アイスにし、ご飯にも混ぜる。","story":"宝城は韓国の茶生産の大半を占め、町全体が茶葉で生きている。小さな急須で淹れる茶、茶園入口の緑茶アイス、緑茶麺、さらには茶かすで育てた豚まである。五月初めに摘む雨前が最も貴重で、渋みが少なく後味が甘い。","ingredients":["宝城の茶葉","湧き水","牛乳（アイス用）"],"flavor":"軽い渋みと甘い後味","bestTime":"5〜6月"},"zh":{"name":"寶城綠茶","summary":"來自韓國最大茶園的綠茶——熱沖、做成冰淇淋，甚至拌進飯裡。","story":"寶城產出韓國大部分的茶，整座小鎮圍著這片葉子生活：以小壺傳統沖泡的茶、茶園門口的綠茶冰淇淋、綠茶麵，甚至以茶渣餵養的豬。五月初採的「雨前」最為珍貴，澀感低而回甘。","ingredients":["寶城茶葉","山泉水","牛奶（製冰淇淋用）"],"flavor":"微澀回甘","bestTime":"5至6月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-andong-jjimdak', 'kr-andong-jjimdak', 'Gà hầm Andong (jjimdak)', 'Andong Jjimdak', '🍲', 'Gà hầm nước tương với miến, khoai tây và ớt khô — một chảo lớn cho cả bàn.', 'Jjimdak ra đời ở chợ cũ Andong, tương truyền khi các quán gà nghĩ ra món mới để cạnh tranh với gà rán. Gà chặt miếng hầm nước tương ngọt cùng khoai tây, cà rốt, hành và miến khoai lang, cay dịu nhờ ớt khô. Một suất đủ cho ba bốn người, và phần miến ngấm nước sốt luôn hết trước.', 'gyeongbuk', '["gyeongbuk"]', '["Gà","Nước tương","Miến khoai lang","Khoai tây","Ớt khô"]', 'Mặn ngọt, cay nhẹ', 'Quanh năm', '[]', 1, '{"en":{"name":"Andong jjimdak","summary":"Chicken braised in soy sauce with glass noodles, potato and dried chilli — one big pan for the table.","story":"Jjimdak was invented in Andong''s old market, reputedly when the chicken shops needed something new to compete with fried chicken. Chicken is braised in sweet soy with potato, carrot, onion and sweet potato noodles, warmed by dried chilli. One order feeds three or four, and the sauce-soaked noodles always go first.","ingredients":["Chicken","Soy sauce","Sweet potato noodles","Potato","Dried chilli"],"flavor":"Salty-sweet with mild heat","bestTime":"Year-round"},"ko":{"name":"안동찜닭","summary":"간장에 닭과 당면, 감자, 마른 고추를 조린 큰 한 판.","story":"안동 구시장에서 시작됐다. 치킨과 경쟁하려던 닭집들이 새 메뉴를 냈다는 이야기가 전한다. 간장에 감자와 당근, 양파, 당면을 넣어 달큰하게 조리고 마른 고추로 은근한 매운맛을 낸다. 한 판이면 서너 명이 먹고, 양념이 밴 당면이 늘 먼저 사라진다.","ingredients":["닭","간장","당면","감자","마른 고추"],"flavor":"짭짤달콤하고 살짝 맵다","bestTime":"연중"},"ja":{"name":"安東チムタク","summary":"醤油で鶏と春雨、じゃがいも、唐辛子を煮た大皿料理。","story":"チムタクは安東の旧市場で生まれた。フライドチキンに対抗するため鶏の店が新しい品を出したのが始まりと言われる。醤油でじゃがいも、にんじん、玉ねぎ、さつまいも春雨と甘く煮て、乾燥唐辛子で穏やかな辛さを付ける。一皿で三、四人分。たれの染みた春雨が必ず先になくなる。","ingredients":["鶏肉","醤油","さつまいも春雨","じゃがいも","乾燥唐辛子"],"flavor":"甘塩っぱく、ほのかに辛い","bestTime":"通年"},"zh":{"name":"安東燉雞","summary":"醬油燉雞加冬粉、馬鈴薯與乾辣椒——一大鍋上桌共享。","story":"燉雞誕生於安東舊市場，據說是雞肉店為了與炸雞競爭而想出的新菜。雞肉以甜醬油與馬鈴薯、紅蘿蔔、洋蔥及地瓜冬粉同燉，乾辣椒帶來溫和的辣。一份夠三四人吃，吸飽醬汁的冬粉總是最先被夾光。","ingredients":["雞肉","醬油","地瓜冬粉","馬鈴薯","乾辣椒"],"flavor":"鹹甜帶微辣","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-andong-mackerel', 'kr-andong-mackerel', 'Cá thu muối Andong (gan-godeungeo)', 'Andong Salted Mackerel', '🐟', 'Cá thu ướp muối trên đường gánh từ biển vào núi — một phương pháp bảo quản thành đặc sản.', 'Andong nằm sâu trong đất liền, và ngày xưa cá từ biển đông gánh tới đây mất cả ngày đường. Người ta ướp muối dọc đường để cá không hỏng, và chính lớp muối cùng thời gian ấy làm thịt cá săn lại, đậm đà hơn hẳn cá tươi nướng. Nay cá thu muối Andong được làm theo quy trình chuẩn và bán khắp nước.', 'gyeongbuk', '["gyeongbuk"]', '["Cá thu","Muối biển","Dầu ăn"]', 'Mặn đậm, béo chắc', 'Quanh năm', '["seafood","rice"]', 0, '{"en":{"name":"Andong salted mackerel","summary":"Mackerel salted on the road from the sea into the mountains — a preservation method that became a delicacy.","story":"Andong lies far inland, and fish carried from the east sea took a full day to arrive. Traders salted the mackerel along the way to stop it spoiling, and that salt and time firmed the flesh into something better than fresh grilled fish. Today salted Andong mackerel is produced to a standard recipe and sold nationwide.","ingredients":["Mackerel","Sea salt","Cooking oil"],"flavor":"Deeply salty, firm and rich","bestTime":"Year-round"},"ko":{"name":"안동 간고등어","summary":"바다에서 산으로 가는 길에 소금을 친 고등어. 보관법이 별미가 되었다.","story":"안동은 내륙 깊숙이 있어 동해에서 온 생선이 하루가 걸렸다. 상하지 않게 길에서 소금을 쳤는데, 그 소금과 시간이 살을 단단하게 만들어 생물 구이보다 맛있어졌다. 지금은 표준화된 방식으로 만들어 전국에 팔린다.","ingredients":["고등어","천일염","식용유"],"flavor":"짭조름하고 살이 단단하며 기름지다","bestTime":"연중"},"ja":{"name":"安東の塩サバ","summary":"海から山へ運ぶ道中で塩をした鯖。保存法が名物になった。","story":"安東は内陸深くにあり、東海からの魚は丸一日かかった。傷まないよう道中で塩をしたのだが、その塩と時間が身を締め、生を焼くよりうまくなった。今では標準化された製法で作られ、全国に出荷されている。","ingredients":["鯖","天日塩","食用油"],"flavor":"しっかりした塩気と締まった脂","bestTime":"通年"},"zh":{"name":"安東鹽漬鯖魚","summary":"從海邊運往山區途中抹鹽的鯖魚——保存方法變成了名產。","story":"安東深居內陸，東海運來的魚要走上一整天。商販在路上抹鹽防腐，而那些鹽與時間讓魚肉更加緊實，比新鮮現烤還好吃。如今安東鹽漬鯖魚已按標準工序製作，行銷全國。","ingredients":["鯖魚","海鹽","食用油"],"flavor":"鹹香濃郁，肉質緊實","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-daegu-makchang', 'kr-daegu-makchang', 'Lòng nướng Daegu (makchang)', 'Daegu Makchang', '🔥', 'Lòng bò nướng than chấm tương đậu — món nhậu đặc trưng nhất của Daegu.', 'Makchang là phần ruột cuối của bò, nướng trên vỉ than cho cháy cạnh, giòn ngoài mềm trong, chấm tương đậu pha hành. Daegu có cả những con phố chỉ bán makchang, khói bay mù mịt từ chiều tới khuya. Đây là món ăn gắn với hình ảnh dân Daegu: nói thẳng, ăn mạnh, uống soju.', 'daegu', '["daegu"]', '["Lòng bò","Tương đậu chấm","Hành lá","Tỏi","Ớt xanh"]', 'Béo, khói than, đậm', 'Tối', '["late-night"]', 1, '{"en":{"name":"Daegu makchang (grilled beef intestine)","summary":"Grilled beef intestine dipped in soybean paste — the definitive Daegu drinking food.","story":"Makchang is the last section of beef intestine, grilled over charcoal until the edges char, crisp outside and soft within, dipped in soybean paste mixed with spring onion. Daegu has whole streets that sell nothing else, smoke pouring out from late afternoon until the small hours. It goes with the city''s reputation: blunt, hearty, soju in hand.","ingredients":["Beef intestine","Soybean dipping paste","Spring onion","Garlic","Green chilli"],"flavor":"Rich, smoky, deeply savoury","bestTime":"Evening"},"ko":{"name":"대구 막창","summary":"숯불에 구운 소막창을 된장 양념에 찍어 먹는 대구의 대표 안주.","story":"막창은 소의 끝 창자다. 숯불에 겉이 그을 때까지 구워 겉은 바삭하고 속은 부드럽게 만들어 파를 넣은 된장 소스에 찍는다. 대구에는 막창만 파는 거리가 있고 오후부터 새벽까지 연기가 자욱하다. 직설적이고 화끈한 대구의 이미지와 잘 어울린다.","ingredients":["소막창","된장 소스","대파","마늘","풋고추"],"flavor":"고소하고 숯향이 진하다","bestTime":"저녁"},"ja":{"name":"大邱マクチャン","summary":"炭火で焼いた牛の腸を味噌だれで。大邱を代表する酒の肴。","story":"マクチャンは牛の腸の最後の部分。炭火で縁が焦げるまで焼くと外は香ばしく中は柔らかい。ねぎを混ぜた味噌だれで食べる。大邱にはマクチャンだけを売る通りがあり、夕方から明け方まで煙が絶えない。ずばりと物を言い、豪快に食べ、焼酎を手にする——大邱らしさそのものだ。","ingredients":["牛の腸","味噌だれ","長ねぎ","にんにく","青唐辛子"],"flavor":"こくがあり、炭の香りが濃い","bestTime":"夜"},"zh":{"name":"大邱烤牛腸（makchang）","summary":"炭烤牛腸沾大醬醬料——大邱最具代表性的下酒菜。","story":"makchang是牛腸的末段，在炭火上烤到邊緣焦脆、外酥內軟，沾上拌了蔥花的大醬。大邱有整條街只賣它，從傍晚到凌晨煙霧不散。這正配得上這座城市的形象：說話直接、吃得豪爽、手裡一杯燒酒。","ingredients":["牛腸","大醬沾醬","青蔥","大蒜","青辣椒"],"flavor":"濃郁、帶炭香、鹹鮮","bestTime":"夜晚"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-daegu-jjim-galbi', 'kr-daegu-jjim-galbi', 'Sườn hấp cay Daegu (jjim-galbi)', 'Daegu Spicy Braised Ribs', '🌶️', 'Sườn bò hầm với cả nắm tỏi và bột ớt, cay xé nhưng dừng lại không nổi.', 'Ở phố Dongin-dong, jjim-galbi được nấu theo kiểu Daegu: sườn bò hầm mềm với tỏi băm và bột ớt thô, gần như không có nước sốt ngọt như galbijjim kiểu Seoul. Vị cay đến mức phải uống nước liên tục, và người Daegu tự hào chính vì điều đó. Cuối bữa, xin thêm cơm rang vào chảo còn sốt.', 'daegu', '["daegu"]', '["Sườn bò","Tỏi","Bột ớt","Nước tương","Hành"]', 'Cay mạnh, đậm tỏi', 'Tối', '["spicy"]', 0, '{"en":{"name":"Daegu spicy braised ribs","summary":"Beef ribs braised with a fistful of garlic and coarse chilli — searing, and impossible to stop eating.","story":"On Dongin-dong street, jjim-galbi is cooked the Daegu way: ribs braised tender with minced garlic and coarse chilli flakes, almost none of the sweet sauce that a Seoul-style galbijjim would have. It is hot enough to keep you drinking water, and Daegu is proud of exactly that. At the end, ask for rice to fry in the remaining sauce.","ingredients":["Beef short ribs","Garlic","Chilli flakes","Soy sauce","Spring onion"],"flavor":"Fiercely spicy and heavy with garlic","bestTime":"Evening"},"ko":{"name":"대구 찜갈비","summary":"다진 마늘과 굵은 고춧가루로 조린 소갈비. 맵지만 멈추기 어렵다.","story":"동인동 골목의 찜갈비는 대구식이다. 서울식 갈비찜처럼 달큰한 소스가 거의 없고, 다진 마늘과 굵은 고춧가루로 조려 낸다. 물을 계속 마시게 될 만큼 맵고, 대구는 바로 그 점을 자랑한다. 끝에는 남은 양념에 밥을 볶는다.","ingredients":["소갈비","마늘","고춧가루","간장","대파"],"flavor":"강하게 맵고 마늘 향이 진하다","bestTime":"저녁"},"ja":{"name":"大邱チムカルビ","summary":"大量のにんにくと粗挽き唐辛子で煮た牛カルビ。辛いのに手が止まらない。","story":"東仁洞の通りでは、チムカルビは大邱流に作られる。ソウル式カルビチムのような甘いたれはほとんどなく、みじん切りのにんにくと粗挽き唐辛子で煮込む。水が止まらないほど辛く、大邱はそこを誇りにしている。締めは残ったたれで炒めるご飯だ。","ingredients":["牛カルビ","にんにく","粗挽き唐辛子","醤油","長ねぎ"],"flavor":"強い辛さとにんにくの香り","bestTime":"夜"},"zh":{"name":"大邱辣燉排骨","summary":"牛小排以大量蒜末與粗辣椒粉燉煮，辣得過癮又停不下來。","story":"在東仁洞街上，燉排骨是大邱做法：牛小排以蒜末與粗辣椒粉燉軟，幾乎沒有首爾式那種甜醬汁。辣到得一直喝水，而大邱恰恰以此自豪。最後別忘了要一份飯，用剩下的醬汁炒。","ingredients":["牛小排","大蒜","辣椒粉","醬油","青蔥"],"flavor":"強烈辛辣，蒜香濃重","bestTime":"夜晚"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-napjak-mandu', 'kr-napjak-mandu', 'Bánh xếp dẹt Daegu (napjak-mandu)', 'Daegu Flat Dumplings', '🥟', 'Bánh xếp mỏng dẹt gần như không nhân, chiên áp chảo rồi rưới sốt cay.', 'Ra đời từ thời khó khăn khi nhân thịt là thứ xa xỉ: vỏ bánh cán mỏng, nhân chỉ chút miến và hành, chiên áp chảo cho giòn rồi rưới nước tương pha ớt, rắc hành. Món này gần như chỉ có ở Daegu, bán trong các chợ và quầy đường phố, thường ăn kèm tteokbokki.', 'daegu', '["daegu"]', '["Vỏ bánh mỏng","Miến","Hành lá","Nước tương ớt"]', 'Giòn nhẹ, mặn cay', 'Chiều', '["street"]', 0, '{"en":{"name":"Daegu flat dumplings","summary":"Paper-thin dumplings with almost no filling, pan-fried and dressed in a spicy sauce.","story":"Born in hard times when meat filling was a luxury: the wrapper is rolled thin, the filling is little more than glass noodles and spring onion, and the dumplings are pan-fried crisp then drizzled with soy-chilli sauce and scattered with spring onion. You find them almost nowhere but Daegu, in markets and street stalls, usually alongside tteokbokki.","ingredients":["Thin dumpling wrappers","Glass noodles","Spring onion","Soy-chilli sauce"],"flavor":"Lightly crisp, salty and spicy","bestTime":"Afternoon"},"ko":{"name":"대구 납작만두","summary":"속이 거의 없는 얇고 납작한 만두를 지져 매콤한 양념을 뿌린다.","story":"고기 속이 귀하던 시절에 태어났다. 피를 얇게 밀고 당면과 파만 조금 넣어 지진 뒤 간장 양념을 뿌리고 파를 얹는다. 대구 외에는 보기 어렵고 시장과 노점에서 떡볶이와 함께 판다.","ingredients":["얇은 만두피","당면","대파","간장 양념"],"flavor":"살짝 바삭하고 짭짤 매콤하다","bestTime":"오후"},"ja":{"name":"大邱の平たい餃子","summary":"具がほとんど入らない薄く平たい餃子を焼き、辛いたれをかける。","story":"肉の具が贅沢だった時代に生まれた。皮を薄く伸ばし、具は春雨とねぎが少しだけ。焼いてから醤油と唐辛子のたれをかけ、ねぎを散らす。大邱以外ではほとんど見かけず、市場や屋台でトッポッキと並んで売られる。","ingredients":["薄い餃子の皮","春雨","長ねぎ","醤油唐辛子だれ"],"flavor":"軽く香ばしく、塩気と辛味","bestTime":"午後"},"zh":{"name":"大邱扁餃子","summary":"薄如紙、幾乎沒有餡的扁餃子，煎過後淋上辣醬。","story":"誕生於肉餡奢侈的年代：餃子皮擀得極薄，內餡不過是一點冬粉與蔥，煎至酥脆後淋上醬油辣醬、撒上蔥花。除了大邱幾乎見不到，多在市場與路邊攤與辣炒年糕一起賣。","ingredients":["薄餃子皮","冬粉","青蔥","醬油辣醬"],"flavor":"微酥，鹹辣","bestTime":"午後"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-dwaeji-gukbap', 'kr-dwaeji-gukbap', 'Canh xương heo Busan (dwaeji-gukbap)', 'Busan Pork Soup Rice', '🍚', 'Nước hầm xương heo trắng đục chan cơm, tự nêm bằng mắm tôm và hẹ — món của người tị nạn.', 'Trong Chiến tranh Triều Tiên, người tị nạn dồn về Busan và nấu canh từ xương heo — thứ rẻ nhất còn lại. Nước dùng ninh nhiều giờ tới khi trắng như sữa, chan lên cơm, thêm thịt luộc thái mỏng. Mỗi bàn có mắm tôm, hẹ băm và bột ớt để tự nêm theo khẩu vị. Đây là món ăn định danh Busan.', 'busan', '["busan"]', '["Xương heo","Thịt heo luộc","Cơm","Hẹ băm","Mắm tôm"]', 'Béo dịu, đậm, mặn tuỳ nêm', 'Quanh năm', '["rice"]', 1, '{"en":{"name":"Busan pork soup rice","summary":"Milky pork bone broth over rice, seasoned at the table with salted shrimp and chives — a refugee''s dish.","story":"During the Korean War, refugees crowded into Busan and made soup from pork bones, the cheapest thing left. The broth is simmered for hours until it turns milky, poured over rice with thin slices of boiled pork. Every table has salted shrimp, chopped chives and chilli powder so you season it your own way. This is the dish that defines Busan.","ingredients":["Pork bones","Boiled pork","Rice","Chopped chives","Salted shrimp"],"flavor":"Gently rich and savoury, seasoned to taste","bestTime":"Year-round"},"ko":{"name":"부산 돼지국밥","summary":"뽀얀 돼지 사골 국물에 밥을 말고 새우젓과 부추로 간을 맞춘다.","story":"한국전쟁 때 부산으로 몰린 피란민이 가장 싼 재료였던 돼지뼈로 국을 끓였다. 여러 시간 고아 우유처럼 하얘진 국물에 밥을 말고 얇게 썬 수육을 얹는다. 상마다 새우젓과 부추, 고춧가루가 있어 각자 간을 맞춘다. 부산을 정의하는 음식이다.","ingredients":["돼지뼈","수육","밥","부추","새우젓"],"flavor":"구수하고 깊으며 간은 취향대로","bestTime":"연중"},"ja":{"name":"釜山テジクッパ","summary":"乳白色の豚骨スープにご飯を入れ、アミの塩辛とにらで自分好みに味を調える。","story":"朝鮮戦争のとき釜山に集まった避難民が、最も安かった豚骨で汁を炊いた。何時間も煮て乳白色になった汁にご飯を入れ、薄切りのゆで豚をのせる。卓ごとにアミの塩辛、刻みにら、粉唐辛子があり、各自で味を決める。釜山を定義する一杯だ。","ingredients":["豚骨","ゆで豚","ご飯","刻みにら","アミの塩辛"],"flavor":"こくがあり滋味深い。味付けは好みで","bestTime":"通年"},"zh":{"name":"釜山豬肉湯飯","summary":"乳白豬骨湯澆飯，在桌邊以蝦醬與韭菜自行調味——難民歲月的菜。","story":"韓戰期間，難民湧入釜山，用最便宜的豬骨熬湯。湯要煮上數小時直到轉為乳白，澆在飯上再鋪幾片水煮豬肉。每桌都備有蝦醬、切碎的韭菜與辣椒粉，讓人自己調味。這道菜定義了釜山。","ingredients":["豬骨","水煮豬肉","白飯","韭菜末","蝦醬"],"flavor":"醇厚鮮美，鹹淡自訂","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-milmyeon', 'kr-milmyeon', 'Mì lạnh bột mì Busan (milmyeon)', 'Busan Milmyeon', '🥶', 'Phiên bản Busan của mì lạnh: sợi bột mì mềm hơn, nước dùng ngọt hơn, đá bào phủ trên.', 'Người tị nạn miền Bắc mang theo món naengmyeon làm từ kiều mạch, nhưng ở Busan thời chiến chỉ có bột mì viện trợ, nên họ làm sợi bằng bột mì — milmyeon ra đời từ đó. Nước dùng ninh xương pha thuốc bắc, uống ngọt và thơm, chan đá bào; ăn kèm tương ớt trộn và một lát thịt luộc.', 'busan', '["busan"]', '["Sợi bột mì","Nước dùng xương","Đá bào","Dưa chuột","Tương ớt trộn"]', 'Ngọt mát, cay nhẹ', 'Mùa hè', '["noodle"]', 0, '{"en":{"name":"Busan milmyeon (cold wheat noodles)","summary":"Busan''s take on cold noodles: softer wheat strands, a sweeter broth, shaved ice on top.","story":"Refugees from the north brought naengmyeon made with buckwheat, but wartime Busan only had aid wheat flour, so they made the noodles from that — and milmyeon was born. The broth is simmered from bones with medicinal herbs, sweet and fragrant, served with shaved ice, a spoon of chilli paste and a slice of boiled pork.","ingredients":["Wheat noodles","Bone broth","Shaved ice","Cucumber","Chilli paste"],"flavor":"Sweet, cooling, gently spicy","bestTime":"Summer"},"ko":{"name":"부산 밀면","summary":"부산식 냉면. 밀가루 면은 더 부드럽고 육수는 더 달며 살얼음을 얹는다.","story":"이북에서 온 피란민이 메밀 냉면을 만들려 했지만 전시의 부산에는 원조 밀가루뿐이라 밀로 면을 뽑았고, 그렇게 밀면이 생겼다. 사골에 한약재를 넣어 낸 육수는 달고 향이 있으며, 살얼음과 양념장, 수육 한 점을 올린다.","ingredients":["밀면","사골 육수","살얼음","오이","양념장"],"flavor":"달고 시원하며 살짝 맵다","bestTime":"여름"},"ja":{"name":"釜山ミルミョン","summary":"釜山式の冷麺。小麦の麺は柔らかく、出汁は甘く、削り氷がのる。","story":"北から来た避難民は蕎麦の冷麺を作ろうとしたが、戦時の釜山には援助の小麦粉しかなく、小麦で麺を打った。そうしてミルミョンが生まれた。骨と漢方素材で取った出汁は甘く香り高く、削り氷とヤンニョム、ゆで豚を添える。","ingredients":["小麦の麺","骨の出汁","削り氷","きゅうり","ヤンニョム"],"flavor":"甘く涼やかで、ほのかに辛い","bestTime":"夏"},"zh":{"name":"釜山小麥冷麵","summary":"釜山版的冷麵：麥麵更軟、湯頭更甜，上頭覆著碎冰。","story":"北方來的難民原想做蕎麥冷麵，但戰時釜山只有援助麵粉，於是用小麥做麵，milmyeon就此誕生。湯以骨頭加中藥材熬煮，甜而芳香，佐以碎冰、一匙辣醬和一片水煮豬肉。","ingredients":["小麥麵","骨湯","碎冰","小黃瓜","辣醬"],"flavor":"清甜冰涼，微辣","bestTime":"夏季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-eomuk', 'kr-eomuk', 'Chả cá Busan (eomuk)', 'Busan Fish Cake', '🍢', 'Chả cá xiên que nhúng nước dùng nóng — món ăn vặt mùa đông của cả nước, gốc từ Busan.', 'Busan là cảng cá lớn nhất, nên chả cá ở đây làm từ cá tươi với tỷ lệ bột thấp, dai và ngọt hơn. Ở chợ và quầy đường phố, chả cá xiên que ngâm trong nồi nước dùng củ cải nóng; khách ăn xong tự rót một cốc nước dùng uống cho ấm. Các thương hiệu eomuk Busan nay bán khắp Hàn Quốc.', 'busan', '["busan","ulsan"]', '["Cá xay","Bột","Củ cải","Rong biển","Nước tương chấm"]', 'Ngọt cá, mặn nhẹ', 'Mùa đông', '["street","seafood"]', 0, '{"en":{"name":"Busan fish cake","summary":"Fish cake on skewers dipped in hot broth — a winter snack nationwide, originally from Busan.","story":"Busan is Korea''s largest fishing port, so its fish cake carries more fish and less flour, springier and sweeter than elsewhere. At markets and street stalls the skewers sit in a pot of hot radish broth; when you finish, you pour yourself a cup of the broth to warm up. Busan''s fish cake brands are now sold across the country.","ingredients":["Minced fish","Flour","Radish","Kelp","Soy dipping sauce"],"flavor":"Sweet with fish, lightly salty","bestTime":"Winter"},"ko":{"name":"부산 어묵","summary":"꼬치 어묵을 뜨거운 국물에 담가 먹는 겨울 간식. 부산이 원조다.","story":"부산은 최대의 어항이라 어묵에 생선 비율이 높아 더 쫄깃하고 달다. 시장과 노점에서는 무 국물에 꼬치를 담가 두고, 다 먹으면 국물을 한 컵 따라 마신다. 부산의 어묵 브랜드는 이제 전국에서 판다.","ingredients":["생선살","밀가루","무","다시마","간장"],"flavor":"생선 맛이 달고 짭짤하다","bestTime":"겨울"},"ja":{"name":"釜山おでん（オムク）","summary":"串の練り物を熱い出汁に浸して食べる冬の定番。発祥は釜山。","story":"釜山は最大の漁港なので、練り物の魚の比率が高く、弾力があって甘い。市場や屋台では大根の出汁に串が浸けてあり、食べ終わると自分で汁を一杯注いで飲む。釜山のオムクのブランドは今や全国で売られている。","ingredients":["魚のすり身","小麦粉","大根","昆布","つけ醤油"],"flavor":"魚の甘みと軽い塩気","bestTime":"冬"},"zh":{"name":"釜山魚糕","summary":"串起的魚糕浸在熱湯裡——全國的冬日小吃，發源自釜山。","story":"釜山是韓國最大的漁港，魚糕的魚肉比例高、澱粉少，因此更彈更甜。市場與路邊攤把魚糕串泡在蘿蔔高湯裡，吃完自己倒一杯湯暖身。釜山的魚糕品牌如今行銷全國。","ingredients":["魚漿","麵粉","白蘿蔔","海帶","沾醬油"],"flavor":"魚鮮微鹹","bestTime":"冬季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-ssiat-hotteok', 'kr-ssiat-hotteok', 'Bánh rán nhân hạt Busan (ssiat-hotteok)', 'Busan Seed Hotteok', '🥞', 'Bánh rán đường mật rạch đôi rồi nhồi đầy hạt hướng dương, hạt bí và lạc.', 'Hotteok là bánh rán nhân đường mật phổ biến khắp Hàn Quốc mùa đông, nhưng ở chợ Gukje Busan người ta thêm một bước: bánh vừa rán xong được kéo ra, rạch một đường rồi xúc đầy hạt rang vào bên trong. Cắn một miếng là vừa nóng chảy đường mật vừa giòn bùi hạt.', 'busan', '["busan"]', '["Bột mì","Đường nâu","Quế","Hạt hướng dương","Hạt bí, lạc"]', 'Ngọt nóng, bùi giòn', 'Mùa đông', '["street","dessert"]', 0, '{"en":{"name":"Busan seed hotteok","summary":"A syrup-filled fried pancake, split open and packed with sunflower, pumpkin seeds and peanuts.","story":"Hotteok — a fried pancake filled with brown sugar syrup — is winter food all over Korea, but at Busan''s Gukje Market they add one step: the pancake is pulled from the oil, slit open and stuffed full of roasted seeds. One bite gives you molten syrup and crunchy nuts at the same time.","ingredients":["Wheat flour","Brown sugar","Cinnamon","Sunflower seeds","Pumpkin seeds and peanuts"],"flavor":"Hot and sweet, crunchy and nutty","bestTime":"Winter"},"ko":{"name":"부산 씨앗호떡","summary":"설탕 호떡을 갈라 해바라기씨와 호박씨, 땅콩을 가득 채운다.","story":"호떡은 전국의 겨울 간식이지만 부산 국제시장에서는 한 단계를 더한다. 갓 튀긴 호떡을 꺼내 반을 가르고 볶은 씨앗을 가득 퍼 넣는다. 한 입에 녹은 흑설탕과 고소한 씨앗이 함께 온다.","ingredients":["밀가루","흑설탕","계피","해바라기씨","호박씨와 땅콩"],"flavor":"뜨겁고 달며 고소하고 바삭하다","bestTime":"겨울"},"ja":{"name":"釜山シアッホットク","summary":"黒糖ホットクを割って、ひまわりの種やかぼちゃの種、落花生を詰める。","story":"ホットクは全国の冬の菓子だが、釜山の国際市場ではもうひと手間かける。揚げたてを取り出して切れ目を入れ、炒った種をたっぷり詰めるのだ。一口で、溶けた黒糖と香ばしい種が同時に来る。","ingredients":["小麦粉","黒糖","シナモン","ひまわりの種","かぼちゃの種と落花生"],"flavor":"熱くて甘く、香ばしくてさくさく","bestTime":"冬"},"zh":{"name":"釜山堅果糖餅","summary":"糖漿糖餅剖開後，塞滿葵花子、南瓜子與花生。","story":"糖餅是全韓國的冬日點心，但釜山國際市場多做一步：剛炸好的餅拿出來剖開，塞進滿滿的烤堅果。一口下去，融化的黑糖與香脆的堅果同時到來。","ingredients":["麵粉","黑糖","肉桂","葵花子","南瓜子與花生"],"flavor":"燙口香甜，堅果酥香","bestTime":"冬季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-eonyang-bulgogi', 'kr-eonyang-bulgogi', 'Bulgogi Eonyang (Ulsan)', 'Eonyang Bulgogi', '🥩', 'Thịt bò băm thô ép thành miếng, nướng vỉ trên than — kiểu bulgogi riêng của Ulsan.', 'Ở Eonyang, bò được nuôi trong vùng và thịt được băm thô rồi ép lại thành miếng tròn, ướp nhẹ, nướng trên vỉ than chứ không xào nước như bulgogi Seoul. Cách làm này giữ được nước ngọt của thịt và cho lớp cháy cạnh thơm. Ăn cuốn rau sống với tương ssamjang.', 'ulsan', '["ulsan"]', '["Thịt bò băm thô","Nước tương","Tỏi","Đường","Rau cuốn"]', 'Ngọt thịt, khói than', 'Quanh năm', '[]', 1, '{"en":{"name":"Eonyang bulgogi (Ulsan)","summary":"Coarsely minced beef pressed into patties and grilled over charcoal — Ulsan''s own style of bulgogi.","story":"In Eonyang the cattle are raised locally, and the beef is coarsely minced, pressed into rounds, lightly seasoned and grilled on a rack over charcoal rather than cooked in liquid like Seoul-style bulgogi. That method keeps the juice in the meat and gives a fragrant char. It is eaten wrapped in lettuce with ssamjang.","ingredients":["Coarsely minced beef","Soy sauce","Garlic","Sugar","Lettuce for wrapping"],"flavor":"Sweet with beef, smoky from the charcoal","bestTime":"Year-round"},"ko":{"name":"언양불고기(울산)","summary":"굵게 다진 소고기를 뭉쳐 석쇠에 숯불로 굽는 울산식 불고기.","story":"언양은 소를 직접 길렀고, 고기를 굵게 다져 동그랗게 뭉친 뒤 가볍게 양념해 국물 없이 석쇠에 굽는다. 그래야 육즙이 남고 겉이 고소하게 그을린다. 상추에 쌈장을 얹어 싸 먹는다.","ingredients":["굵게 다진 소고기","간장","마늘","설탕","쌈 채소"],"flavor":"고기 맛이 달고 숯향이 난다","bestTime":"연중"},"ja":{"name":"彦陽プルコギ（蔚山）","summary":"粗く刻んだ牛肉を丸めて網にのせ、炭火で焼く蔚山式のプルコギ。","story":"彦陽では牛を地元で育て、肉を粗く刻んで丸く固め、軽く味を付けて、汁気のあるソウル式とは違い網にのせて炭火で焼く。そうすると肉汁が残り、表面が香ばしく焦げる。サンチュにサムジャンを添えて包んで食べる。","ingredients":["粗挽き牛肉","醤油","にんにく","砂糖","包み野菜"],"flavor":"肉の甘みと炭の香り","bestTime":"通年"},"zh":{"name":"彥陽烤肉（蔚山）","summary":"粗絞牛肉壓成肉餅在炭火上炙烤——蔚山自成一格的烤肉。","story":"彥陽的牛在當地飼養，牛肉粗絞後壓成圓餅、輕微調味，放在網架上以炭火烤，而不像首爾式烤肉那樣帶湯汁烹煮。這種做法把肉汁留在肉裡，表面帶著香氣的焦邊。以生菜包著沾醬吃。","ingredients":["粗絞牛肉","醬油","大蒜","糖","包菜生菜"],"flavor":"肉甜且帶炭火香","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-mulhoe', 'kr-mulhoe', 'Gỏi cá nước lạnh (mulhoe)', 'Mulhoe (cold raw fish soup)', '🧊', 'Cá sống thái sợi chan nước dùng lạnh chua cay, húp như canh giữa ngày hè.', 'Ngư dân bờ biển đông nghĩ ra món này để ăn nhanh trên thuyền: cá sống thái sợi trộn rau, thả vào nước đá pha tương ớt và giấm. Vị chua cay lạnh buốt làm dịu cái nóng, và cuối bát người ta cho thêm bún hoặc cơm. Ulsan và Pohang là hai nơi làm mulhoe nổi tiếng nhất.', 'ulsan', '["ulsan","gyeongbuk"]', '["Cá sống thái sợi","Nước đá","Tương ớt","Giấm","Rau thái sợi"]', 'Chua cay, lạnh, tươi', 'Mùa hè', '["seafood"]', 0, '{"en":{"name":"Mulhoe (cold raw fish soup)","summary":"Slivers of raw fish in an ice-cold sweet-sour broth, drunk like soup on a hot day.","story":"Fishermen on the east coast invented this to eat quickly on the boat: raw fish sliced thin, tossed with vegetables and dropped into iced water spiked with chilli paste and vinegar. The sour, icy heat cuts the summer, and at the end you add noodles or rice to the bowl. Ulsan and Pohang are the two places best known for it.","ingredients":["Sliced raw fish","Iced water","Chilli paste","Vinegar","Shredded vegetables"],"flavor":"Sour, spicy, icy and fresh","bestTime":"Summer"},"ko":{"name":"물회","summary":"채 썬 생선회를 얼음 육수에 넣어 국처럼 마시는 여름 음식.","story":"동해 어부들이 배 위에서 빨리 먹으려 만든 음식이다. 생선을 채 썰어 채소와 섞고 고추장과 식초를 푼 얼음물에 넣는다. 새콤하고 차가운 맛이 더위를 식히고, 마지막에는 국수나 밥을 말아 먹는다. 울산과 포항이 가장 유명하다.","ingredients":["채 썬 생선회","얼음물","고추장","식초","채 썬 채소"],"flavor":"새콤하고 맵고 차갑다","bestTime":"여름"},"ja":{"name":"ムルフェ（冷たい刺身スープ）","summary":"細切りの刺身を氷の出汁に入れ、汁のようにすする夏の一品。","story":"東海の漁師が船上で手早く食べるために考えた。刺身を細く切って野菜と和え、コチュジャンと酢を溶いた氷水に入れる。酸味と冷たさが暑さを鎮め、最後は麺かご飯を入れる。蔚山と浦項が特に名高い。","ingredients":["細切りの刺身","氷水","コチュジャン","酢","千切り野菜"],"flavor":"酸味と辛味、氷のように冷たい","bestTime":"夏"},"zh":{"name":"水膾（冰鎮生魚湯）","summary":"生魚切絲泡在酸辣冰湯裡，像湯一樣喝下的消暑料理。","story":"東海岸漁民為了在船上快速進食而發明：生魚切絲拌上蔬菜，倒進加了辣椒醬與醋的冰水。酸冽的冰涼壓下暑氣，最後再加入麵條或飯。蔚山與浦項是最有名的兩地。","ingredients":["生魚絲","冰水","辣椒醬","醋","蔬菜絲"],"flavor":"酸辣冰涼，鮮爽","bestTime":"夏季"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-chungmu-gimbap', 'kr-chungmu-gimbap', 'Kimbap Chungmu (Tongyeong)', 'Chungmu Gimbap', '🍙', 'Cuộn cơm trắng không nhân, ăn kèm mực trộn cay và kimchi củ cải riêng ngoài.', 'Ngư dân Tongyeong (tên cũ là Chungmu) mang cơm nắm ra khơi, nhưng cuộn có nhân thì nhanh ôi dưới nắng. Giải pháp: cuộn cơm trắng không nhân, còn mực trộn cay và kimchi củ cải để riêng, ăn tới đâu gắp tới đó. Món ăn thực dụng ấy nay thành đặc sản bán khắp bến cảng.', 'gyeongnam', '["gyeongnam"]', '["Cơm trắng","Rong biển","Mực trộn cay","Kimchi củ cải","Chả cá"]', 'Nhẹ, cay chua đi kèm', 'Quanh năm', '["rice","street"]', 1, '{"en":{"name":"Chungmu gimbap (Tongyeong)","summary":"Plain rice rolls served with spicy squid and radish kimchi on the side.","story":"Fishermen from Tongyeong (formerly Chungmu) took rice rolls to sea, but filled rolls spoiled quickly in the sun. The solution: roll the rice plain and keep the spicy squid and radish kimchi separate, picking them up as you eat. That practical fix became the local speciality, sold all along the harbour.","ingredients":["Plain rice","Seaweed","Spicy squid","Radish kimchi","Fish cake"],"flavor":"Mild rice with sharp, spicy sides","bestTime":"Year-round"},"ko":{"name":"충무김밥(통영)","summary":"속이 없는 흰밥 김밥에 매운 오징어무침과 무김치를 따로 곁들인다.","story":"통영(옛 충무) 어부들이 김밥을 배에 가져갔지만 속을 넣으면 볕에 쉬이 상했다. 그래서 밥만 말고 오징어무침과 무김치를 따로 담아 먹을 때마다 곁들였다. 그 실용적인 해법이 지금은 항구 곳곳에서 파는 명물이 되었다.","ingredients":["흰밥","김","오징어무침","무김치","어묵"],"flavor":"담백한 밥에 맵고 새콤한 반찬","bestTime":"연중"},"ja":{"name":"忠武キンパ（統営）","summary":"具のない白飯の海苔巻きに、辛いイカの和え物と大根キムチを別添えで。","story":"統営（旧・忠武）の漁師は海苔巻きを船に持ち込んだが、具入りは日差しですぐ傷んだ。そこで飯だけを巻き、辛いイカと大根キムチを別にして食べる時に合わせた。その実用の工夫が今では港のあちこちで売られる名物になった。","ingredients":["白飯","海苔","辛いイカの和え物","大根キムチ","練り物"],"flavor":"淡白な飯に辛く酸味のある副菜","bestTime":"通年"},"zh":{"name":"忠武紫菜飯捲（統營）","summary":"不包餡的白飯飯捲，另附辣拌魷魚與蘿蔔泡菜。","story":"統營（舊稱忠武）的漁民把飯捲帶上船，但包了餡的在日曬下很快壞掉。解法是：只捲白飯，辣拌魷魚與蘿蔔泡菜分開放，吃時再配。這個務實的辦法成了當地名物，沿著港邊到處都賣。","ingredients":["白飯","海苔","辣拌魷魚","蘿蔔泡菜","魚板"],"flavor":"清淡米飯配辛辣配菜","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-jinju-bibimbap', 'kr-jinju-bibimbap', 'Bibimbap Jinju (hwabanban)', 'Jinju Bibimbap', '🌸', 'Cơm trộn kiểu Jinju với thịt bò sống, rau theo mùa và canh sò ăn kèm.', 'Bản Jinju được gọi là ''hwaban'' — mâm hoa — vì rau được xếp thành vòng nhiều màu quanh tô. Khác Jeonju, ở đây có thịt bò sống trộn dầu mè đặt giữa và luôn dọn kèm một bát canh sò nhỏ. Tương truyền món này bắt nguồn từ bữa ăn của quân sĩ giữ thành Jinju thời chiến.', 'gyeongnam', '["gyeongnam"]', '["Cơm","Thịt bò sống","Rau theo mùa","Canh sò","Tương ớt"]', 'Tươi, thanh, thơm dầu mè', 'Bữa trưa', '["rice"]', 0, '{"en":{"name":"Jinju bibimbap (hwaban)","summary":"The Jinju version, with raw beef, seasonal greens and a small clam soup on the side.","story":"The Jinju bowl is called ''hwaban'' — flower rice — because the vegetables are arranged in a coloured ring. Unlike Jeonju, it carries raw beef dressed in sesame oil in the centre and always comes with a small bowl of clam soup. Tradition holds that the dish descends from the meals of the soldiers defending Jinju fortress.","ingredients":["Rice","Raw beef","Seasonal greens","Clam soup","Gochujang"],"flavor":"Fresh and clean, fragrant with sesame","bestTime":"Lunch"},"ko":{"name":"진주비빔밥(화반)","summary":"육회와 제철 나물을 올리고 조갯국을 곁들이는 진주식 비빔밥.","story":"진주 것은 나물을 색색으로 둘러 담아 ''화반'', 꽃밥이라 부른다. 전주와 달리 가운데에 참기름에 무친 육회가 놓이고 늘 작은 조갯국이 함께 나온다. 진주성을 지키던 군사들의 밥에서 비롯되었다는 이야기가 전한다.","ingredients":["밥","육회","제철 나물","조갯국","고추장"],"flavor":"신선하고 담백하며 고소하다","bestTime":"점심"},"ja":{"name":"晋州ビビンバ（花飯）","summary":"牛刺しと季節の山菜をのせ、小さな貝の汁を添える晋州式。","story":"晋州のものは野菜を彩りよく輪に並べるので「花飯」と呼ばれる。全州と違い中央にごま油で和えた牛刺しが置かれ、必ず小さな貝の汁が付く。晋州城を守った兵たちの食事に由来するとも言われる。","ingredients":["ご飯","牛刺し","季節の山菜","貝の汁","コチュジャン"],"flavor":"新鮮で淡白、ごまが香る","bestTime":"昼食"},"zh":{"name":"晉州拌飯（花飯）","summary":"晉州版本，配生牛肉與時令野菜，另附一小碗蛤蜊湯。","story":"晉州的這一碗被稱作「花飯」，因為蔬菜排成彩色的環。與全州不同，它中央放的是麻油拌過的生牛肉，而且一定附上一小碗蛤蜊湯。相傳這道菜源自守衛晉州城的士兵的伙食。","ingredients":["白飯","生牛肉","時令野菜","蛤蜊湯","辣椒醬"],"flavor":"清爽鮮甜，麻油生香","bestTime":"午餐"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-tongyeong-gul', 'kr-tongyeong-gul', 'Hàu Tongyeong', 'Tongyeong Oysters', '🦪', 'Hàu nuôi trên vịnh kín gió, ăn sống, nướng, hoặc nấu cơm nồi đá.', 'Vùng biển quanh Tongyeong nhiều đảo che chắn nên nước lặng, là nơi nuôi hàu lớn nhất Hàn Quốc. Mùa lạnh, hàu béo và ngọt nhất: ăn sống chấm nước tương giấm, nướng cả vỏ trên than, hoặc nấu cùng cơm trong nồi đá. Chợ Jungang Tongyeong bán hàu tươi từ sáng sớm.', 'gyeongnam', '["gyeongnam"]', '["Hàu tươi","Nước tương giấm","Cơm","Rong biển","Tỏi"]', 'Ngọt biển, béo nhẹ', 'Tháng 11–3', '["seafood"]', 0, '{"en":{"name":"Tongyeong oysters","summary":"Oysters farmed in a sheltered bay — eaten raw, grilled, or cooked into stone-pot rice.","story":"The waters around Tongyeong are shielded by islands, so the sea stays calm — this is the largest oyster-farming area in Korea. In the cold months the oysters are at their fattest and sweetest: eaten raw with vinegared soy, grilled in the shell over charcoal, or cooked with rice in a stone pot. Tongyeong''s Jungang market sells them fresh from early morning.","ingredients":["Fresh oysters","Vinegared soy sauce","Rice","Seaweed","Garlic"],"flavor":"Sweet with the sea, lightly rich","bestTime":"November–March"},"ko":{"name":"통영 굴","summary":"잔잔한 만에서 기른 굴을 생으로, 구이로, 돌솥밥으로 먹는다.","story":"통영 앞바다는 섬이 많아 물결이 잔잔해 한국 최대의 굴 양식지다. 추운 계절 굴이 가장 살지고 달다. 초간장에 찍어 생으로 먹거나 껍데기째 숯불에 굽고, 돌솥에 밥을 지어 먹는다. 통영 중앙시장에서는 이른 아침부터 생굴을 판다.","ingredients":["생굴","초간장","쌀","김","마늘"],"flavor":"바다의 단맛과 은은한 고소함","bestTime":"11~3월"},"ja":{"name":"統営のカキ","summary":"穏やかな湾で育てたカキを、生で、焼いて、石鍋ご飯で。","story":"統営の周りの海は島に守られて波が穏やかで、韓国最大のカキ養殖地だ。寒い季節にカキは最も肥えて甘くなる。酢醤油で生のまま、殻ごと炭で焼いて、あるいは石鍋でご飯と炊く。統営の中央市場では早朝から生ガキが並ぶ。","ingredients":["生カキ","酢醤油","米","海苔","にんにく"],"flavor":"海の甘みと軽いこく","bestTime":"11〜3月"},"zh":{"name":"統營生蠔","summary":"在避風海灣養殖的牡蠣——生食、炭烤，或做成石鍋飯。","story":"統營周邊海域有島嶼屏障、水面平穩，是韓國最大的牡蠣養殖區。天冷時牡蠣最肥美：沾醋醬油生食、連殼炭烤，或與米一同放進石鍋炊煮。統營中央市場一早就開始賣現剝的生蠔。","ingredients":["鮮牡蠣","醋醬油","白米","海苔","大蒜"],"flavor":"海味清甜，微帶醇厚","bestTime":"11月至3月"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-jeju-heukdwaeji', 'kr-jeju-heukdwaeji', 'Heo đen Jeju nướng', 'Jeju Black Pork BBQ', '🐖', 'Thịt heo đen bản địa nướng than, chấm muối mắm cá cơm đun nóng.', 'Heo đen là giống bản địa Jeju, nuôi lâu hơn heo thường nên thịt chắc, mỡ giòn và da dày ăn được. Miếng thịt được nướng dày trên than, cắt bằng kéo tại bàn, chấm melchijeot — nước mắm cá cơm đun sôi lăn tăn ngay cạnh vỉ nướng. Cuốn cùng lá vừng và tỏi nướng.', 'jeju', '["jeju"]', '["Thịt heo đen","Mắm cá cơm melchijeot","Lá vừng","Tỏi","Hành trộn"]', 'Béo giòn, mặn đậm', 'Quanh năm', '[]', 1, '{"en":{"name":"Jeju black pork","summary":"Native black pork grilled over charcoal, dipped in warm anchovy sauce.","story":"Black pigs are the island''s native breed, raised longer than ordinary pigs, so the meat is firm, the fat crisp and even the skin is eaten. The cuts are grilled thick over charcoal, snipped with scissors at the table, and dipped in melchijeot — anchovy sauce kept simmering right beside the grill. Wrap it with perilla leaves and roasted garlic.","ingredients":["Black pork","Melchijeot anchovy sauce","Perilla leaves","Garlic","Spring onion salad"],"flavor":"Rich and crisp, deeply savoury","bestTime":"Year-round"},"ko":{"name":"제주 흑돼지","summary":"제주 재래 흑돼지를 숯불에 구워 뜨거운 멜젓에 찍어 먹는다.","story":"흑돼지는 제주 재래종으로 일반 돼지보다 오래 길러 살이 단단하고 비계가 바삭하며 껍질까지 먹는다. 두툼하게 썰어 숯불에 굽고 가위로 잘라, 불판 옆에서 자글자글 끓는 멜젓에 찍는다. 깻잎과 구운 마늘을 곁들여 싼다.","ingredients":["흑돼지","멜젓","깻잎","마늘","파채"],"flavor":"고소하고 바삭하며 짭짤하다","bestTime":"연중"},"ja":{"name":"済州の黒豚","summary":"在来の黒豚を炭火で焼き、温かいアミの魚醤に付けて食べる。","story":"黒豚は済州の在来種で、普通の豚より長く育てるため肉が締まり、脂はさくっとして皮まで食べられる。厚めに切って炭火で焼き、卓上でハサミで切り、焼き網の脇でふつふつ煮えるメルジョッ（カタクチイワシの魚醤）に付ける。えごまの葉と焼きにんにくで包む。","ingredients":["黒豚","メルジョッ","えごまの葉","にんにく","ねぎの和え物"],"flavor":"こくがあり香ばしく、塩気が効く","bestTime":"通年"},"zh":{"name":"濟州黑豬肉","summary":"本地黑豬以炭火燒烤，沾溫熱的鯷魚醬。","story":"黑豬是濟州的在地品種，飼養期比一般豬長，因此肉質緊實、油脂酥香，連皮都能吃。厚切後以炭火燒烤，在桌邊用剪刀剪開，沾在烤網旁一直滾著的melchijeot鯷魚醬。以紫蘇葉與烤蒜包著吃。","ingredients":["黑豬肉","鯷魚醬","紫蘇葉","大蒜","蔥絲沙拉"],"flavor":"濃郁酥香，鹹鮮下飯","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-jeonbok-juk', 'kr-jeonbok-juk', 'Cháo bào ngư Jeju (jeonbok-juk)', 'Jeju Abalone Porridge', '🥣', 'Cháo gạo nấu với bào ngư và gan bào ngư, có màu xanh lá đặc trưng.', 'Các haenyeo — thợ lặn nữ Jeju — lặn bắt bào ngư không dùng bình khí, và món cháo này là cách dùng trọn con bào ngư: thịt thái lát, gan nghiền vào cháo tạo màu xanh nhạt và vị biển đậm. Đây là món bồi bổ dọn cho người ốm, người già, và bữa sáng của khách du lịch trên đảo.', 'jeju', '["jeju"]', '["Bào ngư","Gạo","Dầu mè","Gan bào ngư","Muối"]', 'Béo dịu, đậm vị biển', 'Quanh năm', '["seafood","breakfast"]', 0, '{"en":{"name":"Jeju abalone porridge","summary":"Rice porridge cooked with abalone and its liver, which gives it a distinctive green tint.","story":"The haenyeo — Jeju''s women divers — collect abalone without air tanks, and this porridge uses the whole animal: the flesh sliced in, the liver stirred through to give the pale green colour and a deep taste of the sea. It is what you serve to the ill and the elderly, and what visitors eat for breakfast on the island.","ingredients":["Abalone","Rice","Sesame oil","Abalone liver","Salt"],"flavor":"Gently rich, deeply of the sea","bestTime":"Year-round"},"ko":{"name":"제주 전복죽","summary":"전복과 내장을 넣어 연둣빛이 도는 쌀죽.","story":"해녀들은 산소통 없이 물질로 전복을 캔다. 이 죽은 전복을 통째로 쓴다. 살은 썰어 넣고 내장을 으깨 넣어 연한 초록빛과 진한 바다 맛을 낸다. 아픈 사람과 어르신에게 내는 보양식이고, 섬을 찾은 이들의 아침 식사이기도 하다.","ingredients":["전복","쌀","참기름","전복 내장","소금"],"flavor":"부드럽고 고소하며 바다 맛이 깊다","bestTime":"연중"},"ja":{"name":"済州のアワビ粥","summary":"アワビと肝で炊いた、淡い緑を帯びた米の粥。","story":"海女は空気ボンベなしで潜ってアワビを採る。この粥はアワビを丸ごと使う。身は切って入れ、肝を溶き入れて淡い緑色と濃い海の味を出す。病人や年配の方に供する滋養食であり、島を訪れた人の朝食でもある。","ingredients":["アワビ","米","ごま油","アワビの肝","塩"],"flavor":"やわらかくこくがあり、海の味が深い","bestTime":"通年"},"zh":{"name":"濟州鮑魚粥","summary":"以鮑魚與其內臟熬煮的米粥，帶著獨特的淡綠色。","story":"海女不帶氧氣瓶下潛採鮑，而這碗粥用上整隻鮑魚：肉切片入粥，內臟拌入使粥呈淡綠並帶著濃厚的海味。這是給病人與長輩的補品，也是旅人在島上的早餐。","ingredients":["鮑魚","白米","麻油","鮑魚內臟","鹽"],"flavor":"溫潤醇厚，海味深沉","bestTime":"全年"}}', 'kr');
INSERT OR REPLACE INTO dishes (id, slug, name, name_en, emoji, summary, story, origin_province, province_slugs, ingredients, flavor, best_time, tags, featured, i18n, country) VALUES ('kr-galchi-jorim', 'kr-galchi-jorim', 'Cá hố kho Jeju (galchi-jorim)', 'Jeju Braised Cutlassfish', '🐠', 'Cá hố bạc kho cay với củ cải và bí — món cá điển hình của bàn ăn Jeju.', 'Cá hố đánh bắt quanh Jeju to và dày thịt hơn nơi khác. Khúc cá được kho trong nồi cùng củ cải, bí ngòi, bột ớt và nước tương cho tới khi củ cải ngấm hết vị cá. Ở các quán ven biển phía nam đảo, một nồi galchi-jorim dọn kèm cơm và chục món phụ là bữa trưa chuẩn mực.', 'jeju', '["jeju"]', '["Cá hố","Củ cải","Bột ớt","Nước tương","Ớt xanh"]', 'Cay mặn, ngọt cá', 'Tháng 9–12', '["seafood","spicy"]', 0, '{"en":{"name":"Jeju braised cutlassfish","summary":"Silver cutlassfish braised with radish and courgette in chilli — the classic Jeju fish dish.","story":"Cutlassfish caught around Jeju is larger and meatier than elsewhere. The steaks are braised in a pot with radish, courgette, chilli flakes and soy until the radish has taken on all the flavour of the fish. At restaurants along the island''s south coast, a pot of galchi-jorim with rice and a dozen side dishes is the standard lunch.","ingredients":["Cutlassfish","Radish","Chilli flakes","Soy sauce","Green chilli"],"flavor":"Spicy and savoury, sweet with fish","bestTime":"September–December"},"ko":{"name":"제주 갈치조림","summary":"은빛 갈치를 무와 호박을 넣어 맵게 조린 제주 밥상의 대표 생선 요리.","story":"제주 근해 갈치는 크고 살이 두툼하다. 토막 낸 갈치를 무와 애호박, 고춧가루, 간장과 함께 조려 무에 생선 맛이 완전히 배게 한다. 섬 남쪽 해안의 식당에서 갈치조림 한 냄비에 밥과 반찬 열 가지가 나오면 그것이 표준 점심이다.","ingredients":["갈치","무","고춧가루","간장","풋고추"],"flavor":"맵고 짭짤하며 생선이 달다","bestTime":"9~12월"},"ja":{"name":"済州のタチウオの煮付け","summary":"銀色のタチウオを大根やズッキーニと辛く煮た、済州の定番の魚料理。","story":"済州近海のタチウオは大きく身が厚い。ぶつ切りを大根、ズッキーニ、粉唐辛子、醤油と煮て、大根に魚の味が完全に染みるまで火を通す。島の南の海沿いの食堂では、この鍋にご飯と十皿ほどのおかずが付くのが標準の昼食だ。","ingredients":["タチウオ","大根","粉唐辛子","醤油","青唐辛子"],"flavor":"辛く塩気があり、魚が甘い","bestTime":"9〜12月"},"zh":{"name":"濟州燉白帶魚","summary":"銀亮的白帶魚與白蘿蔔、櫛瓜同燉，是濟州餐桌的代表魚料理。","story":"濟州近海的白帶魚體型大、肉厚。切段後與白蘿蔔、櫛瓜、辣椒粉和醬油同燉，燉到蘿蔔完全吸收魚的味道。島南沿海的餐廳裡，一鍋燉白帶魚配飯與十來碟小菜，就是標準的午餐。","ingredients":["白帶魚","白蘿蔔","辣椒粉","醬油","青辣椒"],"flavor":"辣鹹並重，魚肉清甜","bestTime":"9至12月"}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-tosokchon', 'kr-samgyetang', 'Tosokchon Samgyetang', 'seoul', '5 Jahamun-ro 5-gil, Jongno-gu (gần Gyeongbokgung)', 126.9709, 37.5773, '20.000–25.000 KRW', '10:00–22:00', '["local-favorite","atlas-pick"]', 90, '["Quán samgyetang được nhắc tới nhiều nhất Seoul, mở từ thập niên 1980","Ngay cạnh cung Gyeongbokgung — ghép rất gọn vào buổi sáng tham quan","Hàng dài nhưng bàn xoay nhanh, chờ trung bình 15–30 phút"]', '{"en":{"name":"Tosokchon Samgyetang","address":"5 Jahamun-ro 5-gil, Jongno-gu (near Gyeongbokgung)","reasons":["The most talked-about samgyetang house in Seoul, open since the 1980s","Right beside Gyeongbokgung — slots neatly into a morning of sightseeing","Long queue but fast turnover; typically 15–30 minutes"]},"ko":{"name":"토속촌 삼계탕","address":"서울 종로구 자하문로5길 5 (경복궁 인근)","reasons":["1980년대부터 이어온 서울에서 가장 유명한 삼계탕집","경복궁 바로 옆이라 오전 관람과 묶기 좋다","줄은 길지만 회전이 빨라 보통 15~30분"]},"ja":{"name":"土俗村 参鶏湯","address":"ソウル鍾路区紫霞門路5ギル5（景福宮の近く）","reasons":["1980年代から続く、ソウルで最も名高い参鶏湯の店","景福宮のすぐ隣で午前の観光と組みやすい","行列は長いが回転が速く、待ち時間は15〜30分ほど"]},"zh":{"name":"土俗村蔘雞湯","address":"首爾鍾路區紫霞門路5街5號（景福宮附近）","reasons":["1980年代營業至今，首爾最知名的蔘雞湯店","就在景福宮旁，適合接在上午遊覽之後","隊伍雖長但翻桌快，通常等15至30分鐘"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-sindang-tteokbokki-town', 'kr-tteokbokki', 'Phố tteokbokki Sindang', 'seoul', 'Sindang-dong, Jung-gu', 127.0176, 37.5657, '10.000–15.000 KRW', '11:00–22:00', '["street-food","local-favorite"]', 86, '["Nơi khai sinh tteokbokki sốt gochujang vào thập niên 1950","Cả một dãy phố cùng bán một món — dễ so sánh khẩu vị từng quán","Nồi nấu ngay tại bàn, gọi thêm mì và chả cá tuỳ ý"]', '{"en":{"name":"Sindang Tteokbokki Town","address":"Sindang-dong, Jung-gu","reasons":["Where gochujang tteokbokki was created in the 1950s","A whole street cooking one dish — easy to compare houses","Cooked at your table; add noodles and fish cake as you like"]},"ko":{"name":"신당동 떡볶이 골목","address":"서울 중구 신당동","reasons":["1950년대 고추장 떡볶이가 태어난 곳","한 골목에서 같은 음식을 비교해 먹을 수 있다","테이블에서 직접 끓이고 사리와 어묵을 추가할 수 있다"]},"ja":{"name":"新堂洞トッポッキ横丁","address":"ソウル中区新堂洞","reasons":["1950年代にコチュジャン味のトッポッキが生まれた場所","同じ料理を並べて食べ比べできる通り","卓上で煮ながら、麺や練り物を追加できる"]},"zh":{"name":"新堂洞辣炒年糕街","address":"首爾中區新堂洞","reasons":["1950年代辣椒醬炒年糕誕生的地方","一整條街做同一道菜，方便比較口味","在桌邊現煮，可加麵條與魚板"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-gonghwachun', 'kr-jjajangmyeon', 'Gonghwachun (Phố người Hoa)', 'incheon', '43 Chinatown-ro, Jung-gu, Incheon', 126.6175, 37.4742, '8.000–15.000 KRW', '11:00–21:00', '["atlas-pick","family"]', 88, '["Đứng ngay nơi món jjajangmyeon ra đời cuối thế kỷ 19","Bảo tàng Jjajangmyeon nằm sát bên, đi cùng một buổi rất hợp","Cách ga Incheon vài phút đi bộ, tiện cho chuyến trong ngày từ Seoul"]', '{"en":{"name":"Gonghwachun (Chinatown)","address":"43 Chinatown-ro, Jung-gu, Incheon","reasons":["Standing where jjajangmyeon was invented in the late 19th century","The Jjajangmyeon Museum is next door — pair them in one visit","Minutes from Incheon station, easy as a day trip from Seoul"]},"ko":{"name":"공화춘 (차이나타운)","address":"인천 중구 차이나타운로 43","reasons":["19세기 말 짜장면이 탄생한 자리","바로 옆 짜장면박물관과 함께 보기 좋다","인천역에서 도보 몇 분, 서울 당일치기로 충분"]},"ja":{"name":"共和春（チャイナタウン）","address":"仁川広域市中区チャイナタウン路43","reasons":["19世紀末にジャージャー麺が生まれた場所そのもの","隣のジャージャー麺博物館と一緒に回れる","仁川駅から徒歩数分、ソウルからの日帰りに最適"]},"zh":{"name":"共和春（中華街）","address":"仁川中區中華街路43號","reasons":["就站在十九世紀末炸醬麵誕生的位置","隔壁就是炸醬麵博物館，可一併參觀","距仁川站步行數分鐘，適合自首爾一日遊"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-chuncheon-myeongdong-dakgalbi', 'kr-dakgalbi', 'Phố dakgalbi Myeongdong Chuncheon', 'gangwon', 'Myeongdong-gil, Chuncheon', 127.7295, 37.8795, '14.000–18.000 KRW/người', '11:00–22:00', '["local-favorite","street-food"]', 89, '["Cả con phố chỉ bán dakgalbi — nơi món này thành danh từ thập niên 1960","Chảo xào ngay giữa bàn, kết thúc bằng cơm rang trên phần sốt còn lại","Đi tàu ITX từ Seoul tới Chuncheon chỉ hơn một giờ"]', '{"en":{"name":"Chuncheon Myeongdong Dakgalbi Street","address":"Myeongdong-gil, Chuncheon","reasons":["A whole street of dakgalbi, where the dish made its name in the 1960s","Stir-fried at your table and finished with fried rice in the sauce","Just over an hour from Seoul on the ITX train"]},"ko":{"name":"춘천 명동 닭갈비 골목","address":"강원 춘천시 명동길","reasons":["1960년대 닭갈비가 자리 잡은 골목 전체","테이블에서 볶아 마지막에 밥까지 볶아 먹는다","서울에서 ITX로 한 시간 남짓"]},"ja":{"name":"春川明洞タッカルビ通り","address":"江原道春川市明洞ギル","reasons":["1960年代にタッカルビが定着した通りそのもの","卓上で炒め、締めに残ったたれでご飯を炒める","ソウルからITXで1時間あまり"]},"zh":{"name":"春川明洞辣炒雞排街","address":"江原道春川市明洞街","reasons":["一整條街都是雞排，1960年代這道菜在此成名","在桌邊現炒，最後用剩醬炒飯收尾","自首爾搭ITX一小時多可達"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-sungsimdang', 'kr-sungsimdang-bread', 'Sungsimdang (tiệm chính)', 'daejeon', '15 Daejong-ro 480beon-gil, Jung-gu, Daejeon', 127.4272, 36.3277, '2.000–8.000 KRW/bánh', '08:00–22:00', '["atlas-pick","family"]', 91, '["Tiệm bánh mở từ 1956, biến Daejeon thành ''thành phố bánh mì''","Twigim-soboro và bánh nhân kem là hai món phải thử","Cách ga Daejeon khoảng 10 phút — hợp cho điểm dừng giữa hành trình KTX"]', '{"en":{"name":"Sungsimdang (main store)","address":"15 Daejong-ro 480beon-gil, Jung-gu, Daejeon","reasons":["Open since 1956; the bakery that made Daejeon the ''bread city''","Twigim-soboro and the cream pastry are the two to try","Ten minutes from Daejeon station — ideal for a KTX stopover"]},"ko":{"name":"성심당 본점","address":"대전 중구 대종로480번길 15","reasons":["1956년 문을 연, 대전을 ''빵의 도시''로 만든 빵집","튀김소보로와 생크림빵이 대표","대전역에서 10분, KTX 경유 코스로 최적"]},"ja":{"name":"聖心堂 本店","address":"大田広域市中区大宗路480番ギル15","reasons":["1956年開業、大田を「パンの街」にした店","トゥィギムソボロと生クリームパンが看板","大田駅から10分、KTX の乗り継ぎに最適"]},"zh":{"name":"聖心堂（本店）","address":"大田中區大宗路480號街15","reasons":["1956年開業，讓大田成為「麵包之城」的店","炸紅豆酥粒麵包與奶油夾心麵包最值得嘗","距大田站十分鐘，最適合KTX中途停留"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-gogung-jeonju', 'kr-jeonju-bibimbap', 'Gogung (làng hanok Jeonju)', 'jeonbuk', '63 Jeonjugaeksa 3-gil, Wansan-gu, Jeonju', 127.1425, 35.8195, '13.000–20.000 KRW', '10:30–21:30', '["atlas-pick","family"]', 89, '["Bibimbap dọn trong tô đồng đúng lối Jeonju, cơm nấu bằng nước hầm xương","Nằm ngay khu làng hanok, đi bộ được tới mọi điểm tham quan","Có suất chay và suất không cay cho khách nước ngoài"]', '{"en":{"name":"Gogung (Jeonju Hanok Village)","address":"63 Jeonjugaeksa 3-gil, Wansan-gu, Jeonju","reasons":["Bibimbap in a brass bowl, rice cooked in beef stock, the Jeonju way","Inside the hanok village, walkable to everything","Vegetarian and non-spicy versions available for visitors"]},"ko":{"name":"고궁 (전주한옥마을)","address":"전북 전주시 완산구 전주객사3길 63","reasons":["놋그릇에 담고 사골로 지은 밥, 전주식 비빔밥","한옥마을 안이라 도보 이동이 편하다","채식과 덜 매운 메뉴도 준비되어 있다"]},"ja":{"name":"古宮（全州韓屋村）","address":"全羅北道全州市完山区全州客舎3ギル63","reasons":["真鍮の器に牛骨で炊いたご飯、全州式のビビンバ","韓屋村の中にあり徒歩で回れる","ベジタリアン向け・辛くない仕立ても用意がある"]},"zh":{"name":"古宮（全州韓屋村）","address":"全羅北道全州市完山區全州客舍3街63號","reasons":["黃銅碗、牛骨高湯炊飯的正統全州拌飯","位在韓屋村內，步行即可逛遍周邊","備有素食與不辣的版本"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-ssangdungi-dwaeji-gukbap', 'kr-dwaeji-gukbap', 'Phố canh xương heo Seomyeon', 'busan', 'Seomyeon, Busanjin-gu, Busan', 129.0595, 35.1575, '9.000–12.000 KRW', '24 giờ (nhiều quán)', '["local-favorite","street-food"]', 90, '["Khu tập trung nhiều quán dwaeji-gukbap lâu năm nhất Busan","Nhiều quán mở suốt đêm — món giải rượu kinh điển của dân địa phương","Mỗi bàn có mắm tôm và hẹ để tự nêm theo khẩu vị"]', '{"en":{"name":"Seomyeon Pork Soup Rice Street","address":"Seomyeon, Busanjin-gu, Busan","reasons":["The densest cluster of long-running dwaeji-gukbap houses in Busan","Many open around the clock — the classic local hangover cure","Salted shrimp and chives on every table so you season it yourself"]},"ko":{"name":"서면 돼지국밥 골목","address":"부산 부산진구 서면","reasons":["부산에서 오래된 돼지국밥집이 가장 많이 모인 곳","24시간 영업하는 집이 많아 해장으로 제격","새우젓과 부추가 상마다 있어 취향대로 간을 맞춘다"]},"ja":{"name":"西面テジクッパ横丁","address":"釜山広域市釜山鎮区西面","reasons":["釜山で老舗のテジクッパ店が最も集まる一角","24時間営業の店が多く、締めや迎え酒に最適","アミの塩辛とにらが卓上にあり、味は自分で決める"]},"zh":{"name":"西面豬肉湯飯街","address":"釜山釜山鎮區西面","reasons":["釜山老字號豬肉湯飯最密集的一區","許多店24小時營業，是在地經典解酒餐","每桌備有蝦醬與韭菜，自行調味"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-samjin-eomuk', 'kr-eomuk', 'Samjin Eomuk (Yeongdo)', 'busan', '36 Taejong-ro 99beon-gil, Yeongdo-gu, Busan', 129.0435, 35.0905, '3.000–10.000 KRW', '09:00–19:00', '["atlas-pick","family"]', 87, '["Hãng chả cá lâu đời nhất Hàn Quốc, hoạt động từ năm 1953","Có bảo tàng nhỏ và lớp làm chả cá ngay tại xưởng","Chả cá nhiều loại ăn nóng tại chỗ, mua mang đi cũng tiện"]', '{"en":{"name":"Samjin Eomuk (Yeongdo)","address":"36 Taejong-ro 99beon-gil, Yeongdo-gu, Busan","reasons":["Korea''s oldest fish cake maker, in business since 1953","A small museum and fish-cake making classes at the factory","Many varieties to eat hot on the spot or take away"]},"ko":{"name":"삼진어묵 (영도)","address":"부산 영도구 태종로99번길 36","reasons":["1953년부터 이어온 한국에서 가장 오래된 어묵 회사","작은 박물관과 어묵 만들기 체험이 있다","즉석에서 먹거나 포장하기도 편하다"]},"ja":{"name":"三進オムク（影島）","address":"釜山広域市影島区太宗路99番ギル36","reasons":["1953年創業、韓国で最も古い練り物メーカー","小さな博物館と手作り体験教室がある","その場で温かく食べても持ち帰っても良い"]},"zh":{"name":"三進魚糕（影島）","address":"釜山影島區太宗路99號街36","reasons":["1953年創立，韓國歷史最久的魚糕品牌","設有小型博物館與手作體驗課","可現場趁熱吃，也方便外帶"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-andong-jjimdak-alley', 'kr-andong-jjimdak', 'Phố jjimdak chợ cũ Andong', 'gyeongbuk', 'Chợ Andong Gu, Andong', 128.7285, 36.5695, '30.000–45.000 KRW/chảo (2–3 người)', '11:00–21:00', '["local-favorite","family"]', 88, '["Nơi món jjimdak ra đời, cả dãy quán trong khu chợ cũ","Một chảo đủ cho 3 người — hợp đi nhóm","Ghép rất gọn với làng Hahoe và Dosan Seowon trong cùng ngày"]', '{"en":{"name":"Andong Old Market Jjimdak Alley","address":"Andong Gu Market, Andong","reasons":["The birthplace of jjimdak, a whole row of shops in the old market","One pan feeds three — good for groups","Fits neatly with Hahoe village and Dosan Seowon in one day"]},"ko":{"name":"안동 구시장 찜닭 골목","address":"경북 안동시 안동구시장","reasons":["찜닭이 태어난 구시장의 골목 전체","한 판이면 세 명이 먹어 단체 여행에 좋다","하회마을, 도산서원과 하루에 묶기 좋다"]},"ja":{"name":"安東旧市場チムタク横丁","address":"慶尚北道安東市安東旧市場","reasons":["チムタク発祥の旧市場、店が一列に並ぶ","一皿で三人前、グループ旅行に向く","河回村や陶山書院と同じ日に回りやすい"]},"zh":{"name":"安東舊市場燉雞街","address":"慶尚北道安東市安東舊市場","reasons":["燉雞的發源地，舊市場裡整排店家","一鍋足夠三人享用，適合團體","可與河回村、陶山書院安排在同一天"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-jeju-black-pork-street', 'kr-jeju-heukdwaeji', 'Phố heo đen Jeju (Geonip-dong)', 'jeju', 'Geonip-dong, thành phố Jeju', 126.5285, 33.5145, '18.000–25.000 KRW/phần', '12:00–23:00', '["local-favorite","atlas-pick"]', 88, '["Dãy quán chuyên heo đen bản địa, thịt cắt dày nướng than","Chấm melchijeot — mắm cá cơm đun nóng, cách ăn riêng của Jeju","Gần cảng và sân bay Jeju, tiện cho tối đầu tiên trên đảo"]', '{"en":{"name":"Jeju Black Pork Street (Geonip-dong)","address":"Geonip-dong, Jeju City","reasons":["A row of specialists in native black pork, thick-cut over charcoal","Dipped in melchijeot anchovy sauce — the Jeju way of eating it","Near the port and airport, easy for your first night on the island"]},"ko":{"name":"제주 흑돼지 거리 (건입동)","address":"제주시 건입동","reasons":["두툼하게 썰어 숯불에 굽는 흑돼지 전문점 거리","멜젓에 찍어 먹는 제주식 그대로","항구와 공항이 가까워 제주 첫날 저녁에 좋다"]},"ja":{"name":"済州 黒豚通り（健入洞）","address":"済州市健入洞","reasons":["在来黒豚を厚切りで炭火焼きにする専門店街","メルジョッに付ける済州式の食べ方そのまま","港と空港が近く、島の初日の夜に良い"]},"zh":{"name":"濟州黑豬肉街（健入洞）","address":"濟州市健入洞","reasons":["專賣在地黑豬、厚切炭烤的一整條街","沾鯷魚醬吃，正是濟州的吃法","鄰近港口與機場，適合上島第一晚"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-tongyeong-jungang-market', 'kr-tongyeong-gul', 'Chợ Jungang Tongyeong', 'gyeongnam', '12 Tongyeonghaean-ro, Tongyeong', 128.4245, 34.8455, '10.000–30.000 KRW', '06:00–20:00', '["street-food","local-favorite"]', 86, '["Hàu từ vịnh Tongyeong — vùng nuôi hàu lớn nhất Hàn Quốc","Mua hàu tươi tại quầy rồi ăn ngay ở hàng chế biến bên cạnh","Ngay dưới chân làng bích hoạ Dongpirang"]', '{"en":{"name":"Tongyeong Jungang Market","address":"12 Tongyeonghaean-ro, Tongyeong","reasons":["Oysters from Tongyeong bay, Korea''s largest oyster-farming area","Buy them fresh at a stall and eat at the cooking counters beside it","Right below the Dongpirang mural village"]},"ko":{"name":"통영 중앙시장","address":"경남 통영시 통영해안로 12","reasons":["한국 최대 굴 양식지 통영 앞바다의 굴","좌판에서 사서 옆 식당에서 바로 먹을 수 있다","동피랑 벽화마을 바로 아래"]},"ja":{"name":"統営中央市場","address":"慶尚南道統営市統営海岸路12","reasons":["韓国最大のカキ養殖地、統営湾のカキ","売り場で買い、隣の調理場ですぐ食べられる","東ピラン壁画村のすぐ下"]},"zh":{"name":"統營中央市場","address":"慶尚南道統營市統營海岸路12號","reasons":["來自統營灣的牡蠣，韓國最大的牡蠣養殖區","在攤位買新鮮的，旁邊料理攤即可代客烹調","就在東皮廊壁畫村下方"]}}', 'kr');
INSERT OR REPLACE INTO restaurants (id, dish_id, name, province_slug, address, lng, lat, price_range, open_hours, labels, atlas_score, reasons, i18n, country) VALUES ('kr-anjirang-gopchang', 'kr-daegu-makchang', 'Phố lòng nướng Anjirang', 'daegu', 'Anjirang-dong, Nam-gu, Daegu', 128.5745, 35.8305, '12.000–18.000 KRW/phần', '16:00–02:00', '["local-favorite","street-food"]', 85, '["Cả con phố hơn 50 quán chỉ nướng lòng, mở tới rạng sáng","Giá rẻ hơn hẳn Seoul với cùng chất lượng","Không khí nhậu đặc trưng nhất Daegu"]', '{"en":{"name":"Anjirang Grilled Intestine Street","address":"Anjirang-dong, Nam-gu, Daegu","reasons":["More than 50 shops on one street, grilling until dawn","Far cheaper than Seoul for the same quality","The most characteristic drinking street in Daegu"]},"ko":{"name":"안지랑 곱창 골목","address":"대구 남구 안지랑동","reasons":["한 골목에 50곳이 넘는 가게가 새벽까지 굽는다","같은 품질에 서울보다 훨씬 저렴하다","가장 대구다운 술 골목"]},"ja":{"name":"安吉郎コプチャン横丁","address":"大邱広域市南区安吉郎洞","reasons":["一つの通りに50軒以上、明け方まで焼き続ける","同じ質でソウルよりずっと安い","最も大邱らしい酒の通り"]},"zh":{"name":"安吉朗烤腸街","address":"大邱南區安吉朗洞","reasons":["一條街超過50家店，一路烤到天亮","同樣品質比首爾便宜許多","最具大邱風味的宵夜街"]}}', 'kr');
PRAGMA foreign_keys = ON;
